        [6100401] = {
          ContentKR = "한 노인이 모닥불 옆으로 걸어간다. 그의 손에 랜턴이 들려 있는 것이 보인다.",
          DialogueId = 6100401,
          GUID = "0F458F0A",
          NextDialogue = 6100402,
          RougeTalkActorType = 3,
          Subtitle = "An old man approaches the campfire. You notice he's carrying a lantern."
        },
        [6100402] = {
          ContentKR = "\"어디 보자... 오! 자네도 랜턴이 하나 있었군!\"\n\"하지만 모든 불은 결국 꺼질 거네. 알다시피, 만약 심연에서 랜턴이 비치지 않는다면, 영원히 어둠 속에서 길을 잃게 될 테지.\"",
          DialogueId = 6100402,
          GUID = "0F458F34",
          NextDialogue = 6100403,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room304_Char01",
          Subtitle = "\"Let me see… Oh! So you have a lantern too!\"\n\"Yet all flames must fade in time. You know this — without light in the abyss, darkness claims you forever.\""
        },
        [6100403] = {
          ContentKR = "\"랜턴을 하나 더 사서 만일의 사태에 대비하게. 작은 빛 하나가, 자네 목숨을 구해 줄지도 몰라.\"",
          DialogueId = 6100403,
          GUID = "0F458F5E",
          NextOptions = {
            [1] = 6100404,
            [2] = 6100406,
            [3] = 6100408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room304_Char01",
          Subtitle = "\"Best carry a spare lantern. Even the faintest glow may save your life on the road ahead.\""
        },
        [6100404] = {
