          GUID = "0F458FB2",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room304_Char01",
          Subtitle = "\"Ah… Such generosity, traveler! May the God of Stars smile upon you on your path.\"\nEvery wrinkle on his face dances with delight."
        },
        [6100406] = {
          ContentKR = "다른 유용한 물건이 있는지 없는지 묻는다.",
