          DisableMouth = 1,
          Duration = 1,
          GUID = "191062E7",
          SpeakNpcId = 100003,
          Subtitle = "...?! You...!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E7"
        },
        [10012013] = {
          ContentKR = "탈출해야 해.",
          DialogueId = 10012013,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "191062E8",
          SpeakNpcId = 100001,
          Subtitle = "Get out of here, and live.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E8"
        },
        [10012014] = {
          ContentKR = "안 돼!!",
          DialogueId = 10012014,
          DisableMouth = 1,
          Duration = 1.5,
          GUID = "191062E9",
          SpeakNpcId = 100003,
          Subtitle = "No—!!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E9"
        },
        [10012015] = {
          ContentKR = "{nickname}, 문제를 낼게. '눈 세 번 깜빡' 이 암호는...",
          DialogueId = 10012015,
          Duration = 5,
          GUID = "191062F0",
          SpeakNpcId = 100003,
          Subtitle = "Quick question, . The \"three quick blinks\" means—",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F0"
        },
        [10012016] = {
          ContentKR = "베레가 말 안 해줘도 다 기억하고 있다고! 눈 세 번 깜빡의 의미는...",
          DialogueId = 10012016,
          Duration = 6,
          ExStoryInfo = "Player",
          GUID = "191062F1",
          SpeakNpcId = 100001,
          Subtitle = "I've got this, Berry. Three quick blinks means...",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F1"
        },
        [10012017] = {
          ContentKR = "\"혼자 남더라도, 꿋꿋이 살아가야 해.\"",
          DialogueId = 10012017,
          DialoguePanelType = "None",
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "191062F2",
          SpeakNpcId = 100001,
          Subtitle = "\"Even if left all alone, you should be brave and live on.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F2"
        },
        [10012018] = {
          ContentKR = "\"우리가 다시 만날 때까지.\"",
          DialogueId = 10012018,
          DialoguePanelType = "None",
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "191062F3",
          SpeakNpcId = 100001,
          Subtitle = "\"Until the day we meet again.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F3"
        },
        [10012101] = {
          ContentKR = "저건...",
          DialogueId = 10012101,
          Duration = 1.5,
          GUID = "19107252",
          NextDialogue = 10012102,
          SpeakNpcId = 100005,
          Subtitle = "That is...",
          VoiceName = "voice/$Locale$/story/1001/100121/19107252"
        },
        [10012102] = {
          ContentKR = "제로의 힘이 아직 해방되지 않았는데, 왜...",
          DialogueId = 10012102,
          Duration = 2.5,
          GUID = "1910727C",
          NextDialogue = 10012103,
          SpeakNpcId = 100005,
          Subtitle = "No. 0 is not supposed to release all her powers yet. Why...",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727C"
        },
        [10012103] = {
          ContentKR = "아니, 이건 제로 자신의 힘이 아니라, 다른 사람이 준 '레조넌스'야.",
          DialogueId = 10012103,
          Duration = 3,
          GUID = "1910727D",
          NextDialogue = 10012104,
          SpeakNpcId = 100005,
          Subtitle = "No, that's not her power, it's Resonance.",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727D"
        },
        [10012104] = {
          ContentKR = "...제로가 보호하려는 꼬마는... '레조넌스'의 새로운 숙주인 건가?",
          DialogueId = 10012104,
          Duration = 2.5,
          GUID = "191072A6",
          NextDialogue = 10012110,
          SpeakNpcId = 100005,
          Subtitle = "...That brat she's trying to protect... That's the new receptacle for the Power of Resonance?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072A6"
        },
        [10012105] = {
          ContentKR = "이 타이밍에, '레조넌스'와 '제로'가 같이 이곳에 다시 나타나다니... 이게 무슨...",
          DialogueId = 10012105,
          Duration = 3,
          GUID = "191072D0",
          SpeakNpcId = 100005,
          Subtitle = "The reappearance of the \"Power of Resonance\" and \"No. 0\" together... What could this possibly mean...?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D0"
        },
        [10012110] = {
          ContentKR = "그러고 보니, 녀석의 외모도...",
          DialogueId = 10012110,
          GUID = "191072D1",
          NextDialogue = 10012105,
          SpeakNpcId = 100005,
          Subtitle = "Come to think of it,  {性别:his|her} face was...",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D1"
        },
        [10012201] = {
          ContentKR = "어서!",
          DialogueId = 10012201,
          Duration = 2,
          GUID = "191082BA",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          ContentKR = "거기까지다!",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934C"
        },
        [10012303] = {
          Content = "那就好，不要勉强自己。",
          DialogueId = 10012303,
          Duration = 2,
          GUID = "1910934D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934D"
        },
        [10012401] = {
          ContentKR = "여긴 누가 살았던 것 같아.",
          DialogueId = 10012401,
          ExStoryInfo = "Player",
          GUID = "1910A38A",
          NextDialogue = 10012402,
          SpeakNpcId = 100001,
          Subtitle = "It seems someone used to live here.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A38A"
        },
        [10012402] = {
          ContentKR = "왠지 여기가 베레의 집이었던 것 같은데?",
          DialogueId = 10012402,
          ExStoryInfo = "Player",
          GUID = "1910A3B4",
          NextDialogue = 10012403,
          SpeakNpcId = 100001,
          Subtitle = "This was your home, am I right, Berry?",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3B4"
        },
        [10012403] = {
          ContentKR = "...난...",
          DialogueId = 10012403,
          GUID = "1910A3DE",
          NextDialogue = 10012404,
          SpeakNpcId = 100003,
          Subtitle = "...I...",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3DE"
        },
        [10012404] = {
          ContentKR = "...그래. 그런데 내가 아니라, '우리'의 집이었어.",
          DialogueId = 10012404,
          GUID = "1910A408",
          NextDialogue = 10012405,
          SpeakNpcId = 100003,
          Subtitle = "...Yes, and no. It was OUR home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A408"
        },
        [10012405] = {
          ContentKR = "우리? 난 아무것도 기억이 안 나는데.",
          DialogueId = 10012405,
          ExStoryInfo = "Player",
          GUID = "1910A432",
          NextDialogue = 10012406,
          SpeakNpcId = 100001,
          Subtitle = "Our home? But I don't remember a thing.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A432"
        },
        [10012406] = {
          ContentKR = "...괜찮아. 오히려 잘 됐어. 여기에서 탈출하면 새로운 집을 만들자.",
          DialogueId = 10012406,
          GUID = "1910A433",
          SpeakNpcId = 100003,
          Subtitle = "...It's okay. Maybe it's all for the best. After we make it out, we'll build a new home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A433"
        },
        [10012501] = {
          ContentKR = "퀘스트 실패, 다시 시작하세요.",
          DialogueId = 10012501,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910B3F2",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again",
          VoiceName = "voice/$Locale$/story/1001/100125/1910B3F2"
        },
        [10012502] = {
          ContentKR = "퀘스트 실패, 다시 시작하세요.",
          DialogueId = 10012502,
          Duration = 10,
          ExStoryInfo = "Player",
          GUID = "1910B3F3",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again"
        },
        [10012601] = {
          Content = "净界岛上的小村，我和贝蕾妮卡一起长大的地方。",
          DialogueId = 10012601,
          Duration = 2.5,
          GUID = "1910C45A",
          NextDialogue = 10012602,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C45A"
        },
        [10012602] = {
          Content = "这些叫做秽兽的怪物究竟从何而来，我们也无从得知；",
          DefaultLookAt = "KeepState",
          DialogueId = 10012602,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C484",
          LookAt = {
            [1] = "100001:n(100003)"
          },
          NextDialogue = 10012603,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C484"
        },
        [10012603] = {
          Content = "只知道，昔日宁和的村庄，一夜之间变成了这副模样。",
          DialogueId = 10012603,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C4AE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C4AE"
        },
        [10012701] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentKR = "돌아왔구나. {nickname}... 나의 반쪽, 나의 그림자, 나의 메아리.",
          DialogueId = 10012701,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D4EC",
          NextDialogue = 10012702,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You're back, ... My other half, my reflection, and my echo.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D4EC"
        },
        [10012702] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentKR = "내 목소리를 들었구나. 너의 힘, '레조넌스'를 되찾은 걸 보니 말이야.",
          DialogueId = 10012702,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D516",
          NextDialogue = 10012703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You heard my voice and retrieved the power that belongs to you. The \"Resonance.\"",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D516"
        },
        [10012703] = {
          Camera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          ContentKR = "이 힘은 아무것도 바꿀 수 없어. 난 바다로 뛰어들었고, 다시는 깨지 않을 거야. 그렇게 모두 끝이라고.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012703,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D540",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012704,
          SpeakNpcId = 100001,
          Subtitle = "This power didn't change anything. I fell into the sea and I'll never wake up again. It's all over.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D540"
        },
        [10012704] = {
          Camera = "699.554688,-957.21875,341.90564,0.000407,-14.001368,121.374519,35.0,100000.0,false,Manual,22.0",
          ContentKR = "아니, 내게는 다 보여. 너의 미래, 그리고 우리의 미래… 절대 여기서 끝나지 않아.",
          DialogueId = 10012704,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "249.050781,-1061.171875,341.90564,0.00044,-16.201441,91.573235,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D56A",
          NextDialogue = 10012705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "No, I can see it — your future, our future... it doesn't end here.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56A"
        },
        [10012705] = {
          ContentKR = "누군가 널 짜디짠 바닷물에서 건져 척박한 황무지로 데려갈 거야. 그리고 넌 진정한 운명의 시련을 마주하게 되겠지.",
          DialogueId = 10012705,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D56B",
          NextDialogue = 10012706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Someone will pluck you from the briny waters and lead you to a frozen wilderness, where destiny will pose the ultimate test.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56B"
        },
        [10012706] = {
          Camera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          ContentKR = "그 말은... 내가 아직 살아 있다는 거야?",
          DefaultLookAt = "KeepState",
          DialogueId = 10012706,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D594",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012712,
          SpeakNpcId = 100001,
          Subtitle = "Are you saying... I'm still alive?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D594"
        },
        [10012707] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...시간이 됐어. 이건 내가 너에게 주는 마지막 도움이야.",
          DialogueId = 10012707,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D595",
          NextDialogue = 10012708,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "...The time has come. Let me offer you one last gift.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D595"
        },
        [10012708] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentKR = "잠깐 손 좀 내밀어 볼래, {nickname}.",
          DialogueId = 10012708,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D599",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Here, .",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D599"
        },
        [10012709] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentKR = "이 모래알들은 너와 나의 것이야. 과거와 현재, 그리고 미래의 '기억'을 잇지.",
          DialogueId = 10012709,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59A",
          NextDialogue = 10012710,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "These sands are our shared memories, bridging the past, present, and future."
        },
        [10012710] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentKR = "이 기억의 모래 속에 이번 여정에 도움이 되는 게 있을 거야.",
          DialogueId = 10012710,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59B",
          NextDialogue = 10012711,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Within these flowing sands of memory, you shall find strength for your journey.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D59B"
        },
        [10012711] = {
          ContentKR = "부디, 그들이 너의 여정에 도움이 되길.",
          DialogueId = 10012711,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D59C",
          NextDialogue = 10012712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "May they be your strength on your journey.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D59C"
        },
        [10012712] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentKR = "자, 이제 떠날 때야.",
          DialogueId = 10012712,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D596",
          NextDialogue = 10012713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "It's time to set off.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D596"
        },
        [10012713] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...{nickname}. 생명은 무한한 밤 속에서 항해하는 외딴 배와 같아. 강물은 눈물로 가득하고, 강가는 가시로 덮여 있지.",
          DialogueId = 10012713,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D597",
          NextDialogue = 10012714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = ".... Life is like a lonely cruise through the boundless darkness of the night. The river weeps, overflowing its banks, while the thorny thickets on either side stand as a testament to its sorrow.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D597"
        },
        [10012714] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentKR = "난 계속해서... 저편의 네가 어디로 향하는지 지켜볼 거야.",
          DialogueId = 10012714,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D598",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "I'll keep watching over you, The One Across the Shore... to see where you're going.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D598"
        },
        [10012801] = {
          ContentKR = "코퀴투스에 온 것은 처음이지만, 여긴 손님 대접하는 방식이 참 독특한 것 같군.",
          DialogueId = 10012801,
          Duration = 8.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E52A",
          RelatedWikiId = {
            [1] = 408002
          },
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in the Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E52A"
        },
        [10012802] = {
          ContentKR = "악의는 없어... 그저 작은 거래를 하고 싶을 뿐.",
          DialogueId = 10012802,
          Duration = 6.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E57E",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small \"bargain.\"",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E57E"
        },
        [10012803] = {
          ContentKR = "거절할 수 없는 대가를 주지. 네가 해야 할 일은 아주 간단해.",
          DialogueId = 10012803,
          Duration = 6.5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E5A8",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E5A8"
        },
        [10017801] = {
          Content = "......",
          DialogueId = 10017801,
          Duration = 1,
          GUID = "1914197A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001,
            [5] = 403001
          },
          VoiceName = "voice/$Locale$/story/1002/100178/1914197A"
        },
        [10017901] = {
          ContentKR = "비행선은 정상에 있어. 잠시만 정비하고 마저 올라가자.",
          DialogueId = 10017901,
          DisableMouth = 1,
          Duration = 5,
          GUID = "191429E2",
          SpeakNpcId = 100003,
          Subtitle = "The ship is at the mountaintop. After a short break, we'll push on.",
          VoiceName = "voice/$Locale$/story/1001/100179/191429E2"
        },
        [10017902] = {
          ContentKR = "...이렇게 갑자기 연옥도를 떠나게 될 줄이야.",
          DialogueId = 10017902,
          DisableMouth = 1,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19142A0C",
          SpeakNpcId = 100001,
          Subtitle = "...Can't believe we'll be saying goodbye to Purgatorio Island soon.",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0C"
        },
        [10017903] = {
          ContentKR = "...정말 쉴 틈도 안 주는군.",
          DialogueId = 10017903,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19142A0D",
          SpeakNpcId = 100003,
          Subtitle = "...You creatures just can't give us a break, can you?",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0D"
        },
        [10018001] = {
          Content = "走。",
          DialogueId = 10018001,
          Duration = 2,
          GUID = "19143A4A",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100180/19143A4A"
        },
        [10018101] = {
          DialogueId = 10018101,
          Duration = 1,
          GUID = "19144AB2",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100181/19144AB2"
        },
        [10018201] = {
          Content = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
          DialogueId = 10018201,
          DialoguePanelType = "None",
          Duration = 13,
          ExStoryInfo = "Player",
          GUID = "19145B1A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B1A"
        },
        [10018202] = {
          Content = "第一次，我感受到了，我是如此真实地活着。",
          DialogueId = 10018202,
          DialoguePanelType = "None",
          Duration = 7,
          ExStoryInfo = "Player",
          GUID = "19145B44",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B44"
        },
        [10018301] = {
          Content = "下坠。我本应朝着漆黑的深渊下坠。",
          DialogueId = 10018301,
          Duration = 2.5,
          GUID = "19146B82",
          NextDialogue = 10018302,
          VoiceName = "voice/$Locale$/story/1001/100183/19146B82"
        },
        [10018302] = {
          Content = "但，我却感觉自己在晨雾的怀抱里飘浮。",
          DialogueId = 10018302,
          Duration = 2.5,
          GUID = "19146BAC",
          NextDialogue = 10018303,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BAC"
        },
        [10018303] = {
          Content = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
          DialogueId = 10018303,
          Duration = 4,
          GUID = "19146BD6",
          NextDialogue = 10018304,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BD6"
        },
        [10018304] = {
          Content = "而是一种，奇特的触感……亲切，甚至令人怀念。",
          DialogueId = 10018304,
          Duration = 3,
          GUID = "19146C00",
          VoiceName = "voice/$Locale$/story/1001/100183/19146C00"
        },
        [10018401] = {
          ContentKR = "내게 응답한 것은 끝없이 흘러내리는 하얀 모래뿐, 그리고...",
          DialogueId = 10018401,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "19147BEA",
          NextDialogue = 10018402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "But up until now, there has been no answer. Only endless flowing quicksand covering my vision, and...",
          VoiceName = "voice/$Locale$/story/1001/100184/19147BEA"
        },
        [10018402] = {
          ContentKR = "{性别:그녀|그}.",
          DialogueId = 10018402,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "19147C14",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "{性别:her|him}.",
          VoiceName = "voice/$Locale$/story/1001/100184/19147C14"
        },
        [10018501] = {
          Content = "占位文本",
          DialogueId = 10018501,
          GUID = "19148C52",
          VoiceName = "voice/$Locale$/story/1001/100185/19148C52"
        },
        [10018601] = {
          ContentKR = "안돼...",
          DialogueId = 10018601,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19149CBA",
          SpeakNpcId = 100001,
          Subtitle = "No...",
          VoiceName = "voice/$Locale$/story/1001/100186/19149CBA"
        },
        [10018602] = {
