          DialogueId = 10018602,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19149CE4",
          SpeakNpcId = 100001,
          Subtitle = "Don't... take her...",
          VoiceName = "voice/$Locale$/story/1001/100186/19149CE4"
        },
        [10018603] = {
