          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1914FF2A",
          NextDialogue = 10019202,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF2A"
        },
        [10019202] = {
          Content = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
          DialogueId = 10019202,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "1914FF54",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100192/1914FF54"
        },
        [10019301] = {
          ContentKR = "필토이드가 끝도 없이 몰려와...",
          DialogueId = 10019301,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19150F92",
          NextDialogue = 10019302,
          SpeakNpcId = 100001,
          Subtitle = "How many of them are there...",
          VoiceName = "voice/$Locale$/story/1001/100193/19150F92"
        },
        [10019302] = {
          ContentKR = "빨리 올라가자. 필토이드를 떨쳐내는 거야.",
          DialogueId = 10019302,
          Duration = 4,
          GUID = "19150FBC",
          SpeakNpcId = 100003,
          Subtitle = "Let's get to the top to shake them off.",
          VoiceName = "voice/$Locale$/story/1001/100193/19150FBC"
        },
        [10019401] = {
          ContentKR = "코퀴투스에 온 것은 처음이지만, 여긴 손님 대접하는 방식이 참 독특한 것 같군.",
