          GUID = "19153057.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153057"
        },
        [10019502] = {
          Content = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
          DialogueId = 10019502,
          Duration = 9,
          GUID = "19153058.0",
          SpeakNpcId = 100012,
          VoiceName = "voice/$Locale$/story/1001/100195/19153058"
        },
        [10019503] = {
          Content = "？？？：我会处理。但，现在还不是时候。",
