        [10030401] = {
          Camera = "67.060974,63.269043,215.128113,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
          ContentKR = "당신... 난 대체...",
          DialogueId = 10030401,
          FacialId = {
