          VoiceName = "voice/$Locale$/story/1003/100304/191C2F74"
        },
        [10030419] = {
          Camera = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
          ContentKR = "시간이 거의 됐군.",
