          NextDialogue = 10030716,
          SpeakNpcId = 100304,
          Subtitle = "...Alright, I've verified the travel permit. Thank you for your cooperation. Now, let's talk about the attack.",
          TalkActionId = {
            [1] = "200021:Shock_End",
            [2] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100307/191C6039"
        },
        [10030716] = {
          Camera = "-70.692688,-985.964844,130.398438,0.000275,-3.004272,85.63118,35.000011,8667.292969,false,Manual,3.0",
          ContentKR = "저는 범인을 최대한 빨리 잡아서 모두에게 안전을 되찾아주고 싶습니다. 이번 연쇄 습격에서 살아남은 유일한 생존자로서, {nickname} 씨는 저희가 작업을 진행하는 데 매우 중요합니다. 하지만 여기는 사람이 너무 많아서...",
          DialogueId = 10030716,
          FinalCamera = "-68.961426,-964.299805,129.412109,0.000276,-2.604269,85.431206,35.000011,8667.292969,false,Manual,3.0",
          GUID = "191C5E8A",
          NextDialogue = 10030717,
          Scripts = "LookAt{LookAtDescription{\"100304:p(lise_03_looking)\"}}",
          SpeakNpcId = 100304,
          Subtitle = "I want to catch the culprit who attacked you and bring safety back to everyone as soon as possible. As the sole survivor of the incident, your testimony is vital for us to fully understand the case. That said, this tavern is hardly an appropriate place for an enquiry—",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5E8A"
        },
        [10030717] = {
          Camera = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
          ContentKR = "아아, 알겠습니다. 그럼, 저희 좀 조용한 장소로 옮겨서 얘기하죠.",
          DialogueId = 10030717,
          GUID = "191C5EB4",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10030718,
          SpeakNpcId = 200021,
          Subtitle = "Ah, got it. Let's get to a quieter place to talk then.",
          TalkActionId = {
            [1] = "200021:AgreeHead",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5EB4"
        },
        [10030718] = {
          Camera = "136.852234,-320.489258,75.955078,0.000275,7.598257,113.8312,35.000019,482.916321,false,Manual,6.0",
          ContentKR = "감사드립니다. 저를 따라오세요.",
          DialogueId = 10030718,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191C5EDE",
          NextDialogue = 10030719,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100304:n(100304)"}},   
MoveTo{ActorId{100304},TargetPoint{"lise_03_leave"},MoveSpeed{90},Visibility{"Show"}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Thank you for understanding. Please come with me.",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5EDE"
        },
        [10030719] = {
          Camera = "-159.366272,-113.829102,114.5625,0.000285,10.592653,64.027985,35.000019,242.113937,false,Manual,6.0",
          ContentKR = "야, 무슨 멍을 그렇게 때리는 거야?",
          DialogueId = 10030719,
          GUID = "191C5F08",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = "200021:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 10030720,
          Scripts = "SetLocation{ActorId{100304},TargetPoint{\"lise_03_leave\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Hey, what are you waiting for?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          TurnTo = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F08"
        },
        [10030720] = {
          ContentKR = "통행증 때문에 화난 건가. 그게... 크흠, 아는 사람을 통해 구할 수 있는 게 조련사 통행증밖에 없어서 말이야, 신경 쓰지 마.",
          DialogueId = 10030720,
          GUID = "191C603A",
          NextDialogue = 10030721,
          SpeakNpcId = 200021,
          Subtitle = "Don't tell me you're upset about the travel permit. Well, uh, that was the only type I could get for you. Just roll with it, alright?",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C603A"
        },
        [10030721] = {
          Camera = "-6.562927,-65.756836,132.560547,0.000286,2.591954,141.833664,35.000019,103.402161,false,Manual,6.0",
          ContentKR = "......",
          DialogueId = 10030721,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191C5F32",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10030722,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F32"
        },
        [10030722] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0",
          ContentKR = "아닌가, 그럼 그날 밤 일 때문에 아직도 리듬 페실한테 화난거지?",
          DialogueId = 10030722,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "191C5F5C",
          NextDialogue = 10030723,
          SpeakNpcId = 200021,
          Subtitle = "Alright, I know. You're probably still bitter about Rhythm Fischer for what happened that night.",
          TalkActionId = {
            [1] = "200021:Explain01_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F5C"
        },
        [10030723] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0",
          ContentKR = "근데 말이지, 리듬 페실이랑 친해질 수 있으면 나쁘지 않을걸? 군단 정보망이 얼마나 넓은데, 네가 <H>사람 찾는</> 일도 어쩌면 실마리가 생길지도 몰라.",
          DialogueId = 10030723,
          GUID = "191C5FB0",
          NextDialogue = 10030724,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"-22.493896,92.760742,157.833984,0.000282,-9.206241,-123.576553,35.000019,109.330856,false,Manual,3.0\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "But, it wouldn't be a bad thing to get on good terms with Fischer. I mean, the Legion's got connections everywhere. Your search for somebody might get somewhere.",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB0"
        },
        [10030724] = {
          Camera = "7.651123,-118.004883,114.373047,0.000265,8.99109,120.035538,35.000019,156.230972,false,Manual,6.0",
          ContentKR = "게다가, 그 뒤에서 널 습격한 나쁜 놈을 네 손으로 직접 잡고 싶지 않아?",
          DialogueId = 10030724,
          GUID = "191C5FB1",
          NextDialogue = 10030725,
          SpeakNpcId = 200021,
          Subtitle = "Besides, don't you want to take down that dishonorable coward with your own hands?",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB1"
        },
        [10030725] = {
          ContentKR = "그리고, 나도 '카론 사냥' 사건을 얼른 해결하고 싶어. 지금 외성 사람들 모두가 다음에 습격당할 사람이 자신일까 봐 불안에 떨고 있잖아. 이제 우리 집 문에도 더 이상 자물쇠를 달 수 없고 말이야.",
          DialogueId = 10030725,
          GUID = "191C5F86",
          NextDialogue = 10030726,
          SpeakNpcId = 200021,
          Subtitle = "As for me, I want this whole \"Charon Hunt\" mess resolved as soon as possible, too. The whole outer city's been on edge, and that rickety old door on my house can't take another lock.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F86"
        },
        [10030726] = {
          Camera = "13.800354,86.224609,170.464844,0.000277,-12.408418,-140.354614,35.000015,93.577675,false,Manual,3.0",
          ContentKR = "군단... 베레의 소식...",
          DialogueId = 10030726,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "13.800354,86.224609,170.464844,0.000278,-16.20825,-139.955261,35.000019,129.836029,false,Manual,6.0",
          GUID = "191C5FDA",
          NextDialogue = 10030727,
          SpeakNpcId = 100001,
          Subtitle = "The Legion... Berry's whereabout...",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FDA"
        },
        [10030727] = {
          ContentKR = "...살인사건... 날 습격한 범인...",
          DialogueId = 10030727,
          GUID = "191C6004",
          NextDialogue = 10030728,
          SpeakNpcId = 100001,
          Subtitle = "The murders... And the one who attacked me...",
          VoiceName = "voice/$Locale$/story/1003/100307/191C6004"
        },
        [10030728] = {
          Camera = "-405.713257,243.483398,93.306641,0.000202,3.588124,-31.563541,35.000015,535.205933,false,Manual,3.0",
          ContentKR = "휴, 알았어, 네 말대로 하자.",
          DialogueId = 10030728,
          FinalCamera = "13.302612,85.791016,170.464844,0.000279,-16.20825,-139.555191,35.000019,129.836029,false,Manual,6.0",
          GUID = "191C602E",
          SpeakNpcId = 100001,
          Subtitle = "*sighs* Fine. Let's do this.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100001:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C602E"
        },
        [10030801] = {
          Camera = "61.057617,108.540283,127.39502,-0.000122,5.801385,-131.604752,40.000011,1.5,false,DoNotOverride,1.2",
          ContentKR = "이런 곳을 고르다니.",
          DialogueId = 10030801,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = "100001:Confident01"
          },
          FinalCamera = "73.068359,122.071289,125.557617,-0.000122,5.801385,-131.604752,40.000011,1.5,false,DoNotOverride,1.2",
          GUID = "191C6E4A",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100304:n(100001)"
          },
          NextDialogue = 10030802,
          RelatedWikiId = {
            [1] = 201011
          },
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"68.806641,188.34668,131.112061,-0.000122,2.60125,-129.004272,35.0,299.586945,false,Manual,3.390601\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "I thought it would be somewhere like an office.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6E4A"
        },
        [10030802] = {
          Camera = "40.330078,-14.789795,129.912109,-0.000122,3.401612,100.797935,35.000019,1.5,false,DoNotOverride,1.2",
          ContentKR = "네, 전 평소에 힘들 때면 여기로 와서 머리를 식히곤 합니다. 여긴 보통 아무도 안 오거든요. 진지한 얘기를 하기 적합하죠.",
          DialogueId = 10030802,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "42.864258,-28.097412,129.106689,-0.000122,3.401612,100.798004,35.000019,1.5,false,DoNotOverride,1.2",
          GUID = "191C6E74",
          NextDialogue = 10030803,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I come here to clear my head when I'm feeling overwhelmed. It's quiet, and there's rarely anyone around — perfect for discussing serious matters.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6E74"
        },
        [10030803] = {
          Camera = "938.864258,-1600.42627,644.140015,0.000063,-15.356232,125.519363,35.000008,3496.211426,false,Manual,1.2",
          ContentKR = "'카론 사냥'은 아이스레이크 시티에서 발생한 연쇄살인 사건입니다. 이미 어느 정도 알고 있을 거라 믿습니다.",
          DialogueId = 10030803,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "921.212891,-1613.348145,644.140015,0.000062,-15.156223,125.719307,35.000008,3496.211426,false,Manual,1.2",
          GUID = "191C6E9E",
          NextDialogue = 10030804,
          SpeakNpcId = 100304,
          Subtitle = "So, the \"Charon Hunt\" is a series of murders that took place here in Icelake. I assume you've already heard about it.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6E9E"
        },
        [10030804] = {
          Camera = "22.568359,-184.945801,150.498779,14.412785,-8.200291,103.409584,25.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "11월 22일 새벽, 5명이 목숨을 잃고 1명이 다쳤습니다. 11월 25일 새벽, 13명이 살해당했습니다.",
          DialogueId = 10030804,
          FacialId = {
            [1] = "100304:Sad02"
          },
          FinalCamera = "17.014648,-186.657471,149.025391,14.414536,-7.200214,102.210579,25.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6EC8",
          NextDialogue = 10030805,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "November 22, early morning: 5 dead, 1 injured. November 25, early morning: 13 dead.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6EC8"
        },
        [10030805] = {
          Camera = "23.945312,90.854004,160.98999,10.805622,-22.999117,107.011467,25.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "사건이 동쪽 구역에 집중되어 있고, 그쪽에 사는 사람들은 대부분 카론입니다. 그래서 '카론 사냥'이라는 이름이 붙은 거죠.",
          DialogueId = 10030805,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "18.341797,89.56958,158.005859,10.810204,-18.79888,98.613777,25.000002,1.5,false,DoNotOverride,1.2",
          GUID = "191C6EF2",
          NextDialogue = 10030806,
          RelatedWikiId = {
            [1] = 405005
          },
          SpeakNpcId = 100304,
          Subtitle = "The attacks primarily occurred in the eastern district, home to many Charon residents, which is why the case has been dubbed the \"Charon Hunt.\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6EF2"
        },
        [10030806] = {
          Camera = "154.362305,294.067871,116.455078,-0.000122,2.199355,-123.791985,40.000027,420.30722,false,Manual,1.2",
          ContentKR = "그건 전부 아는 내용입니다. {nickname}이(가) 뭘 해드려야 하죠?",
          DialogueId = 10030806,
          FinalCamera = "152.069336,295.810059,116.455078,-0.000122,2.199355,-122.592339,40.000027,420.30722,false,Manual,1.2",
          GUID = "191C6F1C",
          NextDialogue = 10030807,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Yeah, we've heard about that. What do you need from ?",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F1C"
        },
        [10030807] = {
          Camera = "35.023438,-85.893799,135.901367,-0.000122,-1.000022,97.196419,40.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "{nickname} 씨의 더 많은 사건 세부 정보가 필요합니다. 잠시 뒤 두 분을 5일 전 {nickname} 씨가 습격받은 현장으로 안내하겠습니다. 그 거리는 지금 군단에 의해 봉쇄된 상태입니다.",
          DialogueId = 10030807,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "39.05957,-117.875977,136.462891,-0.000122,-1.000022,97.196419,40.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6F46",
          NextDialogue = 10030808,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I need  to provide as many details about the case as possible. In a while, I'll take you all to the scene where {性别:he|she} was attacked five days ago. That street is currently sealed off by the Legion.",
          TalkActionId = {
            [1] = "100304:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F46"
        },
        [10030808] = {
          Camera = "37.841797,-240.143555,136.698242,-0.000122,-0.799986,100.997322,40.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "하지만 당신은 피해자이니 현장에 돌아가는 건 좋지 않은 기억이 떠오르게 할 수도 있겠죠. 조사 효율이 낮아질 수 있지만, 필요하시다면 치안서에서 조사를 받아도 좋습니다.",
          DialogueId = 10030808,
          FinalCamera = "27.549805,-242.12207,136.698242,-0.000122,-0.799959,99.197517,40.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6F70",
          NextOptions = {
            [1] = 10030809,
            [2] = 10030811
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{200021},AnimationId{"Talk02_End"},Duration{2}},
SEQ{CameraMoveTo{_delay{5},TargetPosition{"24.785156,58.79248,123.002441,-0.000123,3.599427,-100.993622,40.000011,1.5,false,DoNotOverride,1.2"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{"32.329102,57.327148,123.002441,-0.000122,3.999438,-104.194237,40.000011,1.5,false,DoNotOverride,1.2"},duration{10}}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "But I understand revisiting the scene might bring up unpleasant memories. If it's too much for you, we can conduct the enquiry at the Security Bureau instead — it might not be as efficient, but it's an option.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F70"
        },
        [10030809] = {
          ContentKR = "괜찮아요, 빨리 가서 빨리 끝내죠.",
          DialogueId = 10030809,
          GUID = "191C6F9A",
          ImprPlusId = 1006,
          NextDialogue = 10030810,
          Subtitle = "No need. Let's just get it over with."
        },
        [10030810] = {
          Camera = "202.821289,-682.109375,384.926758,-0.000121,-20.999859,108.990448,35.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "녹토 보이저의 협조에 감사드립니다. 역시 소문처럼 굳세고 용감하군요.",
          DialogueId = 10030810,
          FinalCamera = "177.298828,-690.292236,384.926758,-0.00012,-21.199854,106.390915,35.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6FC4",
          NextDialogue = 10030813,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Thank you for your cooperation, Noctoyagers. You're as tough and reliable as they say.",
