        [10030813] = {
          Camera = "32.081055,-28.242676,78.543457,-0.000123,11.19845,-70.9897,40.000027,1.5,false,DoNotOverride,1.2",
          ContentKR = "헤헤, 내 시종이 여리여리하게 생겼어도 엄청 강하거든!",
