          NextDialogue = 10030814,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 200002,
          Subtitle = "Hehe, don't be fooled by how gentle my Little Minion looks — {性别:he|she}'s very tough on the inside!",
