          },
          VoiceName = "voice/$Locale$/story/1003/100308/191C7096"
        },
        [10030816] = {
          Camera = "237.609375,311.72168,37.491455,-0.000121,10.798064,-126.589691,30.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "제가 필요할 때 한번 도와준다고 약속해요.",
          DialogueId = 10030816,
          FinalCamera = "258.552734,295.424072,37.491455,-0.000122,10.998025,-130.988983,30.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C70C0",
          NextDialogue = 10030817,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Confident_End\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "On top of the payment, I need you to promise me one thing — help me when I need it in the future.",
          TalkActionId = {
            [1] = "100001:Confident_Start",
            [2] = "100304:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
