        },
        [10030818] = {
          Camera = "-120.288086,-367.168945,91.211426,-0.000122,4.400308,70.991791,35.000023,1.5,false,DoNotOverride,1.2",
          ContentKR = "좋습니다. 제가 도울 수 있는 만큼 도와드리죠.",
          DialogueId = 10030818,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-120.288086,-367.168945,91.211426,-0.000122,2.800302,70.991676,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C7114",
          NextDialogue = 10030819,
          SpeakNpcId = 100304,
          Subtitle = "Alright, I promise you. I'll help however I can.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7114"
        },
        [10030819] = {
          Camera = "-36.814453,-5.089111,124.812256,-AA1160.000122,5.000607,71.789139,35.000023,1.5,false,DoNotOverride,1.2",
          ContentKR = "...잠시만요! 군법에 어긋나는 건 안 됩니다. 살인이나 강도짓도 안 돼요... 그리고 또, 포세이큰 동맹에 협력하는 것도 안 됩니다...",
          DialogueId = 10030819,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-29.711914,16.467773,126.797119,-0.000122,5.000607,71.588997,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C713E",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10030820,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "...Wait! Breaking military regulations is off the table — no murder, no theft... Oh, and absolutely no aiding the Forsakens...!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100308/191C713E"
        },
        [10030820] = {
          Camera = "134.194336,248.073242,103.617432,-0.000122,4.396907,-126.986076,30.000002,1.5,false,DoNotOverride,1.2",
          ContentKR = "그그그렇게 과한 건 아닙니다! 저희는 나쁜 사람이 아니니까 장교님은 걱정하지 않으셔도 돼요! 그냥 저희 대장이 가족과 흩어져서, 나중에 조금만 도와주셨으면 해서요.",
          DialogueId = 10030820,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "129.308594,251.674316,103.617432,-0.000122,4.396907,-125.585915,30.000002,1.5,false,DoNotOverride,1.2",
          GUID = "191C7168",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10030821,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Whoa, nothing like that! Don't worry, Officer, we're law-abiding folks. It's just that our captain got separated from {性别:his|her} family, and might need your help to look for them.",
          TalkActionId = {
            [1] = "200021:Sigh_Start",
            [2] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7168"
        },
        [10030821] = {
          Camera = "40.24707,133.596191,138.103271,-0.000122,2.000023,170.404037,35.0,1.5,false,DoNotOverride,1.2",
          ContentKR = "가족과 흩어졌다구요?",
          DialogueId = 10030821,
          FacialId = {
            [1] = "200021:Shock01"
          },
          FinalCamera = "39.746094,130.626221,138.103271,-0.000122,2.000023,170.404037,35.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C7192",
          NextDialogue = 10030822,
          SpeakNpcId = 100304,
          Subtitle = "Got separated from your family?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7192"
        },
        [10030822] = {
          Camera = "155.024414,-651.978271,105.728516,-0.000122,7.398713,107.904366,40.000023,1.5,false,DoNotOverride,1.2",
          ContentKR = "당신의 어려움은 제가 너무 잘 압니다. 저도 일 년 내내 가족과 한 번도 만나지 못했거든요... '카론 사냥' 사건이 해결되면, 최선을 다해 가족을 찾아드리겠습니다!",
          DialogueId = 10030822,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "155.024414,-651.978271,105.728516,-0.000122,2.598771,106.304527,40.000011,1.5,false,DoNotOverride,1.2",
          GUID = "191C71BC",
          NextDialogue = 10030823,
          Scripts = "PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"Talk02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I completely understand how you feel. I barely get to see my family all year round... Once the \"Charon Hunt\" case is resolved, I promise I'll do everything in my power to help you find your family!",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100308/191C71BC"
        },
        [10030823] = {
          Camera = "6.436523,-56.493652,135.884766,-0.000122,7.398474,-105.213242,35.000019,1.5,false,DoNotOverride,1.2",
          ContentKR = "(윽... 이 녀석 왜 갑자기 기운이 넘치는 거지, 숨, 숨이 막힐 것 같아...)",
          DialogueId = 10030823,
          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "13.727539,-29.676025,130.914795,-0.000122,6.607538,-104.814003,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C71E6",
          NextDialogue = 10030824,
          SpeakNpcId = 100001,
          Subtitle = "(Uh... Why is she so fired up all of a sudden? I... I can't breathe...)",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100308/191C71E6"
