        },
        [10031002] = {
          ContentKR = "네, 기억 나요.",
          DetectiveQuestionId = 1001,
          DialogueId = 10031002,
          GUID = "191C8F44",
          ImprPlusId = 1007,
          NextDialogue = 10031004,
          Subtitle = "Yes, I remember it."
        },
        [10031003] = {
          ContentKR = "길 가다가 머리에 갑자기 한 대 맞으면, 장교님도 잊기 힘들 걸요.",
          DetectiveQuestionId = 1001,
          DialogueId = 10031003,
          GUID = "191C8F6E",
          ImprPlusId = 1010,
          NextDialogue = 10031004,
          Subtitle = "Well, if someone knocked you out cold on the street, you wouldn't forget either."
