        },
        [10031901] = {
          Camera = "30.015625,-85.984131,177.711914,0.000052,-19.395872,148.382233,35.000011,100000.0,false,Manual,22.0",
          ContentKR = "지금까지의 단서로 봤을 때, 가장 의심스러운 곳은 두 군데입니다...",
          DialogueId = 10031901,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "30.015625,-85.984131,177.711914,0.000057,-17.995785,148.381851,35.000011,100000.0,false,Manual,22.0",
          GUID = "191D22C2",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)"
          },
          NextDialogue = 10031902,
          SpeakNpcId = 100304,
