        },
        [10031903] = {
          Camera = "70.767578,-144.760498,130.16748,0.000046,1.207352,133.767914,35.000011,212.896515,false,Manual,3.557978",
          ContentKR = "네, 당신도 같은 결론에 도달한 것 같군요.",
          DialogueId = 10031903,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "70.065918,-145.452881,130.16748,0.000046,1.207352,132.567947,35.000011,212.896515,false,Manual,3.557978",
          GUID = "191D2316",
          NextDialogue = 10031904,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"AgreeHead\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Looks like we've come to the same conclusion.",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100319/191D2316"
        },
        [10031904] = {
          Camera = "20.626953,-127.845825,117.631836,0.000127,5.196702,133.163498,40.000023,676.431458,false,DoNotOverride,3.853879",
          ContentKR = "아이스레이크 시티에 대한 기여에 감사드립니다. 당신께서 중요한 정보를 제공해 주지 않으셨다면 이토록 빨리 위치를 확보할 수는 없었을 겁니다.",
          DialogueId = 10031904,
          FinalCamera = "17.34082,-130.929321,117.631836,0.000126,5.396703,130.76358,40.000023,676.431458,false,DoNotOverride,3.853879",
          GUID = "191D2340",
          NextDialogue = 10031905,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-190.275391,-8.895508,132.186035,0.000135,-1.403228,-14.43922,40.000023,255.154572,false,Manual,2.171579\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-189.625,-6.35083,132.186035,0.000135,-1.403228,-15.039334,40.000023,255.154572,false,Manual,2.171579\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "Thank you for what you've done for the city. The information you've provided has been invaluable. Without it, we wouldn't have been able to narrow things down so quickly.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100319/191D2340"
        },
        [10031905] = {
          Camera = "-5.085938,32.046997,104.761475,0.000069,-14.199068,57.205662,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "하지만 두 군데가 있잖아. 우린 하나, 둘, 셋, 네 명이야!",
          DialogueId = 10031905,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-10.807617,35.774414,104.761475,0.000065,-14.199068,53.205345,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D236A",
          LookAt = {
            [1] = "100304:n(200002)"
          },
          NextDialogue = 10031906,
          SpeakNpcId = 200002,
          Subtitle = "But there are two places! And we've got one, two, three, four people!",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100304:p(20)"
          },
          VoiceName = "voice/$Locale$/story/1003/100319/191D236A"
        },
        [10031906] = {
          Camera = "225.256836,170.580078,47.830078,0.000078,9.399993,-157.992004,40.0,676.431458,false,DoNotOverride,3.853879",
          ContentKR = "제가 공장에 가겠습니다. 제 신분 때문에 조사하기 더 편할 겁니다. 그리고 거기엔 오랜 지인들도 있습니다.",
          DialogueId = 10031906,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "222.537598,177.397705,47.830078,0.000078,9.399993,-156.992142,40.0,676.431458,false,DoNotOverride,3.853879",
          GUID = "191D2394",
          NextDialogue = 10031907,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"533.140625,-240.491943,423.882568,0.000052,-30.599028,154.810074,35.000008,676.431458,false,Manual,3.853879\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"532.318848,-242.241455,423.882568,0.000052,-30.599028,154.810104,35.000008,676.431458,false,Manual,3.853879\"},duration{5}}},PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "I'll take the factory area. It might be easier for a legion officer to investigate that place than civilians, and I have some old acquaintances there.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100319/191D2394"
        },
        [10031907] = {
          Camera = "-109.222656,-79.739136,102.910645,0.000107,9.599025,23.804184,40.0,676.431458,false,DoNotOverride,3.853879",
          ContentKR = "설마 공장에서 일해 본 적도 있어요?",
          DialogueId = 10031907,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "-115.883789,-63.164551,102.910645,0.000109,9.599025,19.003851,40.0,676.431458,false,DoNotOverride,3.853879",
          GUID = "191D23BE",
          NextDialogue = 10031908,
          SpeakNpcId = 200021,
          Subtitle = "Don't tell me you used to work there...",
          TalkActionId = {
