        [10031908] = {
          Camera = "451.617188,-99.952515,73.202881,0.000091,5.878675,167.998718,30.0,577.647949,false,Manual,1.522509",
          ContentKR = "네, 어렸을 때 도우미로 일하러 들어가서 오랫동안 거기서 지냈습니다.",
          DialogueId = 10031908,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "191D23E8",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10031909,
          SpeakNpcId = 100304,
          Subtitle = "Yes. When I was little, I did odd jobs there for quite a long time.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100319/191D23E8"
        },
        [10031909] = {
          Camera = "-410.046875,-176.327026,296.989258,0.000092,-21.197962,21.592611,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "지금 그 자리까지 가기 쉽지 않았겠네요. 근데...",
          DialogueId = 10031909,
          FinalCamera = "-416.799805,-158.999756,296.989258,0.000093,-21.197962,19.792587,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D2412",
          NextDialogue = 10031910,
          SpeakNpcId = 200021,
          Subtitle = "Hah. To think you climbed all the way here — it couldn't have been easy. Though...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100319/191D2412"
        },
        [10031910] = {
          Camera = "-585.371094,624.871887,401.661133,0.000048,-17.12187,-52.0401,30.0,100000.0,false,Manual,22.0",
          ContentKR = "됐어요, 아무것도 아닙니다. 우리도 움직이자, 대장.",
          DialogueId = 10031910,
          FinalCamera = "-585.371094,624.871887,401.661133,0.00005,-19.122007,-48.639709,30.0,100000.0,false,Manual,22.0",
          GUID = "191D243C",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          Scripts = " LookAt{_delay{2},LookAtDescription{\"100001:n(200021)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Never mind. Let's get going too, Captain.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100319/191D243C"
        },
        [10032001] = {
          ContentKR = "<H>은촛불 축제</>가 예정대로 갈레아 극장에서 열립니다. 참가자분들은 자신이 원하는 분장을 준비하시고 연기할 신분을 선택해 주세요.\n\n우리 함께 직업도, 종족도, 갈등도 내려놓고 여기에 모여 황제 폐하의 은총에 몸을 담그고\n황제 폐하의 자비로움을 찬양합시다. 황제 폐하께 영광을!",
          DialogueId = 10032001,
          GUID = "191D332A",
          Subtitle = [[
The Silvercandle Carnival will proceed as scheduled at Galea Theatre. Participants are encouraged to prepare their finest attire and select the role they wish to embody. 
Let us set aside professions, races, and conflicts, and gather under the Emperor's grace. Together, we shall bask in His Majesty's benevolence and proclaim: All glory to our Emperor!]],
          VoiceName = "voice/$Locale$/story/1003/100320/191D332A"
        },
        [10032002] = {
          ContentKR = "어이, 거기 친구들, 지금은 공연 시간이 아니라고.",
          DialogueId = 10032002,
          GUID = "191D3354",
          SpeakNpcId = 100313,
          Subtitle = "Hey, you folks over there. The show hasn't started yet.",
          VoiceName = "voice/$Locale$/story/1003/100320/191D3354"
        },
        [10032101] = {
          Camera = "-21.816895,363.6521,125.128906,0.000173,-1.400626,-117.566429,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "어, 아웃사이더로구나.",
          DialogueId = 10032101,
          FinalCamera = "-21.816895,363.6521,145.550781,0.000173,-3.800747,-115.966316,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D4392",
          LookAt = {
            [1] = "200021:n(100313)",
            [2] = "100001:n(100313)",
            [3] = "200002:n(100313)",
            [4] = "100313:n(200021)"
          },
          NextDialogue = 10032102,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100313},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 100313,
          Subtitle = "Oh, it's you, Outsider.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100313:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100321/191D4392"
        },
        [10032102] = {
          Camera = "-101.5177,-59.163185,99.613281,0.000267,8.199198,105.035461,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "푸치 극단장님, 요즘 잘 지내시나요?",
          DialogueId = 10032102,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "-101.5177,-59.163185,102.683594,0.000267,8.199198,105.035461,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D43BC",
          NextDialogue = 10032103,
          SpeakNpcId = 200021,
          Subtitle = "Director Putsch, still going strong, I see. How have you been?",
          TalkActionId = {
            [1] = "200021:Explain01_Start",
            [2] = "100313:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100321/191D43BC"
        },
        [10032103] = {
          Camera = "-109.880814,56.36647,209.828125,0.000447,-39.203796,-115.755196,40.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "하고 싶은 말이 있으면 바로 해. 넌 이런 곳에 관심 가질만한 놈은 아니잖아.",
          DialogueId = 10032103,
          FinalCamera = "-102.916199,52.570129,212.691406,0.000442,-40.403828,-121.355377,40.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D43E6",
          NextDialogue = 10032104,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"341.679413,-359.78833,249.652344,0.000407,-15.801881,139.968948,30.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"364.691833,-325.24469,234.035156,0.000443,-14.801744,142.565659,30.0,100000.0,false,DoNotOverride,22.0"},duration{5}}
}]],
          SpeakNpcId = 100313,
          Subtitle = "Just drop the pleasantries. You're not exactly the type to hang around places like this. What do you want?",
          TalkActionId = {
            [1] = "200021:Explain01_End",
            [2] = "100313:Disagree"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100321/191D43E6"
        },
        [10032104] = {
          Camera = "-76.871582,-165.163177,125.800781,0.000465,0.196088,111.442703,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "하하, 일을 하나 받게 돼서요. '카론 사냥'과 관련된 건입니다.",
          DialogueId = 10032104,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "-68.612518,-161.773819,125.800781,0.000465,-0.403931,112.642479,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D4410",
          NextDialogue = 10032105,
          SpeakNpcId = 200021,
          Subtitle = "Haha, I'm here on a job. It's about the \"Charon Hunt.\"",
          TalkActionId = {
            [1] = "200021:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100321/191D4410"
        },
        [10032105] = {
          Camera = "227.58429,685.371338,77.011719,0.000455,-0.604465,-116.916443,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "아, 요즘 다들 떠들썩한 그 사건 말이로군. 뭘 조사하든 말든 알아서 하고, '마법 피리' 극단의 리허설만 방해하지 않으면 돼.",
          DialogueId = 10032105,
          FinalCamera = "227.58429,685.371338,85.628906,0.000455,-0.604465,-116.916443,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D443A",
          NextDialogue = 10032106,
          RelatedWikiId = {
            [1] = 404001,
            [2] = 201022
          },
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-127.73233,235.162033,163.292969,0.00052,-10.603151,-102.705711,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-121.892624,233.538239,158.339844,0.000529,-9.402985,-103.307755,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100313,
          Subtitle = "Oh, that case everyone's talking about? Do whatever you want, just don't disturb the Magic Flute troupe's rehearsals.",
          TalkActionId = {
            [1] = "100313:Agree",
            [2] = "200021:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100321/191D443A"
        },
        [10032106] = {
          Camera = "-57.99271,40.446503,110.507812,0.000493,-24.002615,60.69154,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "엄청나게 많은 사람들이 죽은 큰 사건이라고. 왜 아직도 리허설을 멈추지 않는 거야! 범인이 당신들 주변에 있다면 생명이 위험할 수도 있다고!",
          DialogueId = 10032106,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-74.687424,17.77153,121.558594,0.000493,-24.002615,60.69154,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D4464",
          LookAt = {
            [1] = "100313:n(200002)"
          },
          NextDialogue = 10032107,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"201.005814,251.918533,42.921875,0.000411,6.598099,-141.302002,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"201.005814,251.918533,48.984375,0.000413,8.198077,-141.699936,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 200002,
          Subtitle = "Seriously, you're still rehearsing? I mean it's a huge case with many fatalities! If the murderer is among you, you're all in grave danger!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100321/191D4464"
        },
        [10032107] = {
          Camera = "-293.615234,-376.854492,46.109375,0.000463,6.997617,64.301308,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "배우에게 있어선 공연을 완성하는 게 삶의 의미지, 그건 생명 그 자체보다도 눈부시다고. 오히려 공연을 멈추게 하는 게 그들의 생명을 빼앗는 거야.",
          DialogueId = 10032107,
          FinalCamera = "-299.095703,-374.287598,46.109375,0.000462,6.997617,63.701469,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191D448E",
          NextDialogue = 10032108,
          Scripts = "SEQ{CameraMoveTo{_delay{7},TargetPosition{\"102.716476,171.84108,50.386719,0.000454,10.197875,-148.500732,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"102.716476,171.84108,55.585938,0.000454,9.397876,-148.300888,35.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}}",
          SpeakNpcId = 100313,
          Subtitle = "For a performer, completing a performance is the ultimate expression of life — more brilliant and radiant than life itself. Denying them the stage is a greater tragedy than death.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100321/191D448E"
        },
        [10032108] = {
          Camera = "-601.805847,769.078125,-62.539062,-3.000002,9.000303,-56.889706,35.000008,945.516907,false,DoNotOverride,1.608127",
          ContentKR = "다들 준비해. 5분 뒤 오늘의 세 번째 리허설을 시작한다.",
          DialogueId = 10032108,
          FinalCamera = "-601.805847,769.078125,-32.179688,-3.000001,7.000288,-56.890057,35.000008,945.516907,false,DoNotOverride,1.608127",
          GUID = "191D44B8",
          LookAt = {
            [1] = "100313:n(100313)"
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{100313},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100313,
          Subtitle = "Everyone, get ready! The third rehearsal of the day starts in five minutes!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100313:p(180)"
          },
          VoiceName = "voice/$Locale$/story/1003/100321/191D44B8"
        },
        [10032109] = {
          ContentKR = "...힝, 정말 하나도 협조하지 않잖아.",
          DialogueId = 10032109,
          GUID = "191D44E2",
          NextDialogue = 10032110,
          SpeakNpcId = 200002,
          Subtitle = "...Ugh, she's really not making this easy.",
          VoiceName = "voice/$Locale$/story/1003/100321/191D44E2"
        },
        [10032110] = {
          ContentKR = "흩어져서 물어보자, 적어도 막진 않았잖아.",
          DialogueId = 10032110,
          GUID = "191D450C",
          SpeakNpcId = 100001,
          Subtitle = "Let's split up and ask around. At least she didn't stand in the way of our investigation.",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450C"
        },
        [10032111] = {
          ContentKR = "몇 번을 말하는 거야. 불은 다 쓰면 끄라니까! 또 한 번 불 끄는 걸 잊거나 쓰고 난 소품을 창고에 다시 넣지 않으면, 이 소품들을 전부 다 입에 쑤셔 넣을 줄 알아!",
          DialogueId = 10032111,
          Duration = 17,
          GUID = "191D4536",
          SpeakNpcId = 100329,
          Subtitle = "How many times do I have to say it? Turn off the lights when you're done! If I catch anyone forgetting to turn off the lights or put props back in the storage room again, I'll shove these props down their throats!",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4536"
        },
        [10032112] = {
          ContentKR = "어? 못 어디 갔지? 하필 무대 골조 보강하려니까 안 보이네.",
          DialogueId = 10032112,
          Duration = 9,
          GUID = "191D450D",
          Subtitle = "Huh? Where are the nails? Of course they vanish right when I'm fixing the rig...",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450D"
        },
        [10032113] = {
          ContentKR = "데니스는 어디 간 거야? 며칠 뒤면 공연인데, 분장 테스트랑 컨셉 사진이 데니스만 아직이야.",
          DialogueId = 10032113,
          Duration = 10,
          GUID = "191D450E",
          Subtitle = "Where's Dennis? Curtain's just days away, and he's the only one who hasn't done his look test or final shots.",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450E"
        },
        [10032114] = {
          ContentKR = "\"촛불 들고 춤추며, 이 눈 내리는 밤에 소리 높여 노래하리.\"",
          DialogueId = 10032114,
          Duration = 6,
          GUID = "191D450F",
          SpeakNpcId = 100370,
          Subtitle = "\"By candlelight, we dance and sing into the snowy night.\"",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450F"
        },
        [10032115] = {
          ContentKR = "3막 조명 디자인에 수정이 필요해. 우리가 표현하려는 건 촛불이 하나씩 켜지는 조명 변화라고. 알겠어? 하, 나, 씩, 켜, 지, 는, 거!",
          DialogueId = 10032115,
          Duration = 15,
          GUID = "191D4510",
          Subtitle = "Scene Three's lighting needs fixing. We're simulating candles being lit one by one — got it? ONE. BY. ONE!",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4510"
        },
        [10032116] = {
          ContentKR = "또 박자 놓쳤잖아. 며칠 뒤에 그 꼴로 무대 설래? 다시!",
          DialogueId = 10032116,
          Duration = 9,
          GUID = "191D4511",
          Subtitle = "You were early. Planning to hit the stage like that in a few days? Again — from the top.",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4511"
        },
        [10032117] = {
          ContentKR = "미안...",
          DialogueId = 10032117,
          Duration = 2,
          GUID = "191D4512",
          Subtitle = "Sorry...",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4512"
        },
        [10032118] = {
          ContentKR = "벨, 이따 리허설 때 이 물건들 잠깐 써야 하니까, 옮기는 것 좀 도와줘.",
          DialogueId = 10032118,
          Duration = 7,
          GUID = "191D4513",
          Subtitle = "Bell, we need all this for rehearsal — give me a hand, yeah?",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4513"
        },
        [10032119] = {
          ContentKR = "알겠어, 지금 가.",
          DialogueId = 10032119,
          Duration = 2,
          GUID = "191D4514",
          Subtitle = "Coming!",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4514"
        },
        [10032201] = {
          Camera = "-414.882477,353.665741,414.34375,0.000202,-30.196259,-52.800652,35.000015,284.991394,false,DoNotOverride,3.584893",
          ContentKR = "안녕하세요, 혹시...",
          DialogueId = 10032201,
          FinalCamera = "-414.882477,353.665741,414.34375,0.000206,-28.996235,-53.8008,35.000015,284.991394,false,DoNotOverride,3.584893",
          GUID = "191D53FA",
          LookAt = {
            [1] = "200021:n(100329)",
            [2] = "200002:n(100329)",
            [3] = "100001:n(100329)"
          },
          NextDialogue = 10032202,
          SpeakNpcId = 100001,
          Subtitle = "Excuse me, may I ask...",
          TalkActionId = {
            [1] = "100329:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D53FA"
        },
        [10032202] = {
          Camera = "-207.049316,184.011703,115.789062,0.000259,1.803177,-63.821884,35.000015,284.991394,false,DoNotOverride,3.584893",
          ContentKR = "...화관 15개, 문제없고. 승마화 9켤레, 문제없고... 됐다, 정리 끝났어. 넌 누구야, 무슨 볼일이지?",
          DialogueId = 10032202,
          FacialId = {
            [1] = "100329:CM_Angry01"
          },
          FinalCamera = "-207.049316,184.011703,115.789062,0.000259,4.003139,-64.023117,35.000015,284.991394,false,DoNotOverride,3.584893",
          GUID = "191D5424",
          NextDialogue = 10032203,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{_delay{4},ActorId{100329},AnimationId{"Think_End"},Duration{2}},
TurnTo{_delay{3},TurnToDescription{"100329:n(100001)"}}
},
SEQ{
CameraMoveTo{_delay{7},TargetPosition{"-58.123032,-61.803299,184.066406,0.000091,-16.1978,122.415901,35.000011,155.949936,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"-68.912094,-67.938797,184.066406,0.000075,-16.997759,119.416306,35.000015,155.949936,false,DoNotOverride,22.0"},duration{6}}}
}]],
          SpeakNpcId = 100329,
          Subtitle = "...Fifteen flower crowns, check. Nine pairs of riding boots, check. Alright, inventory's done. Now, who are you, and what do you want?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5424"
        },
        [10032203] = {
          Camera = "-51.966774,-30.787083,127.144531,0.000101,1.200146,-113.183083,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentKR = "이 천이 여기 극장의 것이 맞나요?",
          DialogueId = 10032203,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-51.966774,-30.787083,124.570312,0.000114,3.000078,-113.18206,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191D544E",
          NextDialogue = 10032204,
