        [10032204] = {
          Camera = "-38.398422,-255.859344,70.714844,0.000165,6.599745,108.419289,40.0,340.239532,false,Manual,3.429005",
          ContentKR = "바느질도, 패턴도 잘못됐어, 갈레아 극장은 이런 쓰레기 같은 물건 안 써. 누가 보냈지? 너 어디 기자야? 우리 극장 소품이 형편없다는 헛소문 퍼뜨리러 온 건가?",
          DialogueId = 10032204,
