        [10032529] = {
          Camera = "144.700195,198.821289,123.930664,0.000542,0.797261,-121.204803,45.000011,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "...돌겠네, 카밀라가 이 녀석 열은 다 내렸다고 하지 않았냐?",
          DialogueId = 10032529,
          FacialId = {
