          GUID = "191D89A0",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100304:n(200021)"
          },
          NextDialogue = 10032530,
          SpeakNpcId = 200021,
          Subtitle = "...Seriously? Didn't Camilla say you were over the fever?",
          TalkActionId = {
