          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D89A0"
        },
        [10032530] = {
          Camera = "33.316406,-37.37793,155.04126,0.000549,-10.602694,72.394211,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentKR = "군단의 명예를 함부로 모욕해서는 안 됩니다. 그런 농담은 하지 말아주십시오! 작살과 생선 기름, 이 두 단서를 결합해 봤을 때, 용의자는 '어부'일 확률이 가장 높습니다.",
          DialogueId = 10032530,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "50.216919,18.608398,144.636963,0.000552,-9.602693,71.39389,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D89CA",
          NextDialogue = 10032531,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{1.5},TargetPosition{\"-24.407104,-565.220215,68.926025,0.000549,4.198333,79.992966,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-13.015869,-567.29248,68.926025,0.00055,4.198333,80.392738,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Angry01_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "The honour of the Legion is not to be tarnished. Please don't joke about such things! Considering the harpoon and fish oil, I think the suspect is most likely to be a fisherman.",
          TalkActionId = {
            [1] = "100304:Angry01_Start",
            [2] = "200021:Sigh_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100325/191D89CA"
        },
        [10032531] = {
          Camera = "26.899658,-53.543457,109.033691,0.000668,3.801936,71.611046,35.000008,459.907166,false,DoNotOverride,3.252207",
          ContentKR = "아이스레이크 시티의 어부들은 대부분 안개 지역, 즉 빈민가에 거주하고 있습니다. 더 이상 미룰 시간이 없으니 얼른 그곳으로 가서 찾아보도록 하죠.",
          DialogueId = 10032531,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "24.10376,-52.599609,109.033691,0.000668,4.201932,71.410896,35.000008,459.907166,false,DoNotOverride,3.252207",
          GUID = "191D89F4",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"564.560242,341.522949,164.406982,0.000664,-6.397831,-142.585052,35.0,459.907166,false,Manual,3.252207\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"571.416809,346.806641,165.377197,0.000665,-6.397831,-142.385117,35.0,459.907166,false,Manual,3.252207\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "Most of Icelake's fishermen live in Mist Aken, aka the slums. Let's head there immediately and see what we can find.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D89F4"
        },
        [10032601] = {
          ContentKR = "이 근처에 사는 사람들은 전부 어부예요. 리듬 장교님, 어디서부터 찾아야 할까요?",
          DialogueId = 10032601,
          GUID = "191D959A",
          SpeakNpcId = 200021,
          Subtitle = "This area's full of fishermen. Where do we start, Officer Fischer?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D959A"
        },
        [10032602] = {
          ContentKR = "야옹~ 야옹~",
          DialogueId = 10032602,
          GUID = "191D95C4",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow— Meow!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D95C4"
        },
        [10032603] = {
          ContentKR = "야옹... 냥?",
          DialogueId = 10032603,
          GUID = "191D95EE",
          NextDialogue = 10032604,
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow... Meow?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D95EE"
        },
        [10032604] = {
          ContentKR = "(고양이가 리듬을 빤히 쳐다보고 있다... 뭔가 특별한 냄새를 맡은 걸까?)",
          DialogueId = 10032604,
          DisableMouth = 1,
          GUID = "191D9618",
          NextDialogue = 10032605,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(This cat keeps staring at Rhythm... Could it have picked up on some strange scent?)",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9618"
        },
        [10032605] = {
          ContentKR = "리듬 장교님, 그 생선 기름 잠시 줘 보세요.",
          DialogueId = 10032605,
          GUID = "191D9642",
          NextDialogue = 10032606,
          SpeakNpcId = 100001,
          Subtitle = "Officer Fischer, could I borrow that fish oil for a second?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9642"
        },
        [10032606] = {
          ContentKR = "여기요, 뭔가 발견하셨나요?",
          DialogueId = 10032606,
          GUID = "191D966C",
          NextDialogue = 10032607,
          SpeakNpcId = 100304,
          Subtitle = "Here. Did you notice something?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D966C"
        },
        [10032607] = {
          ContentKR = "네, 확인해 볼 게 있어요.",
          DialogueId = 10032607,
          GUID = "191D9696",
          NextDialogue = 10032608,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. I've got a theory I want to test.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9696"
        },
        [10032608] = {
          ContentKR = "냥... 냥냥!",
          DialogueId = 10032608,
          GUID = "191D96C0",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow— Meowww!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96C0"
        },
        [10032609] = {
          ContentKR = "저 고양이를 따라가 봐요. 우릴 어딘가로 데려가려는 것 같아요.",
          DialogueId = 10032609,
          GUID = "191D96EA",
          NextDialogue = 10032610,
          SpeakNpcId = 100001,
          Subtitle = "Let's follow that cat — I think it's trying to lead us somewhere.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EA"
        },
        [10032610] = {
          ContentKR = "예리하시군요, 조련사 출신답습니다.",
          DialogueId = 10032610,
          GUID = "191D96EB",
          NextDialogue = 10032611,
          SpeakNpcId = 100304,
          Subtitle = "Sharp instincts. True to your roots as an animal trainer.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EB"
        },
        [10032611] = {
          ContentKR = "(...아웃사이더, 나중에 보자.)",
          DialogueId = 10032611,
          DisableMouth = 1,
          GUID = "191D96EC",
          NextDialogue = 10032612,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Thanks for that, Outsider.)",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EC"
        },
        [10032612] = {
          ContentKR = "야옹~ 냥냥냥냥!",
          DialogueId = 10032612,
          GUID = "191D9714",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow— Meow meow meowwww!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9714"
        },
        [10032613] = {
          ContentKR = "고양이가 앞쪽에서 사라졌다.",
          DialogueId = 10032613,
          GUID = "191D973E",
          Subtitle = "The cat disappeared into the distance.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D973E"
        },
        [10032614] = {
          ContentKR = "내 시종을 괴롭힌 나쁜 놈, 여기 숨어 있었네!",
          DialogueId = 10032614,
          GUID = "191D9768",
          NextDialogue = 10032615,
          SpeakNpcId = 200002,
          Subtitle = "Aha! You scoundrel! How dare you hurt my Little Minion and then think you can hide! Justice has arrived!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9768"
        },
        [10032615] = {
          ContentKR = "엇? 방위대? 때리지 말아 주십쇼. 다 얘기할게요, 다!",
          DialogueId = 10032615,
          GUID = "191D9792",
          SpeakNpcId = 100314,
          Subtitle = "Huh? The Escort? Please, don't hurt me! I'll talk! I'll tell you everything!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9792"
        },
        [10032701] = {
