        [10032702] = {
          Camera = "334.231567,591.792969,521.387695,0.000063,-16.398499,128.194473,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "요즘 고기가 별로 안 잡혀서 액체 폭시코르를 좀 훔쳤어요. 그게 이렇게 많은 사람들이 출동할 일인가... 장교님들, 한 번만 봐주십쇼...",
          DialogueId = 10032702,
          FacialId = {
            [1] = "100314:CM_Shock01",
            [2] = [[

100304:None]]
          },
          FinalCamera = "334.231567,591.792969,531.23877,0.000063,-16.798521,128.19429,35.000008,100000.0,false,Manual,22.0",
          GUID = "191DA62C",
          NextOptions = {
            [1] = 10032703,
            [2] = 10032705
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{100314},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 100314,
          Subtitle = "I haven't been catching much fish lately, so I stole a couple of Phoxichor canisters to sell... But does that really warrant this many people chasing after me? Officers, please, have mercy! Give me another chance, I beg you...",
          TalkActionId = {
