          VoiceName = "voice/$Locale$/story/1003/100327/191DA680"
        },
        [10032705] = {
          ContentKR = "하는 거 봐서. 장교님의 총은 인내심이 별로 없으시거든.",
          DialogueId = 10032705,
          GUID = "191DA6AA",
          ImprPlusId = 1006,
          NextDialogue = 10032706,
          Subtitle = "That depends on how much you're willing to cooperate. This officer's gun isn't exactly known for its patience."
        },
        [10032706] = {
