          FacialId = {
            [1] = "100001:Unhappy01",
            [2] = "100304:Sad02"
          },
          FinalCamera = "256.6875,-29.730164,40.941162,-0.000244,7.596707,164.966385,35.000015,1.5,false,DoNotOverride,1.2",
          GUID = "191E296C",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10033503,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay. But Officer Fischer is...",
          TalkActionId = {
