        },
        [10033505] = {
          Camera = "-112.908203,-136.419312,107.219604,0.000322,13.597683,-108.007072,35.000023,100000.0,false,Manual,22.0",
          ContentKR = "군단에 대한 여러분의 도움에 감사드립니다. 여러분이 없었다면 방위대의 사상자는 더 많았을 겁니다.",
          DialogueId = 10033505,
          FinalCamera = "-107.800781,-138.011902,107.219604,0.000322,13.397675,-110.206947,35.000023,100000.0,false,Manual,22.0",
          GUID = "191E29EA",
          LookAt = {
            [1] = "200021:n(100311)",
            [2] = "200002:n(100311)"
          },
          NextOptions = {
            [1] = 10033506
          },
          Scripts = "PARA{SetLocation{ActorId{200021},TargetPoint{\"Point1\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point2\"},Visibility{\"Show\"}},SetRotation{SetRotationDescription{\"100311:n(100001)\"}},SetRotation{SetRotationDescription{\"100001:n(100311)\"}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-235.177734,-315.901123,148.828979,0.00035,-3.202812,42.790451,40.0,412.833496,false,Manual,4.354144\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-238.75,-312.088318,148.828979,0.000349,-3.202819,40.790806,40.0,412.833496,false,Manual,4.354144\"},duration{10}}}}",
          SpeakNpcId = 100311,
          Subtitle = "Thank you so much for your help. Without you, the Escort would've suffered far more casualties.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E29EA"
        },
        [10033506] = {
          ContentKR = "별거 아닙니다.",
          DialogueId = 10033506,
          GUID = "191E2A14",
          NextDialogue = 10033507,
          Subtitle = "Just doing my part."
        },
        [10033507] = {
          Camera = "1902.650391,-988.80188,108.232178,0.000259,-0.801236,149.196533,35.000011,3157.576416,false,Manual,1.376868",
          ContentKR = "네, 도와주셔서 감사합니다. 동료들에게 연락해서 바깥으로 안내해 드리겠습니다.",
          DialogueId = 10033507,
          FinalCamera = "1898.128906,-996.384766,108.232178,0.000259,-0.801236,149.596466,35.000011,3157.576416,false,Manual,1.376868",
          GUID = "191E2A3E",
          NextDialogue = 10033508,
          SpeakNpcId = 100311,
          Subtitle = "Still, we truly appreciate it. I'll contact my squadmates and have them escort you out.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2A3E"
        },
        [10033508] = {
          Camera = "-138.914062,-208.657227,182.986816,-0.000002,-38.999802,-104.019676,35.000023,100000.0,false,Manual,22.0",
          ContentKR = "무전기 고장인가... 어쩔 수 없군요, 조금만 걸으시면 저희 동료들을 만나실 수 있을 겁니다. 저희는 당신들이 들어오신 통로를 전부 봉쇄해야 하니 먼저 밖을 향해 가십시오.",
          DialogueId = 10033508,
          FinalCamera = "-125.476562,-154.847595,227.898438,18.000706,-38.999802,-104.019608,35.000023,100000.0,false,Manual,22.0",
          GUID = "191E2A68",
          LookAt = {
            [1] = "200021:n(100311)",
            [2] = "200002:n(100311)"
          },
          NextDialogue = 10033509,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-83.787109,-712.988647,30.291992,-0.001007,8.196595,93.593033,35.000023,505.590393,false,Manual,11.621747\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-104.068359,-713.623779,30.291992,-0.001008,9.196576,91.393059,35.000023,505.590393,false,Manual,11.621747\"},duration{10}}}}",
          SpeakNpcId = 100311,
          Subtitle = "Ugh, the comms are acting up again. Never mind, you'll run into them on your way out. We'll have to seal off the tunnels you came through. Just head that way, and you'll see them soon.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2A68"
        },
        [10033509] = {
          Camera = "108.683594,-29.236145,139.334595,0.000065,-0.203772,172.19281,35.000011,100000.0,false,Manual,22.0",
          ContentKR = "재수도 없네, 일어나자마자 또 이런 난리라니, 리듬이 한번 막아주지 않았다면 넌 또 며칠 동안 누워있어야 했을지도 몰라.",
          DialogueId = 10033509,
          FinalCamera = "109.099609,-16.699524,139.334595,0.000065,-1.003785,179.992462,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E2A92",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 10033510,
          Scripts = "PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Man, you've had it rough. Just woke up from a coma, and now this. If Rhythm hadn't stepped in, you'd probably be taking another long nap right now.",
          TalkActionId = {
            [1] = "200021:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2A92"
        },
        [10033510] = {
          Camera = "-223.230469,-130.493103,71.03064,0.00022,14.995399,178.000687,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentKR = "그래, 그래, 스노우 아깐 정말 깜짝 놀랐어! 내 시종한테 어버버 거리는 후유증이라도 남으면 정말 어떡해!",
          DialogueId = 10033510,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-151.314453,-134.048645,51.274292,0.000221,13.395059,176.400452,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2ABC",
          NextOptions = {
            [1] = 10033511,
            [2] = 10033513
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 200002,
          Subtitle = "Yeah! You almost gave me a heart attack back there! I was so worried my Little Minion would end up with serious brain damage and not even recognise me anymore!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2ABC"
        },
        [10033511] = {
          ContentKR = "걱정해줘서 고마워.",
          DialogueId = 10033511,
          GUID = "191E2AE6",
          ImprPlusId = 1009,
          NextDialogue = 10033512,
          Subtitle = "Thank you for caring about me."
        },
        [10033512] = {
          Camera = "121.15625,-31.336243,130.51001,0.000213,2.795951,170.599884,35.000015,100000.0,false,Manual,22.0",
          ContentKR = "친구끼리 고마운게 어딨어.",
          DialogueId = 10033512,
          FinalCamera = "143.15625,-34.978027,129.421143,0.000213,2.795951,170.599884,35.000015,100000.0,false,Manual,22.0",
          GUID = "191E2B10",
          NextDialogue = 10033516,
          Scripts = "SEQ{PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{2}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "C'mon, no need to get all formal with your buddies.",
          TalkActionId = {
            [1] = "200021:Talk02_Start",
            [2] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B10"
        },
        [10033513] = {
          ContentKR = "됐어, 난 정말 괜찮아.",
          DialogueId = 10033513,
          GUID = "191E2B3A",
          ImprPlusId = 1007,
          NextDialogue = 10033514,
          Subtitle = "I'm fine, really."
        },
        [10033514] = {
          Camera = "171.294922,-63.202942,123.535767,0.000178,2.594707,165.981323,35.000015,100000.0,false,Manual,22.0",
          ContentKR = "어디 불편하면 바로 말해. 젊었을 땐 아무 느낌도 없다가 늙으면 고생하는 상처도 있다고.",
          DialogueId = 10033514,
          FinalCamera = "167.292969,-79.613342,123.535767,0.000178,2.394664,161.180527,35.000015,100000.0,false,Manual,22.0",
          GUID = "191E2B64",
          NextDialogue = 10033515,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Just don't stay quiet if something's wrong, okay? Some injuries don't show until you're old — then they hit you like a truck.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B64"
        },
        [10033515] = {
          Camera = "-241.916016,12.718933,151.480347,0.000221,-24.00493,-116.195557,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentKR = "아웃사이더는 어떻게 저런 어린 나이에 할아버지처럼 얘기하고 있을까?",
          DialogueId = 10033515,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "-230.193359,6.846252,151.480347,0.000232,-24.604969,-123.195885,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2B8E",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10033516,
          SpeakNpcId = 200002,
          Subtitle = "Wow, Outsider, you sound like a grandpa.",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B8E"
        },
        [10033516] = {
          Camera = "-24.765625,-99.843445,139.282227,0.000232,2.592227,163.993256,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentKR = "됐어, 이제 우리가 해야 할 일은 없는 것 같으니까, 집에 가서 쉴까?",
          DialogueId = 10033516,
          FinalCamera = "-32.369141,-124.105286,139.282227,0.000233,2.592227,157.393356,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2BB8",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 10033517,
          SpeakNpcId = 200021,
          Subtitle = "Alright, since our work here's done, how about we head home and rest up?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2BB8"
        },
        [10033517] = {
          Camera = "-140.902344,-181.350952,57.819458,0.000238,9.192799,159.999252,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentKR = "우음... 아까 리듬 장교님이 많이 다친 것 같던데, 먼저 리듬 장교님부터 보러 가자!",
          DialogueId = 10033517,
          FacialId = {
            [1] = "200002:Sad03"
          },
          FinalCamera = "-132.044922,-150.669006,57.819458,0.00024,9.592809,170.198151,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2BE2",
          NextDialogue = 10033518,
          Scripts = "PlayFacial{_delay{3},ActorId{200002},FacialId{\"None\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Mmm... but Officer Fischer looked really bad back there! Shouldn't we check on her first?",
          TalkActionId = {
            [1] = "200002:Bai_Think2Confident",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2BE2"
        },
        [10033518] = {
          Camera = "-69.097656,-83.115845,148.539307,0.000209,1.550528,163.935776,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentKR = "내성의 군단 병원으로 보내졌을 거야. 너 내성이 어떤 곳인지 잘 알잖아, 우린 못 들어가.",
          DialogueId = 10033518,
          FinalCamera = "-30.691406,-94.174072,147.457397,0.000209,1.550528,163.935776,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2C0C",
          LookAt = {
            [1] = "200021:n(100311)"
          },
          NextDialogue = 10033519,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"588.361328,-259.9021,29.950439,0.000221,6.195254,167.58075,35.000019,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"579.164062,-298.835632,29.950439,0.000221,5.995246,163.979752,35.000019,100000.0,false,Manual,22.0\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "She's probably been taken to the Legion Hospital in the inner city. You know how that place is — there's no way they'll just let us waltz in.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2C0C"
        },
        [10033519] = {
          Camera = "-144.302734,-80.81012,63.27771,0.000198,7.796223,-165.788574,35.000011,100000.0,false,Manual,22.0",
          ContentKR = "그래도 해봐야지! 아까도 우리가 그렇게 많이 도와줬는데, 이따가 데리러 오는 병사들이 들어가게 해줄 지도 몰라!",
          DialogueId = 10033519,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "-121.376953,-75.004456,60.040405,0.0002,7.796223,-165.787888,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E2C36",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 10033520,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-424.035156,-125.463745,95.406128,-0.001007,1.595539,15.6097,35.000019,505.590393,false,Manual,11.621747\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-427.814453,-110.609375,95.406128,-0.001007,1.595539,12.010799,35.000019,505.590393,false,Manual,11.621747\"},duration{5}}},PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}}}",
          SpeakNpcId = 200002,
          Subtitle = "Come on, let's at least try! We helped out a ton just now! Maybe the soldiers will help get us in.",
          TalkActionId = {
            [1] = "200002:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2C36"
        },
        [10033520] = {
          Camera = "-2.652344,-20.905457,137.411133,-0.001007,6.791995,19.24058,35.000023,505.590393,false,DoNotOverride,11.621747",
          ContentKR = "물어는 보자. 그래도...",
          DialogueId = 10033520,
          FinalCamera = "-3.791016,-17.602783,137.411133,-0.001007,6.791995,19.24058,35.000023,505.590393,false,DoNotOverride,11.621747",
          GUID = "191E2C60",
          NextOptions = {
            [1] = 10033521,
            [2] = 10033523
          },
          SpeakNpcId = 100001,
          Subtitle = "Let's give it a try. After all...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2C60"
        },
        [10033521] = {
          ContentKR = "약속한 보수도 아직 못 받았어.",
          DialogueId = 10033521,
          GUID = "191E2C8A",
          ImprPlusId = 1006,
          NextDialogue = 10033522,
          Subtitle = "She hasn't fulfilled her promise yet."
        },
        [10033522] = {
          Camera = "-225.560547,-129.777405,118.852295,0.000196,-27.401426,176.001938,35.000011,3519.813721,false,DoNotOverride,1.257729",
          ContentKR = "맞네... 그러고 보니 우리가 처음에 리듬 장교님을 찾아간 것도 네 가족의 소식 때문이었잖아! 까먹을 뻔했네!",
          DialogueId = 10033522,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "-209.878906,-130.874634,127.011353,0.000196,-27.401426,176.001938,35.000011,3519.813721,false,DoNotOverride,1.257729",
          GUID = "191E2CB4",
          NextDialogue = 10033525,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"112.146484,-9.554932,152.045166,0.000209,-9.000365,-178.801422,35.000011,3519.813721,false,DoNotOverride,1.257729\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"112.146484,-9.554932,152.045166,0.000209,-12.200309,-171.200958,35.000011,3519.813721,false,DoNotOverride,1.257729\"},duration{8}}}",
          SpeakNpcId = 200002,
          Subtitle = "Oh, right! We went to her in the first place — so she could dig up info about your family. Almost forget about that part!",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2CB4"
        },
        [10033523] = {
          ContentKR = "아까 그녀가 날 구해줬어.",
          DialogueId = 10033523,
          GUID = "191E2CDE",
          ImprPlusId = 1009,
          NextDialogue = 10033524,
          Subtitle = "She just saved my life."
        },
        [10033524] = {
          ContentKR = "괜찮습니다, 시민들을 보호하는 건 제 책임입니다... 당신들이 괜찮다면... 됐어요.",
          DialogueId = 10033524,
          GUID = "191E2D08",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10033524.T_Story_Recall_10033524'",
          NextDialogue = 10033525,
          SpeakNpcId = 100304,
          Subtitle = "It's alright... Protecting civilians is my duty... as long as... you're all safe...",
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D08"
        },
        [10033525] = {
          Camera = "2442.072266,-1239.279053,1486.851685,0.000195,-26.801941,154.004623,55.0,3519.813721,false,Manual,1.257729",
          ContentKR = "알았어, 알았다고, 너희들 의견대로 할게, 지금 가면 되지?",
          DialogueId = 10033525,
          FinalCamera = "2433.271484,-1257.322388,1486.851562,0.000196,-27.001888,153.805222,55.0,3519.813721,false,Manual,1.257729",
          GUID = "191E2D32",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextOptions = {
            [1] = 10033526,
            [2] = 10033527
          },
          SpeakNpcId = 200021,
          Subtitle = "Alright, alright. Whatever you say. So, should we go now?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D32",
          bForbidSkipOptions = true
        },
        [10033526] = {
          ContentKR = "응, 일단 이 하수도부터 빠져나가자.",
          DialogueId = 10033526,
          GUID = "191E2D33",
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Yeah, let's leave the sewers first."
        },
        [10033527] = {
          ContentKR = "조금만 기다려줘.",
          DialogueId = 10033527,
          GUID = "191E2D34",
          NextDialogue = 10033528,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Just a second."
        },
        [10033528] = {
          ContentKR = "그래, 그럼 준비가 다 되면 바로 나가자.",
          DialogueId = 10033528,
          GUID = "191E2D35",
          SpeakNpcId = 200021,
          Subtitle = "Sure, whenever you're ready.",
          VoiceName = "voice/$Locale$/story/1003/100335/191E2D35"
        },
        [10033601] = {
          ContentKR = "응? 누가 데리러 와준다고 하지 않았어? 어디 있는 거지?",
          DialogueId = 10033601,
          GUID = "191E39AA",
          NextDialogue = 10033602,
          SpeakNpcId = 200002,
          Subtitle = "Hmm? Weren't there supposed to be soldiers meeting us here? Where are they?",
          VoiceName = "voice/$Locale$/story/1003/100336/191E39AA"
        },
        [10033602] = {
          ContentKR = "여길 봐, 벽에 총알 자국이 빽빽하게 있어.",
          DialogueId = 10033602,
          GUID = "191E39D4",
          NextDialogue = 10033603,
          SpeakNpcId = 100001,
          Subtitle = "Look — there's a cluster of bullet holes on the wall.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E39D4"
        },
        [10033603] = {
          ContentKR = "쯧... 우릴 데리러 온 사람들이 범인이랑 마주친 건가? 골치 아프게 됐네.",
          DialogueId = 10033603,
          GUID = "191E39FE",
          NextDialogue = 10033604,
          SpeakNpcId = 200021,
          Subtitle = "Ugh... Looks like the team sent to meet us ran into the perp. This isn't good.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E39FE"
        },
        [10033604] = {
          ContentKR = "...총알 자국의 흔적으로 봐선, 범인은 이쪽으로 간 것 같아. 우리도 한번 가보자.",
          DialogueId = 10033604,
          GUID = "191E3A28",
          SpeakNpcId = 100001,
          Subtitle = "Look at the pattern of the bullet holes... The perpetrator probably went this way. Let's go.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A28"
        },
        [10033605] = {
          ContentKR = "진짜 여기 맞아? 근처에 아무것도 없잖아...",
          DialogueId = 10033605,
          GUID = "191E3A52",
          NextDialogue = 10033606,
          SpeakNpcId = 200002,
          Subtitle = "Are we sure it's this way? There's nothing here...",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A52"
        },
        [10033606] = {
          ContentKR = "여기 바람이 다른 곳보다 더 강하다는 느낌이 들지 않아?",
          DialogueId = 10033606,
          GUID = "191E3A7C",
          NextDialogue = 10033607,
          SpeakNpcId = 100001,
          Subtitle = "Do you feel that? The wind here is stronger than in the other areas.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3A7C"
        },
        [10033607] = {
          ContentKR = "내가 올라가 볼게.",
          DialogueId = 10033607,
          GUID = "191E3AA6",
          NextDialogue = 10033608,
          SpeakNpcId = 200021,
          Subtitle = "Let me get up there and have a look.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AA6"
        },
        [10033608] = {
          ContentKR = "호오, 촉이 꽤 날카롭네. 여기 있는 파이프가 방금 누군가에 의해 파괴당한 것 같아.",
          DialogueId = 10033608,
          GUID = "191E3AD0",
          NextDialogue = 10033609,
          SpeakNpcId = 200021,
          Subtitle = "Ha, you're pretty sharp. The pipe up here looks like it was damaged recently.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AD0"
        },
        [10033609] = {
          ContentKR = "파이프가 이어진 방향으로 봤을 때 범인은 저 앞에 있는 출구 근처에서 나올 것 같아.",
          DialogueId = 10033609,
          GUID = "191E3AFA",
          NextDialogue = 10033610,
          SpeakNpcId = 200021,
          Subtitle = "Judging by the direction it leads, the perp might be heading out the next exit.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3AFA"
        },
        [10033610] = {
          ContentKR = "그래, 다들 조심해.",
          DialogueId = 10033610,
          GUID = "191E3B24",
          SpeakNpcId = 100001,
          Subtitle = "Okay, let's keep moving and stay alert.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B24"
        },
        [10033611] = {
          ContentKR = "응? 누가 데리러 와준다고 하지 않았어? 어디 있는 거지?",
          DialogueId = 10033611,
          GUID = "191E3B25",
          NextDialogue = 10033612,
          SpeakNpcId = 200002,
          Subtitle = "Hmm? Weren't there supposed to be soldiers meeting us here? Where are they?",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B25"
        },
        [10033612] = {
          ContentKR = "스읍, 뭔가 이상해.",
          DialogueId = 10033612,
          GUID = "191E3B4E",
          NextDialogue = 10033613,
          SpeakNpcId = 200021,
          Subtitle = "Hold up... something feels off.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B4E"
        },
        [10033613] = {
          ContentKR = "<H>바람 소리</> 빼면... 너무 조용하잖아.",
          DialogueId = 10033613,
          GUID = "191E3B78",
          SpeakNpcId = 100001,
          Subtitle = "It's too quiet... except for the wind.",
          VoiceName = "voice/$Locale$/story/1003/100336/191E3B78"
        },
        [10033701] = {
          Camera = "451.776855,-745.246033,486.225739,0.00026,-26.796326,117.802917,25.000006,100000.0,false,Manual,22.0",
          ContentKR = "어엇?! 우릴 마중나온 사람들 아니야? 어, 어떻게 된 거야!",
          DialogueId = 10033701,
          FinalCamera = "464.883423,-770.101318,500.417236,0.00026,-26.796326,117.802917,25.000006,100000.0,false,Manual,22.0",
