          GUID = "191E6D2E",
          NextDialogue = 10033916,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"138.259766,246.894287,49.095703,0.000111,7.945723,-128.444931,35.000015,329.660828,false,Manual,2.012213\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"138.259766,246.894287,49.095703,0.000112,12.545684,-128.244171,35.000015,207.928787,false,Manual,2.012213\"},duration{5}}},PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Sigh_End\"},Duration{2}}}",
          SpeakNpcId = 100359,
          Subtitle = "Blues...? Keep it down... I'm so sleepy...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D2E"
        },
        [10033916] = {
          Camera = "526.81543,176.885864,156.60498,0.000122,-6.853343,-167.440613,35.000008,563.148376,false,Manual,1.225325",
          ContentKR = "아잇 진짜, 누난 자꾸 낮에 자더라. 내일이면 시험이야! 방금 내가 어디까지 얘기했는지 기억나?",
          DialogueId = 10033916,
          FinalCamera = "530.197266,161.683472,156.60498,0.000122,-6.85333,-167.240479,35.000008,563.148376,false,Manual,1.225325",
          GUID = "191E6D58",
          NextDialogue = 10033917,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"26.428711,93.085571,95.163818,0.000168,4.34385,-109.880463,35.000015,126.514526,false,Manual,7.109471\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"26.289062,92.703491,95.163818,0.000167,7.343805,-110.680161,35.000015,126.514526,false,Manual,7.109471\"},duration{5}}}",
          SpeakNpcId = 100357,
          Subtitle = "Seriously, you're napping in the middle of the day again? The test's tomorrow! Do you even remember where I left off?",
          TalkActionId = {
            [1] = "100357:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D58"
        },
        [10033917] = {
          Camera = "46.933594,-142.992432,70.192139,0.000176,5.9446,109.526016,35.000011,306.744568,false,Manual,7.109471",
          ContentKR = "아마도... 카론의... '죄업'? 그, 그게 뭐였지...",
          DialogueId = 10033917,
          FacialId = {
            [1] = "100359:Think01"
          },
          FinalCamera = "46.933594,-142.992432,79.62915,0.000177,5.9446,109.526001,35.000011,306.744568,false,Manual,7.109471",
          GUID = "191E6D82",
          NextDialogue = 10033918,
          Scripts = "PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100359,
          Subtitle = "Uh... something about the Charons'... \"sins\"? Yes, what was that again?",
          TalkActionId = {
            [1] = "100359:Explain02_Start",
            [2] = "100357:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6D82"
        },
        [10033918] = {
          Camera = "8.995117,69.829834,100.221191,0.000187,6.743834,-101.07547,35.000015,106.301834,false,Manual,7.109471",
          ContentKR = "에휴, 또 수업 시간에 놀았나 보네.",
          DialogueId = 10033918,
          FacialId = {
            [1] = "100357:Smile01"
          },
          FinalCamera = "18.592773,67.906982,100.221191,0.000188,6.743834,-106.47596,35.000015,106.301834,false,Manual,7.109471",
          GUID = "191E6DAC",
          NextDialogue = 10033919,
          SpeakNpcId = 100357,
          Subtitle = "Ugh, figures you've been slacking off in class again.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6DAC"
        },
        [10033919] = {
          Camera = "22.104492,41.488037,139.45166,10.816259,-23.854141,115.722862,35.000023,106.301834,false,DoNotOverride,7.109471",
          ContentKR = "헤헤... 밤에 일하면 너무 피곤해서... 우리 블루스가 과외 해줄 건데 뭐 어때.",
          DialogueId = 10033919,
          FacialId = {
            [1] = "100359:Ahaha01"
          },
          FinalCamera = "14.884766,37.489014,138.013672,10.817234,-22.054098,108.921974,35.000023,106.301834,false,DoNotOverride,7.109471",
          GUID = "191E6DD6",
          NextDialogue = 10033920,
          SpeakNpcId = 100359,
          Subtitle = "Hehe... working at night always leaves me too sleepy for school the next day... But hey, that's what I've got you for — my personal tutor!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6DD6"
        },
        [10033920] = {
          Camera = "105.572266,235.572021,152.555908,-0.000184,-12.201387,-122.479736,35.000015,106.301834,false,DoNotOverride,7.109471",
          ContentKR = "휴, 일은 나도 같이 하고 있잖아. 학교 다닐 날이 2년 밖에 안 남았는데 아직도 수업을 제대로 안 듣고 있으면 어떡해...\n아무튼 카론의 '죄업' 얘기로 돌아가면, 역시 <H>눈물의 호수의 밤</> 이야기부터 시작해야 해...",
          DialogueId = 10033920,
          FinalCamera = "119.550781,226.407837,152.555908,-0.000183,-12.201387,-127.679604,35.000015,106.301834,false,DoNotOverride,7.109471",
          GUID = "191E6E00",
          NextDialogue = 10033921,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"57.916016,117.509399,78.924561,-0.000183,9.39821,-114.472267,35.000019,106.301834,false,DoNotOverride,7.109471\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"62.908203,115.10022,78.924561,-0.000182,9.398203,-117.471146,35.000019,106.301834,false,DoNotOverride,7.109471\"},duration{10}}},PlayAnimation{_delay{6},ActorId{100359},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 100357,
          Subtitle = "*sigh* I had to work too, but you don't see me nodding off in class. We only get a few years of schooling... How can you just waste them like that? Anyway — the Charons' \"sins.\" It all started from the \"Night of Lamenting Lake.\"",
          TalkActionId = {
            [1] = "100357:Angry01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E00"
        },
        [10033921] = {
          Camera = "21.583984,37.977295,146.400635,-0.000183,-24.001146,-114.668968,35.000015,106.301834,false,DoNotOverride,7.109471",
          ContentKR = "천 년 전, 바로 우리 아이스레이크 시티에서, 뿔 달린 '악마' 카론들이 솔라와 함께 눈물의 호수에서 축제를 여는 척하다가, 그날 밤 아주 나쁜 짓을 저질렀어! 그 자리에 있던 솔라들은 거의 다 목숨을 잃었지...",
          DialogueId = 10033921,
          FacialId = {
            [1] = "100357:Sad01"
          },
          FinalCamera = "21.583984,37.977295,146.400635,-0.000187,-19.60116,-115.469559,35.000015,106.301834,false,DoNotOverride,7.109471",
          GUID = "191E6E2A",
          NextDialogue = 10038401,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"208.77832,286.108398,72.5625,-0.000182,9.583554,-134.240799,35.000023,106.301834,false,DoNotOverride,7.109471\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"208.77832,286.108398,72.5625,-0.000183,3.783597,-132.241501,35.000023,106.301834,false,DoNotOverride,7.109471\"},duration{10}}}",
          SpeakNpcId = 100357,
          Subtitle = "A thousand years ago, right here in Icelake, the horned \"demons\" — the Charons — pretended to join the Solarians for a lakeside festival. But that very night, they did something terrible... Nearly every Solarian there was slaughtered.",
          TalkActionId = {
            [1] = "100359:Explain02_End",
            [2] = "100357:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2A"
        },
        [10033922] = {
          Camera = "23.90625,145.747559,110.425293,-0.000397,-0.998471,-109.465141,35.000019,183.023834,false,Manual,5.506591",
          ContentKR = "'눈물의 호수의 밤'에 저지른 잘못 때문에, 카론의 후손들은 평생에 걸쳐 선조들이 지은 죄를 갚아야만 해.",
          DialogueId = 10033922,
          FacialId = {
            [1] = "100357:None"
          },
          FinalCamera = "28.929688,143.939087,110.425293,-0.000397,-0.998471,-111.464867,35.000019,183.023834,false,Manual,5.506591",
          GUID = "191E6E54",
          NextDialogue = 10033923,
          SpeakNpcId = 100357,
          Subtitle = "That's why... for the crime of the \"Night of Lamenting Lake\", every Charon born since must carry the burden of that sin for the rest of their lives.",
          TalkActionId = {
            [1] = "100357:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E54"
        },
        [10033923] = {
          Camera = "104.679688,-172.143555,57.492432,-0.000398,7.801148,118.534103,35.000015,301.429138,false,Manual,2.621887",
          ContentKR = "하지만, 이미 이렇게 오랜 시간이 지났는 걸... 우린 아직도 평생을 바쳐서 속죄해야 하는 거야?",
          DialogueId = 10033923,
          FacialId = {
            [1] = "100359:Sad01"
          },
          FinalCamera = "104.679688,-172.143555,57.492432,-0.000396,11.201155,119.733948,35.000015,301.429138,false,Manual,2.621887",
          GUID = "191E6E7E",
          NextDialogue = 10033924,
          SpeakNpcId = 100359,
          Subtitle = "But... it's been so long. Do we really have to spend our whole lives paying for something we didn't do?",
          TalkActionId = {
            [1] = "100357:Talk02_End",
            [2] = "100359:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E7E"
        },
        [10033924] = {
          Camera = "12.585938,79.568848,100.525391,-0.000396,5.199898,-102.469757,35.000015,117.480644,false,Manual,2.621887",
          ContentKR = "맞아, 우린 갚을 수밖에 없어... 하지만 군단에 들어가서 휘페르보레아의 충성스러운 전사가 될 수 있다면, 심지어 '계관 카론'이 될 수 있다면, 우리의 삶은... 달라질지도 몰라.",
          DialogueId = 10033924,
          FacialId = {
            [1] = "100357:Smile01"
          },
          FinalCamera = "19.641602,78.040527,100.525391,-0.000396,5.199898,-105.269951,35.000015,117.480644,false,Manual,2.621887",
          GUID = "191E6EA8",
          NextDialogue = 10033925,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"1843.746094,1290.007935,347.944092,-0.000397,-5.799684,-147.667007,55.0,2176.124023,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"1859.686523,1264.762573,347.944092,-0.000396,-5.799684,-148.066879,55.0,2176.124023,false,Manual,1.2\"},duration{10}}}",
          SpeakNpcId = 100357,
          Subtitle = "Yes. Repayment is all we can do... But if we join the Legion, become loyal soldiers of Hyperborea, or even earn the title of Laurelled Charon... Maybe things could change for us then.",
          TalkActionId = {
            [1] = "100359:Think_End",
            [2] = "100357:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6EA8"
        },
        [10033925] = {
          Camera = "42.208008,-128.189453,108.011963,-0.000397,-1.200132,110.128555,35.000015,246.756485,false,Manual,2.621887",
          ContentKR = "블루스는 꼭 해낼 수 있을 거야!",
          DialogueId = 10033925,
          FacialId = {
            [1] = "100359:Smile01"
          },
          FinalCamera = "54.620117,-123.871338,108.011963,-0.000397,-1.200132,115.327736,35.000015,246.756485,false,Manual,2.621887",
          GUID = "191E6ED2",
          NextDialogue = 10033926,
          SpeakNpcId = 100359,
          Subtitle = "You'll make it, Blues! I believe in you!",
          TalkActionId = {
            [1] = "100359:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6ED2"
        },
        [10033926] = {
          Camera = "476.704102,389.137207,151.945068,-0.000397,-7.999592,-144.868225,35.000015,663.789307,false,Manual,2.430077",
          ContentKR = "누나가 그렇게 말해주니까 제6군단 시험도 별로 어려워 보이지 않아.",
          DialogueId = 10033926,
          FinalCamera = "488.553711,372.130981,151.945068,-0.000396,-7.999592,-147.467621,35.000015,663.789307,false,Manual,2.430077",
          GUID = "191E6EFC",
          NextDialogue = 10033927,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"75.076172,205.711304,152.616455,-0.000396,-13.799529,-118.663506,35.000015,265.940674,false,Manual,2.430077\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"85.417969,200.057251,152.616455,-0.000397,-13.799529,-123.663765,35.000015,265.940674,false,Manual,2.430077\"},duration{5}}}",
          SpeakNpcId = 100357,
          Subtitle = "Haha, with your faith in me, the 6th Legion's entrance tests don't seem so daunting anymore.",
          TalkActionId = {
            [1] = "100357:Think_End",
            [2] = "100359:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6EFC"
        },
        [10033927] = {
          Camera = "-9.589844,56.781738,104.453369,-0.000398,6.400085,-90.263626,35.000015,87.994987,false,Manual,4.21821",
          ContentKR = "그럼, 오늘의 페실 가족 수업은 저의 아름다운 하모니카 연주와 함께 끝내보도록 하겠습니다... 어라? 내 하모니카 어디 갔지?",
          DialogueId = 10033927,
          FacialId = {
            [1] = "100357:Ahaha01"
          },
          GUID = "191E6F26",
          NextDialogue = 10033928,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{100357},AnimationId{"BulusiY_Story_Find02_Start"},Duration{2}},
CameraMoveTo{_delay{4},TargetPosition{"-77.882812,47.860352,154.744873,-0.000397,-34.599674,-51.263714,35.000019,87.994987,false,Manual,4.21821"},duration{0}}
}]],
          SpeakNpcId = 100357,
          Subtitle = "Well, let's wrap up today's Fischers Tutorial with a beautiful tune from my harmonica... Wait, where is it?",
          VoiceName = "voice/$Locale$/story/1003/100339/191E6F26"
        },
        [10033928] = {
          Camera = "-64.916992,-23.831787,104.750732,-0.000397,2.599297,64.942268,35.000015,143.102722,false,Manual,4.21821",
          ContentKR = "하모니카에 가죽끈이나 체인 같은 거 걸어두라고 진작에 얘기했잖아... 됐어, 또 비싸서 안 한다고 하겠지, 나중에 하나 만들어줄게.",
          DialogueId = 10033928,
          FacialId = {
            [1] = "100359:Smile01"
          },
          GUID = "191E6F50",
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-577.176758,-950.747559,611.587524,-0.000397,-25.999912,59.331665,35.000015,1582.272949,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-715.947266,-855.034424,611.588623,-0.000397,-25.799891,50.531769,35.000015,1582.272949,false,Manual,22.0\"},duration{10}}},PlayAnimation{_delay{4},ActorId{100359},AnimationId{\"Explain02_End\"},Duration{2}},PlayAnimation{_delay{8},ActorId{100359},AnimationId{\"Talk01_Start\"},Duration{2}}}",
          SpeakNpcId = 100359,
          Subtitle = "I told you to tie a strap or chain to it ages ago... But no, it was \"too expensive\" and \"not worth it.\" ...Fine, I'll make one for you.",
          TalkActionId = {
            [1] = "100359:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100339/191E6F50"
        },
