          SpeakNpcId = 100358,
          Subtitle = "Aw, don't cry! It's okay, really. Three years will fly by before you know it! And hey, maybe you'll get lucky and become a Laurelled Charon next year!",
          TalkActionId = {
            [1] = "100358:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7316"
