          ContentKR = "그리고 우리 같이 저 성벽의 가장 높은 곳으로 올라가는 거야. 아이스레이크 시티의 모든 사람에게 우리가 얼마나 대단한지 보여주자!",
          DialogueId = 10033952,
          FinalCamera = "1574.841797,1070.966309,364.312744,0.002059,-9.084534,-146.866806,35.000008,1941.741211,false,Manual,1.2",
          GUID = "191E7340",
          SpeakNpcId = 100358,
          Subtitle = "Then we'll climb to the top of the city walls together and show everyone in Icelake just how amazing we are!",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7340"
        },
        [10033953] = {
