          GUID = "191E760A",
          NextDialogue = 10033970,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"652.945312,463.934875,412.007812,0.000188,-23.608671,-148.696426,35.000008,216.320572,false,DoNotOverride,3.374357\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"625.39502,505.701294,412.007812,0.000183,-23.408648,-144.695618,35.000008,216.320572,false,DoNotOverride,3.374357\"},duration{5}}}",
          SpeakNpcId = 100360,
          Subtitle = "Here, take this. It's the key to my secret base. The address is written on the back. Could you go there and grab my silver seal with my name on it?",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1003/100339/191E760A"
        },
        [10033970] = {
          Camera = "291.686035,147.772278,166.871094,-10.000484,-20.003922,-142.886566,35.000015,364.535095,false,DoNotOverride,3.069153",
          ContentKR = "지금 직접 도와드릴 순 없지만 다른 사람에게 편지를 몇 통 써서 부탁드릴 순 있습니다.",
          DialogueId = 10033970,
          FinalCamera = "296.286621,140.633057,172.496094,-10.001247,-21.203911,-145.486053,35.000015,364.535095,false,DoNotOverride,3.069153",
          GUID = "191E7634",
          LookAt = {
            [1] = "100360:n(100360)"
          },
          NextOptions = {
            [1] = 10033971,
            [2] = 10033973
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{100001},AnimationId{\"Talk03_End\"},Duration{1}}",
          SpeakNpcId = 100360,
          Subtitle = "I'm in no condition to do much for you right now, but I can at least write a few letters to ask for help on your behalf.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7634"
        },
        [10033971] = {
          ContentKR = "믿을만한 사람들인가요?",
          DialogueId = 10033971,
          GUID = "191E765E",
          ImprPlusId = 1006,
          NextDialogue = 10033972,
          Subtitle = "Can I trust them?"
        },
        [10033972] = {
          Camera = "326.638672,-43.474365,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          ContentKR = "네, 정말 적지만, 카론을 도와주려 하는 사람들은 여전히 존재합니다.",
          DialogueId = 10033972,
          FinalCamera = "322.354492,-50.202484,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E7688",
          NextDialogue = 10033975,
          SpeakNpcId = 100360,
          Subtitle = "Yes. Though few in number, there are still some who are willing to lend a hand to the Charons.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7688"
        },
        [10033973] = {
          ContentKR = "...지금 그 꼴을 하고도 절 도와줄 생각만 하는 거예요?",
          DialogueId = 10033973,
          GUID = "191E76B2",
          ImprPlusId = 1009,
          NextDialogue = 10033974,
          Subtitle = "...Even in a hospital bed, you're still thinking about helping me?"
        },
        [10033974] = {
          Camera = "326.638672,-43.474365,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          ContentKR = "제 책임인걸요. 그리고 저도 당신께서 가족들과 재회할 수 있기를 바랍니다.",
          DialogueId = 10033974,
          FinalCamera = "322.354492,-50.202484,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E76DC",
          NextDialogue = 10033975,
          SpeakNpcId = 100360,
          Subtitle = "I made a promise. Besides, I truly hope you'll reunite with your family.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_End",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E76DC"
        },
        [10033975] = {
          Camera = "301.869629,98.541199,115.601562,0.000116,3.196139,162.306015,40.000011,367.813141,false,Manual,1.2",
          ContentKR = "그럼, 이 호의는 감사하게 받겠습니다.",
          DialogueId = 10033975,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "304.80127,107.63208,115.601562,0.000116,3.196132,163.505875,40.000011,367.813141,false,Manual,1.2",
          GUID = "191E7706",
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-321.128418,431.440491,273.042969,0.000077,-18.603077,-39.290245,40.0,364.535095,false,DoNotOverride,3.069153\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-354.362305,458.634705,287.5,0.000077,-18.603077,-39.290245,40.0,364.535095,false,DoNotOverride,3.069153\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "Alright, we shall gladly accept your help, then.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7706"
        },
        [10034001] = {
          ContentKR = "군인의 비밀 아지트라니, 어떤 모습일까? 진짜 짜릿하네!",
          DialogueId = 10034001,
          GUID = "191E7B4A",
          NextDialogue = 10034002,
          SpeakNpcId = 200002,
          Subtitle = "A soldier's secret base? I bet it's packed with cool stuff! This is so exciting!",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B4A"
        },
        [10034002] = {
          ContentKR = "열쇠에 적혀있는 곳은 고속도로 환승소 근처인 것 같은데.",
          DialogueId = 10034002,
          GUID = "191E7B74",
          NextDialogue = 10034003,
          SpeakNpcId = 200021,
          Subtitle = "The address points to somewhere near the roadside freight station.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B74"
        },
        [10034003] = {
          ContentKR = "비밀 아지트를 이런 곳에 만들다니...",
          DialogueId = 10034003,
          GUID = "191E7B9E",
          NextDialogue = 10034004,
          SpeakNpcId = 100001,
          Subtitle = "She actually built her secret base in a place like that?",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B9E"
        },
        [10034004] = {
          ContentKR = "사람들은 가끔 아무도 이해할 수 없는 곳에 혼자만의 피난처를 만들기 좋아하지...",
          DialogueId = 10034004,
          GUID = "191E7BC8",
          NextDialogue = 10034005,
          SpeakNpcId = 200021,
          Subtitle = "People tend to pick the oddest spots for their hideaways...",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BC8"
        },
        [10034005] = {
          ContentKR = "누군가는 차 안에, 누군가는 파이프 속에 말이야. 그러니까 이런 곳을 비밀 아지트로 삼는 것도 이상하진 않아.",
          DialogueId = 10034005,
          GUID = "191E7BF2",
          NextDialogue = 10034006,
          SpeakNpcId = 200021,
          Subtitle = "Some use cars, some find old pipes... A roadside freight station? Seems pretty normal to me.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BF2"
        },
        [10034006] = {
          ContentKR = "어... 꽤 일반적이잖아. 나만 어릴 때 어딘가 파고 들어가는 걸 좋아했나?",
          DialogueId = 10034006,
          GUID = "191E7C1C",
          SpeakNpcId = 200021,
          Subtitle = "Uh... please tell me I'm not the only one who used to crawl into random places as a kid.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C1C"
        },
        [10034007] = {
          ContentKR = "여긴가?",
          DialogueId = 10034007,
          GUID = "191E7C46",
          NextDialogue = 10034008,
          SpeakNpcId = 100001,
          Subtitle = "Is this it?",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C46"
        },
        [10034008] = {
          ContentKR = "입구가 근처에 있을 거야, 찾아보자.",
          DialogueId = 10034008,
          GUID = "191E7C70",
          SpeakNpcId = 200021,
          Subtitle = "The entrance should be near. Let's look around.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C70"
        },
        [10034101] = {
          Camera = "-1302.09375,188.645508,676.1875,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          ContentKR = "오? 버려진 정비실을 개조한 것 같네.",
          DialogueId = 10034101,
          FinalCamera = "-1145.925781,162.691406,610.441406,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BB2",
          NextDialogue = 10034102,
          SpeakNpcId = 200021,
          Subtitle = "Hmm, looks like this place used to be an old maintenance room.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToExplainR_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BB2"
        },
        [10034102] = {
          Camera = "330.632812,-30.893555,59.353516,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          ContentKR = "이건 그냥 스노우의 난잡한 방이잖아, 아니, 마왕의 호화 침실이랑 비슷하네!",
          DialogueId = 10034102,
          FacialId = {
            [1] = "200002:Doubt01",
            [2] = "200021:Angry01",
            [3] = "100001:Doubt01"
          },
          FinalCamera = "330.792969,-23.540039,59.5625,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BDC",
          NextDialogue = 10034103,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, this place is kind of like my messy... I mean, the Demon King's grand chamber!",
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "200021:ConfidentLRToExplainR_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BDC"
        },
        [10034103] = {
          Camera = "-157.855469,20.635742,139.306641,1.753745,-2.15362,-32.439327,35.000015,199.365784,false,DoNotOverride,8.0",
          ContentKR = "흩어져서 찾아보자, 그 은색 도장.",
          DialogueId = 10034103,
          FinalCamera = "-148.238281,18.021484,147.634766,1.753745,-4.553892,-31.638124,35.000011,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8C06",
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"cp2fixsimple30Point01\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's split up and look for the silver seal.",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C06"
        },
        [10034104] = {
          ContentKR = "황제의 새끼손가락 반지 훈장, 100% 순금으로 만들어졌다. 제국에 탁월한 공헌을 한 군인에게만 수여된다.\n\n코퀴투스 주 아이스레이크 시티 제6군단 소속 방위대, <H>리듬 페실</>은 수년간, 여러 차례의 <H>필토이드 토벌 작전</>을 현명한 판단과 용맹한 전투로 신속하게 마무리 지었다.\n지역 치안을 유지하는 과정에서 더할 나위 없이 핵심적인 작용을 발휘했다.\n군단의 평가를 거쳐, 황제 폐하 율리우스의 이름으로 리듬 페실에게 황제 새끼손가락 반지 훈장과 함께 준위의 계급을 수여하니 모든 군인은 이를 모범으로 삼아 정진하고 성장하기를 바란다.\n황제 폐하께 영광을.",
          DialogueId = 10034104,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000047;content:READ_TEXT_2000047}",
          GUID = "191E8C30",
          Subtitle = [[
The Emperor's signet ring. Crafted entirely from pure gold, this prestigious honour is bestowed exclusively upon those who have made extraordinary contributions to the Empire.

Recipient: Rhythm Fischer, serving in the Icelake Escort under the 6th Legion in the Cocytus Region.
For demonstrating decisive leadership, exemplary bravery, and exceptional efficiency in multiple Filthoid-clearing operations over the years.
For playing an irreplaceable role in maintaining public order and ensuring the safety of the region.
Upon the assessment of the Legion, and by the decree of His Majesty Julius, Rhythm Fischer is hereby awarded the Emperor's signet ring and the rank of Warrant Officer. Let her serve as an inspiration to all soldiers, urging them to strive ever higher for the Empire's glory.
All glory to His Majesty.]],
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C30"
        },
        [10034105] = {
          ContentKR = "석회벽의 한쪽 구석에는 나이프로 새겨진 글자가 빽빽하게 덮여있다. 어떤 글자는 아이의 필체처럼 삐뚤삐뚤하고, 어떤 글자는 어른처럼 성숙한 필체로 쓰여 있다. 글자들은 전부 같은 말이다.\n\"더 이상 그 누구도 필토이드에게 죽는 걸 보고만 있지 않겠다.\"",
          DialogueId = 10034105,
          GUID = "191E8C5A",
          Subtitle = "One corner of the limewashed wall is covered in countless etched words. Some are crooked and childlike, while others are firm and deliberate, clearly written by an adult hand. All of them repeat the same sentence: \"I'll never let anyone die to Filthoids again.\"",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C5A"
        },
        [10034106] = {
          ContentKR = "잡동사니들 밑에 깔린 낡은 신문에는 오래 전의 비참한 사고가 기록되어 있다.\n\n<H>침식자는 매우 위험하니 겉모습에 속지 마세요!</>\n9월 24일, 본 시에서 매우 끔찍한 '침식' 사건이 발생했습니다. 제6군단 방위대의 조사를 거쳐 얻어낸 결론은 다음과 같습니다.\n아이스레이크 시티 주민 페실 부부는 9월 13일 눈물의 호수 옆 도로변에서 로비 브라운이라는 청년을 우연히 만났습니다. 페실 부부는 중상을 입은 그를 집으로 데려가 돌보았습니다.\n그러나 로비 브라운은 제국의 잠재적 침식자에 대한 조사를 피해 도시 밖으로 도피한 침식자였고, 페실 부부의 도움을 받을 때 자신의 침식 흔적을 의도적으로 숨겼습니다. 10일 후, 비극이 발생했습니다. 브라운은 필토이드로 변하여 페실 부부를 포함한 아이스레이크 남쪽 구역 시민 수십 명을 살해했습니다. 제6군단 소속 아이스레이크 시티 방위대가 긴급 출동하여 이번 소란을 진압했습니다.\n이번 사태로 총 18명이 사망했고, 그중 3명은 솔라인 것으로 밝혀졌습니다. 그 외 34명이 다쳤습니다. 시민 여러분들, 명심해 주십시오. 신원불명의 카론을 함부로 수용해서는 안 됩니다. 침식자를 발견하게 되면 즉시 치안서에 신고해 주십시오. 그들은 하나도 빠짐없이, 영원히 인간의 적입니다. 의도적으로 침식자에게 협력하거나 침식자를 은폐하는 자는\n〈휘페르보레아 형사 법전〉제 54조에 따라 사형에 처합니다.",
          DialogueId = 10034106,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000048;content:READ_TEXT_2000048}",
          GUID = "191E8C84",
          Subtitle = "Buried beneath a pile of old clutter, this yellowed newspaper recounts a tragic incident from years ago.\n\nFilthoids Are Exceptionally Dangerous — Do Not Be Fooled by Their Appearances!\nOn September 24th, an egregious Filthoid incident occurred in Icelake. Following an extensive investigation conducted by the 6th Legion's Escort Unit, the details of the tragedy have been confirmed:\nOn September 13th, local residents Mr and Mrs Fischer encountered a gravely injured young man named Robie Brown along the roadside at Lamenting Lake. Out of compassion, the Fischers took him into their home and cared for him.\nHowever, Robie Brown was a Deteriorator who had evaded the Empire's routine screenings and fled to the outskirts of the city. While receiving aid from the Fischers, he deliberately concealed his condition. Ten days later, Brown succumbed to his transformation, becoming a Filthoid and massacring dozens of citizens in Icelake's southern district, including Mr and Mrs Fischer. The 6th Legion's Escort intervened swiftly to suppress the chaos, but the damage was already done.\nThe incident left 18 dead (including 3 Solarians) and 34 others injured. Citizens are hereby reminded: Do not provide shelter to unidentified Charon individuals under any circumstances. If you suspect someone is a Deteriorator, report them to the Security Bureau immediately. They are and will always remain humanity's enemies. No exceptions. Be advised that harbouring Deteriorators or concealing their presence is a capital offence punishable by death under Article 54 of the Hyperborean Criminal Code.",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C84"
        },
        [10034107] = {
          Camera = "-106.066406,611.137695,77.603516,0.000153,5.204611,-92.19577,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "이것 좀 봐.",
          DialogueId = 10034107,
          FinalCamera = "-106.066406,611.137695,77.603516,0.000154,8.004599,-92.39566,35.000008,100000.0,false,Manual,22.0",
          GUID = "191E8CAE",
          LookAt = {
            [1] = "100001:p(Point04)",
            [2] = "200021:p(Point04)"
          },
          NextDialogue = 10034108,
          Scripts = "PARA{MoveTo{ActorId{100001},TargetPoint{\"Point03\"},MoveSpeed{80},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point02\"},Visibility{\"Hide\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "Take a look at this.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8CAE"
        },
        [10034108] = {
          Camera = "-113.304688,236.751953,107.111328,0.000155,-26.791348,130.790771,30.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "버려진 정비실에 웬 광산용 램프와 곡괭이가 이렇게 많지?",
          DialogueId = 10034108,
          FinalCamera = "-113.304688,236.751953,107.111328,0.000152,-33.191277,130.190399,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191E8CD8",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10034109,
          SpeakNpcId = 100001,
          Subtitle = "Why are there so many mining lamps and pickaxes in an abandoned maintenance room?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8CD8"
        },
        [10034109] = {
          Camera = "99.867188,416.986328,118.638672,0.000182,3.20773,-139.803497,35.000011,100000.0,false,Manual,22.0",
          ContentKR = "글로스터 광갱의 월석이 거의 바닥나자, 광부들이 미래가 걱정돼서 광갱의 물건들을 훔쳐 팔았던 적이 있어.",
          DialogueId = 10034109,
          FinalCamera = "107.375,408.098633,118.638672,0.000182,3.607713,-142.203781,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E8D02",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034110,
          SpeakNpcId = 200021,
          Subtitle = "Back when the Glevum Pit was running dry, miners started swiping gear to sell elsewhere, out of fear of losing their livelihood.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D02"
        },
        [10034110] = {
          Camera = "-27.976562,359.482422,156.25,0.00017,-1.390585,-141.406723,30.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "여기가 아마 그 물건들을 감춰 놓은 곳일 거야. 나중에 리듬이 찾아서 비밀 창고로 쓴 거지. 하지만 네가 봤으면 하는 건 그게 아니야.",
          DialogueId = 10034110,
          FinalCamera = "-16.988281,344.918945,156.25,0.000169,-1.590608,-147.206284,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191E8D2C",
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.000061,-16.397821,77.969307,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.00006,-14.397696,77.768784,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{5}}},LookAt{_delay{5},LookAtDescription{\"200021:p(Point04)\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "This place must've been one of their stashes. Rhythm probably stumbled upon it later and turned it into a secret base. But that's not what I wanted to show you.",
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D2C"
        },
        [10034111] = {
          ContentKR = "삐뚤어진 리본이 달린 소박한 선물 상자. 선물 상자 옆에는 제국 최고의 진통제 한 병, 그리고 무슨 이유에서인지 선물 상자에 넣지 못한 쪽지가 있다. 쪽지에는 \"쾌유하시길 바랍니다.\"라는 글귀가 적혀있다.",
          DialogueId = 10034111,
          GUID = "191E8D56",
          Subtitle = "A plain gift box with a clumsily made ribbon bow, accompanied by a bottle of the Empire's finest painkiller. Next to it is an unsent note that reads: \"Get well soon.\"",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D56"
        },
        [10034201] = {
          Camera = "219.984375,651.333008,126.039062,0.000189,-0.595449,-128.390549,35.000008,527.224426,false,Manual,2.038203",
          ContentKR = "의식을 잃은 사이 진통제를 보낸 바보가 누군지 궁금했는데, 이걸 보니 알 것 같아. 리듬 같은 바보가 한 일 답네.",
          DialogueId = 10034201,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "226.792969,645.869141,126.039062,0.000189,-0.795451,-129.390228,35.000008,527.224426,false,Manual,2.038203",
          GUID = "191E9C1A",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034202,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          Scripts = "PARA{SetLocation{ActorId{100001},TargetPoint{\"Point03\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point02\"},Visibility{\"Hide\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "I was wondering who the genius was that sent painkillers to someone in a coma. Now it makes sense — that's so Rhythm.",
          TalkActionId = {
            [1] = "200021:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C1A"
        },
        [10034202] = {
          Camera = "6.648438,363.008789,131.244141,0.000182,3.603758,-146.77739,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "됐어, 내가 찾은 건 이것뿐이야. 넌? 도장은 찾았어?",
          DialogueId = 10034202,
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "13.488281,352.691406,131.244141,0.000182,3.603758,-149.576935,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C44",
          NextDialogue = 10034203,
          SpeakNpcId = 200021,
          Subtitle = "Anyway, this is all I've found so far. What about you? Found the seal yet?",
          TalkActionId = {
            [1] = "200021:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200021:p(-20)"
          },
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C44"
        },
        [10034203] = {
          Camera = "-275.664062,320.675781,156.072266,0.000189,-3.796267,-32.382538,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "아니, 아직. 하지만 또 한 가지 알아낸 게 있어...",
          DialogueId = 10034203,
          FinalCamera = "-271.5625,327.202148,156.072266,0.000189,-3.796267,-35.982929,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C6E",
          NextDialogue = 10034204,
          SpeakNpcId = 100001,
          Subtitle = "Not yet. But I've learned something else...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C6E"
        },
        [10034204] = {
          Camera = "-106.195312,289.816406,169.058594,0.000185,-23.795893,-51.580635,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "리듬이 어렸을 때... 부모님이 필토이드로 변한 침식자에게 죽었나 봐. 그 필토이드가 사람들을 엄청 많이 죽인 것 같아.",
          DialogueId = 10034204,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-101.417969,293.541992,169.058594,0.000177,-23.795885,-56.380722,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C98",
          NextDialogue = 10034205,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-91.234375,264.868164,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-100.582031,264.547852,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "When Rhythm was young... her parents were killed by a Filthoid. That same Filthoid took the lives of so many others.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C98"
        },
        [10034205] = {
          ContentKR = "필토이드는 매우 위험합니다. 지금은 공격을 멈췄지만, 일시적인 휴면 상태일 가능성이 높습니다. 어서 성안으로 피하십시오. 이곳은 방위대가 맡겠습니다.",
          DialogueId = 10034205,
          GUID = "191E9CC2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10031809.T_Story_Recall_10031809'",
          NextDialogue = 10034206,
          SpeakNpcId = 100304,
          Subtitle = "The Filthoid is highly dangerous. Although it's ceased attacking, it may only be in temporary dormancy. Return to the city immediately — the Escort will take it from here.",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CC2"
        },
        [10034206] = {
          ContentKR = "괜찮습니다... 시민들을 보호하는 건... 제 책임입니다. 당신들이 괜찮다면... 됐어요.",
          DialogueId = 10034206,
          GUID = "191E9CEC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10034206.T_Story_Recall_10034206'",
          NextDialogue = 10034207,
          SpeakNpcId = 100304,
          Subtitle = "...Protecting civilians is my duty... as long as... you're all safe...",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CEC"
        },
        [10034207] = {
          Camera = "-83.59375,619.290039,74.404297,0.000918,8.607185,-95.991829,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "리듬은 누군가 또다시 필토이드에게 죽는 걸 보고 싶지 않았던 거야, 그래서 방위대에 들어갔나 봐.",
          DialogueId = 10034207,
          FinalCamera = "-65.59375,616.701172,74.404297,0.000924,8.607192,-98.191681,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9D16",
          NextDialogue = 10034208,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"315.195312,664.356445,432.208984,0.000911,-28.393204,-137.977951,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"326.253906,652.047852,432.208984,0.000918,-28.993189,-141.378052,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Maybe that's why she joined the Escort — to make sure no one else has to suffer like her parents did.",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9D16"
        },
        [10034208] = {
          Camera = "-69.269531,298.607422,122.386719,0.000908,14.007092,-82.585274,35.000011,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "......",
          DialogueId = 10034208,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-66.597656,298.93457,122.386719,0.000909,14.207059,-84.585007,35.000011,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9D40",
          NextDialogue = 10034209,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9D40"
        },
        [10034209] = {
          Camera = "74.128906,313.707031,115.523438,0.00091,8.006245,-156.795731,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "그럼, 그날 밤 일 말인데, 이제 리듬을 용서한 거야?",
          DialogueId = 10034209,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "67.410156,328.6875,115.523438,0.000912,8.006245,-151.796326,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9D6A",
          NextOptions = {
            [1] = 10034210,
            [2] = 10034215
          },
          SpeakNpcId = 200021,
          Subtitle = "Then... you've forgiven her for what happened that night?",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9D6A"
        },
        [10034210] = {
          ContentKR = "응, 이제 미워하지 않아.",
          DialogueId = 10034210,
          GUID = "191E9D94",
          NextDialogue = 10034211,
          Subtitle = "Yes, I don't hate her anymore."
        },
        [10034211] = {
          Camera = "-87.1875,283.529297,139.589844,0.000929,0.00597,-72.795937,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "...사실 훨씬 전부터, 그녀를 미워하지 않는다는 걸 알고 있었어.",
          DialogueId = 10034211,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "-79.628906,285.871094,139.589844,0.000929,0.00597,-72.795937,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9DBE",
          NextDialogue = 10034212,
          SpeakNpcId = 100001,
          Subtitle = "...Or maybe, deep down, I never hated her to begin with.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9DBE"
        },
        [10034212] = {
          Camera = "-278.289062,544.645508,272.761719,0.000823,-24.392176,-64.799492,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "난 그냥... 무의식적으로 핑계가 필요했나 봐, 그래야 마음이 좀 나아질 거라고 생각했지.",
          DialogueId = 10034212,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          FinalCamera = "-266.535156,550.174805,272.761719,0.000823,-24.392176,-68.599632,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9DE8",
          NextDialogue = 10034213,
          SpeakNpcId = 100001,
          Subtitle = "I just... needed a vent to ease the pain inside...",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9DE8"
        },
        [10034213] = {
          Camera = "-247.742188,295.758789,178.650391,0.000831,-14.39187,-24.799393,35.000011,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "네가 진짜 원망한 건, 되돌릴 수 없는 침식, 그리고 그때 아무것도 할 수 없었던 내 자신이었어.",
          DialogueId = 10034213,
          FinalCamera = "-250.34375,290.249023,178.650391,0.000827,-14.39187,-22.798668,35.000011,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9E12",
          NextDialogue = 10034214,
          SpeakNpcId = 100001,
          Subtitle = "What I truly hate is the incurable Deterioration and the gnawing helplessness back then.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E12"
        },
        [10034214] = {
          Camera = "-99.214844,448.524414,117.580078,0.000858,7.807739,-110.798241,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "음, 프시케의 일은 아무도 잘못한 게 없어. 꼭 누군가를 탓해야 한다면, 그건 이 뒤틀린 시대밖에 없겠지.",
          DialogueId = 10034214,
          FinalCamera = "-89.992188,445.055664,117.580078,0.000856,7.807739,-113.997963,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9E3C",
          NextDialogue = 10034219,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-44.121094,598.605469,88.085938,0.000868,6.607477,-102.801109,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-39.066406,621.015625,85.417969,0.000871,6.807472,-103.001343,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{5}}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"ConfidentLRToTalk01_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Nobody's at fault for what happened to Psyche. If anything is to be blamed, it's this broken world we live in.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToTalk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E3C"
        },
        [10034215] = {
          ContentKR = "아니, 아직은 용서 못 해.",
          DialogueId = 10034215,
          GUID = "191E9E66",
          NextDialogue = 10034216,
          Subtitle = "No... I still can't get over it."
        },
        [10034216] = {
          Camera = "31.164062,344.773438,103.396484,0.000867,11.206885,-154.599243,35.000011,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "알아, 너무 무겁고 무거워서 '그냥 잊어버려'라고 하면서 가볍게 넘길 수 있는 일이 아니지.",
          DialogueId = 10034216,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "35.367188,335.894531,103.396484,0.000868,11.206885,-157.59964,35.000011,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9E90",
          NextDialogue = 10034217,
          SpeakNpcId = 200021,
          Subtitle = "I get it. Some wounds run too deep to heal. It's not something you can just brush off with a simple \"forget it.\"",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E90"
        },
        [10034217] = {
          Camera = "-64.0625,325.602539,167.652344,0.000887,-56.191696,118.603279,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "꼭 뭔가를 납득하려고 자신을 강요하지 않아도 돼, 그저 본심을 따르면 되는 거야.",
          DialogueId = 10034217,
          FinalCamera = "-70.183594,322.261719,167.652344,0.000858,-55.591667,110.602448,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9EBA",
          NextDialogue = 10034218,
          SpeakNpcId = 200021,
          Subtitle = "It's okay not to forgive. You don't have to force yourself to.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9EBA"
        },
        [10034218] = {
          Camera = "88.582031,354.351562,113.285156,0.000858,5.408526,-148.789658,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "'카론 사냥' 사건이 끝나고 베레의 소식까지 알아내면 각자 갈 길 가면 돼. 다시 얽힐 일 없을 거야.",
          DialogueId = 10034218,
          FinalCamera = "88.582031,354.351562,113.285156,0.000857,7.208499,-148.789398,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9EE4",
          NextDialogue = 10034219,
          Scripts = "PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"ConfidentLRToTalk01_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Once this \"Charon Hunt\" thing is over, and she's helped you gather information about Berenica, you can cut ties with her and never see her again.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToTalk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9EE4"
        },
        [10034219] = {
          Camera = "-115.113281,280.667969,163.935547,0.000887,-20.591106,-42.988194,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentKR = "응...",
          DialogueId = 10034219,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-111.488281,284.563477,163.935547,0.000886,-20.591114,-46.788067,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9F0E",
          NextDialogue = 10034220,
          SpeakNpcId = 100001,
          Subtitle = "Yeah...",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9F0E"
        },
        [10034220] = {
          Camera = "-140.234375,456.795898,68.025391,0.000896,10.808064,-67.380486,35.000011,247.296616,false,Manual,4.532753",
          ContentKR = "늦었어, 서둘러 그 도장부터 찾자.",
          DialogueId = 10034220,
          FinalCamera = "-137.816406,457.798828,68.025391,0.000897,10.808064,-67.980507,35.000011,247.296616,false,Manual,4.532753",
          GUID = "191E9F38",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-48.074219,-177.825195,242.457031,0.000911,-16.990921,99.013062,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-48.074219,-177.825195,242.457031,0.000915,-15.190948,99.012909,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "It's getting late. Let's hurry up and find that seal.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9F38"
        },
        [10034221] = {
          ContentKR = "(내성 성벽 아래 남매가 함께 찍은 사진. 오른쪽 상단에는 '리듬 페실'과 '블루스 페실' 두 이름이 적혀 있으며, 동생 블루스의 제6군단 합격을 축하하는 축사도 적혀 있다.)",
          DialogueId = 10034221,
          GUID = "191E9F62",
          SpeakNpcId = 100001,
          Subtitle = "(A photo of a brother and sister standing under the inner city wall. Scribbled in the top-right corner are the names \"Rhythm Fischer\" and \"Blues Fischer,\" along with a congratulatory note celebrating Blues' passing the 6th Legion's entrance tests.)",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9F62"
        },
        [10034222] = {
          ContentKR = "(오랫동안 사용하지 않은 듯한 하모니카. 리듬의 취미라기보다는 어떤 선물에 가깝다.)",
          DialogueId = 10034222,
          GUID = "191E9F8C",
          SpeakNpcId = 100001,
          Subtitle = "(A harmonica that looks like it hasn't been used in a long time. Its condition suggests it's more of a cherished gift than a personal hobby of Rhythm's.)",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9F8C"
        },
