}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Congrats, I guess? One in ten thousand, all that hard work, just to lick up the crumbs nobles toss under the table.",
          ToFinalCameraBlendTime = 6.5,
          VoiceName = "voice/$Locale$/story/1003/100343/191EAF4C"
        },
        [10034319] = {
