          ContentKR = "제13군단이 이 사건을 맡게 되었으니, 저흰 이만 물러날게요.",
          DialogueId = 10034332,
          FinalCamera = "-195.574707,748.213745,108.259766,0.000223,-0.799959,-64.338593,35.0,792.118591,false,Manual,3.0",
          GUID = "191EB198",
          NextDialogue = 10034333,
          SpeakNpcId = 100001,
