        [10034334] = {
          Camera = "78.430176,458.281433,156.322266,0.000271,-2.599297,-86.551003,45.0,402.692322,false,Manual,5.0",
          ContentKR = "이런 일은 평민들을 끌어들이지 말아야 했는데, 제6군단의 도움이 안 되는 놈들 때문이지.",
          DialogueId = 10034334,
          FacialId = {
            [1] = "100361:Iyada01"
          },
          FinalCamera = "113.943848,459.992493,156.322266,0.000267,-2.799305,-91.350563,45.0,402.692322,false,Manual,5.0",
          GUID = "191EB216",
          NextDialogue = 10034335,
          SpeakNpcId = 200022,
          Subtitle = "You civilians shouldn't have been caught up in this. Thanks to the 6th Legion's bunch of good-for-nothings.",
          TalkActionId = {
            [1] = "200022:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100343/191EB216"
        },
        [10034335] = {
          Camera = "104.562012,223.299988,127.230469,0.000302,11.197684,95.262558,25.0,110.1381,false,Manual,5.0",
          ContentKR = "<H>내가 아이스레이크 시티에 돌아온 건 오직 카론 사냥 때문이다.</> 페실 준위, 두 시간 안에 이 사건과 관련된 모든 보고서를 가져오도록.",
          DialogueId = 10034335,
          FacialId = {
            [1] = "100361:Doubt01"
          },
          FinalCamera = "104.918457,219.433105,126.466797,0.000302,11.197684,95.262558,25.0,114.541626,false,Manual,5.0",
          GUID = "191EB240",
          NextDialogue = 10034336,
          Scripts = [[
PARA{
