CameraMoveTo{TargetPosition{"148.30127,398.608948,153.080078,0.000262,-8.798369,-109.741692,15.0,402.692322,false,Manual,5.0"},duration{4}}
},
}]],
          SpeakNpcId = 200022,
          Subtitle = "I came to Icelake for only one thing: The \"Charon Hunt.\" Warrant Officer Fischer, I want the full report on this case in my hands within two hours.",
          TalkActionId = {
            [1] = "200022:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100343/191EB240"
        },
        [10034336] = {
          Camera = "133.126465,139.744141,172.181641,0.000278,-11.599545,-118.150055,35.0,167.578171,false,Manual,5.0",
          ContentKR = "그리고 월석 사냥꾼, 이미 휘말렸으니, 여유가 된다면 계속 협력해 줘. 어떤 일은 현지인에게 맡기는 게 더 빠르니까.",
          DialogueId = 10034336,
          FinalCamera = "133.126465,139.744141,168.591797,0.000281,-10.599483,-118.149986,35.0,170.237289,false,Manual,5.0",
          GUID = "191EB26A",
          NextDialogue = 10034337,
          SpeakNpcId = 200022,
          Subtitle = "And Phoxhunters, since you're already in this deep, might as well keep assisting us if you can spare the effort. Certain matters are better left to the locals — they know the lay of the land, after all.",
          TalkActionId = {
            [1] = "200022:Explain02_End"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1003/100343/191EB26A"
        },
        [10034337] = {
