        [10034402] = {
          Camera = "-63.818985,-155.555359,135.214111,0.000046,-0.199496,69.346672,55.0,385.592438,false,Manual,8.0",
          ContentKR = "그럼, 월석 사냥꾼. 첫 번째 퀘스트다. 이 목록을 가지고 주차장으로 가서 클레이프를 만나 우리가 사용할 무기와 탄약을 받아와라.",
          DialogueId = 10034402,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-59.606354,-157.143066,135.214111,0.000046,-0.199496,69.346672,55.0,385.592438,false,Manual,8.0",
          GUID = "191EBD14",
          NextDialogue = 10034403,
          Scripts = [[
SEQ{
