}]],
          SpeakNpcId = 200022,
          Subtitle = "Now, Phoxhunters, here's your first task: take this list and head to the parking lot to find Clive for the weapons and ammo we'll need.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBD14"
        },
        [10034403] = {
          Camera = "8.416705,-2.1773,171.88208,0.000003,-14.599727,-130.256424,35.0,92.029213,false,Manual,3.0",
          ContentKR = "...네.",
          DialogueId = 10034403,
          FinalCamera = "6.728994,-4.170396,171.201904,0.000003,-14.599727,-130.256424,35.0,92.029213,false,Manual,3.0",
          GUID = "191EBD3E",
          NextDialogue = 10034404,
          SpeakNpcId = 100001,
          Subtitle = "...Got it.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100344/191EBD3E"
        },
        [10034404] = {
          Camera = "173.846405,157.876358,270.469482,0.000002,-28.998379,-132.680298,20.0,1171.522461,false,Manual,22.0",
          ContentKR = "보고서를 정리하고 나면 저도 합류할게요.",
