          VoiceName = "voice/$Locale$/story/1003/100345/191ED118"
        },
        [10034525] = {
          Camera = "252.645859,119.817787,133.437744,0.00002,-0.393521,-57.958469,25.000006,100000.0,false,Manual,22.0",
          ContentKR = "괜히 모두를 끌어들이게 됐네요... 미안해요.",
