          VoiceName = "voice/$Locale$/story/1003/100345/191ED142"
        },
        [10034526] = {
          Camera = "123.6875,-318.221191,262.880859,0.00012,-23.791746,51.848705,20.000008,100000.0,false,Manual,22.0",
          ContentKR = "그만. 그런 재미 없는 우울한 소리 하지 마세요. 가요, 이제 며칠 동안 할 일 많으니까.",
          DialogueId = 10034526,
          FinalCamera = "123.6875,-318.221191,267.053223,0.000114,-24.391724,51.849072,20.000008,100000.0,false,Manual,22.0",
          GUID = "191ED16C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          Scripts = "TurnTo{_delay{1.5},TurnToDescription{\"100304:n(200021)\"}},",
          SpeakNpcId = 200021,
          Subtitle = "Uh-uh. Enough with the downer talk. Let's move — we've got our hands full for the next few days.",
          TalkActionId = {
            [1] = "100304:Talk02_End",
