        },
        [10034527] = {
          ContentKR = "이틀 뒤",
          DialogueId = 10034527,
          GUID = "191ED196",
          Subtitle = "Two days later",
          VoiceName = "voice/$Locale$/story/1003/100345/191ED196"
        },
        [10034528] = {
          Camera = "387.177704,-477.28363,251.621094,0.000037,-18.800491,96.200485,35.000011,544.895874,false,Manual,22.0",
          ContentKR = "그 많은 퀘스트를 리듬이 다 끝냈다고?! 세상에, 이렇게 열심히 하다니, 무슨 썰매 끄는 개도 아니고.",
          DialogueId = 10034528,
          FinalCamera = "379.26709,-408.699371,228.950928,0.000039,-18.000458,96.800278,35.000011,544.895874,false,Manual,22.0",
          GUID = "191ED1C0",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10034529,
          SpeakNpcId = 200021,
          Subtitle = "Ooh, Rhythm actually finished that massive task list on her own!? Geeze, what is she, a sled dog?",
          TalkActionId = {
