          FinalCamera = "64.187988,-22.094727,49.855713,0.00041,10.338522,97.824203,50.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191EFFB0",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10034809,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-12.719727,330.859375,138.181396,0.000427,-5.060214,111.810959,30.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-8.650391,332.382812,138.181396,0.000431,-5.060214,117.009903,30.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Right. But this isn't quite what I expected. It even feels... kind of like a cosy little home.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
