        [10034812] = {
          Camera = "79.039062,291.808594,109.609131,-0.00177,8.627402,141.371552,35.000019,427.577942,false,DoNotOverride,3.623266",
          ContentKR = "크흠, 아무것도 아니에요. 여긴 좀 이상하게 꾸며져 있네요. 일단 주변을 둘러보면서 이상한 게 있는지부터 찾아보죠.",
          DialogueId = 10034812,
          FinalCamera = "75.835938,287.754883,109.609131,-0.001769,8.627402,138.971634,35.000019,427.577942,false,DoNotOverride,3.623266",
          GUID = "191F0058",
          LookAt = {
