        },
        [10034822] = {
          Camera = "-2.286133,328.46582,139.172852,0.000183,-0.195316,-81.557655,32.000004,16827.542969,false,Manual,22.0",
          ContentKR = "...하지만 군단이 이미 범인을 찾아냈으니, 이 단서는 이제 큰 의미가 없겠네요.",
          DialogueId = 10034822,
          FacialId = {
