          VoiceName = "voice/$Locale$/story/1003/100348/191F0250"
        },
        [10034825] = {
          ContentKR = "시종, 여기 이상하게 생긴 장치가 있어!",
          DialogueId = 10034825,
          GUID = "191F0101",
          NextDialogue = 10034826,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, Little Minion — look! There's a weird-looking switch here!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0101"
        },
        [10034826] = {
          ContentKR = "꼬맹이, 일단 만지지 마. 함정일 수도 있어! ...음, 다행이네. 그냥 평범한 승강기야.",
          DialogueId = 10034826,
          GUID = "191F0102",
          SpeakNpcId = 200021,
          Subtitle = "No, Button Mushroom — don't touch that! Could be a trap... Huh. Looks like it's just a regular lift.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0102"
        },
        [10034827] = {
          ContentKR = "새로운 길이 나타났어! 마술 같아!",
          DialogueId = 10034827,
          GUID = "191F0103",
          SpeakNpcId = 200002,
          Subtitle = "Whoa! A new path just opened up — like magic!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0103"
        },
        [10034828] = {
          ContentKR = "쳇, 아무것도 없잖아. 난 또 뭐라도 튀어나오는 줄 알았네.",
          DialogueId = 10034828,
          GUID = "191F0104",
          NextDialogue = 10034829,
          SpeakNpcId = 200021,
          Subtitle = "Tch. Nothing at all... I was half expecting something to jump out.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0104"
        },
        [10034829] = {
          ContentKR = "퉤퉤퉤, 재수 없는 소리 하지 마!",
          DialogueId = 10034829,
          GUID = "191F0105",
          NextDialogue = 10034830,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Watch your mouth — you'll jinx it!",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0105"
        },
        [10034830] = {
          ContentKR = "계속 올라가 보자.",
          DialogueId = 10034830,
          GUID = "191F0106",
          NextDialogue = 10034832,
          SpeakNpcId = 100001,
          Subtitle = "Let's just keep moving.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0106"
        },
        [10034831] = {
          ContentKR = "이야, 순식간에 환해졌네. 이제 구석구석 잘 보여.",
          DialogueId = 10034831,
          GUID = "191F0107",
          SpeakNpcId = 200021,
          Subtitle = "Whoa — the whole place just lit up. You can see every corner now.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0107"
        },
        [10034832] = {
          ContentKR = "그건 그렇고, 꽤 예술적으로 꾸몄네. 극장 무대의 축소판이잖아.",
          DialogueId = 10034832,
          GUID = "191F0108",
          SpeakNpcId = 200021,
          Subtitle = "Gotta say, this place's got style. Feels like a mini theatre stage.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0108"
        },
        [10034833] = {
          ContentKR = "여긴 함정은 없는 것 같아. 돌아가서 리듬 장교님한테 알려 주자.",
          DialogueId = 10034833,
          GUID = "191F0109",
          SpeakNpcId = 100001,
          Subtitle = "Looks clear for now. Let's report back to Officer Fischer.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0109"
        },
        [10034901] = {
