        [10035221] = {
          Camera = "-107.312454,-25.77623,149.258545,0.000202,3.187383,-16.873236,35.0,144.868408,false,Manual,15.0",
          ContentKR = "안 되면 제가 직접 조사하죠 뭐. 어차피 월석 사냥꾼은 군단 소속도 아니니 그런 규칙 따위 신경 쓸 필요 없어요. 가자, 대장.",
          DialogueId = 10035221,
