]],
          SpeakNpcId = 100304,
          Subtitle = "It's the same this time. If I just sit by and let the \"Charon Hunt\" case end like this, I'll never forgive myself.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4516"
        },
        [10035232] = {
          Camera = "-514.289307,44.722595,247.631836,0.000043,-15.820329,-3.607711,35.0,612.436279,false,Manual,22.0",
          ContentKR = "죄송합니다, 여러분을 붙잡아 놓고 이렇게 오래된 이야기를 늘어놓다니... 이제 다시 움직여야겠어요! 아직 해가 지기 전에 말입니다.",
          DialogueId = 10035232,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "-511.032501,44.516754,237.636963,0.000039,-14.420188,-4.007435,35.0,612.436279,false,Manual,22.0",
          GUID = "191F4540",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextOptions = {
            [1] = 10035233,
            [2] = 10035234
          },
          SpeakNpcId = 100304,
          Subtitle = "Sorry for unloading all these old memories on you... I should get going while there's still daylight.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = [[

200021:Talk03_Start]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100352/191F4540"
        },
        [10035233] = {
          ContentKR = "같이 가요. 다시는 후회할 일 없게.",
          DialogueId = 10035233,
          GUID = "191F456A",
          ImprPlusId = 1009,
          NextDialogue = 10035235,
          Subtitle = "We'll go with you. I want to help you fix your regrets."
        },
        [10035234] = {
          ContentKR = "우리 몇 명만이 움직이는 건가요?",
          DialogueId = 10035234,
          GUID = "191F4594",
          ImprPlusId = 1006,
          NextDialogue = 10035235,
          Subtitle = "Just you and us?"
        },
        [10035235] = {
          Camera = "-152.189682,50.255051,133.710449,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0",
          ContentKR = "이건 제 스스로 내린 선택입니다. 게다가 이제 더 이상 저를 도울 수 있는 부하도 없어요. 그러니 여러분은 굳이 저를 따라 위험에 뛰어들 필요는 없습니다.",
          DialogueId = 10035235,
          FacialId = {
