            [2] = [[

200021:None]]
          },
          FinalCamera = "-144.869965,49.820297,133.784424,0.000057,0.579876,-3.407065,35.000008,194.348434,false,Manual,5.0",
          GUID = "191F45BE",
          NextDialogue = 10035236,
          SpeakNpcId = 100304,
          Subtitle = "This is my own choice, and I have no other subordinates to call upon. You don't have to risk yourselves to help me.",
