            [1] = "200021:ConfidentLR_Start",
            [2] = [[

100304:Talk01_End]]
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1003/100352/191F45E8"
        },
        [10035237] = {
