CameraMoveTo{_delay{0},TargetPosition{"-503.6875,2.337402,142.166504,10.871674,8.995338,169.140015,35.0,100000.0,false,Manual,22.0"},duration{3.5}}
}]],
          ToFinalCameraBlendTime = 3
        },
        [10035401] = {
          ContentKR = "...역시 범인은 살아 있었군요!",
          DialogueId = 10035401,
          GUID = "191F60FA",
          NextDialogue = 10035402,
          SpeakNpcId = 100304,
          Subtitle = "I knew the perpetrator is still alive!",
          VoiceName = "voice/$Locale$/story/1003/100354/191F60FA"
        },
        [10035402] = {
          ContentKR = "간도 크군, 제 발로 찾아오다니...",
          DialogueId = 10035402,
          GUID = "191F6124",
          NextDialogue = 10035403,
          SpeakNpcId = 200021,
          Subtitle = "Huh, came straight to us this time.",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6124"
        },
        [10035403] = {
          ContentKR = "'범인'이라...",
          DialogueId = 10035403,
          GUID = "191F614E",
          NextDialogue = 10035404,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "\"Perpetrator\"...?",
          VoiceName = "voice/$Locale$/story/1003/100354/191F614E"
        },
        [10035404] = {
          ContentKR = "보아하니, 그들은, 결국, 너에게 진실을, 밝히지 않았군. 역시 13군단도, 한통속이었을 뿐이야.",
          DialogueId = 10035404,
          GUID = "191F6178",
          NextDialogue = 10035405,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Hmph. Even now, they haven't... told you... the truth. Dirty liars. Even the 13th Legion... is no exception.",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6178"
        },
        [10035405] = {
          ContentKR = "진실? 무슨 말을 하는 거야...",
          DialogueId = 10035405,
          GUID = "191F61A2",
          NextDialogue = 10035406,
          SpeakNpcId = 100304,
          Subtitle = "The truth? What do you mean...?",
          VoiceName = "voice/$Locale$/story/1003/100354/191F61A2"
        },
        [10035406] = {
          ContentKR = "괴물이 시간을 끌고 있어요! 먼저 제압해요!",
          DialogueId = 10035406,
          GUID = "191F61CC",
          SpeakNpcId = 200021,
          Subtitle = "It's stalling — Take it down first!",
          VoiceName = "voice/$Locale$/story/1003/100354/191F61CC"
        },
        [10035407] = {
          Camera = "-315.066406,-84.020996,106.125488,0.000016,9.398941,7.940432,30.0,100000.0,false,Manual,7.44259",
          ContentKR = "잘 지냈어? 누나.",
          DialogueId = 10035407,
          FinalCamera = "-309.679688,-83.179199,106.931641,0.000015,8.998944,8.140003,30.0,100000.0,false,Manual,7.44259",
          GUID = "191F61F6",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)",
            [5] = "100327:n(100304)"
          },
          NextDialogue = 10035408,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "It's been so long, Sister.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F61F6"
        },
        [10035408] = {
          Camera = "1161.523438,-515.213623,358.976562,-10.001677,-11.199829,154.540695,35.0,100000.0,false,Manual,14.096215",
          ContentKR = "......?!",
          DialogueId = 10035408,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "1029.605469,-452.223145,330.28418,-10.001463,-11.199829,155.340485,35.0,100000.0,false,Manual,14.096215",
          GUID = "191F6220",
          LookAt = {
            [1] = "100304:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "200021:n(100304)"
          },
          NextDialogue = 10035409,
          SpeakNpcId = 100304,
          Subtitle = "...!?",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6220"
        },
        [10035409] = {
          Camera = "-162.207031,-39.662109,88.29541,0.00001,15.77163,15.197428,30.0,100000.0,false,Manual,13.369958",
          ContentKR = "아니다... 난 이젠, 널, 리듬 장교, 라고 불러야겠군. 진정은, 좀, 됐나.",
          DialogueId = 10035409,
          FacialId = {
            [1] = "100304:None"
          },
          FinalCamera = "-154.007812,-60.436035,88.29541,0.000008,16.371765,18.595819,30.0,100000.0,false,Manual,13.369958",
          GUID = "191F624A",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "200002:n(100327)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10035410,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{\"outside1\"},Visibility{\"Show\"}}",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Or should I say... Officer Fischer. Have you... calmed down... now?",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F624A"
        },
        [10035410] = {
          Camera = "-154.007812,-60.436035,88.29541,0.000008,16.371765,18.595819,30.0,100000.0,false,Manual,13.369958",
          ContentKR = "...넌 대체 누구지?!",
          DialogueId = 10035410,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191F6274",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035411,
          SpeakNpcId = 100304,
          Subtitle = "...Who are you!? Answer me!",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F6274"
        },
        [10035411] = {
          Camera = "-29.5625,-71.805176,165.97998,0.0,7.367677,18.358356,50.0,100000.0,false,Manual,22.0",
          ContentKR = "블루스 페실. 당신의, 동생. 그 하모니카의, 주인.",
          DialogueId = 10035411,
          FinalCamera = "-29.5625,-71.805176,165.97998,0.0,11.16768,18.558241,50.0,100000.0,false,Manual,22.0",
          GUID = "191F629E",
          NextDialogue = 10035412,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Blues Fischer. Your younger brother. The owner of that harmonica.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100354/191F629E"
        },
        [10035412] = {
          Camera = "749.542969,-320.927246,358.976562,0.000014,-16.229792,146.761581,50.0,100000.0,false,Manual,22.0",
          ContentKR = "블루스? 왜 그런 옷을 입고 있어...? 목소리는 또 왜 그래...?",
          DialogueId = 10035412,
          FacialId = {
            [1] = "100304:Shock02"
          },
          FinalCamera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.0",
          GUID = "191F62C8",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035413,
          SpeakNpcId = 100304,
          Subtitle = "Blues? Why are you dressed like that...? What happened to your voice...?",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100354/191F62C8"
        },
        [10035413] = {
          Camera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.0",
          ContentKR = "내성에서 복무하고 있던 거 아니었어? 왜... 네가...",
          DialogueId = 10035413,
          GUID = "191F62F2",
          NextDialogue = 10035414,
          SpeakNpcId = 100304,
          Subtitle = "I thought you were training in the inner city... Why... why are you...?",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F62F2"
        },
        [10035414] = {
          Camera = "720.9375,-367.028809,358.976562,0.000011,-16.029818,142.962021,50.0,100000.0,false,Manual,22.00",
          ContentKR = "허...",
          DialogueId = 10035414,
          GUID = "191F631C",
          NextDialogue = 10035415,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "Heh...",
          VoiceName = "voice/$Locale$/story/1003/100354/191F631C"
        },
        [10035415] = {
          Camera = "221.476562,-7.47168,109.081543,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0",
          ContentKR = "아니야, 거짓말이야. 내 동생 블루스는 열정적이고 착한 사람이야. 그는 타인의 고통을 자신의 고통으로 여기고, 모든 동포를 형제처럼 여겼어! 그런 그가 <H>카론 사냥</> 같은 잔혹한 짓을 저질렀을 리 없잖아!",
          DialogueId = 10035415,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "196.777344,-3.805176,112.84082,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0",
          GUID = "191F6346",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10035425,
          SpeakNpcId = 100304,
          Subtitle = "No... you're lying. My Blues has a heart of gold. He shares other people's suffering as if it were his own and treats every Charon like family! He'd never have committed atrocities like the Charon Hunt!",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6346"
        },
        [10035416] = {
          Camera = "196.777344,-3.805176,112.84082,0.0,8.568786,171.554718,35.0,100000.0,false,Manual,22.0",
          ContentKR = "이건, 어릴 때... 내가 블루스를 위해 만든 체인이잖아...",
          DialogueId = 10035416,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter02_HarmonicaChain.T_Guide_Chapter02_HarmonicaChain'}",
          GUID = "191F6370",
          NextDialogue = 10035417,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/chainpocket\"},PlayAs2D{true}}",
          SpeakNpcId = 100304,
          Subtitle = "This... this is the chain I made for Blues when we were kids...",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6370"
        },
        [10035417] = {
          Camera = "-29.5625,-71.805176,165.97998,0.0,11.16768,18.558241,50.0,100000.0,false,Manual,22.0",
          ContentKR = "돌려줄게. 군단은, 날 배신했어. 이젠, 그건, 더 이상 필요 없어.",
          DialogueId = 10035417,
          GUID = "191F639A",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035418,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "Take it back. The Legion betrayed me. I don't need it anymore.",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F639A"
        },
        [10035418] = {
          Camera = "119.15625,42.66748,164.325195,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "리듬 씨, 일단 흥분하지 마세요. 우리 전에 그놈의 교활함을 겪어봤잖아요. 동생의 이름을 훔쳐서 다른 속셈을 꾸미고 있을 가능성이 커요.",
          DialogueId = 10035418,
          FinalCamera = "156.070312,53.80127,172.121582,0.00001,-11.431517,-163.217941,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F63C4",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10035419,
          SpeakNpcId = 100001,
          Subtitle = "Rhythm, don't jump to conclusions. You've seen how cunning this monster is. He could just be disguising himself as your brother to manipulate you.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F63C4"
        },
        [10035419] = {
          Camera = "-331.53125,-373.69873,96.422363,10.800302,6.167674,40.957329,35.0,100000.0,false,Manual,22.0",
          ContentKR = "...당신 말이 사실이길 얼마나 바라는지 모릅니다. 하지만 저 녀석의 모든 동작은, 저에겐 너무나 익숙한걸요...",
          DialogueId = 10035419,
          FinalCamera = "-289.46875,-337.193848,102.441895,7.200046,6.167674,40.957287,35.0,100000.0,false,Manual,22.0",
          GUID = "191F63EE",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035420,
          SpeakNpcId = 100304,
          Subtitle = "...I wish that were true. But his every move... I know them too well...",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F63EE"
        },
        [10035420] = {
          Camera = "40.863281,-1146.140381,-4.161133,0.000027,7.377881,83.959587,50.0,100000.0,false,Manual,22.0",
          ContentKR = "특히 손을 뒤로 뻗어 뭔가를 찾는 그 모습, 어린 시절의 블루스랑 똑같습니다.",
          DialogueId = 10035420,
          FacialId = {
            [1] = "100304:Sad01"
          },
          GUID = "191F6418",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10035421,
          SpeakNpcId = 100304,
          Subtitle = "Especially the way he reached behind himself to search for something... it's exactly how Blues used to look for his harmonica.",
          VoiceName = "voice/$Locale$/story/1003/100354/191F6418"
        },
        [10035421] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117",
          ContentKR = "...그러고 보니, 리듬을 만난 뒤로 계속 <H>우리를 공격하지 않고 봐주고 있었던 것 같아</>.",
          DialogueId = 10035421,
          GUID = "191F6442",
          LookAt = {
            [1] = "100001:n(100327)"
          },
          NextDialogue = 10035422,
          SpeakNpcId = 100001,
          Subtitle = "...Now that you mention it, since he saw Rhythm, he's been holding back to avoid hurting us.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F6442"
        },
        [10035422] = {
          Camera = "145.246094,50.835938,159.95459,0.000014,-7.221675,-164.220459,35.000008,100000.0,false,Manual,13.900117",
          ContentKR = "넌 아직 의식이 있어. 게다가 <H>네 몸에 있는 저건 갑옷이 아니라</>... 그냥 몸의 일부처럼 보여. 대체 무슨 일이 있었던 거야? \"군단이 배신했다\"는 건 또 무슨 뜻이야?",
          DialogueId = 10035422,
          GUID = "191F646C",
          NextDialogue = 10035423,
          SpeakNpcId = 100001,
          Subtitle = "So, you're still sentient. And... those mechanical pieces encasing you don't look like armour. They're more like... part of your body. What happened to you? What do you mean by \"the Legion betrayed you\"?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100354/191F646C"
        },
        [10035423] = {
          Camera = "-1343.695312,-699.813721,314.711426,10.834046,-7.832737,28.140293,50.0,100000.0,false,Manual,22.0",
          ContentKR = "...너의, 직감, 꽤 날카로워. 하지만 제국에서, 그건 꼭 좋은 일만은, 아니지...",
          DialogueId = 10035423,
          FinalCamera = "-1351.945312,-685.367432,310.913574,10.833482,-7.832731,28.140591,50.0,100000.0,false,Manual,22.0",
          GUID = "191F6496",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10035424,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...Your instincts... are sharp. But in the Empire... that's not always... a good thing.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100354/191F6496"
        },
        [10035424] = {
          Camera = "-1351.945312,-685.367432,310.913574,10.833482,-7.832731,28.140591,50.0,100000.0,false,Manual,22.0",
          ContentKR = "...리듬, 내 누나... 내가 알려줄게. '계관카론'의, 진실을...",
          DialogueId = 10035424,
          GUID = "191F64C0",
          LookAt = {
            [1] = "100327:n(100304)"
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Rhythm... my sister. Let me tell you... the cruel truth behind... the title of \"Laurelled Charon.\"",
          VoiceName = "voice/$Locale$/story/1003/100354/191F64C0"
        },
        [10035425] = {
          Camera = "53.945312,-48.872559,263.330078,0.000002,-24.832872,18.36636,28.000006,100000.0,false,Manual,22.0",
          DialogueId = 10035425,
          DialoguePanelType = "None",
          Duration = 7,
          GUID = "191F6347",
          NextDialogue = 10035416,
          Scripts = "PlayAnimation{_delay{0},ActorId{100327},AnimationId{\"Tuosi02_Story_Find02_Start\"},Duration{5}}"
        },
        [10035501] = {
          ContentKR = "'계관카론', 난 한때 그걸 가장 빛나는 다이아몬드로 여겼어.\n꿈의 끝에서 반짝이며, 마치 아이스레이크 시티 가장 높은 곳에 있는 꺼지지 않는 등불처럼 말이야.",
          DialogueId = 10035501,
          Duration = 4,
          GUID = "191F7162",
          NextDialogue = 10035502,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The \"Laurelled Charon\" — once, I believed it to be a diamond of the utmost brilliance.\nIt gleamed at the horizon of my dreams, like the eternal light atop Icelake's highest peak.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7162"
        },
        [10035502] = {
          ContentKR = "나중에야 알게 됐어, 그건 단단한 다이아몬드가 아니었어.\n그건 유리야. 허상의 빛을 반사하며 아름답고 눈부셨지만,\n조약돌 하나, 진흙 벽돌 한 조각에도 쉽게 산산조각이 났어.",
          DialogueId = 10035502,
          Duration = 4,
          GUID = "191F718C",
          NextDialogue = 10035503,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But later, I realised it wasn't a diamond at all.\nIt was glass — reflecting an illusory light. Beautiful, dazzling, but so fragile it could be shattered by a single pebble or a chunk of clay.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F718C"
        },
        [10035503] = {
          ContentKR = "제6군단의 시험을 통과한 카론은 도살당할 운명의 가엾은 짐승과 다를 바가 없었어.\n오히려 무지하고 무감각한 짐승이 되는 편이 나았을지도 몰라.\n그랬다면 무너진 꿈에 고통받지도, 이루지 못한 약속에 통곡하지도 않았을 테니까.",
          DialogueId = 10035503,
          Duration = 4,
          GUID = "191F71B6",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "A Charon who passes the 6th Legion's tests is nothing more than a caged beast awaiting slaughter.\nIn truth, we would rather become numb, unthinking beasts —\nFor then we wouldn't endure the agony of shattered dreams or weep over unfulfilled promises.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71B6"
        },
        [10035504] = {
          ContentKR = "(윽 눈부셔... 여긴 어디지? 분명 시험을 통과한 후 제6군단 연금원에서 일하게 되었는데...)",
          DialogueId = 10035504,
          GUID = "191F71E0",
          RelatedWikiId = {
            [1] = 407003,
            [2] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(Ah, this glare... Where am I? I remember passing the tests, being assigned to the 6th Legion's alchemy academy, and then...)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71E0"
        },
        [10035505] = {
          ContentKR = "선생님, 개조체가 예상보다 일찍 깨어났는데요. 아주 괴로워 보이는데 마취제를 좀 더 가져오겠습니다.",
          DialogueId = 10035505,
          GUID = "191F720A",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = [[
Professor, the test subject's consciousness seems to have awakened earlier than scheduled.
It seems to be in great pain. Should I administer another dose of anaesthetic?]],
          VoiceName = "voice/$Locale$/story/1003/100355/191F720A"
        },
        [10035506] = {
          ContentKR = "괜찮으니 그대로 둬. 2분 뒤에 저항성 데이터를 수집할 수 있게 준비한다.",
          DialogueId = 10035506,
          GUID = "191F7234",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "No need. Let it stay awake. Begin resistance data extraction in two minutes.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7234"
        },
        [10035507] = {
          DialogueId = 10035507,
          GUID = "191F725E",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F725E"
        },
        [10035508] = {
          ContentKR = "데이터가 나왔습니다. 개조체의 저항성은 이번 실험체 중에 뛰어난 편입니다. 전류는 이식한 두 번째 심장을 직접 관통하지 못했고, 화염이 인공 피부를 손상시켜 체온이 정상치를 크게 상회합니다.",
          DialogueId = 10035508,
          GUID = "191F7288",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = [[
Professor, the data is in. This one shows exceptional resistance among this batch of augmented subjects. 
The current test failed to breach the secondary heart you implanted, while fire has damaged its synthetic skin,
causing its body temperature to spike far beyond normal limits.]],
          VoiceName = "voice/$Locale$/story/1003/100355/191F7288"
        },
        [10035509] = {
          ContentKR = "데이터는 기록했습니다. 일단 좀 쉬게 하죠, 놈의 체력이 버티지 못할 것 같습니다.",
          DialogueId = 10035509,
          GUID = "191F72B2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Data collection complete. It's on the verge of collapse — shall I take it back to rest?",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72B2"
        },
        [10035510] = {
          ContentKR = "이 악마들에게 쓸데없는 동정을 품지 말거라. 진정제를 주사하고 사지를 고정해. 강화 실험을 시작하겠다.",
          DialogueId = 10035510,
          GUID = "191F72DC",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = [[
Do not waste your compassion on these demons.
Administer the sedative, secure its limbs, and prepare for the next enhancement experiment.]],
          VoiceName = "voice/$Locale$/story/1003/100355/191F72DC"
        },
        [10035511] = {
          ContentKR = "(아파... 너무 아파... 대체 나한테 무슨 짓을 한 거야. 온몸의 모든 모공마저도 고통에 비명을 지르고 있는데... 안 들리는 거냐고!)",
          DialogueId = 10035511,
          GUID = "191F7306",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(It hurts... It hurts so much... What have you done to me!? Every inch of my body is screaming in agony — can't you hear!?)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7306"
        },
        [10035512] = {
          ContentKR = "표정이 참 풍부하군. 왜? 짖어 보고 싶은 건가? 안타깝지만 기회는 없을 거야.",
          DialogueId = 10035512,
          GUID = "191F7330",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Such vivid expressions. What, are you trying to bark something at me? Too bad, you won't get the chance.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7330"
        },
        [10035513] = {
          ContentKR = "진정제 주사 완료했습니다. 선생님, 제 생각엔 아무래도...",
          DialogueId = 10035513,
          GUID = "191F735A",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Sedative administered, Professor. But I still think we should—",
          VoiceName = "voice/$Locale$/story/1003/100355/191F735A"
        },
        [10035514] = {
          ContentKR = "내 말대로 해. 가장 민감한 뿔 끝부분부터 샘플을 채취해. 그래야 더 정확한 데이터를 얻을 수 있다.",
          DialogueId = 10035514,
          GUID = "191F7384",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Just follow my instructions. Begin with the horns — they are its most sensitive parts. This way, we'll get the most precise data.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7384"
        },
        [10035515] = {
          ContentKR = "...네, 선생님...",
          DialogueId = 10035515,
          GUID = "191F73AE",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "...Understood, Professor...",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73AE"
        },
        [10035516] = {
          ContentKR = "(너무 아파... 너무 아파... 이게 바로 '악마의 아이'로서 반드시 받아야 할 벌인 건가...)",
          DialogueId = 10035516,
          GUID = "191F73D8",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(It hurts... so much... Is this the punishment for being a \"Demon's Child\"?)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73D8"
        },
        [10035517] = {
          ContentKR = "(하지만 아무리 큰 죄라 해도, 이런 고통은... 진작에 다 갚았어야 맞는 거잖아...!)",
          DialogueId = 10035517,
          GUID = "191F7402",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "(But no matter the sins we bear, shouldn't such suffering and agony... have repaid it all by now!?)",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7402"
        },
        [10035518] = {
          ContentKR = "우린 이런 날들이 얼마나 흘렀는지도 알 수 없었어...\n그저 우리 몸이 점점 흉측한 괴물로 변해가고 있다는 것만 느껴졌지.\n마음도 점점 얼어붙었고, 눈물의 호수 위로 불어오는 차가운 바람 속에서 산산조각이 나버렸어...",
          DialogueId = 10035518,
          GUID = "191F742C",
          NextDialogue = 10035519,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I don't know how long those days dragged on, only that my body was slowly twisted into the shape of a grotesque monster. My heart grew colder with each passing moment, shattered into shards by the frigid winds of Lamenting Lake.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F742C"
        },
        [10035519] = {
          ContentKR = "사람으로 태어났던 옛 기억은 점점 멀어져 갔어. 결국, 이름조차 잊히고 말았지.",
          DialogueId = 10035519,
          GUID = "191F7456",
          NextDialogue = 10035520,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The old memories as a human slipped further and further away, until even my name was lost, swallowed by the abyss.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7456"
        },
        [10035520] = {
          ContentKR = "블루스 페실은 죽었어. 이제 남은 건 <W>47번</>이라는 새 '호칭'뿐이야.",
          DialogueId = 10035520,
          GUID = "191F7480",
          NextDialogue = 10035521,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Blues Fischer is dead. In his place remains a hollow shell, his name erased — now known only as Subject 47.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7480"
        },
        [10035521] = {
          ContentKR = "하지만 그런데도, 우리의 육체는 여전히 비참하게 발버둥 치며 버티고 있었어.",
          DialogueId = 10035521,
          GUID = "191F74AA",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "And yet, this wretched body still clung desperately to the instinct to survive.",
          VoiceName = "voice/$Locale$/story/1003/100355/191F74AA"
        },
        [10035522] = {
          Camera = "-4.90918,-156.237305,105.101868,-0.000091,10.758511,116.110672,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "보고드립니다, 선생님. 배척 반응은 멈췄고, 각종 지표도 안정 상태로 접어들었습니다. 다만 β형 억제제를 너무 많이 사용한 탓인지 정신 상태가 불안정합니다.",
          DialogueId = 10035522,
          FinalCamera = "-9.579102,-158.523438,105.101868,-0.000092,10.758511,114.710289,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "191F74D4",
          NextDialogue = 10035523,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000069,7.559721,84.699837,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000061,11.159675,84.499451,35.0,100000.0,false,DoNotOverride,2.8\"},duration{5}}}",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Professor, the subject's rejection response has ceased, and all vital signs are stabilising. However, it seems we've overused the β-type suppressant — the subject's mental state is unstable.",
          TalkActionId = {
            [1] = "100337:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74D4"
        },
        [10035523] = {
          Camera = "-179.390625,29.248047,164.763611,0.000084,-5.841492,-25.696522,35.0,251.812622,false,Manual,2.797869",
          ContentKR = "정신 따위는 생명 대사의 부산물일 뿐이야. 개조체가 '예'라고 대답할 수 있으면 그걸로 충분하다. 실험장으로 데리고 가라.",
          DialogueId = 10035523,
          FinalCamera = "-182.842773,22.280273,164.763611,0.000086,-5.841492,-21.695681,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F74FE",
          NextDialogue = 10035524,
          SpeakNpcId = 100337,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "The mind is nothing more than a byproduct of biological processes. All we need is obedience — as long as the subject can respond with a \"yes.\" Take it to the testing ground.",
          TalkActionId = {
            [1] = "100337:Explain01_End",
            [2] = "100336:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74FE"
        },
        [10035524] = {
          Camera = "20.333008,-203.238281,111.764038,0.00009,4.758661,116.695335,35.0,251.812622,false,Manual,2.797869",
          ContentKR = "네, 선생님.",
          DialogueId = 10035524,
          FinalCamera = "20.333008,-203.238281,111.764038,0.000089,7.758616,116.69487,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F7528",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Yes, Professor.",
          TalkActionId = {
            [1] = "100337:Agree",
            [2] = "100336:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F7528"
        },
        [10035601] = {
          ContentKR = "억제제가 있으면, <H>우리 명령에 거역하는 것조차 할 수 없어</>. 완전히 가축이나 다름없군.",
          DialogueId = 10035601,
          GUID = "191F81CA",
          NextDialogue = 10035602,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "With those suppressants, it couldn't defy our orders even if it tried. Like pathetic, mindless beasts.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81CA"
        },
        [10035602] = {
          ContentKR = "잔인하고 야만적이며, 이성도 없고 아름다움도 전혀 느껴지지 않는군. 하지만, 그게 바로 카론의 원초적인 모습이지.",
          DialogueId = 10035602,
          GUID = "191F81F4",
          NextDialogue = 10035603,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Savage, brutish, devoid of intelligence or elegance. Hmph, but this is the true form of a Charon.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81F4"
        },
        [10035603] = {
          ContentKR = "이봐, 놈에게서 떨어지라고. 혹시 몸에 뭔가 더러운 게 묻어 있을지도 모르잖아.",
          DialogueId = 10035603,
          GUID = "191F821E",
          NextDialogue = 10035604,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Hey, stay away from it. Who knows what kind of filth it's carrying?",
          VoiceName = "voice/$Locale$/story/1003/100356/191F821E"
        },
        [10035604] = {
          ContentKR = "이따가 놈의 전투 데이터를 잘 기록해 둬. 기준에 못 미치거나 수상한 행동이라도 보이면 바로 처리해.",
          DialogueId = 10035604,
          GUID = "191F8248",
          NextDialogue = 10035605,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Make sure to record its combat data thoroughly. If it fails to meet the standards or shows any suspicious behaviour, dispose of it immediately.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8248"
        },
        [10035605] = {
          ContentKR = "정말 이렇게 해도 되는 건가? 너무 잔인한 거 아닐까?",
          DialogueId = 10035605,
          GUID = "191F8272",
          NextDialogue = 10035606,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Are you sure we can do that? This feels excessively cruel, doesn't it?",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8272"
        },
        [10035606] = {
          ContentKR = "아니, 오히려 이렇게 말해야지. 폐하의 자비와 연금술의 위대함이 이런 쓰레기들에게조차 연금원에 헌신할 가치를 부여한 거라고.",
          DialogueId = 10035606,
          GUID = "191F829C",
          NextDialogue = 10035607,
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Cruel? You've got it all wrong. It is by His Majesty's benevolence and the magnificence of alchemical technology that this trash has been given the honour of serving the academy's great cause.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F829C"
        },
        [10035607] = {
          ContentKR = "도망칠 생각은 하지 마라. 전기 울타리와 기관포는 우리처럼 자비롭지 않으니까. 자해할 생각도 하지 마라. 네 하찮은 목숨을 유지할 약품은 아직도 차고 넘치니까.",
          DialogueId = 10035607,
          GUID = "191F82C6",
          SpeakNpcName = "Cp2CharacterName32",
          Subtitle = "Don't even think about running. The electrified grids and gun turrets are far less forgiving than we are. And forget self-destruction — we have plenty of drugs to prolong your worthless existence.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C6"
        },
        [10035608] = {
          ContentKR = "테스트를 시작한다, 개조체를 투입해.",
          DialogueId = 10035608,
          GUID = "191F82F0",
          NextDialogue = 10035609,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test begins. Release the subject.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82F0"
        },
        [10035609] = {
          ContentKR = "47번, 모든 방해자를 제거해라.",
          DialogueId = 10035609,
          GUID = "191F831A",
          NextDialogue = 10035610,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Subject 47, eliminate all obstacles.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F831A"
        },
        [10035610] = {
          ContentKR = "네.",
          DialogueId = 10035610,
          GUID = "191F8344",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Yes.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8344"
        },
        [10035611] = {
          ContentKR = "저쪽에 아직 적이 있어, 멈추지 말고 계속하거라.",
          DialogueId = 10035611,
          GUID = "191F836E",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "There are still enemies over there. Don't stop now.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F836E"
        },
        [10035612] = {
          ContentKR = "데이터가 예상보다 뒤처지고 있어. 저쪽 적들도 처리해, 빨리.",
          DialogueId = 10035612,
          GUID = "191F8398",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "The numbers are underwhelming. Go and clear out the enemies over there. Now.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8398"
        },
        [10035613] = {
          ContentKR = "힘내! 힘내라고!",
          DialogueId = 10035613,
          GUID = "191F83C2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Keep it up! Keep it up!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83C2"
        },
        [10035614] = {
          ContentKR = "부상인가? 너무 약한 거 아니야?",
          DialogueId = 10035614,
          GUID = "191F83EC",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Injured already? Useless worm.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83EC"
        },
        [10035615] = {
          ContentKR = "저쪽으로~",
          DialogueId = 10035615,
          GUID = "191F8416",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Go that way! Hurry up~!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8416"
        },
        [10035616] = {
          ContentKR = "저쪽 적이 아직 숨이 붙어 있잖아. 이런 적도 제대로 처리 못 하는 거야?",
          DialogueId = 10035616,
          GUID = "191F8440",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "That one over there is still breathing. Can't you even handle that? Finish it!",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8440"
        },
        [10035617] = {
          ContentKR = "테스트 통과. 수용소로 데려가. 우리는 다음 개조체를 맞이할 준비를 한다.",
          DialogueId = 10035617,
          GUID = "191F846A",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test complete. Return it to the cell. Prepare for the next batch of subjects.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F846A"
        },
        [10035618] = {
          ContentKR = "데이터는 언제 나오는 거야? 기다리다 지친다.",
          DialogueId = 10035618,
          GUID = "191F82C7",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "When's the data coming in? I'm running out of patience.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C7"
        },
        [10035619] = {
          ContentKR = "이번엔 제발 성공해야 하는데.",
          DialogueId = 10035619,
          GUID = "191F82C8",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Let's hope it works this time.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C8"
        },
        [10035620] = {
          ContentKR = "3일 뒤에 5차 강화를 시작할 거야.",
          DialogueId = 10035620,
          GUID = "191F82C9",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Fifth injection's scheduled in three days.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C9"
        },
        [10035621] = {
          ContentKR = "폐기율이 좀 높은 게 아쉬운걸...",
          DialogueId = 10035621,
          GUID = "191F82CA",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Failure rate's still high... hope we have enough test subjects left.",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82CA"
        },
        [10035701] = {
          Camera = "220.367188,-259.076172,237.702698,0.000082,-11.603056,-49.20525,20.000011,335.406189,false,Manual,1.2",
          ContentKR = "일어나, 일어나.",
          DialogueId = 10035701,
          FinalCamera = "215.316406,-263.4375,237.702698,0.000082,-11.603056,-49.20525,20.000011,335.406189,false,Manual,1.2",
          GUID = "191F9232",
          NextDialogue = 10035702,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Hey, wake up.",
          TalkActionId = {
            [1] = "100331:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9232"
        },
        [10035702] = {
          Camera = "455.675781,-610.116211,254.409729,0.000055,-14.003389,120.793579,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentKR = "난 36번이야, 넌 누구야?",
          DialogueId = 10035702,
          FinalCamera = "446.724609,-615.169922,254.409729,0.000057,-12.803305,115.393036,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F925C",
          NextDialogue = 10035703,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I'm 36. Who are you?",
          TalkActionId = {
            [1] = "100331:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F925C"
        },
        [10035703] = {
          Camera = "-97.664062,-97.821289,211.294312,0.000093,-6.601774,-26.81625,20.000011,670.626465,false,Manual,1.2",
          ContentKR = "......",
          DialogueId = 10035703,
          FinalCamera = "-91.411133,-85.444336,211.294312,0.000093,-6.601774,-27.615789,20.000011,670.626465,false,Manual,22.0",
          GUID = "191F9286",
          NextDialogue = 10035704,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9286"
        },
        [10035704] = {
          Camera = "316.166016,-370.8125,168.484741,0.000076,8.598402,-44.815922,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentKR = "말하기 싫어도 괜찮아. 그냥 아무 소리나 내봐. 네가 살아 있다는 것만 알면 돼.",
          DialogueId = 10035704,
          FinalCamera = "290.038086,-344.858398,162.916687,0.000075,8.598402,-44.815895,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F92B0",
          NextDialogue = 10035705,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Not in the mood to talk? That's fine. Just make a sound so I know you're alive.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F92B0"
        },
        [10035705] = {
          Camera = "-180.529297,-310.954102,177.634216,0.000067,1.398201,38.782471,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentKR = "...47번.",
          DialogueId = 10035705,
          FinalCamera = "-190.380859,-298.686523,177.634216,0.000067,1.1982,38.781147,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F92DA",
          NextDialogue = 10035706,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...47.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100357/191F92DA"
        },
        [10035706] = {
          Camera = "215.392578,-260.694336,230.287964,0.000079,-5.401976,-49.228199,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentKR = "다행이다. 다시는 얘기 나눌 사람을 못 만날 줄 알았어.",
          DialogueId = 10035706,
          FinalCamera = "220.646484,-256.163086,230.287964,0.000079,-5.401976,-49.228199,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9304",
          NextDialogue = 10035707,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"563.330078,-792.032227,144.184875,0.000041,2.194956,119.372292,20.000011,1068.904175,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"538.634766,-804.90332,144.184875,0.000043,2.794913,115.771866,20.000011,1068.904175,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Thank goodness. I thought I'd never meet another person to talk to.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9304"
        },
        [10035707] = {
          Camera = "-131.793945,-64.760742,220.011841,10.800352,-6.20175,-20.624842,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentKR = "우리 친해?",
          DialogueId = 10035707,
          FinalCamera = "-126.806641,-50.629883,217.170044,10.800995,-6.20175,-22.424656,20.000011,335.406189,false,DoNotOverride,1.2",
          GUID = "191F932E",
          NextDialogue = 10035708,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Do we know each other?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F932E"
        },
        [10035708] = {
          Camera = "268.87207,-364.642578,243.919006,-0.000123,-11.801576,-35.824482,30.0,335.406189,false,DoNotOverride,1.2",
          ContentKR = "하하, 곧 친해지겠지. 우린 이 끔찍한 곳에 남은 유일한 <H>사람</>이잖아.",
          DialogueId = 10035708,
          FinalCamera = "274.612305,-357.021484,243.919006,-0.000123,-11.801535,-39.423576,30.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9358",
          NextDialogue = 10035709,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"511.429688,-699.175781,227.014282,-0.000031,-3.401277,122.771469,25.0,335.406189,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"493.702148,-710.414062,227.014282,-0.000031,-3.001281,119.171577,25.0,335.406189,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Haha, not yet, but we'll get there. After all, we're the only humans in this hellhole.",
          TalkActionId = {
            [1] = "100331:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9358"
        },
        [10035709] = {
          Camera = "-187.094727,-308.035156,217.466675,-0.000031,-2.601619,46.970585,25.0,335.406189,false,DoNotOverride,1.2",
          ContentKR = "하, 우리를 아직 사람이라고 생각하는 건 너뿐이야.",
          DialogueId = 10035709,
          FinalCamera = "-195.34375,-300.339844,217.466675,-0.000031,-2.601619,46.970585,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9382",
          NextDialogue = 10035710,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Humans? Only you would still think of us that way.",
          TalkActionId = {
            [1] = "100331:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9382"
        },
        [10035710] = {
          Camera = "187.789062,-301.319336,147.267517,-0.000031,6.198061,-41.427723,25.0,335.406189,false,DoNotOverride,1.2",
          ContentKR = "중요한 건 마음이야.",
          DialogueId = 10035710,
          FinalCamera = "197.701172,-290.091797,147.267517,-0.000031,6.198061,-41.427723,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F93AC",
          NextDialogue = 10035711,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "It's what's in the heart that counts.",
          TalkActionId = {
            [1] = "100331:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F93AC"
        },
        [10035711] = {
          Camera = "-141.865234,31.176758,158.599976,-0.000031,13.99628,-38.820576,25.0,335.406189,false,DoNotOverride,1.2",
          ContentKR = "그런 건 이미 오래전에 실험대에서 산산조각 났어.",
          DialogueId = 10035711,
          FinalCamera = "-132.458984,42.869141,158.599976,-0.000031,13.796285,-42.620617,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F93D6",
          NextDialogue = 10035712,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "The heart? That was torn apart on the operating table long ago.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F93D6"
        },
        [10035712] = {
          Camera = "147.782227,-325.042969,147.337708,0.000036,5.995984,-31.222105,25.0,335.406189,false,DoNotOverride,1.2",
          ContentKR = "그럼, 우리가 그걸 다시 맞춰보자. 그리고 함께 사람으로 이곳에서 탈출하는 거야.",
          DialogueId = 10035712,
          FinalCamera = "153.202148,-316.107422,147.337708,0.000036,5.995984,-31.222105,25.0,335.406189,false,DoNotOverride,1.2",
          GUID = "191F9400",
          NextDialogue = 10035713,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Then let's piece it back together. And once we've done that, we'll get out of here together — as humans.",
          TalkActionId = {
            [1] = "100331:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100357/191F9400"
        },
        [10035713] = {
          Camera = "255.836914,-351.580078,219.478699,0.000112,-5.004336,131.172974,25.0,374.165375,false,Manual,1.908222",
          ContentKR = "...꿈 깨.",
          DialogueId = 10035713,
          FinalCamera = "273.556641,-371.847656,221.835327,0.000112,-5.004336,131.172974,25.0,374.165375,false,Manual,1.908222",
          GUID = "191F942A",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...Keep dreaming.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100328:n(100331)"
          },
          VoiceName = "voice/$Locale$/story/1003/100357/191F942A"
        },
        [10035801] = {
          ContentKR = "테스트 시작. 이번 적은 비교적 드문 유형이니 데이터 기록을 철저하게 해.",
          DialogueId = 10035801,
          GUID = "191FA29A",
          NextDialogue = 10035802,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Test begins. The targets assigned to the subject this time are rare. Ensure the data is recorded in meticulous detail.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA29A"
        },
        [10035802] = {
          ContentKR = "네, 선생님!",
          DialogueId = 10035802,
          GUID = "191FA2C4",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Yes, Professor!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA2C4"
        },
        [10035803] = {
          ContentKR = "우리가 사로잡히긴 했지만, 감히 우리에게 무기를 주다니, 신의 분노를 맛보게 해주겠다!",
          DialogueId = 10035803,
          GUID = "191FA2EE",
          NextDialogue = 10035804,
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "We may be prisoners, but now that we're given weapons, we can still show you the wrath of the gods!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA2EE"
        },
        [10035804] = {
          ContentKR = "휘페르보레아인, 타락한 신성 모독자들, 이런 괴물을 만들어내다니! 죽여라!",
          DialogueId = 10035804,
          GUID = "191FA318",
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "Hyperboreans, you vile degenerates! How dare you create such a blasphemous monster! Let's kill this abomination!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA318"
        },
        [10035805] = {
          ContentKR = "살, 살려줘! 이미 항복했잖아!",
          DialogueId = 10035805,
          GUID = "191FA342",
          NextDialogue = 10035806,
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "Please, spare us! We've already surrendered!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA342"
        },
        [10035806] = {
          ContentKR = "......",
          DialogueId = 10035806,
          GUID = "191FA36C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10035807,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA36C"
        },
        [10035807] = {
          ContentKR = "아홉 신이시여...! 제발 저를 불쌍히 여기소서. 지혜를 주소서, 힘을 주소서, 그리고 가호를 내려 주소서...!",
          DialogueId = 10035807,
          GUID = "191FA396",
          NextDialogue = 10035808,
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "O the Great Nine...! Hear me... grant me your mercy, your wisdom, your strength, and your deliverance...",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA396"
        },
        [10035808] = {
          ContentKR = "죄송합니다.",
          DialogueId = 10035808,
          GUID = "191FA3C0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10035809,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Sorry.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA3C0"
        },
        [10035809] = {
          ContentKR = "아아... 용서해 주소서, 용서해 주소서...",
          DialogueId = 10035809,
          GUID = "191FA3EA",
          SpeakNpcName = "Cp2CharacterName31",
          Subtitle = "O merciful gods... grant me forgiveness, grant me absolution...",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA3EA"
        },
        [10035810] = {
          ContentKR = "가라! 너희 중 누가 진짜 악마인지 한번 보자고, 하하하!",
          DialogueId = 10035810,
          GUID = "191FA414",
          NextDialogue = 10035811,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Go on! Let's see which of you truly deserves to be called a demon — haha!",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA414"
        },
        [10035811] = {
          ContentKR = "정말 쓸 만하군. 그동안 주사했던 억제제와 함께 안정성도 꽤 높아졌어.",
          DialogueId = 10035811,
          GUID = "191FA43E",
          NextDialogue = 10035812,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Impressive! The suppressants we've been injecting are finally showing results. Stability's never been this high.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA43E"
        },
        [10035812] = {
          ContentKR = "이대로라면 개조 실험을 다른 군단에도 확산시키는 건 시간문제겠어.",
          DialogueId = 10035812,
          GUID = "191FA468",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "At this rate, it won't be long before we can roll out these augmentation experiments across the other legions.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA468"
        },
        [10035813] = {
          ContentKR = "실험 데이터 수집 완료. 너희는 알아서 돌아가, 나는 선생님께 보고서를 제출하러 가야 되니까.",
          DialogueId = 10035813,
          GUID = "191FA492",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Data's all logged. You can head back on your own — I've got to prepare the report for the Professor.",
          VoiceName = "voice/$Locale$/story/1003/100358/191FA492"
        },
        [10035814] = {
          ContentKR = "수치들이 변동 범위 안이야. 이번엔 희망이 보여!",
          DialogueId = 10035814,
          GUID = "191F942B",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "All readings are within tolerance. This one's showing real promise!",
          VoiceName = "voice/$Locale$/story/1003/100358/191F942B"
        },
        [10035815] = {
          ContentKR = "왜 아직도 36번하고 47번 발끝에도 못 미치는 거지? 대체 뭐가 문제야...",
          DialogueId = 10035815,
          GUID = "191F942C",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Still not matching Subjects 36 or 47... what's causing the discrepancy?",
          VoiceName = "voice/$Locale$/story/1003/100358/191F942C"
        },
        [10035816] = {
          ContentKR = "투여량을 늘리는 걸 고려해 봐야겠어.",
          DialogueId = 10035816,
          GUID = "191F942D",
          SpeakNpcName = "Cp2CharacterName22",
          Subtitle = "Time to raise the dosage.",
          VoiceName = "voice/$Locale$/story/1003/100358/191F942D"
        }
      }
    end
  },
