        },
        [10036322] = {
          ContentKR = "잘한다! 한번 더 해줘!",
          DialogueId = 10036322,
          GUID = "191FF814",
          NextDialogue = 10036323,
          SpeakNpcName = "Cp2CharacterName33",
          Subtitle = "Bravo! Let's hear it again!",
