        [10036503] = {
          Camera = "106.291016,-60.851074,45.765625,14.408816,17.79439,114.413322,25.0,100000.0,false,Manual,22.0",
          ContentKR = "페실 준위, 월석 사냥꾼? 지금 뭘 하는 거야, 저 괴물, '카론 사냥'의 범인을 감싸는 건가?!",
          DialogueId = 10036503,
          FinalCamera = "106.291016,-60.851048,45.765625,14.408128,21.19454,114.414146,25.0,100000.0,false,Manual,22.0",
          GUID = "192015C6",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036504,
          SpeakNpcId = 100310,
          Subtitle = "Warrant Officer Fischer and the Phoxhunters? Are you... shielding that monster — the \"Charon Hunt\" perpetrator?",
