    Loader = function()
      return {
        [10036521] = {
          ContentKR = "어쩔 수 없네. 이렇게 된 이상 나도 목숨 걸고 함께할 수밖에 없겠군!",
          DialogueId = 10036521,
          GUID = "192018BA",
          NextDialogue = 10036522,
          SpeakNpcId = 200021,
