        [10036556] = {
          Camera = "67.970703,-683.014221,202.332031,0.000099,-17.213497,28.039291,35.0,100000.0,false,Manual,22.0",
          ContentKR = "\"...무언의 눈송이, 하늘의 딸이여... 이름 없는 아이를 위해, 기도해 줘요... 눈송이와 춤 추는 그대에게...\"",
          DialogueId = 10036556,
          FinalCamera = "67.970703,-683.014221,202.332031,0.000094,-19.413378,27.838545,35.000008,100000.0,false,Manual,22.0",
          GUID = "19201E78",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036556.T_Story_Recall_10036556'",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036557,
          SnapShot = "MEMORY",
          SpeakNpcId = 100304,
          Subtitle = "\"The silent silent snow, child of the sky... May the nameless child be bathed in good time... Dancing with snowflakes, so light, so great...\"",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100365/19201E78"
        },
        [10036557] = {
          Camera = "129.630859,-634.838989,126.636719,0.000079,7.986567,19.837446,35.000011,100000.0,false,DoNotOverride,22",
          ContentKR = "리듬이 말했었지, 블루스는 그 노래 가사가 싫어서, 자기 마음대로 행복한 결말로 가사를 바꿨다고. 그런데 네가 부른 '얼음 땅 아래, 깊이 잠들었네'라는 건, 원래의 슬픈 결말이겠지.",
          DialogueId = 10036557,
          GUID = "19201EA2",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036558,
          SpeakNpcId = 100001,
          Subtitle = "Rhythm told us Blues didn't like the original lyrics. He rewrote them to give the song a happy ending. But what you sang is different — that's the original, sorrowful version, isn't it?",
          VoiceName = "voice/$Locale$/story/1003/100365/19201EA2"
        },
        [10036558] = {
          Camera = "-53.980469,-733.359253,143.015625,0.000226,5.980021,155.884628,35.000011,160.454437,false,Manual,4.0",
          ContentKR = "......!!",
          DialogueId = 10036558,
          FacialId = {
            [1] = "200021:Shock01"
          },
          GUID = "19201ECC",
          LookAt = {
            [1] = "200021:n(100327)"
          },
          NextDialogue = 10036559,
          SpeakNpcId = 200021,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1003/100365/19201ECC"
        },
        [10036559] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "블루스가 아닌데 연금원의 과거를 그렇게 잘 아는 사람은... 이야기 속 또 다른 개조체밖에 없을거고.",
          DialogueId = 10036559,
          GUID = "19201EF6",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100001)"
          },
          NextDialogue = 10036560,
          SpeakNpcId = 100001,
          Subtitle = "You're not Blues, yet you know everything about what happened in the academy... Then you must be the other protagonist of the story.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201EF6"
        },
        [10036560] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "계속 이해가 안 됐어. 우리가 본 범인은 분명 이성을 잃은 상태였는데, 어떻게 우리한테 그 많은 과거 얘기를 해줄 수 있을 만큼 침착할 수 있었을까?",
          DialogueId = 10036560,
          GUID = "19201F20",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036560.T_Story_Recall_10036560'",
          NextDialogue = 10036561,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "It didn't make sense to me before. The culprit everyone described was a rabid beast. But you're nothing like that. You were calm enough to recount your past with such precision and clarity.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201F20"
        },
        [10036561] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "혹시 넌 진짜 '카론 사냥'을 저지른 사람이 아니라, 그걸 연기하고 있는 거 아닐까?... 뭐, 이건 그냥 추측일 뿐이야. 그런데 네 반응을 보니... 내가 맞춘 것 같네.",
          DialogueId = 10036561,
          GUID = "19201F4A",
          NextDialogue = 10036562,
          SpeakNpcId = 100001,
          Subtitle = "So, could it be... you're not the one who committed the \"Charon Hunt\"? Perhaps you've just been playing that role? It was just a guess, but... your reaction tells me I'm right.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201F4A"
        },
        [10036562] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "너는 연기에 능숙해서 블루스의 모든 행동 하나하나를 완벽히 흉내 낼 수 있어. 네 뛰어난 연기력은 블루스의 유일한 가족인 리듬마저 속였을 정도야.",
          DialogueId = 10036562,
          GUID = "19201F74",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036562.T_Story_Recall_10036562'",
          NextDialogue = 10036563,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "You're such a talented performer. You managed to mimic Blues's every gesture so perfectly that even Rhythm bought it.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201F74"
        },
        [10036563] = {
          Camera = "166.142578,-735.137329,169.679688,0.000134,24.978464,-163.348846,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "네 목에 있는 그 <H>새 상처</>도 일부러 낸 거겠지... 네가 스스로 목을 그어 목소리를 망가뜨린 건, 그 목소리만큼은 완벽하게 흉내 낼 수 없다는 걸 알고 있었기 때문이야...",
          DialogueId = 10036563,
          FinalCamera = "142.306641,-742.268066,181.257812,0.000135,24.978464,-163.348846,35.000008,100000.0,false,Manual,22.0",
          GUID = "19201F9E",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036564,
          SpeakNpcId = 100001,
          Subtitle = "That fresh wound on your throat... it wasn't an accident, was it? You deliberately sliced your throat because you knew... Blues's voice was the one thing you couldn't perfectly replicate.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/19201F9E"
        },
        [10036564] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "하지만 왜? 왜 그렇게까지 해야 했던 거지? 왜 굳이 블루스를 연기해야만 했던 거지? 친구의 죄를 대신 뒤집어쓰고 도망칠 수 있게 도와주려는 거야? 아니면...?",
          DialogueId = 10036564,
          GUID = "19201FC8",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036565,
          SpeakNpcId = 100001,
          Subtitle = "But why? Why go to such lengths? Why pretend to be Blues? Was it to bear his guilt for him, to help your friend escape? Or...",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201FC8"
        },
        [10036565] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "...설마...!",
          DialogueId = 10036565,
          GUID = "19201FF2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036565.T_Story_Recall_10036565'",
          LookAt = {
            [1] = "200021:n(100327)"
          },
          NextDialogue = 10036566,
          SpeakNpcId = 100001,
          Subtitle = "Could it be...!?",
          VoiceName = "voice/$Locale$/story/1003/100365/19201FF2"
        },
        [10036566] = {
          Camera = "98.539062,-775.041443,241.195312,0.0001,-18.813387,168.048386,35.000019,383.519501,false,Manual,6.0",
          ContentKR = "진짜 블루스가, 아직... 살아 있는 거 맞아?",
          DialogueId = 10036566,
          GUID = "1920201C",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "100327:n(200021)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 10036567,
          SpeakNpcId = 200021,
          Subtitle = "The real Blues... is he still alive?",
          VoiceName = "voice/$Locale$/story/1003/100365/1920201C"
        },
        [10036567] = {
          Camera = "228.755859,-562.123291,362.398438,0.000009,-34.213959,-130.736176,35.0,100000.0,false,Manual,22.0",
          ContentKR = "그것까지, 맞추다니...",
          DialogueId = 10036567,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "228.755859,-562.123291,362.398438,0.0,-31.414701,-131.336136,35.0,100000.0,false,Manual,22.0",
          GUID = "19202046",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036568,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "You even... figured that out...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19202046"
        },
        [10036568] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          ContentKR = "그래, 블루스는 이제 없어. 하지만 그는 누나가 자신을 죽였다는 사실을 알게 되길 원하지 않았어...",
          DialogueId = 10036568,
          GUID = "19202070",
          LookAt = {
            [1] = "100327:n(100001)",
            [2] = "100001:n(100327)"
          },
          NextDialogue = 10036569,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "Blues is gone. But he didn't want his sister to ever know who it was... that killed him.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19202070"
        },
        [10036569] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          ContentKR = "넌, 정말 똑똑해. 만약 그때 우리도 너처럼... 됐어, 세상에 '만약' 같은 건 없으니까.",
          DialogueId = 10036569,
          GUID = "1920209A",
          LookAt = {
            [1] = "100001:n(100327)",
            [2] = "100327:n(100001)",
            [3] = "200021:n(100327)"
          },
          NextDialogue = 100365691,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "You're sharp. If only... we'd been... as perceptive back then... Doesn't matter now. Regrets won't... change the past.",
          VoiceName = "voice/$Locale$/story/1003/100365/1920209A"
        },
        [10036570] = {
          ContentKR = "난, 너희를 속였어. 그 이야기에서, 두 사람의 이름을, 바꿔 말했어. 날 구한 건... 블루스야. 그는 다시 한번 나에게 인간으로 태어난다는 게 어떤 느낌인지 알려줬어.",
          DialogueId = 10036570,
          GUID = "192020C4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036570.T_Story_Recall_10036570'",
          NextDialogue = 10036571,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "I... lied to you. In the story, I swapped our names. It was the other way around — Blues was the one... who saved me. He reminded me what it felt like... to be human.",
          VoiceName = "voice/$Locale$/story/1003/100365/192020C4"
        },
        [10036571] = {
          Camera = "279.453125,-473.799011,108.164062,0.000056,14.180913,-120.722359,35.000008,698.253357,false,Manual,4.0",
          ContentKR = "하지만 난 이미, 인간으로서의 자격을 빼앗겼어. 이름이란 건, 그저, 죽어버린 허상일 뿐... 날 그냥 <H>환상</>이라고 불러줘.",
          DialogueId = 10036571,
          GUID = "192020EE",
          NextDialogue = 10036572,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName09",
          Subtitle = "But I lost the right... to call myself human long ago. What's the point... of a name for a ghost of the past...? If a name is required, just call me Phantasio.",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192020EE"
        },
        [10036572] = {
          Camera = "-103.888672,-805.379944,258.925781,0.000151,-21.420866,25.25528,35.000011,436.775146,false,Manual,2.8",
          ContentKR = "월석 사냥꾼, 의뢰다. 리듬을 데리고, 이곳을 벗어나, 그녀를 잘 지켜줘.",
          DialogueId = 10036572,
          GUID = "19202118",
          NextDialogue = 10036573,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"-82.046875,-610.927673,194.027344,0.000118,-26.818573,-136.336395,35.000011,436.775146,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Phoxhunters, here's my commission: Take Rhythm, leave this place, and keep her safe.",
          VoiceName = "voice/$Locale$/story/1003/100365/19202118"
        },
        [10036573] = {
          Camera = "-56.003906,-789.403503,240.355469,0.000146,-20.62079,26.854027,35.000011,427.825653,false,Manual,4.0",
          ContentKR = "그리고, 영원히, 그녀에게, 나라는 사람에 대해, 얘기하지 말아줘.",
          DialogueId = 10036573,
          GUID = "19202142",
          NextDialogue = 10036574,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "And... never ever... tell her about me.",
          VoiceName = "voice/$Locale$/story/1003/100365/19202142"
        },
        [10036574] = {
          Camera = "305.888672,-395.790466,84.648438,3.600263,12.786038,-118.316017,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "...나, {nickname}, 그 의뢰를 받을게. 꼭 지킨다고 약속해. 그리고...",
          DialogueId = 10036574,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "1920216C",
          NextDialogue = 10036575,
          SpeakNpcId = 100001,
          Subtitle = "...I, , accept your commission. I swear I'll see it through. And...",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/1920216C"
        },
        [10036575] = {
          Camera = "53.519531,-654.918152,148.410156,3.600489,-3.414336,17.482788,35.0,100000.0,false,Manual,22.0",
          ContentKR = "환상, 넌 최고의 배우야.",
          DialogueId = 10036575,
          FinalCamera = "83.15625,-645.581787,146.570312,3.600519,-3.414295,17.483107,35.000008,43231.078125,false,DoNotOverride,22",
          GUID = "19202196",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10036576,
          SpeakNpcId = 100001,
          Subtitle = "Phantasio... you are the best performer I've ever seen.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/19202196"
        },
        [10036576] = {
          Camera = "165.486328,-539.479675,106.078125,3.601561,21.381168,-118.114235,35.000011,100000.0,false,Manual,22.0",
          ContentKR = "고, 맙다.",
          DialogueId = 10036576,
          GUID = "192021C0",
          NextDialogue = 10036577,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Thank... you.",
          TalkActionId = {
            [1] = "100327:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192021C0"
        },
        [10036577] = {
          Camera = "451.453125,-616.61145,77.289062,-6.000039,10.974379,-171.489777,25.000006,100000.0,false,Manual,22.0",
          ContentKR = "기회가 있다면, 너의 이야기도 듣고 싶어, <H>너 자신의 이야기</>. 그러니까, 조심해.",
          DialogueId = 10036577,
          GUID = "192021EA",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10036578,
          SpeakNpcId = 100001,
          Subtitle = "One day, if fate allows, I'd like to hear your story. The story of your own life. Until then... take care.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192021EA"
        },
        [10036578] = {
          Camera = "451.453125,-616.61145,77.289062,-6.000039,10.974379,-171.489777,25.000006,100000.0,false,Manual,22.0",
          ContentKR = "......",
          DialogueId = 10036578,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "486.880859,-611.310303,70.351562,-6.000037,10.974379,-171.489777,25.000006,100000.0,false,Manual,22.0",
          GUID = "19202214",
