        [10036585] = {
          Camera = "-339.417969,-183.456543,193.113281,-0.001372,12.567883,-79.534264,11.88,100000.0,false,Manual,22.0",
          ContentKR = "이제 마지막으로 해야 할 일이 하나 남았군.",
          DialogueId = 10036585,
          FinalCamera = "-337.652344,-193.002747,195.265625,-0.001372,12.367846,-79.933975,11.88,100000.0,false,Manual,22.0",
