        [10036806] = {
          Camera = "-2647.710938,-2161.527832,644.511719,0.001361,-86.042442,-139.842682,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "너희들, 이 녀석을, 잡으려고, 날 놔줬어... 영리해, 정말 영리하군.",
          DialogueId = 10036806,
          FinalCamera = "-2658.802734,-2162.93457,557.863281,0.001951,-85.029205,-110.631744,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1920477C",
          LookAt = {
            [1] = "100356:n(100356)"
          },
          NextDialogue = 10036807,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-197.001953,-177.368408,271.332031,0.000062,25.596645,-80.446327,40.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-167.640625,-169.903809,271.332031,0.000068,26.396597,-85.246094,40.0,100000.0,false,DoNotOverride,22.0\"},duration{6}}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "You purposely... let me loose... so that you could... catch this guy. That's quite brilliant.",
          TalkActionId = {
            [1] = "100327:Talk01_End",
            [2] = "100327:Talk01_End",
            [3] = "100330:Die"
          },
          ToFinalCameraBlendTime = 10,
