        },
        [10036807] = {
          Camera = "-204.759766,622.954346,74.933594,0.000039,14.192156,-80.992317,40.000027,2402.064941,false,DoNotOverride,1.614437",
          ContentKR = "그렇게 똑똑한 넌, 분명히, 내가 남긴 단서를, 찾았을 텐데... 그런데, 왜, 말하지 않는 거지?",
          DialogueId = 10036807,
          FinalCamera = "-204.759766,619.0,92.800781,0.000041,13.792146,-81.600647,40.000027,2402.064941,false,DoNotOverride,1.614437",
          GUID = "192047A6",
          NextDialogue = 10036808,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-159.652344,-253.256104,344.800781,0.000028,20.190475,-86.998611,40.000031,2402.064941,false,DoNotOverride,1.614437\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-159.652344,-253.256104,357.800781,0.000028,20.190475,-86.998611,40.000031,2402.064941,false,DoNotOverride,1.614437\"},duration{8}}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "And if you're that brilliant, surely... you've already... noticed the clues I left behind. Why, then? Why haven't you... said anything?",
          TalkActionId = {
            [1] = "100327:Angry01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100368/192047A6"
        },
        [10036808] = {
