          FinalCamera = "-224.714844,-698.029907,511.519531,0.000098,-19.010103,78.794853,40.000034,1104.988525,false,Manual,1.614437",
          GUID = "192047D0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036807.T_Story_Recall_10036807'",
          NextDialogue = 10036809,
