          FacialId = {
            [1] = "100356:Confident01"
          },
          FinalCamera = "-225.720703,-116.229614,288.753906,0.000516,-17.209644,77.720398,35.000008,448.265625,false,DoNotOverride,2.768694",
          GUID = "19204824",
          NextDialogue = 10036811,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-368.511719,1440.334229,42.035156,0.000371,9.190435,-81.658394,35.0,1107.910645,false,DoNotOverride,2.743569\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-310.878906,1448.782227,42.035156,0.000371,9.190435,-83.658127,35.0,1107.910645,false,DoNotOverride,2.743569\"},duration{5}}}",
          SpeakNpcId = 100356,
          Subtitle = "Our target has always been The Forsakens. Nothing else. That is the order we received. Everyone has something they must fulfil.",
          TalkActionId = {
