        [10036903] = {
          Camera = "186.626953,551.218262,-297.511719,0.000243,5.806268,-32.186558,60.0,119.689644,false,Manual,8.0",
          ContentKR = "\"어떻게 해서든 이루고 싶은 목표, 우리는 그걸 흔히 '꿈'이라고 부르지.\"",
          DialogueId = 10036903,
          FacialId = {
            [1] = "100357:Happy01"
          },
          FinalCamera = "186.626953,551.218262,-293.175781,0.000243,5.806268,-32.18647,60.0,119.689644,false,Manual,8.0",
          GUID = "19205766",
          NextDialogue = 10036904,
          SpeakNpcId = 100357,
          Subtitle = "\"Something you'd do anything to fulfil. We usually call it a 'dream.'\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100369/19205766"
        },
        [10036904] = {
          Camera = "340.896484,593.860718,-280.917969,0.000343,-0.415986,-124.291214,50.0,584.186157,false,Manual,8.0",
