          Subtitle = "There's more!? But I'm taking a vacation in—",
          TalkActionId = {
            [1] = "100006:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE04"
        },
        [10037627] = {
          Camera = "-222.233154,-129.037109,109.875,0.00011,3.401168,61.604328,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "조용히 해, 네 휴가는 없어.",
          DialogueId = 10037627,
          FacialId = {
            [1] = "100006:None",
            [2] = "200022:Doubt01"
          },
          FinalCamera = "-230.056396,-124.807373,109.875,0.00011,3.401168,59.004227,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CE2E",
          NextDialogue = 10037628,
          SpeakNpcId = 200022,
          Subtitle = "Shut it. No vacation for you.",
          TalkActionId = {
            [1] = "200022:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE2E"
        },
        [10037628] = {
          Camera = "-826.894287,-529.407959,71.751953,0.000124,2.401009,35.401825,35.000008,938.158691,false,Manual,1.2",
          ContentKR = "2번 타깃의 몸에서 이걸 발견했어. 구겨진 쪽지인데, 위에 온갖 잡다하고 장황한 글자들로 가득해.",
          DialogueId = 10037628,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-817.608398,-544.271484,71.751953,0.000123,2.401009,37.001122,35.000008,938.158691,false,Manual,1.2",
          GUID = "1920CE58",
          NextDialogue = 10037629,
          SpeakNpcId = 200022,
          Subtitle = "We found this slip of paper on Target No. 2. It's all wrinkled, covered in rambling nonsense.",
          TalkActionId = {
            [1] = "200022:Give"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE58"
        },
        [10037629] = {
          Camera = "-136.407715,-217.994629,158.533203,0.000115,-3.999,74.389717,35.000008,938.158691,false,DoNotOverride,1.2",
          ContentKR = "난 이런 잉크냄새 나는 건 잘 모르니까, 네가 좀 연구해 봐. 혹시라도 아직 발견 못 한 암호문 같은 걸지도 모르잖아.",
          DialogueId = 10037629,
          FacialId = {
            [1] = "200022:Syouganai01"
          },
          FinalCamera = "-141.900879,-216.459717,158.533203,0.000116,-3.999,72.789558,35.000008,938.158691,false,DoNotOverride,1.2",
          GUID = "1920CE82",
          NextDialogue = 10037630,
          SpeakNpcId = 200022,
          Subtitle = "These flowery words don't make sense to me. You look into it. Could be a hidden message we've missed.",
          TalkActionId = {
            [1] = "200022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CE82"
        },
        [10037630] = {
          Camera = "-117.756836,88.672852,108.013672,0.000201,6.600804,-84.378052,35.0,938.158691,false,DoNotOverride,1.2",
          ContentKR = "그래, 어디 보자... '무언의 눈송이, 하늘의 딸이여'...",
          DialogueId = 10037630,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-131.584961,87.343506,108.013672,0.000202,6.600804,-81.177704,35.0,938.158691,false,DoNotOverride,1.2",
          GUID = "1920CEAC",
          NextDialogue = 10037631,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-96.188477,-92.051025,148.0,0.000183,0.401035,-92.385239,40.000011,938.158691,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-93.185547,-92.176514,148.0,0.000183,0.201033,-92.385246,40.000011,938.158691,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100006,
          Subtitle = "Fine, let me see... \"The silent silent snow, child of the sky...\"",
          TalkActionId = {
            [1] = "100006:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CEAC"
        },
        [10037631] = {
          Camera = "-155.327637,225.379883,147.050781,0.000117,-3.19924,-74.194122,35.000008,938.158691,false,DoNotOverride,1.2",
          ContentKR = "이건 마치, 어... 시 같은데? 아니면, 무슨 노래 가사인가?",
          DialogueId = 10037631,
          FinalCamera = "-164.984863,223.086426,147.050781,0.000122,-3.19924,-71.59314,35.000008,938.158691,false,DoNotOverride,1.2",
          GUID = "1920CED6",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-737.840088,1471.36792,204.878906,0.000128,-1.998384,-68.190025,35.000008,1775.077148,false,Manual,1.527685\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-791.514893,1605.49646,209.912109,0.000128,-1.998384,-68.190025,35.000008,1775.077148,false,Manual,1.527685\"},duration{5}}}",
          SpeakNpcId = 100006,
          Subtitle = "Huh. Sounds like poetry. Or maybe lyrics to some old song?",
          TalkActionId = {
            [1] = "100006:Talk01_End",
            [2] = "200022:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CED6"
        },
        [10037701] = {
          ContentKR = "무언의 눈송이, 하늘의 딸이여.",
          DialogueId = 10037701,
          GUID = "1920DA52",
          NextDialogue = 10037702,
          Subtitle = "The silent silent snow, child of the sky",
          VoiceName = "voice/$Locale$/story/1003/100377/1920DA52"
        },
        [10037702] = {
          ContentKR = "이름 없는 아이를 위해, 기도해 줘요!",
          DialogueId = 10037702,
          GUID = "1920DA53",
          NextDialogue = 10037703,
          Subtitle = "May the nameless child be bathed in pure light"
        },
        [10037703] = {
          ContentKR = "얼음 땅 아래, 깊이 잠들었네.",
          DialogueId = 10037703,
          GUID = "1920DA54",
          NextDialogue = 10037704,
          Subtitle = "The crystal heart will keep shining through"
        },
        [10037704] = {
          ContentKR = "그의 노래, 그의 모습 기억해 줘요,",
          DialogueId = 10037704,
          GUID = "1920DA55",
          NextDialogue = 10037705,
          Subtitle = "The gentle ballad too, and what we've been through"
        },
        [10037705] = {
          ContentKR = "빛나는 그 맑은 마음까지도.",
          DialogueId = 10037705,
          GUID = "1920DA56",
          NextDialogue = 10037706,
          Subtitle = "Beneath the snowfield you will find your own peace"
        },
        [10037706] = {
          ContentKR = "〈이름 없는 아이에게〉",
          DialogueId = 10037706,
          GUID = "1920DA57",
          Subtitle = "——Requiem for the Nameless"
        },
        [10037801] = {
          ContentKR = "리듬 페실, 안으로 들어가서 내가 벽에 남긴 <H>표시</H>를 찾아, 다음 지시를 기다려.",
          DialogueId = 10037801,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1920EABA",
          NextDialogue = 10037802,
          SpeakNpcId = 100310,
          Subtitle = "Rhythm Fischer, find the carved mark I left on the wall. Then wait for further instructions.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EABA"
        },
        [10037802] = {
          ContentKR = "표시... 표시...",
          DialogueId = 10037802,
          GUID = "1920EAE4",
          NextDialogue = 10037803,
          SpeakNpcId = 200002,
          Subtitle = "Carved mark... Carved mark...",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EAE4"
        },
        [10037803] = {
          ContentKR = "찾았습니다. 저쪽 벽에 칼로 새겨진 표시가 있어요.",
          DialogueId = 10037803,
          GUID = "1920EB0E",
          NextDialogue = 10037804,
          SpeakNpcId = 100304,
          Subtitle = "There it is. A knife mark over there.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB0E"
        },
        [10037804] = {
          ContentKR = "어디 어디?",
          DialogueId = 10037804,
          GUID = "1920EB38",
          SpeakNpcId = 200002,
          Subtitle = "Where is it? Where is it?",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB38"
        },
        [10037805] = {
          ContentKR = "거의 다 도착했습니다. 은색 평화 광장 아래쪽은... 음, 바로 저 앞입니다.",
          DialogueId = 10037805,
          GUID = "1920EB62",
          NextDialogue = 10037806,
          SpeakNpcId = 100304,
          Subtitle = "We should be close... Yeah — that's the tunnel right beneath Silverpeace Square.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB62"
        },
        [10037806] = {
          ContentKR = "저 앞이라구? 근데 길이 다 물에 잠겼는데... 아! 쓰레기통 공주가 <H>밸브</>를 쓰면 된다고 했었어!",
          DialogueId = 10037806,
          GUID = "1920EB8C",
          NextDialogue = 10037807,
          SpeakNpcId = 200002,
          Subtitle = "This is it? But the whole passage is flooded... Oh! Princess Rubbish Bin said something about a water valve!",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EB8C"
        },
        [10037807] = {
          ContentKR = "네, 저쪽에 있는 <H>밸브</>를 가동해서 물을 모두 빼낸 다음 지나가도록 하죠.",
          DialogueId = 10037807,
          GUID = "1920EBB6",
          SpeakNpcId = 100304,
          Subtitle = "Right. Let's activate that valve to drain the water — then we move on.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBB6"
        },
        [10037808] = {
          ContentKR = "필토이드가 있어요, 다들 조심하세요!",
          DialogueId = 10037808,
          GUID = "1920EBE0",
          NextDialogue = 10037809,
          SpeakNpcId = 100304,
          Subtitle = "Filthoids coming. Watch out, everyone.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EBE0"
        },
        [10037809] = {
          ContentKR = "제국이 요즘 지하 시설에 신경을 많이 쓴다며, 어떻게 하수도에서 막대기로 아무렇게나 두드려도 필토이드가 나오는 거야?",
          DialogueId = 10037809,
          GUID = "1920EC0A",
          NextDialogue = 10037810,
          SpeakNpcId = 200021,
          Subtitle = "All that big talk about tightening up the underground facilities, and a quick whack on a sewer pipe is kicking out more Filthoids than wastewater? Wonderful!",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC0A"
        },
        [10037810] = {
          ContentKR = "미안합니다... 퀘스트가 끝나면 하수도 순찰을 강화하도록 하겠습니다...",
          DialogueId = 10037810,
          GUID = "1920EC34",
          NextDialogue = 10037811,
          SpeakNpcId = 100304,
          Subtitle = "Sorry... I'll definitely be stepping up patrol of the sewers in the future...",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC34"
        },
        [10037811] = {
          ContentKR = "아, 당신한테 말하는 건 아니에요... 됐어요, 일단 빨리 저것들부터 처리해요.",
          DialogueId = 10037811,
          GUID = "1920EC5E",
          SpeakNpcId = 200021,
          Subtitle = "...I was not talking about you— Ugh, forget it. Let's deal with these uninvited guests first.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC5E"
        },
        [10037812] = {
          ContentKR = "휴, 됐습니다. 저쪽에 또 다른 밸브가 있어요.",
          DialogueId = 10037812,
          GUID = "1920EC88",
          SpeakNpcId = 100304,
          Subtitle = "Phew, one more valve to go. It's over there.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920EC88"
        },
        [10037813] = {
          ContentKR = "됐어요, 이제 들어가도 될 것 같습니다.",
          DialogueId = 10037813,
          GUID = "1920ECB2",
          SpeakNpcId = 100304,
          Subtitle = "All done. Now we can get in.",
          VoiceName = "voice/$Locale$/story/1003/100378/1920ECB2"
        },
        [10037995] = {
          ContentKR = "녀석들이 우리에게 무슨 짓을 시키든, 이것만은 잊지 마. 우리는, 괴물이 아니다.",
          DialogueId = 10037995,
          GUID = "19210B11",
          SpeakNpcId = 100328,
          Subtitle = "Whatever they demand of us... remember this: we are not monsters.",
          VoiceName = "voice/$Locale$/story/1003/100379/19210B11"
        },
        [10037996] = {
          ContentKR = "클레이프는 바람 나루터 근처에 있어요. 그쪽으로 가서 찾아보세요.",
          DialogueId = 10037996,
          GUID = "19210B10",
          SpeakNpcId = 200022,
          Subtitle = "Clive should be near Windwake Pier. Head that way — you'll find him.",
          VoiceName = "voice/$Locale$/story/1003/100379/19210B10"
        },
        [10037997] = {
          ContentKR = "종이랑 펜은 제가 의사 선생님께 부탁드려 볼 테니까, 도장은 여러분께 부탁할게요. 미안해요... 다쳐 버리는 바람에 모두에게 폐를 끼치게 됐네요.",
          DialogueId = 10037997,
          GUID = "19210B0G",
          SpeakNpcId = 100304,
          Subtitle = "I asked the doctor for a pen and some paper — could you fetch the seal for me? Apologies... this injury's turned me into a burden.",
          VoiceName = "voice/$Locale$/story/1003/100379/19210B0G"
        },
        [10037998] = {
          DialogueId = 10037998,
          FinalCamera = "2935.045898,2450.00293,654.427734,0.000057,-7.99936,-141.003235,35.0,100000.0,false,Manual,22.0",
          GUID = "19210B0C",
          Scripts = [[
