        },
        [10038001] = {
          ContentKR = "장교님들... 조심하세요...",
          DialogueId = 10038001,
          GUID = "191DEA43",
          NextDialogue = 10038002,
          SpeakNpcId = 100322,
          Subtitle = "Watch out... Officers...",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA43"
        },
        [10038002] = {
          ContentKR = "자식들이 또 왔구나, 정말 잠시도 쉴 틈이 없네.",
          DialogueId = 10038002,
          GUID = "191DEA44",
          SpeakNpcId = 200021,
          Subtitle = "Here they come again. Ugh, can't even catch a breath with these pests.",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA44"
        },
        [10038004] = {
          ContentKR = "이것도요!",
          DialogueId = 10038004,
          GUID = "191DEA46",
          SpeakNpcId = 100304,
          Subtitle = "Alright, next one",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA46"
        },
        [10038006] = {
          ContentKR = "우와... 너무 어려워... 스노우는 너무 힘들어. 시종, 이제 네가 좀 해줘...",
          DialogueId = 10038006,
          GUID = "191DEA48",
          SpeakNpcId = 200002,
          Subtitle = "Ugh, this water valve's stuck like a rock... Little Minion, I'll leave it to you to prove your strength...",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA48"
        },
        [10038007] = {
          ContentKR = "마지막인 것 같습니다.",
          DialogueId = 10038007,
          GUID = "191DEA49",
          NextDialogue = 10038008,
          SpeakNpcId = 100304,
          Subtitle = "Looks like this is the last one.",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA49"
        },
        [10038008] = {
          ContentKR = "야호... 드디어 다 끝낼 수 있겠어!",
          DialogueId = 10038008,
          GUID = "191DEA4A",
          SpeakNpcId = 200002,
          Subtitle = "Hooray... Finally!",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA4A"
        },
        [10038009] = {
          ContentKR = "컨트롤러 스테이션이 다시 작동합니다. 이걸로 방위 장치를 멈추죠.",
          DialogueId = 10038009,
          GUID = "191DEA4B",
          SpeakNpcId = 100304,
          Subtitle = "The control panel is back online. Use it to shut down the defense system.",
          VoiceName = "voice/$Locale$/story/1003/100380/191DEA4B"
        },
        [10038012] = {
          ContentKR = "마일스, 탄창 두 개나 더 가져와! 야, 안 들려? 쯧... 통신기 또 고장인가?",
          DialogueId = 10038012,
          GUID = "191EF0C3",
          NextDialogue = 10038013,
          SpeakNpcId = 100340,
          Subtitle = "Miles, get me two more mags! ...Do you copy!? Ugh... Is this comms on the blink again?",
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C3"
        },
        [10038013] = {
          ContentKR = "음? 너희구나.",
          DialogueId = 10038013,
          GUID = "191EF0C4",
          NextDialogue = 10038014,
          SpeakNpcId = 100340,
          Subtitle = "Oh, it's you.",
          TurnTo = {
            [1] = "100341:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C4"
        },
        [10038014] = {
          ContentKR = "너희 작전 지역은 앞쪽이잖아? 어서 가라. 이번 작전에는 조금의 실수도 용납되지 않는다니까.",
          DialogueId = 10038014,
          GUID = "191EF0C5",
          NextDialogue = 10038015,
          SpeakNpcId = 100340,
          Subtitle = "Isn't your AO up front? Move on, this mission allows for zero slip-ups.",
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C5"
        },
        [10038015] = {
          ContentKR = "알겠습니다.",
          DialogueId = 10038015,
          GUID = "191EF0C6",
          SpeakNpcId = 100304,
          Subtitle = "Yes, sir.",
          VoiceName = "voice/$Locale$/story/1003/100380/191EF0C6"
        },
        [10038101] = {
          ContentKR = "아이스레이크 시티는 현재 통행금지 시간입니다. 이곳을 지날 수 없습니다.",
          DialogueId = 10038101,
          GUID = "19210B0D",
          Subtitle = "Access is prohibited during Icelake's curfew hours."
        },
        [10038102] = {
          ContentKR = "하수도의 방위 장치가 작동한 것 같습니다. 도움이 될 거예요.",
          DialogueId = 10038102,
          GUID = "191DE875",
          NextDialogue = 10038103,
          SpeakNpcId = 100304,
          Subtitle = "The sewer defense system is also activated. It may help.",
          VoiceName = "voice/$Locale$/story/1003/100381/191DE875"
        },
        [10038103] = {
          ContentKR = "근데... 하수도에 왜 방위 장치가 있어요!",
          DialogueId = 10038103,
          GUID = "191DE876",
          NextDialogue = 10038104,
          SpeakNpcId = 200021,
          Subtitle = "There is a defense system at a place like this!?",
          VoiceName = "voice/$Locale$/story/1003/100381/191DE876"
        },
        [10038104] = {
          ContentKR = "여기에 있는 장치 대부분은 공학 연금원이 설치한 것이에요. 캐묻지 말라고 하길래, 저도 자세히는 잘 모릅니다.",
          DialogueId = 10038104,
          GUID = "191DE877",
          NextDialogue = 10038105,
          SpeakNpcId = 100304,
          Subtitle = "Yes. Most devices in the sewers are installed by The Aeolipile Academy, but they just warned us not to pry.",
          VoiceName = "voice/$Locale$/story/1003/100381/191DE877"
        },
        [10038105] = {
          ContentKR = "하수도에서 군사 장치를... 도대체 무슨 속셈이 있는 거야...",
          DialogueId = 10038105,
          GUID = "191DE878",
          SpeakNpcId = 200021,
          Subtitle = "They rigged the sewers with military equipment... What are they up to...",
          VoiceName = "voice/$Locale$/story/1003/100381/191DE878"
        },
        [10038201] = {
          DialogueId = 10038201,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "19210B0E",
          NextOptions = {
            [1] = 10038202
          }
        },
        [10038202] = {
          ContentKR = "군단 병원에 들어가기",
          DialogueId = 10038202,
          GUID = "19210B0F",
          Subtitle = "Enter the Legion Medical Centre"
        },
        [10038301] = {
          Camera = "-352.324951,420.12915,199.878906,0.000157,-10.802886,-58.593517,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "아이고, 네가 많이 다쳤다고 해서 특별히 위로하러 왔잖아.",
          DialogueId = 10038301,
          FinalCamera = "-377.254883,404.907959,199.878906,0.000155,-10.602905,-55.19278,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA15",
          NextDialogue = 10038302,
          SpeakNpcId = 100006,
          Subtitle = "Oh come on, I heard you were badly hurt and came to offer my regards.",
          TalkActionId = {
            [1] = "100006:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100383/1920CA15"
        },
        [10038302] = {
          Camera = "-158.971191,-46.777344,212.847656,0.000162,-24.602238,66.810852,55.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "됐어. 안 죽었으면 문제없는 거지. 난 너 같은 약골 도련님이 아니니까.",
          DialogueId = 10038302,
          FacialId = {
            [1] = "200022:Confident01"
          },
          FinalCamera = "-152.550293,-49.527588,212.847656,0.000171,-24.402216,70.010948,55.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA16",
          NextDialogue = 10037603,
          SpeakNpcId = 200022,
          Subtitle = "Save it. I'm good as long as I'm still breathing. I'm not some coddled rich child like you.",
          TalkActionId = {
            [1] = "200022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100383/1920CA16"
        },
        [10038401] = {
          ContentKR = "그러고 나서, 카론들은 휘페르보레아 제국 전역에 전쟁의 불씨를 지피고, 곳곳에서 살육을 저질렀어. 제국의 창건자이자 자비로우신 디스 갈레아 폐하께서 전쟁을 종식시키고, 평화를 가져오시기 전까지는 말이야.",
          DialogueId = 10038401,
          GUID = "191E6E2B",
          NextDialogue = 10033922,
          SpeakNpcId = 100357,
          Subtitle = "After that, the Charons started a war across Hyperborea, killing anyone they saw — until His Majesty Dis Galea, the merciful founder of the Empire, ended the bloodshed and restored peace.",
          VoiceName = "voice/$Locale$/story/1003/100339/191E6E2B"
        },
        [10100101] = {
          ContentKR = "...이봐... 이봐!!!",
          DialogueId = 10100101,
          Duration = 3.5,
          GUID = "1948D7D2",
          SpeakNpcId = 200002,
          Subtitle = "...Hello? ...Hello—",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D7D2"
        },
        [10100102] = {
          ContentKR = "내——말——들——려——?",
          DialogueId = 10100102,
          Duration = 7,
          GUID = "1948D7FC",
          SpeakNpcId = 200002,
          Subtitle = "Can— you— hear— me—",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D7FC"
        },
        [10100103] = {
          ContentKR = "<H>카밀라</>, 봐봐, {nickname}이(가) 깼어, 깼다고!",
          DialogueId = 10100103,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1948D826",
          SpeakNpcId = 200002,
          Subtitle = "Camilla, look!  has woken up!",
          VoiceName = "voice/$Locale$/story/1002/101001/1948D826"
        },
        [10100201] = {
          Camera = "-196.878906,-289.845947,119.943359,0.001203,-1.699679,54.031475,35.0,450.0,false,Manual,4.0",
          ContentKR = "그러게, 살아있네. 움직이는 데도 문제없어 보이고, 뼈도 딱히 부러진 곳은 없어 보이고.",
          DialogueId = 10100201,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1948D850",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200003:n(100001)"
          },
          NextDialogue = 10100202,
          RelatedWikiId = {
            [1] = 201001,
            [2] = 408001,
            [3] = 201002
          },
          SpeakNpcId = 200003,
          Subtitle = "Mmm. Alive and not incapacitated, no broken bones then.",
          TalkActionId = {
