        },
        [10100203] = {
          Camera = "-22.90625,-45.071777,149.469238,0.001231,-17.499626,-66.962013,35.0,60.930546,false,Manual,4.493256",
          ContentKR = "아냐, 그때 우리는...",
          DialogueId = 10100203,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "1949781C",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10100204,
