CameraMoveTo{_delay{2},TargetPosition{"-29.773438,54.472656,127.289062,0.00116,-1.800137,-76.755142,35.000008,157.238007,false,Manual,4.0"},duration{0.4}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Hyperborea... I'm in the Hyperborean Empire...?!",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E960"
        },
        [10100210] = {
          Camera = "4915.476562,-702.842285,1756.620605,0.000003,25.494759,-14.000834,12.000003,3073.631592,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "응, 휘페르보레아 제국. 뭘 그렇게 놀라고 그래?",
          DialogueId = 10100210,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "4915.476562,-702.842285,1756.620605,0.000003,30.894625,-20.001587,12.000003,3073.631592,false,Manual,1.2",
          GUID = "1948E98A",
