        [10100616] = {
          Camera = "-365.87207,335.160156,119.696777,0.001258,-1.199463,-44.99984,35.000008,640.0,false,Manual,10.0",
          ContentKR = "좋습니다. 당신 사람이면 문제없겠죠. 하지만 명심해요, 절대 시티 내에서 사고 치지 않게 잘 단속해요. 윗분들이 알면 우리 둘 다 골치 아파진다고요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100616,
          ExStoryInfo = "Player",
          GUID = "19492C50",
          NextDialogue = 10100617,
