          SpeakNpcId = 200006,
          Subtitle = "Are you sad?",
          VoiceName = "voice/$Locale$/story/1002/101018/1949F034"
        },
        [10101811] = {
          ContentKR = "...응?",
          DialogueId = 10101811,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1949F05E",
          NextDialogue = 10101812,
          SpeakNpcId = 100001,
          Subtitle = "...Hmm? Why?",
          VoiceName = "voice/$Locale$/story/1002/101018/1949F05E"
        },
        [10101812] = {
          Camera = "124.00592,396.694336,136.049347,0.001243,0.09998,-101.200462,60.000011,283.596039,false,Manual,8.429013",
          ContentKR = "느껴져. 억지로 웃고 있지만 즐겁지 않잖아.",
          DialogueId = 10101812,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "1949F088",
          NextDialogue = 10101813,
          SpeakNpcId = 200006,
          Subtitle = "I can feel it. Even though you're trying to put on a smile, you're not happy.",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949F088"
        },
        [10101813] = {
          ContentKR = "무슨 일인지 궁금하긴 하지만 헨릭 아저씨가 손님 과거는 캐묻는 게 아니라고 했어.",
          DialogueId = 10101813,
          FacialId = {
            [1] = "200006:Ahaha02"
          },
          GUID = "1949F0B2",
          NextDialogue = 10101814,
          Scripts = "PlayAnimation{_delay{3},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 200006,
          Subtitle = "I'm a bit curious about what you've been through, but Mr Henrik told me not to pry into our guests' pasts.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949F0B2"
        },
        [10101814] = {
          Camera = "387.223511,-833.958069,515.231628,0.000029,-22.073723,106.174774,35.0,1079.091919,false,Manual,1.2",
          ContentKR = "음... 일단 여기서 쉬면서 앞으로 뭘 할지 생각해 봐.",
          DialogueId = 10101814,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "423.065491,-957.536621,567.4104,0.000029,-22.073723,106.174774,35.0,1325.286621,false,Manual,1.2",
          GUID = "1949F0DC",
          NextDialogue = 10101815,
          Scripts = "PlayAnimation{_delay{2},ActorId{200006},AnimationId{\"Talk02_Start\"},Duration{2}}",
          SpeakNpcId = 200006,
          Subtitle = "Anyway... you can take a good rest here, and think about what to do next.",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101018/1949F0DC"
        },
        [10101815] = {
          ContentKR = "응.",
          DialogueId = 10101815,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "1949F106",
          SpeakNpcId = 100001,
          Subtitle = "Thank you.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101018/1949F106"
        },
        [10101901] = {
          Camera = "-48.44191,-84.550293,158.135422,0.00125,-12.40057,63.821815,25.0,187.769821,false,Manual,4.0",
          ContentKR = "프시케, 물어보고 싶은 게 있어.",
          DialogueId = 10101901,
          ExStoryInfo = "Player",
          GUID = "1949FF22",
          LookAt = {
            [1] = "100001:n(200006)",
            [2] = "200006:n(100001)"
          },
          NextDialogue = 10101902,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 405001,
            [4] = 201007
          },
          SpeakNpcId = 100001,
          Subtitle = "Psyche, I need to ask you something.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/1949FF22"
        },
        [10101902] = {
          ContentKR = "돈이 좀 필요한데 이 도시에서 외지인에게 일자리를 줄 만한 곳이 있을까? 내 말은, 신분을 묻지 않는 곳이랄까?",
          DialogueId = 10101902,
          ExStoryInfo = "Player",
          GUID = "1949FF4C",
          NextDialogue = 10101903,
          SpeakNpcId = 100001,
          Subtitle = "I need some money. Is there any place in the city where an outsider might find work without too many questions asked about their past?",
          VoiceName = "voice/$Locale$/story/1002/101019/1949FF4C"
        },
        [10101903] = {
          Camera = "-38.717148,121.221191,133.893906,0.001216,0.400071,-64.497734,33.0,151.507431,false,Manual,6.0",
          ContentKR = "음...",
          DialogueId = 10101903,
          FacialId = {
            [1] = "200006:Sad01"
          },
          GUID = "1949FF76",
          NextDialogue = 10101904,
          SpeakNpcId = 200006,
          Subtitle = "Let me see...",
          TalkActionId = {
            [1] = "200006:Think_Start",
            [2] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/1949FF76"
        },
        [10101904] = {
          Camera = "-38.717148,121.221191,133.893906,0.001216,0.400071,-64.497734,33.0,151.507431,false,Manual,6.0",
          ContentKR = "여긴 대부분이 공장에서 일하는데... 아냐, 모든 공장은 통행증이 필수야... 음, 정 안되면 거기는 어때?",
          DialogueId = 10101904,
          GUID = "1949FFA0",
          NextDialogue = 10101905,
          SpeakNpcId = 200006,
          Subtitle = "Most people here work in the factories... Um, but they all ask to see a travel permit... Well, there's perhaps one place you could try—",
          VoiceName = "voice/$Locale$/story/1002/101019/1949FFA0"
        },
        [10101905] = {
          Camera = "-38.717148,121.221191,133.893906,0.001216,0.400071,-64.497734,33.0,151.507431,false,Manual,6.0",
          ContentKR = "카밀라 스칼렛 씨의 주점 '<H>아스포델</>'말이야. 거긴 의뢰를 받아서 완료하면 사례금을 받을 수 있어.",
          DialogueId = 10101905,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "1949FFCA",
          NextDialogue = 10101906,
          RelatedWikiId = {
            [1] = 405003,
            [2] = 201004
          },
          SpeakNpcId = 200006,
          Subtitle = "Ms Camilla Scarlet's tavern, The Asphodel. You can take up commissions with handsome rewards there.",
          TalkActionId = {
            [1] = "200006:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/1949FFCA"
        },
        [10101906] = {
          ContentKR = "하지만 대부분 의뢰가 위험해. 방위대도 꺼리는 곳에 갔다가 거기에 있던 필토이드라도 만난다면...",
          DialogueId = 10101906,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "-90.181519,24.020996,149.167328,0.0012,-2.49905,-14.966633,40.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1949FFF4",
          NextDialogue = 10101907,
          RelatedWikiId = {
            [1] = 101006
          },
          SpeakNpcId = 200006,
          Subtitle = "But, those commissions are often quite dangerous... You might have to go to places even the local Escort would avoid, and you might encounter some wandering Filthoids...",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101019/1949FFF4"
        },
        [10101907] = {
          Camera = "-48.44191,-84.550293,158.135422,0.00125,-12.40057,63.821815,25.0,187.769821,false,Manual,4.0",
          ContentKR = "카밀라 스칼렛 씨? 나도 만난 적 있어. 술집도 운영하는구나.",
          DialogueId = 10101907,
          ExStoryInfo = "Player",
          GUID = "194A001E",
          NextDialogue = 10101908,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.1},ActorId{100001},AnimationId{"Explain02_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Camilla Scarlet? I met her today. Though I had no idea that her tavern also runs this sort of business.",
          VoiceName = "voice/$Locale$/story/1002/101019/194A001E"
        },
        [10101908] = {
          Camera = "-0.864502,1.519531,134.328049,0.001223,3.799798,92.402924,35.000011,82.431984,false,Manual,4.0",
          ContentKR = "괜찮아, 할 수 있으니 데려다 줘.",
          DialogueId = 10101908,
          ExStoryInfo = "Player",
          GUID = "194A0048",
          SpeakNpcId = 100001,
          Subtitle = "It's okay, I can handle it. Can you take me there?",
          TalkActionId = {
            [1] = "100001:DisagreeHead",
            [2] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101019/194A0048"
        },
        [10102001] = {
          ContentKR = "어라, 결국은 카밀라를 찾아가기로 한 거야?",
          DialogueId = 10102001,
          GUID = "194A0F8A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10102002,
          SpeakNpcId = 200002,
          Subtitle = "Huh? After all this running around, you're going back to Camilla?",
          VoiceName = "voice/$Locale$/story/1002/101020/194A0F8A"
        },
        [10102002] = {
          ContentKR = "그럼 이 스노우가 제격이지, 스노우가 데려가 줄게!",
          DialogueId = 10102002,
          GUID = "194A0FB4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Then count Snow in! Snow's more than familiar with that place.",
          VoiceName = "voice/$Locale$/story/1002/101020/194A0FB4"
        },
        [10102101] = {
          Camera = "144.795166,-59.822609,177.998291,0.000184,-10.995027,-161.813614,35.000008,336.056366,false,Manual,3.399312",
          ContentKR = "통행증...",
          DialogueId = 10102101,
          GUID = "194A1FF2",
          NextDialogue = 10102102,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 201007,
            [4] = 201005,
            [5] = 101006
          },
          SpeakNpcId = 200008,
          Subtitle = "Your travel permit...",
          VoiceName = "voice/$Locale$/story/1002/101021/194A1FF2"
        },
        [10102102] = {
          Camera = "33.546387,-153.258987,93.952881,0.000002,16.403095,174.174957,38.839455,184.656097,false,Manual,2.8",
          ContentKR = "귀가 먹었나? 어서... 통행증을 내놓으란 말이다!",
          DialogueId = 10102102,
          FinalCamera = "-0.705322,-149.764832,97.867188,0.000001,18.403158,174.174957,38.839455,152.921875,false,Manual,2.8",
          GUID = "194A201C",
          NextDialogue = 10102103,
          SpeakNpcId = 200008,
          Subtitle = "Are you deaf? Show me your... travel permit!",
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/1002/101021/194A201C"
        },
        [10102103] = {
          Camera = "-158.199463,-84.212631,168.010742,0.000248,-21.796566,-50.423859,15.255159,136.628647,false,Manual,3.557573",
          ContentKR = "나리, 제가 느려서 그러니 조금만 기다려 주십시오. 찾고 있습니다, 지금...",
          DialogueId = 10102103,
          GUID = "194A2046",
          NextDialogue = 10102104,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{200009},AnimationId{"Agree"},Duration{2}},
PlayAnimation{_delay{7},ActorId{200009},AnimationId{"Agree"},Duration{2}}
}]],
          SpeakNpcId = 200009,
          Subtitle = "Sorry, sir, I'm a bit slow at this age, please bear with me for a moment...",
          TalkActionId = {
            [1] = "200009:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/101021/194A2046"
        },
        [10102104] = {
