          VoiceName = "voice/$Locale$/story/1002/101021/194A209A"
        },
        [10102106] = {
          ContentKR = "예, 나리...",
          DialogueId = 10102106,
          GUID = "194A20C4",
          NextDialogue = 10102107,
          SpeakNpcId = 200009,
          Subtitle = "Yes, sir...",
