          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "아무리 봐도 개처럼 보인단 말이지, 하하, 으하하하하!",
          DialogueId = 10102107,
          FinalCamera = "-324.333984,818.858521,836.514404,-5.000005,-35.792892,-76.391212,40.168049,228.342102,false,DoNotOverride,6.685584",
          GUID = "194A20EE",
          NextDialogue = 10102108,
          SpeakNpcId = 200008,
          Subtitle = "How come it looks more like a mongrel to me, haha, hahaha!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101021/194A20EE"
        },
        [10102108] = {
