}]],
          SpeakNpcId = 200006,
          Subtitle = "...I'm here with a friend. {性别:He|She} is looking for a job and wants to become a Phoxhunter.",
          TalkActionId = {
            [1] = "200006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 6,
