        },
        [10102605] = {
          Camera = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
          ContentKR = "월석 사냥꾼이라고요? 그럼 제대로 찾아왔어요. 마침 의뢰가 하나 있거든요!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10102605,
