          VoiceName = "voice/$Locale$/story/1002/101040/194B57FE"
        },
        [10104004] = {
          Camera = "-751.572632,-799.925781,445.150391,0.001331,-15.60022,38.201538,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "말 나온 김에 이 친구한테도 현재 상황을 알려 줘야지. 솔직히 말해서 요즘 우리 상황이 그다지 좋지 않아. 조금이라도 돈 되는 의뢰는 다 낚아채야 해.",
          DialogueId = 10104004,
          ExStoryInfo = "Player",
          FinalCamera = "-771.009277,-775.231445,445.150391,0.001331,-15.60022,38.201538,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194B5828",
          LookAt = {
            [1] = "200065:n(100001)",
            [2] = "100001:n(200065)",
            [3] = "200006:n(200065)"
          },
          NextDialogue = 10104005,
          Scripts = [[
