PlayAnimation{_delay{5},ActorId{200065},AnimationId{"Disagree"},Duration{4.1}},
PlayAnimation{_delay{7},ActorId{200065},AnimationId{"Sigh_Start"},Duration{1}}
}]],
          SpeakNpcId = 200065,
          Subtitle = "Oh, and I can also catch {性别:him|her} up on our line of work. To be honest, it's been pretty tough lately, any commission worth a jot has to be fought for.",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5828"
        },
        [10104005] = {
          Camera = "1019.142822,-738.232422,198.009766,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "방금 오늘 의뢰를 봤는데, 죄다 돈도 안 되는 작은 일들뿐이야. '그 일' 말고는...",
          DialogueId = 10104005,
          FinalCamera = "1021.591187,-674.18457,195.511719,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194B5852",
          LookAt = {
            [1] = "100001:n(200065)"
          },
          NextOptions = {
            [1] = 101040051
          },
          SpeakNpcId = 200065,
          Subtitle = "I just had a gander at today's jobs, and they're all thankless. Except for that hot potato...",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5852"
        },
        [10104006] = {
          Camera = "206.755127,354.53418,169.501953,0.000076,-7.199996,-92.795441,30.000002,292.884125,false,Manual,2.0",
          ContentKR = "무슨 이상한 돌을 찾는 귀찮은 의뢰야... 하아, 말해봐야 소용없어. 우리 같은 베테랑도 받지 않는 일이거든. 이제 막 시작한 네가 뭘 할 수 있겠어.",
          DialogueId = 10104006,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194B587C",
          LookAt = {
            [1] = "200003:n(100001)",
            [2] = "200002:n(200065)"
          },
          NextOptions = {
            [1] = 101040061
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200065},AnimationId{"Sigh_End"},Duration{2.2}},
