PlayAnimation{ActorId{200065},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200065,
          Subtitle = "A right bother of a job, finding some daft stone — eh, no point in telling you, even us old hands don't dare touch it, let alone a newbie like you.",
          VoiceName = "voice/$Locale$/story/1002/101040/194B587C"
        },
        [10104007] = {
          Camera = "-60.295044,-143.261719,150.679688,0.001294,-1.100057,41.202648,65.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "글로스터 폐광으로 가서 <H>'반짝이는 수정'</>이라는 희귀한 광석을 찾는 거야. <H>헨릭 애설레드</>가 의뢰한 건이야. 아, 네가 만난 그 헨릭말이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104007,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "194B58A6",
          NextDialogue = 10104008,
          RelatedWikiId = {
            [1] = 301004
          },
          Scripts = [[
