          SpeakNpcId = 200065,
          Subtitle = "Phoxhunters are born adventurers, but we're not reckless fools! The stone's very existence aside... Who knows if Henrik can even cough up the cash?",
          VoiceName = "voice/$Locale$/story/1002/101040/194B5924"
        },
        [10104011] = {
