        },
        [10104022] = {
          ContentKR = "반짝이는 수정은 <H>남보라색</> 결정체인데, 안에 성운이 흐르는 것처럼 보여서 어두운 광갱 안에서 쉽게 알아볼 수 있을 거야.",
          DialogueId = 10104022,
          GUID = "194B5A9F",
          NextDialogue = 10104020,
          SpeakNpcId = 200003,
          Subtitle = "Crystallo of Stella is a blue-violet crystal that appears as if nebulae are swirling within it. In the dim mine pit, it is particularly eye-catching — you won't miss it.",
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A9F"
        },
        [10104101] = {
          ContentKR = " ...반짝이는 수정... 헨릭 아저씨...",
          DialogueId = 10104101,
          GUID = "194B6812",
          SpeakNpcId = 200006,
          Subtitle = "...Crystallo of Stella... Mr Henrik...",
          VoiceName = "voice/$Locale$/story/1002/101041/194B6812"
        },
        [10104201] = {
          ContentKR = "조심해야 해, {性别:청년|아가씨}. 일이 잘못되면 뒤도 돌아보지 말고 도망가.",
          DialogueId = 10104201,
          ExStoryInfo = "Player",
          GUID = "194B787A",
          SpeakNpcId = 200015,
          Subtitle = "Don't try to be a hero, kid. Run for your life if things get dicey.",
          VoiceName = "voice/$Locale$/story/1002/101042/194B787A"
        },
        [10104301] = {
          ContentKR = "아스포델에선 술 말고도 아주, 아주 많은 것들을 살 수 있어... 물론 네가, 충분한 대가를 치를 수 있어야겠지.",
          DialogueId = 10104301,
          GUID = "194B88E2",
          NextOptions = {
            [1] = 101043011,
            [2] = 101043051,
            [3] = 101043091,
            [4] = 101043112
          },
          SpeakNpcId = 200003,
          Subtitle = "The Asphodel offer more than just libations... much more. All for a price, naturally.",
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_02"
        },
        [10104302] = {
          ContentKR = "어디서부터 얘기하면 좋을까... 음, 역사가 길거든. 우선 여긴 800년 전 '대이동' 이후에 제국 초대 황제가 세운 초기 도시 중 하나야.",
          DialogueId = 10104302,
          GUID = "194B890C",
          NextDialogue = 10104303,
          SpeakNpcId = 200003,
          Subtitle = "Where to begin... Well, it's got a long history. Built by the Empire's first ruler after the Great Migration 800 years ago, it's among the first few cities of the empire.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B890C"
        },
        [10104303] = {
          ContentKR = "여긴 제국에서 가장 북쪽에 있는 대도시이기도 해. 북쪽으로 100km 정도 더 가서 베드르폴니르 산맥을 넘으면 바로 아스카드 국경이거든.",
          DialogueId = 10104303,
          GUID = "194B8936",
          NextDialogue = 10104304,
          SpeakNpcId = 200003,
          Subtitle = "It's also the northernmost major city of the Empire. Just over a hundred kilometres further north, past the Vidofnir Mountains, and you're on Askard's turf.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8936"
        },
        [10104304] = {
          ContentKR = "아이스레이크 시티는 예전에 월석 산지로 유명했어. 수십 년 전까지만 해도 글로스터 광갱이 휘페르보레아 제국에서 손에 꼽힐 정도로 큰 월석 광산이었지만 지금은 광맥이 고갈돼서 당시 있던 공장만 겨우 돌아가는 정도야.",
          DialogueId = 10104304,
          GUID = "194B8960",
          NextDialogue = 10104305,
          SpeakNpcId = 200003,
          Subtitle = "Icelake used to be known for its Phoxene veins. Take Glevum Pit for example — one of Hyperborea's largest Phoxene mines back in the day. But now, the veins are spent, only the old factories are barely chugging along.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8960"
        },
        [10104305] = {
          ContentKR = "뭐, 이런 건 책에서도 볼 수 있고 누구라도 말해줄 수 있는 내용이야. 내 생각엔 네가 직접 눈으로 보고 귀로 들어보는 게 좋겠어. 이 도시의 두터운 눈 아래 뭐가 숨겨져 있는지 말이지.",
          DialogueId = 10104305,
          GUID = "194B898A",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "But then, this is all stuff you can read about in books, things anyone could tell you. I'd suggest you look with your own eyes and listen with your heart, to find out what truly lurks beneath this city's snow and ice.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B898A"
        },
        [10104306] = {
          ContentKR = "떠들기 좋아하고 트집 잡기 좋아하는 시끄러운 녀석들이지. 누군가는 생계 때문에 의뢰를 받고, 또 누군가는 그냥 사고 치고 모험하는 걸 좋아해서 한다는데, 공통점이라면 자주 다친다는 거야.",
          DialogueId = 10104306,
          GUID = "194B89B4",
          NextDialogue = 10104307,
          SpeakNpcId = 200003,
          Subtitle = "A bunch of cheap, noisy blighters keen on spinning yarns. Some of them became Phoxhunters to eke a living, some just fancy a bit of ruckus and adventure. One thing they have in common is they often end up more battered and bruised than not.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B89B4"
        },
        [10104307] = {
          ContentKR = "솔직히 말하면 다 쫓아내서 추위에 떨게 만들어 버리고 싶을 때가 많아.",
          DialogueId = 10104307,
          GUID = "194B89DE",
          NextDialogue = 10104308,
          SpeakNpcId = 200003,
          Subtitle = "Truth be told, I've often wanted to give them the boot, let them munch on dirty snow and gulp the north wind outside.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B89DE"
        },
        [10104308] = {
          ContentKR = "근데 사실 걔들이 치안서가 해야 할 일도 많이 하고 있거든. 또 걔들 아니면 이 도시에서 한잔하려고 아스포델에 올 사람도 얼마 없을 걸.",
          DialogueId = 10104308,
          GUID = "194B8A08",
          NextDialogue = 10104309,
          SpeakNpcId = 200003,
          Subtitle = "But then, they do manage a fair bit that ought to be the Security Bureau's job. Without them, likely not many in this city would have the luxury to kick back in my tavern.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A08"
        },
        [10104309] = {
          ContentKR = "그래서 모이게 내버려 두는 거지. 서로 이득도 보는 거고. 뭐, 가끔은 좀 작게 말하고 싸움도 덜 했으면 좋겠지만.",
          DialogueId = 10104309,
          GUID = "194B8A32",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "So I let them gather and natter here, a bit of quid pro quo. Still, I do wish they'd keep it down a little and get into fewer brawls.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A32"
        },
        [10104310] = {
          ContentKR = "멋대로 여자의 비밀을 묻는 게 얼마나 실례인지 아무도 말 안 해줬던 거야?",
          DialogueId = 10104310,
          GUID = "194B8A5C",
          NextDialogue = 10104311,
          SpeakNpcId = 200003,
          Subtitle = "Hasn't anyone told you it's rather rude to pry into a lady's secrets for no reason?",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A5C"
        },
        [10104311] = {
          ContentKR = "뭐, 듣고 싶으면 얼마든지 말해줄 수 있는데. 충분한 값어치를 할 만한 대가를 준비할 수 있다면 말이야... 후훗.",
          DialogueId = 10104311,
          GUID = "194B8A86",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "Of course, I can share my stories with you — provided you can pay the right price... hehe.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A86"
        },
        [10104401] = {
          Camera = "937.774414,-120.576172,119.04834,0.000012,-1.999695,166.391983,35.0,762.45813,false,Manual,1.6",
          ContentKR = "잠깐만!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104401,
          FinalCamera = "936.792969,-122.973145,119.04834,0.000012,-1.999695,163.999969,35.0,762.45813,false,Manual,5.0",
