          ContentKR = "그래! 이 마왕님과 함께 이 몬스터로 가득한 소굴을 쓸어버리는 거야! 프시케, 아직 탐험을 해 본 적 없지? 정말 안타깝네, 그럼 인생을 제대로 즐긴 게 아니라고!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104607,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "1278.716797,2242.87793,1126.149414,0.000085,-21.600649,-103.932632,25.0,168.419693,false,DoNotOverride,5.0",
          GUID = "194BBB16",
          NextDialogue = 10104608,
          Scripts = [[
