SEQ{
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"Confident_Start"},Duration{6.3}},
PlayAnimation{ActorId{200021},AnimationId{"Confident_End"},Duration{1.7}},
PlayAnimation{ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}}
}
}]],
          SpeakNpcId = 200021,
          Subtitle = "The button mushroom covers about most of it. Ordinary Charons might be able to handle small Filthoids if they give it their best shot, but huge ones like the one we just fought are deadly for them.",
          TalkActionId = {
            [1] = "200006:SpecialThink_End",
            [2] = [[

200061:Think_End]]
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200021:n(200061)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C436C"
        },
        [10105444] = {
          Camera = "-32.449219,-55.212891,133.299805,0.001344,1.001886,104.931633,50.0,169.448013,false,Manual,8.0",
          ContentKR = "그렇다면 그들 모두 의뢰 때문에...",
          DialogueId = 10105444,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Sad01"
          },
          FinalCamera = "-32.449219,-55.212891,133.299805,0.001344,1.001886,104.931633,51.0,169.448013,false,Manual,8.0",
          GUID = "194C4396",
          LookAt = {
            [1] = "200061:n(200061)"
          },
          NextDialogue = 10105445,
          SpeakNpcId = 200061,
          Subtitle = "They were just trying to complete a commission...",
          TalkActionId = {
            [1] = "200061:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1002/101054/194C4396"
        },
        [10105445] = {
          Camera = "86.544922,-391.478516,183.082031,0.001313,-9.799319,109.31813,35.000008,210.591583,false,DoNotOverride,10.0",
          ContentKR = "그렇게 고상한 게 아니야. 다들 그저 살아남으려고 하다보니 그런 거지. 자, 얼른 가. 이제부터는 나 혼자 하면 돼.",
          DialogueId = 10105445,
          FacialId = {
            [1] = "200061:None"
          },
          FinalCamera = "73.251953,-447.859375,181.362305,0.001316,-9.599339,106.918709,35.000011,210.591583,false,DoNotOverride,10.0",
          GUID = "194C43C0",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10105446,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200021:p(180)"}},
MoveTo{_delay{0.5},ActorId{200021},TargetPoint{"P101054_AoteMove2"},MoveSpeed{90},Visibility{"Show"}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "No, they were just trying to survive. Well, off you go. I'll handle the rest here.",
          TalkActionId = {
            [1] = "200021:Confident_End",
            [2] = [[

200061:Explain02_End]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43C0"
        },
        [10105446] = {
          Camera = "227.804688,530.064453,114.802734,0.000015,-1.793635,-114.596718,35.0,803.517822,false,DoNotOverride,4.0",
          ContentKR = "난 좀 늦게 돌아갈 테니 나중에 우리 집으로 와. 우리 집은 시티 남쪽에 있는 낡은 집 중, 문에 작은 새가 그려진 곳이야.",
          DialogueId = 10105446,
          FinalCamera = "227.804688,530.064453,104.378906,0.000015,-1.393611,-114.396393,35.0,803.517822,false,DoNotOverride,4.0",
          GUID = "194C43EA",
          NextDialogue = 10105447,
          Scripts = [[
SEQ{
TurnTo{_delay{2},TurnToDescription{"200021:n(200061)"}},
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{"Think_Start"},Duration{3}},
}

]],
          SpeakNpcId = 200021,
          Subtitle = "I'll be back a bit late, might miss The Asphodel's closing time. Come and find me at my place — it's among those shabby houses south of the city, the one with a little bird drawn on the door.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101054/194C43EA"
        },
        [10105447] = {
          Camera = "-9.882812,4.484375,146.6875,0.000026,1.206198,-92.395676,50.0,241.293564,false,Manual,4.0",
          ContentKR = "그리고 너 혼자 와... 상관없는 녀석들은 달고 오지 말고.",
          DialogueId = 10105447,
          FinalCamera = "-9.882812,4.484375,146.6875,0.000026,1.406199,-92.39563,52.0,241.293564,false,Manual,4.0",
          GUID = "194C4414",
          LookAt = {
            [1] = "200021:n(200006)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}},\n",
          SpeakNpcId = 200021,
          Subtitle = "And come alone — don't bring anyone unrelated.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4414"
        },
        [10105501] = {
          ContentKR = "아무래도 길이 있는 것 같아! 어서 가보자. 여기 한참 있었더니 뭔가 으스스하단 말이야...",
          DialogueId = 10105501,
          GUID = "194C4DC1",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105502,
          SpeakNpcId = 200002,
          Subtitle = "Looks like there's a path over there! Let's get out of here — this place gives me the creeps...",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC1"
        },
        [10105502] = {
          ContentKR = "...잠깐, 설마 내가 그 '상관없는 녀석'은 아니지?",
          DialogueId = 10105502,
          GUID = "194C4DC2",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Wait, when he said \"anyone unrelated,\" he wasn't talking about me, was he?",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC2"
        },
        [10105601] = {
          ContentKR = "이 오솔길은 아까 갱도와는 다른 것 같아. 꼭 누군가 직접 파낸 것처럼...",
          DialogueId = 10105601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5E2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105602,
          SpeakNpcId = 100001,
          Subtitle = "This trail feels different from the one we passed through earlier, almost as if it's been hand-dug by someone.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E2A"
        },
        [10105602] = {
          ContentKR = "정말 그렇네. 여기 삽도 있어... 다른 모험가가 여기 왔었나 봐!",
          DialogueId = 10105602,
          Duration = 3,
          GUID = "194C5E54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105603,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, there are even pickaxes lying around here... Looks like other adventurers have been here before us!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E54"
        },
        [10105603] = {
          ContentKR = "어라, 프시케, 안색이 왜 그래? 아까부터 말도 없고.",
          DialogueId = 10105603,
          Duration = 3,
          GUID = "194C5E7E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105604,
          SpeakNpcId = 200002,
          Subtitle = "You okay, Psyche? You look pale, and you've been awfully quiet for a while.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E7E"
        },
        [10105604] = {
          ContentKR = "아, 내, 내가 그랬어?",
          DialogueId = 10105604,
          Duration = 3,
          GUID = "194C5EA8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10105605,
          SpeakNpcId = 200006,
          Subtitle = "Ah, h-have I?",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EA8"
        },
        [10105605] = {
          ContentKR = "아마... 아까 그 몬스터가 생각나서, 무서워서 그래. 그 몬스터, 설마 예전에...",
          DialogueId = 10105605,
          Duration = 3,
          GUID = "194C5ED2",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105606,
          SpeakNpcId = 200006,
          Subtitle = "Guess I still reelling from that monster. I keep wondering if it could have once been...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5ED2"
        },
        [10105606] = {
          ContentKR = "뭐가 무서워, 우리가 있잖아!",
          DialogueId = 10105606,
          Duration = 3,
          GUID = "194C5EFC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105607,
          SpeakNpcId = 200002,
          Subtitle = "Relax! We're right here with you!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EFC"
        },
        [10105607] = {
          ContentKR = "아까 그 녀석도 말했지만 여기 시종 녀석이 대단한 '다이몬'이라잖아? 필토이드 정도는 무리로 덤빈다고 해도 상대도 안 된다는 거지.",
          DialogueId = 10105607,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F26",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105608,
          SpeakNpcId = 200002,
          Subtitle = "That Outsider said that my little minion is a strong \"Daimon,\" right? So even if ten more Filthoids came at us, they'd be no match for {性别:him|her}.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F26"
        },
        [10105608] = {
          ContentKR = "그만 놀려, 나도 힘을 거의 다 썼어. 프시케도 방금 괜히 한 말일 거야.",
          DialogueId = 10105608,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F50",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105609,
          SpeakNpcId = 100001,
          Subtitle = "Cut it out. I'm nearly spent, and Psyche was just bluffing.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F50"
        },
        [10105609] = {
          ContentKR = "다들 무사해서 다행이야... 내가 너희를 위험에 빠뜨리지 말아야 했어.",
          DialogueId = 10105609,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F7A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105610,
          SpeakNpcId = 100001,
          Subtitle = "I'm just relieved you're both safe... Maybe I shouldn't have involved you two in such a dangerous event.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F7A"
        },
        [10105610] = {
          ContentKR = "아니야! 이번 '모험'은 아주 만족스러워.",
          DialogueId = 10105610,
          Duration = 3,
          GUID = "194C5FA4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105611,
          SpeakNpcId = 200006,
          Subtitle = "No, not at all! I'm really happy that I took part in such an adventure.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FA4"
        },
        [10105611] = {
          ContentKR = "익숙한 도시를 벗어나, 동료들과 함께 가보지 못한 곳에 가고, 사고도 치고, 험악한 적도 상대했잖아. 이런 건 생각도 못 했어.",
          DialogueId = 10105611,
          Duration = 3,
          GUID = "194C5FCE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105612,
          SpeakNpcId = 200006,
          Subtitle = "I never thought I'd get out of town with friends, explore unknown places, get in trouble, and fight evil enemies together.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FCE"
        },
        [10105612] = {
          ContentKR = "...지금 생각해 보면 아직도 어질어질해. 꼭 긴 꿈을 꾼 것 같아.",
          DialogueId = 10105612,
          Duration = 3,
          GUID = "194C5FF8",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105613,
          SpeakNpcId = 200006,
          Subtitle = "Now that I think about it, it all feels so unreal, like living a daydream.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FF8"
        },
        [10105613] = {
          ContentKR = "봐, 프시케도 이렇게 말하잖아!",
          DialogueId = 10105613,
          Duration = 3,
          GUID = "194C6022",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10105614,
          SpeakNpcId = 200002,
          Subtitle = "See? Psyche agrees with me!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C6022"
        },
        [10105614] = {
          ContentKR = "......",
          DialogueId = 10105614,
          Duration = 3,
          GUID = "194C604C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C604C"
        },
        [10105701] = {
          ContentKR = "저기... 헨릭 아니야? 여긴 어쩐 일이지?",
          DialogueId = 10105701,
          Duration = 3,
          GUID = "194C6E92",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Isn't that Henrik over there...? What's he doing here?",
          VoiceName = "voice/$Locale$/story/1002/101057/194C6E92"
        },
        [10105801] = {
