        },
        [10106106] = {
          ContentKR = "안녕, {nickname}(이)라고 해. 그런데 설마 네가 그 유명한... 무시무시한 아웃사이더의 친척?",
          DialogueId = 10106106,
          GUID = "10106106",
          NextDialogue = 10106107,
          Subtitle = "I'm . You wouldn't happen to be that... \"terrifying relative\", would you?"
