        [10106703] = {
          Camera = "-86.024658,92.782227,128.178589,0.001248,-4.999971,12.501308,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "여긴 무슨 일이지? 날이 밝으면 떠나라고 했을 텐데?",
          DialogueId = 10106703,
          FinalCamera = "-90.269287,111.916992,128.178589,0.00125,-4.999971,12.502479,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194D12CC",
          NextDialogue = 10106704,
          SpeakNpcId = 200005,
          Subtitle = "What are you doing here? Didn't I ask you to leave in the morning?",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101067/194D12CC"
        },
        [10106704] = {
          ContentKR = "당신이 원하는 걸 찾았어요, <H>반짝이는 수정</>말이에요.",
          DialogueId = 10106704,
          ExStoryInfo = "Player",
          GUID = "194D12F6",
          NextDialogue = 10106705,
          SpeakNpcId = 100001,
          Subtitle = "I've got what you were looking for, the Crystallo of Stella.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D12F6"
        },
        [10106705] = {
          ContentKR = "너한테 오라고 한 적 없어. 아스포델에 가서 물건을 카밀라 스칼렛에게 넘겨.",
          DialogueId = 10106705,
          GUID = "194D1320",
          NextDialogue = 10106706,
          SpeakNpcId = 200005,
          Subtitle = "No one asked for you to come here. Go to The Asphodel and give it to Camilla Scarlet.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D1320"
        },
        [10106706] = {
          Camera = "43.533447,190.366211,124.659058,0.001232,1.999995,-65.366714,15.0,73.0,false,Manual,2.8",
          ContentKR = "난 외지에서 와서 아이스레이크 시티의 규칙은 잘 몰라요. 우리가 있는 곳에선 거래란 돈을 내면 물건을 건네는 거라서요.",
          DialogueId = 10106706,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "43.533447,190.366211,132.331177,0.001219,-1.200071,-66.367569,15.000005,73.0,false,Manual,2.8",
          GUID = "194D134A",
          NextDialogue = 10106707,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{"DisagreeHead"},Duration{1.8}},
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I'm not from here, I'm not familiar with Icelake's ways. Where I come from, a deal means cash in one hand, goods in the other.",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101067/194D134A"
        },
        [10106707] = {
          Camera = "15.884277,-55.96582,118.667114,0.001188,0.0,83.499969,22.000006,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "헨릭 씨가 필요 없다면 다른 구매자를 찾아보죠.",
          DialogueId = 10106707,
          ExStoryInfo = "Player",
          FinalCamera = "8.491455,-55.133789,118.667114,0.001188,0.0,83.499969,22.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "194D1374",
          NextDialogue = 10106708,
