            [2] = 101070032
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{8.2},TargetPosition{"-28.324219,26.407959,145.527344,0.000018,1.800424,16.803524,35.000008,93.94474,false,Manual,8.483248"},duration{0}},
