        },
        [10107013] = {
          Camera = "-32.240234,44.838135,145.527344,0.000015,2.000453,6.202501,35.0,93.94474,false,Manual,8.483248",
          ContentKR = "(...그러니까 히프노스의 집에 머무는 모든 투숙객은 <H>병</>을 앓고 있는 거구나.)",
          DialogueId = 10107013,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194D45A8",
          NextDialogue = 10107032,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...So, all the lodgers at the Hypnos' House suffer from some kind of illness.)",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D45A8"
        },
        [10107014] = {
          ContentKR = "전에 마찰도 있었고 하니, 헨릭 씨와 잘 지낼 수 있을까 해서. 시간이 되면 나중에 다시 만나러 오려고.",
          DialogueId = 10107014,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "194D45D2",
          NextDialogue = 10107015,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"ScratchHead_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "I've got off on the wrong foot with Mr Henrik, so I'm looking to make amends with him. If there's a chance, I'd like to visit him in the future.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D45D2"
        },
        [10107015] = {
          Camera = "16.691406,22.081543,148.732422,0.000052,-2.199649,-135.59375,25.0,75.553604,false,Manual,3.314391",
          ContentKR = "정말? 헨릭 아저씨는 거의 매일 집에 있어! 아저씨만 괜찮다고 하면 언제든지 가능해!",
          DialogueId = 10107015,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:None"
          },
          GUID = "194D45FC",
          NextDialogue = 10107016,
          SpeakNpcId = 200006,
          Subtitle = "Really? Mr Henrik is almost always at home! You're welcome to visit anytime if he says it's okay!",
          VoiceName = "voice/$Locale$/story/1002/101070/194D45FC"
        },
        [10107016] = {
          Camera = "16.691406,22.081543,148.732422,0.000052,-2.199649,-135.59375,25.0,75.553604,false,Manual,3.314391",
          ContentKR = "...자주 여기 와서 모두에게 네 고향... 그러니까 남쪽이나 바다 같은 그런, 가보지 못한 곳 얘기를 해주면 다들 엄청 좋아할 거야!",
          DialogueId = 10107016,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Happy02"
          },
