          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101078/194DC9E4"
        },
        [10107819] = {
          Camera = "351.825439,503.387695,167.38916,0.000006,-7.200166,-124.993027,30.000002,446.696014,false,DoNotOverride,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "그리고 다음에 카밀라를 만나면 우리가 임시로 팀을 꾸렸다고 알려줘. 그러면 함께 행동하기 편할 거야.",
          DialogueId = 10107819,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "351.825439,503.387695,111.700684,0.000005,-3.199944,-124.99308,30.000002,446.696014,false,DoNotOverride,3.0",
          GUID = "194DC9E5",
          NextDialogue = 10107820,
          SpeakNpcId = 200021,
          Subtitle = "And hey, next time you run into Camilla, let her know we've teamed up for now. It'll make our partnership seem legit.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101078/194DC9E5"
        },
        [10107820] = {
          Camera = "-9.021729,-26.742188,128.609863,0.000102,5.600222,80.398033,35.0,95.583733,false,Manual,5.0",
          ContentKR = "(...아직 시간이 좀 이른데, 또 받을 만한 의뢰가 있나 살펴볼까...)",
          DialogueId = 10107820,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194DD782",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10107821,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{\"101078Point1\"},Visibility{\"Hide\"}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(It's still early. Maybe I can go to The Asphodel and see if there's any new commissions to take on.)",
          VoiceName = "voice/$Locale$/story/1002/101079/194DD782"
        },
        [10107821] = {
          ContentKR = "(그리고 프시케가 좀 외로워 보이던데. 기회가 되면 아이스레이크 시티를 떠나기 전에 가서 이야기나 나눠볼까.)",
          DialogueId = 10107821,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "194DD783",
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Think_End"},Duration{1}}
}]],
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Also, Psyche seems a bit lonely. Maybe I should try to make some time for her before leaving Icelake.)",
          VoiceName = "voice/$Locale$/story/1002/101078/194DD783"
        },
        [10107822] = {
