          SpeakNpcId = 100006,
          Subtitle = "Chief Sibylle.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101080/194DE7EA"
        },
        [10108002] = {
          ContentKR = "나쁜 소식 하나와 또 하나의... 으음, 어쩌면 이것도 나쁜 소식일 수 있겠군요.",
          DialogueId = 10108002,
          GUID = "194DE814",
          NextDialogue = 10108003,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{3.5},TargetPosition{"-128.663086,624.128906,1.964844,0.000055,-11.999959,57.393639,30.000002,195.345673,false,Manual,3.030511"},duration{0}},
CameraMoveTo{TargetPosition{"-128.663086,624.128906,-0.25,0.00007,-11.999959,57.393517,30.000008,195.345673,false,Manual,3.030511"},duration{2}}
},
PlayAnimation{_delay{5.5},ActorId{100006},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "There's a piece of bad news, and a — um, another that might be considered bad as well.",
          TalkActionId = {
            [1] = "100006:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DE814"
        },
        [10108003] = {
          Camera = "-66.51416,854.927246,-32.269531,1.000004,0.004201,-78.810738,20.0,1068.386597,false,Manual,3.961381",
          ContentKR = "더 나쁜 쪽부터 듣지.",
          DialogueId = 10108003,
          GUID = "194DE83E",
          LookAt = {
            [1] = "100005:n(100006)"
          },
          NextDialogue = 10108004,
          SpeakNpcId = 100005,
          Subtitle = "Let's hear the worse one first.",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE83E"
        },
        [10108004] = {
          ContentKR = "연옥도에 남아있는 부대가 사흘째 수색하고 있지만, 제로 곁에 있던 그 {性别:소년|소녀}의 행방을 발견하지 못했습니다.",
          DialogueId = 10108004,
          ExStoryInfo = "Player",
          GUID = "194DE868",
          NextDialogue = 10108005,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100006},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{100006},AnimationId{"Shock_End"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "The unit left on Purgatorio Island has been searching the area for three days, but they've yet to find any trace of that {性别:boy|girl} who was with No. 0.",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE868"
        },
        [10108005] = {
          Camera = "-92.738281,622.456055,9.740234,0.0001,-14.199403,67.99823,35.000008,179.265518,false,Manual,3.175064",
          ContentKR = "절벽에서 떨어지자마자 즉시 부근의 해역을 수색했으니 생사와 무관하게, 더 먼 곳까지 흘러갔을 리는 없습니다. 누군가...",
          DialogueId = 10108005,
          ExStoryInfo = "Player",
          GUID = "194DE892",
          NextDialogue = 10108006,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100006},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{_delay{3.5},ActorId{100006},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{3},ActorId{100006},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "We searched the nearby waters immediately after {性别:he|she} fell off the cliff. Theoretically speaking, {性别:he|she} shouldn't have drifted far. Unless...",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE892"
        },
        [10108006] = {
          Camera = "-46.48291,518.056641,12.158203,0.000022,5.999481,-87.199181,25.000002,1007.337402,false,Manual,1.2",
          ContentKR = "음?",
          DialogueId = 10108006,
          DisableMouth = 1,
          FacialId = {
            [1] = "100005:Unhappy01"
          },
          FinalCamera = "-43.944824,466.02832,17.613281,0.000022,5.999481,-87.199181,25.000002,1007.337402,false,Manual,1.2",
          GUID = "194DE8BC",
          NextDialogue = 10108007,
          SpeakNpcId = 100005,
          Subtitle = "Hmm?",
          TalkActionId = {
            [1] = "100006:Explain01_End",
            [2] = "100005:Talk03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101080/194DE8BC"
        },
        [10108007] = {
          ContentKR = "...그 {性别:소년을|소녀를} 구한 게 아니라면요.",
          DialogueId = 10108007,
          ExStoryInfo = "Player",
          GUID = "194DE8E6",
          NextDialogue = 10108008,
          SpeakNpcId = 100006,
          Subtitle = "Unless someone rescued {性别:him|her}.",
          TalkActionId = {
            [1] = "100006:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DE8E6"
        },
        [10108008] = {
          Camera = "-39.142578,216.660645,-9.847656,0.000427,17.004915,-88.632324,50.000011,212.416504,false,DoNotOverride,5.0",
          ContentKR = "...주변 섬 주민들을 계속 조사해. 어떤 용의자나 목격자도 놓치지 마라.",
          DialogueId = 10108008,
          FacialId = {
            [1] = "100005:Angry01"
          },
          GUID = "194DE910",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          NextDialogue = 10108009,
          Scripts = [[
SEQ{
TurnTo{_delay{1.5},TurnToDescription{"100005:p(180)"}},
PlayAnimation{_delay{1.5},ActorId{100005},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100005,
          Subtitle = "...Continue investigating the residents on nearby islands. Leave no suspect or witness unchecked.",
          TalkActionId = {
            [1] = "100006:Talk02_End",
            [2] = "100005:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DE910"
        },
        [10108009] = {
          Camera = "-92.738281,622.456055,9.740234,0.0001,-14.199403,67.99823,35.000008,179.265518,false,Manual,3.175064",
          ContentKR = "이미 그렇게 하고 있습니다. 수색 범위도 계속 확대 중이고요. 하지만 감히 여쭙는데...",
          DialogueId = 10108009,
          GUID = "194DE93A",
          NextDialogue = 10130101,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100006},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{3.5},ActorId{100006},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "Already on it. And we're expanding the search area. But if I may ask—",
          TalkActionId = {
            [1] = "100005:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DE93A"
        },
        [10108010] = {
          Camera = "-88.675293,985.40918,-40.296875,0.000035,6.0,-81.79319,50.0,1142.016846,false,Manual,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "만약 정말 그 {性别:소년을|소녀를}... 그러니까 레조넌스의 숙주를 손에 넣으면 어떻게 처리하실 계획입니까?",
          DialogueId = 10108010,
          ExStoryInfo = "Player",
          FinalCamera = "-88.675293,985.40918,-28.716797,0.000035,3.999765,-81.793198,50.0,1142.016846,false,Manual,5.0",
          GUID = "194DE964",
          NextDialogue = 10108011,
          SpeakNpcId = 100006,
          Subtitle = "If we do find {性别:him|her}... the host of Resonance, what's your plan for it, Chief?",
          TalkActionId = {
            [1] = "100005:Explain02_End"
          },
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101080/194DE964"
        },
        [10108011] = {
          Camera = "-80.04834,-432.792969,122.105469,0.000063,-7.999989,81.205322,50.0,772.028992,false,Manual,5.5",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "제가 알기로 제로와 달리 휘페르보레아는 이 힘을 효과적으로 사용할 수 없습니다. 오히려 반대일 수도 있습니다... 어쨌든 이상적인 상태에서 레조넌스는 모든 '다이몬'에게 관여할 수 있으니까요...",
          DialogueId = 10108011,
          FinalCamera = "-80.04834,-432.792969,139.992188,0.000063,-9.999997,81.205353,50.0,772.028992,false,Manual,5.5",
          GUID = "194DE98E",
          NextDialogue = 10108012,
          RelatedWikiId = {
            [1] = 304002
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100006},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{4.5},ActorId{100006},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{0.5},ActorId{100006},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "As far as I'm aware, unlike No. 0, Hyperborea can't effectively harness this power — it might even backfire... After all, Resonance is capable of affecting all Daimons in ideal conditions...",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101080/194DE98E"
        },
        [10108012] = {
          Camera = "-64.435547,-6.380371,98.320312,0.000448,9.605035,-79.632217,30.0,209.305862,false,Manual,1.6",
          ContentKR = "이 힘이 사라지는 거면 몰라도 절대 제국 밖으로 넘어가게 둘 수는 없어. 그럼 다른 나쁜 소식은 뭐지?",
          DialogueId = 10108012,
          GUID = "194DE9B8",
          NextDialogue = 10108013,
          Scripts = [[
SEQ{
PlayAnimation{_delay{6},ActorId{100005},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100005,
          Subtitle = "This power can vanish, but must never end up outside Imperial control. Now, what's the other bad news?",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE9B8"
        },
        [10108013] = {
          Camera = "-1487.203369,2515.675293,1424.984375,0.00003,-29.70046,-53.591125,35.0,198.622971,false,DoNotOverride,3.0",
          ContentKR = "저한테 조사하라고 하신 다른 일에 관한 겁니다.",
          DialogueId = 10108013,
          FinalCamera = "-1590.206055,2655.341553,1523.966797,0.00003,-29.70046,-53.591125,35.0,198.622971,false,DoNotOverride,3.0",
          GUID = "194DE9E2",
          NextDialogue = 10108014,
          SpeakNpcId = 100006,
          Subtitle = "It's about the other matter you've asked me to investigate, Chief.",
          TalkActionId = {
            [1] = "100005:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101080/194DE9E2"
        },
        [10108014] = {
          ContentKR = "수색 과정에서 근처 무인도에서 배를 타고 이곳으로 도망쳐온 마을 사람을 만났는데 재미있는 '무언가'를 발견했습니다.",
          DialogueId = 10108014,
          GUID = "194DEA0C",
          NextDialogue = 10108015,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"-88.142578,691.203125,6.554688,0.000085,-16.999535,59.401443,35.000008,210.882507,false,DoNotOverride,6.0"},duration{0}},
CameraMoveTo{TargetPosition{"-89.819336,688.370605,7.554688,0.000085,-16.999535,59.401443,35.000008,210.882507,false,DoNotOverride,6.0"},duration{6}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "During the search, on a deserted island, I encountered some villagers who had fled there by boat. And then, we discovered something quite intriguing.",
          TalkActionId = {
            [1] = "100006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEA0C"
        },
        [10108015] = {
          ContentKR = "평범한 수프를 먹으려던 그때 예쁜 은빛의 숟가락이 갑자기 칠흑 같이 변한 것과 같달까요.",
          DialogueId = 10108015,
          FacialId = {
            [1] = "100006:Shock01"
          },
          GUID = "194DEA36",
          NextDialogue = 10108016,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{100006},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{_delay{6},ActorId{100005},AnimationId{"Think_End"},Duration{1}}
},
CameraMoveTo{_delay{5.5},TargetPosition{"-136.59082,629.249023,-7.123047,0.000071,-11.799984,57.1945,30.0,195.345673,false,Manual,3.030511"},duration{0}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "It's as if you were tasting a bowl of ordinary thick soup, only to find the spoon you had just used turned from shiny silver to a dreadful black—",
          TalkActionId = {
            [1] = "100005:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEA36"
        },
        [10108016] = {
          Camera = "-90.080566,-82.443359,112.785156,0.000359,8.403502,-64.220345,35.000008,161.292053,false,Manual,6.0",
          ContentKR = "쓸데없는 소리는 됐고, 요점만 간단하게.",
          DialogueId = 10108016,
          FacialId = {
            [1] = "100005:Angry01"
          },
          GUID = "194DEA60",
          NextDialogue = 10108017,
          SpeakNpcId = 100005,
          Subtitle = "Cut the fancy talk. Get to the point.",
          TalkActionId = {
            [1] = "100005:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEA60"
        },
        [10108017] = {
          Camera = "-136.59082,629.249023,-7.123047,0.000071,-11.799984,57.1945,30.0,195.345673,false,Manual,3.030511",
          ContentKR = "아... 예, 예. 그 재미있는 것이란 바로 <H>'시간차'</>입니다.",
          DialogueId = 10108017,
          FinalCamera = "-128.663086,624.128906,1.964844,0.000055,-11.999959,57.393639,30.000002,195.345673,false,Manual,3.030511",
          GUID = "194DEA8A",
          NextDialogue = 10108018,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100006},AnimationId{"Shock_End"},Duration{1}},
PlayFacial{_delay{1},ActorId{100006},FacialId{"None"}},
PlayAnimation{_delay{4},ActorId{100006},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "Ah... yes, Chief. That intriguing thing is a tiny time discrepancy.",
          TalkActionId = {
            [1] = "100005:Explain01_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEA8A"
        },
        [10108018] = {
          Camera = "-432.941406,1929.711914,30.550781,0.000332,-3.300006,-73.81044,30.0,174.408691,false,DoNotOverride,3.236185",
          ContentKR = "마을 사람들이 연옥도의 필토이드는 이전까지 줄곧 산에 살았고, 그동안은 강한 공격성을 보이지 않았다고 했습니다. 하지만 저희가 도착하기 <H>이틀 전</>, 갑자기 폭주라도 한 듯 마을 사람들을 공격했다고 하더군요.",
          DialogueId = 10108018,
          FinalCamera = "-432.941406,1929.711914,67.210938,0.000332,-3.300019,-73.810356,30.0,174.408691,false,DoNotOverride,3.236185",
          GUID = "194DEAB4",
          NextDialogue = 10108019,
          SpeakNpcId = 100006,
          Subtitle = "The villagers told me, that the Filthoids of Purgatorio Island always lived in the mountains without much aggression; but two days before our arrival, they suddenly went berserk and started attacking the villagers.",
          TalkActionId = {
            [1] = "100006:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEAB4"
        },
        [10108019] = {
          Camera = "-44.418457,-154.999023,169.058594,0.000032,-19.399868,-78.186974,30.000002,78.537529,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "이틀 전'이라...",
          DialogueId = 10108019,
          FinalCamera = "-40.415039,-174.143066,162.169922,0.00003,-19.399921,-78.187599,30.000002,58.681007,false,Manual,4.0",
          GUID = "194DEADE",
          NextDialogue = 10108020,
          SpeakNpcId = 100005,
          Subtitle = "\"Two days before our arrival\"...",
          TalkActionId = {
            [1] = "100005:Think_Start"
          },
          ToFinalCameraBlendTime = 1.5,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEADE"
        },
        [10108020] = {
          Camera = "-65.008301,620.166992,-9.789062,0.00008,-5.799861,76.39901,50.000011,165.188309,false,Manual,2.775071",
          ContentKR = "...벌써 짐작하셨나 보군요. 공교롭지 않습니까? 계획이 갑자기 바뀌어서 저희가 원래 계획보다 이틀 늦게 섬에 도착했으니까요.",
          DialogueId = 10108020,
          GUID = "194DEB08",
          NextDialogue = 10108021,
          SpeakNpcId = 100006,
          Subtitle = "...It appears you've already figured it out, Chief. Quite a coincidence, isn't it? Due to a last-minute change of plan, we arrived two days later than initially scheduled.",
          TalkActionId = {
            [1] = "100005:Think_End",
            [2] = "100006:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB08"
        },
        [10108021] = {
          ContentKR = "필토이드를 조종해 암살할 능력을 갖춘 건 <W>포세이큰 동맹</>뿐입니다.",
          DialogueId = 10108021,
          GUID = "194DEB32",
          NextDialogue = 10108022,
          RelatedWikiId = {
            [1] = 101004
          },
          Scripts = "PlayAnimation{delay{4},ActorId{100006},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 100006,
          Subtitle = "The only force capable of manipulating Filthoids is The Forsakens.",
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB32"
        },
        [10108022] = {
          Camera = "-94.642578,-318.927246,96.927734,8.007288,17.396826,65.810257,20.000008,110.446434,false,Manual,6.0",
          ContentKR = "...포세이큰 동맹의 소행이든 아니든, 제13군단에 쥐새끼가 들어온 것 같은데.",
          DialogueId = 10108022,
          FinalCamera = "-100.751465,-332.528809,92.259766,8.007426,17.396826,65.810616,20.000008,110.446434,false,Manual,6.0",
          GUID = "194DEB5C",
          NextDialogue = 10108023,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"100005:p(-180)\"}}",
          SpeakNpcId = 100005,
          Subtitle = "...Whoever it is, the 13th Legion has been compromised by unwelcome elements.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB5C"
        },
        [10108023] = {
          ContentKR = "몇 년 되었더니 또다시 벌레 같은 것들이 꿈틀대기 시작하는군...",
          DialogueId = 10108023,
          GUID = "194DEB86",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          NextDialogue = 10108024,
          SpeakNpcId = 100005,
          Subtitle = "After all these years, those worms have started wriggling again...",
          TalkActionId = {
            [1] = "100005:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101080/194DEB86"
        },
        [10108024] = {
          Camera = "-267.375,-231.39209,11.626953,3.599992,2.500006,0.199989,35.000008,198.622971,false,Manual,3.0",
          ContentKR = "확실히 밟아줘야겠어.",
          DialogueId = 10108024,
          FinalCamera = "-324.33252,-231.588867,9.132812,3.599993,2.500006,0.199989,35.000008,198.622971,false,Manual,3.0",
          GUID = "194DEBB0",
          Scripts = "MoveTo{_delay{3},ActorId{100005},TargetPoint{\"P101080Xibi1\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 100005,
          Subtitle = "It's time for a thorough extermination.",
          TalkActionId = {
            [1] = "100005:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101080/194DEBB0"
        },
        [10108101] = {
          ContentKR = "제13군단은 사냥개가 칩거하는 소굴을 벗어나듯 조용히 어둠의 사냥을 벌였다.",
          DialogueId = 10108101,
          Duration = 4,
          GUID = "194DF852",
          NextDialogue = 10108102,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "Like a predator finally emerging from its lair, the 13th Legion silently commenced a hunt in the dark."
        },
        [10108102] = {
          ContentKR = "한편 아이스레이크 시티에서는...",
          DialogueId = 10108102,
          Duration = 4,
          GUID = "194DF87C",
          NextDialogue = 10108103,
          Subtitle = "Meanwhile, in a city leagues away,"
        },
        [10108103] = {
          ContentKR = "갓 월석 사냥꾼이 된 신입이 베테랑 사냥꾼이 되는 법을 배우고 있었다.",
          DialogueId = 10108103,
          Duration = 4,
          GUID = "194DF8A6",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "a novice is slowly learning to become a dependable hunter."
        },
        [10108201] = {
          ContentKR = "우선은 '그것'부터 조정해 봐야겠어. 아직 시간이 좀 있으니 근처 야수들로 연습해 봐. 저기 꼬맹이는 아직 도시에서 망을 보고 있으니 너무 멀리는 가지 마.",
          DialogueId = 10108201,
          GUID = "194E08BA",
          LookAt = {
            [1] = "200021:n(0)"
          },
          NextDialogue = 10108202,
          SpeakNpcId = 200021,
          Subtitle = "I gotta give \"that thing\" a little tweak. It's still early, so why don't you do some casual practice on those beasts nearby? Just don't wander too far — Button Mushroom is in town keeping watch for us.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101082/194E08BA"
        },
        [10108202] = {
          ContentKR = "내가 미리 함정을 설치해뒀어. 잘 작동하니까, 쓰레기로 만든 거라는 생각은 하지 말고.",
          DialogueId = 10108202,
          GUID = "194E08BB",
          NextDialogue = 10108203,
          SpeakNpcId = 200021,
          Subtitle = "I've already set up some traps. They may look like junk — they're made from scrap, after all — but they work quite well.",
          TalkActionId = {
            [1] = "200021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101082/194E08BB"
        },
        [10108203] = {
          ContentKR = "그래도 조심히 써. 좋은 재료가 아니라서 자칫하면 망가질 수도 있거든, 하하...",
          DialogueId = 10108203,
          GUID = "194E08BC",
          SpeakNpcId = 200021,
          Subtitle = "Be careful with them, though. They aren't made of the sturdiest materials and might break if you step on them. Haha...",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101082/194E08BC"
        },
        [10108301] = {
          Camera = "820.816406,636.059082,465.740234,0.000086,-21.70013,-141.791962,50.0,437.971283,false,DoNotOverride,2.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "하아... 하아...",
          DialogueId = 10108301,
          ExStoryInfo = "Player",
          FinalCamera = "854.382812,662.485352,482.745117,0.000086,-21.70013,-141.791962,50.0,437.971283,false,DoNotOverride,2.0",
          GUID = "194E1922",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10108302,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Whew... Whew...",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1922"
        },
        [10108302] = {
          Camera = "243.050781,-58.478027,50.348633,0.000132,11.999521,161.197205,35.0,321.520721,false,Manual,4.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "좋아, 요 며칠 성장이 꽤 빠른걸. 그래도 아직 멀었어.",
          DialogueId = 10108302,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "241.128906,-63.912598,50.348633,0.000133,12.199516,158.997177,35.0,321.520721,false,Manual,4.0",
          GUID = "194E194C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10108303,
          SpeakNpcId = 200021,
          Subtitle = "Not bad — you've improved a lot these past few days! Still, there's more to learn.",
          TalkActionId = {
            [1] = "200021:AgreeHead",
            [2] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101083/194E194C"
        },
        [10108303] = {
          Camera = "3226.708984,-329.703857,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "예를 들면 이런 큰 필토이드는 달리기는 빨라도 몸집이 육중하잖아. 그러니 벽이나 나무줄기 앞에 서서 녀석들을 도발하는 거야. 그 놈들이 돌진해서 너에게 다가왔을 때쯤 네가 옆으로 살짝 비켜서서 자기 혼자 머리를 부딪혀 정신을 못 차리게 하는 거지.",
          DialogueId = 10108303,
          FinalCamera = "3120.359375,-484.996094,-858.430176,-0.0,2.99999,145.59549,15.0,100000.0,false,Disable,2.8",
          GUID = "194E19A0",
          NextOptions = {
            [1] = 10108304,
            [2] = 10108305
          },
          Scripts = "CameraMoveTo{_delay{6},TargetPosition{\"82.828125,-22.881592,132.529785,0.000104,-1.397983,140.189499,35.000008,161.268082,false,Manual,4.0\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "For example, with larger beasts and Filthoids: they're fast but clumsy, so you can stand in front of something solid, like a wall or a tree, and provoke it to charge at you, then dodge its charge to let it knock itself out.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19A0",
          bForbidSkipOptions = true
        },
        [10108304] = {
          ContentKR = "음, 괜찮은 방법인걸.",
          DialogueId = 10108304,
          GUID = "10108304",
          ImprPlusId = 1006,
          NextDialogue = 10108306,
          Subtitle = "Huh, that's a clever tactic. "
        },
        [10108305] = {
          ContentKR = "윽... 비겁한 수단이잖아. ",
          DialogueId = 10108305,
          GUID = "10108305",
          ImprPlusId = 1007,
          NextDialogue = 10108308,
          Subtitle = "Hmm... that's rather underhanded. "
        },
        [10108306] = {
          Camera = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "하, 그거야 당연하지. 이건 내가 어릴 때부터 고생하며 익힌 묘수라고. 적을 상대하는 것도 비슷한 원리야. 화가 난 인간은 야수와 별반 다를 것 없어.",
          DialogueId = 10108306,
          FacialId = {
            [1] = "200021:Smile02"
          },
          FinalCamera = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0",
          GUID = "194E19CA",
          NextDialogue = 10108307,
          SpeakNpcId = 200021,
          Subtitle = "Hah, naturally. It's a trick I picked up growing up tough. It's the same with these enemies — an enraged person isn't much different from a beast.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19CA"
        },
        [10108307] = {
          Camera = "1436.363281,-566.314941,420.743164,0.000009,-12.299579,153.401611,20.0,489.882812,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "좋아, 이런 것들은 어차피 네 상대가 안 돼. 이제 제대로 된 걸로 가볼까...",
          DialogueId = 10108307,
          FinalCamera = "1506.460938,-601.418945,437.838379,0.000008,-12.299579,153.401855,20.0,489.882812,false,DoNotOverride,1.2",
          GUID = "194E19F4",
          NextDialogue = 10108311,
          SpeakNpcId = 200021,
          Subtitle = "Alright, those random critters weren't much of a challenge for you. Now, let's find you a worthy opponent...",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101083/194E19F4"
        },
        [10108308] = {
          Camera = "352.355469,-143.926758,113.639648,0.000176,0.800027,154.399246,50.000008,466.962006,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "이건 기본적인 상식이야. 비 오는데 우산 쓴다고 '비겁'하다고 하는 거 봤어?",
          DialogueId = 10108308,
          FinalCamera = "354.804688,-138.704834,113.639648,0.000176,0.80002,155.399689,50.000008,466.962006,false,Manual,8.0",
          GUID = "194E1A1E",
          NextDialogue = 10108309,
          SpeakNpcId = 200021,
          Subtitle = "It's just a life hack. You wouldn't call using an umbrella in the rain \"underhanded,\" would you?",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1A1E"
        },
        [10108309] = {
          Camera = "-32.097656,61.484131,137.130859,0.00022,-3.49942,-43.808128,50.0,142.954285,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "네가 말하니까 유난히 비겁하게 들리는 건가...",
          DialogueId = 10108309,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          FinalCamera = "-32.097656,61.484131,137.130859,0.00022,-3.49942,-43.808128,52.0,142.954285,false,Manual,5.0",
          GUID = "194E1A48",
          NextDialogue = 10108310,
          SpeakNpcId = 100001,
          Subtitle = "Maybe it just sounds particularly underhanded coming from you...",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101083/194E1A48"
        },
        [10108310] = {
          Camera = "1436.363281,-566.314941,420.743164,0.000009,-12.299579,153.401611,20.0,489.882812,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "자, 쓸데없는 말다툼은 그만하고, 이런 것들로는 너한테 연습이 안 될 테니 이제 좀 더 큰 걸로 가볼까...",
          DialogueId = 10108310,
          FinalCamera = "1506.460938,-601.418945,437.838379,0.000008,-12.299579,153.401855,20.0,489.882812,false,DoNotOverride,1.2",
          GUID = "194E1A72",
          NextDialogue = 10108311,
          SpeakNpcId = 200021,
          Subtitle = "Alright, enough with the petty bickering. Those random critters weren't much of a challenge for you anyway. Now, let's find you a worthy opponent...",
          TalkActionId = {
