          SpeakNpcId = 200002,
          Subtitle = "\"Through great trials and hardships, the Demon king and her minion finally retrieved a precious treasure from the deep waters. With hopeful hearts and anxious breaths, they opened the box, only to find—\"",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101087/194E5AEC"
        },
        [10108704] = {
