        [10109002] = {
          Camera = "296.376221,434.72168,221.220703,0.000066,-12.002404,-123.593864,35.000008,100000.0,false,Disable,2.8",
          ContentKR = "그 명단에 실종된 헌트의 이름도 있어... 내 생각엔 그다지 좋은 일이 일어났을 것 같지 않아. 게다가... 그 프시케라는 네 친구는 다음 순서일 거야.",
          DialogueId = 10109002,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "294.126709,431.435547,200.367188,0.000066,-9.602358,-123.99411,35.000008,100000.0,false,Disable,2.8",
          GUID = "194E8C24",
          LookAt = {
            [1] = "200021:n(200002)",
            [2] = "200002:n(200021)"
          },
          NextDialogue = 10109003,
          SpeakNpcId = 200021,
          Subtitle = "Hunt appeared on that list after he went missing... I fear things didn't end well for him. And I'm worried your friend Psyche might be next.",
          TalkActionId = {
            [1] = "200021:Talk03_Start",
            [2] = "200002:Shock_End"
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C24"
        },
        [10109003] = {
          Camera = "143.380615,51.583008,147.531738,0.000069,-1.199982,-144.201019,40.0,274.454834,false,Manual,5.0",
          ContentKR = "타이밍이 안 좋았어. 몇 분만 더 있었으면... 내 탓이야. 굴뚝 자물쇠를 뜯느라 너무 시간을 허비했어. 이런 젠장! 헨릭이 좋은 인간이 아니라는 건 진작 예상했지만.",
          DialogueId = 10109003,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "132.862061,65.048828,147.531738,0.00007,-1.199941,-138.801163,40.0,274.454834,false,Manual,5.0",
          GUID = "194E8C4E",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10109004,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{"DisagreeHead"},Duration{0.1}},
PlayAnimation{_delay{6},ActorId{200021},AnimationId{"Angry01_Start"},Duration{0.1}}
}
]],
          SpeakNpcId = 200021,
          Subtitle = "Ugh, Henrik came back at a bad time. If I had just a few more minutes... It's my fault — I wasted too much time with that chimney. D**n it! I knew he was up to no good.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 12.5,
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C4E"
        },
        [10109004] = {
          Camera = "182.130371,-23.287109,254.786621,0.000186,-44.200417,167.992661,50.0,272.284515,false,Manual,8.0",
          ContentKR = "이제 어떡하지? {nickname}, 프시케는 좋은 아이야. 우리가 구해줘야 해!",
          DialogueId = 10109004,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Unacceptable01",
            [2] = "100001:Unacceptable01"
          },
          FinalCamera = "178.129395,-38.544922,254.786621,0.000188,-44.000259,164.590942,50.000008,272.284515,false,Manual,8.0",
          GUID = "194E8C78",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)",
            [3] = "200021:n(200002)"
          },
          NextDialogue = 10109005,
          SpeakNpcId = 200002,
          Subtitle = "What do we do now? , Psyche is a good girl... we have to find a way to save her!",
          TalkActionId = {
            [1] = "200002:Angry01_Start",
            [2] = "200021:Angry01_End"
          },
          ToFinalCameraBlendTime = 5.5,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8C78"
        },
        [10109005] = {
          Camera = "-154.219482,-87.605469,159.164062,0.000126,-5.801665,12.215151,35.000008,199.764572,false,Manual,5.0",
          ContentKR = "...지금 바로 히프노스의 집으로 가야겠어.",
          DialogueId = 10109005,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "194E8CA2",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200021:n(100001)"
          },
          NextDialogue = 10109006,
          SpeakNpcId = 100001,
          Subtitle = "I'm going to the Hypnos' House right now.",
          TalkActionId = {
            [1] = "100001:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8CA2"
        },
        [10109006] = {
          Camera = "114.775879,41.625977,143.989258,0.000065,0.999987,-141.600128,50.000008,229.941086,false,Manual,8.0",
          ContentKR = "진정해. 아직 닷새 남았으니 일단 돌아가서 준비부터 하자.",
          DialogueId = 10109006,
          FacialId = {
            [1] = "200021:Confident01"
          },
          GUID = "194E8CCC",
          NextDialogue = 10109007,
          SpeakNpcId = 200021,
          Subtitle = "Don't rush into it. We still have five days, so let's go back and get prepared first.",
          TalkActionId = {
            [1] = "200021:DisagreeHead",
            [2] = "100001:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8CCC"
        },
        [10109007] = {
          Camera = "-54.203369,-87.207031,170.859375,0.000122,-15.201439,29.00316,50.0,139.404022,false,DoNotOverride,3.698512",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "아니, 사람은 최대한 빨리 구하는 게 좋아. 다시는... 보고 싶지 않아...",
          DialogueId = 10109007,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-8.238281,-62.397461,154.720703,0.00012,-15.201385,28.40259,34.0,139.404022,false,DoNotOverride,3.698512",
          GUID = "194E8CF6",
          NextDialogue = 10109008,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Sigh_Start\"},Duration{1}},\n",
          SpeakNpcId = 100001,
          Subtitle = "No, it's always better to act sooner rather than later to save someone. I can't just...",
          TalkActionId = {
            [1] = "200002:Angry01_End",
            [2] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8CF6"
        },
        [10109008] = {
          DialogueId = 10109008,
