        [10109009] = {
          Camera = "46.280029,5.457031,149.058594,0.000183,0.999714,-140.175919,45.0,163.680023,false,Manual,8.0",
          ContentKR = "누군가를 잃었지만, 아무것도 할 수 없었다'는 건가?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10109009,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "46.280029,5.457031,149.058594,0.000183,0.999714,-140.175919,48.0,163.680023,false,Manual,8.0",
          GUID = "194E8D20",
          NextDialogue = 10109010,
          SpeakNpcId = 200021,
          Subtitle = "\"Just stand there, helplessly watching her leave.\" Right?",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D20"
        },
        [10109010] = {
          Camera = "-218.000488,-102.597656,160.563965,0.000186,-4.601375,10.503407,45.0,275.06012,false,Manual,8.0",
          ContentKR = "...그걸 어떻게...",
          DialogueId = 10109010,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "194E8D4A",
          NextDialogue = 10109011,
          SpeakNpcId = 100001,
          Subtitle = "...How did you know?",
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D4A"
        },
        [10109011] = {
          Camera = "161.370605,114.686523,183.224121,1.999996,-9.799962,-135.169739,35.000008,150.644867,false,DoNotOverride,1.449662",
          ContentKR = "그냥 때려 맞춘 거야. 너 반응이 너무 심각하니까. 고민하던 것도 다 내팽개치고 말이야. 그 사람이 너한테 꽤나 중요했나 보네?",
          DialogueId = 10109011,
          FinalCamera = "143.11377,130.476562,175.044922,1.999993,-7.999879,-128.567734,35.000008,150.644867,false,DoNotOverride,1.449662",
          GUID = "194E8D74",
          NextDialogue = 10109012,
          SpeakNpcId = 200021,
          Subtitle = "Just a guess — you seemed pretty shaken up, tossing all caution and reservations to the wind all of a sudden. She means a lot to you, doesn't she?",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D74"
        },
        [10109012] = {
          Camera = "-673.512451,413.476562,88.712402,0.00009,0.800116,-28.901665,35.0,133.446106,false,DoNotOverride,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "낯선 곳에 홀로 떨어졌을 때 느끼는 그 기분 알지? 공처럼 이리저리 차이는 듯한 느낌. 그런데 그때 누군가 손을 내밀며 살아있으면 좋은 일이 생길 거라고 말해준다면.",
          DialogueId = 10109012,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-673.512451,413.476562,68.34668,0.00009,1.600095,-28.701653,35.0,133.446106,false,DoNotOverride,4.0",
          GUID = "194E8D75",
          NextDialogue = 10109013,
          SpeakNpcId = 100001,
          Subtitle = "Imagine being thrown into a foreign land all alone, feeling unwanted and helpless. Then, someone reaches out and encourages you to hang in there for good things to happen.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D75"
        },
        [10109013] = {
          Camera = "-74.655029,-88.005859,148.110352,0.000069,-3.600554,25.297005,35.0,133.446106,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "그 사람한테 무슨 일이라도 생기면 너도 뭐라도 하려고 할 거잖아.",
          DialogueId = 10109013,
          ExStoryInfo = "Player",
          FinalCamera = "-74.655029,-88.005859,148.110352,0.000069,-3.600575,25.297071,38.000008,133.446106,false,Manual,4.0",
          GUID = "194E8D76",
          NextDialogue = 10109014,
          SpeakNpcId = 100001,
          Subtitle = "If this person were in danger, you'd do anything to help, too.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D76"
        },
        [10109014] = {
          Camera = "151.343506,129.411133,82.873047,0.00011,10.400035,-132.08902,50.0,336.29483,false,Manual,5.0",
          ContentKR = "어쩌면 네가 맞을지도 몰라. 일단 해보고 맛보는 실패의 씁쓸함은 그래도 무수한 밤낮을 채우는 '왜 그때 더 용감하게 나서지 못했을까'라는 후회보다 나으니까.",
          DialogueId = 10109014,
          FinalCamera = "149.474121,131.097656,82.873047,0.00011,10.400035,-132.08902,50.0,336.29483,false,Manual,5.0",
          GUID = "194E8D9E",
          NextDialogue = 10109015,
          SpeakNpcId = 200021,
          Subtitle = "Maybe you're right. The bitterness of failure after trying beats the endless regret of \"Why wasn't I braver back then.\"",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101090/194E8D9E"
        },
        [10109015] = {
          Camera = "30.520752,3.698242,147.486328,0.000088,2.199717,-135.896973,50.0,143.403534,false,Manual,5.0",
          ContentKR = "하지만 기억해, '용감한 것'은 절대 '충동적인 것'과 같은 게 아냐. 용감함은... '이 길의 모든 종착지를 알고 있고, 또 그 모든 종착지를 의연하게 받아들이는 것'이야.",
          DialogueId = 10109015,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = "100001:Shock01",
            [3] = "200002:None"
          },
          GUID = "194E8DC8",
          NextDialogue = 10109016,
          SpeakNpcId = 200021,
          Subtitle = "But remember, being brave doesn't mean acting recklessly. Being brave is... saying \"I'm aware of all the possible endings of this path and I accept them all.\"",
          VoiceName = "voice/$Locale$/story/1002/101090/194E8DC8"
        },
        [10109016] = {
          Camera = "-691.339844,147.462891,407.783691,0.000107,-25.800226,-15.098549,30.0,581.186951,false,DoNotOverride,1.2",
          ContentKR = "그리고 '선택한 길에 들어서면, 어느 것에도 흔들리지 않게' 되지.",
          DialogueId = 10109016,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-758.953369,165.703125,441.637695,0.000107,-25.800226,-15.098549,30.0,581.186951,false,DoNotOverride,1.2",
