        },
        [10109704] = {
          Camera = "-96.394531,130.861328,78.214844,0.000252,-8.00076,-17.689077,25.0,125.918678,false,Manual,3.0",
          ContentKR = "이건...",
          DialogueId = 10109704,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Camera.T_Guide_Chapter01_Camera'}",
          ExStoryInfo = "Player",
