          DialogueId = 10109807,
          GUID = "194F1036",
          NextDialogue = 10109808,
          SpeakNpcId = 200006,
          Subtitle = "The sun's warmer there, and you get to see seasons change.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1036"
        },
        [10109808] = {
