          DialogueId = 10109808,
          GUID = "194F1060",
          NextDialogue = 10109809,
          SpeakNpcId = 200006,
          Subtitle = "When spring comes, the ice and snow melt away, and there are flowers everywhere, even in the wilds.",
          VoiceName = "voice/$Locale$/story/1002/101098/194F1060"
        },
        [10109809] = {
          ContentKR = "그때의 난 열차만 탈 수 있다면 그곳에 갈 수 있을 거라 생각했어.",
          DialogueId = 10109809,
          GUID = "194F108A",
          NextDialogue = 10109810,
          SpeakNpcId = 200006,
          Subtitle = "I always dreamed that if I could catch a train, I could actually get there.",
