CameraMoveTo{_delay{2.4},TargetPosition{"-115.301208,254.134064,42.93457,0.000008,12.800286,-45.021217,30.0,391.693146,false,Manual,4.0"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "I'd never heard of any Deteriorator regaining their self-consciousness, but Psyche briefly did it. With the last bit of sobriety, she shattered that filthy beast with her own hands, telling everyone that she would not surrender.",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101131/19512DA0"
