PlayAnimation{_delay{2},ActorId{200011},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{ActorId{200011},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200011,
          Subtitle = "Um, in a way! Thanks, I'm going after him.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101173/1953DEAE"
        },
        [10117401] = {
          ContentKR = "안개 구역 쓰레기 더미 쪽이라...",
          DialogueId = 10117401,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1953EE1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117402,
          SpeakNpcId = 100001,
          Subtitle = "...The rubbish bin in the Mist Aken."
        },
        [10117402] = {
          ContentKR = "3번 대형 쓰레기통이에요! 여기예요!",
          DialogueId = 10117402,
          Duration = 3,
          GUID = "1953EE44",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "He meant Big Bin No. 3! Now come with me!",
          VoiceName = "voice/$Locale$/story/1002/101174/1953EE44"
        },
        [10117501] = {
          ContentKR = "어서 가 보렴... 옛말에 뭐라 그랬더라? \"일찍 일어난 새가 쓰레기를 줍는다!\"였나?",
          DialogueId = 10117501,
          GUID = "1953FE82",
          SpeakNpcId = 200054,
          Subtitle = "Go get 'em! As the old saying goes, \"Strike while the rubbish is hot!\"",
          VoiceName = "voice/$Locale$/story/1002/101175/1953FE82"
        },
        [10117601] = {
          ContentKR = "이 근처엔 아무도 없네.",
          DialogueId = 10117601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19540EEA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10117602,
          SpeakNpcId = 100001,
          Subtitle = "It's quiet around here.",
          VoiceName = "voice/$Locale$/story/1002/101176/19540EEA"
        },
        [10117602] = {
          ContentKR = "...괜찮아요! 명탐정의 예리한 감각이 이 근처에 분명 단서가 있다고 말해주고 있어요!",
          DialogueId = 10117602,
          Duration = 3,
          GUID = "19540F14",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "...No worries! My detective instincts are telling me there's a clue nearby!",
          VoiceName = "voice/$Locale$/story/1002/101176/19540F14"
        }
      }
