          CameraBlendCurve = "easeInQuad",
          ContentKR = "잠깐, 둘 다 먼저 돌아와!",
          DialogueId = 10121003,
          FinalCamera = "35.885254,-0.811859,96.354614,0.000007,-1.999961,-84.0,35.0,223.618286,false,Manual,2.07011",
