        [10124501] = {
          Camera = "-12.330078,957.673828,58.328125,0.000111,0.998253,164.796356,50.000008,184.890427,false,Manual,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "지금쯤이면 이미 황혼이겠지? 노을 진 눈물의 호수, 정말 아름답지 않아?",
          DialogueId = 10124501,
          FinalCamera = "-13.130859,954.710938,58.328125,0.000111,0.998253,164.796356,50.000008,184.890427,false,Manual,5.0",
          GUID = "19587AF2",
          NextDialogue = 10124502,
          Scripts = [[
