        [10125905] = {
          Camera = "-119.442383,-114.433594,183.290039,0.000117,-11.966764,48.943577,50.000011,448.770081,false,Manual,3.0",
          ContentKR = "난 여행 중인데, 방황하는 영혼의 속삭임이 들려서 '그 아이'를 안개의 바다로 인도하러 왔단다.",
          DialogueId = 10125905,
          FacialId = {
            [1] = "200076:Sad01"
          },
          GUID = "1959614A",
          NextDialogue = 10125906,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Having journeyed here, I've heard the whispers of a wandering soul in this place; thus I've come to guide \"her\" back to the Misty Sea.",
          TalkActionId = {
            [1] = "200076:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/1959614A"
        },
