        },
        [10125911] = {
          Camera = "95.520508,198.755859,124.03125,5.001531,-13.799672,57.99501,20.000008,46.651825,false,Manual,4.0",
          ContentKR = "...제 친구예요.",
          DialogueId = 10125911,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19596246",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10125912,
          SpeakNpcId = 100001,
          Subtitle = "...She was a friend of mine.",
          VoiceName = "voice/$Locale$/story/1002/101259/19596246"
        },
        [10125912] = {
          ContentKR = "제가... 지켜주지 못했어요. 저한테... 실망했을 거예요.",
          DialogueId = 10125912,
          GUID = "19596270",
          NextDialogue = 10125913,
          SpeakNpcId = 100001,
          Subtitle = "I... I failed to protect her. She must be... disappointed in me.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596270"
        },
        [10125913] = {
          Camera = "96.016602,285.619141,103.054688,0.000066,7.001299,-64.589752,25.0,76.61264,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "아니란다, 오히려 그 반대였지. 난 후회와 원망으로 가득 찬 수많은 영혼을 보아왔단다. 그들의 통곡 소리는 강변의 안개처럼 짙었지.",
          DialogueId = 10125913,
          FinalCamera = "150.009766,289.806641,103.926758,0.000063,7.80125,-105.588699,25.0,76.61264,false,Manual,22.0",
          GUID = "1959629A",
          LookAt = {
            [1] = "100001:n(200076)"
          },
          NextDialogue = 10125914,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Quite the opposite. Many souls I've witnessed depart with intense grievances and bitterness, their cries thick as the fog along the riverbanks.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101259/1959629A"
        },
        [10125914] = {
          Camera = "1647.097656,1629.320312,80.411133,0.000092,-1.000056,-134.800735,50.000011,655.091675,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "하지만 그 아이가 가진 영혼의 목소리는 정말 따뜻했어. 한탄도, 분노도, 미련도 없이, 오히려 고마워하며... 축복을 빌더구나.",
          DialogueId = 10125914,
          FinalCamera = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0",
          GUID = "195962C4",
          LookAt = {
            [1] = "200076:p(P_101259Nifu3)"
          },
          NextDialogue = 10125915,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "But her voice was very gentle. It bore no sorrow, anger, nor resentment — only expressions of gratitude and... blessings.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101259/195962C4"
        },
        [10125915] = {
          Camera = "1720.431641,1626.798828,101.317383,0.000085,-1.000022,-137.800919,50.000008,655.091675,false,Manual,22.0",
          ContentKR = "아마 널 향한 축복이었을 거야.",
          DialogueId = 10125915,
          GUID = "195962EE",
          NextDialogue = 10125916,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Perhaps, those were meant for you.",
          VoiceName = "voice/$Locale$/story/1002/101259/195962EE"
        },
        [10125916] = {
          Camera = "219.347656,76.939453,145.862305,0.000099,-11.600249,129.794128,35.000008,102.30249,false,Manual,22.0",
          ContentKR = "하지만...",
          DialogueId = 10125916,
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "19596318",
          LookAt = {
            [1] = "100001:n(200076)"
          },
          NextOptions = {
            [1] = 101259161,
            [2] = 101259162
          },
          Scripts = "SetRotation{SetRotationDescription{\"200076:p(35)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "But...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596318"
        },
        [10125917] = {
          Camera = "686.332031,-345.896484,298.178711,0.000049,-16.400145,137.192245,15.000005,102.302483,false,DoNotOverride,6.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "아이야, 난 이 세상에서 아주아주 오래 살면서 무수한 영혼을 떠나보냈고 그런 말을 무수히 들었단다.",
          DialogueId = 10125917,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "791.003906,-442.84375,340.171875,0.000049,-16.400145,137.192215,15.000005,102.302483,false,DoNotOverride,6.0",
          GUID = "19596342",
          LookAt = {
            [1] = "200076:n(200076)"
          },
          NextDialogue = 10125918,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Child, I have lived long and bid farewell to countless souls, and I've heard such words time and again.",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200076:p(180)"
          },
          VoiceName = "voice/$Locale$/story/1002/101259/19596342"
        },
        [10125918] = {
          Camera = "180.162109,98.261719,148.519531,0.000071,-14.39885,123.596199,30.0,102.302483,false,DoNotOverride,6.0",
          ContentKR = "초목은 산불에 잿더미가 되고, 작은 곤충은 광풍에 깊은 물속으로 스러지지... 죽음은 본디 생명의 일부란다. 이르든 늦든 찾아오기 마련이지.",
          DialogueId = 10125918,
          FacialId = {
            [1] = "200076:Unhappy01"
          },
          FinalCamera = "189.610352,84.568359,152.894531,0.000069,-14.998897,125.396011,30.0,102.302483,false,DoNotOverride,6.0",
          GUID = "1959636C",
          NextDialogue = 10125919,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Just as plants succumb to wildfires and bugs perish in storms... Impermanence is a part of life. Sooner or later, death touches us all.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101259/1959636C"
        },
        [10125919] = {
          Camera = "165.951172,300.587891,72.796875,-5.000034,16.399078,-113.601227,25.000002,192.424774,false,Manual,4.0",
          ContentKR = "운명의 차가움과 잔혹함을 저주하거나 자신의 나약함을 한탄할 수도 있겠지만, 우린... 추억을 소중히 여기는 길을 선택할 수도 있어.",
          DialogueId = 10125919,
          GUID = "19596396",
          LookAt = {
            [1] = "200076:n(100001)"
          },
          NextDialogue = 10125920,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Rather than cursing fate's indifference and cruelty, or lamenting our frailty, we can choose to... cherish the memories we hold dear.",
          VoiceName = "voice/$Locale$/story/1002/101259/19596396"
        },
        [10125920] = {
          Camera = "195.244141,88.742188,144.28125,-5.000003,-9.599489,131.589844,25.0,72.421944,false,Manual,3.0",
          ContentKR = "죽음이 필연적인 거라면, 살아가는 매 순간은 죽음을 비켜간 '기적'이 아니겠니?",
          DialogueId = 10125920,
          GUID = "195963C0",
          LookAt = {
            [1] = "200076:n(200076)"
          },
          NextDialogue = 10125921,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "After all, if death is the inevitable, then every moment alive is a miracle that defies the odds, isn't it?",
          VoiceName = "voice/$Locale$/story/1002/101259/195963C0"
        },
        [10125921] = {
          Camera = "195.244141,88.742188,144.28125,-5.000003,-9.599489,131.589844,25.0,72.421944,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "안개의 바다로 떠난 그 영혼도... 네가 눈물이 아닌 미소를 띠며 함께했던 날들을 기억하길 바랄 거란다.",
          DialogueId = 10125921,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "177.079102,120.476562,136.115234,-5.000005,-11.999385,119.18969,25.0,160.052902,false,Manual,3.0",
          GUID = "195963EA",
          NextOptions = {
            [1] = 101259211
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5.0},TargetPosition{"164.480469,147.314453,126.589844,-5.000003,-5.199488,116.586655,35.0,79.720764,false,Manual,4.0"},duration{0}},
CameraMoveTo{_delay{5.1},TargetPosition{"153.261719,169.722656,124.316406,-5.000003,-5.199488,116.586655,35.0,79.720764,false,Manual,4.0"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "I believe that the gentle soul who journeyed to the Misty Sea would also wish that... when you recall your time together, you'd find yourself smiling, not crying with grief.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101259/195963EA"
        },
        [10125922] = {
          Camera = "284.724609,1376.494141,-241.195312,-2.5,6.600879,85.189873,9.202867,72.421944,false,DoNotOverride,3.0",
          ContentKR = "안개의 바다는... 카론의 생명이 시작되는 곳이자 안식의 땅이란다. 떠난 이의 영혼은 그곳으로 돌아가고 새 생명의 영혼은 그곳에서 태어나지. 생명은 그렇게 끊없이 이어진단다.",
          DialogueId = 10125922,
          FacialId = {
            [1] = "200076:Smile01"
          },
          FinalCamera = "284.724609,1376.494141,-128.970703,-2.499999,6.600879,89.999962,9.202867,72.421944,false,DoNotOverride,3.0",
          GUID = "19596414",
          NextDialogue = 10125923,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "The Misty Sea... is the cradle and resting place of life for Charons. Souls of the deceased return there, and the living emerge from it, life flowing in endless cycles.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101259/19596414"
        },
        [10125923] = {
          Camera = "145.720703,154.630859,133.727539,-2.499969,-10.399044,108.20134,30.0,99.420395,false,Manual,4.0",
          ContentKR = "그렇다면...",
          DialogueId = 10125923,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "1959643E",
          NextOptions = {
            [1] = 101259231,
            [2] = 101259232
          },
          SpeakNpcId = 100001,
          Subtitle = "If that's the case...",
          VoiceName = "voice/$Locale$/story/1002/101259/1959643E"
        },
        [10125924] = {
          Camera = "550.920898,582.548828,29.561523,-5.000001,-21.600601,-133.792847,10.000003,698.191711,false,Manual,11.0",
          ContentKR = "다른 이가 그런 질문을 한다면, 난 이렇게 답할 거란다. 삶과 죽음의 순환은 거스를 수 없는 세상의 이치라 인간의 힘으로는 결코 맞설 수 없다고.",
          DialogueId = 10125924,
          FacialId = {
            [1] = "200076:None"
          },
          FinalCamera = "550.920898,582.548828,29.561523,-5.000004,-1.800445,-136.792801,10.000003,698.191711,false,Manual,11.0",
          GUID = "19596468",
          NextDialogue = 10125925,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Were it someone else asking, my answer would be this: The cycle of life and death is a universal law, not to be defied by human might.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101259/19596468"
        },
        [10125925] = {
          Camera = "550.920898,582.548828,29.561523,-5.000004,-1.800445,-136.792801,10.000003,698.191711,false,Manual,11.0",
          ContentKR = "하지만 느껴져... 넌 특별한 운명을 짊어지고 있구나.",
          DialogueId = 10125925,
          FacialId = {
            [1] = "200076:Smile01"
          },
          GUID = "19596492",
          NextDialogue = 10125926,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.1},TargetPosition{"152.515625,319.517578,95.349609,-5.000006,10.198612,-101.407249,32.500004,193.806732,false,Manual,4.0"},duration{0}},
CameraMoveTo{_delay{4.2},TargetPosition{"147.56543,293.683594,100.081055,-5.000004,10.198612,-100.40712,32.500004,193.806732,false,Manual,4.0"},blend{"easeOutQuad"},duration{4}},
TurnTo{_delay{4},TurnToDescription{"200076:p(-180)"}},
PlayAnimation{_delay{5.5},ActorId{200076},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "However, child, I sense... you are bound by an unusual destiny.",
          VoiceName = "voice/$Locale$/story/1002/101259/19596492"
        },
        [10125926] = {
          Camera = "708.042969,-427.089844,232.430664,-5.000006,-12.598386,132.779541,18.000004,1651574.625,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "언젠가 네가 충분한 힘을 얻어 세상의 진실을 마주하고, 나아가 그 법칙마저 바꿀 수 있게 된다면...",
          DialogueId = 10125926,
          FinalCamera = "708.042969,-427.089844,232.430664,-5.000006,-7.998356,118.776794,18.000004,1651574.625,false,DoNotOverride,22.0",
          GUID = "195964BC",
          NextDialogue = 10125927,
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "One day, when you have garnered enough strength to confront this world's unveiled truths and even challenge its very laws... ",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101259/195964BC"
        },
        [10125927] = {
          ContentKR = "어쩌면 네가 그 생명의 강을 건너, 그 끝인 안개의 바다에서, 떠난 영혼들과 다시 만날 수 있을지도 몰라.",
          DialogueId = 10125927,
          GUID = "195964E6",
          NextOptions = {
            [1] = 101259271
          },
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Perhaps then might you step into the river of life, to its terminus — the Misty Sea, where the departed souls await beyond the veil of time.",
          VoiceName = "voice/$Locale$/story/1002/101259/195964E6"
        },
        [10125928] = {
          Camera = "604.604492,4438.609375,-186.418945,0.000086,-1.000513,-99.205025,24.0,79896.75,false,Manual,22.0",
          ContentKR = "후훗... 난 강가에 머무는 한낱 방관자에 불과하단다. 그 질문의 답은 네가 직접 찾아야만 하지.",
          DialogueId = 10125928,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "19596510",
          NextDialogue = 10125929,
          Scripts = "CameraMoveTo{_delay{3.0},TargetPosition{\"154.625,310.175781,110.634766,0.000082,4.398683,-105.211761,25.0,196.124695,false,Manual,4.0\"},duration{0}}",
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Hehe... I am merely an observer by the riverbank. The answer to this question must be discovered by yourself.",
          VoiceName = "voice/$Locale$/story/1002/101259/19596510"
        },
        [10125929] = {
          Camera = "131.395508,182.603516,129.605469,0.000109,-12.600892,102.794952,25.0,56.213341,false,Manual,22.0",
          ContentKR = "마음 속에 갈망을 품고 있다면 계속 앞으로 나아가 보렴.",
          DialogueId = 10125929,
          FacialId = {
            [1] = "100001:Shock02"
          },
          FinalCamera = "134.668945,169.046875,132.874023,0.000097,-13.400926,103.79464,25.0,83.006569,false,Manual,22.0",
          GUID = "1959653A",
          NextDialogue = 10125930,
          Scripts = [[
SEQ{
SetLocation{ActorId{200076},TargetPoint{"P_101259Nifu2"},Visibility{"Hide"}}
}]],
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "If your heart truly yearns for it, then proceed on your path.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101259/1959653A"
        },
        [10125930] = {
          Camera = "677.972656,898.259766,768.71582,0.000071,-39.198925,-126.606758,18.0,56.213341,false,Manual,22.0",
          ContentKR = "행운이 너와 함께하길 빈단다, 아이야.",
          DialogueId = 10125930,
          FinalCamera = "765.867188,1016.578125,888.923828,0.000071,-39.198925,-126.606758,18.0,56.213341,false,Manual,22.0",
          GUID = "19596564",
          SpeakNpcId = 200076,
          SpeakNpcName = "UI_Npc_Name_Nifu",
          Subtitle = "Godspeed, dear child.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101259/19596564"
        },
        [10125931] = {
          ContentKR = "(안개의 바다... 떠난 이의 영혼...)",
          DialogueId = 10125931,
          DisableMouth = 1,
          GUID = "19596565",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10125932,
          SpeakNpcId = 100001,
          Subtitle = "(The Misty Sea... Departed souls...)",
          VoiceName = "voice/$Locale$/story/1002/101259/19596565"
        },
        [10125932] = {
          ContentKR = "(세상의 진실... 그 법칙...)",
          DialogueId = 10125932,
          DisableMouth = 1,
          GUID = "19596566",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(The world's truths and its laws...)",
          VoiceName = "voice/$Locale$/story/1002/101259/19596566"
        },
        [10126001] = {
          Camera = "21.271936,1262.868164,169.894531,0.000235,-0.800724,-92.056824,30.0,1303.695801,false,DoNotOverride,1.2",
          DialogueId = 10126001,
          GUID = "1959710A"
        },
        [10127001] = {
          Camera = "-261.964844,-143.53418,117.835449,0.000286,-8.398476,29.395039,18.0,411.462158,false,DoNotOverride,2.0",
          ContentKR = "포대기가 들어 있던 작은 요람은 이제 먼지가 가득 쌓여 있다.",
          DialogueId = 10127001,
          GUID = "195A151A",
          Subtitle = "A tiny cradle, once a sanctuary for new life, now covered in dust.",
          VoiceName = "voice/$Locale$/story/1002/101270/195A151A"
        },
        [10127002] = {
          Camera = "-175.474609,0.638672,49.867432,0.0,0.0,0.0,15.0,142.471756,false,DoNotOverride,2.0",
          ContentKR = "바닥에 흩어진 블록 조각들은 누군가에게 거칠게 무너뜨려진 것처럼 보인다.",
          DialogueId = 10127002,
          GUID = "195A1544",
          Subtitle = "Wooden blocks lie scattered across the floor, as if they were knocked over in frustration.",
          VoiceName = "voice/$Locale$/story/1002/101270/195A1544"
        },
        [10127003] = {
          Camera = "-92.993164,-100.354492,108.179443,0.000091,-34.999081,38.198757,20.0,138.826813,false,DoNotOverride,2.0",
          ContentKR = "메모지에는 당신의 '죄목'이 휘갈겨 적혀있다.",
          DialogueId = 10127003,
          GUID = "195A156E",
          Subtitle = "A hastily written report, filled with accusations of your \"crimes.\"",
          VoiceName = "voice/$Locale$/story/1002/101270/195A156E"
        },
        [10127004] = {
          ContentKR = "눈물이 그녀의 주름진 두 눈 아래로 조용히 흘러내렸다.",
          DialogueId = 10127004,
          GUID = "195A1598",
          Subtitle = "Two silent tears trickle down her weathered cheeks.",
          VoiceName = "voice/$Locale$/story/1002/101270/195A1598"
        },
        [10127005] = {
          Camera = "101.757812,-139.77832,28.292236,0.000069,0.600367,129.191574,12.5,133.732285,false,DoNotOverride,2.0",
          ContentKR = "아침 이슬을 머금은 흰 꽃이 바닥에 쓰러져 있고, 꽃잎은 볼품없이 흐트러져 있다.",
          DialogueId = 10127005,
          GUID = "195A15C2",
          Subtitle = "A delicate white flower, fresh with morning dew, lies trampled on the ground, its petals scattered.",
          VoiceName = "voice/$Locale$/story/1002/101270/195A15C2"
        },
        [10127006] = {
          ContentKR = "먼지 털기",
          DialogueId = 10127006,
          GUID = "195A15EC",
          Subtitle = "Brush off the dust"
        },
        [10127007] = {
          ContentKR = "쌓기",
          DialogueId = 10127007,
          GUID = "195A1616",
          Subtitle = "Stack up"
        },
        [10127008] = {
          ContentKR = "펜으로 지우기",
          DialogueId = 10127008,
          GUID = "195A1640",
          Subtitle = "Cross off"
        },
        [10127009] = {
          ContentKR = "그녀의 눈물 닦아주기",
          DialogueId = 10127009,
          GUID = "195A166A",
          Subtitle = "Wipe her tears"
        },
        [10127010] = {
          ContentKR = "꽃송이 복구",
          DialogueId = 10127010,
          GUID = "195A1694",
          Subtitle = "Fix the flower"
        },
        [10127011] = {
          ContentKR = "여기서 쉬었다가 가자",
          DialogueId = 10127011,
          GUID = "195A16BE",
          Subtitle = "Rest here"
        },
        [10128001] = {
          Camera = "2092.79834,-850.263184,574.188477,0.000034,-19.801502,119.803421,10.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10128001,
          FinalCamera = "2149.577148,-817.741333,574.188477,0.000037,-19.801476,122.803436,10.0,100000.0,false,Disable,2.8",
          GUID = "195AB92A",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101280/195AB92A"
        },
        [10128002] = {
          Camera = "964.108154,1014.200562,-209.061523,0.000064,-5.201202,-74.993759,15.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10128002,
          FinalCamera = "876.738525,985.802246,-209.061523,0.000063,-5.201202,-71.993752,15.0,100000.0,false,Disable,2.8",
          GUID = "195AB954",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101280/195AB954"
        },
        [10128101] = {
          ContentKR = "제발 들여보내 주세요. 저희는 그저 장작을 팔고 빵을 좀 사려고 하는 것 뿐입니다…",
          DialogueId = 10128101,
          GUID = "195AC992",
          NextDialogue = 10128102,
          SpeakNpcId = 200089,
          Subtitle = "Please, sir... just let us through. We're only here to sell firewood and maybe buy a little bread...",
          VoiceName = "voice/$Locale$/story/1002/101281/195AC992"
        },
        [10128102] = {
          ContentKR = "통행증이 필요하다는 말은 처음 들어요. 장교님, 제발 좀 봐 주세요. 집에 먹을 게 바닥이 났어요.",
          DialogueId = 10128102,
          GUID = "195AC9BC",
          NextDialogue = 10128103,
          SpeakNpcId = 200089,
          Subtitle = "No one told us we needed a travel permit. Please, sir... we're running out of food back home...",
          VoiceName = "voice/$Locale$/story/1002/101281/195AC9BC"
        },
        [10128103] = {
          ContentKR = "어디서 불평이야. 나라고 좋아서 이러는 줄 알아? 항상 너희같은 카론들이 모여서 소란을 피우니까 그러지.",
          DialogueId = 10128103,
          GUID = "195AC9E6",
          NextDialogue = 10128104,
          SpeakNpcId = 200071,
          Subtitle = "You think I want to stand here all day checking that thing? If you lot didn't keep gathering in groups and stirring up trouble, we wouldn't even need them.",
          VoiceName = "voice/$Locale$/story/1002/101281/195AC9E6"
        },
        [10128104] = {
          ContentKR = "포세이큰 동맹이라는 거, 알지? 제국에 항거하는 놈들 말이야. 통행증은 바로 그놈들을 걸러내려고 만든 거라고. 원망하려면 골칫거리 동족들을 원망해.",
          DialogueId = 10128104,
          GUID = "195ACA10",
          NextDialogue = 10128105,
          SpeakNpcId = 200071,
          Subtitle = "Heard of The Forsakens, the ones stirring up chaos all over? These permits are meant to catch their kind. So if you're looking for someone to blame, start with your own people.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA10"
        },
        [10128105] = {
          ContentKR = "포세이큰 동맹이 뭔지도 모릅니다요... 그럼 장교님, 어디서 그... 그 통행증을 만들 수 있는지 제발 좀 알려 주세요.",
          DialogueId = 10128105,
          GUID = "195ACA3A",
          NextDialogue = 10128106,
          SpeakNpcId = 200089,
          Subtitle = "But I don't know anything about The Forsakens... Alright, sir, could you tell me where to get one of these... travel permits?",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA3A"
        },
        [10128106] = {
          ContentKR = "치안서에 직접 가서 줄 서서 신청하라고!",
          DialogueId = 10128106,
          GUID = "195ACA64",
          NextDialogue = 10128107,
          SpeakNpcId = 200071,
          Subtitle = "Go queue at the Security Bureau.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA64"
        },
        [10128107] = {
          ContentKR = "치안서가... 성 안에 있는데요...",
          DialogueId = 10128107,
          GUID = "195ACA8E",
          NextDialogue = 10128108,
          SpeakNpcId = 200089,
          Subtitle = "The Security Bureau...? But that's inside the city...",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACA8E"
        },
        [10128108] = {
          ContentKR = "그건 내 알 바 아니니 알아서 하라고. 귀찮게 하지 마. 그나마 내가 성격이 좋길래 망정이지, 성질 고약한 사람한테 걸렸으면 총 맞아 뒈져도 네 시체를 거둘 놈 하나 없을 거다.",
          DialogueId = 10128108,
          GUID = "195ACAB8",
          NextDialogue = 10128109,
          SpeakNpcId = 200071,
          Subtitle = "Not my problem. Sort it out yourself, and don't come bothering me again. Count yourself lucky I'm not one of the trigger-happy types — they'd shoot first and let the worms handle the rest.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAB8"
        },
        [10128109] = {
          ContentKR = "어차피 윗사람들은 모든 카론을 잠재적인 포세이큰 동맹 분자로 본다고. 그러니 알아서 해.",
          DialogueId = 10128109,
          GUID = "195ACAE2",
          SpeakNpcId = 200071,
          Subtitle = "As far as the higher-ups are concerned, every Charon's a potential Forsaken sympathiser. So yeah — good luck.",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE2"
        },
        [10128110] = {
          ContentKR = "얼마 전까지만 해도 통행증이 필요 없었는데요...",
          DialogueId = 10128110,
          GUID = "195ACAE3",
          NextDialogue = 10128111,
          SpeakNpcId = 200089,
          Subtitle = "But we didn't need a travel permit last time, sir...",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE3"
        },
        [10128111] = {
          ContentKR = "어디서 불평이야, 내가 하고 싶은 소리라고! 이것도 다 상부의 명령이다!",
          DialogueId = 10128111,
          GUID = "195ACAE4",
          Subtitle = "Don't start whining. Orders are orders — you think I like doing this!?",
          VoiceName = "voice/$Locale$/story/1002/101281/195ACAE4"
        },
        [10128201] = {
          ContentKR = "나도 오늘 통행증을 안 가져왔는데...",
          DialogueId = 10128201,
          GUID = "195AD9FA",
          SpeakNpcId = 200090,
          Subtitle = "Forgot my travel permit today too...",
          VoiceName = "voice/$Locale$/story/1002/101282/195AD9FA"
        },
        [10128202] = {
          ContentKR = "나도 오늘 통행증을 안 가지고 나왔는데, 그 자리에서 끌려가지 않아서 다행이야…",
          DialogueId = 10128202,
          GUID = "195ADA24",
          NextOptions = {
            [1] = 101282021,
            [2] = 101282022,
            [3] = 101282023
          },
          SpeakNpcId = 200090,
          Subtitle = "I forgot my permit today too. Lucky they didn't drag me off to a cell...",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADA24"
        },
        [10128204] = {
          ContentKR = "사실 별 중요한 것도 아니야. 포세이큰 동맹이 들어오는 걸 막기 위해서라지만, 작정하고 일 저지를 놈들이 정문으로 들어오겠어?",
          DialogueId = 10128204,
          GUID = "195ADA78",
          NextDialogue = 10128205,
          SpeakNpcId = 200090,
          Subtitle = "Important? Hah... I mean, they say it's to keep The Forsakens out. But if someone's really up to no good, do you think they're strolling through the front gate like it's nothing?",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADA78"
        },
        [10128205] = {
          ContentKR = "그냥 병사들에게 일반인을 괴롭힐 구실을 하나 더 준 거야. 통행증이 없다는 건 곧 수상하다는 증거가 되고...",
          DialogueId = 10128205,
          GUID = "195ADAA2",
          NextDialogue = 10128206,
          SpeakNpcId = 200090,
          Subtitle = "End of the day, it's just another excuse for the soldiers to push folk like us around. No permit? That makes you \"suspicious.\" Simple as that.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADAA2"
        },
        [10128206] = {
          ContentKR = "가지고 있는 쿠퍼를 다 바치면 웬만하면 넘어가지만, 운이 나쁘면... 방금 자네가 본 꼴이 나는 거야. 에휴...",
          DialogueId = 10128206,
          GUID = "195ADACC",
          NextOptions = {
            [1] = 101282061
          },
          SpeakNpcId = 200090,
          Subtitle = "Most days, you just slip them all the coins in your pocket and they look the other way. But if your luck runs out... well, you saw what happened. That was... brutal.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADACC"
        },
        [10128208] = {
          ContentKR = "있긴 해. 군단 지휘관이 제국에 인정받은 계관 카론이라면, 부하 병사들도 좀 자제하지.",
          DialogueId = 10128208,
          GUID = "195ADB20",
          NextDialogue = 10128209,
          SpeakNpcId = 200090,
          Subtitle = "Some, yeah. If the officer in charge is a Laurelled Charon, the soldiers under 'em usually act a bit better.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB20"
        },
        [10128209] = {
          ContentKR = "다들 아는 시빌라 군단장이나 새로 온 리듬 장교 같은 사람은 부하를 단속할 카론이야.",
          DialogueId = 10128209,
          GUID = "195ADB4A",
          NextDialogue = 10128210,
          SpeakNpcId = 200090,
          Subtitle = "Take Chief Sibylle and that new one, Officer Fischer for example — they keep their unit on a tight leash.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB4A"
        },
        [10128210] = {
          ContentKR = "얘기는 그만하고, 집에 가서 통행증을 가져와야겠어.",
          DialogueId = 10128210,
          GUID = "195ADB74",
          SpeakNpcId = 200090,
          Subtitle = "Anyway... I should go grab my permit before someone else decides I look \"suspicious.\"",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADB74"
        },
        [10128212] = {
          ContentKR = "처벌이라, 물론 처벌받지. 며칠 감금됐다가 벌금 좀 내면 그만이야.",
          DialogueId = 10128212,
          GUID = "195ADBC8",
          NextDialogue = 10128213,
          SpeakNpcId = 200090,
          Subtitle = "Punished? Sure. Maybe a couple nights in the brig, a slap-on-the-wrist fine. That's about it.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADBC8"
        },
        [10128213] = {
          ContentKR = "어쩔 수 없어. 여긴 휘페르보레아 제국이고, 카론은 솔라보다 한 등급 아래라고. 우리 카론이 진 탓이지.",
          DialogueId = 10128213,
          GUID = "195ADBF2",
          NextDialogue = 10128214,
          SpeakNpcId = 200090,
          Subtitle = "But what can we do? This is Hyperborea. Charons were born a rung below the Solas — all because we lost the war.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADBF2"
        },
        [10128214] = {
          ContentKR = "대륙 동쪽 끝에 화서라는 나라가 있다던데, 거긴 좀 다른 모양이야. 카론이 잘 살고 있다는군.",
          DialogueId = 10128214,
          GUID = "195ADC1C",
          NextOptions = {
            [1] = 101282141
          },
          SpeakNpcId = 200090,
          Subtitle = "I heard there's a place far out east, a nation called Huaxu. Word is, things are different there — Charons live proper lives.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC1C"
        },
        [10128216] = {
          ContentKR = "하, 카론은 뭐만 했다 하면 '카론 보호비'란 걸 뜯긴다고, 화서로 가는 비용도 하늘을 뚫는 듯 비싸고…",
          DialogueId = 10128216,
          GUID = "195ADC70",
          NextDialogue = 10128217,
          SpeakNpcId = 200090,
          Subtitle = "*sigh* Because they slap Charons with all sorts of \"supervision levies.\" Just being who we are costs extra. And the trip to Huaxu? That'd bleed me dry.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC70"
        },
        [10128217] = {
          ContentKR = "내 한 몸의 여비는 어찌어찌 한다 해도, 아내와 아이들이 있잖아... 아, 자네는 아직 젊으니, 기회가 있을 거야. 열심히 돈을 모아봐.",
          DialogueId = 10128217,
          GUID = "195ADC9A",
          SpeakNpcId = 200090,
          Subtitle = "Even if I managed to scrape together enough for myself, I've got my wife and kids to think about... But you — you're still young. Maybe you've got a shot. Save what you can.",
          VoiceName = "voice/$Locale$/story/1002/101282/195ADC9A"
        },
        [10128301] = {
          ContentKR = "이 달 들어 몇 번째야...",
          DialogueId = 10128301,
          GUID = "195AEA62",
          SpeakNpcId = 200091,
          Subtitle = "That's the third one this month...",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEA62"
        },
        [10128302] = {
          ContentKR = "이번 달 들어 벌써 몇 번째냐... 세 번째인가... 장사도 못 해먹겠구만. 포세이큰 동맹에라도 들어가야겠어.",
          DialogueId = 10128302,
          GUID = "195AEA8C",
          NextOptions = {
            [1] = 101283021,
            [2] = 101283022,
            [3] = 101283023
          },
          SpeakNpcId = 200091,
          Subtitle = "Third one this month... I reckon. What's the point of keeping my stall open anymore? Might as well join The Forsakens myself.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEA8C"
        },
        [10128304] = {
          ContentKR = "그래, 다들 통행증을 챙기지 않아 병사들과 실랑이하다가 포세이큰 동맹으로 몰려버렸지...",
          DialogueId = 10128304,
          GUID = "195AEAE0",
          NextDialogue = 10128305,
          SpeakNpcId = 200091,
          Subtitle = "Third Charon this month caught without a travel permit. They all argued with the guards and then got branded a member of The Forsakens...",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEAE0"
        },
        [10128305] = {
          ContentKR = "어떻게 이럴 수가 있나... 우리 카론이 솔라보다 열등하게 타고났다는 거야?",
          DialogueId = 10128305,
          GUID = "195AEB0A",
          NextDialogue = 10128306,
          SpeakNpcId = 200091,
          Subtitle = "Can you believe it? Treated like dirt — just because we're Charons and they're Solas.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB0A"
        },
        [10128306] = {
          ContentKR = "흠, 옛날 카론 대반란 때 우리가 이겼다면, 저들이 이렇게나 거만하게 군림할 수 있었을까? 참으로 안타깝구나...",
          DialogueId = 10128306,
          GUID = "195AEB34",
          NextOptions = {
            [1] = 101283061
          },
          SpeakNpcId = 200091,
          Subtitle = "Hmph. If we'd won the uprising, they wouldn't be walking around like they own the place. But we didn't — and here we are...",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB34"
        },
        [10128308] = {
          ContentKR = "자네, 모르나? 하긴, 나이도 젊어 보이니 대반란 때는 태어나지도 않았겠지. 부모님께 여쭤봐, 그때 제국 대부분의 카론이 대반란에 휘말렸으니까 아실 거야.",
          DialogueId = 10128308,
          GUID = "195AEB88",
          NextDialogue = 10128309,
          SpeakNpcId = 200091,
          Subtitle = "You don't know? Ah, figures. You look young. Probably weren't even born yet. Go ask your folks — back then, nearly every Charon in the Empire got swept up in it.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEB88"
        },
        [10128309] = {
          ContentKR = "당시 선봉대가 황성까지 쳐들어갔었는데, 마지막 순간에 패배했어... 그래서 지금 제국이 우리 카론을 철저히 통제하고 억압하는 거야.",
          DialogueId = 10128309,
          GUID = "195AEBB2",
          NextDialogue = 10128310,
          SpeakNpcId = 200091,
          Subtitle = "We got as far as the capital. Frontlines broke through — nearly took the place. But we lost it, right at the end. That's why they keep their boot on our necks now.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEBB2"
        },
        [10128310] = {
          ContentKR = "하지만 황제께서 이렇게 엉망으로 통치하면, 다음 전쟁도 시간문제일 거야.",
          DialogueId = 10128310,
          GUID = "195AEBDC",
          SpeakNpcId = 200091,
          Subtitle = "Still... the way His Majesty runs things these days, I wouldn't be surprised if another war breaks out soon enough.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEBDC"
        },
        [10128312] = {
          ContentKR = "왜? 같이 갈 텐가? 아니면 밀고라도 하게?",
          DialogueId = 10128312,
          GUID = "195AEC30",
          NextDialogue = 10128313,
          SpeakNpcId = 200091,
          Subtitle = "What, you interested? Or are you planning to rat me out?",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC30"
        },
        [10128313] = {
          ContentKR = "에휴, 그냥 화가 나서 한 말이야. 포세이큰 동맹이 카론들이 만든 반항 조직이라곤 하지만, 실제로 그들을 찾는 건 불가능에 가까워.",
          DialogueId = 10128313,
          GUID = "195AEC5A",
          NextDialogue = 10128314,
          SpeakNpcId = 200091,
          Subtitle = "...*sigh* I'm just blowing off steam. The Forsakens might be the Charon resistance, but even if you're Charon, it's nearly impossible to find them.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC5A"
        },
        [10128314] = {
          ContentKR = "지난 카론 대봉기에 실패한 이후, 그들은 극도로 비밀스럽게 활동하고 있어. 지금 그들이 몇 명인지, 본거지가 있는지, 어떻게 찾는지는 아무도 몰라.",
          DialogueId = 10128314,
          GUID = "195AEC84",
          NextDialogue = 10128315,
          SpeakNpcId = 200091,
          Subtitle = "After the uprising failed, they vanished underground. No one knows how many are left — or if they even meet at all anymore.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AEC84"
        },
        [10128315] = {
          ContentKR = "심지어 포세이큰 동맹이 이미 해체되었다는 사람들도 있어. 하지만 치안서의 무능한 놈들이 해결 못 하는 사건이 생기면 포세이큰 동맹 짓이라 보고하고 얼버무린다는군.",
          DialogueId = 10128315,
          GUID = "195AECAE",
          NextDialogue = 10128316,
          SpeakNpcId = 200091,
          Subtitle = "Some say they're long gone. That it's just the Security Bureau making things up — whenever they can't solve a case, they blame it on The Forsakens to save face.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AECAE"
        },
        [10128316] = {
          ContentKR = "하지만 나는 그들이 은밀하게 힘을 키우고 있다고 믿어. 언젠가 솔라들에게 피의 대가를 받아내겠지.",
          DialogueId = 10128316,
          GUID = "195AECD8",
          SpeakNpcId = 200091,
          Subtitle = "Still... I believe they're out there. Lying low, waiting. And when the time comes — the Solas will pay for every drop of blood they spilt.",
          VoiceName = "voice/$Locale$/story/1002/101283/195AECD8"
        },
        [10128401] = {
          ContentKR = "집이 꽤 크긴 한데, 으스스하네...",
          DialogueId = 10128401,
          GUID = "195AFACA",
          SpeakNpcId = 200092,
          Subtitle = "Big house, isn't it? Bit spooky, though...",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFACA"
        },
        [10128402] = {
          ContentKR = "이 집은 크지만, 으스스해. 돈이 있는 사람은 살기 싫어하고, 살고 싶은 사람은 살 돈이 없어.",
          DialogueId = 10128402,
          GUID = "195AFAF4",
          NextOptions = {
            [1] = 101284021,
            [2] = 101284022,
            [3] = 101284023,
            [4] = 101284024
          },
          SpeakNpcId = 200092,
          Subtitle = "Big house, sure... but definitely cursed. Folks who can afford it won't touch the place. And the ones who'd dare live here? Can't afford to own it.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFAF4"
        },
        [10128404] = {
          ContentKR = "그래, 몰랐어? 여기는 아이스레이크 시티의 두 유명한 유령 저택 중 하나야! 여기 머물렀던 사람들은 모두 제국의 탄압을 받거나 가족과 생이별했다고 해.",
          DialogueId = 10128404,
          GUID = "195AFB48",
          NextDialogue = 10128405,
          SpeakNpcId = 200092,
          Subtitle = "Of course! You haven't heard? This is one of the two most infamous cursed houses in Icelake! Everyone who's ever moved in either ran afoul of the Empire... or mysteriously vanished, separated from their loved ones.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB48"
        },
        [10128405] = {
          ContentKR = "그리고 그 다른 하나는 바로, 너희들이 방금 나왔던 히프노스의 집이야. 거기선 밤마다 울음소리가 들린대.",
          DialogueId = 10128405,
          GUID = "195AFB72",
          NextDialogue = 10128406,
          SpeakNpcId = 200092,
          Subtitle = "As for the other one — you just came from it — the Hypnos' House. They say if you stand near it at night, you can hear weeping through the walls.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB72"
        },
        [10128406] = {
          ContentKR = "음… 모든 게 헨릭과 관련이 있는 것 같아.",
          DialogueId = 10128406,
          GUID = "195AFB9C",
          SpeakNpcId = 200092,
          Subtitle = "Funny thing is... both houses happen to be owned by the same person — Henrik.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFB9C"
        },
        [10128408] = {
          ContentKR = "에이, 엿보기는 무슨? 이렇게 큰 집에 누가 새로 이사 오는지 궁금하지도 않아?",
          DialogueId = 10128408,
          GUID = "195AFBF0",
          NextDialogue = 10128409,
          SpeakNpcId = 200092,
          Subtitle = "Snooping? Come now — a mansion like this gets new tenants, and I'm not even allowed a little curiosity?",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFBF0"
        },
        [10128409] = {
          ContentKR = "난 말이야, 아이스레이크 시티에 있는 집들은 속속들이 다 파악하고 있어. 집집마다 일일이 찾아다녔지만, 지금까지 엿본다고 비난받은 적 없어.",
          DialogueId = 10128409,
          GUID = "195AFC1A",
          NextDialogue = 10128410,
          SpeakNpcId = 200092,
          Subtitle = "I know every household in Icelake — top to bottom, side to side. All from good old-fashioned asking around, mind you. Never once been accused of \"snooping.\"",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC1A"
        },
        [10128410] = {
          ContentKR = "하지만 그렇게 말하니, 여기서 더 이상 민폐 끼치지 않을게. 그럼 이만 가보겠네~ 우린 언젠가 다시 만날 거야.",
          DialogueId = 10128410,
          GUID = "195AFC44",
          SpeakNpcId = 200092,
          Subtitle = "But if I'm making you uncomfortable... I'll be on my way. I have a feeling we'll cross paths again.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC44"
        },
        [10128412] = {
          ContentKR = "나? 어머나, 난 글을 써서 돈을 버는 사람이야, 그냥 대기자 안수즈라고 불러 줘.",
          DialogueId = 10128412,
          GUID = "195AFC98",
          NextDialogue = 10128413,
          SpeakNpcId = 200092,
          Subtitle = "Me? Just someone who lives off ink and paper. You can call me Ansuz — intrepid journalist extraordinaire!",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFC98"
        },
        [10128413] = {
          ContentKR = "아이스레이크 시티에서 소식을 모아 글로 쓰고, 신문으로 발행해서 즐거움을 전하지.",
          DialogueId = 10128413,
          GUID = "195AFCC2",
          NextDialogue = 10128414,
          SpeakNpcId = 200092,
          Subtitle = "I go where the whispers lead, unearth the truth, and weave it into tales to bring a bit of cheer to the fine folks of Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFCC2"
        },
        [10128414] = {
          ContentKR = "못 믿겠나 봐? 자, 이거. 오늘 자 〈아이스레이크 시티 모닝 포스트〉야. 공짜로 줄 테니 마음에 들면 다음엔 사서 봐.",
          DialogueId = 10128414,
          GUID = "195AFCEC",
          NextDialogue = 10128415,
          SpeakNpcId = 200092,
          Subtitle = "What's with that look? Go on, take one — today's issue of the Icelake Daily. On the house. If you like what you read, come find me for the next one.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFCEC"
        },
        [10128415] = {
          ContentKR = "물론, 기사거리가 있으면 나를 찾아와. 무료로 교환해 줄게.",
          DialogueId = 10128415,
          GUID = "195AFD16",
          SpeakNpcId = 200092,
          Subtitle = "And if you've got a juicy lead, come find me — I'll trade you a fresh copy for it.",
          VoiceName = "voice/$Locale$/story/1002/101284/195AFD16"
        },
        [10128501] = {
          ContentKR = "마르제 누나가 생활비를 가져왔어.",
          DialogueId = 10128501,
          GUID = "195B0B32",
          NextDialogue = 10128502,
          SpeakNpcId = 200093,
          Subtitle = "Miss Margie brought the money again!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B32"
        },
        [10128502] = {
          ContentKR = "언제까지나 이렇게 살 순 없어.",
          DialogueId = 10128502,
          GUID = "195B0B5C",
          SpeakNpcId = 200094,
          Subtitle = "But we can't rely on her forever.",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B5C"
        },
        [10128503] = {
          ContentKR = "마르제 누나가 이번 달 생활비를 가져왔어. 이제 월말에 굶지 않아도 되겠네. 마르제 누나 정말 좋아!",
          DialogueId = 10128503,
          GUID = "195B0B86",
          NextDialogue = 10128504,
          SpeakNpcId = 200093,
          Subtitle = "Miss Margie brought us the money again — we won't have to worry about going hungry this month! She's the best!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0B86"
        },
        [10128504] = {
          ContentKR = "어디서 들었는데, 전에 도둑을 맞아서 이 생활비가 다 없어질 뻔했어. 마르제 언니와 착한 월석 사냥꾼이 겨우 되찾아온 거래.",
          DialogueId = 10128504,
          GUID = "195B0BB0",
          NextDialogue = 10128505,
          SpeakNpcId = 200094,
          Subtitle = "I heard someone tried to steal it. Miss Margie and a kind Phoxhunter went through a lot just to get it back.",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0BB0"
        },
        [10128505] = {
          ContentKR = "이건 안 되잖아, 이렇게 살 순 없어. 마르제 언니에게만 의지하면 안 돼. 언니에게 무슨 일이 생기면, 계속 굶주려야 하는 거야?",
          DialogueId = 10128505,
          GUID = "195B0BDA",
          NextDialogue = 10128506,
          SpeakNpcId = 200094,
          Subtitle = "We can't keep going like this. It's not right. We're depending on her too much... If — stars forbid — something ever happened to Miss Margie, what would we do? Just sit here and starve?",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0BDA"
        },
        [10128506] = {
          ContentKR = "많이 먹고 힘이 세 지면, 나도 월석 사냥꾼이 되어 마르제 누나를 도울 수 있을 텐데.",
          DialogueId = 10128506,
          GUID = "195B0C04",
          NextDialogue = 10128507,
          SpeakNpcId = 200093,
          Subtitle = "If I eat enough and grow strong, maybe I can become a Phoxhunter too! Then I'll help Miss Margie!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C04"
        },
        [10128507] = {
          ContentKR = "그럼 더 먹어. 난 이 과자 다 못 먹겠으니까 반 줄게. 네가 마르제 언니의 삽보다 더 크게 자라면, 언니 대신 빈민가 사람들을 위해 생활비를 모아 줘.",
          DialogueId = 10128507,
          GUID = "195B0C2E",
          NextDialogue = 10128508,
          SpeakNpcId = 200094,
          Subtitle = "Then eat up. Here — I can't finish this biscuit, so take half. When you're taller than Miss Margie's shovel, you can take her place... and start looking after everyone here in the slums.",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C2E"
        },
        [10128508] = {
          ContentKR = "좋아. 하지만 그때쯤이면 여기 사는 사람들 모두 배불리 먹고, 더 이상 돈을 얻어 구제받을 필요가 없을 거라고 믿어.",
          DialogueId = 10128508,
          GUID = "195B0C58",
          NextDialogue = 10128509,
          SpeakNpcId = 200093,
          Subtitle = "Okay! But I bet by then, no one here will have to starve anymore. We won't need anyone's charity ever again!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C58"
        },
        [10128509] = {
          ContentKR = "그런 날이 오면 좋겠다. 그때는 마르제 언니와 모두가 이렇게 힘들지 않아도 될 텐데... 아, 그렇게 게걸스럽게 먹으니 정말 못생겼네.",
          DialogueId = 10128509,
          GUID = "195B0C82",
          NextDialogue = 10128510,
          SpeakNpcId = 200094,
          Subtitle = "If only that day would come... Then Miss Margie — and the rest of us — wouldn't have to struggle so hard anymore. Ugh, slow down — no one's taking your food, you know...",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0C82"
        },
        [10128510] = {
          ContentKR = "음... 으음...",
          DialogueId = 10128510,
          GUID = "195B0CAC",
          SpeakNpcId = 200093,
          Subtitle = "Nom nom... mmph...!",
          VoiceName = "voice/$Locale$/story/1002/101285/195B0CAC"
        },
        [10128601] = {
          ContentKR = "8시가 다 되어 가네...",
          DialogueId = 10128601,
          GUID = "195B1B9A",
          SpeakNpcId = 200092,
          Subtitle = "Nearly eight o'clock, isn't it...?",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1B9A"
        },
        [10128602] = {
          ContentKR = "친구와 8시에 아스포델에서 만나기로 했는데, 회중시계를 안 가져왔어. 그래서 여기로 왔지. 헨릭이 나타나면 8시가 됐다는 뜻이거든.",
          DialogueId = 10128602,
          GUID = "195B1BC4",
          NextOptions = {
            [1] = 101286021,
            [2] = 101286022,
            [3] = 101286023
          },
          SpeakNpcId = 200092,
          Subtitle = "I'm supposed to meet a friend at The Asphodel at eight, but I forgot my pocket watch. So I came here instead. Once I spot Henrik, I'll know it's exactly eight on the dot.",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1BC4"
        },
        [10128604] = {
          ContentKR = "헨릭이 오랫동안 유지해 온 습관이거든. 그렇게 고지식한 사람이니까 정해진 시간에 외출하고, 정해진 시간에 식사 하는 거야.",
          DialogueId = 10128604,
          GUID = "195B1C18",
          NextDialogue = 10128605,
          SpeakNpcId = 200092,
          Subtitle = "Oh, I just know. Henrik's like clockwork — always steps out the door at the exact same time, eats at the exact same time...",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C18"
        },
        [10128605] = {
          ContentKR = "숨 쉬는 것도 일정한 리듬으로, 의식적으로 조절하는 게 아닐까? 아, 그래. 〈규칙적인 생활, 인생을 파악한다〉라는 제목으로 글을 써볼까. 어때?",
          DialogueId = 10128605,
          GUID = "195B1C42",
          SpeakNpcId = 200092,
          Subtitle = "Honestly, I wouldn't be surprised if he breathes on a schedule. Actually, that might make a good headline — \"Live By the Clock: Take Back Control.\" Catchy, right?",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C42"
        },
        [10128607] = {
          ContentKR = "나? 어머나, 난 글을 써서 돈을 버는 사람이야, 그냥 대기자 안수즈라고 불러 줘.",
          DialogueId = 10128607,
          GUID = "195B1C96",
          NextDialogue = 10128608,
          SpeakNpcId = 200092,
          Subtitle = "Me? Just someone who lives off ink and paper. You can call me Ansuz — intrepid journalist extraordinaire!",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1C96"
        },
        [10128608] = {
          ContentKR = "아이스레이크 시티에서 소식을 모아 글로 쓰고, 신문으로 발행해서 즐거움을 전하지.",
          DialogueId = 10128608,
          GUID = "195B1CC0",
          NextDialogue = 10128609,
          SpeakNpcId = 200092,
          Subtitle = "I go where the whispers lead, unearth the truth, and weave it into tales to bring a bit of cheer to the fine folks of Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1CC0"
        },
        [10128609] = {
          ContentKR = "못 믿겠나 봐? 자, 이거. 오늘 자 〈아이스레이크 시티 모닝 포스트〉야. 공짜로 줄 테니 마음에 들면 다음엔 사서 봐.",
          DialogueId = 10128609,
          GUID = "195B1CEA",
          NextDialogue = 10128610,
          SpeakNpcId = 200092,
          Subtitle = "What's with that look? Go on, take one — today's issue of the Icelake Daily. On the house. If you like what you read, come find me for the next one.",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1CEA"
        },
        [10128610] = {
          ContentKR = "물론, 기사거리가 있으면 나를 찾아와. 무료로 교환해 줄게.",
          DialogueId = 10128610,
          GUID = "195B1D14",
          SpeakNpcId = 200092,
          Subtitle = "And if you've got a juicy lead, come find me — I'll trade you a fresh copy for it.",
          VoiceName = "voice/$Locale$/story/1002/101286/195B1D14"
        },
        [10128701] = {
          ContentKR = "에휴... 기사는 안 쓰는 게 낫겠네.",
          DialogueId = 10128701,
          GUID = "195B2C02",
          SpeakNpcId = 200092,
          Subtitle = "*sigh* Maybe I shouldn't write about it...",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2C02"
        },
        [10128702] = {
          ContentKR = "에휴... 기사는 안 쓰는 게 낫겠네. 온 신문 지면에 안 좋은 소식만 가득해서, 사람들 기분만 잡칠 것 같아.",
          DialogueId = 10128702,
          GUID = "195B2C2C",
          NextOptions = {
            [1] = 101287021,
            [2] = 101287022,
            [3] = 101287023,
            [4] = 101287024
          },
          SpeakNpcId = 200092,
          Subtitle = "*sigh* Maybe I shouldn't write about it at all... Bad news is all there is these days. No sense dragging folks down even further.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2C2C"
        },
        [10128704] = {
          ContentKR = "무슨 기사겠어... 그 소녀에 관한 기사 말이지. 헨릭이 없으니 막는 사람도 없길래, 들어가서 다 알아냈어.",
          DialogueId = 10128704,
          GUID = "195B2C80",
          NextDialogue = 10128705,
          SpeakNpcId = 200092,
          Subtitle = "What else? That poor girl. Now that Henrik's out of the picture, I managed to poke around — pieced together most of the truth.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2C80"
        },
        [10128705] = {
          ContentKR = "나는 〈아이스레이크 시티 모닝 포스트〉로 즐거움과 활력을 주고 싶었어. 하지만 아이스레이크 시티에는 안 좋은 일이 너무 많아.",
          DialogueId = 10128705,
          GUID = "195B2CAA",
          NextDialogue = 10128706,
          SpeakNpcId = 200092,
          Subtitle = "I started the Icelake Daily hoping to bring people a little light. Maybe even a laugh or two. But honestly? There's just too much darkness in this city.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2CAA"
        },
        [10128706] = {
          ContentKR = "전날 보도에 나온 장인 부자가 다음 날 길거리에서 죽을 수도 있고, 인터뷰 예정이었던 카론 시인은 얼마 후 완전히 미쳐버릴 수도 있어.",
          DialogueId = 10128706,
          GUID = "195B2CD4",
          NextDialogue = 10128707,
          SpeakNpcId = 200092,
          Subtitle = "That father and son I wrote about yesterday? Might be lying in a gutter tomorrow. The Charon poet I was planning to interview? Could lose her mind before I even get the chance.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2CD4"
        },
        [10128707] = {
          ContentKR = "눈물의 호수 위에 떨어진 눈처럼, 얼음 알갱이가 되어 아무도 신경 쓰지 않아. 하지만 나는 믿어, 이 얼음이 녹으면 아이스레이크 시티 전체가 무너질 거야.",
          DialogueId = 10128707,
          GUID = "195B2CFE",
          SpeakNpcId = 200092,
          Subtitle = "We're like snowflakes falling over Lamenting Lake — fleeting, fragile... and once frozen into the ice, forgotten. But I believe... when that ice finally cracks, this whole city's going to come crashing down with it.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2CFE"
        },
        [10128709] = {
          ContentKR = "있겠지. 지금은 없지만, 언젠가는 일어날 거야.",
          DialogueId = 10128709,
          GUID = "195B2D52",
          NextDialogue = 10128710,
          SpeakNpcId = 200092,
          Subtitle = "Maybe not yet... but there will be.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2D52"
        },
        [10128710] = {
          ContentKR = "너무 슬퍼하지 마, 장담할게. 우리 카론이 반항을 시작할 날이 멀지 않으니까.",
          DialogueId = 10128710,
          GUID = "195B2D7C",
          SpeakNpcId = 200092,
          Subtitle = "Don't lose heart. Trust me — the day we Charons rise again isn't so far away.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2D7C"
        },
        [10128712] = {
          ContentKR = "〈아이스레이크 시티 모닝 포스트〉의 기자, 안수즈야. 지금은 그거면 돼.",
          DialogueId = 10128712,
          GUID = "195B2DD0",
          NextDialogue = 10128713,
          SpeakNpcId = 200092,
          Subtitle = "Name's Ansuz. Journalist for the Icelake Daily.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2DD0"
        },
        [10128713] = {
          ContentKR = "사실, 다른 도시의 신문들도 나와 어느 정도 관련돼 있어. 나는 글로 우리 카론의 처지를 조금이라도 개선하고 싶어.",
          DialogueId = 10128713,
          GUID = "195B2DFA",
          NextDialogue = 10128714,
          SpeakNpcId = 200092,
          Subtitle = "Truth is, I've had a hand in more than a few papers across more than a few cities. I write to make things a little better for our people — to open some eyes.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2DFA"
        },
        [10128714] = {
          ContentKR = "물론 나도 알아. 펜만으로는 부족하지. 우리는 칼을 들어야 해. 놈들에게 핏값을 받아내야 해.",
          DialogueId = 10128714,
          GUID = "195B2E24",
          NextDialogue = 10128715,
          SpeakNpcId = 200092,
          Subtitle = "I know — words can shine a light, but they won't bring justice. For that, we'll need blades — to make them pay for everything they've done to our kind.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2E24"
        },
        [10128715] = {
          ContentKR = "그날이 오면, 너도 함께해 줄 거라고 믿어.",
          DialogueId = 10128715,
          GUID = "195B2E4E",
          SpeakNpcId = 200092,
          Subtitle = "And I believe... when that day arrives, you'll be right there, fighting beside me.",
          VoiceName = "voice/$Locale$/story/1002/101287/195B2E4E"
        },
        [10128801] = {
          ContentKR = "한 잔... 여섯 잔... 열세 잔...",
          DialogueId = 10128801,
          GUID = "195B3C6A",
          SpeakNpcId = 200095,
          Subtitle = "Mmm... One glass... six glasses... thirteen...",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3C6A"
        },
        [10128802] = {
          ContentKR = "한 잔에 카론과 솔라가 화목하고, 여섯 잔에 제6군단은 돼지 떼, 열세 잔에…",
          DialogueId = 10128802,
          GUID = "195B3C94",
          NextOptions = {
            [1] = 101288021,
            [2] = 101288022,
            [3] = 101288023
          },
          SpeakNpcId = 200095,
          Subtitle = "One drink down, Charons and Solas get along. Six in, damn the pigs in the 6th Legion... Thirteen— Belch...",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3C94"
        },
        [10128804] = {
          ContentKR = "난 멀쩡해. 문제는 아이스레이크 시티야! 그러니 한잔 할래, 친구야. 생각을 놔 버리면 인생을 조화로워. 술이 머리에 들어가면 상사는 돼지가 되지. 너만 좋다면 개도 괜찮아.",
          DialogueId = 10128804,
          GUID = "195B3CE8",
          NextDialogue = 10128805,
          SpeakNpcId = 200095,
          Subtitle = "Me? I'm brilliant. It's this cursed city that's gone sick. Come now, friend — let's numb the thoughts, round out life's sharp edges. This way, your captain starts to look like a pig. Or a dog, if that's your flavour.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3CE8"
        },
        [10128805] = {
          ContentKR = "하지만 난 돼지가 좋아. 개는 인간을 숭배하고, 고양이는 경멸해. 돼지는 우리를 똑같이 대하거든. 그러니 귀족들과 군단은 돼지만도 못해. 카론들은 이렇게 사는데, 그것들은 노래하고 춤추지.",
          DialogueId = 10128805,
          GUID = "195B3D12",
          NextDialogue = 10128806,
          SpeakNpcId = 200095,
          Subtitle = "Me, I prefer pigs. Dogs worship. Cats judge. But pigs? They treat everyone the same — unlike our fine nobles and those legion rats. Charons are starving, and they're still up there — dancing, singing, like it's a festival.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D12"
        },
        [10128806] = {
          ContentKR = "술이 있어서 다행이야, 다행! 내 영혼은 위스키의 흙 내음을 좋아해. 나는 솔라가 아닐지도 몰라. 사실 내 영혼은 73리터의 독주고, 내 몸은 묶인 오크통이야!",
          DialogueId = 10128806,
          GUID = "195B3D3C",
          NextDialogue = 10128807,
          SpeakNpcId = 200095,
          Subtitle = "Thank the stars for whisky. My soul craves the earthy bite of a good dram. Maybe I'm not even a Sola... maybe I'm just 73 litres of liquor in an old oak barrel.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D3C"
        },
        [10128807] = {
          ContentKR = "그래, 그래, 카론과 솔라가 모두 독주라면 좋겠어. 모두가 서로 뒤섞여 조화를 이루잖아. 세상은 끝없이 넓은 칵테일이거나, 설탕이 3분의 1인 오렌지 주스인 거지!",
          DialogueId = 10128807,
          GUID = "195B3D66",
          NextDialogue = 10128808,
          SpeakNpcId = 200095,
          Subtitle = "Yes, yes — if Solas and Charons were all just spirits in a bottle, we'd blend, we'd mix — and the world would be one grand cocktail. Or maybe just a glass of orange juice... with a touch of sweetness.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D66"
        },
        [10128808] = {
          ContentKR = "너도 마셔, 한 잔에 근심을 모두 잊고, 다들 친구가 되는 거야.",
          DialogueId = 10128808,
          GUID = "195B3D90",
          SpeakNpcId = 200095,
          Subtitle = "Come on — join me. One good buzz, and we're all friends.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3D90"
        },
        [10128810] = {
          ContentKR = "아, 새로 온 카론이구나. 뭘 물어보냐, 취해 있는 거 안 보여?",
          DialogueId = 10128810,
          GUID = "195B3DE4",
          NextDialogue = 10128811,
          SpeakNpcId = 200095,
          Subtitle = "What does it look like, stranger? I'm drinking myself stupid!",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3DE4"
        },
        [10128811] = {
          ContentKR = "술에 취하지 않으면, 똑바로 일해야 해. 내가 똑바로 일하면, 너희는 남아나지 못해. 그래서 난 취하기로 한 거야. 나한테 감사하라고. 너희를 오래 살리려고 내가 천천히 자살하는 거니까.",
          DialogueId = 10128811,
          GUID = "195B3E0E",
          NextDialogue = 10128812,
          SpeakNpcId = 200095,
          Subtitle = "Cause if I sober up, I'll have to work. And if I actually did my job right... well, most of you wouldn't last the week. So really — you ought to thank me. I'm slowly poisoning myself, just so the rest of you get to live a little longer.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3E0E"
        },
        [10128812] = {
          ContentKR = "한 잔 따라 봐. 나는 죄인이며, 선인이야. 처음 만난 카론 친구.",
          DialogueId = 10128812,
          GUID = "195B3E38",
          SpeakNpcId = 200095,
          Subtitle = "So cheers, my new Charon friend. I'm a sinful man... and a good man.",
          VoiceName = "voice/$Locale$/story/1002/101288/195B3E38"
        },
        [10128901] = {
          ContentKR = "술통도 아닌데, 그만 좀 마셔…",
          DialogueId = 10128901,
          GUID = "195B4CD2",
          SpeakNpcId = 200096,
          Subtitle = "You're not really a barrel of whisky, you know. Come on... you've had enough...",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4CD2"
        },
        [10128902] = {
          ContentKR = "아, 이 친구 또 퍼마셨네. 이러다간 오래 못 갈 텐데. 감시원이 다른 솔라로 바뀌면 곤란한데 말이야.",
          DialogueId = 10128902,
          GUID = "195B4CFC",
          NextOptions = {
            [1] = 101289021,
            [2] = 101289022,
            [3] = 101289023
          },
          SpeakNpcId = 200096,
          Subtitle = "*sigh*... At it again, that one. If he keeps this up, it'll kill him. And if they send in another Sola to keep watch, we'll all be in for it.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4CFC"
        },
        [10128904] = {
          ContentKR = "그래, 아마 자넨 새로 와서 모를 테지. 이 친구는 제6군단이 빈민가에 보낸 감시원이야. 이쪽의 위험 인물을 찾아내 본보기로 삼으려는 거지.",
          DialogueId = 10128904,
          GUID = "195B4D50",
          NextDialogue = 10128905,
          SpeakNpcId = 200096,
          Subtitle = "Yeah. You must be new. He's from the 6th Legion — posted here to keep an eye on us slumfolk and sniff out \"troublemakers.\"",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4D50"
        },
        [10128905] = {
          ContentKR = "이 친구가 여기 온 첫날, 세 명이 좀 수상하다고 기록했어. 바로 그다음 날, 그 세 명은 모두 교수형에 처했지. 그 일로 충격을 받은 거야. 처음엔 아마 며칠 감금하는 정도로 끝날 줄 알았겠지.",
          DialogueId = 10128905,
          GUID = "195B4D7A",
          NextDialogue = 10128906,
          SpeakNpcId = 200096,
          Subtitle = "First day on the job, he flagged three people as suspicious. Next day, all three were hanging in the square. Hit him hard. Probably thought they'd just get locked up for a few days, not... that.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4D7A"
        },
        [10128906] = {
          ContentKR = "그 후로 이렇게, 매일 술에 빠져 살면서 정말로 술에 절어 죽으려는 것처럼 보여. 세상이 큰 술통이고 자신은 작은 술통이니, 모두 다 술통이 되어야 한다고 하루 종일 그러고 있어.",
          DialogueId = 10128906,
          GUID = "195B4DA4",
          NextDialogue = 10128907,
          SpeakNpcId = 200096,
          Subtitle = "Now he spends most of his days at the bottom of a bottle, mumbling about how the world's a big barrel, and we're all little casks waiting to blend.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4DA4"
        },
        [10128907] = {
          ContentKR = "상사에게는 첫날의 신속한 조치에 놀란 카론들이 겁먹은 메추라기처럼 얌전해졌다고 보고하면서 그럭저럭 넘기고 있어.",
          DialogueId = 10128907,
          GUID = "195B4DCE",
          NextDialogue = 10128908,
          SpeakNpcId = 200096,
          Subtitle = "Still files his reports though. Says the Charons are quiet now — too scared to act up again. Keeps the higher-ups off his back.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4DCE"
        },
        [10128908] = {
          ContentKR = "그럴 리가 없잖아? 처음 같은 근무태도였다면 여기 있는 사람들은 다 열 번도 더 교수형에 처했을 거야. 하지만 그러기 전에 아마 그도 맞아 죽었을 거야.",
          DialogueId = 10128908,
          GUID = "195B4DF8",
          NextDialogue = 10128909,
          SpeakNpcId = 200096,
          Subtitle = "But we all know — if he'd kept going like he did that first day, none of us would still be breathing. Though before that happened, someone would've made sure he never walked again.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4DF8"
        },
        [10128909] = {
          ContentKR = "그래서 지금 이렇게 술에 절어 일을 안 하는 게 그로서는 최선의 방법이지. 이제 이곳의 술손님들도 대부분 그를 미워하지 않아. 군단에 양심 있는 사람이 별로 없는데, 그는 그나마 나은 편이야.",
          DialogueId = 10128909,
          GUID = "195B4E22",
          SpeakNpcId = 200096,
          Subtitle = "So yeah, hiding in his bottle's probably for the best — for everyone. Most of the regulars here don't even hate him anymore. In the whole damned Legion, he's one of the few with a shred of conscience.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4E22"
        },
        [10128911] = {
          ContentKR = "대체로 그렇지. 카론은 태어날 때부터 자기가 사악하고 많은 재앙의 근원이라는 제국 교육을 받게 되지.",
          DialogueId = 10128911,
          GUID = "195B4E76",
          NextDialogue = 10128912,
          SpeakNpcId = 200096,
          Subtitle = "Most days, yeah. From the moment we're born, they drill it into us — \"Charons are cursed, dangerous by nature.\"",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4E76"
        },
        [10128912] = {
          ContentKR = "성장하면서, 무기를 든 뿔 없는 솔라들이 총알과 열차포로 저항하는 자들을 산산조각 내는 모습을 지켜보게 돼.",
          DialogueId = 10128912,
          GUID = "195B4EA0",
          NextDialogue = 10128913,
          SpeakNpcId = 200096,
          Subtitle = "Then we grow up watching the hornless walk around armed to the teeth, mowing down anyone who so much as talks back.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4EA0"
        },
        [10128913] = {
          ContentKR = "카론도 반란을 일으켰을 땐 솔라에게도 가차 없이 대했지만, 지금은 솔라들이 우위를 점하고 있을 뿐이야.",
          DialogueId = 10128913,
          GUID = "195B4ECA",
          NextDialogue = 10128914,
          SpeakNpcId = 200096,
          Subtitle = "And sure, when we Charons hit back, we don't hold back either. But right now — it's the Solas holding the high ground.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4ECA"
        },
        [10128914] = {
          ContentKR = "갈등은 나선을 이루며 계속 쌓여 갔어. 때로는 카론이, 때로는 솔라가 우위에 섰지만, 솔라가 우위에 서 있던 시간이 더 길지 뭐.",
          DialogueId = 10128914,
          GUID = "195B4EF4",
          NextDialogue = 10128915,
          SpeakNpcId = 200096,
          Subtitle = "It's a cycle, you know — hatred, war, blood. Round and round it goes. Sometimes it's us with the upper hand, but they've held theirs a hell of a lot longer.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4EF4"
        },
        [10128915] = {
          ContentKR = "신참인 것 같은데, 충고 하나 하자면 살아남는 게 제일이야. 살아 있다 보면 언젠가 카론에게 볕들 날이 올지도 몰라.",
          DialogueId = 10128915,
          GUID = "195B4F1E",
          SpeakNpcId = 200096,
          Subtitle = "You look like you're new around here. Take it from me — staying alive matters more than anything. Keep your head low, and who knows? You might just live to see better days for our kind.",
          VoiceName = "voice/$Locale$/story/1002/101289/195B4F1E"
        },
        [10129001] = {
          ContentKR = "붙잡아서 다행이야, 다친 사람도 없고, 운이 좋았어.",
          DialogueId = 10129001,
          GUID = "195B5D3A",
          SpeakNpcId = 200095,
          Subtitle = "Somebody caught him? And no one got hurt? Thank goodness.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5D3A"
        },
        [10129002] = {
          ContentKR = "자네가 잡은 그 도둑은 치안서로 보냈다던데? 정말 운이 좋았어. 미리 막아서 다행이야. 잘했어, 젊은이.",
          DialogueId = 10129002,
          GUID = "195B5D64",
          NextOptions = {
            [1] = 101290021,
            [2] = 101290022,
            [3] = 101290023
          },
          SpeakNpcId = 200095,
          Subtitle = "Heard that thief you nabbed ended up at the Security Bureau. Lucky it ended there. Good work, kiddo.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5D64"
        },
        [10129004] = {
          ContentKR = "그래, 그런 경우엔 치안서로 보내는 게 최선이야. 안 그랬다간 더 큰 문제를 일으켜서 카론에 대한 나쁜 소문과 증오가 더 커질 거야.",
          DialogueId = 10129004,
          GUID = "195B5DB8",
          NextDialogue = 10129005,
          SpeakNpcId = 200095,
          Subtitle = "Aye. For someone like him, that's about as kind a fate as he could've hoped for. If he'd stayed on the loose, things could've gotten ugly — and when they do, it's always the whole Charon community that ends up paying the price.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5DB8"
        },
        [10129005] = {
          ContentKR = "도둑에겐 비참한 일이지만, 어쩔 수 없지. 사람은 어차피 죽는 법이니, 지금 이게 가장 괜찮은 결과야.",
          DialogueId = 10129005,
          GUID = "195B5DE2",
          NextDialogue = 10129006,
          SpeakNpcId = 200095,
          Subtitle = "Poor lad... But what can you do? Sooner or later, death would've come knocking. In the bigger picture, this is for the best.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5DE2"
        },
        [10129006] = {
          ContentKR = "자책하지 마, 이건 자네 잘못이 아니야. 아무도 잘못한 게 없어.",
          DialogueId = 10129006,
          GUID = "195B5E0C",
          SpeakNpcId = 200095,
          Subtitle = "Don't beat yourself up. No one's to blame here.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5E0C"
        },
        [10129008] = {
          ContentKR = "술을 마시면 어떻게 되냐는 것 같은 질문이군. 물을 필요가 있나? 내가 줄 수 있는 답은, 그는 독한 술을 마신 것처럼 큰 고통을 겪은 후에 편히 잠들 거라는 거야.",
          DialogueId = 10129008,
          GUID = "195B5E60",
          NextDialogue = 10129009,
          SpeakNpcId = 200095,
          Subtitle = "That's like asking what happens after your fifth stiff drink... Best not to dwell on it. Let's just say — he'll feel the burn, then sleep like the dead.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5E60"
        },
        [10129009] = {
          ContentKR = "하하, 술만 들어가면 제국의 병사가 아니라 예술가라도 된 것 같네. 나쁜 일을 마주하고도 나 자신을 칭찬할 수 있는 이 기분이 좋아. 하지만 자네는 절대 이 기분을 이해하지 말길 바라네.",
          DialogueId = 10129009,
          GUID = "195B5E8A",
          SpeakNpcId = 200095,
          Subtitle = "Ha... listen to me. Few drinks in, and I start sounding more like a poet than a soldier. Funny, isn't it? How you dress something ugly up in grand words — like that could change what it really is. Just hope you never have to.",
          VoiceName = "voice/$Locale$/story/1002/101290/195B5E8A"
        },
        [10129101] = {
          ContentKR = "다 헨릭 때문이었구나…",
          DialogueId = 10129101,
          GUID = "195B6DA2",
          SpeakNpcId = 200095,
          Subtitle = "So it was all Henrik's doing...",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6DA2"
        },
        [10129102] = {
          ContentKR = "아이스레이크 시티의 침식자가 줄어든 게 기적인 줄 알았는데, 알고 보니 헨릭 때문이었어... 이미 죽었으니 군단은 추궁하지 않겠지만, 앞으로 어떻게 해야 할지…",
          DialogueId = 10129102,
          GUID = "195B6DCC",
          NextOptions = {
            [1] = 101291021,
            [2] = 101291022,
            [3] = 101291023
          },
          SpeakNpcId = 200095,
          Subtitle = "I'd thought the sudden drop in Deteriorator sightings around Icelake was some kind of miracle. Turns out... it was all Henrik. Now that he's dead, the Legion won't be holding him to account. But what are we supposed to do now...?",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6DCC"
        },
        [10129104] = {
          ContentKR = "그래, 뭘 어떻게 하겠어. 히프노스의 집은 이미 비어 있고 합법적인 상속인도 있어. 그 집을 불태울 수는 없잖아.",
          DialogueId = 10129104,
          GUID = "195B6E20",
          NextDialogue = 10129105,
          SpeakNpcId = 200095,
          Subtitle = "I mean, what can they do, exactly? The Hypnos' House is empty now, and there's already a legal heir. It's not like they can just burn the place down.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E20"
        },
        [10129105] = {
          ContentKR = "솔직히 , 군단은 그에게 감사하고 상을 줘야 한다고 생각해. 헨릭이 없어서 그렇게 많은 침식자가 사고를 일으킨다면… 상상도 하기 싫어.",
          DialogueId = 10129105,
          GUID = "195B6E4A",
          NextDialogue = 10129106,
          SpeakNpcId = 200095,
          Subtitle = "If you ask me, they should be thanking him. Give him a posthumous medal, even. Without what he did, all those Deteriorators might've turned this whole place into a graveyard.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E4A"
        },
        [10129106] = {
          ContentKR = "그가 침식을 막는 약을 연구했다고 들었어. 아, 정말로 성공했으면 좋았을 텐데. 카론이 태어날 때부터 죄를 짊어진다는 소리가 줄어들었을 거야.",
          DialogueId = 10129106,
          GUID = "195B6E74",
          NextDialogue = 10129107,
          SpeakNpcId = 200095,
          Subtitle = "Heard he was working on a drug — something to stop the Deterioration. If only he'd made it work... Maybe fewer people would go on believing Charons are cursed from birth.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E74"
        },
        [10129107] = {
          ContentKR = "음... 많은 솔라가 카론의 처지를 외면할 수 있는 것도, 이걸 근거로 자기 최면을 걸기 때문이겠지... 죄를 지고 태어나는 종족이니, 고생하는 것도 당연하다고.",
          DialogueId = 10129107,
          GUID = "195B6E9E",
          NextDialogue = 10129108,
          SpeakNpcId = 200095,
          Subtitle = "But I guess that's how most of us Solas sleep at night — by telling ourselves they deserve it.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6E9E"
        },
        [10129108] = {
          ContentKR = "아, 나도 같은 솔라니 뭐라 할 자격이 없지. 카론을 위해 목숨을 바친 헨릭에 비하면 내가 뭘 했다고…",
          DialogueId = 10129108,
          GUID = "195B6EC8",
          SpeakNpcId = 200095,
          Subtitle = "Not that I'm one to talk. Compared to Henrik — a fellow Sola who gave his life for Charons — what have I ever done...?",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6EC8"
        },
        [10129110] = {
          ContentKR = "프시케...? 아, 너와 함께 있던 그 아이 말하는 거지... 군단은 그 아이는 크게 신경 쓰지 않았지. 매일 전국에서 이런 침식자 관련 사건이 적지 않게 일어나니까.",
          DialogueId = 10129110,
          GUID = "195B6F1C",
          NextDialogue = 10129111,
          SpeakNpcId = 200095,
          Subtitle = "Psyche...? Oh, the girl who was your friend. The Legion didn't make much noise about it. Cases involving Deteriorators pop up across the country — this was just one more.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F1C"
        },
        [10129111] = {
          ContentKR = "제6군단의 리듬 장관도 이번 침식 사건이 규모가 크고, 불법 의료 행위가 얽혀 있지만 깊이 조사할 필요는 없다고 했어.",
          DialogueId = 10129111,
          GUID = "195B6F46",
          NextDialogue = 10129112,
          SpeakNpcId = 200095,
          Subtitle = "Officer Fischer of the 6th Legion said the case was serious, with many casualties and illegal medical activities, but she didn't think it warranted further investigation.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F46"
        },
        [10129112] = {
          ContentKR = "현장에 있던 사람은... 너도 포함되겠지. 안 그러면 군단에 끌려가 심문받게 될 거야. 그때 무슨 일이 일어날지는 아무도 몰라.",
          DialogueId = 10129112,
          GUID = "195B6F70",
          NextDialogue = 10129113,
          SpeakNpcId = 200095,
          Subtitle = "Otherwise... any witnesses — including you — could have ended up in a Legion interrogation room. And once you're in there... well, who knows what might've happened.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F70"
        },
        [10129113] = {
          ContentKR = "아, 너도 마음을 추슬러. 많이 힘들겠지. 이 술잔을 그 아이에게 바칠게.",
          DialogueId = 10129113,
          GUID = "195B6F9A",
          SpeakNpcId = 200095,
          Subtitle = "I'm sorry for your loss. Must've been hard. Here's to that girl — may she rest in peace.",
          VoiceName = "voice/$Locale$/story/1002/101291/195B6F9A"
        },
        [10129201] = {
          ContentKR = "글로스터 폐광에 갔다 왔어? 제법이네.",
          DialogueId = 10129201,
          GUID = "195B7001",
          SpeakNpcId = 200092,
          Subtitle = "You made it out of Glevum Pit? Not bad — you're tougher than you look.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7001"
        },
        [10129202] = {
          ContentKR = "무슨 일이야? 글로스터 폐광? 거기서 살아 돌아오다니 정말 운이 좋았구먼. 그런데 말이야, 헨릭이 요즘 더군다나 신경질을 부리더군.",
          DialogueId = 10129202,
          GUID = "195B7002",
          NextOptions = {
            [1] = 101292021,
            [2] = 101292022,
            [3] = 101292023
          },
          SpeakNpcId = 200092,
          Subtitle = "So — you really went down into Glevum Pit and made it back in one piece? That's really something. Then again... Henrik's been acting even stranger lately.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7002"
        },
        [10129204] = {
          ContentKR = "거긴 위험해. 폐광이긴 하지만 안엔 아직도 필토이드가 우글우글대는구먼. 조사하러 사람을 보내 봤는데, 큰 괴물한테 가로막혀서 돌아왔어.",
          DialogueId = 10129204,
          GUID = "195B7004",
          NextDialogue = 10129205,
          SpeakNpcId = 200092,
          Subtitle = "Nasty place. Long abandoned, but still crawling with Filthoids. I once paid someone to have a look around — they bolted right back out after running into some enormous beast.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7004"
        },
        [10129205] = {
          ContentKR = "뭐? 그걸 물리쳤다고? 이거... 실력이 좋은 거야 운이 좋은 거야?",
          DialogueId = 10129205,
          GUID = "195B7005",
          NextDialogue = 10129206,
          SpeakNpcId = 200092,
          Subtitle = "What? You actually beat it? Hah... well, either you're tougher than you look — or luck's been smiling on you.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7005"
        }
      }
    end
  },
  {
    MinKey = 10129206,
    MaxKey = 11011015,
    Loader = function()
      return {
        [10129206] = {
          ContentKR = "음... 시간 있으면 인터뷰 좀 받아 볼래? 제목은 〈떠오르는 신예 월석 사냥꾼——{nickname}〉로 하자. 유명해질 수 있을 거야.",
          DialogueId = 10129206,
          GUID = "195B7006",
          SpeakNpcId = 200092,
          Subtitle = "Say... if you've got a moment, how about a little feature piece? We'll call it: \"Rising Star of Icelake — Ace Phoxhunter !\" Catchy, no? Could give your name a bit of shine.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7006"
        },
        [10129208] = {
          ContentKR = "뭐랄까, 평소에도 딱딱하고 농담도 안 하는 사람이었지. 인터뷰 제의도 거절당했고, 그의 손님들에게 말을 걸어 보다 쫓겨났어.",
          DialogueId = 10129208,
          GUID = "195B7008",
          NextDialogue = 10129209,
          SpeakNpcId = 200092,
          Subtitle = "Well... he's always been stiff — never one for chit-chat. I tried to interview him once — he shut me down flat. Even kicked me out when I tried speaking to his lodgers.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7008"
        },
        [10129209] = {
          ContentKR = "하지만 예전엔 이렇게 차가운 말투도, 누굴 죽일 것 같은 분위기도 아니었어. 요새 무슨 고민이라도 있나 봐. 이런 세상이니 다들 그렇겠지만.",
          DialogueId = 10129209,
          GUID = "195B7009",
          SpeakNpcId = 200092,
          Subtitle = "Still, he wasn't always this cold — like he's ready to slit someone's throat. Maybe he's got something on his mind lately. Then again, who doesn't, these days?",
          VoiceName = "voice/$Locale$/story/1002/101292/195B7009"
        },
        [10129211] = {
          ContentKR = "나? 어머나, 난 글을 써서 돈을 버는 사람이야, 그냥 대기자 안수즈라고 불러 줘.",
          DialogueId = 10129211,
          GUID = "195B700B",
          NextDialogue = 10129212,
          SpeakNpcId = 200092,
          Subtitle = "Me? Just someone who lives off ink and paper. You can call me Ansuz — intrepid journalist extraordinaire!",
          VoiceName = "voice/$Locale$/story/1002/101292/195B700B"
        },
        [10129212] = {
          ContentKR = "아이스레이크 시티에서 소식을 모아 글로 쓰고, 신문으로 발행해서 즐거움을 전하지.",
          DialogueId = 10129212,
          GUID = "195B700C",
          NextDialogue = 10129213,
          SpeakNpcId = 200092,
          Subtitle = "I go where the whispers lead, unearth the truth, and weave it into tales to bring a bit of cheer to the fine folks of Icelake.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B700C"
        },
        [10129213] = {
          ContentKR = "못 믿겠나 봐? 자, 이거. 오늘 자 〈아이스레이크 시티 모닝 포스트〉야. 공짜로 줄 테니 마음에 들면 다음엔 사서 봐.",
          DialogueId = 10129213,
          GUID = "195B700D",
          NextDialogue = 10129214,
          SpeakNpcId = 200092,
          Subtitle = "What's with that look? Go on, take one — today's issue of the Icelake Daily. On the house. If you like what you read, come find me for the next one.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B700D"
        },
        [10129214] = {
          ContentKR = "물론, 기사거리가 있으면 나를 찾아와. 무료로 교환해 줄게.",
          DialogueId = 10129214,
          GUID = "195B700E",
          SpeakNpcId = 200092,
          Subtitle = "And if you've got a juicy lead, come find me — I'll trade you a fresh copy for it.",
          VoiceName = "voice/$Locale$/story/1002/101292/195B700E"
        },
        [10129301] = {
