          DialogueId = 10130502,
          GUID = "195BD034",
          Subtitle = "...Prepare for direct engagement!",
          VoiceName = "voice/$Locale$/story/1002/101305/195BD034"
        },
        [10130601] = {
          Camera = "-90.074219,755.777344,469.635742,0.000111,-25.499575,-93.596069,25.0,467.444916,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "이건... 준위님, 침식자가 이미...!",
          DialogueId = 10130601,
          FacialId = {
            [1] = "100001:Shock02",
            [2] = "200002:Shock02",
            [3] = "200021:Angry01",
            [4] = "2000581:Close"
          },
          FinalCamera = "-95.249023,668.898438,428.417969,0.000102,-26.099579,-95.596054,25.0,467.444916,false,Manual,22.0",
          GUID = "195BD035",
          LookAt = {
            [1] = "100001:n(2000581)"
          },
          NextDialogue = 10130602,
          Scripts = "PlayAnimation{ActorId{2000581},AnimationId{\"BossSaiqi_Story_Die\"},Sync{true}}",
          SpeakNpcId = 700065,
          Subtitle = "...Ma'am, the Deteriorator — it's already...!",
          TalkActionId = {
            [1] = "100001:Crouch_Loop",
            [2] = "2000581:BossSaiqi_Story_Die"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101306/195BD035"
        },
        [10130602] = {
          ContentKR = "...상황이 좀 이상한데. 어쨌든 다행히, 인질들은 모두 무사하군.",
          DialogueId = 10130602,
          GUID = "195BD036",
          NextDialogue = 10130603,
          SpeakNpcId = 100304,
          SpeakNpcName = "UI_Npc_Name_FemaleOfficer",
          Subtitle = "...Something's off. But the hostages are safe, at least.",
          VoiceName = "voice/$Locale$/story/1002/101306/195BD036"
        },
        [10130603] = {
          Camera = "82.416016,128.960938,14.348633,-3.000001,-0.400782,-132.985641,30.000002,214.526855,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "저는 제6군단 소속 코퀴투스 방위대 준위, 리듬 페실입니다.",
