CameraMoveTo{TargetPosition{"-276.560547,-230.78125,137.651367,0.00053,-23.796835,47.828102,50.0,371.84317,false,Manual,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-281.869141,-238.039062,141.693359,0.000539,-23.996824,53.828442,50.0,371.84317,false,Manual,22.0"},duration{3}},
StopTalkGroup{ActorId{100304},Duration{0.5}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "...I see. That would explain why the target was more stable than a typical Filthoid.",
          TalkActionId = {
            [1] = "100304:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101306/195BD040"
        },
        [10130701] = {
          ContentKR = "여기 노트가 있어! 설마 전설 속 모험가의 일기 같은 건가?!",
          DialogueId = 10130701,
          GUID = "195BD041",
          Subtitle = "A notebook's here! Could it be some legendary adventurer's journal?!",
          VoiceName = "voice/$Locale$/story/1002/101307/195BD041"
        },
        [10130800] = {
          DialogueId = 10130800,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_101223;content:Reading_Content_101223}",
          GUID = "195BD04A",
          NextDialogue = 10130801
        },
        [10130801] = {
          Camera = "50.077148,-329.630371,240.10498,0.000162,-26.599609,119.809021,50.0,292.198273,false,Manual,7.759425",
          ContentKR = "봐봐, 시종! 옆에 <H>화약통</>이 많이 놓여 있어!",
          DialogueId = 10130801,
          Duration = 10,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "195BD042",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 10130802,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{1.5},TargetPosition{"50.077148,-329.630371,240.10498,0.000162,-26.599609,119.809021,50.0,292.198273,false,Manual,7.759425"},duration{0}},
CameraMoveTo{TargetPosition{"50.077148,-329.630371,240.10498,0.000181,-16.799314,101.009155,50.0,292.198273,false,Manual,7.759425"},Blend{"easeInOutQuad"},duration{8}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Look over there, Little Minion. There are several powder kegs.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101308/195BD042"
        },
        [10130802] = {
          Camera = "-137.248779,-3.609863,123.338379,0.000239,6.000567,-59.584656,35.0,167.968307,false,Manual,7.759425",
          ContentKR = "응, 노트에도 화약이 언급돼 있어. <H>노란색 결정을 폭파</>하는 데 사용하던 걸 거야.",
          DialogueId = 10130802,
          Duration = 10,
          FinalCamera = "-127.740967,-19.807373,125.3125,0.000239,6.400563,-58.98452,35.0,167.968307,false,Manual,7.759425",
          GUID = "195BD043",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10130803,
          SpeakNpcId = 100001,
          Subtitle = "I see. The journal also mentioned gunpowder. Maybe we can use the kegs to blow up the yellow crystals.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101308/195BD043"
        },
        [10130803] = {
          Camera = "269.530029,368.111084,118.398438,0.000066,-2.199314,-128.599228,30.0,619.991211,false,Manual,1.2",
          ContentKR = "그럼 가져가자! 모험엔 든든한 준비가 필요하잖아!",
          DialogueId = 10130803,
          Duration = 10,
          FinalCamera = "257.802246,377.4729,118.398438,0.000066,-2.199314,-128.599228,30.0,274.965851,false,Manual,1.2",
          GUID = "195BD044",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Let's take them with us then. You can never be too prepared when you're adventuring!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101308/195BD044"
        },
        [10130901] = {
          ContentKR = "윽, 저 역겨운 노란 수정 가시가 길을 막고 있잖아!",
          DialogueId = 10130901,
          GUID = "195BD045",
          NextDialogue = 10130902,
          SpeakNpcId = 200002,
          Subtitle = "Argh, those nasty yellow crystal spikes block our way!",
          VoiceName = "voice/$Locale$/story/1002/101309/195BD045"
        },
        [10130902] = {
          ContentKR = "방금 그 화약통을 쓸 때가 온 것 같아.",
          DialogueId = 10130902,
          GUID = "195BD046",
          SpeakNpcId = 100001,
          Subtitle = "The powder kegs we just found can be of great help now.",
          VoiceName = "voice/$Locale$/story/1002/101309/195BD046"
        },
        [10130903] = {
          ContentKR = "(뒤로 물러나서, <H>총을 쏴서</> 터뜨리자.)",
          DialogueId = 10130903,
          GUID = "195BD047",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "(Might as well stay far and shoot to detonate them.)",
          VoiceName = "voice/$Locale$/story/1002/101309/195BD047"
        },
        [10131001] = {
          ContentKR = "성공이야! ...어? 너희 괜찮아? 마왕님은 왜 바닥에 쪼그리고 있어? 혹시 다친 거야?",
          DialogueId = 10131001,
          GUID = "195BD048",
          NextDialogue = 10131002,
          SpeakNpcId = 200006,
          Subtitle = "It works! ...Oh, are you okay? Why are you squatting on the ground, Demon King? Are you hurt?",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD048"
        },
        [10131002] = {
          ContentKR = "으응? 아, 아니야! 그 그냥 포, 포, 폭발일 뿐이잖아! 나, 난 지형을 조사하고 있었어, 헤헤...",
          DialogueId = 10131002,
          GUID = "195BD049",
          NextDialogue = 10131003,
          SpeakNpcId = 200002,
          Subtitle = "Ah?! I...I'm fine, it was j...just a small blast! I was just... um... checking out the ground... Hehe...",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD049"
        },
        [10131003] = {
          ContentKR = "쉿!",
          DialogueId = 10131003,
          GUID = "195BD050",
          NextDialogue = 10131004,
          SpeakNpcId = 100001,
          Subtitle = "Ssh!",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD050"
        },
        [10131004] = {
          ContentKR = "크르르르——",
          DialogueId = 10131004,
          GUID = "195BD051",
          NextDialogue = 10131005,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          Subtitle = "*Roar—*",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD051"
        },
        [10131005] = {
          ContentKR = "...광갱 깊은 곳에 뭔가 있는 것 같은데?",
          DialogueId = 10131005,
          GUID = "195BD052",
          NextDialogue = 10131006,
          SpeakNpcId = 200006,
          Subtitle = "...There seems to be somthing deep in the pit.",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD052"
        },
        [10131006] = {
          ContentKR = "그러고 보니, 방금 노트에서 광갱 안쪽에 특수한 필토이드가 출몰할 가능성이 있다고 했어... 모두 뒤처지지 않게 조심해.",
          DialogueId = 10131006,
          GUID = "195BD053",
          SpeakNpcId = 100001,
          Subtitle = "The journal mentioned that there could be a special Filthoid down there... We should be careful and stay close.",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD053"
        },
        [10131101] = {
          ContentKR = "봐봐! 저기 한가운데에 반짝반짝 빛나는 커다란 결정체! 저게 혹시 우리가 찾는 반짝이는 수정 아닐까?",
          DialogueId = 10131101,
          GUID = "195BD054",
          SpeakNpcId = 200002,
          Subtitle = "Look, a giant crystal in the middle is glowing. Could it be that the Crystallo of Stella we're looking for is inside?",
          VoiceName = "voice/$Locale$/story/1002/101311/195BD054"
        },
        [10131201] = {
          ContentKR = "크르르르——",
          DialogueId = 10131201,
          GUID = "195BD055",
          NextDialogue = 10131202,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          Subtitle = "*Roar—*",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD055"
        },
        [10131202] = {
          ContentKR = "방금 그 소리야!",
          DialogueId = 10131202,
          GUID = "195BD056",
          NextDialogue = 10131203,
          SpeakNpcId = 200006,
          Subtitle = "That voice again!",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD056"
        },
        [10131203] = {
          ContentKR = "으아아 어디서 갑자기 이렇게 많은 필토이드가 몰려오는 거야! 으으...으허엉...",
          DialogueId = 10131203,
          GUID = "195BD057",
          NextDialogue = 10131204,
          SpeakNpcId = 200002,
          Subtitle = "Ahhh— How come there are so many Filthoids coming at us out of nowhere?! ...Uh... Uh-oh...",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD057"
        },
        [10131204] = {
          ContentKR = "방금 폭발하는 소리에 이끌려 온 게 아닐까?",
          DialogueId = 10131204,
          GUID = "195BD058",
          NextDialogue = 10120102,
          SpeakNpcId = 200006,
          Subtitle = "Perhaps they were attracted by the explosion...",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD058"
        },
        [10131301] = {
          Camera = "775.768799,-65.358398,179.694336,0.000056,-1.399676,-179.401596,20.0,100000.0,false,Disable,2.8",
          ContentKR = "반짝반짝 마법 탄환, 순백의 구원자——! 콰광!",
          DialogueId = 10131301,
          GUID = "195BD059",
          NextDialogue = 10131302,
          SpeakNpcId = 200002,
          Subtitle = "Take my Shiny Bomb! Let the Pure-White Redeemer save the world! Boom!",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD059"
        },
        [10131302] = {
          ContentKR = "콰광'은 됐어. 필토이드는 이미 사라졌는걸.",
          DialogueId = 10131302,
          GUID = "195BD060",
          NextDialogue = 10131303,
          SpeakNpcId = 200006,
          Subtitle = "It's okay. The Filthoids have been taken care of.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD060"
        },
        [10131303] = {
          ContentKR = "아, 그렇구나! 그럼 마왕님의 위대한 전리품을 감상해 볼까——",
          DialogueId = 10131303,
          GUID = "195BD061",
          NextDialogue = 10131304,
          SpeakNpcId = 200002,
          Subtitle = "Oh really? Show this Demon King the loot then—",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD061"
        },
        [10131304] = {
          ContentKR = "카밀라 씨가 반짝이는 수정은 '성운이 흐르는 보라색 결정체'라고 했잖아... 이건 그냥 평범한 실버라이트일 뿐이야.",
          DialogueId = 10131304,
          GUID = "195BD062",
          NextDialogue = 10131305,
          SpeakNpcId = 100001,
          Subtitle = "Camilla once mentioned that Crystallo of Stella is a blue-violet crystal with \"nebulae swirling in it.\" This one is more like a chunk of Silverite.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD062"
        },
        [10131305] = {
          ContentKR = "칫... 재미없네.",
          DialogueId = 10131305,
          GUID = "195BD063",
          NextDialogue = 10131307,
          SpeakNpcId = 200002,
          Subtitle = "Argh... That's lame.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD063"
        },
        [10131306] = {
          ContentKR = "<H>실버라이트</>...? 어렸을 때 옆집 재봉사 아저씨께서 실버라이트는 물감이나 <H>염료</>로 쓸 수 있다고 하셨어.",
          DialogueId = 10131306,
          GUID = "195BD064",
          SpeakNpcId = 200006,
          Subtitle = "Silverite? When I was little, the tailor next door mentioned that this kind of mineral can be used to make pigments or dyes.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD064"
        },
        [10131307] = {
          ContentKR = "그럼 시종, 이건 나중에 <H>대장장이 루나 선배</>님께 가져가 보자! 지금은 일단 날 따라 광갱 깊숙한 곳으로 전진하자고!",
          DialogueId = 10131307,
          GUID = "195BD065",
          NextDialogue = 10131308,
          SpeakNpcId = 200002,
          Subtitle = "Then bring it back to Lunosmith, Little Minion. As for now, let this Demon King continue to lead you deeper into the pit!",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD065"
        },
        [10131308] = {
          ContentKR = "후후... 좋아요, 마왕님.",
          DialogueId = 10131308,
          GUID = "195BD066",
          SpeakNpcId = 200006,
          Subtitle = "Hehe... Yes, Your Majesty.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD066"
        },
        [10131401] = {
          ContentKR = "이 노란 수정 가시 안에 반짝반짝한 돌멩이가 엄청 많이 들어있잖아!",
          DialogueId = 10131401,
          GUID = "195BD067",
          NextDialogue = 10131402,
          SpeakNpcId = 200002,
          Subtitle = "These yellow crystal spikes actually have so many glittering stones inside!",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD067"
        },
        [10131402] = {
          ContentKR = "꼭 누군가 일부러 잘 숨겨둔 보물처럼 말이야...",
          DialogueId = 10131402,
          GUID = "195BD068",
          NextDialogue = 10131403,
          SpeakNpcId = 200006,
          Subtitle = "They seem to have been carefully hidden away like cherished treasures...",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD068"
        },
        [10131403] = {
          ContentKR = "흐응~ 프시케도 몰래 어딘가 보물을 숨겨둔 거 아니야?",
          DialogueId = 10131403,
          GUID = "195BD069",
          NextDialogue = 10131404,
          SpeakNpcId = 200002,
          Subtitle = "Heh heh, could you be hiding some treasures too, Psyche?",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD069"
        },
        [10131404] = {
          ContentKR = "후후... 비밀이야.",
          DialogueId = 10131404,
          GUID = "195BD070",
          SpeakNpcId = 200006,
          Subtitle = "Hehe, that's a secret.",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD070"
        },
        [11000000] = {
          Camera = "67.539062,-1123.730225,550.733276,0.000081,-22.799314,91.999741,35.0,1000.0,false,Manual,2.8",
