        [11011803] = {
          ContentKR = "대장님은 대단한 분이시니까 금방 우릴 구하러 오실 거라면서 얘기 중이었습니다.",
          DialogueId = 11011803,
          GUID = "1B911FEE",
          NextDialogue = 11011804,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110043:n(110016)"}},
LookAt{_delay{0.7},LookAtDescription{"110043:n(110022)"}},
PlayAnimation{_delay{1},_click{False},ActorId{110043},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 110043,
          Subtitle = "I was just trying to get everyone to keep it together — told them how good you are and how you're gonna come flying in and get everyone out of this mess.",
          TalkActionId = {
            [1] = "110043:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B911FEE"
        },
        [11011804] = {
          Camera = "-176.421875,-207.507812,133.143555,0.000077,-4.60016,119.190758,40.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그런데 혹시 혼자 오셨습니까? 시몬은 못 보셨습니까?",
          DialogueId = 11011804,
          GUID = "1B912018",
          LookAt = {
            [1] = "110016:n(110022)",
            [2] = "110022:n(110016)"
          },
          NextDialogue = 11011805,
          SpeakNpcId = 110016,
          Subtitle = "Captain, did you come alone? Did you see Simon?",
          TalkActionId = {
            [1] = "110043:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912018"
        },
        [11011805] = {
          ContentKR = "시몬은... 죽었어.",
          DialogueId = 11011805,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Sad03"
          },
          GUID = "1B912042",
          NextDialogue = 11011806,
          SpeakNpcId = 110022,
          Subtitle = "He's dead.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912042"
        },
        [11011806] = {
          Camera = "-576.783203,132.173828,121.140991,0.000077,-0.800129,-17.610191,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...!! 우리 중에 제일 뛰어난 친구인데, 어떻게...",
          DialogueId = 11011806,
          FinalCamera = "-493.21582,105.644531,117.778931,0.000077,-0.800129,-17.610191,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91206C",
          NextDialogue = 11011807,
          SpeakNpcId = 110016,
          Subtitle = "...!! He... He's the smartest among us. How come...?",
          TalkActionId = {
            [1] = "110016:Shock_Start"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91206C"
        },
        [11011807] = {
          Camera = "-358.588867,96.607422,130.114014,0.000073,-5.400268,106.396278,35.000008,111.478104,false,Manual,2.8",
          ContentKR = "시몬 생각은 잠시 묻어 둬. 일단 전투에서 살아남아야지.",
          DialogueId = 11011807,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "-358.588867,96.607422,135.594849,0.00008,-5.400268,106.396278,35.000015,111.478104,false,Manual,2.8",
          GUID = "1B912096",
          NextDialogue = 11011808,
          SpeakNpcId = 110022,
          Subtitle = "Now is not the time to dwell on Simon. We need to focus on this battle and surviving.",
          TalkActionId = {
            [1] = "110022:DisagreeHead",
            [2] = "110016:Shock_End"
