          VoiceName = "voice/$Locale$/story/1002/110118/1B9120C0"
        },
        [11011809] = {
          Camera = "-656.783203,291.84375,130.419189,0.000108,-4.000244,-31.220165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...맞는 말씀입니다... 무능하게 여기서 울고나 있으라고 시몬이 목숨 걸고 구조 요청하러 간 건 아니니 말입니다.",
          DialogueId = 11011809,
          GUID = "1B9120EA",
          NextDialogue = 11011810,
          SpeakNpcId = 110016,
          Subtitle = "...You're right... He didn't risk his life going out there to look for help so that we could end up here like crybabies.",
          TalkActionId = {
            [1] = "110016:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B9120EA"
        },
        [11011810] = {
          Camera = "-237.097656,-159.654297,134.053345,0.000085,-4.599852,112.993782,40.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "준비됐으면 가지. 오는 길에 아바르 중령님을 만났는데, 나중에 4호 포대에서 모이기로 했다.",
          DialogueId = 11011810,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-275.418945,-69.328125,129.340332,0.000085,-4.599852,112.993782,40.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B912114",
          NextDialogue = 11011811,
          SpeakNpcId = 110022,
          Subtitle = "Get going once you're ready. I ran into Commander Avar on my way here. We plan to join them at Turret 4.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110118/1B912114"
        },
        [11011811] = {
          Camera = "-525.013672,462.529297,124.264893,0.000065,-3.199527,-67.400917,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "4호 포대 말씀이십니까? 거긴 여기서 꽤 먼데, 가는 길에 필토이드가 얼마나 있을지도 모르는데 저희 인원으로만 가기엔 위험하지 않겠습니까?",
          DialogueId = 11011811,
          FinalCamera = "-571.740234,443.087891,124.264893,0.000065,-3.199527,-67.400917,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91213E",
          LookAt = {
            [1] = "110022:n(110043)"
          },
          NextDialogue = 11011812,
          Scripts = [[
SEQ{
LookAt{_delay{0.7},LookAtDescription{"110043:n(110016)"}},
LookAt{_delay{0.7},LookAtDescription{"110043:n(110022)"}}
