        [11011818] = {
          Camera = "-141.424805,-386.271484,135.318604,0.000095,-5.799746,109.587715,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "포로는 산 채로 제국 교도소로 넘겨서 심문받게 해야지.",
