	PlayAnimation{_delay{1},ActorId{110009},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{5},ActorId{110009},AnimationId{"Shock02_End"},Duration{1}}
					}]],
          SpeakNpcId = 110009,
          Subtitle = "Oww, it hurts! Someone do something about this! An armed soldier's hitting a helpless young girl!",
          TalkActionId = {
            [1] = "110009:Shock02_Start"
          },
