        [11012701] = {
          Camera = "-17.772652,-716.293457,114.469177,0.5,-3.598355,87.691597,40.000011,850.827148,false,Manual,10.225481",
          ContentKR = "당장은 풀비스의 지원군이 금방 도착하길 기대하긴 힘들 것 같군.",
          DialogueId = 11012701,
          Duration = 5,
          FinalCamera = "-17.772652,-716.293457,104.522888,0.5,-3.598355,87.691597,40.000023,819.017883,false,Manual,7.752419",
          GUID = "1B91B342",
          NextDialogue = 11012702,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201013,
            [3] = 201015,
