          ContentKR = "뭐? 날 심문하겠다고?",
          DialogueId = 11012728,
          Duration = 3,
          FinalCamera = "947.904724,-1227.703125,128.575073,18.001308,3.599988,-54.103092,40.000011,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B7B0",
          LookAt = {
