          ContentKR = "예!",
          DialogueId = 11012731,
          Duration = 3,
          GUID = "1B91B82E",
          NextDialogue = 11012732,
          SpeakNpcName = "UI_Npc_All",
          Subtitle = "Yes, sir!",
