        },
        [11013602] = {
          Camera = "167.782227,328.865234,78.688873,-5.000004,0.40139,-85.618973,15.0,570.333496,false,DoNotOverride,20.0",
          ContentKR = "이 거짓 증거들은 다 네가 만든 것인가? 원로원의 귀족들은 이런 비열한 짓까진 안 할 줄 알았는데, 내가 잘못 봤군.",
          DialogueId = 11013602,
          Duration = 3,
          FacialId = {
            [1] = "110022:Close"
          },
          FinalCamera = "157.87233,328.103516,77.819336,-5.000004,0.40139,-85.618973,15.0,570.333496,false,DoNotOverride,20.0",
          GUID = "1B924714",
          NextDialogue = 11013603,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8},TargetPosition{"183.857132,-9.058594,30.570129,-0.001556,18.806358,83.179565,55.0,209.993301,false,Manual,9.0"},duration{0}},CameraMoveTo{TargetPosition{"185.70015,6.349609,35.855255,-0.001556,18.806358,83.179565,55.0,209.993301,false,Manual,9.0"},duration{6}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You fabricated all this \"evidence,\" didn't you? I didn't know you old-line aristocrats would stoop to such nasty tricks.",
          TalkActionId = {
