          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924714"
        },
        [11013603] = {
          Camera = "132.141647,116.539062,60.872101,-15.005561,5.400951,-79.810699,35.000011,570.333496,false,DoNotOverride,20.0",
          ContentKR = "난 거기 꽉 막힌 늙은이들이랑은 달라서 말이야. 실용주의자는 쓸 수만 있다면 방법을 가리지 않지.",
          DialogueId = 11013603,
          Duration = 3,
          FinalCamera = "132.141647,116.539062,52.458649,-15.005593,5.400944,-79.810684,35.000011,570.333496,false,DoNotOverride,20.0",
          GUID = "1B92473E",
          NextDialogue = 11013604,
          SpeakNpcId = 110011,
          Subtitle = "I'm nothing like those stubborn old fools. I'm a pragmatist and would do anything that works.",
          TalkActionId = {
            [1] = "110011:DisagreeHead"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110136/1B92473E"
        },
        [11013604] = {
          Camera = "148.312668,2233.953125,666.561768,-0.001619,-68.792679,61.391247,39.663486,100000.0,false,Manual,22.0",
          ContentKR = "이 사람은... 그렇게 자랑하던 제자 아닌가? 네가 이렇게 한 건가?",
          DialogueId = 11013604,
          Duration = 5,
          FacialId = {
            [1] = "110011:Smile01"
          },
          FinalCamera = "165.08638,2264.316406,568.964294,-0.001626,-67.592896,61.591228,39.663486,100000.0,false,Manual,22.0",
          GUID = "1B924768",
          LookAt = {
            [1] = "110011:n(110010)"
          },
          NextDialogue = 11013605,
          SpeakNpcId = 110011,
          Subtitle = "Isn't this your favourite protege? You did this?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110136/1B924768"
        },
        [11013605] = {
          Camera = "151.53949,105.84375,142.877136,-0.001525,-17.594362,56.191444,60.0,100000.0,false,DoNotOverride,4.0",
          ContentKR = "하하, 나하고 거래를 하자. 이건 우리 둘만 알고 있어야 해. 제삼자는 내보내시지.",
          DialogueId = 11013605,
          Duration = 3,
          GUID = "1B924792",
          NextDialogue = 11013606,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"-2055.0979,-34.339844,173.937714,0.0,-2.394063,-0.00531,40.0,100000.0,false,DoNotOverride,4.0"},duration{0}},CameraMoveTo{TargetPosition{"-2055.097656,18.054688,173.937714,0.0,-2.394063,-0.00531,40.0,100000.0,false,DoNotOverride,4.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Heh, I was just setting the stage for a deal with you. I don't think we need a third party.",
          TalkActionId = {
