        },
        [11013607] = {
          Camera = "23.118408,168.939453,59.625854,-0.001587,2.603798,-68.594788,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "나가 있어, 펄시. 괜찮다. 요새 전체가 우리 손안에 있으니 녀석도 섣불리 공격할 수 없을 거다.",
          DialogueId = 11013607,
          Duration = 3,
          GUID = "1B9247E6",
          LookAt = {
            [1] = "110011:n(110012)"
          },
          NextDialogue = 11013608,
          RelatedWikiId = {
            [1] = 201016
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{110011},AnimationId{\"Talk02_End\"},Duration{3}}",
          SpeakNpcId = 110011,
          Subtitle = "Off you go, Falsi. It's alright, the entire fortress is in our hands. This old man dares not make a move.",
          TalkActionId = {
            [1] = "110011:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B9247E6"
