        },
        [11016502] = {
          Camera = "43.549805,139.308594,128.25798,0.001613,-1.609104,-101.194138,36.903526,100000.0,false,Manual,22.0",
          ContentKR = "...왜 갑자기 깬 거지? 가장 중요한 걸 묻고 있었는데!",
          DialogueId = 11016502,
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "52.8125,137.478516,128.257767,0.001613,-1.209135,-100.994232,36.903526,100000.0,false,Manual,22.0",
          GUID = "1B9422DC",
          LookAt = {
            [1] = "110022:n(110039)"
          },
          NextDialogue = 11016503,
          SpeakNpcId = 110039,
          Subtitle = "...Why did you wake up? My questioning had just reached a pivotal point!",
          TalkActionId = {
            [1] = "110022:Weita_Story_Awake_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110165/1B9422DC"
        },
        [11016503] = {
          Camera = "67.43457,-649.426758,129.53125,0.001605,-4.809197,104.412491,36.90353,100000.0,false,Manual,22.0",
          ContentKR = "괜찮습니다, 교도소장님. 제가 꿈에서 어떤 말들을 했는지 기억하고 있습니다. 하지만 이건 기밀과 관련되어 있으니, 단독 대화를 요청합니다.",
          DialogueId = 11016503,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942306",
          NextDialogue = 11016504,
          Scripts = "SitOrStand{ActorId{110022},State{\"Sit\"}}",
          SpeakNpcId = 110022,
          Subtitle = "It's alright, ma'am. I remember what I told you in my dreams. But this is classified, I request a private conversation with you.",
          VoiceName = "voice/$Locale$/story/1002/110165/1B942306"
        },
        [11016504] = {
          Camera = "-5.238281,-133.301758,125.070312,0.001531,-4.805598,92.405151,36.903526,105.270081,false,Manual,22.0",
          ContentKR = "그날의 진실을 있는 그대로 말씀드릴 테니 다 들은 후 교도소장님 마음속의 '정의'에 따라 결단을 내려 주십시오.",
          DialogueId = 11016504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B942330",
          NextDialogue = 11016505,
