        },
        [11017520] = {
          Camera = "699.135376,388.0625,157.425171,10.009494,-3.598785,-51.594585,40.0,100000.0,false,DoNotOverride,20.0",
          ContentKR = "전원을 종료하는 것만으로는 폭시코르를 멈출 수 없으니 스스로 멈추도록 두는 게 좋겠군.",
          DialogueId = 11017520,
          Duration = 3,
          FacialId = {
            [1] = "110010:Angry01"
          },
          FinalCamera = "699.135376,388.0625,156.380249,10.010453,-3.598785,-51.595715,40.0,100000.0,false,DoNotOverride,20.0",
          GUID = "1B94C9E0",
          NextDialogue = 11017521,
          SpeakNpcId = 110010,
          Subtitle = "Since we can't shut them down our way, we can let them do it in a self-destructive way.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C9E0"
        },
        [11017521] = {
          Camera = "992.544189,397.238281,178.074951,-0.0,-8.599126,-138.38974,40.000011,100000.0,false,DoNotOverride,20.0",
          ContentKR = "그러니까... 과부하로 폭시코르를 폭파하자는 것입니까? 알겠습니다.",
          DialogueId = 11017521,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94CA0A",
          Scripts = "PlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110022,
          Subtitle = "You mean... exploding the Phoxichor tank by overloading it? Got it.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94CA0A"
        },
        [11017601] = {
          ContentKR = "스페어 회전체 1호를 조작할 수 있을 것이다. 한 번 작동해봐라.",
          DialogueId = 11017601,
          GUID = "1B94D72A",
          SpeakNpcId = 110010,
          Subtitle = "Back-up Phoxynamo Wheel No.1 is ready. Now activate it.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D72A"
        },
        [11017602] = {
          ContentKR = "잘했다. 이제 내가 남은 세 개의 조작 권한도 해제해 주겠다.",
          DialogueId = 11017602,
          GUID = "1B94D754",
          NextDialogue = 11017603,
          SpeakNpcId = 110010,
          Subtitle = "Well done. I'll unlock the control authority for the remaining three Phoxynamo Wheels.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D754"
        },
        [11017603] = {
          ContentKR = "노란색 불이 들어오면 가동시키도록.",
          DialogueId = 11017603,
          GUID = "1B94D77E",
          SpeakNpcId = 110010,
          Subtitle = "Activate them once the yellow light is on.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D77E"
        },
        [11017604] = {
          ContentKR = "(회전체에 불이 들어왔어. 교관님이 해제에 성공하셨나 보네.)",
          DialogueId = 11017604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7A8",
          SpeakNpcId = 110022,
          Subtitle = "(The light is on. Looks like Sir Avar has made it on his side.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7A8"
        },
        [11017605] = {
          ContentKR = "<W>경고: 폭시코르의 작업량이 너무 많습니다. 남은 작업 가능량이 50% 미만입니다. 스페어 회전체의 사용을 즉시 중단하고 무단으로 자리를 이탈하지 마십시오.</>",
          DialogueId = 11017605,
          GUID = "1B94D7D2",
          NextDialogue = 11017606,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank is overloaded by 50%. Please shut down the Phoxynamo Wheels immediately; unauthorized departure is not permitted.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7D2"
        },
        [11017606] = {
          ContentKR = "(...서둘러야 해.)",
          DialogueId = 11017606,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7FC",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...I need to hurry up.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7FC"
        },
        [11017607] = {
          ContentKR = "3호도 됐다. 서둘러라!",
          DialogueId = 11017607,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D826",
          SpeakNpcId = 110010,
          Subtitle = "No.3 is also ready. Go get it!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D826"
        },
        [11017608] = {
          ContentKR = "(후...)",
          DialogueId = 11017608,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D850",
          NextDialogue = 11017609,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Phew...)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D850"
        },
        [11017609] = {
          ContentKR = "아주 깔끔하게 잘했군.",
          DialogueId = 11017609,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D87A",
          SpeakNpcId = 110010,
          Subtitle = "Quick and clean! Well done, kid.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D87A"
        },
        [11017610] = {
          ContentKR = "이제 마지막 하나 남았다!",
          DialogueId = 11017610,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D8A4",
          SpeakNpcId = 110010,
          Subtitle = "The control authority is unlocked. This is the last one!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8A4"
        },
        [11017611] = {
          ContentKR = "<W>경고: 폭시코르가 곧 폭파됩니다. 자수하십시오.</>",
          DialogueId = 11017611,
          GUID = "1B94D8CE",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank sabotage detected. Anyone held responsible should confess your crime.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8CE"
        },
        [11017612] = {
          ContentKR = "서둘러! 어서 안전문 뒤로 물러서!",
          DialogueId = 11017612,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D8F8",
          NextDialogue = 11017613,
          SpeakNpcId = 110010,
          Subtitle = "Run! Get behind the safety door!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8F8"
        },
        [11017613] = {
          ContentKR = "<W>경고: 폭시코르가 곧 폭파됩니다. 자수하십시오.</>",
          DialogueId = 11017613,
          GUID = "1B94D922",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank sabotage detected. Anyone held responsible should confess your crime.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D922"
        },
        [11017701] = {
          ContentKR = "이쪽입니다...",
          DialogueId = 11017701,
          GUID = "1B94E792",
          SpeakNpcId = 110017,
          Subtitle = "This way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E792"
        },
        [11017702] = {
          ContentKR = "이쪽으로 내려가면 하수도입니다.",
          DialogueId = 11017702,
          GUID = "1B94E7BC",
          NextDialogue = 11017703,
          SpeakNpcId = 110017,
          Subtitle = "Sir, we can get into the sewer tunnels from here.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E7BC"
        },
        [11017703] = {
          ContentKR = "카론, 빨리 앞장서라고.",
          DialogueId = 11017703,
          GUID = "1B94E7E6",
          NextDialogue = 11017704,
          SpeakNpcId = 110016,
          Subtitle = "You go first, Charon.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E7E6"
        },
        [11017704] = {
          ContentKR = "예? 아, 알겠습니다...",
          DialogueId = 11017704,
          GUID = "1B94E810",
          SpeakNpcId = 110017,
          Subtitle = "Yes, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E810"
        },
        [11017705] = {
          ContentKR = "이 뜨거운 연기는...",
          DialogueId = 11017705,
          GUID = "1B94E83A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017706,
          SpeakNpcId = 110034,
          Subtitle = "The hot steam...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E83A"
        },
        [11017706] = {
          ContentKR = "조심하세요! 앞에 냉각기가 있어서 가까이 가면 다칠 수 있어요!",
          DialogueId = 11017706,
          GUID = "1B94E864",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Watch out! There's a condenser up ahead. You'll get hurt if you get too close!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E864"
        },
        [11017707] = {
          ContentKR = "냉각기에서 나오는 스팀은 정말 위험합니다. 멀리 떨어지시는 게 좋을 겁니다.",
          DialogueId = 11017707,
          GUID = "1B94E88E",
          SpeakNpcId = 110017,
          Subtitle = "Sir... Steam produced by the condenser is dangerous. We should not stay too long.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E88E"
        },
        [11017708] = {
          ContentKR = "하아, 후... 너무 덥네요... 괜찮으세요?",
          DialogueId = 11017708,
          GUID = "1B94E8B8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Huff, huff... It's so hot... Are you okay, sir?",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E8B8"
        },
        [11017709] = {
          ContentKR = "이쪽입니다...",
          DialogueId = 11017709,
          GUID = "1B94E8E2",
          NextDialogue = 11017710,
          SpeakNpcId = 110017,
          Subtitle = "This way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E8E2"
        },
        [11017710] = {
          ContentKR = "피, 필토이드예요...!",
          DialogueId = 11017710,
          GUID = "1B94E90C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017711,
          SpeakNpcId = 110034,
          Subtitle = "Fil...Filthoids!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E90C"
        },
        [11017711] = {
          ContentKR = "일반인들은 모두 내 뒤로!",
          DialogueId = 11017711,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94E936",
          SpeakNpcId = 110022,
          Subtitle = "The unarmed retreat behind me.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E936"
        },
        [11017712] = {
          ContentKR = "살려주셔서 감사합니다! 제국 병사라고 해서 다 나쁜...",
          DialogueId = 11017712,
          GUID = "1B94E960",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017713,
          SpeakNpcId = 110034,
          Subtitle = "Thank you for saving our lives! It turned out not all the Imperial soldiers are...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E960"
        },
        [11017713] = {
          ContentKR = "앗, 죄송합니다! 그러니까 제 말은, 제국 병사들도 포세이큰 놈들처럼 폭력적이거나 피도 눈물도 없을 거라고 생각했는데, 제 오해였군요!",
          DialogueId = 11017713,
          GUID = "1B94E98A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Ah, sorry! I mean, I used to think that Imperial soldiers were no different from those Forsaken rotters. But now I know I was wrong!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E98A"
        },
        [11017714] = {
          ContentKR = "저기 저 사람은... 아바르 중령님입니다!",
          DialogueId = 11017714,
          GUID = "1B94E9B4",
          NextDialogue = 11017715,
          SpeakNpcId = 110015,
          Subtitle = "Over there is... Sir Avar!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E9B4"
        },
        [11017715] = {
          ContentKR = "(휴, 드디어 만났네.)",
          DialogueId = 11017715,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94E9DE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Nice, we can safely join forces with them.)",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E9DE"
        },
        [11017801] = {
          ContentKR = "멈춰.",
          DialogueId = 11017801,
          GUID = "1B94F7FA",
          SpeakNpcId = 110010,
          Subtitle = "Here it is.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F7FA"
        },
        [11017802] = {
          ContentKR = "여기 시야가 괜찮은 것 같군. 여기에서 중앙 관제실을 포격한다.",
          DialogueId = 11017802,
          GUID = "1B94F824",
          SpeakNpcId = 110010,
          Subtitle = "The view is good. Let's bombard the central control room from here.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F824"
        },
        [11017803] = {
          ContentKR = "젠장...",
          DialogueId = 11017803,
          GUID = "1B94F84E",
          SpeakNpcId = 110010,
          Subtitle = "Damn it...",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F84E"
        },
        [11017804] = {
          ContentKR = "필토이드부터 처리한다. 저들이 방해하지 못하게 해야 한다!",
          DialogueId = 11017804,
          GUID = "1B94F878",
          SpeakNpcId = 110010,
          Subtitle = "Take down the Filthoids first. Don't let them distract you!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F878"
        },
        [11017805] = {
          ContentKR = "좋아, 모두 처리했군.",
          DialogueId = 11017805,
          GUID = "1B94F8A2",
          NextDialogue = 11017806,
          SpeakNpcId = 110010,
          Subtitle = "Alright, all cleared out.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8A2"
        },
        [11017806] = {
          ContentKR = "자, 그러면 지금부터는 비교적 금방 부서질 것 같은 <H>옆문</>부터 포격한다.",
          DialogueId = 11017806,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94F8CC",
          SpeakNpcId = 110010,
          Subtitle = "Next, let's start with the relatively thin side door.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8CC"
        },
        [11017807] = {
          ContentKR = "멈추지 말고 계속 포격해! 고폭탄은 되는대로 계속 사용하고.",
          DialogueId = 11017807,
          GUID = "1B94F8F6",
          SpeakNpcId = 110010,
          Subtitle = "Keep it up! Use the High-Explosive Shells!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8F6"
        },
        [11017808] = {
          ContentKR = "거의 끝났어! 가서 확인해 봐!",
          DialogueId = 11017808,
          GUID = "1B94F920",
          SpeakNpcId = 110010,
          Subtitle = "That's our cue — move in.",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957C0C"
        },
        [11017809] = {
          ContentKR = "멍하니 서있지 말고, 서둘러!",
          DialogueId = 11017809,
          GUID = "1B94F94A",
          SpeakNpcId = 110010,
          Subtitle = "Snap out of it! Keep firing!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F94A"
        },
        [11017810] = {
          ContentKR = "괜찮나? 어디 다친 건가?",
          DialogueId = 11017810,
          GUID = "1B94F974",
          SpeakNpcId = 110010,
          Subtitle = "Are you okay? Did you get hurt?",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F974"
        },
        [11017811] = {
          ContentKR = "그렇게 두드려서 어느 세월에 다 부순다는 건가! 어서 가서 포격이나 해.",
          DialogueId = 11017811,
          GUID = "1B94F99E",
          SpeakNpcId = 110010,
          Subtitle = "I'll be an old man by the time you break the door with that! Go back to the cannon.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F99E"
        },
        [11017812] = {
          DialogueId = 11017812,
          GUID = "1B94F9C8",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F9C8"
        },
        [11017901] = {
          ContentKR = "어서 가라. 계속 통신할 테니 내 지시 잘 듣고.",
          DialogueId = 11017901,
          GUID = "1B950862",
          SpeakNpcId = 110010,
          Subtitle = "Go, stay in touch, and be careful.",
          VoiceName = "voice/$Locale$/story/1002/110179/1B950862"
        },
        [11017902] = {
          ContentKR = "빅...",
          DialogueId = 11017902,
          GUID = "1B95088C",
          SpeakNpcId = 110020,
          Subtitle = "Vic...",
          VoiceName = "voice/$Locale$/story/1002/110179/1B95088C"
        },
        [11017903] = {
          ContentKR = "준비다 됐으면, 회전체를 활성화하고 출발해.",
          DialogueId = 11017903,
          GUID = "1B9508B6",
          SpeakNpcId = 110010,
          Subtitle = "Activate the Phoxynamo Wheels and set off whenever you're ready.",
          VoiceName = "voice/$Locale$/story/1002/110179/1B9508B6"
        },
        [11018001] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "잠깐!",
          DialogueId = 11018001,
          GUID = "1B9518CA",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110034:n(110010)",
            [3] = "110015:n(110010)",
            [4] = "110017:n(110010)"
          },
          NextDialogue = 11018002,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201013,
            [3] = 201015,
            [4] = 408007,
            [5] = 101004
          },
          Scripts = [[
PARA{
MoveTo{ActorId{110017},MoveSpeed{150},TargetPoint{"fulankemoVe"}},
MoveTo{ActorId{110010},MoveSpeed{150},TargetPoint{"fix30awa"}},
MoveTo{ActorId{110022},MoveSpeed{150},TargetPoint{"qiannanzhumoVe"}},
MoveTo{ActorId{110034},MoveSpeed{150},TargetPoint{"kajiamoVe"}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Wait.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B9518CA"
        },
        [11018002] = {
          Camera = "436.131592,1.919922,136.800903,0.000139,-1.999415,173.000534,35.0,100000.0,false,Manual,22.0",
          ContentKR = "다음 임무는 절대 실수하면 안 되니 위험 요소부터 배제하는 게 좋겠군. 그러니 여자 아이와 노인은 함께 갈 수 없다.",
          DialogueId = 11018002,
          GUID = "1B9518F4",
          LookAt = {
            [1] = "110010:n(110034)"
          },
          NextDialogue = 11018003,
          SpeakNpcId = 110010,
          Subtitle = "We cannot afford any mistakes in our mission moving forward. We have to rule out all the potential risks — this girl and the old man, they should stop here.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B9518F4"
        },
        [11018003] = {
          Camera = "27.165649,69.382324,136.855469,0.000141,-0.199305,10.000502,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "...왜요? 방금 보셨잖아요. 주변에 필토이드가 잔뜩이에요. 함께 갈 수 없다면 저와 할아버지는 죽은 목숨일 거예요!",
          DialogueId = 11018003,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B95191E",
          LookAt = {
            [1] = "110034:n(110010)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11018004,
          Scripts = "CameraMoveTo{_delay{8},TargetPosition{\"-263.419067,35.512207,120.94928,0.000142,0.800758,5.202505,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}}",
          SpeakNpcId = 110034,
          Subtitle = "...Why? As you can see, there are Filthoids all over this place. If you leave us here, Mr Frank and I will die!",
          VoiceName = "voice/$Locale$/story/1002/110180/1B95191E"
        },
        [11018004] = {
          Camera = "-143.649597,-86.15332,142.109314,0.000144,-2.799244,26.800621,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "나리, 제가 도울게요! 지금까지 길도 잘 안내했잖아요... 제발... 제발 저희를 버리지 말아 주세요!",
          DialogueId = 11018004,
          GUID = "1B951948",
          LookAt = {
            [1] = "110034:n(110022)",
            [2] = "110017:n(110010)"
          },
          NextOptions = {
            [1] = 11018005,
            [2] = 11018008
          },
          Scripts = "LookAt{_delay{1},LookAtDescription{\"110022:n(110034)\"}}",
          SpeakNpcId = 110034,
          Subtitle = "Sir, please! We offered help, we led you all the way here so you could rendezvous with them... Please... I'm begging you, don't leave us behind!",
          VoiceName = "voice/$Locale$/story/1002/110180/1B951948"
        },
        [11018005] = {
          ContentKR = "카지아를 믿는다",
          DialogueId = 11018005,
          GUID = "1B951972",
          ImprPlusId = 1009,
          NextDialogue = 11018006,
          Subtitle = "Trust Katya"
        },
        [11018006] = {
          Camera = "-372.804108,82.572754,153.340088,0.000149,-3.999233,-7.999348,50.000011,450.777496,false,DoNotOverride,7.0",
          ContentKR = "교관님 걱정하지 않으셔도 될 것 같습니다. 이 사람들이 우리 편이 아니었다면, 지하수도의 길도 제대로 알려주지 않았을 게 분명합니다.",
          DialogueId = 11018006,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95199C",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110010:n(110010)"
          },
          NextDialogue = 11018007,
          SpeakNpcId = 110022,
          Subtitle = "Maybe you're overthinking it, sir. If they were enemies, misleading us in the sewer tunnels would be a better idea, but they didn't do that.",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B95199C"
        },
        [11018007] = {
          Camera = "32.585205,14.534668,146.054871,0.00015,-1.399219,162.798279,50.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "저들이 다른 속셈이 있는 거라면? 방금도 이 요새를 '너무 잘 알고' 있다는 생각 안 드나?",
          DialogueId = 11018007,
          GUID = "1B9519C6",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11018011,
          SpeakNpcId = 110010,
          Subtitle = "What if they're up to something else? Don't you think that they are \"too familiar\" with everything in this fortress so far?",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B9519C6"
        },
        [11018008] = {
          ContentKR = "카지아를 믿지 않는다",
          DialogueId = 11018008,
          GUID = "1B9519F0",
          ImprPlusId = 1008,
          NextDialogue = 11018009,
          Subtitle = "Do not trust Katya"
        },
        [11018009] = {
          Camera = "209.203857,228.964844,146.143616,0.000167,-4.599087,-120.406746,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentKR = "...교관님 판단에 동의합니다.",
          DialogueId = 11018009,
          ExStoryInfo = "EXPlayer",
          GUID = "1B951A1A",
          LookAt = {
            [1] = "110022:n(110034)"
          },
          NextDialogue = 11018010,
          Scripts = "SetRotation{SetRotationDescription{\"110022:n(110034)\"}}",
          SpeakNpcId = 110022,
          Subtitle = "...I agree with Sir Avar.",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A1A"
        },
        [11018010] = {
          Camera = "-127.301941,-114.787598,142.109314,0.000143,-1.599302,31.20196,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "중앙 관제실에 들어가기 전이라면 모를까 아무래도 넌 이 요새에 대해 '너무 잘 알고' 있는 것 같군.",
          DialogueId = 11018010,
          ExStoryInfo = "EXPlayer",
          GUID = "1B951A44",
          LookAt = {
            [1] = "110010:n(110022)",
            [2] = "110022:n(110034)"
          },
          NextDialogue = 11018011,
          SpeakNpcId = 110022,
          Subtitle = "I could have trusted you if we haven't got into the central control room. But now it seems to me that you're just \"too familiar\" with this fortress.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A44"
        },
        [11018011] = {
          Camera = "414.556763,7.735352,138.894348,0.000155,-2.599324,169.392776,50.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "중앙 관제실은 론샤 요새의 심장부다. 포세이큰 동맹이라고 해도 길에서 마구잡이로 데려온 사람들이 이런 핵심 지역을 돌아다니도록 놔두지 않았을 것이다.",
          DialogueId = 11018011,
          GUID = "1B951A6E",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11018012,
          SpeakNpcId = 110010,
          Subtitle = "The central control room is the core of Lonza Fortress, even the Forsakens wouldn't let their enslaved labor in such an essential place.",
          TurnTo = {
            [1] = "110022:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A6E"
        },
        [11018012] = {
          ContentKR = "이렇게 내부 동선을 제 집인 양 잘 알고 있다는 건 말이 안 돼.",
          DialogueId = 11018012,
          GUID = "1B951A98",
          LookAt = {
            [1] = "110010:n(110034)"
          },
          NextDialogue = 11018013,
          SpeakNpcId = 110010,
          Subtitle = "You're not supposed to know the routes so well.",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951A98"
        },
        [11018013] = {
          Camera = "-38.761108,62.896484,133.47168,0.000157,0.600497,8.994007,50.000008,100000.0,false,DoNotOverride,22.0",
          ContentKR = "아... 그건...",
          DialogueId = 11018013,
          GUID = "1B951AC2",
          LookAt = {
            [1] = "110034:n(110010)"
          },
          NextDialogue = 11018014,
          SpeakNpcId = 110034,
          Subtitle = "Umm... That's because—",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951AC2"
        },
        [11018014] = {
          Camera = "528.188843,-8.837402,130.242065,0.000159,-1.599541,172.787582,50.000008,824.380615,false,Manual,10.0",
          ContentKR = "꼬마 아가씨, 연기력이 대단한데. 황성의 극단에 들어가 보는 건 어떤가?",
          DialogueId = 11018014,
          GUID = "1B951AEC",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11018015,
          SpeakNpcId = 110010,
          Subtitle = "If you're so interested in acting, little girl, I suggest you find a job in the Grand Theatre in the capital.",
          VoiceName = "voice/$Locale$/story/1002/110180/1B951AEC"
        }
      }
    end
  },
  {
    MinKey = 11018015,
    MaxKey = 11019414,
    Loader = function()
      return {
        [11018015] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "시간이 없으니 이만 가지. 레온, 넌 여기 남아서 저들을 잘 지켜보도록.",
          DialogueId = 11018015,
          GUID = "1B951B16",
          SpeakNpcId = 110010,
          Subtitle = "We're running out of time. Let's go. Leon, stay here and keep an eye on them.",
          TalkActionId = {
            [1] = "110010:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110180/1B951B16"
        },
        [11018101] = {
          ContentKR = "젊은 병사는 차가운 벽에 몸을 기댄 채 이미 숨을 거두고 있었다. 거대한 발톱이 그의 가슴을 꿰뚫고 지나간 흔적이 선명했다. 방금 마주한 거대한 필토이드 앞에서, 평범한 인간의 힘은 너무나도 나약했다.",
          DialogueId = 11018101,
          GUID = "1B952932",
          Subtitle = "The young soldier lies slumped against the cold wall, lifeless. A massive claw had torn straight through his chest. Against something like that... an ordinary human never stood a chance.",
          VoiceName = "voice/$Locale$/story/1002/110181/1B952932"
        },
        [11018102] = {
          ContentKR = "(...편히 쉬기를.)",
          DialogueId = 11018102,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95295C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...Rest in peace.)",
          VoiceName = "voice/$Locale$/story/1002/110181/1B95295C"
        },
        [11018201] = {
          ContentKR = "저 포세이큰 놈부터 먼저 처리해! 이 필토이드들은 그놈이 조종하고 있어!",
          DialogueId = 11018201,
          GUID = "1B95399A",
          SpeakNpcId = 110010,
          Subtitle = "Take out that Forsaken guy first — the Filthoids are following his lead!",
          VoiceName = "voice/$Locale$/story/1002/110182/1B95399A"
        },
        [11018202] = {
          ContentKR = "빅, 모니카, 조금만 더 버텨... 곧 갈게.",
          DialogueId = 11018202,
          GUID = "1B9539C4",
          SpeakNpcId = 110010,
          Subtitle = "Vic, Monica... hang in there. We're coming.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B9539C4"
        },
        [11018203] = {
          ContentKR = "(좋아, 종료시켰어. 이제 남은 회전체를 찾아보자.)",
          DialogueId = 11018203,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9539EE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Alright, that's one down. Time to find the rest.)",
          VoiceName = "voice/$Locale$/story/1002/110182/1B9539EE"
        },
        [11018204] = {
          ContentKR = "남자의 새 군복은 갈기갈기 찢어져 있었고, 너덜너덜한 천 사이로 수많은 발톱 자국과 이빨 자국이 선명하게 드러났다. 그는 수많은 필토이드에게 물어뜯겨 처참하게 죽음을 맞이한 듯했다. 푸르게 질린 손가락은 여전히 부러진 칼날을 단단히 움켜쥐고 있었고, 마지막 순간까지도 필토이드들과 치열하게 싸웠음을 보여주고 있었다.",
          DialogueId = 11018204,
          GUID = "1B953A18",
          NextDialogue = 11018205,
          Subtitle = "His uniform — freshly issued — is in tatters. Beneath the torn fabric, claw slashes and bite marks mar his body. He was clearly ripped apart by a swarm of Filthoids. In his lifeless grasp, a broken blade — knuckles pale and stiff — a silent testament that he fought to the bitter end.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A18"
        },
        [11018205] = {
          ContentKR = "그의 곁에는 명패 하나가 조용히 놓여 있었다. 군단이 신병들에게 지급하는 명패라는 걸 알아볼 수 있다. 앞면에는 그의 이름, 빅 지라드가 새겨져 있었고, 뒷면에는 칼로 새긴 듯한 작은 글씨가 남아 있었다. \"모니카, 다음 사격 대회에선 내가 꼭 이길 거야.\"",
          DialogueId = 11018205,
          GUID = "1B953A42",
          Subtitle = "Beside him, an identity disc lies quietly. You recognise it instantly — standard issue for fresh recruits. The front reads: Vic Girard. On the back, a message scratched in with a blade: \"Monica — next time, I'm beating you at the shooting range.\"",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A42"
        },
        [11018206] = {
          ContentKR = " (폭시코르가 폭발하고 나서, 이 장치들도 전부 멈춰 버렸군.)",
          DialogueId = 11018206,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953A6C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Looks like destroying the Phoxichor tank knocked everything offline.)",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A6C"
        },
        [11018207] = {
          ContentKR = "이 짐승들이... 모두를... 이렇게...",
          DialogueId = 11018207,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953A96",
          NextDialogue = 11018208,
          SpeakNpcId = 110022,
          Subtitle = "These beasts... They killed everyone...",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A96"
        },
        [11018208] = {
          ContentKR = "<W>그래, 바로 그거야. 증오가 심장을 후벼 파고, 이렇게까지 피를 원한 적은 한 번도 없었지.</>",
          DialogueId = 11018208,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953AC0",
          NextDialogue = 11018209,
          SnapShot = "MONSTER",
          Subtitle = "Yes... let that hatred fester. You've never craved blood like this before, have you?",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953AC0"
        },
        [11018209] = {
          ContentKR = "<W>이 괴물들은 피도 눈물도 없어. 네 분노도, 슬픔도 전혀 느끼지 못해. 그걸 증오하고 있지?</>",
          DialogueId = 11018209,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953AEA",
          NextDialogue = 11018210,
          SnapShot = "MONSTER",
          Subtitle = "If only they could bleed. If only they could weep. Then maybe they'd understand the fire roaring in your chest.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953AEA"
        },
        [11018210] = {
          ContentKR = "<W>하지만 괜찮아. 그냥 검을 휘둘러, 또 휘두르고, 계속 휘두르면 돼...</>",
          DialogueId = 11018210,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B14",
          NextDialogue = 11018211,
          SnapShot = "MONSTER",
          Subtitle = "But none of that matters now. Just raise your blade. Swing it. Again — and again.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B14"
        },
        [11018211] = {
          ContentKR = "(...안 돼!)",
          DialogueId = 11018211,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B3E",
          NextDialogue = 11018212,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...No!)",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B3E"
        },
        [11018212] = {
          ContentKR = "(아직도 내가 구해야 할 사람들이 있어... 여기서 필토이드들에게 발목 잡힐 순 없어!)",
          DialogueId = 11018212,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B68",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(They're waiting for me... I can't let these Filthoids drag me down!)",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B68"
        },
        [11018301] = {
          ContentKR = "버티세요, 대장님이 곧 오십니다!",
          DialogueId = 11018301,
          GUID = "1B954A02",
          SpeakNpcId = 110016,
          Subtitle = "Hang in there! The captain's on the way!",
          VoiceName = "voice/$Locale$/story/1002/110183/1B954A02"
        },
        [11018302] = {
          ContentKR = "저희는 포세이큰 동맹이 요새를 개조하는 데 일손이 필요해서 끌려왔을 뿐이에요. 심지어 솔라는 쏙 빼고 카론만 골라서 끌려왔죠...",
          DialogueId = 11018302,
          FacialId = {
            [1] = "110034:Sad01"
          },
          GUID = "1B954A2C",
          NextDialogue = 11011824,
          RelatedWikiId = {
            [1] = 201015
          },
          SpeakNpcId = 110034,
          Subtitle = "The Forsakens grabbed us from our homes and forced us to help rebuild this fortress. They left the Solas in peace and only took the Charons...",
          VoiceName = "voice/$Locale$/story/1002/110183/1B954A2C"
        },
        [11018401] = {
          Camera = "-274.711914,194.082031,124.856079,0.00015,-1.800322,-91.197739,35.000008,229.080856,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "맞아요. 솔라보다 힘이 세고 추위나 더위를 덜 탄다는 이유만으로요. 사람들 눈에는 저희가 포세이큰 동맹과 같은 부류로 보이겠지만, 그 사람들은 단 한 번도 저희를 '동족'으로 대한 적이 없어요.",
          DialogueId = 11018401,
          FacialId = {
            [1] = "110034:None"
          },
          FinalCamera = "-275.310547,165.044922,123.943848,0.00015,-1.800322,-91.197739,35.000008,208.205566,false,Manual,2.8",
          GUID = "1B955A6A",
          LookAt = {
            [1] = "110034:n(110016)"
          },
          NextDialogue = 11011826,
          Scripts = "PlayFacial{_delay{6},ActorId{110034},FacialId{\"Sad01\"}}",
          SpeakNpcId = 110034,
          Subtitle = "Exactly. They exploit us because Charons are stronger and withstand extreme heat and cold better than Solas. You may think we're the same as The Forsakens, but they've never accepted us as their own.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110184/1B955A6A"
        },
        [11018402] = {
          Camera = "-114.378906,-14.172058,128.482971,-1.0,1.597315,-43.841934,18.000004,100000.0,false,DoNotOverride,20.0",
          ContentKR = "그래, 지금 요새의 동력이 마비됐으니 우선 이 캐논을 옮길 방법을 찾아야 해.",
          DialogueId = 11018402,
          FinalCamera = "-116.232422,-16.133057,128.436096,-1.0,1.597315,-43.44199,18.000004,100000.0,false,DoNotOverride,20.0",
          GUID = "1B91327B",
          NextDialogue = 11011939,
          Scripts = [[
SEQ{
PlayAnimation{_delay{7},ActorId{110010},AnimationId{"Call_Start"},Duration{0}},
PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/signal_on"},PlayAs2D{true}}
}
]],
          SpeakNpcId = 110010,
          Subtitle = "Exactly. But the power to the entire fortress has been cut off, we need to get this thing there.",
          TalkActionId = {
            [1] = "110010:Think_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110119/1B91327B"
        },
        [11018403] = {
          ContentKR = "먼저 회전체를 가동해서 이 구역의 전력을 복구해.",
          DialogueId = 11018403,
          GUID = "1B955ABE",
          NextDialogue = 11017417,
          SpeakNpcId = 110010,
          Subtitle = "Let's get the Phoxynamo Wheels up and running — it should bring this sector back online.",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955ABE"
        },
        [11018404] = {
          ContentKR = "포를 거의 다 조정했고, 모의 전장 지역의 에너지도 복구됐어.",
          DialogueId = 11018404,
          GUID = "1B955AE8",
          NextDialogue = 11018405,
          SpeakNpcId = 110010,
          Subtitle = "Turret's aligned. The Sim Battlefield's powered up as well.",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955AE8"
        },
        [11018405] = {
          ContentKR = "가자, 콘솔로 가서 문을 열자. 나도 함께 하지.",
          DialogueId = 11018405,
          GUID = "1B955B12",
          SpeakNpcId = 110010,
          Subtitle = "Let's head to the control panel — I'll open the gate with you.",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955B12"
        },
        [11018406] = {
          ContentKR = "모의 전장 지역이 성공적으로 초기화되었습니다. 모의 전장이 재가동 중입니다.",
          DialogueId = 11018406,
          GUID = "1B955B3C",
          NextDialogue = 11018407,
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Simulation successfully overwritten. Reboot in progress.",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955B3C"
        },
        [11018407] = {
          ContentKR = "현재 테스트 환경: 코퀴투스 주, 아이스레이크 시티. 통로가 개방되었습니다. 훈련 인원, 대기 완료.",
          DialogueId = 11018407,
          GUID = "1B955B66",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Test environment: Icelake, Cocytus. Gate unlocked. Training personnel, standby.",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955B66"
        },
        [11018408] = {
          ContentKR = "문이 열렸다. 가자, 포대로 돌아가자.",
          DialogueId = 11018408,
          GUID = "1B955B90",
          SpeakNpcId = 110010,
          Subtitle = "The gate's open. Let's get back to the turret.",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955B90"
        },
        [11018409] = {
          ContentKR = "(이제 포대를 가동할 수 있겠어.)",
          DialogueId = 11018409,
          ExStoryInfo = "EXPlayer",
          GUID = "1B955BBA",
          SpeakNpcId = 110022,
          Subtitle = "(Locked and loaded.)",
          VoiceName = "voice/$Locale$/story/1002/110184/1B955BBA"
        },
        [11018501] = {
          ContentKR = "{nickname2}, 무사히 다시 만나서 다행입니다.",
          DialogueId = 11018501,
          GUID = "1B956AD2",
          SpeakNpcId = 110020,
          Subtitle = "! Thank goodness you're safe.",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956AD2"
        },
        [11018502] = {
          ContentKR = "아, 맞네요. 이건 빅이 남긴 겁니다. 당신이... 이걸 보관하는 게 좋을 것 같습니다.",
          DialogueId = 11018502,
          ExStoryInfo = "EXPlayer",
          GUID = "1B956AFC",
          NextDialogue = 11018503,
          SpeakNpcId = 110022,
          Subtitle = "I found this on Vic. Thought you should have it.",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956AFC"
        },
        [11018503] = {
          ContentKR = "이건... 빅의 명패...",
          DialogueId = 11018503,
          GUID = "1B956B26",
          NextDialogue = 11018504,
          SpeakNpcId = 110020,
          Subtitle = "His identity disc...",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B26"
        },
        [11018504] = {
          ContentKR = "\"모니카, 다음 사격 대회에선 내가 꼭 이길 거야\"라니... 하, 하하... 이 녀석, 이게 뭐야...",
          DialogueId = 11018504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B956B50",
          NextDialogue = 11018505,
          SpeakNpcId = 110022,
          Subtitle = "\"Monica — next time, I'm beating you at the shooting range.\" ...Heh. Haha... That idiot. What kind of farewell is that...",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B50"
        },
        [11018505] = {
          ContentKR = "이렇게까지 마음에 담아둘 줄 알았으면... 지난번엔 그냥 져줄걸...",
          DialogueId = 11018505,
          GUID = "1B956B7A",
          NextDialogue = 11018506,
          SpeakNpcId = 110020,
          Subtitle = "If I'd known he'd be that petty... maybe I would've let him win...",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956B7A"
        },
        [11018506] = {
          ContentKR = "...모니카, 앞으로 또 힘든 싸움이 기다리고 있어요. 정신 똑바로 차려주세요.",
          DialogueId = 11018506,
          ExStoryInfo = "EXPlayer",
          GUID = "1B956BA4",
          NextDialogue = 11018507,
          SpeakNpcId = 110022,
          Subtitle = "...Monica. We've got another fight ahead. Stay sharp.",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956BA4"
        },
        [11018507] = {
          ContentKR = "...알겠습니다. 이걸 전해줘서 고마워요.",
          DialogueId = 11018507,
          GUID = "1B956BCE",
          SpeakNpcId = 110020,
          Subtitle = "I... Yes, sir. And thank you... for bringing this back.",
          VoiceName = "voice/$Locale$/story/1002/110185/1B956BCE"
        },
        [11018601] = {
          ContentKR = "뒤쪽을 조심해!",
          DialogueId = 11018601,
          GUID = "1B957B3A",
          SpeakNpcId = 110010,
          Subtitle = "Watch your six!",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957B3A"
        },
        [11018602] = {
          ContentKR = "다른 방향도 주의해!",
          DialogueId = 11018602,
          GUID = "1B957B64",
          SpeakNpcId = 110010,
          Subtitle = "Stay alert — they're coming from all sides.",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957B64"
        },
        [11018603] = {
          ContentKR = "좋았어!",
          DialogueId = 11018603,
          GUID = "1B957B8E",
          SpeakNpcId = 110010,
          Subtitle = "Nice shot!",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957B8E"
        },
        [11018604] = {
          ContentKR = "이놈이 우두머리야! 해치워!",
          DialogueId = 11018604,
          GUID = "1B957BB8",
          SpeakNpcId = 110010,
          Subtitle = "That's their leader — bring it down!",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957BB8"
        },
        [11018605] = {
          ContentKR = "멋졌어! 역시 우리의 폭파 전문가!",
          DialogueId = 11018605,
          GUID = "1B957BE2",
          SpeakNpcId = 110010,
          Subtitle = "Nice work. You've got a real talent for demolitions.",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957BE2"
        },
        [11018606] = {
          ContentKR = "거의 끝났어! 가서 확인해 봐!",
          DialogueId = 11018606,
          GUID = "1B957C0C",
          SpeakNpcId = 110010,
          Subtitle = "That's our cue — move in.",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957C0C"
        },
        [11018701] = {
          ContentKR = "이 꼬마 아가씨는 포세이큰 동맹 소속이야, 잘 지켜보도록!",
          DialogueId = 11018701,
          GUID = "1B958BA2",
          IsBlack = 1,
          SpeakNpcId = 110010,
          Subtitle = "This girl's with The Forsakens. Keep an eye on her.",
          VoiceName = "voice/$Locale$/story/1002/110187/1B958BA2"
        },
        [11018702] = {
          ContentKR = "방어 모드가 활성화되었습니다. 먼저 안전 모드로 재설정하세요.",
          DialogueId = 11018702,
          GUID = "1B958BCC",
          NextOptions = {
            [1] = 11018801,
            [2] = 11018802,
            [3] = 11018804
          },
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Defence Mode currently active. Please switch to Safe Mode to proceed.",
          VoiceName = "voice/$Locale$/story/1002/110187/1B958BCC"
        },
        [11018801] = {
          ContentKR = "안전 모드 활성화",
          DialogueId = 11018801,
          GUID = "1B959C0A",
          Subtitle = "Switch to Safe Mode"
        },
        [11018802] = {
          ContentKR = "방어 모드 활성화",
          DialogueId = 11018802,
          GUID = "1B959C34",
          NextDialogue = 11018803,
          Subtitle = "Switch to Defence Mode"
        },
        [11018803] = {
          ContentKR = "(머리 위에서 붉은 불빛이 깜빡이고 있다. 지금은 방어 모드다.)",
          DialogueId = 11018803,
          GUID = "1B959C5E",
          NextDialogue = 11018702,
          Subtitle = "(Red light's on. This must be the Defence Mode.)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959C5E"
        },
        [11018804] = {
          ContentKR = "자폭 모드 활성화",
          DialogueId = 11018804,
          GUID = "1B959C88",
          NextDialogue = 11018805,
          Subtitle = "Switch to Self-Destruct Mode"
        },
        [11018805] = {
          ContentKR = "(?)",
          DialogueId = 11018805,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959CB2",
          NextDialogue = 11018806,
          SpeakNpcId = 110022,
          Subtitle = "(...What?)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959CB2"
        },
        [11018806] = {
          ContentKR = "(정말 이 버튼을 눌러야 하나...?)",
          DialogueId = 11018806,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959CDC",
          NextDialogue = 11018702,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Am I actually thinking about pressing that?)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959CDC"
        },
        [11018807] = {
          ContentKR = "론샤 요새 정기 안전 점검\n주요 위험:\n1. 지하수도: 수도관이 심하게 노화되어 고압 가스 누출이 잦고, 정비 인원 화상 사고가 종종 있습니다.\n답변: 오히려 잘된 일이군요. 우리 정비 인원도 접근할 수 없다면, 그 교활하고 끈질긴 포세이큰 동맹 역시 하수도를 통해 침입할 수 없을 테니까요.",
          DialogueId = 11018807,
          GUID = "1B959D06",
          NextDialogue = 11018808,
          Subtitle = [[
Lonza Fortress Maintenance Log
Safety Hazards:
1. Underground Sewers: Severe corrosion in the piping. High-pressure gas leaks occur frequently. Several maintenance personnel have already suffered burns.
Reply: Perfect. If our own engineers can't get in, neither can those slippery Forsakens.]],
          VoiceName = "voice/$Locale$/story/1002/110188/1B959D06"
        },
        [11018808] = {
          ContentKR = "2. 동력실: 요새의 동력 공급이 지나치게 단일화되어 있어, 적이 동력실을 점령하면 방어 시설이 전부 무력화됩니다. 예비 동력실을 새로 건설하거나 중앙 관제실처럼 구역별로 독립적인 전력 공급 방안을 고려해야 합니다.\n답변: 아주 좋은 생각이네요. 그런데, 돈은 누가 댑니까?",
          DialogueId = 11018808,
          GUID = "1B959D30",
          NextDialogue = 11018809,
          Subtitle = "2. Engine Room: The fortress currently depends on a single power source. If the enemy takes the engine room, all defensive systems will go offline.\nRecommendation: Establish a backup engine room or redesign the grid so each area — like the central control room — has its own independent power supply.\nReply: Brilliant. Who's footing the bill, then?",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959D30"
        },
        [11018809] = {
          ContentKR = "(요새가 점령되기 전의 문서들이군... 그들도 이 약점을 알고 있었던 거야. 다행히 미처 수리하지 못한 덕분에, 우리가 덕을 보게 됐지만.)",
          DialogueId = 11018809,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959D5A",
          NextDialogue = 11018810,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Looks like these were written before the fortress fell... So they knew about the weak spots. Lucky for us none of it ever got fixed.)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959D5A"
        },
        [11018810] = {
          ContentKR = "(더 이상 특별한 건 없군. 다른 곳을 조사해 보자.)",
          DialogueId = 11018810,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959D84",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Nothing else useful here. Better keep looking.)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959D84"
        },
        [11018811] = {
          ContentKR = "첫 번째 문서 확인하기",
          DialogueId = 11018811,
          GUID = "1B959DAE",
          NextDialogue = 11018812,
          Subtitle = "View the First Document"
        },
        [11018812] = {
          ContentKR = "(포세이큰 동맹이 철수 직전에 론샤 요새에 함정을 배치한 계획서, 서명한 엔지니어는 카지아 어언이다.)",
          DialogueId = 11018812,
          GUID = "1B959DD8",
          NextDialogue = 11018813,
          Subtitle = "(A tactical deployment plan detailing how The Forsakens laid traps throughout Lonza Fortress in the days leading up to their retreat. Signed by engineer Katya Orn.)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959DD8"
        },
        [11018813] = {
          ContentKR = "(역시 그녀였군.)",
          DialogueId = 11018813,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959E02",
          NextDialogue = 11018821,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(So it was her.)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E02"
        },
        [11018814] = {
          ContentKR = "두 번째 문서 확인하기",
          DialogueId = 11018814,
          GUID = "1B959E2C",
          NextDialogue = 11018815,
          Subtitle = "View the Second Document"
        },
        [11018815] = {
          ContentKR = "론샤 요새는 마노 계곡 고지에 자리 잡고 있으며, 한때 황성과 스칼렛을 잇는 수로 교통의 핵심 요충지였다. 제국의 기틀이 아직 불안정하던 시절, 초대 황제 갈레아는 이곳에서 적 연합군을 매복 공격하여 승리했고, 제국 통일의 초석을 다졌다.",
          DialogueId = 11018815,
          GUID = "1B959E56",
          NextDialogue = 11018816,
          Subtitle = "Lonza Fortress overlooks the Agate Valley from high ground. Once a key stronghold guarding the river routes between the Imperial Capital and Scarletriver, it played a pivotal role in the early days of the Empire. It was here that Emperor Galea, the first emperor of Hyperborea, orchestrated a decisive ambush, defeating a coalition of enemies and cementing the Empire's unification.",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E56"
        },
        [11018816] = {
          ContentKR = "그러나 디스마니아와 스칼렛을 잇는 철도가 개통되면서, 철도에서 멀리 떨어진 론샤 요새의 전략적 가치는 낮아졌고, 중요한 교통 요충지에서 단순한 군사 요새로 전락하고 말았다.",
          DialogueId = 11018816,
          GUID = "1B959E80",
          NextDialogue = 11018817,
          Subtitle = "However, after the railway connecting Dismania and Scarletriver was completed, Lonza Fortress — now cut off from the main line — lost its strategic relevance and was relegated to a purely military outpost.",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959E80"
        },
        [11018817] = {
          ContentKR = "(굳이 신경 쓸 필요는 없겠군.)",
          DialogueId = 11018817,
          ExStoryInfo = "EXPlayer",
          GUID = "1B959EAA",
          NextDialogue = 11018821,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Nothing here that's worth my time.)",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959EAA"
        },
        [11018818] = {
          ContentKR = "녹음 재생하기",
          DialogueId = 11018818,
          GUID = "1B959ED4",
          NextDialogue = 11013001,
          Subtitle = "Play Recording"
        },
        [11018819] = {
          Camera = "-728.527649,841.050781,855.071045,-0.001556,-33.192566,-39.009785,20.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "역시 우리 아바르야... 정말로 살아서 여기까지 왔군.",
          DialogueId = 11018819,
          FinalCamera = "-767.580811,792.833984,855.06958,-0.001558,-33.192551,-39.009628,20.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B959EFE",
          LookAt = {
            [1] = "110010:n(110011)",
            [2] = "110011:n(110010)",
            [3] = "110012:n(110010)"
          },
          NextDialogue = 11013601,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201013,
            [3] = 201014,
            [4] = 408007,
            [5] = 101004
          },
          SpeakNpcId = 110011,
          Subtitle = "Very impressive, Avar... didn't think you'd make it this far.",
          TalkActionId = {
            [1] = "110011:Talk03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959EFE"
        },
        [11018820] = {
          ContentKR = "<W>경고: 20분 후 자폭 모드가 활성화됩니다. 즉시 대피하십시오. 즉시 대피하십시오.</>",
          DialogueId = 11018820,
          GUID = "1B959F28",
          IsBlack = 1,
          NextDialogue = 11019306,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Warning: Self-destruct sequence initiated. Estimated time to detonation: 20 minutes. Evacuate immediately. Repeat: Evacuate immediately.",
          VoiceName = "voice/$Locale$/story/1002/110188/1B959F28"
        },
        [11018821] = {
          ContentKR = "......",
          DialogueId = 11018821,
          GUID = "1B959F29",
          NextOptions = {
            [1] = 11018811,
            [2] = 11018814,
            [3] = 11018818
          },
          Subtitle = "..."
        },
        [11018902] = {
          ContentKR = "다른 사람들은... 무사한 거야...?",
          DialogueId = 11018902,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95AC9C",
          SpeakNpcId = 110022,
          Subtitle = "How are the others holding up...?",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AC9C"
        },
        [11018903] = {
          ContentKR = "저건... 아바르... 교관님...!",
          DialogueId = 11018903,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95ACC6",
          SpeakNpcId = 110022,
          Subtitle = "That's... Sir Avar!",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95ACC6"
        },
        [11018904] = {
          Camera = "223.848587,-12.462891,99.281006,0.000007,13.799665,-121.595177,40.278976,100000.0,false,DoNotOverride,2.8",
          ContentKR = "가시죠. 먼저 마르코 일행의 상황을 확인하고, 다 같이 안전한 곳으로 숨읍시다.",
          DialogueId = 11018904,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Unhappy02"
          },
          GUID = "1B95ACF0",
          NextDialogue = 11014211,
          Scripts = "PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Sigh_End\"},Duration{1}}",
          SpeakNpcId = 110022,
          Subtitle = "Come on. We should check on Marco and the others — find somewhere safe to regroup.",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95ACF0"
        },
        [11018905] = {
          Camera = "153.141327,144.036758,158.609253,-1.999969,-27.598812,-143.18782,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "레온, 마르코, 그리고... 모니카...",
          DialogueId = 11018905,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "153.141327,144.036758,158.609253,-1.999968,-21.998583,-142.587128,25.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95AD1A",
          NextDialogue = 11018906,
          SpeakNpcId = 110022,
          Subtitle = "Leon, Marco, and... Monica...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AD1A"
        },
        [11018906] = {
          Camera = "-20.442005,40.117725,126.334839,0.000017,-0.000307,6.615975,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...모두 단 한 발의 총알로 쓰러졌어요. 저항한 흔적조차 없습니다.",
          DialogueId = 11018906,
          Duration = 3,
          FacialId = {
            [1] = "110005:Unacceptable01"
          },
          GUID = "1B95AD44",
          NextDialogue = 11018907,
          SpeakNpcId = 110005,
          Subtitle = "...All taken down by a single shot. No signs of a struggle. Not even a chance to fight back.",
          TalkActionId = {
            [1] = "110005:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AD44"
        },
        [11018907] = {
          Camera = "-20.442005,40.117725,126.334839,0.000017,-0.000307,6.615975,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "믿었던 사람한테 살해당한 겁니다... 핏자국을 보면, 우리가 중앙 관제실에 갇혔을 때쯤이고요... 풀비스, 이 쓰레기 같은 놈...",
          DialogueId = 11018907,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-27.532495,36.781734,125.492981,0.000016,5.199693,15.214883,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95AD6E",
          NextDialogue = 11018908,
          SpeakNpcId = 110022,
          Subtitle = "They were killed by someone they trusted... From the blood, it must've happened while we were trapped in the central control room... Damn you, Fulvis...!",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AD6E"
        },
        [11018908] = {
          Camera = "42.116222,90.153992,115.693787,0.000007,16.799519,3.010553,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 11018908,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Angry01"
          },
          GUID = "1B95AD98",
          NextDialogue = 11018909,
          SpeakNpcId = 110022,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AD98"
        },
        [11018909] = {
          Camera = "-20.834232,797.99054,571.317139,0.000029,-33.599148,-82.178711,22.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "가시죠, 다프네. 우리는 반드시 살아서 나가야 합니다.",
          DialogueId = 11018909,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "14.237665,802.805603,571.317139,0.000027,-33.599148,-82.178497,22.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95ADC2",
          NextDialogue = 11014301,
          SpeakNpcId = 110022,
          Subtitle = "Let's go, Daphne. We must get out of here alive.",
          TalkActionId = {
            [1] = "110005:Explain02_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "110022:n(110005)"
          },
          VoiceName = "voice/$Locale$/story/1002/110189/1B95ADC2"
        },
        [11018910] = {
          ContentKR = "암호키가 이놈한테는 없네요. 계속 찾아봅시다.",
          DialogueId = 11018910,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95ADEC",
          SpeakNpcId = 110022,
          Subtitle = "Nothing on him. Keep going.",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95ADEC"
        },
        [11018911] = {
          ContentKR = "여기도 아니에요...",
          DialogueId = 11018911,
          GUID = "1B95AE16",
          SpeakNpcId = 110005,
          Subtitle = "Still no luck...",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AE16"
        },
        [11018912] = {
          ContentKR = "암호키를 찾았어요, 여기 있어요!",
          DialogueId = 11018912,
          Duration = 3,
          GUID = "1B95AE40",
          SpeakNpcId = 110005,
          Subtitle = "Got it! The key!",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AE40"
        },
        [11018913] = {
          ContentKR = "갑시다!",
          DialogueId = 11018913,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95AE6A",
          SpeakNpcId = 110022,
          Subtitle = "Let's move!",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AE6A"
        },
        [11018914] = {
          ContentKR = "물이 계속 차오르고 있어요. 완전히 잠기기 전에 서둘러 나가야 해요!",
          DialogueId = 11018914,
          GUID = "1B95AE94",
          SpeakNpcId = 110005,
          Subtitle = "The water's rising fast — we need to get out before this place floods!",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AE94"
        },
        [11018915] = {
          ContentKR = "여기 사용 설명이 새겨져 있어요. \"저수지 외곽의 보조 밸브 세 개를 동시에 열면 물이 더 빠르게 빠질 수 있습니다...\"",
          DialogueId = 11018915,
          GUID = "1B95AEBE",
          NextDialogue = 11014803,
          SpeakNpcId = 110005,
          Subtitle = "It says here: \"Activate all three valves around the reservoir to accelerate water discharge.\"",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AEBE"
        },
        [11018916] = {
          ContentKR = "좋아요, 이제 나갈 수 있겠어요...",
          DialogueId = 11018916,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95AEE8",
          SpeakNpcId = 110022,
          Subtitle = "That should do it. Let's get out of here...",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AEE8"
        },
        [11018917] = {
          ContentKR = "저들이... 여길 불태우려는 건가...?",
          DialogueId = 11018917,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95AC72",
          NextDialogue = 11018902,
          SpeakNpcId = 110022,
          Subtitle = "They're going to burn this place down...?",
          VoiceName = "voice/$Locale$/story/1002/110189/1B95AC72"
        },
        [11019005] = {
          Camera = "14.98733,-14.154265,30.628906,0.000071,5.795005,178.84024,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "헬파이어 교도소장님, 저는 당신이 직접 심문하러 오기를 기다리고 있었습니다. 이 진실은 반드시 제 입으로 직접 말씀드려야 합니다.",
          DialogueId = 11019005,
          Duration = 7,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "2.373075,-13.902337,31.914062,0.000071,5.795005,178.84024,45.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95BD82",
          NextDialogue = 11015315,
          SpeakNpcId = 110022,
          Subtitle = "Warden Hellfire... I've been waiting for this moment. To speak with you face to face — because I had to tell you the truth myself.",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BD82"
        },
        [11019006] = {
          ContentKR = "생각났어... 아까 교도소장이... '심문'이라고 했지...",
          DialogueId = 11019006,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BDAC",
          NextDialogue = 11019007,
          SpeakNpcId = 110022,
          Subtitle = "Wait... the Warden said something about... interrogation...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BDAC"
        },
        [11019007] = {
          ContentKR = "심문관이 '최면 주사제'라는 말을 했었지...",
          DialogueId = 11019007,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BDD6",
          NextDialogue = 11019008,
          SpeakNpcId = 110022,
          Subtitle = "That interrogator mentioned a hypnotic agent...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BDD6"
        },
        [11019008] = {
          ContentKR = "여긴... 현실 세계가 아닌 거야. 이건 꿈인가 보군.",
          DialogueId = 11019008,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BE00",
          SpeakNpcId = 110022,
          Subtitle = "I'm probably not in a real world. This is a dream..",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BE00"
        },
        [11019009] = {
          ContentKR = "('교관님'과 '다프네'가 사라졌어...)",
          DialogueId = 11019009,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BE2A",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(\"Sir Avar\" and \"Daphne\"... They're gone...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BE2A"
        },
        [11019010] = {
          ContentKR = "(포세이큰 동맹...?)",
          DialogueId = 11019010,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BE54",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(The Forsakens...?)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BE54"
        },
        [11019011] = {
          ContentKR = "선발대가 전멸했어.",
          DialogueId = 11019011,
          GUID = "1B95BE7E",
          Subtitle = "The vanguard squad's wiped out.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BE7E"
        },
        [11019012] = {
          ContentKR = "잘했어, 친구.",
          DialogueId = 11019012,
          GUID = "1B95BEA8",
          Subtitle = "Nice work, friend.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BEA8"
        },
        [11019013] = {
          ContentKR = "이게 바로 군단 개들이 받을 만한 최후지.",
          DialogueId = 11019013,
          GUID = "1B95BED2",
          Subtitle = "Serves them right.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BED2"
        },
        [11019014] = {
          ContentKR = "우리의 협력을 위해 건배!",
          DialogueId = 11019014,
          GUID = "1B95BEFC",
          Subtitle = "Here's to a fruitful partnership!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BEFC"
        },
        [11019015] = {
          ContentKR = "함께 축하하자, 사랑하는 이여~",
          DialogueId = 11019015,
          GUID = "1B95BF26",
          Subtitle = "Cheers, darling~",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BF26"
        },
        [11019016] = {
          ContentKR = "내 꿈에서 당장 꺼져.",
          DialogueId = 11019016,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BF50",
          SpeakNpcId = 110022,
          Subtitle = "...Get the hell out of my dream.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BF50"
        },
        [11019017] = {
          Camera = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
          ContentKR = "첫 번째 질문이다. 너는 제국의 병사로서 제국을 배신하고 포세이큰 동맹에 정보를 누설한 게 맞나?",
          DialogueId = 11019017,
          Duration = 3,
          GUID = "1B95BF7A",
          NextDialogue = 11019018,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "First question: As an Imperial soldier, have you conspired with The Forsakens and betrayed your Empire?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BF7A"
        },
        [11019018] = {
          ContentKR = "만약 네가 제국의 정의를 배신했다면, 필토이드의 발톱에 갈기갈기 찢길 것이다!",
          DialogueId = 11019018,
          Duration = 3,
          GUID = "1B95BFA4",
          NextDialogue = 11019019,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Should you betray the justice of the Empire, these Filthoids shall tear you apart with their claws!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BFA4"
        },
        [11019019] = {
          ContentKR = "(...이 질문은 쉽게 대답할 수 있지.)",
          DialogueId = 11019019,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BFCE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...This one's easy.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BFCE"
        },
        [11019020] = {
          ContentKR = "(으윽...! 몸이 갑자기 너무 무거워졌어... 그 혐의를 인정하지 말아야 했는데.)",
          DialogueId = 11019020,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95BFF8",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Ngh—! My body... it's getting heavy... I shouldn't have admitted to those charges...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95BFF8"
        },
        [11019021] = {
          ContentKR = "(어째서 여기도 필토이드가...!)",
          DialogueId = 11019021,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C022",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Why are there Filthoids here...!?)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C022"
        },
        [11019022] = {
          ContentKR = "(아니... 진정하자. 저것들은 그저 환영일 뿐이야.)",
          DialogueId = 11019022,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C04C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(No — stay calm. They're just illusions.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C04C"
        },
        [11019023] = {
          ContentKR = "(맞아. 절대로 그 혐의를 인정하면 안 돼.)",
          DialogueId = 11019023,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C076",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(That's right. I won't confess to a lie.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C076"
        },
        [11019024] = {
          ContentKR = "(필토이드...)",
          DialogueId = 11019024,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C0A0",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Filthoids...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C0A0"
        },
        [11019025] = {
          ContentKR = "(아니, 저것들은 그저 환영일 뿐이야.)",
          DialogueId = 11019025,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C0CA",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(No — illusions. They're not real.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C0CA"
        },
        [11019026] = {
          Camera = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
          ContentKR = "두 번째 질문이다. 론샤 요새 전투에서 선발대가 전멸한 것이 너와 관련되어 있나?",
          DialogueId = 11019026,
          GUID = "1B95C0F4",
          NextDialogue = 11019027,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Second question: The vanguard squads were annihilated at Lonza Fortress. Were you the architect of their doom?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C0F4"
        },
        [11019027] = {
          Camera = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
          ContentKR = "만약 네가 동포의 정의를 저버렸다면, 너의 칼날이 네 피로 물들게 될 것이다!",
          DialogueId = 11019027,
          GUID = "1B95C11E",
          NextDialogue = 11019028,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "Should you betray the justice of your comrades, your own blade shall spill your blood!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C11E"
        },
        [11019028] = {
          Camera = "13.287109,114.423828,114.03125,-0.000825,14.198904,-86.82589,17.134987,100000.0,false,Manual,22.0",
          ContentKR = "(망설일 필요 없어. 확고하게 선택하자.)",
          DialogueId = 11019028,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C148",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(No hesitation. Make the choice — and stick to it.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C148"
        },
        [11019029] = {
          ContentKR = "(으윽...! 몸이 갑자기 너무 무거워졌어... 그 혐의를 인정하지 말아야 했는데.)",
          DialogueId = 11019029,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C172",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Ngh—! My body... it's getting heavy... I shouldn't have admitted to those charges...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C172"
        },
        [11019030] = {
          ContentKR = "(너는... 누구지?!)",
          DialogueId = 11019030,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C19C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...Who are you!?)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C19C"
        },
        [11019031] = {
          ContentKR = "(아니... {性别: 그는|그녀는} 내가 아니야.)",
          DialogueId = 11019031,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C1C6",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(No — this isn't me.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C1C6"
        },
        [11019032] = {
          ContentKR = "(맞아, 여기서 나가야 해. 진실을...)",
          DialogueId = 11019032,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C1F0",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Yes... I have to keep going. The truth must come to light...)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C1F0"
        },
        [11019033] = {
          ContentKR = "(너는 내가 아니야. 넌 그저 어리석은 모조품일 뿐이지.)",
          DialogueId = 11019033,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C21A",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(You're not me. You're just a cheap imitation.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C21A"
        },
        [11019034] = {
          ContentKR = "사라져라.",
          DialogueId = 11019034,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C244",
          SpeakNpcId = 110022,
          Subtitle = "Get lost.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C244"
        },
        [11019035] = {
          ContentKR = "(앞이 막힌 것 같은데... 돌아갈까?)",
          DialogueId = 11019035,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C26E",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(The path ahead's blocked... Should I turn back?)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C26E"
        },
        [11019036] = {
          ContentKR = "무죄를 주장하는 자여, 분노로 인해 흔들릴 것인가?",
          DialogueId = 11019036,
          GUID = "1B95C298",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "You who claim innocence — will your resolve falter in anger?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C298"
        },
        [11019037] = {
          ContentKR = "뒷정리는 잘 되었나?",
          DialogueId = 11019037,
          GUID = "1B95C2C2",
          NextDialogue = 11019038,
          SpeakNpcId = 110011,
          Subtitle = "How's the cleanup?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C2C2"
        },
        [11019038] = {
          ContentKR = "보시다시피, 깔끔하게 처리했습니다.",
          DialogueId = 11019038,
          GUID = "1B95C2EC",
          SpeakNpcId = 110012,
          Subtitle = "Flawless. As you can see.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C2EC"
        },
        [11019039] = {
          ContentKR = "(저 둘이었어...!)",
          DialogueId = 11019039,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C316",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(It's them... Fulvis and Falsi!)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C316"
        },
        [11019040] = {
          ContentKR = "무죄를 주장하는 자여, 슬픔으로 인해 흔들릴 것인가?",
          DialogueId = 11019040,
          GUID = "1B95C340",
          SpeakNpcId = 110032,
          Subtitle = "You who claim innocence — will your resolve waver in sorrow?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C340"
        },
        [11019041] = {
          ContentKR = "{nickname2}, 나의 학생...",
          DialogueId = 11019041,
          GUID = "1B95C36A",
          NextDialogue = 11019042,
          SpeakNpcId = 110010,
          Subtitle = "... my cadet...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C36A"
        },
        [11019042] = {
          ContentKR = "아바르 교관님?!",
          DialogueId = 11019042,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C394",
          SpeakNpcId = 110022,
          Subtitle = "Sir Avar!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C394"
        },
        [11019043] = {
          ContentKR = "어어—! ",
          DialogueId = 11019043,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C3BE",
          SpeakNpcId = 110022,
          Subtitle = "Ugh—! ",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C3BE"
        },
        [11019044] = {
          ContentKR = "(전혀 모르는 얼굴이다.)",
          DialogueId = 11019044,
          GUID = "1B95C3E8",
          Subtitle = "(This isn't Sir Avar. It's a complete stranger.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C3E8"
        },
        [11019045] = {
          ContentKR = "무죄를 주장하는 자여, 혼란으로 인해 흔들릴 것인가?",
          DialogueId = 11019045,
          GUID = "1B95C412",
          NextDialogue = 11019046,
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "You who claim innocence — will your resolve crumble under the weight of doubt?",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C412"
        },
        [11019046] = {
          ContentKR = "나리, 제가 길을 안내해 드리겠습니다...",
          DialogueId = 11019046,
          GUID = "1B95C43C",
          NextDialogue = 11019047,
          SpeakNpcId = 110009,
          Subtitle = "Allow me to show you the way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C43C"
        },
        [11019047] = {
          ContentKR = "그 길은... 지옥으로 가는 길입니다...",
          DialogueId = 11019047,
          GUID = "1B95C466",
          SpeakNpcId = 110009,
          Subtitle = "Yes... The way to hell.",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C466"
        },
        [11019048] = {
          ContentKR = "교도소장님, 이제 그만하세요...! 제발 멈춰주세요!",
          DialogueId = 11019048,
          GUID = "1B95C490",
          NextDialogue = 11019049,
          SpeakNpcId = 110005,
          Subtitle = "That's enough, ma'am! Please... stop!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C490"
        },
        [11019049] = {
          ContentKR = "{nickname2}, 저와 함께 가요. 제가 여기서 나가게 해드릴게요!",
          DialogueId = 11019049,
          GUID = "1B95C4BA",
          SpeakNpcId = 110005,
          Subtitle = "Come with me, . I'll lead you out!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C4BA"
        },
        [11019050] = {
          ContentKR = "앞에 무엇이 기다리고 있든... 꼭 기억해 주세요...",
          DialogueId = 11019050,
          GUID = "1B95C4E4",
          SpeakNpcId = 110005,
          Subtitle = "Whatever lies ahead... please remember...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C4E4"
        },
        [11019051] = {
          ContentKR = "저는 당신과 함께 살아갈 거예요!",
          DialogueId = 11019051,
          GUID = "1B95C50E",
          SpeakNpcId = 110005,
          Subtitle = "We will survive this — together!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C50E"
        },
        [11019052] = {
          ContentKR = "(이것이 그녀가 내 의지를 시험하는 마지막 시련이구나.)",
          DialogueId = 11019052,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C538",
          NextDialogue = 11019053,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(This is it — the final trial.)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C538"
        },
        [11019053] = {
          ContentKR = "(이 심판의 꿈을 견뎌내야 해... 반드시 진실을 그녀에게 직접 전해야 해!)",
          DialogueId = 11019053,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95C562",
          NextDialogue = 11019054,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(I have to survive this... I have to speak the truth to her face!)",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C562"
        },
        [11019054] = {
          ContentKR = "무죄를 주장하는 자여, 네가 여전히 흔들리지 않았다면, 가슴속 의지를 단련하여 칼날로 만들어라...",
          DialogueId = 11019054,
          DisableMouth = 1,
          GUID = "1B95C58C",
          NextDialogue = 11019055,
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "You who claim innocence — if your resolve still holds true, then forge that will into a blade...",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C58C"
        },
        [11019055] = {
          ContentKR = "네 손에 든 검으로 나에게 답하라!",
          DialogueId = 11019055,
          DisableMouth = 1,
          GUID = "1B95C5B6",
          SnapShot = "MONSTER",
          SpeakNpcId = 110032,
          SpeakNpcName = "UI_Npc_Wardenry",
          Subtitle = "...and answer me with your sword!",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C5B6"
        },
        [11019056] = {
          ContentKR = "네",
          DialogueId = 11019056,
          GUID = "1B95C5E0",
          Subtitle = "Yes",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C5E0"
        },
        [11019057] = {
          ContentKR = "아니요",
          DialogueId = 11019057,
          GUID = "1B95C60A",
          Subtitle = "No",
          VoiceName = "voice/$Locale$/story/1002/110190/1B95C60A"
        },
        [11019101] = {
          ContentKR = "절대 병사들의 억울한 울부짖음이 론샤 요새의 하늘 위를 영원히 맴돌게 해서는 안 된다.",
          DialogueId = 11019101,
          GUID = "1B95CD42",
          SpeakNpcId = 110005,
          Subtitle = "We can't let the cries of the wronged echo over Lonza Fortress forever.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD42"
        },
        [11019102] = {
          Camera = "582.071289,-479.369141,593.910156,-0.000856,-38.992104,162.400696,15.284281,100000.0,false,Manual,22.0",
          ContentKR = "그래서 우리는 이런 방식으로 당신을 만나기로 했습니다.",
          DialogueId = 11019102,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "476.848633,-672.017578,593.910156,-0.000855,-39.992191,138.000839,15.284281,100000.0,false,Manual,22.0",
          GUID = "1B95CD6C",
          NextDialogue = 11019103,
          SpeakNpcId = 110022,
          Subtitle = "That's why... we came to you like this.",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD6C"
        },
        [11019103] = {
          ContentKR = "풀비스가 아바르를 함정에 빠뜨린 진정한 목적은 제국 고위층에 있는 카론을 제거하려는 것입니다. 그의 계획이 성공하면 제국뿐 아니라 <H>당신</>에게도 어떤 결과가 닥칠지 아실 겁니다.",
          DialogueId = 11019103,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CD96",
          NextDialogue = 11016706,
          SpeakNpcId = 110022,
          Subtitle = "Framing Avar was never the real goal. What Fulvis truly wants is to purge every Charon-born from the Empire's upper echelons. If he succeeds, you know what that would mean — for the Empire... and for you.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CD96"
        },
        [11019104] = {
          ContentKR = "운이 좋다면 결정적인 증거를 확보할 수 있을 겁니다. 설령 증거가 사라지더라도 그녀의 증언은 매우 중요합니다. 당신이 보는 앞에서 그녀와 직접 만나 증명할 기회를 주십시오.",
          DialogueId = 11019104,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CDC0",
          NextDialogue = 11016707,
          SpeakNpcId = 110022,
          Subtitle = "If we're lucky, you'll recover concrete proof. If not, even her testimony will carry weight. Let me face her — right before you. Let the truth speak for itself.",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CDC0"
        },
        [11019105] = {
          ContentKR = "응. 네가 충분히 쉬고 나면 다시 천천히 설명해 줄게.",
          DialogueId = 11019105,
          GUID = "1B95CDEA",
          NextDialogue = 11019106,
          SpeakNpcId = 110018,
          Subtitle = "I'll explain later — after you've had some proper rest.",
          TalkActionId = {
            [1] = "110018:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CDEA"
        },
        [11019106] = {
          Camera = "-201.890625,-407.858398,414.960938,0.000216,-22.600248,41.391022,18.0,254.013382,false,DoNotOverride,7.801928",
          ContentKR = "이 감옥의 피비린내가 싫어. 준비가 됐으면 떠나자.",
          DialogueId = 11019106,
          FinalCamera = "-251.734375,-451.791016,442.613281,0.000208,-22.000229,41.39093,18.0,254.013382,false,DoNotOverride,7.801928",
          GUID = "1B95CE14",
          SpeakNpcId = 110018,
          Subtitle = "The stench of blood here is proving itself noisome. Let's leave this dismal place once you're ready.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CE14"
        },
        [11019107] = {
          ContentKR = "5일 후",
          DialogueId = 11019107,
          GUID = "1B95CE3E",
          NextDialogue = 11019108,
          Subtitle = "Five days later",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CE3E"
        },
        [11019108] = {
          ContentKR = "황성 디즈마니아, 황실 대극장",
          DialogueId = 11019108,
          GUID = "1B95CE68",
          Subtitle = "Royal Grand Theatre, Dismania",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CE68"
        },
        [11019109] = {
          Camera = "41.970703,146.506836,246.835938,0.000077,-0.000096,-100.601891,31.194523,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "방금 공연한 〈설국의 아이〉는 작곡가 카바라도시의 작품이야. 그의 고향 아이스레이크 시티에 전해오는 요정에 관한 전설을 각색한 이야기지... {nickname2}, 듣고 있어?",
          DialogueId = 11019109,
          Duration = 1,
          FacialId = {
            [1] = "110022:Think01"
          },
          FinalCamera = "29.609375,169.513672,167.746094,0.000082,-1.799652,-105.405334,31.194523,205.992798,false,Manual,22.0",
          GUID = "1B95CE92",
          LookAt = {
            [1] = "110018:n(110018)",
            [2] = "110022:p(BP_EX01_FixSimple_29_nanzhu)"
          },
          NextDialogue = 11019110,
          Scripts = [[
SEQ{
LookAt{_delay{8.5},LookAtDescription{"110018:p(BP_EX01_FixSimple_29_weiji)"}},
SEQ{
CameraMoveTo{_delay{0.5},TargetPosition{"-44.542969,-185.030273,185.652344,0.000056,-10.200437,87.394356,31.194523,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-44.542969,-185.030273,185.652344,0.000056,-9.600492,81.393951,31.194523,100000.0,false,DoNotOverride,22.0"},duration{8}}
}
}
]],
          SpeakNpcId = 110018,
          Subtitle = "That last piece, Children From the Snowfield, was composed by Cavaradossi. It was inspired by a folktale in his hometown, Icelake — one about a mystical creature that roams the snowy wilderness... You're not really listening, are you, ?",
          TalkActionId = {
            [1] = "110018:Talk03_Start",
            [2] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CE92"
        },
        [11019110] = {
          Camera = "98.070312,162.706055,155.070312,0.00008,-5.000156,83.993164,40.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "아? 네, 듣고 있습니다. 요정이 있다고 하셨나요? 아이스레이크 시티에?",
          DialogueId = 11019110,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CEBC",
          LookAt = {
            [1] = "110022:n(110018)"
          },
          NextDialogue = 11019111,
          SpeakNpcId = 110022,
          Subtitle = "Huh? Yeah... something about a mystical creature? In Icelake?",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CEBC"
        },
        [11019111] = {
          Camera = "265.580078,432.883789,136.324219,0.000048,-0.600217,-131.199738,31.194523,532.562439,false,Manual,4.15071",
          ContentKR = "...그래, 여전히 걱정이 많아 보이는구나. 여기 오면 조금이라도 기분이 풀릴 줄 알았는데.",
          DialogueId = 11019111,
          FinalCamera = "272.865234,426.507812,136.324219,0.000048,-0.600217,-131.199738,31.194523,532.562439,false,Manual,4.15071",
          GUID = "1B95CEE6",
          LookAt = {
            [1] = "110018:n(110018)"
          },
          NextDialogue = 11019112,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4.01},TargetPosition{"-63.695312,-164.354492,174.359375,0.000116,-5.400268,75.38089,45.0,135.993378,false,Manual,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-56.982422,-166.160156,174.359375,0.000117,-5.600284,76.579796,45.0,479.429016,false,Manual,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Thought so. Still carrying the weight, I see. I'd hoped this might offer a brief escape.",
          TalkActionId = {
            [1] = "110018:DisagreeHead"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CEE6"
        },
        [11019112] = {
          ContentKR = "지난번 말씀하신 '경호'라는 게 무슨 이야기인가요? 앞으로의 계획을 알고 싶습니다. 저... 꼭 해야 할 일이 있어서요.",
          DialogueId = 11019112,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CF10",
          NextDialogue = 11019113,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"212.978516,356.34375,65.824219,0.000064,10.1995,-132.999237,31.194523,532.562439,false,Manual,4.15071"},duration{0}},
CameraMoveTo{TargetPosition{"212.978516,356.34375,65.824219,0.000064,10.1995,-132.999237,31.194523,105.220139,false,Manual,22.0"},duration{2}}
},
PlayAnimation{_delay{4.5},ActorId{110022},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{6.5},ActorId{110022},AnimationId{"Fist02_Start"},Duration{1}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "About that \"bodyguard\" role you mentioned... I need to know what it actually entails. There's something I have to deal with — I need to know if this gets in the way.",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110018:Talk03_End"
          },
          TurnTo = {
            [1] = "110018:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CF10"
        },
        [11019113] = {
          Camera = "150.314453,114.749023,93.257812,0.000076,12.398924,-146.393463,31.194523,265.276245,false,Manual,2.500234",
          ContentKR = "오늘 바로 그 얘기를 하려고 했어. 조만간 플래그슨 주의 스칼렛에 반년 정도 다녀올 예정인데, 그동안 네가 내 경호를 맡아줘야겠어.",
          DialogueId = 11019113,
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "157.380859,103.807617,93.257812,0.000082,12.39891,-147.592407,31.194523,265.276245,false,Manual,2.500234",
          GUID = "1B95CF3A",
          NextDialogue = 11017113,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"98.070312,162.706055,155.070312,0.00008,-5.000156,83.993126,40.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"89.480469,163.738281,155.070312,0.000084,-4.600125,78.992691,40.0,100000.0,false,DoNotOverride,22.0"},duration{10}}
},
PlayAnimation{_delay{9.01},ActorId{110018},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "That's what I wanted to talk to you about. So, I've been assigned to Scarletriver on royal orders — a six-month posting, give or take. It would ease my mind to have you accompany me.",
          TalkActionId = {
            [1] = "110022:Fist02_End",
            [2] = "110018:Confident_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CF3A"
        },
        [11019115] = {
          Camera = "27.921875,-356.951172,536.433594,0.000073,-35.199646,124.770035,45.0,100000.0,false,Manual,22.0",
          ContentKR = "5일 전에 폐하께서 나를 불러 황실의 이름으로 스칼렛을 방문하라고 하셨어. 그래서 너를 내 경호원으로 데려가고 싶다고 말씀드렸고, 폐하께서 허락하셨어.",
          DialogueId = 11019115,
          FinalCamera = "-9.732422,-383.087891,536.433594,0.000073,-35.199646,124.770035,45.0,100000.0,false,Manual,22.0",
          GUID = "1B95CF8E",
          NextDialogue = 11019116,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"143.337891,24.485352,118.726562,0.000105,12.600271,-165.22699,45.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"144.664062,19.453125,118.726562,0.000105,12.600271,-165.227493,45.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "I submitted your name as my aide when I met with my brother five days ago. He approved.",
          TalkActionId = {
            [1] = "110018:Talk03_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CF8E"
        },
        [11019116] = {
          Camera = "154.613281,113.302734,105.09375,0.000112,9.199677,106.796791,31.194523,100000.0,false,DoNotOverride,22.0",
          ContentKR = "제가 황성을 떠나 스칼렛으로 가야 한다는 말씀이신가요?",
          DialogueId = 11019116,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CFB8",
          NextDialogue = 11017116,
          SpeakNpcId = 110022,
          Subtitle = "So you're asking me to leave Dismania... and head for Scarletriver, Flagson?",
          TalkActionId = {
            [1] = "110022:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CFB8"
        },
        [11019119] = {
          Camera = "207.460938,360.240234,139.1875,0.000101,-0.600462,-130.806396,31.194527,446.287842,false,Manual,11.834087",
          ContentKR = "알겠습니다. 말씀대로 하죠. 마침 제가 찾는 것도 그쪽에 있습니다. 베르길리우스 전하께 충성 맹세라도 해야 합니까?",
          DialogueId = 11019119,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D036",
          NextDialogue = 11017119,
          Scripts = [[
PARA{
PlayAnimation{_delay{8},ActorId{110022},AnimationId{"Explain02_Start"},Duration{3}},
CameraMoveTo{_delay{7.5},TargetPosition{"149.958984,156.460938,171.972656,0.000133,-12.599397,104.987122,35.000008,506.425873,false,DoNotOverride,22.0"},duration{0}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Understood. Then I'll go. What I'm looking for lies in the same direction anyway. Shall I swear an oath of service, Your Highness?",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D036"
        },
        [11019121] = {
          ContentKR = "간단히 준비해. 우리는 3일 후에 출발할 거야.",
          DialogueId = 11019121,
          GUID = "1B95D08A",
          LookAt = {
            [1] = "110018:n(110018)"
          },
          NextDialogue = 11019122,
          Scripts = "MoveTo{ActorId{110022},TargetPoint{\"BP_EX01_FixSimple_29_nanzhu02\"},MoveSpeed{75},Visibility{\"Show\"}}",
          SpeakNpcId = 110018,
          Subtitle = "Pack your things. We'll leave in three days.",
          TurnTo = {
            [1] = "110018:p(-170)"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D08A"
        },
        [11019122] = {
          ContentKR = "예, 알겠습니다.",
          DialogueId = 11019122,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D0B4",
          SpeakNpcId = 110022,
          Subtitle = "Sure.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D0B4"
        },
        [11019123] = {
          ContentKR = "(플래그슨 주...)",
          DialogueId = 11019123,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D0DE",
          NextDialogue = 11019124,
          SpeakNpcId = 110022,
          Subtitle = "(Flagson...)",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D0DE"
        },
        [11019124] = {
          ContentKR = "(거기에는 교도소장에게조차 말하지 않았던... <H>그것</>이 있어...)",
          DialogueId = 11019124,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488BE",
          NextDialogue = 11019125,
          SpeakNpcId = 110022,
          Subtitle = "(There is something there... that I didn't even tell the Warden...)",
          VoiceName = "voice/$Locale$/story/1002/110171/1B9488BE"
        },
        [11019125] = {
          ContentKR = "(<H>'두 번째 새싹' 계획의 또 다른 핵심...</> 제로의 <H>촉매제</>.)",
          DialogueId = 11019125,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D132",
          SpeakNpcId = 110022,
          Subtitle = "(The other piece of the Second Scion Program — the catalyst of No. 0...)",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D132"
        },
        [11019201] = {
          ContentKR = "이봐, 왜 이래? 왜 무릎을 꿇는 거지?",
          DialogueId = 11019201,
          GUID = "1B95DDAA",
          IsBlack = 1,
          NextDialogue = 11019202,
          SpeakNpcId = 110015,
          Subtitle = "Hey, what's wrong? Why are you squatting down?",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDAA"
        },
        [11019202] = {
          ContentKR = "불쌍한 척은 그만둬. 이런 게 나한테 먹힐 것 같아?! 어서 따라와!",
          DialogueId = 11019202,
          GUID = "1B95DDD4",
          IsBlack = 1,
          NextDialogue = 11012303,
          SpeakNpcId = 110015,
          Subtitle = "Don't you play the victim here! I won't buy it! Get up and go!",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD4"
        },
        [11019203] = {
          ContentKR = "이쪽이에요!",
          DialogueId = 11019203,
          GUID = "1B95DDD5",
          SpeakNpcId = 110034,
          Subtitle = "This way!",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD5"
        },
        [11019204] = {
          ContentKR = "......",
          DialogueId = 11019204,
          GUID = "1B95DDD6",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD6"
        },
        [11019205] = {
          ContentKR = "(운송용 승강기네. 보급품이 있을지도 모르겠지만, 매복한 적이 있는지 주의해야 해.)",
          DialogueId = 11019205,
          DisableMouth = 1,
          GUID = "1B95DDD7",
          SnapShot = "HEART",
          Subtitle = "(A cargo lift. Could be a good chance to resupply... but I'd better stay alert. Could be an ambush.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [11019206] = {
          ContentKR = "이 방은 당분간 안전해. 이제 콘솔을 조작할 수 있어.",
          DialogueId = 11019206,
          GUID = "1B95DDD8",
          Subtitle = "Room's clear for now. Time to access the control panel.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [11019207] = {
          ContentKR = "제어 권한 획득 중입니다. 잠시 기다려 주세요.",
          DialogueId = 11019207,
          GUID = "1B95DDD9",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Authorising access. Please wait...",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [11019208] = {
          ContentKR = "(중앙 관제실은 독립적으로 전력을 공급받고 있군... 여기의 회전체는 동력실 폭발의 영향을 받지 않았어.)",
          DialogueId = 11019208,
          GUID = "1B95DDDA",
          Subtitle = "(So the Central Control Room runs on a separate grid... That's why the blast didn't reach this part.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [11019209] = {
          ContentKR = "회로 오류, 콘솔이 보호 상태입니다. 보호 상태를 해제하려면 회전체를 종료시키세요.",
          DialogueId = 11019209,
          GUID = "1B95DDDB",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Power flow error detected. Control panel locked for protection. Please shut down all Phoxynamo Wheels to lift the lock.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [11019301] = {
          ContentKR = "......",
          DialogueId = 11019301,
          GUID = "1B95EE12",
          IsBlack = 1,
          NextDialogue = 11019302,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/searchcloth\"},PlayAs2D{true}}",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE12"
        },
        [11019302] = {
          ContentKR = "펄시... 직접... 관제... 폭...",
          DialogueId = 11019302,
          GUID = "1B95EE3C",
          IsBlack = 1,
          NextDialogue = 11019303,
          Scripts = [[
SEQ{
PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/signal_on"},PlayAs2D{true}},
PlayNormalSound{_delay{4},EventPath{"event:/sfx/common/story/ex01/signal_off"},PlayAs2D{true}}			
}	]],
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Falsi... blow up... control room...",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE3C"
        },
        [11019303] = {
          ContentKR = "네.",
          DialogueId = 11019303,
          GUID = "1B95EE66",
          IsBlack = 1,
          NextDialogue = 11019304,
          SpeakNpcId = 110012,
          Subtitle = "Yes, sir.",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE66"
        },
        [11019304] = {
          ContentKR = "......",
          DialogueId = 11019304,
          GUID = "1B95EE90",
