          SpeakNpcId = 220007,
          Subtitle = "But it's worth every coin! From that seat, you'll see every sparkle on Lady Violetta's gown, every subtle movement of her lips. It's absolutely a once-in-a-lifetime experience!",
          TalkActionId = {
            [1] = "220007:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "220007:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE1AA"
        },
        [12000706] = {
          Camera = "-41.440186,-178.4375,124.235352,0.000064,8.399623,-139.188477,22.448526,74.47065,false,Manual,10.0",
          ContentKR = "고맙지만 괜찮아. 우린 이미 티켓이 있어.",
