          DialogueId = 12000706,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "1E0AE1D4",
          NextDialogue = 12000710,
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but we've already got our tickets.",
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE1D4"
        },
        [12000707] = {
