        [12000708] = {
          Camera = "-192.296631,-210.211426,150.428711,0.000017,-10.000517,-1.204193,55.0,264.948456,false,Manual,10.0",
          ContentKR = "그럼... 티켓을 되팔아 보는 건 어때요? 제가 티켓을 사드릴게요. 이걸 넘기면 주머니에 실버 코인이 가득 차겠죠! 어떠세요?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000708,
          FinalCamera = "-192.321045,-211.428223,150.428711,0.000017,-10.000517,-1.204193,55.0,267.196838,false,Manual,10.0",
          GUID = "1E0AE228",
          NextDialogue = 12000709,
          SpeakNpcId = 220007,
          Subtitle = "Well then... I also buy tickets. If you're willing to sell, you could walk away with a pocketful of shiny silver coins. What do you say?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE228"
        },
        [12000709] = {
