          ContentKR = "미안하지만, 이건 누군가의 선물이라서 함부로 팔 수 없어.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000709,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "1E0AE252",
          NextDialogue = 12000710,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, these were a gift. I wouldn't feel right selling them.",
          TalkActionId = {
            [1] = "100001:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE252"
        },
        [12000710] = {
          Camera = "-89.339111,-5.74707,150.428711,0.00002,-10.800386,-53.803547,55.000008,267.196838,false,Manual,10.0",
          ContentKR = "...그런 건 미리 말하지. 괜히 시간 낭비했잖아. 재수 없게.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000710,
          GUID = "1E0AE27C",
          SpeakNpcId = 220007,
          Subtitle = "...You should've said that earlier! What a bummer.",
          TalkActionId = {
            [1] = "220007:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE27C"
        },
        [12000711] = {
          ContentKR = "소년이 화난 듯 어깨를 툭 치고 지나갔다. 일부러 세게 부딪치며 화를 드러내려는 것 같았다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000711,
          Duration = 3,
          GUID = "1E0AE2A6",
          Subtitle = "The boy stomped off. As if to prove his frustration, he deliberately shoved his shoulder into you and Snow as he passed.",
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE2A6"
        },
        [12000712] = {
