            [2] = "200002:Angry01",
            [3] = "100001:Unhappy01"
          },
          FinalCamera = "236.039062,-1352.068359,268.0,0.000141,-9.198488,34.811592,30.0,240.0,false,Manual,10.0",
          GUID = "1E0B22F6",
          LookAt = {
