},
PlayAnimation{_delay{2.5},ActorId{220010},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 220010,
          Subtitle = "Did you really think you could scribble over the dates and sneak in with expired tickets? You filthy lowlifes! I can spot cheap tricks like this a mile away!",
          TalkActionId = {
            [1] = "220010:Talk01_End",
            [2] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
