          VoiceName = "voice/$Locale$/story/1200/120011/1E0B22F6"
        },
        [12001104] = {
          ContentKR = "(명백한 증거 앞에 아무 말도 할 수 없었다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001104,
          Duration = 3,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E0B2320",
