          DialogueId = 12001106,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "1E0B2374",
          NextDialogue = 12001107,
          SpeakNpcId = 100001,
          Subtitle = "Could it be... that boy swapped our tickets when he bumped into us!?",
          TalkActionId = {
