          GUID = "1E0B4738",
          NextDialogue = 12001325,
          Subtitle = "Ladies and gentlemen, the performance is about to begin. Kindly take your seats at your earliest convenience.",
          TalkActionId = {
            [1] = "220041:Sit_Idle_Start",
            [2] = "220042:Sit_Talk03_Loop"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4738"
        },
        [12001325] = {
