          ContentKR = "작은 요정은 야수에게 날아갔지만...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001327,
          FinalCamera = "7183.162109,5440.892578,605.769531,0.000291,26.788889,-155.961044,20.0,500.0,false,Manual,10.0",
          GUID = "1E0B47B6",
          NextDialogue = 12001328,
          Subtitle = "The tiny fairy flew towards the monstrous creature...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B47B6"
        },
        [12001328] = {
          ContentKR = "야수는 가볍게 요정의 사지를 꺾어버렸어요...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001328,
          FacialId = {
            [1] = "220041:Sad03"
