          },
          NextDialogue = 12001329,
          Subtitle = "...only for its delicate limbs to snap beneath its might.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B47E0"
        },
        [12001329] = {
          Camera = "32.304688,240.658203,114.476562,0.000086,-2.603053,-135.186905,30.000002,132.470917,false,Manual,6.527582",
          ContentKR = "요정은 처음으로 자신의 마음이 뛰는 소리를 들었어요, 그건 자신의 운명을 외치는 소리였어요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001329,
          Duration = 5,
          FinalCamera = "41.55957,229.902832,114.476562,0.000085,-3.003077,-141.986862,30.000002,132.470917,false,Manual,6.527582",
          GUID = "1E0B480A",
          NextDialogue = 12001370,
          Subtitle = "The fairy's frozen heart pulsed for the first time — beating, screaming its own destiny—",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B480A"
        },
