SEQ{
CameraMoveTo{_delay{7.8},TargetPosition{"-96.761719,405.072266,41.273438,0.000106,6.599212,-80.597214,35.000008,134.024002,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-99.173828,419.692871,39.5625,0.000106,6.599212,-80.597214,35.000008,134.024002,false,Manual,10.0"},duration{6}}
},
PlayFacial{_delay{7.8},ActorId {220014}, FacialId {"Smile01"}}
}]],
          SpeakNpcId = 220014,
          Subtitle = "There are two possibilities. Either I'm hopelessly naive, trusting that this exchange will proceed peacefully... or I'm entirely certain that no matter how many men you've brought, I'll leave here unscathed.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CF6"
        },
        [12001360] = {
          ContentKR = "네 생각엔 어느 쪽일 것 같아?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001360,
          GUID = "1E0B4D20",
          LookAt = {
            [1] = "220014:n(220018)"
          },
          NextDialogue = 12001361,
          SpeakNpcId = 220014,
          Subtitle = "Now, which do you think it is?",
          TalkActionId = {
            [1] = "220014:Confident_Start"
          },
          TurnTo = {
            [1] = "220014:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4D20"
        },
        [12001361] = {
          Camera = "131.576172,289.608887,84.367188,0.000099,-6.600128,133.393799,35.0,300.0,false,DoNotOverride,10.0",
          ContentKR = "보, 보스... 이 여자 진짜 자신만만한 것 같은데요?",
          DialogueId = 12001361,
          GUID = "1E0B4D4A",
          NextDialogue = 12001362,
          SpeakNpcId = 220045,
          Subtitle = "Wh—What do we do, boss? It sounds like she's got everything under control...",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4D4A"
        },
        [12001362] = {
          ContentKR = "...이 여자가 우리한테 겁만 주고 있는 거다! 얘들아, 처리해라!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001362,
          GUID = "1E0B4D74",
          LookAt = {
            [1] = "220017:n(220014)"
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"37.453125,910.947266,426.960938,0.000127,-36.200096,-101.606094,25.0,300.0,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"42.201172,934.023438,444.207031,0.000127,-36.200096,-101.606094,20.0,300.0,false,DoNotOverride,10.0"},duration{0.3}}
}]],
          SpeakNpcId = 220018,
          Subtitle = "...She's bluffing! Let's get her!",
          TalkActionId = {
            [1] = "220018:Angry01_Start"
          },
          TurnTo = {
            [1] = "220017:n(220014)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4D74"
        },
        [12001370] = {
          Camera = "474.283203,3090.055664,-626.992188,0.000068,19.598019,33.409706,30.0,4259.26123,false,Manual,1.345738",
          Content = "……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001370,
          Duration = 10,
          FinalCamera = "533.871094,3129.377441,-599.800781,0.000063,21.397827,33.612,30.0,4259.26123,false,Manual,1.345738",
          GUID = "1E0B480B",
          NextDialogue = 12001330,
          ToFinalCameraBlendTime = 13
        },
        [12001401] = {
          ContentKR = "여기 두 어린 친구도 있으니, 다치지 않게 해야겠지.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001401,
          GUID = "1E0B53DA",
          SpeakNpcId = 220014,
          Subtitle = "There are two young ones with me. I shall ensure they remain unharmed.",
          VoiceName = "voice/$Locale$/story/1200/120014/1E0B53DA"
        },
        [12001501] = {
          Camera = "-115.833984,258.624512,75.933594,0.000124,-13.000274,139.878876,15.726627,200.0,false,Manual,10.0",
          ContentKR = "멈춰, 멈춰요! 여사님, 멈춰 주세요!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001501,
          FinalCamera = "-109.376953,253.17627,77.878906,0.000124,-13.000267,139.878876,15.726627,200.0,false,Manual,10.0",
          GUID = "1E0B6442",
          LookAt = {
            [1] = "220017:n(220014)"
