          SpeakNpcId = 220017,
          Subtitle = "Stop! Ma'am, please!",
          TalkActionId = {
            [1] = "220017:Shock_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "220045:n(220017)"
