SetLocation{ActorId{220045},TargetPoint{"TargetPointbaobiao3"},Visibility{"Show"}},
SetLocation{ActorId{220018},TargetPoint{"TargetPointheishang"},Visibility{"Show"}}
}]],
          Subtitle = "(Zhiliu retrieves a small, intricate object and lights it. Its design jogs your memory — you recall reading about it in a book. Could it be a carved incense burner?)",
          TalkActionId = {
            [1] = "220014:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6514"
        },
        [12001507] = {
          Camera = "-37.900391,41.320801,125.242188,0.00003,17.980465,116.970291,22.896927,616.28064,false,Manual,10.0",
          ContentKR = "(향로의 연기가 가늘게 피어오르며 곧게 하늘로 뻗어 올라가다, 그대로 사라진다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001507,
          Duration = 5,
          FinalCamera = "-37.900391,41.320801,125.242188,0.000031,26.780283,116.768852,22.896927,616.28064,false,Manual,10.0",
          GUID = "1E0B653E",
          NextDialogue = 12001508,
          Subtitle = "(Slender trails of smoke curl upwards, perfectly straight, before fading into nothingness.)",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B653E"
        },
        [12001508] = {
          Camera = "-1.962891,363.010254,80.773438,0.000094,-10.804443,-134.590561,35.000011,200.0,false,DoNotOverride,10.0",
          ContentKR = "이 향은 우리 화서만 있는 특산물이야. 폭시코르 원액에 포함된 어떤 특수 물질과 높은 친화력을 가지고 있어서, 조금만 닿아도 연기 흔적에 변화를 일으키거든.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001508,
          GUID = "1E0B6568",
          NextDialogue = 12001509,
          SpeakNpcId = 220014,
          Subtitle = "This incense is a rare speciality of Huaxu. It resonates powerfully with a particular substance found in pure Phoxichor. Even the slightest contact will cause the smoke to change its pattern.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6568"
        },
        [12001509] = {
          Camera = "26.769531,320.916504,68.851562,0.000117,-2.605321,-158.169327,58.891438,116.774818,false,Manual,10.0",
          ContentKR = "...연기 흔적을 보니, 그들이 가져온 물건은 최하급도 못 되는 수준이군.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001509,
          FacialId = {
            [1] = "220014:None"
          },
          GUID = "1E0B6592",
          LookAt = {
            [1] = "220014:p(LookatZhiliu)"
          },
          NextDialogue = 12001510,
          Scripts = "LookAt{_delay{3},LookAtDescription{\"220014:n(220018)\"}}",
          SpeakNpcId = 220014,
          Subtitle = "...Judging by this reaction, the Phoxichor he's brought is worse than even the lowest-grade.",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6592"
        },
        [12001510] = {
          Camera = "-23.337891,188.639648,65.816406,0.00015,-4.200252,113.402977,35.000011,302.910889,false,Manual,10.0",
          ContentKR = "고순도 폭시코르 원액은 군에서 관리하는 물자라 우리가 쉽게 구할 수 있는 게 아니긴 합니다...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001510,
          FacialId = {
            [1] = "220018:CM_Sad01"
          },
          GUID = "1E0B65BC",
          NextDialogue = 12001511,
          SpeakNpcId = 220018,
          Subtitle = "High-purity Phoxichor is military-regulated. It's not as though common folk like us can get hold of it easily...",
          TalkActionId = {
            [1] = "220018:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B65BC"
        },
        [12001511] = {
          Camera = "-32.541016,606.330078,36.949219,0.000098,0.798538,-99.188156,35.000015,350.264587,false,Manual,4.0",
          ContentKR = "뭐, 나름대로 특별한 연줄이라도 있는 줄 알았더니 결국 별거 없었네. 괜히 헛걸음만 했군.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001511,
          GUID = "1E0B65E6",
          NextDialogue = 12001512,
          SpeakNpcId = 220014,
          Subtitle = "I was under the impression you had your own connections. Clearly not. What a complete waste of my time.",
          TalkActionId = {
            [1] = "220014:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B65E6"
        },
        [12001512] = {
