        [12001519] = {
          Camera = "-79.387329,-101.302734,236.034424,0.000077,-24.5979,142.995789,37.000004,300.0,false,Manual,10.0",
          ContentKR = "괜찮아, 괜찮아! 우리 시종은 원래 가는 곳마다 사고를 몰고 다니는 체질이라니까!",
