          DialogueId = 12001519,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1E0B6736",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 12001520,
          SpeakNpcId = 200002,
          Subtitle = "Oh, no worries at all! My Little Minion has a special knack for attracting trouble wherever {性别:he|she} goes!",
          TalkActionId = {
            [1] = "200002:Deny01"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6736"
