          SpeakNpcId = 220014,
          Subtitle = "Hehe... Well then, take care.",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B678A"
        },
        [12001522] = {
          ContentKR = "...맞다, 내가 이 근처는 아직 잘 모르는데, 혹시 '아스포델'이라는 술집이 어디 있는지 알아?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001522,
          FacialId = {
            [1] = "220014:Smile01"
          },
          GUID = "1E0B67B4",
          NextDialogue = 12001523,
          SpeakNpcId = 220014,
          Subtitle = "Oh, one more thing — I'm not familiar with this area. Do you happen to know the way to a tavern called The Asphodel?",
          TalkActionId = {
            [1] = "220014:Talk02_Start",
            [2] = "100001:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B67B4"
