          FinalCamera = "-713.664185,420.12207,115.166016,0.000445,19.023415,99.934578,45.0,80.998604,false,Manual,10.0",
          GUID = "1E0B6BF8",
          Scripts = "CameraMoveTo{_delay{0.3},TargetPosition{\"-714.71991,426.150391,115.296875,0.000431,19.023422,99.934555,45.000011,73.319534,false,Manual,10.0\"},duration{5}}",
          SpeakNpcId = 100001,
          Subtitle = "...!",
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6BF8"
        },
        [12001549] = {
          ContentKR = "〈분실물 공고〉",
          DialogueId = 12001549,
          Duration = 2,
          GUID = "1E0B6C22",
          NextDialogue = 12001556,
          Subtitle = "Lost and Found Notice",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C22"
        },
        [12001550] = {
          Camera = "-695.929321,48.697266,125.119141,0.000423,-2.775563,92.313728,35.0,445.0,false,Manual,10.0",
          ContentKR = "시종, 뭘 그렇게 뚫어지게 보고 있는 거야? 스노우도 좀 보여줘!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001550,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1E0B6C4C",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "220019:n(100001)",
            [3] = "100001:p(paper)"
          },
          NextDialogue = 12001551,
          Scripts = [[
SEQ{
PlayAnimation{_delay{2.5},ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Hey, Little Minion, what are you looking at? Let me see!",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C4C"
        },
        [12001551] = {
          Camera = "-509.560974,609.379883,181.859375,0.000415,-15.375602,-144.277359,35.0,360.0,false,Manual,10.0",
          ContentKR = "어라? 이 검, 뭔가 익숙한데? 어디서 본 것 같은데...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001551,
          GUID = "1E0B6C76",
          NextDialogue = 12001552,
          Scripts = "PlayFacial{_delay{2},ActorId{200002},FacialId{\"Syouganai01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Huh? This sword looks kind of familiar... Have we seen it somewhere before?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C76"
        },
        [12001552] = {
          Camera = "-646.596497,493.004883,151.15625,0.000393,-22.975636,-135.875137,35.000008,181.619598,false,Manual,10.0",
          ContentKR = "검에 있는 문양... 아! 스노우 기억 났어! 이거 시종 네 거잖아, 그 '시대를 풍미했던 전설의 무기' 말이야!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001552,
          FinalCamera = "-669.792358,470.508789,137.451172,0.000393,-22.975636,-135.875137,35.000008,139.75914,false,Manual,10.0",
          GUID = "1E0B6CA0",
          NextDialogue = 12001553,
          Scripts = "PlayFacial{_delay{2.5},ActorId{200002},FacialId{\"Shock01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "The pattern on the blade... Ah! I remember now! That's your \"legendary weapon,\" isn't it?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6CA0"
        },
        [12001553] = {
          ContentKR = "오늘 자정에 돌려달라니... 이 공고를 낸 사람 진짜 바보 같네. 만약 아무도 못 본다면, 그 사람은 전화부스에서 밤새워 기다리다 지치겠지? 안 그래, 시종?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001553,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          GUID = "1E0B6CCA",
          NextDialogue = 12001554,
          SpeakNpcId = 200002,
          Subtitle = "\"By midnight\"...? What kind of goof writes a lost-and-found notice like this? What if the person who has the sword never comes across the notice and doesn't show up? That poor person might end up waiting all night at the phone booth! Am I right, Little Minion?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6CCA"
        },
        [12001554] = {
          Camera = "-464.445679,605.799805,172.630859,0.000425,-12.175925,-151.479797,35.000008,287.978119,false,Manual,10.0",
          ContentKR = "...시종, 너 갑자기 왜 이렇게 조용해졌어? 야, 야... 너 왜 그래?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001554,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-440.479553,548.991211,172.630859,0.000429,-12.375913,-162.080276,35.000008,287.978119,false,Manual,10.0",
          GUID = "1E0B6CF4",
          NextDialogue = 12001555,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "...Hey, Little Minion, I was talking to you! Hello? Are you okay?",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6CF4"
        },
        [12001555] = {
          Camera = "-715.893799,240.316406,68.830078,0.000409,9.823683,97.518883,35.0,265.0,false,Manual,10.0",
          ContentKR = "응, 어... 몸이 좀 안 좋아서. 먼저 돌아가서 쉬어야겠어...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001555,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "1E0B6D1E",
          SpeakNpcId = 100001,
          Subtitle = "Uh... I'm not feeling great. I think I'll head back and rest for a bit.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6D1E"
        },
        [12001556] = {
          ContentKR = "잃어버린 검을 찾습니다. 이 검은 저에게 매우 소중한 물건입니다. 저는 가장 가까운 사람과 헤어지게 되었고, 그때 그녀가 마침 이 검을 가지고 있었습니다. ",
          DialogueId = 12001556,
          Duration = 2,
          GUID = "1E0B6C23",
          NextDialogue = 12001557,
          Subtitle = "I've lost a sword — a very precious one. It was last in the possession of a close family member of mine from whom I was separated.",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C23"
        },
        [12001557] = {
          ContentKR = "이 검에 대한 소식을 알고 계신 분은 오늘 자정, 광장 앞 빨간색 전화부스로 가져다주십시오. 반드시 후한 보답을 드리겠습니다...",
          DialogueId = 12001557,
          Duration = 4,
          GUID = "1E0B6C24",
          Subtitle = "If you have any information about its whereabouts, please bring it to the red phone booth in the square by midnight tonight. A generous reward is guaranteed.",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6C24"
        },
        [12001601] = {
          ContentKR = "(잠깐 쉬어가자...)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001601,
          GUID = "1E0B74AA",
          SpeakNpcId = 100001,
          Subtitle = "(...I should take a break for now.)",
          VoiceName = "voice/$Locale$/story/1200/120016/1E0B74AA"
        },
        [12001602] = {
          ContentKR = "(곧 스토리 내용이 이어집니다. 충분히 준비한 후 플레이하시는 것을 추천합니다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001602,
          GUID = "1E0B74D4",
          Subtitle = "(For the upcoming storyline, it is recommended to allocate sufficient time for the best experience.)",
          VoiceName = "voice/$Locale$/story/1200/120016/1E0B74D4"
        },
        [12001700] = {
          Content = "【过场动画】玩家蹑手蹑脚地关上休憩所的门，一转身，和守在门外本来摆着装逼抱胸姿势的白相撞。白吃痛捂住额头。",
          DialogueId = 12001700,
          GUID = "1E0B8511"
        },
        [12001701] = {
          Camera = "-138.622559,507.972168,78.030762,0.000004,0.99994,-73.992325,35.000011,110.363411,false,Manual,10.0",
          ContentKR = "아파파파파파...",
          DialogueId = 12001701,
          FacialId = {
            [1] = "200002:Sad01"
          },
          FinalCamera = "-108.891602,410.023926,84.251953,0.000004,0.99994,-73.992134,35.000015,124.311493,false,Manual,10.0",
          GUID = "1E0B8512",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 12001702,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"BaiTX_Story_RubForehead_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Owwww! That hurts!",
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8512"
        },
        [12001702] = {
          Camera = "231.329102,370.69043,84.921143,0.000096,1.799058,-174.790344,35.000008,324.411682,false,DoNotOverride,2.202561",
          ContentKR = "...스노우, 여기서 뭐 하고 있는 거야?",
          DialogueId = 12001702,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B853C",
          NextDialogue = 12001703,
          SpeakNpcId = 100001,
          Subtitle = "...Snow? What are you doing here?",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B853C"
        },
        [12001703] = {
          Camera = "-143.492676,420.148926,90.224854,0.000035,-3.800105,-62.792645,35.000015,158.019394,false,Manual,10.0",
          ContentKR = "내가 여기 왜 있냐고?... 아, 맞다!",
          DialogueId = 12001703,
          GUID = "1E0B8566",
          NextDialogue = 12001704,
          Scripts = [[
PARA{
PlayFacial{_delay{3},ActorId{200002},FacialId{"Shock01"}},
LookAt{_delay{3},LookAtDescription{"200002:n(100001)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "What's Snow doing here? Oh, right!",
          TalkActionId = {
            [1] = "200002:BaiTX_Story_RubForehead_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8566"
        },
        [12001704] = {
          Camera = "-209.10791,563.994629,166.718994,0.000088,-16.400301,-72.382965,35.000008,319.844727,false,DoNotOverride,10.0",
          ContentKR = "몰래 빠져나가려는 거지? 네 모든 행동은 이 마왕님의 반짝이는 눈을 속일 수 없다고!",
          DialogueId = 12001704,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-220.403809,560.411621,166.718994,0.000088,-16.400301,-72.382965,35.000008,318.951508,false,DoNotOverride,10.0",
          GUID = "1E0B8590",
          NextDialogue = 12001705,
          SpeakNpcId = 200002,
          Subtitle = "You were trying to sneak off, weren't you? Nothing escapes the sharp eyes of this Demon King!",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8590"
        },
        [12001705] = {
          ContentKR = "오늘 하루 종일 네가 정신 팔린 것 같더니, 저녁도 거의 안 먹더라. 내가 딱 알아봤지.",
          DialogueId = 12001705,
          GUID = "1E0B85BA",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001706,
          Scripts = [[
SEQ{
MoveTo{ActorId{200002},MoveSpeed{45},TargetPoint{"12000303Xiaobai"}},
PlayAnimation{_delay{3.5},ActorId{200002},AnimationId{"Confident_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Look at you — you've been out of it all day, and you barely even touched your dinner. I saw right through it—",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B85BA"
        },
        [12001706] = {
          Camera = "-182.647461,379.094727,120.482178,0.000029,-26.199799,-40.567471,23.066504,99.404587,false,Manual,10.0",
          ContentKR = "이 마왕님 몰래 혼자서 모험이라도 가려고? 안 돼!",
          DialogueId = 12001706,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          GUID = "1E0B85E4",
          NextDialogue = 12001707,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Trying to ditch me and go adventuring all by yourself? Not a chance!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B85E4"
        },
        [12001707] = {
          Camera = "-26.722656,319.375977,59.239258,0.000077,19.398317,164.820892,35.000011,187.953278,false,Manual,10.0",
          ContentKR = "...너를 일부러 데려가지 않으려던 건 아니야. 다만 이번 일은 휘페르보레아 제국 병사들과 얽힐 가능성이 있어서, 너까지 끌어들이고 싶지 않아.",
          DialogueId = 12001707,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "1E0B860E",
          NextDialogue = 12001708,
          SpeakNpcId = 100001,
          Subtitle = "...It's not that I don't want to bring you. It's just... this time, I might have to deal with the Hyperborean soldiers and land myself in trouble. I don't want to drag you into my mess.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B860E"
        },
        [12001708] = {
          Camera = "-182.111328,611.16748,189.450439,0.000017,-21.399889,-85.183884,35.000011,306.042999,false,Manual,10.0",
          ContentKR = "그게... 우리 휘페르보레아 제국 병사들 건드린 게 이번이 처음도 아니잖아?",
          DialogueId = 12001708,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "1E0B8638",
          NextDialogue = 12001709,
          SpeakNpcId = 200002,
          Subtitle = "Uh, haven't we already messed with the Hyperborean soldiers like a hundred times before?",
          TalkActionId = {
            [1] = "200002:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8638"
        },
        [12001709] = {
          Camera = "-103.983398,353.585449,106.5271,0.000045,18.199305,158.02092,35.000015,95.311615,false,Manual,10.0",
          ContentKR = "어, 그러고 보니 그렇긴 해.",
          DialogueId = 12001709,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "1E0B8662",
          NextDialogue = 12001710,
          SpeakNpcId = 100001,
          Subtitle = "...Can't argue with that.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8662"
        },
        [12001710] = {
          Camera = "-179.918945,441.123047,116.523438,0.000046,-14.999873,-65.990524,35.000019,142.117508,false,Manual,10.0",
          ContentKR = "어쨌든! 넌 내가 책임지는 사람이야. 시종 네 일이면 이 마왕님의 일이기도 하지.",
          DialogueId = 12001710,
          GUID = "1E0B868C",
          NextOptions = {
            [1] = 120017101,
            [2] = 120017111
          },
          SpeakNpcId = 200002,
          Subtitle = "Anyway! You're under my wing, Little Minion. Your mess is surely my mess!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B868C"
        },
        [12001711] = {
          ContentKR = "히히, 그건 당연하지!",
          DialogueId = 12001711,
          FacialId = {
            [1] = "200002:Smile01"
          },
          GUID = "1E0B86B6",
          NextDialogue = 12001714,
          SpeakNpcId = 200002,
          Subtitle = "Hm-hmm~ Of course! That goes without saying!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B86B6"
        },
        [12001712] = {
          ContentKR = "전, 전혀 그런 적 없거든...! 그건 네 실력을 시험해 본 거야. 오해하지 마!",
          DialogueId = 12001712,
          FacialId = {
            [1] = "200002:Guilty"
          },
          GUID = "1E0B86E0",
          NextDialogue = 12001713,
          SpeakNpcId = 200002,
          Subtitle = "T—That's not true... I was just testing your strength! Don't get the wrong idea!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B86E0"
        },
        [12001713] = {
          ContentKR = "게다가, 스노우처럼 똑똑한 머리라면 뒤에서 지휘만 해도 크게 도움이 될 거야!",
          DialogueId = 12001713,
          GUID = "1E0B870A",
          NextDialogue = 12001714,
          Scripts = "PlayFacial{_delay{2.5},ActorId{200002},FacialId{\"Happy02\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Besides, even if I'm not on the front lines, my genius-level combat tactics must have been a huge help!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B870A"
        },
        [12001714] = {
          Camera = "-193.492676,858.771973,219.772217,0.000168,-15.999936,-85.57428,34.755398,150.385727,false,DoNotOverride,10.0",
          ContentKR = "아무튼, 결론은... 너의 모험엔 내 동행이 꼭 필요하다는 거야!",
          DialogueId = 12001714,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "1E0B8734",
          NextDialogue = 12001715,
          SpeakNpcId = 200002,
          Subtitle = "In any case — your adventures wouldn't be complete without the great Demon King at your side!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8734"
        },
        [12001715] = {
          Camera = "-89.208496,337.930176,121.906006,0.000111,7.796852,155.010193,43.911587,110.917465,false,Manual,10.0",
          ContentKR = "스노우...",
          DialogueId = 12001715,
          Duration = 1,
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "-97.441895,341.768066,123.625977,0.000109,7.796852,155.010193,43.911587,98.815788,false,Manual,10.0",
          GUID = "1E0B875E",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 12001716,
          SpeakNpcId = 100001,
          Subtitle = "Snow...",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B875E"
        },
        [12001716] = {
          Camera = "-174.07666,474.493164,117.193115,0.000148,-9.602412,-73.385498,35.000008,162.486938,false,Manual,10.0",
          ContentKR = "그, 그러니까, 너 너무 감동하지는 마... 너 그러면 스노우가 검 휘두르는 데 방해되잖아...",
          DialogueId = 12001716,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E0B8788",
          NextDialogue = 12001717,
          SpeakNpcId = 200002,
          Subtitle = "W—Well... don't get too impressed, okay? You'll throw me off my game if you keep that up...",
          TalkActionId = {
            [1] = "200002:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8788"
        },
        [12001717] = {
