          NextDialogue = 12001719,
          SpeakNpcId = 200002,
          Subtitle = "Absolutely and perfectly got it! I'm great at running... I mean, tactical retreat!",
          TalkActionId = {
            [1] = "200002:Agree"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B87DC"
        },
        [12001719] = {
