        },
        [12001723] = {
          ContentKR = "뭐야, 쓰레기잖아... 대체 누가 아무 데나 쓰레기를 버려놓은 거야? 예의도 없는 사람들 같으니. 쓰레기통 공주님한테 혼쭐이 나야겠어!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001723,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E0B88AE",
          NextDialogue = 12001724,
          Scripts = [[
SEQ{
PlayAnimation{_delay{2.5},ActorId{200002},AnimationId{"Angry01_Start"},Duration{2}},
CameraMoveTo{_delay{3.5},TargetPosition{"227.583008,-137.688293,53.102295,0.000012,6.199059,171.79805,35.000011,418.803284,false,Manual,10.0"},duration{0}},
