}]],
          SpeakNpcId = 200002,
          Subtitle = "Oh, it's just rubbish... Who's been throwing it around like this? Seriously, where are their manners? They need a good talking-to from Princess Rubbish Bin!",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B88AE"
        },
        [12001724] = {
          ContentKR = "괜찮아, 스노우? 혹시 졸린 거 아니야?",
