        },
        [12001725] = {
          Camera = "-153.960083,23.094482,182.556152,0.000015,-36.798935,-91.580711,35.000008,171.976578,false,Manual,10.0",
          ContentKR = "너를 딱 잡으려고 스노우가 졸린 것도 참고 문 앞에서 정말 오래 기다렸다니까...",
