          NextDialogue = 12001726,
          Scripts = "PlayFacial{_delay{2},ActorId{200002},FacialId{\"Unacceptable01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "To catch you in the act, I had to stay up late waiting outside your door for sooo long...",
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8902"
        },
        [12001726] = {
