          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "200002:p(90)"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8956"
        },
        [12001728] = {
          ContentKR = "뒷모습은 정말 닮은 것 같은데... 확신할 순 없어...",
