        [12001732] = {
          Camera = "-175.340332,270.149841,203.560059,0.000169,-16.199125,-91.996445,54.999645,435.053986,false,Manual,10.0",
          ContentKR = "언니, 혹시 동전 하나 빌려줄 수 있어요?",
