          DialogueId = 12001733,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "1E0B8A52",
          NextDialogue = 12001734,
          SpeakNpcId = 200002,
          Subtitle = "I was really hoping for a nice warm cup of honey milk, but I tripped on the way out... and my coin rolled right into the sewer.",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8A52"
        },
        [12001734] = {
