        },
        [12001765] = {
          Camera = "194.37793,-166.161133,140.183105,0.000003,-1.799557,152.996048,37.747215,362.031006,false,Manual,10.0",
          ContentKR = "뭐가 그렇게 궁금한 겁니까?! 그쪽이 알아야 할 일은 아니잖습니까!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001765,
          GUID = "1E0B8F92",
          NextDialogue = 12001766,
          SpeakNpcId = 220025,
          Subtitle = "What business is that of yours? That's classified information—",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8F92"
        },
        [12001766] = {
          Camera = "-108.702148,25.432129,82.476562,0.000077,13.598018,-45.800716,51.545876,204.890732,false,Manual,3.882469",
          ContentKR = "(병사의 호통이 갑자기 멈춘다. 곁눈질로 보니, 지류가 묵직한 주머니를 하나 건네고 있다. 병사는 그 무게를 느끼더니 슬쩍 소매 속에 넣는다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001766,
          Duration = 5,
          GUID = "1E0B8FBC",
          NextDialogue = 12001767,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"100001:p(Nvzhu_Look_309)\"}}",
          Subtitle = "(The soldier's outburst stops short. Out of the corner of your eye, you see Zhiliu hand him a small, weighty pouch. The soldier weighs it in his hand before discreetly slipping it into his sleeve.)",
          TalkActionId = {
            [1] = "220014:Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8FBC"
        },
        [12001767] = {
          Camera = "355.125,200.536621,154.582031,0.000034,-5.1997,-148.204956,35.000011,100000.0,false,DoNotOverride,10.0",
          ContentKR = "아, 뭐 별건 아니고... 오늘 밤 중요한 도망자를 잡으라는 명령이 떨어져서, 도시 전 병력이 동원된 상황입니다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001767,
          GUID = "1E0B8FE6",
          LookAt = {
            [1] = "100001:n(220025)"
          },
          NextDialogue = 12001768,
          SpeakNpcId = 220025,
          Subtitle = "Well... I suppose there's no harm in sharing a little. We've been told to catch a high-profile fugitive tonight. Every guard in the city has been called in for the search.",
          TalkActionId = {
            [1] = "220014:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8FE6"
        },
        [12001768] = {
          ContentKR = "근데 아직 그 도망자가 어디 있는지, 생김새는 어떤지 아무 정보도 없군요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001768,
          GUID = "1E0B9010",
          NextDialogue = 12001769,
          SpeakNpcId = 220025,
          Subtitle = "Problem is, nobody seems to know where this fugitive is hiding — or what they even look like.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9010"
        },
        [12001769] = {
          Camera = "-270.78418,255.63623,167.03418,0.000086,-8.000794,-55.608383,35.000011,100000.0,false,DoNotOverride,10.0",
          ContentKR = "흠, 이거 좀 곤란하네요... 저는 화서에서 온 상인입니다. 제 전용 비행선이 지금 교외에 정박 중이고, 6시간 후에는 중요한 상업 회담에 참석해야 해요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001769,
          GUID = "1E0B903A",
          LookAt = {
            [1] = "100001:n(220025)",
            [2] = "200002:n(220025)"
          },
          NextDialogue = 12001770,
          SpeakNpcId = 220014,
          Subtitle = "Ah, that's unfortunate... You see, I'm a merchant from Huaxu, and my private airship is docked just outside the city. In six hours, I have an important business meeting that I simply cannot miss.",
          TalkActionId = {
            [1] = "220014:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B903A"
        },
        [12001770] = {
          ContentKR = "저와 차에 있는 동료들도 모두 신원이 확실한 사람들이고, 공식적인 출국 서류도 준비한 상태입니다. 어떻게 좀 봐주실 수 있을까요?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001770,
          GUID = "1E0B9064",
          NextDialogue = 12001771,
          SpeakNpcId = 220014,
          Subtitle = "Everyone aboard, myself included, is a law-abiding citizen with all the proper exit permits. Surely you could find it in your heart to make an exception?",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9064"
        },
        [12001771] = {
          Camera = "-90.224609,27.822266,129.658691,0.000123,-0.199885,-48.183372,51.572987,182.084885,false,Manual,10.0",
          ContentKR = "(지류가 서류를 보여준다. 서류에 있는 자신의 사진이 깔끔하게 붙어 있는게 보인다. 사진 속 약간 딱딱한 표정이 낯설게 느껴진다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001771,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
          Duration = 5,
          FinalCamera = "-83.21582,19.981934,129.623047,0.000123,-0.199885,-48.18306,51.572987,171.736893,false,Manual,10.0",
          GUID = "1E0B908E",
          NextDialogue = 12001772,
          Subtitle = "(Among the documents Zhiliu presents, you spot your own photograph neatly attached in the designated section. The stern expression in the picture feels oddly unfamiliar.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B908E"
        },
        [12001772] = {
          ContentKR = "(지류 사장님이... 언제 이런 서류를 준비한 거지?)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001772,
          DisableMouth = 1,
          Duration = 5,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B90B8",
          LookAt = {
            [1] = "220014:n(220025)"
          },
          NextDialogue = 12001773,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...When did she prepare these documents?)",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B90B8"
        },
        [12001773] = {
          Camera = "100.349609,-20.827148,139.20459,0.000054,-0.000246,-172.803757,35.000011,264.540283,false,Manual,6.124233",
          ContentKR = "여사님... 제가 일부러 이러는 건 아니지만, 저희 상관께서 어떤 사람도 이곳을 지나가게 하지 말라고 엄격히 명령했습니다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001773,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E0B90E2",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 12001774,
          SpeakNpcId = 220025,
          Subtitle = "Ma'am... It's not my intention to give you a hard time, but our orders are clear — no one is allowed through here tonight.",
          TalkActionId = {
            [1] = "220025:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B90E2"
        },
        [12001774] = {
          Camera = "-410.826172,260.788574,156.883301,0.000045,-3.800918,-40.007858,60.419567,100000.0,false,DoNotOverride,10.0",
          ContentKR = "좋아요, 그럼 당신들 군번과 상관의 이름을 알려 주세요. 제가 직접 해결 방법을 찾아보죠.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001774,
          GUID = "1E0B910C",
          NextDialogue = 12001775,
          SpeakNpcId = 220014,
          Subtitle = "Oh? I see. Then perhaps you could tell me your regiment number and the name of your commanding officer. I may be able to sort this out myself.",
          TalkActionId = {
            [1] = "220014:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B910C"
        },
        [12001775] = {
          Camera = "-60.169922,20.828613,119.424805,0.000075,12.599663,-45.606236,46.428596,118.094795,false,Manual,10.0",
          ContentKR = "...후훗, 만약 루시아나 로레토님이 제가 여기서 한 병사 때문에 중요한 협상을 놓쳤다는 걸 알게 된다면, 아마 그의 티타임 자리에서 꽤 흥미로운 이야기감이 되겠죠.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001775,
          GUID = "1E0B9136",
          NextDialogue = 12001776,
          SpeakNpcId = 220014,
          Subtitle = "After all, if Luciana Loretto were to hear that I was detained by a foot soldier and missed a crucial business engagement, wouldn't that make for quite the amusing tale over afternoon tea?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9136"
        },
        [12001776] = {
          Camera = "24.524414,3.004395,148.750488,0.000044,-2.599973,-158.404205,35.000008,100000.0,false,DoNotOverride,10.0",
          ContentKR = "루시아나 로레토... 어디서 들어본 이름인데... 제국 재무관님의 존함 아니신가?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001776,
          GUID = "1E0B9160",
          LookAt = {
            [1] = "220026:n(220025)",
            [2] = "220025:n(220026)"
          },
          NextDialogue = 12001777,
          SpeakNpcId = 220026,
          Subtitle = "Luciana Loretto... Wait, isn't that the Imperial Minister of Finance!?",
          TalkActionId = {
            [1] = "220025:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9160"
        },
        [12001777] = {
          ContentKR = "이봐, 여기 다시 봐. 서류에 그분의 친필 서명이 있는 것 같네!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001777,
          GUID = "1E0B918A",
          NextDialogue = 12001778,
          SpeakNpcId = 220026,
          Subtitle = "Hey, look — this document actually bears her personal signature!",
          TalkActionId = {
            [1] = "220014:Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B918A"
        },
        [12001778] = {
          ContentKR = "이건...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001778,
          GUID = "1E0B91B4",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 12001779,
          SpeakNpcId = 220025,
          Subtitle = "Er...",
          TalkActionId = {
            [1] = "220025:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B91B4"
        },
        [12001779] = {
          Camera = "-491.920898,478.322754,448.695801,0.000088,-10.999807,-47.399258,9.196175,100000.0,false,DoNotOverride,10.0",
          ContentKR = "전 부대 주의! 목표가 극장 근처에서 발견된 것으로 추정된다. 무기를 소지하고 있으며 탈출을 시도 중이다. 인근 부대는 현장으로 신속히 지원하라. 다시 반복한다. 인근 부대는 현장으로 신속히 지원하라.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001779,
          FinalCamera = "-491.920898,478.322754,448.695801,0.000088,-1.599603,-42.39946,9.196175,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B91DE",
          NextDialogue = 12001780,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/intro_crowdcombat\"},PlayAs2D{true}}",
          Subtitle = "Attention, all units! The target is believed to have been sighted near the theatre, armed and attempting to escape. Nearby squads, proceed to the location immediately. I repeat — nearby squads, converge on the theatre for support!",
          TalkActionId = {
            [1] = "220025:Shock_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B91DE"
        },
        [12001780] = {
          Camera = "-245.133789,192.716309,132.871094,0.00009,-3.199267,-51.80265,30.0,100000.0,false,DoNotOverride,10.0",
          ContentKR = "흠... 보아하니 용의자가 나타난 모양이군요. 그럼, 어떻게 하겠습니까? 우리를 계속 붙잡아 둘 겁니까?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001780,
          FacialId = {
            [1] = "220014:Smile01"
          },
          GUID = "1E0B9208",
          LookAt = {
            [1] = "220014:n(220025)",
            [2] = "100001:n(220025)",
            [3] = "200002:n(220025)"
          },
          NextDialogue = 12001781,
          SpeakNpcId = 220014,
          Subtitle = "It seems your fugitive has finally turned up. So, what now? Do you still intend to detain us?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9208"
        },
        [12001781] = {
          Camera = "259.166016,139.326172,124.026855,0.0001,-2.599324,-148.204941,30.000002,100000.0,false,DoNotOverride,10.0",
          ContentKR = "...이렇게 하시죠, 여사님. 더 이상 귀한 시간 뺏지 않겠습니다. 대신, 저희가 당신의 출국을 보장할 수 있도록 배웅 인원을 붙이겠습니다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001781,
          GUID = "1E0B9232",
          NextDialogue = 12001782,
          SpeakNpcId = 220025,
          Subtitle = "...How about this, ma'am: we won't delay your journey any further, but we'll assign personnel to escort you and ensure safe passage out of the city.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9232"
        },
        [12001782] = {
          ContentKR = "비행선이 이륙하기 전까지, 여사님과 부하분들 모두 우리 시야 안에 머물러야 합니다. 만약 조금이라도 수상한 행동이 포착된다면, 이는 제국에 대한 도발로 간주할 것입니다. 여사님, 이 방안은 괜찮으십니까?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001782,
          GUID = "1E0B925C",
          NextDialogue = 12001783,
          SpeakNpcId = 220025,
          Subtitle = "Until your airship departs, you and your party must remain in our line of sight. Any unusual behaviour will be treated as an act of provocation against the Empire. Does that sound acceptable?",
          TalkActionId = {
            [1] = "220014:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B925C"
        },
        [12001783] = {
          Camera = "-247.888672,60.718262,171.297363,0.000116,-9.999724,-29.603325,35.000011,298.698639,false,Manual,10.0",
          ContentKR = "하하... 괜찮습니다. 남을 돕는 것은 곧 자신을 돕는 것이니까요. 장관님들의 요구에 꼭 따를게요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001783,
          GUID = "1E0B9286",
          LookAt = {
            [1] = "100001:n(220025)"
          },
          NextDialogue = 12001784,
          SpeakNpcId = 220014,
          Subtitle = "Hehe... That's perfectly fine. Helping others, as they say, is helping oneself. Rest assured, I'll cooperate fully.",
          TalkActionId = {
            [1] = "220014:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9286"
        },
        [12001784] = {
          Camera = "-459.007812,408.505859,307.084473,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
          ContentKR = "이해해 주셔서 감사합니다. 길을 열어라!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001784,
          FinalCamera = "-534.192383,507.5625,345.104492,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B92B0",
          SpeakNpcId = 220025,
          Subtitle = "Thank you for your understanding, ma'am. Let them through!",
          TalkActionId = {
            [1] = "220014:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B92B0"
        },
        [12001785] = {
          ContentKR = "루나가 식식거리며 달려갔다.",
          DialogueId = 12001785,
          GUID = "1E0B8AD1",
          Subtitle = "Snow stormed off in a huff."
        },
        [12001801] = {
          Camera = "26.581055,-95.871094,153.29248,0.000088,-8.170654,-51.38456,12.0,60.0,false,Manual,10.0",
          ContentKR = "자, 이제 좀 자유롭게 이야기할 수 있겠네. 다만, 표정을 관리하는 게 좋겠어. 뒤따라오는 병사들이 아직은 열심히 따라올 테니까.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001801,
          FinalCamera = "1.03418,-98.566895,152.582031,0.000092,-8.970668,-40.585316,12.0,100.0,false,Manual,10.0",
          GUID = "1E0B957A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/1_0/0085_scene_icelake"}},
PlayNormalSound{EventKey{"car2drive"},EventPath{"event:/sfx/common/story/yinru/car_drive"},PlayAs2D{true}}
}]],
          SpeakNpcId = 220014,
          Subtitle = "Alright, we can speak freely now. Just be sure to keep your expressions in check — those soldiers are still dutifully trailing behind us.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B957A",
          bNotRecall = 1
        },
        [12001802] = {
          ContentKR = "하하, 그건 내가 고용한 월석 사냥꾼이지.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001802,
          GUID = "1E0B95A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001803,
          SpeakNpcId = 220014,
          Subtitle = "Ah, that would be a Phoxhunter I hired.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95A4"
        },
        [12001803] = {
          ContentKR = "그리 많지 않은 보수만으로도, 위험을 무릅쓰고 나서는 사람들이 있거든. 그 돈으로는 재무관의 교외 저택에 있는 사냥개 한 마리조차 살 수 없을 텐데 말이지.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001803,
          GUID = "1E0B95CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001804,
          SpeakNpcId = 220014,
          Subtitle = "It required very little — just a modest sum of money to entice someone into taking the risk. The amount was so minimal, it wouldn't even cover the cost of a single hunting hound owned by the Finance Minister at her countryside estate.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95CE"
        },
        [12001804] = {
          ContentKR = "그래도 덕분에 오늘 밤 위기를 넘길 수 있었으니 다행이네.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001804,
          GUID = "1E0B95F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          Subtitle = "And yet, that small investment was all it took to steer us safely through tonight's crisis.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95F8"
        },
        [12001805] = {
          ContentKR = "재미있는 이야기를 하나 들려줄까?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001805,
          GUID = "1E0B9622",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001806,
          SpeakNpcId = 220014,
          Subtitle = "Would you like to hear something intriguing?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9622"
        },
        [12001806] = {
          ContentKR = "〈휘페르보레아 제국 조간신문〉은 제국 전역에 배포되는 신문이고, 휘페르보레아의 모든 주요 도시 중심 광장에는... 우연히도 빨간색 전화부스가 하나씩 서 있지.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001806,
          GUID = "1E0B964C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001807,
          SpeakNpcId = 220014,
          Subtitle = "The Hyperborea Daily is a newspaper sold throughout the entire Empire. And, as it happens, every major city in Hyperborea has... a red phone booth in its central square.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B964C"
        },
        [12001807] = {
          ContentKR = "오늘 아침 카밀라와 신문에 실린 사건 전말에 관해 이야기를 나눴어. 그 뒤로 혹시 몰라 몇 군데에 조심스럽게 무전을 보냈지.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001807,
          GUID = "1E0B9676",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001808,
          SpeakNpcId = 220014,
          Subtitle = "This morning, Camilla shared the story behind that article with me. After hearing the details, I decided to take precautions and sent out a few extra telegrams.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9676"
        },
        [12001808] = {
          ContentKR = "좋은 소식을 하나 알려줄게. 오늘 밤, 모든 도시의 전화부스에는 하얀 머리칼을 가진 여성이 서서 오지 않을 '옛 친구'를 기다리고 있을 거다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001808,
          GUID = "1E0B96A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001809,
          SpeakNpcId = 220014,
          Subtitle = "Here's some good news for you: tonight, in each of those cities, a white-haired woman is standing inside a red phone booth, patiently awaiting a \"long-lost family\" who will never arrive.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96A0"
        },
        [12001809] = {
          ContentKR = "아니, 이게 왜 좋은 소식이라는 거야? 스노우는 잘 모르겠는데...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001809,
          GUID = "1E0B96CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001810,
          SpeakNpcId = 200002,
          Subtitle = "Why is that good news? I don't get it...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96CA"
        },
        [12001810] = {
          ContentKR = "아마도 지류 사장님의 뜻은 적들이 제 정확한 위치를 모르고, 제가 아직 살아 있는지도 확신하지 못하기 때문에 큰 범위로 미끼를 뿌려서 절 유인해 내려는 것 같네요...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001810,
          GUID = "1E0B96F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001811,
          SpeakNpcId = 100001,
          Subtitle = "I think Proprietress Zhiliu means they aren't sure where I am — or even if I'm still alive. So, they had to scatter their bait across multiple cities to draw me out...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96F4"
        },
        [12001811] = {
          ContentKR = "정답이야, 정말 영리하군.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001811,
          GUID = "1E0B971E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001812,
          SpeakNpcId = 220014,
          Subtitle = "Precisely. You're quite the clever one.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B971E"
        },
        [12001812] = {
          ContentKR = "(나의 존재를 알고, 이런 함정을 설계한 제국 군단의 인물은 도대체 누구일까...?)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001812,
          GUID = "1E0B9748",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(They know I exist, and they've gone to such lengths to set such a complicated trap... Who in the Legion could be behind this?)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9748"
        },
        [12001813] = {
          ContentKR = "현재 상황을 보아하니, 비행선이 이륙할 때까지는 차량 밖으로 나갈 수 없네. 미안하지만, 이제부터는 나와 함께 화서로 가야겠군.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001813,
          GUID = "1E0B9772",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001814,
          RelatedWikiId = {
            [1] = 203001,
            [2] = 408010
          },
          SpeakNpcId = 220014,
          Subtitle = "Given the current circumstances, I'm afraid you can't leave the car until the airship departs. My apologies — it appears I'll have to take you to Huaxu with me.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9772"
        },
        [12001814] = {
          ContentKR = "지류 사장님, 몇 번이고 저를 도와주셔서 어떻게 감사드려야 할지 모르겠어요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001814,
          GUID = "1E0B979C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001815,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, you've saved me from trouble on multiple occasions. I don't even know how to begin repaying you.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B979C"
        },
        [12001815] = {
          ContentKR = "음... 감사라.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001815,
          GUID = "1E0B97C6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001816,
          SpeakNpcId = 220014,
          Subtitle = "Repay me? Hmm...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97C6"
        },
        [12001816] = {
          ContentKR = "마침 일이 하나 있는데 손이 모자라네. 화서에서 휘페르보레아로 돌아가는 비행선이 7일 후 출발하니, 그동안 괜찮다면 도와주면 어떨까?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001816,
          GUID = "1E0B97F0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001817,
          SpeakNpcId = 220014,
          Subtitle = "As it happens, there is a task that would benefit from an extra pair of capable hands. The airship returning from Huaxu to Hyperborea departs in seven days. If you don't mind staying with me until then, perhaps you could assist me.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97F0"
        },
        [12001817] = {
          ContentKR = "어때? 한 번 고려해 봐, 똑똑한 친구이니 보수는 충분히 챙길 거야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001817,
          GUID = "1E0B981A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001818,
          SpeakNpcId = 220014,
          Subtitle = "What do you say, my clever one? Of course, the compensation will be more than fair.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B981A"
        },
        [12001818] = {
          ContentKR = "(역시... 이 모든 게 우연이 아니었어.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001818,
          GUID = "1E0B9844",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextOptions = {
            [1] = 12001819,
            [2] = 12001820
          },
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I knew it... This was far too convenient to be a mere coincidence.)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9844"
        },
        [12001819] = {
          ContentKR = "이 차에 탄 이상, 거절할 기회는 없는 거겠죠.",
          DialogueId = 12001819,
          GUID = "1E0B986E",
          ImprPlusId = 1006,
          NextDialogue = 12001821,
          Subtitle = "Now that I'm in this car... I suppose refusing isn't really an option, is it?"
        },
        [12001820] = {
          ContentKR = "몇 번이나 저를 도와주셨으니, 기꺼이 보답하겠습니다.",
          DialogueId = 12001820,
          GUID = "1E0B9898",
          ImprPlusId = 1007,
          NextDialogue = 12001821,
          Subtitle = "You've helped me plenty of times — I'd be more than happy to return the favour."
        },
        [12001821] = {
          ContentKR = "멀고 먼 나라에 가서 한 번도 먹어보지 못한 맛있는 음식을 맛보고, 게다가 엄청난 보수도 받을 수 있다니... 시종, 이거 정말 멋진 대모험이 될 것 같은데!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001821,
          GUID = "1E0B98C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001822,
          SpeakNpcId = 200002,
          Subtitle = "Travelling to a far-off country, trying foods we've never seen before, and earning a hefty reward on top of it... Little Minion, doesn't that sound like the perfect adventure?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98C2"
        },
        [12001822] = {
          ContentKR = "맞다, 출발하기 전에... 한 가지 부탁을 더 드려도 될까요?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001822,
          GUID = "1E0B98EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001823,
          SpeakNpcId = 100001,
          Subtitle = "By the way, before we leave... may I ask one more favour?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98EC"
        },
        [12001823] = {
          ContentKR = "걱정하지 않아도 돼. 다른 도시에도 내가 고용한 임시 인력들이 있거든. 여기저기 던져놓은 미끼 덕분에 휘페르보레아 제국 병사들은 오늘 밤 아무 성과 없이 허탕을 치게 될 거야. 그들은 너희가 아이스레이크 시티에 있다는 걸 알아채지는 못할 거야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001823,
          GUID = "1E0B9916",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001824,
          SpeakNpcId = 220014,
          Subtitle = "There's no need to worry. I've hired temporary workers in other cities as well. With so many \"fish\" taking the bait across the country, the Hyperborean soldiers will be kept busy tonight and come up empty-handed — they won't have a clue you're actually here in Icelake.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9916"
        },
        [12001824] = {
          ContentKR = "(이런 것까지 미리 예측했다니... 이 <H>화서</> 출신의 여사님, 도대체 날 통해 무슨 일을 의뢰하려는 거지...)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001824,
          GUID = "1E0B9940",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001825,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(She even accounted for that... Just what does this Huaxu lady really want from me...?)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9940"
        },
        [12001825] = {
          ContentKR = "(하지만 여기까지 왔으니 다른 선택은 없겠지. 7일이라면, 그래도 여유는 있는 편이야...)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001825,
          GUID = "1E0B996A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001826,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(But at this point, there's really no other way. Seven days... that should be manageable.)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B996A"
        },
        [12001826] = {
          ContentKR = "좋아요! 이 의뢰, 우리가 맡겠습니다!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001826,
          GUID = "1E0B9994",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          Scripts = "StopNormalSound{EventKey{\"car2drive\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright! We'll take on this commission!",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9994"
        },
        [12001830] = {
          DialogueId = 12001830,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 12001813,
          GUID = "1E0B957B",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextOptions = {
            [1] = 120018011,
            [2] = 120018041
          }
        },
        [12001901] = {
          Content = "假装这里非常热闹、节日氛围",
          DialogueId = 12001901,
          GUID = "1E0BA5E2"
        },
