    Loader = function()
      return {
        [12013903] = {
          ContentKR = "시, 시종 너너너, 함부로 귀신 이야기 같은 거 하지 마! 부소 언니는 여기 살고 있는 거 맞잖아. 그, 그렇지...?",
          DialogueId = 12013903,
          Duration = 3,
          GUID = "1E1356F6",
