          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "가훈에 따라, 축유는 이 세상의 모든 이들을 구해야 한다고 해서... 혹시 뭔가 잘못됐나요?",
          DialogueId = 12014004,
          FacialId = {
            [1] = "210013:Shy"
          },
          FinalCamera = "-32.965408,-8.578339,142.960938,0.00009,-1.597711,-174.588303,35.000011,144.691895,false,Manual,8.0",
          GUID = "1E136788",
          NextDialogue = 12014005,
          Scripts = "PlayAnimation{_delay{5.1},ActorId{210013},AnimationId{\"TilteHead_Start\"},Duration{1}}\n",
          SpeakNpcId = 210013,
          Subtitle = "Our family teachings say: \"Zhuyou therapy user must bring salvation to all living beings...\" Is there any fault in what I do?",
          TalkActionId = {
            [1] = "210013:Explain02_Start",
            [2] = "200002:Talk03_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136788"
        },
        [12014005] = {
