          ContentKR = "당연히 이상하지! 아무리 그래도 자기 몸부터 챙기고 나서 남을 생각해야 하는 거 아니야?",
          DialogueId = 12014005,
          FinalCamera = "-139.686951,3.986969,131.131836,0.000168,-21.198324,-6.583653,40.000011,130.4021,false,Manual,6.0",
          GUID = "1E1367B2",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "200002:n(210013)"
          },
          NextDialogue = 12014006,
          Scripts = "PlayAnimation{ActorId{210013},AnimationId{\"TilteHead_End\"},Duration{1}}\n",
          SpeakNpcId = 200002,
          Subtitle = "But how can you help others if you don't look after yourself first!?",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1201/120140/1E1367B2"
        },
        [12014006] = {
          Camera = "266.129486,-304.112732,99.563477,0.000088,1.401568,140.811783,35.000011,519.066956,false,Manual,6.0",
          ContentKR = "제겐 몸 안의 탁한 기운을 몰아내는 특별한 방법이 있어서 괜찮아요...",
          DialogueId = 12014006,
          FinalCamera = "250.848297,-322.864258,99.563477,0.000088,1.201567,138.411911,35.000011,523.788696,false,Manual,6.0",
          GUID = "1E1367DC",
