        [12014010] = {
          Camera = "-8.599365,-111.106323,114.814453,0.000091,8.002468,157.225708,40.000011,192.971207,false,Manual,8.0",
          ContentKR = "그럼 부소 몸부터 잘 챙기면 좋겠어.",
