            [2] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E13692C"
        },
        [12014015] = {
          Camera = "-160.908493,-160.138596,126.569336,0.000092,7.202004,94.83432,45.000023,134.189529,false,Manual,10.0",
          ContentKR = "...죄송해요, 아픈 기억을 떠올리게 했나 보네요.",
          DialogueId = 12014015,
          FinalCamera = "-169.812134,-160.684509,126.569336,0.000095,7.202011,90.234421,45.000023,134.189529,false,Manual,10.0",
          GUID = "1E136956",
          NextDialogue = 12014016,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I didn't mean to stir old grief.",
          TalkActionId = {
            [1] = "210013:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136956"
        },
        [12014016] = {
