        [12015523] = {
          Camera = "188.509262,31.106506,50.589233,0.000078,-30.155823,110.398247,40.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "걱정 마! 이제 나랑 내 시종이 언니 편이 되어줄게. 그럼 친구가 둘이나 생기는 거잖아!",
          DialogueId = 12015523,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "181.691696,60.230335,63.322021,0.000088,-1.155688,96.397728,40.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1460BE",
          NextDialogue = 12015524,
          Scripts = "PlayAnimation{delay{1.5},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Hey, you're not alone! Not anymore — you've got this Demon King and her Little Minion watching your back now!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1460BE"
        },
        [12015524] = {
          Camera = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          ContentKR = "두 사람 모두 고마워요.",
          DialogueId = 12015524,
          FacialId = {
            [1] = "100001:None",
            [2] = "210013:Smile01"
          },
          GUID = "1E1460E8",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12015525,
          SpeakNpcId = 210013,
          Subtitle = "Then I shall rely on you, my friends. Thank you.",
          TalkActionId = {
            [1] = "200002:Excited02_End",
            [2] = "210013:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E1460E8"
        },
        [12015525] = {
          Camera = "-171.576187,16.046459,219.450195,0.000053,-24.99765,-0.400124,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "옛날이야기를 나누러 일부러 이곳까지 찾아온 건 아닐 것 같소만?",
          DialogueId = 12015525,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "-237.973511,24.827023,258.312012,0.000038,-26.797733,2.000224,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E146112",
          LookAt = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          NextDialogue = 12015526,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Now, I suspect you didn't come all this way merely to reminisce with an old spectre.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E146112"
        },
        [12015526] = {
          ContentKR = "네... 저희는 고서에 나온 '망우초'라는 식물을 찾으러 왔어요. 혹시 어디에서 자라고 있는지 아시나요?",
          DialogueId = 12015526,
          GUID = "1E14613C",
          NextDialogue = 12015527,
          SpeakNpcId = 210013,
          Subtitle = "You're right. We seek a plant known in the old records as \"Wangyou.\" Do you know where it might still grow?",
          TalkActionId = {
            [1] = "210013:Shy03_Start",
            [2] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E14613C"
        },
        [12015527] = {
          Camera = "784.648315,1688.77478,793.957031,0.000106,-20.798943,-107.790878,30.000013,212.18367,false,DoNotOverride,11.418732",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "허허, 망우초라... 내 젊었을 적에는 그 풀이 온 산에 지천이었네만, 이제는 뒷산 폭포 근처에서나 겨우 드문드문 자라는 걸 볼 수 있다오.",
          DialogueId = 12015527,
          FinalCamera = "784.648315,1688.77478,793.957031,0.000117,-5.398848,-81.190453,30.000013,212.18367,false,DoNotOverride,11.418732",
          GUID = "1E146166",
          NextDialogue = 12015528,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Ah, Wangyou... In my younger days, it blanketed every hill. But now, you'll find only a few sparse clusters near the waterfall beyond the rear mountain.",
          TalkActionId = {
            [1] = "210013:Shy03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146166"
        },
        [12015528] = {
          Camera = "97.456741,233.233795,41.130371,0.000063,8.802215,-50.793129,35.000008,224.867065,false,Manual,6.960648",
          ContentKR = "뒷산 폭포라... 그렇군요. 알려 주셔서 감사해요.",
          DialogueId = 12015528,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "92.520905,229.20755,41.130371,0.000063,8.802215,-50.793156,35.000008,224.867065,false,Manual,6.960648",
          GUID = "1E146190",
          NextDialogue = 12015529,
          Scripts = [[
