LookAt{delay{0.5},LookAtDescription{"210013:n(100001)"}},
LookAt{delay{1.5},LookAtDescription{"100001:n(210013)"}},
LookAt{_delay{3.1},LookAtDescription{"210013:n(210040)"}},
}]],
          SpeakNpcId = 210013,
          Subtitle = "I see. Thank you for sharing your knowledge.",
          TalkActionId = {
            [1] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146190"
        },
        [12015529] = {
          Camera = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "참, 혹시 그쪽으로 갈 예정이라면, 내 부탁 하나만 들어주겠소?",
          DialogueId = 12015529,
          FinalCamera = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1461BA",
          NextDialogue = 12015530,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "One more thing — if you're heading that way, may I trouble you to watch for something on my behalf?",
          TalkActionId = {
            [1] = "210013:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1461BA"
        },
        [12015530] = {
          ContentKR = "말씀하세요.",
          DialogueId = 12015530,
          GUID = "1E1461E4",
          LookAt = {
            [1] = "100001:n(210040)"
          },
          NextDialogue = 12015531,
          SpeakNpcId = 100001,
          Subtitle = "Sure. What is it?",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E1461E4"
        },
        [12015531] = {
          Camera = "506.800385,633.872742,77.709961,0.000065,0.602477,-123.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그대들이 오기 얼마 전에, 이 우천에 낙진이 덮쳤다오. 그때 무유생 몇몇이 실종되었는데, 마지막으로 모습이 확인되었던 곳이 바로 폭포 근처였지.",
          DialogueId = 12015531,
          FinalCamera = "543.195251,689.077759,77.014893,0.000065,0.60247,-123.397171,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E14620E",
          NextDialogue = 12015532,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Not long before you arrived, the Gritblight reached the Spring of Yu. Some of the little ones vanished — last seen near the waterfall.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120155/1E14620E"
        },
        [12015532] = {
          Camera = "81.046371,94.984283,109.258301,0.000053,-23.95587,34.01368,45.000011,118.771225,false,Manual,8.928488",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "혹시 그 아이들이 곤경에 빠진 것을 발견하면, 부디 꼭 좀 도와주시오. 무유생들이 밤낮으로 눈물을 멈추지 못하고 있다오.",
          DialogueId = 12015532,
          FinalCamera = "81.046371,94.984283,109.258301,0.000052,-25.15588,33.813671,45.000011,118.771225,false,Manual,8.928488",
          GUID = "1E146238",
          NextDialogue = 12015533,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Should you come across any of them trapped... please lend your aid. They have been weeping for days on end.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146238"
        },
        [12015533] = {
          ContentKR = "기억해 둘게요.",
          DialogueId = 12015533,
          GUID = "1E146262",
          NextDialogue = 12015534,
          SpeakNpcId = 100001,
          Subtitle = "We'll keep an eye out.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E146262"
        },
        [12015534] = {
          Camera = "121.226036,125.787674,88.543091,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
          ContentKR = "허허, 어서들 가시오. 산 자의 시간은 더없이 소중한 것이니 말이야.",
          DialogueId = 12015534,
          FinalCamera = "146.449402,146.941391,76.819092,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
          GUID = "1E14628C",
          NextDialogue = 12015535,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Thank you. Then be on your way. The living mustn't squander their fleeting hours.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120155/1E14628C"
        },
        [12015535] = {
          Camera = "1428.752563,1073.151489,38.327271,0.000178,-0.197604,-141.396988,30.000002,1974.44458,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "백 년쯤 지나 다시 와서 못다 한 이야기를 나누어도 늦지 않을 거요. 이 늙은이는 얼마든 기다릴 수 있으니 말이오.",
          DialogueId = 12015535,
          FinalCamera = "1560.888916,1093.783447,38.735229,0.000178,-0.197604,-144.99707,30.000002,1974.44458,false,Manual,1.2",
          GUID = "1E1462B6",
          NextDialogue = 12015536,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "When your time in the mortal world is done, you can always return — I will be waiting still for a proper catch-up.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1462B6"
        },
        [12015536] = {
          Camera = "203.142548,172.754639,84.036987,0.000236,-41.194706,-124.995682,30.000013,127.563431,false,Manual,8.594169",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "...틀린 말은 아닌데, 왜 괜히 등골이 오싹해지는 느낌이지?!",
          DialogueId = 12015536,
          FacialId = {
