        [12015537] = {
          ContentKR = "시종, 우리 빨리 가자...!",
          DialogueId = 12015537,
          GUID = "1E14630A",
          SpeakNpcId = 200002,
          Subtitle = "Let's get going, Little Minion...!",
          TalkActionId = {
