        },
        [12015601] = {
          Camera = "77.056641,185.4375,189.325562,0.000108,-31.7983,-71.775475,35.000011,290.254242,false,Manual,6.747885",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "자줏빛 줄기, 둘씩 마주 보고 난 잎, 작고 하얀 꽃... 이 식물이 맞는 것 같아요.",
          DialogueId = 12015601,
          FinalCamera = "63.588379,226.34082,216.024658,0.000108,-31.798326,-71.775505,35.000011,290.254242,false,Manual,6.747885",
          GUID = "1E146D8A",
          NextDialogue = 12015602,
          Scripts = [[
SEQ{
LookAt{_delay{4.1},LookAtDescription{"210013:n(100001)"}},
TurnTo{TurnToDescription{"210013:n(100001)"}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Crimson stalks, paired leaves, tiny white blossoms... Yes. This is Wangyou.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146D8A"
        },
        [12015602] = {
          Camera = "1049.913574,-119.71582,311.329102,0.0001,-14.398373,162.820862,30.0,248.711517,false,DoNotOverride,6.747885",
          ContentKR = "{nickname} 씨, 스노우. 좀 도와줄 수 있어요? 이슬이 마르기 전에 망우초 열 포기를 캐야 하거든요.",
          DialogueId = 12015602,
          Duration = 1,
          FinalCamera = "1015.789062,-208.617188,311.329102,0.000098,-13.998349,157.021118,30.0,248.711517,false,DoNotOverride,6.747885",
          GUID = "1E146DB4",
          NextDialogue = 12015603,
          Scripts = [[
PARA{
PlayAnimation{_delay{4.1},ActorId{210013},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{1.1},ActorId{100001},AnimationId{"Shy02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = ", Snow — could you lend a hand? Before the dew vanishes, I need ten fresh sprigs of Wangyou.",
          TalkActionId = {
            [1] = "210013:Talk02_Start"
          },
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146DB4"
        },
        [12015603] = {
          Camera = "60.763,225.503906,204.802368,0.000088,-28.598343,-74.769676,30.0,117.073692,false,Manual,6.747885",
          ContentKR = "꽃이 활짝 피고 뿌리 색이 선명한 걸로 고르면 약효가 더 좋을 거예요.",
          DialogueId = 12015603,
          FinalCamera = "73.483093,228.381836,204.802368,0.000087,-28.798365,-81.168892,30.0,117.073692,false,Manual,6.747885",
          GUID = "1E146DDE",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          NextDialogue = 12015604,
          SpeakNpcId = 210013,
