        },
        [12015604] = {
          Camera = "315.013123,-16.664062,87.76709,0.000089,7.94519,113.863701,40.000011,248.711517,false,DoNotOverride,6.747885",
          ContentKR = "응! 우리한테 맡겨!",
          DialogueId = 12015604,
          FinalCamera = "307.165344,-20.133789,87.76709,0.000089,7.94519,113.863922,40.000011,248.711517,false,DoNotOverride,6.747885",
          GUID = "1E146E08",
          Scripts = [[
PARA{
LookAt{_delay{1.1},LookAtDescription{"100001:n(200002)"}},
LookAt{_delay{2.1},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{2.5},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "You got it!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146E08"
        },
        [12015701] = {
          ContentKR = "저기, 시종! 빨리 이리 와서 좀 봐!",
          DialogueId = 12015701,
          Duration = 3,
          GUID = "1E147DF2",
          SpeakNpcId = 200002,
          Subtitle = "Hey— Little Minion! Come over here a sec!",
          VoiceName = "voice/$Locale$/story/1201/120157/1E147DF2"
        },
        [12015801] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...이 스노우님이 뭘 잘못 들었나? 시종, 이쪽에서 이상한 소리 들리지 않아? 와서 확인 좀 해 봐봐.",
          DialogueId = 12015801,
          GUID = "1E148E5A",
          NextDialogue = 12015802,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "...Am I hearing things? Little Minion, come here and check — did a voice come from this way?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148E5A"
        },
        [12015802] = {
          ContentKR = "알았어.",
          DialogueId = 12015802,
          GUID = "1E148E84",
          NextDialogue = 12015803,
          SpeakNpcId = 100001,
          Subtitle = "Alright.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148E84"
        },
        [12015803] = {
          ContentKR = "누가... 나... 살... 누... 나...",
          DialogueId = 12015803,
          GUID = "1E148EAE",
          NextDialogue = 12015804,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Save me... save me...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148EAE"
        },
        [12015804] = {
          ContentKR = "누가 말하는 소리야. 지나가는 사람한테 도와달라고 하는 것 같아.",
          DialogueId = 12015804,
          GUID = "1E148ED8",
          NextDialogue = 12015805,
          SpeakNpcId = 100001,
          Subtitle = "There is a voice — someone calling for help.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148ED8"
        },
        [12015805] = {
          ContentKR = "'누나'...라고 외치는 건가? 저 사람도 가족을 찾는 건가?",
          DialogueId = 12015805,
          GUID = "1E148F02",
          NextDialogue = 12015806,
          SpeakNpcId = 200002,
          Subtitle = "Did she say... \"Baby\"? ...Is she calling out for someone she loves?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F02"
        },
        [12015806] = {
          ContentKR = "사라지면 안 돼... 나 아직...",
          DialogueId = 12015806,
          GUID = "1E148F2C",
          NextDialogue = 12015807,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Can't disappear... I still have to...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F2C"
        },
        [12015807] = {
          ContentKR = "...전에... 제발...",
          DialogueId = 12015807,
          GUID = "1E148F56",
          NextDialogue = 12015808,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Before it's too late... let me...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F56"
        },
        [12015808] = {
          ContentKR = "내 말이 맞지? 이 스노우님이 잘못 들은 게 아니었어! 이 마왕님은 아스포델 저 구석의 속삭임까지 다 들릴 정도로 귀가 엄청 밝다니까!",
          DialogueId = 12015808,
          GUID = "1E148F80",
          NextDialogue = 12015809,
          SpeakNpcId = 200002,
          Subtitle = "See? I knew I wasn't hearing things! Ha — never doubt this Demon King's ears. Sharp enough to catch whispers in every corner of The Asphodel!",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F80"
        },
        [12015809] = {
          ContentKR = "그래, 다음에 네 앞에서 말하기 좀 그런 일 있으면, 멀리 떨어져서 얘기해야겠다.",
          DialogueId = 12015809,
          GUID = "1E148FAA",
          NextDialogue = 12015810,
          SpeakNpcId = 100001,
          Subtitle = "Duly noted. Next time I've got a secret to keep, I'll make sure you're nowhere nearby.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FAA"
        },
        [12015810] = {
          ContentKR = "윽, 너무하잖아!!",
          DialogueId = 12015810,
          GUID = "1E148FD4",
          NextDialogue = 12015811,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Not cool, Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FD4"
        },
        [12015811] = {
          ContentKR = "...그래서, 이 목소리 주인은 어디 있고, 우린 또 어떻게 찾아야 하는 거야?",
          DialogueId = 12015811,
          GUID = "1E148FFE",
          SpeakNpcId = 200002,
          Subtitle = "Still... where's that voice coming from? And how do we even start looking for them?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FFE"
        },
        [12015901] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "시종, 방금 뭐였어?",
          DialogueId = 12015901,
          GUID = "1E149EC2",
          NextDialogue = 12015902,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, what was that noise?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149EC2"
        },
        [12015902] = {
          ContentKR = "시종, 시종? ...{nickname}?!",
          DialogueId = 12015902,
          GUID = "1E149EEC",
          NextDialogue = 12015903,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion...? Little Minion!  — what's wrong!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149EEC"
        },
        [12015903] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "왜, 왜 말을 안 해...",
          DialogueId = 12015903,
          GUID = "1E149F16",
          NextDialogue = 12015904,
          SpeakNpcId = 200002,
          Subtitle = "Say something...!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F16"
        },
        [12015904] = {
          ContentKR = "어떡해! 부, 부소 언니, 큰일 났어!",
          DialogueId = 12015904,
          GUID = "1E149F40",
          NextDialogue = 12015905,
          SpeakNpcId = 200002,
          Subtitle = "Oh no... oh no — Fushu! Fushu, something's really wrong—!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F40"
        },
        [12015905] = {
          ContentKR = "무슨 일이에요?",
          DialogueId = 12015905,
          GUID = "1E149F6A",
          NextDialogue = 12015906,
          SpeakNpcId = 210013,
          Subtitle = "What happened?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F6A"
        },
        [12015906] = {
          ContentKR = "우으... 아까 어디선가 말소리가 들리길래 시종이랑 같이 찾아보려고 했는데, 갑자기 빛이 번쩍하고 '스르륵' 소리가 나더니 시종이 이렇게 바보가 돼 버렸어!",
          DialogueId = 12015906,
          GUID = "1E149F94",
          NextDialogue = 12015907,
          SpeakNpcId = 200002,
          Subtitle = "Waaah... There was a voice, coming from somewhere we couldn't see, so we went to look... and then all of a sudden — there was this flash and a fwoosh, and my Little Minion just... froze up!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F94"
        },
        [12015907] = {
          ContentKR = "아무리 불러도 대답도 없고... 꼭 영혼이 빠져나간 것 같아!",
          DialogueId = 12015907,
          GUID = "1E149FBE",
          NextDialogue = 12015908,
          SpeakNpcId = 200002,
          Subtitle = "I called {性别:his|her} name many times, but {性别:he|she} just stood there like a statue — like {性别:his|her} soul's been snatched away!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149FBE"
        },
        [12015908] = {
          ContentKR = "스노우, 우선 진정해요. 조급해한다고 상황이 나아지지는 않아요. 안심해요, 제가 있잖아요.",
          DialogueId = 12015908,
          GUID = "1E149FE8",
          NextDialogue = 12015910,
          SpeakNpcId = 210013,
          Subtitle = "Take a breath, Snow. Panic will only cloud your thoughts. Don't worry, I'm here with you.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149FE8"
        },
        [12015910] = {
          ContentKR = "마지막으로 {nickname} 씨의 멀쩡한 모습을 본 곳이... 여기예요?",
          DialogueId = 12015910,
          GUID = "1E14A03C",
          NextDialogue = 12015912,
          SpeakNpcId = 210013,
          Subtitle = "So... the last place you saw  before {性别:he|she} froze — was right here?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A03C"
        },
        [12015912] = {
          ContentKR = "이게 뭐야? {nickname}, 위험한 건 아니지?!",
          DialogueId = 12015912,
          GUID = "1E14A090",
          NextDialogue = 12015913,
          SpeakNpcId = 200002,
          Subtitle = "What is that!? Is  going to be okay!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A090"
        },
        [12015913] = {
          ContentKR = "제 짐작이 맞다면, {nickname} 씨의 정신이 <H>과거의 틈</>에 삼켜진 것 같아요.",
          DialogueId = 12015913,
          GUID = "1E14A0BA",
          NextDialogue = 12015914,
          RelatedWikiId = {
            [1] = 304008
          },
          SpeakNpcId = 210013,
          Subtitle = "If I'm not mistaken, {性别:his|her} spirit has been swallowed by a place known as the Oblivion Rift.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A0BA"
        },
        [12015914] = {
          ContentKR = "과거의 틈...? 그게 뭔데? 말하는 뉘앙스를 보니까, 뭔가 엄청 안 좋은 거구나!",
          DialogueId = 12015914,
          GUID = "1E14A0E4",
          NextDialogue = 12015915,
          SpeakNpcId = 200002,
          Subtitle = "The Oblivion Rift...? That sounds awful! What is it?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A0E4"
        },
        [12015915] = {
          ContentKR = "우천은 사람들의 집착이 얽혀서 만들어진 저승이라고 할 수 있어요... 우천이 촉룡의 재앙에 영향을 받으면 '과거의 틈'이라는 게 생겨나요. 모든 것을 잊게 하고 소멸시키는, 빛 한 점 없는 곳이죠.",
          DialogueId = 12015915,
          GUID = "1E14A10E",
          NextDialogue = 12015916,
          SpeakNpcId = 210013,
          Subtitle = "The Spring of Yu is a realm woven from human yearning, and the Oblivion Rift is its shadow — born of Zhuyin's corruption. It is a lightless void where all memory is consumed and undone.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A10E"
        },
        [12015916] = {
          ContentKR = "잘못 발을 들인 사람은, 과거의 틈이 생긴 후 2시간 안에 돌아오지 못하면, 혼백이 영원히 그 안에 갇혀 돌아올 수 없게 돼요.",
          DialogueId = 12015916,
          GUID = "1E14A138",
          NextDialogue = 12015917,
          SpeakNpcId = 210013,
          Subtitle = "Anyone who falls in must find their way out within one hour of the Rift's birth. If they do not... their soul will be lost forever, with no path home.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A138"
        },
        [12015917] = {
          ContentKR = "그럼...",
          DialogueId = 12015917,
          GUID = "1E14A162",
          NextDialogue = 12015918,
          SpeakNpcId = 200002,
          Subtitle = "Then what do we do...!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A162"
        },
        [12015918] = {
          ContentKR = "너무 걱정하지 말아요. 제가 {nickname} 씨를 데리고 돌아올게요. 스노우는 여기서 기다려 주세요.",
          DialogueId = 12015918,
          GUID = "1E14A18C",
          NextDialogue = 12015919,
          SpeakNpcId = 210013,
          Subtitle = "Don't be afraid. I will go in and bring {性别:him|her} back. Stay here and wait for us.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A18C"
        },
        [12015919] = {
          ContentKR = "...나도 같이 갈 거야!",
          DialogueId = 12015919,
          GUID = "1E14A1B6",
          NextDialogue = 12015920,
          SpeakNpcId = 200002,
          Subtitle = "...I'm coming with you!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A1B6"
        },
        [12015920] = {
          ContentKR = "안 돼요. 과거의 틈은 아주 위험한 곳이라, 스노우까지 그 안에 빠지면 상황이 더욱 걷잡을 수 없게 돼요.",
          DialogueId = 12015920,
          GUID = "1E14A1E0",
          NextDialogue = 12015921,
          SpeakNpcId = 210013,
          Subtitle = "No, it's far too perilous. If you were to be lost as well... it would only make things worse.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A1E0"
        },
        [12015921] = {
          ContentKR = "그, 그치만, 난 여기서 아무것도 못 하고, 안에서 무슨 일이 일어나고 있는지도 모르잖아. 시종이 대체 어떻게 됐는지도 모르는 상태로 계속 여기서 기다리고만 있어야 한다니...",
          DialogueId = 12015921,
          GUID = "1E14A20A",
          NextDialogue = 12015922,
          SpeakNpcId = 200002,
          Subtitle = "But... but I don't want to just wait here doing nothing! Not knowing what's happening in there... or if my Little Minion is safe...",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A20A"
        },
        [12015922] = {
          ContentKR = "흑흑... 그런 건... 너무 괴로워...",
          DialogueId = 12015922,
          GUID = "1E14A234",
          NextDialogue = 12015923,
          SpeakNpcId = 200002,
          Subtitle = "I can't take it... Waaaah!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A234"
        },
        [12015923] = {
          ContentKR = "스노우, 자, 손을 줘요.",
          DialogueId = 12015923,
          GUID = "1E14A25E",
          NextDialogue = 12015924,
          SpeakNpcId = 210013,
          Subtitle = "Snow, come here. Give me your hand.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A25E"
        },
        [12015924] = {
          ContentKR = "어? 이건...",
          DialogueId = 12015924,
          GUID = "1E14A288",
          NextDialogue = 12015925,
          SpeakNpcId = 200002,
          Subtitle = "Huh? What is this?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A288"
        },
        [12015925] = {
          ContentKR = "언니가 그랬어요. 약이 쓸 땐 당과를 먹으면 달콤함이 느껴질 거라고요. 제 생각엔, 마음이 괴로울 때도 마찬가지일 거예요.",
          DialogueId = 12015925,
          GUID = "1E14A2B2",
          NextDialogue = 12015926,
          SpeakNpcId = 210013,
          Subtitle = "My sister once said, \"When potion is bitter, chase it with something sweet.\" I believe hearts work the same way.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A2B2"
        },
        [12015926] = {
          ContentKR = "울지 말아요, 네? 제가 꼭 {nickname} 씨를 무사히 데리고 돌아올게요. 약속해요.",
          DialogueId = 12015926,
          GUID = "1E14A2DC",
          NextDialogue = 12015927,
          SpeakNpcId = 210013,
          Subtitle = "So no more tears, alright? I'll bring {性别:him|her} back safe and sound. I promise.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A2DC"
        },
        [12015927] = {
          ContentKR = "그럼... 어서 가 봐! 내가 이 무슨 틈새인지 뭔지가 갑자기 닫히지 않게 잘 지켜보고 있을게!",
          DialogueId = 12015927,
          GUID = "1E14A306",
          NextDialogue = 12015928,
          SpeakNpcId = 200002,
          Subtitle = "Then... then go already! I'll keep an eye on this creepy rift — no way I'm letting it shut!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A306"
        },
        [12015928] = {
          ContentKR = "맨날 대단한 마왕님이라더니, 결국 자기 시종 하나도 못 지키고...",
          DialogueId = 12015928,
          GUID = "1E14A330",
          NextDialogue = 12015929,
          SpeakNpcId = 200002,
          Subtitle = "I go around telling everyone I'm the Demon King... and I can't even protect my own Little Minion...",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A330"
        },
        [12015929] = {
          ContentKR = "너 진짜 나빠! 스노우가 똑똑히 지켜볼 거니까, 사라지면 가만 안 둬!",
          DialogueId = 12015929,
          GUID = "1E14A35A",
          NextDialogue = 12015930,
          SpeakNpcId = 200002,
          Subtitle = "You evil rift thing — don't you dare close up! I'm watching you!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A35A"
        },
        [12015930] = {
          ContentKR = "바보 시종, 너 꼭 무사히 돌아와야 해! 안 그러면 카밀라한테 1년... 아니, 10년, 100년 동안 일 시킬 줄 알아!",
          DialogueId = 12015930,
          GUID = "1E14A384",
          SpeakNpcId = 200002,
          Subtitle = "And you — stupid Little Minion — you'd better come back in one piece! Or else I'll have you waiting tables for Camilla for a year — no, ten — no, a hundred years!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A384"
        },
        [12016001] = {
          ContentKR = "(여긴... 어디지...)",
          DialogueId = 12016001,
          Duration = 2,
          GUID = "1E14AF2A",
          NextDialogue = 12016002,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Where... am I?)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF2A"
        },
        [12016002] = {
          ContentKR = "(아무도 없고, 아무 소리도 들리지 않아. 온통 조용해서 내 심장 소리밖에 안 들려...)",
          DialogueId = 12016002,
          Duration = 3,
          GUID = "1E14AF54",
          NextDialogue = 12016003,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(No one's here. Not a sound. It's so still I can hear my own heartbeat...)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF54"
        },
        [12016003] = {
          ContentKR = "(마치... 하얀 모래가 쏟아져 내리던 그 시작점으로 돌아온 것처럼, 처음부터 아무 일도 일어나지 않은 것처럼 느껴져.)",
          DialogueId = 12016003,
          Duration = 3,
          GUID = "1E14AF7E",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(It's as if... I'm back where it all began. Where the white sand flows from the sky. As though nothing ever happened.)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF7E"
        },
        [12016101] = {
          ContentKR = "{nickname} 씨, 제 목소리 들려요?",
          DialogueId = 12016101,
          Duration = 3,
          GUID = "1E14BF92",
          NextDialogue = 12016102,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Can you hear me, ?",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BF92"
        },
        [12016102] = {
          ContentKR = "부소? 부소? 어디 있어?!",
          DialogueId = 12016102,
          Duration = 2,
          GUID = "1E14BFBC",
          NextDialogue = 12016103,
          SpeakNpcId = 100001,
          Subtitle = "Fushu? Is that you? Where are you!?",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BFBC"
        },
        [12016103] = {
          ContentKR = "제가 있는 곳은 거기랑 좀 떨어져 있어요. 하지만 여긴 특수한 공간이라 생각만으로도 서로 통할 수 있죠. 그래서 제가 당신을 보고 목소리를 전할 수 있는 거예요.",
          DialogueId = 12016103,
          Duration = 5,
          GUID = "1E14BFE6",
          NextDialogue = 12016104,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "There lies a distance between us in the mortal realm. Yet this place is not bound by such constraints. Here, thoughts connect — I can see you, and my voice may find you.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BFE6"
        },
        [12016104] = {
          ContentKR = "걱정 말아요, 이제 괜찮아요. 제가 안전한 곳으로 안내해 드릴게요.",
          DialogueId = 12016104,
          Duration = 4,
          GUID = "1E14C010",
          NextDialogue = 12016105,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do not fear. You are safe here. I shall guide you back to where you belong.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C010"
        },
        [12016105] = {
          ContentKR = "...응, 알겠어!",
          DialogueId = 12016105,
          Duration = 2,
          GUID = "1E14C03A",
          SpeakNpcId = 100001,
          Subtitle = "...Okay. I understand.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C03A"
        },
        [12016201] = {
          ContentKR = "저 등불꽃 보여요? 살아있는 사람들은 소원을 등불에 담아 깊은 강에 띄워 보내면서, 그 등불이 그리움을 망자의 땅으로 실어다 주길 바라곤 하죠.",
          DialogueId = 12016201,
          Duration = 4,
          GUID = "1E14CFFA",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do you see those lantern blossoms? The living send forth their prayers upon them, setting them adrift in deep, silent waters — hoping they might reach those who have departed.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14CFFA"
        },
        [12016202] = {
          ContentKR = "촛불의 불빛이 당신을 지켜 줄 거예요. 과거의 틈에 침식되지 않도록요.",
          DialogueId = 12016202,
          Duration = 3,
          GUID = "1E14D024",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Their gentle light shall shield you from the oblivion's creeping grasp.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D024"
        },
        [12016251] = {
          ContentKR = "부소, 나 여길 어떻게 나가야 해?",
          DialogueId = 12016251,
          Duration = 3,
          GUID = "1E14D026",
          NextDialogue = 12016303,
          SpeakNpcId = 100001,
          Subtitle = "How am I supposed to leave here, Fushu?",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D026"
        },
        [12016301] = {
          ContentKR = "옆에 있는 강을 조심해요. 저건 망각의 강인데, 그 물에 닿으면 존재가 점점 희미해져서 삶에 대한 의지를 잃게 될지도 몰라요.",
          DialogueId = 12016301,
          Duration = 3,
          GUID = "1E14E062",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Beware the river that lies close at hand. That is Lethe — the River of Forgetting. Should its waters touch you, your sense of self will begin to fade, and your will to live shall wane.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E062"
        },
        [12016302] = {
          ContentKR = "...하지만 사방이 강물이라 길이 없는데... 어떻게 하지?",
          DialogueId = 12016302,
          Duration = 3,
          GUID = "1E14E08C",
          SpeakNpcId = 100001,
          Subtitle = "...But there's water everywhere. There's no path forward. What do I do?",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E08C"
        },
        [12016303] = {
          ContentKR = "{nickname} 씨에게는, 어떻게든 이루고 싶은 간절한 소원이 있나요?",
          DialogueId = 12016303,
          Duration = 3,
          GUID = "1E14E0B6",
          NextDialogue = 12016401,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = ", do you bear a wish that you must see fulfilled, no matter the cost?",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E0B6"
        },
        [12016304] = {
          ContentKR = "그 소원이 바로 당신을 이승과 잇는 끈이에요. 앞에 보이는 풍령을 향해 마음속 소원을 되뇌어 보세요.",
          DialogueId = 12016304,
          Duration = 3,
          GUID = "1E14E0E0",
          NextDialogue = 12016305,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "That wish is your tether to this world. Face the Aeolian Chime that stands before you, and let that wish take shape upon your mind.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E0E0"
        },
        [12016305] = {
          ContentKR = "풍령이 바람을 불러와, 집착을 저 높은 곳으로 보내서, 당신을 다시 살아있는 이들의 세계로 돌려보내줄 거예요.",
          DialogueId = 12016305,
          Duration = 3,
          GUID = "1E14E10A",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "It shall call to the wind — carrying your wish to the heights, and guiding you back to the land of the living.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E10A"
        },
        [12016401] = {
          ContentKR = "(어떻게든... 꼭 이뤄야만 하는 일.)",
          DialogueId = 12016401,
          Duration = 2,
          GUID = "1E14F0CA",
          NextDialogue = 12016402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Something I must do no matter the cost...)",
          VoiceName = "voice/$Locale$/story/1201/120164/1E14F0CA"
        },
        [12016402] = {
          ContentKR = "(베레가 아직 날 기다리고 있어... 베레를 구해야 하니까, 여기서 멈출 수는 없어!)",
          DialogueId = 12016402,
          Duration = 3,
          GUID = "1E14F0F4",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Berry is still waiting for me... I have to bring her back. I can't stop here!)",
          VoiceName = "voice/$Locale$/story/1201/120164/1E14F0F4"
        },
        [12016501] = {
          ContentKR = "...! 등이 켜졌어. 예쁘다.",
          DialogueId = 12016501,
          Duration = 2,
          GUID = "1E150132",
          NextDialogue = 12016502,
          SpeakNpcId = 100001,
          Subtitle = "...! The lanterns lit up. How beautiful.",
          VoiceName = "voice/$Locale$/story/1201/120165/1E150132"
        },
        [12016502] = {
          ContentKR = "저 기원등의 불꽃이라면, 등불꽃을 피워서 새로운 길을 열어줄 수 있을 거예요.",
          DialogueId = 12016502,
          Duration = 3,
          GUID = "1E15015C",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The flames of the sky lanterns shall awaken the blossoms ahead, lighting the path for your return.",
          VoiceName = "voice/$Locale$/story/1201/120165/1E15015C"
        },
        [12016601] = {
          ContentKR = "{nickname}, 맞지?",
          DialogueId = 12016601,
          Duration = 2,
          GUID = "1E15119A",
          NextDialogue = 12016602,
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = ", is that you?",
          TalkActionId = {
            [1] = "210024:Explain01_Start"
          },
          TurnTo = {
            [1] = "210024:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E15119A"
        },
        [12016602] = {
          ContentKR = "...베레!",
          DialogueId = 12016602,
          Duration = 2,
          GUID = "1E1511C4",
          NextDialogue = 12016603,
          SpeakNpcId = 100001,
          Subtitle = "...Berry!",
          TalkActionId = {
            [1] = "210024:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E1511C4"
        },
        [12016603] = {
          ContentKR = "우린 꼭 다시 만날 수 있을 거야. 그때까지 몸 조심하고, 다치지 말고 지내.",
          DialogueId = 12016603,
          Duration = 3,
          GUID = "1E1511EE",
          NextDialogue = 12016604,
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = "We'll definitely meet again. Until then, take good care of yourself and stay safe.",
          TalkActionId = {
            [1] = "210024:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E1511EE"
        },
        [12016604] = {
          ContentKR = "이제 앞으로 나아가, 멈추지 마. 난, 여기서 지켜보고 있을게.",
          DialogueId = 12016604,
          Duration = 3,
          GUID = "1E151218",
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = "Keep going forward now. I'll always be watching over you.",
          TalkActionId = {
            [1] = "210024:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E151218"
        },
        [12016701] = {
          ContentKR = "그분이 전에 말했던 '가족'이군요.",
          DialogueId = 12016701,
          Duration = 2,
          GUID = "1E152202",
          NextDialogue = 12016702,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "She is the family you have sought so long to find, right?",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152202"
        },
        [12016702] = {
          ContentKR = "찬물을 끼얹는 것 같지만... 여기 있는 건 소원과 그리움이 뭉쳐서 만들어진 형상일 뿐, 진짜 사람은 아니에요.",
          DialogueId = 12016702,
          Duration = 3,
          GUID = "1E15222C",
          NextDialogue = 12016703,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Yet I must tell you this — what you beheld was but a wisp of longing, not her true form.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E15222C"
        },
        [12016703] = {
          ContentKR = "알고 있어.",
          DialogueId = 12016703,
          Duration = 2,
          GUID = "1E152256",
          NextDialogue = 12016704,
          SpeakNpcId = 100001,
          Subtitle = "I understand.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152256"
        },
        [12016704] = {
          ContentKR = "그렇다 해도, 여기서 그 아이를 볼 수 있고, 세상 어딘가에서 날 기다리고 있다고 믿을 수 있다면... 마음이 훨씬 놓여.",
          DialogueId = 12016704,
          Duration = 4,
          GUID = "1E152280",
          SpeakNpcId = 100001,
          Subtitle = "But even so... to see her here, to believe she is waiting for me somewhere in this world... it brings me solace. It gives me strength.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152280"
        },
        [12016801] = {
          ContentKR = "또 새로운 풍령이네요. {nickname}, 어떻게 해야 할지 알죠?",
          DialogueId = 12016801,
          Duration = 3,
          GUID = "1E15326A",
          NextDialogue = 12016802,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Another Aeolian Chime. You know what must be done, .",
          VoiceName = "voice/$Locale$/story/1201/120168/1E15326A"
        },
        [12016802] = {
          ContentKR = "(무사히 아이스레이크 시티로 돌아가야 해... 모두 날 기다리고 있으니, 여기서 멈출 수는 없어!)",
          DialogueId = 12016802,
          Duration = 3,
          GUID = "1E153294",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I must make it back to Icelake safely. Everyone's still waiting for me. I can't stop now!)",
          VoiceName = "voice/$Locale$/story/1201/120168/1E153294"
        }
      }
    end
  },
  {
    MinKey = 12016901,
    MaxKey = 12019305,
    Loader = function()
      return {
        [12016901] = {
          ContentKR = "오랜만이야, {nickname}.",
          DialogueId = 12016901,
          Duration = 2,
          GUID = "1E1542D2",
          NextDialogue = 12016902,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "It's been a long time, .",
          TalkActionId = {
            [1] = "210024:Explain02_Start"
          },
          TurnTo = {
            [1] = "210025:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E1542D2"
        },
        [12016902] = {
          ContentKR = "어디 갔다 온 거지... 내가 한 번도 들어본 적 없는, 낯설고 새로운 곳?",
          DialogueId = 12016902,
          Duration = 3,
          GUID = "1E1542FC",
          NextDialogue = 12016903,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "Have you gone somewhere new and different? A place that I've never heard of?",
          TalkActionId = {
            [1] = "210024:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E1542FC"
        },
        [12016903] = {
          ContentKR = "언젠가 아이스레이크 시티에 돌아오면 나한테 그 이야기 해줄 수 있을까?",
          DialogueId = 12016903,
          Duration = 3,
          GUID = "1E154326",
          NextDialogue = 12016904,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "Could you tell me about it when you come back to Icelake?",
          TalkActionId = {
            [1] = "210024:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E154326"
        },
        [12016904] = {
          ContentKR = "좀 사치스러운 소원일지도 모르지만... 가능하다면, 날 잊지 말아줘.",
          DialogueId = 12016904,
          GUID = "1E154350",
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "I know it's kind of way too much to ask, but... please don't forget about me.",
          VoiceName = "voice/$Locale$/story/1201/120169/1E154350"
        },
        [12017001] = {
          ContentKR = "시종, 왜 이렇게 느려, 빨리 따라와! 이 마왕님께선 아직 너랑 같이 이 세상을 정복하러 가야 한다고!",
          DialogueId = 12017001,
          Duration = 4,
          GUID = "1E15533A",
          NextDialogue = 12017002,
          SnapShot = "MEMORY",
          SpeakNpcId = 200002,
          SpeakNpcName = "UI_CMName_Name_BaiPhantom",
          Subtitle = "Hurry up, Little Minion! The Demon King still needs your help to conquer the world!",
          VoiceName = "voice/$Locale$/story/1201/120170/1E15533A"
        },
        [12017002] = {
          ContentKR = "도대체 어딜 갔다 온 거야, 찾을 수가 없던데. 피나가 네 이야기나 들으려고 기다리고 있었어.",
          DialogueId = 12017002,
          GUID = "1E155364",
          SnapShot = "MEMORY",
          SpeakNpcId = 100401,
          SpeakNpcName = "UI_CMName_Name_AotePhantom",
          Subtitle = "Where on earth have you gone? It's making it so hard to find you. Come back soon — Fina still wants to hear stories from you.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E155364"
        },
        [12017003] = {
          ContentKR = "밖에서 다리 부러지지 말고. 일 끝나면 바로 아스포델로 돌아와, 따뜻한 음료 준비해 뒀으니까. 식기 전에 마시라고.",
          DialogueId = 12017003,
          Duration = 3,
          GUID = "1E15538E",
          NextDialogue = 12017004,
          SnapShot = "MEMORY",
          SpeakNpcId = 200003,
          SpeakNpcName = "UI_CMName_Name_KamiPhantom",
          Subtitle = "Mind you don't go breaking a leg out there. I've saved you a hot drink, but it won't stay warm forever. Just head back to The Asphodel once you're done with your business.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E15538E"
        },
        [12017004] = {
          ContentKR = "돈 버는 것도 중요하지만, 살아 있어야 돈 쓸 수 있지. 목숨 걸고 돈 버는 건 바보짓이야.",
          DialogueId = 12017004,
          Duration = 3,
          GUID = "1E1553B8",
          SnapShot = "MEMORY",
          SpeakNpcId = 200003,
          Subtitle = "Earning your keep's one thing, but it's pointless if you don't have the time to enjoy it.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E1553B8"
        },
        [12017005] = {
          ContentKR = "당신은 인연을 맺은 사람도, 걱정해 주는 사람도 참 많네요... 참 보기 좋아요.",
          DialogueId = 12017005,
          Duration = 3,
          GUID = "1E1553E2",
          NextDialogue = 12017006,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "It seems there are many who care for you, who've formed bonds of rare and precious worth. This is nice.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E1553E2"
        },
        [12017006] = {
          ContentKR = "나가는 길은 바로 저 앞이에요. 망각의 강을 건너 그 앞의 나하교에 오르면, 그 다리가 당신을 저편으로 데려다줄 거예요.",
          DialogueId = 12017006,
          GUID = "1E15540C",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The way out lies just ahead. Cross the Lethe, then step onto the Bridge of Forgetfulness — it will carry you back to the living world.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E15540C"
        },
        [12017101] = {
          ContentKR = "...휴, 무사해서 다행이에요, {nickname} 씨.",
          DialogueId = 12017101,
          Duration = 3,
          GUID = "1E1563A2",
          NextDialogue = 12017102,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "...Phew.  is safe now.",
          VoiceName = "voice/$Locale$/story/1201/120171/1E1563A2"
        },
        [12017102] = {
          ContentKR = "과거의 틈과 이승의 연결이 점차 닫히고 있어요... 서둘러 나가야 해요.",
          DialogueId = 12017102,
          Duration = 3,
          GUID = "1E1563CC",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The link between the Oblivion Rift and this world is growing faint... I must hurry and leave.",
          VoiceName = "voice/$Locale$/story/1201/120171/1E1563CC"
        },
        [12017201] = {
          ContentKR = "야하하!",
          DialogueId = 12017201,
          GUID = "1E15740A",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ee-ya—",
          VoiceName = "voice/$Locale$/story/1201/120172/1E15740A"
        },
        [12017202] = {
          ContentKR = "여긴 어쩐 일이니...?",
          DialogueId = 12017202,
          GUID = "1E157434",
          NextDialogue = 12017203,
          SpeakNpcId = 210013,
          Subtitle = "Little one, what brings you here...?",
          VoiceName = "voice/$Locale$/story/1201/120172/1E157434"
        },
        [12017203] = {
          ContentKR = "야히, 야!",
          DialogueId = 12017203,
          GUID = "1E15745E",
          NextDialogue = 12017204,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120172/1E15745E"
        },
        [12017204] = {
          ContentKR = "...너무 오랜 시간 이곳의 기운에 물들어 있어서, 이젠 말하는 능력도 잃어버린 거니? 정말 안됐구나.",
          DialogueId = 12017204,
          GUID = "1E157488",
          NextDialogue = 12017205,
          SpeakNpcId = 210013,
          Subtitle = "...You've lingered in this realm too long, and have lost even the power of speech. How pitiful.",
          VoiceName = "voice/$Locale$/story/1201/120172/1E157488"
        },
        [12017205] = {
          ContentKR = "너도 안전한 곳으로 데려다줄게. 나를 잘 따라오렴.",
          DialogueId = 12017205,
          GUID = "1E1574B2",
          SpeakNpcId = 210013,
          Subtitle = "Stay close to me. I will guide you to safety as well.",
          VoiceName = "voice/$Locale$/story/1201/120172/1E1574B2"
        },
        [12017206] = {
          ContentKR = "야하!",
          DialogueId = 12017206,
          GUID = "1E1574DC",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120172/1E1574DC"
        },
        [12017301] = {
          ContentKR = "(내 평생의 소원은 오직 고영법으로 세상 사람들을 구하는 거야. 이 맹세만큼은 절대로 저버릴 수 없어.)",
          DialogueId = 12017301,
          Duration = 3,
          GUID = "1E158472",
          NextDialogue = 12017302,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(In this fleeting life, my sole resolve is to wield the Art of Ephemerality — to heal all who suffer. That resolve, I shall never forsake.)",
          VoiceName = "voice/$Locale$/story/1201/120173/1E158472"
        },
        [12017302] = {
          ContentKR = "촛불 색이... 좀 이상한데요.",
          DialogueId = 12017302,
          Duration = 2,
          GUID = "1E15849C",
          SpeakNpcId = 210013,
          Subtitle = "The colour of the flame... it's not as it should be.",
          VoiceName = "voice/$Locale$/story/1201/120173/1E15849C"
        },
        [12017401] = {
          ContentKR = "너무 아파요... 상처에서 고름이 흘러나와, 아파서 밤새 잠을 이룰 수가 없어요...",
          DialogueId = 12017401,
          Duration = 2,
          GUID = "1E1594DA",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "It hurts so much... My wounds are festering — I haven't known sleep in days...",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1594DA"
        },
        [12017402] = {
          ContentKR = "전... 이제 가망이 없는 거죠? 축유 어르신, 차라리 절 끝내주세요...",
          DialogueId = 12017402,
          Duration = 3,
          GUID = "1E159504",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "There's no hope left, is there? Lady Zhuyou... please, put me out of my misery...",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159504"
        },
        [12017403] = {
          ContentKR = "갓 태어난 우리 애는, 아직 엄마도 한번 불러보지 못했단 말이에요! 제발, 우리 애를 살려주세요, 살려주세요!",
          DialogueId = 12017403,
          Duration = 3,
          GUID = "1E15952E",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "My baby... she's just come into the world, and hasn't even called me \"Mama\" yet! Please, I beg you — save her. Save her!",
          VoiceName = "voice/$Locale$/story/1201/120174/1E15952E"
        },
        [12017404] = {
          ContentKR = "소문에 부씨 가문은 손만 대면 병이 낫는다면서요? 어서 고쳐 줘요. 혹시 힘을 쓰기 싫어서 그래요?",
          DialogueId = 12017404,
          Duration = 4,
          GUID = "1E159558",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "They say the House of Zhuyou can heal any affliction — so why won't you help us? Don't you care!?",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159558"
        },
        [12017405] = {
          ContentKR = "저건... 백 년 전의 큰 역병 때 모습이에요.",
          DialogueId = 12017405,
          Duration = 1,
          GUID = "1E159582",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12017406,
          SpeakNpcId = 210013,
          Subtitle = "This was... the plague that ravaged our lands a century ago.",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159582"
        },
        [12017406] = {
          ContentKR = "사방으로 진이 다 빠지게 뛰어다녔지만, 그저 환자들이 절망과 고통 속에서 죽어가는 걸 지켜볼 수밖에 없었어요.",
          DialogueId = 12017406,
          Duration = 3,
          GUID = "1E1595AC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "I ran from dawn to dusk, doing all I could... yet still, all I could do was watch them die, one by one — helpless in their agony.",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1595AC"
        },
        [12017407] = {
          ContentKR = "(이건... 촛불이 답을 주는 걸까? ...내 마음이 이미 흔들리고 있었다고...?)",
          DialogueId = 12017407,
          Duration = 2,
          GUID = "1E1595D6",
          NextDialogue = 12017501,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Such is the flame's response... So my heart had wavered, after all?)",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1595D6"
        },
        [12017501] = {
          ContentKR = "(내가 마음에 품고 있는 건, 병마에 시달리는 사람들뿐만이 아니었던 걸까?)",
          DialogueId = 12017501,
          Duration = 3,
          GUID = "1E15A542",
          NextDialogue = 12017502,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Is it only the pain of others I grieve... or is it something I've long kept hidden?)",
          VoiceName = "voice/$Locale$/story/1201/120175/1E15A542"
        },
        [12017502] = {
          ContentKR = "(하지만 내가 평생 배우고 실천한 건 고영법뿐인데. 마음을 다스리지 못한다면, 어떻게 이곳을 벗어날 수 있을까...)",
          DialogueId = 12017502,
          Duration = 4,
          GUID = "1E15A56C",
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Yet all I have known, all I have ever offered, is the Art of Ephemerality. If my heart wavers... how can I find a way back?)",
          VoiceName = "voice/$Locale$/story/1201/120175/1E15A56C"
        },
        [12017601] = {
          ContentKR = "...역시 예상대로네요.",
          DialogueId = 12017601,
          Duration = 1,
          GUID = "1E15B5AA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12017602,
          SpeakNpcId = 210013,
          Subtitle = "...As I feared.",
          VoiceName = "voice/$Locale$/story/1201/120176/1E15B5AA"
        },
        [12017602] = {
          ContentKR = "미안. 데리고 나가 주겠다고 했었는데, 아무래도 약속을 못 지킬 것 같구나.",
          DialogueId = 12017602,
          Duration = 2,
          GUID = "1E15B5D4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "Forgive me... I promised to lead you out. But now... it seems I must break that promise.",
          VoiceName = "voice/$Locale$/story/1201/120176/1E15B5D4"
        },
        [12017701] = {
          ContentKR = "야하, 야하, 야하하!",
          DialogueId = 12017701,
          Duration = 1,
          GUID = "1E15C612",
          NextDialogue = 12017702,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ya, ee-ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C612"
        },
        [12017702] = {
          ContentKR = "...! 너 자신을 태워 빛을 내겠다는 거니? 그러다간 영영 사라져 버릴 텐데...",
          DialogueId = 12017702,
          Duration = 3,
          GUID = "1E15C63C",
          NextDialogue = 12017703,
          SpeakNpcId = 210013,
          Subtitle = "...! You would burn yourself as fuel? If you continue, your form will fade into nothingness...",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C63C"
        },
        [12017703] = {
          ContentKR = "야하!",
          DialogueId = 12017703,
          Duration = 1,
          GUID = "1E15C666",
          NextDialogue = 12017704,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C666"
        },
        [12017704] = {
          ContentKR = "...알겠어. 힘껏 널 지켜줄게.",
          DialogueId = 12017704,
          Duration = 2,
          GUID = "1E15C690",
          SpeakNpcId = 210013,
          Subtitle = "...I understand. Then I shall shield you with all that I am.",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C690"
        },
        [12017801] = {
          ContentKR = "부소, 네가 사람들을 치료해 주다가 쓰러졌다는 얘길 듣고 한달음에 달려왔어... 이제 고영법은 쓰지 마.",
          DialogueId = 12017801,
          GUID = "1E15D67A",
          NextDialogue = 12017802,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Fushu, I heard you collapsed while treating the sick — I travelled far to see you... You must stop using the Art of Ephemerality.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D67A"
        },
        [12017802] = {
          ContentKR = "걱정해 줘서 고마워, 언니. 난 이제 괜찮으니까, 돌아가.",
          DialogueId = 12017802,
          GUID = "1E15D6A4",
          NextDialogue = 12017803,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Thank you for your concern. But I am well now, Sister. You should return.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6A4"
        },
        [12017803] = {
          ContentKR = "괜찮다고?! 그렇게 자기 몸을 아끼지 않다가, 기어이 목숨까지 잃어야 성에 차겠니?",
          DialogueId = 12017803,
          GUID = "1E15D6CE",
          NextDialogue = 12017804,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Well? You call this \"well\"? You're harming your own life, Fushu — can't you see that?",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6CE"
        },
        [12017804] = {
          ContentKR = "사람을 구하는 건 대풍구장이 우리 부씨 가문에 내린 사명이야. 사람들이 병으로 고통받는 걸 보고도 모른 척하라는 말이야?",
          DialogueId = 12017804,
          GUID = "1E15D6F8",
          NextDialogue = 12017805,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Saving lives is the mission the Nine Chapters gave to us. Should I stand idle as others suffer in agony?",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6F8"
        },
        [12017805] = {
          ContentKR = "언니가 처음에 <H>약초학</>인지 뭔지를 연구하겠다며 대대로 내려오는 고영법을 저버리지 않았다면, 내가 이 지경이 됐을까?",
          DialogueId = 12017805,
          GUID = "1E15D722",
          NextDialogue = 12017806,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Had you not forsaken our ancestral art to pursue pharmacology, I wouldn't have pushed myself this far!",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D722"
        },
        [12017806] = {
          ContentKR = "미안, 언니처럼 제 몸 아끼는 일, 난 못 해.",
          DialogueId = 12017806,
          GUID = "1E15D74C",
          NextDialogue = 12017901,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Forgive me, Sister... but I cannot bring myself to cherish my own life above others', as you do.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D74C"
        },
        [12017901] = {
          ContentKR = "부소, 너... 줄곧 날 그렇게 생각해 왔던 거구나.",
          DialogueId = 12017901,
          Duration = 2,
          GUID = "1E15E6E2",
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "...So this is how you see me, Fushu.",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E6E2"
        },
        [12017902] = {
          ContentKR = "(그런 말들은 내 본심이 아니었는데... 한번 입이 열리니, 모진 말들이 봇물 터지듯 쏟아져 나왔지.)",
          DialogueId = 12017902,
          Duration = 3,
          GUID = "1E15E70C",
          NextDialogue = 12017903,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Those words... they were never what I meant. But once I spoke, the bitterness surged forth like a flood I couldn't hold back.)",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E70C"
        },
        [12017903] = {
          ContentKR = "(결국, 언니를 어떻게 봐야 할지 몰라 도망치듯 자리를 떠나고 말았어. 그게 언니와의 마지막 대화가 될 줄도... 모른 채.)",
          DialogueId = 12017903,
          Duration = 3,
          GUID = "1E15E736",
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(In the end, I didn't know how to face her... so I left. That was the last time we ever spoke.)",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E736"
        },
        [12018001] = {
          Camera = "-361.291565,868.035156,176.938965,0.000062,-2.401447,-174.821503,35.0,506.121063,false,Manual,2.8",
          ContentKR = "부소... 네가 이 꽃다운 나이에 이렇게 세상을 떠나게 둘 순 없어...",
          DialogueId = 12018001,
          Duration = 3,
          GUID = "1E15F74A",
          NextDialogue = 12018002,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Fushu... You're still in the prime of your life. I will not stand by and watch you die.",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F74A"
        },
        [12018002] = {
          ContentKR = "널 살릴 약을 반드시 만들어낼 거야. 내 남은 생을 다 바쳐서라도... 그러니까, 기다려 주렴.",
          DialogueId = 12018002,
          Duration = 2,
          GUID = "1E15F774",
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "I will find a cure for you. Even if it costs me everything — my life, my years — I will not rest until I do. Wait for me.",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F774"
        },
        [12018003] = {
          ContentKR = "......",
          DialogueId = 12018003,
          GUID = "1E15F775",
          SpeakNpcId = 210013,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F775"
        },
        [12018004] = {DialogueId = 12018004, GUID = "1E15F776"},
        [12018101] = {
          ContentKR = "...언니.",
          DialogueId = 12018101,
          Duration = 2,
          GUID = "1E1607B2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12018102,
          SpeakNpcId = 210013,
          Subtitle = "...Sister...",
          VoiceName = "voice/$Locale$/story/1201/120181/1E1607B2"
        },
        [12018102] = {
          ContentKR = "(언니는 진심으로 날 대했지만, 나는 그 마음을 헤아리지 못했어.)",
          DialogueId = 12018102,
          Duration = 3,
          GUID = "1E1607DC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12018103,
          SpeakNpcId = 210013,
          Subtitle = "She gave her whole heart to me, and I was blind to it.",
          VoiceName = "voice/$Locale$/story/1201/120181/1E1607DC"
        },
        [12018103] = {
          ContentKR = "(언니를 한 번만 다시 만나고 싶어... \"미안해\" 그 한마디라도 전할 수 있게...)",
          DialogueId = 12018103,
          Duration = 2,
          GUID = "1E160806",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "All I want is to see her again. To say that \"I'm sorry.\"",
          VoiceName = "voice/$Locale$/story/1201/120181/1E160806"
        },
        [12018201] = {
          ContentKR = "야하! 야하하!",
          DialogueId = 12018201,
          Duration = 1,
          GUID = "1E16181A",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ee! Ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16181A"
        },
        [12018202] = {
          ContentKR = "부소! 난 부소가...",
          DialogueId = 12018202,
          GUID = "1E161844",
          NextDialogue = 12018203,
          SpeakNpcId = 100001,
          Subtitle = "Fushu! I thought...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161844"
        },
        [12018203] = {
          ContentKR = "죄송해요, 걱정을 끼쳤네요.",
          DialogueId = 12018203,
          GUID = "1E16186E",
          NextDialogue = 12018204,
          SpeakNpcId = 210013,
          Subtitle = "I am well. Forgive me for worrying you.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16186E"
        },
        [12018204] = {
          ContentKR = "이름 모를 이 무유생 덕분에 과거의 틈에서 길을 잃지 않았어요. 남을 돕는 게 자신을 돕는 거라더니, 옛말 틀린 거 하나 없네요...",
          DialogueId = 12018204,
          GUID = "1E161898",
          NextDialogue = 12018205,
          SpeakNpcId = 210013,
          Subtitle = "Thanks to this nameless little one, I did not lose myself in the Oblivion Rift. As the old saying goes: \"By guiding others, we find our own path as well.\" Once again, these words have proven true.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161898"
        },
        [12018205] = {
          ContentKR = "야하, 야하하, 야하!",
          DialogueId = 12018205,
          GUID = "1E1618C2",
          NextDialogue = 12018206,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee, ee-ya-ee, ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1618C2"
        },
        [12018206] = {
          ContentKR = "정말 잘 됐어. 다시 만날 수 있어서 정말 마음이 놓여.",
          DialogueId = 12018206,
          GUID = "1E1618EC",
          NextDialogue = 12018207,
          SpeakNpcId = 100001,
          Subtitle = "I'm glad you're safe. That's a big relief.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1618EC"
        },
        [12018207] = {
          ContentKR = "아직 위험에서 완전히 벗어난 건 아니에요. 가장 위험한 곳은 빠져나왔지만, 아직 안심할 순 없어요. 저를 따라 어서 이곳을 떠나 원래 세계로 돌아가요.",
          DialogueId = 12018207,
          GUID = "1E161916",
          NextDialogue = 12018208,
          SpeakNpcId = 210013,
          Subtitle = "We are not yet free of peril. Though we have emerged from the deepest shadow, we must not let caution slip. Come — let us return to the world of the living.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161916"
        },
        [12018208] = {
          ContentKR = "응, 알겠어!",
          DialogueId = 12018208,
          GUID = "1E161940",
          NextDialogue = 12018209,
          SpeakNpcId = 100001,
          Subtitle = "Right. I'm ready.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161940"
        },
        [12018209] = {
          ContentKR = "우선 이 빛나는 옥을 따라 앞으로 나아가요. 살길을 안내해 줄 거예요.",
          DialogueId = 12018209,
          GUID = "1E16196A",
          SpeakNpcId = 210013,
          Subtitle = "Follow the Luminous Jades. They shall illuminate the path ahead.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16196A"
        },
        [12018210] = {
          ContentKR = "부소, 아까 망각의 강에서 뭘 봤어?",
          DialogueId = 12018210,
          GUID = "1E161994",
          NextDialogue = 12018211,
          SpeakNpcId = 100001,
          Subtitle = "Fushu, what did you see in the River of Forgetting?",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161994"
        },
        [12018211] = {
          ContentKR = "그저 지나간 사람들과 일들뿐이었어요... 모두 시간과 함께 사라졌죠.",
          DialogueId = 12018211,
          GUID = "1E1619BE",
          NextDialogue = 12018212,
          SpeakNpcId = 210013,
          Subtitle = "Just echoes of the past... people and moments long since gone.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1619BE"
        },
        [12018212] = {
          ContentKR = "그다지 즐거운 기억은 아닌 것 같네...",
          DialogueId = 12018212,
          GUID = "1E1619E8",
          NextDialogue = 12018213,
          SpeakNpcId = 100001,
          Subtitle = "Doesn't sound like they were happy memories...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1619E8"
        },
        [12018213] = {
          ContentKR = "살려줘!",
          DialogueId = 12018213,
          GUID = "1E161A12",
          NextDialogue = 12018214,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Help—!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A12"
        },
        [12018214] = {
          ContentKR = "야히, 야!",
          DialogueId = 12018214,
          GUID = "1E161A3C",
          NextDialogue = 12018215,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A3C"
        },
        [12018215] = {
          ContentKR = "저쪽에서 도와달라는 소리가 들리는 것 같아, 어서 가 보자!",
          DialogueId = 12018215,
          GUID = "1E161A66",
          SpeakNpcId = 100001,
          Subtitle = "Someone's calling for help — let's move!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A66"
        },
        [12018216] = {
          ContentKR = "고마워, 착한 사람!",
          DialogueId = 12018216,
          GUID = "1E161A90",
          NextDialogue = 12018217,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Thank you, kind soul!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A90"
        },
        [12018217] = {
          ContentKR = "아직... 더 많은... 동료들이... 흩어져 있어.",
          DialogueId = 12018217,
          GUID = "1E161ABA",
          NextDialogue = 12018218,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Others... more of us, still trapped.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161ABA"
        },
        [12018218] = {
          ContentKR = "여긴... 안 좋아... 어서 도망쳐야 해. 여길 벗어나려면... 모두의 힘이... 필요해!",
          DialogueId = 12018218,
          GUID = "1E161AE4",
          NextDialogue = 12018219,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "This place... feels wrong. Must leave. Need everyone's strength, to escape!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161AE4"
        },
        [12018219] = {
          ContentKR = "여기에 더 많은 무유생들이 갇혀 있다는 거야? 알겠어, 기억해 둘게.",
          DialogueId = 12018219,
          GUID = "1E161B0E",
          NextDialogue = 12018220,
          SpeakNpcId = 100001,
          Subtitle = "You mean there are still more of you trapped here? Got it. I'll keep an eye out.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B0E"
        },
        [12018220] = {
          ContentKR = "고마워, 고마워! 힘을... 빌려줄게!",
          DialogueId = 12018220,
          GUID = "1E161B38",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Thank you, thank you! My strength... take it!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B38"
        },
        [12018221] = {
          ContentKR = "어두운 돌이여, 힘을! 빛을 발하라!",
          DialogueId = 12018221,
          GUID = "1E161B62",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Dim stones... with strength, and they glow!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B62"
        },
        [12018222] = {
          ContentKR = "앞길이 석문에 막혔어...",
          DialogueId = 12018222,
          GUID = "1E161B8C",
          NextDialogue = 12018223,
          SpeakNpcId = 100001,
          Subtitle = "The road ahead is blocked by a stone gate..."
        },
        [12018223] = {
          ContentKR = "근처를 한번 살펴봐요. 혹시 뭔가 실마리가 있을지도 몰라요.",
          DialogueId = 12018223,
          GUID = "1E161BB6",
          SpeakNpcId = 210013,
          Subtitle = "Let us take a closer look around. There might be some hidden mechanism or clue.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161BB6"
        },
        [12018224] = {
          ContentKR = "어두운 돌들이여, 동시에! 빛을 발하라!",
          DialogueId = 12018224,
          GUID = "1E161BE0",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Dim stones... light up, all at once!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161BE0"
        },
        [12018225] = {
          ContentKR = "와아...! 축유 대인이다, 그리고 낯선 사람들도 있어!",
          DialogueId = 12018225,
          GUID = "1E161C0A",
          NextDialogue = 12018226,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Whoa...! It's Lady Zhuyou! And... another human!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C0A"
        },
        [12018226] = {
          ContentKR = "우천으로 돌아가는 출구를 보니까, 너무너무 멀어. 왠지 기운이 빠져서 더는 못 걷겠어...",
          DialogueId = 12018226,
          GUID = "1E161C34",
          NextDialogue = 12018227,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "The exit to the Spring of Yu looks so, so far away... I'm so tired... I don't think I can keep going...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C34"
        },
        [12018227] = {
          ContentKR = "차라리 여기서 한숨 푹 자고 모든 걸 잊은 채, 이대로 사라져도 상관없지 않을까...",
          DialogueId = 12018227,
          GUID = "1E161C5E",
          NextDialogue = 12018228,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "I just want to curl up here, forget everything... and let myself fade away...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C5E"
        },
        [12018228] = {
          ContentKR = "하지만, 동료가 왔으니까, 다시 힘내서 앞으로 나아가야지!",
          DialogueId = 12018228,
          GUID = "1E161C88",
          NextDialogue = 12018229,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "But now that our friends are here, we can't just give up. Let's keep going!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C88"
        },
        [12018229] = {
          ContentKR = "망각의 강에서 오랫동안 헤매느라, 영혼이 좀 무겁게 느껴지지 않아? 내가 너희 짐을 덜어줄게. 몸이 제비처럼 가벼워질 거야!",
          DialogueId = 12018229,
          GUID = "1E161CB2",
          NextDialogue = 12018230,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "You've walked the River of Forgetting for so long... Are your souls feeling heavy? Let me lighten them — make you as swift as the wind!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161CB2"
        },
        [12018230] = {
          ContentKR = "그럼, 나는 멀리 있는 장애물을 치워서, 너희 움직임을 한결 수월하게 해 줄게!",
          DialogueId = 12018230,
          GUID = "1E161CDC",
          NextDialogue = 12018231,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Then let me clear the path ahead — no more obstacles in your way!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161CDC"
        },
        [12018231] = {
          ContentKR = "야하, 야하하! 이제 문제없어, 어서 출발하자!",
          DialogueId = 12018231,
          GUID = "1E161D06",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_WuyoushengA&B",
          Subtitle = "Ee-ya! Now we're all set — let's go!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D06"
        },
        [12018232] = {
          ContentKR = "야하하, 야하!",
          DialogueId = 12018232,
          GUID = "1E161D30",
          NextDialogue = 12018233,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Ee-ee, ya!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D30"
        },
        [12018233] = {
          ContentKR = "나쁜 꽃이 동료를 가둬버렸어, 어서 도와줘!",
          DialogueId = 12018233,
          GUID = "1E161D5A",
          NextDialogue = 12018234,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "The mean flowers have trapped my friends! Please, help them!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D5A"
        },
        [12018234] = {
          ContentKR = "고서에서 이런 기이한 꽃을 본 적이 있어요. 꽃잎이 닫혀 있을 때는 어떤 공격도 통하지 않아서, 꽃이 활짝 피어날 때를 기다릴 수밖에 없어요.",
          DialogueId = 12018234,
          GUID = "1E161D84",
          SpeakNpcId = 210013,
          Subtitle = "I have seen this kind of flower in the old records. When its petals are shut, no blade can cut it. We must wait for it to bloom.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D84"
        },
        [12018235] = {
          ContentKR = "꽃술이 밖으로 드러났어요, 바로 지금이에요!",
          DialogueId = 12018235,
          GUID = "1E161DAE",
          SpeakNpcId = 210013,
          Subtitle = "The core is exposed — strike now!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161DAE"
        },
        [12018236] = {
          ContentKR = "축유 대인, 그리고 처음 보는 백발의 용사님, 고마워!",
          DialogueId = 12018236,
          GUID = "1E161DD8",
          NextDialogue = 12018237,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Lady Zhuyou! And the white-haired stranger — thank you both!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161DD8"
        },
        [12018237] = {
          ContentKR = "나도 너희들한테 힘을 보태줄게! 내 쇠망치는 땅도 쿵쿵 울리게 할 수 있다고!",
          DialogueId = 12018237,
          GUID = "1E161E02",
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Let me lend a hand too! My iron headbutt can even crack the earth!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E02"
        },
        [12018238] = {
          ContentKR = "마지막 동료다, 마지막 동료!",
          DialogueId = 12018238,
          GUID = "1E161E2C",
          NextDialogue = 12018239,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengA",
          Subtitle = "The last ones! Friends still trapped!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E2C"
        },
        [12018239] = {
          ContentKR = "아까와 같은 기이한 꽃이네요. {nickname}, 꽃이 활짝 피었을 때를 노려서, 꽃술과 가지까지 한 번에 날려 버리세요.",
          DialogueId = 12018239,
          GUID = "1E161E56",
          SpeakNpcId = 210013,
          Subtitle = "It is the same kind of flower as before. , wait for it to bloom fully — then strike the core and all the vines in one stroke.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E56"
        },
        [12018240] = {
          ContentKR = "이 늙은이, 평생 무예를 갈고닦고도 하마터면 이곳에서 세상과 하직할 뻔했구려. 부끄럽고 또 부끄럽소이다...",
          DialogueId = 12018240,
          GUID = "1E161E80",
          NextDialogue = 12018241,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_CMName_Name_MatureWuyou",
          Subtitle = "With all my years of martial skill, I nearly met my end here... How shameful...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E80"
        },
        [12018241] = {
          ContentKR = "이로써 동료들이 모두 모였어! 한 명도 빠짐없이 말이야!",
          DialogueId = 12018241,
          GUID = "1E161EAA",
          NextDialogue = 12018242,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengA",
          Subtitle = "Now we're all here — no one left behind, not a single one!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161EAA"
        },
        [12018242] = {
          ContentKR = "앞에는 거대한 꽃 요괴가 이승으로 가는 길목을 떡하니 가로막고 있소이다. 이 늙은이가 자네들과 함께 가 요괴를 물리치고, 모든 것을 제자리로 돌려놓겠소!",
          DialogueId = 12018242,
          GUID = "1E161ED4",
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_CMName_Name_MatureWuyou",
          Subtitle = "The final path is blocked by a monstrous Filthoid flower. Let me stand with you. Together, we shall cut it down and restore this place!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161ED4"
        },
        [12018243] = {
          ContentKR = "{nickname}, 망각의 강이 곧 무너져 내릴 거예요! 어서 이 싸움을 끝내야 해요!",
          DialogueId = 12018243,
          GUID = "1E161EFE",
          Subtitle = ", the River of Forgetting is about to collapse! We must end this now!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161EFE"
        },
        [12018244] = {
          ContentKR = "지금이에요, 손을 주세요.",
          DialogueId = 12018244,
          GUID = "1E161F28",
          Subtitle = "Now — take my hand.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161F28"
        },
        [12018300] = {
          ContentKR = "목숨을 구해 줘서 고마워. 나중에 꼭 보답할게. 그럼 우리 먼저 갈게!",
          DialogueId = 12018300,
          GUID = "1E162858",
          NextDialogue = 12018301,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_Wuyoushengmen",
          Subtitle = "Thank you, both of you! We'll never forget this kindness. Goodbye for now!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162858"
        },
        [12018301] = {
          ContentKR = "...훌쩍 ...드디어 돌아왔구나, 부소 언니, {nickname}! 나 진짜 걱정돼 죽는 줄 알았다고...",
          DialogueId = 12018301,
          GUID = "1E162882",
          NextDialogue = 12018302,
          SpeakNpcId = 200002,
          Subtitle = "Waaah... Fushu! ! You're finally back! I was worried sick...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162882"
        },
        [12018302] = {
          ContentKR = "조금만 늦었어도... 에이, 퉤퉤퉤! 나쁜 말은 입 밖에 안 내면 괜찮아!",
          DialogueId = 12018302,
          GUID = "1E1628AC",
          NextDialogue = 12018303,
          SpeakNpcId = 200002,
          Subtitle = "I thought you were... uh-uh! If I don't say it out loud, those bad things will never happen to you!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1628AC"
        },
        [12018303] = {
          ContentKR = "부소, 위험을 무릅쓰고 날 데리고 나와줘서 고마워.",
          DialogueId = 12018303,
          GUID = "1E1628D6",
          NextDialogue = 12018304,
          SpeakNpcId = 100001,
          Subtitle = "Fushu, thank you for risking your own life to bring me back.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1628D6"
        },
        [12018304] = {
          ContentKR = "제가 마땅히 해야 할 일인걸요.",
          DialogueId = 12018304,
          GUID = "1E162900",
          NextDialogue = 12018305,
          SpeakNpcId = 210013,
          Subtitle = "It was what I had to do.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162900"
        },
        [12018305] = {
          ContentKR = "괜찮아? 안색이 안 좋아 보이는데...",
          DialogueId = 12018305,
          GUID = "1E16292A",
          NextDialogue = 12018306,
          SpeakNpcId = 100001,
          Subtitle = "Are you okay? You look pale...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E16292A"
        },
        [12018306] = {
          ContentKR = "괜찮아요. 다만 마음이 좀 복잡해서, 조용히 생각을 정리할 시간이 필요해요.",
          DialogueId = 12018306,
          GUID = "1E162954",
          NextDialogue = 12018307,
          SpeakNpcId = 210013,
          Subtitle = "My body is unharmed. It's only my thoughts — still tangled and unclear. I need a moment to gather them.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162954"
        },
        [12018307] = {
          ContentKR = "응... 혹시 무슨 고민이 있어서 누군가한테 털어놓고 싶다면, 난 언제든 괜찮아.",
          DialogueId = 12018307,
          GUID = "1E16297E",
          NextDialogue = 12018308,
          SpeakNpcId = 100001,
          Subtitle = "Alright... But if you ever need someone to talk to — I'm always here for you.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E16297E"
        },
        [12018308] = {
          ContentKR = "물론이죠. 이런 일을 겪었으니, 이제 두 분은 제게 세상에 둘도 없는 벗이나 마찬가지인걸요.",
          DialogueId = 12018308,
          GUID = "1E1629A8",
          NextDialogue = 12018309,
          SpeakNpcId = 210013,
          Subtitle = "Sure. After all we have endured together... you and Snow are the only companions I hold dear in this world.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1629A8"
        },
        [12018309] = {
          ContentKR = "훌쩍, 부소...",
          DialogueId = 12018309,
          GUID = "1E1629D2",
          NextDialogue = 12018310,
          SpeakNpcId = 200002,
          Subtitle = "Aww, Fushu...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1629D2"
        },
        [12018310] = {
          ContentKR = "자. 비록 과정에 우여곡절이 좀 있었지만, 필요한 약초는 다 구했어요. 이슬이 마르기 전에 어서 가지고 돌아가 약으로 만들어야죠.",
          DialogueId = 12018310,
          GUID = "1E1629FC",
          NextDialogue = 12018311,
          SpeakNpcId = 210013,
          Subtitle = "Well then. Though it was a harrowing journey, we have managed to gather the herbs we needed. I must see them safely home, so I can begin refining them before the dew fades.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1629FC"
        },
        [12018311] = {
          ContentKR = "야하!",
          DialogueId = 12018311,
          GUID = "1E162A26",
          NextDialogue = 12018312,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162A26"
        },
        [12018312] = {
          ContentKR = "와앗, 넌 또 어디서 갑자기 튀어나온 거야! 깜짝 놀랐네!",
          DialogueId = 12018312,
          GUID = "1E162A50",
          NextDialogue = 12018313,
          SpeakNpcId = 200002,
          Subtitle = "Ahh! Where did you pop out from!? You nearly gave me a heart attack!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162A50"
        },
        [12018313] = {
          ContentKR = "너는 다른 아이들과 함께 떠나지 않았네...",
          DialogueId = 12018313,
          GUID = "1E162A7A",
          NextDialogue = 12018314,
          SpeakNpcId = 210013,
          Subtitle = "You did not depart with the others...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162A7A"
        },
        [12018314] = {
          ContentKR = "과거의 틈 깊은 곳에서 우연히 이 아이를 만나서, 데리고 나왔어요. 이것도 뜻밖의 좋은 인연이겠죠.",
          DialogueId = 12018314,
          GUID = "1E162AA4",
          NextDialogue = 12018315,
          SpeakNpcId = 210013,
          Subtitle = "I came across this little one deep within the Oblivion Rift and brought it back with me. A chance encounter... or perhaps that, too, is fate.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162AA4"
        },
        [12018315] = {
          ContentKR = "야하! 야하하!",
          DialogueId = 12018315,
          GUID = "1E162ACE",
          NextDialogue = 12018316,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ee! Ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162ACE"
        },
        [12018316] = {
          ContentKR = "유난히 부소를 잘 따르는 것 같네.",
          DialogueId = 12018316,
          GUID = "1E162AF8",
          NextDialogue = 12018317,
          SpeakNpcId = 100001,
          Subtitle = "It seems really attached to you.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162AF8"
        },
        [12018317] = {
          ContentKR = "좀 곤란하네요... 이제부터 집중해서 환자를 치료해야 해서, 방해를 받으면 안 되거든요.",
          DialogueId = 12018317,
          GUID = "1E162B22",
          NextDialogue = 12018318,
          SpeakNpcId = 210013,
          Subtitle = "That may be a problem... I will need complete focus and peace to tend to the patient.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162B22"
        },
        [12018318] = {
          ContentKR = "{nickname} 씨, 잠시 이 아이를 좀 맡아줄 수 있어요?",
          DialogueId = 12018318,
          GUID = "1E162B4C",
          NextDialogue = 12018319,
          SpeakNpcId = 210013,
          Subtitle = ", might I trouble you to watch over it for a while?",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162B4C"
        },
        [12018319] = {
          ContentKR = "쫄병의 쫄병이라... 그럼 쫄병 2호잖아!",
          DialogueId = 12018319,
          GUID = "1E162B76",
          NextDialogue = 12018320,
          SpeakNpcId = 200002,
          Subtitle = "So now my Little Minion has a little minion of their own? Guess that makes you Minion #2!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162B76"
        },
        [12018320] = {
          ContentKR = "야하하! 야하!",
          DialogueId = 12018320,
          GUID = "1E162BA0",
          NextDialogue = 12018321,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ya-ee! Ee-ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162BA0"
        },
        [12018321] = {
          ContentKR = "썩 내키지 않는 눈치인데.",
          DialogueId = 12018321,
          GUID = "1E162BCA",
          NextDialogue = 12018322,
          SpeakNpcId = 100001,
          Subtitle = "It doesn't look happy with that arrangement.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162BCA"
        },
        [12018322] = {
          ContentKR = "...미안, 네 생각을 너무 가볍게 여겼구나. 이왕 우리 인연이 닿았으니, 앞으로는 날 따라다니렴. 함부로 널 홀로 두진 않을게, 괜찮겠니?",
          DialogueId = 12018322,
          GUID = "1E162BF4",
          NextDialogue = 12018323,
          SpeakNpcId = 210013,
          Subtitle = "...My apologies. That was thoughtless of me. Since fate has brought us together, stay with me. I promise I won't turn you away. Will that suffice?",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162BF4"
        },
        [12018323] = {
          ContentKR = "야하!",
          DialogueId = 12018323,
          GUID = "1E162C1E",
          NextDialogue = 12018324,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162C1E"
        },
        [12018324] = {
          ContentKR = "{nickname}, 무유생 장로님께도 돌아가서 보고 좀 부탁드릴게요. 전 환자분 상태가 좀 나아지면, 그때 다시 두 사람을 만나러 갈게요.",
          DialogueId = 12018324,
          GUID = "1E162C48",
          NextDialogue = 12018325,
          SpeakNpcId = 210013,
          Subtitle = ", could I trouble you to report to Elder Wishen? Once the patient is resting more easily, I will meet with you again.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162C48"
        },
        [12018325] = {
          ContentKR = "좋아, 약속한 거야!",
          DialogueId = 12018325,
          GUID = "1E162C72",
          SpeakNpcId = 100001,
          Subtitle = "It's a promise!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162C72"
        },
        [12018401] = {
          Camera = "-82.743599,-22.173996,191.510315,0.000107,-18.000362,104.812141,25.000002,269.56311,false,Manual,6.0",
          ContentKR = "왔나? 출발하지.",
          DialogueId = 12018401,
          FacialId = {
            [1] = "210012:Smile01"
          },
          FinalCamera = "-85.275848,-12.593918,188.29126,0.000105,-18.000381,104.811234,25.000002,269.806946,false,Manual,6.0",
          GUID = "1E1638EA",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12018402,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210012,
          Subtitle = "Ah, you've arrived, young friend. Come — let us not keep the day waiting.",
          TalkActionId = {
            [1] = "210012:Talk03_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120184/1E1638EA"
        },
        [12018402] = {
          Camera = "31.293282,90.810593,118.199219,0.000119,3.198878,148.801849,35.000008,243.817368,false,Manual,6.0",
          ContentKR = "출발? 어디로요? 저한테 먼저 설명해주셔야 하지 않을까요?",
          DialogueId = 12018402,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E163914",
          NextDialogue = 12018403,
          SpeakNpcId = 100001,
          Subtitle = "We're leaving? Where are we going? Don't you think you owe me some kind of explanation?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163914"
        },
        [12018403] = {
          Camera = "17.345215,243.589844,108.354248,0.000138,7.597834,-130.80278,35.000008,255.516861,false,Manual,6.0",
          ContentKR = "...설명?",
          DialogueId = 12018403,
          FacialId = {
            [1] = "210012:Think01"
          },
          FinalCamera = "17.345215,243.589844,108.354248,0.000137,10.997827,-130.802673,35.000008,255.516861,false,Manual,6.0",
          GUID = "1E16393E",
          NextDialogue = 12018404,
          SpeakNpcId = 210012,
          Subtitle = "An explanation? ...Heh.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_Start",
            [2] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1201/120184/1E16393E"
        },
        [12018404] = {
          Camera = "-52.819229,197.234238,148.239014,0.000148,5.597148,-120.211037,35.000011,164.675781,false,Manual,6.0",
          ContentKR = "용병술은 속도가 생명인 법이지. 만약 자네에게 설명하느라 시간을 허비해서 사냥감이 달아나 버린다면, 뒷감당할 자신 있나?",
          DialogueId = 12018404,
          FacialId = {
            [1] = "210012:Doubt01"
          },
          GUID = "1E163968",
          NextDialogue = 12018405,
          Scripts = "PlayAnimation{_delay{1},ActorId{210012},AnimationId{\"Talk03ToThink_End\"},Duration{2}},",
          SpeakNpcId = 210012,
          Subtitle = "Timing is everything. Idle chatter can cost us dearly — and once lost, the prey may never be seen again.",
          VoiceName = "voice/$Locale$/story/1201/120184/1E163968"
        },
        [12018405] = {
          Camera = "-63.644783,133.544785,118.57605,0.000155,11.196975,138.185074,35.000011,122.361931,false,Manual,6.0",
          ContentKR = "그건 그쪽에서 고려하실 문제고요. 전 이번 행동이 위험하지는 않은지, 그리고 '정당'한 일인지에만 관심 있어요.",
          DialogueId = 12018405,
          FacialId = {
            [1] = "100001:Angry01"
          },
          FinalCamera = "-63.644783,133.544785,118.57605,0.000169,16.996433,-169.21553,35.000011,122.361931,false,Manual,6.0",
          GUID = "1E163992",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12018406,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{210012},AnimationId{"Angry01_Start"},Duration{2}},
CameraMoveTo{_delay{1.8},TargetPosition{"111.541771,105.213097,52.417542,0.000211,17.193266,-176.41481,25.000002,279.10498,false,Manual,6.0"},duration{0}},
SEQ{
MoveTo{ActorId{100001},MoveSpeed{120},TargetPoint{"nvzhu_47_duizhi"}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Nvzhu_Story_Angry02_Start"},Duration{2}},
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "That's your problem. What matters to me is whether this mission is dangerous — and whether it's even legitimate.",
          TalkActionId = {
            [1] = "210012:Talk03_End"
          },
          ToFinalCameraBlendTime = 0.9,
          VoiceName = "voice/$Locale$/story/1201/120184/1E163992"
        },
        [12018406] = {
          Camera = "-113.994232,54.671646,165.879028,0.000155,-25.60232,96.198647,25.000002,113.956665,false,DoNotOverride,22.0",
          ContentKR = "우와, 분위기 엄청 살벌하네... 시종, 그냥 관두는 게 어떨까?",
          DialogueId = 12018406,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "1E1639BC",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(210012)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12018407,
          SpeakNpcId = 200002,
          Subtitle = "Uwah, the tension is unreal... Little Minion, maybe we should just let it go?",
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E1639BC"
        },
        [12018407] = {
          Camera = "295.454956,542.930176,371.227875,0.000125,-26.204176,-133.401733,24.0,113.956657,false,DoNotOverride,22.0",
          ContentKR = "후후... 비굴하지도 거만하지도 않고, 조목조목 따질 줄도 알고. 자못 내 젊은 시절의 풍모가 보이는 듯하여 아주 마음에 드는군.",
          DialogueId = 12018407,
          FacialId = {
            [1] = "210012:Ahaha01"
          },
          GUID = "1E1639E6",
          NextDialogue = 12018408,
          SpeakNpcId = 210012,
          Subtitle = "Haha... Calm yet assertive. Standing your ground with reason — reminds me of my own youthful days. I admire that.",
          TalkActionId = {
            [1] = "210012:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E1639E6"
        },
        [12018408] = {
          Camera = "-125.168137,93.99778,144.010498,0.000147,-24.602682,79.995262,25.000002,166.176483,false,Manual,6.0",
          ContentKR = "...저 사람 갑자기 얼굴색이 변했어!",
          DialogueId = 12018408,
          GUID = "1E163A10",
          NextDialogue = 12018409,
          SpeakNpcId = 200002,
          Subtitle = "...He put on a new face just like that!?",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A10"
        },
        [12018409] = {
          Camera = "-95.768387,166.50177,121.84198,0.000135,-26.202879,76.599541,24.0,113.956657,false,DoNotOverride,22.0",
          ContentKR = "잠깐, 누가 저렇게 자기 자랑하듯이 남을 칭찬해! 완전 자뻑대마왕이잖아!",
          DialogueId = 12018409,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E163A3A",
          NextDialogue = 12018410,
          SpeakNpcId = 200002,
          Subtitle = "Hold on — who compliments others like that? This man's so full of himself!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A3A"
        },
        [12018410] = {
          Camera = "64.890961,321.150482,91.39502,0.000176,5.395296,-137.398178,24.0,297.770538,false,Manual,6.0",
          ContentKR = "가면서 이야기해 주겠네. 자네들이 궁금해하는 건, 내가 최대한 답해 주지.",
          DialogueId = 12018410,
          FacialId = {
            [1] = "210012:None"
          },
          GUID = "1E163A64",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(200002)",
            [3] = "200002:n(100001)"
          },
          SpeakNpcId = 210012,
          Subtitle = "Come, then. Let us speak as we walk. I shall do my best to answer what questions weigh upon your mind.",
          TalkActionId = {
            [1] = "210012:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A64"
        },
        [12018501] = {
          ContentKR = "촉룡의 재앙이 어째서 검은 폐안의 모습으로 나타나는지 의문을 품어본 적 있나?",
          DialogueId = 12018501,
          Duration = 3,
          GUID = "1E164952",
          NextDialogue = 12018502,
          SpeakNpcId = 210012,
          Subtitle = "Tell me, young friend — have you ever wondered why the Scourge of Zhuyin takes the form of Sable Bi'an?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164952"
        },
        [12018502] = {
          ContentKR = "화서에서 깊은 존경을 받는 폐안은, 바깥세상에서는 도리어 재앙과 공포를 불러일으키는 필토이드네. 그 차이를 만드는 건 바로 대풍구장의 속박이지.",
          DialogueId = 12018502,
          Duration = 5,
          GUID = "1E16497C",
          SpeakNpcId = 210012,
          Subtitle = "The Bi'an, revered in Huaxu, is elsewhere known as a Filthoid — a harbinger of calamity and dread. The difference lies in the constraints imposed by the Nine Chapters of Dafeng.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E16497C"
        },
        [12018503] = {
          ContentKR = "검은 폐안의 출현은, 오직 한 가지 추측으로 귀결될 뿐이네. …대풍구장은, 지금 통제 불능 상태라는 거지.",
          DialogueId = 12018503,
          Duration = 3,
          GUID = "1E1649A6",
          NextDialogue = 12018504,
          SpeakNpcId = 210012,
          Subtitle = "The emergence of these Sable Bi'an suggests but one troubling possibility: that the Nine Chapters are beginning to waver.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649A6"
        },
        [12018504] = {
          ContentKR = "하지만 지류 사장님은 촉룡의 재앙을 해결하면 그런 문제는 정상으로 돌아올 거라고 했어요.",
          DialogueId = 12018504,
          Duration = 3,
          GUID = "1E1649D0",
          NextDialogue = 12018505,
          SpeakNpcId = 100001,
          Subtitle = "But Proprietress Zhiliu said once we resolve the Scourge of Zhuyin, everything will go back to normal.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649D0"
        },
        [12018505] = {
          ContentKR = "맞네. 하지만 그것도 임시변통일 뿐이야.",
          DialogueId = 12018505,
          Duration = 2,
          GUID = "1E1649FA",
          NextDialogue = 12018506,
          SpeakNpcId = 210012,
          Subtitle = "Indeed. But that would be a temporary reprieve at best.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649FA"
        },
        [12018506] = {
          ContentKR = "만약 촉룡의 재앙이 반복되어, 오랜 세월 백성들의 삶을 피폐하게 만든다면 어찌하겠나?",
          DialogueId = 12018506,
          Duration = 3,
          GUID = "1E164A24",
          NextDialogue = 12018507,
          SpeakNpcId = 210012,
          Subtitle = "What if it returns, again and again, steadily hollowing out the people's strength?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A24"
        },
        [12018507] = {
          ContentKR = "지류 대방에게는 그 나름의 생각이 있을 것이네. 어떤 짐작들은, 자네에게 미처 말하지 않았을 수도 있고 말이지.",
          DialogueId = 12018507,
          Duration = 3,
          GUID = "1E164A4E",
          NextDialogue = 12018508,
          SpeakNpcId = 210012,
          Subtitle = "The Proprietress has her own considerations — some suspicions she may not yet share with you.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A4E"
        },
        [12018508] = {
          ContentKR = "내가 보기에, 대풍구장의 근간에 문제가 생겼다면, 아무리 손 써 봐야 그저 임시방편에 불과하네.",
          DialogueId = 12018508,
          Duration = 3,
          GUID = "1E164A78",
          NextDialogue = 12018509,
          SpeakNpcId = 210012,
          Subtitle = "From my perspective... if the very foundations of the Nine Chapters are compromised, no amount of patchwork can truly cure the rot.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A78"
        },
        [12018509] = {
          ContentKR = "그러니까, 애초에 대풍구장을 인정하지 않으신다는 건가요?",
          DialogueId = 12018509,
          Duration = 2,
          GUID = "1E164AA2",
          NextDialogue = 12018510,
          SpeakNpcId = 100001,
          Subtitle = "So you're saying... you've never really believed in the Nine Chapters?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164AA2"
        },
        [12018510] = {
          ContentKR = "허허허... 그렇게 딱 잘라 단정 지을 필요 있겠는가. 옛말에 지피지기면 백전백승이란 말이 있지 않나.",
          DialogueId = 12018510,
          Duration = 4,
          GUID = "1E164ACC",
          NextDialogue = 12018511,
          SpeakNpcId = 210012,
          Subtitle = "Haha... No need to be so categorical, young friend. As the saying goes: Know yourself, know your enemy, and you shall never taste defeat.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164ACC"
        },
        [12018511] = {
          ContentKR = "이번에 가는 목적은 폐안 한 마리를 잡아 나의 '수집품'으로 삼아, 그 원리를 철저히 연구해서 만일의 사태에 대비하려는 것이네.",
          DialogueId = 12018511,
          Duration = 5,
          GUID = "1E164AF6",
          NextDialogue = 12018512,
          SpeakNpcId = 210012,
          Subtitle = "This trip's purpose is to capture a Bi'an for my \"collection.\" I intend to study it thoroughly — a form of insurance against the worst.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164AF6"
        },
        [12018512] = {
          ContentKR = "어떤가? 이만하면 충분히 납득하겠나?",
          DialogueId = 12018512,
          Duration = 2,
          GUID = "1E164B20",
          NextDialogue = 12018513,
          SpeakNpcId = 210012,
          Subtitle = "So — does this reasoning satisfy you?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B20"
        },
        [12018513] = {
          ContentKR = "...폐안과 적이 되면, 대풍구장의 벌을 받지는 않나요?",
          DialogueId = 12018513,
          Duration = 5,
          GUID = "1E164B4A",
          NextDialogue = 12018514,
          SpeakNpcId = 100001,
          Subtitle = "...Won't turning against a Bi'an bring punishment from the Nine Chapters?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B4A"
        },
        [12018514] = {
          ContentKR = "허허, 우리 암시장 사람들은 늘 대풍구장의 경계를 아슬아슬 넘나드니, 다 방도가 있다네.",
          DialogueId = 12018514,
          Duration = 2,
          GUID = "1E164B74",
          SpeakNpcId = 210012,
          Subtitle = "Heh. We in the black market have long walked the knife's edge of the Nine Chapters. We know well how to stay within bounds.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B74"
        },
        [12018601] = {
          Camera = "24.121033,469.795776,75.995605,0.000102,15.589243,-120.015869,25.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "두목, 오셨습니까!",
          DialogueId = 12018601,
          FacialId = {
            [1] = "210010:CM_Smile01"
          },
          FinalCamera = "24.121033,469.795776,75.995605,0.00012,7.589159,-99.01458,25.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1E1659BA",
          NextDialogue = 12018602,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_CMName_Name_HeiShiXiaoDi",
          Subtitle = "Boss!",
          TalkActionId = {
            [1] = "210010:Agree"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1201/120186/1E1659BA"
        },
        [12018602] = {
          Camera = "-136.252167,91.878937,113.345459,0.000122,16.784575,27.185421,35.000011,182.757812,false,Manual,4.0",
          ContentKR = "상황은 어떤가?",
          DialogueId = 12018602,
          FacialId = {
            [1] = "210012:Doubt01"
          },
          GUID = "1E1659E4",
          NextDialogue = 12018603,
          SpeakNpcId = 210012,
          Subtitle = "How is everything going?",
          VoiceName = "voice/$Locale$/story/1201/120186/1E1659E4"
        },
        [12018603] = {
          Camera = "32.268948,257.847717,186.833252,0.00014,-8.414738,-115.807419,35.000011,279.251068,false,Manual,6.0",
          ContentKR = "예상하신 대로, 사냥감은 부상을 입고 이미 청아원으로 몰렸습니다. 여긴 사방이 바다로 둘러싸인 외딴섬이라 도망칠 수 없을 겁니다. 이제 독 안에 든 쥐나 다름없습니다!",
          DialogueId = 12018603,
          FacialId = {
            [1] = "210010:CM_Idle"
          },
          GUID = "1E165A0E",
          NextDialogue = 12018604,
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_CMName_Name_HeiShiXiaoDi",
          Subtitle = "Just as you foresaw — the prey's been wounded and driven into Crowsong Hollow. The place is ringed by the sea — like an island cut off from the world. There's no way out for it. Now we've only to close the net.",
          TalkActionId = {
            [1] = "210010:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A0E"
        },
        [12018604] = {
          Camera = "-13.461863,151.743454,164.995361,0.000152,9.581034,39.99184,24.0,21.207821,false,Manual,6.0",
          ContentKR = "청아원? 누가 그런 생각을 했지?",
          DialogueId = 12018604,
          FacialId = {
            [1] = "210012:Angry01"
          },
          GUID = "1E165A38",
          NextDialogue = 12018605,
          RelatedWikiId = {
            [1] = 408014,
            [2] = 401003
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{4},TargetPosition{"-105.969948,58.336342,92.497803,0.000142,18.781393,43.997467,24.0,197.430618,false,Manual,6.0"},duration{0.5}},
PlayAnimation{_delay{0},ActorId{210012},AnimationId{"Angry01_Start"},Duration{2}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Crowsong Hollow? Whose idea was that?",
          TalkActionId = {
            [1] = "210010:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A38"
        },
        [12018605] = {
          Camera = "-107.528519,199.333679,246.244141,0.000131,-27.816887,-94.392662,35.0,212.235535,false,Manual,6.0",
          ContentKR = "......",
          DialogueId = 12018605,
          FacialId = {
            [1] = "210010:CM_Shock01"
          },
          GUID = "1E165A62",
          NextDialogue = 12018606,
          SpeakNpcId = 210010,
          Subtitle = "...",
          TalkActionId = {
            [1] = "210010:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A62"
        },
        [12018606] = {
          Camera = "-103.426682,207.213165,221.943604,0.000147,-24.816774,-27.574326,35.000008,245.026596,false,Manual,22.0",
          ContentKR = "청아원에 무슨 문제라도 있나요?",
          DialogueId = 12018606,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E165A8C",
          LookAt = {
            [1] = "100001:n(210012)"
          },
          NextDialogue = 12018607,
          SpeakNpcId = 100001,
          Subtitle = "Is there something wrong with that place?",
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A8C"
        },
        [12018607] = {
          Camera = "-14.455,160.474716,158.683838,0.000099,-0.817505,-128.967682,35.0,196.648346,false,Manual,6.0",
          ContentKR = "그곳은 고대 전장 옛터라서, 평소에도 분위기가 으스스해 사람들이 다들 피해 가지 않습니까. 그래서 방해받을 일이 적을 듯하여...",
          DialogueId = 12018607,
          FacialId = {
            [1] = "210010:CM_Sad01"
          },
          GUID = "1E165AB6",
          NextDialogue = 12018608,
          SpeakNpcId = 210010,
          Subtitle = "Well, sir... it's part of the ancient battlefield — cold winds, eerie as can be. Nobody goes near it, so we thought it would be safer — less chance of interruption...",
          TalkActionId = {
            [1] = "210010:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165AB6"
        },
        [12018608] = {
          Camera = "-208.853943,31.453308,168.279785,0.00011,-6.41742,16.636448,25.0,316.576935,false,Manual,6.0",
          ContentKR = "그곳에서 탄식의 전투가 벌어졌던 것은 맞다. 하지만, 그보다 더 예전에는 어떤 용도로 쓰였는지 아나?",
          DialogueId = 12018608,
          GUID = "1E165AE0",
          LookAt = {
            [1] = "100001:n(210010)"
          },
          NextDialogue = 12018609,
          SpeakNpcId = 210012,
          Subtitle = "This was indeed the site of the Battle of Shuli. But do you know what it was before that?",
          TalkActionId = {
            [1] = "210012:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165AE0"
        },
        [12018609] = {
          ContentKR = "어어, 잘 모르겠습니다... 말씀해 주십시오, 두목.",
          DialogueId = 12018609,
          GUID = "1E165B0A",
          NextDialogue = 12018610,
          SpeakNpcId = 210010,
          Subtitle = "Uh... no, sir. Please, enlighten us.",
          TalkActionId = {
            [1] = "210010:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B0A"
        },
        [12018610] = {
          Camera = "-2403.743896,115.38797,1248.473267,0.00005,-28.217525,2.442638,25.0,316.576935,false,Manual,22.0",
          ContentKR = "그곳은 아주 먼 옛날, 기추파의 중요한 연구 시설이 있던 곳이다. 수백 년 전, 반란을 모의한다고 의심한 현형파가, 중무장한 병력을 이끌고 진압하러 올 때까지 말이야.",
          DialogueId = 12018610,
          FinalCamera = "-2292.674805,-508.969971,1248.90564,0.000039,-28.817556,18.043545,25.0,316.576935,false,Manual,22.0",
          GUID = "1E165B34",
          LookAt = {
            [1] = "210012:p(48_lookat)"
          },
          NextDialogue = 12018611,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4},TargetPosition{"101.46463,2433.009766,1018.791992,0.000078,-9.019374,-144.965591,14.0,316.576935,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{4.1},TargetPosition{"-306.286438,2143.177002,1099.884155,0.000079,19.780664,-144.165909,14.0,316.576935,false,Manual,22.0"},duration{10}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Long ago, this place served as a key research ground for the Jishu Sect — until a few centuries past, when the Xuanheng Sect grew suspicious of rebellion and sent in a heavy force to put it down.",
          TalkActionId = {
            [1] = "210012:Talk03_Start",
            [2] = "210010:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B34"
        },
        [12018611] = {
          Camera = "-92.525726,134.76416,116.622314,0.000168,23.376129,15.452583,25.000002,141.235916,false,Manual,22.0",
          ContentKR = "결국 싸우던 양측 모두 이곳에서 전멸하여, 단 한 명도 살아남지 못했다. 기추파도 그때부터 세가 기울기 시작했고.",
          DialogueId = 12018611,
          GUID = "1E165B5E",
          LookAt = {
            [1] = "210012:n(210012)"
          },
          NextDialogue = 12018612,
          SpeakNpcId = 210012,
          Subtitle = "In the end, both sides were lost — no survivors. From then on, the Jishu Sect faded into obscurity.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B5E"
        },
        [12018612] = {
          Camera = "-182.100525,11.012974,170.185303,0.000135,-6.422201,31.032133,25.0,57.624985,false,Manual,6.0",
          ContentKR = "사람은 역사의 먼지 속으로 사라졌지만, 물건은 그대로 남아있지.",
          DialogueId = 12018612,
          FinalCamera = "-182.100525,11.012974,170.185303,0.000135,-6.422201,31.032133,25.0,257.755127,false,Manual,6.0",
          GUID = "1E165B88",
          LookAt = {
            [1] = "210012:p(48_lookat)"
          },
          NextDialogue = 12018613,
          Scripts = "LookAt{_delay{3},LookAtDescription{\"210012:n(210010)\"}}",
          SpeakNpcId = 210012,
          Subtitle = "Those who vanished into the mists of history... left behind what they had crafted.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_End"
          },
          ToFinalCameraBlendTime = 1.2,
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B88"
        },
        [12018613] = {
          ContentKR = "기묘한 장치들의 원리를 더 이상 아는 자가 없으니, 혹여 실수로라도 잘못 건드렸다간 무슨 일이 벌어질지 알 수 없단 말이다.",
          DialogueId = 12018613,
          GUID = "1E165BB2",
          LookAt = {
            [1] = "210012:n(210010)"
          },
          NextDialogue = 12018614,
          SpeakNpcId = 210012,
          Subtitle = "The mechanisms here have long been concealed by time. Should any be carelessly triggered... the consequences could be unpredictable.",
          VoiceName = "voice/$Locale$/story/1201/120186/1E165BB2"
        },
        [12018614] = {
          Camera = "-80.173622,81.490814,193.79834,0.000193,-22.421099,-132.158981,35.0,81.858253,false,Manual,6.0",
