        [12018701] = {
          ContentKR = "쫓아!",
          DialogueId = 12018701,
          GUID = "1E166A22",
          SpeakNpcId = 210012,
          Subtitle = "Get him!",
          VoiceName = "voice/$Locale$/story/1201/120187/1E166A22"
        },
        [12018801] = {
          ContentKR = "이, 이건 대체 땅속에서 뭐가 깨어난 거야...?! 굉장한 장치들이네!",
          DialogueId = 12018801,
          GUID = "1E167A8A",
          NextDialogue = 12018802,
          SpeakNpcId = 200002,
          Subtitle = "D—Did something just wake up from under the ground!? Whoa... an ancient mega maze!?",
          VoiceName = "voice/$Locale$/story/1201/120188/1E167A8A"
        },
        [12018802] = {
          ContentKR = "규선생이 앞에 있어. 가서 한번 물어보자.",
          DialogueId = 12018802,
          GUID = "1E167AB4",
          SpeakNpcId = 100001,
          Subtitle = "Mr Qiu went ahead. Let's catch up and find out what's going on.",
          VoiceName = "voice/$Locale$/story/1201/120188/1E167AB4"
        },
        [12018901] = {
          Camera = "1602.116455,-389.513306,871.401367,0.000128,-28.607693,165.210678,18.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "재미있군, 아주 재미있어... 수백 년의 세월도 이 고대 기계 장치들을 망가뜨리지는 못한 모양이군. 지금까지도 멀쩡히 작동하다니.",
          DialogueId = 12018901,
          FacialId = {
            [1] = "210012:Smile01"
          },
          FinalCamera = "1640.834229,-8.196655,871.401367,0.000124,-28.807701,-179.789062,18.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1E168AF2",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(100001)",
            [3] = "200002:n(210012)"
          },
          NextDialogue = 12018902,
          RelatedWikiId = {
            [1] = 203005,
            [2] = 408014,
            [3] = 401003,
            [4] = 403007
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"280.892273,11.721771,32.181641,0.000083,13.191847,164.411865,25.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{_delay{5.1},TargetPosition{"291.415833,60.84111,32.181641,0.000094,12.991886,173.011993,25.0,100000.0,false,DoNotOverride,22.0"},duration{7}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Fascinating... utterly fascinating. Centuries have passed, yet these ancient war contraptions still function flawlessly.",
          TalkActionId = {
            [1] = "210012:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120189/1E168AF2"
        },
        [12018902] = {
          Camera = "-34.330143,72.500282,189.90625,0.000091,6.999919,-141.000183,35.0,100000.0,false,DoNotOverride,22.0",
          ContentKR = "기추파의 선인들은 이토록 신묘한 솜씨로 위대한 업적을 이루었건만, 지금은 대풍구장의 금지령 때문에 이름조차 남아있지 않으니, 애석하지 않나?",
          DialogueId = 12018902,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "210012:Angry01"
          },
          FinalCamera = "14.608597,109.413803,133.554688,0.00009,13.399642,-139.400177,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1E168B1C",
          NextDialogue = 12018903,
          Scripts = "PlayAnimation{_delay{2},ActorId{210012},AnimationId{\"Confident_Start\"},Duration{2}},",
          SpeakNpcId = 210012,
          Subtitle = "The forebears of the Jishu Sect created such masterworks — yet thanks to the bans of the Nine Chapters, their legacy has slipped into obscurity. Don't you think that's a pity?",
          TalkActionId = {
            [1] = "210012:Talk01_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120189/1E168B1C"
        },
        [12018903] = {
          Camera = "-85.09005,-41.354012,187.742188,0.000135,-16.999964,79.203743,25.000002,265.992188,false,Manual,6.0",
          ContentKR = "지금 이게 무슨 상황이에요? 여기서 어떻게 하면 나갈 수 있는 거죠?",
          DialogueId = 12018903,
          GUID = "1E168B46",
          NextDialogue = 12018904,
          SpeakNpcId = 100001,
          Subtitle = "What's going on? How do we get out of here?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120189/1E168B46"
        },
        [12018904] = {
          Camera = "25.055338,-3.090464,104.582031,0.000121,-7.799625,60.402626,35.0,125.585297,false,Manual,6.0",
          ContentKR = "맞아! 쓸데없는 소리는 그만둬, 난 여기 갇히기 싫다고!",
          DialogueId = 12018904,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "25.055338,-3.090464,104.582031,0.000121,-7.799625,62.202351,35.000008,125.585297,false,Manual,6.0",
          GUID = "1E168B70",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(200002)",
            [3] = "200002:n(210012)"
          },
          NextDialogue = 12018905,
          SpeakNpcId = 200002,
          Subtitle = "Yeah! Enough with the history lessons — I don't want to be stuck here!",
          TalkActionId = {
            [1] = "200002:Angry02_Start"
          },
          ToFinalCameraBlendTime = 0.8,
          VoiceName = "voice/$Locale$/story/1201/120189/1E168B70"
        },
        [12018905] = {
          Camera = "99.821701,41.477108,120.901367,0.00014,11.999624,-174.197815,35.000008,210.213547,false,Manual,6.0",
          ContentKR = "쯧, 풍류를 모르는군. 골동품의 아름다움도 모르는 자들이라니.",
          DialogueId = 12018905,
          FacialId = {
            [1] = "200002:None",
            [2] = "210012:Doubt01"
          },
          GUID = "1E168B9A",
          NextDialogue = 12018906,
          Scripts = "PlayAnimation{_delay{2},ActorId{210012},AnimationId{\"Confident_End\"},Duration{2}},",
          SpeakNpcId = 210012,
          Subtitle = "Tsk. No appreciation for the beauty of ancient marvels... How disappointing.",
          TalkActionId = {
            [1] = "210012:DisagreeHead",
            [2] = "200002:Angry02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120189/1E168B9A"
        },
        [12018906] = {
          Camera = "99.821701,41.477108,120.901367,0.00014,11.999624,-174.197815,35.000008,210.213547,false,Manual,6.0",
          ContentKR = "무릇 장치란, 반드시 비상구를 남겨두는 법이네... 예를 들면, 눈앞의 저 비석, 성세비 말이지. 딱 봐도 누군가 두드려주길 기다리는 것처럼 보이지 않나?",
          DialogueId = 12018906,
          GUID = "1E168BC4",
          LookAt = {
            [1] = "210012:n(210012)"
          },
          NextDialogue = 12018907,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"-2599.537109,-2099.010498,495.693359,0.00015,-8.80078,40.403954,18.0,256766.0625,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{_delay{2.1},TargetPosition{"-2722.54248,-2203.702393,520.700195,0.00015,-8.80078,40.403954,18.0,256766.0625,false,DoNotOverride,22.0"},duration{8}},
CameraMoveTo{_delay{4.5},TargetPosition{"-6405.689453,-5441.508301,1031.489258,0.000213,13.197038,-140.794937,18.000008,256766.0625,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{_delay{4.6},TargetPosition{"-6437.628906,-5467.57373,1041.154297,0.000213,13.197038,-140.794937,18.000008,256766.0625,false,DoNotOverride,22.0"},duration{6}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Every mechanism leaves a fail-safe... like that Enlightenment Stele ahead. Doesn't it look as though it's just waiting to be struck?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          TurnTo = {
            [1] = "210012:p(-179)"
          },
          VoiceName = "voice/$Locale$/story/1201/120189/1E168BC4"
        },
        [12018907] = {
          Camera = "-94.359398,-63.731007,207.273438,0.000093,-26.399609,66.203903,20.0,285.160034,false,Manual,6.0",
          ContentKR = "어이, 만약 틀리면 어떡하려고 그래?!",
          DialogueId = 12018907,
          FacialId = {
            [1] = "200002:Shock02"
          },
          GUID = "1E168BEE",
          NextDialogue = 12018908,
          SpeakNpcId = 200002,
          Subtitle = "Um, what if you're wrong?",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120189/1E168BEE"
        },
        [12018908] = {
          ContentKR = "허허... 그렇다면야 {nickname} 자네의 날랜 몸놀림에 기댈 수밖에.",
          DialogueId = 12018908,
          FacialId = {
            [1] = "210012:Ahaha01"
          },
          GUID = "1E168C18",
          SpeakNpcId = 210012,
          Subtitle = "Hehe... then we'll be counting on your nimble moves, .",
          TurnTo = {
            [1] = "210012:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120189/1E168C18"
        },
        [12019001] = {
          ContentKR = "듣자 하니, 기추파는 붉은색을 으뜸으로 쳤다고 하더군.",
          DialogueId = 12019001,
          GUID = "1E169B5A",
          NextDialogue = 12019002,
          SpeakNpcId = 210012,
          Subtitle = "I've heard the Jishu Sect revered the colour red above all others.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B5A"
        },
        [12019002] = {
          ContentKR = "즉, 붉은색 길이 안전하다는 뜻이군요.",
          DialogueId = 12019002,
          GUID = "1E169B84",
          SpeakNpcId = 100001,
          Subtitle = "So the red path is the safer one — got it.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B84"
        },
        [12019050] = {
          ContentKR = "장치들 중 일부에 불이 들어온 것 같아... 시종, 이게 무슨 뜻일까?",
          DialogueId = 12019050,
          GUID = "1E169B85",
          NextDialogue = 12019051,
          SpeakNpcId = 200002,
          Subtitle = "Look, some of the blocks lit up... What does that mean, Little Minion?",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B85"
        },
        [12019051] = {
          ContentKR = "뻔하지 않나. 장치에 불이 들어온 순서대로 따라가면, 여기서 나갈 수 있을 거네.",
          DialogueId = 12019051,
          GUID = "1E169B86",
          NextDialogue = 12019052,
          SpeakNpcId = 210012,
          Subtitle = "The intent is quite clear. Proceed in the order the blocks illuminated, and you shall resolve our current predicament.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B86"
        },
        [12019052] = {
          ContentKR = "...그런 건 그쪽이 말해주지 않아도 우리 시종이 다 알고 있거든!",
          DialogueId = 12019052,
          GUID = "1E169B87",
          NextDialogue = 12019053,
          SpeakNpcId = 200002,
          Subtitle = "...We didn't need you to tell us that! My Little Minion already knew!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B87"
        },
        [12019053] = {
          ContentKR = "좋아요, 해보죠.",
          DialogueId = 12019053,
          GUID = "1E169B88",
          SpeakNpcId = 100001,
          Subtitle = "Alright, I'll give it a try.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B88"
        },
        [12019054] = {
          ContentKR = "으아아아아, 이 장치들이 왜 움직이는 거야! 발이라도 헛디디면 떨어져 버리겠어!",
          DialogueId = 12019054,
          GUID = "1E169B89",
          NextDialogue = 12019055,
          SpeakNpcId = 200002,
          Subtitle = "Whoaaaa, these blocks are moving! If we miss a step, we'll fall right down!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B89"
        },
        [12019055] = {
          ContentKR = "똑똑한 마왕님이 아니었으면 진짜 큰일날 뻔 했잖아... 여기 너무 비겁한 거 아냐?",
          DialogueId = 12019055,
          GUID = "1E169B91",
          NextDialogue = 12019056,
          SpeakNpcId = 200002,
          Subtitle = "The great Demon King almost got bested by such a cheap trick... How treacherous!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B91"
        },
        [12019056] = {
          ContentKR = "후후, 뻔한 난이도라면 도전이라 할 수 없지 않나.",
          DialogueId = 12019056,
          GUID = "1E169B92",
          NextDialogue = 12019057,
          SpeakNpcId = 210012,
          Subtitle = "Heh. A predictable path can hardly be called a challenge, can it?",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B92"
        },
        [12019057] = {
          ContentKR = "흥, 그쪽한테 물어본 거 아니거든!",
          DialogueId = 12019057,
          GUID = "1E169B93",
          SpeakNpcId = 200002,
          Subtitle = "Hmph! Nobody asked you!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B93"
        },
        [12019058] = {
          ContentKR = "으악! 이, 이 녀석은 어디서 튀어나온 거야! 움직이잖... 아니 우릴 공격하잖아!",
          DialogueId = 12019058,
          GUID = "1E169B94",
          NextDialogue = 12019059,
          SpeakNpcId = 200002,
          Subtitle = "Ah! Where did these things come from?! They're moving... and they're attacking us!",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B94"
        },
        [12019059] = {
          ContentKR = "아마 이곳을 설계할 때 남겨둔 수비병들일 거네. 외부의 침입자를 막기 위한 용도였겠지.",
          DialogueId = 12019059,
          GUID = "1E169B95",
          NextDialogue = 12019060,
          SpeakNpcId = 210012,
          Subtitle = "Must be guardians left here since this place was built, meant to defend against intruders.",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B95"
        },
        [12019060] = {
          ContentKR = "{nickname}, 정신 똑바로 차리고 상대하게.",
          DialogueId = 12019060,
          GUID = "1E169B96",
          SpeakNpcId = 210012,
          Subtitle = "Stay sharp and deal with them, .",
          VoiceName = "voice/$Locale$/story/1201/120190/1E169B96"
        },
        [12019101] = {
          ContentKR = "어, 똑같이 생긴 성세비가 동시에 두 개나 나타났네...",
          DialogueId = 12019101,
          GUID = "1E16ABC2",
          NextDialogue = 12019102,
          SpeakNpcId = 200002,
          Subtitle = "Huh? Two identical Steles at the same time...?",
          VoiceName = "voice/$Locale$/story/1201/120191/1E16ABC2"
        },
        [12019102] = {
          ContentKR = "음... 아무래도 두 사람이 각기 다른 곳에서 동시에 두드려야 하는 모양이군.",
          DialogueId = 12019102,
          GUID = "1E16ABEC",
          NextDialogue = 12019103,
          SpeakNpcId = 210012,
          Subtitle = "Hmm... Perhaps they must be struck simultaneously from separate positions.",
          VoiceName = "voice/$Locale$/story/1201/120191/1E16ABEC"
        },
        [12019103] = {
          ContentKR = "{nickname}, 같이 한번 해 보도록 하지.",
          DialogueId = 12019103,
          GUID = "1E16AC16",
          SpeakNpcId = 210012,
          Subtitle = "Let's give it a try, . ",
          VoiceName = "voice/$Locale$/story/1201/120191/1E16AC16"
        },
        [12019201] = {
          ContentKR = "으아아아아악! 스, 스노우 엉덩이 너무 아파!",
          DialogueId = 12019201,
          GUID = "1E16BC2A",
          NextDialogue = 12019202,
          SpeakNpcId = 200002,
          Subtitle = "Aaaahhhh—! My poor buns! They really took a critical hit!",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC2A"
        },
        [12019202] = {
          ContentKR = "규선생은 어디로 떨어진 거지...",
          DialogueId = 12019202,
          GUID = "1E16BC54",
          NextDialogue = 12019203,
          SpeakNpcId = 200002,
          Subtitle = "Where did Mr Qiu end up...?",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC54"
        },
        [12019203] = {
          ContentKR = "설마, 이 기계 장치는 같이 온 사람들을 갈라놓는 건가...?",
          DialogueId = 12019203,
          GUID = "1E16BC7E",
          NextDialogue = 12019204,
          SpeakNpcId = 100001,
          Subtitle = "Could it be... this entire mechanism array was meant to separate anyone travelling together...?",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BC7E"
        },
        [12019204] = {
          ContentKR = "잠깐, 시종! 앞에 사람이 있어!",
          DialogueId = 12019204,
          GUID = "1E16BCA8",
          SpeakNpcId = 200002,
          Subtitle = "Wait, Little Minion! There's someone up ahead!",
          VoiceName = "voice/$Locale$/story/1201/120192/1E16BCA8"
        },
        [12019301] = {
          ContentKR = "잘 됐군, 사람이 왔어! 이제 나 혼자만 여기 갇힌 게 아니게 됐구나.",
          DialogueId = 12019301,
          GUID = "1E16CC92",
          NextDialogue = 12019302,
          SpeakNpcId = 210021,
          SpeakNpcName = "UI_CMName_Name_SaTuoBuJi",
          Subtitle = "Haha... Finally, some company! I'm not alone in this pit anymore.",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CC92"
        },
        [12019302] = {
          ContentKR = "내 이름은 각주, 화서를 떠도는 나그네다. 두 분은 성함이 어찌 되시는가?",
          DialogueId = 12019302,
          GUID = "1E16CCBC",
          NextDialogue = 12019303,
          RelatedWikiId = {
            [1] = 203007
          },
          SpeakNpcId = 210021,
          Subtitle = "The name's Kezhou, a Drifter from Huaxu. And you two are...?",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CCBC"
        },
        [12019303] = {
          ContentKR = "그럼... 나는 순백의 구원자☆ 빛의 마왕님, 스노우라고 해. 보다시피, 마왕이지! 세계 정복은 나한테 맡기라고!",
          DialogueId = 12019303,
          GUID = "1E16CCE6",
          NextDialogue = 12019304,
          SpeakNpcId = 200002,
          Subtitle = "Since you asked... Ahem! I am the Pure-White Redeemer ☆ Demon King of Light! You can call me Snow! As you can see, I'm a real Demon King, and my purpose is to conquer the world!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CCE6"
        },
        [12019304] = {
          ContentKR = "이쪽은 내 시종, {nickname}인데, 얘는 나 다음으로 세!",
          DialogueId = 12019304,
          GUID = "1E16CD10",
          NextDialogue = 12019305,
          SpeakNpcId = 200002,
          Subtitle = "And this is my Little Minion, . {性别:He|She}'s the second strongest fighter in the world — right after me!",
          VoiceName = "voice/$Locale$/story/1201/120193/1E16CD10"
        },
        [12019305] = {
          ContentKR = "오오...! 그랬던 것이냐! 어쩐지 내가 가진 온갖 창칼로 이곳을 몇 번이나 뒤집어엎어도 꿈쩍하지 않더니... 여기를 두드려야 했던 게로군. 그건 그렇고, 이 기추파가 만든 물건은 참으로 단단하구나.",
          DialogueId = 12019305,
          GUID = "120193141.0",
          SpeakNpcId = 210021,
          Subtitle = "Huh — so that's the trick! No wonder I battered this place with all the blades I carry, and it wouldn't budge an inch... turns out you just have to give the right spot a tap! Gotta hand it to the Jishu Sect — they built things to last.",
