          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120198/1E170E5D"
        },
        [12019801] = {
          ContentKR = "서로 다른 곳으로 떨어졌을 때 생겼던 일들을 규선생에게 알려 주었다.",
