PlayAnimation{ActorId{211002},AnimationId{"Sigh_Start"},Duration{1}}
}]],
          SpeakNpcId = 211002,
          Subtitle = "I'm never gonna live that one down, am I...",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DEB4E"
        },
        [12030412] = {
          Camera = "-449.797119,284.380859,80.856934,0.000134,3.600438,-23.285967,35.0,272.126312,false,Manual,22.0",
          ContentKR = "이제 슬슬 따라가 봐. 부탁해, '유니콘 {性别:오빠|언니}' 겸 '수호령' {性别:형님|누님}!",
          DialogueId = 12030412,
          FinalCamera = "-458.496094,299.924805,79.969238,0.000133,3.600438,-23.085436,35.0,272.126312,false,Manual,22.0",
          GUID = "1E1DEB78",
          Scripts = [[
PARA{
PlayAnimation{ActorId{211002},AnimationId{"Sigh_End"},Duration{1}},
LookAt{LookAtDescription{"100001:n(211001)"}},
LookAt{LookAtDescription{"211002:n(211001)"}},
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Look01_Start"},Duration{1}},
MoveTo{_delay{6},ActorId{211001},TargetPoint{"simple0401"},MoveSpeed{75},Visibility{"Show"}}
}]],
          SpeakNpcId = 211002,
          Subtitle = "Alright — time to shadow her. I'm counting on you, {性别:Mr|Miss} Unicorn, Guardian Extraordinaire!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DEB78"
        },
        [12030425] = {
          ContentKR = "뭐? 마크는 오늘 안 온대...?",
          DialogueId = 12030425,
          GUID = "1E1DEB79",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
