PlayAnimation{_delay{0.5},ActorId{211002},AnimationId{"ConfidentR_Start"},Duration{1.5}},
PlayFacial{_delay{0.5},ActorId{211002},FacialId{"Smile02"}},
}]],
          SpeakNpcId = 211002,
          Subtitle = "Though seriously... did the Great Magician have to be a dog?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E6D92"
        },
        [12031206] = {
          Camera = "-324.616211,113.357422,145.507812,0.000084,-5.994993,-26.582512,35.000015,350.0,false,DoNotOverride,3.0",
          ContentKR = "강아지는 귀여운 귀도 있고, 냄새도 잘 맡잖아. 얼마나 멋지다고!",
          DialogueId = 12031206,
          GUID = "1E1E6DBC",
          NextDialogue = 12031207,
          Scripts = [[
