PlayAnimation{_delay{0},ActorId{211003},AnimationId{"Confident_Start"}}
}]],
          SpeakNpcId = 211003,
          Subtitle = "But the Security Bureau didn't think it counts as evidence... So now it's up to me — the Reticent Detective — to track them down, stop their wicked plot, and keep the children of Icelake safe!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E8070"
        },
        [12031321] = {
          Camera = "0.609863,-390.711426,114.49585,0.000112,-0.000246,91.142174,35.000015,440.047546,false,DoNotOverride,4.5",
          ContentKR = "꼬마 조수, 우리 같이 힘내 보자! 1~5번 쓰레기통은 벌써 다 확인해서, 이제 난 6번을 확인하러 갈 거야... 그러니까, 7번은 너한테 맡길게!",
          DialogueId = 12031321,
          FinalCamera = "-2.351074,-242.245605,114.412109,0.000112,-0.200261,91.142151,35.000015,440.047546,false,DoNotOverride,4.5",
          GUID = "1E1E809A",
          NextDialogue = 12031322,
          Scripts = [[
PARA{
