          SpeakNpcId = 211003,
          Subtitle = "You're back, Little Sidekick! Look — I found a local paper with a mark on it! It's an ad for a theatre show... maybe the bandits are targeting the theatre!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E9E22"
        },
        [12031502] = {
