        [12032029] = {
          Camera = "-136.98381,-96.949409,138.581787,0.00012,-0.998656,-161.679504,28.0,218.307404,false,Manual,8.0",
          ContentKR = "이 아이 친구. 월석 사냥꾼이야.",
          DialogueId = 12032029,
          FinalCamera = "-210.195267,-120.908394,151.526123,0.000123,-2.198658,-161.879517,28.0,123.901291,false,Manual,2.8",
          GUID = "1E1EF4C2",
          NextDialogue = 12032101,
          Scripts = [[
PARA{
PlayFacial{ActorId{100001},FacialId{"Happy02"}},
PlayAnimation{ActorId{100001},AnimationId{"Wave02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "A friend of hers. And a Phoxhunter, for the record.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF4C2"
        },
        [12032030] = {
          ContentKR = "카산드라가 주인공의 무기를 힐끗 본다.",
          DialogueId = 12032030,
          GUID = "1E1EF4EC",
          NextDialogue = 12032101,
          Subtitle = "Cassandra eyes the protagonist's weapon",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF4EC"
        },
        [12032101] = {
          Camera = "-234.579056,-133.042816,122.354248,0.000082,-2.599946,47.71814,35.000008,210.94072,false,Manual,2.8",
          ContentKR = "그, 그게 뭐! 어차피 카론이면서! 말해 두겠는데, 난 내성에서 왔거든?!",
          DialogueId = 12032101,
          GUID = "1E1F0092",
          NextDialogue = 12032102,
          SpeakNpcId = 211012,
          Subtitle = "So what? You're just a Charon! And I'll have you know I'm from the inner city!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F0092"
        },
        [12032102] = {
          Camera = "-193.513412,-117.182365,150.495117,0.000083,-0.599943,-161.482178,35.000008,151.270233,false,Manual,2.8",
          ContentKR = "아, 그래?",
          DialogueId = 12032102,
          GUID = "1E1F00BC",
          NextDialogue = 12032103,
          Scripts = [[
PARA{
PlayFacial{ActorId{100001},FacialId{"Smile02"}},
PlayAnimation{ActorId{100001},AnimationId{"Wave02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Good for you.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F00BC"
        },
        [12032103] = {
          Camera = "-503.357483,-430.700165,180.279785,0.000079,-6.800013,47.918465,35.000008,1134.2052,false,Manual,8.0",
          ContentKR = "돼, 됐어. 도와주기 싫으면 관둬. 다른 사람 찾으면 그만이니까!",
          DialogueId = 12032103,
          GUID = "1E1F00E6",
          Scripts = "MoveTo{_delay{2},ActorId{211012},TargetPoint{\"Kashandela01\"},MoveSpeed{250},Visibility{\"Show\"}}",
          SpeakNpcId = 211012,
          Subtitle = "Tch—! Fine! If you won't help, I'll find someone else!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F00E6"
        },
        [12032104] = {
          ContentKR = "카산드라가 떠난다.",
          DialogueId = 12032104,
          GUID = "1E1F0110",
          Subtitle = "Cassandra huffs and runs off",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F0110"
        },
        [12032201] = {
          Camera = "-262.630035,518.570374,384.213135,0.00006,-27.400436,-73.273003,28.000008,252.567276,false,Manual,10.0",
          ContentKR = "피나, 괜찮아?",
          DialogueId = 12032201,
          FinalCamera = "-233.775208,527.242126,384.213135,0.00006,-27.400436,-73.273003,28.000008,252.567276,false,Manual,10.0",
          GUID = "1E1F10FA",
          NextDialogue = 12032202,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},MoveSpeed{75},TargetPoint{"Nvzhu02"}},
LookAt{LookAtDescription{"100001:n(211001)"}},
LookAt{LookAtDescription{"211001:n(100001)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You alright, Fina?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F10FA"
        },
        [12032202] = {
          Camera = "-297.106384,-36.227322,125.762207,0.000083,2.59916,-5.271038,35.0,296.228882,false,Manual,1.4",
          ContentKR = "응, 걱정해 줘서 고마워! 근데, 아까 걔...",
          DialogueId = 12032202,
          GUID = "1E1F1124",
          NextDialogue = 12032203,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
LookAt{_delay{3.5},LookAtDescription{"211001:p(Kashandela01)"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I'm fine. Thanks for looking out for me! But... that girl—",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1124"
        },
        [12032203] = {
          Camera = "-2.594985,-240.799469,116.917969,0.000117,5.19819,119.91935,35.000008,206.443939,false,Manual,2.8",
          ContentKR = "벌써 저 멀리 가 버렸을 거야. 저렇게 거들먹거리는 솔라들 많이 봤는데, 다 허세야.",
          DialogueId = 12032203,
          GUID = "1E1F114E",
          NextDialogue = 12032204,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk02R_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "She's long gone. I've met plenty of puffed-up Solarians — all bark, no bite.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F114E"
        },
        [12032204] = {
          Camera = "44.288864,-68.407341,133.100342,0.000122,1.398044,-174.282288,35.000008,159.098145,false,Manual,2.8",
          ContentKR = "피나도 앞으론 조심해야 해. 아무한테나 그렇게 친절하게 대하면, 우리가 네 걱정을 엄청 하게 될걸.",
          DialogueId = 12032204,
          GUID = "1E1F1178",
          NextDialogue = 12032205,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk02R_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Still, you've got to be careful. Don't go being kind to just anyone... There are bad people out there.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1178"
        },
        [12032205] = {
          Camera = "-95.046806,-140.193008,140.690674,0.000125,-4.602113,49.317894,35.0,159.098129,false,Manual,2.8",
          ContentKR = "그치만... 아까 내가 마법을 쓸 줄 안다고 하니까, 웃어 줬는걸... 내 눈엔 보여, 진심이란 거. 나쁜 마법산 그렇게 웃지 않으니까.",
          DialogueId = 12032205,
          FinalCamera = "-82.042175,-125.063324,139.085938,0.000125,-4.602113,49.317894,35.000008,159.098129,false,Manual,2.8",
          GUID = "1E1F11A2",
          NextDialogue = 12032206,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"211001:n(211001)"}},
PlayAnimation{ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Think01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "But when I said I could do magic... she smiled. And I could see it — it was a real smile. Honest, and innocent. Bad sorcerers don't smile like that.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11A2"
        },
        [12032206] = {
          Camera = "-82.042175,-125.063324,139.085938,0.000125,-4.602113,49.317894,35.000008,159.098129,false,Manual,2.8",
          ContentKR = "그리고, 걘 어린애잖아! 나도 그 정도 나이였을 때, 이름도 모르는 어떤 오빠한테서 도움을 받은 적이 있었어...",
          DialogueId = 12032206,
          GUID = "1E1F11CC",
          NextDialogue = 12032207,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "And... she's just a child. When I was her age, a kind-hearted stranger once helped me...",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11CC"
        },
        [12032207] = {
          Camera = "6.907836,-321.75943,129.159912,0.000122,-0.802151,102.716034,24.0,159.098129,false,Manual,10.0",
          ContentKR = "그때 결심했어. 나중에 어른이 되면, 도움이 필요한 아이를 만났을 때, 그 오빠처럼 도움을 주자고 말이야.",
          DialogueId = 12032207,
          GUID = "1E1F11F6",
          NextDialogue = 12032208,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk03_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Sad01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I promised myself then: When I grow up, I'll help any child in need — just like that big brother helped me.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11F6"
        },
        [12032208] = {
          Camera = "-217.036926,-261.586731,133.03418,0.000126,0.197871,53.31599,35.000011,311.586395,false,Manual,2.8",
          ContentKR = "그러니까, 난 그 꼬마를 찾아서 확실히 물어보고 싶어! 진짜로 곤란한 상황에 처한 거면, 보고도 모른 척할 순 없어.",
          DialogueId = 12032208,
          GUID = "1E1F1220",
          NextDialogue = 12032209,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk03_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "So... I want to find that girl. Ask if she's alright. And if she's really in trouble... I want to help.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1220"
        },
        [12032209] = {
          Camera = "173.914368,-27.305672,142.411133,0.000137,-3.602255,-174.485565,35.000008,1783.921265,false,Manual,10.0",
          ContentKR = "음, 알겠어! 그렇다면 내가 같이 가 줄게. 혹시라도 무슨 일이 생기면, 이 {性别:오빠|언니}가 피나 '어린이'를 도와줘야지.",
          DialogueId = 12032209,
          GUID = "1E1F124A",
          NextDialogue = 12032210,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Alright. Then let's go together. If anything happens, this {性别:big brother|big sister} will be right there to back you up.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F124A"
        },
        [12032210] = {
          Camera = "-184.001755,-162.542816,152.971924,0.000154,-4.801753,40.315285,35.000023,249.784531,false,Manual,2.8",
          ContentKR = "헤헤, 고마워! 유니콘 {性别:오빠|언니}가 같이 있어 준다면, 난 겁 하나도 안 나.",
          DialogueId = 12032210,
          GUID = "1E1F1274",
          NextDialogue = 12032211,
          Scripts = [[
PARA{

PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_Start"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{ActorId{100001},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Hehe... Thank you, {性别:Mr|Miss} Unicorn! With you by my side, I'm not afraid of anything!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1274"
        },
        [12032211] = {
          Camera = "-184.001755,-162.542816,152.971924,0.000154,-4.801753,40.315285,35.000023,249.784531,false,Manual,2.8",
          ContentKR = "좋아, 그럼 출발하자. 아까 걔가 광장 쪽으로 가는 걸 봤어.",
          DialogueId = 12032211,
          FinalCamera = "40.894524,-343.161194,107.66748,0.000154,2.797645,109.714264,20.000008,139.632568,false,Manual,10.0",
          GUID = "1E1F129E",
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_End"},Duration{1}},
LookAt{LookAtDescription{"211001:p(Kashandela01)"}},
LookAt{LookAtDescription{"100001:p(Kashandela01)"}}
}
]],
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's go. Pretty sure she headed for the square.",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F129E"
        },
        [12032212] = {
          ContentKR = "아이스레이크 시티 광장으로 이동 후, 카산드라를 발견한다.",
          DialogueId = 12032212,
          GUID = "1E1F12C8",
          Subtitle = "At Icelake Square – Fina and the protagonist approach Cassandra",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F12C8"
        },
        [12032301] = {
          Camera = "334.360657,-587.908386,278.855469,0.000115,-14.00104,114.318268,35.000019,267.529114,false,Manual,22.0",
          ContentKR = "너네... 왜 여기까지 따라온 거야?! 내가 너네한테 뭘 어쨌다고...",
          DialogueId = 12032301,
          FinalCamera = "300.830353,-513.711609,258.553711,0.000115,-14.00104,114.318268,35.000019,267.529114,false,Manual,22.0",
          GUID = "1E1F2162",
          NextDialogue = 12032302,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(100001)"}},
LookAt{LookAtDescription{"211012:n(211001)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "It's you... Why are you two following me!? I didn't do anything to you!",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2162"
        },
        [12032302] = {
          Camera = "-112.066307,156.878036,123.823242,0.000105,0.598953,-20.880886,35.000008,267.529114,false,Manual,22.0",
          ContentKR = "오해하지 마, 친구야.",
          DialogueId = 12032302,
          FinalCamera = "-88.106537,147.737793,124.091797,0.00011,0.598953,-20.880886,35.000011,267.529114,false,Manual,22.0",
          GUID = "1E1F218C",
          NextDialogue = 12032303,
          Scripts = [[
SEQ{
PARA{
LookAt{LookAtDescription{"211012:n(211001)"}},
PlayAnimation{ActorId{211001},AnimationId{"DisagreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Blink"}}
},
SEQ{
PlayFacial{ActorId{211001},FacialId{"None"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "You've got it wrong, little one.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F218C"
        },
        [12032303] = {
          Camera = "147.284775,-92.297577,143.766602,0.000095,-6.801092,105.718018,28.0,267.529114,false,Manual,12.0",
          ContentKR = "난 네 친구 아니거든!",
          DialogueId = 12032303,
          FinalCamera = "151.795822,-108.326996,145.751953,0.000095,-6.801092,105.718018,28.0,267.529114,false,Manual,12.0",
          GUID = "1E1F21B6",
          NextDialogue = 12032304,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Don't talk to me like I'm a child!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F21B6"
        },
        [12032304] = {
          Camera = "5.529626,121.547981,133.878174,0.00013,-1.200856,-34.879982,35.000011,161.242813,false,Manual,2.8",
          ContentKR = "음... 그럼 아가씨라고 불러 줬으면 좋겠어?",
          DialogueId = 12032304,
          FinalCamera = "24.18462,108.543846,133.4021,0.00013,-1.200856,-34.879948,35.000015,161.242813,false,Manual,2.8",
          GUID = "1E1F21E0",
          NextDialogue = 12032305,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{211001},AnimationId{"Shy01_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Oh... would you prefer I call you ma'am, then?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F21E0"
        },
        [12032305] = {
          Camera = "150.017807,-126.066467,137.447021,0.000129,-4.200894,101.319115,28.0,338.300903,false,Manual,2.8",
          ContentKR = "아니, 당연히 아니지!",
          DialogueId = 12032305,
          FinalCamera = "156.439041,-158.144165,139.850098,0.000129,-4.200894,101.319115,28.0,338.300903,false,Manual,2.8",
          GUID = "1E1F220A",
          NextDialogue = 12032306,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Confident_End\"},Duration{1}}\n",
          SpeakNpcId = 211012,
          Subtitle = "I...I'm not that old!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F220A"
        },
        [12032306] = {
          Camera = "-91.302147,156.300644,138.539307,0.000134,-4.600863,-24.48016,35.000008,274.79599,false,Manual,12.0",
          ContentKR = "친구도 안 되고, 아가씨도 안 되면, 뭐라고 불러야 해?",
          DialogueId = 12032306,
          FinalCamera = "-78.309174,150.385452,137.390869,0.000135,-4.600863,-24.479845,35.000011,274.79599,false,Manual,12.0",
          GUID = "1E1F2234",
          NextDialogue = 12032307,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Shy01_End"},Duration{1}},
PlayAnimation{_delay{2},ActorId{211001},AnimationId{"TilteHead_Start"},Duration{1}},
PlayAnimation{_delay{2},ActorId{211001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Then... what should I call you?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2234"
        },
        [12032307] = {
          Camera = "90.149757,-15.050601,109.933594,0.000203,1.39984,114.12458,28.000008,220.298309,false,Manual,12.0",
          ContentKR = "너—— 어휴, 됐어! 특별히 너희 카론들에게 내 이름을 알려 줄게. 날 카산드라 양이라고 부르도록 해.",
          DialogueId = 12032307,
          FinalCamera = "96.089043,-28.312765,109.579102,0.000203,1.39984,114.12458,28.000008,220.298309,false,Manual,12.0",
          GUID = "1E1F225E",
          NextDialogue = 12032308,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(211012)"}},
PlayAnimation{ActorId{211012},AnimationId{"Confident_Start"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Ugh... fine! I'll be nice and tell you. My name's Cassandra — and you can call me Miss Cassandra, Charon girl.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F225E"
        },
        [12032308] = {
          Camera = "-52.819042,289.31662,211.429199,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
          ContentKR = "좋아. 안녕, 카산드라 양. 난 피나야, 만나서 반가워!",
          DialogueId = 12032308,
          FinalCamera = "-35.368748,254.650131,197.914062,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2288",
          NextDialogue = 12032309,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"TilteHead_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Talk02R_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Very well, Miss Cassandra. I'm Fina — it's lovely to meet you!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2288"
        },
        [12032309] = {
          Camera = "-35.368748,254.650131,197.914062,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
          ContentKR = "안녕. {nickname}, 이게 내 이름이야.",
          DialogueId = 12032309,
          FinalCamera = "-29.449783,242.889984,193.328857,0.000155,-19.20089,-63.279915,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F22B2",
          NextDialogue = 12032310,
          Scripts = [[
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Wave02_Start"},Duration{1}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Talk02R_End"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Hi there.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F22B2"
        },
        [12032310] = {
          Camera = "90.268677,307.583374,138.179688,0.000137,-3.600889,-93.077568,28.0,274.79599,false,Manual,12.0",
          ContentKR = "으악—— 이 무시무시한 흰 머리 애꾸는 대체 뭐야? 네 경호원이야?",
          DialogueId = 12032310,
          FinalCamera = "91.618958,332.695404,139.762695,0.00015,-3.600889,-93.077148,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F22DC",
          NextDialogue = 12032311,
          Scripts = [[
SEQ{
PARA{
LookAt{LookAtDescription{"211012:n(100001)"}},
PlayAnimation{ActorId{211012},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Wave02_End"},Duration{1}}
},
SEQ{
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Whoa! Who's this scary one with the white hair and eyepatch!? Your bodyguard?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F22DC"
        },
        [12032311] = {
          Camera = "91.618958,332.695404,139.762695,0.00015,-3.600889,-93.077148,28.000006,274.79599,false,Manual,12.0",
          ContentKR = "겁먹지 마. 유니콘 {性别:오빠|언니}는 내 친구고, 나랑 같이 널 도와주러 온 거니까! 카산드라 양, 왜 마법을 쓸 줄 아는 사람을 찾고 있어? 곤란한 일이라도 있는 거야?",
          DialogueId = 12032311,
          FinalCamera = "92.618301,351.292145,140.934814,0.00015,-3.600889,-93.07692,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2306",
          NextDialogue = 12032312,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Don't be scared — {性别:Mr|Miss} Unicorn is my friend. We're here because we want to help you. Miss Cassandra, why did you need someone who knows magic? Are you in trouble?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2306"
        },
        [12032312] = {
          Camera = "169.509918,-103.683769,140.384277,0.000153,-6.000949,114.122322,28.000008,274.79599,false,Manual,12.0",
          ContentKR = "하나도 겁 안 나거든. 난 그냥...",
          DialogueId = 12032312,
          FinalCamera = "179.292389,-125.529129,142.900146,0.000153,-6.000949,114.122322,28.000008,274.79599,false,Manual,12.0",
          GUID = "1E1F2330",
          NextDialogue = 12032313,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(211001)"}},
PlayFacial{ActorId{100001},FacialId{"None"}},
PlayAnimation{ActorId{211012},AnimationId{"Shock_End"},Duration{1}},
}]],
          SpeakNpcId = 211012,
          Subtitle = "I'm not scared! I just...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2330"
        },
        [12032313] = {
          ContentKR = "...이유를 알려 주면, 도와줄 거야?",
          DialogueId = 12032313,
          GUID = "1E1F235A",
          NextDialogue = 12032314,
          SpeakNpcId = 211012,
          Subtitle = "...If I tell you the reason, would you really help?",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F235A"
        },
        [12032314] = {
          Camera = "-120.740486,142.964783,128.572998,0.000203,-1.00024,-16.275805,28.000006,153.150421,false,Manual,12.0",
          ContentKR = "물론이지. 나쁜 일만 아니면, 우리가 힘껏 도와줄게!",
          DialogueId = 12032314,
          FinalCamera = "-89.13591,133.737701,127.997559,0.000203,-1.00024,-16.275805,28.000008,153.150421,false,Manual,12.0",
          GUID = "1E1F2384",
          NextDialogue = 12032315,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Of course! As long as it's not something bad, we'll do whatever we can!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2384"
        },
        [12032315] = {
          ContentKR = "음... 좋아. 사실, 내가 아니라 내 친구한테 곤란한 일이 생겼어.",
          DialogueId = 12032315,
          GUID = "1E1F23AE",
          NextDialogue = 12032316,
          SpeakNpcId = 211012,
          Subtitle = "Um... okay. Actually, it's not me who's in trouble — it's my friend.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F23AE"
        },
        [12032316] = {
          Camera = "203.592789,-234.095764,139.684326,0.000146,-4.000817,116.320793,28.000008,274.79599,false,Manual,12.0",
          ContentKR = "걔네 엄마는 얼마 전에 사고로 돌아가셨고, 아빠도 얼마 전에 실종되시는 바람에... 요즘 정말 힘들어하고 있거든. 그런데 학교에선 걜 놀리기까지 해. 아무도 원하지 않는 애라나...",
          DialogueId = 12032316,
          FinalCamera = "217.068558,-261.337952,141.80957,0.000146,-4.000817,116.320793,28.000008,274.79599,false,Manual,12.0",
          GUID = "1E1F23D8",
          NextDialogue = 12032317,
          Scripts = [[
SEQ{
PlayFacial{ActorId{100001},FacialId{"None"}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "His mum died in an accident, and now his dad's gone missing too... He's been really down, and now the other kids at school are picking on him. They say awful things... like he's an orphan, and nobody loves him...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F23D8"
        },
        [12032317] = {
          Camera = "-26.852451,76.142693,129.977295,0.000147,-0.800874,-16.678049,28.0,274.79599,false,Manual,12.0",
          ContentKR = "뭐? 그건 너무하잖아!",
          DialogueId = 12032317,
          GUID = "1E1F2402",
          NextDialogue = 12032318,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Sad02"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "What!? That's horrible!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2402"
        },
        [12032318] = {
          Camera = "-26.852451,76.142693,129.977295,0.000147,-0.800874,-16.678049,28.0,274.79599,false,Manual,12.0",
          ContentKR = "그래서... 마법으로 뭘 하려는 건데? 그 아이들한테 복수해 달라고?",
          DialogueId = 12032318,
          FinalCamera = "-26.852451,76.142693,133.725098,0.000153,1.59905,-52.277107,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F242C",
          NextDialogue = 12032319,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk01_Start\"},Duration{1}}\n",
          SpeakNpcId = 100001,
          Subtitle = "So... you want to use magic to get back at them?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F242C"
        },
        [12032319] = {
          Camera = "-242.433731,141.123764,141.605469,0.00018,-5.00073,-16.078661,28.0,274.79599,false,Manual,12.0",
          ContentKR = "당연히 아니지. 너넨 내성에 들어가지도 못하잖아. 그리고, 걔네 부모님들은 다 대단한 사람들이라, 까딱 잘못하면 우리가 쥐도 새도 모르게 사라져 버릴걸!",
          DialogueId = 12032319,
          FinalCamera = "-199.410095,128.722565,137.687744,0.00018,-5.00073,-16.078661,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2456",
          NextDialogue = 12032320,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"211012:n(100001)"}},
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_End"},Duration{1}},
PlayAnimation{ActorId{211012},AnimationId{"Disagree"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Nuh-uh! That wouldn't work anyway. You can't even get into the inner city. And those bullies — their families are rich and powerful. If they get mad, we're toast!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2456"
        },
        [12032320] = {
          ContentKR = "으... 내성은 그렇게 무시무시한 곳이구나...",
          DialogueId = 12032320,
          GUID = "1E1F2480",
          NextDialogue = 12032321,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Think01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Whoa... so the inner city really is a scary place...",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2480"
        },
        [12032321] = {
          Camera = "-54.569389,-159.021255,138.489502,0.000182,-1.600675,68.320656,28.0,274.79599,false,Manual,12.0",
          ContentKR = "마법을 쓸 줄 아는 카론을 찾으려고 한 건, 내 친구가 예전에 '나비 요정'을 보는 게 소원이라고 한 적이 있어서야.",
          DialogueId = 12032321,
          FinalCamera = "-47.614666,-141.681595,137.967529,0.000182,-1.600675,67.920319,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F24AA",
          NextDialogue = 12032322,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "The reason I was looking for a Charon who can use magic is... my friend once said he really wants to see a Butterfly Fairy.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F24AA"
        },
        [12032322] = {
          Camera = "-59.477188,150.637482,127.989502,0.000234,-0.800286,-34.870335,16.0,153.150421,false,Manual,12.0",
          ContentKR = "...그런 눈으로 보지 마. 꼬마도 아닌데 내가 그런 걸 믿을 줄 알아! 하지만 내 친구는 계속 '나비 요정'이 진짜 있다고 믿으니까, 걔 소원을 이뤄 주고 싶어.",
          DialogueId = 12032322,
          FinalCamera = "-68.546638,156.957001,128.143555,0.000234,-0.800286,-34.870335,16.0,153.150421,false,Manual,12.0",
          GUID = "1E1F24D4",
          NextDialogue = 12032323,
          Scripts = "PlayFacial{ActorId{100001},FacialId{\"Nervous\"}}",
          SpeakNpcId = 211012,
          Subtitle = "...Don't look at me like that! I'm not some silly little kid — I don't believe in that fairy-tale nonsense. But he does. And I just... wanted to cheer him up.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F24D4"
        },
        [12032323] = {
          ContentKR = "그치만 난 나비 요정이 어디 있는지도 모르고... 그래서... 카론이라면 마법으로 나비 요정을 만들어 낼 수 있지 않을까 해서...",
          DialogueId = 12032323,
          GUID = "1E1F24FE",
          NextDialogue = 12032324,
          SpeakNpcId = 211012,
          Subtitle = "Thing is, I've no idea where to find one... So I thought maybe... magic could summon one.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F24FE"
        },
        [12032324] = {
          Camera = "23.925068,57.94698,131.850098,0.000211,-1.400605,-16.076214,28.000011,121.007385,false,Manual,2.8",
          ContentKR = "그랬던 거구나...!",
          DialogueId = 12032324,
          FinalCamera = "39.95945,53.326424,131.442627,0.000211,-1.400605,-16.076214,28.000011,109.218246,false,Manual,2.8",
          GUID = "1E1F2528",
          NextDialogue = 12032325,
          Scripts = "PlayFacial{ActorId{100001},FacialId{\"None\"}}",
          SpeakNpcId = 211001,
          Subtitle = "I see now...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2528"
        },
        [12032325] = {
          Camera = "224.278809,-263.152527,136.943359,0.000176,-3.400635,116.920578,28.000008,274.79599,false,Manual,12.0",
          ContentKR = "흥, 비웃고 싶으면 비웃어... 어차피, 카론한테 도와달라고 하는 거로만도 엄청 창피하니까...",
          DialogueId = 12032325,
          FinalCamera = "236.240723,-286.707947,138.512939,0.000176,-3.400635,116.920578,28.000008,274.79599,false,Manual,12.0",
          GUID = "1E1F2552",
          NextDialogue = 12032326,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Confident_Start"},Duration{1}},
LookAt{LookAtDescription{"211012:n(211001)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Hmph. Go ahead and laugh. Asking a Charon for help is already embarrassing enough...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2552"
        },
        [12032326] = {
          Camera = "-34.413658,253.57933,192.084717,0.000166,-17.40048,-63.677631,28.0,274.79599,false,Manual,12.0",
          ContentKR = "왜 창피해? 친구를 생각하는 마음을 가졌다는 건, 네가 착한 사람이란 거잖아. 누구에게나 도움이 필요할 때가 있어. 서로 돕는 건 당연한 거야.",
          DialogueId = 12032326,
          FinalCamera = "-34.413658,253.57933,176.957031,0.000137,-13.80026,-64.077011,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F257C",
          NextDialogue = 12032327,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Why would that be embarrassing? Wanting to help a friend — that's a sign of kindness. Everyone needs help sometimes. That's what friends are for.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F257C"
        },
        [12032327] = {
          ContentKR = "어...?",
          DialogueId = 12032327,
          GUID = "1E1F25A6",
          NextDialogue = 12032328,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Shock_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "...Huh?",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F25A6"
        },
        [12032328] = {
          Camera = "40.453804,161.041077,120.28833,0.000161,1.999504,-53.476494,28.0,274.79599,false,Manual,12.0",
          ContentKR = "카산드라 양, 내가 도와줄게. 나한테는 동화 친구들이 잔뜩 있으니까, 나비 요정을 불러내도록 도와줄 수 있을 거야!",
          DialogueId = 12032328,
          FinalCamera = "55.666523,140.499908,121.180908,0.000161,1.999504,-53.476067,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F25D0",
          NextDialogue = 12032329,
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{ActorId{211001},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Let me help you, Miss Cassandra. I've got lots of fairy-tale friends — I'm sure one of them can help us call a Butterfly Fairy!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F25D0"
        },
        [12032329] = {
          Camera = "84.29216,-17.900318,125.307617,0.000159,-3.600363,111.523712,28.0,274.79599,false,Manual,12.0",
          ContentKR = "정말...? 진짜 도와줄 거야?",
          DialogueId = 12032329,
          FinalCamera = "79.318932,-5.290113,124.455566,0.000161,-3.600329,111.523697,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F25FA",
          NextDialogue = 12032330,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Shock_End\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Really...? You'd help me?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F25FA"
        },
        [12032330] = {
          Camera = "62.020981,146.839935,132.97998,0.000167,-1.600491,-57.275826,28.0,274.79599,false,Manual,12.0",
          ContentKR = "응!",
          DialogueId = 12032330,
          FinalCamera = "69.900589,134.576202,132.573242,0.000167,-1.600491,-57.275318,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2624",
          NextDialogue = 12032331,
          Scripts = "PlayAnimation{ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 211001,
          Subtitle = "Mhm!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2624"
        },
        [12032331] = {
          Camera = "-27.262102,270.959961,186.104004,0.000174,-15.400416,-68.075371,28.0,274.79599,false,Manual,12.0",
          ContentKR = "그럼... 돈은 얼마 주면 돼?",
          DialogueId = 12032331,
          FinalCamera = "-14.037029,238.10144,176.3479,0.000174,-15.400416,-68.075371,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F264E",
          NextDialogue = 12032332,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Blink"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Then... how much do you want?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F264E"
        },
        [12032332] = {
          Camera = "-14.037029,238.10144,176.3479,0.000174,-15.400416,-68.075371,28.000006,274.79599,false,Manual,12.0",
          ContentKR = "돈은 안 줘도 돼.",
          DialogueId = 12032332,
          FinalCamera = "-20.75071,254.782547,181.300537,0.000177,-15.400416,-68.075386,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F2678",
          NextDialogue = 12032333,
          Scripts = [[
SEQ{
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"DisagreeHead"},Duration{1}}
},
SEQ{
LookAt{LookAtDescription{"100001:n(211001)"}},
PlayFacial{ActorId{100001},FacialId{"Shy"}},
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I don't want any money.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2678"
        },
        [12032333] = {
          Camera = "245.334137,-220.686401,130.174316,0.000187,-1.400257,124.525352,28.000006,274.79599,false,Manual,12.0",
          ContentKR = "뭐...? 그건 안 돼. 네가 카론이라도, 공짜로 도움을 받을 순 없어. 돈이 싫다면, 다른 건? 사탕? 인형? 아니면 머리핀?",
          DialogueId = 12032333,
          FinalCamera = "228.133057,-195.493896,129.428467,0.000187,-1.400257,124.325394,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F26A2",
          NextDialogue = 12032334,
          SpeakNpcId = 211012,
          Subtitle = "What...? That's not how it works. Even if you're a Charon, I can't let you help me for free. If you won't take money, then... what, candy? A doll? A hair clip?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F26A2"
        },
        [12032334] = {
          Camera = "-80.740562,151.478546,130.119385,0.00019,-2.400258,-22.474829,28.0,274.79599,false,Manual,12.0",
          ContentKR = "음... 그럼, 카산드라 양이 내 친구가 돼 줬으면 좋겠어.",
          DialogueId = 12032334,
          FinalCamera = "-57.840847,142.005096,129.080811,0.00019,-2.400258,-22.474977,28.000006,274.79599,false,Manual,12.0",
          GUID = "1E1F26CC",
          NextDialogue = 12032335,
          Scripts = [[
SEQ{
PlayFacial{ActorId{211001},FacialId{"None"}},
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Um... if you really want to give me something... then I'd like you to be my friend.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F26CC"
        },
        [12032335] = {
          ContentKR = "어? 어째서...?",
          DialogueId = 12032335,
          GUID = "1E1F26F6",
          NextDialogue = 12032336,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100001:n(100001)"}},
PlayFacial{ActorId{100001},FacialId{"None"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "What? Why...?",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F26F6"
        },
        [12032336] = {
          Camera = "14.998245,105.034851,129.62207,0.000192,0.799692,-33.275356,28.0,153.150421,false,Manual,2.8",
          ContentKR = "카산드라 양은 까칠하고 화도 잘 내지만, 나한테 말을 걸어 준 첫 솔라니까! 내 친구가 돼 주면, 난 정말 기쁠 거야!",
          DialogueId = 12032336,
          FinalCamera = "37.042255,90.568626,129.345703,0.000192,-0.600285,-33.27573,28.000006,117.743881,false,Manual,2.8",
          GUID = "1E1F2720",
          NextDialogue = 12032337,
          Scripts = "PlayFacial{ActorId{211001},FacialId{\"Happy01\"}}",
          SpeakNpcId = 211001,
          Subtitle = "Even though you're kind of grumpy, and not very polite... you're the first Solarian who's taken the initiative to talk to me. If we could be friends, that would make me really happy.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2720"
        },
        [12032337] = {
          Camera = "152.708511,-67.00544,132.65918,0.000203,-4.800018,110.524124,28.000006,222.0345,false,Manual,2.8",
          ContentKR = "내가 언제... 음... 됐어. 기쁠 게 뭐가 있는진 모르겠지만, 네 친구가 돼 줄게.",
          DialogueId = 12032337,
          FinalCamera = "149.072327,-57.292805,131.78833,0.000203,-4.800018,110.524124,28.000006,222.0345,false,Manual,2.8",
          GUID = "1E1F274A",
          NextDialogue = 12032338,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Talk02_End\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "I'm not grum— ...Ugh, whatever. I don't really get why that would make you happy... But fine — we can be friends.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F274A"
        },
        [12032338] = {
          ContentKR = "대신 여기저기 자랑하고 다니지 마. 안 그럼 반 애들이 나도 놀릴 테니까...",
          DialogueId = 12032338,
          GUID = "1E1F2774",
          NextDialogue = 12032339,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Just don't go telling anyone, okay? They'd make fun of me at school...",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2774"
        },
        [12032339] = {
          Camera = "-62.638371,154.365982,124.664307,0.000202,-1.000117,-27.274698,28.000006,222.0345,false,Manual,2.8",
          ContentKR = "응, 비밀 꼭 지킬게! 그럼 어떻게 도와주면 돼? 네 친구는 내성에 있는 거지? 난 거기 못 들어가.",
          DialogueId = 12032339,
          FinalCamera = "-50.188278,147.94722,124.419922,0.000202,-1.000117,-27.274611,28.000006,222.0345,false,Manual,2.8",
          GUID = "1E1F279E",
          NextDialogue = 12032340,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I promise to keep it a secret! So... how do we help your friend? He's in the inner city, right? I can't get in there.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F279E"
        },
        [12032340] = {
          Camera = "196.052933,-242.947266,132.572754,0.0002,-1.600218,114.924568,28.0,153.150421,false,Manual,12.0",
          ContentKR = "3일 뒤에 우리 학교에서 행사가 있는데, 선생님이 우릴 갈레아 극장에 데려가실 거야. 그때 내가 친구를 몰래 데리고 나와서 널 찾아갈게! 아스포델 옆에 있는 그 통로에서 만나자.",
          DialogueId = 12032340,
          FinalCamera = "221.301102,-297.276489,134.245605,0.000202,-1.600183,114.924568,28.000006,220.298309,false,Manual,12.0",
          GUID = "1E1F27C8",
          NextDialogue = 12032341,
          SpeakNpcId = 211012,
          Subtitle = "In three days, our school's going to the Galea Theatre for an event. I'll sneak out with him then — meet us in the alley next to The Asphodel.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F27C8"
        },
        [12032341] = {
          ContentKR = "좋아, 그럼 난 그동안 나비 요정을 불러낼 마법을 연구하고 있을게.",
          DialogueId = 12032341,
          GUID = "1E1F27F2",
          NextDialogue = 12032342,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Explain02_Start"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Sounds perfect! I'll spend the next few days working on my magic — see if I can really summon a Butterfly Fairy!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F27F2"
        },
        [12032342] = {
          ContentKR = "그럼 약속한 거다! 취소하면 용서 안 해! 약속 어기면 사람 아니야!",
          DialogueId = 12032342,
          GUID = "1E1F281C",
          SpeakNpcId = 211012,
          Subtitle = "It's a deal, then. No backsies!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F281C"
        },
        [12032343] = {
          ContentKR = "카산드라가 떠난다.",
          DialogueId = 12032343,
          GUID = "1E1F2846",
          Subtitle = "Cassandra walks away",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F2846"
