          Camera = "-27.086937,207.318359,130.097656,0.00019,2.721981,-40.169811,35.0,119.172356,false,Manual,2.8",
          ContentKR = "말하기 싫으면 억지로 말 안 해도 돼. 괜찮아, 피나.",
          DialogueId = 12033007,
          GUID = "1E1F9560",
          NextDialogue = 12033008,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "It's okay, Fina. You don't have to say anything if you don't want to.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F9560"
        },
        [12033008] = {
          Camera = "-216.786224,638.707031,116.921875,0.000216,-0.677821,-70.769394,35.0,406.579437,false,Manual,2.8",
          ContentKR = "고마워, 유니콘 {性别:오빠|언니}...",
          DialogueId = 12033008,
          FinalCamera = "-211.665588,624.029297,116.75,0.000216,-0.677821,-70.769394,35.0,406.579437,false,Manual,2.8",
          GUID = "1E1F958A",
          NextDialogue = 12033009,
          SpeakNpcId = 211001,
          Subtitle = "Thank you, {性别:Mr|Miss} Unicorn...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F958A"
        },
        [12033009] = {
          Camera = "-103.942352,216.216797,150.742188,0.000137,-14.478873,152.218048,28.000006,103.690712,false,Manual,2.8",
          ContentKR = "그치만 도와주기로 해 놓고, 중간에 도망쳐 버렸어... 어떡하지...",
          DialogueId = 12033009,
          GUID = "1E1F95B4",
          NextDialogue = 12033010,
          SpeakNpcId = 211001,
          Subtitle = "But... I ran away. I promised to help Cassandra — and I just ran. What should I do...?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F95B4"
        },
        [12033010] = {
          Camera = "-84.477493,229.648438,149.128906,0.000138,-4.679171,-33.583679,55.000008,174.406815,false,Manual,2.8",
          ContentKR = "걱정하지 마. 그건 나한테 맡겨. 난 월석 사냥꾼이잖아. 의뢰를 완수하는 건 내 전문이야.",
          DialogueId = 12033010,
          FinalCamera = "-73.702179,222.496094,148.070312,0.000138,-4.679171,-33.583744,55.000008,158.766953,false,Manual,2.8",
          GUID = "1E1F95DE",
          NextDialogue = 12033011,
          Scripts = [[
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Don't worry. Leave this one to me. I'm a Phoxhunter — finishing tough jobs is what I do best.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F95DE"
        },
        [12033011] = {
          Camera = "108.718094,134.107422,142.527344,0.000134,-3.278443,166.01561,28.000006,316.033936,false,Manual,2.8",
          ContentKR = "...응! 그럼 나 대신 카산드라 양한테 미안하다고도...",
          DialogueId = 12033011,
          GUID = "1E1F9608",
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Stop"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0051_story_danger"}},
LookAt{LookAtDescription{"211001:n(100001)"}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"Talk02_End"},Duration{1}}
}
]],
          SpeakNpcId = 211001,
          Subtitle = "Okay...! But could you maybe say sorry to Miss Cassandra for me—?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F9608"
        },
        [12033012] = {
          Content = "敲门声",
          DialogueId = 12033012,
          GUID = "1E1F9609"
        },
        [12033101] = {
          Camera = "321.198364,-231.621094,114.386719,0.000126,2.827363,109.062408,35.000008,180.208557,false,DoNotOverride,6.0",
          ContentKR = "어...? 누구지?",
          DialogueId = 12033101,
          GUID = "1E1FA4CC",
          NextDialogue = 12033102,
          Scripts = [[
PARA{
SEQ{
MoveTo{ActorId{211001},MoveSpeed{80},TargetPoint{"pFeina_FixSimple04_Moveto"}},
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{"Explain02_Start"}},
},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Disappoint01"}},
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Hmm? Who could that be...?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FA4CC"
        },
        [12033102] = {
          Camera = "345.997009,-2.503906,147.578125,0.000145,-10.572681,-123.136963,35.000008,116.474312,false,DoNotOverride,6.0",
          ContentKR = "피나 언니, 안에 있어? 내성에서 온 어떤 예쁜 꼬마가 언닐 찾아!",
          DialogueId = 12033102,
          GUID = "1E1FA4F6",
          NextDialogue = 12033103,
          SpeakNpcId = 211011,
          Subtitle = "Fina! Are you home? A pretty girl from the inner city wants to see you!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FA4F6"
        },
        [12033103] = {
          ContentKR = "피나? 피나, 나야, 빨리 문 열어! 큰일 났어!",
          DialogueId = 12033103,
          GUID = "1E1FA520",
          SpeakNpcId = 211012,
          Subtitle = "Fina? Fina, it's me — open the door! Something awful just happened!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FA520"
        },
        [12033104] = {
          Content = "主角开门，门外站着卡珊德拉，后面跟着三小孩（芙蕾达、珂芮，戴维）",
          DialogueId = 12033104,
          GUID = "1E1FA521"
        },
        [12033201] = {
          Camera = "-293.495544,461.670685,188.538086,0.000028,-22.599463,-82.803284,13.080084,434.859222,false,Manual,22.0",
          ContentKR = "무슨 일이야?",
          DialogueId = 12033201,
          FinalCamera = "-291.470306,445.629303,181.808105,0.000028,-22.599463,-82.803284,13.080084,434.859222,false,Manual,22.0",
          GUID = "1E1FB50A",
          NextDialogue = 12033202,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211012)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(211012)"}},
LookAt{_delay{0},LookAtDescription{"211010:n(211012)"}},
LookAt{_delay{0.2},LookAtDescription{"211012:n(211012)"}},
LookAt{_delay{0.7},LookAtDescription{"211011:n(211012)"}},
LookAt{_delay{0.6},LookAtDescription{"211013:n(211012)"}},
PlayAnimation{_delay{0},ActorId{211012},AnimationId{"Sigh_Start"}},
PlayFacial{ActorId{211012},FacialId{"CM_Sad01"}},
SetLocation{ActorId{211001},TargetPoint{"feina_31_hide"},Visibility{"Hide"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "What's wrong?",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FB50A"
        },
        [12033202] = {
          Camera = "-195.357635,106.520752,127.771973,0.000041,-13.999544,116.397713,13.080085,123.93045,false,Manual,4.0",
          ContentKR = "세비오가 없어졌어!",
          DialogueId = 12033202,
          GUID = "1E1FB534",
          NextDialogue = 12033203,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0051_story_danger"}},
PlayAnimation{_delay{0},ActorId{211012},AnimationId{"Sigh_End"}}, 
PlayAnimation{_delay{3},ActorId{211012},AnimationId{"Talk02_Start"}},
}]],
          SpeakNpcId = 211012,
          Subtitle = "It's Savio — he's gone! I can't find him anywhere!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FB534"
        },
        [12033203] = {
          Camera = "-206.954987,162.348816,128.731934,0.000059,4.800099,-85.600464,35.0,123.930466,false,Manual,4.0",
          ContentKR = "뭐...? 어떻게 된 거야? 언제 없어졌는데?",
          DialogueId = 12033203,
          GUID = "1E1FB55E",
          NextDialogue = 12033204,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{100001},AnimationId{"Shock03_Start"}},
PlayFacial{ActorId{100001},FacialId{"Shock01"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "What? When did this happen?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FB55E"
        },
        [12033204] = {
          Camera = "-139.243134,14.521248,143.611816,0.000146,-15.199629,127.008095,18.0,272.20813,false,Manual,4.0",
          ContentKR = "조금 전에! 너네를 쫓아가다가 뒤를 돌아봤는데 안 보이는 거야! 극장 쪽도 찾아봤는데, 다들 못 봤대. 훌쩍, 어떡해...",
          DialogueId = 12033204,
          GUID = "1E1FB588",
          NextDialogue = 12033205,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211012},AnimationId{"Talk02_End"}}, 
}]],
          SpeakNpcId = 211012,
          Subtitle = "Just now. I was following you two for a bit, and then... I turned around, and he was gone! I searched around the theatre, but no one saw him come back. Waaaah... what do I do...!?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FB588"
        },
        [12033205] = {
          Camera = "-265.27298,259.746368,105.448242,0.000154,-1.199613,-84.593338,18.0,272.20813,false,Manual,4.0",
          ContentKR = "진정해. 어린애 혼자서 멀리 가진 못했을 거야. 우선 이 근처부터 찾아보자.",
          DialogueId = 12033205,
          GUID = "1E1FB5B2",
          NextDialogue = 12033206,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{100001},AnimationId{"Shock03_End"}}, 
PlayAnimation{_delay{0},ActorId{100001},AnimationId{"Talk01_Start"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Don't panic. He can't have gone far. Let's start by checking the area.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FB5B2"
        },
        [12033206] = {
          Camera = "24.507023,19.049276,123.163574,0.00017,-5.999515,-139.785721,25.0,272.20813,false,Manual,22.0",
          DialogueId = 12033206,
          GUID = "1E1FB5DC",
          NextDialogue = 12033301,
          Scripts = [[
PARA{
MoveTo{ActorId{211001},TargetPoint{"feina_31_walk"},MoveSpeed{120},Visibility{"Show"}},
CameraMoveTo{_delay{1},TargetPosition{"-90.753601,152.936554,136.99707,0.00018,-0.000061,-120.984047,18.0,64.156151,false,Manual,4.0"},duration{0}}
}
]],
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FB5DC"
        },
        [12033301] = {
          Camera = "-256.25235,34.504696,138.248535,0.000103,-1.801387,19.109745,35.000008,164.538193,false,Manual,4.0",
          ContentKR = "나도 같이 찾을게.",
          DialogueId = 12033301,
          GUID = "1E1FC572",
          NextDialogue = 12033302,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211001)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(100001)"}},
LookAt{_delay{0},LookAtDescription{"211010:n(211001)"}},
LookAt{_delay{0.2},LookAtDescription{"211012:n(211001)"}},
LookAt{_delay{0.7},LookAtDescription{"211011:n(211001)"}},
LookAt{_delay{0.6},LookAtDescription{"211013:n(211001)"}},
PlayAnimation{_delay{0},ActorId{211001},AnimationId{"Explain02_Start"}},
}]],
          SpeakNpcId = 211001,
          Subtitle = "I want to help too.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC572"
        },
        [12033302] = {
          Camera = "-90.753601,152.936554,136.99707,0.00018,-0.000061,-120.984047,18.0,64.156151,false,Manual,4.0",
          ContentKR = "피나, 넌...",
          DialogueId = 12033302,
          GUID = "1E1FC59C",
          NextDialogue = 12033303,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Talk01_End\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Fina...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC59C"
        },
        [12033303] = {
          Camera = "-256.25235,34.504696,138.248535,0.000103,-1.801387,19.109745,35.000008,164.538193,false,Manual,4.0",
          ContentKR = "내가 도망쳐서 일이 이렇게 된 거잖아... 게다가... 게다가 세비오는... 나 때문에...",
          DialogueId = 12033303,
          GUID = "1E1FC5C6",
          NextDialogue = 12033304,
          Scripts = "PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Explain02_End\"}},",
          SpeakNpcId = 211001,
          Subtitle = "This happened because I ran away... And it's also because of me that he... he—",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC5C6"
        },
        [12033304] = {
          Camera = "-76.54538,161.461548,133.384277,0.000121,-0.20218,-129.285965,35.000011,164.538193,false,Manual,4.0",
          ContentKR = "...그래, 알겠어. 다 같이 가서 찾자. 대신 나한테서 너무 멀리 떨어지면 안 돼.",
          DialogueId = 12033304,
          GUID = "1E1FC5F0",
          NextDialogue = 12033305,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{100001},AnimationId{"AgreeHead"}},
PlayFacial{ActorId{100001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...Alright. We'll search together. Just don't wander too far from me, okay?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC5F0"
        },
        [12033305] = {
          Camera = "-96.779709,-151.616333,144.003418,0.000136,-5.001925,104.710579,50.0,242.830399,false,Manual,1.0",
          ContentKR = "어? 지금 누구 찾으러 가는 거야? 그럼 나도 도울래!",
          DialogueId = 12033305,
          FinalCamera = "-96.779709,-151.616333,144.003418,0.000136,-5.001925,104.710579,50.0,560.6521,false,Manual,4.0",
          GUID = "1E1FC61A",
          NextDialogue = 12033306,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211011)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(211011)"}},
LookAt{_delay{0},LookAtDescription{"211010:n(211011)"}},
LookAt{_delay{0.2},LookAtDescription{"211012:n(100001)"}},
LookAt{_delay{0.7},LookAtDescription{"211011:n(100001)"}},
LookAt{_delay{0.6},LookAtDescription{"211013:n(211011)"}},
}]],
          SpeakNpcId = 211011,
          Subtitle = "You're looking for someone? I'll help!",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC61A"
        },
        [12033306] = {
          ContentKR = "나도...!",
          DialogueId = 12033306,
          GUID = "1E1FC644",
          NextDialogue = 12033307,
          Scripts = "LookAt{_delay{0.6},LookAtDescription{\"211013:n(100001)\"}}",
          SpeakNpcId = 211013,
          Subtitle = "Me too!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC644"
        },
        [12033307] = {
          Camera = "-214.859619,538.500977,141.89502,0.000199,-5.601991,-88.089539,35.0,560.6521,false,Manual,4.0",
          ContentKR = "꼬마 친구들은 여기서 얌전히 기다리고 있어.",
          DialogueId = 12033307,
          GUID = "1E1FC66E",
          NextDialogue = 12033308,
          Scripts = "PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Confident_Start\"}}",
          SpeakNpcId = 100001,
          Subtitle = "You two kids stay here.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC66E"
        },
        [12033308] = {
          Camera = "-151.192551,-29.119432,139.736328,0.000225,-6.202235,101.306007,35.000008,560.6521,false,Manual,22.0",
          ContentKR = "왜 어린애라고 무시하는데! 우린 아이스레이크 시티에서 10년 동안 먹보 게임을 했단 말이야. 우리가 못 찾는 사람은 없어! 없어졌다는 앤 어떻게 생겼는데? 빨리 말해 봐!",
          DialogueId = 12033308,
          GUID = "1E1FC698",
          NextDialogue = 12033309,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211011},AnimationId{"Talk03_Start"}},
PlayFacial{ActorId{211011},FacialId{"CM_Angry01"}}
}]],
          SpeakNpcId = 211011,
          Subtitle = "Hey! Don't underestimate us! We're Greedy Gobbler pros — undefeated in Icelake for ten years! We never miss! Now — what does this missing kid look like?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC698"
        },
        [12033309] = {
          Camera = "-283.217163,387.314117,81.605469,0.000261,5.997555,-75.884804,35.000015,341.991852,false,Manual,4.0",
          ContentKR = "남자애고, 키는 이만해. 하얀색 단발머리에, 눈은 초록색이야. 나랑 똑같은 교복을 입고 있어.",
          DialogueId = 12033309,
          GUID = "1E1FC6C2",
          NextDialogue = 12033310,
          Scripts = [[
PARA{
PlayAnimation{_delay{0},ActorId{211012},AnimationId{"Explain02_Start"}},
LookAt{_delay{0.5},LookAtDescription{"100001:n(211012)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(211012)"}},
PlayAnimation{_delay{0},ActorId{211011},AnimationId{"Talk03_End"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "He's about this tall, white hair, green eyes — same school uniform as mine.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC6C2"
        },
        [12033310] = {
          Camera = "-259.942474,67.673576,90.111328,0.000218,6.797206,91.514595,35.000008,341.991852,false,Manual,4.0",
          ContentKR = "흐음... 그럼 둘이 어디서 길이 엇갈린 거야?",
          DialogueId = 12033310,
          GUID = "1E1FC6EC",
          NextDialogue = 12033311,
          Scripts = "PlayFacial{_delay{2},ActorId{211011},FacialId{\"CM_Idle\"}}",
          SpeakNpcId = 211011,
          Subtitle = "Got it. Where did you last see him?",
          TurnTo = {
            [1] = "211011:n(211012)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC6EC"
        },
        [12033311] = {
          ContentKR = "주점 근처에 있는 골목 근처에서.",
          DialogueId = 12033311,
          GUID = "1E1FC716",
          NextDialogue = 12033312,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{211012},AnimationId{"Explain02_End"}},
TurnTo{_delay{1},TurnToDescription{"211012:n(211011)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "In the alley by the tavern.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC716"
        },
        [12033312] = {
          Camera = "-438.694794,219.296844,103.061523,0.000218,1.397532,20.50848,25.0,560.6521,false,Manual,4.0",
          ContentKR = "아까 나랑 데이비가 거기 입구에서 돌멩이 쌓으면서 놀고 있었는데, 네가 말한 남자애는 못 봤어.",
          DialogueId = 12033312,
          GUID = "1E1FC740",
          NextDialogue = 12033313,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211011)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(211011)"}},
LookAt{_delay{0},LookAtDescription{"211010:n(211011)"}},
LookAt{_delay{0.2},LookAtDescription{"211012:n(211010)"}},
LookAt{_delay{0.7},LookAtDescription{"211011:n(211010)"}},
LookAt{_delay{0.6},LookAtDescription{"211013:n(211010)"}},
}]],
          SpeakNpcId = 211010,
          Subtitle = "Davy and I were stacking pebbles near there just now. I didn't see any kid like that.",
          TurnTo = {
            [1] = "211010:n(211012)",
            [2] = "211013:n(211010)"
          },
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC740"
        },
        [12033313] = {
          ContentKR = "나도 못 봤어...",
          DialogueId = 12033313,
          GUID = "1E1FC76A",
          NextDialogue = 12033314,
          Scripts = "PlayAnimation{_delay{0},ActorId{211013},AnimationId{\"Talk01_Start\"}},",
          SpeakNpcId = 211013,
          Subtitle = "Me neither...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC76A"
        },
        [12033314] = {
          Camera = "-115.656433,-8.532393,142.876465,0.000173,-11.202848,117.306786,18.0,433.05719,false,Manual,4.0",
          ContentKR = "그럼 골목 밖으로 갔을 거야.",
          DialogueId = 12033314,
          GUID = "1E1FC794",
          NextDialogue = 12033315,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211011)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(211011)"}},
LookAt{_delay{0},LookAtDescription{"211010:n(211011)"}},
LookAt{_delay{0.2},LookAtDescription{"211012:n(211011)"}},
LookAt{_delay{0.7},LookAtDescription{"211011:n(211011)"}},
LookAt{_delay{0.6},LookAtDescription{"211013:n(211011)"}},
}]],
          SpeakNpcId = 211011,
          Subtitle = "Then he must've run off the other way.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC794"
        },
        [12033315] = {
          ContentKR = "아, 맞다... 저쪽 길목에 세워져 있는 차에 마크가 맨날 몰래 들어가서 빵빵거리고 놀거든. 걔가 오늘도 거기 있었다면, 뭔가 보지 않았을까?",
          DialogueId = 12033315,
          GUID = "1E1FC7BE",
          NextDialogue = 12033316,
          Scripts = "PlayAnimation{_delay{0},ActorId{211013},AnimationId{\"Talk01_End\"}}",
          SpeakNpcId = 211013,
          Subtitle = "Oh! I just remembered — there was a car parked at the junction by the tavern! Mark always sneaks in and honks the horn. If he was there today, maybe he saw something!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC7BE"
        },
        [12033316] = {
          ContentKR = "그럼 가서 물어보자!",
          DialogueId = 12033316,
          GUID = "1E1FC7E8",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0051_story_danger\"}}",
          SpeakNpcId = 211011,
          Subtitle = "Good thinking! Let's go and ask him!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC7E8"
        },
        [12033317] = {
          ContentKR = "아이들이 달려간다.\n아스포델 입구의 차량 옆으로 이동하면, 카산드라와 세 아이, 그리고 새로운 아이(마크)가 함께 모여 있다.",
          DialogueId = 12033317,
          GUID = "1E1FC812",
          Subtitle = [[
The children rush off
Cut: Near the vehicle by The Asphodel
Cassandra, Freda, Kori, Davy, and a new kid (Mark) are gathered]],
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FC812"
        },
        [12033401] = {
          Camera = "-105.724152,605.271057,208.438477,0.00007,-13.321648,-104.470268,35.000011,453.640076,false,DoNotOverride,12.0",
          ContentKR = "어? 다들 왜 나와 있어? 마침 같이 놀자고 부르러 가려고 했는데!",
          DialogueId = 12033401,
          FinalCamera = "-89.904701,598.424988,208.438477,0.000069,-13.321682,-107.869789,35.000011,453.640076,false,DoNotOverride,12.0",
          GUID = "1E1FD5DA",
          NextDialogue = 12033402,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"100001:n(211014)"}},
LookAt{_delay{1},LookAtDescription{"211001:n(211014)"}},
LookAt{_delay{0},LookAtDescription{"211010:n(211014)"}},
LookAt{_delay{0.2},LookAtDescription{"211012:n(211014)"}},
LookAt{_delay{0.7},LookAtDescription{"211011:n(211014)"}},
LookAt{_delay{0.6},LookAtDescription{"211013:n(211014)"}},
PlayAnimation{_delay{0.5},ActorId{211014},AnimationId{"Talk03_Start"}}
}]],
          SpeakNpcId = 211014,
          Subtitle = "Huh? What's going on? I was just coming to play with you guys!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD5DA"
        },
        [12033402] = {
          Camera = "-450.762573,18.759333,154.709473,0.000131,-11.121706,41.12257,35.000011,316.938934,false,DoNotOverride,3.5",
          ContentKR = "우리 사람을 찾고 있어.",
          DialogueId = 12033402,
          GUID = "1E1FD604",
          NextDialogue = 12033403,
          Scripts = [[
PARA{
LookAt{_delay{0.6},LookAtDescription{"211014:n(211010)"}},
PlayAnimation{_delay{0.5},ActorId{211010},AnimationId{"Explain01_Start"}},
PlayAnimation{_delay{1},ActorId{211014},AnimationId{"Talk03_End"}}
}]],
          SpeakNpcId = 211010,
          Subtitle = "We're looking for someone.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD604"
        },
        [12033403] = {
          Camera = "-76.398384,420.032104,170.840576,0.000102,-13.921988,-126.06813,35.000015,689.353516,false,DoNotOverride,12.0",
          ContentKR = "뭐?! 설마 너네... 나 빼고 먹보 게임 하는 거야?",
          DialogueId = 12033403,
          GUID = "1E1FD62E",
          NextDialogue = 12033404,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.2},ActorId{211014},AnimationId{"Shock_Start"}},
PlayAnimation{_delay{4},ActorId{211014},AnimationId{"Shock_End"}}
}]],
          SpeakNpcId = 211014,
          Subtitle = "Wait—what!? You're playing Greedy Gobbler without me!?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD62E"
        },
        [12033404] = {
          Camera = "-190.92775,502.22348,189.769531,0.000107,-13.321833,-95.471069,35.000011,689.353516,false,DoNotOverride,12.0",
          ContentKR = "그게 아니라, 이 예쁜 애가 사람 찾는 걸 도와주고 있어. 얘랑 똑같은 교복을 입은 남자애래.",
          DialogueId = 12033404,
          GUID = "1E1FD658",
          NextDialogue = 12033405,
          Scripts = [[
SEQ{
PARA{
PlayAnimation{_delay{0.5},ActorId{211011},AnimationId{"Disagree"}},
PlayAnimation{_delay{0.5},ActorId{211010},AnimationId{"Explain01_End"}}
},
LookAt{_delay{0.2},LookAtDescription{"211011:n(211014)"}}
}]],
          SpeakNpcId = 211011,
          Subtitle = "No, silly! We're helping this pretty girl find someone — a boy wearing the same school uniform as her.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD658"
        },
        [12033405] = {
          ContentKR = "이 근처에서 길을 잃었을 거 같은데, 혹시 기억나는 거 없어?",
          DialogueId = 12033405,
          GUID = "1E1FD682",
          NextDialogue = 12033406,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{211011},AnimationId{\"Talk02_Start\"}}",
          SpeakNpcId = 211011,
          Subtitle = "We think he went missing nearby. Did you see anyone like that?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD682"
        },
        [12033406] = {
          Camera = "-184.196564,208.952484,88.146484,0.000141,7.678321,-144.26712,35.000011,198.340698,false,DoNotOverride,12.0",
          ContentKR = "아! 그 하얀 머리 남자애 맞지? 나 걔 봤어!",
          DialogueId = 12033406,
          GUID = "1E1FD6AC",
          NextDialogue = 12033407,
          Scripts = [[
PARA{
SEQ{
PlayAnimation{_delay{0.5},ActorId{211014},AnimationId{"Think_Start"}},
PlayAnimation{_delay{2.5},ActorId{211014},AnimationId{"Think_End"}},
PlayAnimation{_delay{1},ActorId{211014},AnimationId{"Agree"}}
},
PlayAnimation{_delay{0.5},ActorId{211011},AnimationId{"Talk02_End"}}
}]],
          SpeakNpcId = 211014,
          Subtitle = "Oh! A white-haired boy, right? Yeah, I saw him!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD6AC"
        },
        [12033407] = {
          ContentKR = "차에서 빵빵거리면서 놀고 있었는데, 걔가 지나가다가 소릴 듣고 깜짝 놀라서 펄쩍 뛰는 거야! 미안하다고 말하려고 차에서 내리니까, 벌써 멀리 가 버렸더라고...",
          DialogueId = 12033407,
          GUID = "1E1FD6D6",
          NextDialogue = 12033408,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{211014},AnimationId{"Talk03_Start"}},
PlayAnimation{_delay{3},ActorId{211014},AnimationId{"Talk03_End"}},
PlayAnimation{_delay{3.5},ActorId{211014},AnimationId{"Sigh_Start"}},
PlayAnimation{_delay{3},ActorId{211014},AnimationId{"Sigh_End"}},
}]],
          SpeakNpcId = 211014,
          Subtitle = "I was messing around in the car, honking the horn, and he walked past. The noise gave him a good scare — he nearly jumped out of his shoes! I wanted to say sorry, but by the time I got down, he was already gone.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD6D6"
        },
        [12033408] = {
          Camera = "-145.854355,386.006195,242.959961,0.000151,-26.721802,-114.066803,35.000011,198.340698,false,DoNotOverride,12.0",
          ContentKR = "뭐라고? 어느 쪽으로 갔는데?!",
          DialogueId = 12033408,
          GUID = "1E1FD700",
          NextDialogue = 12033409,
          Scripts = [[
PARA{
LookAt{_delay{0.5},LookAtDescription{"211014:n(211012)"}},
SEQ{
MoveTo{ActorId{211012},TargetPoint{"Feinafx33moveto01"},MoveSpeed{100},Visibility{"Show"}},
PlayAnimation{_delay{0.5},ActorId{211012},AnimationId{"Confident_Start"}}
}
}]],
          SpeakNpcId = 211012,
          Subtitle = "What!? Which way did he go!?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD700"
        },
        [12033409] = {
          ContentKR = "성문 쪽으로. 혼자서 성문을 지나갈 생각을 하다니, 내성에 사는 애들은 진짜 용감하다니까.",
          DialogueId = 12033409,
          GUID = "1E1FD72A",
          NextDialogue = 12033410,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{211014},AnimationId{"Talk02_Start"}},
PlayAnimation{_delay{5},ActorId{211014},AnimationId{"Talk02_End"}}
}]],
          SpeakNpcId = 211014,
          Subtitle = "Towards the city gate. I couldn't believe it — he actually went off on his own! Inner city kids sure are gutsy...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD72A"
        },
        [12033410] = {
          Camera = "-429.89566,116.990479,117.795654,0.000124,-1.722382,0.522152,35.000011,202.363037,false,DoNotOverride,2.8",
          ContentKR = "성문...? 여기서 내성으로 가는 성문 말하는 거야, 아니면...",
          DialogueId = 12033410,
          GUID = "1E1FD754",
          NextDialogue = 12033411,
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{211012},AnimationId{"Confident_End"}},
LookAt{_delay{0.5},LookAtDescription{"211012:n(211011)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "City gate... you mean the gate to the inner city?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD754"
        },
        [12033411] = {
          Camera = "-138.852493,413.402557,174.547852,0.000144,-10.322205,-112.074112,35.000011,360.37265,false,DoNotOverride,2.8",
          ContentKR = "당연히 성 밖으로 나가는 성문이지. 난 내성으로 가는 성문은 무서워서 보지도 못해.",
          DialogueId = 12033411,
          FinalCamera = "-138.852493,413.402557,174.547852,0.000148,-12.722095,-116.674217,35.000011,360.37265,false,DoNotOverride,2.8",
          GUID = "1E1FD77E",
          NextDialogue = 12033412,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{211014},AnimationId{"Talk01_Start"}},
PlayAnimation{_delay{3},ActorId{211014},AnimationId{"Talk01_End"}}
}]],
          SpeakNpcId = 211014,
          Subtitle = "Nuh-uh. The main gate. No way I'd stare at the inner city gate — I'd get in trouble.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD77E"
        },
        [12033412] = {
          Camera = "-237.754028,239.283752,119.808838,0.000117,-0.121919,-71.676437,35.000011,86.998222,false,DoNotOverride,2.8",
          ContentKR = "뭐...? 왜 그렇게 위험한 곳에... 이제 어떡하면 좋아...",
          DialogueId = 12033412,
          FinalCamera = "-237.754028,239.283752,119.808838,0.000117,-0.121919,-71.676437,35.000011,212.450943,false,DoNotOverride,3.2",
          GUID = "1E1FD7A8",
          NextDialogue = 12033413,
          Scripts = [[
SEQ{
PARA{
LookAt{_delay{0.5},LookAtDescription{"211001:n(211012)"}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Sad02"}}
},
LookAt{_delay{0.5},LookAtDescription{"211012:n(211014)"}}}]],
          SpeakNpcId = 211012,
          Subtitle = "Oh no... that's way too dangerous. What do we do...!?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD7A8"
        },
        [12033413] = {
          ContentKR = "음? 아, 그래! '월석 사냥꾼'을 고용해서 성 밖에 나가서 찾을 동안 우릴 호위해 달라고 하자! 돈만 많이 주면 뭐든지 해 준대!",
          DialogueId = 12033413,
          GUID = "1E1FD7D2",
          NextDialogue = 12033414,
          Scripts = [[
SEQ{
PARA{
LookAt{_delay{0.5},LookAtDescription{"211012:n(211001)"}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Shock01"}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Talk03_Start"}}
},
PlayAnimation{_delay{2},ActorId{211012},AnimationId{"Talk02_Start"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Wait — I know! We'll hire a Phoxhunter to take us outside the city! I hear they'll do anything — as long as you pay enough!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD7D2"
        },
        [12033414] = {
          Camera = "-371.668549,102.6278,152.601807,0.000084,-9.521973,1.526568,35.000011,259.37915,false,DoNotOverride,3.5",
          ContentKR = "유니콘 {性别:오빠|언니}가 바로 월석 사냥꾼이야! 게다가 월석 사냥꾼 중에서도 엄청 세!",
          DialogueId = 12033414,
          GUID = "1E1FD7FC",
          NextDialogue = 12033415,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{211012},AnimationId{"Talk02_End"}},
PARA{
PlayFacial{_delay{0.5},ActorId{100001},FacialId{"Smile01"}}
},
SEQ{
LookAt{_delay{0.5},LookAtDescription{"211001:n(211012)"}},
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{"Explain02_Start"}}
},
SEQ{
TurnTo{_delay{0},TurnToDescription{"211011:n(100001)"}},
LookAt{_delay{0.5},LookAtDescription{"211011:n(100001)"}}
},
SEQ{
TurnTo{_delay{0},TurnToDescription{"211013:n(100001)"}},
LookAt{_delay{0.5},LookAtDescription{"211013:n(100001)"}}
},
SEQ{
TurnTo{_delay{0},TurnToDescription{"211013:n(100001)"}},
LookAt{_delay{0.5},LookAtDescription{"211013:n(100001)"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "{性别:Mr|Miss} Unicorn is a Phoxhunter! And a really amazing one!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD7FC"
        },
        [12033415] = {
          Camera = "-296.6315,90.475662,114.222412,0.000088,5.677895,23.727402,35.000011,177.889099,false,DoNotOverride,3.5",
          ContentKR = "어?! 그, 그럼 같이 찾으러 가 주라! 부탁할게. 그리고 아무개, 아니, {nickname} {性别:오빠|언니}! 보수도 줄게!",
          DialogueId = 12033415,
          FinalCamera = "-296.6315,90.475662,114.222412,0.000088,5.07789,27.32766,35.000011,177.889099,false,DoNotOverride,3.5",
          GUID = "1E1FD826",
          NextDialogue = 12033416,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{"Explain02_End"}},
LookAt{_delay{0.5},LookAtDescription{"100001:n(211012)"}},
SEQ{
TurnTo{_delay{0},TurnToDescription{"211012:n(100001)"}},
LookAt{_delay{0.5},LookAtDescription{"211012:n(100001)"}}
}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Really!? You are? Then can you help me look for Savio? I'll pay you! Please, Eyepa— Uh, I mean, {性别:Mr|Miss} !",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD826"
        },
        [12033416] = {
          Camera = "-296.6315,90.475662,114.222412,0.000088,5.07789,27.32766,35.000011,177.889099,false,DoNotOverride,3.5",
          ContentKR = "...그래, 피나를 봐서라도 네 의뢰를 받아 줄게.",
          DialogueId = 12033416,
          GUID = "1E1FD850",
          NextDialogue = 12033417,
          Scripts = [[
SEQ{
PARA{
PlayFacial{_delay{0.5},ActorId{100001},FacialId{"Close"}},
PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{"Talk03_End"}}
},
PARA{
PlayFacial{_delay{3},ActorId{100001},FacialId{"Smile01"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "...Alright. For Fina's sake, I'll take the job.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD850"
        },
        [12033417] = {
          Camera = "-151.644821,327.130096,181.968506,0.000056,-15.922331,-98.076088,35.000011,227.608078,false,DoNotOverride,2.8",
          ContentKR = "그럼 우리도...",
          DialogueId = 12033417,
          FinalCamera = "-157.182602,288.441681,171.730225,0.000059,-14.522272,-98.075798,35.000011,396.708557,false,DoNotOverride,2.8",
          GUID = "1E1FD87A",
          NextDialogue = 12033418,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{211011},AnimationId{\"Confident_Start\"}}",
          SpeakNpcId = 211011,
          Subtitle = "Then let's—",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD87A"
        },
        [12033418] = {
          Camera = "-232.455872,62.259274,137.736328,0.000081,-0.522277,39.522854,35.000011,130.079315,false,DoNotOverride,2.8",
          ContentKR = "이번엔 정말 따라오면 안 돼. 성 밖은 지형이 복잡해서, 나 혼자 너희 모두를 챙기는 건 불가능해.",
          DialogueId = 12033418,
          FinalCamera = "-220.870056,57.896755,137.674805,0.000081,1.077715,45.921753,35.000011,130.079315,false,DoNotOverride,2.8",
          GUID = "1E1FD8A4",
          NextDialogue = 12033419,
          Scripts = [[
PARA{
PlayFacial{_delay{1},ActorId{100001},FacialId{"Beg"}},
LookAt{_delay{0.5},LookAtDescription{"100001:n(211011)"}},
SEQ{
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"DisagreeHead"}},
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Talk02_Start"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Not this time. It's dangerous beyond the gates, and I can't watch over all of you.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD8A4"
        },
        [12033419] = {
          Camera = "-312.716248,-126.369667,120.318848,0.00011,-1.122282,47.925896,35.000011,246.67305,false,DoNotOverride,12.0",
          ContentKR = "으... 알겠어. 성 밖은 우리가 잘 모르니까, 이쯤에서 포기할게.",
          DialogueId = 12033419,
          GUID = "1E1FD8CE",
          NextDialogue = 12033420,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{211011},AnimationId{"Confident_End"}},
PlayAnimation{_delay{0.5},ActorId{211011},AnimationId{"Disagree"}}
}]],
          SpeakNpcId = 211011,
          Subtitle = "Aw... fine. We don't know the area anyway. Guess we're benched for this one...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FD8CE"
        },
        [12033420] = {
          Camera = "-239.750458,-5.53299,128.551025,0.000122,0.877618,48.124439,35.000011,178.3181,false,DoNotOverride,2.8",
          ContentKR = "피나, 너도 여기 남...",
          DialogueId = 12033420,
          FinalCamera = "-224.170609,-19.498493,128.551025,0.000122,0.877618,48.124439,35.000011,96.430061,false,DoNotOverride,6.0",
          GUID = "1E1FD8F8",
          NextDialogue = 12033421,
          Scripts = [[
PARA{
