        [12033501] = {
          ContentKR = "이렇게 찾는 건 비효율적이야... 카산드라, 세비오가 갔을 만한 곳이라든가, 성 밖으로 나가려고 한 이유가 뭔지 짐작 가는 거 없어?",
          DialogueId = 12033501,
          GUID = "1E1FE642",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033502,
          SpeakNpcId = 100001,
          Subtitle = "Searching blindly won't help... Cassandra, can you think of anywhere Savio might go? Why would he even leave the city?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE642"
        },
        [12033502] = {
          ContentKR = "음... 어쩌면 나비를 찾으러 간 걸지도 몰라. 며칠 전에 수업 때 선생님이 눈물의 호수 근처에 나비가 살고 있다고 그러셨는데, 그때 세비오가 질문을 엄청 많이 했었거든...",
          DialogueId = 12033502,
          GUID = "1E1FE66C",
          NextDialogue = 12033503,
          SpeakNpcId = 211012,
          Subtitle = "Umm... maybe he went to look for butterflies. A few days ago in class, the teacher said they live near Lamenting Lake. He wouldn't stop asking about it...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE66C"
        },
        [12033503] = {
          ContentKR = "세비오는 왜 그렇게 나비를 좋아하는 거야? 나비랑 관련된 동화 같은 거 때문이야?",
          DialogueId = 12033503,
          GUID = "1E1FE696",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033504,
          SpeakNpcId = 100001,
          Subtitle = "Why's he so obsessed with butterflies? Is there a fairy tale behind it or something?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE696"
        },
        [12033504] = {
          ContentKR = "걔가 어렸을 때 겪은 일 때문이야. 나한테 몇 번이나 말해 줬었는데, 어느 날 갑자기 아빠랑 엄마가 안 보이더래. 아무리 찾아도 안 보이니까, 무서워서 엉엉 울었고.",
          DialogueId = 12033504,
          GUID = "1E1FE6C0",
          NextDialogue = 12033505,
          SpeakNpcId = 211012,
          Subtitle = "It's because of something that happened when he was little. He told me the story a bunch of times... One day, his mum and dad disappeared. He was scared and cried a lot.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6C0"
        },
        [12033505] = {
          ContentKR = "바로 그때 나비 요정이 나타나서 자기랑 놀아 주고, 세비오네 아빠랑 엄마가 집으로 돌아올 때까지 계속 같이 기다려 줬다는 거야.",
          DialogueId = 12033505,
          GUID = "1E1FE6EA",
          NextDialogue = 12033506,
          SpeakNpcId = 211012,
          Subtitle = "Then the Butterfly Fairies came. They played with him, kept him company until his parents came home.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6EA"
        },
        [12033506] = {
          ContentKR = "그래서, 아마도, 나비 요정을 찾으면, 자기 아빠랑 엄마가 돌아올 거라고 생각하는 걸지도...",
          DialogueId = 12033506,
          GUID = "1E1FE714",
          NextDialogue = 12033507,
          SpeakNpcId = 211012,
          Subtitle = "I think... maybe he believes if he finds them again, they'll bring his parents back...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE714"
        },
        [12033507] = {
