        [12033615] = {
          Camera = "823.866516,-170.169342,58.013672,0.000193,-10.305163,101.909111,35.000019,351.790253,false,Manual,2.8",
          ContentKR = "자, 피나. 우리도 모험을 떠나 보자!",
          DialogueId = 12033615,
          FinalCamera = "821.287842,-157.941132,55.742188,0.000193,-10.305163,101.909111,35.000019,351.790253,false,Manual,2.8",
          GUID = "1E1FF8F6",
          NextDialogue = 12033616,
          Scripts = [[
