}]],
          SpeakNpcId = 100001,
          Subtitle = "Alright then, Fina — ready for an adventure?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FF8F6"
        },
        [12033616] = {
          Camera = "779.510742,98.28862,32.064453,0.000213,0.094933,-86.689522,55.0,175.820221,false,Manual,2.8",
          ContentKR = "응!",
          DialogueId = 12033616,
          FinalCamera = "780.014343,89.009392,32.080078,0.000213,0.094933,-86.889565,55.0,175.820221,false,Manual,2.8",
          GUID = "1E1FF920",
          Scripts = [[
