PARA{

MoveTo{ActorId{211037},TargetPoint{"CinPoint_FN36b_Moveto01"},MoveSpeed{220},Visibility{"Show"}},
MoveTo{ActorId{211038},TargetPoint{"CinPoint_FN36b_Moveto02"},MoveSpeed{220},Visibility{"Show"}},
