        [12034211] = {
          Camera = "-672.598206,204.975342,115.760742,0.000151,-5.746887,68.417374,40.000011,316.116333,false,Manual,8.0",
          ContentKR = "얘기가 나왔으니 말인데, 피나, 앞으론 그냥 카산드라라고 불러. 우린 친구잖아!",
          DialogueId = 12034211,
          FinalCamera = "-675.080505,205.959122,115.760742,0.000151,-5.746887,68.417374,40.000011,316.116333,false,Manual,8.0",
          GUID = "1E205ABE",
          NextDialogue = 12034212,
          Scripts = "PlayAnimation{_delay{6},ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "You know what — just call me Cassandra. We're friends now, aren't we?",
          ToFinalCameraBlendTime = 8.5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205ABE"
        },
        [12034212] = {
          Camera = "24.936897,211.303375,233.266602,0.00015,-15.146654,163.41217,30.0,303.841736,false,DoNotOverride,8.0",
          ContentKR = "미안해... 그동안 너무 못되게 굴어서. 사람들이 맨날 카론은 욕심 많고 교활한 악당들이라고 그러길래, 진짜 그런 줄 알았어...",
          DialogueId = 12034212,
          FinalCamera = "20.340214,196.053726,233.266602,0.000151,-15.146654,162.212265,30.0,303.841736,false,DoNotOverride,8.0",
          GUID = "1E205AE8",
          LookAt = {
            [1] = "211015:n(211012)"
          },
          NextDialogue = 12034213,
          Scripts = "PlayAnimation{_delay{4},ActorId{211012},AnimationId{\"Explain01_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "I'm sorry I was mean to you before. I'd heard all these awful things about Charons — greedy, cunning, dangerous — and I believed them...",
          TalkActionId = {
            [1] = "211012:Confident_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205AE8"
        },
        [12034213] = {
          Camera = "-462.737854,733.426208,85.525391,0.000146,-1.145969,-114.188133,30.0,303.841736,false,DoNotOverride,8.0",
          ContentKR = "흥, 알고 보니까 전부 다 새빨간 거짓말이었어. 너희 둘이 사람을 무시하는 솔라보다 백 배, 아니 천 배는 나아!",
          DialogueId = 12034213,
          FinalCamera = "-462.737854,733.426208,73.604492,0.000146,1.054096,-113.987686,30.0,303.841736,false,DoNotOverride,8.0",
          GUID = "1E205B12",
          NextDialogue = 12034214,
          Scripts = "PlayAnimation{_delay{4},ActorId{211012},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "Turns out it was all rubbish. You two are a hundred — no, a thousand times nicer than those snobby Solarians!",
          TalkActionId = {
            [1] = "211012:Explain01_End"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205B12"
        },
        [12034214] = {
          Camera = "-364.645142,423.454132,114.674805,0.000121,-9.546288,169.611847,30.0,303.841736,false,DoNotOverride,8.0",
          ContentKR = "나도 고마워! 훌쩍... 하마터면 저 강도들한테 잡혀서 눈물의 호수에 사는 물고기들 밥이 돼 버릴 뻔했어...",
          DialogueId = 12034214,
          FinalCamera = "-365.643707,417.940216,114.674805,0.000121,-9.546288,169.611847,30.0,303.841736,false,DoNotOverride,8.0",
          GUID = "1E205B3C",
          LookAt = {
            [1] = "211015:n(211015)",
            [2] = [[

211012:n(211015)]],
            [3] = [[

211001:n(211015)]],
            [4] = [[

100001:n(211015)]]
          },
          NextDialogue = 12034215,
          SpeakNpcId = 211015,
          Subtitle = "I want to thank you too! *sniffles* I thought I was a goner... Waaah!",
          TalkActionId = {
            [1] = "211012:Confident_End",
            [2] = [[

211015:Sigh_Start]]
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205B3C"
        },
        [12034215] = {
          Camera = "-791.641052,842.650452,140.891602,0.000069,-7.345704,-66.589088,30.0,319.085938,false,DoNotOverride,8.0",
          ContentKR = "울지 마. 친구가 이렇게 많은데, 무서울 게 뭐가 있어? 앞으론 나쁜 애들이든 강도든, 누가 널 괴롭히면, 피나한테 커다란 괴물을 불러서 깜짝 놀라게 만들어 달라고 해! 흥!",
          DialogueId = 12034215,
          FinalCamera = "-791.641052,842.650452,110.082031,0.000073,-4.745547,-67.189018,30.0,319.085938,false,DoNotOverride,8.0",
          GUID = "1E205B66",
          NextDialogue = 12034216,
          SpeakNpcId = 211012,
          Subtitle = "Don't cry! You've got loads of friends now — no one's going to hurt you. And if any bullies or bandits show up again? Fina will just summon a giant monster to chase them off!",
          TalkActionId = {
            [1] = "211015:Sigh_End",
            [2] = [[

211012:Talk01_Start]]
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120114/1E205B66"
        },
        [12034216] = {
