          SpeakNpcId = 211001,
          Subtitle = "Of course you can — we're friends, aren't we?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E209BB6"
        },
        [12034608] = {
          ContentKR = "피나, 피나! 우리도 왔어!",
          DialogueId = 12034608,
          GUID = "1E209BE0",
          SpeakNpcId = 211012,
          Subtitle = "Fina! We made it!",
