        },
        [12034701] = {
          Camera = "67.369461,704.07135,163.671875,0.000133,0.9707,-140.685501,28.000008,150.821991,false,Manual,10.0",
          ContentKR = "피나, 내 말 좀 들어 봐. 아까 가게에서 아무개 {性别:오빠|언니}랑 마주쳤어! 엄청난 우연이지! 헤헤, 오늘은 내가 사는 거니까, 다들 케이크랑 쿠키, 그리고 과자도 잔뜩 먹어!",
          DialogueId = 12034701,
          FinalCamera = "343.453094,606.111816,172.441406,0.00007,-6.629395,-144.681458,35.000011,261.24472,false,Manual,12.0",
          GUID = "1E20AB22",
          NextDialogue = 12034702,
          Scripts = [[
SEQ{
