PlayAnimation{ActorId{211012},AnimationId{"Confident_Start"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Fina, guess what — I ran into {性别:Mr|Miss} Eyepatch at the shop! Hehe, I brought cakes, cookies, and candy — my treat! Help yourselves!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AB22"
        },
        [12034702] = {
