PlayAnimation{ActorId{100001},AnimationId{"Talk02R_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}},
PlayFacial{_delay{1.5},ActorId{211001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "...Okay! I will! Thank you, {性别:Mr|Miss} Unicorn.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20ACF0"
        },
        [12034713] = {
          Camera = "-470.035645,260.954132,99.352539,0.000137,3.969959,-23.284956,35.0,150.137177,false,Manual,22.0",
          ContentKR = "피나, 아무개 {性别:오빠|언니}, 왜 아직도 둘이 밖에서 속닥거려? 빨리 안 들어오면, 우리끼리 케이크 다 먹어 버린다?",
          DialogueId = 12034713,
          GUID = "1E20AD1A",
          NextDialogue = 12034714,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Shy01_End"},Duration{1}},
PlayFacial{_delay{1},ActorId{211001},FacialId{"None"}},
LookAt{LookAtDescription{"100001:p(simple43a01)"}},
LookAt{LookAtDescription{"211001:p(simple43a01)"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Fina, Eyepatch — what are you doing out there? Come in, or we'll eat all the cake without you!",
          TurnTo = {
            [1] = "211001:p(-70)"
