          },
          FinalCamera = "-56.127686,4.689941,50.209229,0.00031,5.598692,-20.219845,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B654",
          NextDialogue = 20000515,
          SpeakNpcId = 200024,
          Subtitle = "!!!",
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B654"
        },
        [20000515] = {
          Camera = "-1132.003174,-2957.388672,210.885498,0.000319,-1.000759,65.576195,27.995377,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(그녀는 검의 무늬에서 무언가를 읽으려는 듯 검을 자세히 들여다보았다.)",
          DialogueId = 20000515,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 3,
          FinalCamera = "-1148.861572,-2949.662109,210.885498,0.000319,-1.000759,64.376427,27.995377,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B67E",
          NextDialogue = 20000516,
          Subtitle = "(She carefully examined the sword, attempting to glean some information from its pattern.)",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B67E"
        },
        [20000516] = {
          Camera = "-134.061523,50.801758,95.63208,0.000289,-10.201447,-24.418987,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "좋은 검, 좋은 검이야! 검의 재질이나 검을 만든 기술을 보아하니 휘페르보레아의 범재들이 만든 것은 아닐 테지. 자넨 나이도 어린데 어떻게 이런 보물을 얻은 거지?",
          DialogueId = 20000516,
          Duration = 2,
          FacialId = {
            [1] = "200024:Happy01"
          },
          GUID = "3211B6A8",
          NextDialogue = 20000517,
          SpeakNpcId = 200024,
          Subtitle = "Amazing! That's incredible! Look at the texture and the craftsmanship! This clearly wasn't made by those mediocre Hyperborean blacksmiths. Where did you get it?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B6A8"
        },
        [20000517] = {
          Camera = "-197.926575,232.563965,156.319824,0.000096,-15.201227,-51.775345,50.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(이 루나 대장장이는 이 검이 예사롭지 않다고 생각하는 것 같다.)",
          DialogueId = 20000517,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          GUID = "3211B6FC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20000518.T_Story_Recall_20000518'",
          LookAt = {
            [1] = "100001:p(200005Point2)"
          },
          NextDialogue = 20000519,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          Subtitle = "(The Luno blacksmith recognised that this sword was no ordinary weapon.)",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B6FC"
        },
        [20000519] = {
          Camera = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
          ContentKR = "잘 모르겠는데...",
          DialogueId = 20000519,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "3211B750",
          NextDialogue = 20000520,
          SpeakNpcId = 100001,
          Subtitle = "I'm not sure...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B750"
        },
        [20000520] = {
          Camera = "47.933167,48.183594,106.281372,0.000106,0.998942,164.023529,50.0,162.033707,false,Manual,14.755679",
          ContentKR = "내가 어릴 적부터 쭉 이 검은 나와 함께였어. 어쩌면 부모님이 남겨주신 게 아닐까?",
          DialogueId = 20000520,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "3211B77A",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000522,
          SpeakNpcId = 100001,
          Subtitle = "This sword has been with me for as long as I can remember. Maybe it was passed down to me by my parents?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B77A"
        },
        [20000522] = {
          Camera = "-189.288086,203.751465,151.934326,0.000147,-16.40097,-49.57642,50.000008,162.033707,false,Disable,14.755679",
          ContentKR = "재미있군, 재미있어. 평생 대장장이로 살아왔지만, 이 검을 만든 사람의 실력에는 미치지 못하는군.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000522,
          Duration = 3,
          FacialId = {
            [1] = "200024:Happy02"
          },
          GUID = "3211B7CE",
          NextDialogue = 20000523,
          SpeakNpcId = 200024,
          Subtitle = "Intriguing. Very intriguing. I've been a blacksmith my whole life, yet I've never seen a weapon like this before.",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B7CE"
        },
        [20000523] = {
          ContentKR = "젊은이, 나는 오랫동안 떠돌아다니며 정착할 곳이 없었네. 한동안 자네를 따라다녀도 괜찮겠는가?",
          DialogueId = 20000523,
          Duration = 3,
          FacialId = {
            [1] = "200024:Smile02"
          },
          GUID = "3211B7F8",
          NextDialogue = 20000524,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Kiddo, I'm Lunosmith, a wandering blacksmith. Would you mind if I accompanied you on your journey?",
          VoiceName = "voice/$Locale$/story/2001/200005/3211B7F8"
        },
        [20000524] = {
          Camera = "-38.022217,110.633789,44.966553,0.000129,4.598534,-58.971298,50.000008,162.033707,false,Disable,14.755679",
          ContentKR = "휘페르보레아에서 엘리시안까지, 못 본 무기가 없고 안 만든 무기가 없지! 무기를 만들고 싶다면, 나에게 맡기게.",
          DialogueId = 20000524,
          Duration = 2,
          FinalCamera = "-38.022217,110.633789,46.349609,0.000129,4.598534,-58.971333,50.000008,162.033707,false,Disable,14.755679",
          GUID = "3211B822",
          NextDialogue = 20000525,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "I've travelled all over the land, from Hyperborea to Elysium, and I've forged countless weapons. If you require any weapons, I'm at your disposal.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B822"
        },
        [20000525] = {
          Camera = "232.871338,-185.234375,83.503784,0.000127,-5.002772,134.234024,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "우와, 대장장이셨구나!",
          DialogueId = 20000525,
          Duration = 3,
          FacialId = {
            [1] = "200025:Shock02"
          },
          GUID = "3211B84C",
          NextDialogue = 20000526,
          SpeakNpcId = 200025,
          Subtitle = "Wow! So you're an experienced master blacksmith!",
          TalkActionId = {
            [1] = "200025:SpecialHappy_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B84C"
        },
        [20000526] = {
          Camera = "-189.288086,203.751465,151.934326,0.000147,-16.40097,-49.57642,50.000008,162.033707,false,Disable,14.755679",
          ContentKR = "가격은 다른 대장장이들보다 저렴할 걸세. 하지만 내게 그 검을 연구할 시간을 좀 주게나. 하하.",
          DialogueId = 20000526,
          Duration = 2,
          FacialId = {
            [1] = "200024:Happy02"
          },
          GUID = "3211B876",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "All I request is a basic salary, and an opportunity to examine your sword, hehe.",
          TalkActionId = {
            [1] = "200025:SpecialHappy_End"
          },
          TalkOptions = {
            [1] = 200005261,
            [2] = 200005262
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B876"
        },
        [20000528] = {
          Camera = "112.837646,-162.337891,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          ContentKR = "허... 젊은이 표정을 보아하니, 이 늙은이를 의심하는구나.",
          DialogueId = 20000528,
          Duration = 3,
          FacialId = {
            [1] = "200024:Shock01"
          },
          FinalCamera = "114.166748,-161.282227,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          GUID = "3211B8CA",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000529,
          Scripts = "CameraMoveTo{_delay{3.5},TargetPosition{\"-257.094238,105.374512,89.299316,0.000146,-7.001647,-20.17968,50.000008,421.26944,false,Manual,6.435696\"},duration{0}}",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Look, I can see scepticism written on your face.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8CA"
        },
        [20000529] = {
          Camera = "-69.666748,-17.761719,56.248047,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "걱정하지 말게. '루나는 결코 먼저 다른 이를 해치지 않는다'. 이건 아트라시아 대륙의 모두가 알고 있는 사실이지.",
          DialogueId = 20000529,
          Duration = 2,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "-69.666748,-17.761719,57.486084,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B8F4",
          NextDialogue = 20000530,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "You can trust me. You must know the saying, \"Lunos never harm.\" Everyone in Atlasia knows that.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8F4"
        },
        [20000530] = {
          Camera = "-257.729492,-42.183594,76.834473,0.000131,-5.203491,35.769909,50.0,290.309357,false,Manual,3.710212",
          ContentKR = "맞아 맞아!",
          DialogueId = 20000530,
          Duration = 3,
          FacialId = {
            [1] = "200025:Doubt01"
          },
          GUID = "3211B91E",
          LookAt = {
            [1] = "200025:n(100001)"
          },
          NextDialogue = 20000531,
          SpeakNpcId = 200025,
          Subtitle = "Yes, exactly!",
          TalkActionId = {
            [1] = "200025:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B91E"
        },
        [20000531] = {
          Camera = "-7.611328,-33.099121,102.976074,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          ContentKR = "(그래, 루나인 스노우도 따뜻한 마음을 가졌으니까. 게다가 대장장이가 빈털터리인 우리 둘을 노릴 이유가 있을까?)",
          DialogueId = 20000531,
          DialoguePanelType = "Voiceover",
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-15.199463,-23.983398,104.64917,0.0,0.0,129.770859,35.0,211.517212,false,Manual,3.358988",
          GUID = "3211B948",
          NextDialogue = 20000532,
          Subtitle = "(She was right. You could see that trait in Snow. Besides, what could she get from you? You have nothing to offer.)",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B948"
        },
        [20000532] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래, 내 생각이 짧았네. 같이 가자.",
          DialogueId = 20000532,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "3211B972",
          NextDialogue = 20000533,
          SpeakNpcId = 100001,
          Subtitle = "Yeah, you're right. Let's head back together then.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200005/3211B972"
        },
        [20000533] = {
          Camera = "-2423.703857,1080.132324,250.907959,0.000098,-4.001944,-26.573547,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "젊은이가 동의한 모양이군. 좋아, 좋아! 어서 자네들이 사는 곳으로 가자고!",
          DialogueId = 20000533,
          Duration = 3,
          FinalCamera = "-2421.345459,1084.854004,250.907959,0.000098,-4.001944,-26.573236,60.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B99C",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "So you'll have me? Excellent! Then take me to where you live.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B99C"
        },
        [20000601] = {
