        [20000602] = {
          Camera = "-160.725159,-13.358643,119.220985,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          ContentKR = "그러고 보니 길에서 스노우와 대장장이님이랑 비슷하게 생긴 사람들을 봤는데, 그 사람들도 <H>루나</>인 건가?",
          DialogueId = 20000602,
          Duration = 2,
          ExStoryInfo = "Player",
          FinalCamera = "-174.055298,-12.71582,117.098991,0.0,4.999999,-2.79654,35.0,142.092117,false,Manual,5.04021",
          GUID = "3211C4C4",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000603,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4.6},TargetPosition{"-275.118378,-120.86499,74.379753,0.000004,3.39987,31.806273,25.0,279.088654,false,Manual,1.419143"},duration{0}},
CameraMoveTo{_delay{4.7},TargetPosition{"-287.599518,-128.604248,69.15966,0.000004,3.39987,31.807192,25.0,279.088654,false,Manual,1.419143"},duration{4}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I've seen many who resemble you and Snow. Are they also Lunos?",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C4C4"
        },
        [20000603] = {
          Camera = "-4.034668,-120.357422,84.402077,0.00001,-0.800252,111.203094,25.0,279.088654,false,Manual,4.45866",
          ContentKR = "젊은이, 어디 외진 곳에서 왔나?",
          DialogueId = 20000603,
          Duration = 3,
          GUID = "3211C4EE",
          NextDialogue = 20000604,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Did you come from a remote village or something, kiddo?",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C4EE"
        },
        [20000604] = {
          Camera = "172.062653,-1154.075806,143.87851,0.0,0.0,89.999985,25.0,200.0,false,Disable,2.8",
          ContentKR = "맞아... 내 고향은 번화했다고 보기엔 힘든 곳이야.",
          DialogueId = 20000604,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          FinalCamera = "172.062653,-1154.075806,164.062302,-0.0,-0.999987,89.999985,25.0,200.0,false,Disable,2.8",
          GUID = "3211C518",
          NextDialogue = 20000605,
          SpeakNpcId = 100001,
          Subtitle = "Yes, my hometown isn't a big city.",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C518"
        },
        [20000605] = {
          Camera = "375.018433,-82.650635,97.525391,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
          ContentKR = "하하, 어쩐지, 어쩐지. 이 늙은이가 머물렀던 곳은 말이야, 사람이 있는 곳엔 항상 루나가 있었지. 자네처럼 우리 일족을 본 적이 없는 아이는 많지 않아.",
          DialogueId = 20000605,
          Duration = 1.5,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "356.082672,-77.70874,94.312401,0.000002,-1.800014,165.397888,25.0,200.0,false,Disable,2.8",
          GUID = "3211C542",
          NextOptions = {
            [1] = 200006051
          },
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Ha, that explains it. In all my travels, wherever there are humans, Lunos can always be found. It's quite uncommon to come across someone like you who's never heard of us.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C542"
        },
        [20000606] = {
          Camera = "155.926254,-348.624268,84.660477,0.0,-0.799986,116.795898,25.0,200.0,false,Disable,2.8",
          ContentKR = "우리 루나는 모두 스노우처럼 귀엽고 긴 수명을 가지고 있어.",
          DialogueId = 20000606,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "3211C56C",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)",
            [3] = "200024:n(200002)"
          },
          NextDialogue = 20000607,
          SpeakNpcId = 200002,
          Subtitle = "We share a similar appearance. Everyone is as attractive as me. And we live very long lives.",
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200006/3211C56C"
        },
        [20000607] = {
          Camera = "-55.37558,-141.429932,74.678345,0.000005,-1.600122,102.597961,25.0,136.939529,false,Manual,2.8",
          ContentKR = "그리고 여기 대장장이님처럼, 각자 잘하는 것이 있다구!",
          DialogueId = 20000607,
          Duration = 3,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "3211C596",
          LookAt = {
            [1] = "200002:n(200024)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 20000608,
          SpeakNpcId = 200002,
          Subtitle = "Like the master blacksmith, every Luno has a particular forte.",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C596"
        },
        [20000608] = {
          Camera = "-273.669891,-169.162842,94.503487,0.000062,-4.201106,40.194386,20.0,189.105499,false,Manual,2.8",
          ContentKR = "호오, 그럼 스노우도 잘하는 게 있겠네?",
          DialogueId = 20000608,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Happy01",
            [2] = "200002:None",
            [3] = "200024:None"
          },
          GUID = "3211C5C0",
          NextDialogue = 20000609,
          SpeakNpcId = 100001,
          Subtitle = "Wow. Then do you have any unique talents, Snow?",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C5C0"
        },
        [20000609] = {
          Camera = "-124.017761,-72.534912,96.158783,0.000383,-4.797825,32.343403,30.0,153.148956,false,Manual,3.33564",
          ContentKR = "음... 그게... 당연히... 있지!",
          DialogueId = 20000609,
          Duration = 6,
          GUID = "3211C5EA",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 20000610,
          SpeakNpcId = 200002,
          Subtitle = "Hmm... Yeah... Of course, I do!",
          TalkActionId = {
            [1] = "200002:Bai_Shock2Think2Confident"
          },
          VoiceName = "voice/$Locale$/story/2001/200006/3211C5EA"
        },
        [20000610] = {
          Camera = "-124.017761,-72.534912,96.158783,0.000383,-4.797825,32.343403,30.0,153.148956,false,Manual,3.33564",
          ContentKR = "이거, 이거, 보이지! 스노우는 다른 루나랑 다르게 생겼다니까!",
          DialogueId = 20000610,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-115.367767,-61.598877,96.529541,0.000382,-4.797825,32.34626,30.0,153.148956,false,Manual,3.33564",
          GUID = "3211C614",
          NextDialogue = 20000611,
          Scripts = "CameraMoveTo{_delay{3.1},TargetPosition{\"-29.559052,-9.855469,93.745667,0.000395,-1.597868,52.748596,30.0,80.996147,false,Manual,3.33564\"},duration{0}}",
          SpeakNpcId = 200002,
          Subtitle = "As you can see, I have demonic appendages on my head. No other Lunos have these!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C614"
        },
        [20000611] = {
          Camera = "121.44281,0.996094,87.475624,0.000284,-1.203274,162.815094,40.0,255.986099,false,Manual,4.671523",
          ContentKR = "확실히, 이 늙은이가 이렇게 나이를 먹었지만, 너처럼 생긴 루나는 처음 보는 것 같군. 네 모습은, <H>카론</>이랑 비슷하게 생겼어...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000611,
          Duration = 3,
          FinalCamera = "120.606506,-1.710693,87.475624,0.000284,-1.203274,162.815094,40.0,255.986099,false,Manual,4.671523",
          GUID = "3211C63E",
          NextDialogue = 20000612,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Indeed. In all my years, I've never seen a Luno with horns like those. You look just like those human Charons.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C63E"
        },
        [20000612] = {
          Camera = "-400.428558,-346.687256,65.11969,0.000289,0.592908,43.232693,30.0,150.0,false,Disable,2.8",
          ContentKR = "그러니까, 스노우는 하나밖에 없는 마왕 루나라고! 어쩌면 스노우는 루나를 이끌어 세계를 정복하기 위해 태어났을지도!",
          DialogueId = 20000612,
          Duration = 3,
          FinalCamera = "-400.428558,-346.687256,74.75869,0.000289,0.592908,43.232693,30.0,150.0,false,Disable,2.8",
          GUID = "3211C668",
          NextDialogue = 20000613,
          SpeakNpcId = 200002,
          Subtitle = "Sooooo, I'm Luno the Demon King, different and unique! Perhaps I was meant to lead the Lunos and dominate the world!",
          TalkActionId = {
            [1] = "200002:Bai_Talk03Quick"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C668"
        },
        [20000613] = {
          Camera = "73.592575,17.665527,68.467941,0.000294,7.195904,171.812531,50.0,197.801682,false,Manual,3.959335",
          ContentKR = "허... 젊은이가 야망이 크군!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000613,
          Duration = 3,
          FacialId = {
            [1] = "200024:Satisfy01"
          },
          GUID = "3211C692",
          NextDialogue = 20000614,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Oh... that's quite the ambition.",
          VoiceName = "voice/$Locale$/story/2001/200006/3211C692"
        },
        [20000614] = {
          Camera = "-147.118195,-74.93335,97.300194,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          ContentKR = "휴, 보통 루나는 정말 야망이라고는 찾아볼 수 없다니까. 그저 인간을 따라다니는 것을 좋아하고, 인간의 칭찬을 받으면 기뻐서 빙빙 돌기나 하고... 하지만 이런 걸로는 이 스노우 님을 만족시킬 수 없지!",
          DialogueId = 20000614,
          Duration = 3,
          FacialId = {
            [1] = "200002:Syouganai01"
          },
          GUID = "3211C6BC",
          NextDialogue = 20000615,
          SpeakNpcId = 200002,
          Subtitle = "Unfortunately, most Lunos lack ambition. They'd rather follow the humans, and are content with just a few words of appreciation. But for me, I want so much more!",
          TalkActionId = {
            [1] = "200002:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200006/3211C6BC"
        },
        [20000615] = {
          BlendTime = 2,
          Camera = "-147.118195,-74.93335,97.300194,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          CameraBlendCurve = "easeInQuad",
          ContentKR = "시종아! 이 스노우 님을 잘 따라다니면서 열심히 수행하라고! 스노우가 세계 정복을 하면 널 마왕군의 군단장으로 임명해 줄 테니! 그때 대장장이 루나님한테 우리 모습을 다시 보여주는 거야!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000615,
          Duration = 3,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-155.359039,-80.880859,97.762383,0.000344,-2.603818,35.809223,50.0,210.030212,false,Manual,5.267603",
          GUID = "3211C6E6",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextOptions = {
            [1] = 200006151,
            [2] = 200006152
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{3.1},TargetPosition{"-277.723358,-99.678711,81.074387,0.000378,1.599985,26.80905,25.0,272.329132,false,Manual,1.32502"},duration{0}},
CameraMoveTo{_delay{3.2},TargetPosition{"-291.878387,-106.830566,80.631393,0.000378,1.599985,26.80905,25.0,272.329132,false,Manual,1.32502"},blend{"easeOutQuad"},duration{3}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "My little minion, you must stick with me. After I conquer the world, you'll be the leader of my legion! Just you wait and see!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200006/3211C6E6"
        },
        [20000618] = {
          Camera = "-100.573456,-44.273193,82.943001,0.000289,2.394917,38.210751,50.0,255.910919,false,Disable,2.8",
          ContentKR = "음... 매일 마왕님의 친필 사인이 담긴 칭찬 편지 20장을 받을 수 있는 거? 에이, 어쨌든, 절대 푸대접하지 않는다니까.",
          DefaultLookAt = "Self",
          DialogueId = 20000618,
          Duration = 3,
          GUID = "3211C764",
          NextDialogue = 20000619,
          SpeakNpcId = 200002,
