          NextDialogue = 20000826,
          SpeakNpcId = 100001,
          Subtitle = "But these petals seem to have lost their shine. The edges are dark and curled, as though they've been burnt...",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E95A"
        },
        [20000826] = {
          Camera = "10.355469,-77.708008,125.386719,0.000002,-1.399991,143.804291,35.0,144.500336,false,Manual,4.079638",
          ContentKR = "음... 아마도 물을 더 줘야 할 것 같아.",
          DialogueId = 20000826,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211E984",
          NextDialogue = 20000848,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... I believe the flowers are thirsting for some water.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211E984"
        },
        [20000827] = {
          Camera = "27.541016,-42.623047,120.214844,0.000004,-1.200071,-161.593994,25.0,104.410446,false,Manual,1.989418",
          ContentKR = "꽃잎에 부드러운 무늬가 있어. 안쪽에서 바깥쪽으로 퍼져 있는데, 잎맥이랑 좀 비슷해. 그런데 엄청 생기있어 보이진 않아...",
          DialogueId = 20000827,
          Duration = 3,
          ExStoryInfo = "Player",
          FinalCamera = "26.746094,-40.242188,120.214844,0.000004,-1.200071,-161.593994,25.0,160.037735,false,Manual,4.199908",
          GUID = "3211E9AE",
          LookAt = {
            [1] = "100001:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000828,
          SpeakNpcId = 100001,
          Subtitle = "The petals have soft stripes that radiate from the center outward, somewhat resembling the veins of the leaves. However, they seem not to be very plump...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E9AE"
        },
        [20000828] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그건 영양분을 전달하는 선이야, 잎맥이랑 비슷한 역할을 하지.",
          DialogueId = 20000828,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211E9D8",
          LookAt = {
            [1] = "100001:n(200027)"
          },
          NextDialogue = 20000829,
          SpeakNpcId = 200027,
          Subtitle = "The stripes deliver nutrients and function just like the veins of the leaves.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          TurnTo = {
            [1] = "100001:n(200027)"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211E9D8"
        },
        [20000829] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "사람들은 주로 꽃에만 관심을 가지지만, 사실 꽃과 잎은 그렇게 다르지 않아. 둘 다 열심히 숨 쉬며 자라고 있는 거지.",
          DialogueId = 20000829,
          Duration = 3,
          GUID = "3211EA02",
          NextDialogue = 20000830,
          SpeakNpcId = 200027,
          Subtitle = "Although the flowers usually steal our attention, they're not that different when compared to leaves. Both parts of the plant are doing their best to respire and grow.",
          TalkActionId = {
            [1] = "200027:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA02"
        },
        [20000830] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "음... 꽃잎이 시들어 보인다면 아마도 영양분이 부족한 것 같아.",
          DialogueId = 20000830,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211EA2C",
          NextDialogue = 20000848,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200027},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 200027,
          Subtitle = "Let me see... If they look shrivelled, they may be low on nutrients.",
          TalkActionId = {
            [1] = "200027:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA2C"
        },
        [20000831] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이제 대충 알 것 같아. 고마워.",
          DialogueId = 20000831,
          Duration = 3,
          FacialId = {
            [1] = "200027:None"
          },
          GUID = "3211EA56",
          NextDialogue = 20000832,
          SpeakNpcId = 200027,
          Subtitle = "I think I understand the issue now, thank you.",
          TalkActionId = {
            [1] = "200027:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA56"
        },
        [20000832] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.587082,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이런 꽃은 키우기 어려워?",
          DialogueId = 20000832,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211EA80",
          NextDialogue = 20000833,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Is this kind of flower hard to care for?",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA80"
        },
        [20000833] = {
          Camera = "-147.613281,70.731934,123.0,0.000019,0.0,-105.39399,35.0,200.0,false,DoNotOverride,2.8",
          ContentKR = "아니, 원래는 아주 튼튼한 품종이야. 아이스레이크 시티처럼 겨울이 긴 곳에서도 잘 자라.",
          DialogueId = 20000833,
          Duration = 3,
          FinalCamera = "-147.613281,70.731934,134.0,0.000019,0.0,-105.39399,35.0,200.0,false,DoNotOverride,2.8",
          GUID = "3211EAAA",
          NextDialogue = 20000834,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "No, it's quite resilient actually — it can even thrive in places with long winters, like Icelake.",
          TalkActionId = {
            [1] = "200027:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200008/3211EAAA"
        },
        [20000834] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.403259,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "가지치기랑 거름 주기, 습도와 온도만 잘 관리하면 아주 오래 예쁘게 필 수 있는데... 내가 잘 관리하지 못한 것 같아. 아빠랑 엄마 같은 훌륭한 정원사가 되기에는 아직 멀었나 봐.",
          DialogueId = 20000834,
          Duration = 3,
          GUID = "3211EAD4",
          NextOptions = {
            [1] = 200008341,
            [2] = 200008342
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200027},AnimationId{"Explain02_Start"},Duration{3}},
PlayAnimation{ActorId{200027},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{200027},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200027,
          Subtitle = "As long as it is well trimmed, fertilised, and given the proper humidity and temperature, it can bloom beautifully for weeks on end... But I didn't do it well. I'm far from being as good a florist as my parents.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EAD4"
        },
        [20000835] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아, 그렇지... 아, 잠깐, {nickname}, 생각났어!",
          DialogueId = 20000835,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211EAFE",
          NextDialogue = 20000837,
          SpeakNpcId = 200027,
          Subtitle = "You might be right, but... oh, wait, ! Something just occurred to me.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EAFE"
        },
        [20000836] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "예전에도 아이스레이크 시티에서 키웠으니 환경 같은 것도 이전과 다르지 않을 텐데... 아, 생각났다!",
          DialogueId = 20000836,
          Duration = 3,
          GUID = "3211EB28",
          NextDialogue = 20000837,
          SpeakNpcId = 200027,
          Subtitle = "I've grown it the same way as my parents did, and it's always been in Icelake, so the environment should be consistent... Ah, I get it!",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EB28"
        },
        [20000837] = {
          Camera = "-364.001953,-139.020996,113.833984,0.0,-0.399996,20.204187,35.0,150.0,false,Manual,2.8",
          ContentKR = "아마도 문제는 <H>흙</>에 있을 거야...",
          DialogueId = 20000837,
          Duration = 3,
          GUID = "3211EB52",
          LookAt = {
            [1] = "200027:p(TargetPonit_Flower)",
            [2] = "100001:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000838,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"200027:p(-70)\"}},TurnTo{TurnToDescription{\"100001:p(50)\"}}}",
          SpeakNpcId = 200027,
          Subtitle = "Maybe it's the soil...",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EB52"
        },
        [20000838] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentKR = "흙?",
          DialogueId = 20000838,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211EB7C",
          LookAt = {
            [1] = "100001:n(200027)"
          },
          NextDialogue = 20000839,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "The soil?",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EB7C"
        },
        [20000839] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아. 우리 집에서 키우는 꽃은 특별한 흙을 써. 아빠가 아이스레이크 시티 밖 어느 동굴에서 가져온 거야.",
          DialogueId = 20000839,
          Duration = 3,
          GUID = "3211EBA6",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 20000840,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "Yes. Dad used to gather special soil from a cave beyond Icelake for our plants.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EBA6"
        },
        [20000840] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아빠 말씀으로는 그 흙이 보통 흙보다 더 비옥하대. 거기 가서...",
          DialogueId = 20000840,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211EBD0",
          NextDialogue = 20000841,
          SpeakNpcId = 200027,
          Subtitle = "He mentioned that the special soil is more fertile than the others. Perhaps I can go there and—",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EBD0"
        },
        [20000841] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...아냐, 며칠만 더 지켜보고...",
          DialogueId = 20000841,
          Duration = 3,
          GUID = "3211EBFA",
          NextOptions = {
            [1] = 200008411,
            [2] = 200008412
          },
          SpeakNpcId = 200027,
          Subtitle = "...Um, forget it. I'll worry about this later...",
          TalkActionId = {
            [1] = "200027:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EBFA"
        },
        [20000842] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentKR = "간단하네, 내가 좀 가져다줄게.",
          DialogueId = 20000842,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200027:None"
          },
          GUID = "3211EC24",
          NextDialogue = 20000843,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Don't worry, I can collect some for you.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EC24"
        },
        [20000843] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "넌 그냥 나랑 얘기만 해줘도 돼, 굳이 그렇게까지...",
          DialogueId = 20000843,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211EC4E",
          NextDialogue = 20000844,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "You don't have to do that... Just coming here and talking with me is already—",
          TalkActionId = {
            [1] = "200027:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EC4E"
        },
        [20000844] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentKR = "괜찮아, 어차피 의뢰 때문에 자주 나가니까 별 일 아니야. 그 동굴이 어디 있는데?",
          DialogueId = 20000844,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "3211EC78",
          NextDialogue = 20000845,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "It's okay, I'll have to leave town for the commissions anyway. Gathering soil isn't that hard. So where's that cave you mentioned?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EC78"
        },
        [20000845] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...응, 고마...",
          DialogueId = 20000845,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01"
          },
          GUID = "3211ECA2",
          NextDialogue = 20000846,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "...Thank y... um, no.",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211ECA2"
        },
        [20000846] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니... 이제 우리 사이에 그런 말은 안 해도 되겠다. 친구니까.",
          DialogueId = 20000846,
          Duration = 3,
          GUID = "3211ECCC",
          NextDialogue = 20000847,
          SpeakNpcId = 200027,
          Subtitle = "I was about to say thank you, but I think we're beyond such formalities with each other.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211ECCC"
        },
        [20000847] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "동굴 위치를 알려줄게...",
          DialogueId = 20000847,
          Duration = 3,
          GUID = "3211ECF6",
          SpeakNpcId = 200027,
          Subtitle = "Let me give you the location of the cave.",
          TalkActionId = {
            [1] = "200027:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211ECF6"
        },
        [20000848] = {
          DialogueId = 20000848,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 20000831,
          GUID = "3211E889",
          NextOptions = {
            [1] = 200008201,
            [2] = 200008202,
            [3] = 200008203
          }
        },
        [20000901] = {
          Camera = "-140.695312,18.599854,123.658203,0.0,0.200002,-41.587856,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "프시케, 동굴에서 흙을 가져왔어. 한번 봐봐, 네가 말한 그 흙이 맞아?",
          DialogueId = 20000901,
          Duration = 3,
          ExStoryInfo = "Player",
          FinalCamera = "-133.978516,27.376221,123.658203,0.0,0.200002,-36.587448,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211F5D2",
          NextDialogue = 20000902,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_huaqiweizhi\"},EventPath{\"event:/bgm/cbt02/0050_story_saiqi_grow_flower\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, here's the soil from that cave. Does it look right?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "200027:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F5D2"
        },
        [20000902] = {
          Camera = "208.482422,-19.678467,129.025391,0.0,0.0,-157.197144,35.0,208.263901,false,Manual,6.0",
          ContentKR = "음... 이 촉감은... 정말 아빠가 예전에 쓰던 것과 똑같아.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000902,
          Duration = 3,
          GUID = "3211F5FC",
          NextDialogue = 20000903,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... Its touch is exactly like that of the soil Dad used to grow flowers with.",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F5FC"
        },
        [20000903] = {
          Camera = "134.650391,-45.876221,128.087891,0.0,0.0,-169.994003,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "많이 가져왔네... 덕분에 여기 꽃들이 모두 더 예쁘게 필 수 있을 것 같아.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000903,
          Duration = 3,
          GUID = "3211F626",
          NextOptions = {
            [1] = 20000904
          },
          SpeakNpcId = 200027,
          Subtitle = "And there's so much of it... This should be enough to help every plant thrive here.",
          TalkActionId = {
            [1] = "200027:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F626"
        },
        [20000904] = {
          ContentKR = "마음에 드는 것 같아 다행이다.",
          DialogueId = 20000904,
          GUID = "3211F650",
          NextDialogue = 20000905,
          Subtitle = "I'm glad you're happy. This trip was totally worth it."
        },
        [20000905] = {
          Camera = "-152.634766,127.236084,85.355469,0.000004,4.999999,-59.59177,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeOutQuad",
          ContentKR = "(프시케가 흙을 만지작거리며 기뻐한다. 문득 프시케한테 받은 꽃이 생각난다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000905,
          DisableMouth = 1,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01",
            [2] = "100001:Happy02"
          },
          FinalCamera = "-155.263672,125.692383,85.355469,0.000004,4.999999,-61.591789,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211F67A",
          LookAt = {
            [1] = "200027:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000906,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"36.587891,-51.674805,131.013672,0.000006,0.999926,-10.192198,30.0,103.831886,false,Manual,2.984025\"},duration{0}}",
          Subtitle = "(Psyche is lost in happiness as she feels the soil in her hand. You suddenly remember the flower — the one that Psyche gave you.)",
          TalkActionId = {
            [1] = "200027:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 2.5,
          TurnTo = {
            [1] = "200027:p(130)"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F67A"
        },
        [20000906] = {
          Camera = "36.587891,-51.674805,131.013672,0.000006,0.999926,-10.192198,30.0,103.831886,false,Manual,2.984025",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "(꽃을 꺼내 본다. 시간이 꽤 지났지만, 아직 시들지 않은 모습이다.)",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000906,
          DisableMouth = 1,
          Duration = 3,
          FacialId = {
            [1] = "100001:Happy01"
          },
          FinalCamera = "-6.515625,-43.923828,124.070312,0.000006,0.999926,-10.192293,30.0,148.292877,false,Manual,2.984025",
          GUID = "3211F6A4",
          NextDialogue = 20000907,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Give\"},Duration{1}}",
          Subtitle = "(You take out the flower and it rests peacefully on your palm. Though much time has passed since you received it, its petals remain immaculate.)",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F6A4"
        },
        [20000907] = {
          Camera = "55.597656,319.302246,78.720703,0.0,0.0,-87.5,25.0,295.179138,false,DoNotOverride,1.2",
          ContentKR = "아, 그 꽃이구나... 계속 잘 가지고 다녔네!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000907,
          Duration = 3,
          FinalCamera = "57.142578,283.636963,78.720703,0.0,0.0,-87.5,25.0,291.235352,false,DoNotOverride,1.2",
          GUID = "3211F6CE",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 20000908,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200027},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 200027,
          Subtitle = "Aww, it's that flower I gave you... And you've been carrying it around all this time.",
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "200027:p(-90)"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F6CE"
        },
        [20000908] = {
          Camera = "-6.515625,-43.923828,124.070312,0.000006,0.999926,-10.192293,30.0,147.70752,false,Manual,2.984025",
          ContentKR = "소중한 선물이니까. 근데 너한테도 이 꽃들이 모두 소중할 텐데, 이렇게 꺾어줘도 괜찮은 거야?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000908,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F6F8",
          NextDialogue = 20000909,
          SpeakNpcId = 100001,
          Subtitle = "Of course, it's a precious gift. You love these flowers, don't you? Is it okay for you to pluck one from the plant and give it away?",
          TalkActionId = {
            [1] = "200027:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F6F8"
        },
        [20000909] = {
          Camera = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,215.0,false,Manual,2.984025",
          ContentKR = "음... 예전에 꽃을 꺾으면 안 된다고 생각한 적도 있긴 해. 어렸을 때 말이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000909,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211F722",
          NextDialogue = 20000910,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... I was not, when I was little.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F722"
        },
        [20000910] = {
          Camera = "125.662109,-37.871582,125.59375,0.0,0.599998,-165.793549,25.0,127.299126,false,DoNotOverride,1.2",
          ContentKR = "꽃집에서 파는 생화 본 적 있어? 사실 그때는 생화를 별로 안 좋아했어... 꺾인 꽃이 불쌍하다고 생각했거든.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000910,
          Duration = 3,
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "125.382812,-36.4729,125.59375,0.0,0.599998,-168.793213,25.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F74C",
          NextDialogue = 20000911,
          Scripts = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{200027},AnimationId{\"DisagreeHead\"},Duration{1}}}",
          SpeakNpcId = 200027,
          Subtitle = "Have you seen freshly cut flowers sold at the florists? I never liked that practice... It always made me feel sorry for the flowers.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F74C"
        },
        [20000911] = {
          Camera = "-6.826172,100.584717,97.013672,0.000043,9.999396,-119.386726,25.0,118.235596,false,DoNotOverride,1.2",
          ContentKR = "꽃도 뿌리, 줄기, 잎과 마찬가지로 식물의 일부잖아. 그런데 사람들은 꽃의 아름다움을 감상하겠다고 줄기에서 잘라내서 관상용으로 쓰고, 가지에서 떨어트려 외롭게 시들게 하니까.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000911,
          Duration = 3,
          FinalCamera = "-38.798828,43.810303,123.986328,0.000043,9.999396,-119.386726,25.0,118.235596,false,DoNotOverride,1.2",
          GUID = "3211F776",
          NextOptions = {
            [1] = 200009111,
            [2] = 200009112
          },
          SpeakNpcId = 200027,
          Subtitle = "Flowers, stems, and leaves all belong to the same plant, yet people cut the flowers to admire their beauty, leaving them to wilt and die alone.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F776"
        },
        [20000912] = {
          Camera = "278.988281,10.379639,123.230469,0.0,0.0,-157.596741,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "우리 입장에서 보면 그렇게 생각할 수도 있겠네...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000912,
          Duration = 3,
          GUID = "3211F7A0",
          NextDialogue = 20000913,
          SpeakNpcId = 200027,
          Subtitle = "It does seem so, from our perspective...",
          VoiceName = "voice/$Locale$/story/2001/200009/3211F7A0"
        },
        [20000913] = {
          Camera = "-76.474609,-28.993408,129.525391,0.000001,-2.400053,-20.986586,33.0,211.485077,false,Manual,4.671381",
          ContentKR = "아까 '어렸을 때'라고 했는데... 지금은 생각이 바뀌었어?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000913,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F7CA",
          NextDialogue = 20000914,
          SpeakNpcId = 100001,
          Subtitle = "You said when you were little... Does that mean you feel differently now?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F7CA"
        },
        [20000914] = {
          Camera = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,219.542435,false,Manual,2.984025",
          ContentKR = "완전히 바뀐 건 아니야. 그냥...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000914,
          Duration = 3,
          GUID = "3211F7F4",
          NextDialogue = 20000915,
          SpeakNpcId = 200027,
          Subtitle = "Not entirely. But...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200027:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F7F4"
        },
        [20000915] = {
          Camera = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,219.542435,false,Manual,2.984025",
          ContentKR = "먼저 너한테 물어봐도 될까? 넌 꺾인 꽃에 대해 어떻게 생각해?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000915,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F81E",
          NextOptions = {
            [1] = 200009151,
            [2] = 200009152,
            [3] = 200009153
          },
          Scripts = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}}}",
          SpeakNpcId = 200027,
          Subtitle = "Can I ask you something first? What do you think about flowers that are plucked from their plants?",
          VoiceName = "voice/$Locale$/story/2001/200009/3211F81E"
        },
        [20000916] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "음... 역시 꽃을 너한테 준 게 잘한 일이었네. 너라면 분명 잘 돌봐줄 거야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000916,
          Duration = 3,
          GUID = "3211F848",
          NextDialogue = 20000919,
          SpeakNpcId = 200027,
          Subtitle = "I'm glad I gave you the flower. I knew you'd take good care of it.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F848"
        },
        [20000917] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "응... 그렇구나, 나도 그렇게 생각해.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000917,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211F872",
          NextDialogue = 20000919,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... I understand. That's what I thought.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F872"
        },
        [20000918] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "어렸을 때 내 생각이랑 똑같네.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000918,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211F89C",
          NextDialogue = 20000919,
          SpeakNpcId = 200027,
          Subtitle = "You feel the same way I did when I was little.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F89C"
        },
        [20000919] = {
          Camera = "624.845703,-2701.800537,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "지금의 나는 말이야, 꺾인 꽃을 보면 여전히 조금 슬퍼. 하지만 동시에 그 꽃들이 대단하다는 걸 깨달았어. 내가 생각했던 것보다 훨씬 더 대단해.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000919,
          Duration = 3,
          FinalCamera = "624.845703,-2600.36084,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F8C6",
          NextDialogue = 20000920,
          SpeakNpcId = 200027,
          Subtitle = "Now, when I see cut flowers, I still feel a bit sad. But over the years, I've come to realise that they are amazing — far more amazing than I thought.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F8C6"
        },
        [20000920] = {
          Camera = "260.572266,-2538.362549,380.068359,0.0,-7.500005,90.0,15.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "꺾이는 순간부터 열매를 맺을 수 없고 천천히 시들 수밖에 없는데도...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000920,
          Duration = 3,
          FinalCamera = "260.572266,-2339.146973,232.763672,0.0,-2.499965,90.0,17.5,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F8F0",
          NextDialogue = 20000921,
          SpeakNpcId = 200027,
          Subtitle = "A plucked flower would no longer bear fruit. It's fated to perish in a slow, wilting death...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F8F0"
        },
        [20000921] = {
          Camera = "454.208984,234.598389,25.705078,0.000022,5.099815,-140.996017,30.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "그래도 그 꽃들은 필사적으로 물을 빨아들이고, 짧은 시간 동안 온 힘을 다해 활짝 피어. 마치 아직 뿌리가 있는 것처럼, 마치 한 번도 꺾이지 않은 것처럼 말이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000921,
          Duration = 3,
          FinalCamera = "428.185547,247.284424,26.796875,0.000022,5.099815,-136.996017,30.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F91A",
          NextDialogue = 20000922,
          SpeakNpcId = 200027,
          Subtitle = "Yet it tries to absorb water, as if still rooted, blooming fully before its brief life fades.",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "200027:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F91A"
        },
        [20000922] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "그래서 이제는 그 꽃들을 불쌍히 여기지 않아. 오히려 대견한걸.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000922,
          Duration = 3,
          GUID = "3211F944",
          NextOptions = {
            [1] = 200009221,
            [2] = 200009222
          },
          SpeakNpcId = 200027,
          Subtitle = "I no longer pity them — I'm impressed by them.",
          TalkActionId = {
            [1] = "200027:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F944"
        },
        [20000923] = {
          Camera = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
          ContentKR = "응, 너도 그렇게 생각하지!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000923,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01"
          },
          GUID = "3211F96E",
          NextDialogue = 20000925,
          SpeakNpcId = 200027,
          Subtitle = "You feel the same, right?",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F96E"
        },
        [20000924] = {
          Camera = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
          ContentKR = "넌 정말 착하구나... 응, 네 말이 맞아... 꺾이지 않았다면 더 좋았겠지.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000924,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F998",
          NextDialogue = 20000925,
          SpeakNpcId = 200027,
          Subtitle = "You have a kind soul... And yes, you're right — it might be best not to cut them at all.",
          VoiceName = "voice/$Locale$/story/2001/200009/3211F998"
        },
        [20000925] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "아, 갑자기 분위기가 무거워졌네. 나 때문이야, 나 때문...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000925,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad02"
          },
          GUID = "3211F9C2",
          NextDialogue = 20000926,
          SpeakNpcId = 200027,
          Subtitle = "Oh, just listen to how sombre and heavy our conversation has become. That wasn't my intention...",
          TalkActionId = {
            [1] = "200027:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F9C2"
        },
        [20000926] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "아, 맞다. 흙 가져와줘서 고마워. 습도랑 부드러운 정도가 딱 좋은 것 같아... 어쩌면 넌 원예 쪽으로도 재능이 있을지도 몰라!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000926,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211F9EC",
          NextOptions = {
            [1] = 200009261,
            [2] = 200009262
          },
          SpeakNpcId = 200027,
          Subtitle = "Anyway, the soil you brought back is great. The wetness and softness are perfect... You might have a real knack for gardening!",
          TalkActionId = {
            [1] = "200027:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F9EC"
        },
        [20000927] = {
          Camera = "106.785156,-624.62207,37.896484,0.0,2.399917,5.600382,30.0,352.267853,false,Manual,1.2",
          ContentKR = "좋아, 내가 아는 모든 비법을 알려줄게! ...시간이 된다면 말이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000927,
          Duration = 3,
          FinalCamera = "106.785156,-624.62207,56.728516,0.000001,0.0,5.600479,30.0,352.267853,false,Manual,1.2",
          GUID = "3211FA16",
          NextDialogue = 20000928,
          SpeakNpcId = 200027,
          Subtitle = "Certainly! I'd be delighted to share all the gardening secrets I know! ...If time allows.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200009/3211FA16"
        },
        [20000928] = {
          Camera = "-73.154297,-38.155029,129.271484,0.000001,-2.400053,-18.186663,33.0,255.978088,false,Manual,4.671381",
          ContentKR = "응, 그렇게 하자.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000928,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211FA40",
          NextDialogue = 20000929,
          SpeakNpcId = 100001,
          Subtitle = "Okay, it's settled then.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211FA40"
        },
        [20000929] = {
          Camera = "428.185547,247.284424,82.193359,0.000022,-0.999987,-136.995941,30.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "{nickname}, 넌... 정말 좋은 사람이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000929,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211FA6A",
          NextDialogue = 20000930,
          SpeakNpcId = 200027,
          Subtitle = "... you are such a wonderful person.",
          VoiceName = "voice/$Locale$/story/2001/200009/3211FA6A"
        },
        [20000930] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentKR = "아빠랑 엄마 말고는 아무도 내 말에 귀 기울여주지 않았어. 화분 하나 때문에 이렇게까지 힘써줄 사람은 더더욱 없었고.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000930,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01"
          },
          GUID = "3211FA94",
          NextDialogue = 20000931,
          SpeakNpcId = 200027,
          Subtitle = "Apart from my parents, nobody else has ever taken my casual remarks so seriously or done so much for a simple plant.",
          VoiceName = "voice/$Locale$/story/2001/200009/3211FA94"
        },
        [20000931] = {
          Camera = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
          ContentKR = "이건 보답이야. 엄청 비싼 건 아니지만, 그래도 내 마음이니 받아줘.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000931,
          Duration = 3,
          GUID = "3211FABE",
          NextDialogue = 20000932,
          SpeakNpcId = 200027,
          Subtitle = "Please, take this as a token of my appreciation. It's not much, but I hope you'll accept it.",
          TalkActionId = {
            [1] = "200027:Give"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211FABE"
        },
        [20000932] = {
          Camera = "-51.462891,437.980225,224.990234,0.000043,-14.999996,-75.99987,30.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentKR = "이 꽃들이 다시 예쁘게 피면, 꼭 다시 와서 봐줘.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000932,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy02"
          },
          FinalCamera = "-51.462891,437.980225,188.777344,0.000045,-10.999991,-75.998978,30.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211FAE8",
          SpeakNpcId = 200027,
          Subtitle = "Do come back and admire these flowers when they bloom once more.",
          TalkActionId = {
            [1] = "200027:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200009/3211FAE8"
        },
        [20001001] = {
          ContentKR = "여기 흙은 좀 건조한 것 같아... 다른 곳도 살펴보자.",
          DialogueId = 20001001,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3212063A",
          SpeakNpcId = 100001,
          Subtitle = "The soil here feels dry... perhaps I should look elsewhere.",
          VoiceName = "voice/$Locale$/story/2001/200010/3212063A"
        },
        [20001201] = {
          ContentKR = "찾았다...! 여기 흙이 좀 더 부드럽고, 습도도 적당해 보여. 좀 더 가져가자.",
          DialogueId = 20001201,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3212270A",
          SpeakNpcId = 100001,
          Subtitle = "Found it...! The soil is soft and the wetness feels right. I should collect more.",
          VoiceName = "voice/$Locale$/story/2001/200012/3212270A"
        },
        [20001301] = {
          ContentKR = "{nickname}, 아까 말한 흙은 찾았어?",
          DialogueId = 20001301,
          ExStoryInfo = "Player",
          GUID = "32123772",
          NextDialogue = 20001302,
          SpeakNpcId = 200027,
          Subtitle = ", did you manage to find the soil?",
          VoiceName = "voice/$Locale$/story/2001/200013/32123772"
        },
        [20001302] = {
          ContentKR = "아직 못 찾았어.",
          DialogueId = 20001302,
          ExStoryInfo = "Player",
          GUID = "3212379C",
          NextDialogue = 20001303,
          SpeakNpcId = 100001,
          Subtitle = "No, not yet.",
          VoiceName = "voice/$Locale$/story/2001/200013/3212379C"
        },
        [20001303] = {
          ContentKR = "못 찾아도 괜찮아, 무리하지 마...",
          DialogueId = 20001303,
          GUID = "321237C6",
          SpeakNpcId = 200027,
          Subtitle = "It's alright. You don't need to go to all this trouble for me...",
          VoiceName = "voice/$Locale$/story/2001/200013/321237C6"
        },
        [20001401] = {
          ContentKR = "맞다맞다, 너한테 물어볼 게 몇 가지 더 있어.",
          DialogueId = 20001401,
          GUID = "321247DA",
          NextDialogue = 20001402,
          SpeakNpcId = 200027,
          Subtitle = "Oh, before I forget — I have a couple of questions:",
          VoiceName = "voice/$Locale$/story/2001/200014/321247DA"
        },
        [20001402] = {
          ContentKR = "혹시 천국의 나무 아래에 직접 가본 적 있어? 정말로 전설처럼 그~~렇게 크고, 하늘을 다 가릴 정도야? 아래에서 위를 올려다보면... 마치 하늘 전체가 수정으로 가득 찬 것처럼 보여?",
          DialogueId = 20001402,
          ExStoryInfo = "Player",
          GUID = "32124804",
          NextDialogue = 20001403,
          SpeakNpcId = 200027,
          Subtitle = "Have you ever stood under the Heaventree? Are the legends really true — is the Heaventree so massive that its crown covers the entire sky? Could we see... a glittering canopy of crystals looking up its trunk?",
          VoiceName = "voice/$Locale$/story/2001/200014/32124804"
        },
        [20001403] = {
          ContentKR = "그리고 그리고... 바닷가 모래는 정말 보들보들해? 밟으면 밀가루처럼 푹신푹신하고, 전혀 까칠하지 않아?",
          DialogueId = 20001403,
          GUID = "3212482E",
          NextDialogue = 20001404,
          SpeakNpcId = 200027,
          Subtitle = "And... and another question — is the sandy beach really as soft and smooth as they say — malleable like dough, and not at all rough on the feet?",
          VoiceName = "voice/$Locale$/story/2001/200014/3212482E"
        },
        [20001404] = {
          ContentKR = "물어볼 게 좀 많을지도 몰라! 다들 대신 물어봐 달라고 해서... 헤헤, 귀찮아하면 안돼!",
          DialogueId = 20001404,
          GUID = "32124858",
          SpeakNpcId = 200027,
          Subtitle = "Sorry for bombarding you with so many questions! I'm asking for my friends at the inn... Hehe, they are all very fascinated by your hometown.",
          VoiceName = "voice/$Locale$/story/2001/200014/32124858"
        },
        [20001501] = {
          ContentKR = "음... 이 정도면 충분할 것 같아. 프시케에게 가져다주자.",
          DialogueId = 20001501,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "32125842",
          SpeakNpcId = 100001,
          Subtitle = "Okay... This should be enough. Time to head back and bring it to Psyche.",
          VoiceName = "voice/$Locale$/story/2001/200015/32125842"
        },
        [20001601] = {
          Camera = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
          Content = "嗯等。",
          DialogueId = 20001601,
          GUID = "321268AA",
          NextDialogue = 20001602
        },
        [20001602] = {
          Camera = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          Content = "等不耐烦了。",
          DialogueId = 20001602,
          FinalCamera = "1700.51709,233.67041,212.238281,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "321268D4",
          NextDialogue = 20001603,
          ToFinalCameraBlendTime = 4
        },
        [20001603] = {
          Content = "赛琪怎么还没出来，我们去瞅瞅吧。",
          DialogueId = 20001603,
          GUID = "321268FE"
        },
        [20001701] = {
          Camera = "-284.28125,-104.837433,123.125,0.000002,0.199954,98.206268,35.0,310.0,false,Manual,22.0",
          ContentKR = "침식자를 막는 건 쉬운 일이 아니야. 먼저 준비를 잘 하고 성 밖으로 나가서 프시케를 찾아보자.",
          DialogueId = 20001701,
          FinalCamera = "-286.169922,-91.687805,123.117188,0.000002,-0.200043,98.206268,35.0,310.0,false,Manual,22.0",
          GUID = "32127912",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"-369.230469,214.921021,133.806641,0.000008,-2.000091,-40.793766,25.0,100.0,false,Manual,3.5"},duration{0}},
LookAt{_delay{5.5},LookAtDescription{"100001:n(100001)"}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Stopping a Deteriorator won't be an easy task. Make sure you're well-prepared before heading out of the city to look for Psyche.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/story/2001/200017/32127912"
        },
        [20001801] = {
          ContentKR = "와... 날아갈 것 같아!",
          DialogueId = 20001801,
          GUID = "3212897A",
          IsBlack = 1,
          NextDialogue = 20001802,
          SpeakNpcId = 200002,
          Subtitle = "Waah... The wind's gonna blow me away!",
          VoiceName = "voice/$Locale$/story/2001/200018/3212897A"
        },
        [20001802] = {
          ContentKR = "스노우, 우리 뒤에 붙어. 바람이 잠잠할 때 함께 앞으로 가자.",
          DialogueId = 20001802,
          ExStoryInfo = "Player",
          GUID = "321289A4",
          NextDialogue = 20001803,
          SpeakNpcId = 100001,
          Subtitle = "Stay behind us, Snow. We'll make our move when it calms a little.",
          VoiceName = "voice/$Locale$/story/2001/200018/321289A4"
        },
        [20001803] = {
          ContentKR = "바람이 너무 세면 바위 뒤에 숨어도 돼. 너무 서두르지 마.",
          DialogueId = 20001803,
          GUID = "321289CE",
          SpeakNpcId = 200021,
          Subtitle = "And if the wind gets strong, we can stay behind the rocks to take a little break. Don't rush in.",
          VoiceName = "voice/$Locale$/story/2001/200018/321289CE"
        },
        [20001901] = {
          Camera = "-362.765625,-80.016602,-24.530273,0.000006,17.167358,25.771385,15.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "먼 곳의 아이스레이크에서 폭풍이 몰아치고 있다. 프시케는 아마도 그 방향에 있을 것이다...",
          DialogueId = 20001901,
          GUID = "321299E2",
          Subtitle = "There's a storm blowing over the frozen lake. It should be the direction Psyche has headed to..."
        },
        [20002001] = {
          ContentKR = "...나비? 겨울에 어떻게 나비가?",
          DialogueId = 20002001,
          ExStoryInfo = "Player",
          GUID = "3212AA4A",
          SpeakNpcId = 100001,
          Subtitle = "...Butterflies? How come there are butterflies in such coldness?",
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA4A"
        },
        [20002002] = {
          ContentKR = "마치... 우리를 안내하는 것 같아...",
          DialogueId = 20002002,
          ExStoryInfo = "Player",
          GUID = "3212AA74",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "And it seems as if... they are leading the way for us...",
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA74"
        },
        [20002101] = {
          ContentKR = "여기 필토이드들은 거의 죽어가는데. 아마도 프시케와 싸웠던 것 같아.",
          DialogueId = 20002101,
          GUID = "3212BAB2",
          NextDialogue = 20002102,
          SpeakNpcId = 200021,
          Subtitle = "These Filthoids are half-dead, probably defeated by Psyche.",
          VoiceName = "voice/$Locale$/story/2001/200021/3212BAB2"
        },
        [20002102] = {
          ContentKR = "그렇다면 이놈들이 온 길을 거슬러 가면 프시케를 찾을 수 있겠네...",
          DialogueId = 20002102,
          GUID = "3212BADC",
          SpeakNpcId = 200021,
          Subtitle = "So if we trace them all the way back, we might be able to find Psyche...",
          VoiceName = "voice/$Locale$/story/2001/200021/3212BADC"
        },
        [20002201] = {
          Content = "兄弟，你还好吗。",
          DialogueId = 20002201,
          ExStoryInfo = "Player",
          GUID = "3212CB1A",
          NextDialogue = 20002202,
          SpeakNpcId = 100001
        },
        [20002202] = {
          Content = "不太好。",
          DialogueId = 20002202,
          GUID = "3212CB44",
          NextDialogue = 20002203
        },
        [20002203] = {
          Content = "外面情况怎么样？",
          DialogueId = 20002203,
          GUID = "3212CB6E",
          NextDialogue = 20002204
        },
        [20002204] = {
          Content = "刮了好大的风，秽兽的行为也很反常。",
          DialogueId = 20002204,
          GUID = "3212CB98"
        },
        [20002301] = {
          ContentKR = "(이성을 잃은 프시케가 침식과 싸우고 있다... 뭔가 해야 할 것 같다...)",
          DialogueId = 20002301,
          DisableMouth = 1,
          GUID = "3212DB82",
          Subtitle = "(Psyche has lost her senses, and is till fighting against Deterioration... We need to do something...)"
        },
        [20002401] = {
          ContentKR = "...프시케가 성 밖으로 간 것 같아.",
          DialogueId = 20002401,
          GUID = "3212EBEA",
          NextDialogue = 20002402,
          SpeakNpcId = 700049,
          Subtitle = "...Psyche seems to have rushed out of the city."
        },
        [20002402] = {
          ContentKR = "아마도 성 밖에 사람이 적어서겠지. 마지막 이성이 남아있을 때 최대한 사람이 적은 곳으로 가려고 한 거야.",
          DialogueId = 20002402,
          GUID = "3212EC14",
          SpeakNpcId = 700049,
          Subtitle = "Because there are fewer people there, right? She tried to keep herself from the crowd with her last shred of sanity."
        },
        [20002501] = {
          ContentKR = "너희... 프시케를 찾으러 가는 거야?",
          DialogueId = 20002501,
          GUID = "3212FC52",
          NextDialogue = 20002502,
          SpeakNpcId = 200045,
          Subtitle = "Are you... going to find Psyche?"
        },
        [20002502] = {
          ContentKR = "프시케를 찾게 되면... 망설이지 말고 그 아이의 고통을 끝내줘. 프시케도 그러길 바랄 거야...",
          DialogueId = 20002502,
          GUID = "3212FC7C",
          SpeakNpcId = 200045,
          Subtitle = "Once you find her, please, end her pains. I think she would want you to do the same..."
        },
        [20002601] = {
          ContentKR = "방금 그 언니는 왜 그렇게 빨리 뛰어간 거예요?",
          DialogueId = 20002601,
          GUID = "32130CBA",
          NextDialogue = 20002602,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc1",
          Subtitle = "That young lady just swooshed by. How did she do that?",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CBA"
        },
        [20002602] = {
          ContentKR = "쉿! 빨리 가자. 성 안으로 들어가. 저건 침식자야!",
          DialogueId = 20002602,
          GUID = "32130CE4",
          NextDialogue = 20002603,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc2",
          Subtitle = "Ssh, drop it and get back into the city! That is a Deteriorator!",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CE4"
        },
        [20002603] = {
          ContentKR = "당... 당황하지 마... 이미 누군가 수비대를 부르러 갔어!",
          DialogueId = 20002603,
          GUID = "32130D0E",
          NextDialogue = 20002604,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc3",
          Subtitle = "Don...Don't panic... The Escort will be here soon!",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D0E"
        },
        [20002604] = {
          ContentKR = "이런 식으로 몰래 들어가려는 건 아니겠지. 통행증, 통행증을 보여줘!",
          DialogueId = 20002604,
          GUID = "32130D38",
          NextDialogue = 20002605,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc4",
          Subtitle = "Don't you slip into the city amidst the chaos! Show your travel permit first!",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D38"
        },
        [20002605] = {
          ContentKR = "제발 들여보내 주세요. 통행증은 정말 실수로 잃어버렸을 뿐이에요!",
          DialogueId = 20002605,
          GUID = "32130D62",
          NextDialogue = 20002606,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc5",
          Subtitle = "Please, let us in. We did accidentally lose our travel permit! ",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D62"
        },
        [20002606] = {
          ContentKR = "이런 때에 무슨 통행증이야. 어차피 밖에 있어도 죽을 텐데 그냥 들어가버리자고!",
          DialogueId = 20002606,
          GUID = "32130D8C",
          NextDialogue = 20002607,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc6",
          Subtitle = "All you can think of is that damn travel permit! We must get in, or we'll die here!",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D8C"
        }
      }
    end
  },
  {
    MinKey = 20002607,
    MaxKey = 20006402,
    Loader = function()
      return {
        [20002607] = {
