        },
        [20002609] = {
          ContentKR = "정말... 독하구나. 좋아, 일단 들어와. 수비대가 침식자를 처리하면 그때 다시 얘기하자.",
          DialogueId = 20002609,
          GUID = "32130E0A",
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc9",
          Subtitle = "You... Fine, just get in. I'll get to you after the Escort has taken care of the Deteriorator.",
          VoiceName = "voice/$Locale$/story/2001/200026/32130E0A"
        },
        [20002701] = {
          ContentKR = "바람이 너무 세... 직접 뛰어내리면 날아갈 거야.",
          DialogueId = 20002701,
          GUID = "32131D22",
          NextDialogue = 20002702,
          SpeakNpcId = 200021,
          Subtitle = "The wind is strong... Taking a direct jump could get us blown away.",
          VoiceName = "voice/$Locale$/story/2001/200027/32131D22"
        },
        [20002702] = {
          ContentKR = "저기, 우리 승강기를 타고 내려가자.",
          DialogueId = 20002702,
          GUID = "32131D4C",
          SpeakNpcId = 200021,
          Subtitle = "Over there, we could use the lift.",
          VoiceName = "voice/$Locale$/story/2001/200027/32131D4C"
        },
        [20002801] = {
          ContentKR = "괜찮아, 우리는 프시케가 어디로 갔는지 알았으니 따라가기만 하면 돼.",
          DialogueId = 20002801,
          Duration = 3,
          GUID = "32132D8A",
          NextDialogue = 20002802,
          SpeakNpcId = 200021,
          Subtitle = "It's okay, we already know where Psyche has gone. All we have to do is follow her trail.",
          VoiceName = "voice/$Locale$/story/2001/200028/32132D8A"
        },
        [20002802] = {
          ContentKR = "맞아, 프시케만 찾으면 반드시 방법이 있을 거야!",
          DialogueId = 20002802,
          Duration = 3,
          GUID = "32132DB4",
          NextDialogue = 20002803,
          SpeakNpcId = 200002,
          Subtitle = "Right! As long as we can find Psyche, there's gotta be a way to save her!",
          VoiceName = "voice/$Locale$/story/2001/200028/32132DB4"
        },
        [20002803] = {
          ContentKR = "고마워...",
          DialogueId = 20002803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "32132DDE",
          SpeakNpcId = 100001,
          Subtitle = "Thank you...",
          VoiceName = "voice/$Locale$/story/2001/200028/32132DDE"
        },
        [20002901] = {
          ContentKR = "(이미 아웃사이더와 스노우에게 오늘 있었던 일을 다 얘기했는데.)",
          DialogueId = 20002901,
          DisableMouth = 1,
          Duration = 3,
          GUID = "32133DF2",
          NextDialogue = 20002902,
          Subtitle = "(I've filled in Outsider and Snow on everything that happened today.)"
        },
        [20002902] = {
          ContentKR = "(이제 할 수 있는 건, 약속 장소에서... 기다리는 것뿐이야.)",
          DialogueId = 20002902,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "32133E1C",
          Subtitle = "(Now, all that's left to do is get to the meeting spot... and wait.)"
        },
