          SpeakNpcId = 200074,
          Subtitle = "Thank you, Ms Camilla! I was a little nervous back there and ended up calling Vivar Winery \"Wawa Winery\"... Sorry...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150BC8"
        },
        [20005717] = {
          Camera = "294.547546,290.117188,144.820312,-0.000763,4.408443,-13.40922,35.0,169.661919 ,false,Manual,4.0",
          ContentKR = "괜찮아. 녀석들은 내가 준 술에 완전히 정신이 팔려서 무슨 말을 하든 들리지도 않을 거야.",
          DialogueId = 20005717,
          FinalCamera = "304.853149,286.924805,145.734375,-0.000763,7.408207,-13.809915,35.0,169.661919 ,false,Manual,4.0",
          GUID = "32150BF2",
          NextDialogue = 20005719,
          SpeakNpcId = 700248,
          Subtitle = "It's okay. They were too busy drowning themselves in the wine I gave them to care.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150BF2"
        },
        [20005718] = {
          Camera = "141.321762,448.1875,118.052734,-0.000763,2.207988,-38.807972,35.0,369.08606,false,Manual,12.0",
          ContentKR = "그럼, 네가 그 마령 사냥꾼들을 빨리 찾아내길 바랄게, 식량 보급원 씨.",
          DialogueId = 20005718,
          FinalCamera = "123.571815,447.842773,138.019531,-0.000763,-2.595362,-36.363739,35.000011,503.919495,false,Manual,12.0",
          GUID = "32150C1C",
          LookAt = {
            [1] = "700248:n(200074)"
          },
          NextDialogue = 20005719,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.1},ActorId{200074},AnimationId{"Sigh_End"}},
SEQ{
PlayAnimation{_delay{2.1},ActorId{700248},AnimationId{"Talk02_Start"}},
PlayAnimation{_delay{2.1},ActorId{700248},AnimationId{"Talk02_End"}}
}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Alright, hope you track down those Geniemon poachers soon, little commissary.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150C1C"
        },
        [20005719] = {
          Camera = "154.377365,415.154297,99.683594,-0.000763,-3.236574,-15.412816,35.000011,369.08606,false,Manual,12.0",
          ContentKR = "드디어 들어왔네, 트러플, 잘 왔어!",
          DialogueId = 20005719,
          FinalCamera = "157.402649,409.47168,99.427734,-0.000763,-3.836606,-14.613382,35.000011,369.08606,false,Manual,12.0",
          GUID = "32150C46",
          NextDialogue = 20005720,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{200002},AnimationId{"Confident_Start"}},
PlayFacial{_delay{0.5},ActorId{200002},FacialId{"Happy02"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "You made it, Truffle! Welcome to Icelake!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150C46"
        },
        [20005720] = {
          Camera = "496.032623,271.400391,167.851562,-0.000763,-15.436493,171.781372,35.000011,285.391632,false,Manual,12.0",
          ContentKR = "헤헤, 그 무섭던 경비들이 카밀라 씨 앞에서는 마령처럼 얌전해졌어.",
          DialogueId = 20005720,
          FinalCamera = "535.708679,265.305664,177.851562,-0.000763,-14.436451,172.180801,35.000011,285.391632,false,Manual,12.0",
          GUID = "32150C70",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20005721,
          Scripts = [[
SEQ{
PARA{
PlayAnimation{_delay{0.1},ActorId{200074},AnimationId{"Talk02_Start"}},
PlayFacial{_delay{1.1},ActorId{200074},FacialId{"Smile02"}}
},
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{"Talk02_End"}},
}]],
          SpeakNpcId = 200074,
          Subtitle = "Hehe, who would've thought those big, scary guards would turn into meek little kittens in front of Ms Camilla? Just like Geniemons when you've got treats.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150C70"
        },
        [20005721] = {
          Camera = "326.630066,314.076172,119.080078,-0.000763,-0.992235,160.615051,35.000008,86.408539,false,Manual,12.0",
          ContentKR = "아, 마령 얘기하니까 생각나네, 이제 그 나쁜 놈들을 찾아야겠어. 아이스레이크 시티는 내가 생각했던 것보다 훨씬 크네, 서둘러야겠어!",
          DialogueId = 20005721,
          GUID = "32150C9A",
          NextDialogue = 20005722,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.01},TargetPosition{"405.59903,285.685547,124.849609,-0.000763,-5.39227,160.014969,35.000008,216.630737,false,Manual,12.0"},duration{0}},
SEQ{
PlayFacial{_delay{0.3},ActorId{200074},FacialId{"Shock01"}},
PARA{
PlayAnimation{_delay{2.1},ActorId{200074},AnimationId{"Explain02_Start"}},
PlayFacial{_delay{2.1},ActorId{200074},FacialId{"Confident01"}}
},
PlayAnimation{_delay{5.1},ActorId{200074},AnimationId{"Explain02_End"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "Oh! Speaking of which, we've got bad guys to catch! Icelake is WAY bigger than I expected — we need to hurry!",
          VoiceName = "voice/$Locale$/story/2001/200057/32150C9A"
        },
        [20005722] = {
          Camera = "345.16864,317.928711,137.46875,-0.000763,1.607089,136.417633,35.0,169,false,Manual,12.0",
          ContentKR = "단서라도 있어?",
          DialogueId = 20005722,
          FinalCamera = "311.653595,331.706055,134.34375,-0.000763,4.806766,132.015808,35.0,169.08606,false,Manual,12.0",
          GUID = "32150CC4",
          NextDialogue = 20005723,
          SpeakNpcId = 100001,
          Subtitle = "Do you have any idea?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150CC4"
        },
        [20005723] = {
          Camera = "427.671539,393.154297,128.347656,-0.000763,-6.992433,-162.983078,35.000008,216.630737,false,Manual,12.0",
          ContentKR = "단서 있지! 믿음직한 헤이즐넛. 헤이즐넛은 후각이 엄청 예민해서 근처의 마령들이 어디 있는지 금방 찾아낼 수 있을 거야. 그러면 그 마령 사냥꾼들도 쉽게 잡을 수 있겠지!",
          DialogueId = 20005723,
          FinalCamera = "427.671539,393.154297,128.347656,-0.000763,-8.192443,-154.983536,35.000008,216.630737,false,Manual,12.0",
          GUID = "32150CEE",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          Scripts = [[
PARA{
PlayFacial{_delay{2.1},ActorId{200074},FacialId{"Happy01"}},
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{"Confident_Start"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "I have my dear — Filbert! Filbert's nose is incredible — she can sniff out Geniemons from miles away! And those bad hunters must be around!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200074:p(45)"
          },
          VoiceName = "voice/$Locale$/story/2001/200057/32150CEE"
        },
        [20005801] = {
          ContentKR = "가자, 먼저 높은 곳으로 올라가자. 높은 곳일수록 냄새가 더 멀리 퍼지거든.",
          DialogueId = 20005801,
          GUID = "321519BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let's go higher. The scent spreads farther up there.",
          VoiceName = "voice/$Locale$/story/2001/200058/321519BA"
        },
        [20005802] = {
          ContentKR = "앗, 헤이즐넛이 냄새를 맡았어, 저쪽이야!",
          DialogueId = 20005802,
          GUID = "321519E4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Oh! Filbert's onto something — over there!",
          VoiceName = "voice/$Locale$/story/2001/200058/321519E4"
        },
        [20005803] = {
          ContentKR = "여긴데... 마령은 없고, 대신...",
          DialogueId = 20005803,
          GUID = "32151A0E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "This should be the place. Strange, I don't see any Geniemons but—",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A0E"
        },
        [20005804] = {
          ContentKR = "이건 그들이 설치한 함정의 흔적이야. 정말 나빴어, 벌써 떠난 것 같아.",
          DialogueId = 20005804,
          GUID = "32151A38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005805,
          SpeakNpcId = 200074,
          Subtitle = "The trap they set up! Those baddies must have been here moments ago.",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A38"
        },
        [20005805] = {
          ContentKR = "그럼, 다음엔 사람이 적은 곳으로 가자. 그쪽이 냄새를 더 잘 맡을 수 있을 거야.",
          DialogueId = 20005805,
          GUID = "32151A62",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let's try somewhere quieter. The scent will stand out more where there are fewer people.",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A62"
        },
        [20005901] = {
          ContentKR = "여기야 여기, {性别:오빠|언니} 서두르지 마, 천천히 와, 미끄러지겠다.",
          DialogueId = 20005901,
          GUID = "32152A22",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "This way! Careful, {性别:Sir|Miss} — it's slippery here.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A22"
        },
        [20005902] = {
          ContentKR = "어... 여기도 똑같아, 누군가 함정을 설치한 흔적이 있어.",
          DialogueId = 20005902,
          GUID = "32152A4C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005903,
          SpeakNpcId = 200074,
          Subtitle = "Ugh... Another trap here.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A4C"
        },
        [20005903] = {
          ContentKR = "꿀...",
          DialogueId = 20005903,
          GUID = "32152A76",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005904,
          SpeakNpcId = 200086,
          Subtitle = "Oink...",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A76"
        },
        [20005904] = {
          ContentKR = "헤이즐넛, 괜찮아. 다시 한번 찾아보자.",
          DialogueId = 20005904,
          GUID = "32152AA0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "It's okay, Filbert. Let's try another spot.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152AA0"
        },
        [20006001] = {
          Camera = "606.297791,-918.271484,784.640625,0.000207,-7.459188,79.056267,35.000015,174.116943,false,Manual,12.0",
          ContentKR = "여긴... 하수도 입구?",
          DialogueId = 20006001,
          FinalCamera = "541.89978,-1160.757812,832.416992,0.000208,-8.459162,77.455727,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153A8A",
          NextDialogue = 20006002,
          SpeakNpcId = 100001,
          Subtitle = "Is this... the entrance to the sewers?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153A8A"
        },
        [20006002] = {
          Camera = "-38.9104,-306.495117,391.232422,0.000209,-8.45895,-1.344757,35.000015,174.116943,false,Manual,12.0",
          ContentKR = "응, 이 근처엔 습기가 많고 사람도 별로 없어서 분명히 마령이 나타날 거야.",
          DialogueId = 20006002,
          FinalCamera = "-508.082397,-300.290039,450.730469,0.000209,-7.058932,-0.744781,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153AB4",
          NextDialogue = 20006003,
          SpeakNpcId = 200074,
          Subtitle = "Yes. The water vapor and quietness here make this a perfect spot for Geniemons.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153AB4"
        },
        [20006003] = {
          Camera = "-768.485962,-608.558594,293.948242,0.000155,-2.058947,167.054123,35.000015,174.116943,false,Manual,12.0",
          ContentKR = "하지만, 방금 그 두 곳의 마령이 모두 잡혀갔잖아. 여기도 똑같이 당했을까 봐 좀 걱정돼...",
          DialogueId = 20006003,
          FinalCamera = "-796.652222,-602.085938,292.908691,0.000155,-0.458948,167.453751,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153ADE",
          NextDialogue = 20006004,
          SpeakNpcId = 200074,
          Subtitle = "But... the two previous spots were already wiped clean. I've got a bad feeling about this one too...",
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ADE"
        },
        [20006004] = {
          Camera = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
          ContentKR = "앗, 아직 치워지지 않은 덫이야! 안에 마령이 한 마리 갇혀 있어!",
          DialogueId = 20006004,
          FinalCamera = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153B08",
          NextDialogue = 20006005,
          SpeakNpcId = 200002,
          Subtitle = "Look! They haven't taken this trap yet — and there's a Geniemon inside!",
          TalkActionId = {
            [1] = "200074:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B08"
        },
        [20006005] = {
          Camera = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,733.116943,false,Manual,22.0",
          ContentKR = "잘됐다! 이번엔 드디어 제때 도착했네. 먼저 마령을 풀어주고, 그다음에 그 마령 사냥꾼들이 나타나길 기다리자.",
          DialogueId = 20006005,
          FinalCamera = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,733.116943,false,Manual,22.0",
          GUID = "32153B32",
          SpeakNpcId = 200074,
          Subtitle = "Finally! We made it in time for once. Let's get it out first, then wait for those baddies to show up.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B32"
        },
        [20006006] = {
          ContentKR = "우왕좌왕하는 사이 덫에 갇혀 있던 마령을 구해냈지만 마령의 태도가 왠지... 별로 우호적이지 않은 것 같다.",
          DialogueId = 20006006,
          GUID = "32153B5C",
          Subtitle = "After some scrambling, the trapped Geniemon is freed. However... it doesn't seem very friendly.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153B5C"
        },
        [20006007] = {
          Camera = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,22.0",
          ContentKR = "무서워하지 마, 마령아. 이 마왕님과 시종, 그리고 마령 사냥꾼 사냥꾼은 너희들을 구하러 온 거야. 이제 자유야, 여기서 멀리 떠나!",
          DialogueId = 20006007,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32153B86",
          LookAt = {
            [1] = "200002:n(820000)"
          },
          NextDialogue = 20006008,
          SpeakNpcId = 200002,
          Subtitle = "Don't be scared, little one~ The great Demon King and my loyal Little Minion, and the Geniemon Hunter Hunter, are here to save you! Now, off you go — get out of here and take care!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153B86"
        },
        [20006008] = {
          Camera = "-1100.135376,-637.394531,335.55957,0.000086,-3.391571,1.375749,35.0,1674.542114,false,Manual,6.0",
          ContentKR = "이이야~",
          DialogueId = 20006008,
          GUID = "32153BB0",
          NextDialogue = 20006009,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Yip—!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153BB0"
        },
        [20006009] = {
          Camera = "-619.304932,-686.379883,266.316895,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
          ContentKR = "그렇게 흥분할 필요 없어, 이건 우리가 당연히 해야 할 일이니까. 그런데 뭔가 눈에 좀 익은데? 혹시 아이스레이크 시티 밖에서 우리가 한 번 구해줬던 그 마령 아니야?",
          DialogueId = 20006009,
          FinalCamera = "-646.760498,-696.469727,267.117676,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153BDA",
          NextDialogue = 20006010,
          SpeakNpcId = 200002,
          Subtitle = "You're welcome. We're happy to help... Wait, this one looks kind of familiar. Did we save it once outside the city?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153BDA"
        },
        [20006010] = {
          Camera = "-422.686035,-758.615234,323.150879,0.000171,-5.031971,158.176743,35.000019,294.116943,false,Manual,12.0",
          ContentKR = "얼른 집으로 돌아가. 마령 사냥꾼들한테 다시 잡히면 안 되잖아! 내가 진정한 마령 사냥꾼 사냥꾼이 되기 전까지는, 더욱더 조심해야 해!",
          DialogueId = 20006010,
          GUID = "32153C04",
          LookAt = {
            [1] = "200074:n(820000)"
          },
          NextDialogue = 20006011,
          SpeakNpcId = 200074,
          Subtitle = "Now go home, and stay safe! Don't let those mean hunters catch you again. Until I'm a true, capable Geniemon Hunter Hunter, you'd better be extra careful.",
          TalkActionId = {
            [1] = "200074:Explain02_Start",
            [2] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153C04"
        },
        [20006011] = {
          Camera = "-781.993408,-607.023438,317.071777,0.00017,-1.2322,-155.023941,35.000019,174.116943,false,Manual,12.0",
          ContentKR = "똑같이 생기긴... 했네.",
          DialogueId = 20006011,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "32153C2E",
          NextDialogue = 20006012,
          SpeakNpcId = 100001,
          Subtitle = "I think we did.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153C2E"
        },
        [20006012] = {
          Camera = "-823.676147,-643.197266,314.435547,0.00011,-1.391562,0.574502,35.000008,242.039719,false,Manual,3.5",
          ContentKR = "이이이야——",
          DialogueId = 20006012,
          GUID = "32153C58",
          NextDialogue = 20006013,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Yiiiip—!",
          VoiceName = "voice/$Locale$/story/2001/200060/32153C58"
        },
        [20006013] = {
          Camera = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,314.116943,false,Manual,2.8",
          ContentKR = "에잇 진짜, 시끄럽게 하지 말고 얼른 가. 다음에 또 잡히면 이번처럼 운이 좋을 거란 보장 없어.",
          DialogueId = 20006013,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-444.914062,-637.505859,353.714355,0.000175,-13.432099,-162.221298,35.000019,324.116943,false,Manual,2.8",
          GUID = "32153C82",
          NextDialogue = 20006014,
          SpeakNpcId = 200002,
          Subtitle = "Alright, alright, enough yipping. Just go! You might not be this lucky next time.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153C82"
        },
        [20006014] = {
          Camera = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
          ContentKR = "내가 봤을 땐... 이 마령은 머리가 나쁜 것 같아, 이렇게 여러 번이나 말했는데도 안 가잖아.",
          DialogueId = 20006014,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "-644.868896,-667.681641,299.754395,0.000098,-11.858697,-147.368286,35.000023,174.116943,false,Manual,12.0",
          GUID = "32153CAC",
          SpeakNpcId = 200002,
          Subtitle = "Hmm... I don't think this one is very bright. We explained everything, but it just won't leave.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153CAC"
        },
        [20006015] = {
          ContentKR = "철컥!",
          DialogueId = 20006015,
          GUID = "32153CD6",
          Subtitle = "*clack*—",
          VoiceName = "voice/$Locale$/story/2001/200060/32153CD6"
        },
        [20006016] = {
          Camera = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
          ContentKR = "어? 왜 또 덫 안으로 들어가는 거지? 이 마령, 설마 우리가 너무 무서워서 덫을 안전한 곳이라고 생각하는 거 아니야?",
          DialogueId = 20006016,
          FinalCamera = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
          GUID = "32153D00",
          NextDialogue = 20006017,
          SpeakNpcId = 200002,
          Subtitle = "Wait... Did it just slip back into the trap!? Is it so scared of us that it thinks the trap is safer?",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D00"
        },
        [20006017] = {
          Camera = "-760.560303,-565.728516,290.460938,0.000099,-1.191192,-176.627136,35.000011,174.459366,false,Manual,2.8",
          ContentKR = "음, 이상하네. 분명 우리가 녀석을 구해줬고 적대적인 태도도 보이지 않았잖아. 마령들은 비록 말은 못 해도, 누가 자기한테 잘해줬는지, 누가 해를 끼치는지는 분명히 구분할 줄 아는데 말이야.",
          DialogueId = 20006017,
          FacialId = {
            [1] = "200074:Sad01"
          },
          FinalCamera = "-784.401123,-567.131836,289.964355,0.000099,-1.191192,-176.427139,35.000011,138.232086,false,Manual,2.8",
          GUID = "32153D2A",
          NextDialogue = 20006018,
          SpeakNpcId = 200074,
          Subtitle = "That doesn't make sense... We rescued it, and we didn't do anything bad to it. Geniemons might not talk, but they can tell good from bad.",
          TalkActionId = {
            [1] = "200074:Think_Start",
            [2] = "200002:SpecialConfident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D2A"
        },
        [20006018] = {
          Camera = "-538.68689,-695.786133,229.021973,0.000027,5.603125,151.387604,35.000008,345.779022,false,Manual,12.0",
          ContentKR = "생각해보자... 헤이즐넛이 이런 식으로 내가 전혀 이해할 수 없는 행동을 한 적이 있었나...?",
          DialogueId = 20006018,
          FinalCamera = "-556.785034,-685.914062,231.044922,0.000028,5.603125,151.387619,35.000008,278.757599,false,Manual,12.0",
          GUID = "32153D54",
          NextDialogue = 20006019,
          SpeakNpcId = 200074,
          Subtitle = "Hmm... let me think — has Filbert ever done something that didn't make sense to me at first...?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D54"
        },
        [20006019] = {
          Camera = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
          ContentKR = "한 번은 꼭 아무것도 없는 골짜기에 가야 한다고 고집을 부렸었지. 나중에 알고 보니 골짜기 깊숙한 곳에서 잔뜩 나는 베리 냄새를 맡았던 거였고... 또 한 번은 꽃집 문 앞에서 꼼짝도 안 하고 서 있었는데, 내가 꽃을 사니까 기뻐하며 한입에 먹어 치웠어...",
          DialogueId = 20006019,
          FinalCamera = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
          GUID = "32153D7E",
          NextDialogue = 20006020,
          SpeakNpcId = 200074,
          Subtitle = "There was that one time she insisted on going into a valley that looked barren — turns out she'd sniffed out a hidden patch of berries deep inside. Then there was the time she wouldn't budge from a flower shop until I bought some flowers — just so she could eat them in one bite.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D7E"
        },
        [20006020] = {
          ContentKR = "또 한 번은, 갑자기 날 두고 산비탈 위로 필사적으로 뛰어간 거였어. 알고 보니 근처 풀숲에 뱀이 있었기 때문에... 뱀을 멀리 유인해 내려고 했던 거지...",
          DialogueId = 20006020,
          GUID = "32153DA8",
          NextDialogue = 20006021,
          SpeakNpcId = 200074,
          Subtitle = "And that other time, when she suddenly took off, sprinting straight up a hill without looking back at me for once. Then I realised there was a snake in the grass, and she was leading it away.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153DA8"
        },
        [20006021] = {
          Camera = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
          ContentKR = "음... 전부 뭔가 굉장히 신경 쓰이는 일이 있었기 때문이었네. 그렇다면 마령이 신경 쓸 만한 건 뭐가 있을까? 먹이... 그리고 동료!",
          DialogueId = 20006021,
          FinalCamera = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
          GUID = "32153DD2",
          NextDialogue = 20006022,
          SpeakNpcId = 200074,
          Subtitle = "Every time she acted strange, it was because of something really important to her... What's important to a Geniemon? Food? And perhaps... their friends!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153DD2"
        },
        [20006022] = {
          Camera = "-800.104004,-669.561523,327.374512,0.000095,-2.797638,176.175522,35.000008,104.665184,false,Manual,12.0",
          ContentKR = "동료... 알겠다! 내 추측이 맞다면, 그 마령 사냥꾼들의 은신처는 하수도 안에 있는 게 분명해!",
          DialogueId = 20006022,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "32153DFC",
          NextDialogue = 20006023,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"535.722229,-1070.53125,709.230469,0.000068,-6.997009,79.177307,35.0,174.116943,false,Manual,12.0\"},duration{0}},CameraMoveTo{_delay{0.5},TargetPosition{\"868.026001,153.00293,482.812988,0.000102,-2.791628,85.174393,35.000008,1674.542114,false,Manual,2.8\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Friends... That's it! If I'm right, those Geniemon hunters must be hiding in the sewers.",
          TalkActionId = {
            [1] = "200074:Think_End",
            [2] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153DFC"
        },
        [20006023] = {
          Camera = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
          ContentKR = "사로잡힌 마령 친구들의 냄새를 맡을 수 있었던 거야. 그래서 이곳을 떠나기 싫어했던 거였어.",
          DialogueId = 20006023,
          FacialId = {
            [1] = "100001:Confident02"
          },
          FinalCamera = "-771.952148,-667.40625,310.516113,0.000069,5.202958,177.175873,35.0,174.116943,false,Manual,12.0",
          GUID = "32153E26",
          NextDialogue = 20006024,
          SpeakNpcId = 100001,
          Subtitle = "This Geniemon can smell the scent of its captured friends from here — that's why it won't leave.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E26"
        },
        [20006024] = {
          Camera = "-821.866577,-728.666992,342.821289,0.000095,-11.597776,130.969742,35.000008,178.123947,false,Manual,2.8",
          ContentKR = "그럴 가능성이 높아! 그럼, 여기서 숨어 기다리면 되겠네. 그 마령 사냥꾼들이 나타나면, 바로 뒤따라가서 제대로 혼쭐을 내주자!",
          DialogueId = 20006024,
          FacialId = {
            [1] = "200074:Confident01"
          },
          FinalCamera = "-828.375366,-721.172852,340.748047,0.000093,-11.797785,130.969742,35.000008,178.123947,false,Manual,2.8",
          GUID = "32153E50",
          NextDialogue = 20006025,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200074:n(100001)"}},
LookAt{LookAtDescription{"100001:n(200074)"}},
PlayAnimation{ActorId{200074},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{5},
ActorId{200074},AnimationId{"Angry01_Start"},Duration{2}}}]],
          SpeakNpcId = 200074,
          Subtitle = "That makes so much sense! In that case, we can wait right here. And as long as those bad hunters show up, we can follow them and teach them a good lesson!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E50"
        },
        [20006025] = {
          Camera = "-788.137817,-637.754883,224.224121,0.000072,-2.597166,-0.625336,35.0,174.116943,false,Manual,12.0",
          ContentKR = "응응응!",
          DialogueId = 20006025,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-756.913574,-638.139648,223.32666,0.000072,-3.397097,-1.225342,35.0,174.116943,false,Manual,12.0",
          GUID = "32153E7A",
          NextDialogue = 20006026,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_PanBeikun",
          Subtitle = "Yiip—!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E7A"
        },
        [20006026] = {
          Camera = "-412.370728,-629.598633,225.119141,0.000073,3.802544,-175.221069,28.0,265.494751,false,Manual,12.0",
          ContentKR = "음, 이 마령은 똑똑하다고 해야 할지, 아니면 멍청하다고 해야 할지 모르겠네. 동료를 찾으려는 걸 보면 똑똑하다고 할 수 있는데 스스로 덫에 들어가는 건 좀 멍청한 것 같기도 하고.",
          DialogueId = 20006026,
          FinalCamera = "-412.370728,-629.598633,241.541992,0.000073,0.002452,-175.420853,28.0,265.494751,false,Manual,12.0",
          GUID = "32153EA4",
          LookAt = {
            [1] = "200002:n(700251)"
          },
          NextDialogue = 20006027,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200074:n(200074)"}},
LookAt{LookAtDescription{"100001:n(100001)"}},
PlayAnimation{ActorId{200074},AnimationId{"Angry01_End"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "So, is this Geniemon smart or dumb? I mean, it's got the brains to want us to save its friends, but it also just walked right back into a trap...",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153EA4"
        },
        [20006027] = {
          Camera = "-700.815918,-705.999023,263.483887,0.000069,3.402636,153.177032,35.0,174.116943,false,Manual,12.0",
          ContentKR = "우리를 보고 일부러 다시 덫에 들어간 걸지도 모르잖아. 우리가 더 잘 추적할 수 있게 하려고 말이야. ",
          DialogueId = 20006027,
          FinalCamera = "-755.168457,-688.192383,266.806152,0.000068,3.602624,148.576843,35.0,174.116943,false,Manual,12.0",
          GUID = "32153ECE",
          NextDialogue = 20006028,
          SpeakNpcId = 200074,
          Subtitle = "Maybe it did that on purpose? That way we can just follow the bad guys who come to collect the trapped Geniemon to their hideout.",
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ECE"
        },
        [20006028] = {
          Camera = "-486.203613,-623.530273,240.246582,0.000087,2.002625,-162.023193,35.0,174.116943,false,Manual,12.0",
          ContentKR = "에이 설마, 내 생각엔...",
          DialogueId = 20006028,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-531.324463,-638.469727,243.410156,0.000087,4.602584,-160.822952,35.0,174.116943,false,Manual,12.0",
          GUID = "32153EF8",
          NextDialogue = 20006029,
          SpeakNpcId = 200002,
          Subtitle = "Oh, really? That's—",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153EF8"
        },
        [20006029] = {
          ContentKR = "어라? 나쁘지 않네, 진짜 한 마리 잡았잖아.",
          DialogueId = 20006029,
          GUID = "32153F22",
          NextDialogue = 20006030,
          SpeakNpcId = 200075,
          Subtitle = "Oh? Not bad. Looks like we caught another one.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153F22"
        },
        [20006030] = {
          Camera = "-647.833496,-724.029297,337.969727,0.000094,-6.997679,159.175262,35.0,324.116943,false,Manual,12.0",
          ContentKR = "마령 사냥꾼이야, 얼른 숨자.",
          DialogueId = 20006030,
          GUID = "32153F4C",
          NextDialogue = 20006031,
          SpeakNpcId = 100001,
          Subtitle = "It's the Geniemon hunters! Quick, hide!",
          TurnTo = {
            [1] = "100001:n(200074)",
            [2] = "200074:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153F4C"
        },
        [20006031] = {
          ContentKR = "그래!",
          DialogueId = 20006031,
          GUID = "32153F76",
          SpeakNpcId = 200074,
          Subtitle = "Got it!",
          VoiceName = "voice/$Locale$/story/2001/200060/32153F76"
        },
        [20006032] = {
          Camera = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
          ContentKR = "지금 당장 때려주고 싶지만 참겠어. 이따가 혼쭐을 내줄 거야!",
          DialogueId = 20006032,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
          GUID = "32153FA0",
          NextDialogue = 20006033,
          SpeakNpcId = 200002,
          Subtitle = "Ugh, I really want to punch 'em... Let's just take notes for now and settle the score with them later!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FA0"
        },
        [20006033] = {
          Camera = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
          ContentKR = "아이스레이크 시티의 마령은 다 잡은 줄 알았는데, 뜻밖의 수확이군요.",
          DialogueId = 20006033,
          GUID = "32153FCA",
          NextDialogue = 20006034,
          SpeakNpcId = 200075,
          Subtitle = "I thought we'd already captured all the Geniemons in Icelake, but looks like we scored another one.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153FCA"
        },
        [20006034] = {
          Camera = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          ContentKR = "역시 성 밖으로 나와야 더 많이 잡을 수 있어. 그 돼지 타고 다니는 꼬마는 언제쯤이면 떠날까.",
          DialogueId = 20006034,
          FinalCamera = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          GUID = "32153FF4",
          NextDialogue = 20006035,
          SpeakNpcId = 200087,
          Subtitle = "We still need to head out of the city — that's where the real haul is. But that pig-riding brat is always out there messing with us.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FF4"
        },
        [20006035] = {
          ContentKR = "조급해할 거 없어요. 반달 정도 더 버티고, 그녀가 계속 거기 지킬 수 있을까요?",
          DialogueId = 20006035,
          GUID = "3215401E",
          NextDialogue = 20006036,
          SpeakNpcId = 200075,
          Subtitle = "Don't worry, she'll leave. No way she's gonna camp out there forever.",
          TalkActionId = {
            [1] = "200075:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/3215401E"
        },
        [20006036] = {
          ContentKR = "그건 그렇지, 날도 춥고 필토이드들도 있는데, 어쩌면 내일쯤엔 울면서 집으로 돌아갈지도 몰라.",
          DialogueId = 20006036,
          GUID = "32154048",
          NextDialogue = 20006037,
          SpeakNpcId = 200087,
          Subtitle = "Right. With the cold and the Filthoids, I'd bet she'll be crying her way home in a day or two.",
          TalkActionId = {
            [1] = "200075:Talk02_End",
            [2] = "200087:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154048"
        },
        [20006037] = {
          ContentKR = "그럼 최고죠!",
          DialogueId = 20006037,
          GUID = "32154072",
          SpeakNpcId = 200075,
          Subtitle = "Yeah! She better be!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154072"
        },
        [20006101] = {
          Camera = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
          ContentKR = "놈들이 하수도로 돌아간다, 얼른 따라가자.",
          DialogueId = 20006101,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32154AF2",
          NextDialogue = 20006102,
          Scripts = "PARA{SEQ{TurnTo{TurnToDescription{\"200002:n(100001)\"}},PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}},CameraMoveTo{_delay{2},TargetPosition{\"-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8\"},duration{0}}}",
          SpeakNpcId = 200002,
          Subtitle = "They're slipping back into the sewers! Come on, let's go!",
          VoiceName = "voice/$Locale$/story/2001/200061/32154AF2"
        },
        [20006102] = {
          Camera = "-691.08667,-817.638672,263.54541,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
          ContentKR = "조용히 해, 너무 들뜨지 말고, 마령 사냥꾼들한테 들키기라도 하면 저 마령이 널 바보라고 할 거야.",
          DialogueId = 20006102,
          FinalCamera = "-710.927734,-796.919922,267.683105,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
          GUID = "32154B1C",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 20006103,
          Scripts = "LookAt{LookAtDescription{\"200074:n(200002)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Shh, keep it down. If we give ourselves away, that Geniemon we just saved would probably call you an idiot in its Geniemon language.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B1C"
        },
        [20006103] = {
          Camera = "-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8",
          ContentKR = "흥, 절대 아니거든! 내가 아까 그렇게 신경 써줬으니, 분명 나한테 좋은 인상이 남았을 거야!",
          DialogueId = 20006103,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "32154B46",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20006104,
          SpeakNpcId = 200002,
          Subtitle = "Hmph! No way. I was so nice to it — I must have made a good impression.",
          VoiceName = "voice/$Locale$/story/2001/200061/32154B46"
        },
        [20006104] = {
          Camera = "-832.142822,-728.967773,342.387207,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
          ContentKR = "푸흡... 너희들... 내가 나이는 어리지만, 헤이즐넛이랑 같이 다니면서 사람도 많이 봤거든. 근데 마령 생각까지 신경 쓰는 사람은 정말 드물었어.",
          DialogueId = 20006104,
          FinalCamera = "-837.814453,-721.487305,340.496582,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
          GUID = "32154B70",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006105,
          SpeakNpcId = 200074,
          Subtitle = "Haha... You two really are something. I've met plenty of people travelling with Filbert, but few people genuinely care about what Geniemons think.",
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B70"
        },
        [20006105] = {
          ContentKR = "누구나 다 너희들처럼 동물이랑 마령도 자기 취향이 있다는 걸 알았다면, 마령 사냥꾼 같은 건 없었을 거야!",
          DialogueId = 20006105,
          GUID = "32154B9A",
          NextDialogue = 20006106,
          SpeakNpcId = 200074,
          Subtitle = "If more people understood that Geniemons have their own thoughts and feelings, just like you do, we wouldn't have Geniemon hunters in the first place!",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200061/32154B9A"
        },
        [20006106] = {
          Camera = "-809.379883,-578.354492,277.954102,0.000212,5.809533,178.160782,35.000011,115.034302,false,Manual,2.8",
          ContentKR = "가자, 가자! 이번엔 제대로 잘못을 깨닫게 해줄 거야!",
          DialogueId = 20006106,
          FinalCamera = "-822.223877,-577.945312,279.260742,0.000213,5.809533,178.160782,35.000011,110.479393,false,Manual,2.8",
          GUID = "32154BC4",
          LookAt = {
            [1] = "200074:n(200074)"
          },
          SpeakNpcId = 200074,
          Subtitle = "Let's go. This time, I'll make sure they learn their lesson once and for all!",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154BC4"
        },
        [20006201] = {
          Camera = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
          ContentKR = "음, 여기 하수도는 정말 복잡하네. 헤이즐넛, 마령의 냄새를 맡을 수 있겠어?",
          DialogueId = 20006201,
          GUID = "32155B5A",
          NextDialogue = 20006202,
          SpeakNpcId = 200074,
          Subtitle = "I didn't realise there would be so many tunnels in the sewers... Filbert, can you pick up a Geniemon's scent?",
          VoiceName = "voice/$Locale$/story/2001/200062/32155B5A"
        },
        [20006202] = {
          ContentKR = "꿀...",
          DialogueId = 20006202,
          GUID = "32155B84",
          NextDialogue = 20006203,
          SpeakNpcId = 200086,
          Subtitle = "Oink...",
          VoiceName = "voice/$Locale$/story/2001/200062/32155B84"
        },
        [20006203] = {
          ContentKR = "냄새가 너무 많아서 방향을 못 잡겠다고? 음, 그럼 일단 앞으로 가볼 수밖에 없겠네.",
          DialogueId = 20006203,
          GUID = "32155BAE",
          NextDialogue = 20006204,
          SpeakNpcId = 200074,
          Subtitle = "Too many overlapping smells? Hmm... Let's just keep moving then.",
          VoiceName = "voice/$Locale$/story/2001/200062/32155BAE"
        },
        [20006204] = {
          ContentKR = "나만 따라오면 돼, 여긴 내가 잘 알아.",
          DialogueId = 20006204,
          GUID = "32155BD8",
          NextDialogue = 20006205,
          SpeakNpcId = 200002,
          Subtitle = "Just follow me. I know my way around here.",
          VoiceName = "voice/$Locale$/story/2001/200062/32155BD8"
        },
        [20006205] = {
          ContentKR = "어? 스노우는 평소에 이런 곳에서 지내는 거야?",
          DialogueId = 20006205,
          GUID = "32155C02",
          NextDialogue = 20006206,
          SpeakNpcId = 200074,
          Subtitle = "Huh? Why? Is this where you live?",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C02"
        },
        [20006206] = {
          ContentKR = "아니... 아니야! 마왕님으로서 전에 몇 번 여기 순찰하러 온 적이 있을 뿐이야. 멀리서 온 마령 사냥꾼 사냥꾼이여, 잘 따라오라고!",
          DialogueId = 20006206,
          GUID = "32155C2C",
          NextDialogue = 20006207,
          SpeakNpcId = 200002,
          Subtitle = "O...Of course not. But as the great Demon King, I've inspected these tunnels many times. Now, keep up, foreign Geniemon Hunter Hunter!",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C2C"
        },
        [20006207] = {
          ContentKR = "그래~",
          DialogueId = 20006207,
          GUID = "32155C56",
          SpeakNpcId = 200074,
          Subtitle = "Okay~",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C56"
        },
        [20006301] = {
          ContentKR = "어? 이 흔적은, 전에 순찰할 땐 본 적 없었는데.",
          DialogueId = 20006301,
          GUID = "32156BC2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 20006302,
          SpeakNpcId = 200002,
          Subtitle = "Ah, this mark wasn't here last time I checked.",
          VoiceName = "voice/$Locale$/story/2001/200063/32156BC2"
        },
        [20006302] = {
          ContentKR = "잡혀간 그 마령이 남긴 흔적 같아, 이 흔적을 따라가 보자.",
          DialogueId = 20006302,
          GUID = "32156BEC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Looks like something the Geniemon we just saved might have left behind. Let's follow it.",
          VoiceName = "voice/$Locale$/story/2001/200063/32156BEC"
        },
        [20006401] = {
          ContentKR = "흔적이 점점 선명해져, 아마 멀지 않은 것 같아...",
          DialogueId = 20006401,
          GUID = "32157C2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20006402,
          SpeakNpcId = 200074,
          Subtitle = "The marks are getting fresher... It shouldn't be far.",
          VoiceName = "voice/$Locale$/story/2001/200064/32157C2A"
        },
        [20006402] = {
          ContentKR = "누군가 말하는 소리가 들리는 것 같아...",
          DialogueId = 20006402,
          GUID = "32157C54",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Wait— I think I hear voices...",
          VoiceName = "voice/$Locale$/story/2001/200064/32157C54"
        }
      }
    end
  },
  {
    MinKey = 20006501,
    MaxKey = 50103601,
    Loader = function()
      return {
        [20006501] = {
          Camera = "802.462891,37.094727,399.100616,0.000002,-18.600189,1.600099,35.000011,403.34671,false,Manual,12.0",
          ContentKR = "이 마령 말이야... 모든 마령 중에 제일 똑똑하고 희귀한 존재이며, 모든 마령의 최초 형태인 판신이라고 하더라고.",
          DialogueId = 20006501,
          FinalCamera = "559.453125,30.306641,481.861816,0.000002,-18.800184,1.600099,35.000011,403.34671,false,Manual,12.0",
          GUID = "32158C92",
          NextDialogue = 20006502,
          SpeakNpcId = 200075,
          Subtitle = "We hit the jackpot, you know — this one's special! It's called Paniemon, and they say it's the smartest, rarest, and the original form of all Geniemon.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158C92"
        },
        [20006502] = {
          ContentKR = "제일 똑똑하다고? 정말이요? 제일 똑똑한데 왜 우리한테 잡혔죠?",
          DialogueId = 20006502,
          GUID = "32158CBC",
          NextDialogue = 20006503,
          SpeakNpcId = 200087,
          Subtitle = "The smartest? Seriously? If it's so smart, how'd it end up in our trap?",
          TalkActionId = {
            [1] = "200087:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158CBC"
        },
        [20006503] = {
          Camera = "565.943359,-554.305664,435.741028,0.000025,-6.400112,56.795567,35.000008,100000.0,false,Manual,22.0",
          ContentKR = "무슨 뜻이야? 우리가 멍청해서 제일 똑똑한 마령을 잡을 수 없다는 거야?",
          DialogueId = 20006503,
          FinalCamera = "586.517578,-522.865234,431.526306,0.000026,-6.400112,56.795399,35.000008,100000.0,false,Manual,22.0",
          GUID = "32158CE6",
          LookAt = {
            [1] = "200075:n(200087)"
          },
          NextDialogue = 20006504,
          SpeakNpcId = 200075,
          Subtitle = "What do you mean? Are you saying we're too dumb to catch the smartest Geniemon?",
          TalkActionId = {
            [1] = "200075:Talk03_Start",
            [2] = "200087:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158CE6"
        },
        [20006504] = {
          Camera = "485.179688,62.989258,489.663513,0.000012,-12.999386,-2.199652,35.000008,450.0,false,Manual,6.0",
          ContentKR = "전... 전 그런 뜻이 아니라, 형님 똑똑하다는 거죠. 형님 만든 덫이 아니면 어떻게 이렇게 많은 마령을 잡을 수 있었겠냐는 거죠.",
          DialogueId = 20006504,
          FinalCamera = "610.728516,58.283203,460.538757,0.000012,-13.199401,-1.999653,35.000008,450.0,false,Manual,6.0",
          GUID = "32158D10",
          LookAt = {
            [1] = "200087:n(200075)"
          },
          NextDialogue = 20006505,
          SpeakNpcId = 200087,
          Subtitle = "O...Of course not, Boss! You're a genius! If it weren't for your traps, we wouldn't have caught half as many.",
          TalkActionId = {
            [1] = "200087:Shock_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/2001/200065/32158D10"
        },
        [20006505] = {
          ContentKR = "당연하지, 봐봐, 이미 이렇게 많은 마령을 잡았잖아. 천천히 연구하다 보면, 마령들한테서 월석을 추출하는 방법을 찾아내고 논문도 쓸 수 있을 거야.",
          DialogueId = 20006505,
          GUID = "32158D3A",
          LookAt = {
            [1] = "200075:n(200075)"
          },
          NextDialogue = 20006506,
          SpeakNpcId = 200075,
          Subtitle = "It's true. Now, with all the Geniemons we've rounded up, it's only a matter of time before I crack the secret to extracting Phoxene from them. And once I finish my thesis on it...",
          TalkActionId = {
            [1] = "200087:Shock_End",
            [2] = "200075:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D3A"
        },
        [20006506] = {
          ContentKR = "그때가 되면 아무도 내가 연금원의 중퇴생이라고 비웃을 수 없을 거야!",
          DialogueId = 20006506,
          GUID = "32158D64",
          NextDialogue = 20006507,
          SpeakNpcId = 200075,
          Subtitle = "I'd like to see who dares laugh at me for dropping out of the Alchemy Academy again!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D64"
        },
        [20006507] = {
          ContentKR = "형님, 전 논문엔 관심 없고, 실버나 조금 나눠주면 돼요.",
          DialogueId = 20006507,
          GUID = "32158D8E",
          NextDialogue = 20006508,
          SpeakNpcId = 200087,
          Subtitle = "Boss, I don't care much about all that thesis stuff. I just want to get my share of the silver coins.",
          TalkActionId = {
            [1] = "200075:Angry01_End",
            [2] = "200087:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D8E"
        },
        [20006508] = {
          ContentKR = "그럼, 그건 당연하지.",
          DialogueId = 20006508,
          GUID = "32158DB8",
          LookAt = {
            [1] = "200087:n(200087)"
          },
          NextDialogue = 20006509,
          SpeakNpcId = 200075,
          Subtitle = "Sure, easy.",
          TalkActionId = {
            [1] = "200087:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158DB8"
        },
        [20006509] = {
          Camera = "0.919922,-0.328125,154.78241,0.000047,-0.999783,-169.994827,35.000008,147.718536,false,Manual,8.0",
          ContentKR = "별로 당연하지 않은 것 같은데.",
          DialogueId = 20006509,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "32158DE2",
          NextDialogue = 20006510,
          SpeakNpcId = 100001,
          Subtitle = "It won't be that easy from now on.",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158DE2"
        },
        [20006510] = {
          Camera = "460.484375,70.31543,355.815216,0.000048,1.599391,-2.995058,35.000008,300.0,false,Manual,8.0",
          ContentKR = "너희들은...",
          DialogueId = 20006510,
          FinalCamera = "525.451172,67.851562,357.435608,0.000048,1.39939,-2.39505,35.000008,300.0,false,Manual,8.0",
          GUID = "32158E0C",
          NextDialogue = 20006511,
          Scripts = "PARA{TurnTo{TurnToDescription{\"200075:p(-150)\"}},TurnTo{TurnToDescription{\"200087:p(150)\"}}}",
          SpeakNpcId = 200075,
          Subtitle = "Who are you...?",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E0C"
        },
        [20006511] = {
          Camera = "47.310547,-89.34375,82.346375,0.000071,6.199694,-170.591293,35.000011,184.872482,false,Manual,8.0",
          ContentKR = "난 순백의 구원자, 빛의 마왕님이시다!",
          DialogueId = 20006511,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "33.654297,-91.604492,83.850006,0.000072,8.199676,-167.790817,35.000011,131.269821,false,Manual,8.0",
          GUID = "32158E36",
          NextDialogue = 20006512,
          SpeakNpcId = 200002,
          Subtitle = "I am the Pure-White Redeemer ☆ Demon King of Light!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E36"
        },
        [20006512] = {
          Camera = "13.498047,83.051758,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
          ContentKR = "나... 난 마령 사냥꾼 사냥꾼, 식량보급원 트러플이다! 그리고 특별 식량보급원, 헤이즐넛이다!",
          DialogueId = 20006512,
          FinalCamera = "2.105469,81.813477,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
          GUID = "32158E60",
          NextDialogue = 20006513,
          Scripts = [[
PARA{
CameraMoveTo{_delay{6.01},TargetPosition{"150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0"},duration{0}},
SEQ{
PlayFacial{_delay{3.5},ActorId{200074},FacialId{"Confident01"}},
PlayAnimation{_delay{3.1},ActorId{200074},AnimationId{"Confident_Start"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "I... I am the Geniemon Hunter Hunter, Commissary Truffle! And Filbert, the Special Commissary!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E60"
        },
        [20006513] = {
          Camera = "150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0",
          ContentKR = "꿀꿀!",
          DialogueId = 20006513,
          FinalCamera = "134.871094,118.75,17.023186,0.000235,24.799322,157.617859,35.0,628.586243,false,Manual,12.0",
          GUID = "32158E8A",
          NextDialogue = 200065130,
          SpeakNpcId = 200086,
          Subtitle = "Oink, oink!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E8A"
        },
        [20006514] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,16.0",
          ContentKR = "그래 알겠어, 너희들은 갈레아 극장의 배우인 모양이군.",
          DialogueId = 20006514,
          GUID = "32158EB4",
          NextDialogue = 20006515,
          SpeakNpcId = 200075,
          Subtitle = "Oh, I get it. You're performers from the Galea Theatre.",
          TalkActionId = {
            [1] = "200075:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158EB4"
        },
        [20006515] = {
          Camera = "-26.337891,71.758789,115.010025,0.000102,5.001563,-179.000427,35.000019,100.535843,false,Manual,8.0",
          ContentKR = "아... 아니야! 어서 이 마령들을 풀어줘! 그렇지 않으면, 헤이즐넛이 너희들을 날려버리게 할 거야!",
          DialogueId = 20006515,
          GUID = "32158EDE",
          Scripts = [[
SEQ{
PlayFacial{_delay{0.1},ActorId{200074},FacialId{"Unacceptable01"}},
PlayFacial{_delay{0.6},ActorId{200074},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "That's not it...! Let the Geniemons go, or Filbert will knock you flying!",
          TalkActionId = {
            [1] = "200074:Confident_End",
            [2] = "200074:Disagree"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158EDE"
        },
        [20006516] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
          ContentKR = "아까 성 밖에서 우리 일을 망친 게 바로 너랑 저 빛의 마귀인가 뭔가 하는 녀석 아니야?",
          DialogueId = 20006516,
          GUID = "32158F08",
          NextDialogue = 20006517,
          SpeakNpcId = 200075,
          Subtitle = "Wasn't it you and that Demon King of something or other who ruined our hunt outside the city?",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158F08"
        },
        [20006517] = {
          Camera = "-27.242188,73.443359,154.929871,0.00007,-15.000351,-177.200226,35.000015,130.614029,false,Manual,8.0",
          ContentKR = "빛의 마왕님이야, 다른 사람의 이름을 제대로 기억하지 않는 건 정말 무례한 행동이야, 그러다 헤이즐넛한테 맞는다!",
          DialogueId = 20006517,
          FacialId = {
            [1] = "200074:Confident02"
          },
          GUID = "32158F32",
          LookAt = {
            [1] = "200074:n(200075)"
          },
          SpeakNpcId = 200074,
          Subtitle = "It's the Demon King of Light! It's very rude to get someone's name wrong! You'll get rammed by Filbert for that!",
          VoiceName = "voice/$Locale$/story/2001/200065/32158F32"
        },
        [20006518] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
          ContentKR = "꿈 깨라!",
          DialogueId = 20006518,
          GUID = "32158F5C",
          NextDialogue = 20006519,
          SpeakNpcId = 200075,
          Subtitle = "In — your— dreams!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158F5C"
        },
        [20006519] = {
          Camera = "9.128906,71.000977,164.786407,0.000102,-18.198389,-178.600586,35.000008,450.0,false,Manual,6.0",
          ContentKR = "그렇다면... 헤이즐넛, 날려버려!",
          DialogueId = 20006519,
          FinalCamera = "-9.466797,68.333008,115.745117,0.000102,3.801383,-177.600464,35.000011,131.004227,false,Manual,6.0",
          GUID = "32158F86",
          LookAt = {
            [1] = "200074:n(200075)"
          },
          Scripts = [[
SEQ{
PlayFacial{_delay{0.1},ActorId{200074},FacialId{"Confident02"}},
PlayFacial{_delay{1.6},ActorId{200074},FacialId{"Doubt01"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "If that's how you want it... Filbert, charge!",
          TalkActionId = {
            [1] = "200074:Confident_End",
            [2] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200065/32158F86"
        },
        [20006601] = {
          ContentKR = "그래 싸우자, 애들 몇 명이랑 짐승 하나쯤이야, 내가 무서워 할 줄 알아?",
          DialogueId = 20006601,
          GUID = "32159CFA",
          NextDialogue = 20006602,
          SpeakNpcId = 200087,
          Subtitle = "Pfft, what's the holdup? You think I'd be scared of a few kids and their walking pile of bacon?",
          VoiceName = "voice/$Locale$/story/2001/200066/32159CFA"
        },
        [20006602] = {
          ContentKR = "헤이즐넛은 짐승이 아니야! 헤이즐넛한테 사과해!",
          DialogueId = 20006602,
          GUID = "32159D24",
          NextDialogue = 20006603,
          SpeakNpcId = 200074,
          Subtitle = "You take that back! Apologize to Filbert now!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D24"
        },
        [20006603] = {
          ContentKR = "이기고나 말하시지!",
          DialogueId = 20006603,
          GUID = "32159D4E",
          SpeakNpcId = 200087,
          Subtitle = "Oh yeah? Make me!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D4E"
        },
        [20006604] = {
          ContentKR = "이이야~",
          DialogueId = 20006604,
          GUID = "32159D78",
          NextDialogue = 20006605,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D78"
        },
        [20006605] = {
          ContentKR = "큰일 났다, 형님! 저 마령이 다른 마령들을 다 풀어줬어요!",
          DialogueId = 20006605,
          GUID = "32159DA2",
          NextDialogue = 20006606,
          SpeakNpcId = 200075,
          Subtitle = "B—Boss! That Geniemon — it released all the other ones!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DA2"
        },
        [20006606] = {
          ContentKR = "쮸~",
          DialogueId = 20006606,
          GUID = "32159DCC",
          NextDialogue = 20006607,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Chirp—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DCC"
        },
        [20006607] = {
          ContentKR = "메에~",
          DialogueId = 20006607,
          GUID = "32159DF6",
          NextDialogue = 20006608,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Baa—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DF6"
        },
        [20006608] = {
          ContentKR = "딩동~",
          DialogueId = 20006608,
          GUID = "32159E20",
          NextDialogue = 20006609,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ding-dong—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E20"
        },
        [20006609] = {
          ContentKR = "아앗, 뜨거 뜨거! 찌릿찌릿해! 추워추워추워!",
          DialogueId = 20006609,
          GUID = "32159E4A",
          NextDialogue = 20006610,
          SpeakNpcId = 200087,
          Subtitle = "Aghhh—! Too hot— Too tingly— No, too cold—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E4A"
        },
        [20006610] = {
          ContentKR = "잘못했어요! 잘못했어요!",
          DialogueId = 20006610,
          GUID = "32159E74",
          SpeakNpcId = 200087,
          Subtitle = "I'm sorry! I SURRENDER! PLEASE!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E74"
        },
        [20006701] = {
          Camera = "-939.216797,26.854492,320.087097,0.0,-13.407927,0.807412,35.000008,450.0,false,Manual,6.0",
          ContentKR = "{nickname}님, 마령 사냥꾼 사냥꾼님, 빛의 마왕님, 잘못했어요, 저희가 잘못했어요. 이 마령들 다 데려가세요, 살려주세요.",
          DialogueId = 20006701,
          GUID = "3215AD62",
          NextDialogue = 20006702,
          SpeakNpcId = 200087,
          Subtitle = "Lord , Great Geniemon Hunter Hunter, and mighty Demon King of Light — have mercy! We're sorry! We'll leave the Geniemons alone!",
          TalkActionId = {
            [1] = "200075:Avoid",
            [2] = "200087:Avoid"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215AD62"
        },
        [20006702] = {
          ContentKR = "에? 그렇게 겁낼 필요 없어. 앞으로 다시는 마령을 함부로 잡지 않겠다고 약속만 하면, 나랑 헤이즐넛은 너희한테 아무 짓도 안 할 거야.",
          DialogueId = 20006702,
          GUID = "3215AD8C",
          NextDialogue = 20006703,
          SpeakNpcId = 200074,
          Subtitle = "Well, no need to be so terrified. As long as you promise you'll never lay a hand on Geniemons again, Filbert and I won't hurt you.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AD8C"
        },
        [20006703] = {
          ContentKR = "물론입니다, 물론이에요.",
          DialogueId = 20006703,
          GUID = "3215ADB6",
          NextDialogue = 20006704,
          SpeakNpcId = 200075,
          Subtitle = "I promise... I swear...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215ADB6"
        },
        [20006704] = {
          ContentKR = "저도 다시는 마령을 잡지 않겠습니다! 그리고 형님도 감시하고 있을게요, 형님이 다시 마령을 잡기 시작하면 제가 바로 알려드릴게요!",
          DialogueId = 20006704,
          GUID = "3215ADE0",
          NextDialogue = 20006705,
          SpeakNpcId = 200087,
          Subtitle = "Same here! And I'll keep an eye on Boss — if he so much as thinks about catching another Geniemon, I'll turn him in myself!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215ADE0"
        },
        [20006705] = {
          ContentKR = "좋아, 이제 마령들한테도 사과해야지.",
          DialogueId = 20006705,
          GUID = "3215AE0A",
          NextDialogue = 20006706,
          SpeakNpcId = 200074,
          Subtitle = "Alright, then. But you also owe them an apology.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE0A"
        },
        [20006706] = {
          ContentKR = "정말 죄송합니다! 제가 욕심에 눈이 멀었어요. 원래는 마령을 연구하려고 했는데, 논문을 도저히 쓸 수가 없어서 나쁜 마음을 먹었습니다… 이제 저를 사냥하세요. 마령 사냥꾼인 제가 마령에게 사냥을 당하는 기분을 느껴보게 해주세요…",
          DialogueId = 20006706,
          GUID = "3215AE34",
          NextDialogue = 20006708,
          SpeakNpcId = 200075,
          Subtitle = "I—I'm truly sorry! I let greed get the best of me. I wanted to study Geniemons, but I couldn't even write a proper research paper, that's why I turned to this... Go ahead. Take your revenge — hunt me like how I did to you...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE34"
        },
        [20006707] = {
          ContentKR = "제가 정말 어리석었습니다. 판신님의 지능을 의심하다니요. 판신님은 저보다 훨씬 똑똑하시고… 우리 형보다도 더 똑똑하십니다! 오늘부터 판신님을 형님이라고 부르겠습니다…",
          DialogueId = 20006707,
          GUID = "3215AE5E",
          SpeakNpcId = 200087,
          Subtitle = "I was such a fool to question Lord Paniemon's intelligence — Lord Paniemon is smarter than me... smarter than my boss even! From today onward, I pledge my loyalty to you, Lord Paniemon!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE5E"
        },
        [20006708] = {
          ContentKR = "이이.",
          DialogueId = 20006708,
          GUID = "3215AE88",
          NextDialogue = 20006709,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE88"
        },
        [20006709] = {
          Camera = "35.800781,50.916992,117.894058,0.000003,-4.407924,143.206772,35.000011,450.0,false,Manual,6.0",
          ContentKR = "음, 너희가 이렇게 진심인 걸 보니 일단 믿어보도록 할게. 그럼, 이제… 우리, 이 마령들을 어떻게 처리할지 생각해 봐야겠어.",
          DialogueId = 20006709,
          FinalCamera = "140.537109,-26.151367,129.112198,0.000003,-5.407959,144.206726,35.000011,450.0,false,Manual,6.0",
          GUID = "3215AEB2",
          NextDialogue = 20006710,
          SpeakNpcId = 200074,
          Subtitle = "Well, you do seem genuinely sorry. We'll believe you for now. Alright, {性别:Sir|Miss}, Snow, what should we do with the Geniemons?",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AEB2"
        },
        [20006710] = {
          Camera = "-101.119141,154.260742,108.99675,0.000025,3.592208,132.807907,35.000015,110.824821,false,Manual,6.0",
          ContentKR = "이렇게 많은 마령을 아이스레이크 시티 밖으로 데리고 나가는 건 어려울 거야. 그냥 풀어주기엔... 근처엔 월석 같은 에너지원이 없어서 녀석들도 힘들 텐데…",
          DialogueId = 20006710,
          FacialId = {
            [1] = "200074:Unhappy01"
          },
          GUID = "3215AEDC",
          NextDialogue = 20006711,
          SpeakNpcId = 200074,
          Subtitle = "There are so many of them, it'd be impossible to sneak them out of Icelake. But we can't just release them here — there's no steady source of Phoxene energy for them to survive...",
          TalkActionId = {
            [1] = "200074:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215AEDC"
        },
        [20006711] = {
          Camera = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192425,35.000015,161.420593,false,Manual,6.0",
          ContentKR = "이럴 수가... 그러니까 마령들을 구했다고 해도 그들의 생존은 장담할 수 없다는 거야?",
          DialogueId = 20006711,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          FinalCamera = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192459,35.000011,450.0,false,Manual,6.0",
          GUID = "3215AF06",
          NextDialogue = 20006712,
          SpeakNpcId = 200002,
          Subtitle = "How can this be...? Are you saying, that even though we saved them from the poachers, we still can't make sure they all survive?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF06"
        },
        [20006712] = {
          Camera = "-64.103516,31.655273,119.67865,0.000029,-4.808036,119.607536,35.000011,450.0,false,Manual,6.0",
          ContentKR = "맞아, 충분히 많은 월석이 있어야 해... 하지만, 이 많은 마령을 살리려면 아이스레이크 시티의 모든 주민이 월석을 하나씩은 내놓아야 할 텐데... 일반인들은 마령을 무서워해서 그건 어려울 거야...",
          DialogueId = 20006712,
          FinalCamera = "14.46875,-50.96875,106.754761,0.000019,-3.007906,-59.192356,35.000015,134.451996,false,Manual,6.0",
          GUID = "3215AF30",
          NextDialogue = 20006713,
          SpeakNpcId = 200074,
          Subtitle = "That's right. Unless we can get enough Phoxene for all of them... That would require every household in Icelake to chip in at least one piece. But most people are afraid of Geniemons. There's no way they'd agree to help...",
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF30"
        },
        [20006713] = {
          Camera = "-108.800781,-45.291992,165.959991,0.000029,-12.807772,59.206985,35.000008,450.0,false,Manual,6.0",
          ContentKR = "꿀꿀...",
          DialogueId = 20006713,
          GUID = "3215AF5A",
          NextDialogue = 20006714,
          SpeakNpcId = 200086,
          Subtitle = "Oink, oink...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF5A"
        },
        [20006714] = {
          Camera = "-112.921875,-23.537109,160.274353,0.000064,1.1921,-114.590996,35.000011,159.3237,false,Manual,6.0",
          ContentKR = "음... 뭔가 방법을 생각해 봐야겠어...",
          DialogueId = 20006714,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-122.841797,-45.224609,160.77063,0.000065,2.392089,-114.590553,35.000011,142.061966,false,Manual,6.0",
          GUID = "3215AF84",
          NextDialogue = 20006715,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... We need a plan...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF84"
        },
        [20006715] = {
          Camera = "-20.984375,-89.079102,120.151733,0.000088,-7.208342,-37.78812,35.000015,123.723419,false,Manual,6.0",
          ContentKR = "내가 직접 본 건 아니지만, 이 일이 정말일 수도 있다고 생각하니 너무 무서워!",
          DialogueId = 20006715,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-40.863281,-87.678711,84.628616,0.000085,7.591741,-32.988117,35.000015,161.950012,false,Manual,6.0",
          GUID = "3215AFAE",
          NextDialogue = 20006716,
          SpeakNpcId = 200002,
          Subtitle = "I haven't seen it yet, but just thinking about it — ooh, I'm getting goosebumps already!",
          TalkActionId = {
            [1] = "200002:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AFAE"
        },
        [20006716] = {
          Camera = "-92.931641,513.984375,128.895233,0.000055,-1.407743,-97.792145,35.000008,450.0,false,Manual,6.0",
          ContentKR = "트러플, 너희 고향 사람들은 헤이즐넛을 어떻게 생각해?",
          DialogueId = 20006716,
          GUID = "3215AFD8",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006717,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.1},ActorId{100001},AnimationId{"Think_End"}},
PARA{
PlayFacial{_delay{0.5},ActorId{100001},FacialId{"Confident01"}},
PlayAnimation{_delay{2.1},ActorId{100001},AnimationId{"Talk02_Start"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Truffle, back in your hometown, are people scared of Filbert?",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AFD8"
        },
        [20006717] = {
          Camera = "-130.119141,-252.262695,186.619904,0.00007,-10.007689,106.210793,35.000011,450.0,false,Manual,6.0",
          ContentKR = "응? 처음엔 다들 이렇게 큰 돼지를 본 적이 없어서 좀 무서워했어. 하지만 헤이즐넛이 나랑 같이 많은 먹을거리를 찾아내는 걸 보고, 정말 능력 있다는 걸 알게 되니까 마음을 열기 시작했지.",
          DialogueId = 20006717,
          FacialId = {
            [1] = "200074:Smile01"
          },
          GUID = "3215B002",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20006718,
          SpeakNpcId = 200074,
          Subtitle = "Well, at first, yeah. No one had ever seen a pig this big before, so they were a little scared. But once they saw how she helped me find food, how smart and hardworking she is — they weren't scared anymore.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200074:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B002"
        },
        [20006718] = {
          Camera = "-143.039062,97.484375,110.879364,0.000087,0.791714,106.205078,35.000015,140.05127,false,Manual,6.0",
          ContentKR = "그래, 무서운 건 잘 모르기 때문이야. 사람들이 마령의 능력을 느끼고, 마령의 도움을 받게 된다면 무서움은 분명히 사라지게 될 거야.",
          DialogueId = 20006718,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-146.861328,105.399414,111.090088,0.000087,1.391712,107.405457,35.000015,140.05127,false,Manual,6.0",
          GUID = "3215B02C",
          NextDialogue = 20006719,
          SpeakNpcId = 100001,
          Subtitle = "Right. Fear comes from not knowing. But if people see what Geniemons are capable of — how they can help — then maybe that fear will disappear.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B02C"
        },
        [20006719] = {
          ContentKR = "트러플, 스노우, 우리 이 마령들을 아스포델로 데려가자.",
          DialogueId = 20006719,
          GUID = "3215B056",
          SpeakNpcId = 100001,
          Subtitle = "Truffle, Snow — let's take them to The Asphodel.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B056"
        },
        [20006720] = {
          Camera = "390.472656,-23.833008,76.522202,0.000054,0.592102,149.805954,35.000011,450.0,false,Manual,6.0",
          ContentKR = "그래, 헤이즐넛, 앉아. 마령들을 등에 업고 단숨에 데리고 나가자.",
          DialogueId = 20006720,
          FinalCamera = "290.703125,34.223633,80.627289,0.000054,2.592091,149.805908,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B080",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          NextDialogue = 20006721,
          SpeakNpcId = 200074,
          Subtitle = "Alright! Filbert, sit down — let's load them onto your back and take them all in one trip!",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B080"
        },
        [20006721] = {
          ContentKR = "응? 또 카밀라를 찾아가? 카밀라라면... 분명 또 싫다고 해놓고선 너랑 같이 방법을 찾겠지.",
          DialogueId = 20006721,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "3215B0AA",
          NextDialogue = 20006722,
          SpeakNpcId = 200002,
          Subtitle = "Huh? We're going to Camilla again? She's totally going to wear a big frown and act like she doesn't want to get involved... then come up with a perfect idea to help us.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0AA"
        },
        [20006722] = {
          ContentKR = "저도 돕겠습니다!",
          DialogueId = 20006722,
          GUID = "3215B0D4",
          NextDialogue = 20006723,
          SpeakNpcId = 200087,
          Subtitle = "I'll help too!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0D4"
        },
        [20006723] = {
          ContentKR = "저도요, 저도요.",
          DialogueId = 20006723,
          GUID = "3215B0FE",
          NextDialogue = 20006724,
          SpeakNpcId = 200075,
          Subtitle = "Me too!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0FE"
        },
        [20006724] = {
          Camera = "25.234375,43.664062,76.073486,0.000057,-10.207888,-1.19403,35.000011,450.0,false,Manual,6.0",
          ContentKR = "이이.",
          DialogueId = 20006724,
          FinalCamera = "-37.855469,44.204102,84.949371,0.000057,-8.007871,-0.194,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B128",
          NextDialogue = 20006725,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B128"
        },
        [20006725] = {
          Camera = "447.40625,104.102539,80.368851,0.000072,-1.207823,-159.593887,35.000011,450.0,false,Manual,6.0",
          ContentKR = "응? 넌 같이 가지 않겠다고?",
          DialogueId = 20006725,
          FinalCamera = "483.496094,102.482422,81.651184,0.000072,-3.00781,-160.39386,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B152",
          LookAt = {
            [1] = "100001:n(700251)"
          },
          NextDialogue = 20006726,
          SpeakNpcId = 100001,
          Subtitle = "Huh? You're not coming with us?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B152"
        },
        [20006726] = {
          Camera = "45.181641,44.441406,28.436035,0.000076,6.992051,-0.794525,35.000011,450.0,false,Manual,6.0",
          ContentKR = "판신은 보통 사람들과 최대한 거리를 두려고 해요. 그냥 여러분의 힘을 빌려 다른 마령을 구하려고 했던 것 같아요.",
          DialogueId = 20006726,
          FinalCamera = "-94.589844,48.933594,37.514648,0.000076,0.791967,-1.194519,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B17C",
          NextDialogue = 20006727,
          SpeakNpcId = 200075,
          Subtitle = "Paniemon usually keeps its distance from people. It probably just showed up to get you to help free the other Geniemons.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B17C"
        },
        [20006727] = {
          Camera = "-76.480469,-72.768555,129.284988,0.000097,13.191738,-135.390411,35.000015,137.250519,false,Manual,6.0",
          ContentKR = "그래, 그럼 조심하고.",
          DialogueId = 20006727,
          FinalCamera = "-99.601562,-95.574219,136.62146,0.000099,15.191671,-135.990753,35.000015,105.456551,false,Manual,6.0",
          GUID = "3215B1A6",
          NextDialogue = 20006728,
          SpeakNpcId = 100001,
          Subtitle = "I see. Alright, take care, Paniemon.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1A6"
        },
        [20006728] = {
          Camera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          ContentKR = "이이이.",
          DialogueId = 20006728,
          FinalCamera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B1D0",
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yiiiip~",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1D0"
        },
        [20006801] = {
          ContentKR = "결국, 이 마령들은 모두 아스포델로 옮겨졌고, 술집에 가득 있던 손님들을 놀라 도망치게 만들었다.\n그리고 카밀라는 깊은 한숨을 내쉬며, 애초에 {nickname}을(를) 도시로 데려오지 말아야 했던 건 아닐까 하는 고민에 빠지고 말았다.",
          DialogueId = 20006801,
          Duration = 5,
          GUID = "3215BDCA",
          Subtitle = [[
And so, the Geniemons were successfully brought to The Asphodel.
The moment they arrived, the tavern customers scrambled for the exits, knocking over chairs in their haste.
Camilla did frown, pinching the bridge of her nose as she reconsidered whether bringing  into the city had been a terrible mistake.]],
          VoiceName = "voice/$Locale$/story/2001/200068/3215BDCA"
        },
        [20006901] = {
          ContentKR = "또 시간이 한동안 지나고, 카밀라의 찌푸렸던 미간이 마침내 서서히 펴지기 시작했다...",
          DialogueId = 20006901,
          Duration = 3,
          GUID = "3215CE32",
          Subtitle = "But as the days passed, Camilla's frown began to ease...",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE32"
        },
        [20006902] = {
          Camera = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
          ContentKR = "헤, 카밀라, '불닭이 특제 칵테일'로 한잔 부탁해. 이렇게 추운 날 한 모금이면 딱이지.",
          DialogueId = 20006902,
          GUID = "3215CE5C",
          LookAt = {
            [1] = "700253:n(700248)",
            [2] = "700254:n(700253)"
          },
          NextDialogue = 20006903,
          Scripts = [[
PARA{
PlayFacial{_delay{3.5},ActorId{700248},FacialId{"Confident01"}},
PlayAnimation{_delay{3.1},ActorId{700248},AnimationId{"Talk03_Start"}}
}]],
          SpeakNpcId = 700253,
          Subtitle = "Camilla, I'll have a Zippyro Special. Nothing beats a drink warmed by real flames on a freezing day like this.",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE5C"
        },
        [20006903] = {
          ContentKR = "처음엔 이 작은 녀석이 좀 수상쩍다고 생각했는데, 뿜어내는 불꽃으로 술을 데우다니, 완전 최고야!",
          DialogueId = 20006903,
          GUID = "3215CE86",
          LookAt = {
            [1] = "700253:n(700253)"
          },
          NextDialogue = 20006904,
          SpeakNpcId = 700253,
          Subtitle = "Gotta admit, when I first saw this little thing, I thought it was evil with that weird flame. But turns out that flame's perfect for heating a nice drink. Hah — who'd have thought!",
          TalkActionId = {
            [1] = "700253:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE86"
        },
        [20006904] = {
          Camera = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "비참하군요, 웨일즈 씨. 애처롭군요, 웨일즈 씨.",
          DialogueId = 20006904,
          GUID = "3215CEB0",
          NextDialogue = 20006905,
          SpeakNpcId = 700254,
          Subtitle = "Oh, the folly, Wells! The wretched, wretched folly!",
          TalkActionId = {
            [1] = "700254:Sigh_Start",
            [2] = "700253:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEB0"
        },
        [20006905] = {
          Camera = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "웨일즈 씨는 그저 불닭이의 불꽃이 술을 데워 배를 따뜻하게 해준다는 것만 알고 있을 뿐, 그 진정한 가치가 어둠을 갈라 저의 책을 밝혀주어 영감을 가져다주는 것이라는 걸 모르고 있군요!",
          DialogueId = 20006905,
          GUID = "3215CEDA",
          NextDialogue = 20006906,
          SpeakNpcId = 700254,
          Subtitle = "You see only the fleeting comfort of a warm drink! But Zippyro's flame — it doesn't merely warm the body! It carves through the abyss! It ignites the eternal night! It is the fire of my muse!",
          TalkActionId = {
            [1] = "700254:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEDA"
        },
        [20006906] = {
          Camera = "-89.716675,175.708008,152.642578,-0.000763,-3.992218,-88.380859,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "불, 닭, 이. 얼마나 아름다운 세 글자인가요. 제 창작 인생의 빛, 제 창작 욕망의 불꽃! 저의 죄악, 저의 영혼!",
          DialogueId = 20006906,
          GUID = "3215CF04",
          SpeakNpcId = 700254,
          Subtitle = "Zippyro! Three syllables of pure poetry! The spark of my words, the pyre of my soul, my sin, and my salvation!",
          TalkActionId = {
            [1] = "700254:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CF04"
        },
        [20007001] = {
          Camera = "410.60437,303.494141,154.748047,0.000089,0.396813,37.710804,35.0,369.08606,false,Manual,12.0",
          ContentKR = "누군가는 또로록으로 꽃에 물을 주고, 또 누군가는 좋은 꿈 씨로 잠에 들어... 그리고 이제 내 장사도 불닭이를 떠날 수 없게 됐네. ",
          DialogueId = 20007001,
          FinalCamera = "262.071167,223.890625,147.691406,0.000094,-1.403686,36.110554,35.000011,369.08606,false,Manual,12.0",
          GUID = "3215DE9A",
          NextDialogue = 20007002,
          Scripts = [[
PARA{
SEQ{
TurnTo{_delay{2},TurnToDescription{"700248:p(180)"}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Confident_Start"},Duration{1}}
},
PlayFacial{_delay{0.5},ActorId{700248},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Some people use Dripplet to water their plants. Others rely on Mr Goodnight for sleep. And now, even my business depends on a Zippyro.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DE9A"
        },
        [20007002] = {
          ContentKR = "요즘은 아무도 마령에게서 월석을 추출하려고 하지 않아. 오히려 마령들과 더 가까워지기 위해 일부러 월석을 사서 그들에게 먹이로 주지. 참 흥미로운 일이야.",
          DialogueId = 20007002,
          GUID = "3215DEC4",
          LookAt = {
            [1] = "100001:n(200074)",
            [2] = "200002:n(200074)"
          },
          NextDialogue = 20007003,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Confident_End"},Duration{1}},
PARA{
PlayAnimation{_delay{1.5},ActorId{700248},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{_delay{7.5},ActorId{700248},FacialId{"Smile02"}}
},
PlayFacial{_delay{1.0},ActorId{700248},FacialId{"None"}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Funny how things turn around. Not long ago, people were all about extracting Phoxene from Geniemons — now they're buying it just to keep them around.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEC4"
        },
        [20007003] = {
          Camera = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "저도 트러플과 헤이즐넛을 보고 나서야 알게 됐어요. 헤이즐넛이 인간과 친하게 지낼 수 있다면, 다른 마령도 가능하죠.",
          DialogueId = 20007003,
          GUID = "3215DEEE",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007004,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "That all thanks to Truffle and Filbert. If Filbert can live peacefully with humans, then so can Geniemons.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEEE"
        },
        [20007004] = {
          Camera = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,169.08606,false,Manual,12.0",
          ContentKR = "그리고 마령이 인간과 잘 지낼 수 있다면, 카론과 솔라도 언젠가는 화합하며 지낼 날이 오겠죠.",
          DialogueId = 20007004,
          GUID = "3215DF18",
          NextDialogue = 20007005,
          Scripts = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
          SpeakNpcId = 100001,
          Subtitle = "And if Geniemons and humans can get along, maybe one day Charons and Solarians will too.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF18"
        },
        [20007005] = {
          Camera = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
          ContentKR = "하하, 순진하다고 해야 할지, 멀리 내다본다고 해야 할지 모르겠네. 그럴 날이 오길 기대할게. 근데 그날이 오기 전에, 꼬마 친구와 작별할 때가 온 것 같네.",
          DialogueId = 20007005,
          FinalCamera = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DF42",
          NextDialogue = 20007006,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_Start"},Duration{2}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_End"},Duration{1}}}]],
          SpeakNpcId = 700248,
          Subtitle = "Haha, I can't decide if you're just naive or a true visionary. Either way, I'll be looking forward to that day. But for now... it's time to say goodbye to a certain little traveller.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF42"
        },
        [20007006] = {
          Camera = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
          ContentKR = "엉엉엉, 트러플, 그냥 아이스레이크 시티에 남아 있으면 안 돼? 겨우 나랑 같이 빛의 마왕님이라는 칭호를 외쳐줄 친구를 구했단 말이야! ",
          DialogueId = 20007006,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "3215DF6C",
          NextDialogue = 20007007,
          SpeakNpcId = 200002,
          Subtitle = "Boohoo... Truffle, can't you just stay? As the Demon King of Light, I finally found someone who would chant the title I gave them aloud with me, and now you're leaving so soon... Waaah!",
          TurnTo = {
            [1] = "200074:p(30)"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF6C"
        },
        [20007007] = {
          ContentKR = "울지 마, 스노우. 난 이미 너무 오래 나와 있었어, 이제 돌아가야 해. 게다가 그 마령 사냥꾼들도 이제 마령 학자가 됐잖아? 그 사람들과 같이 칭호를 외치면 되잖아.",
          DialogueId = 20007007,
          GUID = "3215DF96",
          NextDialogue = 20007008,
          SpeakNpcId = 200074,
          Subtitle = "Aww, don't cry, Snow. I've been away for so long — it's time for me to go home. Besides, those ex-poachers are now Geniemon researchers. You can always ask them to chant with you.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF96"
        },
        [20007008] = {
          Camera = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
          ContentKR = "아니야, 걔들은 네 목소리만큼 듣기 좋지도 않고, 너처럼 헤이즐넛과 함께 드라이브시켜 줄 수도 없잖아. {nickname} 너도 멍하니 서 있지 말고, 트러플을 좀 붙잡아 봐!",
          DialogueId = 20007008,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "3215DFC0",
          NextOptions = {
            [1] = 200070081
          },
          SpeakNpcId = 200002,
          Subtitle = "Nah-uh, it's not the same. They're not as sweet as you... And they definitely can't carry me on Filbert for a ride! , don't just stand there — help me convince Truffle to stay!",
          TalkActionId = {
            [1] = "700248:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFC0"
        },
        [20007009] = {
          Camera = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
          ContentKR = "헤헤, 나중에 가끔 놀러 올 거야. {性别:오빠|언니}, 몰래 알려주는 거야. 내가 돌아가야 하는 그 아주아주 먼 곳은 사실 엘리시안 교회야.",
          DialogueId = 20007009,
          FacialId = {
            [1] = "200002:CM_Idle"
          },
          FinalCamera = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DFEA",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007010,
          SpeakNpcId = 200074,
          Subtitle = "Hehe, I'll be back to visit, I promise. And let me secretly tell you something— the faraway place I'm returning to is actually the Elysian Church.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFEA"
        },
        [20007010] = {
          Camera = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
          ContentKR = "난 식량을 모을 때 가끔 헤이즐넛과 함께 아무도 지키지 않는 높은 산을 넘어 휘페르보레아로 오곤 해. 처음엔 좀 무서웠어, 왜냐하면 교회랑 제국은 계속 전쟁 중이잖아.",
          DialogueId = 20007010,
          GUID = "3215E014",
          NextDialogue = 20007011,
          SpeakNpcId = 200074,
          Subtitle = "When Filbert and I forage for food, we sometimes cross the unguarded mountain border to reach Hyperborea. At first, I was a little scared — after all, the Church and the Empire have always been at war...",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E014"
        },
        [20007011] = {
          ContentKR = "근데 {性别:오빠|언니}를 만나고 난 뒤로 안 무서워졌어.",
          DialogueId = 20007011,
          GUID = "3215E03E",
          NextDialogue = 20007012,
          SpeakNpcId = 200074,
          Subtitle = "But after meeting you, I'm not scared anymore.",
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E03E"
        },
        [20007012] = {
          ContentKR = "{性别:오빠|언니}가 마령과 인간이 함께 지낼 방법을 생각해 낼 수 있다면, 분명 카론과 솔라가 서로 미워하지 않게 만들 수도 있을 거야. 그러면 제국과 교회도 더 이상 싸우지 않을 수 있겠지.",
          DialogueId = 20007012,
          GUID = "3215E068",
          NextDialogue = 20007013,
          SpeakNpcId = 200074,
          Subtitle = "Because if you can find a way for Geniemons and humans to become friends, then I believe one day, you'll also figure out how to make Charons and Solas friends — and maybe even the Empire and the Church too!",
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E068"
        },
        [20007013] = {
          ContentKR = "그렇게 되면, 다들 배고프지 않게 될 거야!",
          DialogueId = 20007013,
          GUID = "3215E092",
          NextDialogue = 20007014,
          SpeakNpcId = 200074,
          Subtitle = "And once the war stops, there will be no more hunger!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E092"
        },
        [20007014] = {
          ContentKR = "그때가 되면,  {性别:오빠|언니}랑 스노우, 그리고 카밀라 씨도 같이 남쪽으로 와줘. 통통한 붉은 버섯도 먹고, 따뜻한 바닷바람도 쐬고, 여기서는 볼 수 없는 별들도 보면서, 내가 여기서 지냈던 것처럼 행복하게 지내자! 기다릴게!",
          DialogueId = 20007014,
          GUID = "3215E0BC",
          NextDialogue = 20007015,
          SpeakNpcId = 200074,
          Subtitle = "When that day comes, please come and visit me in the South with Snow and Ms Camilla. I'll treat you to our pink-red mushroom called Russula, and we'll go to the beach and feel the warmth of the sea breeze, and look up at stars you can't see from here. You'll have a great time, just like I did here!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0BC"
        },
        [20007015] = {
          ContentKR = "그래, 그렇게 해볼게.",
          DialogueId = 20007015,
          GUID = "3215E0E6",
          NextDialogue = 20007016,
          SpeakNpcId = 100001,
          Subtitle = "That sounds wonderful. I'll try my best to make that happen.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0E6"
        },
        [20007016] = {
          ContentKR = "약속이야.",
          DialogueId = 20007016,
          GUID = "3215E110",
          NextOptions = {
            [1] = 200070161
          },
          SpeakNpcId = 200074,
          Subtitle = "Pinky swear~",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E110"
        },
        [20007017] = {
          ContentKR = "헤이즐넛과도 약속해.",
          DialogueId = 20007017,
          GUID = "3215E13A",
          NextDialogue = 20007018,
          SpeakNpcId = 200074,
          Subtitle = "And Filbert too!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E13A"
        },
        [20007018] = {
          ContentKR = "헤이즐넛은 발굽이 너무 굵어서 새끼손가락을 걸 수가 없잖아.",
          DialogueId = 20007018,
          GUID = "3215E164",
          NextDialogue = 20007019,
          SpeakNpcId = 100001,
          Subtitle = "Uh, her hooves seem a little too big for a pinky swear.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E164"
        },
        [20007019] = {
          ContentKR = "그럼 그냥 발굽을 움켜쥐면 돼. 자, 다 같이, 새끼손가락 걸고 약속, 영원히 변치 말기!",
          DialogueId = 20007019,
          GUID = "3215E18E",
          NextDialogue = 20007020,
          SpeakNpcId = 200074,
          Subtitle = "Then just hold onto her hoof — it still counts! Okay, together — cross my heart, hope to die, stick a needle in my eye!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E18E"
        },
        [20007020] = {
          ContentKR = "꿀!",
          DialogueId = 20007020,
          GUID = "3215E1B8",
          SpeakNpcId = 200086,
          Subtitle = "Oink!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E1B8"
        },
        [20007101] = {
          ContentKR = "이 몸은, 아이스레이크 시티 최고의 마령 학자시다! 마령에 대해 질문이 있다면 이 몸에게 물어보도록... 앗, 당신이군요... 무... 무슨 일이신지?",
          DialogueId = 20007101,
          GUID = "3215EF02",
          NextOptions = {
            [1] = 200071011,
            [2] = 200071012,
            [3] = 200071013
          },
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "I am Icelake's foremost Geniemon scholar! If you have any questions about them, feel free to— Oh, it's you. Uh, is—is there anything I can help you with?",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF02"
        },
        [20007102] = {
          ContentKR = "그 굉장히 똑똑한 마령 말씀이죠?",
          DialogueId = 20007102,
          GUID = "3215EF2C",
          NextDialogue = 20007103,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "You mean that incredibly intelligent Geniemon?",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF2C"
        },
        [20007103] = {
          ContentKR = "판신 마령에 대한 기록은 매우 적어요. 저도 단 한 번 밖에 본 적 없습니다. 판신 마령의 인정을 받아야만 그들을 찾을 수 있다고 합니다.",
          DialogueId = 20007103,
          GUID = "3215EF56",
          NextDialogue = 20007104,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "There's very little documented about it. I've only ever seen it once myself. They say it doesn't reveal itself to just anyone. Only those it deems worthy ever get to meet it.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF56"
        },
        [20007104] = {
          ContentKR = "하지만 당신이라면 그들이 남긴 흔적을 따라 그들의 은신처를 찾을 수 있을 겁니다.",
          DialogueId = 20007104,
          GUID = "3215EF80",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "But you might be able to track it down by following the traces it leaves behind.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF80"
        },
        [20007105] = {
          ContentKR = "마량 사냥꾼보다 많이 낫습니다. 매일 사람들이 몰려와 저에게 마령에 대한 질문을 합니다. 마치 제가 무슨 대학자인 것처럼요.",
          DialogueId = 20007105,
          GUID = "3215EFAA",
          NextDialogue = 20007106,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "Much better than being a Geniemon hunter, that's for sure. People actually come to me for advice now. I almost feel like a real academic.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFAA"
        },
        [20007106] = {
          ContentKR = "이게 다 당신과 트러플이 너그럽게 봐주신 덕분입니다, 감사합니다.",
          DialogueId = 20007106,
          GUID = "3215EFD4",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "Speaking of which, I really appreciate that you and Truffle went easy on me back then.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFD4"
        },
        [20007107] = {
          ContentKR = "깊게 새겨진 흔적. 어떤 날카로운 물체로 긁은 듯하다.",
          DialogueId = 20007107,
          GUID = "3215EFD5",
          Subtitle = "Several deep gouges, as if left by some jagged object."
        },
        [20007108] = {
          ContentKR = "\"위험, 통행금지\"라고 쓰여 있는 경고 푯말. 경고문이 낡자 그대로 새 경고문으로 덮은 모양인지, 종이가 덕지덕지 두껍게 붙어 있다. 가장 최근의 것은 신력 1004년, 즉 24년 전으로, 글로스터 광갱은 아마 그때 완전히 폐기된 듯하다.",
          DialogueId = 20007108,
          GUID = "3215EFD6",
          Subtitle = "A sign reading \"Danger: No Entry\" was piled up with multiple layers, as if a new one was posted each time the old one faded. The latest was dated 1004  — twenty years ago — suggesting Glevum Pit was abandoned around that time."
        },
        [21000101] = {
          Content = "背白白进场台词（测试用）",
          DialogueId = 21000101,
          GUID = "34925112",
          TalkActionId = {
            [1] = "900005:Beibao_Start"
          }
        },
        [21000102] = {
          Content = "背白白退场台词（测试用）",
          DialogueId = 21000102,
          GUID = "3492513C",
          TalkActionId = {
            [1] = "900005:Beibao_Finish"
          }
        },
        [50000101] = {
          ContentKR = "이봐, 너 말이야, 너. 통행증은 있나?",
          DialogueId = 50000101,
          Duration = 3,
          GUID = "7D2B8592",
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?",
          VoiceName = "voice/$Locale$/env/700002/7D2B8592"
        },
        [50000201] = {
          ContentKR = "자네 같은 월석 사냥꾼이 여기까지 오다니... 영웅의 기질이 보이는구먼.",
          DialogueId = 50000201,
          Duration = 4,
          GUID = "7D2B95FA",
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          VoiceName = "voice/$Locale$/env/700003/7D2B95FA"
        },
        [50000301] = {
          ContentKR = "젠장, 전부 그란데 탓이야. 대체 이제 어떡해야 하지... 응? 뭘 봐, 요 며칠은 뭘 부탁한 적도 없잖아!",
          DialogueId = 50000301,
          Duration = 3,
          GUID = "7D2BA662",
          SpeakNpcId = 700004,
          Subtitle = "D*mn it, it's all Grandet's fault! What am I supposed to do now... Hm? What are you looking at? I've got no work for you today!",
          VoiceName = "voice/$Locale$/env/700004/7D2BA662"
        },
        [50000401] = {
          ContentKR = "제 이름이... 애니라고요?",
          DialogueId = 50000401,
          Duration = 3,
          GUID = "7D2BB6CA",
          SpeakNpcId = 700032,
          Subtitle = "My name is... Annie?",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700032/7D2BB6CA"
        },
        [50000501] = {
          ContentKR = "몸만 회복되면 다음 모험을 떠나려고요.",
          DialogueId = 50000501,
          Duration = 3,
          GUID = "7D2BC732",
          SpeakNpcId = 700005,
          Subtitle = "As soon as I'm back in form, I'm off on another adventure.",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BC732"
        },
        [50000601] = {
          ContentKR = "엄마한테 갈 때 뭘 가져가면 좋을까... 분명 날 무척 보고 싶어 하실 텐데.",
          DialogueId = 50000601,
          Duration = 3,
          GUID = "7D2BD79A",
          SpeakNpcId = 700005,
          Subtitle = "What gift should I get for mother... She must've missed me terribly.",
          TalkActionId = {
            [1] = "700005:Think_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BD79A"
        },
        [50000701] = {
          ContentKR = "애니... 애니!",
          DialogueId = 50000701,
          Duration = 3,
          GUID = "7D2BE802",
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          VoiceName = "voice/$Locale$/env/700006/7D2BE802"
        },
        [50000801] = {
          ContentKR = "어머, 이 꽃이 오늘 옷차림이랑 잘 어울리시네요... 그 아이도 있었다면 똑같이 말했을 거예요.",
          DialogueId = 50000801,
          Duration = 3,
          GUID = "7D2BF86A",
          SpeakNpcId = 700007,
          Subtitle = "The flowers today are quite lovely. I should save a few for that kid.",
          TalkActionId = {
            [1] = "700007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700007/7D2BF86A"
        },
        [50000901] = {
          ContentKR = "안녕하세요, 이 꽃은 오늘 당신과 잘 어울리네요... 그 애가 살아 있다면 분명 이렇게 말했을 거예요.",
          DialogueId = 50000901,
          Duration = 5,
          GUID = "7D2C08D2",
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here.",
          VoiceName = "voice/$Locale$/env/700007/7D2C08D2"
        },
        [50001001] = {
          ContentKR = "그런 옷걸이를 가지고 우리 옷을 안 입는다니, 너무 아쉽네요.",
          DialogueId = 50001001,
          Duration = 3,
          GUID = "7D2C193A",
          SpeakNpcId = 700008,
          Subtitle = "Hello, gorgeous! I bet you'd be a vision in our apparel.",
          VoiceName = "voice/$Locale$/env/700008/7D2C193A"
        },
        [50001101] = {
          ContentKR = "우리 농장 과일이라 하는 말이 아니라 이런 기술로 키우는 데는 어디에도 없다니까!",
          DialogueId = 50001101,
          Duration = 3,
          GUID = "7D2C29A2",
          SpeakNpcId = 700009,
          Subtitle = "Try these fine fruits from our orchard — grown with unmatched cultivation techniques!",
          TalkActionId = {
            [1] = "700009:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700009/7D2C29A2"
        },
        [50001201] = {
          ContentKR = "아... 어, 으어어...",
          DialogueId = 50001201,
          Duration = 2,
          GUID = "7D2C3A0A",
          SpeakNpcId = 700010,
          Subtitle = "Ah... whoa, I... um...",
          VoiceName = "voice/$Locale$/env/700010/7D2C3A0A"
        },
        [50001301] = {
          ContentKR = "음... 첫 번째 실험 대상은 너로 정했어!",
          DialogueId = 50001301,
          Duration = 3,
          GUID = "7D2C4A72",
          SpeakNpcId = 700011,
          Subtitle = "Hmm... I've made up my mind — hello, Test subject No. 1!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C4A72"
        },
        [50001401] = {
          ContentKR = "{NickName}, 또 만났네! 난 매일 새로운 것들을 열심히 공부하고 있어. 같이 힘내자!",
          DialogueId = 50001401,
          Duration = 4,
          GUID = "7D2C5ADA",
          SpeakNpcId = 700011,
          Subtitle = ", lovely to see you again! I'm trying my best to learn new things every day, let's keep at it!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C5ADA"
        },
        [50001501] = {
          ContentKR = "너는... 카론... 나와 같은...",
          DialogueId = 50001501,
          Duration = 6,
          GUID = "7D2C6B42",
          SpeakNpcId = 700012,
          Subtitle = "You... Charon... You're one of us...",
          VoiceName = "voice/$Locale$/env/700012/7D2C6B42"
        },
        [50001601] = {
          ContentKR = "말로 표현하기 힘든 일들도 많이 보아 왔지만, 그 일들의 중심엔 항상 '악마'만 있는 것도 아니었지.\n...나도 가끔은 솔라와 카론 중 대체 누가 악마인지 잘 모르겠어.",
          DialogueId = 50001601,
          Duration = 4,
          GUID = "7D2C7BAA",
          SpeakNpcId = 700013,
          Subtitle = [[
I've witnessed deeds that daylight never sees, and not all are the work of "demons".
...Sometimes, between Solas and Charons, I can't tell which is the true demon.]],
          VoiceName = "voice/$Locale$/env/700013/7D2C7BAA"
        },
        [50001701] = {
          ContentKR = "보는 눈도 없는 멍청한 여자 같으니! 언제까지 그렇게 뻗대나 보자고!",
          DialogueId = 50001701,
          Duration = 4,
          GUID = "7D2C8C12",
          SpeakNpcId = 700014,
          Subtitle = "Pah! Stupid hag! Let's see how long you can keep this charade up!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/env/700014/7D2C8C12"
        },
        [50001801] = {
          ContentKR = "신이시어, 저같이 선량한 사람에게 영감을 훔치는 영혼을 보내시다니요! 이렇게 억울할 수가!",
          DialogueId = 50001801,
          Duration = 4,
          GUID = "7D2C9C7A",
          SpeakNpcId = 700015,
          Subtitle = "Good grief! Who'd have thought a gentle soul like myself would be beset by an inspiration-stealing spectre?! Such wretchedness would surely draw heaven's own tears!",
          VoiceName = "voice/$Locale$/env/700015/7D2C9C7A"
        },
        [50001901] = {
          ContentKR = "정말 짜증 나! 맨날 쓸데없는 행사만 하고, 차라리 좀 쉬는 게 낫겠네!",
          DialogueId = 50001901,
          Duration = 3,
          GUID = "7D2CACE2",
          SpeakNpcId = 700016,
          Subtitle = "What a drag! Who arranged these pointless events? I'd rather have half a day off!",
          VoiceName = "voice/$Locale$/env/700016/7D2CACE2"
        },
        [50002001] = {
          ContentKR = "\"비가 와서 엄마 꽃이 망가졌어요. 그래서 하늘이 물웅덩이에 작은 꽃들을 많이 만들어서 엄마한테 줬어요.\"",
          DialogueId = 50002001,
          Duration = 3,
          GUID = "7D2CBD4A",
          NextDialogue = 50002002,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          VoiceName = "voice/$Locale$/env/700017/7D2CBD4A"
        },
        [50002002] = {
          ContentKR = "그거 알아요? 이건 제 여섯 살짜리 학생이 쓴 〈사죄〉라는 시예요.",
          DialogueId = 50002002,
          Duration = 3,
          GUID = "7D2CBD74",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700017/7D2CBD74"
        },
        [50002101] = {
          ContentKR = "자연의 법칙을 거스르며 던진 돌은 결국 자신의 머리로 날아오는 법이죠.",
          DialogueId = 50002101,
          Duration = 3,
          GUID = "7D2CCDB2",
          SpeakNpcId = 700018,
          Subtitle = "The rocks cast against the laws of nature will inevitably fall back on one's own head.",
          TalkActionId = {
            [1] = "700018:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/env/700018/7D2CCDB2"
        },
        [50002201] = {
          ContentKR = "도대체 어디로 간 거야...",
          DialogueId = 50002201,
          Duration = 3,
          GUID = "7D2CDE1A",
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700019/7D2CDE1A"
        },
        [50002301] = {
          ContentKR = "오늘 저녁의 버섯 크림수프가 마님께 조금이나마 위안이 되었으면 좋겠는데요.",
          DialogueId = 50002301,
          Duration = 4,
          GUID = "7D2CEE82",
          SpeakNpcId = 700020,
          Subtitle = "I hope tonight's creamy mushroom soup will bring some comfort to her ladyship.",
          TalkActionId = {
            [1] = "700020:Agree"
          },
          VoiceName = "voice/$Locale$/env/700020/7D2CEE82"
        },
        [50002401] = {
          ContentKR = "언제나 제정신이 아니네. 정말 안쓰러워.",
          DialogueId = 50002401,
          Duration = 3,
          GUID = "7D2CFEEA",
          NextDialogue = 50002402,
          SpeakNpcId = 700023,
          Subtitle = "Poor thing, having lost her mind like that.",
          VoiceName = "voice/$Locale$/env/700023/7D2CFEEA"
        },
        [50002402] = {
          ContentKR = "딸이 떠난 것도 이해가 될 지경이야...",
          DialogueId = 50002402,
          Duration = 3,
          GUID = "7D2CFF14",
          SpeakNpcId = 700024,
          Subtitle = "No wonder her daughter had left.",
          VoiceName = "voice/$Locale$/env/700024/7D2CFF14"
        },
        [50002501] = {
          ContentKR = "도시의 모든 쓰레기통은 제 것이나 마찬가지죠. 그 안에는 별의별 것이 다 들어 있답니다! 몇 번밖에 신지 않은 사슴 가죽 장화, 아직 시들지 않은 백합, 그리고 누가 부쉈는지 알 수 없는 꿈도 있어요...",
          DialogueId = 50002501,
          Duration = 3,
          GUID = "7D2D0F52",
          SpeakNpcId = 700115,
          Subtitle = "I oversee all the rubbish bins around the city, and oh, the treasures to be found in each of them! Nearly new deerskin boots, still-fresh lilies, and the fragments of someone's shattered dreams...",
          TalkActionId = {
            [1] = "700115:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700022/7D2D0F52"
        },
        [50002601] = {
          ContentKR = "다음 역으로 가는 열차가 곧 출발할 예정이니 표는 이곳에서 구매하시면 됩니다. 돈이 없다고요? 그럼 헛된 꿈은 그만 꾸고 꺼지세요!",
          DialogueId = 50002601,
          Duration = 5,
          GUID = "7D2D0F53",
          SpeakNpcId = 700021,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700021:Confident_Start"
          }
        },
        [50002701] = {
          ContentKR = "13번 파이프는 벌써 고치는 중이야. 아, 진짜, 쥐가 너무 많아서 미치겠네.",
          DialogueId = 50002701,
          Duration = 4,
          GUID = "7D2D3022",
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700069/7D2D3022"
        },
        [50002801] = {
          ContentKR = "꺼져! 망할 카론 자식!",
          DialogueId = 50002801,
          DialoguePanelType = "{type:Bubble;style:ExcitedBubble}",
          Duration = 3,
          GUID = "7D2D408A",
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!",
          VoiceName = "voice/$Locale$/env/700068/7D2D408A"
        },
        [50002901] = {
          ContentKR = "아이고... 왜 이렇게 안 지워지는 거야.",
          DialogueId = 50002901,
          Duration = 3,
          GUID = "7D2D50F2",
          SpeakNpcId = 700067,
          Subtitle = "Ugh... these bloodstains just won't come off!",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700067/7D2D50F2"
        },
        [50003001] = {
          Content = "凶猛的狼咆哮着 撕咬着狡猾的狗",
          DialogueId = 50003001,
          Duration = 3,
          GUID = "7D2D615A",
          NextDialogue = 50003002,
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D615A"
        },
        [50003002] = {
          Content = "狡猾的狗呜咽着 啃食着腐朽的肉",
          DialogueId = 50003002,
          Duration = 3,
          GUID = "7D2D6184",
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D6184"
        },
        [50003101] = {
          Content = "您也喜欢这些百合吗？",
          DialogueId = 50003101,
          Duration = 3,
          GUID = "7D2D71C2",
          SpeakNpcId = 700072,
          TalkActionId = {
            [1] = "700072:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700072/7D2D71C2"
        },
        [50003201] = {
          ContentKR = "성 밖의 괴물은 우리의 살을 먹고~ 성안의 괴물은 우리의 털을 깎고~ 사냥개는 흰 빵을 먹지만~ 우리 양들은 풀만 뜯어 먹는다네~",
          DialogueId = 50003201,
          Duration = 3,
          GUID = "7D2D822A",
          NextDialogue = 50003202,
          SpeakNpcId = 700073,
          Subtitle = "♪ \"Monsters beyond the walls feast on our flesh; the ones within shear our fleece. While the hounds dine on fine white loaves; we lowly sheep are content with chewing grass...\"",
          TalkActionId = {
            [1] = "700073:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700073/7D2D822A"
        },
        [50003202] = {
          ContentKR = "젠장! 이 노래는 누구한테 배운 거야... 너 때문에 조만간 우리 둘 다 죽게 생겼어!",
          DialogueId = 50003202,
          Duration = 3,
          GUID = "7D2D8254",
          NextDialogue = 50003203,
          SpeakNpcId = 700074,
          Subtitle = "Whoa, whoa! Where did you learn that ditty... you're going to get us both killed one of these days!",
          TalkActionId = {
            [1] = "700074:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D8254"
        },
        [50003203] = {
          ContentKR = "오! 무엇이 필요하세요? 전부 제가 직접 만든 겁니다. 품질은 말할 것도 없죠!",
          DialogueId = 50003203,
          Duration = 3,
          GUID = "7D2D827E",
          SpeakNpcId = 700074,
          Subtitle = "Ah, welcome! What can I get you, dear customer? Each piece here is crafted by my own hands, top-notch quality guaranteed!",
          TalkActionId = {
            [1] = "700074:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D827E"
        },
        [50003301] = {
          Content = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
          DialogueId = 50003301,
          Duration = 3,
          GUID = "7D2D9292",
          SpeakNpcId = 700075,
          TalkActionId = {
            [1] = "700075:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/env/700075/7D2D9292"
        },
        [50003401] = {
          Content = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
          DialogueId = 50003401,
          Duration = 3,
          GUID = "7D2DA2FA",
          SpeakNpcId = 700076,
          TalkActionId = {
            [1] = "700076:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700076/7D2DA2FA"
        },
        [50003501] = {
          Content = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
          DialogueId = 50003501,
          Duration = 3,
          GUID = "7D2DB362",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2DB362"
        },
        [50003601] = {
          Content = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
          DialogueId = 50003601,
          Duration = 3,
          GUID = "7D2DC3CA",
          NextDialogue = 50003602,
          SpeakNpcId = 700078,
          TalkActionId = {
            [1] = "700078:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700078/7D2DC3CA"
        },
        [50003602] = {
          Content = "子爵大人要最好的皮料！要从最健壮的头狼身上剥下的顶级货！懂了吗蠢蛋！你的这些残次品只配给乞丐穿！",
          DialogueId = 50003602,
          Duration = 3,
          GUID = "7D2DC3F4",
          SpeakNpcId = 700079,
          TalkActionId = {
            [1] = "700079:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700079/7D2DC3F4"
        },
        [50003701] = {
          ContentKR = "팝콘! 담배! 그리고 술! 뭔가 잃어버리셨다고요? 전 몰라요! 아, 진짜 못 봤다니까요!",
          DialogueId = 50003701,
          Duration = 4,
          GUID = "7D2DD432",
          SpeakNpcId = 700080,
          Subtitle = "Popcorn! Cigs! Booze! Lost something, you say? Didn't see it! I swear!",
          VoiceName = "voice/$Locale$/env/700080/7D2DD432"
        },
        [50003801] = {
          ContentKR = "모든 카론이 내 나이만큼만 살 수 있다면, 나도 이렇게 외롭진 않을 텐데.",
          DialogueId = 50003801,
          Duration = 7,
          GUID = "7D2DE49A",
          SpeakNpcId = 700081,
          Subtitle = "If every Charon could live as long as I have, I wouldn't feel so alone.",
          VoiceName = "voice/$Locale$/env/700081/7D2DE49A"
        },
        [50003901] = {
          ContentKR = "손이 부러진 적이 있지만, 잡화는 아직 옮길 수 있어요. 뭐가 필요하세요?",
          DialogueId = 50003901,
          Duration = 3,
          GUID = "7D2DF502",
          SpeakNpcId = 700082,
          Subtitle = "Welcome! And don't worry about my broken arm — I can still get you anything you need. So, what will it be?",
          TalkActionId = {
            [1] = "700082:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700082/7D2DF502"
        },
        [50004001] = {
          ContentKR = ".........(달걀 루나가 보드에 빠르게 \"안녕하세요\"라고 적었다)",
          DialogueId = 50004001,
          Duration = 3,
          GUID = "7D2E056A",
          SpeakNpcId = 900008,
          Subtitle = "... (Lunoeggy quickly scribbles \"Hello\" on the board.)",
          VoiceName = "voice/$Locale$/env/900008/7D2E056A"
        },
        [50004101] = {
          ContentKR = "새 의뢰를 받았는데, 늘 하던 대로 8:2로 나누자고. 이것만 다 마시면 바로 출발하려고 하는데, 어때?",
          DialogueId = 50004101,
          Duration = 3,
          GUID = "7D2E15D2",
          SpeakNpcId = 200015,
          Subtitle = "I've yet again been commissioned recently. Let's go with the usual 80-20 split and head out after I finish this bottle. What do you say?",
          TalkActionId = {
            [1] = "200015:Agree"
          },
          VoiceName = "voice/$Locale$/env/200015/7D2E15D2"
        },
        [50004201] = {
          ContentKR = "한 잔 줄까?",
          DialogueId = 50004201,
          Duration = 3,
          GUID = "7D2E263A",
          SpeakNpcId = 200003,
          Subtitle = "Care for a drink?",
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_01"
        },
        [50004301] = {
          ContentKR = "♪날지 못하는 나이팅게일, 울지 마렴...",
          DialogueId = 50004301,
          Duration = 3,
          GUID = "7D2E36A2",
          NextDialogue = 50004302,
          SpeakNpcId = 700142,
          Subtitle = "♪ \"Nightingale, broken wings, you can weep you can sleep...\"",
          TalkActionId = {
            [1] = "700142:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36A2"
        },
        [50004302] = {
          ContentKR = "♪나-의 나이팅게일, 여기 잠들지 마렴...",
          DialogueId = 50004302,
          Duration = 3,
          GUID = "7D2E36CC",
          SpeakNpcId = 700142,
          Subtitle = "♪ \"Nightingale, rise above, you will free you will see...\"",
          TalkActionId = {
            [1] = "700142:Explain02_End"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36CC"
        },
        [50004401] = {
          ContentKR = "제, 제발... 가 주세요... 월석 사시려는 게 아니면 그냥 어서 가세요... 병사들이 오면 안 된다고요...",
          DialogueId = 50004401,
          Duration = 4,
          GUID = "7D2E470A",
          SpeakNpcId = 700113,
          Subtitle = "S-Scoot if you ain't buying any Phoxene... Lest your presence draws the soldiers' attention to us...",
          TalkActionId = {
            [1] = "700113:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700113/7D2E470A"
        },
        [50004501] = {
          ContentKR = "춤추자! 다 같이 춤추는 거야! 사는 게 뭐가 중요해? 골치 아픈 건 다 잊고 내일까지 춤추자고!",
          DialogueId = 50004501,
          Duration = 3,
          GUID = "7D2E5772",
          SpeakNpcId = 700129,
          Subtitle = "Dance! Find your own groove! What's the meaning of life, you ask? Into the bin with all the stress and the fuss, and let's dance the night away!",
          VoiceName = "voice/$Locale$/env/700129/7D2E5772"
        },
        [50004601] = {
          ContentKR = "나리, 이번 달 보조금은... 아, 아직 안 나왔군요. 쿨럭 쿨럭... 괜찮습니다. 우선은 제 돈으로 보충하겠습니다... 귀찮게 해드려 죄송합니다...",
          DialogueId = 50004601,
          Duration = 4,
          GUID = "7D2E67DA",
          SpeakNpcId = 700070,
          Subtitle = "Sir, about this month's Imperial pension... Oh, you haven't received approval for that yet? *cough* *cough*... It's okay, I'll put my own money down first... Sorry to trouble you...",
          TalkActionId = {
            [1] = "700070:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700070/7D2E67DA"
        },
        [50004701] = {
          ContentKR = "보물에 대한 정보가 내게 있소...",
          DialogueId = 50004701,
          Duration = 3,
          GUID = "7D2E7842",
          SpeakNpcId = 700048,
          Subtitle = "Treasure the intel, never miss the thrill!",
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E7842"
        },
        [50004801] = {
          ContentKR = "어부 공제 조합에 대해 알아보겠나!",
          DialogueId = 50004801,
          Duration = 3,
          GUID = "7D2E88AA",
          SpeakNpcId = 700048,
          Subtitle = "Come join the Fishermen's Mutual Aid Society, let's hook the fun!",
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E88AA"
        },
        [50004901] = {
          ContentKR = "제대로 소독만 하면 맛있는 요리가 된다고!",
          DialogueId = 50004901,
          Duration = 3,
          GUID = "7D2E9912",
          SpeakNpcId = 700116,
          Subtitle = "Properly disinfected, it can become a delicious dish!",
          TalkActionId = {
            [1] = "700116:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700116/7D2E9912"
        },
        [50005001] = {
          ContentKR = "흠, 처음 보는 얼굴이군.",
          DialogueId = 50005001,
          Duration = 3,
          GUID = "7D2EA97A",
          SpeakNpcId = 700096,
          Subtitle = "Ugh, new face.",
          TalkActionId = {
            [1] = "700096:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EA97A"
        },
        [50005101] = {
          ContentKR = "뭐, 살 거라도 있나?",
          DialogueId = 50005101,
          Duration = 3,
          GUID = "7D2EB9E2",
          SpeakNpcId = 700096,
          Subtitle = "What do you want?",
          TalkActionId = {
            [1] = "700096:Agree"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EB9E2"
        },
        [50005201] = {
          ContentKR = "욕망에 충실하라, 욕망에 충실하라, 욕망에 충실하라... 아, 도대체 어떻게 해야 욕망에 충실한 거야...",
          DialogueId = 50005201,
          Duration = 4,
          GUID = "7D2ECA4A",
          SpeakNpcId = 700077,
          Subtitle = "Stay true to yourself. stay true to yourself... Ugh, what am I supposed to do to stay true to myself... ",
          TalkActionId = {
            [1] = "700077:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2ECA4A"
        },
        [50005301] = {
          ContentKR = "다음 역으로 가는 열차가 곧 출발합니다. 표는 이곳에서 구매하시면 됩니다. 뭐라고요? 돈이 없다고요? 헛된 꿈은 그만 꾸고 저리 가세요!",
          DialogueId = 50005301,
          Duration = 4,
          GUID = "7D2D1FBA",
          SpeakNpcId = 700147,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700147:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700021/7D2D1FBA"
        },
        [50005401] = {
          ContentKR = "하하하, 정말 빠르게 도망가네! 생쥐보다도 더 빠른걸!",
          DialogueId = 50005401,
          Duration = 3,
          GUID = "7D2EEB1A",
          SpeakNpcId = 700089,
          Subtitle = "Hahaha, she's running so fast, faster than a mouse!"
        },
        [50005501] = {
          ContentKR = "이 더러운 카론 녀석아, 뭘 멍하니 서 있어! 어서 쫓아가라고!",
          DialogueId = 50005501,
          Duration = 3,
          GUID = "7D2EFB82",
          SpeakNpcId = 700088,
          Subtitle = "Stinky Charon, what are you waiting for? Go after your little brat!",
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [50005601] = {
          ContentKR = "간판을 좀 더 큰 걸로 바꿔봐야 할까...",
          DialogueId = 50005601,
          Duration = 3,
          GUID = "7D2F0BEA",
          SpeakNpcId = 700143,
          Subtitle = "Should we get a bigger board..."
        },
        [50100101] = {
          ContentKR = "바늘부터 실까지, 향유부터 향주머니까지 다 있어요! 구경하고 가세요~",
          DialogueId = 50100101,
          GUID = "7D6B9BD2",
          Subtitle = "Needles, thread, balsams and sachets — does anything catch your eye?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6B9BD2"
        },
        [50100201] = {
          ContentKR = "화서의 특별한 기념품 좀 보고 가세요! 가족, 친구 선물로 그만입니다!",
          DialogueId = 50100201,
          GUID = "7D6BAC3A",
          Subtitle = "Come, have a look! Fine souvenirs of Huaxu — take one home for your dear ones!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BAC3A"
        },
        [50100301] = {
          ContentKR = "저 바다 너머는... 어떤 모습일까?",
          DialogueId = 50100301,
          GUID = "7D6BBCA2",
          Subtitle = "I wonder... what the world beyond the sea is like.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBCA2"
        },
        [50100311] = {
          ContentKR = "반장이 어제 기분이 좋았나 봐. 우리한테까지 장려금을 찔러 주더라니까!",
          DialogueId = 50100311,
          GUID = "7D6BBE46",
          Subtitle = "The foreman was in a good mood yesterday — he even slipped us a little bonus.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE46"
        },
        [50100312] = {
          ContentKR = "그게 끝이 아니야! 출항 전엔 사장님이 차도 한잔 사 줬다고!",
          DialogueId = 50100312,
          GUID = "7D6BBE70",
          Subtitle = "Ha! That's nothing — the boss treated us to tea before we set off.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE70"
        },
        [50100401] = {
          ContentKR = "허리 아파 죽겠네. 시간 날 때 시원하게 안마라도 받아야겠어...",
          DialogueId = 50100401,
          GUID = "7D6BCD0A",
          Subtitle = "Ugh, my back's killing me. Gotta get someone to work the knots out one of these days...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BCD0A"
        },
        [50100501] = {
          ContentKR = "이 상자는 귀한 물건이니까, 부드러운 천으로 한 겹 싸고 나서 옮기자고.",
          DialogueId = 50100501,
          GUID = "7D6BDD72",
          Subtitle = "Careful with that crate — it's pricey. Wrap it in something soft before we move it.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BDD72"
        },
        [50100601] = {
          ContentKR = "나무로 만든 이 비녀랑 장신구, 예쁘긴 한데 어떻게 쓰는 건지 모르겠네.",
          DialogueId = 50100601,
          GUID = "7D6BEDDA",
          Subtitle = "These embossed hairpins are gorgeous... but I've no idea how to wear them right.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BEDDA"
        },
        [50100701] = {
          ContentKR = "향료, 비단, 찻잎, 기름, 그릇... 종류가 너무 많아!",
          DialogueId = 50100701,
          GUID = "7D6BFE42",
          Subtitle = "Incense, silks, teas, oils, salves, fine wares... where do I even start?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BFE42"
        },
        [50100801] = {
          ContentKR = "침월향이 다 팔렸다고요? 말도 안 돼. 어제 막 들어왔잖아요!",
          DialogueId = 50100801,
          GUID = "7D6C0EAA",
          Subtitle = "Out of Lunarose already? That can't be right — it just came in yesterday!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C0EAA"
        },
        [50100901] = {
          ContentKR = "수량 딱 맞고, 종류도 다 있고~ 오늘은 시작이 좋네~",
          DialogueId = 50100901,
          GUID = "7D6C1F12",
          Subtitle = "All tallied, all tidy — looks like a smooth start today~",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C1F12"
        },
        [50101001] = {
          ContentKR = "역시 화서는 소문대로 대단한 곳이군. 별을 잇는 자들의 고향다워.",
          DialogueId = 50101001,
          GUID = "7D6C2F7A",
          Subtitle = "So this is where the Starweavers hail from... Huaxu really does live up to its name.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C2F7A"
        },
        [50101101] = {
          ContentKR = "산 좋고 물 좋은 곳에서 마시는 차 한잔~ 캬, 정말 기가 막히다~",
          DialogueId = 50101101,
          GUID = "7D6C3FE2",
          Subtitle = "Such a fine view... a cup of fragrant tea here would be pure delight.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C3FE2"
        },
        [50101201] = {
          ContentKR = "내기에서 지면 나한테 탕후루 3개 사 줘야 돼. 나중에 딴소리하지 마.",
          DialogueId = 50101201,
          GUID = "7D6C504A",
          Subtitle = "A bet's a bet! You lost, so you owe me three tanghulu skewers. No backsies!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C504A"
        },
        [50101202] = {
          ContentKR = "걱정 마, 내일 엄마한테 용돈 받으면 바로 사 줄게!",
          DialogueId = 50101202,
          GUID = "7D6C5074",
          Subtitle = "All right, all right — I'll get them for you when I've got my spending money tomorrow!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C5074"
        },
        [50101203] = {
          ContentKR = "별빛 부두는 해마다 더 활기가 넘치네...",
          DialogueId = 50101203,
          GUID = "7D6C509E",
          Subtitle = "Starwharf grows busier by the year.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C509E"
        },
        [50101301] = {
          ContentKR = "어머나! 부딪히는 바람에 머리 모양이 다 망가졌잖아!",
          DialogueId = 50101301,
          GUID = "7D6C60B2",
          Subtitle = "Oof! You knocked my hair loose!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C60B2"
        },
        [50101401] = {
          ContentKR = "어이! 한눈팔면서 걷지 마! 다른 사람이랑 부딪히잖아!",
          DialogueId = 50101401,
          GUID = "7D6C711A",
          Subtitle = "Watch where you're going, young friend — don't go barging into people like that.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C711A"
        },
        [50101501] = {
          ContentKR = "비단은 가지런히 접어 두고, 잡곡은 가게 안에 들여놔야 마음이 편하다니까...",
          DialogueId = 50101501,
          GUID = "7D6C8182",
          Subtitle = "Silks in place, grain stacked neatly — only then can a man rest easy.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C8182"
        },
        [50101601] = {
          ContentKR = "가문 대대로 전해 내려오는 산삼~ 백 년 된 아교~ 싸고 좋은 물건 들여가세요!",
          DialogueId = 50101601,
          GUID = "7D6C91EA",
          Subtitle = "Finest ginseng and aged donkey-hide gelatin — fair prices! Come have a look!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C91EA"
        },
        [50101701] = {
          ContentKR = "좋은 물건은 싸게 안 팔아요. 알아봐 주는 손님이 있기 마련이거든요!",
          DialogueId = 50101701,
          GUID = "7D6CA252",
          Subtitle = "Quality doesn't come cheap — those with taste know it's worth the coin.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CA252"
        },
        [50101801] = {
          ContentKR = "도자기는 깨지기 쉽습니다~ 살살 다뤄 주세요~",
          DialogueId = 50101801,
          GUID = "7D6CB2BA",
          Subtitle = "Careful now — fine porcelain. Easy does it, dear customer.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CB2BA"
        },
        [50101901] = {
          ContentKR = "조금만 더 깎아 주세요. 바로 살게요.",
          DialogueId = 50101901,
          GUID = "7D6CC322",
          Subtitle = "Knock a little off and I'll take it right now.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CC322"
        },
        [50102001] = {
          ContentKR = "예뻐 보이긴 하는데... 병에 흠집 같은 건 없죠?",
          DialogueId = 50102001,
          GUID = "7D6CD38A",
          Subtitle = "Lovely vase... no cracks or chips, right?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CD38A"
        },
        [50102101] = {
          ContentKR = "계화떡 좀 싸 주세요. 집사람한테 갖다주려고요~",
          DialogueId = 50102101,
          GUID = "7D6CE3F2",
          Subtitle = "A few osmanthus cakes, please. They're my wife's favorite.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CE3F2"
        },
        [50102201] = {
          ContentKR = "보들보들하니까, 안에 받쳐 입는 옷을 만들면 딱이겠어.",
          DialogueId = 50102201,
          GUID = "7D6CF45A",
          Subtitle = "This fabric's soft and smooth — it'll make a fine lining, that's for sure.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CF45A"
        },
        [50102301] = {
          ContentKR = "신군님께 맹세하건대, 나는 평생 네 마음을 저버리지...",
          DialogueId = 50102301,
          GUID = "7D6D04C2",
          Subtitle = "By Lord Argent as my witness, I, Xueji, swear never to fail Chuqing, or I'll—",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D04C2"
        },
        [50102401] = {
          ContentKR = "쉿! 거기까지! 무슨 말을 할 건지 다 알아...",
          DialogueId = 50102401,
          GUID = "7D6D152A",
          Subtitle = "Uh-uh! Don't say it! I know...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D152A"
        },
        [50102501] = {
          ContentKR = "백룡신군이시여, 무사히 이번 항해를 마치도록 굽어살펴 주시옵소서!",
          DialogueId = 50102501,
          GUID = "7D6D2592",
          Subtitle = "May Lord Argent grant this voyage fair winds and safe seas!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D2592"
        },
        [50102601] = {
          ContentKR = "집안 어른들께서 건강하게 오래오래 사시게 해 주세요.",
          DialogueId = 50102601,
          GUID = "7D6D35FA",
          Subtitle = "May Lord Argent bless my family with good health and long, peaceful years.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D35FA"
        },
        [50102701] = {
          ContentKR = "명 선생, 요즘 어디서 큰돈이라도 번 겁니까?",
          DialogueId = 50102701,
          GUID = "7D6D4662",
          Subtitle = "It's been a while, Ming. Been turning a decent profit lately?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D4662"
        },
        [50102702] = {
          ContentKR = "운이 좋았던 겁니다! 사업은 역시 강 선생 쪽이 더 탄탄하죠.",
          DialogueId = 50102702,
          GUID = "7D6D468C",
          Subtitle = "Ha! Pure luck, that's all. Your business runs steadier than mine any day.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D468C"
        },
        [50102801] = {
          ContentKR = "다음 항해 때는 케메트 북쪽으로 조금만 더 가 보자...",
          DialogueId = 50102801,
          GUID = "7D6D56CA",
          Subtitle = "Next trip, I'll head a bit farther north of Khemet — see what's there.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D56CA"
        },
        [50102901] = {
          ContentKR = "가격을 확 낮췄는데도, 어째서 판매량은 여전히 이 모양이지...",
          DialogueId = 50102901,
          GUID = "7D6D6732",
          Subtitle = "I've slashed prices to the bone — why aren't sales picking up...?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D6732"
        },
        [50103001] = {
          ContentKR = "얼마 전에 별을 잇는 자가 됐습니다! 앞으로 많이 가르쳐 주세요!",
          DialogueId = 50103001,
          GUID = "7D6D779A",
          Subtitle = "I'm new to the Starweavers — I'll be relying on your guidance.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D779A"
        },
        [50103002] = {
          ContentKR = "천만에, 궁금한 게 있으면 편히 물어봐.",
          DialogueId = 50103002,
          GUID = "7D6D77C4",
          Subtitle = "You're too kind. Feel free to ask anything.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77C4"
        },
        [50103003] = {
          ContentKR = "추가 투자를 해야 할까요, 아니면 좀 괜찮다 싶을 때 발을 빼는 게 맞을까요?",
          DialogueId = 50103003,
          GUID = "7D6D77EE",
          Subtitle = "What do you think, then — double down, or cut my losses while I still can?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77EE"
        },
        [50103101] = {
          ContentKR = "새로 온 녀석 말이야, 돈은 좀 있어 보여?",
          DialogueId = 50103101,
          GUID = "7D6D8802",
          Subtitle = "New face, eh? Do you think he's got any silver?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D8802"
        },
        [50103201] = {
          ContentKR = "깡촌에서 온 놈이라 가진 것도 얼마 없는 것 같던데.",
          DialogueId = 50103201,
          GUID = "7D6D986A",
          Subtitle = "From a poor patch, him. Don't think he can rub two coins together.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D986A"
        },
        [50103301] = {
          ContentKR = "구경하시겠어요? 감쪽같이 수리한 진짜 골동품이랍니다.",
          DialogueId = 50103301,
          GUID = "7D6DA8D2",
          Subtitle = "Have a look, friend — authentic antiques, fresh off the dig.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DA8D2"
        },
        [50103401] = {
          ContentKR = "원래 외국인들하고만 거래했었는데, 정말 어렵게 다시 화서로 들여온 거예요!",
          DialogueId = 50103401,
          GUID = "7D6DB93A",
          Subtitle = "These pieces once went straight to foreign buyers. Took work and coin to bring them back!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DB93A"
        },
        [50103501] = {
          ContentKR = "바람결엔 태호 님의 숨결이 서려 있어. 마음을 비우고 그냥 느끼면 돼...",
          DialogueId = 50103501,
          GUID = "7D6DC9A2",
          Subtitle = "The wind carries Taihao's will. Be still, and you'll feel it.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DC9A2"
        },
        [50103601] = {
          ContentKR = "황해쑥 50근, 춘일품 30근... 어이, 거기! 향료는 다 귀한 물건이라니까! 옮길 때 조심하라고!",
          DialogueId = 50103601,
          GUID = "7D6DDA0A",
          SpeakNpcId = 701039,
          Subtitle = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DDA0A"
        }
      }
    end
  },
  {
    MinKey = 50103701,
    MaxKey = 50107215,
    Loader = function()
      return {
        [50103701] = {
          ContentKR = "외국 손님들을 위한 기념품 가게입니다! 화서에 오셨다면 놓치지 마세요! 향주머니부터 부채, 골동품, 진귀한 보물까지 원하시는 건 뭐든 있습니다!",
          DialogueId = 50103701,
          GUID = "7D6DEA72",
          SpeakNpcId = 701040,
          Subtitle = "Souvenirs for travellers! First time to Huaxu? Don't pass me by — sachets, folding fans, curios, trinkets, all the little treasures you could want!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DEA72"
        },
        [50103801] = {
          ContentKR = "지나가는 분들은 다들 이 늙은이가 들려주는 별빛 부두의 역사를 들어 보시게. 장사꾼이라면 현명해야 하니, 이 땅의 과거도 훤히 알고 있어야지 않겠나.",
          DialogueId = 50103801,
          GUID = "7D6DFADA",
          SpeakNpcId = 701041,
          Subtitle = "Folks, lend me your ears for a moment — let me tell you the thousand-year tale of our very own Starwharf! Just as trade should be fair and square, so too should our past — plain and open for all to see.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DFADA"
        },
        [50103901] = {
          ContentKR = "잘 들으세요. 대풍구장 제1장은 \"남을 해하거나 목숨을 빼앗지 말지어다\"로 규정하고 있어요.",
          DialogueId = 50103901,
          GUID = "7D6E0B42",
          SpeakNpcId = 701044,
          Subtitle = "Listen well. The first of the Nine Chapters says: \"To wound or kill — this must not be done.\"",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E0B42"
        },
        [50104001] = {
          ContentKR = "뿔이 나게 하려면 어떻게 해야 하지? 끄으응... 아야! 당겨 봐야 아프기만 한데...",
          DialogueId = 50104001,
          GUID = "7D6E1BAA",
          SpeakNpcId = 701045,
          Subtitle = "How do I make my horns grow? Maybe if I give them a little tug... ow! That hurts!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E1BAA"
        },
        [50104101] = {
          ContentKR = "별을 잇는 자가 되면 좋은 점이 정말 많구나! 백년춘은 정말 대단한 곳이네!",
          DialogueId = 50104101,
          GUID = "7D6E2C12",
          SpeakNpcId = 701046,
          Subtitle = "I never realized being a Starweaver came with so many perks. EverSpring truly is remarkable.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E2C12"
        },
        [50104201] = {
          ContentKR = "응접실을 하나 지을까? 아니면 작은 부엌을 추가해 볼까?",
          DialogueId = 50104201,
          GUID = "7D6E3C7A",
          SpeakNpcId = 701048,
          Subtitle = "How about adding a reception hall? Or perhaps a small kitchen?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E3C7A"
        },
        [50104301] = {
          ContentKR = "달 위로 올라가자고? 그게 되겠어?",
          DialogueId = 50104301,
          GUID = "7D6E4CE2",
          SpeakNpcId = 701050,
          Subtitle = "Climb all the way to the moon? There's no way we can do that!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E4CE2"
        },
        [50104401] = {
          ContentKR = "이야, 정말 오래된 천성판이네!",
          DialogueId = 50104401,
          GUID = "7D6E5D4A",
          SpeakNpcId = 701051,
          Subtitle = "Ah... this Stellapass — now that's a piece of history!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E5D4A"
        },
        [50104501] = {
          ContentKR = "이익보다 상도가 먼저다, 사치가 아닌 덕망을 중시하라...",
          DialogueId = 50104501,
          GUID = "7D6E6DB2",
          SpeakNpcId = 701052,
          Subtitle = "Count not profit but righteousness as honour; count not splendour but virtue as nobility...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E6DB2"
        },
        [50104601] = {
