          DialogueId = 50104601,
          GUID = "7D6E7E1A",
          SpeakNpcId = 701054,
          Subtitle = "If you have any enquiries regarding EverSpring's services, you may speak to me here.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E7E1A"
        },
        [50104701] = {
          ContentKR = "아이스베리잼은 어제 도착했는데, 왜 아직도 통관을 안 시켜줘! 빨리 물건 달라고!",
          DialogueId = 50104701,
          GUID = "7D6E8E82",
          SpeakNpcId = 701057,
