        },
        [50105501] = {
          ContentKR = "쉬익... 쉬익...",
          DialogueId = 50105501,
          GUID = "7D6F11C2",
          SpeakNpcId = 701071,
          Subtitle = "Huff... Huff...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F11C2"
        },
        [50105601] = {
          ContentKR = "왜 이리 추웠다 더웠다 하는지... 증조할머니한테 듣기론, 옛날엔 꽃들이 활짝 핀 따뜻한 곳이라고 했는데!",
          DialogueId = 50105601,
          GUID = "7D6F222A",
          SpeakNpcId = 701072,
          Subtitle = "Hot one minute, freezing the next... My great-grandmother always said it used to be spring all year round.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F222A"
        },
        [50105701] = {
          ContentKR = "여기서 향을 피우는 거야! 그러면 신화에서처럼 백룡신군께서 나타나 저 사악한 짐승들을 모두 처치해 주시겠지!",
          DialogueId = 50105701,
          GUID = "7D6F3292",
