          VoiceName = "voice/$Locale$/env/Ver0101/7D6F3292"
        },
        [50105801] = {
          ContentKR = "천성판 작동 상태는 전부 이상 없군. 어디 보자, 이제 곧 다음 정비일인가...",
          DialogueId = 50105801,
