          GUID = "7D6F9502",
          SpeakNpcId = 900012,
          Subtitle = "New Lucky Egg variants just dropped! Fancy giving one a spin?"
        },
        [50107001] = {
          ContentKR = "내 돈주머니가 어디 갔지? 갑자기 어디로 사라진 거야?",
          DialogueId = 50107001,
          GUID = "7D7007DA",
          Subtitle = "Where's my purse!? I had it a second ago..."
        },
        [50107002] = {
          ContentKR = "그 입만 산 행상인 녀석 짓이 틀림없어!",
          DialogueId = 50107002,
          GUID = "7D700804",
          Subtitle = "I'll wager it was that fast-talking hawker."
        },
        [50107003] = {
