        },
        [51000210] = {
          ContentKR = "(노부인의 눈에 가득했던 웃음기는 점차 사라지고, 그 자리를 반짝이는 눈물이 대신했다.)",
          DialogueId = 51000210,
          GUID = "7FAC75F4",
          Subtitle = "(The smile slowly fades from the old woman's eyes, replaced by glistening tears.)",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51000301] = {
          ContentKR = "대체 어디로 간 걸까...",
          DialogueId = 51000301,
          GUID = "7FAC84E2",
          NextDialogue = 51000302,
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          }
        },
        [51000302] = {
          ContentKR = "(노부인의 슬픈 눈동자는 먼 곳에 고정되어 있었고, 목소리를 듣지 못한 듯했다.)",
          DialogueId = 51000302,
          GUID = "7FAC850C",
          NextOptions = {
            [1] = 510003021,
            [2] = 510003022,
            [3] = 510003023
          },
          Subtitle = "(The old lady's sorrowful gaze lingers in the distance, oblivious to your approach.)",
          bForbidSkipOptions = true
        },
        [51000303] = {
          ContentKR = "(옷은 오래됐지만 만듦새가 정교하고 세련됐다. 꽤 부유한 집안 출신일지도 모르겠다.)",
          DialogueId = 51000303,
          GUID = "7FAC8536",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          Subtitle = "(Her attire, though slightly worn, is crafted from fine fabric and exquisitely tailored, indicating an affluent background.)",
          bForbidSkipOptions = true
        },
        [51000304] = {
          ContentKR = "(내내 성 밖을 바라보며 누군가가 돌아오길 기다리는 것 같다.)",
          DialogueId = 51000304,
          GUID = "7FAC8560",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          Subtitle = "(She gazes beyond the city gates, seemingly waiting for someone's return.)",
          bForbidSkipOptions = true
        },
        [51000305] = {
          ContentKR = "(노쇠한 두 눈에 슬픔이 가득한 것이 꼭 길고 희망 없는 기다림을 겪은 듯하다.)",
          DialogueId = 51000305,
          GUID = "7FAC858A",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          Subtitle = "(Her aged eyes are filled with sorrow, seemingly bearing the weight of a long and hopeless wait.)",
          bForbidSkipOptions = true
        },
        [51000306] = {
          ContentKR = "(노부인은 당신을 뒤돌아보더니 다시 고개를 돌렸다. 당신의 말에 관심 없는 듯하다.)",
          DialogueId = 51000306,
          GUID = "7FAC85B4",
          Subtitle = "(The old woman glances at you briefly before turning away, seemingly uninterested in conversation.)"
        },
        [51000307] = {
          ContentKR = "...너는...",
          DialogueId = 51000307,
          GUID = "7FAC85DE",
          NextDialogue = 51000308,
          SpeakNpcId = 700019,
          Subtitle = "Who are you...?",
          TalkActionId = {
            [1] = "700019:Sigh_End"
          }
        },
        [51000308] = {
          ContentKR = "처음 보는 얼굴이구나. 근처 마을에서 왔니?",
          DialogueId = 51000308,
          GUID = "7FAC8608",
          NextDialogue = 51000309,
          SpeakNpcId = 700019,
          Subtitle = "I haven't seen you before. Are you from a nearby village?",
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51000309] = {
          ContentKR = "혹시 하멜 디킨슨이라는 카론 남자를 본 적 있니? 아이스레이크 시티에서 태어났고, 옅은 갈색 머리에 열여덟아홉 살쯤 되었고, 즐겨 입는 옷은... 아니, 지금은 나랑 비슷한 나이가 됐을 거야.",
          DialogueId = 51000309,
          GUID = "7FAC8632",
          NextDialogue = 51000310,
          SpeakNpcId = 700019,
          Subtitle = "Have you ever come across a Charon man named Hamel Dickinson? He's an Icelake local, light brown hair, about nineteen years old, wears... Oh, no, I think he'd be about my age now."
        },
        [51000310] = {
