          DialogueId = 51002421,
          GUID = "7FADE0B2",
          NextDialogue = 51002422,
          SpeakNpcId = 700020,
          Subtitle = "You're a Phoxhunter, must be quite busy with your commissions. I won't keep you any longer."
        },
