        [51009222] = {
          Camera = "302.543945,-108.304688,186.282227,0.000152,-9.201569,139.426468,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentKR = "뜻밖의 대답이긴 하지만, 도색 또한 미관에 영향을 주는 요소 중 하나지. 그 부분을 중시하는 사람도 더러 있고 말일세.",
          DialogueId = 51009222,
          FacialId = {
            [1] = "230002:Ahaha02"
          },
          FinalCamera = "278.34668,-132.726074,186.282227,0.000151,-9.00156,131.226593,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23C7C",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextDialogue = 51009223,
          SpeakNpcId = 230002,
          Subtitle = "Not at all. Wasn't the answer I expected, but fair enough. Paintwork and palette do matter — plenty of folk care how their weapon looks.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 30
        },
        [51009223] = {
          Camera = "414.796875,83.106445,83.046387,0.000167,1.99893,178.023361,25.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "조금 전에 영웅님의 무기를 보니 색감이 무척 수수하더군요. 개인 취향을 존중해 드리고 싶었지만, 예술과 미에 대한 열정을 주체할 수 없어 그만...",
          DialogueId = 51009223,
          FinalCamera = "334.032227,127.685059,137.778564,0.000189,-2.60138,-169.170135,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23CA6",
          LookAt = {
            [1] = "230003:n(100001)",
            [2] = "100001:n(230003)"
          },
          NextDialogue = 51009224,
          SpeakNpcId = 230003,
          Subtitle = "Just now, I noticed your weapon was... rather muted in tone. I meant to respect your taste and refrain from commenting — but the artist in me simply couldn't resist...",
          TalkActionId = {
            [1] = "230003:Explain01_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009224] = {
          ContentKR = "아무튼, 이건 저만의 염료 배합법과 염료 시제품 몇 가지입니다. 부디 꼭 한번 사용해 보십시오.",
          DialogueId = 51009224,
          GUID = "7FB23CD0",
          LookAt = {
            [1] = "230002:n(230002)"
          },
          NextDialogue = 51009225,
          SpeakNpcId = 230003,
          Subtitle = "So — please, accept this exclusive dye recipe, along with a few trial samples.",
          TalkActionId = {
            [1] = "230003:Explain01_End"
          }
        },
        [51009225] = {
          Camera = "140.89209,77.023438,171.302979,0.000198,-10.586759,-153.78447,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "무기든, 몸에 걸치는 장신구든 상관없습니다. 이걸 쓰시는 순간, 미학의 진리에 한 걸음 더 다가서게 될 겁니다!",
          DialogueId = 51009225,
          FinalCamera = "147.106445,6.32666,173.12915,0.000199,-13.386808,178.615372,25.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23CFA",
          NextOptions = {
            [1] = 510092251,
            [2] = 510092252,
            [3] = 510092253
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{230003},AnimationId{"Give"},Duration{2}},
PlayAnimation{ActorId{230003},AnimationId{"Angry01_Start"},Duration{2}}
}]],
          SpeakNpcId = 230003,
          Subtitle = "Be it blade or accessory, a touch of this shall draw you ever closer to aesthetic enlightenment!",
          ToFinalCameraBlendTime = 15
        },
        [51009226] = {
          Camera = "274.12793,98.953613,123.311523,0.000205,0.68726,-170.794342,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "판매라뇨. 이건 미학의 진리에 다가서기 위한 자그마한 대가일 뿐입니다.",
          DialogueId = 51009226,
          GUID = "7FB23D24",
          NextDialogue = 51009227,
          SpeakNpcId = 230003,
          Subtitle = "Sales pitch? Perish the thought! Merely a modest toll in pursuit of sublime beauty.",
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        },
        [51009227] = {
          Camera = "113.979492,13.10791,128.264404,0.000198,2.998221,54.034763,25.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "물건 파는 사람은 다들 그런 소릴 하더라고요.",
