          SpeakNpcId = 100001,
          Subtitle = "Said every salesperson making a pitch.",
          TalkActionId = {
            [1] = "230003:Explain02_End"
          },
          ToFinalCameraBlendTime = 30
        },
        [51009228] = {
          Camera = "274.12793,98.953613,123.311523,0.000205,0.68726,-170.794342,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "미적 감각이 부족하다고 해서 부끄러워하실 필요는 없습니다. 누구나 그런 실수 정도는 하는 법이지요.",
          DialogueId = 51009228,
          GUID = "7FB23D78",
          NextDialogue = 51009229,
          SpeakNpcId = 230003,
          Subtitle = "Oh, don't be ashamed. A lack of aesthetic awareness is a common — and entirely forgivable — flaw.",
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        }
      }
    end
