          LookAt = {
            [1] = "100001:n(230002)",
            [2] = "230003:n(230002)",
            [3] = "230002:n(230003)"
          },
          NextDialogue = 51009234,
          SpeakNpcId = 230002,
          Subtitle = "Strange as he may be, the lad makes a fair point. I'll take this recipe off your hands.",
          ToFinalCameraBlendTime = 30
        },
        [51009234] = {
          ContentKR = "어르신께서는 역시 대단한 혜안을 가지고 계시군요. 덕분에 저는 미학의 전파라는 위업에 한 걸음 더 다가섰습니다.",
          DialogueId = 51009234,
          GUID = "7FB23E74",
          NextDialogue = 51009235,
          SpeakNpcId = 230003,
          Subtitle = "Ah! A true connoisseur! Thanks to you, my crusade for aesthetic reform takes yet another glorious step forward.",
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        },
        [51009235] = {
          Camera = "232.278809,-1.471191,144.844971,0.00021,-12.512626,123.00547,25.000006,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이 배합법이 어떤 효과가 있을지 함께 시험해 보세, 젊은이.",
          DialogueId = 51009235,
          GUID = "7FB23E9E",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          SpeakNpcId = 230002,
          Subtitle = "Come now — let's put this formula to the test, shall we?",
          TalkActionId = {
            [1] = "230003:Explain02_End"
          }
        },
        [51009236] = {
          Camera = "50.263702,-171.348389,180.614441,0.00006,-22.054018,109.22464,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentKR = "품질은 제법 괜찮구먼. 칠도 고르고 단단히 잘 입혀졌어. 그렇지만 이 늙은이 눈엔 영...",
          DialogueId = 51009236,
          FacialId = {
