        },
        [51009623] = {
          ContentKR = "사람들 집이랑 가구도 고쳐 주시고, 다친 사람한테 약도 가져다주시고, 눈이 펑펑 오는 날엔 갈 곳 없는 사람들을 거둬 주시기도 해... 빈민가 사람들은 거의 다 아저씨한테 도움을 받았다고 보면 돼.",
          DialogueId = 51009623,
          GUID = "7FB27E46",
          NextDialogue = 51009624,
          SpeakNpcId = 700303,
          Subtitle = "He fixes homes and furniture, brings medicine to the sick, even takes in beggars when the snow gets bad... Almost everyone in the slums owes him something."
        },
        [51009624] = {
          ContentKR = "그리고 또...",
          DialogueId = 51009624,
          GUID = "7FB27E70",
          NextDialogue = 51009625,
          SpeakNpcId = 700303,
          Subtitle = "And, and—"
        },
        [51009625] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...음, 그게 아니라, 어떻게 생기셨어?",
          DialogueId = 51009625,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "7FB27E9A",
          NextDialogue = 51009626,
          SpeakNpcId = 100001,
          Subtitle = "...Er, I meant, what does he look like?",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51009626] = {
          Camera = "47.982422,-602.043945,9.373535,0.00001,7.999701,87.596718,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어? 아차... 미안해.",
          DialogueId = 51009626,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB27EC4",
          NextDialogue = 51009627,
          SpeakNpcId = 700303,
          Subtitle = "Huh? Oh... sorry!",
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "700303:Explain02_Start"
          }
        },
        [51009627] = {
          ContentKR = "마흔 좀 넘으셨고, 갈색 머리에, 키는 크고 마른 편이셔... 엄청 낡은 옷을 입고 계실 거야.",
          DialogueId = 51009627,
          GUID = "7FB27EEE",
          NextDialogue = 51009628,
          SpeakNpcId = 700303,
          Subtitle = "He's in his early forties, tall, skinny, brown hair... his clothes are pretty worn..."
        },
        [51009628] = {
          Camera = "-195.67627,-36.560547,82.240234,0.00003,-0.800662,3.794627,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "알겠어, 기억해 둘게. ",
          DialogueId = 51009628,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB27F18",
          SpeakNpcId = 100001,
          Subtitle = "Got it.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          }
        },
        [51009629] = {
          ContentKR = "콜록, 콜록...",
          DialogueId = 51009629,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB27F42",
          NextOptions = {
            [1] = 51009630
          },
          SpeakNpcId = 700301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "*cough*"
        },
        [51009630] = {
          ContentKR = "저기...",
          DialogueId = 51009630,
          GUID = "7FB27F6C",
          NextDialogue = 510095401,
          Subtitle = "Excuse me..."
        },
        [51009631] = {
          ContentKR = "도나트 씨, 맞으세요?",
          DialogueId = 51009631,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB27F96",
          NextDialogue = 51009632,
          SpeakNpcId = 100001,
          Subtitle = "Are you Donat?",
          TalkActionId = {
            [1] = "700301:Explain01_End"
          }
        },
        [51009632] = {
          ContentKR = "누구...?",
          DialogueId = 51009632,
          GUID = "7FB27FC0",
          NextDialogue = 51009633,
          SpeakNpcId = 700301,
          Subtitle = "You are...?"
        },
        [51009633] = {
          ContentKR = "어떤 꼬마한테 부탁받아서 도나트 씨를 찾으러 왔어요.",
          DialogueId = 51009633,
          GUID = "7FB27FEA",
          NextDialogue = 51009634,
          SpeakNpcId = 100001,
          Subtitle = "A child asked me to find you."
        },
        [51009634] = {
          ContentKR = "아... 라스 말이구나. 그 아이는 늘 걱정이 많지.",
          DialogueId = 51009634,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28014",
          NextDialogue = 51009635,
          SpeakNpcId = 700301,
          Subtitle = "Ah... Lars, was it? That boy's a worrier.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009635] = {
          ContentKR = "난 그냥, 이 광산에 와 보고 싶었을 뿐이야... 예전엔 계속 몬스터들이 점령하고 있어서, 가까이 올 수가 없었거든.",
          DialogueId = 51009635,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB2803E",
          NextDialogue = 51009636,
          SpeakNpcId = 700301,
          Subtitle = "I just... wanted to revisit this old pit. I remember it swarming with monsters — no way to get near."
        },
        [51009636] = {
          ContentKR = "그런데 얼마 전에 어떤 엄청난 월석 사냥꾼이 몬스터들을 쓰러뜨렸다는 얘기를 들어서... 좋은 기회다 싶어서 와 본 거지.",
          DialogueId = 51009636,
          GUID = "7FB28068",
          NextOptions = {
            [1] = 510096361,
            [2] = 510096362
          },
          SpeakNpcId = 700301,
          Subtitle = "Then I heard a skilled Phoxhunter had cleared them out, so... I figured it was safe enough to come back.",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009637] = {
          ContentKR = "그랬구나... 정말 고마워. 콜록, 콜록!",
          DialogueId = 51009637,
          GUID = "7FB28092",
          NextDialogue = 51009638,
          SpeakNpcId = 700301,
          Subtitle = "Is that so...? Thank you, truly—*cough*"
        },
        [51009638] = {
          ContentKR = "미안, 이렇게 먼 걸음 해 줘서 고마운데, 난 더 안쪽으로 들어가 봐야 해... 먼저 돌아가서 라스한테 난 괜찮다고 좀 전해줘. 보수는, 나중에 내가 아스포델에 가서... 콜록!",
          DialogueId = 51009638,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB280BC",
          NextDialogue = 51009639,
          SpeakNpcId = 700301,
          Subtitle = "Sorry... I need to press on a bit further in. Thank you for coming all this way. Please tell Lars I'm okay. I'll leave your reward for the commission at The Asphodel later... *cough*"
        },
        [51009639] = {
          ContentKR = "그땐 가장 덩치 큰 녀석만 처치한 거라, 아직 필토이드가 몇 마리 남아 있을 거예요. 지금 몸 상태로는 힘드실 테니까, 어디로 가실 건지 말씀해 주시면, 모셔다드릴게요.",
          DialogueId = 51009639,
          GUID = "7FB280E6",
          NextDialogue = 51009640,
          SpeakNpcId = 100001,
          Subtitle = "I've only taken care of the largest one. There might still be Filthoids inside. You're not in any shape to explore alone. Where were you headed? Let me walk with you."
        },
        [51009640] = {
          ContentKR = "그래도... 될까?",
          DialogueId = 51009640,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28110",
          NextDialogue = 51009641,
          SpeakNpcId = 700301,
          Subtitle = "You'd... do that?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009641] = {
          ContentKR = "네. 라스한테 도나트 씨를 무사히 모시고 돌아가겠다고 약속했거든요.",
          DialogueId = 51009641,
          GUID = "7FB2813A",
          NextDialogue = 51009642,
          SpeakNpcId = 100001,
          Subtitle = "I promised Lars I'd bring you home safely."
        },
        [51009642] = {
          ContentKR = "고마워. 정말 고마워, 마음씨 고운 젊은 친구.",
          DialogueId = 51009642,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28164",
          SpeakNpcId = 700301,
          Subtitle = "Thank you... thank you, kind soul.",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009643] = {
          Camera = "-375.460938,260.694336,170.375488,0.000148,-11.001406,-38.598434,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "정말로 고마워, 젊은 친구...",
          DialogueId = 51009643,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB2818E",
          NextDialogue = 51009644,
          SpeakNpcId = 700301,
          Subtitle = "Thank you, young one...",
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009644] = {
          Camera = "704.804688,1549.59082,762.798828,0.000162,-10.801759,-103.40123,25.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "생각보다 훨씬 폐허가 됐군...",
          DialogueId = 51009644,
          FinalCamera = "704.804688,1549.59082,762.798828,0.000163,-10.801759,-103.401352,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB281B8",
          NextDialogue = 51009645,
          SpeakNpcId = 700301,
          Subtitle = "It's even more run-down than I'd imagined...",
          ToFinalCameraBlendTime = 5
        },
        [51009645] = {
          Camera = "949.248047,585.90332,736.995117,0.000167,0.198089,-138.598633,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이 문도 잠겼어. 다행히, 이쪽 파이프로 지나갈 수 있겠네...",
          DialogueId = 51009645,
          GUID = "7FB281E2",
          SpeakNpcId = 700301,
          Subtitle = "Main gate's locked, too. Good thing this pipe still lets us through..."
        },
        [51009646] = {
          ContentKR = "콜록... 콜록콜록...",
          DialogueId = 51009646,
          GUID = "7FB2820C",
          NextDialogue = 51009647,
          SpeakNpcId = 700301,
          Subtitle = "*cough* *cough* *cough*..."
        },
        [51009647] = {
          ContentKR = "괜찮으세요?",
          DialogueId = 51009647,
          GUID = "7FB28236",
          NextDialogue = 51009648,
          SpeakNpcId = 100001,
          Subtitle = "You alright?"
        },
        [51009648] = {
          ContentKR = "괜찮... 콜록, 콜록, 괜찮아... 계속 가자. 조금만 더 가면 내가 찾는 곳이 나올 거야.",
          DialogueId = 51009648,
          GUID = "7FB28260",
          NextDialogue = 51009649,
          SpeakNpcId = 700301,
          Subtitle = "I'm f—*cough*—fine... Let's keep moving. The place I'm looking for is just ahead."
        },
        [51009649] = {
          ContentKR = "여기 지리를 잘 아시나 봐요?",
          DialogueId = 51009649,
          GUID = "7FB2828A",
          NextDialogue = 51009650,
          SpeakNpcId = 100001,
          Subtitle = "You seem to know this place well."
        },
        [51009650] = {
          ContentKR = "그렇지... 여기서 광부로 일한 적이 있거든. 16년 전에는 일하느라 매일 지나다녔어.",
          DialogueId = 51009650,
          GUID = "7FB282B4",
          NextDialogue = 51009651,
          SpeakNpcId = 700301,
          Subtitle = "I do... I used to be a miner here. Sixteen years ago, I walked this path every day."
        },
        [51009651] = {
          ContentKR = "그땐, 하루에 10시간 이상 여기 있었으니까, 여기 길이라면, 구석구석 눈 감아도 훤해.",
          DialogueId = 51009651,
          GUID = "7FB282DE",
          SpeakNpcId = 700301,
          Subtitle = "Back then, we'd spend ten, twelve hours down here... I knew every turn — even with my eyes closed."
        },
        [51009652] = {
          ContentKR = "이런, 필토이드들한테 포위당해 버렸네...",
          DialogueId = 51009652,
          GUID = "7FB28308",
          SpeakNpcId = 700301,
          Subtitle = "Darn it... it's surrounded by Filthoids..."
        },
        [51009653] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다행히 훼손되진 않았구나... 고마워, 젊은 친구.",
          DialogueId = 51009653,
          GUID = "7FB28332",
          NextDialogue = 51009654,
          SpeakNpcId = 700301,
          Subtitle = "Thank goodness... It's still intact. Thank you, truly."
        },
        [51009654] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "내 친구 시그, 자넬 보러 왔어...",
          DialogueId = 51009654,
          FinalCamera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2835C",
          NextDialogue = 51009655,
          SpeakNpcId = 700301,
          Subtitle = "Sig... my old friend. I've come to see you...",
          ToFinalCameraBlendTime = 5
        },
        [51009655] = {
          ContentKR = "묘비...인가요?",
          DialogueId = 51009655,
          GUID = "7FB28386",
          NextDialogue = 51009656,
          SpeakNpcId = 100001,
          Subtitle = "Is this... a grave?"
        },
        [51009656] = {
          ContentKR = "아무리 봐도 형편없지?",
          DialogueId = 51009656,
          GUID = "7FB283B0",
          NextDialogue = 51009657,
          SpeakNpcId = 700301,
          Subtitle = "Doesn't look like much, does it?"
        },
        [51009657] = {
          Camera = "391.647461,354.068359,51.502441,0.000019,-5.200888,-159.003296,40.0,565.324158,false,Manual,2.8",
          ContentKR = "세상에 둘도 없는 친구라고 떠들고 다닌 주제에, 고작 이런 별 볼 일 없는 곳에 묻어 주다니 말이야.",
          DialogueId = 51009657,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB283DA",
          NextDialogue = 51009658,
          SpeakNpcId = 700301,
          Subtitle = "He called me his best mate... and this — this sorry little spot — is all I could manage for him.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009658] = {
          ContentKR = "잠깐, 이건... 아니, 이게 왜?",
          DialogueId = 51009658,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28404",
          NextDialogue = 51009659,
          SpeakNpcId = 700301,
          Subtitle = "Wait... is that—!? No... Why...?",
          TalkActionId = {
            [1] = "700301:Shock_Start"
          }
        },
        [51009659] = {
          ContentKR = "(병색이 짙던 남자의 얼굴에 핏대가 불거지며 표정이 굳는다. 경악과 당혹감, 그리고 슬픔이 뒤엉킨 채, 그의 시선은 묘비 옆에 덩그러니 놓여 있는 남보라색 리본에 머문다.)",
          DialogueId = 51009659,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2842E",
          NextDialogue = 51009660,
          Subtitle = "(The sick man's face — ashen moments ago — suddenly stiffens, veins standing taut beneath his skin, his eyes locked in shock and disbelief. Following his gaze, you spot it: a violet ribbon, lying untouched beside the gravestone.)"
        },
        [51009660] = {
          Camera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "바이올렛, 네가 왜... 돌아온 거야?",
          DialogueId = 51009660,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28458",
          NextDialogue = 51009661,
          SpeakNpcId = 700301,
          Subtitle = "Violet... why have you come back?",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700301)"
          }
        },
        [51009661] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "바이올렛이... 누구예요?",
          DialogueId = 51009661,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28482",
          NextDialogue = 51009662,
          SpeakNpcId = 100001,
          Subtitle = "Violet? Who's that?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "후... 젊은 친구, 해묵은 이야기지만, 들어 주겠나?",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          Subtitle = "Ah... would you humour an old man for a moment? I've a few old stories to tell.",
          TalkActionId = {
            [1] = "700301:Sigh_End",
            [2] = "100001:Talk02_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009663] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "네. 그래도 일단 돌아가서 이야기하죠. 라스가 애타게 기다릴 거예요.",
          DialogueId = 51009663,
          GUID = "7FB284D6",
          NextDialogue = 51009664,
          SpeakNpcId = 100001,
          Subtitle = "I'd love to. But let's head back first, alright? Lars must be worried sick."
        },
        [51009664] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇지, 그래... 일단 돌아가지.",
          DialogueId = 51009664,
          GUID = "7FB28500",
          SpeakNpcId = 700301,
          Subtitle = "Yes... yes, you're right. Let's go.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009665] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "도나트 아저씨! 돌아왔구나!",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat — you're back!",
          TurnTo = {
            [1] = "700303:n(700301)",
            [2] = "700301:n(700303)",
            [3] = "100001:n(700303)"
          }
        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "미안하다, 꼬마야. 많이 걱정했지... 콜록... 콜록콜록...",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          Subtitle = "Sorry, lad... made you worry again — *cough*",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아저씨, 또 기침하잖아! 내가 의사 선생님한테 데려다줄게.",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          Subtitle = "You're coughing again! Come on — let me take you to a doctor.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니, 괜찮아... 이건 내가 받아야 할 벌이라서, 의사도 고칠 수 없어.",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          Subtitle = "No, no need... This is what I deserve. No cure's going to fix it.",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아저씨, 왜 또 그런 말을 해...",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          Subtitle = "Don't say that, Uncle Donat...",
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          ContentKR = "기억 안 나? 엄청 추운 겨울날, 조금이라도 따뜻하게 있고 싶어서 공장 폐가스가 나오는 파이프 옆에 웅크리고 있었는데, 아저씨가 덜덜 떨면서도, 딱 하나 있던 두꺼운 솜옷을 나 입으라고 줬잖아.",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303,
          Subtitle = "Remember that winter, when I had to sleep next to the factory vents just to stay warm? You were freezing too — and still gave me the only padded coat you had."
        },
        [51009671] = {
          ContentKR = "아저씨가 좋은 사람이란 건 온 동네 사람이 다 알아! 그런데 왜 자꾸 '받아야 할 벌'이라는 이상한 소리를 하는 거야?",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303,
          Subtitle = "Everyone round here knows what a good person you are! So why do you keep saying you deserve this? It's just not true!"
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...혹시 저한테 해 주신다고 했던 '해묵은 이야기'랑 관련이 있는 건가요?",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          Subtitle = "...Does this have to do with the \"old stories\" you wanted to tell?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아. 그건 16년 전 일이었지...",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          Subtitle = "Mm. Sixteen years back...",
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "지루하기 짝이 없는 내 인생처럼, 광부로 일하던 시절은 좋지도, 나쁘지도 않았어. 매일 녹초가 될 만큼 일하면, 식구들이 배불리 먹을 빵을 구할 순 있었거든.",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301,
          Subtitle = "Like every other dreary chapter of my life, the years I spent as a miner weren't good, but they weren't the worst either. Long days of grind, just enough to wear you down, just enough to put bread on the table."
        },
        [51009675] = {
          ContentKR = "지금 생각해 보면, 높으신 분들은 한 번도 우리를 자기들과 같은 존재라고 여기지 않았지만, 오히려 그때가 내 인생에서 가장 속 편한 시절이었어...",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301,
          Subtitle = "Looking back... even though the bigwigs never treated us fairly, those might've been the least troubled days I ever had..."
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "하지만 내 친구 시그는 나만큼 운이 좋지 못했지. 병마가 그 친구의 유일한 가족인 여동생을 덮쳤거든. 가엾은 바이올렛은 겨우 열여덟이었는데 말이야.",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301,
          Subtitle = "But my friend Sig... he wasn't so lucky. His little sister, Violet — the only family he had — fell ill. Only eighteen, that girl..."
        },
        [51009677] = {
          ContentKR = "그런데 사람 일이라는 게, 바닥이라고 생각하면 더 깊은 나락이 있기 마련이더군.",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301,
          Subtitle = "And just when you think things can't get worse... they usually do."
        },
        [51009678] = {
          ContentKR = "글로스터 광산에서 나오는 월석이 날이 갈수록 줄어든 거야. 급여는 점점 쥐꼬리만 해져서, 밀빵이 호밀빵으로 바뀌고, 나중엔 호밀빵에 겨와 톱밥까지 섞여 나왔지.",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301,
          Subtitle = "Phoxene from Glevum Pit grew scarcer by the day — and so did our wages. White bread became dust-stained bread... then even that was bulked with husks and sawdust."
        },
        [51009679] = {
          ContentKR = "바이올렛의 병은, 급여로 간신히 입에 풀칠이나 하던 시그에겐, 가족이 사형 선고를 받은 거나 다름없었어.",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          Subtitle = "For Sig — barely making ends meet — Violet falling ill was like hearing her death sentence out loud.",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          ContentKR = "아직도 그날 새벽이 눈에 선해. 시그가 몸을 덥히려고 동료들에게 싸구려 독주를 잔뜩 얻어왔고, 우리는 글로스터 광산 앞 바위에 걸터앉아 병나발을 불었지.",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          Subtitle = "I still remember that dawn. Sig scrounged up cheap liquor from the lads, and we sat on the stone outside the pit, knocking them back one bottle at a time.",
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          ContentKR = "그 친구는 여동생과 서로를 의지하며 살아온 날들을 추억하며, 꼴사납게 울었어. 바이올렛처럼 노래를 흥얼거리다가, 파브리스 러스포드를 저주하기도 했고.",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301,
          Subtitle = "He cried like a child, rambling on about how the two of them had always relied on each other. One moment he was softly humming her favourite songs... the next, muttering curses at Fabrice Ruthford through gritted teeth."
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "파브리스 러스포드가 누구예요?",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          Subtitle = "Who's that?",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "공학 연금원의 고위 간부야. 당시 글로스터 광산의 책임자였지.",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          Subtitle = "An officer at The Aeolipile, the one who ran Glevum Pit back then.",
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          ContentKR = "난 그런 시그의 어깨를 두드리며 말했어. \"다 우리가 못나서 그런 건데, 그 사람 욕한다고 뭐가 달라지겠어. 능력 있으면 차라리 그 녀석을 납치해서, 한몫 크게 챙기면 되잖아?\"라고.",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          Subtitle = "I remember clapping him on the shoulder and saying, \"What good does cursing him do? We're just nobodies. If you've got guts, why not grab the man himself and get the money straight from his pocket?\"",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          ContentKR = "...지난 16년 동안, 늘 스스로에게 되물었어. 그날 내가 술을 조금만 덜 마셨더라면, 그런 경솔한 소리를 내뱉지 않았다면, 그런 비극은 일어나지 않았을 텐데 하고 말이야.",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          Subtitle = "...Sixteen years on, I still ask myself — if I hadn't been drunk and mouthing off like that, would any of this have happened?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "설마, 그 시그라는 아저씨가 진짜...",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          Subtitle = "You mean... Sig actually did it?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아. 어느 날, 시그는 갑자기 광산 일을 그만뒀어. 내가 그 친구 집에 찾아갔을 땐, 바이올렛과 함께 어딘가로 사라져 버린 뒤였고.",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          Subtitle = "Yes. One day, he quit the mine without a word. When I went to his house to check on him, both he and Violet were gone.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          ContentKR = "처음엔 바이올렛이 다른 곳에서 치료를 받게 해주려고 같이 아이스레이크 시티를 떠났나 보다 했는데... 일주일 뒤에 바이올렛이 편지를 하나 보냈더군.",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301,
          Subtitle = "I thought he'd taken her elsewhere for treatment... until a week later, I received a letter from Violet."
        },
        [51009689] = {
          ContentKR = "난 시그하곤 형제처럼 지냈지만, 그 친구 동생은 얼굴도 거의 본 적 없었어. 바이올렛은 거의 늘 몸져누워 있었거든. 그런 바이올렛이 가진 돈을 긁어모아, 지나가는 월석 사냥꾼 편에 편지를 보낸 거야.",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301,
          Subtitle = "Sig and I were close back then, but I hardly knew his sister. She was always bedridden. She spent her last coins getting that letter delivered to the mine via a passing Phoxhunter."
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그 편지엔, 시그가 연금원 간부 딸을 납치해서 몸값을 받아 내려고 한다는 내용과 함께, 오빠가 더는 잘못을 저지르지 않게 막아 달라는 부탁이 적혀 있었지.",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301,
          Subtitle = "She said Sig had kidnapped Officer Ruthford's daughter, demanding ransom. She begged me to stop him before it was too late."
        },
        [51009691] = {
          ContentKR = "시그는 여자애를 교외의 한 허름한 집에 가둬 두고 있었어. 내가 찾아가니까 소스라치게 놀라더군. 금세 자기 짓인 걸 인정했지만 말이야.",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301,
          Subtitle = "He was holding the girl in an old house on the outskirts. When I found him, he was stunned... but he owned up to it."
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "난 이 모든 게 내가 그날 밤 생각 없이 내뱉은 말 때문이란 사실을 깨닫고, 뼈저리게 후회했어. 시그를 말리려고 했지만, 말도 제대로 못 할 만큼 쇠약해진 바이올렛을 보니 차마 입이 안 떨어지더군...",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301,
          Subtitle = "My drunken rant that night opened a door to a nightmare. I was consumed by regret. I wanted to stop him — I truly did... but when I saw Violet, so frail she could barely speak... I hesitated."
        },
        [51009693] = {
          ContentKR = "시그는 그냥 모르는 척해달라고 했지만, 수사망이 점점 좁혀오자 그 일이 자꾸 떠올랐고, 두려움에 온몸이 떨렸어.",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301,
          Subtitle = "He begged me to pretend nothing had happened. But the investigation was tightening... and the fear... it shook me to my bones."
        },
        [51009694] = {
          ContentKR = "그래서... 결국...",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301,
          Subtitle = "In the end... I—"
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "신고해... 버린 거예요?",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          Subtitle = "You... turned them in?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러는 게 아니었어! 그러지 말았어야 했다고!",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          Subtitle = "I shouldn't have... I never should have!",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래서? 그 사람들은 어떻게 됐는데?",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          Subtitle = "What happened after that?",
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "군단 책임자가 직접 사람들을 데리고 시그를 잡으러 왔고, 그 친구는 저항하다가 실수로 집에 불을 질렀어.",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          Subtitle = "The officer came himself, leading the arrest. During the struggle, Sig accidentally set the house on fire.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          ContentKR = "난 사람을 구하겠다는 생각으로 불길에 뛰어들었지만, 결국 구해낸 건 바이올렛 하나였지. 그 아이는 겁에 질려 있었어. 새카만 재로 뒤덮인 얼굴 위엔 하염없이 흐른 눈물 자국만 선명했지.",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301,
          Subtitle = "I rushed in, trying to save them — but in the chaos, I only managed to get Violet out. Her face was black with soot... only her tears had carved two pale trails down her cheeks."
        },
        [51009700] = {
          ContentKR = "난 바이올렛이 이 일에 엮일까 봐, 군단 녀석들에게 들키지 않게 그 아이를 물통 안에 숨겼어.",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301,
          Subtitle = "I was terrified she'd be punished for her brother's crime. So I hid her in a water barrel, hoping the Legion wouldn't find her."
        },
        [51009701] = {
          ContentKR = "결국, 시그는 군단에 붙잡혔고, 간부의 딸은... 폐허 속에서 새까맣게 타 버린 시신으로 발견됐지.",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301,
          Subtitle = "In the end, Sig was caught. And the officer's daughter... all they found was her charred remains in the rubble."
        },
        [51009702] = {
          ContentKR = "그 후, 분노한 연금원 간부는 재판 절차도 건너뛰고 직접 시그를 처형해 버렸어. 그리고 바이올렛은... 내가 받은 포상금을 전부 쥐여 주고, 어수선한 틈을 타 몰래 아이스레이크 시티 밖으로 내보냈지. 부디 이 일에 엮이지 않길 바라면서 말이야...",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301,
          Subtitle = "The officer was enraged. He didn't even wait for a trial — he executed Sig with his own hands. As for Violet... I gave her all the bounty money and smuggled her out of Icelake, praying she'd get away from all this."
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "바이올렛을 떠나보낼 때의 그 초췌하면서도 분노에 찬 표정이 아직도 눈에 선해. 그때 그 아이는 이 남보라색 리본을 하고 있었지...",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301,
          Subtitle = "I still remember her face when she left — worn thin by sickness, but her eyes were burning with fury. She was wearing this violet ribbon that day..."
        },
        [51009704] = {
          ContentKR = "바이올렛이 그러더군. 자기는 아이스레이크 시티를 영원히 떠날 거고, 두 번 다시 날 보고 싶지 않다고.",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301,
          Subtitle = "She said she'd leave Icelake for good. Said she never wanted to see me again."
        },
        [51009705] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞는 말이지... 입을 잘못 놀려 친구를 위험한 길로 내몰더니, 나중엔 겁 조금 난다고 두 목숨을 앗아가게 만든 겁쟁이를 누가 보고 싶겠어?",
          DialogueId = 51009705,
          FinalCamera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28BBA",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextOptions = {
            [1] = 510095461,
            [2] = 510095462
          },
          SpeakNpcId = 700301,
          Subtitle = "And who could blame her? I was the drunk who doomed a friend and the coward whose fear cost two innocent lives. Why would anyone want to see me again?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009706] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "백번 천번 맞는 말이야.",
          DialogueId = 51009706,
          GUID = "7FB28BE4",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          Subtitle = "You're right.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009707] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아, 도나트 아저씨! 아저씨는 해야 할 일을 했을 뿐인걸!",
          DialogueId = 51009707,
          GUID = "7FB28C0E",
          NextDialogue = 51009708,
          SpeakNpcId = 700303,
          Subtitle = "Yeah! You just did what you thought was right, Uncle Donat!",
          TalkActionId = {
            [1] = "700303:Angry01_Start"
          }
        },
        [51009708] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "많은 사람이 그렇게 이야기해 줬지만... 나 때문에 무고한 두 생명이 스러졌단 사실은 변하지 않아.",
          DialogueId = 51009708,
          GUID = "7FB28C38",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          Subtitle = "That's what they all say. But it doesn't change the fact that two innocent lives were gone because of me.",
          TalkActionId = {
            [1] = "700301:Disagree",
            [2] = "700303:Angry01_End"
          }
        },
        [51009709] = {
          ContentKR = "난 큰 병을 앓았고, 그때부터 끊임없이 선행을 베풀고 남을 돕기 시작했어. 좋은 일을 하나 할 때마다, 과거에 저지른 죄업을 조금이나마 만회하길 바라면서.",
          DialogueId = 51009709,
          GUID = "7FB28C62",
          NextDialogue = 51009710,
          SpeakNpcId = 700301,
          Subtitle = "After that, I got really sick. Then I started doing what I could to help others, trying to make things right. I thought... maybe each good deed could chip away at my sins.",
          TalkActionId = {
            [1] = "700301:Explain01_Start"
          }
        },
        [51009710] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇지만 늘 시그가 분노에 찬 눈으로 날 노려보는 꿈을 꾸곤 해. 그리고, 그 가엾은 소녀 엘로라도 불길 속에서 무력하게 울부짖지. 산 사람에게 아무리 잘해도, 죽은 자는 널 용서하지 않는다면서 말이야.",
          DialogueId = 51009710,
          GUID = "7FB28C8C",
          NextDialogue = 51009711,
          SpeakNpcId = 700301,
          Subtitle = "But still... I see Sig in my dreams, glaring at me in rage. I hear poor Enola screaming as the fire takes her. They say no kindness to the living will ever buy forgiveness from the dead."
        },
        [51009711] = {
          ContentKR = "아... 바이올렛, 그래서 아이스레이크 시티로 돌아온 거니? 너도 나처럼, 이 죄인 도나트를 도저히 용서할 수 없었던 거지?",
          DialogueId = 51009711,
          GUID = "7FB28CB6",
          NextDialogue = 51009712,
          SpeakNpcId = 700301,
          Subtitle = "Violet... is that why you came back to Icelake? Because you still can't forgive me... just like I never could?",
          TalkActionId = {
            [1] = "700301:Disagree"
          }
        },
        [51009712] = {
          ContentKR = "날 이 고통에서 해방시켜 주러 온 거야? 바이올렛...",
          DialogueId = 51009712,
          GUID = "7FB28CE0",
          SpeakNpcId = 700301,
          Subtitle = "Have you come to put me out of my misery...?",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009713] = {
          ContentKR = "(목소리가 점점 작아지더니, 이윽고 도나트 씨가 바닥에 쓰러진다.)",
          DialogueId = 51009713,
          GUID = "7FB28D0A",
          Subtitle = "(His voice trails off. He collapses.)"
        },
        [51009714] = {
          Camera = "564.476807,-378.041016,169.732422,0.00009,-13.999387,141.803299,30.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아저씨? 도나트 아저씨?!",
          DialogueId = 51009714,
          GUID = "7FB28D34",
          NextDialogue = 51009715,
          Scripts = [[
PARA{
SEQ{
TurnTo{TurnToDescription{"700303:n(700301)"}},
PlayAnimation{ActorId{700303},AnimationId{"Angry01_Start"},Duration{1}}
},
SEQ{
TurnTo{TurnToDescription{"100001:n(700301)"}},
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}}
}
}]],
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat!? Are you alright!?",
          TalkActionId = {
            [1] = "700301:Onground02"
          }
        },
        [51009715] = {
          ContentKR = "후... 괜찮아. 몸도 약하신데 너무 긴장해서 기절하신 것 같아. 앞으론 아저씨가 함부로 돌아다니시지 못하게, 네가 잘 지켜봐 줘.",
          DialogueId = 51009715,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB28D5E",
          LookAt = {
            [1] = "700303:n(100001)"
          },
          NextDialogue = 51009716,
          SpeakNpcId = 100001,
          Subtitle = "Whew... he's fine. Looks like he just fainted from exhaustion and stress. Keep an eye on him — don't let him wander off again.",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700303:Angry01_End"
          }
        },
        [51009716] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "응, 내가 다른 사람들한테도 얘기해서 도나트 아저씨 잘 챙길게.",
          DialogueId = 51009716,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28D88",
          NextDialogue = 51009717,
          SpeakNpcId = 700303,
          Subtitle = "Mm. I'll get the others — we'll take care of him together.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          },
          TurnTo = {
            [1] = "100001:n(700303)"
          }
        },
        [51009717] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "있잖아, {性别:형|누나}...",
          DialogueId = 51009717,
          GUID = "7FB28DB2",
          NextDialogue = 51009718,
          SpeakNpcId = 700303,
          Subtitle = "Um... can I ask you something, {性别:sir|miss}?",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          },
          TurnTo = {
            [1] = "700303:n(100001)"
          }
        },
        [51009718] = {
          Camera = "-204.549316,-144.984375,111.20166,0.000049,-3.59994,24.790976,40.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "왜?",
          DialogueId = 51009718,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28DDC",
          NextDialogue = 51009719,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009719] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "도나트 아저씨는... 진짜 나쁜 사람이야?",
          DialogueId = 51009719,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28E06",
          NextOptions = {
            [1] = 510096291,
            [2] = 510096292,
            [3] = 510096293,
            [4] = 510096294
          },
          SpeakNpcId = 700303,
          Subtitle = "Do you think... Uncle Donat is a bad person?",
          TalkActionId = {
            [1] = "700303:Explain02_Start"
          }
        },
        [51009720] = {
          Camera = "174.810547,-35.033203,84.850098,0.000033,-4.400117,168.992874,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{性别:형|누나} 생각은 그렇구나... 알겠어. 고마워. 이거 내가 엄청 오래 모은 건데, 보수로 줄게!",
          DialogueId = 51009720,
          GUID = "7FB28E30",
          NextDialogue = 51009721,
          SpeakNpcId = 700303,
          Subtitle = "So that's what you think... I see. Thank you, {性别:sir|miss}! This is for you — I saved it up for a long time!",
          TalkActionId = {
            [1] = "700303:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51009721] = {
          Camera = "34.74585,-46.004883,96.84375,0.000042,-1.400134,16.193537,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(그 남보라색 리본은... 아마 바이올렛이 시그의 묘비 앞에 놔둔 걸 거야.)",
          DialogueId = 51009721,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28E5A",
          NextDialogue = 51009722,
          SpeakNpcId = 100001,
          Subtitle = "(That violet ribbon... it must've been left by Violet at Sig's grave.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009722] = {
          ContentKR = "(그때 18살이었으면 이제 중년이 됐겠지. 지금 아이스레이크 시티에 있으려나? 나중에 시간 날 때 알아봐야겠다...)",
          DialogueId = 51009722,
          GUID = "7FB28E84",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 100001,
          Subtitle = "(Sixteen years... she'd be in her thirties by now. Has she really returned? Maybe I should ask around when I get the chance.)"
        },
        [51009723] = {
          Camera = "-1245.721924,-374.627869,402.247803,-8.001631,-17.80077,20.798534,23.337744,100000.0,false,DoNotOverride,2.8",
          ContentKR = "잠 못 이루네... 잠 못 이루네!",
          DialogueId = 51009723,
          FinalCamera = "-1026.618896,-291.636963,327.767822,-8.001973,-14.000665,19.198555,23.337744,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28EAE",
          NextDialogue = 51009724,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023200"}},
PlayFacial{ActorId{100001},FacialId{"Angry01"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Another restless night... no peace for the weary!",
          ToFinalCameraBlendTime = 3
        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentKR = "가엾은 이여, 그대도 나와 같나요? 차가운 복도에서, 사랑과 희망으로 빛나는 저 별을 애타게 바라보나요...",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O, wretched soul — do you too wander these icy halls, chasing the distant gleam, yearning for love and a starlit dream?"
        },
        [51009725] = {
          ContentKR = "(길모퉁이에서 노랫소리가 들려오는데, 둘러봐도 노래하는 사람은 보이지 않는다. 주변을 좀 더 살펴볼까?)",
          DialogueId = 51009725,
          GUID = "7FB28F02",
          Subtitle = "(From a quiet street corner, you hear a melodic voice — but there's no one in sight. Should you keep looking?)"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentKR = "끽... 끽끽...",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Da... Da da...",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          ContentKR = "뭐야? 거기 누구 있어?",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001,
          Subtitle = "Who's there!?"
        },
        [51009728] = {
          ContentKR = "어머, 미안해요. 저 때문에 놀랐군요? 전 여기 있어요. 앞으로 다섯 걸음만 더요. 그래요, 바로 여기예요.",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh — pardon me. I didn't mean to startle you. I'm right here — five steps ahead. Yes, just here.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentKR = "좋은 밤이에요, 잠 못 이루는 친구.",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023201"}},
TurnTo{TurnToDescription{"100001:n(700309)"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A good evening to you, sleepless one."
        },
        [51009730] = {
          ContentKR = "착각 아니에요. 당신은 지금 저하고 대화를 나누고 있답니다.",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "It's not just you. I really am talking."
        },
        [51009731] = {
          ContentKR = "왜 누가 꼭 숨어 있어야 하나요? 그냥 말하는 상자일 수도 있잖아요?",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "Must there be someone hiding inside? Can't a crate simply... talk?"
        },
        [51009732] = {
          ContentKR = "미안하지만, 전 평범한 상자라 그런 힘은 없어요.",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "Sorry — I'm just a plain old crate. I don't grant wishes."
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그런데 상자가 어떻게 말을 하는 거야?",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          Subtitle = "But... how can a crate talk?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그거라면... 상자가 노래하는 게 어려울 것 같아요? 아니면 말하는 게 더 어려울 것 같아요?",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309,
          Subtitle = "If you must ask — tell me this: what's harder, singing or speaking?"
        },
        [51009735] = {
          ContentKR = "노래하는 거.",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001,
          Subtitle = "Singing, I suppose."
        },
        [51009736] = {
          ContentKR = "하지만 노래하는 상자는 이미 있잖아요. 태엽만 몇 번 감아주면 노래가 나오는걸요. 말하는 건 노래보다 훨씬 쉽고, 게다가 전 오르골보다 더 크고 대단하니까...",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309,
          Subtitle = "Little music boxes can sing — simply wind a key and out comes a melody. Since speaking's easier than singing, and I'm larger and better made than any music box..."
        },
        [51009737] = {
          ContentKR = "제가 당신하고 이렇게 대화를 나눌 수 있는 거죠. 당신이 지금 저하고 이야기를 나누고 있는 것처럼요.",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          Subtitle = "Why shouldn't I be able to talk to you, just as you're talking to me?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentKR = "그래도...",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          Subtitle = "But...",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentKR = "알아요, 의심스러운 거.",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309,
          Subtitle = "I understand — you're confused."
        },
        [51009740] = {
          ContentKR = "옹이구멍처럼 메아리나 울려 퍼지면 모를까, 상자가 말할 리 없다고 생각하는 거죠. 그렇지만 솔직히 말해서, 말하는 상자를 마다할 사람이 있나요?",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309,
          Subtitle = "People think crates shouldn't talk — like hollow trees, only echoing back your voice. But be honest with yourself: wouldn't you want a crate that actually answers?"
        },
        [51009741] = {
          ContentKR = "당신이 바로 절 열어 보지 않은 것도, 내심 상자가 말을 걸어 줬으면 하는 마음이 있어서 아닐까요?",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          Subtitle = "You didn't pry me open straight away. That means... part of you wanted me to speak, didn't it?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentKR = "제 설명을 납득하신 것 같네요. 그러면 같이 이야기 좀 나눠주실래요?",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          Subtitle = "Seems like you've come to terms with it. So — will you stay a while and talk?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "무슨 얘기를 하고 싶은데?",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          Subtitle = "What do you want to talk about?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentKR = "음, 어디 보자... 이틀 전에 아이스레이크 시티 오페라 극장에서 했던 공연 얘기는 어때요?",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          Subtitle = "Hmm... how about the opera at the Galea Theatre, two nights ago?",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          ContentKR = "〈푸치니〉라는 공연인데, 혹시 보셨나요? 여자 주인공은 노래를 잘하던가요?",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309,
          Subtitle = "It was called Putini. Did you see it? What did you think of the lead's voice?"
        },
        [51009747] = {
          ContentKR = "아시다시피 전 상자라서, 극장에 공연을 보러 갈 수가 없거든요.",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309,
          Subtitle = "I'm just a crate, after all. I can't go to the theatre."
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "미안, 본 적 없어.",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I didn't see it.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentKR = "괜찮아요. 비난하는 게 아니라요, 나중에 기회가 되면 한번 보세요. 아주 좋은 공연이거든요. 푸치니라는 주인공은 아름답고, 선하고... 자유를 좇는 용기도 지녔어요.",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309,
          Subtitle = "That's all right. No one's blaming you. But you should see it someday — it's a beautiful piece. The heroine, Putini — she's radiant, kind... and brave enough to chase her freedom."
        },
        [51009750] = {
          ContentKR = "저도 그런 사람이 되고 싶지만, 전 일개 나무 상자일 뿐이죠.",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309,
          Subtitle = "I want to be like her. But I'm just a crate."
        },
        [51009751] = {
          ContentKR = "그래서 전 결심했답니다.",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309,
          Subtitle = "So, I made a decision."
        },
        [51009752] = {
          ContentKR = "어떤 결심을 했는데?",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentKR = "먼바다로 떠나고 싶어요. 상자라고 해서 길모퉁이에 쌓여 있어야만 하는 건 아니잖아요. 배가 돼서 해류를 따라 정처 없이 떠돌 수도 있어요... 전 바닷물을 느끼고 싶어요. 모래알이 섞인 바람도요.",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          Subtitle = "I want to set sail. Who says crates must stay on street corners? A crate could become a boat, drifting on the tide... I want to feel the sea wind — rough with salt and sand.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentKR = "하지만 여길 떠난다는 건, 지금 제가 가진 모든 걸 잃는다는 뜻이기도 해요.",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309,
          Subtitle = "But leaving here means losing everything I have."
        },
        [51009755] = {
          ContentKR = "새장 밖으로 나간다는 건, 보금자리를 잃는다는 의미예요. 자유를 얻는다는 건, 알 수 없는 위험을 감수해야 한다는 거고요.",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309,
          Subtitle = "To leave the cage... is to leave the shelter. And freedom — well, that means stepping into the unknown."
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentKR = "친구로서 조언해 주세요. 전 어떻게 해야 할까요?",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309,
          Subtitle = "So tell me, my friend... what do you think I should do?"
        },
        [51009757] = {
          ContentKR = "...그건 그렇네요.",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309,
          Subtitle = "...You're right."
        },
        [51009758] = {
          ContentKR = "상자의 이야기에 어울려 줘서 고마워요. 이제 곧 날이 밝을 거예요. 이 낡은 나무의 마법도 사라져 버리겠죠.",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309,
          Subtitle = "Thank you for keeping a lonely crate company, kind soul. Dawn is close... and with it, the magic in these old timbers begins to fade."
        },
        [51009759] = {
          ContentKR = "앞으로 잠 못 드는 밤마다... 아니, 매일 밤 달콤한 꿈을 꾸시길 바랄게요.",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309,
          Subtitle = "May every sleepless night you face... no — may all your nights be filled with peaceful dreams."
        },
        [51009760] = {
          ContentKR = "(상자 뒤에 숨었던 작은 요정이 동트기 전에 아이의 머리맡을 몰래 빠져나가는 것처럼, 미약한 진동이 느껴졌다.\n정신을 차리자, 상자 아가씨는 이미 떠나고 없었다.)",
          DialogueId = 51009760,
          GUID = "7FB294C0",
          Subtitle = "(You hear a faint tremble — like a pixie slipping from a child's bedside just before dawn.)\n(And when you come back to your senses, Miss Crate is gone.)"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(상자 속에서 났던 그 목소리... 나도 모르게 그 페이스에 말려들고 말았어.)",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          Subtitle = "(What just happened...? That voice in the crate somehow steered the whole conversation.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(어떤 집 꼬마가 장난치는 걸지도 모르니까, 그냥 내버려둘 순 없어. 주변 사람들한테 물어봐야겠다.)",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001,
          Subtitle = "(It's probably some local kid messing around... but I can't just leave it. I should ask around.)"
        },
        [51009763] = {
          ContentKR = "실례지만... 누구지? 아까부터 계속 우리 집 근처를 어슬렁거리던데.",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Excuse me... who are you? You've been hanging around my place for a while."
        },
        [51009764] = {
          ContentKR = "의뢰할 거라도 있어? 사람 찾기? 재료 수집? 다른 의뢰라고 안 받는 건 아니지만, 합법적인 거라야 해.",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Looking to hire someone? I take all kinds of commissions — tracking, foraging, courier work — so long as it's legal."
        },
        [51009765] = {
          ContentKR = "의뢰요?",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001,
          Subtitle = "Commission?"
        },
        [51009766] = {
          ContentKR = "응? 의뢰하러 온 게 아니었어?",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Huh? So you're not here to hire me?"
        },
        [51009767] = {
          ContentKR = "흠, '월석 사냥꾼 지젤'이라는 이름이 카밀라 말처럼 유명하지는 않은 모양이군.",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302,
          Subtitle = "Alright. I guess Camilla oversold it — \"Giselle the Phoxhunter\" isn't exactly a household name."
        },
        [51009768] = {
          ContentKR = "월석 사냥꾼 지젤... 그러고 보니 들어본 것 같기도 해요.",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001,
          Subtitle = "Giselle the Phoxhunter... yeah, that does sound familiar."
        },
        [51009769] = {
          ContentKR = "내 기분 맞춰 주려고 굳이 그렇게 말할 필요 없어.",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302,
          Subtitle = "Thanks, but you don't have to say that just to make me feel better."
        },
        [51009770] = {
          ContentKR = "그게 아니라요... 사실은...",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001,
          Subtitle = "No no, I mean it—"
        },
        [51009771] = {
          ContentKR = "(지젤에게 그녀의 집 뒤편에 있던 상자에 대해 설명해 준다.)",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772,
          Subtitle = "(You tell Giselle about the talking crate behind her house.)"
        },
        [51009772] = {
          ContentKR = "네 말은, 우리 집 뒤에 있던 나무 상자가 말을 걸더니, 오페라를 보라고 추천했다는 거야? 음, 알겠어.",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302,
          Subtitle = "So— a crate behind my house struck up a conversation and suggested you watch an opera. Got it."
        },
        [51009773] = {
          ContentKR = "......",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51009774] = {
          ContentKR = "제가 생각했던 거랑 반응이 좀 다르시네요?",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001,
          Subtitle = "That's... not quite the reaction I was expecting."
        },
        [51009775] = {
          ContentKR = "그런가? 내 성격이 원래 좀 이래. 꼬마가 장난으로 상자에 숨어서 말을 걸었든, 아니면 정말 상자가 말을 했든, 난 다 가능하다고 생각하거든.",
