        [51010036] = {
          ContentKR = "아냐, 너처럼 말이 잘 통하는 사람한테까지 비밀로 하는 것도 좀 그렇지.",
          DialogueId = 51010036,
          GUID = "7FB2C208",
          NextDialogue = 51010037,
          SpeakNpcId = 700302,
          Subtitle = "...Okay. No point playing coy with someone as sincere and kind as you.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51010037] = {
          ContentKR = "본인에게 이미 들었겠지만, 시그가 납치범이라고 신고한 건 도나트였어. 그리고 그때 그 신고를 접수한 게 바로 나였고.",
          DialogueId = 51010037,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2C232",
          NextDialogue = 51010038,
          SpeakNpcId = 700302,
          Subtitle = "Donat told you he turned Sig in, right? The person he came to... was me."
        },
        [51010038] = {
          ContentKR = "원래 난 혼자 조용히 시그랑 협상해서 인질을 구출할 계획이었어. 섣불리 움직였다간 녀석을 자극할 수도 있잖아... 그런데 피해자가 연금원 간부 딸이니까, 망설이다가 결국엔 보고를 올린 거야.",
          DialogueId = 51010038,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2C25C",
          NextDialogue = 51010039,
          SpeakNpcId = 700302,
          Subtitle = "At first, to avoid tipping off the culprit, I planned to go in alone, talk Sig down, and get the hostage out safely. But when I realised who she was — my superior's daughter — I hesitated. Ended up reporting it up the chain instead."
        },
        [51010039] = {
          ContentKR = "뒷이야기는 네가 아는 대로야. 엘로라... 비올레타의 아버지는 길길이 날뛰며 내 계획을 묵살했고, 대규모 병력을 동원해 그 집을 포위해 버렸어.",
          DialogueId = 51010039,
          GUID = "7FB2C286",
          NextDialogue = 51010040,
          SpeakNpcId = 700302,
          Subtitle = "And... you know the rest. Her father lost it, rejected my proposal, and launched a full-on raid."
        },
        [51010040] = {
          ContentKR = "그때 내가 조금 더 고집을 부렸더라면, 이 모든 일은 일어나지 않았을지도 몰라.",
          DialogueId = 51010040,
          GUID = "7FB2C2B0",
          NextDialogue = 51010041,
          SpeakNpcId = 700302,
          Subtitle = "If I'd just stuck to my plan... maybe none of this would've happened."
        },
        [51010041] = {
          ContentKR = "비올레타에겐 미안한 말이지만, 적어도 시그가 누명을 쓰고 죽는 일은 없었겠지.",
          DialogueId = 51010041,
          GUID = "7FB2C2DA",
          NextDialogue = 51010042,
          SpeakNpcId = 700302,
          Subtitle = "It might've made things a bit harder for Violetta... but at least Sig wouldn't have died for something he didn't do."
        },
        [51010042] = {
          ContentKR = "지젤 씨...",
          DialogueId = 51010042,
          GUID = "7FB2C304",
          NextDialogue = 51010043,
          SpeakNpcId = 100001,
          Subtitle = "Giselle...",
          TalkActionId = {
            [1] = "700302:Talk02_End"
          }
        },
        [51010043] = {
          ContentKR = "그 사람 심정도... 이해는 가. 자기 딸이 하루아침에 사고로 죽었는데 가만히 있을 사람이 어디 있겠어. 하지만 조사가 다 끝나기도 전에 함부로 결론 내리는 건 인정할 수 없었어.",
          DialogueId = 51010043,
          GUID = "7FB2C32E",
          NextDialogue = 51010044,
          SpeakNpcId = 700302,
          Subtitle = "I get why he did it — any parent who lost their child would. But justice should come after the full truth comes to light, not before.",
          TalkActionId = {
            [1] = "700302:Sigh_Start"
          }
        },
        [51010044] = {
          ContentKR = "난 그러려고 방위대에 들어간 게 아니었으니까.",
          DialogueId = 51010044,
          GUID = "7FB2C358",
          NextDialogue = 51010045,
          SpeakNpcId = 700302,
          Subtitle = "I didn't join the Escort for that."
        },
        [51010045] = {
          ContentKR = "지젤 씨처럼 정의감 넘치는 사람을 잃다니, 방위대 손해네요.",
          DialogueId = 51010045,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C382",
          NextDialogue = 51010046,
          SpeakNpcId = 100001,
          Subtitle = "Then the Escort was a fool to lose someone who actually stood for justice.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51010046] = {
          ContentKR = "그거, 칭찬이야?",
          DialogueId = 51010046,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C3AC",
          NextDialogue = 51010047,
          SpeakNpcId = 700302,
          Subtitle = "Was that a compliment?",
          TalkActionId = {
            [1] = "700302:Sigh_End"
          }
        },
        [51010047] = {
          ContentKR = "어쨌든 이젠 다 지난 일이고 사건도 해결됐으니, 이젠 납치 방화 사건의 진상을 일부라도 공개할 방법을 찾아볼까 해... 물론, 비올레타의 정체는 철저히 비밀로 해야겠지만.",
          DialogueId = 51010047,
          GUID = "7FB2C3D6",
          NextDialogue = 51010048,
          SpeakNpcId = 700302,
          Subtitle = "Anyway, what's done is done. I'll see if I can reveal part of the truth — without exposing Violetta, of course.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51010048] = {
          ContentKR = "당사자인 엘로라 본인이 없는 이상, 방위대가 재수사에 나서게 만들 증거는 부족하지 않나요?",
          DialogueId = 51010048,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C400",
          NextDialogue = 51010049,
          SpeakNpcId = 100001,
          Subtitle = "But without Enola herself, there's no solid proof. The Escort wouldn't reopen a case over just hearsay.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010049] = {
          ContentKR = "방위대? 그럴 필요 없어. 신문사나 다른 단체에 정보를 흘릴 생각이야. 딱딱한 공문보다 입소문이 훨씬 효과적일 때도 있거든.",
          DialogueId = 51010049,
          GUID = "7FB2C42A",
          NextDialogue = 51010050,
          SpeakNpcId = 700302,
          Subtitle = "The Escort? Nah, I'm not going to them. I'll tell the local papers. Let the story spread. The public makes a better jury than some dusty court records.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010050] = {
          ContentKR = "그 방법이 정말 통할까요...?",
          DialogueId = 51010050,
          GUID = "7FB2C454",
          NextDialogue = 51010051,
          SpeakNpcId = 100001,
          Subtitle = "Will that really work...?"
        },
        [51010051] = {
          ContentKR = "사람들은 사건의 이면엔 숨겨진 진실이 있다고 믿고 싶어 하지. 그래야만 자기가 남들보다 똑똑하다고 느낄 수 있거든. 이번엔 그 심리를 역으로 이용해 볼 생각이야.",
          DialogueId = 51010051,
          GUID = "7FB2C47E",
          NextDialogue = 51010052,
          SpeakNpcId = 700302,
          Subtitle = "People love hidden truths. Believing they know more than others about what's beneath the surface makes them feel smart. I'm just going to take advantage of that."
        },
        [51010052] = {
          ContentKR = "...아야!",
          DialogueId = 51010052,
          GUID = "7FB2C4A8",
          IsBlack = 1,
          NextDialogue = 51010053,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint1_20023305"},MoveSpeed{250},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700305)"}},
LookAt{LookAtDescription{"700302:n(700305)"}},
TurnTo{TurnToDescription{"700305:n(100001)"}}
},
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{ActorId{700302},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{ActorId{700305},AnimationId{"Explain02_Start"},Duration{1}}
}}]],
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "...Whoops!"
        },
        [51010053] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "죄, 죄송해요! 앞을 못 봤어요! 혹시 다치신 덴 없으세요? 어디 불편한 덴 없으시고요?",
          DialogueId = 51010053,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2C4D2",
          NextDialogue = 51010054,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "S—Sorry! I didn't see you! Are you okay? Did I hurt you?"
        },
        [51010054] = {
          ContentKR = "난 괜찮아. 다음부턴 조심해.",
          DialogueId = 51010054,
          GUID = "7FB2C4FC",
          NextDialogue = 51010055,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just be more careful next time, alright?",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010055] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "으음...",
          DialogueId = 51010055,
          GUID = "7FB2C526",
          NextDialogue = 51010056,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Mm...",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010056] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "내 얼굴에 뭐 묻었어?",
          DialogueId = 51010056,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2C550",
          NextDialogue = 51010057,
          SpeakNpcId = 100001,
          Subtitle = "What? Something on my face?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010057] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아무것도 아니에요. 헤헤... 약초, 고마웠어요. 아! 약속 시간에 늦겠다!",
          DialogueId = 51010057,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2C57A",
          NextDialogue = 51010058,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Nope! Hehe... Thanks for the herbs! Oh no, I'm gonna be late!",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010058] = {
          ContentKR = "약초...? 잠깐, 이거 떨어뜨렸어!",
          DialogueId = 51010058,
          GUID = "7FB2C5A4",
          NextDialogue = 51010059,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint2_20023305"},MoveSpeed{250},Visibility{"Hide"}},
PlayAnimation{ActorId{100001},AnimationId{"Nvzhu_Story_StretchHand_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Herbs...? Wait— You dropped something!"
        },
        [51010059] = {
          ContentKR = "그거, 선물이니까 받아 줘요!",
          DialogueId = 51010059,
          GUID = "7FB2C5CE",
          NextDialogue = 51010060,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "You can keep it!!!"
        },
        [51010060] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "요즘 젊은 애들은 정말 에너지가 넘치네.",
          DialogueId = 51010060,
          GUID = "7FB2C5F8",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010061,
          SpeakNpcId = 700302,
          Subtitle = "Seriously. Kids these days — always a whirlwind.",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010061] = {
          ContentKR = "저한테 주는 선물이라는데... 여기 뭔가 수놓아져 있어요. 아까 그 소녀 이름일까요?",
          DialogueId = 51010061,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C622",
          NextDialogue = 51010062,
          SpeakNpcId = 100001,
          Subtitle = "Why'd she leave this...? Huh, there's embroidery — is this her name...?"
        },
        [51010062] = {
          ContentKR = "...푸치니?",
          DialogueId = 51010062,
          GUID = "7FB2C64C",
          NextDialogue = 51010063,
          SpeakNpcId = 100001,
          Subtitle = "...Putini?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010063] = {
          ContentKR = "나중에 푸치니라는 소녀를 만나게 된다면, 그게 저란 걸 알아봐 주세요. 저도 꼭 당신을 알아볼게요.",
          DialogueId = 51010063,
          GUID = "7FB2C676",
          IsBlack = 1,
          NextDialogue = 51010064,
          Subtitle = "If one day, you meet a girl named Putini... I hope you'll recognise me. And I promise — I'll recognise you."
        },
        [51010064] = {
          ContentKR = "뭐야? 왜 웃어?",
          DialogueId = 51010064,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "7FB2C6A0",
          NextDialogue = 51010065,
          SpeakNpcId = 700302,
          Subtitle = "What's so funny?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010065] = {
          ContentKR = "지젤 씨도 못 알아봤다니, 천의 얼굴을 가진 게 비올레타 씨 하나만은 아닌 모양이에요.",
          DialogueId = 51010065,
          GUID = "7FB2C6CA",
          NextDialogue = 51010066,
          SpeakNpcId = 100001,
          Subtitle = "If even you didn't recognise her... maybe Violetta's not the only one with a thousand faces.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010066] = {
          ContentKR = "인생은 1막짜리 연극이 아니니까, 우린 다른 무대에서 또 만나게 될 거야. 그때까지 즐거운 여행이 되길 바랄게, 상자 아가씨.",
          DialogueId = 51010066,
          GUID = "7FB2C6F4",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "Life's a play with more than one act. We'll meet again — on a new stage. Until then... safe travels, Miss Crate."
        },
        [51010067] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51010067,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2C71E",
          NextDialogue = 51010068,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51010068] = {
          ContentKR = "좋은 아침이야, {nickname}. 그런데 표정이 왜 그렇게 어두워?",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300,
          Subtitle = "Morning, . Why the gloomy face?"
        },
        [51010069] = {
          ContentKR = "비올레타 씨...",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta..."
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentKR = "괜찮으니까 거기까지만 해. 은퇴하는 건 난데, 오히려 네가 더 속상해하는 것 같네.",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          Subtitle = "Now, now — no need to feel sorry for me. I'm stepping down, not dying.",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentKR = "넌 소신을 지키는 사람이라면 누구나 했을 법한 선택을 한 것뿐이야. 괜한 부담 갖지 말고, 집 나간 꼬마 하나 잡아냈다고 생각하면 돼, 알겠지?",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300,
          Subtitle = "You simply did what anyone with a conscience would. Don't let it weigh on you. Think of it this way: you just helped a runaway find her way home, that's all."
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다 모인 것 같네?",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302,
          Subtitle = "Looks like everyone's here."
        },
        [51010073] = {
          ContentKR = "지젤 씨도 왔군요. 자, 두 사람 티켓이에요.",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          Subtitle = "Miss Giselle — perfect timing. Here are your tickets.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentKR = "잘 받을게. 방위대 친구들한테는 이미 말해 뒀으니까, 공연이 끝날 때까진 아무 일 없을 거야.",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          Subtitle = "Thanks. I've spoken to my old Escort contacts — they'll hold off until the curtain falls.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentKR = "정말 감사해요. 이제 곧 공연이 시작돼서, 먼저 실례할게요.",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          Subtitle = "Much appreciated. The show's about to start — I'd better get backstage.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentKR = "우리도 들어가자. 내가 원인 제공을 한 셈이지만, 비올레타의 고별 무대라니까 확실히 기대되긴 하네.",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302,
          Subtitle = "Let's head in too, then. I may have played a part in ending her stage career... but I've got to admit, I'm looking forward to her swan song."
        },
        [51010077] = {
          ContentKR = "네.",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001,
          Subtitle = "Let's."
        },
        [51010078] = {
          ContentKR = "비올레타 씨가 마련해 준 좌석에 앉아, 공연이 시작되기를 기다린다.",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079,
          Subtitle = "You find the seats Violetta reserved for you and settle in, waiting for the curtain to rise."
        },
        [51010079] = {
          ContentKR = "객석이 서서히 어둠에 잠기고, 한 여성의 힘찬 노랫소리가 기대와 호기심을 싣고 무대 막 뒤편부터 공연장 전체로 울려 퍼진다.",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080,
          Subtitle = "As the house lights dim, a powerful soprano unfurls from behind the curtain, flooding the theatre with wonder."
        },
        [51010080] = {
          ContentKR = "객석은 이상할 만큼 조용하고, 이런 분위기가 낯선 나는 왠지 마음이 살짝 불안해진다.",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081,
          Subtitle = "The audience holds its breath. The silence is so deep, it unsettles you."
        },
        [51010081] = {
          ContentKR = "멋진 장면이 나올 때마다 터져 나오는 감탄사를 삼키는 건 상당한 고역이다. 나도 모르게 튀어나온 소리가 다른 사람의 즐거움을 방해할까 봐 조마조마하다.",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082,
          Subtitle = "It's hard to hold back a gasp at the dazzling moments — you're almost afraid the sound of your spontaneous awe might spoil the magic."
        },
        [51010082] = {
          ContentKR = "하지만 그건 쓸데없는 걱정이었다...",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083,
          Subtitle = "But your worries melt away —"
        },
        [51010083] = {
          ContentKR = "오페라 속 인물들에게 완전히 몰입한 나는, 공연이 끝나는 순간까지 박수 치는 것도 잊고 말았으니까...",
          DialogueId = 51010083,
          GUID = "7FB2C9BE",
          Subtitle = "By the time the final note falls, you're so mesmerised, you've forgotten even to applaud."
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "지젤, 어떻게 된 건지 설명해 보게!",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Giselle — you owe me an explanation!",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentKR = "오호? 천하의 파브리스 나리께서 저 같은 사람한테 무슨 설명을 듣고 싶으신 걸까요?",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          Subtitle = "Oh? And what could the all-knowing Lord Ruthford possibly need me to explain?",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          ContentKR = "비올레타가 엘로라라고 신고한 게 자네잖나! 그런데 내가 사람들을 데리고 가 봤더니, 무대 뒤엔 개미 새끼 한 마리 없었네!",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304,
          Subtitle = "You told the Escort Violetta was Enola — but when I brought my men backstage, there was no one there!"
        },
        [51010087] = {
          ContentKR = "그 일이었군요... 직접 행차하실 줄 몰랐네요. 책임감이 어마어마하신걸요.",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302,
          Subtitle = "Ah, that. Didn't think you'd come in person. Very hands-on of you, sir."
        },
        [51010088] = {
          ContentKR = "비아냥거리지 말게! 이건 명령일세. 어서 날 엘로라가 있는 곳으로 안내해!",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304,
          Subtitle = "Don't get clever with me! Take me to Enola — now!"
        },
        [51010089] = {
          ContentKR = "잊으셨나 본데, 전 이젠 방위대 소속이 아니에요. 그건 당신도 마찬가지고요. 전 평범한 시민으로서 방위대에 정보를 제공한 것뿐이에요.",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302,
          Subtitle = "I think you're forgetting something — I'm not with the Escort anymore. And neither are you. I just passed on a tip... as a civilian."
        },
        [51010090] = {
          ContentKR = "그러니까 전 당신의 명령을 들을 이유가 없어요. 아, 차라리 '월석 사냥꾼 지젤'한테 정식으로 의뢰해 보시는 건 어때요?",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302,
          Subtitle = "So no, I don't take orders from you. But hey — you could always file a commission with Giselle the Phoxhunter."
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이게...! 까짓것, 좋아, 의뢰하지!",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          Subtitle = "Tch... Fine! Then I'll file one!",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentKR = "네, 그 의뢰 거절할게요.",
          DialogueId = 51010092,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CB38",
          NextDialogue = 51010093,
          SpeakNpcId = 700302,
          Subtitle = "Great. I refuse to take the job.",
          TalkActionId = {
            [1] = "700302:Talk01_Start"
          }
        },
        [51010093] = {
          ContentKR = "지금 날 우롱하는 건가?!",
          DialogueId = 51010093,
          GUID = "7FB2CB62",
          NextDialogue = 51010094,
          SpeakNpcId = 700304,
          Subtitle = "You messing with me!?"
        },
        [51010094] = {
          ContentKR = "전 지금 백작 영애를 납치했다는 혐의를 받고 있어서, 당분간은 월석 사냥꾼 일도 못 해요.",
          DialogueId = 51010094,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CB8C",
          NextDialogue = 51010095,
          SpeakNpcId = 700302,
          Subtitle = "Well, seeing as I'm currently a suspect in the kidnapping of an earl's daughter, let's just say my services are temporarily suspended."
        },
        [51010095] = {
          ContentKR = "그러니까, 애초에 제 조언대로 얌전히 협상만 하셨어도, 일이 이렇게까진 복잡해지진 않았을걸요.",
          DialogueId = 51010095,
          GUID = "7FB2CBB6",
          NextDialogue = 51010096,
          SpeakNpcId = 700302,
          Subtitle = "Truth is, if you'd listened back then and gone with the peaceful route I proposed, none of this would've happened."
        },
        [51010096] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "자네...! 내가 사람을 잘못 봐도 한참 잘못 봤군. 자네가 엘로라를 찾아낼 거라고 믿었다니.",
          DialogueId = 51010096,
          GUID = "7FB2CBE0",
          NextDialogue = 51010097,
          SpeakNpcId = 700304,
          Subtitle = "You... I was a fool to ever believe you'd find Enola.",
          TalkActionId = {
            [1] = "700302:Talk01_End"
          }
        },
        [51010097] = {
          ContentKR = "엘로라... 이 아비가 꼭 찾아내 주마... 자네! 앞으로 다시는 내 눈에 띄지 않는 게 좋을 걸세!",
          DialogueId = 51010097,
          GUID = "7FB2CC0A",
          NextDialogue = 51010098,
          SpeakNpcId = 700304,
          Subtitle = "Enola... my daughter... I'll find you myself. And you — don't ever show your face again!"
        },
        [51010098] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇다면 저야 환영이죠.",
          DialogueId = 51010098,
          GUID = "7FB2CC34",
          NextDialogue = 51010099,
          Scripts = "MoveTo{ActorId{700304},TargetPoint{\"FabricePoint_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700302,
          Subtitle = "Gladly.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010099] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentKR = "지젤 씨, 괜찮아요?",
          DialogueId = 51010099,
          FinalCamera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2CC5E",
          NextDialogue = 51010100,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},TargetPoint{"NvzhuPoint_20023305"},MoveSpeed{150},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700302)"}},
LookAt{LookAtDescription{"700302:n(100001)"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You alright, Giselle?",
          ToFinalCameraBlendTime = 5
        },
        [51010100] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "멀쩡해. 방위대에 있을 땐 아까처럼 쏘아붙일 기회가 없었는데, 속이 다 시원해.",
          DialogueId = 51010100,
          GUID = "7FB2CC88",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010101,
          SpeakNpcId = 700302,
          Subtitle = "Never better. Couldn't talk to him like that when I was in the Escort. Felt pretty darn good."
        },
        [51010101] = {
          ContentKR = "아까 그 사람은...",
          DialogueId = 51010101,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2CCB2",
          NextDialogue = 51010102,
          SpeakNpcId = 100001,
          Subtitle = "Who was that, anyway?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010102] = {
          ContentKR = "파브리스 러스포드야, 비올레타의 친아버지. 16년 전이나 지금이나 참을성 없는 건 여전하네.",
          DialogueId = 51010102,
          GUID = "7FB2CCDC",
          NextDialogue = 51010103,
          SpeakNpcId = 700302,
          Subtitle = "Fabrice Ruthford. Violetta's father. Still as hot-headed as he was sixteen years ago.",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010103] = {
          ContentKR = "비올레타 씨는요?",
          DialogueId = 51010103,
          GUID = "7FB2CD06",
          NextDialogue = 51010104,
          SpeakNpcId = 100001,
          Subtitle = "Then where's Ms Violetta?"
        },
        [51010104] = {
          ContentKR = "도망쳤어. 파브리스가 사람들을 데리고 들이닥쳤을 땐 이미 개미 새끼 한 마리 없었다더라.",
          DialogueId = 51010104,
          GUID = "7FB2CD30",
          NextDialogue = 51010105,
          SpeakNpcId = 700302,
          Subtitle = "Gone. Backstage was already empty by the time he barged in."
        },
        [51010105] = {
          ContentKR = "...아야!",
          DialogueId = 51010105,
          GUID = "7FB2CD5A",
          IsBlack = 1,
          NextDialogue = 51010106,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint1_20023305"},MoveSpeed{250},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700305)"}},
LookAt{LookAtDescription{"700302:n(700305)"}},
TurnTo{TurnToDescription{"700305:n(100001)"}}
},
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{ActorId{700302},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{ActorId{700305},AnimationId{"Explain02_Start"},Duration{1}}
}}]],
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "...Whoops!"
        },
        [51010106] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "죄, 죄송해요! 앞을 못 봤어요! 혹시 다치신 덴 없으세요? 어디 불편한 덴 없으시고요?",
          DialogueId = 51010106,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2CD84",
          NextDialogue = 51010107,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "S—Sorry! I didn't see you! Are you okay? Did I hurt you?"
        },
        [51010107] = {
          ContentKR = "난 괜찮아. 다음부턴 조심해.",
          DialogueId = 51010107,
          GUID = "7FB2CDAE",
          NextDialogue = 51010108,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just be more careful next time, alright?",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010108] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "으음...",
          DialogueId = 51010108,
          GUID = "7FB2CDD8",
          NextDialogue = 51010109,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Mm...",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010109] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "내 얼굴에 뭐 묻었어?",
          DialogueId = 51010109,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2CE02",
          NextDialogue = 51010110,
          SpeakNpcId = 100001,
          Subtitle = "What? Something on my face?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010110] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아무것도 아니에요. 헤헤... 약초, 고마웠어요.",
          DialogueId = 51010110,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2CE2C",
          NextDialogue = 51010111,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Nothing! Hehe... Thanks for the herbs!",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010111] = {
          ContentKR = "약속 시간에 늦겠다!",
          DialogueId = 51010111,
          GUID = "7FB2CE56",
          NextDialogue = 51010112,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Time's ticking. Hurry or you'll miss it."
        },
        [51010112] = {
          ContentKR = "앗, 죄송해요, 저 먼저 가 볼게요! ...잠깐만요, 지금 가요!",
          DialogueId = 51010112,
          GUID = "7FB2CE80",
          NextDialogue = 51010113,
          Scripts = "MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}}",
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Oh no... Sorry! I gotta go! I'm coming — wait for me!"
        },
        [51010113] = {
          ContentKR = "약초라니...? 잠깐, 이거 떨어뜨렸어!",
          DialogueId = 51010113,
          GUID = "7FB2CEAA",
          NextDialogue = 51010114,
          SpeakNpcId = 100001,
          Subtitle = "Herbs...? Wait — you dropped something!",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010114] = {
          ContentKR = "그거, 선물이니까 받아 줘요!",
          DialogueId = 51010114,
          GUID = "7FB2CED4",
          NextDialogue = 51010115,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "You can keep it!!!",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010115] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "요즘 젊은 애들은 정말 에너지가 넘치네.",
          DialogueId = 51010115,
          GUID = "7FB2CEFE",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010116,
          SpeakNpcId = 700302,
          Subtitle = "Seriously. Kids these days — always a whirlwind."
        },
        [51010116] = {
          ContentKR = "저한테 주는 선물이래요...",
          DialogueId = 51010116,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "700302:CM_Idle"
          },
          GUID = "7FB2CF28",
          NextDialogue = 51010117,
          SpeakNpcId = 100001,
          Subtitle = "Why'd she leave this...?"
        },
        [51010117] = {
          ContentKR = "용감한 나비가 고치를 벗고 하늘로 날갯짓하다, 마치 스토크 한 송이가 꽃밭에 스며들 듯 바람과 함께 자취를 감추는군요.",
          DialogueId = 51010117,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2CF52",
          NextDialogue = 51010118,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"ViolettePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A brave butterfly has broken free of her cocoon and taken wing. She's vanished into the wind — like a violet in a sea of blooms."
        },
        [51010118] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "한동안 다시 만나지 못할지도 몰라요... 그러니 그녀가 소중한 친구에게 남기는 이 작별 선물을 받아 주세요.",
          DialogueId = 51010118,
          GUID = "7FB2CF7C",
          LookAt = {
            [1] = "100001:n(700311)",
            [2] = "700302:n(700311)"
          },
          NextDialogue = 51010119,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "She may not return for some time. So take it — a parting gift, from someone who held you dear."
        },
        [51010119] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "작별 선물이라니... 여기 뭐가 수놓아져 있어요. 아까 그 소녀 이름일까요?",
          DialogueId = 51010119,
          GUID = "7FB2CFA6",
          NextDialogue = 51010120,
          SpeakNpcId = 100001,
          Subtitle = "A parting gift...? Hmm, there's embroidery on it... Is this her name?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010120] = {
          ContentKR = "...푸치니?",
          DialogueId = 51010120,
          GUID = "7FB2CFD0",
          NextDialogue = 51010121,
          SpeakNpcId = 100001,
          Subtitle = "...Putini?"
        },
        [51010121] = {
          ContentKR = "나중에 푸치니라는 소녀를 만나게 된다면, 그게 저란 걸 알아봐 주세요. 저도 꼭 당신을 알아볼게요.",
          DialogueId = 51010121,
          GUID = "7FB2CFFA",
          IsBlack = 1,
          NextDialogue = 51010122,
          Subtitle = "If one day, you meet a girl named Putini... I hope you'll recognise me. And I promise — I'll recognise you."
        },
        [51010122] = {
          ContentKR = "그랬군요. 상자 아가씨는 무사히 여행을 시작한 모양이네요. 그렇다면 당신은...",
          DialogueId = 51010122,
          GUID = "7FB2D024",
          NextDialogue = 51010123,
          SpeakNpcId = 100001,
          Subtitle = "Ah, I see. So Miss Crate made it out safe and sound. Which would make you—",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010123] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "쉿, 진실을 밝힌 건 인정해 줄게. 하지만 비밀을 지킬 줄 아는 아이가 더 사랑스러운 법이란다.",
          DialogueId = 51010123,
          GUID = "7FB2D04E",
          NextDialogue = 51010124,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Shhh — I respect your choice to reveal the truth, but those who know how to keep a secret are always the most charming.",
          TalkActionId = {
            [1] = "700311:Disagree"
          }
        },
        [51010124] = {
          ContentKR = "이렇게 대놓고 정체를 밝히다니, 내가 또 귀찮게 하면 어떻게 하려고?",
          DialogueId = 51010124,
          GUID = "7FB2D078",
          NextDialogue = 51010125,
          SpeakNpcId = 700302,
          Subtitle = "Aren't you afraid I'll come after you again?"
        },
        [51010125] = {
          ContentKR = "'비올레타'는 이제 무대에 서지 않겠지만, 난 당분간 여길 떠날 생각이 없어요. 내 학생과 관련된 일만큼은 외면할 수 없거든요. 당신이 날 또 고발하더라도 원망하지 않을게요.",
          DialogueId = 51010125,
          GUID = "7FB2D0A2",
          NextDialogue = 51010126,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "\"Violetta\" won't return to the stage — but I'm not quite ready to leave. Even if you turn me in again, I won't blame you. There's still another student I have to protect."
        },
        [51010126] = {
          ContentKR = "......",
          DialogueId = 51010126,
          GUID = "7FB2D0CC",
          NextDialogue = 51010127,
          SpeakNpcId = 700302,
          Subtitle = "..."
        },
        [51010127] = {
          ContentKR = "...모른 척 넘어가 줘서 고마워요.",
          DialogueId = 51010127,
          FacialId = {
            [1] = "700311:CM_Happy01"
          },
          GUID = "7FB2D0F6",
          NextDialogue = 51010128,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Thank you for your silence.",
          TalkActionId = {
            [1] = "700311:Agree"
          }
        },
        [51010128] = {
          ContentKR = "그러면 이만 실례할게요. 두 사람 모두 근사한 휴일을 즐기길 바랄게요.",
          DialogueId = 51010128,
          GUID = "7FB2D120",
          NextDialogue = 51010129,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Then I'll take my leave. Wishing you both a lovely evening."
        },
        [51010129] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "하하, 내가 이럴 줄 알았어. 저런 여자가 순순히 잡혀 줄 리가 없지.",
          DialogueId = 51010129,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D14A",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010130,
          SpeakNpcId = 700302,
          Subtitle = "Hah. Knew it. A woman like her was never going to let herself get caught that easily.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010130] = {
          ContentKR = "어쩐지 조금 즐거워 보이시네요?",
          DialogueId = 51010130,
          GUID = "7FB2D174",
          NextDialogue = 51010131,
          SpeakNpcId = 100001,
          Subtitle = "You seem... almost pleased.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010131] = {
          ContentKR = "그래? 솔직히 나도 많이 고민했어. 산 사람의 인생을 희생시키면서까지 죽은 사람의 결백을 밝히는 게 맞는 건가 싶어서...",
          DialogueId = 51010131,
          GUID = "7FB2D19E",
          NextDialogue = 51010132,
          SpeakNpcId = 700302,
          Subtitle = "Do I? To be honest, I wrestled with the choice — whether it was worth ruining a gifted woman's future just to clear a dead man's name...",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010132] = {
          ContentKR = "너도 봤겠지만, 난 선택을 했지. 그게 바로 이 지젤이라는 사람의 고집이야.",
          DialogueId = 51010132,
          GUID = "7FB2D1C8",
          NextDialogue = 51010133,
          SpeakNpcId = 700302,
          Subtitle = "But I made my choice. Stubborn as ever, I guess."
        },
        [51010133] = {
          ContentKR = "하지만 두 가지 선택지에서 벗어났다는 사실에 마음이 놓이는 걸 보면, 16년 동안 나도 꽤 성장했다는 거겠지?",
          DialogueId = 51010133,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2D1F2",
          NextDialogue = 51010134,
          SpeakNpcId = 700302,
          Subtitle = "Still... maybe being at peace with an open ending means I've grown."
        },
        [51010134] = {
          ContentKR = "16년 전의 내가 지금 같았다면, 아무도 죽지 않았을지 몰라.",
          DialogueId = 51010134,
          GUID = "7FB2D21C",
          NextDialogue = 51010135,
          SpeakNpcId = 700302,
          Subtitle = "If I'd understood that sixteen years ago... maybe no one would've had to die."
        },
        [51010135] = {
          ContentKR = "지젤 씨 잘못이 아니에요.",
          DialogueId = 51010135,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2D246",
          NextDialogue = 51010136,
          SpeakNpcId = 100001,
          Subtitle = "It wasn't your fault, Giselle.",
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51010136] = {
          ContentKR = "슬퍼하는 거 아니니까 걱정하지 마. 그냥 '월석 사냥꾼'을 그만두면 뭐로 먹고 살아야 하나 생각 중인 거니까.",
          DialogueId = 51010136,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D270",
          NextDialogue = 51010137,
          SpeakNpcId = 700302,
          Subtitle = "I know. I'm not sad. Just... wondering what comes next, now that \"Giselle the Phoxhunter\" is off the case."
        },
        [51010137] = {
          ContentKR = "배우는 안 하려고. 비올레타의 공연을 보고 나니까, 농담으로라도 그런 소린 못 하겠더라고...",
          DialogueId = 51010137,
          GUID = "7FB2D29A",
          NextOptions = {
            [1] = 510100471,
            [2] = 510100472
          },
          SpeakNpcId = 700302,
          Subtitle = "Acting's off the table. After watching Violetta perform, I realised the stage really isn't for me..."
        },
        [51010138] = {
          ContentKR = "돈벌이가 꽤 쏠쏠할 것 같았거든.",
          DialogueId = 51010138,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D2C4",
          NextDialogue = 51010140,
          SpeakNpcId = 700302,
          Subtitle = "Well, I thought acting paid well."
        },
        [51010139] = {
          ContentKR = "그만 놀려, 진짜 명탐정님.",
          DialogueId = 51010139,
          GUID = "7FB2D2EE",
          NextDialogue = 51010140,
          SpeakNpcId = 700302,
          Subtitle = "Alright, alright — no need to rub it in, Detective ."
        },
        [51010140] = {
          ContentKR = "그러면 앞으론 뭐 하실 거예요?",
          DialogueId = 51010140,
          GUID = "7FB2D318",
          NextDialogue = 51010141,
          SpeakNpcId = 100001,
          Subtitle = "So, what now? Got a new plan?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010141] = {
          ContentKR = "음... 글쎄. 어차피 시간은 많으니까, 천천히 생각해 보려고.",
          DialogueId = 51010141,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D342",
          NextDialogue = 51010142,
          SpeakNpcId = 700302,
          Subtitle = "Hmm... not yet. But there's time. I'll figure something out."
        },
        [51010142] = {
          ContentKR = "세상이라는 무대는 넓잖아. 나한테 어울리는 배역 하나쯤은 찾을 수 있겠지.",
          DialogueId = 51010142,
          GUID = "7FB2D36C",
          SpeakNpcId = 700302,
          Subtitle = "It's a big stage. I'll find my part eventually."
        },
        [51010143] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentKR = "잠깐만요!",
          DialogueId = 51010143,
          FacialId = {
            [1] = "700300:CM_Smile01",
            [2] = "700302:CM_Angry01",
            [3] = "100001:Angry01"
          },
          GUID = "7FB2AA92",
          NextDialogue = 51009894,
          SpeakNpcId = 100001,
          Subtitle = "Wait — stop!",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010201] = {
          ContentKR = "♪용광로가 여명을 불태워, 눈과 강철의 성채를 무너뜨리네...",
          DialogueId = 51010201,
          GUID = "7FB2DD1A",
          SpeakNpcId = 700342,
          Subtitle = "♪ Furnace-fire burns the dawn, tipping out the fortress of iron 'n' snow...",
          VoiceName = "voice/$Locale$/env/700342/7FB2DD1A"
        },
        [51010202] = {
          ContentKR = "♪용광로가 여명을 불태워, 눈과 강철의 성채를 무너뜨리네.\n톱니바퀴 목 놓아 노래하며, 샛별을 삼키고, 북방의 위대한 시대를 찬미하라——",
          DialogueId = 51010202,
          GUID = "7FB2DD44",
          NextDialogue = 51010203,
          SpeakNpcId = 700342,
          Subtitle = "♪ Furnace-fire burns the dawn, tipping out the fortress of iron 'n' snow.\nGears sing in hymns, devour the stars, hailing the great age of ice in north—",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD44"
        },
        [51010203] = {
          ContentKR = "음? 날 부른 거야...?",
          DialogueId = 51010203,
          GUID = "7FB2DD6E",
          LookAt = {
            [1] = "700342:n(0)"
          },
          NextOptions = {
            [1] = 510102031,
            [2] = 510102032
          },
          SpeakNpcId = 700342,
          Subtitle = "Hmm? Were you talking to me...?",
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_End"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD6E"
        },
        [51010204] = {
          ContentKR = "고마워, 낯선 여행자님! 사실은 이 노래, 아직 미완성이야. 괜찮다면 같이 만들어 볼래?",
          DialogueId = 51010204,
          GUID = "7FB2DD98",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          Subtitle = "Thank you, kind traveller! But the song's not quite finished yet... Perhaps we could find its ending together?",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD98"
        },
        [51010205] = {
          ContentKR = "방해가 됐다면 미안해! 그런데 저 병사분께 물어봤을 땐, 이 도시엔 광장에서 음유시인이 노래하면 안 된다는 법은 없다고 했어.",
          DialogueId = 51010205,
          GUID = "7FB2DDC2",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          Subtitle = "Oh — apologies if I disturbed you! Though I did check with the guard over there, and he said there's no law against bards singing in the square.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDC2"
        },
        [51010206] = {
          ContentKR = "다음 구절은 뭐가 좋을까...",
          DialogueId = 51010206,
          GUID = "7FB2DDEC",
          NextDialogue = 51010207,
          SpeakNpcId = 700342,
          Subtitle = "Now, how should the final line go...?",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDEC"
        },
        [51010207] = {
          ContentKR = "'바람'에 대해 써야 할 것 같아... 바람은 장소에 따라 다 다른 느낌을 주거든...",
          DialogueId = 51010207,
          GUID = "7FB2DE16",
          NextDialogue = 51010208,
          SpeakNpcId = 700342,
          Subtitle = "I think it should be about the wind. Every place has its own wind...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE16"
        },
        [51010208] = {
          ContentKR = "엘리시아의 바람엔 저녁 기도의 우유 향이 녹아들어 있고, 루카 공화국의 바람엔 화실의 테레빈유와 카페의 캐러멜 향이, 이스엘의 바람엔 박하 향이 섞여 있어...",
          DialogueId = 51010208,
          GUID = "7FB2DE40",
          NextDialogue = 51010209,
          SpeakNpcId = 700342,
          Subtitle = "The wind in Elysium smells of frankincense, melting into evening prayers. In Luca, it's turpentine from painter's lofts, and caramel wafting from cafés. In Aethyrie, the scent is ink laced with wild mint...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE40"
        },
        [51010209] = {
          ContentKR = "그렇다면 휘페르보레아 제국의 '바람'은 어떤 느낌이려나?",
          DialogueId = 51010209,
          GUID = "7FB2DE6A",
          NextOptions = {
            [1] = 510102091,
            [2] = 510102092,
            [3] = 510102093
          },
          SpeakNpcId = 700342,
          Subtitle = "So — what does the wind smell like, here in Hyperborea?",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE6A"
        },
        [51010210] = {
          ContentKR = "음... 일리 있는 말이야. 여긴 이 도시처럼 강철 숲이 아주 많으니까.",
          DialogueId = 51010210,
          GUID = "7FB2DE94",
          NextDialogue = 51010211,
          SpeakNpcId = 700342,
          Subtitle = "Hmm... you may be right. This city was born of steel — a forest forged, not grown.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE94"
        },
        [51010211] = {
          ContentKR = "바람은 차가워도, 그 끝에 실려 오는 톱니바퀴와 엔진 소리는 언제나 뜨겁게 끓어오르지.",
          DialogueId = 51010211,
          GUID = "7FB2DEBE",
          NextDialogue = 51010212,
          SpeakNpcId = 700342,
          Subtitle = "The wind may sting with cold, but it hums with gears and hisses with flame. And when you touch it... it burns.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEBE"
        },
        [51010212] = {
          ContentKR = "병사들의 총구도 아마 델 듯이 뜨거울 거야. 다들 표정은 얼음장 같지만...",
          DialogueId = 51010212,
          GUID = "7FB2DEE8",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          Subtitle = "Like the barrel of a soldier's rifle — even when their face is cold as stone.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEE8"
        },
        [51010213] = {
          ContentKR = "그렇네! 이 도시의 4분의 3은 눈으로 이루어져 있으니까. 여기 사람들 말이, 아이스레이크 시티는 일 년에 딱 3개월만 빼고 늘 눈이 내린대.",
          DialogueId = 51010213,
          GUID = "7FB2DF12",
          NextDialogue = 51010214,
          SpeakNpcId = 700342,
          Subtitle = "So true! They say three-quarters of this city is made of snow. Locals told me it's always snowing in Icelake — only thaws three months a year.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF12"
        },
        [51010214] = {
          ContentKR = "게다가 바람과 눈은 늘 함께 다니잖아. 대자연이 우리에게 준 최고의 조합이네!",
          DialogueId = 51010214,
          GUID = "7FB2DF3C",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          Subtitle = "And snow always has its partner: the wind. They dance together — nature's perfect duet!",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF3C"
        },
        [51010215] = {
          ContentKR = "'눈물'이라... 이 노래의 앞부분에선 한 번도 쓰지 않은 소재인데...",
          DialogueId = 51010215,
          GUID = "7FB2DF66",
          NextDialogue = 51010216,
          SpeakNpcId = 700342,
          Subtitle = "\"Tears?\" Hmm... That's a line I haven't used yet...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF66"
        },
        [51010216] = {
          ContentKR = "......",
          DialogueId = 51010216,
          GUID = "7FB2DF90",
          NextDialogue = 51010217,
          SpeakNpcId = 700342,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF90"
        },
        [51010217] = {
          ContentKR = "이 광장에 처음 온 날, 눈먼 광대가 공연하는 걸 봤어. 몇 년 전에 보일러 연기 때문에 그렇게 됐다고 하더라. 어떤 아이가 공연을 보고 배를 잡고 웃으니까, 아이의 하인이 실버를 툭 던져 주었지.",
          DialogueId = 51010217,
          GUID = "7FB2DFBA",
          NextDialogue = 51010218,
          SpeakNpcId = 700342,
          Subtitle = "On my first day in this square, I saw a blind jester performing. He said his eyes were burned by boiler fumes years ago. A child laughed wildly at his tricks, and the servant beside him tossed down a silver coin.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFBA"
        },
        [51010218] = {
          ContentKR = "내가 지금 앉아 있는 이 벤치에선 어떤 퇴역 군인이 딱 하나 남은 훈장을 판다며 소리쳤고, 바로 옆 벤치에선 야윈 어머니가 아픈 아이에게 말라 버린 젖을 물리고 있었어.",
          DialogueId = 51010218,
          GUID = "7FB2DFE4",
          NextDialogue = 51010219,
          SpeakNpcId = 700342,
          Subtitle = "On this very bench I'm sitting on now, a retired soldier cried out, trying to sell his last medal. Beside him, a frail mother coaxed out the last of her milk to feed her sick child.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFE4"
        },
        [51010219] = {
          ContentKR = "...그때, 이 광장을 스친 바람엔 아마도 '눈물'이 실려 있었을 거야.",
          DialogueId = 51010219,
          GUID = "7FB2E00E",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          Subtitle = "That day, the wind drifting through this square... it felt like it was weeping too.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E00E"
        },
        [51010220] = {
          ContentKR = "조언 고마워, 설원의 장미 같은 여행자님... 이제 곧, 노래를 완성할 수 있을 것 같아.",
          DialogueId = 51010220,
          GUID = "7FB2E038",
          SpeakNpcId = 700342,
          Subtitle = "Thank you, dear {性别:sir|miss} — you've given me the line I needed. You're a rose blooming on the tundra. I think I can finally finish this song.",
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E038"
        },
        [51010221] = {
          ContentKR = "조언 고마워, 설원의 장미 같은 여행자님.",
          DialogueId = 51010221,
          GUID = "7FB2E062",
          SpeakNpcId = 700342,
          Subtitle = "Thank you, dear {性别:sir|miss}, for giving me the line I needed. You're a rose blooming on the tundra.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E062"
        },
        [51010301] = {
          ContentKR = "카론의 안개의 바다 신화에서...",
          DialogueId = 51010301,
          GUID = "7FB2ED82",
          SpeakNpcId = 700342,
          Subtitle = "The Misty Sea myths of the Charon...",
          VoiceName = "voice/$Locale$/env/700342/7FB2ED82"
        },
        [51010302] = {
          ContentKR = "...가장 재미있는 부분은, 안개 바다의 만물이 삶과 죽음을 영원히 되풀이한다는 거야. 넌 어떻게 생각해? 이디...",
          DialogueId = 51010302,
          GUID = "7FB2EDAC",
          NextDialogue = 51010303,
          SpeakNpcId = 700342,
          Subtitle = "This one's the most fascinating — it says everything in the Misty Sea is caught in an endless cycle of life and death. What do you think, Idy—",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDAC"
        },
        [51010303] = {
          ContentKR = "아, 너였구나! 기억나, 저번에 여기서 이야기했었잖아.",
          DialogueId = 51010303,
          GUID = "7FB2EDD6",
          NextDialogue = 51010304,
          SpeakNpcId = 700342,
          Subtitle = "Ah! It's you! I remember — we spoke right here, didn't we?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDD6"
        },
        [51010304] = {
          ContentKR = "혹시 내 친구 못 봤어? 빨간 머리 여자앤데, 아까까지만 해도 여기 있었거든...",
          DialogueId = 51010304,
          GUID = "7FB2EE00",
          NextOptions = {
            [1] = 51010305
          },
          SpeakNpcId = 700342,
          Subtitle = "Have you seen my friend? Red hair, always drifting in and out like the wind... She was just here a moment ago.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE00"
        },
        [51010305] = {
          ContentKR = "못 봤어.",
          DialogueId = 51010305,
          GUID = "7FB2EE2A",
          NextDialogue = 51010306,
          Subtitle = "I haven't seen anyone like that around."
        },
        [51010306] = {
          ContentKR = "알겠어! 그럼 여기서 조금 더 기다려 봐야겠다. 툭하면 갑자기 없어졌다, 다시 나타나곤 하는 애라서 말이야.",
          DialogueId = 51010306,
          GUID = "7FB2EE54",
          NextDialogue = 51010307,
          SpeakNpcId = 700342,
          Subtitle = "Thanks anyway. I'll wait a bit — she has a habit of vanishing... then turning up out of nowhere.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE54"
        },
        [51010307] = {
          ContentKR = "요 며칠 여기서 카론의 고대 신화를 많이 수집했어. 여기 사람들은 그런 얘기를 전혀 거리낌 없이 하더라. 깜짝 놀랐다니까.",
          DialogueId = 51010307,
          GUID = "7FB2EE7E",
          NextDialogue = 51010308,
          SpeakNpcId = 700342,
          Subtitle = "We've been gathering Charon myths these past few days. It's surprising how openly people speak of them here.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE7E"
        },
        [51010308] = {
          ContentKR = "나랑 내 친구 고향 엘리시안에서, 카론은 신과 대화하고 권력을 휘두르는 아주 높은 신분이거든. 하지만 고대 신화는 입에 올리기만 해도 아주 위험해.",
          DialogueId = 51010308,
          GUID = "7FB2EEA8",
          NextDialogue = 51010309,
          SpeakNpcId = 700342,
          Subtitle = "Charons are shunned here in Hyperborea, but back in my homeland, Elysium, they're venerated as divine messengers enthroned in sacred halls. But to speak those old myths aloud... is dangerous there.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EEA8"
        },
        [51010309] = {
          ContentKR = "참, 카론의 신화에 대해 알아?",
          DialogueId = 51010309,
          GUID = "7FB2EED2",
          NextOptions = {
            [1] = 51010310,
            [2] = 51010311
          },
          SpeakNpcId = 700342,
          Subtitle = "Do you know much about the myths of the Charon?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EED2"
        },
        [51010310] = {
          ContentKR = "조금은.",
          DialogueId = 51010310,
          GUID = "7FB2EEFC",
          NextDialogue = 51010312,
          Subtitle = "A little."
        },
        [51010311] = {
          ContentKR = "전혀 몰라.",
          DialogueId = 51010311,
          GUID = "7FB2EF26",
          NextDialogue = 51010312,
          Subtitle = "Not really."
        },
        [51010312] = {
          ContentKR = "'카론'은 '안개의 바다에서 온 자'라는 뜻이야...",
          DialogueId = 51010312,
          GUID = "7FB2EF50",
          NextDialogue = 51010313,
          SpeakNpcId = 700342,
          Subtitle = "\"Charon\" means \"those who came from the Misty Sea\"...",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF50"
        },
        [51010313] = {
          ContentKR = "모든 건 안개의 바다에서 시작됐어. 성스러운 나무, 그러니까 성수는 안개의 바다에서 자라는데, 성수의 커다란 잎사귀가 바로 천국의 나무야. 세계는 성수 위에 세워져 있지.",
          DialogueId = 51010313,
          GUID = "7FB2EF7A",
          NextDialogue = 51010314,
          SpeakNpcId = 700342,
          Subtitle = "The Misty Sea is the origin of all things. From it rose the Sacred Tree. Its canopy stretched across the heavens — and each of its branches became a Heaventree. Its roots, meanwhile, cradled the world.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF7A"
        },
        [51010314] = {
          ContentKR = "성수에서 순백의 꽃이 피어나자, 그 속에서 어머니 신 엠블라가 태어났어. 엠블라는 만물을 창조했고, 아버지 신 아스크도 창조했지. 이 두 신 사이에서 카론들의 공통된 선조가 태어난 거야.",
          DialogueId = 51010314,
          GUID = "7FB2EFA4",
          NextDialogue = 51010315,
          SpeakNpcId = 700342,
          Subtitle = "The tree bloomed with white flowers, and from them stepped forth Mother Embla. She created all things — and from her came Father Ask. Together, they gave birth to the first of the Charons.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFA4"
        },
        [51010315] = {
          ContentKR = "그렇지만 <W>죽음의 권능</>을 관장하는 아스크는 재앙의 화신이 됐고, 결국엔 '일식'이란 종말을 불러오고 말았지.",
          DialogueId = 51010315,
          GUID = "7FB2EFCE",
          NextDialogue = 51010316,
          SpeakNpcId = 700342,
          Subtitle = "Yet Ask, bearer of the power of death, became a vessel of calamity. In the end, it was he who brought ruin to the world — the cataclysm we call Ragnarok.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFCE"
        },
        [51010316] = {
          ContentKR = "종말이 찾아오자, <H>생명의 권능</>을 관장하는 어머니 신은 자신의 백성들을 지켜 줬고, 조각난 그녀의 영혼은 바다로 흩어져, 마침내 안개의 바다로 돌아갔어.",
          DialogueId = 51010316,
          GUID = "7FB2EFF8",
          NextDialogue = 51010317,
          SpeakNpcId = 700342,
          Subtitle = "In that final hour, Mother Embla — keeper of the power of life — gathered her children and sheltered them. Her soul scattered into the sea... and at last, returned to the Misty Sea.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFF8"
        },
        [51010317] = {
          ContentKR = "아버지 신의 육신은 대지로 변했고, 그가 높이 들어 올렸던 팔은 산맥이 되어, 언제 돌아올지 모르는 신을 향해 영원히 뻗어 있게 되었지.",
          DialogueId = 51010317,
          GUID = "7FB2F022",
          NextOptions = {
            [1] = 51010318
          },
          SpeakNpcId = 700342,
          Subtitle = "Ask's body became the land and his arms, upraised, became the mountains, still reaching for the gods... who no longer come.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F022"
        },
        [51010318] = {
          ContentKR = "조금 슬픈 이야기네.",
          DialogueId = 51010318,
          GUID = "7FB2F04C",
          NextDialogue = 51010319,
          Subtitle = "That's... kind of a sad story."
        },
        [51010319] = {
          ContentKR = "응. 하지만 고대 신화 중엔 흥미로운 이야기가 하나 더 있어.",
          DialogueId = 51010319,
          GUID = "7FB2F076",
          NextDialogue = 51010320,
          SpeakNpcId = 700342,
          Subtitle = "Mm... but there's another thread in the myths that caught my ear.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F076"
        },
        [51010320] = {
          ContentKR = "종말이 끝난 후, 엠블라랑 아스크가 새로운 세상에서, 새로운 모습으로 태어났다는 이야기야.",
          DialogueId = 51010320,
          GUID = "7FB2F0A0",
          NextDialogue = 51010321,
          SpeakNpcId = 700342,
          Subtitle = "It says Ask and Embla were reborn after the world's end — in new forms, walking again in a new world.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0A0"
        },
        [51010321] = {
          ContentKR = "새롭게 태어난 두 신은 또다시 새로운 종말과 파멸, 그리고 새로운 시작을 가져온대.",
          DialogueId = 51010321,
          GUID = "7FB2F0CA",
          NextDialogue = 51010322,
          SpeakNpcId = 700342,
          Subtitle = "And that their reborn selves would one day bring about another ending — and another beginning.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0CA"
        },
        [51010322] = {
          ContentKR = "세계는 끝없이 순환하고, 모든 생명은 삶과 죽음을 반복하는 거지.",
          DialogueId = 51010322,
          GUID = "7FB2F0F4",
          NextOptions = {
            [1] = 51010323
          },
          SpeakNpcId = 700342,
          Subtitle = "Thus the world turns, ever in circles. Life and death, again and again.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0F4"
        },
        [51010323] = {
          ContentKR = "옛날 사람들도 비극적인 결말을 싫어했나 보네.",
          DialogueId = 51010323,
          GUID = "7FB2F11E",
          NextDialogue = 51010324,
          Subtitle = "Seems that the ancients didn't like tragic endings either."
        },
        [51010324] = {
          ContentKR = "근데... 살짝 신경 쓰이는 게, 이야기의 작가는 어째서 아버지 신과 어머니 신이 새로운 삶을 얻었다고 믿은 걸까? 다시 말하면, 엠블라와 아스크의 본질을 '정의'하는 건 과연 뭘까?",
          DialogueId = 51010324,
          GUID = "7FB2F148",
          NextDialogue = 51010325,
          SpeakNpcId = 700342,
          Subtitle = "But... what I keep wondering is — why was the storyteller so sure that the gods were reborn? Or rather... what makes Embla and Ask who they are?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F148"
        },
        [51010325] = {
          ContentKR = "그들의 육체일까, 영혼일까? 아니면... 다른 무언가일까?",
          DialogueId = 51010325,
          GUID = "7FB2F172",
          NextDialogue = 51010326,
          SpeakNpcId = 700342,
          Subtitle = "Is it their bodies? Their souls? ...Or something else entirely?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F172"
        },
        [51010326] = {
          ContentKR = "만약... 어디까지나 가정이지만, 어떤 위대한 마법사가 우리 발밑의 대지를 아스크의 모습으로 만들었다고 해봐. 그러면 그 아스크와 새로 태어난 아스크 중에, 누가 우리의 아버지 신인 걸까?",
          DialogueId = 51010326,
          GUID = "7FB2F19C",
          NextOptions = {
            [1] = 510103261,
            [2] = 510103262,
            [3] = 510103263,
            [4] = 510103264
          },
          SpeakNpcId = 700342,
          Subtitle = "Imagine this — just for a moment — that a great mage turned the land beneath our feet back into Ask's original form... Then who would truly be Father Ask? The one made of ancient earth? Or the one who bears his soul reborn?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F19C"
        },
        [51010327] = {
          ContentKR = "그렇게 생각하는구나... 고마워! 덕분에 영감을 많이 얻었어.",
          DialogueId = 51010327,
          GUID = "7FB2F1C6",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          Subtitle = "Ah... so that's how you see it. Thank you. You've given me something new to ponder.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1C6"
        },
        [51010328] = {
          ContentKR = "수많은 창작이 다 이런 사소한 질문에서 시작되는 거 아닐까?",
          DialogueId = 51010328,
          GUID = "7FB2F1F0",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          Subtitle = "Most songs begin with a question that sounds pointless, don't they?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1F0"
        },
        [51010329] = {
          ContentKR = "고마워, 촛불의 불꽃 같은 여행자님. 난 이 신화들이 정말 마음에 들어. 이제 이걸 노래로 만들 수 있게 됐네.",
          DialogueId = 51010329,
          GUID = "7FB2F21A",
          SpeakNpcId = 700342,
          Subtitle = "Thank you for your time, dear {性别:sir|miss}. You're a spark on a cold wick. I've come to love these myths. I think... I've found a song inside them, at last.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F21A"
        },
        [51010330] = {
          ContentKR = "우리를 '우리'로 만들어 주는 건 대체 뭘까?",
          DialogueId = 51010330,
          GUID = "7FB2F244",
          SpeakNpcId = 700342,
          Subtitle = "What made us who we are?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F244"
        },
        [51010401] = {
          ContentKR = "갈레아 극장...",
          DialogueId = 51010401,
          GUID = "7FB2FDEA",
          SpeakNpcId = 700342,
          Subtitle = "The Galea Theatre...",
          VoiceName = "voice/$Locale$/env/700342/7FB2FDEA"
        },
        [51010402] = {
          ContentKR = "또 만났네, 백사장 위의 석류석 같은 여행자님. 여길 많이 좋아하나 봐. 나도 그래.",
          DialogueId = 51010402,
          GUID = "7FB2FE14",
          NextDialogue = 51010403,
          SpeakNpcId = 700342,
          Subtitle = "We meet again, dear {性别:sir|miss}. You're a garnet on white sand. You must like it here. I do too.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE14"
        },
        [51010403] = {
          ContentKR = "갈레아 극장에 가 본 적 있어?",
          DialogueId = 51010403,
          GUID = "7FB2FE3E",
          NextOptions = {
            [1] = 510104031,
            [2] = 510104032,
            [3] = 510104033
          },
          SpeakNpcId = 700342,
          Subtitle = "Have you ever been inside the Galea Theatre?",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE3E"
        },
        [51010404] = {
          ContentKR = "와! 부자구나. 정말 부럽다.",
          DialogueId = 51010404,
          GUID = "7FB2FE68",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "Oh! How enviable... You must be well-off.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE68"
        },
        [51010405] = {
          ContentKR = "음... 나랑 같구나.",
          DialogueId = 51010405,
          GUID = "7FB2FE92",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "Ah... then I'm not the only one kept outside the gates.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE92"
        },
        [51010406] = {
          ContentKR = "군단이랑? 우와, 여행자님한테도 이야깃거리가 엄청 많겠구나.",
          DialogueId = 51010406,
          GUID = "7FB2FEBC",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "You fought the Legion? Remarkable... You must have stories tucked away like old sheet music.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEBC"
        },
        [51010407] = {
          ContentKR = "난 루카 공화국에 있는 어지간한 극장은 다 가 봤어. 그런데 휘페르보레아 제국의 극장만은 좀처럼 들어가볼 수가 없어.",
          DialogueId = 51010407,
          GUID = "7FB2FEE6",
          NextDialogue = 51010408,
          SpeakNpcId = 700342,
          Subtitle = "I've visited opera houses across Luca, but here in Hyperborea... they always turn me away.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEE6"
        },
        [51010408] = {
          ContentKR = "여긴 카론이 살기 좋은 곳이 아니란 건 알고 있었지만, 공공시설에서 받는 비용도 생각보다 훨씬 비싸더라.",
          DialogueId = 51010408,
          GUID = "7FB2FF10",
          NextDialogue = 51010409,
          SpeakNpcId = 700342,
          Subtitle = "I knew Charons had it rough in this city, but I never imagined the supervision levies for public spaces would be so steep...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF10"
        },
        [51010409] = {
          ContentKR = "운 좋게 해마다 딱 한 번 무료입장이 가능한 축제 날에 맞춰 왔는데, 하필이면 그날 거기서 무력 충돌이 일어났다고 하더라고... 정말 최악이었지.",
          DialogueId = 51010409,
          GUID = "7FB2FF3A",
          NextDialogue = 51010410,
          SpeakNpcId = 700342,
          Subtitle = "Still — I was lucky to arrive just in time for the Silvercandle Carnival. It's the city's one day when even paupers like me can step through the theatre doors for free. Tragic, though... to hear there'd been a shootout inside. Absolutely dreadful.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF3A"
        },
        [51010410] = {
          ContentKR = "그래도 다행히 악보는 잔뜩 모았어! 서점 판매가는 나름 합리적이었고, 노래를 불러 주면 악보를 주겠단 분들도 꽤 많았거든. 그리고 어떤 마음씨 좋은 친구가 유명한 노래도 한 곡 가르쳐 줬어!",
          DialogueId = 51010410,
          GUID = "7FB2FF64",
          NextOptions = {
            [1] = 510104101
          },
          SpeakNpcId = 700342,
          Subtitle = "Even so, I gathered plenty of sheet music! The bookshop prices were fair, and a few kind souls let me trade verses for pages. And one mysterious person... even taught me a famous aria.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF64"
        },
        [51010411] = {
          ContentKR = "며칠 전 일인데, 밤에 달빛 아래 벽에 기대서, 어렵게 구한 악보에서 배운 노래를 흥얼거리고 있었거든. 멜로디가 복잡하진 않아서, 금방 외울 수 있는 노래였어.",
          DialogueId = 51010411,
          GUID = "7FB2FF8E",
          NextDialogue = 51010412,
          SpeakNpcId = 700342,
          Subtitle = "A few nights ago, I was leaning against a wall under the moonlight, humming a melody I'd picked up from a second-hand score. It was simple enough — soft, easy to carry on the wind.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF8E"
        }
      }
    end
  },
  {
    MinKey = 51010412,
    MaxKey = 51011314,
    Loader = function()
      return {
        [51010412] = {
          ContentKR = "근데 노래를 다 부르고 나니까, 갑자기 벽 너머에서 이상한 노크 소리가 들리는 거야... 들어보니까 소리에 어떤 규칙이 있더라. 알다시피, 음유시인은 리듬에 민감한 편이잖아.",
          DialogueId = 51010412,
          GUID = "7FB2FFB8",
          NextDialogue = 51010413,
          SpeakNpcId = 700342,
          Subtitle = "When I finished, I heard knocking — on the other side of the wall. Rhythmic. Intentional. Bards are always sensitive to rhythm... I knew it wasn't random.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFB8"
        },
        [51010413] = {
          ContentKR = "그래서 그 리듬을 분석해 봤더니, 흔하디흔한 옛날식 암호였어. 두 가지 노크 소리로 나한테 신호를 보내고 있더라고.",
          DialogueId = 51010413,
          GUID = "7FB2FFE2",
          NextDialogue = 51010414,
          SpeakNpcId = 700342,
          Subtitle = "It was code — old knock code, passed down long ago. Just two kinds of taps, but enough to send meaning through stone.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFE2"
        },
        [51010414] = {
          ContentKR = "벽 너머의 사람은 내가 노래를 잘못 불렀다고 알려 줬어. 그건 여기서 굉장히 유명한 오페라에 나오는 파트였는데, 난 대본을 읽어 본 적이 없으니까, 노래가 관중들에게 전달하려는 감정을 제대로 이해하지 못했던 거야.",
          DialogueId = 51010414,
          GUID = "7FB3000C",
          NextDialogue = 51010415,
          SpeakNpcId = 700342,
          Subtitle = "They told me I'd sung it wrong. It was a well-known operatic piece here — but I hadn't read the libretto, so I'd missed its feeling and heart.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3000C"
        },
        [51010415] = {
          ContentKR = "그 사람은 어떤 이유 때문인지 말을 하거나 노래를 부를 수 없는 상황이었어. 그렇지만 노크로 신호를 보내서 어떻게 불러야 하는지 알려 줄 순 있었지.",
          DialogueId = 51010415,
          GUID = "7FB30036",
          NextDialogue = 51010416,
          SpeakNpcId = 700342,
          Subtitle = "They couldn't speak or sing. I don't know why. But they used that rhythm to teach me how to sing it true.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30036"
        },
        [51010416] = {
          ContentKR = "덕분에 노래를 제대로 부를 수 있게 됐을 때, 감사 인사를 하려고 벽 너머로 달려가 보니까, 그 마음씨 좋은 분은 이미 떠나고 없더라.",
          DialogueId = 51010416,
          GUID = "7FB30060",
          NextOptions = {
            [1] = 510104161,
            [2] = 510104162
          },
          SpeakNpcId = 700342,
          Subtitle = "And when I had finally mastered the song, I ran to the other side of the wall to thank them... Only to find they were already gone.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30060"
        },
        [51010417] = {
          ContentKR = "앗! 굉장한 우연이네!",
          DialogueId = 51010417,
          GUID = "7FB3008A",
          NextDialogue = 51010418,
          SpeakNpcId = 700342,
          Subtitle = "Oh, how lucky!",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3008A"
        },
        [51010418] = {
          ContentKR = "괜찮다면 나 대신 그분께 감사 인사와... 축복을 전해 줘! 사정은 모르겠지만, 하루빨리 말할 수 있게 되길 바란다고 말이야. 난 알아, 그분은 노래를 정말 정말 좋아하는 분이야.",
          DialogueId = 51010418,
          GUID = "7FB300B4",
          NextDialogue = 51010419,
          SpeakNpcId = 700342,
          Subtitle = "If it's not too much trouble... would you thank them for me? And send them my best wishes, too. I don't know why they couldn't sing — but I'm sure they loved music, deeply.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300B4"
        },
        [51010419] = {
          ContentKR = "...응, 그럴게.",
          DialogueId = 51010419,
          GUID = "7FB300DE",
          NextDialogue = 51010421,
          SpeakNpcId = 100001,
          Subtitle = "...Sure, I will.",
          TalkActionId = {
            [1] = "0:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300DE"
        },
        [51010420] = {
          ContentKR = "그렇지... 숨겨진 이야기도 많고.",
          DialogueId = 51010420,
          GUID = "7FB30108",
          NextDialogue = 51010421,
          SpeakNpcId = 700342,
          Subtitle = "That it is... and full of kooky tales, too.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30108"
        },
        [51010421] = {
          ContentKR = "그러고 보면, 여기 오페라는 루카 공화국하곤 많이 달라...",
          DialogueId = 51010421,
          GUID = "7FB30132",
          NextDialogue = 51010422,
          SpeakNpcId = 700342,
          Subtitle = "The opera here is quite unlike Luca's.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30132"
        },
        [51010422] = {
          ContentKR = "루카 공화국의 오페라는 불꽃이고, 이스엘의 오페라는 바람이야.",
          DialogueId = 51010422,
          GUID = "7FB3015C",
          NextDialogue = 51010423,
          SpeakNpcId = 700342,
          Subtitle = "Luca's opera is fire. Aethyrie's — wind.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3015C"
        },
        [51010423] = {
          ContentKR = "여기 오페라는 대지야. 드넓고, 고통스러운 땅이지...",
          DialogueId = 51010423,
          GUID = "7FB30186",
          NextDialogue = 51010424,
          SpeakNpcId = 700342,
          Subtitle = "But Hyperborea... its opera is the earth itself. Heavy, vast, and full of pain...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30186"
        },
        [51010424] = {
          ContentKR = "나랑 내 친구는 곧 떠날 거야. 하지만 그 전에 여길 위한 노래를 한 곡 만들고 싶어.",
          DialogueId = 51010424,
          GUID = "7FB301B0",
          SpeakNpcId = 700342,
          Subtitle = "My friend and I will be leaving soon. But before that... I want to write one last song for this place.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB301B0"
        },
        [51010425] = {
          ContentKR = "♪새하얀 눈은 아이를 위한 생명수, 새벽 어스름의 경계는 아이를 위한 생명줄...",
          DialogueId = 51010425,
          GUID = "7FB301DA",
          SpeakNpcId = 700342,
          Subtitle = "♪ White snow is her birth-flow, and twilight her warm cord aglow...",
          VoiceName = "voice/$Locale$/env/700342/7FB301DA"
        },
        [51010426] = {
          ContentKR = "♪새하얀 눈은 아이를 위한 생명수, 새벽 어스름의 경계는 아이를 위한 생명줄.\n그녀는 위대함과 고난을 낳아, 하얀 산 아래 흑철의 요람으로 흘려보내네...",
          DialogueId = 51010426,
          GUID = "7FB30204",
          SpeakNpcId = 700342,
          Subtitle = "♪ White snow is her birth-flow, and twilight her warm cord aglow.\nShe bears grand and pain to iron cradle — beneath the mountain, in the cold...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30204"
        },
        [51010501] = {
          ContentKR = "이봐, 너 말이야, 너. 통행증은 있나?",
          DialogueId = 51010501,
          GUID = "7FB30E52",
          NextOptions = {
            [1] = 51010502,
            [2] = 51010504,
            [3] = 51010506
          },
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?"
        },
        [51010502] = {
          ContentKR = "(법을 잘 지키고 싶지만 우연히 또 통행증을 깜빡한 거라고 울먹이며 호소한다.)",
          DialogueId = 51010502,
          GUID = "7FB30E7C",
          ImprPlusId = 1004,
          NextDialogue = 51010503,
          Subtitle = "(Tearfully explain that you're a law-abiding citizen who's once again forgotten your travel permit.)"
        },
        [51010503] = {
          ContentKR = "됐어, 대체 몇 번째야, 좀 더 신선한 핑계 없어? 아무튼 눈에 띄는 짓 하지 말고 얼른 가.",
          DialogueId = 51010503,
          GUID = "7FB30EA6",
          NextDialogue = 51010508,
          SpeakNpcId = 700111,
          Subtitle = "Oh, spare me — I've heard that so many times my ears are calloused. Off you go, and don't make a spectacle of yourself."
        },
        [51010504] = {
          ContentKR = "(카밀라가 위조해 준 통행증을 꺼낸다.)",
          DialogueId = 51010504,
          GUID = "7FB30ED0",
          ImprPlusId = 1003,
          NextDialogue = 51010505,
          Subtitle = "(Hand over the travel permit Camilla forged.)"
        },
        [51010505] = {
          ContentKR = "통행증 확인 완료, 통행을 허가한다.",
          DialogueId = 51010505,
          GUID = "7FB30EFA",
          NextDialogue = 51010508,
          SpeakNpcId = 700111,
          Subtitle = "Travel permit verified. You may pass."
        },
        [51010506] = {
          ContentKR = "케빈, 눈물의 호수에서의 일이 윗선에 알려지기를 바라진 않으시겠죠...",
          DialogueId = 51010506,
          GUID = "7FB30F24",
          ImprPlusId = 1005,
          NextDialogue = 51010507,
          Subtitle = "Mr Kevin, you wouldn't want your superiors finding out about that incident by Lamenting Lake, would you...?"
        },
        [51010507] = {
          ContentKR = "그만!!! 지나가게 해 주면 될 거 아냐!",
          DialogueId = 51010507,
          GUID = "7FB30F4E",
          NextDialogue = 51010508,
          SpeakNpcId = 700111,
          Subtitle = "Alright, alright! Fine — you can go, just go!"
        },
        [51010508] = {
          ContentKR = "오늘은 모처럼 평화롭네...",
          DialogueId = 51010508,
          GUID = "7FB30F78",
          NextOptions = {
            [1] = 51010509
          },
          RestartTag = 51010508,
          SpeakNpcId = 700111,
          Subtitle = "For once... no trouble..."
        },
        [51010509] = {
          ContentKR = "(보통 이런 말을 하면 예상 밖의 상황이 생기곤 하던데.)",
          DialogueId = 51010509,
          FailDialogue = 51010510,
          GUID = "7FB30FA2",
          ImprCheckId = 1074,
          NextDialogue = 51010511,
          Subtitle = "(Famous last words — something's bound to happen now.)"
        },
        [51010510] = {
          ContentKR = "(예상과는 달리, 별다른 상황은 생기지 않았다. 케빈과 잠시 인사를 나눈 후 다들 각자의 근무지로 돌아간다.)",
          DialogueId = 51010510,
          GUID = "7FB30FCC",
          Subtitle = "(The expected chaos never arrives. After a brief word with Kevin, everyone returns to their duties.)"
        },
        [51010511] = {
          ContentKR = "(입구 근처에서 갑자기 전화벨이 울린다. 화들짝 놀란 케빈이 다급히 전화를 받는다.)",
          DialogueId = 51010511,
          GUID = "7FB30FF6",
          NextDialogue = 51010512,
          Subtitle = "(A shrill ring erupts by the gate. Kevin jumps like a startled rabbit and scrambles to answer.)"
        },
        [51010512] = {
          ContentKR = "아, 네... 네! 알겠습니다!",
          DialogueId = 51010512,
          GUID = "7FB31020",
          NextDialogue = 51010513,
          SpeakNpcId = 700111,
          Subtitle = "Alright, alright... Yes — understood!"
        },
        [51010513] = {
          ContentKR = "(짧은 통화 후, 케빈은 전화를 끊고 입구를 향해 '통과' 제스처를 취한다.)",
          DialogueId = 51010513,
          GUID = "7FB3104A",
          NextDialogue = 51010514,
          Subtitle = "(After a brief exchange, Kevin lowers the phone and gestures for you to pass.)"
        },
        [51010514] = {
          ContentKR = "볼일 끝났으면 얼른 돌아가. 오늘도 제때 퇴근하긴 글렀네.",
          DialogueId = 51010514,
          GUID = "7FB31074",
          NextDialogue = 51010515,
          SpeakNpcId = 700111,
          Subtitle = "If that's all, off you go. So much for a quiet shift..."
        },
        [51010515] = {
          ContentKR = "휴... 널 만나기만 하면 일이 터진다니까...",
          DialogueId = 51010515,
          GUID = "7FB3109E",
          SpeakNpcId = 700111,
          Subtitle = "Why does trouble always find you...?"
        },
        [51010516] = {
          ContentKR = "이봐! 통행증... 아, 너구나. 얼른 가, 얼른.",
          DialogueId = 51010516,
          GUID = "7FB310C8",
          SpeakNpcId = 700111,
          Subtitle = "Oi! Permit — oh, it's you. Go on, off you go."
        },
        [51010601] = {
          ContentKR = "선생님, 제발 좀 도와주십시오... 얼마라도 좋으니 제발 이 빈털터리 늙은이를 도와주십시오...",
          DialogueId = 51010601,
          GUID = "7FB31EBA",
          NextDialogue = 51010602,
          SpeakNpcId = 700338,
          Subtitle = "Kind soul... I beg you... Anything you can spare... I've nothing left..."
        },
        [51010602] = {
          ContentKR = "(백발이 성성한 노인의 얼굴엔 세월의 풍파가 고스란히 묻어 있다. 그는 멍한 표정으로 아이스레이크 시티를 오가는 사람들을 바라보며 쉰 목소리로 자비를 구걸한다.)",
          DialogueId = 51010602,
          GUID = "7FB31EE4",
          NextOptions = {
            [1] = 51010603,
            [2] = 51010606,
            [3] = 51010610
          },
          Subtitle = "(A grey-haired, weather-beaten old man stands before you. His blank gaze scans the bustling streets of Icelake as he pleads in a hoarse voice.)"
        },
        [51010603] = {
          ContentKR = "(참 안 됐네, 조금이라도 도와야겠다.)",
          DialogueId = 51010603,
          GUID = "7FB31F0E",
          ImprPlusId = 1004,
          NextDialogue = 51010604,
          Subtitle = "(Poor old soul. Give him some money.)"
        },
        [51010604] = {
          ContentKR = "휴, 고맙네. 젊은이.",
          DialogueId = 51010604,
          GUID = "7FB31F38",
          NextDialogue = 51010605,
          SpeakNpcId = 700338,
          Subtitle = "Ah... thank you, young one."
        },
        [51010605] = {
          ContentKR = "이 늙은이가 내일의 태양을 볼 수 있을런진 몰라도... 적어도 오늘은 배불리 먹을 수 있겠어.",
          DialogueId = 51010605,
          GUID = "7FB31F62",
          SpeakNpcId = 700338,
          Subtitle = "Never know if an old man like me will wake up tomorrow... but at least I'm getting a proper meal today."
        },
        [51010606] = {
          ContentKR = "(노인의 낡은 그릇에 놓인 동전 몇 개를 챙긴다.)",
          DialogueId = 51010606,
          GUID = "7FB31F8C",
          ImprPlusId = 1005,
          NextDialogue = 51010607,
          Subtitle = "(Take a few coins from the old man's cracked bowl.)"
        },
        [51010607] = {
          ContentKR = "자네... 휴.",
          DialogueId = 51010607,
          GUID = "7FB31FB6",
          NextDialogue = 51010608,
          SpeakNpcId = 700338,
          Subtitle = "You... Ah, well."
        },
        [51010608] = {
          ContentKR = "그 눈은... 설마 자네도 그들한테 당한 건가?",
          DialogueId = 51010608,
          GUID = "7FB31FE0",
          NextDialogue = 51010609,
          SpeakNpcId = 700338,
          Subtitle = "Your eyes, {性别:lad|lass}... did they do a number on you too?"
        },
        [51010609] = {
          ContentKR = "됐으니 가져가게. 나보단 자네한테 더 필요할 것 같군.",
          DialogueId = 51010609,
          GUID = "7FB3200A",
          SpeakNpcId = 700338,
          Subtitle = "Never mind. Go on, take them. You probably need them more than I do."
        },
        [51010610] = {
          ContentKR = "몸도 건강하신데 직접 일해서 먹고사셔야죠.",
          DialogueId = 51010610,
          GUID = "7FB32034",
          ImprPlusId = 1001,
          NextDialogue = 51010611,
          Subtitle = "You're fit enough to work — you should be doing so."
        },
        [51010611] = {
          ContentKR = "일이라... 하, 나도 한때는 멀쩡한 직장을 다녔지...",
          DialogueId = 51010611,
          GUID = "7FB3205E",
          NextDialogue = 51010612,
          SpeakNpcId = 700338,
          Subtitle = "Work... ha. I used to have a decent job, once..."
        },
        [51010612] = {
          ContentKR = "하지만 그게 다 무슨 소용이겠나? 그들이 누군가의 일자리를 빼앗는 건, 자네가 이 낡은 그릇에서 동전을 집어 가는 것만큼이나 쉽단 말일세.",
          DialogueId = 51010612,
          GUID = "7FB32088",
          NextDialogue = 51010613,
          SpeakNpcId = 700338,
          Subtitle = "But what good did it do? Sometimes they snatch your job as easily as they snatch the coins from this bowl."
        },
        [51010613] = {
          ContentKR = "멋들어진 집에서 구걸하나, 거리에서 구걸하나 다 같은 것 아니겠나?",
          DialogueId = 51010613,
          GUID = "7FB320B2",
          SpeakNpcId = 700338,
          Subtitle = "Begging in a fancy house, begging in the street... what's the difference?"
        },
        [51010614] = {
          ContentKR = "잘 살아가게나... 휴우, 정말이지 착한 사람일수록 살아가기 퍽퍽한 세상이네 그려.",
          DialogueId = 51010614,
          GUID = "7FB320DC",
          SpeakNpcId = 700338,
          Subtitle = "Live well, yeah? This world's cruel... crueler still to the good ones."
        },
        [51010701] = {
          ContentKR = "종말이 오고 있어... 종말이...",
          DialogueId = 51010701,
          GUID = "7FB32F22",
          NextDialogue = 51010702,
          SpeakNpcId = 700337,
          Subtitle = "The end draws near... it draws near..."
        },
        [51010702] = {
          ContentKR = "(눈앞의 루나는 책상에 엎드려 졸면서 고개를 절레절레 흔들고 있다.)",
          DialogueId = 51010702,
          GUID = "7FB32F4C",
          NextOptions = {
            [1] = 51010703,
            [2] = 51010704
          },
          Subtitle = "(The Luno before you slumps over the table, nodding off.)"
        },
        [51010703] = {
          ContentKR = "깨운다.",
          DialogueId = 51010703,
          GUID = "7FB32F76",
          NextDialogue = 51010705,
          Subtitle = "Wake her up."
        },
        [51010704] = {
          ContentKR = "그냥 자게 둔다.",
          DialogueId = 51010704,
          GUID = "7FB32FA0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "Let her sleep."
        },
        [51010705] = {
          ContentKR = "(비관론자 루나가 갑자기 고개를 번쩍 들더니, 눈을 희번덕거리며 말을 쏟아낸다.)",
          DialogueId = 51010705,
          GUID = "7FB32FCA",
          NextDialogue = 51010706,
          Subtitle = "(Lunogloom's head snaps up, her eyes gleaming as the words pour out in a sudden torrent.)"
        },
        [51010706] = {
          ContentKR = "종말... 종말이 오고 있어. 아무도 피할 수 없다고.",
          DialogueId = 51010706,
          GUID = "7FB32FF4",
          NextDialogue = 51010707,
          SpeakNpcId = 700337,
          Subtitle = "The end... it's coming! No one will escape..."
        },
        [51010707] = {
          ContentKR = "꽃집의 꽃은 더 이상 알록달록하지 않고, 하얀 포티니아처럼 색이 바랠 거야...",
          DialogueId = 51010707,
          GUID = "7FB3301E",
          NextDialogue = 51010708,
          SpeakNpcId = 700337,
          Subtitle = "The flowers at the shop are dull, fading to bleached-white heather..."
        },
        [51010708] = {
          ContentKR = "광장의 고양이들도 더 이상 복슬복슬하지 않고, 석고처럼 딱딱하고 미끄러워질 거고...",
          DialogueId = 51010708,
          GUID = "7FB33048",
          NextDialogue = 51010709,
          SpeakNpcId = 700337,
          Subtitle = "The cats in the square are no longer soft and fluffy. They're hard and smooth... like plaster statues..."
        },
        [51010709] = {
          ContentKR = "빵집에서는 폭신폭신한 빵 대신 정체불명의 검은 물체를 굽게 될 테고...",
          DialogueId = 51010709,
          GUID = "7FB33072",
          NextDialogue = 51010710,
          SpeakNpcId = 700337,
          Subtitle = "The bakery can't make fluffy bread anymore. No matter what they do, it just turns into black sludge..."
        },
        [51010710] = {
          ContentKR = "내가 제일 좋아하는 아이스크림도 더는 차갑지 않고, 목구멍에 끈적끈적하게 달라붙을 거야...",
          DialogueId = 51010710,
          GUID = "7FB3309C",
          NextDialogue = 51010711,
          SpeakNpcId = 700337,
          Subtitle = "My favourite ice lollies aren't even cold anymore. They turn all sticky and glue up your throat..."
        },
        [51010711] = {
          ContentKR = "모두가 점차 루나만 해지고, 하얗게 변할 거야...",
          DialogueId = 51010711,
          GUID = "7FB330C6",
          NextDialogue = 51010712,
          SpeakNpcId = 700337,
          Subtitle = "Everyone's getting taller... whiter... just like a Luno..."
        },
        [51010712] = {
          ContentKR = "그리고 결국...",
          DialogueId = 51010712,
          GUID = "7FB330F0",
          NextDialogue = 51010713,
          SpeakNpcId = 700337,
          Subtitle = "In the end..."
        },
        [51010713] = {
          ContentKR = "꽃집의 아주머니도, 빵집의 아줌마도, 아이스크림을 파는 할아버지도... 다들 루나가 되어버릴 거야!",
          DialogueId = 51010713,
          GUID = "7FB3311A",
          NextOptions = {
            [1] = 51010714,
            [2] = 51010715
          },
          SpeakNpcId = 700337,
          Subtitle = "The flower shop lady, the baker, the lolly seller... Everyone will turn into a Luno!"
        },
        [51010714] = {
          ContentKR = "안녕, 루나. 나도 루나가 되고 싶어.",
          DialogueId = 51010714,
          GUID = "7FB33144",
          ImprPlusId = 1005,
          NextDialogue = 51010716,
          Subtitle = "Lunos are great. I want to be one too."
        },
        [51010715] = {
          ContentKR = "정말 끔찍한 종말이네...",
          DialogueId = 51010715,
          GUID = "7FB3316E",
          ImprPlusId = 1004,
          NextDialogue = 51010716,
          Subtitle = "What a terrifying end..."
        },
        [51010716] = {
          ContentKR = "너... 그, 그 머리카락이랑 옷, 그리고 키까지... 벌써 루나가 되기 시작한 거야?",
          DialogueId = 51010716,
          GUID = "7FB33198",
          NextDialogue = 51010717,
          SpeakNpcId = 700337,
          Subtitle = "Your hair... your clothes... your height... Are you turning into a Luno already?!"
        },
        [51010717] = {
          ContentKR = "역시... 종말... 종말이 온 거야. 모든 게 끝장이야.",
          DialogueId = 51010717,
          GUID = "7FB331C2",
          NextDialogue = 51010718,
          SpeakNpcId = 700337,
          Subtitle = "The end's here... It really is. It's all over now."
        },
        [51010718] = {
          ContentKR = "(비관론자 루나는 힘없이 두 손을 늘어뜨린다. 그녀의 멍한 시선은 당신과 겹겹의 건물을 뚫고, 흐릿한 하늘에 고정된다. 그녀가 말한 종말이 곧 현실이 되기라도 할 것처럼.)",
          DialogueId = 51010718,
          GUID = "7FB331EC",
          NextDialogue = 51010719,
          Subtitle = "(Lunogloom's arms fall limp. She stares right through you, her gaze lost somewhere beyond the buildings, fixed on the dim sky, as if her prophecy is about to come true.)"
        },
        [51010719] = {
          ContentKR = "(당연하지만 몇 분이 지나도, 아무 일도 일어나지 않는다. 루나는 더 이상 당신을 바라보지 않고, 그저 \"종말이 온다\"라는 말만 되풀이한다.)",
          DialogueId = 51010719,
          GUID = "7FB33216",
          NextDialogue = 51010720,
          Subtitle = "(A few minutes pass. As expected, nothing happens. Lunogloom never looks your way again, murmuring endlessly that the end is nigh...)"
        },
        [51010720] = {
          ContentKR = "(루나가 되는 게 대체 어떤 느낌일지 궁금하긴 해도, 지금 당신이 할 수 있는 일은 그냥 돌아서서 떠나는 것뿐이다.)",
          DialogueId = 51010720,
          GUID = "7FB33240",
          Subtitle = "(You do wonder what it might feel like... becoming a Luno. But there's nothing to be done now — so you turn and walk away.)"
        },
        [51010721] = {
          ContentKR = "종말, 종말이 이미 시작됐어...",
          DialogueId = 51010721,
          GUID = "7FB3326A",
          SpeakNpcId = 700337,
          Subtitle = "The end... it's begun..."
        },
        [51010801] = {
          ContentKR = "어머, 이 꽃이 오늘 옷차림이랑 잘 어울리시네요... 그 아이도 있었다면 똑같이 말했을 거예요.",
          DialogueId = 51010801,
          GUID = "7FB33F8A",
          NextOptions = {
            [1] = 51010802,
            [2] = 51010803
          },
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here."
        },
        [51010802] = {
          ContentKR = "절 아세요?",
          DialogueId = 51010802,
          GUID = "7FB33FB4",
          NextDialogue = 51010804,
          Subtitle = "Do I know you?"
        },
        [51010803] = {
          ContentKR = "'그 아이'라니, 설마...",
          DialogueId = 51010803,
          GUID = "7FB33FDE",
          NextDialogue = 51010804,
          Subtitle = "\"Your little girl\"... You don't mean...?"
        },
        [51010804] = {
          ContentKR = "제 딸, 프시케요.",
          DialogueId = 51010804,
          GUID = "7FB34008",
          NextDialogue = 51010805,
          SpeakNpcId = 700203,
          Subtitle = "My daughter. Psyche. That was her name."
        },
        [51010805] = {
          ContentKR = "그 아이가 편지에서 '새로 사귄 친구'를 언급한 적이 있거든요. 프시케가 말한 분의 이미지와 너무 닮아서... 제가 착각한 거라면 부디 너그럽게 이해해 주세요.",
          DialogueId = 51010805,
          GUID = "7FB34032",
          NextOptions = {
            [1] = 51010806,
            [2] = 51010807
          },
          SpeakNpcId = 700203,
          Subtitle = "She mentioned a \"new friend\" in her letters. You look just as she described... but forgive me, if I'm mistaken.",
          bForbidSkipOptions = true
        },
        [51010806] = {
          ContentKR = "...제가 어떤 사람이라고 하던가요?",
          DialogueId = 51010806,
          GUID = "7FB3405C",
          NextDialogue = 51010809,
          Subtitle = "...What did she say about me?"
        },
        [51010807] = {
          ContentKR = "...네, 사람 잘못 보셨습니다.",
          DialogueId = 51010807,
          GUID = "7FB34086",
          NextDialogue = 51010808,
          Subtitle = "...You've got the wrong person."
        },
        [51010808] = {
          ContentKR = "(당신은 도망치듯 자리를 떠난다. 그것은 모두의 아픔이었고, 당신은 더 이상 그 상처를 건드리고 싶지 않다.)",
          DialogueId = 51010808,
          GUID = "7FB340B0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(You turn away, almost running. It's a shared, silent wound you're not ready to face.)"
        },
        [51010809] = {
          ContentKR = "아이스레이크 시티에 온 그날로 글로스터 폐광에 들어간 똑똑하고 용감한 분이라고 하더군요. 자기가 본 또래들 중에서 가장 강한 친구라고도 했어요.",
          DialogueId = 51010809,
          GUID = "7FB340DA",
          NextDialogue = 51010810,
          SpeakNpcId = 700203,
          Subtitle = "That you're clever. And brave. She said you ventured into Glevum Pit your very first day in Icelake... Of everyone her age, she said you were the strongest. But more importantly..."
        },
        [51010810] = {
          ContentKR = "\"그 친구는 아이스레이크 시티의 대부분 사람들과 달라요. 우리가 진작 잃어버린... 정의와 자유에 대한 갈망을 간직하고 있거든요.\"",
          DialogueId = 51010810,
          GUID = "7FB34104",
          NextDialogue = 51010811,
          SpeakNpcId = 700203,
          Subtitle = "\"{性别:He|She}'s different from most people in Icelake. {性别:He|She} still holds on to something we all lost long ago — a yearning for justice and freedom.\""
        },
        [51010811] = {
          ContentKR = "\"그 친구한테서 전 또 다른 삶을 보게 됐어요.\"",
          DialogueId = 51010811,
          GUID = "7FB3412E",
          NextDialogue = 51010812,
          SpeakNpcId = 700203,
          Subtitle = "\"Being with {性别:him|her} shows me there's a different way to live.\""
        },
        [51010812] = {
          ContentKR = "편지에 그렇게 적혀 있었어요.",
          DialogueId = 51010812,
          GUID = "7FB34158",
          NextDialogue = 51010813,
          SpeakNpcId = 700203,
          Subtitle = "That's what she wrote. Word for word."
        },
        [51010813] = {
          ContentKR = "(여인은 그 편지를 수도 없이 반복해 읽은 듯 능숙하게 문장을 되뇐다.)",
          DialogueId = 51010813,
          GUID = "7FB34182",
          NextDialogue = 51010814,
          Subtitle = "(She recites it by heart — clearly, she's read that letter more times than she can count.)"
        },
        [51010814] = {
          ContentKR = "죄송해요, 전...",
          DialogueId = 51010814,
          GUID = "7FB341AC",
          NextDialogue = 51010815,
          SpeakNpcId = 100001,
          Subtitle = "I'm so sorry. I couldn't..."
        },
        [51010815] = {
          ContentKR = "사과는 안 해도 돼요. 프시케는 당신이 마지막까지 함께해줘서 분명 행복했을 거예요. 그거면 돼요. 오히려 우리가 감사할 일이죠.",
          DialogueId = 51010815,
          GUID = "7FB341D6",
          NextDialogue = 51010816,
          SpeakNpcId = 700203,
          Subtitle = "Don't apologise, child. I could see it. She was happy, with you by her side. That's all we could've asked for. It's us who should be thanking you."
        },
        [51010816] = {
          ContentKR = "이 꽃다발 받아요. 우리의 축복이 늘 당신과 함께하길 바라요.",
          DialogueId = 51010816,
          GUID = "7FB34200",
          SpeakNpcId = 700203,
          Subtitle = "Please, take these flowers. Our blessings go with you."
        },
        [51010817] = {
          ContentKR = "모든 게 순조롭길, 우리의 축복이 늘 당신과 함께하길 바라요.",
          DialogueId = 51010817,
          GUID = "7FB3422A",
          SpeakNpcId = 700203,
          Subtitle = "Travel safe. Our blessings go with you."
        },
        [51010901] = {
          ContentKR = "우리 농장 과일이라 하는 말이 아니라 이런 기술로 키우는 데는 어디에도 없다니까요!",
          DialogueId = 51010901,
          GUID = "7FB34FF2",
          NextDialogue = 51010902,
          SpeakNpcId = 700009,
          Subtitle = "Come try these fine fruits from our orchard — grown with unmatched cultivation techniques!"
        },
        [51010902] = {
          ContentKR = "과일 좀 드셔보실래요? 좋은 씨앗에 최고급 비료로 저희 온실에서 정성껏 키운 거랍니다. 영양도 풍부하고 맛도 정말 좋아요!",
          DialogueId = 51010902,
          GUID = "7FB3501C",
          NextOptions = {
            [1] = 51010903,
            [2] = 51010905
          },
          SpeakNpcId = 700009,
          Subtitle = "Fancy a few? Finest seeds, top-tier fertiliser — all greenhouse-grown, right here. Full of flavour and packed with goodness!"
        },
        [51010903] = {
          ContentKR = "온실에서 재배한 과일이라면 굉장히 비싸겠네요.",
          DialogueId = 51010903,
          GUID = "7FB35046",
          ImprPlusId = 1001,
          NextDialogue = 51010904,
          Subtitle = "Greenhouse-grown? Must cost a fair bit."
        },
        [51010904] = {
          ContentKR = "과일마다 다르죠. 그래도 좋은 과일 먹는 것 자체가 얼마나 힘든 일인데요. 저도 전엔 전쟁터에 있었을 땐 꿈도 못 꿨다니까요.",
          DialogueId = 51010904,
          GUID = "7FB35070",
          NextOptions = {
            [1] = 51010907
          },
          SpeakNpcId = 700009,
          Subtitle = "Depends on the fruit. Just getting a bite of something decent is rare enough. Back on the front, I never saw any of this."
        },
        [51010905] = {
          ContentKR = "온실 재배 기술을 익히기가 쉽지 않았을 텐데요.",
          DialogueId = 51010905,
          GUID = "7FB3509A",
          ImprPlusId = 1003,
          NextDialogue = 51010906,
          Subtitle = "Must be tricky learning how to raise things in a greenhouse."
        },
        [51010906] = {
          ContentKR = "저희 할아버지께서 전수해 주셨어요. 처음에는 가업을 물려받을 생각이 전혀 없었지만, 제대한 후로 생각이 바뀌었죠.",
          DialogueId = 51010906,
          GUID = "7FB350C4",
          NextOptions = {
            [1] = 51010907
          },
          SpeakNpcId = 700009,
          Subtitle = "It's my grandpa's technique. Didn't want anything to do with it at first... but after I left the army, I came around."
        },
        [51010907] = {
          ContentKR = "군인이셨어요?",
          DialogueId = 51010907,
          GUID = "7FB350EE",
          NextDialogue = 51010908,
          Subtitle = "You served?"
        },
        [51010908] = {
          ContentKR = "그럼요, 혼자서 세 명 몫은 거뜬히 해내는 군인이었죠!",
          DialogueId = 51010908,
          GUID = "7FB35118",
          NextDialogue = 51010909,
          SpeakNpcId = 700009,
          Subtitle = "That's me! One soldier, work of three. Top of my unit!"
        },
        [51010909] = {
          ContentKR = "그러다 다치고 나니 몸이 점점 안 따라주더라고요. 그래서 결국 조기 제대했어요.",
          DialogueId = 51010909,
          GUID = "7FB35142",
          NextDialogue = 51010910,
          SpeakNpcId = 700009,
          Subtitle = "But I got injured and couldn't keep up anymore, so I took an early discharge."
        },
        [51010910] = {
          ContentKR = "알고 보니, 그냥 과일 열심히 키우고, 좋은 사람 만나서 조용히 살아가는 삶도 큰 행복이더군요.",
          DialogueId = 51010910,
          GUID = "7FB3516C",
          NextOptions = {
            [1] = 51010911
          },
          RestartTag = 51010910,
          SpeakNpcId = 700009,
          Subtitle = "These days, I've learned. It's the quiet life that really matters. Grow good fruit... meet a good lass... sounds like a fine life to me."
        },
        [51010911] = {
          ContentKR = "마음에 둔 분은 있나요?",
          DialogueId = 51010911,
          FailDialogue = 51010912,
          GUID = "7FB35196",
          ImprCheckId = 1075,
          NextDialogue = 51010914,
          Subtitle = "Anyone caught your eye?"
        },
        [51010912] = {
          ContentKR = "(남자는 잠시 말문이 막힌 듯 어버버하다가 힘겹게 말을 내뱉는다.)",
          DialogueId = 51010912,
          GUID = "7FB351C0",
          NextDialogue = 51010913,
          Subtitle = "(The man is speechless. He opens his mouth awkwardly, struggling to find the words.)"
        },
        [51010913] = {
          ContentKR = "그, 그건 묻지 말아 주세요. 참, 제, 제가 좋은 과일로 골라 드릴게요.",
          DialogueId = 51010913,
          GUID = "7FB351EA",
          SpeakNpcId = 700009,
          Subtitle = "Ah, best not to ask. Er, how about you take a proper look at the fruit? I'll help you pick some out."
        },
        [51010914] = {
          ContentKR = "(남자의 눈동자가 잠시 반짝이더니, 자신도 모르게 미소 짓다가 금세 당혹스러운 표정을 한다.)",
          DialogueId = 51010914,
          GUID = "7FB35214",
          NextDialogue = 51010915,
          Subtitle = " (A flicker of light dances in his eyes and a smile plays on his lips, but it quickly gives way to confusion.)"
        },
        [51010915] = {
          ContentKR = "...있긴 한데요, 아직 뒷모습밖에 본 적이 없어요.",
          DialogueId = 51010915,
          GUID = "7FB3523E",
          NextDialogue = 51010916,
          SpeakNpcId = 700009,
          Subtitle = "...Well, there is someone. But I've only ever seen her from behind."
        },
        [51010916] = {
          ContentKR = "이렇게 오래도록 말 한마디도 못 나눴어요. 휴...",
          DialogueId = 51010916,
          GUID = "7FB35268",
          NextDialogue = 51010917,
          SpeakNpcId = 700009,
          Subtitle = "All this time, and I still haven't said a single word to her."
        },
        [51010917] = {
          ContentKR = "괜히 갑자기 말 걸면 놀랄까 봐서, 건물주 루나한테 대신 전해달라고 부탁했거든요. 근데 어쩜 그렇게 타이밍이 안 맞는지... 매번 집에 없더라고요.",
          DialogueId = 51010917,
          GUID = "7FB35292",
          NextOptions = {
            [1] = 51010918
          },
          SpeakNpcId = 700009,
          Subtitle = "I'm worried I'll scare her off if I just go up to her. So, I asked Lunolaze to pass on a message. But I've got the worst luck. Every time Lunolaze goes, she's not in."
        },
        [51010918] = {
          ContentKR = "겉으론 털털해 보여도, 상대를 존중하는 마음이 보이네요.",
          DialogueId = 51010918,
          GUID = "7FB352BC",
          ImprPlusId = 1002,
          NextDialogue = 51010919,
          Subtitle = "You're direct — and I appreciate the thoughtfulness behind it."
        },
        [51010919] = {
          ContentKR = "하하, 그런 칭찬을 들으니 쑥스럽네요.",
          DialogueId = 51010919,
          GUID = "7FB352E6",
          NextDialogue = 51010920,
          SpeakNpcId = 700009,
          Subtitle = "Haha, now you're just embarrassing me."
        },
        [51010920] = {
          ContentKR = "딱 봐도 많이 배우신 분 같은데, 제가 쓴 이 어설픈 문장 좀 다듬어주실 수 있을까요? 제가 글재주가 없어서요.",
          DialogueId = 51010920,
          GUID = "7FB35310",
          NextOptions = {
            [1] = 51010921
          },
          SpeakNpcId = 700009,
          Subtitle = "Say... you look like you know your way around words. Mind helping a rough fellow like me clean up a line or two? Can't seem to get it right."
        },
        [51010921] = {
          ContentKR = "마침 한가한데 그럼 한 번 들려주세요.",
          DialogueId = 51010921,
          GUID = "7FB3533A",
          NextDialogue = 51010922,
          Subtitle = "Please, go ahead. I'm ready to listen."
        },
        [51010922] = {
          ContentKR = "흠흠.",
          DialogueId = 51010922,
          GUID = "7FB35364",
          NextDialogue = 51010923,
          SpeakNpcId = 700009,
          Subtitle = "Ahem."
        },
        [51010923] = {
          ContentKR = "\"당신을 향한 내 마음은 날이 갈수록 더 뜨거워져요. 겨울 온실보다도 더 따뜻하죠.\"",
          DialogueId = 51010923,
          GUID = "7FB3538E",
          NextOptions = {
            [1] = 51010924
          },
          SpeakNpcId = 700009,
          Subtitle = "\"My feelings for you keep growing warmer. Warmer than a greenhouse in the dead of winter.\""
        },
        [51010924] = {
          ContentKR = "......",
          DialogueId = 51010924,
          GUID = "7FB353B8",
          NextDialogue = 51010925,
          Subtitle = "..."
        },
        [51010925] = {
          ContentKR = "\"당신은 언제쯤 알아줄까요? 내 마음은 과일처럼, 그대가 따러 와주기만을 기다리고 있어요.\"",
          DialogueId = 51010925,
          GUID = "7FB353E2",
          NextDialogue = 51010926,
          SpeakNpcId = 700009,
          Subtitle = "\"When will you see that my heart is like a ripe fruit, just waiting to be picked?\""
        },
        [51010926] = {
          ContentKR = "\"날 받아주세요, 내 사랑. 제발 이 마음이 썩은 과일처럼 땅바닥에 버려지지 않게 해줘요.\"",
          DialogueId = 51010926,
          GUID = "7FB3540C",
          NextDialogue = 51010927,
          SpeakNpcId = 700009,
          Subtitle = "\"Please accept me, my dear! Don't let my love rot on the ground like fallen fruit.\""
        },
        [51010927] = {
          ContentKR = "...어떤가요? 다듬을 만한 곳이 있나요?",
          DialogueId = 51010927,
          GUID = "7FB35436",
          NextOptions = {
            [1] = 51010928
          },
          SpeakNpcId = 700009,
          Subtitle = "...So, what do you reckon? Anything I can improve?"
        },
        [51010928] = {
          ContentKR = "...개성 있고 진솔한 글이네요. 지금 그대로가 좋을 것 같아요.",
          DialogueId = 51010928,
          GUID = "7FB35460",
          NextDialogue = 51010929,
          Subtitle = "They're very... you. And very sincere. I'd say leave them just as they are."
        },
        [51010929] = {
          ContentKR = "정말요? 그럼 다행이네요. 좋은 말씀 감사합니다.",
          DialogueId = 51010929,
          GUID = "7FB3548A",
          NextDialogue = 51010930,
          SpeakNpcId = 700009,
          Subtitle = "Really? That's brilliant! I'll take that as a good sign."
        },
        [51010930] = {
          ContentKR = "제 마음이 결실을 맺는다면 나중에 과일을 사러 오실 때 아주 싸게 드리겠습니다, 하하.",
          DialogueId = 51010930,
          GUID = "7FB354B4",
          SpeakNpcId = 700009,
          Subtitle = "If it works out, swing by for some fruit. I'll give you the biggest discount ever, haha!"
        },
        [51010931] = {
          ContentKR = "아직 그쪽 답은 없어서요... 휴, 파격 할인은 조금 더 기다리셔야겠네요.",
          DialogueId = 51010931,
          GUID = "7FB354DE",
          SpeakNpcId = 700009,
          Subtitle = "She still hasn't replied... so that discount'll have to wait, I'm afraid."
        },
        [51011001] = {
          ContentKR = "잠시만요, 갑자기 말을 걸어 죄송합니다.",
          DialogueId = 51011001,
          GUID = "7FB3605A",
          NextDialogue = 51011002,
          SpeakNpcId = 700008,
          Subtitle = "Ah, pardon me! Forgive the sudden interruption."
        },
        [51011002] = {
          ContentKR = "저희 가게의 옷에 영혼이 깃들어 있다면, 꼭 당신처럼 멋진 분께 입혀지길 바랄 거예요.",
          DialogueId = 51011002,
          GUID = "7FB36084",
          NextDialogue = 51011003,
          SpeakNpcId = 700008,
          Subtitle = "It's just... if my garments had thoughts, they'd be begging to be worn by someone as elegant as you."
        },
        [51011003] = {
          ContentKR = "이대로 당신을 지나친다면, 옷들이 분명 슬퍼할 거예요.",
          DialogueId = 51011003,
          GUID = "7FB360AE",
          NextDialogue = 51011004,
          SpeakNpcId = 700008,
          Subtitle = "I couldn't bear to let you simply walk past — they'd be heartbroken."
        },
        [51011004] = {
          ContentKR = "(눈앞의 남자는 귀족처럼 우아한 분위기로, 말투와 몸짓에 품위가 느껴진다. 포근한 눈웃음은 봄바람처럼 따뜻하다.)",
          DialogueId = 51011004,
          GUID = "7FB360D8",
          NextOptions = {
            [1] = 51011005,
            [2] = 51011006
          },
          Subtitle = "(The man before you carries himself with an aristocratic air. He's slender yet poised, with warm, smiling eyes that instantly put you at ease.)"
        },
        [51011005] = {
          ContentKR = "제가 감당할 수 있는 가격일까요?",
          DialogueId = 51011005,
          GUID = "7FB36102",
          ImprPlusId = 1001,
          NextDialogue = 51011007,
          Subtitle = "Can I actually afford anything in here?"
        },
        [51011006] = {
          ContentKR = "전 마대 자루를 걸쳐도 충분히 소화할 수 있어요.",
          DialogueId = 51011006,
          GUID = "7FB3612C",
          ImprPlusId = 1005,
          NextDialogue = 51011007,
          Subtitle = "Please. I could make a potato sack look dashing."
        },
        [51011007] = {
          ContentKR = "그럼요. 이건 가게 카탈로그예요. 마음에 드는 디자인이 있으면 얼마든지 입어보셔도 돼요.",
          DialogueId = 51011007,
          GUID = "7FB36156",
          NextDialogue = 51011008,
          SpeakNpcId = 700008,
          Subtitle = "Of course. Do browse our catalogue. If anything catches your eye, you're more than welcome to try it on."
        },
        [51011008] = {
          ContentKR = "(카탈로그에 기록된 디자인이 너무 많아서 무엇부터 봐야 할지 고민될 정도다.)",
          DialogueId = 51011008,
          GUID = "7FB36180",
          NextDialogue = 51011009,
          Subtitle = "(You take the catalogue he offers. It's filled with a dazzling array of designs.)"
        },
        [51011009] = {
          ContentKR = "(이제 삶을 즐겨보는 건 어떨까? 우선 새 옷부터 사는 게 좋겠다. 당신은 화려한 색상의 {性别:치마|옷}을 가리킨다.)",
          DialogueId = 51011009,
          GUID = "7FB361AA",
          NextDialogue = 51011010,
          Subtitle = "(Time to treat yourself. And a new {dress|outfit} feels like the perfect place to start. You point to a vibrant piece.)"
        },
        [51011010] = {
          ContentKR = "{性别:죄송합니다. 이건 여성복인 데다, 제 사이즈에 맞춰 제작된 옷이라 고객님께 맞는 사이즈가 없네요...|아쉽게도 이 옷은 제 치수에 맞춰 만든 거라, 손님께 맞는 사이즈가 없네요...}",
          DialogueId = 51011010,
          GUID = "7FB361D4",
          NextOptions = {
            [1] = 51011011
          },
          RestartTag = 51011010,
          SpeakNpcId = 700008,
          Subtitle = "{性别:I must apologise. That's a ladies' piece, made to my own size. Not available in yours, I'm afraid.|What a pity. That one was made to my own measurements, so it's not available in your size.}"
        },
        [51011011] = {
          ContentKR = "전 이 옷이 마음에 들어요. 스타일을 참고할 수 있게 그쪽이 한번 입어봐 주실래요?",
          DialogueId = 51011011,
          FailDialogue = 51011012,
          GUID = "7FB361FE",
          ImprCheckId = 1076,
          NextDialogue = 51011013,
          Subtitle = "But that's the one I want. Why don't you model it for me?"
        },
        [51011012] = {
          ContentKR = "하하, 농담을 잘하시는 분이네요.",
          DialogueId = 51011012,
          GUID = "7FB36228",
          SpeakNpcId = 700008,
          Subtitle = "Come now, don't mock me so."
        },
        [51011013] = {
          ContentKR = "꼭 보시겠다면... 안 될 것도 없지만, 지금 이 옷으로 갈아입으면 불필요한 오해를 살지도 몰라요.",
          DialogueId = 51011013,
          GUID = "7FB36252",
          NextDialogue = 51011014,
          SpeakNpcId = 700008,
          Subtitle = "Well, if you truly insist... though putting it on now might cause... complications."
        },
        [51011014] = {
          ContentKR = "여자로 오해받을까 봐 걱정되시는 건가요?",
          DialogueId = 51011014,
          GUID = "7FB3627C",
          NextDialogue = 51011015,
          SpeakNpcId = 100001,
          Subtitle = "You'll be mistaken for a woman?"
        },
        [51011015] = {
          ContentKR = "맞긴 한데... 중요한 건 '여자로 착각했다'가 아니라, '착각한 다음에 무슨 일이 생기느냐'예요.",
          DialogueId = 51011015,
          GUID = "7FB362A6",
          NextDialogue = 51011016,
          SpeakNpcId = 700008,
          Subtitle = "Precisely, but that's only half of it. The problem isn't being mistaken for a lady, it's what happens as a result."
        },
        [51011016] = {
          ContentKR = "말로 설명하기 좀 그렇긴 한데...",
          DialogueId = 51011016,
          GUID = "7FB362D0",
          NextDialogue = 51011017,
          SpeakNpcId = 700008,
          Subtitle = "It's rather difficult to put into words..."
        },
        [51011017] = {
          ContentKR = "설마... 당신을 여자로 오해하고 반한 사람이라도 있는 건가요?!",
          DialogueId = 51011017,
          GUID = "7FB362FA",
          NextDialogue = 51011018,
          SpeakNpcId = 100001,
          Subtitle = "Don't tell me... someone mistook you for a woman and fell for you?!"
        },
        [51011018] = {
          ContentKR = "아, 현명하신 분이라 설명할 수고를 덜었네요.",
          DialogueId = 51011018,
          GUID = "7FB36324",
          NextDialogue = 51011019,
          SpeakNpcId = 700008,
          Subtitle = "Oh, thank heavens you're so sharp. That saves me quite the explanation."
        },
        [51011019] = {
          ContentKR = "그 순애보 씨는 저한테 미모의 여동생이 있다고 굳게 믿고 있더군요. 실제와는 완전히 다른 상황이죠.",
          DialogueId = 51011019,
          GUID = "7FB3634E",
          NextDialogue = 51011020,
          SpeakNpcId = 700008,
          Subtitle = "However, this devoted gentleman appears to have invented a reality where I have a beautiful younger sister."
        },
        [51011020] = {
          ContentKR = "어느 날 귀여운 루나 아가씨가 가게에 찾아와 상대방의 편지를 구구절절 읽기 전까진, 제 행동이 오해를 불러일으켰다는 것조차 몰랐답니다.",
          DialogueId = 51011020,
          GUID = "7FB36378",
          NextDialogue = 51011021,
          SpeakNpcId = 700008,
          Subtitle = "I hadn't the faintest about the misunderstanding I caused until a sweet Luno turned up at my shop and dramatically recited his love letters to me."
        },
        [51011021] = {
          ContentKR = "그래서 매번 루나 아가씨가 대신 고백을 전하러 올 때마다, 여동생이 외출했다는 거짓말로 둘러댈 수밖에 없었어요.",
          DialogueId = 51011021,
          GUID = "7FB363A2",
          NextDialogue = 51011022,
          SpeakNpcId = 700008,
          Subtitle = "Every time he sends that poor Luno to deliver his love, I have to claim my \"sister\" is out on some errands. It's become routine."
        },
        [51011022] = {
          ContentKR = "왜 사실대로 말하지 않은 거죠?",
          DialogueId = 51011022,
          GUID = "7FB363CC",
          NextDialogue = 51011023,
          SpeakNpcId = 100001,
          Subtitle = "Then why not just tell him the truth?"
        },
        [51011023] = {
          ContentKR = "왜라니... 재밌으니까요?",
          DialogueId = 51011023,
          GUID = "7FB363F6",
          NextDialogue = 51011024,
          SpeakNpcId = 700008,
          Subtitle = "Why? Because... it's rather fun, isn't it?"
        },
        [51011024] = {
          ContentKR = "\"당신의 예쁜 스카프는 우리 농장의 아이스베리처럼 싱그럽고 매혹적이에요.\"",
          DialogueId = 51011024,
          GUID = "7FB36420",
          NextDialogue = 51011025,
          SpeakNpcId = 700008,
          Subtitle = "\"Your lovely headscarf, as sweet and tempting as the borealberries in my garden.\""
        },
        [51011025] = {
          ContentKR = "\"불꽃처럼 붉은 당신의 드레스는 불의 근원처럼 뜨거워서, 절 긴장하게 만들어요.\"",
          DialogueId = 51011025,
          GUID = "7FB3644A",
          NextDialogue = 51011026,
          SpeakNpcId = 700008,
          Subtitle = "\"Your scarlet dress burns as hotly as a flame root, making me sweat with nerves.\""
        },
        [51011026] = {
          ContentKR = "제가 어떤 옷차림을 하든, 이틀 뒤면 항상 제 코디에 대한 평가를 해주더라고요.",
          DialogueId = 51011026,
          GUID = "7FB36474",
          NextDialogue = 51011027,
          SpeakNpcId = 700008,
          Subtitle = "Whatever I wear, two days later, a review in that same peculiar style arrives."
        },
        [51011027] = {
          ContentKR = "말투는 좀... 투박하지만, 은근히 참고가 되어서요.",
          DialogueId = 51011027,
          GUID = "7FB3649E",
          NextDialogue = 51011028,
          SpeakNpcId = 700008,
          Subtitle = "His metaphors may be a tad... rustic, but they're oddly insightful critiques."
        },
        [51011028] = {
          ContentKR = "이 말투, 뭔가 익숙한데...",
          DialogueId = 51011028,
          GUID = "7FB364C8",
          NextDialogue = 51011029,
          SpeakNpcId = 100001,
          Subtitle = "That style sounds quite familiar..."
        },
        [51011029] = {
          ContentKR = "설마 그 순애보 씨랑 아는 사이세요? 그렇다면 이 비밀을 꼭 지켜주셔야 해요.",
          DialogueId = 51011029,
          GUID = "7FB364F2",
          NextDialogue = 51011030,
          SpeakNpcId = 700008,
          Subtitle = "You know that poor romantic soul? Then I must ask — do keep this between us."
        },
        [51011030] = {
          ContentKR = "그냥 새로 디자인한 옷을 평가해 줄 공짜 도구가 필요했던 거잖아요...",
          DialogueId = 51011030,
          GUID = "7FB3651C",
          NextDialogue = 51011031,
          SpeakNpcId = 100001,
          Subtitle = "So you're just using him for free design critiques, is that it?"
        },
        [51011031] = {
          ContentKR = "\"그 진실한 분이 내일은 또 어떤 새롭고 기발한 비유로 내 옷을 표현하려나?\" 손님도 이런 일을 겪는다면 같은 호기심이 생기지 않을까요?",
          DialogueId = 51011031,
          GUID = "7FB36546",
          NextDialogue = 51011032,
          SpeakNpcId = 700008,
          Subtitle = "\"What new metaphor will this earnest man dream up for my clothes tomorrow?\" Honestly, if you were in my shoes, wouldn't you be just as curious?"
        },
        [51011032] = {
          ContentKR = "다만 요샌 그분의 말투가 예전만 못해요. 잡히지 않는 꿈 앞에서 망설이는 사람처럼요.",
          DialogueId = 51011032,
          GUID = "7FB36570",
          NextDialogue = 51011033,
          SpeakNpcId = 700008,
          Subtitle = "Lately, though, his words have become less direct. Hesitant, as if he's having doubts about some elusive dream..."
        },
        [51011033] = {
          ContentKR = "너무 밀어내진 말고, 타이밍 봐서 살짝 반응해 줄까 봐요. 그래야 포기하지 않겠죠?",
          DialogueId = 51011033,
          GUID = "7FB3659A",
          NextDialogue = 51011034,
          SpeakNpcId = 700008,
          Subtitle = "Perhaps I should offer a subtle reply at just the right moment? Enough to keep his interest, without letting him get too close."
        },
        [51011034] = {
          ContentKR = "완전히 이 상황을 즐기고 있잖아요...",
          DialogueId = 51011034,
          GUID = "7FB365C4",
          SpeakNpcId = 100001,
          Subtitle = "You're absolutely revelling in this, aren't you..."
        },
        [51011035] = {
          ContentKR = "아, 당신이었군요. 그 비밀은 꼭 지켜주세요. 보답으로 저희 가게에 오시면 평생 할인해 드릴게요.",
          DialogueId = 51011035,
          GUID = "7FB365EE",
          SpeakNpcId = 700008,
          Subtitle = "Ah, it's you. Do keep the secret between us, won't you? In return, your discount here will be permanent."
        },
        [51011101] = {
          ContentKR = "이야, 사장님들 열심히 일하시네!",
          DialogueId = 51011101,
          GUID = "7FB370C2",
          NextDialogue = 51011102,
          SpeakNpcId = 700336,
          Subtitle = "Blimey, everyone's working so hard!"
        },
        [51011102] = {
          ContentKR = "난 햇볕 쬐기랑 자는 것밖에 할 줄 모르는데...",
          DialogueId = 51011102,
          GUID = "7FB370EC",
          NextOptions = {
            [1] = 51011103,
            [2] = 51011104,
            [3] = 51011105
          },
          SpeakNpcId = 700336,
          Subtitle = "Unlike me... I just snooze in the sun."
        },
        [51011103] = {
          ContentKR = "누구나 자기만의 삶의 방식이 있는 법이야.",
          DialogueId = 51011103,
          GUID = "7FB37116",
          ImprPlusId = 1002,
          NextDialogue = 51011106,
          Subtitle = "Everyone lives life their own way."
        },
        [51011104] = {
          ContentKR = "햇볕이나 쬐고 잠이나 자는 게 인생이지!",
          DialogueId = 51011104,
          GUID = "7FB37140",
          ImprPlusId = 1004,
          NextDialogue = 51011106,
          Subtitle = "Napping in the sun — now that's living!"
        },
        [51011105] = {
          ContentKR = "햇볕을 쬐고 잠을 자는 건 건강에 대한 장기 투자야.",
          DialogueId = 51011105,
          GUID = "7FB3716A",
          ImprPlusId = 1003,
          NextDialogue = 51011106,
          Subtitle = "It's a long-term investment in your health, isn't it?"
        },
        [51011106] = {
          ContentKR = "오, 뭘 좀 아는데.",
          DialogueId = 51011106,
          GUID = "7FB37194",
          NextDialogue = 51011107,
          SpeakNpcId = 700336,
          Subtitle = "Haha, you really get it."
        },
        [51011107] = {
          ContentKR = "근데 일을 안 하니까 어쩐지 죄책감이 느껴지긴 해. 봐봐, 다들 열심히 돈을 벌고 있는데 난 놀고 먹는데도 이렇게 부자라니, 뭔가 미안해지잖아...",
          DialogueId = 51011107,
          GUID = "7FB371BE",
          NextDialogue = 51011108,
          SpeakNpcId = 700336,
          Subtitle = "Still, I can't help feeling a bit guilty. Seeing them all working so hard to get by while I just lounge about, flush with cash... It just doesn't feel right."
        },
        [51011108] = {
          ContentKR = "루나는 사람을 돕지 않으면 온몸이 근질근질하고 마음이 불안해지거든, 휴...",
          DialogueId = 51011108,
          GUID = "7FB371E8",
          NextOptions = {
            [1] = 51011109
          },
          RestartTag = 51011108,
          SpeakNpcId = 700336,
          Subtitle = "A Luno's gotta help people. I get antsy if I'm not helping someone. It feels off."
        },
        [51011109] = {
          ContentKR = "(건물주 루나에게 부자가 되는 비결에 대해 묻는다.)",
