          ContentKR = "종말이 오고 있어... 종말이...",
          DialogueId = 51011601,
          GUID = "7FB3C2CA",
          SpeakNpcId = 700337,
          Subtitle = "The end draws near... it draws near..."
        },
        [51011701] = {
          ContentKR = "이야, 사장님들 열심히 일하시네!",
          DialogueId = 51011701,
          GUID = "7FB3D332",
          SpeakNpcId = 700336,
          Subtitle = "Blimey, everyone's working so hard!"
        },
        [51011801] = {
          ContentKR = "......",
          DialogueId = 51011801,
          GUID = "7FB3E39A",
          SpeakNpcId = 700339,
          Subtitle = "..."
        },
        [51011901] = {
          ContentKR = "저리 가… 난 아무것도 모른다니까!",
          DialogueId = 51011901,
          GUID = "7FB3F402",
          SpeakNpcId = 700341,
          Subtitle = "Stay away from me... I don't know anything!!"
        },
        [51012001] = {
          ContentKR = "...조용히 해 봐. 이 계단, 아직 안 닦았으니까.",
          DialogueId = 51012001,
          GUID = "7FB4046A",
          SpeakNpcId = 700340,
          Subtitle = "...Quiet, please. These stairs... they are not clean yet."
        },
        [51012101] = {
          ContentKR = "냥... 냥냥!",
          DialogueId = 51012101,
          GUID = "7FB414D2",
          NextDialogue = 51012102,
          SpeakNpcId = 700334,
          Subtitle = "Meow, meowww! "
        },
        [51012102] = {
          ContentKR = "(먼 곳에서 길고양이가 흥분한 듯 야옹거리며 나에게 달려온다.)",
          DialogueId = 51012102,
          GUID = "7FB414FC",
          NextDialogue = 51012103,
          Subtitle = "(Spotting you from afar, the stray cat meows in delight, bouncing its way towards you.)"
        },
        [51012103] = {
          ContentKR = "야옹.",
          DialogueId = 51012103,
          GUID = "7FB41526",
          NextDialogue = 51012104,
          SpeakNpcId = 700334,
          Subtitle = "Meow."
        },
        [51012104] = {
          ContentKR = "(기운이 넘쳐 보여서, 같이 놀거나 먹을 것을 줄 사람이 필요한 것 같지는 않다. 녀석은 내 발치를 두 바퀴 돈 뒤 휴식처 방향으로 뛰어갔다가, 다시 나를 돌아본다. 자기를 따라오라는 뜻 같다.)",
          DialogueId = 51012104,
          GUID = "7FB41550",
          NextOptions = {
            [1] = 51012105,
            [2] = 51012106
          },
          Subtitle = "(The cat looks so full of life, needing neither your playtime nor the food. Instead, it twirls around you, then darts towards Sanctuary — glancing back at you, as if inviting you to come along.)"
        },
        [51012105] = {
          ContentKR = "(따라가 보자.)",
          DialogueId = 51012105,
          GUID = "7FB4157A",
          Subtitle = "(Follow the cat)"
        },
        [51012106] = {
          ContentKR = "(지금은 바쁘다.)",
          DialogueId = 51012106,
          GUID = "7FB415A4",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Maybe later)"
        },
        [51012107] = {
          ContentKR = "(길고양이가 휴식처 근처의 풀숲에서 딱딱한 냉동 생선을 물고 나와, 나에게 고개를 까딱한다. 내게 주는 보답인 것 같다.)",
          DialogueId = 51012107,
          GUID = "7FB415CE",
          NextDialogue = 51012108,
          Subtitle = "(From the grass nearby Sanctuary, the cat drags out a rigid frozen fish. Then, it tilts its head at you, as if saying, “This is my thank-you gift.”)"
        },
        [51012108] = {
          ContentKR = "(냉동 생선을 받아 드니, 생선 입에서 무언가 또르르 굴러 나온다. 아, 어둡게 빛나는 쿠퍼다...)",
          DialogueId = 51012108,
          GUID = "7FB415F8",
          NextDialogue = 51012109,
          Subtitle = "(You pick up this frozen fish, and clink, clink — a few coins slip from its mouth, shining dimly.)"
        },
        [51012109] = {
          ContentKR = "내 냄새를 기억해서, 나한테 선물을 준 거니?",
          DialogueId = 51012109,
          GUID = "7FB41622",
          NextDialogue = 51012110,
          SpeakNpcId = 100001,
          Subtitle = "You remembered my scent, didn't you? And, brought me a gift in return?"
        },
        [51012110] = {
          ContentKR = "야옹——",
          DialogueId = 51012110,
          GUID = "7FB4164C",
          NextDialogue = 51012111,
          SpeakNpcId = 700335,
          Subtitle = "Meowww—"
        },
        [51012111] = {
          ContentKR = "(길고양이는 그 말을 알아들었다는 듯, 길게 울음소리를 낸 뒤, 다정하게 머리를 내 발에 비빈다.)",
          DialogueId = 51012111,
          GUID = "7FB41676",
          NextOptions = {
            [1] = 51012112,
            [2] = 51012113
          },
          Subtitle = "(As if understood, the cat lets out a long meow and rubbing its head lovingly against you.)"
        },
        [51012112] = {
          ContentKR = "따뜻한 선물 고마워.",
          DialogueId = 51012112,
          GUID = "7FB416A0",
          ImprPlusId = 1004,
          NextDialogue = 51012114,
          Subtitle = "Thank you for your kindness."
        },
        [51012113] = {
          ContentKR = "더 나은 선물은 없어?",
          DialogueId = 51012113,
          GUID = "7FB416CA",
          ImprPlusId = 1005,
          NextDialogue = 51012114,
          Subtitle = "Is that all? Bring me something truly worthy."
        },
        [51012114] = {
          ContentKR = "(나의 말에 길고양이는 고개를 끄덕인 후, 폴짝거리며 멀리 뛰어간다. 다음번엔 어떤 선물을 가져올지 모르지만, 앞으로 오랫동안 휴식처에서 이 녀석을 자주 볼 수 있을 것 같다.)",
          DialogueId = 51012114,
          GUID = "7FB416F4",
          Subtitle = "(The cat nods and bounces away. You may not know what it'll bring you next time, yet you know you'll see it around at the Sanctuary for a long while.)"
        },
        [51012201] = {
          ContentKR = "(녀석은 휴식처에 머물 생각인 것 같다. 이렇게 된 거, 이름을 지어주자.)",
          DialogueId = 51012201,
          GUID = "7FB4253A",
          Subtitle = "(Looks like it is planning to stay at the Sanctuary. Time to give it a name.)"
        },
        [51012202] = {
          ContentKR = "야옹~ 야옹~",
          DialogueId = 51012202,
          GUID = "7FB42564",
          NextDialogue = 51012203,
          SpeakNpcId = 888888,
          Subtitle = "Meow, Meowww—"
        },
        [51012203] = {
          ContentKR = "(새 이름을 얻은 고양이는 야옹거리며 당신 주위를 빙빙 돈다. {catname}(이)라는 이름이 무척 마음에 드나 보다.)",
          DialogueId = 51012203,
          GUID = "7FB4258E",
          NextDialogue = 51012204,
          Subtitle = "(Hearing its new name, the cat meows and spin cycles around you, showing how much it favors the name {catname}.)"
        },
        [51012204] = {
          ContentKR = "좋아, 그럼 앞으로 네 이름은 {catname}인 거다.",
          DialogueId = 51012204,
          GUID = "7FB425B8",
          SpeakNpcId = 100001,
          Subtitle = "{catname} it is! That'll be your name from now on! "
        },
        [51100001] = {
          ContentKR = "정성이 지극하면 가시밭길도 두렵지 않은 법. 용신께서 굽어살피실지어다. 험난하고 속된 길이라 하여도, 큰 뜻을 위해... 머, 멈추시오, 용의 자손이여! 잠시만 서 보시오!",
          DialogueId = 51100001,
          GUID = "7FEC69EA",
          Subtitle = "With a true heart, no road brings dread — Lord Argent watches o'er me where'er I tread. Though filth and thorns may line the path, to fulfil my vow, I press o—on—Oi! You there — Loongscion! Hold, a moment!"
        },
        [51100002] = {
          ContentKR = "두리번거릴 것 없소. 자네를 부른 것이라오.",
          DialogueId = 51100002,
          GUID = "7FEC6A14",
          NextOptions = {
            [1] = 51100003,
            [2] = 51100006,
            [3] = 51100009
          },
          SpeakNpcId = 700319,
          Subtitle = "No need to peer about — yes, I mean you!"
        },
        [51100003] = {
          ContentKR = "용신께서 어르신을 보살펴 주신다면, 왜 절 불러 세우신 거예요?",
          DialogueId = 51100003,
          GUID = "7FEC6A3E",
          ImprPlusId = 1208,
          NextDialogue = 51100004,
          Subtitle = "If Lord Argent is guarding you, what use have you for me?"
        },
        [51100004] = {
          ContentKR = "크흠, 용신께서는 다망하시다오. 많은 이를 굽어살피시다가, 이 늙은이를 못 보고 지나치실 수도 있지 않겠소?",
          DialogueId = 51100004,
          GUID = "7FEC6A68",
          NextDialogue = 51100005,
          SpeakNpcId = 700319,
          Subtitle = "Ahem... Lord Argent is a busy one — watching over me, and countless others besides. Should Their gaze turns away for but a moment, and I stumble into danger...",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          }
        },
        [51100005] = {
          ContentKR = "하늘의 뜻에 기대기 전에, 사람이 먼저 도리를 다해야 하는 것이오!",
          DialogueId = 51100005,
          GUID = "7FEC6A92",
          NextDialogue = 51100015,
          SpeakNpcId = 700319,
          Subtitle = "One ought to do one's part before leaving all to fate, don't you think?",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          }
        },
        [51100006] = {
          ContentKR = "어르신, 혹시 곤란한 일이라도 있으세요?",
          DialogueId = 51100006,
          GUID = "7FEC6ABC",
          ImprPlusId = 1207,
          NextDialogue = 51100007,
          Subtitle = "Are you in some kind of trouble, sir?"
        },
        [51100007] = {
          ContentKR = "참으로 예의 바른 젊은이구려! 여기서 반나절을 꼬박 서 있었건만, 이 늙은이의 하소연에 귀 기울여주는 이가 아무도 없었다오.",
          DialogueId = 51100007,
          GUID = "7FEC6AE6",
          NextDialogue = 51100008,
          SpeakNpcId = 700319,
          Subtitle = "Ah, such courtesy! I've stood here half the day, and but a rare few would lend an old man their ear.",
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          }
        },
        [51100008] = {
          ContentKR = "다른 건 바라지도 않소. 그저 이 늙은이의 이야기를 끝까지 들어주기만 한다면, 그걸로 족하오이다!",
          DialogueId = 51100008,
          GUID = "7FEC6B10",
          NextDialogue = 51100015,
          SpeakNpcId = 700319,
          Subtitle = "If you'd be so kind as to stay and hear me out properly... well, that'd be even better!",
          TalkActionId = {
            [1] = "700319:Talk02_End"
          }
        },
        [51100009] = {
          ContentKR = "이상하다, 전 죽은 지 한참됐는데... 제가 보이시는 거예요?",
          DialogueId = 51100009,
          GUID = "7FEC6B3A",
          ImprPlusId = 1210,
          NextDialogue = 51100010,
          Subtitle = "Strange... I've been dead for ages. How is it you can still see me?"
        },
        [51100010] = {
          ContentKR = "......",
          DialogueId = 51100010,
          GUID = "7FEC6B64",
          NextDialogue = 51100011,
          SpeakNpcId = 700319,
          Subtitle = "..."
        },
        [51100011] = {
          ContentKR = "............",
          DialogueId = 51100011,
          GUID = "7FEC6B8E",
          NextDialogue = 51100012,
          SpeakNpcId = 700319,
          Subtitle = "......"
        },
        [51100012] = {
          ContentKR = "귀신이다!",
          DialogueId = 51100012,
          GUID = "7FEC6BB8",
          NextDialogue = 51100013,
          SpeakNpcId = 700319,
          Subtitle = "Mercy! A ghost!",
          TalkActionId = {
            [1] = "700319:Shock_Start"
          }
        },
        [51100013] = {
          ContentKR = "농담이었어요. 자, 보세요. 그림자도 있고, 발도 땅에 잘 붙어 있잖아요.",
          DialogueId = 51100013,
          GUID = "7FEC6BE2",
          NextDialogue = 51100014,
          SpeakNpcId = 100001,
          Subtitle = "Kidding. Look — I've got a shadow and both feet on the ground.",
          TalkActionId = {
            [1] = "700319:Shock_End"
          }
        },
        [51100014] = {
          ContentKR = "아이고... 명이 십 년은 준 것 같구려! 앞으로 그런 농담은 삼가시오. 설령 놀라 숨이 끊어진대도, 젊은이에게 내 저금의 행방을 알려주진 않을 터이니!",
          DialogueId = 51100014,
          GUID = "7FEC6C0C",
          NextDialogue = 51100015,
          SpeakNpcId = 700319,
          Subtitle = "Mercy me! You near scared the soul clean out of me! No more jokes like that! Even if I died of fright, I still wouldn't hand over my savings!",
          TalkActionId = {
            [1] = "700319:Explain01_Start"
          }
        },
        [51100015] = {
          ContentKR = "실은, 내가 일이 있어 낙진의 바다에 가야 하는데, 나이가 나이라 여기까지 오는데도 숨이 턱턱 막히더구려!",
          DialogueId = 51100015,
          GUID = "7FEC6C36",
          NextDialogue = 51100016,
          SpeakNpcId = 700319,
          Subtitle = "Truth be told, I must make a journey into the Gritblight Expanse on a personal matter. Yet at my age, why, reaching even this far was trial enough."
        },
        [51100016] = {
          ContentKR = "오는 길에 난데없이 검은 폐안이 나타나 이 늙은이를 해치려 들지 않겠소? 미처 피하지 못해 이젠 죽었구나 했는데, 홀연히 나타난 흰 폐안이 꼬리로 나를 휙 날려 보내줬지 뭐요!",
          DialogueId = 51100016,
          GUID = "7FEC6C60",
          NextDialogue = 51100017,
          SpeakNpcId = 700319,
          Subtitle = "First a Sable Bi'an sprang upon me. I'd made my peace — ready to meet my end — when, lo and behold, an Argent Bi'an sprang in to intervene! One swish of its tail, and I was flung a dozen feet clean!"
        },
        [51100017] = {
          ContentKR = "아이고! 머리부터 발끝까지 안 쑤시는 데가 없소!",
          DialogueId = 51100017,
          GUID = "7FEC6C8A",
          NextDialogue = 51100018,
          SpeakNpcId = 700319,
          Subtitle = "Oh, my head, my neck, my shoulders, my back, my spine, my hips, my arms, my legs!",
          TalkActionId = {
            [1] = "700319:Explain01_End"
          }
        },
        [51100018] = {
          ContentKR = "세월 앞에 장사 없지, 한창때 같았으면 옷 한번 툭 털고 일어나면 그만이었을 것이오. 간이 컸다면, 폐안이 법을 집행할 때 같이 사진이라도 찍어, 며칠은 자랑삼아 떠들고 다녔겠지.",
          DialogueId = 51100018,
          GUID = "7FEC6CB4",
          NextDialogue = 51100019,
          SpeakNpcId = 700319,
          Subtitle = "Time shows mercy to none. In my youth, I'd have dusted myself off — bold lads even posed for pictures mid-enforcement, then bragged for days on end.",
          TalkActionId = {
            [1] = "700319:Sigh_Start"
          }
        },
        [51100019] = {
          ContentKR = "하지만 이 나이가 되면 말이오. 검은 폐안에게 물려 다음 생을 기약하는 게 낫지. 이게 흰 폐안에게 구조된 건지 아니면 매타작을 당한 건지, 삭신이 쑤셔서 한두 달은 앓아눕게 생겼소!",
          DialogueId = 51100019,
          GUID = "7FEC6CDE",
          NextDialogue = 51100020,
          SpeakNpcId = 700319,
          Subtitle = "These days? One bite from a Sable Bi'an and it's straight to the afterlife — clean, at least. But an Argent one saving me? Leaves me half-dead and bedridden for months!",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100020] = {
          ContentKR = "아, 폐안을 탓하는 건 아니니, 오해는 마시오. 만약 무슨 일이 생긴다 한들, 그건 전부 태호님의 뜻 아니겠소! 태호 님의 뜻은 늘 옳지! 아니 그렇소, 젊은이?",
          DialogueId = 51100020,
          GUID = "7FEC6D08",
          NextOptions = {
            [1] = 51100021,
            [2] = 51100023,
            [3] = 51100025
          },
          SpeakNpcId = 700319,
          Subtitle = "Oh, don't mistake me — I lay no blame on our noble protectors! If anything befalls me, well... it's Taihao's will. And They make no mistakes, eh, youngster?"
        },
        [51100021] = {
          ContentKR = "이만 집으로 돌아가시는 게 좋겠어요. 지금 밖은 너무 위험해요.",
          DialogueId = 51100021,
          GUID = "7FEC6D32",
          ImprPlusId = 1207,
          NextDialogue = 51100022,
          Subtitle = "Go home, sir. It's too dangerous out here."
        },
        [51100022] = {
          ContentKR = "나라고 왜 돌아가고 싶지 않겠소. 허나 여기서 발길을 돌린다면, 나는 태호님을 저버린 불경한 자가 되는 것이오!",
          DialogueId = 51100022,
          GUID = "7FEC6D5C",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "Nothing I'd like more — yet to turn back now would be to betray Taihao Themselves!",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100023] = {
          ContentKR = "위험을 무릅쓰고서라도 꼭 가시려는 걸 보면, 굉장히 중요한 일인가 봐요?",
          DialogueId = 51100023,
          GUID = "7FEC6D86",
          ImprPlusId = 1209,
          NextDialogue = 51100024,
          Subtitle = "If you're braving danger like this, then it must be for something that's very important to you."
        },
        [51100024] = {
          ContentKR = "내 속을 훤히 들여다보는구려. 살다 보면, 목에 칼이 들어와도 절대 물러설 수 없는 일이 몇 가지는 있는 법이외다.",
          DialogueId = 51100024,
          GUID = "7FEC6DB0",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "Didn't expect such wisdom from one so young. Aye... there are things in life a man simply cannot back down from.",
          TalkActionId = {
            [1] = "700319:Agree"
          }
        },
        [51100025] = {
          ContentKR = "어쨌든, 결론은 넘어진 김에 저한테 한몫 뜯어내시겠단 거 아니에요?",
          DialogueId = 51100025,
          GUID = "7FEC6DDA",
          ImprPlusId = 1210,
          NextDialogue = 51100026,
          Subtitle = "Cut the crap. You're not faking an injury to shake me down, are you?"
        },
        [51100026] = {
          ContentKR = "당치도 않소! 자해 공갈도 사람을 봐 가면서 하는 것이지, 온몸에 붕대를 감고 돌아다니는 자네 같은 사람을 고를 성싶소!",
          DialogueId = 51100026,
          GUID = "7FEC6E04",
          NextDialogue = 51100027,
          SpeakNpcId = 700319,
          Subtitle = "What rot! If I were out to swindle someone, it wouldn't be you — just look at you! A weary traveller swathed in bandages! What's there to gain?",
          TalkActionId = {
            [1] = "700319:Disagree"
          }
        },
        [51100027] = {
          ContentKR = "어쨌거나, 이 늙은이 혼자서는 낙진의 바다까지 갈 방법이 없소.",
          DialogueId = 51100027,
          GUID = "7FEC6E2E",
          NextDialogue = 51100028,
          SpeakNpcId = 700319,
          Subtitle = "Truth is, I can't reach the Gritblight Expanse on my own."
        },
        [51100028] = {
          ContentKR = "그래서 태호께서 굽어살피시어, 인정 많고 의로우며, 무예 또한 출중하여, 저 바다와 분진을 두려워하지 않고, 나를 안전히 데려다줄 수 있는 용사를 보내 주시길 기다리고 있었소만...",
          DialogueId = 51100028,
          GUID = "7FEC6E58",
          NextDialogue = 51100029,
          SpeakNpcId = 700319,
          Subtitle = "So here I wait, praying Taihao might send me a kind, able soul — one bold enough to brave the Expanse and see me through.",
          TalkActionId = {
            [1] = "700319:Confident_Start"
          }
        },
        [51100029] = {
          ContentKR = "지금 보니, 그 용사는 자네가 틀림없구려!",
          DialogueId = 51100029,
          GUID = "7FEC6E82",
          NextDialogue = 51100030,
          SpeakNpcId = 700319,
          Subtitle = "And clearly, that soul is you!"
        },
        [51100030] = {
          ContentKR = "이게 모두 태호 님의 은총이 아니고 뭐겠소!",
          DialogueId = 51100030,
          GUID = "7FEC6EAC",
          NextDialogue = 51100031,
          SpeakNpcId = 700319,
          Subtitle = "By Taihao's grace! Truly, by Their grace!"
        },
        [51100031] = {
          ContentKR = "하지만 걱정 마시구려. 나도 도리를 아는 사람이오.",
          DialogueId = 51100031,
          GUID = "7FEC6ED6",
          NextDialogue = 51100032,
          SpeakNpcId = 700319,
          Subtitle = "Have no worry — I'll not take your kindness for naught."
        },
        [51100032] = {
          ContentKR = "신께 도움을 청할 땐 공물을 올려야 하듯, 사람에겐 품삯을 치러야 하는 것이 세상의 이치. 날 목적지까지 무사히 데려다준다면, 내 크게 사례하겠소이다!",
          DialogueId = 51100032,
          GUID = "7FEC6F00",
          NextOptions = {
            [1] = 51100033
          },
          RestartTag = 51100032,
          SpeakNpcId = 700319,
          Subtitle = "When you ask the gods for favour, you bring offerings. When you ask a person, you pay your dues. See me there safely, and you'll be well rewarded.",
          TalkActionId = {
            [1] = "700319:Confident_End"
          }
        },
        [51100033] = {
          ContentKR = "굳이 시간과 노력을 들여, 이 노인을 위험한 곳까지 데려다줄 가치가 있을까?",
          DialogueId = 51100033,
          FailDialogue = 51100034,
          GUID = "7FEC6F2A",
          ImprCheckId = 1072,
          NextDialogue = 51100036,
          Subtitle = "Should I really spend time and energy escorting this old man through danger?"
        },
        [51100034] = {
          ContentKR = "(사정은 딱하지만, 지금은 도울 여유가 없다. 나중에 다시 오도록 하자.)",
          DialogueId = 51100034,
          GUID = "7FEC6F54",
          NextDialogue = 51100035,
          Subtitle = "(You've more urgent matters to attend to. Perhaps later.)"
        },
        [51100035] = {
          ContentKR = "태호께서 이 늙은이의 간절한 기도에 응답하실 때까지, 희망의 끈을 놓지 않고 기다릴 것이오...",
          DialogueId = 51100035,
          GUID = "7FEC6F7E",
          SpeakNpcId = 700319,
          Subtitle = "Until Taihao hears my prayer, I'll wait here... hope steady in my heart."
        },
        [51100036] = {
          ContentKR = "역시 태호께서 이 늙은이를 굽어살펴 주실 줄 알았소!",
          DialogueId = 51100036,
          GUID = "7FEC6FA8",
          SpeakNpcId = 700319,
          Subtitle = "I knew it — Taihao has smiled upon me!"
        },
        [51100037] = {
          ContentKR = "원래 낙진의 바다는 이렇게 음산하고 기분 나쁜 곳이에요?",
          DialogueId = 51100037,
          Duration = 4,
          GUID = "7FEC6FD2",
          NextDialogue = 51100038,
          SpeakNpcId = 100001,
          Subtitle = "Has the Gritblight Expanse always been this bleak and frightening?"
        },
        [51100038] = {
          ContentKR = "휴... 사실은 긴 사연이 있다오.",
          DialogueId = 51100038,
          Duration = 2,
          GUID = "7FEC6FFC",
          NextDialogue = 51100039,
          SpeakNpcId = 700319,
          Subtitle = "Ah... that's a tale and a half."
        },
        [51100039] = {
          ContentKR = "아주 먼 옛날, 낙진의 바다는 바위가 숲처럼 늘어선 곳이었다오. 그러나 촉룡의 재앙이 휩쓸고 간 뒤, 이곳은 낙진에 삼켜져 버렸소.",
          DialogueId = 51100039,
          Duration = 8,
          GUID = "7FEC7026",
          NextDialogue = 51100040,
          SpeakNpcId = 700319,
          Subtitle = "Long ago, this was but an ordinary stone forest. Then came the Scourge of Zhuyin, and the Gritblight swallowed it whole."
        },
        [51100040] = {
          ContentKR = "온갖 식물이 검붉은 수정에 뒤덮여 버렸지. 일단 휘감겼다 하면, 마치 호박 속에 갇힌 벌레처럼 생장을 멈추고, 그대로 박제되어 버리는 것이오.",
          DialogueId = 51100040,
          Duration = 10,
          GUID = "7FEC7050",
          NextDialogue = 51100041,
          SpeakNpcId = 700319,
          Subtitle = "All the trees and grasses were wrapped in dark-violet crystal. Once caught, they were like insects in amber — frozen at that moment, life sealed away."
        },
        [51100041] = {
          ContentKR = "어디 식물뿐이겠소. 짐승조차 낙진의 바다에 오래 머물다간 '살아있는 화석' 신세가 되고 만다오.",
          DialogueId = 51100041,
          Duration = 6,
          GUID = "7FEC707A",
          NextDialogue = 51100042,
          SpeakNpcId = 700319,
          Subtitle = "Even the beasts, if they lingered too long, became \"living fossils\"."
        },
        [51100042] = {
          ContentKR = "일설에는, 검은 폐안이 실은 저 낙진에 침식당한 흰 폐안이라는 이야기도 있소...",
          DialogueId = 51100042,
          Duration = 8,
          GUID = "7FEC70A4",
          SpeakNpcId = 700319,
          Subtitle = "Some even whisper the Sable Bi'an were once Argent Bi'an — corrupted by the Gritblight's taint..."
        },
        [51100043] = {
          ContentKR = "이곳은 워낙 인적이 드물어, 오래 머물지만 않는다면, 짐승이나 폐안과 마주칠 염려도 없소. 그래서 내가 지름길로 삼았던 게요.",
          DialogueId = 51100043,
          DisableMouth = 0,
          GUID = "7FEC70CE",
          IsBlack = 0,
          NextDialogue = 51100044,
          SpeakNpcId = 700319,
          Subtitle = "This place is desolate. So long as we don't linger, we're unlikely to cross paths with beasts or Bi'an. That's precisely why I chose this route.",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100044] = {
          ContentKR = "화서 사람들이 말하는 '등잔 밑이 어둡다'는 게, 바로 이런 거네요?",
          DialogueId = 51100044,
          DisableMouth = 0,
          GUID = "7FEC70F8",
          IsBlack = 0,
          NextDialogue = 51100045,
          SpeakNpcId = 100001,
          Subtitle = "It's called \"hiding in plain sight\" in Huaxu, right?",
          bAllowClickSkipScript = false
        },
        [51100045] = {
          ContentKR = "오호라, 뭘 좀 아는구려!",
          DialogueId = 51100045,
          DisableMouth = 0,
          GUID = "7FEC7122",
          IsBlack = 0,
          NextDialogue = 51100046,
          SpeakNpcId = 700319,
          Subtitle = "Hah! Sharp one, aren't you!",
          bAllowClickSkipScript = false
        },
        [51100046] = {
          ContentKR = "솔직히 말하자면, 이 길은 내가 밥 먹듯이 드나들던 곳이라, 이번에 이렇게 된통 당할 줄은 꿈에도 몰랐다오.",
          DialogueId = 51100046,
          DisableMouth = 0,
          GUID = "7FEC714C",
          IsBlack = 0,
          NextDialogue = 51100047,
          SpeakNpcId = 700319,
          Subtitle = "Truth be told, I've cut through here many a time. Never thought I'd take a tumble last time.",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100047] = {
          ContentKR = "어찌 된 영문인지 그날은 이 낙진의 바다가 끝도 없이 넓어진 듯했소. 날이 저물도록 걷고 또 걸어도, 도무지 밖으로 나갈 수가 없었지.",
          DialogueId = 51100047,
          DisableMouth = 0,
          GUID = "7FEC7176",
          IsBlack = 0,
          NextDialogue = 51100048,
          SpeakNpcId = 700319,
          Subtitle = "That day, the Expanse felt vaster than ever. I walked and walked, till nightfall — yet found no way out.",
          bAllowClickSkipScript = false
        },
        [51100048] = {
          ContentKR = "본래도 어두컴컴한 곳인데, 해까지 지고 나니 정말 한 치 앞도 보이지 않더구려. 게다가 늙어서 눈까지 침침하니, 아무리 헤매도 도무지 빠져나갈 방도가 없었소.",
          DialogueId = 51100048,
          DisableMouth = 0,
          GUID = "7FEC71A0",
          IsBlack = 0,
          NextDialogue = 51100049,
          SpeakNpcId = 700319,
          Subtitle = "Even in daylight it's a gloomy place. Once the sun sets, you can scarce see your own hand. With these old eyes, I wandered in circles, lost in the dark.",
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100049] = {
          ContentKR = "결국 기력이 다해 꺼꾸러져 뒤통수를 찧었고... 의식이 희미해져 가는 와중에, 폐안들이 주위를 깡충거리며 맴도는 걸 본 것 같소...",
          DialogueId = 51100049,
          DisableMouth = 0,
          GUID = "7FEC71CA",
          IsBlack = 0,
          NextDialogue = 51100050,
          SpeakNpcId = 700319,
          Subtitle = "At last I toppled, struck the back of my skull. In the haze, I swear I saw a pack of Bi'an darting to and fro before me...",
          bAllowClickSkipScript = false
        },
        [51100050] = {
          ContentKR = "아! 그리고 '누군가' 내게 말을 거는 목소리도 들었소! 법을 집행하는 폐안을 거느릴 수 있는 분이라면, 필시 백룡신군 태호님일 터이니, 그날 나는 분명히 신의 계시를 들은 게요!",
          DialogueId = 51100050,
          DisableMouth = 0,
          GUID = "7FEC71F4",
          IsBlack = 0,
          NextDialogue = 51100051,
          SpeakNpcId = 700319,
          Subtitle = "Ah, and I heard a voice! To have Argent Bi'an at their side — surely it could only have been Lord Argent Themselves! I must have heard divine words that night!",
          bAllowClickSkipScript = false
        },
        [51100051] = {
          ContentKR = "정신을 차려 보니, 어느새 낙진의 바다를 빠져나와 있더구려. 뒤통수에 커다란 혹이 하나 생긴 것 말곤 멀쩡했으니, 태호님의 가호가 아니면 무엇이겠소!",
          DialogueId = 51100051,
          DisableMouth = 0,
          GUID = "7FEC721E",
          IsBlack = 0,
          NextOptions = {
            [1] = 51100054,
            [2] = 51100052
          },
          SpeakNpcId = 700319,
          Subtitle = "When I came to, I'd been carried clear of the Expanse — save a lump on my head, I was sound and whole. All by Taihao's grace!",
          bAllowClickSkipScript = false
        },
        [51100052] = {
          ContentKR = "구사일생하셨네요. 구해 준 게 태호님이 아니었더라도, 어쨌든 결과적으론 전화위복이 된 셈이고요.",
          DialogueId = 51100052,
          GUID = "7FEC7248",
          ImprPlusId = 1209,
          NextDialogue = 51100053,
          Subtitle = "Sounds like a narrow escape. Whether or not it was Taihao, you could call it a blessing in disguise."
        },
        [51100053] = {
          ContentKR = "구사일생과 전화위복이란 말은 마음에 들지만, 중간에 쓸데없는 사족이 들리는구려.",
          DialogueId = 51100053,
          DisableMouth = 0,
          GUID = "7FEC7272",
          IsBlack = 0,
          NextDialogue = 51100056,
          SpeakNpcId = 700319,
          Subtitle = "\"Blessing in disguise,\" I'll take — but must you spoil it with such doubt?",
          bAllowClickSkipScript = false
        },
        [51100054] = {
          ContentKR = "머리를 세게 부딪치면, 뇌진탕 때문에 헛것을 볼 수도 있대요.",
          DialogueId = 51100054,
          GUID = "7FEC729C",
          ImprPlusId = 1208,
          NextDialogue = 51100055,
          Subtitle = "A knock to the head like that... could well have been a concussion. You might've been seeing things."
        },
        [51100055] = {
          ContentKR = "어허, 노인 앞에서 그게 무슨 막말이오?",
          DialogueId = 51100055,
          DisableMouth = 0,
          GUID = "7FEC72C6",
          IsBlack = 0,
          NextDialogue = 51100056,
          SpeakNpcId = 700319,
          Subtitle = "Bah, listen to you! What kind of youngster jinxes an elder like that?",
          bAllowClickSkipScript = false
        },
        [51100056] = {
          ContentKR = "내 말이 거짓 같소? 태호님이 틀림없으셨소! 내게 이 증표까지 하사하셨단 말이오. 다음에 낙진의 바다에서 곤경에 처했을 때, 이 보물을 입으로 힘껏 불면 꼭 나타나시겠다 하셨소.",
          DialogueId = 51100056,
          DisableMouth = 0,
          GUID = "7FEC72F0",
          IsBlack = 0,
          NextDialogue = 51100057,
          SpeakNpcId = 700319,
          Subtitle = "I'm telling you — it was Taihao! They even left me a keepsake! Said that next time I was in peril within the Expanse, I need only blow upon it, and Taihao would appear!",
          bAllowClickSkipScript = false
        },
        [51100057] = {
          ContentKR = "자, 바로 이 물건이오!",
          DialogueId = 51100057,
          DisableMouth = 0,
          GUID = "7FEC731A",
          IsBlack = 0,
          NextDialogue = 51100058,
          SpeakNpcId = 700319,
          Subtitle = "Here! Look — this is it!",
          TalkActionId = {
            [1] = "700319:Give"
          },
          bAllowClickSkipScript = false
        },
        [51100058] = {
          ContentKR = "(물건을 받아 들고 꼼꼼히 살펴본다. 하지만 특별한 점이라곤 눈 씻고 찾아봐도 없는 평범한 나뭇잎일 뿐이다.)",
          DialogueId = 51100058,
          DisableMouth = 0,
          GUID = "7FEC7344",
          IsBlack = 0,
          NextDialogue = 51100059,
          Subtitle = "(You turn the object over in your hand. Every detail shows it is nothing more than an ordinary leaf.)",
          bAllowClickSkipScript = false
        },
        [51100059] = {
          ContentKR = "제가 만약 저기서 나뭇잎 하나를 따와서 섞어 둔다면, 그중 어떤 게 태호께서 주신 증표인지 분간하실 수 있겠어요?",
          DialogueId = 51100059,
          DisableMouth = 0,
          GUID = "7FEC736E",
          IsBlack = 0,
          NextDialogue = 51100060,
          SpeakNpcId = 100001,
          Subtitle = "If I plucked another leaf this very moment and shuffled them about, could you truly tell which one Taihao gave you?",
          bAllowClickSkipScript = false
        },
        [51100060] = {
          ContentKR = "젊은이, 자네는 본질을 보지 못하는구려! 이게 보통 나뭇잎인지 아닌지는 중요하지 않소. 태호께서 친히 꺾으신 순간부터, 이는 더없이 특별한 물건이 된 거요.",
          DialogueId = 51100060,
          DisableMouth = 0,
          GUID = "7FEC7398",
          IsBlack = 0,
          NextDialogue = 51100061,
          SpeakNpcId = 700319,
          Subtitle = "You miss the point, youngster! Aye, it may be but a leaf — yet if plucked by Taihao, it is anything but ordinary.",
          TalkActionId = {
            [1] = "700319:Explain01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100061] = {
          ContentKR = "게다가, 불어 봐야 백룡신군께서 응답을 해 주시는지 아닌지 알 거 아니오! 신의 기적을 증명할 유일한 방법은 그뿐이지 않소!",
          DialogueId = 51100061,
          DisableMouth = 0,
          GUID = "7FEC73C2",
          IsBlack = 0,
          NextDialogue = 51100062,
          SpeakNpcId = 700319,
          Subtitle = "Still, only by calling upon Lord Argent with it can one prove it a true divine grace.",
          bAllowClickSkipScript = false
        },
        [51100062] = {
          ContentKR = "다만 내가 나이를 먹어 이가 성치 않아, 아무리 용을 써도 바람만 새는구려. 번거롭겠지만, 이 풀피리를 대신 불어 봐 주시오!",
          DialogueId = 51100062,
          DisableMouth = 0,
          GUID = "7FEC73EC",
          IsBlack = 0,
          NextOptions = {
            [1] = 51100063
          },
          SpeakNpcId = 700319,
          Subtitle = "Problem is, I'm short a few teeth — can't get the sound right no matter how I try. So I'll have to trouble you to blow it for me!",
          TalkActionId = {
            [1] = "700319:Explain01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100063] = {
          ContentKR = "나뭇잎을 악기처럼 불어본 적은 한 번도 없지만, 어쩌면 내게 숨겨진 재능이 있을지도 모른다는 희망을 품어보기로 한다.",
          DialogueId = 51100063,
          GUID = "7FEC7416",
          ImprCheckId = 1073,
          NextDialogue = 51100065,
          Subtitle = "You've never tried playing a leaf like a flute, but maybe — just maybe — you've a knack for it. You decide to give it a try."
        },
        [51100064] = {
          ContentKR = "(얼굴이 터져라 힘껏 불어 보지만, 아무 소리도 나지 않는다. 공기 중에 어색한 정적만이 흐른다.)",
          DialogueId = 51100064,
          GUID = "7FEC7440",
          Subtitle = "(You puff until your cheeks ache, but the leaf will not sing. An awkward silence hangs in the air.)"
        },
        [51100065] = {
          ContentKR = "(놀랍게도 나뭇잎에서 새가 지저귀듯 맑고 영롱한 소리가 울려 퍼진다.)",
          DialogueId = 51100065,
          DisableMouth = 0,
          GUID = "7FEC746A",
          IsBlack = 0,
          NextDialogue = 51100066,
          Subtitle = "(The leaf trills a clear note, uncannily like a bird's call.)",
          bAllowClickSkipScript = false
        },
        [51100066] = {
          ContentKR = "(순간 주변이 쥐 죽은 듯 조용해지고, 나와 노인은 말없이 서로를 멀뚱히 바라본다.)",
          DialogueId = 51100066,
          DisableMouth = 0,
          GUID = "7FEC7494",
          IsBlack = 0,
          NextDialogue = 51100067,
          Subtitle = "(The air falls still. You and the old man look at each other in bewilderment.)",
          bAllowClickSkipScript = false
        },
        [51100067] = {
          ContentKR = "나의 단잠을 깨우다니, 누구냐?",
          DialogueId = 51100067,
          DisableMouth = 0,
          GUID = "7FEC74BE",
          IsBlack = 0,
          NextDialogue = 51100068,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Who is it? I was sleeping!",
          bAllowClickSkipScript = false
        },
        [51100068] = {
          ContentKR = "(어디선가 목소리가 들려온다. 갓 잠에서 깬 듯 나른하지만, 어딘지 모르게 익숙한 음성이다.)",
          DialogueId = 51100068,
          DisableMouth = 0,
          GUID = "7FEC74E8",
          IsBlack = 0,
          NextDialogue = 51100069,
          Subtitle = "(A voice drifts from nowhere, groggy as though roused from slumber. Something about it feels oddly familiar.)",
          bAllowClickSkipScript = false
        },
        [51100069] = {
          ContentKR = "???",
          DialogueId = 51100069,
          DisableMouth = 0,
          GUID = "7FEC7512",
          IsBlack = 0,
          NextDialogue = 51100070,
          SpeakNpcId = 100001,
          Subtitle = "...?",
          bAllowClickSkipScript = false
        },
        [51100070] = {
          ContentKR = "바로 이 목소리요! 젊은이, 내가 그랬잖소. 나는 백룡신군의 가호를 받은 몸이란 말이오!",
          DialogueId = 51100070,
          DisableMouth = 0,
          GUID = "7FEC753C",
          IsBlack = 0,
          NextDialogue = 51100071,
          SpeakNpcId = 700319,
          Subtitle = "That voice! You hear it too, don't you? It is Lord Argent — I told you I was favoured!",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100071] = {
          ContentKR = "어르신, 제 생각엔 아무래도...",
          DialogueId = 51100071,
          DisableMouth = 0,
          GUID = "7FEC7566",
          IsBlack = 0,
          NextDialogue = 51100072,
          SpeakNpcId = 100001,
          Subtitle = "Sir, I think you might wan—",
          bAllowClickSkipScript = false
        },
        [51100072] = {
          ContentKR = "쉿, 조용히! 크흠... 태호시여, 이 미천한 늙은이가 태호님의 단잠을 방해하였습니다. 용서해 주시옵소서!",
          DialogueId = 51100072,
          DisableMouth = 0,
          GUID = "7FEC7590",
          IsBlack = 0,
          NextDialogue = 51100073,
          SpeakNpcId = 700319,
          Subtitle = "Shh! Quiet! Ahem... O Taihao above, this old soul begs forgiveness for disturbing Your rest!",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100073] = {
          ContentKR = "태호? 나를 태호라 부른 것이냐?",
          DialogueId = 51100073,
          DisableMouth = 0,
          GUID = "7FEC75BA",
          IsBlack = 0,
          NextDialogue = 51100074,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Taihao? You call me Taihao?",
          bAllowClickSkipScript = false
        },
        [51100074] = {
          ContentKR = "예! 혹시 이 늙은이가 신의 이름을 함부로 입에 올려, 무례를 범하였습니까?",
          DialogueId = 51100074,
          DisableMouth = 0,
          GUID = "7FEC75E4",
          IsBlack = 0,
          NextDialogue = 51100075,
          SpeakNpcId = 700319,
          Subtitle = "Ah! Forgive my presumption, Lord Argent!",
          TalkActionId = {
            [1] = "700319:Talk02_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100075] = {
          ContentKR = "하핫, 네 말이 맞구나. 나... 이 몸의 뜻은, 한낱 인간이 어찌 감히 신의 이름을 입에 올린단 말이냐?",
          DialogueId = 51100075,
          DisableMouth = 0,
          GUID = "7FEC760E",
          IsBlack = 0,
          NextDialogue = 51100076,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hah! Right... yes, precisely what I meant! A mere mortal should know better than to bandy my name about so freely!",
          bAllowClickSkipScript = false
        },
        [51100076] = {
          ContentKR = "아이고, 지당하신 말씀이옵니다. 이 미천한 것이 죽을죄를 지었습니다!",
          DialogueId = 51100076,
          DisableMouth = 0,
          GUID = "7FEC7638",
          IsBlack = 0,
          NextDialogue = 51100077,
          SpeakNpcId = 700319,
          Subtitle = "Ah, You are right, my Lord — it was my transgression entirely!",
          TalkActionId = {
            [1] = "700319:Talk02_End"
          },
          bAllowClickSkipScript = false
        },
        [51100077] = {
          ContentKR = "되었다. 이 몸은 아량이 넓으니, 이번만은 눈 감아 주겠다! 인간이여, 묻노니, 어째...어인 연유로 이 외딴곳까지 찾아와 이 몸의 잠을 방해한 것이냐?",
          DialogueId = 51100077,
          DisableMouth = 0,
          GUID = "7FEC7662",
          IsBlack = 0,
          NextDialogue = 51100078,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "No matter — I am magnanimous enough to forgive you this once! Now then, mortal... what brings you to this rotten—ahem... this remote place, disturbing my peace?",
          bAllowClickSkipScript = false
        },
        [51100078] = {
          ContentKR = "예, 흐흐흐, 다름이 아니라, 지난번에 신군님의 자비 덕에 이 미천한 목숨을 부지하지 않았습니까? 참으로 망극한 은혜를 입었습니다!",
          DialogueId = 51100078,
          DisableMouth = 0,
          GUID = "7FEC768C",
          IsBlack = 0,
          NextDialogue = 51100079,
          SpeakNpcId = 700319,
          Subtitle = "Nothing grand, my Lord — last time, You saved me from this wretched place, and I have been grateful ever since!",
          bAllowClickSkipScript = false
        },
        [51100079] = {
          ContentKR = "사실대로 아뢰자면, 이 늙은이가 고향에서 밤낮으로 향불을 올리며 기도한 까닭은, 다시 한번 백룡신군님께 고귀한 가르침을 듣고 싶어서였습니다...",
          DialogueId = 51100079,
          DisableMouth = 0,
          GUID = "7FEC76B6",
          IsBlack = 0,
          NextDialogue = 51100080,
          SpeakNpcId = 700319,
          Subtitle = "Since returning home, I have prayed day and night, offered incense and gifts — all in hope of hearing Your wisdom once more...",
          bAllowClickSkipScript = false
        },
        [51100080] = {
          ContentKR = "그런데 아무리 간절히 빌어도 응답을 내리지 않으시니, 혹여 제가 잘못을 저질러 신군님의 노여움을 산 것은 아닌지, 그 까닭을 여쭙고자 이 험한 길을 마다치 않고 달려왔습니다...",
          DialogueId = 51100080,
          DisableMouth = 0,
          GUID = "7FEC76E0",
          IsBlack = 0,
          NextDialogue = 51100081,
          SpeakNpcId = 700319,
          Subtitle = "But no matter how I prayed, You gave no answer. I feared I had angered You — so I braved these perils to seek Your guidance in person...",
          TalkActionId = {
            [1] = "700319:Talk01_Start"
          },
          bAllowClickSkipScript = false
        },
        [51100081] = {
          ContentKR = "오호! 바로 너... 그대였구나! 아직 기억하느니라! 머리를 찧고 정신이 나가서는, 온갖 헛소리를 늘어놓다가 하마터면 이 몸의 옷에 속엣것을 게워 낼 뻔했었지. 기억나느냐?",
          DialogueId = 51100081,
          DisableMouth = 0,
          GUID = "7FEC770A",
          IsBlack = 0,
          NextDialogue = 51100082,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! Yes, yes, I recall now! You're the one who cracked your head! You clung to my sleeve, babbling nonsense — near spewed all over me! Don't you remember?",
          bAllowClickSkipScript = false
        },
        [51100082] = {
          ContentKR = "역시 머리를 부딪치는 바람에 헛걸 보신 게...",
          DialogueId = 51100082,
          DisableMouth = 0,
          GUID = "7FEC7734",
          IsBlack = 0,
          NextDialogue = 51100083,
          SpeakNpcId = 100001,
          Subtitle = "So it really was a concuss—",
          bAllowClickSkipScript = false
        },
        [51100083] = {
          ContentKR = "아이고! 아이고오! 백룡신군께 감히 그런 무례를! 이 늙은이, 실로 만 번 죽어 마땅합니다!",
          DialogueId = 51100083,
          DisableMouth = 0,
          GUID = "7FEC775E",
          IsBlack = 0,
          NextDialogue = 51100084,
          SpeakNpcId = 700319,
          Subtitle = "How outrageous of me! Such disrespect to Lord Argent! I deserve death for this transgression!",
          TalkActionId = {
            [1] = "700319:Talk01_End"
          },
          bAllowClickSkipScript = false
        },
        [51100084] = {
          ContentKR = "그래서 그날 이후로 제 기도에 묵묵부답이셨군요! 모든 게 이 우매한 늙은이의 잘못이었습니다!",
          DialogueId = 51100084,
          DisableMouth = 0,
          GUID = "7FEC7788",
          IsBlack = 0,
          NextDialogue = 51100085,
          SpeakNpcId = 700319,
          Subtitle = "No wonder You've shunned me since — it was entirely my fault!",
          bAllowClickSkipScript = false
        },
        [51100085] = {
          ContentKR = "이곳에 찾아오지 않았더라면, 신군께 저지른 무례조차 깨닫지 못할 뻔했습니다! 그럼에도 이 풀피리 소리에 몸소 응답해 주시니, 역시 자애롭고 공평하시며, 너그럽고 온화하시고 인자하신 백룡신군님이십니다!",
          DialogueId = 51100085,
          DisableMouth = 0,
          GUID = "7FEC77B2",
          IsBlack = 0,
          NextDialogue = 51100086,
          SpeakNpcId = 700319,
          Subtitle = "Thank heavens I came today — else I'd never have known my offence against You! And yet You still answered my call... so merciful, so benevolent, so boundless in grace!",
          bAllowClickSkipScript = false
        },
        [51100086] = {
          ContentKR = "???",
          DialogueId = 51100086,
          DisableMouth = 0,
          GUID = "7FEC77DC",
          IsBlack = 0,
          NextDialogue = 51100087,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...?",
          bAllowClickSkipScript = false
        },
        [51100087] = {
          ContentKR = "푸하하하하하하... 그래! 말 한번 잘했다! 보는 눈이 있구나!",
          DialogueId = 51100087,
          DisableMouth = 0,
          GUID = "7FEC7806",
          IsBlack = 0,
          NextDialogue = 51100088,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hahahahaha! Well said! You've quite the eye for greatness!",
          bAllowClickSkipScript = false
        },
        [51100088] = {
          ContentKR = "풉...",
          DialogueId = 51100088,
          DisableMouth = 0,
          GUID = "7FEC7830",
          IsBlack = 0,
          NextDialogue = 51100089,
          SpeakNpcId = 100001,
          Subtitle = "Pffft...",
          bAllowClickSkipScript = false
        },
        [51100089] = {
          ContentKR = "어허! 어느 안전이라고 웃음소리를 내는 것이오!",
          DialogueId = 51100089,
          DisableMouth = 0,
          GUID = "7FEC785A",
          IsBlack = 0,
          NextDialogue = 51100090,
          SpeakNpcId = 700319,
          Subtitle = "What are you laughing at? Mind your manners — you stand before Lord Argent!",
          bAllowClickSkipScript = false
        },
        [51100090] = {
          ContentKR = "본디 타고난 성품은 막을 수 없는 것이다. 웃음이 나온다면, 마음껏 웃게 두어라.",
          DialogueId = 51100090,
          DisableMouth = 0,
          GUID = "7FEC7884",
          IsBlack = 0,
          NextDialogue = 51100091,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ahem... Human nature cannot be bent by force. If {性别:he|she} wishes to laugh, let {性别:him|her}.",
          bAllowClickSkipScript = false
        },
        [51100091] = {
          ContentKR = "신군께선 역시 너그러우십니다! 하오나 이 화서의 백성은 누구나 대풍구장의 가르침을 따라야 하는데, 타고난 성품일지라도 어느 정도는 단속하는 것이 도리가 아닐지요...",
          DialogueId = 51100091,
          DisableMouth = 0,
          GUID = "7FEC78AE",
          IsBlack = 0,
          NextDialogue = 51100092,
          SpeakNpcId = 700319,
          Subtitle = "How merciful You are, my Lord! Still, all in Huaxu are bound by the Nine Chapters. Even nature must walk their path, must it not?",
          bAllowClickSkipScript = false
        },
        [51100092] = {
          ContentKR = "오호라? 그렇다면 대풍구장 9조, \"하늘의 법도에 경청하여 엄숙히 대하는 것이 경이라\"는 규율은 어찌하겠느냐? 일전에 그대가 무례를 범했으나, 그대의 정신이 온전치 못함을 가엾이 여겨 벌하지 않았다.",
          DialogueId = 51100092,
          DisableMouth = 0,
          GUID = "7FEC78D8",
          IsBlack = 0,
          NextDialogue = 51100093,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh? And does not the Ninth Admonition say: \"Attend to Heaven's edict with a reverent mind and a solemn heart\"? You offended me once — I forgave you, knowing your mind was muddled.",
          bAllowClickSkipScript = false
        },
        [51100093] = {
          ContentKR = "하나, 지금은 멀쩡한 정신으로 감히 이 몸에게 말대꾸를 하고 있으니, 이 죄를 어찌 벌해야 하겠느냐!",
          DialogueId = 51100093,
          DisableMouth = 0,
          GUID = "7FEC7902",
          IsBlack = 0,
          NextDialogue = 51100094,
          SpeakNpcId = 700318,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "But now, with your wits clear, you dare disrespect me again — what punishment do you deserve?",
          bAllowClickSkipScript = false
        },
        [51100094] = {
          ContentKR = "그, 그것이...",
          DialogueId = 51100094,
          DisableMouth = 0,
          GUID = "7FEC792C",
          IsBlack = 0,
          SpeakNpcId = 700319,
          Subtitle = "I... I...",
          bAllowClickSkipScript = false
        },
        [51100095] = {
          ContentKR = "백룡신군께서 진노하셔서, 폐안들이 날 잡으러 왔구나! 아이고, 사람 살려! 주둥이만 살아 이리 나불대었지만, 이대로 죽고 싶지는 않소!",
          DialogueId = 51100095,
          GUID = "7FEC7956",
          NextDialogue = 51100096,
          SpeakNpcId = 700319,
          Subtitle = "Lord Argent is angry! The Argent Bi'an have come to pass judgement! Save me! I was only exaggerating when I said I deserved death!"
        },
        [51100096] = {
          ContentKR = "정신 차리고, 잘 보세요! 이 폐안들, 우리가 아니라 다른 사람을 노리고 있어요.",
          DialogueId = 51100096,
          GUID = "7FEC7980",
          NextDialogue = 51100097,
          SpeakNpcId = 100001,
          Subtitle = "Calm yourself. Look closely — they're not here for you."
        },
        [51100097] = {
          ContentKR = "또 만났구나, {nickname}!",
          DialogueId = 51100097,
          GUID = "7FEC79AA",
          NextDialogue = 51100098,
          SpeakNpcId = 700318,
          Subtitle = ", we meet again!"
        },
        [51100098] = {
          ContentKR = "이 폐안 녀석들, 하필 재밌을 때 훼방을 놓는단 말이야. 하지만 폐안들하고 싸우는 건 질릴 대로 질렸다. 이번엔 미안하지만 네가 솜씨 좀 보여 줘라!",
          DialogueId = 51100098,
          GUID = "7FEC79D4",
          SpeakNpcId = 700318,
          Subtitle = "These Bi'an sure know when to show themselves — but I've grown bored of crossing blades with the same old foes. Mind lending a hand? Drive them off for me."
        },
        [51100104] = {
          ContentKR = "이게 어찌 된 영문이오! 백룡신군께선 어디 가셨소? 더는 이 늙은이를 굽어살펴 주시지 않는단 말이오?!",
          DialogueId = 51100104,
          GUID = "7FEC7AD0",
          NextDialogue = 51100105,
          SpeakNpcId = 700319,
          Subtitle = "What just happened!? Where is Lord Argent? Am I forsaken!?"
        },
        [51100105] = {
          ContentKR = "게다가, 저 무뢰배는 대체 누군데 갑자기 튀어나온 거요?",
          DialogueId = 51100105,
          GUID = "7FEC7AFA",
          NextDialogue = 51100106,
          SpeakNpcId = 700319,
          Subtitle = "And who is this stranger, springing from nowhere?"
        },
        [51100106] = {
          ContentKR = "도무지 이해할 수가 없구려... 이게 대체 다 무슨 조화요!",
          DialogueId = 51100106,
          GUID = "7FEC7B24",
          NextOptions = {
            [1] = 51100110,
            [2] = 51100107,
            [3] = 51100108,
            [4] = 51100109
          },
          SpeakNpcId = 700319,
          Subtitle = "All of this... what in Taihao's name is going on!?"
        },
        [51100107] = {
          ContentKR = "어르신께서 겪은 일은 전형적인 뇌진탕 후유증이에요. 애초부터 백룡신군을 만나신 적이 없어요.",
          DialogueId = 51100107,
          GUID = "7FEC7B4E",
          ImprPlusId = 1208,
          NextDialogue = 51100111,
          Subtitle = "All your symptoms point to a concussion. You never met the real Lord Argent at all."
        },
        [51100108] = {
          ContentKR = "그때 어르신을 구한 건 백룡신군이 아니라, 여기 이분이었어요. 그래도 덕분에 목숨을 구하셨으니, 그것만으로도 다행이죠.",
          DialogueId = 51100108,
          GUID = "7FEC7B78",
          ImprPlusId = 1209,
          NextDialogue = 51100111,
          Subtitle = "It wasn't Lord Argent who saved you — it was this man who happened by. Either way, you lived. That's blessing enough, isn't it?"
        },
        [51100109] = {
          ContentKR = "저도 어르신이 올리신다는 기도 때문에 온 거잖아요. 물론 보수는 그대로 받을 거예요.",
          DialogueId = 51100109,
          GUID = "7FEC7BA2",
          ImprPlusId = 1206,
          NextDialogue = 51100111,
          Subtitle = "I wasn't sent by Lord Argent to protect you either — but I'm still charging you for my trouble."
        },
        [51100110] = {
          ContentKR = "제가 아까 왜 웃었을까요?",
          DialogueId = 51100110,
          GUID = "7FEC7BCC",
          ImprPlusId = 1210,
          NextDialogue = 51100111,
          Subtitle = "Wanna guess what I was laughing at earlier?"
        },
        [51100111] = {
          ContentKR = "내가 누구냐고? 나그네 각주 님이시다! 물론, 계속 나를 태호라 부르고 싶다면, 굳이 마다하진 않겠다!",
          DialogueId = 51100111,
          GUID = "7FEC7BF6",
          NextDialogue = 51100112,
          SpeakNpcId = 700318,
          Subtitle = "Who am I? Kezhou — a Drifter, nothing more. But if you'd prefer to keep calling me Taihao... I won't stop you!"
        },
        [51100112] = {
          ContentKR = "아니면, 방금 전의 그 칭찬들을 다시 한번 읊어 보겠느냐? 이번엔 진짜 은인한테 말이다! 자애롭고 공평하시며, 너그럽고... 또 뭐가 있었지?",
          DialogueId = 51100112,
          GUID = "7FEC7C20",
          NextDialogue = 51100113,
          SpeakNpcId = 700318,
          Subtitle = "Or better yet, you could say those pretty words to me again. What was it? Merciful, benevolent, and... what was the last one again?"
        },
        [51100113] = {
          ContentKR = "어이, 영감님. 사람 칭찬하는 솜씨가 제법이던데! 당신을 처음 구해 줬을 때도, 자기가 누군지는 기억 못 하면서, 입에 발린 말은 아주 술술 튀어나오더군. 제정신일 때랑도 별 차이 없던데?",
          DialogueId = 51100113,
          GUID = "7FEC7C4A",
          NextDialogue = 51100114,
          SpeakNpcId = 700318,
          Subtitle = "You've quite the knack for flattery, old man. That day I pulled you back from death's door, you couldn't even remember your own name — yet still your tongue rolled out praises as smooth as today."
        },
        [51100114] = {
          ContentKR = "그, 그렇다면 내가 정신을 잃기 직전에 봤던 폐안들은...",
          DialogueId = 51100114,
          GUID = "7FEC7C74",
          NextDialogue = 51100115,
          SpeakNpcId = 700319,
          Subtitle = "Th—Then... those Bi'an I saw before blacking out... they were...?"
        },
        [51100115] = {
          ContentKR = "영 눈치가 없군. 폐안과 늘 '함께' 다니는 게 어디 백룡신군이나 응천위뿐이던가? 녀석들이 죽자고 쫓아다니는 나그네일 수도 있잖아!",
          DialogueId = 51100115,
          GUID = "7FEC7C9E",
          NextDialogue = 51100116,
          SpeakNpcId = 700318,
          Subtitle = "Oh, you didn't know? Lord Argent and the Magistrates of Yingtian aren't the only ones with Bi'an at their side. Now and then, a Drifter finds them trailing along too."
        },
        [51100116] = {
          ContentKR = "네, 네, 네 이노옴——",
          DialogueId = 51100116,
          GUID = "7FEC7CC8",
          NextDialogue = 51100117,
          SpeakNpcId = 700319,
          Subtitle = "Y—Y—Y—You—!"
        },
        [51100117] = {
          ContentKR = "어쩐지 뭔가 이상하다 싶었지! 백룡신군께서 사람의 성품 따위를 논하실 리가 있나! 그런 돼먹지도 않은 소리를 하는 건, 네놈들 같은 무법자들뿐이야!",
          DialogueId = 51100117,
          GUID = "7FEC7CF2",
          NextDialogue = 51100118,
          SpeakNpcId = 700319,
          Subtitle = "No wonder! Lord Argent would never speak of \"human nature\" — only you outlaws spout such twisted drivel!"
        },
        [51100118] = {
          ContentKR = "괘씸한 놈! 내 잠시 눈이 멀어 네 놈의 본모습을 몰라봤구나!",
          DialogueId = 51100118,
          GUID = "7FEC7D1C",
          NextDialogue = 51100119,
          SpeakNpcId = 700319,
          Subtitle = "Curse my blindness — I failed to see you for what you are!"
        },
        [51100119] = {
          ContentKR = "허, 참! 너무하는군! 사람이 그렇게 안면몰수하면 쓰나! 잘 생각해 봐, 영감님, 당신이 지금 거기 두 발로 서 있는 게 다 누구 덕인지!",
          DialogueId = 51100119,
          GUID = "7FEC7D46",
          NextDialogue = 51100120,
          SpeakNpcId = 700318,
          Subtitle = "Hey! That's no way to talk to the man who just saved your life. What happened to all those grateful words? You're still breathing because of me, mind you!"
        },
        [51100120] = {
          ContentKR = "저 영감이랑 입씨름하기도 귀찮다. {nickname}, 네 생각은 어떠냐?",
          DialogueId = 51100120,
          GUID = "7FEC7D70",
          NextOptions = {
            [1] = 51100125,
            [2] = 51100121
          },
          SpeakNpcId = 700318,
          Subtitle = "Unbelievable, this guy. What do you think, ?"
        },
        [51100121] = {
          ContentKR = "당연히 각주한테 고마워해야지.",
          DialogueId = 51100121,
          GUID = "7FEC7D9A",
          ImprPlusId = 1207,
          NextDialogue = 51100122,
          Subtitle = "I think you owe Kezhou a thank you."
        },
        [51100122] = {
          ContentKR = "어르신, 각주가 놀린 건 잘못했지만, 어쨌든 어르신을 구한 건 각주잖아요. 그리고 나뭇잎을 드린 걸 보면, 앞으로도 구해드리려던 것 같은데, 그냥 화해하시면 안 될까요?",
          DialogueId = 51100122,
          GUID = "7FEC7DC4",
          NextDialogue = 51100123,
          SpeakNpcId = 100001,
          Subtitle = "He may've teased you pretending to be the Loong God, but whichever way you look at it, he saved your life. Even the leaf he gave you — it meant he was prepared to help again if you were in danger. Can't you give him that much credit?"
        },
        [51100123] = {
          ContentKR = "나는 평생을 백룡신군과 대풍구장의 가호 아래서 자랐소. 만약 폐안이 하늘의 뜻을 받들어 법을 집행하지 않았더라면, 난 젊은이를 만나기도 전에 검은 폐안의 밥이 되고 말았을 게요.",
          DialogueId = 51100123,
          GUID = "7FEC7DEE",
          NextDialogue = 51100124,
          SpeakNpcId = 700319,
          Subtitle = "I was raised under the protection of Lord Argent and the Nine Chapters. Without the Argent Bi'an enforcing the law, I'd have perished to a Sable Bi'an's fangs long before meeting you."
        },
        [51100124] = {
          ContentKR = "저 나그네가 나를 몇 번을 구한들, 백룡신군의 하해와 같은 은혜에 비하면 한 점 티끌에 불과하오. 나는 백룡신군을 섬기는 몸이니, 저런 무뢰배와는 상종치 않을 것이오.",
          DialogueId = 51100124,
          GUID = "7FEC7E18",
          NextDialogue = 51100129,
          SpeakNpcId = 700319,
          Subtitle = "This Drifter may have saved me once, twice, even thrice — yet compared with Lord Argent, it is nothing. I revere Them, and thus must keep my distance from the lawless."
        },
        [51100125] = {
          ContentKR = "어쩌면 이번 일도 다 신의 뜻이 아니었을까?",
          DialogueId = 51100125,
          GUID = "7FEC7E42",
          ImprPlusId = 1208,
          NextDialogue = 51100126,
          Subtitle = "Maybe this was Taihao's plan all along."
        },
        [51100126] = {
          ContentKR = "어르신, 생과 사가 모두 태호의 뜻이라면, 어르신이 나그네에게 구조된 것도 백룡신군의 뜻 아닐까요? 그렇다면 생명의 은인이 설령 무뢰배라도, 담담히 받아들이셔야죠.",
          DialogueId = 51100126,
          GUID = "7FEC7E6C",
          NextDialogue = 51100127,
          SpeakNpcId = 100001,
          Subtitle = "If you truly believe life and death lie in the Loong God's hands, then being saved by a Drifter must also be part of Their will. Isn't that worth making peace with?"
        },
        [51100127] = {
          ContentKR = "흠? 뭔데 나까지 끌어들이는 거냐? 우리 나그네는 어떤 굴레에도 얽매이지 않는다. 영감님은 구할 만하니까 구한 거고, 다만 저 무지몽매한 믿음이 꼴 보기 싫어 장난 좀 친 것뿐이다.",
          DialogueId = 51100127,
          GUID = "7FEC7E96",
          NextDialogue = 51100128,
          SpeakNpcId = 700318,
          Subtitle = "Hah! Nearly had me there — but no. A Drifter's bound by no rules and no orders. I saved him simply because I chose to — and teased him because I can't stomach blind faith."
        },
        [51100128] = {
          ContentKR = "도무지 모르겠구나. 왜 사람들은 제 발로 걸음을 내딛고도 신에게 공을 돌리는 거지? 초목과 달리 손발이 멀쩡히 달려 있는데도 말이야. 저 노인도 백룡신군을 굳게 믿는다면서, 결국 네게 호위를 부탁하지 않았느냐?",
          DialogueId = 51100128,
          GUID = "7FEC7EC0",
          NextDialogue = 51100129,
          SpeakNpcId = 700318,
          Subtitle = "That's what I don't get — why credit Heaven for what you choose to do? People aren't stones. We move because we will it. Look at this old man: claims to trust in Lord Argent's protection — yet still hires you to keep him safe."
        },
        [51100129] = {
          ContentKR = "이 오만 방자한...!",
          DialogueId = 51100129,
          GUID = "7FEC7EEA",
          NextDialogue = 51100130,
          SpeakNpcId = 700319,
          Subtitle = "Insolence!"
        },
        [51100130] = {
          ContentKR = "고집불통이로군!",
          DialogueId = 51100130,
          GUID = "7FEC7F14",
          NextDialogue = 51100131,
          SpeakNpcId = 700318,
          Subtitle = "Blockhead!"
        },
        [51100131] = {
          ContentKR = "...노력은 해봤지만, 아무래도 두 사람이 악수하고 화해하는 모습은 못 볼 것 같네.",
          DialogueId = 51100131,
          GUID = "7FEC7F3E",
          NextDialogue = 51100132,
          SpeakNpcId = 100001,
          Subtitle = "...Well, I tried. Looks like these two won't be shaking hands anytime soon."
        },
        [51100132] = {
          ContentKR = "쳇! 나야말로 이런 곳에서 시간 낭비할 생각 없다. 가자, {nickname}. 오늘 제대로 실력이나 한번 겨뤄 보자!",
          DialogueId = 51100132,
          GUID = "7FEC7F68",
          NextDialogue = 51100133,
          SpeakNpcId = 700318,
          Subtitle = "Tch. No point wasting daylight bickering with someone that stubborn. Come on,  — let's have ourselves a proper spar instead!"
        },
        [51100133] = {
          ContentKR = "잠깐!",
          DialogueId = 51100133,
          GUID = "7FEC7F92",
          NextDialogue = 51100134,
          SpeakNpcId = 700319,
          Subtitle = "Wait!"
        },
        [51100134] = {
          ContentKR = "(노인이 보수를 둘로 나누어, 하나는 내게, 다른 하나는 각주에게 내민다.)",
          DialogueId = 51100134,
          GUID = "7FEC7FBC",
          NextDialogue = 51100135,
          Subtitle = "(The old man produces two coin pouches — one pressed into your hand, the other into Kezhou's.)"
        },
        [51100135] = {
          ContentKR = "대풍구장 2조에 \"사람의 근본은 글을 세워 신의를 지키는 것\"이라 하였소. 젊은이에게 보수를 약속했으니, 그 약속은 지키겠소.",
          DialogueId = 51100135,
          GUID = "7FEC7FE6",
          NextDialogue = 51100136,
          SpeakNpcId = 700319,
          Subtitle = "The Second Admonition of the Nine Chapters teaches: A man is measured by the strength of his word. I promised this youngster a reward, and so I must keep my word."
        },
        [51100136] = {
          ContentKR = "대풍구장 6조에 \"나를 미루어 남을 헤아리고, 옮음을 행함이 의(義)\"라 하였다. 네놈은 미우나, 도움을 받았으니, 이 돈으로 우리 둘 사이의 셈을 청산할 것이다. 받아 두어라.",
          DialogueId = 51100136,
          GUID = "7FEC8010",
          NextDialogue = 51100137,
          SpeakNpcId = 700319,
          Subtitle = "The Sixth Admonition teaches: \"Let compassion and righteousness guide your mind and every deed.\" Though I despise you, Drifter, I cannot deny the fact you saved me. Take this — and let our accounts be settled. From here on, we walk separate roads."
        },
        [51100137] = {
          ContentKR = "(말을 마치자, 노인은 누구의 도움도 받지 않고, 더디지만 흔들림 없는 발걸음으로 왔던 길을 되돌아갔다. 나는 차마 따라가지 못한 채, 멀어지는 노인의 뒷모습을 말없이 바라보았다.)",
          DialogueId = 51100137,
          GUID = "7FEC803A",
          NextDialogue = 51100138,
          Subtitle = "(Without another word, the old man turns away. Step by step, he makes for home. You do not follow — only watch as his figure fades into the distance.)"
        },
        [51100138] = {
          ContentKR = "그나저나, 한동안 코빼기도 안 비치더니, 여긴 웬일이야?",
          DialogueId = 51100138,
          GUID = "7FEC8064",
          NextDialogue = 51100139,
          SpeakNpcId = 100001,
          Subtitle = "Come to think of it, I haven't seen you in a while. What brings you here?"
        },
        [51100139] = {
          ContentKR = "촉룡의 재앙이 점점 심각해지고 있다. 여긴 원래 현형파의 향탑이 사악한 기운을 억누르던 곳인데, 요즘 들어 힘이 약해지고 있다. 저 노인이 여기서 길을 잃었던 것도 우연이 아니야.",
          DialogueId = 51100139,
          GUID = "7FEC808E",
          NextDialogue = 51100140,
          SpeakNpcId = 700318,
          Subtitle = "The Scourge of Zhuyin grows worse by the day. There used to be a Xuanheng incense tower here to keep the ley lines in check. But lately, it's failing. No wonder that old man got lost."
        },
        [51100140] = {
          ContentKR = "낙진에 침식된 땅이 점점 넓어지는 바람에, 날이 저물도록 걸어도 빠져나오지 못했던 거다.",
          DialogueId = 51100140,
          GUID = "7FEC80B8",
          NextDialogue = 51100141,
          SpeakNpcId = 700318,
          Subtitle = "The Gritblight's spreading faster. That's why he wandered till nightfall without finding the way out."
        },
        [51100141] = {
          ContentKR = "혹시나 사형이 명을 받고 이쪽을 살피러 올까 싶어 죽치고 기다리고 있었는데, 마침 저 노인이 길을 잃었더군. 말솜씨 하나는 기가 막혀서 제법 재미있었는데, 아쉽게 됐어...",
          DialogueId = 51100141,
          GUID = "7FEC80E2",
          NextDialogue = 51100142,
          SpeakNpcId = 700318,
          Subtitle = "I thought my Shixiong might be sent to investigate, so I lingered here. Never thought I'd run into a sharp-tongued old fossil. Amusing sort... pity, really."
        },
        [51100142] = {
          ContentKR = "(각주가 돈주머니를 휙휙 던졌다 받더니, 내 품으로 툭 던진다.)",
          DialogueId = 51100142,
          GUID = "7FEC810C",
          NextDialogue = 51100143,
          Subtitle = "(Kezhou tosses the coin pouch lightly, weighs it in hand — then flings it into your arms.)"
        },
        [51100143] = {
          ContentKR = "이 돈이면 최고급 술을 몇 병은 살 수 있을 테니, 기뻐야 하겠지만... 난 대가를 바라고 사람을 구한 것이 아니야. 이건 네가 가져라.",
          DialogueId = 51100143,
          GUID = "7FEC8136",
          NextDialogue = 51100144,
          SpeakNpcId = 700318,
          Subtitle = "That'd buy a good few bottles of fine wine. Should've been a lovely little gain — but I never save lives for coin. You take it."
        },
        [51100144] = {
          ContentKR = "참 웃기는 세상 아니냐? 지고하신 용신께서 사람을 구하면, 모두 성은이 망극하다 절을 올리고, 일개 나그네가 사람을 구하면, 고작 돈 몇 푼 던져주곤 업신여기니 말이야.",
          DialogueId = 51100144,
          GUID = "7FEC8160",
          NextOptions = {
            [1] = 51100146,
            [2] = 51100145
          },
          SpeakNpcId = 700318,
          Subtitle = "Funny, isn't it? When the lofty Loong God saves a man, He's praised and worshipped. But when a Drifter does the same... we get scorn and a cold shoulder."
        },
        [51100145] = {
          ContentKR = "그래도 신이 구했든, 사람이 구했든, 똑같이 한 사람의 생명을 구한 거야.",
          DialogueId = 51100145,
          GUID = "7FEC818A",
          ImprPlusId = 1207,
          NextDialogue = 51100147,
          Subtitle = "But it still counts — doesn't matter what others think."
        },
        [51100146] = {
          ContentKR = "스스로 옳다고 믿는 일을 했다면, 그걸로 충분해.",
          DialogueId = 51100146,
          GUID = "7FEC81B4",
          ImprPlusId = 1209,
          NextDialogue = 51100147,
          Subtitle = "It's still worth it, for conscience's sake."
        },
        [51100147] = {
          ContentKR = "하하! 역시 나와 생각이 같구나! 네가 말하지 않아도, 난 다 알고 있었다!",
          DialogueId = 51100147,
          GUID = "7FEC81DE",
          NextDialogue = 51100148,
          SpeakNpcId = 700318,
          Subtitle = "Ha! I knew you were a kindred spirit. Say no more — I get it!"
        },
        [51100148] = {
          ContentKR = "뭐, 됐다. 일어나지도 않은 일을 걱정해서 뭐 하겠느냐. 이 아름다운 자연을 벗 삼아, 우리 함께 검의 대화나 나누자꾸나. 마침 딱 떠오르는 구절이 있군...",
          DialogueId = 51100148,
          GUID = "7FEC8208",
          NextDialogue = 51100149,
          SpeakNpcId = 700318,
          Subtitle = "Bah — dwelling on it won't change a thing. Come, let's cross swords and sing it out! Hah... can't think of a verse more fitting than this—"
        },
        [51100149] = {
          ContentKR = "꿈이란 결국 헛된 망상일 뿐이니,",
          DialogueId = 51100149,
          GUID = "7FEC8232",
          NextDialogue = 51100150,
          SpeakNpcId = 700318,
          Subtitle = "Dreams are but illusions, twisting thought awry;"
        },
        [51100150] = {
          ContentKR = "밝은 달 아래, 자유로운 사람으로 살고 싶구나!",
          DialogueId = 51100150,
          GUID = "7FEC825C",
          SpeakNpcId = 700318,
          Subtitle = "Better by far, to live free beneath the moonlit sky!"
        },
        [51101001] = {
          ContentKR = "이번에도 대출 금액이 꽤 만만치 않으신데...",
          DialogueId = 51101001,
          GUID = "7FED0DFA",
          SpeakNpcId = 700320,
          Subtitle = "Not a small sum you're borrowing again..."
        },
        [51101002] = {
          ContentKR = "어? 저 사람들 싸우나 봐! 시종, 시종, 우리가 가서 말리자!",
          DialogueId = 51101002,
          GUID = "7FED0E24",
          SpeakNpcId = 900003,
          Subtitle = "Hey — those two look like they're squabbling over something! Little Minion, quick, let's break it up!"
        },
        [51101003] = {
          ContentKR = "대출 계약서입니다. 쭉 읽어보시고 이상 없으시면 여기에 서명 날인 부탁드려요.",
          DialogueId = 51101003,
          GUID = "7FED0E4E",
          NextDialogue = 51101004,
          SpeakNpcId = 700320,
          Subtitle = "Here's the loan agreement. If everything looks right, sign and make your marks here."
        },
        [51101004] = {
          ContentKR = "금액이 상당한데, 또 어디 다녀오실 건가 보죠?",
          DialogueId = 51101004,
          GUID = "7FED0E78",
          NextDialogue = 51101005,
          SpeakNpcId = 700320,
          Subtitle = "Not a small sum you're taking again — off on another trip, are you?"
        },
        [51101005] = {
          ContentKR = "하하, 역시 잘 아시네요! 이번에는 말이죠, 오랜만에 베드르폴니르 산에 가 볼 생각입니다. 거기 꼬마들이 저를 목이 빠지라 기다리고 있을 테니까요.",
          DialogueId = 51101005,
          GUID = "7FED0EA2",
          NextDialogue = 51101006,
          SpeakNpcId = 700321,
          Subtitle = "Hah, you know me too well! Heading back to the Vidofnir Mountains — the little ones up there haven't seen me in a while. Bet they're already waiting for me."
        },
        [51101006] = {
