          GUID = "7FEE5AB2",
          SpeakNpcId = 700323,
          Subtitle = "The gate shifts its position with each pull. Halt it at just the right point, and you'll be able to slip through and claim the reward. Clear?"
        },
        [51103034] = {
          Camera = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "해 보니 어떻던가?",
          DialogueId = 51103034,
          GUID = "7FEE5ADC",
          LookAt = {
