        [51103036] = {
          Camera = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "허허, 그럴 줄 알았지. 기추의 즐거움을 알게 되면 다들 푹 빠져 헤어나지를 못하더군! 기추 장치들을 연진 나루터 곳곳에 설치해 뒀으니, 마음껏 즐겨 보게.",
          DialogueId = 51103036,
          GUID = "7FEE5B06",
          NextDialogue = 51103042,
          SpeakNpcId = 700323,
          Subtitle = "Hah! None who’ve savoured the wonders of fine craft ever leave unimpressed. And don't worry — I've set up plenty more in Mistwharf. You're welcome to test yourself further.",
          TalkActionId = {
            [1] = "700323:Agree"
          }
        },
        [51103037] = {
          ContentKR = "보상이 너무 짜요.",
          DialogueId = 51103037,
          GUID = "7FEE5B07",
          ImprPlusId = 1201,
          NextDialogue = 51103038,
          Subtitle = "Bit stingy with the rewards."
