          DialogueId = 51104013,
          FacialId = {
            [1] = "700328:Smile01"
          },
          GUID = "7FEEFC22",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104014,
          SpeakNpcId = 700328,
          Subtitle = "Coming right up.",
          TalkActionId = {
            [1] = "700328:Give"
          }
        },
        [51104014] = {
          ContentKR = "음... 혹시 계화떡을 반만... 아니, 3분의 1만 살 순 없을까요? 가지고 온 돈이 좀 모자라서요...",
          DialogueId = 51104014,
          GUID = "7FEEFC4C",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104015,
          SpeakNpcId = 700326,
          Subtitle = "Um... sir, could we maybe just get half a portion? Or... a third? I don't think I've enough coins...",
          TalkActionId = {
            [1] = "700326:Sigh_Start"
          }
        },
        [51104015] = {
          ContentKR = "어허, 참... 어쩔 수 없군.",
          DialogueId = 51104015,
          FacialId = {
            [1] = "700328:Syouganai01"
          },
          GUID = "7FEEFC76",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104016,
          SpeakNpcId = 700328,
          Subtitle = "You little scamp... ah, forget it.",
          TalkActionId = {
            [1] = "700326:Sigh_End"
          }
        },
        [51104016] = {
          ContentKR = "우리 집 어르신께서 아이들이 떡을 먹고 싶어 하면, 너무 야박하게 굴지 말라고 하셨거든. 그러니까 어르신 말씀대로, 너희한테 수수께끼를 낼게.",
          DialogueId = 51104016,
          GUID = "7FEEFCA0",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104017,
          SpeakNpcId = 700328,
          Subtitle = "My old man always said — if kids came begging for a cake, that was fine. But they had to earn it:",
          TalkActionId = {
            [1] = "700328:Think_Start"
          }
        },
        [51104017] = {
          ContentKR = "정답을 맞히면, 이 계화떡 값은 안 받을 거야.",
          DialogueId = 51104017,
          GUID = "7FEEFCCA",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104018,
          SpeakNpcId = 700328,
          Subtitle = "Answer a riddle right, and the cake was on the house."
        },
        [51104018] = {
          ContentKR = "정말로?",
          DialogueId = 51104018,
          GUID = "7FEEFCF4",
          LookAt = {
            [1] = "700326:n(700327)",
            [2] = "700328:n(700327)"
          },
          NextDialogue = 51104019,
          SpeakNpcId = 700327,
          Subtitle = "Really!?",
          TalkActionId = {
            [1] = "700327:Huanhu_Nan_Start",
            [2] = "700328:Think_End"
          }
        },
        [51104019] = {
          ContentKR = "내가 너희 같은 꼬맹이들을 속여서 뭘 하겠어.",
          DialogueId = 51104019,
          GUID = "7FEEFD1E",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextDialogue = 51104020,
          SpeakNpcId = 700328,
          Subtitle = "What would I lie to a couple of kids for?",
          TalkActionId = {
            [1] = "700328:Talk01_Start"
          }
        },
        [51104020] = {
          ContentKR = "무, 아저씨한테 고맙다고 해야지!",
          DialogueId = 51104020,
          GUID = "7FEEFD48",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)",
            [3] = "700326:n(700327)"
          },
          NextDialogue = 51104021,
          SpeakNpcId = 700326,
          Subtitle = "Let's thank this kind sir, Wu!",
          TalkActionId = {
            [1] = "700326:Talk01_Start"
          }
        },
        [51104021] = {
          ContentKR = "이런, 감사 인사는 나중에 하고, 수수께끼부터 맞춰 봐. \"산허리에 걸린 옥고리, 나뭇가지 위의 은빛 조각배, 차고 이지러지는 화장 거울, 밝았다 흐렸다 가을 들판을 비추네.\" 이게 뭘 가리키는 걸까?",
          DialogueId = 51104021,
          GUID = "7FEEFD72",
          LookAt = {
            [1] = "700327:n(700328)",
            [2] = "700326:n(700328)"
          },
          NextOptions = {
            [1] = 51104022,
            [2] = 51104024,
            [3] = 51104026
          },
          SpeakNpcId = 700328,
          Subtitle = "Hold your thanks — riddle first: \"A jade sickle upon slopes, A silver boat caught in the boughs. Full, then thin — a boudoir mirror gleams and pales; clouded or clear, it watches over ripening fields come harvest-time.\"",
          TalkActionId = {
            [1] = "700326:Talk01_End"
          }
        },
        [51104022] = {
          ContentKR = "쟁반",
          DialogueId = 51104022,
          GUID = "7FEEFD9C",
          NextDialogue = 51104023,
          Subtitle = "A plate"
        },
        [51104023] = {
          ContentKR = "뭔가 아닌 것 같은데...",
          DialogueId = 51104023,
          GUID = "7FEEFDC6",
          NextOptions = {
            [1] = 51104201,
            [2] = 51104026
          },
          SpeakNpcId = 100001,
          Subtitle = "That doesn't seem quite right..."
        },
        [51104024] = {
          ContentKR = "천국의 나무",
          DialogueId = 51104024,
          GUID = "7FEEFDF0",
          NextDialogue = 51104025,
          Subtitle = "A Heaventree"
        },
        [51104025] = {
          ContentKR = "뭔가 아닌 것 같은데...",
          DialogueId = 51104025,
          GUID = "7FEEFE1A",
          NextOptions = {
            [1] = 51104200,
            [2] = 51104026
          },
          SpeakNpcId = 100001,
          Subtitle = "That doesn't seem quite right..."
        },
        [51104026] = {
          ContentKR = "달",
          DialogueId = 51104026,
          GUID = "7FEEFE44",
          NextDialogue = 51104027,
          Subtitle = "The moon"
        },
        [51104027] = {
          ContentKR = "정답은...",
          DialogueId = 51104027,
          GUID = "7FEEFE6E",
          NextDialogue = 51104028,
          SpeakNpcId = 100001,
          Subtitle = "The answer is..."
        },
        [51104028] = {
          ContentKR = "나 정답이 뭔지 알아! 달이야!",
          DialogueId = 51104028,
          GUID = "7FEEFE98",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700328:n(700326)"
          },
          NextDialogue = 51104029,
          SpeakNpcId = 700326,
          Subtitle = "I know! It's the moon!",
          TalkActionId = {
            [1] = "700326:Confident_Start"
          }
        },
        [51104029] = {
          ContentKR = "어르신이 너무 쉬운 수수께끼를 내셨네... 좋아, 계화떡 받아. 싸우지 말고, 형제끼리 사이좋게 반씩 나눠 먹어.",
          DialogueId = 51104029,
          GUID = "7FEEFEC2",
          NextDialogue = 51104030,
          SpeakNpcId = 700328,
          Subtitle = "Ha, seems the old man made that one too easy. Here you go. Split it fair — no fighting over it!",
          TalkActionId = {
            [1] = "700328:Give",
            [2] = "700326:Confident_End"
          }
        },
        [51104030] = {
          ContentKR = "계화떡이다!",
          DialogueId = 51104030,
          GUID = "7FEEFEEC",
          Scripts = [[
PARA{
MoveTo{ActorId{700327},TargetPoint{"P51104030XiaoWu"},MoveSpeed{220},Visibility{"Show"}},
MoveTo{ActorId{700326},TargetPoint{"P51104030XiaoWen"},MoveSpeed{220},Visibility{"Show"}}
}]],
          SpeakNpcId = 700327,
          Subtitle = "Yay! Osmanthus cake time!"
        },
        [51104031] = {
          Camera = "672.617188,97.414062,143.926758,0.000022,-5.400849,-167.989822,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "사장님.",
          DialogueId = 51104031,
          GUID = "7FEEFF16",
          LookAt = {
            [1] = "100001:n(700328)",
            [2] = "700324:n(700328)",
            [3] = "700328:n(100001)"
          },
          NextDialogue = 51104032,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},TargetPoint{"P51104031Avatar"},MoveSpeed{80},Visibility{"Show"}},
MoveTo{ActorId{700324},TargetPoint{"P51104031White"},MoveSpeed{80},Visibility{"Show"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Excuse me, sir."
        },
        [51104032] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "오? 외국에서 오신 분들이군요? 옆에 있는 꼬마 친구가 먹으려는 건가요?",
          DialogueId = 51104032,
          GUID = "7FEEFF40",
          NextDialogue = 51104033,
          SpeakNpcId = 700328,
          Subtitle = "Oh? A traveller from afar? Picking up some local sweets for the little one here?",
          TurnTo = {
            [1] = "700324:n(700328)",
            [2] = "100001:n(700328)"
          }
        },
        [51104033] = {
          Camera = "447.546875,110.363281,105.350098,0.000169,-6.799733,-128.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "스노우는 꼬마 아니거든! 잘 들어, 난 장차 이 세계를 정복할 빛의 마왕님이야!",
          DialogueId = 51104033,
          FacialId = {
            [1] = "700324:Unhappy02"
          },
          GUID = "7FEEFF6A",
          LookAt = {
            [1] = "700328:n(700324)"
          },
          NextOptions = {
            [1] = 51104034,
            [2] = 51104035
          },
          SpeakNpcId = 700324,
          Subtitle = "Hey! I'm not a little one! You're standing before the Demon King of Light — future ruler of the world!",
          TalkActionId = {
            [1] = "700324:Angry02_Start"
          }
        },
        [51104034] = {
          ContentKR = "저희도 수수께끼 맞히면 공짜로 주시나요?",
          DialogueId = 51104034,
          GUID = "7FEEFF94",
          ImprPlusId = 1206,
          NextDialogue = 51104036,
          Subtitle = "Can we play the riddle game for a free cake too?"
        },
        [51104035] = {
          ContentKR = "아까 저 꼬마들은 특별 할인 행사에 참여한 건가요?",
          DialogueId = 51104035,
          GUID = "7FEEFFBE",
          ImprPlusId = 1203,
          NextDialogue = 51104036,
          Subtitle = "Those two kids earlier seemed to get a special deal..."
        },
        [51104036] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "음... 어르신이 어른 손님은 어떻게 해야 하는지 말씀을 안 해 주셨는데...",
          DialogueId = 51104036,
          GUID = "7FEEFFE8",
          LookAt = {
            [1] = "700328:n(100001)"
          },
          NextDialogue = 51104037,
          SpeakNpcId = 700328,
          Subtitle = "Er... the old man never said if grown-ups could riddle their way to freebies...",
          TalkActionId = {
            [1] = "700328:Talk01_Start",
            [2] = "700324:Bai_Idle"
          }
        },
        [51104037] = {
          ContentKR = "에이, 어차피 꼬마 친구가 먹을 거죠? 그럼 뭐 괜찮을 거예요.",
          DialogueId = 51104037,
          GUID = "7FEF0012",
          NextDialogue = 51104038,
          SpeakNpcId = 700328,
          Subtitle = "But hey, if it's for the little one, I suppose it's fine.",
          TalkActionId = {
            [1] = "700328:Talk01_End"
          }
        },
        [51104038] = {
          Camera = "447.546875,110.363281,105.350098,0.000169,-6.799733,-128.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "저기! 나 꼬마 아니라니까!",
          DialogueId = 51104038,
          FacialId = {
            [1] = "700324:Doubt01"
          },
          GUID = "7FEF003C",
          NextDialogue = 51104039,
          SpeakNpcId = 700324,
          Subtitle = "Hey! Who are you calling \"little\"!?",
          TalkActionId = {
            [1] = "700324:Angry01_Start"
          }
        },
        [51104039] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "뭘 내 볼까... 음. 아, 이걸로 하죠. \"가지마다 여문 황금 좁쌀, 은은한 향이 가을을 깨우네. 꽃이 작다고 슬퍼 마라, 신선도 달빛 아래 향기를 좇으니.\" 이게 뭘 가리키는 걸까요?",
          DialogueId = 51104039,
          FinalDialogueId = 51104045,
          GUID = "7FEF0066",
          NextOptions = {
            [1] = 51104040,
            [2] = 51104042,
            [3] = 51104044
          },
          SpeakNpcId = 700328,
          Subtitle = "Hmm... let me think. Right — try this one: \"Golden clusters on unsullied boughs, a subtle scent whispers of autumn's first prime. Though modest, unadorned in hue, Immortals sought them by the moonlit dew.\"",
          TalkActionId = {
            [1] = "700328:Talk02_Start"
          }
        },
        [51104040] = {
          ContentKR = "백년춘",
          DialogueId = 51104040,
          GUID = "7FEF0090",
          NextDialogue = 51104041,
          Subtitle = "EverSpring"
        },
        [51104041] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다시 한번 생각해 보시겠어요?",
          DialogueId = 51104041,
          GUID = "7FEF00BA",
          NextOptions = {
            [1] = 51104204,
            [2] = 51104044
          },
          SpeakNpcId = 700328,
          Subtitle = "Not quite. Care to try again?"
        },
        [51104042] = {
          ContentKR = "침월향",
          DialogueId = 51104042,
          GUID = "7FEF00E4",
          NextDialogue = 51104043,
          Subtitle = "Lunarose"
        },
        [51104043] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "비슷하긴 한데, 다시 한번 생각해 보시겠어요?",
          DialogueId = 51104043,
          GUID = "7FEF010E",
          NextOptions = {
            [1] = 51104203,
            [2] = 51104044
          },
          SpeakNpcId = 700328,
          Subtitle = "That's close... but not quite. Want to give it another go?"
        },
        [51104044] = {
          ContentKR = "계화",
          DialogueId = 51104044,
          GUID = "7FEF0138",
          NextDialogue = 51104045,
          Subtitle = "Osmanthus"
        },
        [51104045] = {
          ContentKR = "맞추셨네요! 바로 이 계화떡의 재료인 계화지요... 자, 막 쪄내서 김이 모락모락 나는 떡이에요. 여기, 받으세요.",
          DialogueId = 51104045,
          GUID = "7FEF0162",
          NextDialogue = 51104046,
          SpeakNpcId = 700328,
          Subtitle = "That's it. Osmanthus it is — just like the cake's name. Fresh from the steamer. Here you are.",
          TalkActionId = {
            [1] = "700328:Talk02_End",
            [2] = "700324:Angry02_End"
          }
        },
        [51104046] = {
          ContentKR = "전 어르신 속을 알 수가 없어요. 떡 장사해 봐야 얼마 남는 것도 없는데, 수수께끼만 맞추면 공짜로 주신단 말이죠. 이러다 어르신 노후 자금까지 동나는 거 아닌가 싶다니까요.",
          DialogueId = 51104046,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake01.T_Guide_ChapterEast01_GuiHuaCake01'}",
          GUID = "7FEF018C",
          NextDialogue = 51104047,
          SpeakNpcId = 700328,
          Subtitle = "Still don't know what the old man was thinking... running a little stall like this, giving out free cakes to anyone who cracks a riddle. Keep that up and he'll burn through his retirement money in no time.",
          TalkActionId = {
            [1] = "700328:Sigh_Start"
          }
        },
        [51104047] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이 방식이 마음에 안 드시나 봐요?",
          DialogueId = 51104047,
          GUID = "7FEF01B6",
          NextDialogue = 51104048,
          SpeakNpcId = 100001,
          Subtitle = "So... you don't agree with it?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51104048] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아 오해는 마세요. 약속한 건 당연히 드려야죠. 사실 저도 아이들이 옆에서 침 꼴깍 삼키는 모습을 보면, 마음이 약해지는걸요.",
          DialogueId = 51104048,
          GUID = "7FEF01E0",
          NextDialogue = 51104049,
          SpeakNpcId = 700328,
          Subtitle = "Oh, don't get me wrong. If we say it's free for a right answer, then it's free. You see a kid staring, drool on their chin and wiping it off on their sleeve... who'd have the heart to turn them away?",
          TalkActionId = {
            [1] = "700328:Sigh_End",
            [2] = "100001:Think_End"
          }
        },
        [51104049] = {
          ContentKR = "아이들이 먹어봐야 얼마나 먹겠어요? 그냥 줄 수도 있죠. 예전에 제가 이 거리를 혼자 떠돌 때, 이 계화떡 향기에 홀려 어르신을 만나 제자로 들어가지 않았더라면, 저도 아마...",
          DialogueId = 51104049,
          FacialId = {
            [1] = "700328:Happy01"
          },
          GUID = "7FEF020A",
          NextDialogue = 51104050,
          SpeakNpcId = 700328,
          Subtitle = "Kids don't eat much anyway — what's a single cake? Truth is, I used to wander these streets with no home to return to. It was that same craving for osmanthus cake that caught the old man's eye. He took me in, made me his apprentice... I'd rather not think where I'd have ended up if he hadn't.",
          TalkActionId = {
            [1] = "700328:Talk02_Start"
          }
        },
        [51104050] = {
          ContentKR = "어이쿠, 제가 손님 앞에서 별소리를 다 하네요... 전 그냥 어르신이 왜 하필 수수께끼를 내시는 건지, 그게 궁금한 거예요.",
          DialogueId = 51104050,
          FacialId = {
            [1] = "700328:None"
          },
          GUID = "7FEF0234",
          NextDialogue = 51104051,
          SpeakNpcId = 700328,
          Subtitle = "Ah, listen to me rambling... Anyway, I've always wondered why he ever made that rule of riddles for cake.",
          TalkActionId = {
            [1] = "700328:Talk02_End"
          }
        },
        [51104051] = {
          ContentKR = "하지만 저도 굳이 그 이유를 묻진 않아요. 이 가게도, 떡 만드는 비법도 전부 어르신 거고, 손님들도 전부 '이계화'라는 간판을 보고 찾아오는 거니까요. 저 같은 굴러온 돌한테 이 모든 걸 물려주신 것만으로도, 이미 감지덕지죠.",
          DialogueId = 51104051,
          GUID = "7FEF025E",
          NextDialogue = 51104052,
          SpeakNpcId = 700328,
          Subtitle = "But he never said, and I never asked. The stall, the recipe, the customers — they were all his. And he handed them down to a stray like me. That's more than I ever deserved."
        },
        [51104052] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "툴툴거리시는 것 같아도, 속으론 스승님을 아주 좋아하시나 봐요?",
          DialogueId = 51104052,
          GUID = "7FEF0288",
          NextDialogue = 51104053,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like you're complaining... but really, you're quite fond of him, aren't you?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51104053] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "하하... 절 먹여 주고 재워 주고, 기술까지 전수해 주신 분이니까요. 저한텐 아버지 같은 분이시죠. 그래도 평소엔 꼭 아버지가 아니라 스승님이라고 부르게 하시지만요.",
          DialogueId = 51104053,
          GUID = "7FEF02B2",
          NextDialogue = 51104054,
          SpeakNpcId = 700328,
          Subtitle = "Haha... you've seen through me. He gave me a roof, filled my bowl, taught me everything I know. I've long seen him as a father. But he won't let me call him that — insists on \"Shifu\" instead.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51104054] = {
          ContentKR = "이 은혜는 정말 평생을 다 바쳐도 갚기 힘들겠죠. 전 그냥 평생 곁에서 스승님을 모시고, 노년을 편안하게 보내실 수 있게 해 드리고 싶어요.",
          DialogueId = 51104054,
          GUID = "7FEF02DC",
          NextDialogue = 51104055,
          SpeakNpcId = 700328,
          Subtitle = "There's no repaying a debt like that. All I can do is look after him, and see that he spends his days in peace."
        },
        [51104055] = {
          Camera = "470.919922,-447.367188,169.704102,0.000065,-7.799495,112.800148,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어이, 이 군, 바쁜가?",
          DialogueId = 51104055,
          GUID = "7FEF0306",
          LookAt = {
            [1] = "100001:n(700332)",
            [2] = "700324:n(700332)",
            [3] = "700328:n(700332)"
          },
          NextDialogue = 51104056,
          Scripts = "MoveTo{ActorId{700332},TargetPoint{\"P51104055ZhaoShu\"},MoveSpeed{90},Visibility{\"Show\"}}",
          SpeakNpcId = 700332,
          Subtitle = "Oi, Li! Busy as ever, I see."
        },
        [51104056] = {
          ContentKR = "아저씨, 어쩐 일이세요? 방금 나온 따끈한 계화떡 하나 드시겠어요?",
          DialogueId = 51104056,
          GUID = "7FEF0330",
          LookAt = {
            [1] = "700332:n(700328)"
          },
          NextDialogue = 51104057,
          SpeakNpcId = 700328,
          Subtitle = "Uncle Zhao! What brings you by? Fresh batch just came out — fancy a bit of osmanthus cake?",
          TurnTo = {
            [1] = "700328:n(700332)"
          }
        },
        [51104057] = {
          ContentKR = "아니, 아니야. 손님부터 챙기고, 이따가 한가할 때, 자네 스승한테 얘기나 해줘. 한잔하러 온대놓고 왜 여지껏 코빼기도 안 보이는 거야. 이 좋은 술이 언제까지 기다려 줄지 모른다고.",
          DialogueId = 51104057,
          GUID = "7FEF035A",
          NextDialogue = 51104058,
          SpeakNpcId = 700332,
          Subtitle = "Nah, don't fuss. See to your customers. Just tell your old man to drop in like he promised. Said he'd come by for a drink, but I've been waiting ages. If he doesn't show soon, there'll be no good wine left for him!",
          TalkActionId = {
            [1] = "700332:Talk02_Start"
          }
        },
        [51104058] = {
          ContentKR = "...이상하네요. 어르신은 늘 약속에 미리 나가면 나가셨지, 단 한 번도 늦으신 적이 없거든요. 전 약속에 늦었다고, 종아리를 맞은 적도 있어요.",
          DialogueId = 51104058,
          GUID = "7FEF0384",
          LookAt = {
            [1] = "100001:n(700328)",
            [2] = "700324:n(700328)"
          },
          NextDialogue = 51104059,
          SpeakNpcId = 700328,
          Subtitle = "...That's odd. The old man's never late for anything — always turns up early, cane in hand, ready to whack me if I'm even a minute behind.",
          TalkActionId = {
            [1] = "700332:Talk02_End",
            [2] = "700328:Talk01_Start"
          }
        },
        [51104059] = {
          ContentKR = "아무래도 안 되겠어요. 오늘은 이만 장사를 접고, 어르신을 찾으러 가야겠어요.",
          DialogueId = 51104059,
          GUID = "7FEF03AE",
          NextDialogue = 51104060,
          SpeakNpcId = 700328,
          Subtitle = "No... something's wrong. I'm closing the stall for the day. I need to go look for him.",
          TalkActionId = {
            [1] = "700328:Talk01_End"
          }
        },
        [51104060] = {
          ContentKR = "아저씨는 일단 댁에 가 계세요. 어르신을 찾는 대로 바로 알려드릴게요.",
          DialogueId = 51104060,
          GUID = "7FEF03D8",
          NextDialogue = 51104061,
          SpeakNpcId = 700328,
          Subtitle = "Uncle Zhao, head home for now. I'll let you know the moment I find him.",
          TalkActionId = {
            [1] = "700328:Talk02_Start"
          }
        },
        [51104061] = {
          Camera = "447.546875,110.363281,105.350098,0.000169,-6.799733,-128.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어...? 지금 밖에 검은 폐안이 엄청 많은데? 설마... 에이, 퉤퉤퉤, 괜히 불길한 소리 하지 말아야지!",
          DialogueId = 51104061,
          FacialId = {
            [1] = "700324:Shock01"
          },
          GUID = "7FEF0402",
          LookAt = {
            [1] = "700332:n(100001)"
          },
          NextDialogue = 51104062,
          SpeakNpcId = 700324,
          Subtitle = "Huh...? There's been loads of Sable Bi'an roaming about lately... Could he have run into— gah! No jinxing it! Phooey!",
          TalkActionId = {
            [1] = "700324:Shock_Start",
            [2] = "700328:Talk02_End"
          }
        },
        [51104062] = {
          Camera = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...사장님, 저희도 같이 갈게요. 의뢰비는 이 계화떡으로 받은 셈 치죠.",
          DialogueId = 51104062,
          GUID = "7FEF042C",
          NextDialogue = 51104063,
          SpeakNpcId = 100001,
          Subtitle = "...Sir, let us come with you. Think of it as thanks for the cake.",
          TurnTo = {
            [1] = "700328:n(100001)"
          }
        },
        [51104063] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래 주시면 정말 감사하죠. 어르신께서 가실 법한 곳을 몇 군데 알고 있으니까, 절 따라오세요.",
          DialogueId = 51104063,
          GUID = "7FEF0456",
          LookAt = {
            [1] = "700328:n(100001)"
          },
          SpeakNpcId = 700328,
          Subtitle = "That'd be a real help. I've a few places in mind where he might have gone — come along."
        },
        [51104064] = {
          ContentKR = "이 벼락 맞을 짐승 놈들! 얘들아, 겁먹지 말고 어서 이 할애비 뒤로 숨거라!",
          DialogueId = 51104064,
          GUID = "7FEF0480",
          NextDialogue = 51104065,
          SpeakNpcId = 700333,
          Subtitle = "Blasted beasts — Sable Bi'an again! Don't be afraid, children. Get behind me!"
        },
        [51104065] = {
          ContentKR = "형, 나 무서워...",
          DialogueId = 51104065,
          GUID = "7FEF04AA",
          NextDialogue = 51104066,
          SpeakNpcId = 700327,
          Subtitle = "Wen... I'm scared..."
        },
        [51104066] = {
          ContentKR = "괜찮아, 이 향주머니를 꼭 쥐고 있으면, 백룡신군께서 우릴 지켜 주실 거야.",
          DialogueId = 51104066,
          GUID = "7FEF04D4",
          NextDialogue = 51104067,
          SpeakNpcId = 700326,
          Subtitle = "It's alright. Hold onto the sachet — Lord Argent will protect us."
        },
        [51104067] = {
          ContentKR = "저 애들은... 아까 그 꼬마들이잖아!",
          DialogueId = 51104067,
          GUID = "7FEF04FE",
          SpeakNpcId = 100001,
          Subtitle = "Wait... those are the two kids from earlier!"
        },
        [51104068] = {
          ContentKR = "죄를 지으면, 벌이 따르는 법!",
          DialogueId = 51104068,
          GUID = "7FEF0528",
          SpeakNpcId = 700325,
          Subtitle = "Justice demands retribution!"
        },
        [51104069] = {
          ContentKR = "욱명이야!",
          DialogueId = 51104069,
          GUID = "7FEF0552",
          SpeakNpcId = 100001,
          Subtitle = "Yuming!"
        },
        [51104070] = {
          Camera = "-137.351562,325.910156,238.606445,0.00011,-10.794915,-30.803417,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "너희들이었군... 도와줘서 고맙다.",
          DialogueId = 51104070,
          GUID = "7FEF057C",
          LookAt = {
            [1] = "700325:n(100001)"
          },
          NextDialogue = 51104071,
          SpeakNpcId = 700325,
          Subtitle = "...It's you. My thanks for your aid.",
          TalkActionId = {
            [1] = "700326:Shock_Start"
          }
        },
        [51104071] = {
          Camera = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어르신! 검은 폐안에게 포위당하시다니, 이게 어떻게 된 거예요? 다치신 곳은 없으세요?",
          DialogueId = 51104071,
          GUID = "7FEF05A6",
          LookAt = {
            [1] = "700328:n(700333)"
          },
          NextDialogue = 51104072,
          SpeakNpcId = 700328,
          Subtitle = "Shifu! What's happened? How did you get cornered by Sable Bi'an? Are you hurt?",
          TalkActionId = {
            [1] = "700328:Angry01_Start"
          }
        },
        [51104072] = {
          Camera = "222.753906,168.0625,157.84082,0.00014,-5.794309,-28.59362,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "난 멀쩡하니 걱정 말거라. 나보다는 이 아이들이 크게 놀랐겠구나. 마침 내가 근처에 있었기에 망정이지, 조금만 늦었더라면...",
          DialogueId = 51104072,
          GUID = "7FEF05D0",
          LookAt = {
            [1] = "700326:n(700333)",
            [2] = "700327:n(700333)"
          },
          NextDialogue = 51104073,
          SpeakNpcId = 700333,
          Subtitle = "No need to fuss. These old bones still hold up well enough. The little ones were badly shaken, though. Luckily I was close by... only just managed to shield them. A moment later an—"
        },
        [51104073] = {
          Camera = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이 녀석들, 왜 얼른 집에 안 돌아가고 이런 외진 곳을 돌아다니는 거야!",
          DialogueId = 51104073,
          GUID = "7FEF05FA",
          NextDialogue = 51104074,
          SpeakNpcId = 700328,
          Subtitle = "You two scamps! What are you doing out here in the wilds? You should be at home!"
        },
        [51104074] = {
          Camera = "222.753906,168.0625,157.84082,0.00014,-5.794309,-28.59362,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "완아, 아는 사이인 게냐?",
          DialogueId = 51104074,
          GUID = "7FEF0624",
          NextDialogue = 51104075,
          SpeakNpcId = 700333,
          Subtitle = "You know these children?",
          TalkActionId = {
            [1] = "700328:Angry01_End"
          }
        },
        [51104075] = {
          Camera = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아까 나루터에서 만났어요. 수수께끼를 맞히고 계화떡을 받아 갔죠.",
          DialogueId = 51104075,
          GUID = "7FEF064E",
          NextDialogue = 51104076,
          SpeakNpcId = 700328,
          Subtitle = "Met them at the dock. They solved a riddle and earned themselves one of our osmanthus cakes.",
          TalkActionId = {
            [1] = "700328:Talk01_Start",
            [2] = "700333:Talk02_Start",
            [3] = "700326:Shock_End"
          }
        },
        [51104076] = {
          Camera = "254.984375,78.167969,126.896484,0.000137,-6.39389,-21.59598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "죄송해요. 집에 늦게 들어가면 혼날까 봐, 동생이랑 지름길로 가려다가...",
          DialogueId = 51104076,
          GUID = "7FEF0678",
          LookAt = {
            [1] = "700327:n(700326)",
            [2] = "700326:n(700327)"
          },
          NextDialogue = 51104077,
          SpeakNpcId = 700326,
          Subtitle = "I'm sorry... I didn't want to be scolded for coming home late, so I took my little brother down the shortcut...",
          TalkActionId = {
            [1] = "700326:Explain02_Start"
          },
          TurnTo = {
            [1] = "700327:n(700326)"
          }
        },
        [51104077] = {
          ContentKR = "형... 형은 잘못 없어. 내가 딴짓하느라 늦은 거잖아.",
          DialogueId = 51104077,
          GUID = "7FEF06A2",
          NextDialogue = 51104078,
          SpeakNpcId = 700327,
          Subtitle = "It's not your fault, Wen. I was caught up playing and didn't realise how late it had gotten.",
          TalkActionId = {
            [1] = "700327:Sigh_Start",
            [2] = "700326:Explain02_End"
          }
        },
        [51104078] = {
          Camera = "-137.351562,325.910156,238.606445,0.00011,-10.794915,-30.803417,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래, 하고 싶은 말은 집에 가서 하거라. 완아, 이 아이들부터 집까지 바래다주거라.",
          DialogueId = 51104078,
          GUID = "7FEF06CC",
          NextDialogue = 51104079,
          SpeakNpcId = 700333,
          Subtitle = "Best not linger here. Huan, take these two home at once, will you?"
        },
        [51104079] = {
          Camera = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "네, 어르신도 얼른 돌아가셔서 조씨 아저씨를 안심시켜 주세요. 그리고 여러분, 도와주셔서 정말 감사합니다. 전 이만 가 볼게요.",
          DialogueId = 51104079,
          GUID = "7FEF06F6",
          NextDialogue = 51104080,
          SpeakNpcId = 700328,
          Subtitle = "Understood. You head back soon as well — and don't forget to let Uncle Zhao know you're safe. Thanks again, everyone. I'll be off now."
        },
        [51104080] = {
          Camera = "-137.351562,325.910156,238.606445,0.00011,-10.794915,-30.803417,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "응천위, 그리고 외국에서 온 두 영웅, 정말 고맙네. 자네들이 아니었다면, 나 혼자선 저 두 아이를 지켜내지 못했을 걸세.",
          DialogueId = 51104080,
          GUID = "7FEF0720",
          LookAt = {
            [1] = "700325:n(700333)"
          },
          NextDialogue = 51104081,
          SpeakNpcId = 700333,
          Subtitle = "My thanks to you, Magistrate — and to you two heroes from foreign lands as well. Without your help, these old bones might not have been enough to keep those boys safe.",
          TurnTo = {
            [1] = "700325:n(700333)"
          }
        },
        [51104081] = {
          Camera = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "마땅히 해야 할 일을 했을 뿐입니다. 감사 인사는 필요 없습니다.",
          DialogueId = 51104081,
          GUID = "7FEF074A",
          NextDialogue = 51104082,
          SpeakNpcId = 700325,
          Subtitle = "Only fulfilling my duty. No need for thanks.",
          TalkActionId = {
            [1] = "700325:Talk02_Start"
          }
        },
        [51104082] = {
          Camera = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...혹시 이 늙은이가 잘못 본 거라면, 부디 용서하게. 응천위 자네... 예전에 우리 가게에 온 적이 있지 않나? 아우도 같이 말이야. ",
          DialogueId = 51104082,
          GUID = "7FEF0774",
          NextDialogue = 51104083,
          SpeakNpcId = 700333,
          Subtitle = "...Forgive my boldness — perhaps these failing eyes deceive me. But tell me, sir... have I seen you before at my stall? With your younger brother, perhaps?",
          TalkActionId = {
            [1] = "700325:Talk02_End"
          }
        },
        [51104083] = {
          Camera = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51104083,
          GUID = "7FEF079E",
          NextDialogue = 51104084,
          SpeakNpcId = 700325,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700325:Think_Start"
          }
        },
        [51104084] = {
          ContentKR = "네.",
          DialogueId = 51104084,
          GUID = "7FEF07C8",
          NextDialogue = 51104085,
          SpeakNpcId = 700325,
          Subtitle = "Yes."
        },
        [51104085] = {
          Camera = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "역시 그랬군. 어쩐지 낯이 익다 했네. 자네는 형이었고, 곁에는 말 안 듣는 아우가 하나 붙어 다녔지... 방금 전 그 형제와 어찌나 닮았는지.",
          DialogueId = 51104085,
          GUID = "7FEF07F2",
          NextOptions = {
            [1] = 51104086,
            [2] = 51104087
          },
          SpeakNpcId = 700333,
          Subtitle = "I thought so! No wonder you seemed familiar. You were the elder one — and your little brother, quite the handful. Just like... just like those two boys earlier.",
          TalkActionId = {
            [1] = "700325:Think_End"
          }
        },
        [51104086] = {
          ContentKR = "응천위한테도 가족이 있었구나.",
          DialogueId = 51104086,
          GUID = "7FEF081C",
          ImprPlusId = 1209,
          NextDialogue = 51104088,
          Subtitle = "So the Magistrate of Yingtian once had family, too..."
        },
        [51104087] = {
          ContentKR = "말 안 듣는 동생이라면... 설마 각주?",
          DialogueId = 51104087,
          GUID = "7FEF0846",
          ImprPlusId = 1203,
          NextDialogue = 51104088,
          Subtitle = "A bit of a handful... could it be Kezhou?"
        },
        [51104088] = {
          Camera = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "같은 스승을 모신 사형제였을 뿐, 친형제는 아닙니다.",
          DialogueId = 51104088,
          GUID = "7FEF0870",
          NextDialogue = 51104089,
          SpeakNpcId = 700325,
          Subtitle = "Not by blood. We trained under the same Shifu, nothing more."
        },
        [51104089] = {
          Camera = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그랬나... 이제 응천위가 되었으니, 크게 성공했군그래. 아우는 어찌 지내나? 고집은 좀 세도 머리는 비상했으니, 자네 못지않은 훌륭한 인물이 되어 있겠지?",
          DialogueId = 51104089,
          GUID = "7FEF089A",
          NextDialogue = 51104090,
          SpeakNpcId = 700333,
          Subtitle = "I see... Well, you've done well for yourself. A Magistrate of Yingtian — quite the accomplishment. And your junior... hot-tempered as he was, he had a keen mind. I imagine he's grown into someone just as impressive."
        },
        [51104090] = {
          Camera = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51104090,
          GUID = "7FEF08C4",
          NextDialogue = 51104091,
          SpeakNpcId = 700325,
          Subtitle = "..."
        },
        [51104091] = {
          Camera = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...늙은이가 괜한 소리를 했나 보군. 어쩔 수 없지. 세월은 무상하고, 운명은 알 수 없는 법이니, 어찌 모든 일이 사람 마음대로만 되겠는가.",
          DialogueId = 51104091,
          GUID = "7FEF08EE",
          NextDialogue = 51104092,
          SpeakNpcId = 700333,
          Subtitle = "...Ah, seems I've spoken out of turn. Time passes, fate charts its own course — seldom as we wish it.",
          TalkActionId = {
            [1] = "700333:Sigh_Start"
          }
        },
        [51104092] = {
          Camera = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어르신, 밖은 위험하니, 이제 그만 댁으로 돌아가시지요.",
          DialogueId = 51104092,
          GUID = "7FEF0918",
          NextDialogue = 51104093,
          SpeakNpcId = 700325,
          Subtitle = "It's dangerous out here, sir. Best you return home soon."
        },
        [51104093] = {
          ContentKR = "그래야지. 늦으면 완이 녀석이 또 애가 탈 게야. 괜찮다면, 가는 길에 이 늙은이의 말동무가 되어 주겠나?",
          DialogueId = 51104093,
          GUID = "7FEF0942",
          SpeakNpcId = 700333,
          Subtitle = "True enough. Don't want Huan fretting after me. If you're headed that way, perhaps you might walk with me a while?"
        },
        [51104094] = {
          Camera = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "또 신세를 졌군. 요새 이 주변이 영 심상치가 않아.",
          DialogueId = 51104094,
          GUID = "7FEF096C",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104095,
          SpeakNpcId = 700333,
          Subtitle = "Thank you again. Things haven't been peaceful round here of late.",
          TalkActionId = {
            [1] = "700333:Talk01_Start"
          }
        },
        [51104095] = {
          ContentKR = "저기 보이나? 예전엔 저기 계화 숲이 있었네. 아, 숲이라기보단, 계화나무 몇 그루가 있었지. 꽃이 어찌나 흐드러지게 피던지, 꽃 필 때가 되면 향기가 산 너머까지 퍼졌다네.",
          DialogueId = 51104095,
          GUID = "7FEF0996",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104096,
          SpeakNpcId = 700333,
          Subtitle = "There used to be a grove of osmanthus trees out that way. Well... not a grove, really — just a handful of trees growing close together. But when they bloomed, their scent drifted clear across the hills.",
          TalkActionId = {
            [1] = "700333:Talk01_End"
          }
        },
        [51104096] = {
          ContentKR = "그 계화나무 아래에, 작은 마을이 하나 있었네. 겨우 몇 가구가 옹기종기 모여 사는 작은 마을이었지만, 옆에 자그마한 밭이 있어서, 거기서 나는 작물들로 다 같이 먹고 살았지.",
          DialogueId = 51104096,
          GUID = "7FEF09C0",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104097,
          SpeakNpcId = 700333,
          Subtitle = "Beneath those trees stood a tiny village. \"Village\" might be too grand a word — just a handful of scattered homes. A modest plot of land nearby, just enough to keep those families fed."
        },
        [51104097] = {
          ContentKR = "마을이 작고 호경에서도 한참 떨어진 두메산골이라, 아이들한텐 이렇다 할 놀잇거리가 없었다네. 그래서 내가 아이들에게 계화꽃을 따오게 해서, 떡을 만들어 나눠 주고, 수수께끼도 내면서 놀아 주곤 했지.",
          DialogueId = 51104097,
          GUID = "7FEF09EA",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104098,
          SpeakNpcId = 700333,
          Subtitle = "It was quiet, far from Haojing. With little for the children to do, I set them gathering osmanthus blossoms, made cakes with them, shared them round. I'd throw in a riddle or two for fun, just to keep their wits sharp."
        },
        [51104098] = {
          ContentKR = "내 수수께끼를 가장 잘 맞히던 아이는... 바로 내 아들이었네. 우리 완이는 어릴 적부터 참 총명했지. 난 아들이 큰 인물이 되길 바라지 않았네. 그저 무탈하게 자라, 이 보잘것없는 떡 장사라도 물려받길 바랐는데...",
          DialogueId = 51104098,
          GUID = "7FEF0A14",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104099,
          SpeakNpcId = 700333,
          Subtitle = "The one best at solving them... was my son. Huan was a bright boy. I never asked much — only that he grow up safe, and maybe take on this little trade of mine one day.",
          TalkActionId = {
            [1] = "700333:Disagree"
          }
        },
        [51104099] = {
          Camera = "-118.90625,-330.195312,98.025879,0.0002,-11.993771,63.773678,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "설마...",
          DialogueId = 51104099,
          GUID = "7FEF0A3E",
          LookAt = {
            [1] = "700333:n(100001)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104100,
          SpeakNpcId = 100001,
          Subtitle = "You mean...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51104100] = {
          Camera = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "허허, 우리 완이는 응천위를 좋아하고 많이 따랐지. 하루는 기어코 응천위가 법을 집행하는 모습을 보겠다고 길을 나섰다가, 그만 사건에 휘말려 불귀의 객이 되고 말았다네...",
          DialogueId = 51104100,
          GUID = "7FEF0A68",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104101,
          SpeakNpcId = 700333,
          Subtitle = "Heh... Huan revered the Magistrates. One day he insisted on watching an arrest — said he wanted to see justice done. He was caught in the chaos... and never made it home.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51104101] = {
          ContentKR = "세월이 흘러, 마을은 사라지고 사람들은 하나둘 뿔뿔이 흩어졌네. 이젠 내 본명을 기억하는 사람도 없지. 그저 내 성이 이 씨고, 계화떡을 잘 만든다 하여, 이계화라고 부를 뿐이야.",
          DialogueId = 51104101,
          GUID = "7FEF0A92",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104102,
          SpeakNpcId = 700333,
          Subtitle = "Decades have passed. The villagers I once knew are long gone, and the ones who came after never knew my name. To them, I'm just the man who sells osmanthus cake."
        },
        [51104102] = {
          ContentKR = "늙은이가 돼서 이제 떠돌아다니기도 싫고, 그렇다고 외톨이로 지낼 수는 없으니, 결국 성안 나루터에 자리를 잡고 떡을 팔게 된 걸세. 그러다 부모 없는 아이를 하나 거두게 됐고, 죽은 아들의 이름까지 내주었지.",
          DialogueId = 51104102,
          GUID = "7FEF0ABC",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104103,
          SpeakNpcId = 700333,
          Subtitle = "I didn't want to leave, but with no kin left and no one to turn to, I couldn't stay in that place forever. So I came to the city, selling steamed cakes by the dock. Took in a little orphan, and gave him my son's name."
        },
        [51104103] = {
          ContentKR = "친자식처럼 정을 쏟아 키웠는데도, 막상 그 아이가 날 아버지라고 부를 때면, 가슴 한구석이 미어지더군. 그럴 때마다 여길 찾아와 하염없이 걷곤 했다네.",
          DialogueId = 51104103,
          GUID = "7FEF0AE6",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104104,
          SpeakNpcId = 700333,
          Subtitle = "I raised him as my own... yet when he calls me \"Dad\", it still tears at me. When that pain grows too heavy, I find myself walking back here."
        },
        [51104104] = {
          ContentKR = "여기서 내려다보고 있으면, 사라진 마을이 꼭 다시 돌아온 것 같거든. 아니, 처음부터 아무 데도 가지 않고 쭉 여기 있었던 것 같네.",
          DialogueId = 51104104,
          GUID = "7FEF0B10",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104105,
          SpeakNpcId = 700333,
          Subtitle = "From this hill, looking down... it's as though the village were still there."
        },
        [51104105] = {
          ContentKR = "젊은이, 자네가 아우를 데리고 처음 내 가게에 왔던 그날, 내가 냈던 수수께끼를 아직 기억하고 있나?",
          DialogueId = 51104105,
          GUID = "7FEF0B3A",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104106,
          SpeakNpcId = 700333,
          Subtitle = "Child... do you remember the riddle I gave you, that first time you brought your Shidi to buy osmanthus cake?"
        },
        [51104106] = {
          Camera = "-86.242188,466.148438,64.947754,0.000178,-7.393345,-67.627014,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"바람에 시름하고 비에 근심하노라. 계화는 가을 따라 돌아오건만, 배에 함께 기대설 이 없네.\"",
          DialogueId = 51104106,
          GUID = "7FEF0B64",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700333:n(700325)"
          },
          NextDialogue = 51104107,
          SpeakNpcId = 700325,
          Subtitle = "The wind sighs, the rain sighs too. Where osmanthus falls, autumn returns anew. A lonely shadow drifts at the prow."
        },
        [51104107] = {
          Camera = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "용케 기억하고 있군. 그때 자네들은 끝내 답을 맞히지 못했지. 당연한 일이네. 이 늙은이의 푸념일 뿐이었는데, 거기에 무슨 답이 있었겠나.",
          DialogueId = 51104107,
          GUID = "7FEF0B8E",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104108,
          SpeakNpcId = 700333,
          Subtitle = "Quite the memory you have. You couldn't solve it back then — because it wasn't really a riddle. Just something an old man murmured to himself."
        },
        [51104108] = {
          ContentKR = "세월이 참 많이 흘렀지. 아들이 떠난 대신 제자를 얻었고, 벗은 갔지만 함께 술 한잔 기울여 줄 늙은이들이 생겼네. 하지만 저 계화나무 아래 작은 마을만큼은, 영영 돌아갈 수 없게 되었어.",
          DialogueId = 51104108,
          GUID = "7FEF0BB8",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104109,
          SpeakNpcId = 700333,
          Subtitle = "All these years... My son is gone, but I have an apprentice. My old friends are gone, yet I've found new ones to drink with. Only that little village beneath the osmanthus trees... never returned."
        },
        [51104109] = {
          ContentKR = "자네는 아직 젊지 않은가. 옛 인연도, 돌아갈 곳도 아직 남아 있겠지. 부디, 자네는 이 늙은이의 전철을 밟지 말게나...",
          DialogueId = 51104109,
          GUID = "7FEF0BE2",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          NextDialogue = 51104110,
          SpeakNpcId = 700333,
          Subtitle = "You're still young. Those you cherish are still around, and a home still awaits your return. Don't end up like me..."
        },
        [51104110] = {
          ContentKR = "이제 그만 됐네. 여기서부터는 혼자서도 거뜬해. 다들 도와줘서 고맙네.",
          DialogueId = 51104110,
          GUID = "7FEF0C0C",
          LookAt = {
            [1] = "100001:n(700333)",
            [2] = "700325:n(700333)"
          },
          Scripts = "MoveTo{ActorId{700333},TargetPoint{\"P51104110GuiHuaLi\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 700333,
          Subtitle = "This is far enough. I can walk the rest on my own. Thank you again, all of you."
        },
        [51104111] = {
          Camera = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "욱명, 여기서 다시 보게 될 줄 몰랐어. 저번에 청아원에서 헤어지고 나서, 각주가 널 만나면 이 얘길 전해 달라고 하더라...",
          DialogueId = 51104111,
          GUID = "7FEF0C36",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700325:n(100001)",
            [3] = "700324:n(700325)"
          },
          NextDialogue = 51104112,
          SpeakNpcId = 100001,
          Subtitle = "Yuming — I didn't expect to see you again, here of all places. After we parted at Crowsong Hollow, Kezhou asked me to pass on a message..."
        },
        [51104112] = {
          Camera = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "각주가 무슨 말을 하려는 건지는 이미 알고 있지만, 그 뜻에 응할 순 없어... 미안.",
          DialogueId = 51104112,
          GUID = "7FEF0C60",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104113,
          SpeakNpcId = 700325,
          Subtitle = "I already know what's in his heart. But I cannot answer that wish. Thank you, both, all the same."
        },
        [51104113] = {
          Camera = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "있잖아, 얘길 들어 보니까, 둘이 예전엔 같이 계화떡 먹을 정도로 친했던 거 아냐? 오해가 있으면 그냥 시원하게 풀면 안 돼?",
          DialogueId = 51104113,
          GUID = "7FEF0C8A",
          LookAt = {
            [1] = "100001:n(700324)",
            [2] = "700325:n(700324)"
          },
          NextDialogue = 51104114,
          SpeakNpcId = 700324,
          Subtitle = "Hey hey, come on now! Weren't you two thick as thieves? You bought osmanthus cake together! Whatever happened — can't you just talk it out?",
          TalkActionId = {
            [1] = "700324:Think_Start"
          }
        },
        [51104114] = {
          Camera = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...세상엔 돌아갈 곳이 사라져 돌아가지 못하는 사람도 있고, 돌아갈 곳이 있어도 돌아가지 못하는 사람도 있어.",
          DialogueId = 51104114,
          GUID = "7FEF0CB4",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104115,
          SpeakNpcId = 700325,
          Subtitle = "...Some seek to return home, only to find it gone. Some still have a home, yet can never return.",
          TalkActionId = {
            [1] = "700324:Think_End"
          }
        },
        [51104115] = {
          ContentKR = "그동안의 오해와 갈등은 말 몇 마디로 풀어낼 수 있는 게 아냐. 게다가 난 이제 법을 집행하는 응천위고, 각주는 나그네지. 우리의 길은, 이미 너무도 멀어졌어.",
          DialogueId = 51104115,
          GUID = "7FEF0CDE",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)"
          },
          NextDialogue = 51104116,
          SpeakNpcId = 700325,
          Subtitle = "What lies between us cannot be set right with a few words. Now I serve as a Magistrate of Yingtian... and he, a Drifter. Our paths lie worlds apart."
        },
        [51104116] = {
          ContentKR = "중간에서 애써준 건 고마워... 하지만 내 입장은 변하지 않아.",
          DialogueId = 51104116,
          GUID = "7FEF0D08",
          LookAt = {
            [1] = "100001:n(700325)",
            [2] = "700324:n(700325)",
            [3] = "700325:n(100001)"
          },
          NextDialogue = 51104117,
          SpeakNpcId = 700325,
          Subtitle = "Still, I thank you both. Forgive me for letting you down.",
          TalkActionId = {
            [1] = "700325:Talk02_Start"
          }
        },
        [51104117] = {
          Camera = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "말이 너무 어려워서 스노우는 무슨 소린지 하나도 모르겠어... 그치만, 네 결정이 그렇다면, 나랑 시종도 더는 뭐라고 안 할게.",
          DialogueId = 51104117,
          GUID = "7FEF0D32",
          LookAt = {
            [1] = "100001:n(700324)",
            [2] = "700325:n(700324)"
          },
          NextDialogue = 51104118,
          SpeakNpcId = 700324,
          Subtitle = "I don't really get it... sounds super deep and mysterious. But if you've made up your mind, then my Little Minion and I won't press you.",
          TalkActionId = {
            [1] = "700325:Talk02_End"
          }
        },
        [51104118] = {
          ContentKR = "그럼 우리 먼저 갈게. 잘 지내. 너무 무리하진 말고.",
          DialogueId = 51104118,
          GUID = "7FEF0D5C",
          NextDialogue = 51104119,
          Scripts = [[
PARA{
MoveTo{_delay{3},ActorId{100001},TargetPoint{"P51104118Avatar"},MoveSpeed{80},Visibility{"Show"}},
MoveTo{_delay{3},ActorId{700324},TargetPoint{"P51104118White"},MoveSpeed{80},Visibility{"Show"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Then we'll be off. Take care of yourself, alright? Don't overdo it."
        },
        [51104119] = {
          Camera = "-1452.339844,-2423.003906,585.456543,0.000174,-7.592308,44.551308,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "사형, 산외산 사람들은 아무도 사형을 원망하지 않아. 대체 왜 그렇게 고집을 부리는 거야?",
          DialogueId = 51104119,
          GUID = "7FEF0D86",
          IsBlack = 1,
          NextDialogue = 51104120,
          Subtitle = "Shixiong, no one back at the Outer Peaks blames you. Why are you so damn stubborn?",
          TurnTo = {
            [1] = "700325:p(90)"
          }
        },
        [51104120] = {
          ContentKR = "관두지. 오늘은 사형을 쓰러뜨려서라도, 반드시 산외산으로 데리고 돌아가겠어!",
          DialogueId = 51104120,
          GUID = "7FEF0DB0",
          IsBlack = 1,
          NextDialogue = 51104121,
          Subtitle = "Fine then — if that's how it has to be, I'll fight you to the ground and drag you back myself!"
        },
        [51104121] = {
          ContentKR = "...한번 떠나온 길은, 다시 되돌릴 수 없는 법. 이게 바로 하늘의 뜻이겠지.",
          DialogueId = 51104121,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake02.T_Guide_ChapterEast01_GuiHuaCake02'}",
          GUID = "7FEF0DDA",
          NextDialogue = 51104122,
          SpeakNpcId = 700325,
          Subtitle = "...We are no longer who we once were. Perhaps... that is how it was always meant to be.",
          TalkActionId = {
            [1] = "700325:Explain02_Start"
          }
        },
        [51104122] = {
          ContentKR = " 옛 인연도, 돌아갈 곳도 아직 남아 있다라... 결국은 부질없는 희망일 뿐이야.",
          DialogueId = 51104122,
          GUID = "7FEF0E04",
          SpeakNpcId = 700325,
          Subtitle = "\"Those you cherish are still around, and a home still awaits your return...\" ...Just wishful thinking."
        },
        [51104200] = {
          ContentKR = "쟁반",
          DialogueId = 51104200,
          GUID = "7FEF1AD0",
          NextDialogue = 51104202,
          Subtitle = "A plate"
        },
        [51104201] = {
          ContentKR = "천국의 나무",
          DialogueId = 51104201,
          GUID = "7FEF1AD1",
          NextDialogue = 51104202,
          Subtitle = "A Heaventree"
        },
        [51104202] = {
          ContentKR = "뭔가 아닌 것 같은데...",
          DialogueId = 51104202,
          GUID = "7FEF1AD2",
          NextOptions = {
            [1] = 51104026
          },
          SpeakNpcId = 100001,
          Subtitle = "That doesn't seem quite right..."
        },
        [51104203] = {
          ContentKR = "백년춘",
          DialogueId = 51104203,
          GUID = "7FEF0139",
          NextDialogue = 51104205,
          Subtitle = "EverSpring"
        },
        [51104204] = {
          ContentKR = "침월향",
          DialogueId = 51104204,
          GUID = "7FEF013A",
          NextDialogue = 51104206,
          Subtitle = "Lunarose"
        },
        [51104205] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다시 한번 생각해 보시겠어요?",
          DialogueId = 51104205,
          GUID = "7FEF013B",
          NextOptions = {
            [1] = 51104044
          },
          SpeakNpcId = 700328,
          Subtitle = "Not quite. Care to try again?"
        },
        [51104206] = {
          Camera = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "비슷하긴 한데, 다시 한번 생각해 보시겠어요?",
          DialogueId = 51104206,
          GUID = "7FEF013C",
          NextOptions = {
            [1] = 51104044
          },
          SpeakNpcId = 700328,
          Subtitle = "That's close... but not quite. Want to give it another go?"
        },
        [51105001] = {
          ContentKR = "너무 무서워요... 흑흑... 백룡신군님, 제발 우리 할머니를 보내서 절 지켜 주세요...",
          DialogueId = 51105001,
          GUID = "7FEF1AFA",
          NextDialogue = 51105002,
          SpeakNpcId = 700329,
          Subtitle = "I'm scared... waaah... Lord Argent up above, could Nana come keep me safe...?",
          TalkActionId = {
            [1] = "700329:Sigh_Start"
          }
        },
        [51105002] = {
          ContentKR = "제 소원을 들어주시면요, 제가 겁쟁이라는 것도 인정할게요. 엄마랑 아빠한테 안 무섭다고 했던 건, 전부 다 거짓말이었어요!",
          DialogueId = 51105002,
          GUID = "7FEF1B24",
          NextOptions = {
            [1] = 51105003,
            [2] = 51105005,
            [3] = 51105007
          },
          SpeakNpcId = 700329,
          Subtitle = "If Lord Argent says yes, then I'll admit that I'm just a big scaredy-cat! I only told Mum and Dad I wasn't afraid so I'd sound brave..."
        },
        [51105003] = {
          ContentKR = "무서울 땐, 솔직하게 무섭다고 말하는 게 좋아.",
          DialogueId = 51105003,
          GUID = "7FEF1B4E",
          ImprPlusId = 1207,
          NextDialogue = 51105004,
          Subtitle = "If you're afraid, it's better to be honest about it."
        },
        [51105004] = {
          ContentKR = "네, 맞아요. 근데 전 제가 이거보단 용감할 줄 알았단 말이에요. 일부러 거짓말한 거 아니에요...",
          DialogueId = 51105004,
          GUID = "7FEF1B78",
          NextDialogue = 51105009,
          SpeakNpcId = 700329,
          Subtitle = "Ah, y—you're right! I thought I was way braver than this... I didn't mean to hide it on purpose..."
        },
        [51105005] = {
          ContentKR = "백룡신군이 지켜 주시는데, 왜 할머니까지 필요한 거야?",
          DialogueId = 51105005,
          GUID = "7FEF1BA2",
          ImprPlusId = 1208,
          NextDialogue = 51105006,
          Subtitle = "If Lord Argent is watching over you, why do you still need Nana?"
        },
        [51105006] = {
          ContentKR = "신군님이 절 안 다치게 지켜 주실 순 있는데요, 할머니가 계시면, 더 안심이 되거든요... 그리고 신군님은 엄청 바쁘시니까, 저한테 못 오실 수도 있잖아요.",
          DialogueId = 51105006,
          GUID = "7FEF1BCC",
          NextDialogue = 51105009,
          SpeakNpcId = 700329,
          Subtitle = "Lord Argent can keep me from getting hurt... but Nana makes me feel safe inside. And They're super, super busy — They might not have time to come all the way down just for me..."
        },
        [51105007] = {
          ContentKR = "백룡신군이랑 할머니 중에서 한 명만 널 지켜줄 수 있다면, 누굴 고를 거야?",
          DialogueId = 51105007,
          GUID = "7FEF1BF6",
          ImprPlusId = 1210,
          NextDialogue = 51105008,
          Subtitle = "You can only pick one to protect you — Lord Argent or Nana. Who's it going to be?"
        },
        [51105008] = {
          ContentKR = "...왜 맨날 \"엄마가 좋아? 아빠가 좋아?\"같은 걸 물어보는 친척들처럼 짜증 나게 굴어요?",
          DialogueId = 51105008,
          GUID = "7FEF1C20",
          NextDialogue = 51105009,
          SpeakNpcId = 700329,
          Subtitle = "...You sound just like those nosy aunties and uncles always asking, \"Who do you love more, Mum or Dad?\""
        },
        [51105009] = {
          ContentKR = "우으, 할머니만 계셨으면, 혼자 집 지킬 필요도 없고, 신군님한테 우리 집의 이상한 일들을 해결해 달라고 기도드리지 않아도 됐을 텐데...",
          DialogueId = 51105009,
          GUID = "7FEF1C4A",
          NextDialogue = 51105010,
          SpeakNpcId = 700329,
          Subtitle = "Aw... If Nana were here, I wouldn't have to stay home all by myself... and Lord Argent wouldn't have to come fix all the spooky stuff either...",
          TalkActionId = {
            [1] = "700329:Sigh_End"
          }
        },
        [51105010] = {
          ContentKR = "집에 무슨 일 있었어?",
          DialogueId = 51105010,
          GUID = "7FEF1C74",
          NextDialogue = 51105011,
          SpeakNpcId = 100001,
          Subtitle = "What happened, exactly?",
          TalkActionId = {
            [1] = "0:Talk02_Start"
          },
          TurnTo = {
            [1] = "700329:n(0)"
          }
        },
        [51105011] = {
          ContentKR = "듣고 놀라지 마세요! 집에 자꾸 이상한 일들이 생겨요! 예를 들면요, 책장에 꽂혀 있던 책이 갑자기 '쿵!' 떨어지는 거예요. 너무 무서워서 멀리 떨어져 있었는데...",
          DialogueId = 51105011,
          GUID = "7FEF1C9E",
          NextDialogue = 51105012,
          SpeakNpcId = 700329,
          Subtitle = "You promise you won't get scared? There's been loads of strange things at my house! Like — thud! — books falling right off the shelf! I was way too scared to go near them...",
          TalkActionId = {
            [1] = "700329:Think_Start"
          }
        },
        [51105012] = {
          ContentKR = "그 책이 발이랑 눈이 달린 것처럼, 나를 막 따라오는 거 있죠!",
          DialogueId = 51105012,
          GUID = "7FEF1CC8",
          NextDialogue = 51105013,
          SpeakNpcId = 700329,
          Subtitle = "And then one of them started chasing me! Like it had eyes! And legs!"
        },
        [51105013] = {
          ContentKR = "또 있어요! 며칠 전부터 엄마랑 아빠가 집에 안 계시는데요, 창가에 자꾸만 고창꽃 한 다발이 '뿅!'하고 나타나요. 주변에 다 물어봤는데, 아무도 가져다 둔 사람이 없대요!",
          DialogueId = 51105013,
          GUID = "7FEF1CF2",
          NextDialogue = 51105014,
          SpeakNpcId = 700329,
          Subtitle = "And — and! Mum and Dad haven't been home lately, but I keep finding Sky Lilies on the windowsill! I asked around, but nobody said they brought them..."
        },
        [51105014] = {
          ContentKR = "이게 끝이 아니에요!",
          DialogueId = 51105014,
          GUID = "7FEF1D1C",
          NextDialogue = 51105015,
          SpeakNpcId = 700329,
          Subtitle = "There's been tons of weird things like that!"
        },
        [51105015] = {
          ContentKR = "어떤 날은요. 제가 무릎을 다쳤는데, 밤에 잘 때 어디선가 '호호'하고 바람 부는 소리가 나는 거예요. 그런데 아침에 일어나 보니까, 상처에 약이 발라져 있었어요.",
          DialogueId = 51105015,
          GUID = "7FEF1D46",
          NextDialogue = 51105016,
          SpeakNpcId = 700329,
          Subtitle = "Like one time, I scraped my knee, and in the middle of the night I heard this soft \"fwooo, fwooo\" like the wind... Then when I woke up — someone had already put herb paste on my knee!"
        },
        [51105016] = {
          ContentKR = "그리고 또 한 번은요. 아무 이유도 없이 갑자기 제 방에 귀뚜라미가 우글거렸던 적도 있어요. 전 벌레를 엄청 싫어하는데, 대체 누가 그런 장난을 친 걸까요...",
          DialogueId = 51105016,
          GUID = "7FEF1D70",
          NextDialogue = 51105017,
          SpeakNpcId = 700329,
          Subtitle = "And another time, a bunch of Loomhoppers got into my room! I hate bugs! Who let them in — was it some kind of mean prank?",
          TalkActionId = {
            [1] = "700329:Think_End"
          }
        },
        [51105017] = {
          ContentKR = "부모님은 어디 가셨는데?",
          DialogueId = 51105017,
          GUID = "7FEF1D9A",
          NextDialogue = 51105018,
          SpeakNpcId = 100001,
          Subtitle = "What about your parents?"
        },
        [51105018] = {
          ContentKR = "엄마랑 아빠는 별을 잇는 자라서, 집에 돌아오시려면 한참 멀었어요. 할머니는... 백룡신군님 곁으로 가셔서, 하늘의 별이 되셨고요.",
          DialogueId = 51105018,
          GUID = "7FEF1DC4",
          NextDialogue = 51105019,
          SpeakNpcId = 700329,
          Subtitle = "Mum and Dad are Starweavers — they won't be back for a while. As for Nana... she went to Lord Argent's side. She's a star in the sky now.",
          TalkActionId = {
            [1] = "700329:Explain02_Start"
          }
        },
        [51105019] = {
          ContentKR = "할머니는 별이 돼서 엄마랑 아빠가 돌아오는 길을 밝히고, 꿈속에서 절 지켜 주실 거예요. 우리가 호경에 있든, 연진 나루터에 있든, 아니면 화서 밖에 있든, 할머니는 항상 절 지켜보실 거고요...",
          DialogueId = 51105019,
          GUID = "7FEF1DEE",
          NextDialogue = 51105020,
          SpeakNpcId = 700329,
          Subtitle = "As a star, Nana lights the way home for Mum and Dad... She watches me every night, no matter where I live — Haojing, Mistwharf... even if I went far, far away from Huaxu."
        },
        [51105020] = {
          ContentKR = "하지만 할머니가 너무 보고 싶어요. 할머니가 멀리 하늘에 계시지 말고, 제 곁에 있어 주셨으면 좋겠어요...",
          DialogueId = 51105020,
          GUID = "7FEF1E18",
          NextDialogue = 51105021,
          SpeakNpcId = 700329,
          Subtitle = "But... I still miss her so much. I'd rather have her here with me... not way up in the sky..."
        },
        [51105021] = {
          ContentKR = "(아마 영아의 할머니는 아마 이미 돌아가신 거겠지...)",
          DialogueId = 51105021,
          GUID = "7FEF1E42",
          NextDialogue = 51105022,
          SpeakNpcId = 100001,
          Subtitle = "(You realise now — Lingling's Nana must have passed away.)",
          TalkActionId = {
            [1] = "0:Talk02_End"
          }
        },
        [51105022] = {
          ContentKR = "흐윽... 으아아앙!",
          DialogueId = 51105022,
          GUID = "7FEF1E6C",
          NextDialogue = 51105026,
          NextOptions = {
            [1] = 51105023
          },
          RestartTag = 51105021,
          SpeakNpcId = 700329,
          Subtitle = "Waah... waaaahhh!"
        },
        [51105023] = {
          ContentKR = "엉엉 우는 영아를 보니 문득 이런 생각이 떠오른다. 이 아이를 지키고 싶다는 마음은, 집착이 되어 무유생이 되기에 충분하지 않을까.",
          DialogueId = 51105023,
          FailDialogue = 51105024,
          GUID = "7FEF1E96",
          ImprCheckId = 1078,
          NextDialogue = 51105026,
          Subtitle = "Watching Lingling cry her heart out, it hits you: maybe what has been protecting her is a lingering wish strong enough to give birth to a Wishen."
        },
        [51105024] = {
          ContentKR = "(도와주고 싶은 마음은 굴뚝같지만, 당장은 뾰족한 방법이 떠오르지 않는다.)",
          DialogueId = 51105024,
          GUID = "7FEF1EEA",
          NextDialogue = 51105025,
          Subtitle = "(Sadly, it's not that you don't want to help... you just haven't figured out how yet.)"
        },
        [51105025] = {
          ContentKR = "같이 있어 줘서 고마워요. 이젠 조금 덜 무서워요. 엄마랑 아빠가 돌아오실 때까지, 전 계속 할머니랑 신군님께 기도하고 있을게요...",
          DialogueId = 51105025,
          GUID = "7FEF1F14",
          SpeakNpcId = 700329,
          Subtitle = "Thanks for staying with me. I'm not so scared now. I'll keep praying to Nana and Lord Argent until Mum and Dad come back..."
        },
        [51105026] = {
          ContentKR = "어쩌면 내가 문제를 해결해 줄 수 있을지도 몰라. 짚이는 게 있거든.",
          DialogueId = 51105026,
          GUID = "7FEF1F68",
          NextDialogue = 51105027,
          SpeakNpcId = 100001,
          Subtitle = "I think I might have a lead. Maybe I can help you sort this out."
        },
        [51105027] = {
          ContentKR = "어? 우리 할머니도 아니고, 백룡신군님도 아닌데, 어떻게요?",
          DialogueId = 51105027,
          GUID = "7FEF1F92",
          NextOptions = {
            [1] = 51105028,
            [2] = 51105031,
            [3] = 51105034
          },
          SpeakNpcId = 700329,
          Subtitle = "Huh? But you're not Nana... or Lord Argent...",
          TalkActionId = {
            [1] = "700329:Explain02_Start"
          }
        },
        [51105028] = {
          ContentKR = "사실 난 백룡신군님의 명을 받고 여기 온 거야.",
          DialogueId = 51105028,
          GUID = "7FEF1FBC",
          ImprPlusId = 1210,
          NextDialogue = 51105029,
          Subtitle = "Lord Argent sent me."
        },
        [51105029] = {
          ContentKR = "크흠, 신군님께서 네 기도를 듣고, 널 도와 줄 신의 사자로 날 보내셨거든.",
          DialogueId = 51105029,
          GUID = "7FEF1FE6",
          NextDialogue = 51105030,
          SpeakNpcId = 100001,
          Subtitle = "Ahem... Lord Argent heard your prayers and sent me — Their very own messenger — to help you."
        },
        [51105030] = {
          ContentKR = "우와! {性别:오빠|언니}는 백룡신군의 은총을 받은 대단한 사람이었네요! 소문으로만 들었지, 실제로 보는 건 이번이 처음이에요!",
          DialogueId = 51105030,
          GUID = "7FEF2010",
          NextDialogue = 51105037,
          SpeakNpcId = 700329,
          Subtitle = "Wow! So you're one of the mighty ones Lord Argent picked? I've only ever heard of people like you in stories — it's my first time meeting one for real!"
        },
        [51105031] = {
          ContentKR = "네 할머니가 날 여기로 보내셨어.",
          DialogueId = 51105031,
          GUID = "7FEF203A",
          ImprPlusId = 1209,
          NextDialogue = 51105032,
          Subtitle = "Your Nana sent me."
        },
        [51105032] = {
          ContentKR = "하늘의 별 하나가 나한테 이리로 가라고 알려 줬는데, 그 별이 네 할머니였던 것 같아.",
          DialogueId = 51105032,
          GUID = "7FEF2064",
          NextDialogue = 51105033,
          SpeakNpcId = 100001,
          Subtitle = "I followed the stars here. Maybe one of them is your Nana."
        },
        [51105033] = {
          ContentKR = "훌쩍... 역시... 할머니는 계속 제 곁에서, 절 지켜보셨던 거예요...",
          DialogueId = 51105033,
          GUID = "7FEF208E",
          NextDialogue = 51105037,
          SpeakNpcId = 700329,
          Subtitle = "*sniff*... I knew it... Nana's always watching over me... she's never really gone..."
        },
        [51105034] = {
          ContentKR = "난 월석 사냥꾼이야.",
          DialogueId = 51105034,
          GUID = "7FEF20B8",
          ImprPlusId = 1206,
          NextDialogue = 51105035,
          Subtitle = "I'm a Phoxhunter."
        },
        [51105035] = {
          ContentKR = "난 월석 사냥꾼이야. 화서식으로 말하면, 돈을 받고 문제를 해결해 주는 사람인 거지. 나한테 보수만 주면, 네 문제를 해결해 줄게.",
          DialogueId = 51105035,
          GUID = "7FEF20E2",
          NextDialogue = 51105036,
          SpeakNpcId = 100001,
          Subtitle = "I'm a Phoxhunter. Like you say in Huaxu — \"paid to fix your troubles.\" If you've got something to offer, I'll take care of your problem."
        },
        [51105036] = {
          ContentKR = "아! 뭔지 알겠어요. 엄마랑 아빠가 바다에 나갈 때, 실력 좋은 뱃사람을 구하는 거랑 똑같은 거잖아요! 그럼... 제가 모은 용돈을 전부 드릴게요.",
          DialogueId = 51105036,
          GUID = "7FEF210C",
          NextDialogue = 51105037,
          SpeakNpcId = 700329,
          Subtitle = "Oh! Just like when Mum and Dad hire sailors before going to sea! Then... I'll give you all my pocket money!",
          TalkActionId = {
            [1] = "700329:Explain02_End"
          }
        },
        [51105037] = {
          ContentKR = "그럼 잘 부탁드려요! 우리 집은 저쪽이에요...",
          DialogueId = 51105037,
          GUID = "7FEF2136",
          SpeakNpcId = 700329,
          Subtitle = "Thank you, then! My house is that way..."
        },
        [51105038] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "어떻게 된 건지 알 것 같아. 진실은 단 하나야. 영아의 할머니가 무유생으로 변해서, 영아의 주의를 끌려고 한 거지.",
          DialogueId = 51105038,
          GUID = "7FEF2B62",
          NextDialogue = 51105039,
          SpeakNpcId = 100001,
          Subtitle = "I think I've figured it out. There's only one explanation — Lingling's Nana became a Wishen... and she's been trying to reach her.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51105039] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "간단한 이치인데, 무유생을 볼 수 있는 사람은 워낙 드무니까, 귀신 소동으로 오해할 만도 해.",
          DialogueId = 51105039,
          GUID = "7FEF2B8C",
          NextDialogue = 51105040,
          SpeakNpcId = 100001,
          Subtitle = "It's a simple truth, really — but since most people can't see a Wishen, it's no wonder they thought it was a ghost."
        },
        [51105040] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "문제는... 영아한테 이게 귀신의 장난이 아니라, 무유생의 집착 때문이란 걸 어떻게 설명하지?",
          DialogueId = 51105040,
          GUID = "7FEF2BB6",
          NextOptions = {
            [1] = 51105041
          },
          RestartTag = 51105040,
          SpeakNpcId = 100001,
          Subtitle = "The real question is... how do I help Lingling understand that this isn't a haunting, but the echo of a Wishen's will?"
        },
        [51105041] = {
          ContentKR = "예전에 비슷한 문제를 겪었을 때, 누군가에게 도움을 받았었던 것 같은데...",
          DialogueId = 51105041,
          FailDialogue = 51105042,
          GUID = "7FEF2BE0",
          ImprCheckId = 1079,
          NextDialogue = 51105044,
          Subtitle = "You've dealt with something similar before. There is someone who might be able to help."
        },
        [51105042] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "(분명히 누군가 떠올랐는데, 순식간에 잊어버리고 말았다. 흔히 있는 일이지만, 타이밍이 좋지 않다.)",
          DialogueId = 51105042,
          GUID = "7FEF2C0A",
          NextDialogue = 51105043,
          Subtitle = "(You almost remembered... but the thought slipped away. It happens — just not at the best time.)",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51105043] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "조금 있으면 다시 생각나겠지, 뭐...",
          DialogueId = 51105043,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FEF2C34",
          SpeakNpcId = 100001,
          Subtitle = "Guess it'll come back to me soon..."
        },
        [51105044] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "전에 우곡에서 부소가 나한테 무유생을 볼 수 있게 해 줬어.",
          DialogueId = 51105044,
          GUID = "7FEF2C5E",
          NextDialogue = 51105045,
          SpeakNpcId = 100001,
          Subtitle = "Back in Yu Abysm... it was Fushu who helped me see a Wishen."
        },
        [51105045] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "영아가 무유생으로 변한 자기 할머니를 보게 되면, 더 이상 무서워하지 않을 거야. 무유생도 집착을 버리고 편히 잠들 수 있겠지.",
          DialogueId = 51105045,
          GUID = "7FEF2C88",
          NextDialogue = 51105046,
          SpeakNpcId = 100001,
          Subtitle = "If I can help Lingling see her Nana again, maybe she won't be scared anymore... and maybe the Wishen can finally rest."
        },
        [51105046] = {
          Camera = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
          ContentKR = "부소한테 가 봐야겠어.",
          DialogueId = 51105046,
          GUID = "7FEF2CB2",
          SpeakNpcId = 100001,
          Subtitle = "Time to pay Fushu a visit.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51105047] = {
          ContentKR = "또 만났네요, {nickname}.",
          DialogueId = 51105047,
          GUID = "7FEF3BCA",
          NextDialogue = 51105048,
          SpeakNpcId = 700330,
          Subtitle = "Ah, , we meet again.",
          TalkActionId = {
            [1] = "700330:Confident_Start"
          }
        },
        [51105048] = {
          ContentKR = "급한 일이라도 있는 건가요? 몸이 불편하신 거라면, 고영법으로 치료해 드릴 수 있어요.",
          DialogueId = 51105048,
          GUID = "7FEF3BF4",
          NextDialogue = 51105049,
          SpeakNpcId = 700330,
          Subtitle = "Do you come on urgent business, or has some affliction led you here — that I might tend to it with the Art of Ephemerality?"
        },
        [51105049] = {
          ContentKR = "부소에게 영아의 사연을 전부 이야기한다.",
          DialogueId = 51105049,
          GUID = "7FEF3C1E",
          IsBlack = 1,
          NextDialogue = 51105050,
          Subtitle = "You tell Fushu all about Lingling."
        },
        [51105050] = {
          ContentKR = "그랬군요... 가족을 그리워하는 마음은 저도 잘 알아요. 제 힘이 필요하다면, 기꺼이 도울게요.",
          DialogueId = 51105050,
          GUID = "7FEF3C48",
          NextDialogue = 51105051,
          SpeakNpcId = 700330,
          Subtitle = "I see... Such longing for one's kin — it is a feeling I know well. You have asked my aid, and so you shall have it.",
          TalkActionId = {
            [1] = "700330:Confident_End"
          }
        },
        [51105051] = {
          ContentKR = "다만... 제가 지금 일 때문에 자리를 비울 수가 없어서, 직접 그 아이를 만나러 갈 순 없어요.",
          DialogueId = 51105051,
          GUID = "7FEF3C72",
          NextDialogue = 51105052,
          SpeakNpcId = 700330,
          Subtitle = "However... there are matters I cannot set aside at present, and thus I cannot accompany the girl myself."
        },
        [51105052] = {
          ContentKR = "하지만 물건에 축유의 비술을 걸어 드릴 순 있어요. 그 물건을 몸에 지니면, 그 아이도 무유생을 볼 수 있을 거예요. 되도록 무유생과 그 아이, 모두에게 의미 있는 물건이 좋아요.",
          DialogueId = 51105052,
          GUID = "7FEF3C9C",
          NextDialogue = 51105053,
          SpeakNpcId = 700330,
          Subtitle = "But I can weave the Art of Zhuyou into an object — ideally one tied to both the child and the Wishen. So long as she keeps it with her, she shall be able to see the Wishen.",
          TalkActionId = {
            [1] = "700330:Explain02_Start"
          }
        },
        [51105053] = {
          ContentKR = "혹시 짚이는 물건이 있나요? 가져와 주시면, 바로 준비할게요.",
          DialogueId = 51105053,
          GUID = "7FEF3CC6",
          NextDialogue = 51105054,
          SpeakNpcId = 700330,
          Subtitle = "If you have such an item in mind, bring it to me — and I shall begin the process. Will that suffice?"
        },
        [51105054] = {
          ContentKR = "그래 주면 좋지. 고마워, 부소.",
          DialogueId = 51105054,
          GUID = "7FEF3CF0",
          SpeakNpcId = 100001,
          Subtitle = "Of course. Thank you, Fushu."
        },
        [51105055] = {
          ContentKR = "이 정도면 충분할 거야. 이제 부소한테 가자.",
          DialogueId = 51105055,
          GUID = "7FEF3D1A",
          SpeakNpcId = 100001,
          Subtitle = "That should do it. Time to give them to Fushu."
        },
        [51105056] = {
          ContentKR = "수고 많았어요. 금방 비술을 걸어 줄게요.",
          DialogueId = 51105056,
          GUID = "7FEF4C32",
          NextDialogue = 51105057,
          SpeakNpcId = 700330,
          Subtitle = "You have done well. I shall begin at once — it will not take long.",
          TalkActionId = {
            [1] = "700330:Baiheng_Story_Special03_Start"
          }
        }
      }
    end
  },
