          DialogueId = 51108008,
          GUID = "7FF18B90",
          NextDialogue = 51108009,
          SpeakNpcId = 100001,
          Subtitle = "I'm a merchant from Hyperborea, here in Huaxu for business."
        },
        [51108009] = {
          ContentKR = "휘페르보레아 제국? 거긴 카론한테 별로 우호적이지 않을 텐데... 용케 거기서 국제 무역을 하네? 가져다 팔고 싶은 물건 있어? 내가 다리 놔 줄게.",
          DialogueId = 51108009,
          GUID = "7FF18BBA",
          NextDialogue = 51108016,
          SpeakNpcId = 701008,
          Subtitle = "Hyperborea? Not the kindest place towards Charons, from what I've heard. A Charon engaged in international trade out of there — that's quite something. What goods do you handle? I can introduce you to a few contacts."
        },
        [51108010] = {
          ContentKR = "여행자",
          DialogueId = 51108010,
          GUID = "7FF18BE4",
          ImprPlusId = 1209,
          NextDialogue = 51108011,
          Subtitle = "Traveller"
        },
        [51108011] = {
          ContentKR = "난 연옥도라는 작은 섬에서 왔어. 지금은 아트라시아의 여러 나라를 여행 중이고.",
          DialogueId = 51108011,
          GUID = "7FF18C0E",
          NextDialogue = 51108012,
          SpeakNpcId = 100001,
          Subtitle = "I'm from a small island called Purgatorio Island. I'm travelling through the countries of Atlasia at the moment."
        },
        [51108012] = {
          ContentKR = "연옥도라... 처음 들어보는 곳이네. 뭐, 기왕 화서에 왔으니, 내가 기가 막힌 명소랑 식당 몇 군데 추천해 줄게. 지금까지 별로란 사람은 하나도 없었어.",
          DialogueId = 51108012,
          GUID = "7FF18C38",
          NextDialogue = 51108016,
