        },
        [51108018] = {
          ContentKR = "왜 도와주냐고... 하하, 내 얼굴 보면 감이 오지 않아? 나도 너처럼 외국인이야. 이스엘 출신이거든. 이스엘, 들어 봤어?",
          DialogueId = 51108018,
