        [51115027] = {
          ContentKR = "(소녀가 손에 든 공책을 넘긴다. 빽빽하게 채워진 종이가 적어도 70~80장은 넘어 보인다.)",
          DialogueId = 51115027,
          GUID = "7FF60B1E",
          NextDialogue = 51115028,
          Subtitle = "(She flips through the notebook. The writing is pressed so hard the ink has bled straight through the pages. By your guess, there must be seventy or eighty of them.)"
        },
        [51115028] = {
          ContentKR = "되게 많이 적었네... 언제부터 적기 시작한 거야?",
          DialogueId = 51115028,
          GUID = "7FF60B48",
          NextDialogue = 51115029,
          SpeakNpcId = 100001,
          Subtitle = "That's... a lot. How long have you been at this?"
        },
        [51115029] = {
          ContentKR = "음... 재작년 가을부터였나? 재재작년이었을지도... 기억이 잘 안 나.",
          DialogueId = 51115029,
          GUID = "7FF60B72",
          NextDialogue = 51115030,
          SpeakNpcId = 701019,
          Subtitle = "Erm... the autumn before last? Or maybe the year before that... I can't quite remember."
        },
        [51115030] = {
          ContentKR = "...준비가 너무 긴 거 아니야?",
          DialogueId = 51115030,
          GUID = "7FF60B9C",
          NextDialogue = 51115031,
          SpeakNpcId = 100001,
          Subtitle = "...Isn't that a rather long timetable for revenge?"
        },
        [51115031] = {
          ContentKR = "\"군자의 복수는 10년이 걸려도 늦지 않는다\"잖아!",
          DialogueId = 51115031,
          GUID = "7FF60BC6",
          NextDialogue = 51115032,
          SpeakNpcId = 701019,
          Subtitle = "They say revenge is a dish best served cold!"
        },
        [51115032] = {
          ContentKR = "복수도 하기 전에 녀석들이 먼저 망할 수도 있겠는데.",
          DialogueId = 51115032,
          GUID = "7FF60BF0",
          NextDialogue = 51115033,
          SpeakNpcId = 100001,
          Subtitle = "At this rate they'll go out of business before you get round to doing anything."
        },
        [51115033] = {
          ContentKR = "그걸 어떻게 알았어?",
          DialogueId = 51115033,
          GUID = "7FF60C1A",
          NextDialogue = 51115034,
          SpeakNpcId = 701019,
          Subtitle = "How did you know!?",
          TalkActionId = {
            [1] = "701019:Shock_Start"
          }
        },
        [51115034] = {
          ContentKR = "저번에 날 괴롭히던 녀석들도 내가 복수 계획을 반 정도 적었을 때 망해 버렸거든.",
          DialogueId = 51115034,
          GUID = "7FF60C44",
          NextDialogue = 51115035,
          SpeakNpcId = 701019,
          Subtitle = "The last supplier who pushed me around shut down halfway through my revenge plan!",
          TalkActionId = {
            [1] = "701019:Shock_End"
          }
        },
        [51115035] = {
          ContentKR = "그러니까, 네 진짜 계획은 \"누가 먼저 나가떨어지나 보자\"인 거네...",
          DialogueId = 51115035,
          GUID = "7FF60C6E",
          NextDialogue = 51115036,
          SpeakNpcId = 100001,
          Subtitle = "So your real plan is... just outlasting them?"
        },
        [51115036] = {
          ContentKR = "그럼 나보고 어떡하라고. 난 머리가 나쁘니까, 근성이라도 있어야 한단 말이야. '천 리 길도 한 걸음부터'란 말처럼!",
          DialogueId = 51115036,
          GUID = "7FF60C98",
          NextOptions = {
            [1] = 51115037,
            [2] = 51115042,
            [3] = 51115045
          },
          SpeakNpcId = 701019,
          Subtitle = "What else can I do? I'm not very clever — I just have to keep at it. As the old saying goes: \"Slow and steady wins the race.\" So I'll just keep writing!"
        },
        [51115037] = {
          ContentKR = "차라리 지류 대방님한테 도와달라고 해 봐.",
          DialogueId = 51115037,
          GUID = "7FF60CC2",
          ImprPlusId = 1207,
          NextDialogue = 51115038,
          Subtitle = "You could ask Zhiliu for help."
        },
        [51115038] = {
          ContentKR = "지, 지류 대방님한테?! 아, 안 돼! 바쁘신 분이라, 내 하소연 같은 거 들어줄 시간 없으실 거야...",
          DialogueId = 51115038,
          GUID = "7FF60CEC",
          NextDialogue = 51115039,
          SpeakNpcId = 701019,
          Subtitle = "P—Proprietress Zhiliu!? No, no — absolutely not... She's far too busy to listen to me whinge..."
        },
        [51115039] = {
          ContentKR = "내가 잘 아는데, 사실 되게 다정한 사람이야. 너희 행상인들한테도 엄청 신경 많이 쓰고.",
          DialogueId = 51115039,
          GUID = "7FF60D16",
          NextDialogue = 51115040,
          SpeakNpcId = 100001,
          Subtitle = "I know her. She's very kind — and she really does care about traders like you."
        },
        [51115040] = {
          ContentKR = "진짜...? 그러면 생각해 볼게. 가서 무슨 말 할지부터 생각해 봐야겠지만...",
          DialogueId = 51115040,
          GUID = "7FF60D40",
          NextDialogue = 51115041,
          SpeakNpcId = 701019,
          Subtitle = "Really...? Then... I'll think about it... Maybe practise what to say first..."
        },
        [51115041] = {
          ContentKR = "이러다 또 몇 년 걸리겠네...",
          DialogueId = 51115041,
          GUID = "7FF60D6A",
          NextDialogue = 51115047,
          SpeakNpcId = 100001,
          Subtitle = "Just don't spend another three years rehearsing it this time."
        },
        [51115042] = {
          ContentKR = "뭐, 그렇게 해서 네 마음이 조금이라도 풀린다면, 그것도 나쁘진 않지.",
          DialogueId = 51115042,
          GUID = "7FF60D94",
          ImprPlusId = 1209,
          NextDialogue = 51115043,
          Subtitle = "If it helps you feel better, then it might be worth doing."
        },
        [51115043] = {
          ContentKR = "고마워. 있잖아, 외국에서 온 사람들은 다들 원래 말을 이렇게 예쁘게 해?",
          DialogueId = 51115043,
          GUID = "7FF60DBE",
          NextDialogue = 51115044,
          SpeakNpcId = 701019,
          Subtitle = "Thanks! Are people from outside Huaxu all this nice?"
        },
        [51115044] = {
          ContentKR = "내 친구들은 그냥 현실 부정 아니냐고 매일 비웃기만 하거든. 솔직히 나도 알아... 아는데, 그래도 생각나는 게 이거밖에 없는걸.",
          DialogueId = 51115044,
          GUID = "7FF60DE8",
          NextDialogue = 51115047,
          SpeakNpcId = 701019,
          Subtitle = "My friends just laugh at me — say I'm deluding myself. And... honestly, I know that too. I just can't think of anything else to do."
        },
        [51115045] = {
          ContentKR = "내가 대신 복수해 줄 수도 있어. 보수만 주면.",
          DialogueId = 51115045,
          GUID = "7FF60E12",
          ImprPlusId = 1206,
          NextDialogue = 51115046,
          Subtitle = "I do offer revenge-for-hire, you know."
        },
        [51115046] = {
          ContentKR = "아냐, 아냐, 이런 목숨 걸린 위험한 일에 남을 끌어들일 순 없지.",
          DialogueId = 51115046,
          GUID = "7FF60E3C",
          NextDialogue = 51115047,
          SpeakNpcId = 701019,
          Subtitle = "No, no — I can't have someone risking their life on my account."
        },
        [51115047] = {
          ContentKR = "하... 그래도 이렇게 내 푸념 들어 줘서 정말 고마워.",
          DialogueId = 51115047,
          GUID = "7FF60E66",
          NextDialogue = 51115048,
          SpeakNpcId = 701019,
          Subtitle = "*sign*... Anyway, thanks for listening to me ramble."
        },
        [51115048] = {
          ContentKR = "탁 털어놓고 나니까, 마음이 많이 편해졌어... 오늘은 계획을 두 장은 적을 수 있을 것 같아!",
          DialogueId = 51115048,
          GUID = "7FF60E90",
          NextOptions = {
            [1] = 51115049
          },
          SpeakNpcId = 701019,
          Subtitle = "Talking to you's really helped... I think I can write two more pages today!"
        },
        [51115049] = {
          ContentKR = "...그래, 힘내.",
          DialogueId = 51115049,
          GUID = "7FF60EBA",
          NextDialogue = 51115050,
          Subtitle = "...Alright. Good luck."
        },
        [51115050] = {
          ContentKR = "(소녀는 붓을 들어 공책에 무언가를 끄적이며, 남이야 뭐라든, 또다시 자신의 복수 선언을 중얼거린다.)",
          DialogueId = 51115050,
          GUID = "7FF60EE4",
          Subtitle = "(She picks up her pen and starts scribbling once more, muttering new revenge ideas under her breath.)"
        },
        [51115051] = {
          ContentKR = "그래! 녀석들 베개에다 고춧가루를 집어넣는 거야... 후후...",
          DialogueId = 51115051,
          GUID = "7FF60F0E",
          SpeakNpcId = 701019,
          Subtitle = "I've got it! I'll put chilli powder in their pillows... heehee..."
        },
        [51116000] = {
          ContentKR = "{性别:친구|아가씨} 잠깐만요! 부탁 하나만 들어줘요!",
          DialogueId = 51116000,
          GUID = "7FF6AAC0",
          LookAt = {
            [1] = "701020:n(0)"
          },
          NextOptions = {
            [1] = 51116001
          },
          SpeakNpcId = 701020,
          Subtitle = "Good {性别：sir|lady}, pray wait a moment — I have a favour to ask."
        },
        [51116001] = {
          ContentKR = "무슨 일인데요?",
          DialogueId = 51116001,
          GUID = "7FF6AAEA",
          NextDialogue = 51116002,
          Subtitle = "What is it?"
        },
        [51116002] = {
          ContentKR = "작은 동물 몇 마리만 구해다 줄 수 없나요?",
          DialogueId = 51116002,
          GUID = "7FF6AB14",
          NextDialogue = 51116003,
          SpeakNpcId = 701020,
          Subtitle = "Could you help me catch a few small animals?",
          TalkActionId = {
            [1] = "701020:Talk01_Start"
          }
        },
        [51116003] = {
          ContentKR = "작은 동물이요...? 그걸 왜요?",
          DialogueId = 51116003,
          GUID = "7FF6AB3E",
          NextDialogue = 51116004,
          SpeakNpcId = 100001,
          Subtitle = "Small animals...? What exactly are you planning?"
        },
        [51116004] = {
          ContentKR = "죄 없는 동물을 해칠 생각은 없으니까 안심해요, {性别:친구|아가씨}. 그냥 오늘 여기서 연주를 할 건데, 동물들이 제 관객이 돼 줬으면 해서요.",
          DialogueId = 51116004,
          GUID = "7FF6AB68",
          NextDialogue = 51116005,
          SpeakNpcId = 701020,
          Subtitle = "Rest assured, good {性别：sir|lady} — I've no wish to harm a single living creature. I'm to perform on the zither here today, and hoped the little animals might be my audience."
        },
        [51116005] = {
          ContentKR = "왜 하필 동물이어야 하는데요?",
          DialogueId = 51116005,
          GUID = "7FF6AB92",
          NextDialogue = 51116006,
          SpeakNpcId = 100001,
          Subtitle = "Why animals, specifically?"
        },
        [51116006] = {
          ContentKR = "이 얘기를 모르시는군요. 옛날, 화서에는 아주 유명한 악사가 하나 있었어요. 연주 솜씨가 신의 경지에 이를 정도라, 동물들까지 와서 듣고 갈 정도였다고 해요.",
          DialogueId = 51116006,
          GUID = "7FF6ABBC",
          NextDialogue = 51116007,
          SpeakNpcId = 701020,
          Subtitle = "Perhaps you've not heard — in ancient Huaxu there lived a zither-master celebrated across the land. It's said that when she performed, even wild beasts would stop and listen.",
          TalkActionId = {
            [1] = "701020:Talk01_End"
          }
        },
        [51116007] = {
          ContentKR = "제 평생의 꿈이, 바로 그런 경지에 도달하는 거랍니다!",
          DialogueId = 51116007,
          GUID = "7FF6ABE6",
          NextDialogue = 51116008,
          SpeakNpcId = 701020,
          Subtitle = "It has long been my aspiration to reach such heights!",
          TalkActionId = {
            [1] = "701020:Confident_Start"
          }
        },
        [51116008] = {
          ContentKR = "그런데 이 연진 나루터 근처에 사는 동물들은 어찌나 겁이 많은지, 제가 와서 앉으면, 연주를 시작하기도 전에 다 도망가 버리더군요.",
          DialogueId = 51116008,
          GUID = "7FF6AC10",
          NextDialogue = 51116009,
          SpeakNpcId = 701020,
          Subtitle = "But the little creatures around Mistwharf are dreadfully timid. I had barely sat down — hadn't so much as touched the strings — before they all fled."
        },
        [51116009] = {
          ContentKR = "그래서 안타깝게도 제가 공들여 만든 곡을 들려 줄 기회가 없었어요...",
          DialogueId = 51116009,
          GUID = "7FF6AC3A",
          NextDialogue = 51116010,
          SpeakNpcId = 701020,
          Subtitle = "So I've never once had the chance to let them hear the piece I composed with such devotion. A pity... truly a pity.",
          TalkActionId = {
            [1] = "701020:Confident_End"
          }
        },
        [51116010] = {
          ContentKR = "제가 꿈을 이룰 수 있도록, {性别:친구|아가씨}가 동물들을 여기로 데려와 준다면, 사례는 섭섭지 않게 할게요.",
          DialogueId = 51116010,
          GUID = "7FF6AC64",
          NextOptions = {
            [1] = 51116011
          },
          RestartTag = 51116010,
          SpeakNpcId = 701020,
          Subtitle = "If you could bring them here and help me realise this wish, I'd be deeply grateful — and of course, you shall be handsomely rewarded."
        },
        [51116011] = {
          ContentKR = "알겠어요. 방법을 찾아보죠.",
          DialogueId = 51116011,
          FailDialogue = 51116012,
          GUID = "7FF6AC8E",
          ImprCheckId = 1124,
          NextDialogue = 51116013,
          Subtitle = "All right then — I'll see what I can do."
        },
        [51116012] = {
          ContentKR = "(다시 생각해 보자. 동물들을 어떻게 여기까지 데려오지?)",
          DialogueId = 51116012,
          GUID = "7FF6ACB8",
          SpeakNpcId = 100001,
          Subtitle = "(Now... how am I supposed to get animals to come over here?)"
        },
        [51116013] = {
          ContentKR = "잠시 고민한 끝에, 먹이를 이용해 동물들을 이 근처로 유인하기로 했다.",
          DialogueId = 51116013,
          GUID = "7FF6ACE2",
          IsBlack = 1,
          NextDialogue = 51116014,
          Subtitle = "After giving it some thought, you decide to attract them with food."
        },
        [51116014] = {
          ContentKR = "노력 끝에, 사슴과 새 몇 마리가 먹이 냄새를 쫓아 목현의 곁으로 다가왔다.",
          DialogueId = 51116014,
          GUID = "7FF6AD0C",
          IsBlack = 1,
          NextDialogue = 51116015,
          Subtitle = "Soon enough, a few birds and a deer follow the scent and draw near to Ju Mu."
        },
        [51116015] = {
          ContentKR = "이런 기막힌 방법이 있었다니! 정말 똑똑한 {性别:친구|아가씨}로군요! 보수는 여기 있으니 받아요, {性别:친구|아가씨}!",
          DialogueId = 51116015,
          GUID = "7FF6AD36",
          NextDialogue = 51116016,
          SpeakNpcId = 701020,
          Subtitle = "What a clever idea — truly ingenious, good {性别：sir|lady}! Your reward is prepared; please, accept it.",
          TalkActionId = {
            [1] = "701020:Give"
          }
        },
        [51116016] = {
          ContentKR = "이럴 때가 아니라, 지금 바로 연주를 시작해야겠어요. 혹시 {性别:친구|아가씨}도 관심 있으면, 꼭 듣고 가 줘요!",
          DialogueId = 51116016,
          GUID = "7FF6AD60",
          NextDialogue = 51116017,
          SpeakNpcId = 701020,
          Subtitle = "I shall begin at once. If you've the leisure, you are most welcome to stay and listen."
        },
        [51116017] = {
          ContentKR = "(목현이 진지하게 바닥에 앉아 소매를 걷어붙이더니, 손목을 위로 들어 연주를 시작한다...)",
          DialogueId = 51116017,
          GUID = "7FF6AD8A",
          NextDialogue = 51116018,
          Subtitle = "(Ju Mu settles himself with great ceremony, rolls up his sleeves, raises his hands — and begins to play...)"
        },
        [51116018] = {
          ContentKR = "(...그 순간, 아까 들렸던 기묘한 소음의 정체를 알 수 있었다.)",
          DialogueId = 51116018,
          GUID = "7FF6ADB4",
          NextDialogue = 51116019,
          Subtitle = "(...And at last you discover the source of that strange noise from earlier.)"
        },
        [51116019] = {
          ContentKR = "짹?!",
          DialogueId = 51116019,
          GUID = "7FF6ADDE",
          NextDialogue = 51116020,
          SpeakNpcName = "UI_CMNpc_Yanjindu_Name_Bird",
          Subtitle = "Cheep!?"
        },
        [51116020] = {
          ContentKR = "끼이잉——!",
          DialogueId = 51116020,
          GUID = "7FF6AE08",
          NextDialogue = 51116021,
          SpeakNpcName = "UI_CMNpc_Yanjindu_Name_Deer",
          Subtitle = "Brrh—!!"
        },
        [51116021] = {
          ContentKR = "(동물들은 먹던 음식마저 내팽개치고, 사방으로 뿔뿔이 도망친다.)",
          DialogueId = 51116021,
          GUID = "7FF6AE32",
          NextOptions = {
            [1] = 51116022,
            [2] = 51116023,
            [3] = 51116024
          },
          Subtitle = "(The animals scatter at once, abandoning their food mid-bite.)"
        },
        [51116022] = {
          ContentKR = "연습을 더 많이 하셔야겠는데요.",
          DialogueId = 51116022,
          GUID = "7FF6AE5C",
          ImprPlusId = 1207,
          NextDialogue = 51116025,
          Subtitle = "Looks like you've got a lot more practising to do."
        },
        [51116023] = {
          ContentKR = "제 귀에 비용을 지불하셔야겠는데요.",
          DialogueId = 51116023,
          GUID = "7FF6AE86",
          ImprPlusId = 1206,
          NextDialogue = 51116025,
          Subtitle = "You should be paying me for sitting through that."
        },
        [51116024] = {
          ContentKR = "와! 연주가 너무 훌륭해서 동물들도 가슴이 벅차올랐나 봐요!",
          DialogueId = 51116024,
          GUID = "7FF6AEB0",
          ImprPlusId = 1210,
          NextDialogue = 51116025,
          Subtitle = "Good heavens — you played so well the animals are all fired up!"
        },
        [51116025] = {
          ContentKR = "이, 이런 일이... 대체 뭐가 문제지...?",
          DialogueId = 51116025,
          GUID = "7FF6AEDA",
          NextDialogue = 51116026,
          SpeakNpcId = 701020,
          Subtitle = "H—How could this happen...? Why would it turn out like this...?"
        },
        [51116026] = {
          ContentKR = "아까 연주한 거, 진짜 음악 맞아요?",
          DialogueId = 51116026,
          GUID = "7FF6AF04",
          NextDialogue = 51116027,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure that even counts as music?"
        },
        [51116027] = {
          ContentKR = "'신의 경지에 이른 연주'는, 평범한 음악하곤 다른 면이 있어야 하잖아요.",
          DialogueId = 51116027,
          GUID = "7FF6AF2E",
          NextDialogue = 51116028,
          SpeakNpcId = 701020,
          Subtitle = "A piece meant to transcend the ordinary naturally sounds different from common tunes.",
          TalkActionId = {
            [1] = "701020:Talk02_Start"
          }
        },
        [51116028] = {
          ContentKR = "동물들도 감상할 수 있으려면, 소재를 자연에서 찾는 게 좋겠다고 생각했어요... 아까 그 곡은, 나뭇가지 부러지는 소리, 모기 날갯짓 소리, 들개가 땅 파는 소리 같은 걸 한데 모은 곡이었고요...",
          DialogueId = 51116028,
          GUID = "7FF6AF58",
          NextDialogue = 51116029,
          SpeakNpcId = 701020,
          Subtitle = "As it was meant to delight even animals, I thought it best to draw inspiration from nature. For instance, the piece I played included the snap of breaking branches, the buzz of insects' wings, and the sound of stray dogs scratching at the ground..."
        },
        [51116029] = {
          ContentKR = "완벽한 곡이라고 생각했는데, 지금 보니 다 헛수고였던 거군요...",
          DialogueId = 51116029,
          GUID = "7FF6AF82",
          NextOptions = {
            [1] = 51116030
          },
          SpeakNpcId = 701020,
          Subtitle = "I truly believed I'd poured my heart into a flawless composition... Never did I imagine all that effort would amount to nothing...",
          TalkActionId = {
            [1] = "701020:Talk02_End"
          }
        },
        [51116030] = {
          ContentKR = "소재로 삼은 소리부터 별로였던 건 아닐까요...",
          DialogueId = 51116030,
          GUID = "7FF6AFAC",
          NextDialogue = 51116031,
          Subtitle = "Is it possible that the sounds you chose are just... not very pleasant to begin with?"
        },
        [51116031] = {
          ContentKR = "......!",
          DialogueId = 51116031,
          GUID = "7FF6AFD6",
          NextDialogue = 51116032,
          SpeakNpcId = 701020,
          Subtitle = "...!"
        },
        [51116032] = {
          ContentKR = "{性别:친구|아가씨} 얘길 들으니 정신이 확 드네요!",
          DialogueId = 51116032,
          GUID = "7FF6B000",
          NextDialogue = 51116033,
          SpeakNpcId = 701020,
          Subtitle = "Good {性别：sir|lady}, you have enlightened me — with a single remark!",
          TalkActionId = {
            [1] = "701020:Sigh_Start"
          }
        },
        [51116033] = {
          ContentKR = "소재를 잘못 골랐던 거예요... 당장 돌아가서 곡을 다시 써야겠어요! 이번엔... 까마귀 울음소리, 들쥐가 뭔가 갉아 먹는 소리, 금속 긁히는 소리를 소재로... 음, 괜찮겠네요!",
          DialogueId = 51116033,
          GUID = "7FF6B02A",
          NextDialogue = 51116034,
          SpeakNpcId = 701020,
          Subtitle = "I see... the choice of sounds was at fault. I must go home and start afresh! Let me think... the cawing of crows, the gnawing of field mice, the scrape of metal on stone... yes, that should do nicely!",
          TalkActionId = {
            [1] = "701020:Sigh_End"
          }
        },
        [51116034] = {
          ContentKR = "(목현은 이미 자기만의 예술 세계에 푹 빠진 것 같다. 어쨌든 보수는 이미 받았으니, 귀 건강을 위해서라도 어서 자리를 뜨는 편이 좋겠다.)",
          DialogueId = 51116034,
          GUID = "7FF6B054",
          Subtitle = "(Ju Mu is utterly absorbed in his \"art\". Well, you've received your reward — best slip away now and spare your ears while you can.)"
        },
        [51116035] = {
          ContentKR = "새야, 여우야, 고양이야~ 도망가지 말고 한 곡만 더 듣고 가렴!",
          DialogueId = 51116035,
          GUID = "7FF6B07E",
          SpeakNpcId = 701020,
          Subtitle = "Little birds, little foxes, wild kittens — do not flee! Stay for just one more piece!"
        },
        [51117000] = {
          Camera = "-56.007812,179.976562,127.53125,0.000043,-7.60004,-107.399704,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "무유생이라니까!",
          DialogueId = 51117000,
          GUID = "7FF74ED0",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)"
          },
          NextDialogue = 51117001,
          SpeakNpcId = 701021,
          Subtitle = "It must be a Wishen!",
          TalkActionId = {
            [1] = "701021:Angry01_Start"
          }
        },
        [51117001] = {
          Camera = "-175.459961,-170.417969,118.708984,0.000063,-4.799348,68.995163,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "폐안 맞거든!",
          DialogueId = 51117001,
          GUID = "7FF74EFA",
          NextDialogue = 51117002,
          SpeakNpcId = 701022,
          Subtitle = "Nah-uh! It's a Bi'an!",
          TalkActionId = {
            [1] = "701022:Angry01_Start"
          }
        },
        [51117002] = {
          Camera = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(고영각 밖에서 꼬마 둘이 말다툼을 하고 있다. 무슨 일인가 싶어 걸음을 늦추자, 아이들의 눈길이 나에게 쏠린다...)",
          DialogueId = 51117002,
          GUID = "7FF74F24",
          NextDialogue = 51117003,
          Subtitle = "(Outside the Hall of Ephemerality, two children are loudly arguing about something. You slow your steps without meaning to — and they spot you.)",
          TalkActionId = {
            [1] = "701021:Angry01_End",
            [2] = "701022:Angry01_End"
          }
        },
        [51117003] = {
          ContentKR = "{性别:오빠|언니}!, {性别:오빠|언니}는 어떻게 생각해?",
          DialogueId = 51117003,
          GUID = "7FF74F4E",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)"
          },
          NextOptions = {
            [1] = 51117004
          },
          SpeakNpcId = 701021,
          Subtitle = "{性别：Sir|Miss}! What do you think?"
        },
        [51117004] = {
          ContentKR = "뭘 말이야?",
          DialogueId = 51117004,
          GUID = "7FF74F78",
          NextDialogue = 51117005,
          Subtitle = "Huh?"
        },
        [51117005] = {
          ContentKR = "하얀 그림자 말이야. 그게 도대체 뭘까?",
          DialogueId = 51117005,
          GUID = "7FF74FA2",
          NextDialogue = 51117006,
          SpeakNpcId = 701021,
          Subtitle = "What do you think the white shadow is?",
          TalkActionId = {
            [1] = "701021:Think_Start"
          }
        },
        [51117006] = {
          ContentKR = "하얀 그림자라니?",
          DialogueId = 51117006,
          GUID = "7FF74FCC",
          NextDialogue = 51117007,
          SpeakNpcId = 100001,
          Subtitle = "What white shadow?",
          TalkActionId = {
            [1] = "701021:Think_End"
          }
        },
        [51117007] = {
          Camera = "807.511719,-81.339844,690.010742,0.000093,5.194338,77.734879,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "옆에 있는 저택에 나타나는 그거 말이야! 우리 다 봤잖아.",
          DialogueId = 51117007,
          GUID = "7FF74FF6",
          NextDialogue = 51117008,
          SpeakNpcId = 701021,
          Subtitle = "The one that shows up in that house! We all saw it."
        },
        [51117008] = {
          ContentKR = "이리저리 날아다녔다가, 공중에 둥둥 떠 있다가, 갑자기 뿅 나타났다, 슉 사라졌다 하던데, 그게 대체 뭘까?",
          DialogueId = 51117008,
          GUID = "7FF75020",
          NextDialogue = 51117009,
          SpeakNpcId = 701021,
          Subtitle = "It flies about, floats in mid-air — comes and goes in a flash. What do you think it is?"
        },
        [51117009] = {
          Camera = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "폐안 맞다니까! 폐안은 법의 집행자라 사람들 앞에선 근엄해야 하는데, 맨날 얼마나 힘들겠어. 그러니까 빈집에 몰래 들어가서 노는 거야.",
          DialogueId = 51117009,
          GUID = "7FF7504A",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701022)"
          },
          NextDialogue = 51117010,
          SpeakNpcId = 701022,
          Subtitle = "I think it's a Bi'an! They're law-keepers, right? They have to act all serious in front of people — must be exhausting! So maybe they sneak into this empty house to run around and play.",
          TalkActionId = {
            [1] = "701022:Talk01_Start"
          }
        },
        [51117010] = {
          ContentKR = "바보야? 폐안이 대풍구장의 사자지 너네 집 강아지야? 놀긴 뭘 놀아! 그리고 저 집에 요즘 사람 살거든!",
          DialogueId = 51117010,
          GUID = "7FF75074",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117011,
          SpeakNpcId = 701021,
          Subtitle = "No way! A Bi'an's an enforcer of the Nine Chapters — it's not your pet dog. They don't need to play! And someone lives in that house now — it's not empty anymore.",
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117011] = {
          ContentKR = "내 생각엔 틀림없이 무유생이야. 저 집 집주인이었던 사람이 무유생이 된 거지. 집을 너무너무 좋아해서, 떠나기 싫으니까...",
          DialogueId = 51117011,
          GUID = "7FF7509E",
          NextDialogue = 51117012,
          SpeakNpcId = 701021,
          Subtitle = "I think the white shadow must be a Wishen! Maybe the last owner turned into one — they loved the house so much they never wanted to leave...",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117012] = {
          ContentKR = "집주인이 변한 거면, 왜 이제야 나타난 건데?",
          DialogueId = 51117012,
          GUID = "7FF750C8",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117013,
          SpeakNpcId = 701022,
          Subtitle = "If it really was the owner, why would it only show up now?",
          TalkActionId = {
            [1] = "701021:Talk02_End"
          }
        },
        [51117013] = {
          ContentKR = "무유생은 엄청 오래 살잖아. 그동안 어디 놀러 갔다 왔나 보지.",
          DialogueId = 51117013,
          GUID = "7FF750F2",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117014,
          SpeakNpcId = 701021,
          Subtitle = "Wishen can live for ages — maybe it was just out playing before!"
        },
        [51117014] = {
          ContentKR = "그치만 무유생은 하얀색이 아니잖아!",
          DialogueId = 51117014,
          GUID = "7FF7511C",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117015,
          SpeakNpcId = 701022,
          Subtitle = "But Wishen aren't even white!",
          TalkActionId = {
            [1] = "701022:Explain01_Start"
          }
        },
        [51117015] = {
          ContentKR = "하얀색 무유생이 있는지 없는지 네가 어떻게 알아? 그리고 무유생은 날 수 있잖아. 폐안은 못 날고!",
          DialogueId = 51117015,
          GUID = "7FF75146",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117016,
          SpeakNpcId = 701021,
          Subtitle = "How do you know there aren't white Wishen? Wishen can fly — Bi'an can't!",
          TalkActionId = {
            [1] = "701022:Explain01_End"
          }
        },
        [51117016] = {
          ContentKR = "너야말로 하늘을 나는 폐안이 있는지 없는지 어떻게 알아!",
          DialogueId = 51117016,
          GUID = "7FF75170",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117017,
          SpeakNpcId = 701022,
          Subtitle = "Then how do you know there aren't flying Bi'an?"
        },
        [51117017] = {
          ContentKR = "...흥! {性别:오빠|언니} 생각은 어때? 그건 무유생일까, 아니면 폐안일까?",
          DialogueId = 51117017,
          GUID = "7FF7519A",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)"
          },
          NextOptions = {
            [1] = 51117018
          },
          RestartTag = 51117017,
          SpeakNpcId = 701021,
          Subtitle = "...Hmph! {性别：Sir|Miss}, what do you think? Wishen or Bi'an?"
        },
        [51117018] = {
          ContentKR = "(하얀 그림자라... 대체 뭘까?)",
          DialogueId = 51117018,
          FailDialogue = 51117019,
          GUID = "7FF751C4",
          ImprCheckId = 1125,
          NextDialogue = 51117020,
          Subtitle = "(A white shadow... what could it be?)"
        },
        [51117019] = {
          ContentKR = "(지금은 딱히 떠오르는 게 없다.)",
          DialogueId = 51117019,
          GUID = "7FF751EE",
          Subtitle = "(Nothing comes to mind.)"
        },
        [51117020] = {
          ContentKR = "둘 다 아닐 것 같아. 그냥 저 집에 사는 사람이 키우는 동물이겠지.",
          DialogueId = 51117020,
          GUID = "7FF75218",
          NextDialogue = 51117021,
          SpeakNpcId = 100001,
          Subtitle = "I don't think either of you got it right. My guess? It's just the resident's pet.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51117021] = {
          ContentKR = "엥...?",
          DialogueId = 51117021,
          GUID = "7FF75242",
          NextDialogue = 51117022,
          SpeakNpcId = 701021,
          Subtitle = "Huh...?"
        },
        [51117022] = {
          ContentKR = "키운다면... 고양이나 강아지 같은 거? 근데 우리가 본 건 순식간에 뿅 사라졌단 말이야!",
          DialogueId = 51117022,
          GUID = "7FF7526C",
          NextDialogue = 51117023,
          SpeakNpcId = 701021,
          Subtitle = "A pet? Like a cat or a dog? But the shadow disappears so fast!",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117023] = {
          ContentKR = "맞아! 그리고 엄청 빨리 날아다녔어! 우리 집 고양이가 화들짝 놀라서 폴짝 뛸 때보다 빨랐다니까!",
          DialogueId = 51117023,
          GUID = "7FF75296",
          NextDialogue = 51117024,
          SpeakNpcId = 701022,
          Subtitle = "Yeah! And sometimes it moves even faster than our cat when it leaps up after getting scared by the rolling pin!",
          TalkActionId = {
            [1] = "701022:Think_Start",
            [2] = "701021:Talk02_End"
          }
        },
        [51117024] = {
          ContentKR = "못 믿겠으면 찾아가서 물어보면 되잖아.",
          DialogueId = 51117024,
          GUID = "7FF752C0",
          NextDialogue = 51117025,
          SpeakNpcId = 100001,
          Subtitle = "If you don't believe me, you could always knock on the door and ask.",
          TalkActionId = {
            [1] = "701022:Think_End"
          }
        },
        [51117025] = {
          ContentKR = "그, 그치만 누가 사는지 모르는데...",
          DialogueId = 51117025,
          GUID = "7FF752EA",
          NextDialogue = 51117026,
          SpeakNpcId = 701021,
          Subtitle = "B—But the person inside is a stranger...",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51117026] = {
          ContentKR = "우리 할머니가, 저 집엔 엄청나게 대단한 사람이 산다고 그랬어. 괜히 물어봤다가 막 화내면 어떡해?",
          DialogueId = 51117026,
          GUID = "7FF75314",
          NextDialogue = 51117028,
          SpeakNpcId = 701022,
          Subtitle = "My gran says someone really important lives in there. What if they get angry with us?"
        },
        [51117027] = {
          ContentKR = "세 번째 아이 등장",
          DialogueId = 51117027,
          GUID = "7FF7533E",
          Subtitle = "(A third child trots over.)"
        },
        [51117028] = {
          Camera = "-183.449219,717.648438,135.62793,0.000058,-3.004539,-77.045387,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어? 란예야, 왕남아, 너네 여기서 뭐 해?",
          DialogueId = 51117028,
          GUID = "7FF75368",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(100001)"
          },
          NextDialogue = 51117029,
          Scripts = "MoveTo{ActorId{701023},TargetPoint{\"YuXian_Target\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 701023,
          Subtitle = "Huh? Lan Ye, Wang Nan — what are you two doing out here?"
        },
        [51117029] = {
          Camera = "-157.855469,429.066406,150.193359,0.000067,-5.60486,-83.644531,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "전에 봤던 그 하얀 그림자가 뭔지 토론하고 있었어!",
          DialogueId = 51117029,
          GUID = "7FF75392",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117030,
          SpeakNpcId = 701021,
          Subtitle = "We're trying to figure out what the white shadow really is!"
        },
        [51117030] = {
          ContentKR = "아, 그거? 난 뭔지 아는데. 어제 여기 지나가다가 안에 사는 언니를 만났거든. 그 하얀 그림자는 '어룡'이래.",
          DialogueId = 51117030,
          GUID = "7FF753BC",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117031,
          SpeakNpcId = 701023,
          Subtitle = "Oh, that? I already know! I met the lady who lives there yesterday — she said the white shadow is a Fish-loong.",
          TalkActionId = {
            [1] = "701023:Explain01_Start"
          }
        },
        [51117031] = {
          ContentKR = "'염원'이랑 '그리움' 같은 어려운 말을 잔뜩 써서 설명해 줬는데, 잘은 모르겠고... 아무튼 애완동물 비슷한 거야!",
          DialogueId = 51117031,
          GUID = "7FF753E6",
          NextDialogue = 51117032,
          SpeakNpcId = 701023,
          Subtitle = "She started talking about \"remembrance\" and \"someone dearly missed\"... I didn't really get it. Anyway, it's basically like a little pet!"
        },
        [51117032] = {
          ContentKR = "그 언니가 '어룡'을 한 마리 소환해서 보여 줬는데, 물 만지는 느낌처럼 차가워서, 엄청 신기했어!",
          DialogueId = 51117032,
          GUID = "7FF75410",
          NextDialogue = 51117033,
          SpeakNpcId = 701023,
          Subtitle = "She even summoned one for me! It felt like it was made of water — all soft and cool. It was amazing!",
          TalkActionId = {
            [1] = "701023:Explain01_End"
          }
        },
        [51117033] = {
          ContentKR = "뭐?!",
          DialogueId = 51117033,
          GUID = "7FF7543A",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117034,
          SpeakNpcId = 701021,
          Subtitle = "What!?"
        },
        [51117034] = {
          ContentKR = "지, 진짜 애완동물이었을 줄이야...",
          DialogueId = 51117034,
          GUID = "7FF75464",
          LookAt = {
