            [3] = 51117044
          },
          SpeakNpcId = 701021,
          Subtitle = "I honestly thought {性别：he|she} was joking..."
        },
        [51117036] = {
          ContentKR = "사실 나도 저 집에 사는 사람을 만나 본 적이 있거든. 그래서 맞힌 거야.",
          DialogueId = 51117036,
          GUID = "7FF754B8",
          ImprPlusId = 1207,
          NextDialogue = 51117037,
          Subtitle = "I've met that lady before — that's how I knew."
        },
        [51117037] = {
          ContentKR = "그게 진짜야? 나도 만나러 갈래!",
          DialogueId = 51117037,
          GUID = "7FF754E2",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117038,
          SpeakNpcId = 701021,
          Subtitle = "You've seen her too? Then I want to meet her!",
          TalkActionId = {
            [1] = "701021:Talk01_Start"
          }
        },
        [51117038] = {
          ContentKR = "나도! 나도, 나도!",
          DialogueId = 51117038,
          GUID = "7FF7550C",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117039,
          SpeakNpcId = 701022,
          Subtitle = "Me too! Me too!"
        },
        [51117039] = {
          ContentKR = "음... 그럼 다음엔 맛있는 거 챙겨가서 그 언니랑 같이 놀자. '어룡'도 보여 달라고 하고~",
          DialogueId = 51117039,
          GUID = "7FF75536",
          NextDialogue = 51117048,
          SpeakNpcId = 701021,
          Subtitle = "Hmm... next time let's bring some snacks and go visit her! Maybe she'll show us a Fish-loong!",
          TalkActionId = {
            [1] = "701021:Talk01_End"
          }
        },
        [51117040] = {
          ContentKR = "어쩌면 너희가 본 건 어룡이 아닐 수도 있어.",
          DialogueId = 51117040,
          GUID = "7FF75560",
          ImprPlusId = 1209,
          NextDialogue = 51117041,
          Subtitle = "Maybe you saw a different white shadow."
        },
        [51117041] = {
          ContentKR = "하긴 그러네!",
          DialogueId = 51117041,
          GUID = "7FF7558A",
          LookAt = {
            [1] = "701021:n(701021)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)",
            [4] = "701023:n(701021)"
          },
          NextDialogue = 51117042,
          SpeakNpcId = 701021,
          Subtitle = "Oh! That actually makes sense!",
          TalkActionId = {
            [1] = "701021:Talk01_Start"
          }
        },
        [51117042] = {
          ContentKR = "그 집엔 어룡이랑 폐안이랑 무유생이 다 같이 사는 걸지도 몰라!",
          DialogueId = 51117042,
          GUID = "7FF755B4",
          NextDialogue = 51117043,
          SpeakNpcId = 701021,
          Subtitle = "Maybe there's a Fish-loong, and a Bi'an, and a Wishen all living in there!"
        },
        [51117043] = {
          ContentKR = "그러면 우리 둘 다 맞힌 거네! 야호~",
          DialogueId = 51117043,
          GUID = "7FF755DE",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117048,
          SpeakNpcId = 701022,
          Subtitle = "Then we were all right! Yay~!",
          TalkActionId = {
            [1] = "701021:Talk01_End"
          }
        },
        [51117044] = {
          ContentKR = "후후, 이게 바로 어른의 실력이란 거야.",
          DialogueId = 51117044,
          GUID = "7FF75608",
          ImprPlusId = 1210,
          NextDialogue = 51117045,
          Subtitle = "Heh-heh~ I know that because I'm a smart grown-up."
        },
        [51117045] = {
          ContentKR = "그럼 나도 커서 이렇게 똑똑한 어른이 될래.",
          DialogueId = 51117045,
          GUID = "7FF75632",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117046,
          SpeakNpcId = 701022,
          Subtitle = "When I grow up, I'm going to be just as smart!",
          TalkActionId = {
            [1] = "701022:Talk01_Start"
          }
        },
        [51117046] = {
          ContentKR = "난 이 {性别:오빠|언니}보다 훨씬 더 똑똑해질 거야!",
          DialogueId = 51117046,
          GUID = "7FF7565C",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117047,
          SpeakNpcId = 701021,
          Subtitle = "Then I'll be even smarter!",
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117047] = {
          ContentKR = "그럼 여기서 이러고 있으면 안 되지. 얼른 집에 가서 숙제해.",
          DialogueId = 51117047,
          GUID = "7FF75686",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117048,
          SpeakNpcId = 701023,
          Subtitle = "Then what are the two of you still standing here for? Messing about won't make you smarter. Go on — get your homework done!"
        },
        [51117048] = {
          ContentKR = "(아이들은 재잘거리며 집으로 돌아갔다. 다음에 부소를 만나면, 이 재미있는 이야기를 꼭 전해 줘야겠다.)",
          DialogueId = 51117048,
          GUID = "7FF756B0",
          Scripts = [[
PARA{
MoveTo{ActorId{701021},TargetPoint{"LanYe_Leave_Target"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701022},TargetPoint{"WangNan_Leave_Target"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701023},TargetPoint{"YuXian_Leave_Target"},MoveSpeed{100},Visibility{"Hide"}}
}]],
          Subtitle = "(The children scamper off, laughing and chattering. Perhaps the next time you see Fushu, you can share this little tale.)"
        },
        [51118000] = {
          ContentKR = "으음... 왜 아직도 안 오지...",
          DialogueId = 51118000,
          GUID = "7FF7F2E0",
          NextDialogue = 51118001,
          SpeakNpcId = 701024,
          Subtitle = "Aw... why isn't he here yet...?",
          TalkActionId = {
            [1] = "701024:Sigh_Start"
          }
        },
        [51118001] = {
          ContentKR = "(소녀가 눈을 반쯤 감은 채, 처마 밑에 앉아 무언가 중얼거리고 있다. 그대로 지나치려는데, 소녀가 갑자기 바닥으로 고꾸라진다.)",
          DialogueId = 51118001,
          GUID = "7FF7F30A",
          NextDialogue = 51118002,
          Subtitle = "(Eyes half-closed, the little girl mumbles under the eaves. As you walk past, she suddenly slumps forward.)"
        },
        [51118002] = {
          ContentKR = "어?!",
          DialogueId = 51118002,
          GUID = "7FF7F334",
          NextDialogue = 51118003,
          SpeakNpcId = 100001,
          Subtitle = "Ah!?"
        },
        [51118003] = {
          ContentKR = "(서둘러 소녀의 상태를 살핀다. 어깨를 토닥이자, 소녀가 부스스 눈을 깜빡이며 일어난다.)",
          DialogueId = 51118003,
          GUID = "7FF7F35E",
          NextDialogue = 51118004,
          Subtitle = "(You rush over. A light tap on her shoulder makes her blink awake, and she pushes herself upright.)"
        },
        [51118004] = {
          ContentKR = "우음...",
          DialogueId = 51118004,
          GUID = "7FF7F388",
          NextOptions = {
            [1] = 51118005
          },
          SpeakNpcId = 701024,
          Subtitle = "Nnh..."
        },
        [51118005] = {
          ContentKR = "꼬마야, 괜찮니?",
          DialogueId = 51118005,
          GUID = "7FF7F3B2",
          NextDialogue = 51118006,
          Subtitle = "Are you all right?"
        },
        [51118006] = {
          ContentKR = "아, 전 괜찮아요. 그냥 졸려서 그래요... 고마워요, {性别:오빠|언니}.",
          DialogueId = 51118006,
          GUID = "7FF7F3DC",
          LookAt = {
            [1] = "701024:n(0)"
          },
          NextDialogue = 51118007,
          SpeakNpcId = 701024,
          Subtitle = "Mm... I'm fine. Just really, really sleepy... Thank you, {性别：sir|miss}.",
          TalkActionId = {
            [1] = "701024:Sigh_End"
          }
        },
        [51118007] = {
          ContentKR = "졸리면 들어가서 자지, 왜 여기서 이러고 있어?",
          DialogueId = 51118007,
          GUID = "7FF7F406",
          NextDialogue = 51118008,
          SpeakNpcId = 100001,
          Subtitle = "If you're tired, why not go home and get some rest?"
        },
        [51118008] = {
          ContentKR = "오빠를 기다리고 있어요! 우리 오빠는 별을 잇는 자라서 이곳저곳 돌아다니는데요, 매년 이맘때면 꼭 선물이랑 편지를 가져오거든요.",
          DialogueId = 51118008,
          GUID = "7FF7F430",
          NextDialogue = 51118009,
          SpeakNpcId = 701024,
          Subtitle = "I'm waiting for my big brother! He's a Starweaver — always travelling around. But every year around this time, he brings me presents and a letter.",
          TalkActionId = {
            [1] = "701024:Talk02_Start"
          }
        },
        [51118009] = {
          ContentKR = "집 안에서 기다려도 되지 않을까?",
          DialogueId = 51118009,
          GUID = "7FF7F45A",
          NextDialogue = 51118010,
          SpeakNpcId = 100001,
          Subtitle = "Can't you wait for him at home?"
        },
        [51118010] = {
          ContentKR = "그러면 오빠 얼굴을 못 보는걸요. 매번 올 때마다 문 앞에 선물이랑 편지만 두고 가 버리거든요. 아침에 일어나서 나가 보면 사라지고 없어요.",
          DialogueId = 51118010,
          GUID = "7FF7F484",
          NextDialogue = 51118011,
          SpeakNpcId = 701024,
          Subtitle = "Then I'd miss him. He never comes inside — he leaves the presents at the door really early in the morning. By the time I wake up, he's already gone."
        },
        [51118011] = {
          ContentKR = "그래서 올해는 오빠가 올 때까지, 문 앞에서 꼭 지키고 있으려고요!",
          DialogueId = 51118011,
          GUID = "7FF7F4AE",
          NextDialogue = 51118012,
          SpeakNpcId = 701024,
          Subtitle = "So this year I'm waiting right here. I have to see him for real!"
        },
        [51118012] = {
          ContentKR = "그런데 몇 시에 올지 몰라서 새벽부터 계속 기다렸는데... 하암... 아직도 안 왔어요... 하아암...",
          DialogueId = 51118012,
          GUID = "7FF7F4D8",
          NextOptions = {
            [1] = 51118013
          },
          RestartTag = 51118012,
          SpeakNpcId = 701024,
          Subtitle = "But I don't know when he'll come, so I started waiting in the middle of the night... yawn... and he still hasn't come... yawn...",
          TalkActionId = {
            [1] = "701024:Talk02_End"
          }
        },
        [51118013] = {
          ContentKR = "(소녀를 도울 방법을 생각해 보자.)",
          DialogueId = 51118013,
          FailDialogue = 51118014,
          GUID = "7FF7F502",
          ImprCheckId = 1126,
          NextDialogue = 51118015,
          Subtitle = "(Think about how you can help her.)"
        },
        [51118014] = {
          ContentKR = "(하암... 하품도 전염되는지, 졸리기 시작한다.)",
          DialogueId = 51118014,
          GUID = "7FF7F52C",
          Subtitle = "(Yawn... you're feeling sleepy too.)"
        },
        [51118015] = {
          ContentKR = "혹시 네가 거기서 기다리고 있으니까, 오빠가 안 나타나는 건 아닐까?",
          DialogueId = 51118015,
          GUID = "7FF7F556",
          NextDialogue = 51118016,
          SpeakNpcId = 100001,
          Subtitle = "What if he's not coming because he sees you waiting?"
        },
        [51118016] = {
          ContentKR = "어? 그게 무슨 말이에요?",
          DialogueId = 51118016,
          GUID = "7FF7F580",
          NextDialogue = 51118017,
          SpeakNpcId = 701024,
          Subtitle = "Huh? What do you mean?",
          TalkActionId = {
            [1] = "701024:Think_Start"
          }
        },
        [51118017] = {
          ContentKR = "오빠는 너한테 깜짝선물을 주고 싶은 걸지도 모르잖아.",
          DialogueId = 51118017,
          GUID = "7FF7F5AA",
          NextDialogue = 51118018,
          SpeakNpcId = 100001,
          Subtitle = "Maybe he wants to surprise you."
        },
        [51118018] = {
          ContentKR = "그치만 나는 깜짝선물보다, 우리 오빠를 보고 싶은데...",
          DialogueId = 51118018,
          GUID = "7FF7F5D4",
          NextDialogue = 51118019,
          SpeakNpcId = 701024,
          Subtitle = "But I want to see him more than I want a surprise...",
          TalkActionId = {
            [1] = "701024:Think_End"
          }
        },
        [51118019] = {
          ContentKR = "그럼 이렇게 해보자.",
          DialogueId = 51118019,
          GUID = "7FF7F5FE",
          NextDialogue = 51118020,
          SpeakNpcId = 100001,
          Subtitle = "Then I've got an idea."
        },
        [51118020] = {
          ContentKR = "넌 바로 방에 들어가서 자는 척해. 난 저기 구석에 숨어 있다가, 네 오빠가 오면 나와서 딱 붙잡아 둘게. 어때?",
          DialogueId = 51118020,
          GUID = "7FF7F628",
          NextDialogue = 51118021,
          SpeakNpcId = 100001,
          Subtitle = "You go inside and pretend to sleep. I'll keep an eye on the door from over there — and if your brother comes, I'll grab him for you. What do you think?"
        },
        [51118021] = {
          ContentKR = "하아암... 어?! 진짜 {性别:오빠|언니}가 대신 기다려 줄 거예요? 와, 진짜 착하다! 정말 고마워요!",
          DialogueId = 51118021,
          GUID = "7FF7F652",
          NextDialogue = 51118022,
          SpeakNpcId = 701024,
          Subtitle = "Yaaawn... huh!? You mean... you'll wait here for me? Really!? You're so kind, {性别：sir|miss}!"
        },
        [51118022] = {
          ContentKR = "오빠 이름이 뭐야?",
          DialogueId = 51118022,
          GUID = "7FF7F67C",
          NextDialogue = 51118023,
          SpeakNpcId = 100001,
          Subtitle = "What's your brother's name?"
        },
        [51118023] = {
          ContentKR = "조우요.",
          DialogueId = 51118023,
          GUID = "7FF7F6A6",
          NextDialogue = 51118024,
          SpeakNpcId = 701024,
          Subtitle = "Zhaoyu."
        },
        [51118024] = {
          ContentKR = "알겠어, 기억해 둘게.",
          DialogueId = 51118024,
          GUID = "7FF7F6D0",
          NextDialogue = 51118025,
          SpeakNpcId = 100001,
          Subtitle = "Got it."
        },
        [51118025] = {
          ContentKR = "(소녀는 눈을 비비며 비틀비틀 방으로 들어가고, 나는 구석에 자리를 잡고 망을 보기 시작한다.)",
          DialogueId = 51118025,
          GUID = "7FF7F6FA",
          Subtitle = "(Nodding drowsily, she totters indoors. You move to a corner and watch in silence.)"
        },
        [51118026] = {
          ContentKR = "(소녀가 들어간 지 얼마 지나지 않아, 정말로 청년 하나가 나타난다. 주위를 두리번거리던 청년은 문 앞에 잽싸게 선물 꾸러미를 내려놓고, 자리를 떠나려 몸을 돌린다.)",
          DialogueId = 51118026,
          GUID = "7FF7F724",
          Subtitle = "(And sure enough — not long after she leaves, a young man appears. He glances around, sets a parcel at the door in haste, and turns to go.)"
        },
        [51118027] = {
          ContentKR = "잠깐만요!",
          DialogueId = 51118027,
          GUID = "7FF7F74E",
          LookAt = {
            [1] = "701025:n(0)"
          },
          NextDialogue = 51118028,
          SpeakNpcId = 100001,
          Subtitle = "Wait!"
        },
        [51118028] = {
          ContentKR = "어?!",
          DialogueId = 51118028,
          GUID = "7FF7F778",
          NextDialogue = 51118029,
          SpeakNpcId = 701025,
          Subtitle = "Huh!?",
          TalkActionId = {
            [1] = "701025:Shock_Start"
          }
        },
        [51118029] = {
          ContentKR = "조우 씨 맞죠!",
          DialogueId = 51118029,
          GUID = "7FF7F7A2",
          NextDialogue = 51118030,
          SpeakNpcId = 100001,
          Subtitle = "You're Zhaoyu, aren't you?"
        },
        [51118030] = {
          ContentKR = "(이름을 들은 남자가 놀란 표정을 짓더니, 잠시 굳어 있다가, 무겁게 입을 연다.)",
          DialogueId = 51118030,
          GUID = "7FF7F7CC",
          NextDialogue = 51118031,
          Subtitle = "(He freezes at the name, then after a long silence finally speaks.)",
          TalkActionId = {
            [1] = "701025:Shock_End"
          }
        },
        [51118031] = {
          ContentKR = "아뇨... 전 조우가 아니에요.",
          DialogueId = 51118031,
          GUID = "7FF7F7F6",
          NextDialogue = 51118032,
          SpeakNpcId = 701025,
          Subtitle = "No... I'm not Zhaoyu.",
          TalkActionId = {
            [1] = "701025:Talk01_Start"
          }
        },
        [51118032] = {
          ContentKR = "그런데 어떻게 그 이름을 알고 계시는 거죠? 설마 아는 사이신가요?",
          DialogueId = 51118032,
          GUID = "7FF7F820",
          NextDialogue = 51118033,
          SpeakNpcId = 701025,
          Subtitle = "How did you know that name? Do you know him?"
        },
        [51118033] = {
          ContentKR = "조우 씨 여동생이랑 아는 사이예요. 문 앞에서 계속 오빠를 기다리고 있더라고요.",
          DialogueId = 51118033,
          GUID = "7FF7F84A",
          NextDialogue = 51118034,
          SpeakNpcId = 100001,
          Subtitle = "I know his little sister. She's been expecting him."
        },
        [51118034] = {
          ContentKR = "그랬군요... 청아가 오빠를 만나고 싶어서 계속 기다리고 있었나 보네요.",
          DialogueId = 51118034,
          GUID = "7FF7F874",
          NextDialogue = 51118035,
          SpeakNpcId = 701025,
          Subtitle = "...So Qingqing sat here because she wanted to see her brother. I see.",
          TalkActionId = {
            [1] = "701025:Talk01_End"
          }
        },
        [51118035] = {
