          DialogueId = 51118036,
          GUID = "7FF7F8C8",
          NextDialogue = 51118037,
          SpeakNpcId = 100001,
          Subtitle = "Why? Who are you?"
        },
        [51118037] = {
          ContentKR = "저는 조우의 친구예요. 몇 해 전, 그 친구와 같은 상단에서 일할 때, 배에 침몰 사고가 있었어요. 그 친구는... 수영을 못 하는 절 구하려다 목숨을 잃고 말았죠.",
          DialogueId = 51118037,
          GUID = "7FF7F8F2",
          NextDialogue = 51118038,
          SpeakNpcId = 701025,
          Subtitle = "An old friend of his. Years ago, our caravan took ship for an overseas trade. The ship went down, and... Zhaoyu died saving me. I couldn't swim.",
          TalkActionId = {
            [1] = "701025:Talk02_Start"
          }
        },
        [51118038] = {
          ContentKR = "그 은혜는 평생 다 갚을 수 없겠지만... 적어도 친구가 끔찍이 아끼던 여동생만은 상처받지 않았으면 해서, 이런 방법을 생각해 낸 거예요.",
          DialogueId = 51118038,
          GUID = "7FF7F91C",
          NextDialogue = 51118039,
          SpeakNpcId = 701025,
          Subtitle = "I can never repay him. But I couldn't bear the thought of the little sister he cherished falling into grief. So I started doing this."
        },
        [51118039] = {
          ContentKR = "청아가 어른이 될 때까지, 제가 매년 그 친구인 척하고 선물과 편지를 보내 주는 거죠.",
          DialogueId = 51118039,
          GUID = "7FF7F946",
          NextDialogue = 51118040,
          SpeakNpcId = 701025,
          Subtitle = "Until she grows up, I'll bring gifts and letters in his place. Every year."
        },
        [51118040] = {
          ContentKR = "그런 사연이 있었군요...",
          DialogueId = 51118040,
          GUID = "7FF7F970",
          NextDialogue = 51118041,
