          }
        },
        [51118046] = {
          ContentKR = "오빠는 이미 떠났어.",
          DialogueId = 51118046,
          GUID = "7FF7FA6C",
          NextDialogue = 51118047,
          SpeakNpcId = 100001,
          Subtitle = "He's already gone.",
          TalkActionId = {
            [1] = "701024:Talk01_End",
