        [51125039] = {
          Camera = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "네... 네 녀석의 가문은 대대로 현형파의 향관을 배출한 충신 집안이거늘, 어찌...",
          DialogueId = 51125039,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FFC75B6",
          NextDialogue = 51125040,
          SpeakNpcId = 100001,
          Subtitle = "Your... your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like—"
        },
        [51125040] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그게 뭐 어쨌다는 거냐!",
          DialogueId = 51125040,
          GUID = "7FFC75E0",
          NextDialogue = 51125041,
          SpeakNpcId = 700366,
          Subtitle = "So what!"
        },
        [51125041] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "제 대사 아직 안 끝났다니까요!",
          DialogueId = 51125041,
          GUID = "7FFC760A",
          NextDialogue = 51125042,
          SpeakNpcId = 100001,
          Subtitle = "Hey, what's wrong with you?",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51125042] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아이고, 내 정신 좀 봐. 진짜 미안, 미안. 연기에 너무 몰입했나 봐. 다시 할게, 다시.",
          DialogueId = 51125042,
          GUID = "7FFC7634",
          NextDialogue = 51125043,
          SpeakNpcId = 700366,
          Subtitle = "Ah, blast — sorry, sorry! Really got into the moment there. Again, from the top.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          }
        },
        [51125043] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"네 녀석의 가문은 대대로 현형파의 향관을 배출한 충신 집안이거늘, 어찌 너 같은 인간 말종이 나왔단 말이냐!\", 이거 끝날 때까지 대사 치지 마세요, 알겠죠?",
          DialogueId = 51125043,
          GUID = "7FFC765E",
          NextDialogue = 51125044,
          SpeakNpcId = 100001,
          Subtitle = "Do not speak your line — at all — until I finish: \"Your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like you?\" Understood?"
        },
        [51125044] = {
          Camera = "325.265625,-73.105469,141.634766,0.017556,-1.600095,166.905365,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그럼, 제대로 기억해 뒀어! 이번엔 절대 안 잊어버릴게!",
          DialogueId = 51125044,
          GUID = "7FFC7688",
          NextDialogue = 51125045,
          SpeakNpcId = 700366,
          Subtitle = "Understood! Won't happen this time!",
          TalkActionId = {
            [1] = "700366:Talk03_End"
          }
        },
        [51125045] = {
          DialogueId = 51125045,
          GUID = "7FFC76B2",
          IsBlack = 1,
          NextDialogue = 51125046
        },
        [51125046] = {
          ContentKR = "큭큭, 날고 기는 응천위 나리라도 뒤에서 날아드는 독침은 당해 낼 수 없나 보군!",
          DialogueId = 51125046,
          GUID = "7FFC76DC",
          NextDialogue = 51125047,
          SpeakNpcId = 700366,
          Subtitle = "Heh. Your Honour, for all your prowess, you never stood a chance against a needle in the back.",
          TalkActionId = {
            [1] = "700366:Talk03_Start"
          }
        },
        [51125047] = {
          Camera = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "네... 네 녀석의 가문은 대대로 현형파의 향관을 배출한 충신 집안이거늘, 어찌 너 같은 인간 말종이 나왔단 말이냐!",
          DialogueId = 51125047,
          GUID = "7FFC7706",
          NextDialogue = 51125048,
          SpeakNpcId = 100001,
          Subtitle = "Your... your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like you?"
        },
        [51125048] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그게 뭐 어쨌다는 거냐!",
          DialogueId = 51125048,
          GUID = "7FFC7730",
          NextDialogue = 51125049,
          SpeakNpcId = 700366,
          Subtitle = "So what!"
        },
        [51125049] = {
          ContentKR = "우리 현형파는 쥐꼬리만 한 보수나 받으면서, 일 년에 며칠 쉬지도 못하고, 하루 종일 죽어라 향만 피운다고.",
          DialogueId = 51125049,
          GUID = "7FFC775A",
          NextDialogue = 51125050,
          SpeakNpcId = 700366,
          Subtitle = "What did we even get out of working for the Xuanheng Sect, huh? Barely any pay, breathing in incense ash all day, hardly any days off."
        },
        [51125050] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "게다가 우리는 지나다니는 개 한 마리도 못 건드려. 개 주인이 학대니 뭐니 따지고 들면, 대풍구장을 어기는 게 돼 버릴 테니까.",
          DialogueId = 51125050,
          GUID = "7FFC7784",
          NextDialogue = 51125051,
          SpeakNpcId = 700366,
          Subtitle = "And we were always bound by the Nine Chapters — couldn't even kick a dog on the street! What if it had an owner? We'd be punished by Bi'an!"
        },
        [51125051] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니, 잠깐만요...",
          DialogueId = 51125051,
          GUID = "7FFC77AE",
          NextDialogue = 51125052,
          SpeakNpcId = 100001,
          Subtitle = "Wait a minute...",
          TalkActionId = {
            [1] = "100001:RaiseHand_Start"
          }
        },
        [51125052] = {
          ContentKR = "다들 그냥, 잘되면 백룡신군 덕이고 안되면 우리 때문이지! 그럴 바에야 자유로운 나그네가 되는 게 훨씬 낫다고! 바로 나!그! 네!",
          DialogueId = 51125052,
          GUID = "7FFC77D8",
          NextDialogue = 51125053,
          SpeakNpcId = 700366,
          Subtitle = "None of the credit, either — when things went well, it was \"All praise to Lord Argent\" When they went south, it was our fault! I'd rather be a Drifter — free as the wind! I! Am! A! Drifter—!"
        },
        [51125053] = {
          Camera = "-352.015625,-106.05957,152.610352,0.017523,-3.999574,17.508425,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니, 좀! 그거 대본에 있는 대사 맞아요?",
          DialogueId = 51125053,
          GUID = "7FFC7802",
          NextDialogue = 51125054,
          SpeakNpcId = 100001,
          Subtitle = "Stop! Is any of this in the script?!",
          TalkActionId = {
            [1] = "100001:RaiseHand_End"
          }
        },
        [51125054] = {
          ContentKR = "대본대로면 \"그게 뭐 어쨌다는 거냐!\"라고 한 다음에 저한테 달려드는 거잖아요. 그럼 제가 고통을 참으면서 나그네 몇 명을 상대하다가 전부 쓰러뜨리는 거고요...",
          DialogueId = 51125054,
          GUID = "7FFC782C",
          NextDialogue = 51125055,
          SpeakNpcId = 100001,
          Subtitle = "According to the script, after \"So what!\", you're supposed to rush me. Then I fight through the pain and take all you Drifters down..."
        },
        [51125055] = {
          Camera = "-183.84375,271.606445,161.805664,0.017533,-4.59964,-29.49268,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "감독님, 지금 이거 맞게 찍고 있는 거예요? 뭐가 이래요!",
          DialogueId = 51125055,
          GUID = "7FFC7856",
          SpeakNpcId = 100001,
          Subtitle = "Director! This can't be right!"
        },
        [51125056] = {
          Camera = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "잠깐, 잠깐만, 일단 멈춰 봐!",
          DialogueId = 51125056,
          GUID = "7FFC7880",
          NextDialogue = 51125057,
          SpeakNpcId = 700365,
          Subtitle = "Cut! Cut!",
          TalkActionId = {
            [1] = "700366:Talk03_End",
            [2] = "700365:Talk03_Start"
          }
        },
        [51125057] = {
          Camera = "520.042969,-611.853516,206.539062,0.01755,-6.400604,132.109695,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "진상이 너, 재미가 있을 땐 분량을 탐내 봐야 씨알도 안 먹혔는데, 오늘은 재미가 없다고 아주 살판났구나?",
          DialogueId = 51125057,
          GUID = "7FFC78AA",
          LookAt = {
            [1] = "700365:n(700366)"
          },
          NextDialogue = 51125058,
          SpeakNpcId = 700365,
          Subtitle = "Hengsheng, I know now — when Miaoqu was here, he kept you in check. Now that he's gone, you're just running wild, aren't you?",
          TalkActionId = {
            [1] = "700365:Talk03_End"
          }
        },
        [51125058] = {
          ContentKR = "다 감독님이 가르쳐 주신 거잖아요! 뭐더라... 훌륭한 배우는 연기로 관객들의 시선을 사로잡을 줄 알아야 한다면서요!",
          DialogueId = 51125058,
          GUID = "7FFC78D4",
          LookAt = {
            [1] = "700366:n(700365)"
          },
          NextDialogue = 51125059,
          SpeakNpcId = 700366,
          Subtitle = "But Director, didn't you teach us that a good actor should always \"find the character's spotlight\"?"
        },
        [51125059] = {
          ContentKR = "스읍... 그런 소리를 하긴 했지.",
          DialogueId = 51125059,
          GUID = "7FFC78FE",
          NextDialogue = 51125060,
          SpeakNpcId = 700365,
          Subtitle = "Great... I did say that.",
          TalkActionId = {
            [1] = "700365:Think_Start"
          }
        },
        [51125060] = {
          ContentKR = "맞죠, 그랬다니까요.",
          DialogueId = 51125060,
          GUID = "7FFC7928",
          NextDialogue = 51125061,
          SpeakNpcId = 700366,
          Subtitle = "See?"
        },
        [51125061] = {
          ContentKR = "아니, 그래도 네가 맡은 역할은 악당이잖아. 정의로운 응천위한테 칼 맞고 죽는 역할이라고! 악당이 시선을 사로잡으면 어떡해!",
          DialogueId = 51125061,
          GUID = "7FFC7952",
          NextDialogue = 51125062,
          SpeakNpcId = 700365,
          Subtitle = "No — you're playing the villain! You're supposed to be cut down by the Magistrate in the next scene! What \"spotlight\" does a villain need?",
          TalkActionId = {
            [1] = "700365:Think_End"
          }
        },
        [51125062] = {
          ContentKR = "그놈의 악당! 제가 감독님이랑 몇 년이나 작품을 같이 했는데, 생판 남한테는 재미 대타로 응천위 역할을 시켜 주시면서, 전 언제까지 악당 해야 돼요!",
          DialogueId = 51125062,
          FacialId = {
            [1] = "700366:CM_Angry01"
          },
          GUID = "7FFC797C",
          NextDialogue = 51125063,
          SpeakNpcId = 700366,
          Subtitle = "Always a villain — I've been with your team for years, and you always stick me with the villains! Even with Miaoqu out, you'd rather give the Magistrate part to some stranger than let me have a go!"
        },
        [51125063] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "넌 응천위 역할을 맡기엔 좀 껄렁껄렁해 보이잖아. 관객들이 납득하겠어?",
          DialogueId = 51125063,
          GUID = "7FFC79A6",
          NextDialogue = 51125064,
          SpeakNpcId = 700365,
          Subtitle = "Just look at that smug face of yours! Who'd believe a Magistrate looks like that?"
        },
        [51125064] = {
          Camera = "127.339844,-18.349609,122.799805,0.017557,2.000023,179.711273,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "왜 납득을 못 해요? 훌륭한 배우는 '잘생김마저 연기'해야 한다면서요? 재미보다 잘할 자신 있으니까, 기회를 주세요! 아니면, 제 연기력을 못 믿으시는 거예요?",
          DialogueId = 51125064,
          GUID = "7FFC79D0",
          NextDialogue = 51125065,
          SpeakNpcId = 700366,
          Subtitle = "Why not? You also said a great actor should have \"transformative acting skills\". If you'd just let me suit up as a Magistrate, I'd play it just as well as Miaoqu! You just don't trust me."
        },
        [51125065] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그만하죠. 저 오늘 연기 못 해요! 이만 가 보겠습니다!",
          DialogueId = 51125065,
          GUID = "7FFC79FA",
          NextDialogue = 51125066,
          SpeakNpcId = 700366,
          Subtitle = "You know what? I'm done for today! I'm out!"
        },
        [51125066] = {
          ContentKR = "아니, 진상아, 왜 갑자기 화를 내고 그래! 일단 좀 진정해 봐! 오늘이 우리 마지막 촬영날이잖아!",
          DialogueId = 51125066,
          GUID = "7FFC7A24",
          NextDialogue = 51125067,
          SpeakNpcId = 700365,
          Subtitle = "Hey — oi! Cool off! We're up against the clock today!"
        },
        [51125067] = {
          Camera = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...이대로 찍는 건 좀 아닌 거 같은데, {性别:거기 친구|아가씨} 생각은 어때? 둘이 역할을 바꿔 볼래?",
          DialogueId = 51125067,
          GUID = "7FFC7A4E",
          LookAt = {
            [1] = "700365:n(100001)"
          },
          NextOptions = {
            [1] = 51125068,
            [2] = 51125069
          },
          SpeakNpcId = 700365,
          Subtitle = "...What do you think, {性别：brother丨lass}? This isn't working. How about... we swap your roles?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51125068] = {
          ContentKR = "저렇게까지 응천위 역할을 하고 싶어 하니까, 제가 양보할게요.",
          DialogueId = 51125068,
          GUID = "7FFC7A78",
          ImprPlusId = 1209,
          NextDialogue = 51125070,
          Subtitle = "If he wants the part that badly, let him have it."
        },
        [51125069] = {
          ContentKR = "바꿔 드릴 순 있는데, 출연료를 더 주세요.",
          DialogueId = 51125069,
          GUID = "7FFC7AA2",
          ImprPlusId = 1201,
          NextDialogue = 51125070,
          Subtitle = "Fine. But it'll cost you extra."
        },
        [51125070] = {
          ContentKR = "좋아, 그렇게 하자.",
          DialogueId = 51125070,
          GUID = "7FFC7ACC",
          NextDialogue = 51125071,
          SpeakNpcId = 700365,
          Subtitle = "Done.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51125071] = {
          ContentKR = "몇 분 후...",
          DialogueId = 51125071,
          GUID = "7FFC7AF6",
          IsBlack = 1,
          NextDialogue = 51125072,
          Subtitle = "A few minutes later..."
        },
        [51125072] = {
          Camera = "246.074219,-350.594727,117.375,0.01754,0.797944,105.297958,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51125072,
          GUID = "7FFC7B20",
          NextDialogue = 51125073,
          SpeakNpcId = 700365,
          Subtitle = "..."
        },
        [51125073] = {
          ContentKR = "......",
          DialogueId = 51125073,
          GUID = "7FFC7B4A",
          LookAt = {
            [1] = "100001:n(700365)"
          },
          NextDialogue = 51125074,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51125074] = {
          ContentKR = "...진짜 악당 연기할 수 있겠어? 아무리 봐도 금지 소설 같은 데 나오는 '산외산 대협' 같이 생겼는데...",
          DialogueId = 51125074,
          GUID = "7FFC7B74",
          NextDialogue = 51125075,
          SpeakNpcId = 700365,
          Subtitle = "Are you sure you can pull off a villain? You still look more like one of those \"Outer Peaks Swordsmen\" from those banned romance novels.."
        },
        [51125075] = {
          ContentKR = "에라 모르겠다. 난 진상이가 의상 다 갈아입었나 보러 갈게.",
          DialogueId = 51125075,
          GUID = "7FFC7B9E",
          SpeakNpcId = 700365,
          Subtitle = "Never mind. Let's see if Hengsheng's ready."
        },
        [51125076] = {
          DialogueId = 51125076,
          GUID = "7FFC7BC8",
          IsBlack = 1
        },
        [51125077] = {
          Camera = "-515.558594,-201.037109,125.110352,0.017539,0.198321,23.096621,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "십몇 년을 악당만 하다가 드디어 정의의 사도 역할을 맡게 됐다! 으하하하하!",
          DialogueId = 51125077,
          GUID = "7FFC7BF2",
          NextDialogue = 51125078,
          SpeakNpcId = 700379,
          Subtitle = "After all these years, it's finally my turn to be the hero! Ahahahaha!"
        },
        [51125078] = {
          ContentKR = "어이, 이거 봐. 나 이제 응천위야, 멋지지? 촤악—— 샥—— 슉슈슈슉—— 캬!",
          DialogueId = 51125078,
          GUID = "7FFC7C1C",
          NextDialogue = 51125079,
          SpeakNpcId = 700379,
          Subtitle = "Hey, look at me now, I'm a Magistrate! Cool, right? Swoosh —  zing — Aiyah!"
        },
        [51125079] = {
          ContentKR = "감독님, 제 말이 맞죠? 누가 봐도 영락없는 응천위잖아요!",
          DialogueId = 51125079,
          GUID = "7FFC7C46",
          NextDialogue = 51125080,
          SpeakNpcId = 700379,
          Subtitle = "See, Director? What did I tell you? Don't I look every bit the Magistrate now?"
        },
        [51125080] = {
          ContentKR = "진짜 괜찮을까... 됐어, 막상 연기 들어가면 또 다를 수도 있고... 자, 다들 움직여! 촬영 시작한다!",
          DialogueId = 51125080,
          GUID = "7FFC7C70",
          SpeakNpcId = 700365,
          Subtitle = "Is this really going to work?... Ah, forget about it. Maybe he'll settle into the role once we start rolling... Alright everyone, positions! Let's shoot this!"
        },
        [51125081] = {
          DialogueId = 51125081,
          GUID = "7FFC7C9A",
          IsBlack = 1
        },
        [51125082] = {
          ContentKR = "크윽... 힘이...!",
          DialogueId = 51125082,
          GUID = "7FFC7CC4",
          NextDialogue = 51125083,
          SpeakNpcId = 700379,
          Subtitle = "Blast it... I'm out of strength!"
        },
        [51125083] = {
          ContentKR = "얘들아, 쳐라!",
          DialogueId = 51125083,
          GUID = "7FFC7CEE",
          SpeakNpcName = "UI_CMNpc_Name_QunYan",
          Subtitle = "Let's get him, lads!"
        },
        [51125084] = {
          DialogueId = 51125084,
          GUID = "7FFC7D18",
          IsBlack = 1
        },
        [51125085] = {
          ContentKR = "가소롭구나, 잔챙이 녀석들! 이야압! 어서 물렀거라!",
          DialogueId = 51125085,
          GUID = "7FFC7D42",
          NextDialogue = 51125086,
          SpeakNpcId = 700379,
          Subtitle = "Hmph — be gone! Hah — you villains!"
        },
        [51125086] = {
          ContentKR = "속박의 올가미에 묶이고도 밀리는 기색 하나 없다니! 다들 어서 도망쳐!",
          DialogueId = 51125086,
          GUID = "7FFC7D6C",
          NextDialogue = 51125087,
          SpeakNpcName = "UI_CMNpc_Name_QunYan",
          Subtitle = "He's still standing even bound by the Rope! Fall back, now!"
        },
        [51125087] = {
          ContentKR = "이 녀석! 어딜 도망가느냐!",
          DialogueId = 51125087,
          GUID = "7FFC7D96",
          NextDialogue = 51125088,
          SpeakNpcId = 700379,
          Subtitle = "Hah! You think you can escape?!"
        },
        [51125088] = {
          ContentKR = "이 독침 맛을 봐라!",
          DialogueId = 51125088,
          GUID = "7FFC7DC0",
          NextDialogue = 51125089,
          SpeakNpcId = 100001,
          Subtitle = "Take my poison needle!"
        },
        [51125089] = {
          ContentKR = "하핫! 그까짓 독침 따윈 가뿐히 피해 주마!",
          DialogueId = 51125089,
          GUID = "7FFC7DEA",
          SpeakNpcId = 700379,
          Subtitle = "A mere poison needle? I'll simply evade its sting!"
        },
        [51125090] = {
          DialogueId = 51125090,
          GUID = "7FFC7E14",
          IsBlack = 1
        },
        [51125091] = {
          ContentKR = "저기요, 방금 건 대본에 없었잖아요.",
          DialogueId = 51125091,
          GUID = "7FFC7E3E",
          NextDialogue = 51125092,
          SpeakNpcId = 100001,
          Subtitle = "Wait — that wasn't in the script."
        },
        [51125092] = {
          ContentKR = "이히히히히, 그 쪼그만 독침으로 뭘 하겠다는 거야. 이 보검엔 맹독이 잔뜩 발려 있다고~",
          DialogueId = 51125092,
          GUID = "7FFC7E68",
          NextDialogue = 51125093,
          SpeakNpcId = 700379,
          Subtitle = "Ee-hee-hee... What's a little needle to me? This blade in my hand — is drenched in deadly poison."
        },
        [51125093] = {
          ContentKR = "(왜 또 애드리브야!)",
          DialogueId = 51125093,
          GUID = "7FFC7E92",
          SpeakNpcId = 100001,
          Subtitle = "(He's improvising again!)"
        },
        [51125094] = {
          DialogueId = 51125094,
          GUID = "7FFC7EBC",
          IsBlack = 1
        },
        [51125095] = {
          Camera = "493.785156,-135.24707,12.011719,0.017552,14.799428,162.905365,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "날고 기는 응천위 나리라도 뒤에서 날아드는 독침은 당해 낼 수 없나 보군!",
          DialogueId = 51125095,
          GUID = "7FFC7EE6",
          NextDialogue = 51125096,
          SpeakNpcId = 100001,
          Subtitle = "Heh. Your Honour, for all your prowess, you never stood a chance against a needle in the back."
        },
        [51125096] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 51125096,
          GUID = "7FFC7F10",
          NextDialogue = 51125097,
          SpeakNpcId = 700379,
          Subtitle = "..."
        },
        [51125097] = {
          Camera = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "대사 쳐야죠!",
          DialogueId = 51125097,
          GUID = "7FFC7F3A",
          NextDialogue = 51125098,
          SpeakNpcId = 100001,
          Subtitle = "Your line!"
        },
        [51125098] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "대사가 뭐였지?",
          DialogueId = 51125098,
          GUID = "7FFC7F64",
          NextDialogue = 51125099,
          SpeakNpcId = 700379,
          Subtitle = "What was it?"
        },
        [51125099] = {
          Camera = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"네 녀석의 가문은 대대로 현형파의 향관을 배출한 충신 집안이거늘, 어찌 너 같은 인간 말종이 나왔단 말이냐!\"",
          DialogueId = 51125099,
          GUID = "7FFC7F8E",
          NextDialogue = 51125100,
          SpeakNpcId = 100001,
          Subtitle = "\"Your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like you?\""
        },
        [51125100] = {
          Camera = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "와, 인간 말종이라니? 말이 너무 심하네? 있지, 우리 현형파는 쥐꼬리만 한 보수나 받으면서, 일 년에 며칠 쉬지도 못하고, 하루 종일 죽어라 향만 피운다고.",
          DialogueId = 51125100,
          GUID = "7FFC7FB8",
          NextDialogue = 51125101,
          SpeakNpcId = 700379,
          Subtitle = "Hey, who are you calling a scoundrel? Think about it — what did we even get out of working for the Xuanheng Sect, huh? Barely any pay, breathing in incense ash all day, hardly any days off."
        },
        [51125101] = {
          ContentKR = "게다가 우리는 지나다니는 개 한 마리도 못 건드려. 개 주인이 학대니 뭐니 따지고 들면, 대풍구장을 어기는 게 돼 버릴 테니까.",
          DialogueId = 51125101,
          GUID = "7FFC7FE2",
          NextDialogue = 51125102,
          SpeakNpcId = 700379,
          Subtitle = "And we were always bound by the Nine Chapters — couldn't even kick a dog on the street! What if it had an owner? We'd be punished by Bi'an!"
        },
        [51125102] = {
          Camera = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니, 잠깐만요...",
          DialogueId = 51125102,
          GUID = "7FFC800C",
          NextDialogue = 51125103,
          SpeakNpcId = 100001,
          Subtitle = "Wait...",
          TalkActionId = {
            [1] = "100001:RaiseHand_Start"
          }
        },
        [51125103] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다들 그냥, 잘되면 백룡신군 덕이고 안되면 우리 때문이지! 그럴 바에야 자유로운 나그네가 되는 게 훨씬 낫다고!",
          DialogueId = 51125103,
          GUID = "7FFC8036",
          NextDialogue = 51125104,
          SpeakNpcId = 700379,
          Subtitle = "None of the credit, either — when things went well, it was \"All praise to Lord Argent\" When they went south, it was our fault!"
        },
        [51125104] = {
          ContentKR = "흐흐, 우리가 나가떨어지는 게 먼저일지, 응천위 나리 목숨줄이 끊어지는 게 먼저일지 보자고! 내 정의의 독침을 받아랏!",
          DialogueId = 51125104,
          GUID = "7FFC8060",
          SpeakNpcId = 700379,
          Subtitle = "Heheh... We'll see what's harder — the Magistrate's life, or my blade!"
        },
        [51125105] = {DialogueId = 51125105, GUID = "7FFC808A"},
        [51125106] = {
          Camera = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "훌륭해! 물 흐르듯 자연스러웠어! 진상, 넌 역시 하늘이 내린 타고난 악역이야!",
          DialogueId = 51125106,
          FacialId = {
            [1] = "700365:CM_Happy01"
          },
          GUID = "7FFC80B4",
          NextDialogue = 51125107,
          SpeakNpcId = 700365,
          Subtitle = "Brilliant! Smooth as silk, flawless from start to finish! Hengsheng, you were born to play the villain!"
        },
        [51125107] = {
          ContentKR = "자, 촬영 끝! 철수! 연진 나루터 장면들은 내가 감독판 편집할 때 어떻게든 살려 볼게.",
          DialogueId = 51125107,
          GUID = "7FFC80DE",
          LookAt = {
            [1] = "700365:n(700379)"
          },
          NextDialogue = 51125108,
          SpeakNpcId = 700365,
          Subtitle = "That's a wrap! We're done here! I'll just have to save the Mistwharf scenes in the editing room."
        },
        [51125108] = {
          ContentKR = "{性别:친구|아가씨}, 이거 오늘 출연료야. 받아 둬.",
          DialogueId = 51125108,
          GUID = "7FFC8108",
          LookAt = {
            [1] = "700365:n(100001)"
          },
          NextDialogue = 51125109,
          SpeakNpcId = 700365,
          Subtitle = "Here {性别：brother丨lass}, your pay for today. You've earned it."
        },
        [51125109] = {
          ContentKR = "(이 황당한 소동도 드디어 막을 내렸다. 진상은 바라던 대로 관객의 시선을 사로잡을 수 있을 것이다... 아마도.)",
          DialogueId = 51125109,
          GUID = "7FFC8132",
          IsBlack = 1,
          Subtitle = "(And so, this utterly absurd farce finally came to a close. Hengsheng had gotten his wish — his moment in the spotlight… or so it seemed.)"
        },
        [51125201] = {
          ContentKR = "휴... 겨우 다 옮겼네. 이제 빠뜨린 거 없지?",
          DialogueId = 51125201,
          GUID = "7FFC904A",
          NextDialogue = 51125202,
          SpeakNpcId = 701034,
          Subtitle = "Phew... that's the last of it. We're not short of anything, are we?"
        },
        [51125202] = {
          ContentKR = "아니, 오늘은 장 형이 쉬는 날이라, 우리가 그 형 몫까지 다 옮겨야 해.",
          DialogueId = 51125202,
          GUID = "7FFC9074",
          NextDialogue = 51125203,
          SpeakNpcId = 701035,
          Subtitle = "Zhuang's off today — we've got to finish his load too."
        },
        [51125203] = {
          ContentKR = "내일 자기가 직접 옮기라고 하면 되잖아?",
          DialogueId = 51125203,
          GUID = "7FFC909E",
          NextDialogue = 51125204,
          SpeakNpcId = 701034,
          Subtitle = "And why can't he haul it himself tomorrow?"
        },
        [51125204] = {
          ContentKR = "집에 좋은 일이 있대. 돌아오면 차 한잔 사 주겠다던데.",
          DialogueId = 51125204,
          GUID = "7FFC90C8",
          NextDialogue = 51125205,
          SpeakNpcId = 701035,
          Subtitle = "Says there's good news at home. When he's back, he's treating us to tea."
        },
        [51125205] = {
          ContentKR = "어이쿠! 좋은 일이 있는데 우릴 안 불러? 제일 비싼 차로 얻어 마셔야겠어!",
          DialogueId = 51125205,
          GUID = "7FFC90F2",
          SpeakNpcId = 701034,
          Subtitle = "Ha! Celebrating without us, is he? I'll make him cough up a pot of his finest!"
        },
        [51125301] = {
          ContentKR = "아니, 우리 화서만큼 안전한 곳이 없다니까? 저기 순찰 도는 폐안들 보여? 나쁜 놈이 나쁜 짓 하려고 하면, 바로 잡혀가!",
          DialogueId = 51125301,
          GUID = "7FFCA0B2",
          NextDialogue = 51125302,
          SpeakNpcId = 701036,
          Subtitle = "You've got to admit, Huaxu's one of the safest places around. See those Bi'an patrols everywhere? The moment someone stirs up trouble, they pounce and bring them down."
        },
        [51125302] = {
          ContentKR = "흥, 우리 휘페르보레아 제국도 안전하거든? 제국 군단의 명성을 들어는 봤어? 반항의 싹이 돋기도 전에 뽑아 버리는 게 제국 철기군의 방식이야.",
          DialogueId = 51125302,
          GUID = "7FFCA0DC",
          NextDialogue = 51125303,
          SpeakNpcId = 701037,
          Subtitle = "Hmph. Hyperborea's just as safe, I'll have you know. Ever heard of the Hyperborean Legion? The Empire's cavalry silences any whisper of rebellion."
        },
        [51125303] = {
          ContentKR = "웃기시네! 외국 갔다 온 별을 잇는 자들이 휘페르보레아 제국은 허구한 날 남쪽이랑 싸운다던데? 그게 안전한 거야?",
          DialogueId = 51125303,
          GUID = "7FFCA106",
          NextDialogue = 51125304,
          SpeakNpcId = 701036,
          Subtitle = "Oh, come off it. Every Starweaver back from abroad says Hyperborea's always at war with the south. You call that safe?"
        },
        [51125304] = {
          ContentKR = "그건... 능력이 되니까 싸우는 거야... 평화를 위한 투쟁이라고!",
          DialogueId = 51125304,
          GUID = "7FFCA130",
          NextDialogue = 51125305,
          SpeakNpcId = 701037,
          Subtitle = "Uh... well, that's how the Empire shows its might. We fight for peace, don't you see?"
        },
        [51125305] = {
          ContentKR = "쯧쯧, 그런데 왜 굳이 화서에서 지내려고 하는 건데? 이봐, 화서에 왔으면 마음 곱게 먹고 착하게 살아. 백룡신군께서 늘 지켜 주실 테니까.",
          DialogueId = 51125305,
          GUID = "7FFCA15A",
          SpeakNpcId = 701036,
          Subtitle = "Pfft. Then why did you come all the way to move to Huaxu, eh? Trust me, mate — keep a good heart here and Lord Argent will see you safe day in, day out."
        },
        [51125401] = {
          ContentKR = "이 버려진 탑도 꽤 오래됐네. 한때는 우리 기추파의 걸작이었는데, 관리해 주는 사람이 아무도 없다니...",
          DialogueId = 51125401,
          GUID = "7FFCB11A",
          NextOptions = {
            [1] = 51125402
          },
          SpeakNpcId = 701038,
          Subtitle = "This old tower's seen better days. I'd wager it was fine work of our sect once. Hard to watch it left to wind and rain, with no one to tend it..."
        },
        [51125402] = {
          ContentKR = "이 탑의 용도는 뭐예요?",
          DialogueId = 51125402,
          GUID = "7FFCB144",
          NextDialogue = 51125403,
          Subtitle = "What was it for?"
        },
        [51125403] = {
          ContentKR = "기추파가 별을 잇는 자들을 도와 지었던 복천루야. 그렇지만 지금은... 거들떠보는 사람 하나 없는 고철 덩어리지.",
          DialogueId = 51125403,
          GUID = "7FFCB16E",
          NextOptions = {
            [1] = 51125404
          },
          SpeakNpcId = 701038,
          Subtitle = "Back in the day, our sect built it for the Starweavers — they called it a Tower of Divination. These days it's just forgotten scrap and rust."
        },
        [51125404] = {
          ContentKR = "복천루는 뭐죠?",
          DialogueId = 51125404,
          GUID = "7FFCB198",
          NextDialogue = 51125405,
          Subtitle = "Tower of Divination?"
        },
        [51125405] = {
          ContentKR = "하늘의 움직임을 보고 길흉을 점치는 탑이야. 말이 그렇지, 실제론 별자리를 잘 관찰해서 며칠 뒤 날씨를 예측하는 장치에 불과하지만.",
          DialogueId = 51125405,
          GUID = "7FFCB1C2",
          NextOptions = {
            [1] = 51125406
          },
          SpeakNpcId = 701038,
          Subtitle = "Right — for reading the heavens and charting omens and fortunes, or so they said. In truth, nothing so mystical: it helped them study the stars and forecast the days ahead."
        },
        [51125406] = {
          ContentKR = "그런데 왜 버려진 거예요?",
          DialogueId = 51125406,
          GUID = "7FFCB1EC",
          NextDialogue = 51125407,
          Subtitle = "Why was it abandoned?"
        },
        [51125407] = {
          ContentKR = "...말하자면 길지만, 어쨌든 가장 큰 이유는 기추파가 몰락하면서 관리할 사람이 없어졌고, 정확도가 떨어졌기 때문일 거야.",
          DialogueId = 51125407,
          GUID = "7FFCB216",
          NextDialogue = 51125408,
          SpeakNpcId = 701038,
          Subtitle = "Ah, that's a long one. It began when the Jishu Sect fell on hard times — few were left to tend the towers, and the readings grew increasingly unreliable."
        },
        [51125408] = {
          ContentKR = "나중엔 별을 잇는 자들이 개량한 천성판으로도 날씨를 어느 정도 예측할 수 있게 되면서, 이 탑은 쓸모가 없어져 버린 거지.",
          DialogueId = 51125408,
          GUID = "7FFCB240",
          NextDialogue = 51125409,
          SpeakNpcId = 701038,
          Subtitle = "Later, the Starweavers refined their Stellapasses — clever things. They could forecast the weather well enough on their own, so the towers were no longer needed."
        },
        [51125409] = {
          ContentKR = "기추파의 위세가 백 년 전처럼 드높았다면, 후학들이 진작에 새로운 쓸모를 찾아 줬겠지만 말이야.",
          DialogueId = 51125409,
          GUID = "7FFCB26A",
          NextDialogue = 51125410,
          SpeakNpcId = 701038,
          Subtitle = "Still, if you ask me — had the Jishu Sect been what it was a century ago, these towers would have found new purposes by now."
        },
        [51125410] = {
          ContentKR = "하아... 다 지나간 일을 붙잡고 뭐 하겠어. 미련을 버려야지, 훌훌 털어 버려야지...",
          DialogueId = 51125410,
          GUID = "7FFCB294",
          SpeakNpcId = 701038,
          Subtitle = "*sigh* It's long past now. No sense raking through the dust. Let it be."
        },
        [51125501] = {
          ContentKR = "멀리서 온 친구, 옆으로 좀 비켜서 주지 않겠어?",
          DialogueId = 51125501,
          GUID = "7FFCC182",
          NextOptions = {
            [1] = 51125502,
            [2] = 51125505
          },
          SpeakNpcId = 701039,
          Subtitle = "Hey there, friend from afar — give us a bit of space, yeah?"
        },
        [51125502] = {
          ContentKR = "죄송해요.",
          DialogueId = 51125502,
          GUID = "7FFCC1AC",
          ImprPlusId = 1207,
          NextDialogue = 51125503,
          Subtitle = "Ah, my bad."
        },
        [51125503] = {
          ContentKR = "뭐 이런 걸로. 다른 나라 친구가 화서에 왔으니까, 낯설기도 하고 뭐가 뭔지 모르겠지. 궁금하거나 이해 안 되는 게 있으면 언제든 와서 물어봐.",
          DialogueId = 51125503,
          GUID = "7FFCC1D6",
          NextDialogue = 51125504,
          SpeakNpcId = 701039,
          Subtitle = "No worries at all. First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler."
        },
        [51125504] = {
          ContentKR = "보기엔 이래도, 난 이 별빛 부두에선 잘나가는 검수원이거든. 난 말이야, 천문, 지리부터 시작해서 사람 사는 얘기까지 모르는 게 없어.",
          DialogueId = 51125504,
          GUID = "7FFCC200",
          SpeakNpcId = 701039,
          Subtitle = "I might not look like much, but I'm one of the best tallymen on Starwharf. Ask me anything — from the skies above to life on the streets — I've got it all down pat."
        },
        [51125505] = {
          ContentKR = "그쪽이 이 길 전세 냈어요?",
          DialogueId = 51125505,
          GUID = "7FFCC22A",
          ImprPlusId = 1210,
          NextDialogue = 51125506,
          Subtitle = "You don't own this road."
        },
        [51125506] = {
          ContentKR = "어이쿠, 한 성격 하네. 그냥 걱정돼서 하는 얘기였어. 이 부두는 일꾼들이 무거운 짐 들고 왔다 갔다 하는데, 부딪히기라도 하면 큰일 나잖아.",
          DialogueId = 51125506,
          GUID = "7FFCC254",
          NextDialogue = 51125507,
          SpeakNpcId = 701039,
          Subtitle = "Whoa there, friend from afar — no need to get all worked up! I'm just looking out for you. Porters come and go here all day, hauling heavy stuff. One wrong bump and you'll get hurt."
        },
        [51125507] = {
          ContentKR = "화서에 처음 왔으니까, 아무래도 익숙하지 않겠지. 뭐든 모르는 게 있으면 언제든 물어봐. 검수원 나부랭이지만, 그래도 화서 토박이거든.",
          DialogueId = 51125507,
          GUID = "7FFCC27E",
          SpeakNpcId = 701039,
          Subtitle = "First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler. I may just be a tallyman, but hey — I grew up here."
        },
        [51125508] = {
          ContentKR = "황해쑥 50근, 춘일품 30근... 어이, 거기! 향료는 다 귀한 물건이라니까! 옮길 때 조심하라고!",
          DialogueId = 51125508,
          GUID = "7FFCC2A8",
          NextDialogue = 51125509,
          Subtitle = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!"
        },
        [51125509] = {
          ContentKR = "오, 얼마 전에 화서에 온 외국 친구 맞지? 아직 별빛 부두에 있었네? 혹시 장사하러 온 젊은 사장이었던 건가? 검수원은 평소에 뭐 하는지 구경하러 온 거야?",
          DialogueId = 51125509,
          GUID = "7FFCC2D2",
          NextOptions = {
            [1] = 51125510,
            [2] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "Hey, look who it is! Still hanging around Starwharf, huh? What's this then — come to trade, young merchant? Or just curious to see how we tallymen earn our rice?"
        },
        [51125510] = {
          ContentKR = "물어볼 게 있어요.",
          DialogueId = 51125510,
          GUID = "7FFCC2FC",
          NextDialogue = 51125511,
          Subtitle = "I have something to ask you."
        },
        [51125511] = {
          ContentKR = "뭐든 물어봐. 내가 아는 거라면, 전부 다 대답해 줄게.",
          DialogueId = 51125511,
          GUID = "7FFCC326",
          NextOptions = {
            [1] = 51125512,
            [2] = 51125516
          },
          SpeakNpcId = 701039,
          Subtitle = "Ask away, friend! Anything I know, I'll share."
        },
        [51125512] = {
          ContentKR = "검수원은 무슨 일을 해요?",
          DialogueId = 51125512,
          GUID = "7FFCC350",
          NextDialogue = 51125513,
          Subtitle = "What's a tallyman do?"
        },
        [51125513] = {
          ContentKR = "말 그대로 별을 잇는 자들 대신 화물을 검수해 주는 사람이지.",
          DialogueId = 51125513,
          GUID = "7FFCC37A",
          NextDialogue = 51125514,
          SpeakNpcId = 701039,
          Subtitle = "Pretty much what the name says — we help the Starweavers keep track of their cargo."
        },
        [51125514] = {
          ContentKR = "이 별빛 부두는 매일 드나드는 배가 굉장히 많아. 별을 잇는 자들이 직접 화물 수량을 확인한다면, 몸이 몇 개라도 모자랄걸.",
          DialogueId = 51125514,
          GUID = "7FFCC3A4",
          NextDialogue = 51125515,
          SpeakNpcId = 701039,
          Subtitle = "You see, Starwharf's busy every day — ships coming and going nonstop. If the Starweavers had to handle all the counting, they'd never get a break."
        },
        [51125515] = {
          ContentKR = "그래서 우리 같은 검수원이 필요한 거야. 해외로 나가는 화물의 수량을 세서 누락된 게 없는지 확인해야, 별을 잇는 자들도 나중에 외국 상인들한테 할 말이 생기잖아.",
          DialogueId = 51125515,
          GUID = "7FFCC3CE",
          NextOptions = {
            [1] = 51125516,
            [2] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "That's where we tallymen come in. We check what's coming and going, make sure nothing's short — otherwise the Starweavers would have a hard time explaining it to their buyers in distant lands."
        },
        [51125516] = {
          ContentKR = "화서의 별을 잇는 자들은 화물이 드나들 때마다 신고를 해야 하나요?",
          DialogueId = 51125516,
          GUID = "7FFCC3F8",
          NextDialogue = 51125517,
          Subtitle = "So the Starweavers here have to log everything coming in and out?"
        },
        [51125517] = {
          ContentKR = "당연하지. 화서는 무역이 발달한 곳이라 천록사에서 꼼꼼하고 까다롭게 관리하거든. 다 세금이랑 관련된 거니까.",
          DialogueId = 51125517,
          GUID = "7FFCC422",
          NextDialogue = 51125518,
          SpeakNpcId = 701039,
          Subtitle = "Naturally! Trade's booming here in Huaxu, and the Ministry of Fortune's got rules — whatever comes in or goes out gets taxed."
        },
        [51125518] = {
          ContentKR = "다른 이유는 화서에선 중요한 향료는 할당량을 아주 엄격하게 관리하기 때문이야. 고창처럼 여기서 많이 쓰는 향료를 싹 다 외국에 팔아 버리면, 정작 우리가 쓸 게 없어지잖아?",
          DialogueId = 51125518,
          GUID = "7FFCC44C",
          NextDialogue = 51125519,
          SpeakNpcId = 701039,
          Subtitle = "And some of the key incense materials — they've got strict limits. Take Sky Lilies, for instance: folks here burn a lot of it. If the Starweavers ship it all overseas, what are we supposed to do when we run short?"
        },
        [51125519] = {
          ContentKR = "들어오는 물건은 더 철저히 신고해야지. 그 휘페르보레아 제국인가 뭔가 하는 데서 칼이나 총 같은 게 화서에 마구 들어오면 난리 날 거 아냐!",
          DialogueId = 51125519,
          GUID = "7FFCC476",
          NextOptions = {
            [1] = 51125520,
            [2] = 51125524,
            [3] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "And what's coming in needs even tighter checks! Take Hyperborea — blades, firearms, that sort of stuff. Let all that in unchecked and Huaxu'd be a madhouse!"
        },
        [51125520] = {
          ContentKR = "금지품이 몰래 섞여 들어올 수도 있잖아요?",
          DialogueId = 51125520,
          GUID = "7FFCC4A0",
          NextDialogue = 51125521,
          Subtitle = "So what happens if something illegal slips through?"
        },
        [51125521] = {
          ContentKR = "이 친구 보게, 그건 말처럼 쉽지가 않아요! 우리처럼 오래 일한 검수원들은, 화물 크기나 냄새만 맡아도 무슨 물건인지 다 알아.",
          DialogueId = 51125521,
          GUID = "7FFCC4CA",
          NextDialogue = 51125522,
          SpeakNpcId = 701039,
          Subtitle = "Ha! My friend, it's not that easy. We tallymen've been at this forever — one look, one sniff, and we know what's in the crate."
        },
        [51125522] = {
          ContentKR = "게다가 이 부두 주변을 돌아다니는 폐안님들을 봐. 우리가 잡아내는 오차 정돈 다 알고 계셔. 우리가 못 찾아도 저분들 눈을 속일 순 없다고.",
          DialogueId = 51125522,
          GUID = "7FFCC4F4",
          NextDialogue = 51125523,
          SpeakNpcId = 701039,
          Subtitle = "See those Bi'an patrolling the docks? What we catch, they spot — and what we don't, ha, they still will."
        },
        [51125523] = {
          ContentKR = "폐안님들은 몹쓸 물건들이 우리 화서엔 얼씬도 못 하게 하루 종일 부두를 순찰하셔. 냄새를 기가 막히게 맡아서, 숨겨 봤자 바로 들켜 버린다니까.",
          DialogueId = 51125523,
          GUID = "7FFCC51E",
          SpeakNpcId = 701039,
          Subtitle = "Those Bi'an keep watch day and night to stop anything shady from getting into Huaxu. Their noses? Sharp as can be — one sniff and they'll know exactly who's hiding what."
        },
        [51125524] = {
          ContentKR = "그러니까, 그쪽은 별을 잇는 자가 아닌 거예요?",
          DialogueId = 51125524,
          GUID = "7FFCC548",
          NextDialogue = 51125525,
          Subtitle = "Oh, so you're not a Starweaver?"
        },
        [51125525] = {
          ContentKR = "응. 뭐랄까, 이 화서에서 별을 잇는 자가 되긴 쉬워. 그렇지만 모두가 그래야 할 필요는 없잖아?",
          DialogueId = 51125525,
          GUID = "7FFCC572",
          NextDialogue = 51125526,
          SpeakNpcId = 701039,
          Subtitle = "Yes and no. In Huaxu, anyone can be a Starweaver if they want — but why bother?"
        },
        [51125526] = {
          ContentKR = "장사하다 보면 벌 때도 있고 손해 볼 때도 있잖아. 배 타고 멀리 나가면 가족한테 신경도 못 쓰게 되고. 그러느니 설렁설렁 일하면서 꼬박꼬박 월급 받는 게 낫지. 난 인생 편히 살고 싶어.",
          DialogueId = 51125526,
          GUID = "7FFCC59C",
          SpeakNpcId = 701039,
          Subtitle = "You know how it is for traders — sometimes they make a fortune, sometimes they lose their shirts. Me, I keep it simple — easy job, steady coin. Why run off to sea like them and barely ever see home?"
        },
        [51125527] = {
          ContentKR = "이만 가 볼게요.",
          DialogueId = 51125527,
          GUID = "7FFCC5C6",
          NextDialogue = 51125528,
          Subtitle = "I should get going."
        },
        [51125528] = {
          ContentKR = "잘 가~ 궁금한 거 있으면 또 찾아오라고!",
          DialogueId = 51125528,
          GUID = "7FFCC5F0",
          SpeakNpcId = 701039,
          Subtitle = "Have a nice day, friend! If you've got questions, you know where to find me!"
        },
        [51125601] = {
          ContentKR = "구경하고 가세요. 화서 여행에 빠뜨려선 안 될 핫템만 모았습니다! 특히 이 침월향 향주머니는 화서 백룡신군의 가호를 받고 싶다면 무조건 사셔야 해요!",
          DialogueId = 51125601,
          GUID = "7FFCD1EA",
          NextOptions = {
            [1] = 51125602,
            [2] = 51125604
          },
          SpeakNpcId = 701040,
          Subtitle = "Good taste, my friend — Huaxu's finest, right here. These Lunarose sachets above all: if you'd seek Lord Argent's favour, you'll want one."
        },
        [51125602] = {
          ContentKR = "다른 사람한테 받은 게 있어요.",
          DialogueId = 51125602,
          GUID = "7FFCD214",
          ImprPlusId = 1209,
          NextDialogue = 51125603,
          Subtitle = "Someone already gave me one."
        },
        [51125603] = {
          ContentKR = "어? 화서에 친구분을 만나러 오셨나 보군요? 어느 별을 잇는 자가 모시고 온 거려나? 괜찮습니다! 향주머니 말고도 많거든요. 이 비단 부채는 어떠신가요? 화려한 금칠과 조각이 돋보이는 이 거울은요?",
          DialogueId = 51125603,
          GUID = "7FFCD23E",
          SpeakNpcId = 701040,
          Subtitle = "Oh? So you've friends in Huaxu — maybe a Starweaver brought you? No matter! I've plenty besides sachets — a silk fan, perhaps, or an embossed gilt-lacquered mirror?"
        },
        [51125604] = {
          ContentKR = "돈이 없는데, 공짜로 주시면 안 돼요?",
          DialogueId = 51125604,
          GUID = "7FFCD268",
          ImprPlusId = 1210,
          NextDialogue = 51125605,
          Subtitle = "I'm short on cash — any chance I could get a freebie?"
        },
        [51125605] = {
          ContentKR = "하하하, 농담도 잘하시네요. 하긴, 뭐, 안 될 것도 없죠. 침월향 향주머니는 화서에선 그렇게 귀한 것도 아니니까요. 괜찮으시다면, 여기서 아무거나 하나 골라 가세요!",
          DialogueId = 51125605,
          GUID = "7FFCD292",
          NextDialogue = 51125606,
          SpeakNpcId = 701040,
          Subtitle = "Ha! You jest — but why not? Lunarose sachets are common enough here. Go on, take whichever you fancy!"
        },
        [51125606] = {
          ContentKR = "나중에 화서에서 돈 많이 버시면, 저희 가게에 꼭 들러서 친구분들 줄 기념품을 구입해 주세요!",
          DialogueId = 51125606,
          GUID = "7FFCD2BC",
          SpeakNpcId = 701040,
          Subtitle = "One day, when you've coin to spare, come back and take a few souvenirs for your friends and family."
        },
        [51125607] = {
          ContentKR = "외국 손님들을 위한 기념품 가게입니다! 화서에 오셨다면 놓치지 마세요! 향주머니부터 부채, 골동품, 진귀한 보물까지 원하시는 건 뭐든 있습니다!",
          DialogueId = 51125607,
          GUID = "7FFCD2E6",
          NextDialogue = 51125608,
          SpeakNpcId = 701040,
          Subtitle = "Souvenirs for travellers! First time in Huaxu? Don't pass me by — sachets, folding fans, curios, trinkets, all the little treasures you could want!"
        },
        [51125608] = {
          ContentKR = "편하게 구경하고 가세요. 마음에 드시는 게 있으면 말씀하시고요. 가격은 최대한 맞춰 드릴게요.",
          DialogueId = 51125608,
          GUID = "7FFCD310",
          NextOptions = {
            [1] = 51125609,
            [2] = 51125620,
            [3] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "Ah, welcome! Take your time — see what takes your fancy. If something catches your eye, just give me a word and we'll talk price."
        },
        [51125609] = {
          ContentKR = "'이건 무조건 사야 한다'하는 물건 있나요? 향주머니 말고요.",
          DialogueId = 51125609,
          GUID = "7FFCD33A",
          NextDialogue = 51125610,
          Subtitle = "Any must-haves besides the sachets?"
        },
        [51125610] = {
          ContentKR = "있고 말고요! 이 대풍구장 족자랍니다. 대풍구장의 내용이 빠짐없이 적혀 있어서, 귀국해서 친구분들께 설명할 때 딱 꺼내서 보여 주면 되거든요! 손짓발짓하며 설명할 필요가 없죠!",
          DialogueId = 51125610,
          GUID = "7FFCD364",
          NextDialogue = 51125611,
          SpeakNpcId = 701040,
          Subtitle = "Of course! Here — this hanging scroll, every verse of the Nine Chapters of Dafeng laid out clear as day. Take it home, and you'll have the perfect piece to show your friends."
        },
        [51125611] = {
          ContentKR = "그리고 이 화서 특유의 장신구도 좋아요. 화서에선 어르신부터 아이까지 고풍스러운 디자인을 좋아한답니다! 유행을 안 타거든요!",
          DialogueId = 51125611,
          GUID = "7FFCD38E",
          NextDialogue = 51125612,
          SpeakNpcId = 701040,
          Subtitle = "And take a look at our Huaxu exclusives — traditional pieces, well loved by both young and old."
        },
        [51125612] = {
          ContentKR = "특이한 걸 원하신다면, 이런 곤충 모양 장신구도 있어요. 남다른 안목을 지닌 사람이란 걸 제대로 보여 줄 수 있죠.",
          DialogueId = 51125612,
          GUID = "7FFCD3B8",
          NextDialogue = 51125613,
          SpeakNpcId = 701040,
          Subtitle = "If you fancy something a bit different, we've insect-motif pieces too — just the thing for a unique taste."
        },
        [51125613] = {
          ContentKR = "참! 저희 가게의 이 신상품 향초도 꼭 고려해 주세요. 다른 초랑은 다르게 화서 특유의 은은한 향이 일품이거든요. 다른 나라 손님들도 꼭 재구매하시는 물건이에요!",
          DialogueId = 51125613,
          GUID = "7FFCD3E2",
          NextOptions = {
            [1] = 51125614,
            [2] = 51125618
          },
          SpeakNpcId = 701040,
          Subtitle = "Oh, and don't miss our new scented candles: a breath of Huaxu in each — travellers from abroad always come back for more!"
        },
        [51125614] = {
          ContentKR = "다 별로 마음에 안 드는데, 더 실용적인 건 없어요?",
          DialogueId = 51125614,
          GUID = "7FFCD40C",
          NextDialogue = 51125615,
          Subtitle = "Not my thing. Anything more practical — something for day-to-day use?"
        },
        [51125615] = {
          ContentKR = "손님~ 전 그냥 기념품 상인이에요. 원래 기념품이란 게 딱히 쓸모는 없지만, 재미로 사는 물건이잖아요.",
          DialogueId = 51125615,
          GUID = "7FFCD436",
          NextDialogue = 51125616,
          SpeakNpcId = 701040,
          Subtitle = "Ah, dear guest, I'm but a peddler of souvenirs. Such things are for delight and remembrance, not for use."
        },
        [51125616] = {
          ContentKR = "외국분들은 관광하러 오셨든 일로 오셨든, 여기 못 와 본 친구들한테 줄 기념품을 사 가고 싶어 하세요. 실용적인 물건은 가져가 봐야 취향에 안 맞으실 수 있으니까요.",
          DialogueId = 51125616,
          GUID = "7FFCD460",
          NextDialogue = 51125617,
          SpeakNpcId = 701040,
          Subtitle = "Guests from abroad — travellers and traders alike — carry a token home for those left behind. As for things of real use... truth be told, our everyday wares seldom suit their habits."
        },
        [51125617] = {
          ContentKR = "그리고 솔직히, 엄청나게 유용한 물건이었으면, 상인들이 진작에 좋은 물건이라면서 여기저기 수출했겠죠. 이 화서에서만 팔겠어요.",
          DialogueId = 51125617,
          GUID = "7FFCD48A",
          NextOptions = {
            [1] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "And if something were truly needed, the Starweavers would've made it common long ago — sold everywhere. It wouldn't be a Huaxu exclusive."
        },
        [51125618] = {
          ContentKR = "전부 다 마음에 드는데, 돈이 없네요. 외상도 되나요?",
          DialogueId = 51125618,
          GUID = "7FFCD4B4",
          NextDialogue = 51125619,
          Subtitle = "I want the lot, but I've no money — could I have them on tick?"
        },
        [51125619] = {
          ContentKR = "손님... 이거 팔아 봐야 얼마나 남는다고 이러세요. 아니면 제가 일자리를 소개해 드릴게요. 별을 잇는 자들이 부두에서 짐꾼을 자주 구하던데, 가서 물어보시는 건 어때요?",
          DialogueId = 51125619,
          GUID = "7FFCD4DE",
          NextOptions = {
            [1] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "AAh... sorry, no can do for a small stall like mine. But if you're looking to earn a bit of coin, I can put in a word with the Starweavers down at the docks — they're always hiring porters."
        },
        [51125620] = {
          ContentKR = "외국인이라고 바가지 씌우는 건 아니겠죠?",
          DialogueId = 51125620,
          GUID = "7FFCD508",
          NextDialogue = 51125621,
          Subtitle = "You don't fleece tourists, do you?"
        },
        [51125621] = {
          ContentKR = "무슨 그런 섭섭한 말씀을 하세요! 제가 이 자리에서만 거의 10년을 장사했어요. 신용이라면 이름 나 있고, 가격도 최대한 저렴하게 드리고 있다고요.",
          DialogueId = 51125621,
          GUID = "7FFCD532",
          NextOptions = {
            [1] = 51125609,
            [2] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "Wouldn't dream of it! I've been at this stall for nearly ten years — folk round here know I give a fair deal. Ask around if you like."
        },
        [51125622] = {
          ContentKR = "딱히 별거 없네요. 전 가 볼게요.",
          DialogueId = 51125622,
          GUID = "7FFCD55C",
          NextDialogue = 51125623,
          Subtitle = "That's all I needed to know. See you."
        },
        [51125623] = {
          ContentKR = "안녕히 가세요! 나중에 시간 나시면 또 들러 주시고요. 마음에 쏙 드는 물건을 찾으실 수 있을 거예요!",
          DialogueId = 51125623,
          GUID = "7FFCD586",
          SpeakNpcId = 701040,
          Subtitle = "Take care! Pop by again — sure to be something you'll fancy."
        },
        [51125701] = {
          ContentKR = "이 별빛 부두가 지금은 별을 잇는 자들의 화물이나 오가는 조그만 부둣가에 불과하지만, 천 년 전만 해도 아주 대단한 분을 배출한 곳이라네.",
          DialogueId = 51125701,
          GUID = "7FFCE252",
          NextDialogue = 51125702,
          SpeakNpcId = 701041,
          Subtitle = "You lot might not know this, but this humble wharf of ours wasn't always so quiet. A thousand years ago, a great man once set sail from right here!"
        },
        [51125702] = {
          ContentKR = "그게 누구냐고? 이름만 대면 다들 알 양반이지. 바로 대풍구장의 창시자이시자, 장구파의 시조 되시는 '구' 님일세!",
          DialogueId = 51125702,
          GUID = "7FFCE27C",
          NextOptions = {
            [1] = 51125703,
            [2] = 51125720
          },
          SpeakNpcId = 701041,
          Subtitle = "And who was that great man, you ask? You all know his name — Ju, co-founder of the Nine Chapters, and the forefather of the Jishu Sect!"
        },
        [51125703] = {
          ContentKR = "계속 듣는다.",
          DialogueId = 51125703,
          GUID = "7FFCE2A6",
          NextDialogue = 51125704,
          Subtitle = "Listen on."
        },
        [51125704] = {
          ContentKR = "지나가는 분들은 다들 이 늙은이가 들려주는 별빛 부두의 역사를 들어 보시게. 장사꾼이라면 현명해야 하니, 이 땅의 과거도 훤히 알고 있어야지 않겠나.",
          DialogueId = 51125704,
          GUID = "7FFCE2D0",
          NextDialogue = 51125705,
          SpeakNpcId = 701041,
          Subtitle = "Folks, lend me your ears for a moment — let me tell you the thousand-year tale of our very own Starwharf! Just as trade should be fair and square, so too should our past — plain and open for all to see."
        },
        [51125705] = {
          ContentKR = "그 옛날, 화서에 대풍구장의 가호가 없었던 시절에는 사방에 들끓는 필토이드가 죄 없는 사람들을 닥치는 대로 공격했지. 살기 위해선 너 나 할 것 없이 녀석들과 목숨을 걸고 싸워야만 했어.",
          DialogueId = 51125705,
          GUID = "7FFCE2FA",
          NextDialogue = 51125706,
          SpeakNpcId = 701041,
          Subtitle = "Before the Nine Chapters came to guard us, old Huaxu was a hard place to live. Back then, the Filthoids ran wild, feasting on the helpless. To stay alive, every man, woman, and child had to fight or flee — no exceptions."
        },
        [51125706] = {
          ContentKR = "싸움이 있으면 죽고 다치는 사람이 생기는 법이라, 그때 화서는 사람의 씨가 마를 지경이었다네. 세상이 험해 아이들 태반이 살아남질 못했거든. 그래서 용의 자손들은 이 땅에 평화를 가져올 방법을 찾아 곳곳을 헤매고 다녔어.",
          DialogueId = 51125706,
          GUID = "7FFCE324",
          NextDialogue = 51125707,
          SpeakNpcId = 701041,
          Subtitle = "And where there's strife, there are graves. People dwindled, babies rarely saw their first spring. Even the proud Loongscions were at their wits' end, searching high and low for a way to bring peace back to the land."
        },
        [51125707] = {
          ContentKR = "우리의 선조이신 구 님도 화서 땅 구석구석을 다녔지만, 두 다리 뻗고 잘 곳이 없었다네. 그러다가 '차라리 이 나라 밖으로 나가서, 다른 사람들이 어찌 사는지 보고, 뛰어난 걸 배워서 우리 것으로 만들자'라는 생각이 드셨지.",
          DialogueId = 51125707,
          GUID = "7FFCE34E",
          NextOptions = {
            [1] = 51125708
          },
          SpeakNpcId = 701041,
          Subtitle = "Among them was Ju. He roamed every corner of Huaxu, seeking peace and finding none. At last, he thought: If peace can't be found on our shores, maybe it lies beyond the sea — in what others know, in what we've yet to learn."
        },
        [51125708] = {
          ContentKR = "계속 듣는다.",
          DialogueId = 51125708,
          GUID = "7FFCE378",
          NextDialogue = 51125709,
          Subtitle = "Listen on."
        },
        [51125709] = {
          ContentKR = "그 시절엔 지금처럼 튼튼한 배도 없었고, 별을 잇는 자도 없었다네. 바다로 나간다는 건 순전히 하늘에 목숨을 맡기는 일이라, 운 좋으면 무인도에 떠내려가서 새 구경이나 하는 거고, 운 나쁘면 물고기 밥 신세였어.",
          DialogueId = 51125709,
          GUID = "7FFCE3A2",
          NextDialogue = 51125710,
          SpeakNpcId = 701041,
          Subtitle = "Back in those days, there were no great ships — not a single Starweaver to be seen. To set sail was a pure gamble: with luck, you might wash ashore on some lonely isle, counting seabirds to pass the days; without it, you'd be fish food at the bottom of the sea."
        },
        [51125710] = {
          ContentKR = "그렇지만 구 님께선 모두가 평화로이 살게 하겠다는 마음 하나만으로, 손수 배를 만드셨다네. 게다가 남에게 폐 끼칠 순 없다고 덜컥 혼자서 이 별빛 부두에서 바다로 나가셨지!",
          DialogueId = 51125710,
          GUID = "7FFCE3CC",
          NextDialogue = 51125711,
          SpeakNpcId = 701041,
          Subtitle = "But Ju, bent on peace for all, built a boat with his own hands — asking help from no one — and pushed off alone from this very Starwharf!"
        },
        [51125711] = {
          ContentKR = "다행히도 백룡신군께서 보살펴 주신 덕분에, 구 님께선 거센 풍랑을 헤치고 신비로운 탑의 나라에 당도하셨네. 안타깝게도 그 나라도 제 코가 석 자라, 오히려 평온한 삶을 바라던 그곳 사람들을 데리고 귀국 길에 오르셨지.",
          DialogueId = 51125711,
          GUID = "7FFCE3F6",
          NextDialogue = 51125712,
          SpeakNpcId = 701041,
          Subtitle = "By Lord Argent's grace, Ju braved every storm the sea could throw at him, till at last he reached a hidden land where a sacred tower rose into the clouds. But peace? Not a trace of it there, either. So he turned his prow homeward once more — and with him came others who, like him, longed for peace."
        },
        [51125712] = {
          ContentKR = "몇 년이 지났을까, 다들 구 님은 진작 죽은 줄로만 알고 있었어. 그런데 이게 웬걸, 멀쩡히 살아 있는 걸로도 모자라, 수많은 사람을 데리고 떡하니 이 별빛 부두로 돌아오신 거네.",
          DialogueId = 51125712,
          GUID = "7FFCE420",
          NextOptions = {
            [1] = 51125713
          },
          SpeakNpcId = 701041,
          Subtitle = "Seasons passed, years slipped away... and folks here thought Ju had long been claimed by the sea. Then one day — from the horizon he came sailing back, right into Starwharf's arms, a handful of weary souls at his side."
        },
        [51125713] = {
          ContentKR = "계속 듣는다.",
          DialogueId = 51125713,
          GUID = "7FFCE44A",
          NextDialogue = 51125714,
          Subtitle = "Listen on."
        },
        [51125714] = {
          ContentKR = "어떻게 망망대해에서 정확히 길을 찾았는지 다들 궁금하지? 신령님의 가호일까? 아니면 엄청난 신념과 직감 덕분일까?",
          DialogueId = 51125714,
          GUID = "7FFCE474",
          NextDialogue = 51125715,
          SpeakNpcId = 701041,
          Subtitle = "You might be wondering — how did Ju find his way across that endless sea? Was it the gods who guided him? Or sheer guts and blind faith?"
        },
        [51125715] = {
          ContentKR = "둘 다 아니야! 속 시원히 알려 주지. 요새 별을 잇는 자들이 바다에서 길 찾는 데 쓰는 도구를 천성판이라고 하지? 구 님도 그걸 쓰셨던 거라네. 단지, 그분 건 최초의 천성판이었다 이 말일세.",
          DialogueId = 51125715,
          GUID = "7FFCE49E",
          NextDialogue = 51125716,
          SpeakNpcId = 701041,
          Subtitle = "Neither! All right, I won't keep you guessing — you know that Stellapass the Starweavers use to find their way at sea? Well, Ju's was the very first — built with his own hands."
        },
        [51125716] = {
          ContentKR = "그분은 나무판 몇 개로 별자리를 읽고 항로를 기록해서, 그 넓은 바다를 거침없이 자유자재로 오갈 수 있으셨던 거야.",
          DialogueId = 51125716,
          GUID = "7FFCE4C8",
          NextDialogue = 51125717,
          SpeakNpcId = 701041,
          Subtitle = "With plain old planks, he charted the stars, found his bearings, and sailed wherever his heart pleased."
        },
        [51125717] = {
          ContentKR = "구 님이 바다에서 무사히 돌아오신 뒤로, 화서의 용의 자손들은 더는 바다를 두려워하지 않게 됐지. 오늘날 별빛 부두와 별을 잇는 자들의 번영도 다 물꼬를 터 주신 그분 덕분이라네.",
          DialogueId = 51125717,
          GUID = "7FFCE4F2",
          NextDialogue = 51125718,
          SpeakNpcId = 701041,
          Subtitle = "It was Ju's voyage — out into the unknown and back again — that freed the Loongscions of Huaxu from their fear of the sea. For Starwharf's prosperity and the Starweavers' success today, we owe our thanks to Ju — the first soul brave enough to face the waves."
        },
        [51125718] = {
          ContentKR = "그러니까 우리는 늘 이 나라의 기틀을 닦아 주신 구와 양 두 선조님과 그분들의 업적을 가슴 깊이 새겨야 하네. 지금의 화서를 존재하게 해 주신 분들이니 말이야! 알겠는가?",
          DialogueId = 51125718,
          GUID = "7FFCE51C",
          NextDialogue = 51125719,
          SpeakNpcId = 701041,
          Subtitle = "And remember this, folks — Ju and Yang, founders side by side, names we must never let fade. Without them, there'd be no Huaxu as we know it today. So keep their names close, keep their deeds alive — and pass them on!"
        },
        [51125719] = {
          ContentKR = "(여기저기서 환호성이 터져 나온다.)",
          DialogueId = 51125719,
          GUID = "7FFCE546",
          Subtitle = "(The crowd bursts into cheers.)"
        },
        [51125720] = {
          ContentKR = "듣지 않는다.",
          DialogueId = 51125720,
          GUID = "7FFCE570",
          NextDialogue = 51125721,
          Subtitle = "That's enough for now."
        },
        [51125721] = {
          ContentKR = "(등 뒤로 노인이 화서의 기틀을 닦은 두 선조를 칭송하는 이야기보따리를 풀어놓는 소리와 차를 마시던 이들의 환호성이 들려온다...)",
          DialogueId = 51125721,
          GUID = "7FFCE59A",
          Subtitle = "(Behind you, Old Man Liu's voice carries on — still praising Huaxu's two founders as the onlookers clap along...)"
        },
        [51125801] = {
          ContentKR = "천성판 작동 상태는 전부 이상 없군. 어디 보자, 이제 곧 다음 정비일인가...",
          DialogueId = 51125801,
          GUID = "7FFCF2BA",
          NextDialogue = 51125802,
          SpeakNpcId = 701042,
          Subtitle = "The Stellapass is running fine. Come to think of it, it's about due for its next maintenance..."
        },
        [51125802] = {
          ContentKR = "설치한 지 3년도 안 됐는데 정비를 왜 벌써 받아야 하는 거람. 이번엔 기추파 기술자들한테 미리 예약해 뒀으려나... 일단 눈금이 닳았는지부터 확인해 보자!",
          DialogueId = 51125802,
          GUID = "7FFCF2E4",
          NextDialogue = 51125803,
          SpeakNpcId = 701042,
          Subtitle = "It's been less than three years since we installed this Stellapass. Why does it need maintenance already? I just hope they remembered to call in a craftsman from the Jishu Sect... Better check whether the calibration marks have faded."
        },
        [51125803] = {
          ContentKR = "꺅! 깜짝이야! 외국분이세요? 우리 배엔 왜 올라오셨어요?",
          DialogueId = 51125803,
          GUID = "7FFCF30E",
          NextOptions = {
            [1] = 51125804,
            [2] = 51125807
          },
          SpeakNpcId = 701042,
          Subtitle = "Whoa! You scared me! You're not from around here, are you? What are you doing on our ship?"
        },
        [51125804] = {
          ContentKR = "뭐 하시는 건지 궁금해서요.",
          DialogueId = 51125804,
          GUID = "7FFCF338",
          ImprPlusId = 1208,
          NextDialogue = 51125805,
          Subtitle = "Just curious what you're doing."
        },
        [51125805] = {
          ContentKR = "저요? 이 배의 천성판 상태를 점검하고 있었어요. 전 이 배에 배정된 기술자인데, 천성판이 잘 작동하는지 매일 확인하고 관리하는 게 제 일이거든요. 이게 없으면 배가 출항을 못 해요.",
          DialogueId = 51125805,
          GUID = "7FFCF362",
          NextDialogue = 51125806,
          SpeakNpcId = 701042,
          Subtitle = "Me? I'm just checking the ship's Stellapass. I'm the mechanic in charge of its maintenance. Without it, the ship wouldn't be able to leave port."
        },
        [51125806] = {
          ContentKR = "근데 볼일이 있으면 나중에 다시 찾아와 주실래요? 지금은 과열 상태를 점검해야 하거든요...",
          DialogueId = 51125806,
          GUID = "7FFCF38C",
          SpeakNpcId = 701042,
          Subtitle = "If you need anything, come back later — I still need to check for overheating."
        }
      }
    end
  },
  {
    MinKey = 51125807,
    MaxKey = 51126606,
    Loader = function()
      return {
        [51125807] = {
          ContentKR = "구경하다 보니까 여기 오게 됐네요.",
          DialogueId = 51125807,
          GUID = "7FFCF3B6",
          ImprPlusId = 1207,
          NextDialogue = 51125808,
          Subtitle = "Just taking a look around."
        },
        [51125808] = {
          ContentKR = "아, 그래요? 그런데 제가 지금 천성판 상태를 점검하는 중이라서요. 이게 고장 나면 배가 출항을 못 하거든요. 혹시 볼일이 있는 거면 나중에 다시 와서 얘기해 주세요.",
          DialogueId = 51125808,
          GUID = "7FFCF3E0",
          SpeakNpcId = 701042,
          Subtitle = "Oh, I'm in the middle of checking the Stellapass. If anything's off, we won't be able to set sail. Whatever you need, please come back later."
        },
        [51125809] = {
          ContentKR = "천성판 작동 상태는 전부 이상 없군. 어디 보자, 이제 곧 다음 정비일인가...",
          DialogueId = 51125809,
          GUID = "7FFCF40A",
          NextDialogue = 51125810,
          SpeakNpcId = 701042,
          Subtitle = "The Stellapass is running fine. Come to think of it, it's about due for its next maintenance..."
        },
        [51125810] = {
          ContentKR = "눈금 오차가... 수동으로 다섯 번이나 보정을 해도 결과가 비슷하네... 이러면 정비를 연기해 달라고 해도 되려나?",
          DialogueId = 51125810,
          GUID = "7FFCF434",
          NextDialogue = 51125811,
          SpeakNpcId = 701042,
          Subtitle = "Hmm, there was a slight scale error, but after five additional calibration runs, the readings are basically correct now. Perhaps we can request to postpone the maintenance."
        },
        [51125811] = {
          ContentKR = "앗, 또 만났네요, 외국분. 이번에도 구경하다 여기까지 온 모양이군요.",
          DialogueId = 51125811,
          GUID = "7FFCF45E",
          NextOptions = {
            [1] = 51125812,
            [2] = 51125815,
            [3] = 51125825
          },
          SpeakNpcId = 701042,
          Subtitle = "Oh, it's you again — the visitor from afar. Here to take another look?"
        },
        [51125812] = {
          ContentKR = "하시는 일이 어떻게 되세요?",
          DialogueId = 51125812,
          GUID = "7FFCF488",
          NextDialogue = 51125813,
          Subtitle = "What do you do?"
        },
        [51125813] = {
          ContentKR = "저요? 그야 이 배에 배정된 기술자죠. 항해 중에 갑자기 문제가 생기지 않도록, 천성판이 문제없이 잘 작동하는지 확인하는 게 제 일이에요.",
          DialogueId = 51125813,
          GUID = "7FFCF4B2",
          NextDialogue = 51125814,
          SpeakNpcId = 701042,
          Subtitle = "Me? I'm the ship's mechanic. I make sure the Stellapass runs smoothly — if it fails, the next voyage will be in trouble."
        },
        [51125814] = {
          ContentKR = "이런 정보들은 전부 꼼꼼하게 기록해 둬야 해요. 나중에 천록사에 통행증 신청할 때 필요하거든요.",
          DialogueId = 51125814,
          GUID = "7FFCF4DC",
          NextOptions = {
            [1] = 51125815,
            [2] = 51125825
          },
          SpeakNpcId = 701042,
          Subtitle = "I need to log all this down — it'll be useful when we file our report to the Ministry of Fortune."
        },
        [51125815] = {
          ContentKR = "천성판이 뭐예요?",
          DialogueId = 51125815,
          GUID = "7FFCF506",
          NextDialogue = 51125816,
          Subtitle = "What's a Stellapass?"
        },
        [51125816] = {
          ContentKR = "우리 별을 잇는 자들한테는 목숨줄이나 다름없는 보물이에요! 망망대해에서 길을 잘못 들고 싶지 않다면, 별의 위치를 관측해서 항로를 알려 주는 천성판이 필수죠.",
          DialogueId = 51125816,
          GUID = "7FFCF530",
          NextDialogue = 51125817,
          SpeakNpcId = 701042,
          Subtitle = "It's the Starweavers' lifeline — a marvel our ancestors left us. Out on the open sea, it reads the stars and keeps us steady, so we never lose our course."
        },
        [51125817] = {
          ContentKR = "화서 주변은 해류가 복잡해서, 천성판이 없으면 길을 잃고 헤매기 쉽거든요. 그래서, 별을 잇는 자들은 먼바다로 나가기 전에 항상 천성판의 상태를 꼼꼼히 점검해요.",
          DialogueId = 51125817,
          GUID = "7FFCF55A",
          NextOptions = {
            [1] = 51125818,
            [2] = 51125822
          },
          SpeakNpcId = 701042,
          Subtitle = "The seas around Huaxu are wild — without the Stellapass to guide us, we'd be swept off course in no time. That's why we always carry out a full check before every long voyage."
        },
        [51125818] = {
          ContentKR = "방금 정비란 건 무슨 말이에요?",
          DialogueId = 51125818,
          GUID = "7FFCF584",
          NextDialogue = 51125819,
          Subtitle = "What's that \"maintenance\" you mentioned?"
        },
        [51125819] = {
          ContentKR = "정비요? 기추파의 전문가들한테 천성판의 부품이 헐거워지거나 하진 않았는지 봐 달라고 하는 거예요. 대개는 별문제 없지만, 항해하다 보면 풍랑 때문에 부딪히거나 할 수 있으니까요.",
          DialogueId = 51125819,
          GUID = "7FFCF5AE",
          NextDialogue = 51125820,
          SpeakNpcId = 701042,
          Subtitle = "Maintenance? It just means having the Jishu Sect masters inspect it, to see if any parts have come loose. Usually it's fine — but out at sea, with all the pitching and rolling, a few bumps are hard to avoid."
        },
        [51125820] = {
          ContentKR = "저 같은 일반 기술자들은 문제를 찾아내긴 해도 수리는 못 하거든요. 그래서 전문 측정 장비를 가진 기추파 기술자들한테 점검을 받아야 해요. 자주는 아니고, 4~5년에 한 번이면 돼요.",
          DialogueId = 51125820,
          GUID = "7FFCF5D8",
          NextDialogue = 51125821,
          SpeakNpcId = 701042,
          Subtitle = "We regular mechanics can identify problems, but we can't repair them. Only the Jishu Sect has the proper tools for that. No need to trouble them too often — once every four or five years is enough."
        },
        [51125821] = {
          ContentKR = "근데 무작정 찾아가면 안 되고, 평소에 측정한 이런 데이터들을 같이 드려야 그분들도 정확한 판단을 내릴 수 있어요.",
          DialogueId = 51125821,
          GUID = "7FFCF602",
          SpeakNpcId = 701042,
          Subtitle = "And when we do, we have to bring along our daily readings — it helps them make a proper assessment."
        },
        [51125822] = {
          ContentKR = "천성판이 어디 있어요? 제 눈엔 안 보이는데요?",
          DialogueId = 51125822,
          GUID = "7FFCF62C",
          NextDialogue = 51125823,
          Subtitle = "Where's the Stellapass? I don't see it."
        },
        [51125823] = {
          ContentKR = "하하, 바보 같긴. 바로 우리 발밑에 있잖아요. 이런 큰 배는 천성판을 선실 안에 설치해 둬요. 대신 별을 관측하기 쉽게, 가장 커다란 판 하나는 하늘을 향해 거꾸로 달아 두죠.",
          DialogueId = 51125823,
          GUID = "7FFCF656",
          NextDialogue = 51125824,
          SpeakNpcId = 701042,
          Subtitle = "Ha! It's right beneath our feet, silly. On ships like this, the Stellapass is built into the hold — only the main plate is turned upward to face the sky, so it can read the stars."
        },
        [51125824] = {
          ContentKR = "외국분이 이해하기 쉽게 설명하자면, 커다란 샹들리에 같다고 생각하면 돼요. 바다에 나가 있을 땐, 누구 하나는 선실에서 계속 천성판이 얼마큼 돌아갔는지 기록해야 해요. 안 그러면 항로에서 벗어나기 쉽거든요.",
          DialogueId = 51125824,
          GUID = "7FFCF680",
          SpeakNpcId = 701042,
          Subtitle = "If I had to put it in your terms, it's a bit like a massive chandelier. Out at sea, there's always someone below keeping watch on how it turns — otherwise, we'd drift off course."
        },
        [51125825] = {
          ContentKR = "이제 궁금한 거 없어요.",
          DialogueId = 51125825,
          GUID = "7FFCF6AA",
          NextDialogue = 51125826,
          Subtitle = "That's all I wanted to ask."
        },
        [51125826] = {
          ContentKR = "전 이제 새로운 데이터를 측정해야겠네요. 무슨 일 있으면 또 찾아와요.",
          DialogueId = 51125826,
          GUID = "7FFCF6D4",
          SpeakNpcId = 701042,
          Subtitle = "If you need me, come back later — I've still got readings to take."
        },
        [51125901] = {
          ContentKR = "선생님, '해하다'가 무슨 뜻이죠? 잘 이해가 안 돼요.",
          DialogueId = 51125901,
          GUID = "7FFD0322",
          NextDialogue = 51125902,
          SpeakNpcId = 701043,
          Subtitle = "Ms Bai, could you clarify that?"
        },
        [51125902] = {
          ContentKR = "'해하다'는 해친다는 뜻이에요. 발음도 비슷하고 뜻도 같죠.",
          DialogueId = 51125902,
          GUID = "7FFD034C",
          NextDialogue = 51125903,
          SpeakNpcId = 701044,
          Subtitle = "In Huaxu, none may harm another — by any means, for any reason. Should another be hurt because of you, the fault is yours."
        },
        [51125903] = {
          ContentKR = "아! '회 치다'요? 그렇죠, 그렇죠! 사람을 회를 치면 큰일 나죠.",
          DialogueId = 51125903,
          GUID = "7FFD0376",
          NextDialogue = 51125904,
          SpeakNpcId = 701043,
          Subtitle = "Right... so, no shooting anyone. I can manage that."
        },
        [51125904] = {
          ContentKR = "음... 네, 그렇게 이해하셔도 돼요. 아무튼, 화서에선 남을 해치는 행위가 용납되지 않아요. 그러니까 그 총도 저희가 가지고 있다가, 나중에 떠나실 때 돌려드릴게요.",
          DialogueId = 51125904,
          GUID = "7FFD03A0",
          NextDialogue = 51125905,
          SpeakNpcId = 701044,
          Subtitle = "Good. Since you are in Huaxu, we shall keep the firearms you brought for safekeeping, and return them once you depart."
        },
        [51125905] = {
          ContentKR = "오케이, 노 프라블럼. 비즈니스 하러 왔으니까, 여기 규칙 따를게요. 그 대풍 어쩌고 말인데, 다른 규칙도 있어요?",
          DialogueId = 51125905,
          GUID = "7FFD03CA",
          NextDialogue = 51125906,
          SpeakNpcId = 701043,
          Subtitle = "Fair enough. I'm here to trade, not to fight. I'll follow the local rules — that Dafeng thing. Anything else I should know?"
        },
        [51125906] = {
          ContentKR = "사업을 하러 오셨다면, 두 번째 조항 \"약조를 어기거나 맹세를 저버리지 말지어다\"를 명심하세요.",
          DialogueId = 51125906,
          GUID = "7FFD03F4",
          NextDialogue = 51125907,
          SpeakNpcId = 701044,
          Subtitle = "Since you are here for trade, hear the second chapter: \"To break faith or betray a vow — this must not be done.\""
        },
        [51125907] = {
          ContentKR = "약조 그건 무슨 뜻인지 알겠는데, 맹세를 저버리지 말라는 건 무슨 뜻이죠? 맹세한 종이를 접지 말라는 건가요?",
          DialogueId = 51125907,
          GUID = "7FFD041E",
          NextDialogue = 51125908,
          SpeakNpcId = 701043,
          Subtitle = "I get \"betray a vow\", but what does \"break faith\" mean?"
        },
        [51125908] = {
          ContentKR = "종이접기의 '접다'가 아니라... 배신한다는 뜻의 '저버리다'예요. 그러니까, 화서 사람들하고 거래할 땐, 가격 협상이 끝나면, 백룡신군님을 증인으로 계약을 체결해야만 믿을 수 있다는 거죠.",
          DialogueId = 51125908,
          GUID = "7FFD0448",
          NextDialogue = 51125909,
          SpeakNpcId = 701044,
          Subtitle = "When you trade with our people, once a price is agreed, it must be sealed as a covenant under Lord Argent's witness. Without that, your promise holds no weight here."
        },
        [51125909] = {
          ContentKR = "아하, 이해했어요. 계약서를 쓰라는 거잖아요. 우리나라에서도 써요. 노 프라블럼, 노 프라블럼!",
          DialogueId = 51125909,
          GUID = "7FFD0472",
          NextDialogue = 51125910,
          SpeakNpcId = 701043,
          Subtitle = "Oh, I see — contracts. We do that too. No problem!"
        },
        [51125910] = {
          ContentKR = "아뇨, 그거하곤 달라요. 화서의 계약은 백룡신군이 지켜보는 가운데 서로 맹세하는 거예요. 화서에선 침월향의 재를 섞은 먹으로 계약서를 쓰게 되는데, 계약을 맺는 그 순간부터 그분께서 증인이 되어 주시죠.",
          DialogueId = 51125910,
          GUID = "7FFD049C",
          NextDialogue = 51125911,
          SpeakNpcId = 701044,
          Subtitle = "Not quite the same. Our covenants are written in ink mixed with Lunarose ash, beneath Lord Argent's gaze. That mark bears the deity's witness."
        },
        [51125911] = {
          ContentKR = "만약 한쪽이 맹세를 어기게 되면, 폐안님들의 추격을 받게 될 거예요!",
          DialogueId = 51125911,
          GUID = "7FFD04C6",
          NextDialogue = 51125912,
          SpeakNpcId = 701044,
          Subtitle = "And should either side break their oath... Bi'an will come for them."
        },
        [51125912] = {
          ContentKR = "폐안! 알아요! 화서에서 볼 수 있는 커다란 개 말하는 거잖아요!",
          DialogueId = 51125912,
          GUID = "7FFD04F0",
          NextDialogue = 51125913,
          SpeakNpcId = 701043,
          Subtitle = "Bi'an? The great hound of Huaxu — I've heard of it!"
        },
        [51125913] = {
          ContentKR = "무례하군요! 폐안님들을 그렇게 부르면 안 돼요!",
          DialogueId = 51125913,
          GUID = "7FFD051A",
          SpeakNpcId = 701044,
          Subtitle = "Mind your tongue! Speak not of Bi'an so lightly!"
        },
        [51126001] = {
          ContentKR = "크면 뿔이 날 거라더니, 엄마는 거짓말쟁이야. 재작년엔 작년에 난다 그랬고, 작년엔 올해 난다고 그랬는데, 아직까지 아무 일도 없는걸...",
          DialogueId = 51126001,
          GUID = "7FFD138A",
          NextDialogue = 51126002,
          SpeakNpcId = 701045,
          Subtitle = "Mum keeps saying I'll get horns when I'm older. Year before last she said \"next year\", and last year she said \"next year\" again... still nothing!"
        },
        [51126002] = {
          ContentKR = "설마 영원히 뿔이 안 나는 건 아니겠지? 싫어! 난 땅의 자손 하기 싫어! 멋있는 용의 자손 할래.",
          DialogueId = 51126002,
          GUID = "7FFD13B4",
          NextOptions = {
            [1] = 51126003,
            [2] = 51126005
          },
          SpeakNpcId = 701045,
          Subtitle = "What if they never grow? No — I don't want to be an Earthborn forever. I want to be a proper Loongscion!"
        },
        [51126003] = {
          ContentKR = "땅의 자손인 게 뭐가 어때서 그래?",
          DialogueId = 51126003,
          GUID = "7FFD13DE",
          ImprPlusId = 1207,
          NextDialogue = 51126004,
          Subtitle = "What's wrong with being an Earthborn?"
        },
        [51126004] = {
          ContentKR = "싫어, 완전 싫어. 엄청 센 마법을 쓸 수 있는 건 용의 자손들밖에 없단 말이야. 화서에서 신군님을 위해 일하려면, 용의 자손이 돼야만 해.",
          DialogueId = 51126004,
          GUID = "7FFD1408",
          SpeakNpcId = 701045,
          Subtitle = "Uh-uh! Earthborns don't get magic. Only Loongscions do — they're the ones who serve Lord Argent in Huaxu!"
        },
        [51126005] = {
          ContentKR = "용의 자손은 필토이드가 될 수도 있잖아.",
          DialogueId = 51126005,
          GUID = "7FFD1432",
          ImprPlusId = 1209,
          NextDialogue = 51126006,
          Subtitle = "But Loongcions might turn into Filthoids."
        },
        [51126006] = {
          ContentKR = "필토이드? 난 겁 하나도 안 나. 그리고 난 필토이드로 변해도, 멋진 폐안이 될 거야. 우리 엄마가 자랑스러워할 만큼!",
          DialogueId = 51126006,
          GUID = "7FFD145C",
          SpeakNpcId = 701045,
          Subtitle = "Filthoids? I'm not scared! If I ever turned into one, I'd be a mighty Bi'an! Mum would be so proud of me!"
        },
        [51126007] = {
          ContentKR = "뿔이 나게 하려면 어떻게 해야 하지? 끄으응... 아야! 당겨 봐야 아프기만 한데...",
          DialogueId = 51126007,
          GUID = "7FFD1486",
          NextDialogue = 51126008,
          SpeakNpcId = 701045,
          Subtitle = "How do I make my horns grow? Maybe if I give them a little tug... ow! That hurts!"
        },
        [51126008] = {
          ContentKR = "아! {性别:오빠|언니}구나? 얼마 전에 엄마가 새로 가르쳐 주신 건데, 별빛 부두를 지나다니는 용의 자손들 뿔을 많이 만지면, 나한테도 뿔이 자랄 거래.",
          DialogueId = 51126008,
          GUID = "7FFD14B0",
          NextDialogue = 51126009,
          SpeakNpcId = 701045,
          Subtitle = "Oh, it's you, {性别：sir|miss}. Mum taught me a trick: she says if I touch other Loongscions' horns here at the Starwharf, mine will grow too."
        },
        [51126009] = {
          ContentKR = "그리고 있잖아, 많이 만진 뿔이랑 똑같은 모양으로 자라니까, 멋있는 뿔을 가진 용의 자손을 골라야 한댔어! 난 {性别:오빠|언니} 뿔이 좋은데, 만져도 돼?",
          DialogueId = 51126009,
          GUID = "7FFD14DA",
          NextOptions = {
            [1] = 51126010,
            [2] = 51126030
          },
          SpeakNpcId = 701045,
          Subtitle = "She also said mine will grow just like those I touch! So I have to find the Loongscion with the prettiest horns! {性别：Sir|Miss}, I like yours — can I touch them?"
        },
        [51126010] = {
          ContentKR = "만지게 해 준다.",
          DialogueId = 51126010,
          GUID = "7FFD1504",
          NextDialogue = 51126011,
          Subtitle = "Let her touch."
        },
        [51126011] = {
          ContentKR = "고마워! 앙증맞고 단단하네. 잔뜩 만져야지.",
          DialogueId = 51126011,
          GUID = "7FFD152E",
          NextDialogue = 51126012,
          SpeakNpcId = 701045,
          Subtitle = "Thank you! They're small and hard — let me have a proper feel."
        },
        [51126012] = {
          ContentKR = "있잖아, 언젠가 나한테도 뿔이 자라면 엄마가 기뻐해 줄까? 나도 엄청난 마법 같은 거 쓸 수 있으려나? {性别:오빠|언니}는 마법 쓸 줄 알아?",
          DialogueId = 51126012,
          GUID = "7FFD1558",
          NextOptions = {
            [1] = 51126013,
            [2] = 51126017
          },
          SpeakNpcId = 701045,
          Subtitle = "If I grow horns one day, will Mum be happy? Will I get amazing magic too? {性别：Sir|Miss}, can you do magic?"
        },
        [51126013] = {
          ContentKR = "응, 그런데 화서에선 못 쓸 거야.",
          DialogueId = 51126013,
          GUID = "7FFD1582",
          NextDialogue = 51126014,
          Subtitle = "I can, but I won't be able to use it while I'm in Huaxu."
        },
        [51126014] = {
          ContentKR = "앗, 그렇구나. {性别:오빠|언니}처럼 엄청난 용의 자손이면 산과 바다를 뒤집는 마법도 쓸 수 있겠다! 검은 폐안 30마리 정도는 한 방에 날려 버릴 수도 있지?!",
          DialogueId = 51126014,
          GUID = "7FFD15AC",
          NextDialogue = 51126015,
          SpeakNpcId = 701045,
          Subtitle = "Oh, I know! You must have super strong magic, right? I bet you could blow up mountains — or send thirty Sable Bi'an flying with just one punch!"
        },
        [51126015] = {
          ContentKR = "우와! 생각만 해도 진짜 멋있다! {性别:오빠|언니}, 나중에 나 뿔 생기면, 그 엄청난 마법 좀 가르쳐 주라!",
          DialogueId = 51126015,
          GUID = "7FFD15D6",
          NextDialogue = 51126016,
          SpeakNpcId = 701045,
          Subtitle = "Wow! That sounds amazing! {性别：Sir|Miss}, if my horns grow, will you teach me that magic?"
        },
        [51126016] = {
          ContentKR = "그러려면 일단 뿔부터 나야지.",
          DialogueId = 51126016,
          GUID = "7FFD1600",
          SpeakNpcId = 100001,
          Subtitle = "Grow them first, then we'll talk."
        },
        [51126017] = {
          ContentKR = "그건 어렵겠는데. 난 검이랑 주먹밖에 쓸 줄 모르거든.",
          DialogueId = 51126017,
          GUID = "7FFD162A",
          NextDialogue = 51126018,
          Subtitle = "I can't — I only use a sword and my fists to fight."
        },
        [51126018] = {
          ContentKR = "어? 화서에선 남 때리고 그러면 안 돼. 근데 {性别:오빠|언니}가 그렇게 자신 있어 하는 걸 보니까, 그거랑 닮았어. 응천... 음... 뭐더라, 아무튼 화서에서 유일하게 싸워도 되는 그 사람들 말이야.",
          DialogueId = 51126018,
          GUID = "7FFD1654",
          NextDialogue = 51126019,
          SpeakNpcId = 701045,
          Subtitle = "Huh? But in Huaxu you're not supposed to be violent! Still... you're so confident. Maybe you're one of those... Yingtian-somethings? Um, I forgot the name — but they're the only ones allowed to fight in Huaxu!"
        },
        [51126019] = {
          ContentKR = "그 사람들 진짜 멋있어. 어딜 가든 사람들이 존경해 주고. 왜냐하면 신군님을 위해 일하는 분들이라 엄청 세거든!",
          DialogueId = 51126019,
          GUID = "7FFD167E",
          NextDialogue = 51126020,
          SpeakNpcId = 701045,
          Subtitle = "They're amazing! They serve Lord Argent directly. Everyone respects them. Super cool!"
        },
        [51126020] = {
          ContentKR = "나도 뿔이 나면, {性别:오빠|언니}처럼 멋진 용의 자손이 될 수 있을까...",
          DialogueId = 51126020,
          GUID = "7FFD16A8",
          NextDialogue = 51126021,
          SpeakNpcId = 701045,
          Subtitle = "Do you think... when I grow horns, I could be a Loongscion as awesome as you?"
        },
        [51126021] = {
          ContentKR = "그러려면 일단 뿔부터 나야지.",
          DialogueId = 51126021,
          GUID = "7FFD16D2",
          SpeakNpcId = 100001,
          Subtitle = "Grow them first, then we'll talk."
        },
        [51126022] = {
          ContentKR = "만진다고 뿔이 나진 않아.",
          DialogueId = 51126022,
          GUID = "7FFD16FC",
          NextDialogue = 51126023,
          Subtitle = "Touching them won't make yours grow, you know."
        },
        [51126023] = {
          ContentKR = "거짓말! 엄마는 그런 말 안 했어! 이 나쁜 용의 자손! 으아아앙! 나쁜 용의 자손은 폐안님이 잡아간댔어!",
          DialogueId = 51126023,
          GUID = "7FFD1726",
          NextOptions = {
            [1] = 51126024,
            [2] = 51126027
          },
          SpeakNpcId = 701045,
          Subtitle = "Liar! That's not what Mum said! You're mean! Waaah! Bi'an's gonna come and drag you away!"
        },
        [51126024] = {
          ContentKR = "아이를 달래 주기 위해 거짓말을 한다.",
          DialogueId = 51126024,
          GUID = "7FFD1750",
          NextDialogue = 51126025,
          Subtitle = "Tell a white lie to calm her."
        },
        [51126025] = {
          ContentKR = "그래, 그래, 내가 거짓말한 거야. 너도 언젠간 뿔이 나서 용의 자손이 될 거야.",
          DialogueId = 51126025,
          GUID = "7FFD177A",
          NextDialogue = 51126026,
          SpeakNpcId = 100001,
          Subtitle = "Alright, alright — I'm only joking. You'll grow horns sooner or later, and you'll be a Loongscion."
        },
        [51126026] = {
          ContentKR = "흥... 당연하지. 내 꿈은 용의 자손이 되는 거란 말이야...",
          DialogueId = 51126026,
          GUID = "7FFD17A4",
          SpeakNpcId = 701045,
          Subtitle = "Hmph... that's better. Becoming a Loongscion is my dream..."
        },
        [51126027] = {
          ContentKR = "사실을 말한다.",
          DialogueId = 51126027,
          GUID = "7FFD17CE",
          NextDialogue = 51126028,
          Subtitle = "Stick to your story."
        },
        [51126028] = {
          ContentKR = "성장한다고 종족이 바뀌는 경우는 없어. 어렸을 때 뿔이 없었으면, 커서도 뿔은 안 나는 거야.",
          DialogueId = 51126028,
          GUID = "7FFD17F8",
          NextDialogue = 51126029,
          SpeakNpcId = 100001,
          Subtitle = "People don't suddenly change when they grow up. If you don't have horns as a child, you won't suddenly sprout them later."
        },
        [51126029] = {
          ContentKR = "으아아앙!!! 어린이를 괴롭히는 나쁜 용의 자손! 아빠한테 혼내 주라고 할 거야, 여기서 딱 기다려!",
          DialogueId = 51126029,
          GUID = "7FFD1822",
          SpeakNpcId = 701045,
          Subtitle = "Waaah! You're a mean Loongscion! You're being mean to me! Just you wait — I'll get my dad to beat you up!"
        },
        [51126030] = {
          ContentKR = "떠난다.",
          DialogueId = 51126030,
          GUID = "7FFD184C",
          NextDialogue = 51126031,
          Subtitle = "I'm leaving."
        },
        [51126031] = {
          ContentKR = "나는 용의 자손이 되고 말 거야, 꼭!",
          DialogueId = 51126031,
          GUID = "7FFD1876",
          SpeakNpcId = 701045,
          Subtitle = "I'll be a Loongscion yet — just you wait and see!"
        },
        [51126101] = {
          ContentKR = "이럴 줄 알았으면 진작 와서 신청하는 거였는데. 그랬으면 자금 융통이 안 돼서 그 큰 건을 놓치는 일도 없었겠지...",
          DialogueId = 51126101,
          GUID = "7FFD23F2",
          NextDialogue = 51126102,
          SpeakNpcId = 701046,
          Subtitle = "If I'd known sooner, I would've joined right away. With EverSpring supporting me, I wouldn't have lost that big deal just for lacking a bit of capital..."
        },
        [51126102] = {
          ContentKR = "안녕하세요, 그쪽도 별을 잇는 자가 되려고 신청하러 온 건가요?",
          DialogueId = 51126102,
          GUID = "7FFD241C",
          NextOptions = {
            [1] = 51126103,
            [2] = 51126107
          },
          SpeakNpcId = 701046,
          Subtitle = "Ah, my friend — are you here to apply to become a Starweaver as well?"
        },
        [51126103] = {
          ContentKR = "그런 셈이죠. 마침 얘기하시는 걸 들어서요.",
          DialogueId = 51126103,
          GUID = "7FFD2446",
          NextDialogue = 51126104,
          Subtitle = "Sort of. I just happened to hear you talking about it."
        },
        [51126104] = {
          ContentKR = "사람 잘 찾아오셨네요. 전 조금 전에 신청 절차를 다 끝냈거든요. 서류 작성부터 잔고 증명까지 싹 다 꿰고 있죠.",
          DialogueId = 51126104,
          GUID = "7FFD2470",
          NextDialogue = 51126105,
          SpeakNpcId = 701046,
          Subtitle = "Then you've found the right person. I just completed the entire process myself — paperwork, proof of capital, every step. I know it inside out."
        },
        [51126105] = {
          ContentKR = "그렇다고... 절차가 아주 까다롭단 소리는 아니에요. 백년춘은 진심으로 상인이 되고 싶어 하는 사람을 난처하게 만드는 곳은 절대 아니거든요.",
          DialogueId = 51126105,
          GUID = "7FFD249A",
          NextDialogue = 51126106,
          SpeakNpcId = 701046,
          Subtitle = "Not that it's troublesome — EverSpring never makes things difficult for an honest trader."
        },
        [51126106] = {
          ContentKR = "마음은 감사한데, 아직 신청할 생각은 없어요.",
          DialogueId = 51126106,
          GUID = "7FFD24C4",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but I don't have such plans at the moment."
        },
        [51126107] = {
          ContentKR = "아뇨, 어쩌다 그쪽 얘기를 들은 것뿐이에요.",
          DialogueId = 51126107,
          GUID = "7FFD24EE",
          NextDialogue = 51126108,
          Subtitle = "I just happened to hear you talking about it."
        },
        [51126108] = {
          ContentKR = "아~ 전 백년춘에 찾아오는 외국인은 다 별을 잇는 자가 되려는 사람인 줄 알았어요. 그러고 보니까, 외국인은 신청 절차가 우리 화서 사람들하곤 좀 다른 모양이더라고요.",
          DialogueId = 51126108,
          GUID = "7FFD2518",
          NextDialogue = 51126109,
          SpeakNpcId = 701046,
          Subtitle = "Oh? I thought most visitors came to EverSpring hoping to become Starweavers. Now that you mention it, the process does differ a bit between locals and outsiders."
        },
        [51126109] = {
          ContentKR = "그래도 걱정 마세요! 백년춘은 진심으로 상인이 되고 싶어 하는 사람을 난처하게 만드는 곳은 절대 아니까요.",
          DialogueId = 51126109,
          GUID = "7FFD2542",
          NextDialogue = 51126110,
          SpeakNpcId = 701046,
          Subtitle = "Still, don't worry — EverSpring treats every fair and honest merchant equally."
        },
        [51126110] = {
          ContentKR = "마음은 감사한데, 아직 신청할 생각은 없어요.",
          DialogueId = 51126110,
          GUID = "7FFD256C",
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but I don't have such plans at the moment."
        },
        [51126111] = {
          ContentKR = "별을 잇는 자가 되면 좋은 점이 정말 많구나! 백년춘은 정말 대단한 곳이네!",
          DialogueId = 51126111,
          GUID = "7FFD2596",
          NextDialogue = 51126112,
          SpeakNpcId = 701046,
          Subtitle = "I never realized being a Starweaver came with so many perks. EverSpring truly is remarkable."
        },
        [51126112] = {
          ContentKR = "또 만났네요. 이번에는 별을 잇는 자가 되기로 마음을 굳힌 건가요?",
          DialogueId = 51126112,
          GUID = "7FFD25C0",
          NextOptions = {
            [1] = 51126113,
            [2] = 51126119,
            [3] = 51126126
          },
          SpeakNpcId = 701046,
          Subtitle = "Ah, my foreign friend — have you decided to join the Starweavers this time?"
        },
        [51126113] = {
          ContentKR = "혹시 별을 잇는 자 홍보 대사예요?",
          DialogueId = 51126113,
          GUID = "7FFD25EA",
          NextDialogue = 51126114,
          Subtitle = "You're quite the spokesperson for them, you know."
        },
        [51126114] = {
          ContentKR = "별을 잇는 자가 됐을 때 백년춘에서 얼마나 든든한 지원을 해 주는지 알면, 그쪽도 이렇게 될 거예요.",
          DialogueId = 51126114,
          GUID = "7FFD2614",
          NextOptions = {
            [1] = 51126115
          },
          SpeakNpcId = 701046,
          Subtitle = "If you knew how much support EverSpring gives its Starweavers, you'd be just as enthusiastic as I am."
        },
        [51126115] = {
          ContentKR = "대체 어떤 혜택이 있는데요?",
          DialogueId = 51126115,
          GUID = "7FFD263E",
          NextDialogue = 51126116,
          Subtitle = "Then what sort of benefits are we talking about?"
        },
        [51126116] = {
          ContentKR = "엄청 많죠! 먼저, 저 같은 사업 왕초보도 별을 잇는 자가 되면 바로 사업 자금을 빌릴 수 있어요. 이자는 굉장히 낮고, 그 돈으로 무슨 장사를 하든 상관없죠.",
          DialogueId = 51126116,
          GUID = "7FFD2668",
          NextDialogue = 51126117,
          SpeakNpcId = 701046,
          Subtitle = "Quite a few, actually. For newcomers like me, once you join, you can apply for a starting fund — there's interest, but it's low — and you can use it for any kind of trade you prefer."
        },
        [51126117] = {
          ContentKR = "게다가 백년춘이란 든든한 뒷배가 있으니까, 아무리 큰 거래처라도 함부로 대하지 못해요. 가끔은 별을 잇는 자라는 이름만 보고 먼저 찾아오는 사람들도 있고요.",
          DialogueId = 51126117,
          GUID = "7FFD2692",
          NextDialogue = 51126118,
          SpeakNpcId = 701046,
          Subtitle = "With EverSpring's name behind us, even the largest merchants treat us with respect — some even approach us first simply because we're Starweavers."
        },
        [51126118] = {
          ContentKR = "제가 집집마다 돌아다니면서 물건 사러 다녔던 때하곤 하늘과 땅 차이라니까요.",
          DialogueId = 51126118,
          GUID = "7FFD26BC",
          SpeakNpcId = 701046,
          Subtitle = "It's a far cry from the days when I had to go door to door trying to gather stock."
        },
        [51126119] = {
          ContentKR = "화서의 상인이면 다 별을 잇는 자 아니었어요?",
          DialogueId = 51126119,
          GUID = "7FFD26E6",
          NextDialogue = 51126120,
          Subtitle = "So not every merchant in Huaxu is a Starweaver, then?"
        },
        [51126120] = {
          ContentKR = "아뇨, 완전히 잘못 알고 있는 거예요. 별을 잇는 자는 별을 잇는 자고, 행상인이나 노점상도 있어요. 다 다르답니다.",
          DialogueId = 51126120,
          GUID = "7FFD2710",
          NextDialogue = 51126121,
          SpeakNpcId = 701046,
          Subtitle = "No, not at all. Starweavers are one group; there are also hawkers and stallholders — quite a different crowd."
        },
        [51126121] = {
          ContentKR = "별을 잇는 자가 되면 편리한 점도 많지만, 지킬 규칙도 많아져요. 거래가 성사되면 꼭 계약서를 써야 한다는 점 같은 게 그렇죠. 행상인 생활을 오래 하셨거나, 동네 장사에 익숙하신 분들은 오히려 이런 규칙들을 답답해하세요.",
          DialogueId = 51126121,
          GUID = "7FFD273A",
          NextDialogue = 51126122,
          SpeakNpcId = 701046,
          Subtitle = "Being a Starweaver certainly has its advantages, but also plenty of rules. Once a deal is made, you must seal a covenant and follow the proper terms. For those used to traveling trade or running small stalls, such rules can feel a bit restrictive."
        },
        [51126122] = {
          ContentKR = "저도 그랬었거든요. 여기저기 돌아다니면서 장사도 좀 하다가, 돈이 좀 모여서 사업을 키워 보려고 여기 온 거예요.",
          DialogueId = 51126122,
          GUID = "7FFD2764",
          NextOptions = {
            [1] = 51126123
          },
          SpeakNpcId = 701046,
          Subtitle = "I used to be the same — traveling from place to place, doing small trades along the way. Saved up a little, then came here hoping to make something bigger of it."
        },
        [51126123] = {
          ContentKR = "화서엔 별을 잇는 자가 대략 얼마나 돼요?",
          DialogueId = 51126123,
          GUID = "7FFD278E",
          NextDialogue = 51126124,
          Subtitle = "How many Starweavers are there in Huaxu?"
        },
        [51126124] = {
          ContentKR = "구체적인 숫자라... 글쎄요, 세 본 사람이 있을까요? 자기 이름에 신뢰감을 주려고 별을 잇는 자가 되는 상인들도 있거든요. 굳이 따지면... 열 명 중 일곱, 아니, 여섯 명 정도려나요?",
          DialogueId = 51126124,
          GUID = "7FFD27B8",
          NextDialogue = 51126125,
          SpeakNpcId = 701046,
          Subtitle = "How many? Hard to say. Plenty of shops register just to make their names sound more trustworthy. If I had to guess... perhaps six or seven out of ten."
        },
        [51126125] = {
          ContentKR = "결론은, 별을 잇는 자는 어디에서 만나든 이상하지 않다는 거예요.",
          DialogueId = 51126125,
          GUID = "7FFD27E2",
          SpeakNpcId = 701046,
          Subtitle = "In any case, it's common to meet Starweavers in all sorts of trades wherever you go."
        },
        [51126126] = {
          ContentKR = "다음에 또 얘기해요.",
          DialogueId = 51126126,
          GUID = "7FFD280C",
          NextDialogue = 51126127,
          Subtitle = "Let's talk next time."
        },
        [51126127] = {
          ContentKR = "좋죠. 다음에 신청하러 올 때 또 이야기 나눠요.",
          DialogueId = 51126127,
          GUID = "7FFD2836",
          SpeakNpcId = 701046,
          Subtitle = "Of course. Come find me when you're ready to apply."
        },
        [51126201] = {
          ContentKR = "총 선생님, 올해 백년춘의 증축 규모는 계획을 훨씬 넘어섰어요. 건물 보수만 하려 했는데, 다실까지 짓게 됐잖아요.",
          DialogueId = 51126201,
          GUID = "7FFD345A",
          NextDialogue = 51126202,
          SpeakNpcId = 701047,
          Subtitle = "Mr Cong, this year's building work at EverSpring has already gone well beyond the plan. It was meant to be a modest repair, and now there's even a tea room added."
        },
        [51126202] = {
          ContentKR = "알아, 알아. 다 이 씨가 낸 돈이잖아. 그 양반이 낸 후원금은 받으면서, 내 돈은 왜 못 받겠다는 거야? 돈을 번 별을 잇는 자가 백년춘에 보답하는 건 오래된 전통이라고.",
          DialogueId = 51126202,
          GUID = "7FFD3484",
          NextDialogue = 51126203,
          SpeakNpcId = 701048,
          Subtitle = "Yes, I know — Li provided the silver for that. If his gift was accepted, why not mine? We Starweavers earn our living abroad and return home to honour EverSpring — it's been our custom for generations."
        },
        [51126203] = {
          ContentKR = "정말 안 돼요, 선생님. 아시잖아요. 다들 백년춘에 기부하고 싶어 해서, 십시일반으로 보태다 보니까, 건물이 더는 못 버틸 정도의 규모가 돼 버렸단 걸요.",
          DialogueId = 51126203,
          GUID = "7FFD34AE",
          NextDialogue = 51126204,
          SpeakNpcId = 701047,
          Subtitle = "We truly cannot, sir. You know how people are — everyone wishes to contribute to EverSpring. The guild was never a grand one to begin with; it's grown brick by brick to what it is now. We can't continue like this forever."
        },
        [51126204] = {
          ContentKR = "이렇게 계속 증축하다간 백년춘 건물이 무너져 버릴지도 몰라요. 그렇게 되면 건물을 새로 지어야 해요.",
          DialogueId = 51126204,
          GUID = "7FFD34D8",
          NextDialogue = 51126205,
          SpeakNpcId = 701047,
          Subtitle = "If we keep building at this rate, EverSpring will wear itself thin — and we'll all end up rebuilding in the end."
        },
        [51126205] = {
          ContentKR = "그건 내 알 바 아니고, 이 씨 돈을 받았으면 내 돈도 받아야지. 여차하면 밤에 몰래 돈 던져 놓고 가는 수가 있어.",
          DialogueId = 51126205,
          GUID = "7FFD3502",
          NextDialogue = 51126206,
          SpeakNpcId = 701048,
          Subtitle = "I don't care. You've taken Li's silver, you'll take mine as well. If not, I'll come by in the dead of night and leave the money here myself."
        },
        [51126206] = {
          ContentKR = "그야... 이 선생님은 재작년부터 증축 허가가 나길 기다리셨다가, 올해 허가가 나자마자 제일 먼저 신청서를 내셨으니까 그렇죠. 일 처리엔 순서란 게 있잖아요.",
          DialogueId = 51126206,
          GUID = "7FFD352C",
          NextDialogue = 51126207,
          SpeakNpcId = 701047,
          Subtitle = "Well... Mr Li has been waiting since the year before last for this year's building quota. He put in his request the moment it opened — there is, after all, an order of precedence."
        },
        [51126207] = {
          ContentKR = "그러면 내 돈은 새로 들어온 별을 잇는 자를 도와주는 데 써. 나도 그렇게 도움을 받았었으니까!",
          DialogueId = 51126207,
          GUID = "7FFD3556",
          SpeakNpcId = 701048,
          Subtitle = "Then use my silver to help the new Starweavers — just as the guild once lent its hand to me."
        },
        [51126301] = {
          ContentKR = "그야 모르지. 저 달도 옛날에 별을 잇는 자들이 벽돌을 차곡차곡 쌓아서 만든 거니까, 올라가는 길 하나는 남겨 놨을 거야.",
          DialogueId = 51126301,
          GUID = "7FFD44C2",
          NextDialogue = 51126302,
          SpeakNpcId = 701049,
          Subtitle = "I'm not sure. But the Starweavers made this moon, piece by piece — there must be a way up!"
        },
        [51126302] = {
          ContentKR = "게다가 이건 이 근처에서 제일 큰 향로니까, 평소에도 수리하러 사람이 오르내릴걸.",
          DialogueId = 51126302,
          GUID = "7FFD44EC",
          NextDialogue = 51126303,
          SpeakNpcId = 701049,
          Subtitle = "And it's like a huge incense burner for our city! Someone's got to climb up and clean it once in a while."
        },
        [51126303] = {
          ContentKR = "그렇긴 한데, 길이 어디 있어? 내 눈엔 안 보이는데?",
          DialogueId = 51126303,
          GUID = "7FFD4516",
          NextDialogue = 51126304,
          SpeakNpcId = 701050,
          Subtitle = "Yes, but where's the way up? I can't see anything!"
        },
        [51126304] = {
          ContentKR = "어휴, 조용히 좀 해 봐. 지금 생각 중이잖아.",
          DialogueId = 51126304,
          GUID = "7FFD4540",
          NextOptions = {
            [1] = 51126305,
            [2] = 51126312,
            [3] = 51126323
          },
          SpeakNpcId = 701049,
          Subtitle = "Shh, I'm thinking! I'll figure something out!"
        },
        [51126305] = {
          ContentKR = "둘이 무슨 얘기 중이야?",
          DialogueId = 51126305,
          GUID = "7FFD456A",
          NextDialogue = 51126306,
          Subtitle = "What are you two talking about?"
        },
        [51126306] = {
          ContentKR = "으앗! 외국인이다!",
          DialogueId = 51126306,
          GUID = "7FFD4594",
          NextDialogue = 51126307,
          SpeakNpcId = 701050,
          Subtitle = "Whoa! A foreigner!?"
        },
        [51126307] = {
          ContentKR = "외국인도 저 커다란 달에 관심 있어?",
          DialogueId = 51126307,
          GUID = "7FFD45BE",
          NextOptions = {
            [1] = 51126308,
            [2] = 51126310
          },
          SpeakNpcId = 701049,
          Subtitle = "Do you like the big moon too?"
        },
        [51126308] = {
          ContentKR = "응, 관심 있어.",
          DialogueId = 51126308,
          GUID = "7FFD45E8",
          NextDialogue = 51126309,
          Subtitle = "I do."
        },
        [51126309] = {
          ContentKR = "토토, 이 바보야. 백년춘에 온 사람이 달에 관심 없을 리가 없잖아? 저렇게 큰 달이면, 바다 저 멀리서부터 보였을걸.",
          DialogueId = 51126309,
          GUID = "7FFD4612",
          SpeakNpcId = 701049,
          Subtitle = "Silly Bunny! Everyone likes it! It's so big you can even see it from the sea!"
        },
        [51126310] = {
          ContentKR = "아니, 별로 관심 없어.",
          DialogueId = 51126310,
          GUID = "7FFD463C",
          NextDialogue = 51126311,
          Subtitle = "Not really."
        },
        [51126311] = {
          ContentKR = "어라? 말도 안 돼! 저렇게 커다랗고 밝은데 관심이 없다고? 거짓말!",
          DialogueId = 51126311,
          GUID = "7FFD4666",
          SpeakNpcId = 701050,
          Subtitle = "What? Really? It's so bright and huge! How can you not like it? You must be fibbing!"
        },
        [51126312] = {
          ContentKR = "그런데 저긴 왜 올라가려고 하는 거야?",
          DialogueId = 51126312,
          GUID = "7FFD4690",
          NextDialogue = 51126313,
          Subtitle = "Why do you want to climb it?"
        },
        [51126313] = {
          ContentKR = "저 커다란 달 꼭대기가 우리 연진 나루터에서 제일 높은 곳이라고 했거든. 저 위에선 나루터가 한눈에 내려다보일 것 같아서!",
          DialogueId = 51126313,
          GUID = "7FFD46BA",
          NextDialogue = 51126314,
          SpeakNpcId = 701049,
          Subtitle = "Someone said the very top's the highest place in Mistwharf! You can see the whole Mistwharf from up there. We just want to have a look!"
        },
        [51126314] = {
          ContentKR = "맞아! 올라가서 백년춘 지붕 위로 감자갈매기가 하루에 몇 마리나 날아가는지 세어 볼 거야!",
          DialogueId = 51126314,
          GUID = "7FFD46E4",
          NextOptions = {
            [1] = 51126315
          },
          SpeakNpcId = 701050,
          Subtitle = "Uh-huh! We want to count all the Chipgulls that fly over EverSpring in one day!"
        },
        [51126315] = {
          ContentKR = "그러니까, 저 달이 건물이라는 거야?",
          DialogueId = 51126315,
          GUID = "7FFD470E",
          NextDialogue = 51126316,
          Subtitle = "So it's not real? People built it?"
        },
        [51126316] = {
          ContentKR = "몰랐어? 아, 맞다, 외국 사람이었지. 저 달은 우리 연진 나루터에 있는 커다란 향로야. 옛날에 엄청 부자였던 별을 잇는 자가 돈 내서 만든 거래.",
          DialogueId = 51126316,
          GUID = "7FFD4738",
          NextOptions = {
            [1] = 51126317
          },
          SpeakNpcId = 701049,
          Subtitle = "You didn't know? Oh, right — you're not from here! The moon's actually a giant incense burner in Mistwharf. A really rich Starweaver paid to have it built!"
        },
        [51126317] = {
          ContentKR = "왜 달 모양인 거야?",
          DialogueId = 51126317,
          GUID = "7FFD4762",
          NextDialogue = 51126318,
          Subtitle = "Why did they make it look like a moon?"
        },
        [51126318] = {
          ContentKR = "그건 내가 알아! 그 사람이, 바다 건너 외국에 있는 별을 잇는 자들은 다들 하늘의 별처럼, 언젠간 고향에 돌아올 테니까, 그 사람들을 맞이해 줄 밝은 달이 있어야 한다고 그랬대!",
          DialogueId = 51126318,
          GUID = "7FFD478C",
          NextDialogue = 51126319,
          SpeakNpcId = 701050,
          Subtitle = "Oh, I know this one! The Starweaver said people who sail away are like stars in the sky — they'll all come home one day! So home needs a bright moon to guide them back!"
        },
        [51126319] = {
          ContentKR = "오, 좀 아네! 너 그럼 그 사람이 저 커다란 달에 붙여 준 이름이 뭔지도 알아?",
          DialogueId = 51126319,
          GUID = "7FFD47B6",
          NextDialogue = 51126320,
          SpeakNpcId = 701049,
          Subtitle = "Aren't you a know-it-all! Then do you know what the Starweaver called it?"
        },
        [51126320] = {
          ContentKR = "음... 그건 기억 안 나는데...",
          DialogueId = 51126320,
          GUID = "7FFD47E0",
          NextDialogue = 51126321,
          SpeakNpcId = 701050,
          Subtitle = "Erm... I forgot..."
        },
        [51126321] = {
          ContentKR = "에헴, 내가 알려 줄게. 바로 '달은 고향에서도 밝게 빛나리'라는 이름이야.",
          DialogueId = 51126321,
          GUID = "7FFD480A",
          NextDialogue = 51126322,
          SpeakNpcId = 701049,
          Subtitle = "Ahem! Let me tell you then — it's called... Homeward Bright Moon!"
        },
        [51126322] = {
          ContentKR = "내가 못 외울 만도 하네, 뭔 이름이 그렇게 길어! 그냥 '커다란 달'이라고 하면 기억하기 쉽잖아.",
          DialogueId = 51126322,
          GUID = "7FFD4834",
          SpeakNpcId = 701050,
          Subtitle = "That's such a long name! No wonder I forgot. \"Big Moon\" sounds much better!"
        },
        [51126323] = {
          ContentKR = "다음에 또 놀러 올게.",
          DialogueId = 51126323,
          GUID = "7FFD485E",
          NextDialogue = 51126324,
          Subtitle = "See you next time."
        },
        [51126324] = {
          ContentKR = "잘 가, 외국 사람! 우린 저기 어떻게 올라갈지 잘 생각해 보자.",
          DialogueId = 51126324,
          GUID = "7FFD4888",
          SpeakNpcId = 701049,
          Subtitle = "See you, traveller! Come on, let's get back to figuring out how to climb it!"
        },
        [51126401] = {
          ContentKR = "거 참 신기해라. 이렇게 오래된 골동품 천성판을 보게 될 줄이야. 이걸론 운세는커녕... 날씨 예측도 힘들겠지만...",
          DialogueId = 51126401,
          GUID = "7FFD552A",
          NextDialogue = 51126402,
          SpeakNpcId = 701051,
          Subtitle = "Didn't expect to stumble upon something this old today. It seems barely stable enough to read the weather, let alone fortunes..."
        },
        [51126402] = {
          ContentKR = "이건 아마 우리 할아버지의 할아버지의 할아버지보다도 나이가 많을... 아니지, 할아버지의 할아... 어휴, 혀 꼬여. 어쨌든 엄청난 조상님뻘이야!",
          DialogueId = 51126402,
          GUID = "7FFD5554",
          NextOptions = {
            [1] = 51126403,
            [2] = 51126405
          },
          SpeakNpcId = 701051,
          Subtitle = "It must date back to my great-great-grandfather's time — or perhaps even earlier. Well, you get the idea. It's ancient."
        },
        [51126403] = {
          ContentKR = "뭐 하시는 거예요?",
          DialogueId = 51126403,
          GUID = "7FFD557E",
          NextDialogue = 51126404,
          Subtitle = "What are you doing?"
        },
        [51126404] = {
          ContentKR = "저요? 아까 오래된 천성판을 하나 구했는데, 집에 가져가서 소장품으로 삼을까 해서요. 그런데 누구시죠? 그쪽도 옛날 물건에 관심이 많나요?",
          DialogueId = 51126404,
          GUID = "7FFD55A8",
          SpeakNpcId = 701051,
          Subtitle = "Me? I happened upon this old Stellapass and thought I'd keep it as a curio. And you? Are you interested in relics as well?"
        },
        [51126405] = {
          ContentKR = "그냥 천성판이 뭔지 궁금한 거예요.",
          DialogueId = 51126405,
          GUID = "7FFD55D2",
          NextDialogue = 51126406,
          Subtitle = "Just curious about the Stellapass."
        },
        [51126406] = {
          ContentKR = "오? 외국분이 화서 물건에 관심을 보이신다니, 당연히 이 나라 사람인 제가 가르쳐 드려야죠. 모르는 게 있으면 뭐든 물어보세요. 아는 건 다 가르쳐 드릴게요!",
          DialogueId = 51126406,
          GUID = "7FFD55FC",
          SpeakNpcId = 701051,
          Subtitle = "Ah, a traveller with a taste for Huaxu craftsmanship. Then allow me to play the host — ask away, and I'll share what I know."
        },
        [51126407] = {
          ContentKR = "이야, 정말 오래된 천성판이네!",
          DialogueId = 51126407,
          GUID = "7FFD5626",
          NextDialogue = 51126408,
          SpeakNpcId = 701051,
          Subtitle = "Ah... this Stellapass — now that's a piece of history!"
        },
        [51126408] = {
          ContentKR = "왔군요. 천성판에 대해 궁금한 게 있나요?",
          DialogueId = 51126408,
          GUID = "7FFD5650",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "There you are. You wished to learn about the Stellapass, did you not?"
        },
        [51126409] = {
          ContentKR = "천성판은 어떻게 만들어진 거예요?",
          DialogueId = 51126409,
          GUID = "7FFD567A",
          NextDialogue = 51126410,
          Subtitle = "Can you tell me the story of the Stellapass?"
        },
        [51126410] = {
          ContentKR = "천성판의 기원이라... 그건 화서가 세워지기 전, 그러니까 구 님과 양 님의 시대로 거슬러 올라가야 해요. 그땐 다양한 학파가 존재했는데, 별자리를 관찰하고 연구하는 병촉이란 학파가 있었어요.",
          DialogueId = 51126410,
          GUID = "7FFD56A4",
          NextDialogue = 51126411,
          SpeakNpcId = 701051,
          Subtitle = "A long story indeed. These instruments date back to before the founding of Huaxu — to the age of Ju and Yang. In those days, a hundred schools of thought flourished, and among them, the Bingzhu Sect devoted itself to the study of the stars."
        },
        [51126411] = {
          ContentKR = "병촉파 사람들은 저 하늘 위에 이 세상을 멸망시킬 위기가 도사리고 있다고 여겼고, 대비책으로 하늘과 별자리를 관측하는 '천성술'을 연구했죠.",
          DialogueId = 51126411,
          GUID = "7FFD56CE",
          NextDialogue = 51126412,
          SpeakNpcId = 701051,
          Subtitle = "The Bingzhu believed the heavens concealed a calamity great enough to end the world. To withstand it, they refined the art of Stellomancy — reading the stars for omens, seeking a way to avert disaster."
        },
        [51126412] = {
          ContentKR = "그 병촉파에는 북락이란 사람이 있었는데, 북락은 온종일 별, 달, 미래, 허무 같은 데 매달리는 건 따분하다고 여겼어요.",
          DialogueId = 51126412,
          GUID = "7FFD56F8",
          NextDialogue = 51126413,
          SpeakNpcId = 701051,
          Subtitle = "From that very school came a remarkable mind named Beiluo. He found endless stargazing and talk of destiny rather tiresome."
        },
        [51126413] = {
          ContentKR = "오히려 벗들과 거리를 쏘다니는 걸 훨씬 좋아했죠. 그 벗들 중엔 화서 땅을 떠나기 전이었던 구 님도 계셨고요.",
          DialogueId = 51126413,
          GUID = "7FFD5722",
          NextDialogue = 51126414,
          SpeakNpcId = 701051,
          Subtitle = "He preferred wandering the streets with his friends — one of whom was Ju, long before Ju ever left Huaxu."
        },
        [51126414] = {
          ContentKR = "최초의 천성판은 바로 그 두 분이 함께 만드신 거예요. 그 시절엔 제가 가지고 있는 이것처럼 길 안내 기능이 전부였지만, 그땐 그걸로도 충분했답니다.",
          DialogueId = 51126414,
          GUID = "7FFD574C",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "Together they built the first Stellapass — much like this one. It served only for navigation at first, yet even that was a marvel for its time."
        },
        [51126415] = {
          ContentKR = "천성판은 별을 잇는 자들만 가질 수 있는 거예요?",
          DialogueId = 51126415,
          GUID = "7FFD5776",
          NextDialogue = 51126416,
          Subtitle = "So only Starweavers have these devices?"
        },
        [51126416] = {
          ContentKR = "아뇨, 사고 싶다면 얼마든지 살 수 있어요. 그렇지만 천성판을 손에 넣었다고 해도 누구나 쓸 줄 아는 건 아니죠.",
          DialogueId = 51126416,
          GUID = "7FFD57A0",
          NextDialogue = 51126417,
          SpeakNpcId = 701051,
          Subtitle = "One could acquire one easily enough. Yet owning a Stellapass and understanding it are very different matters."
        },
        [51126417] = {
          ContentKR = "자, 제가 천성판을 작동시켜 볼 테니까, 이해가 되는지 보세요.",
          DialogueId = 51126417,
          GUID = "7FFD57CA",
          NextDialogue = 51126418,
          SpeakNpcId = 701051,
          Subtitle = "Observe — I shall set it in motion. See whether its design speaks to you."
        },
        [51126418] = {
          ContentKR = "(남자가 천성판을 손바닥에 올리자, 겹쳐 있던 조각들이 천천히 회전하며, 약간의 간격을 두고 미세하게 떠오른다. 맨 위의 작은 조각까지 돌자 천성판이 움직임을 멈춘다.)",
          DialogueId = 51126418,
          GUID = "7FFD57F4",
          NextDialogue = 51126419,
          Subtitle = "(He sets the Stellapass upon his palm. The interlocking squares lift and turn, layer by layer, until a shard drifts between them and the smallest square atop comes to rest.)"
        },
        [51126419] = {
          ContentKR = "제대로 작동하면 이런 모습이에요. 사용자의 방위에 맞춰 회전하는 각도가 달라지는데, 이걸 보고 방위를 알아내는 법을 배운 건 별을 잇는 자들뿐이죠.",
          DialogueId = 51126419,
          GUID = "7FFD581E",
          NextDialogue = 51126420,
          SpeakNpcId = 701051,
          Subtitle = "There — a clean start. The Stellapass turns as direction shifts. Only trained Starweavers can read those changing angles."
        },
        [51126420] = {
          ContentKR = "이론적으론 배우기만 하면 누구나 쓸 수 있어요. 문제는... 배우기 쉽지 않다는 거지만요.",
          DialogueId = 51126420,
          GUID = "7FFD5848",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "In theory, anyone might learn to do so — but in practice, it's far from easy."
        },
        [51126421] = {
          ContentKR = "천성판에는 어떤 기능들이 있나요?",
          DialogueId = 51126421,
          GUID = "7FFD5872",
          NextDialogue = 51126422,
          Subtitle = "What can a Stellapass do?"
        },
        [51126422] = {
          ContentKR = "최초의 천성판에는 길 안내 기능이 전부였지만, 별을 잇는 자들이 꾸준히 개량한 덕분에 이젠 기능이 몇 가지 추가됐어요.",
          DialogueId = 51126422,
          GUID = "7FFD589C",
          NextDialogue = 51126423,
          SpeakNpcId = 701051,
          Subtitle = "Its earliest use was navigation. Later, the Starweavers refined their craft, adding new functions."
        },
        [51126423] = {
          ContentKR = "날씨 예측 기능 같은 거요. 별의 변화와 흐름을 보고 앞으로의 날씨가 어떨지 예측하는 건데, 굉장히 유용해요. 습기에 취약한 화물을 운송할 때 비라도 내리면 낭패잖아요.",
          DialogueId = 51126423,
          GUID = "7FFD58C6",
          NextDialogue = 51126424,
          SpeakNpcId = 701051,
          Subtitle = "One is the reading of weather — observing how the stars drift to foresee the coming days. Most helpful when your cargo must be kept dry."
        },
        [51126424] = {
          ContentKR = "그리고 운세도 볼 수 있어요. 별을 잇는 자들은 세상의 모든 일이 다 밤하늘의 변화와 관련돼 있다고 믿거든요. 사업, 이사 계획 같은 덴 특히 더요.",
          DialogueId = 51126424,
          GUID = "7FFD58F0",
          NextDialogue = 51126425,
          SpeakNpcId = 701051,
          Subtitle = "Another is divination. The Starweavers hold that the heavens move in rhythm with all things below — especially commerce and travel."
        },
        [51126425] = {
          ContentKR = "그래서 멀리 외출하거나 중요한 결정을 내릴 땐, 별의 기운이 좋은 날을 택해요. 반대로 기운이 썩 좋지 않은 날엔 외출이나 거래를 피하죠.",
          DialogueId = 51126425,
          GUID = "7FFD591A",
          NextDialogue = 51126426,
          SpeakNpcId = 701051,
          Subtitle = "They would choose auspicious star-days for journeys or major ventures, and stay home when the stars foretold misfortune."
        },
        [51126426] = {
          ContentKR = "하지만 기능이 많으면 사용하기가 좀 어렵고, 가장 기본적인 건 역시 길 안내 기능이에요. 간단하고 직관적이라 집집마다 하나씩은 가지고 있죠.",
          DialogueId = 51126426,
          GUID = "7FFD5944",
          NextDialogue = 51126430,
          SpeakNpcId = 701051,
          Subtitle = "Still, the more complex models are difficult to master. Navigation remains the core — simple and direct. Most households keep one for that purpose."
        },
        [51126427] = {
          ContentKR = "이제 궁금증은 다 풀렸어요.",
          DialogueId = 51126427,
          GUID = "7FFD596E",
          NextDialogue = 51126428,
          Subtitle = "That's all I wished to know."
        },
        [51126428] = {
          ContentKR = "별을 잇는 자들은 천성술의 시조인 병촉파에 매년 조금씩 성의 표시를 하고 있어요. 오랫동안 그래 왔죠. 기술 사용료를 내는 셈이랄까요.",
          DialogueId = 51126428,
          GUID = "7FFD5998",
          NextDialogue = 51126429,
          SpeakNpcId = 701051,
          Subtitle = "Even now, the Starweavers make yearly offerings to the Bingzhu Sect — the cradle of Stellomancy. One might say it's their way of paying for the knowledge."
        },
        [51126429] = {
          ContentKR = "기회가 되면 꼭 병촉파에 한번 들러 보세요. 천성술로 또 새로운 뭔가를 발명해 냈을지도 몰라요.",
          DialogueId = 51126429,
          GUID = "7FFD59C2",
          SpeakNpcId = 701051,
          Subtitle = "Should you find the chance, do visit them. You may discover what new insights they have drawn from the stars."
        },
        [51126430] = {
          DialogueId = 51126430,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51126428,
          GUID = "7FFD59EC",
          NextOptions = {
            [1] = 51126409,
            [2] = 51126415,
            [3] = 51126421,
            [4] = 51126427
          }
        },
        [51126501] = {
          ContentKR = "머리를 써서 이해를 해야지, 달달 외워봐야 소용없다니까.",
          DialogueId = 51126501,
          GUID = "7FFD6592",
          NextDialogue = 51126502,
          SpeakNpcId = 701053,
          Subtitle = "Reciting it by rote won't help. Use your head — you must understand it, or it will never stay with you."
        },
        [51126502] = {
          ContentKR = "말이 쉽지, 나처럼 글도 잘 모르는 사람한테 이렇게 빽빽한 상인 수칙을 주면 어떻게 이해해?",
          DialogueId = 51126502,
          GUID = "7FFD65BC",
          NextDialogue = 51126503,
          SpeakNpcId = 701052,
          Subtitle = "Easy for you to say. I can hardly read, and that sheet's packed full of words. I can't make sense of them."
        },
        [51126503] = {
          ContentKR = "별을 잇는 자 상인 수칙이 빽빽하긴 뭐가 빽빽해? 다 해 봐야 겨우 일곱 갠데. 대풍구장도 규율이 아홉 개거든!",
          DialogueId = 51126503,
          GUID = "7FFD65E6",
          NextDialogue = 51126504,
          SpeakNpcId = 701053,
          Subtitle = "Packed? The Starweavers' maxims run to only seven lines. The Nine Chapters of Dafeng have nine!"
        },
        [51126504] = {
          ContentKR = "난 대풍구장도 못 외웠단 말이야...",
          DialogueId = 51126504,
          GUID = "7FFD6610",
          NextOptions = {
            [1] = 51126505,
            [2] = 51126539
          },
          SpeakNpcId = 701052,
          Subtitle = "Well, I've not memorised the Nine Chapters either..."
        },
        [51126505] = {
          ContentKR = "무슨 얘기 중이세요?",
          DialogueId = 51126505,
          GUID = "7FFD663A",
          NextDialogue = 51126506,
          Subtitle = "What are you two talking about?"
        },
        [51126506] = {
          ContentKR = "누구? 아, 외국 사람이구나. 창피한 꼴을 보였네. 이쪽은 이번에 별을 잇는 자가 된 상인이야. 내 친구이기도 해서 상인 수칙을 가르쳐 주고 있었어.",
          DialogueId = 51126506,
          GUID = "7FFD6664",
          NextDialogue = 51126507,
          SpeakNpcId = 701053,
          Subtitle = "Ah, you're a traveller, aren't you? Pardon the scene. My friend here's just joined the Starweavers — I'm teaching him our trade maxims."
        },
        [51126507] = {
          ContentKR = "으, 신청할 때 물어본다니까 외우는 거지, 아니면 쳐다도 안 봤어. 장사꾼이 됨됨이만 바르면 됐지, 이런 복잡한 걸 왜...",
          DialogueId = 51126507,
          GUID = "7FFD668E",
          NextDialogue = 51126508,
          SpeakNpcId = 701052,
          Subtitle = "If they hadn't asked about them when we joined, I'd never have learnt a word. I trade fair and square — that should be proof enough, without all this fuss."
        },
        [51126508] = {
          ContentKR = "됐으니까, 빨리 외우기나 해!",
          DialogueId = 51126508,
          GUID = "7FFD66B8",
          NextOptions = {
            [1] = 51126509
          },
          SpeakNpcId = 701053,
          Subtitle = "Enough talk. Recite!"
        },
        [51126509] = {
          ContentKR = "별을 잇는 자 상인 수칙이 뭐예요? 저도 궁금해서요.",
          DialogueId = 51126509,
          GUID = "7FFD66E2",
          NextDialogue = 51126510,
          Subtitle = "I'm curious about the maxims as well — what are they, exactly?"
        },
        [51126510] = {
          ContentKR = "외국 사람인데 이런 게 궁금해? 하긴, 한 명한테 설명하나 두 명한테 설명하나 마찬가지니까, 같이 알려 줄게.",
          DialogueId = 51126510,
          GUID = "7FFD670C",
          NextDialogue = 51126511,
          SpeakNpcId = 701053,
          Subtitle = "You are? Very well then — one more listener won't hurt. You can both listen in."
        },
        [51126511] = {
          ContentKR = "별을 잇는 자 상인 수칙은 총 7조로 되어 있어.",
          DialogueId = 51126511,
          GUID = "7FFD6736",
          NextDialogue = 51126512,
          SpeakNpcId = 701053,
          Subtitle = "There are seven in all. They go as follows:"
        },
        [51126512] = {
          ContentKR = "이익보다 상도가 먼저다.",
          DialogueId = 51126512,
          GUID = "7FFD6760",
          NextDialogue = 51126513,
          SpeakNpcId = 701053,
          Subtitle = "Count not profit but righteousness as honour;"
        },
        [51126513] = {
          ContentKR = "사치가 아닌 덕망을 중시하라",
          DialogueId = 51126513,
          GUID = "7FFD678A",
          NextDialogue = 51126514,
          SpeakNpcId = 701053,
          Subtitle = "Count not splendour but virtue as nobility;"
        },
        [51126514] = {
          ContentKR = "가격보다 품질을 우선하라.",
          DialogueId = 51126514,
          GUID = "7FFD67B4",
          NextDialogue = 51126515,
          SpeakNpcId = 701053,
          Subtitle = "Count not cheapness but quality as value;"
        },
        [51126515] = {
          ContentKR = "잔꾀 대신 성실함을 무기로 삼아라.",
          DialogueId = 51126515,
          GUID = "7FFD67DE",
          NextDialogue = 51126516,
          SpeakNpcId = 701053,
          Subtitle = "Count not cunning but honesty as skill;"
        },
        [51126516] = {
          ContentKR = "희귀함보다 쓸모를 살펴라.",
          DialogueId = 51126516,
          GUID = "7FFD6808",
          NextDialogue = 51126517,
          SpeakNpcId = 701053,
          Subtitle = "Count not rarity but fitness as treasure;"
        },
        [51126517] = {
          ContentKR = "축재가 아닌 상생을 도모하라.",
          DialogueId = 51126517,
          GUID = "7FFD6832",
          NextDialogue = 51126518,
          SpeakNpcId = 701053,
          Subtitle = "Count not hoarding but kindness as wealth;"
        },
        [51126518] = {
          ContentKR = "말보다 실제를 앞세워라.",
          DialogueId = 51126518,
          GUID = "7FFD685C",
          NextDialogue = 51126519,
          SpeakNpcId = 701053,
          Subtitle = "Count not rhetoric but truth as measure."
        },
        [51126519] = {
          ContentKR = "오오, 백룡신군이시여! 어떻게 그걸 한 글자도 안 틀리고 다 외웠어? 설마 종이 너머 글자를 보는 초능력이라도 있는 거야?",
          DialogueId = 51126519,
          GUID = "7FFD6886",
          NextDialogue = 51126520,
          SpeakNpcId = 701052,
          Subtitle = "By Lord Argent — how did you remember every word? You've got second sight, seeing the text clear through the page?"
        },
        [51126520] = {
          ContentKR = "모두가 다 너처럼 멍청하진 않거든! 외국 친구, 혹시 이해 안 되는 부분 있어? 내가 설명해 줄게.",
          DialogueId = 51126520,
          GUID = "7FFD68B0",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "Not everyone's as slow as you! Traveller, was there any line you didn't quite catch? I can explain it if you wish."
        },
        [51126521] = {
          ContentKR = "\"이익보다 상도가 먼저다.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126521,
          GUID = "7FFD68DA",
          NextDialogue = 51126522,
          Subtitle = "About \"Count not profit but righteousness as honour.\" I'm not quite sure what that means."
        },
        [51126522] = {
          ContentKR = "그건 말이지, 돈을 많이 벌어 이익을 남기는 것보다 상도를 지키는 게 더 중요하다는 거야. 백년춘 증축에 기부하는 상인이 많은 것도 다 그래서지.",
          DialogueId = 51126522,
          GUID = "7FFD6904",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means a merchant should take pride not in how much he earns, but in how fairly he trades. That's why so many support the common good and help EverSpring prosper."
        },
        [51126523] = {
          ContentKR = "\"사치가 아닌 덕망을 중시하라.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126523,
          GUID = "7FFD692E",
          NextDialogue = 51126524,
          Subtitle = "About \"Count not splendour but virtue as nobility.\" I'm not quite sure what that means."
        },
        [51126524] = {
          ContentKR = "그건 말이지, 돈 좀 벌었다고 거들먹거리지 말고, 사람 됨됨이부터 갖추란 소리야. 뛰는 놈 위엔 나는 놈 있기 마련이니까.",
          DialogueId = 51126524,
          GUID = "7FFD6958",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means one shouldn't set oneself above others for wealth or finery. Mind your conduct instead — there's always someone richer, after all."
        },
        [51126525] = {
          ContentKR = "\"가격보다 품질을 우선하라.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126525,
          GUID = "7FFD6982",
          NextDialogue = 51126526,
          Subtitle = "About \"Count not cheapness but quality as value.\" I'm not quite sure what that means."
        },
        [51126526] = {
          ContentKR = "그건 말이지, 무조건 싸게 팔려고만 하지 말고, 물건의 품질에 더 신경 쓰란 소리야. 아니면 나중에 큰 문제가 생길 수도 있거든.",
          DialogueId = 51126526,
          GUID = "7FFD69AC",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means a merchant shouldn't chase low prices alone — he must mind the make of his goods. Cut corners on quality, and ruin soon follows."
        },
        [51126527] = {
          ContentKR = "\"잔꾀 대신 성실함을 무기로 삼아라.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126527,
          GUID = "7FFD69D6",
          NextDialogue = 51126528,
          Subtitle = "About \"Count not cunning but honesty as skill.\" I'm not quite sure what that means."
        },
        [51126528] = {
          ContentKR = "그건 말이지, 잔머리 써서 이득 봤다고 그걸 '비법'이라고 착각하지 말고, 신용을 지키란 소리야. 진정한 비법은 평판이 좋아져서 손님이 저절로 찾아오는 거니까.",
          DialogueId = 51126528,
          GUID = "7FFD6A00",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means never mistake trickery for wit. Keep your word — a good name brings good trade. That's the true craft of a merchant."
        },
        [51126529] = {
          ContentKR = "\"희귀함보다 쓸모를 살펴라.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126529,
          GUID = "7FFD6A2A",
          NextDialogue = 51126530,
          Subtitle = "About \"Count not rarity but fitness as treasure.\" I'm not quite sure what that means."
        },
        [51126530] = {
          ContentKR = "그건 말이지, 희귀한 물건이라고 무작정 사고팔 게 아니라, 시장 수요부터 살피란 소리야. 사재기해서 비싼 값에 파는 짓은 더더욱 안 될 말이고.",
          DialogueId = 51126530,
          GUID = "7FFD6A54",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means rarity's no excuse for greed. Judge worth by need, not by price, and never hoard to twist the market — that way lies ruin, not fortune."
        },
        [51126531] = {
          ContentKR = "\"축재가 아닌 상생을 도모하라.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126531,
          GUID = "7FFD6A7E",
          NextDialogue = 51126532,
          Subtitle = "About \"Count not hoarding but kindness as wealth.\" I'm not quite sure what that means."
        },
        [51126532] = {
          ContentKR = "그건 말이지, 자기 주머니 채울 생각만 하지 말고, 어진 마음으로 재물을 올바른 곳에 쓸 줄 알아야 한다는 소리야.",
          DialogueId = 51126532,
          GUID = "7FFD6AA8",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means don't stash every coin in your own pouch. Keep kindness in mind and put your silver to good use — that's true wealth."
        },
        [51126533] = {
          ContentKR = "\"말보다 실제를 앞세워라.\"가 무슨 말인지 잘 모르겠어요.",
          DialogueId = 51126533,
          GUID = "7FFD6AD2",
          NextDialogue = 51126534,
          Subtitle = "About \"Count not rhetoric but truth as measure.\" I'm not quite sure what that means."
        },
        [51126534] = {
          ContentKR = "그건 말이지, 상인의 약속은 꼭 지켜야 한다는 거야. 특히 거래를 할 땐 말을 바꾸거나, 허풍을 떨거나, 값을 부풀리지 말고 약속한 사실 그대로 하란 소리지.",
          DialogueId = 51126534,
          GUID = "7FFD6AFC",
          NextDialogue = 51126542,
          SpeakNpcId = 701053,
          Subtitle = "It means a merchant must keep his word — above all in trade — and deal by the facts. No backtracking, no bluster, no price games to deceive. That's what marks a trader of honour."
        },
        [51126535] = {
          ContentKR = "이젠 다 알겠어요.",
          DialogueId = 51126535,
          GUID = "7FFD6B26",
          NextDialogue = 51126536,
          Subtitle = "All clear now."
        },
        [51126536] = {
          ContentKR = "어떻게 된 게 외국인이 너보다 더 잘 이해하냐!",
          DialogueId = 51126536,
          GUID = "7FFD6B50",
          NextDialogue = 51126537,
          SpeakNpcId = 701053,
          Subtitle = "See? The traveller's quicker on the uptake than you are."
        },
        [51126537] = {
          ContentKR = "아니... 공부 머리가 안 돼서 장사판에 뛰어든 건데, 나보고 어떻게 외우란 거야. 친구야, 우린 어릴 때부터 빤스도 같이 입던 사이잖아! 너 내 스타일 몰라?",
          DialogueId = 51126537,
          GUID = "7FFD6B7A",
          NextDialogue = 51126538,
          SpeakNpcId = 701052,
          Subtitle = "Hey now... I only took up trade 'cause books beat me. Why must I learn all this by heart? Qiaofeng, you know me — we've been thick as thieves since we were kids!"
        },
        [51126538] = {
          ContentKR = "야! 누가 너랑 빤스를 같이 입어! 자꾸 이상한 소리 할래!",
          DialogueId = 51126538,
          GUID = "7FFD6BA4",
          SpeakNpcId = 701053,
          Subtitle = "Oi! Thick as thieves, my foot!"
        },
        [51126539] = {
          ContentKR = "전 신경 쓰지 마세요.",
          DialogueId = 51126539,
          GUID = "7FFD6BCE",
          NextDialogue = 51126540,
          Subtitle = "Nothing."
        },
        [51126540] = {
          ContentKR = "복룡, 어딜 도망가! 얼른 와서 마저 외워!",
          DialogueId = 51126540,
          GUID = "7FFD6BF8",
          NextDialogue = 51126541,
          SpeakNpcId = 701053,
          Subtitle = "Fulong, where do you think you're going? Back here! Keep reciting!"
        },
        [51126541] = {
          ContentKR = "죽어도 싫어!!!!!",
          DialogueId = 51126541,
          GUID = "7FFD6C22",
          SpeakNpcId = 701052,
          Subtitle = "Nooooooo!!"
        },
        [51126542] = {
          DialogueId = 51126542,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 51126540,
          GUID = "7FFD6C4C",
          NextOptions = {
            [1] = 51126521,
            [2] = 51126523,
            [3] = 51126525,
            [4] = 51126527,
            [5] = 51126529,
            [6] = 51126531,
            [7] = 51126533,
            [8] = 51126535
          }
        },
        [51126601] = {
