          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill03"
        },
        [60140207] = {
          ContentKR = "...어서... 도망가...!",
          DialogueId = 60140207,
          Duration = 4,
          GUID = "968E00B6",
          Subtitle = "...Run... please...!",
          VoiceName = "sfx/boss/Saiqi/vo_$Locale$_skill10"
        },
        [60140401] = {
          ContentKR = "세상에서 가장 사랑하는 아가, 이 세상에 태어나줘서 고마워. ",
          DialogueId = 60140401,
          Duration = 4,
          GUID = "968E208A",
          Subtitle = "My dearest child, thank you for coming into the world.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E208A"
        },
        [60140402] = {
          ContentKR = "넌 우리 인생 최고의 자랑이란다. ",
          DialogueId = 60140402,
          Duration = 3,
          GUID = "968E20B4",
          Subtitle = "You are the pride of our lives.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20B4"
        },
        [60140403] = {
          ContentKR = "프시케, 자, 약속! 이제 우리는 영원한 친구야!",
          DialogueId = 60140403,
          Duration = 4,
          GUID = "968E20DE",
          Subtitle = "Psyche, pinky promise. We'll be best friends for life!",
          VoiceName = "voice/$Locale$/story/1002/101125/968E20DE"
        },
        [60140404] = {
          ContentKR = "네가 살아있었음을 기억할게. ",
          DialogueId = 60140404,
          Duration = 3,
          GUID = "968E2108",
          Subtitle = "I'll remember that you've lived in this world.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2108"
        },
        [60140405] = {
          ContentKR = "우리가 널 기다리고 있어. ",
          DialogueId = 60140405,
          Duration = 2.5,
          GUID = "968E2132",
          Subtitle = "We'll wait for your return.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2132"
        },
        [60140406] = {
          ContentKR = "운명이여, 한 번이라도 자비를 베풀어 그 아이의 소원을 이뤄줄 수 있게 해 주오. ",
          DialogueId = 60140406,
          Duration = 6,
          GUID = "968E215C",
          Subtitle = "Fate, please have mercy on me. Let me help her fulfil this wish.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E215C"
        },
        [60140407] = {
          ContentKR = "이 꽃을 가져가렴, 행운을 가져다줄 거야. ",
          DialogueId = 60140407,
          Duration = 3,
          GUID = "968E2186",
          Subtitle = "Take this flower with you. It will bring you good luck.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E2186"
        },
        [60140408] = {
          ContentKR = "작은 섬에 가면 집 몇 채를 짓고, 집 주변에 하얀 꽃을 가득 심을 수 있어. ",
          DialogueId = 60140408,
          Duration = 6,
          GUID = "968E21B0",
          Subtitle = "You'll go to a small island, where you can build a house by the sea and grow white flowers around it.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21B0"
        },
        [60140409] = {
          ContentKR = "프시케, 집에 가자.",
          DialogueId = 60140409,
          Duration = 3,
          GUID = "968E21DA",
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/101125/968E21DA"
        },
        [60140501] = {
          ContentKR = "심판은 곧 정의다.",
          DialogueId = 60140501,
          Duration = 5,
          GUID = "968E30F2",
          Subtitle = "All verdicts are in the name of justice.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleStart"
        },
        [60140502] = {
          ContentKR = "감히 법에 맞서다니...",
          DialogueId = 60140502,
          Duration = 5,
          GUID = "968E311C",
          Subtitle = "How dare you defy the law...",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_condemn"
        },
        [60140503] = {
          ContentKR = "넌... 맹렬한 불 앞에서 자신을 증명했다.",
          DialogueId = 60140503,
          Duration = 5,
          GUID = "968E3146",
          Subtitle = "You... have proved yourself in the face of fiery flame.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_battleEnd"
        },
        [60140504] = {
          ContentKR = "마지막 변명을 시작해 봐라.",
          DialogueId = 60140504,
          Duration = 5,
          GUID = "968E3170",
          Subtitle = "Present your final pleas.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_01"
        },
        [60140505] = {
          ContentKR = "추하게 발버둥 쳐봐라.",
          DialogueId = 60140505,
          Duration = 5,
          GUID = "968E319A",
          Subtitle = "Writhing pathetically won't delay your sentence.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill06_02"
        },
        [60140506] = {
          ContentKR = "족쇄 속에서 죽음을 맞이해라.",
          DialogueId = 60140506,
          Duration = 5,
          GUID = "968E31C4",
          Subtitle = "Meet your demise within these chains.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_01"
        },
        [60140507] = {
          ContentKR = "법이 너의 죄상을 낱낱이 밝혀낼 것이다.",
          DialogueId = 60140507,
          Duration = 5,
          GUID = "968E31EE",
          Subtitle = "The law shall recount your crimes.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill08_02"
        },
        [60140508] = {
          ContentKR = "불의 감옥에서 도망칠 생각은 마라.",
          DialogueId = 60140508,
          Duration = 5,
          GUID = "968E3218",
          Subtitle = "No escape from the inferno's grasp.",
          VoiceName = "sfx/boss/Lianhuo/vo_$Locale$_skill03"
        },
        [60149001] = {
          ContentKR = "가가가가가진 것 다 내놔! 윽... 만만치 않은 녀석 같은데... 도, 도망가야겠다.",
          DialogueId = 60149001,
          Duration = 5,
          GUID = "9693A37A",
          SpeakNpcId = 920001,
          Subtitle = "H...H...H...H...Hands in the air! Ooh, this one looks tough... I'm outta here.",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r01"
        },
        [60149002] = {
          ContentKR = "악! 왜 또 너야. 다다, 다음에 보자고.",
          DialogueId = 60149002,
          Duration = 3.8,
          GUID = "9693A3A4",
          SpeakNpcId = 920001,
          Subtitle = "Argh, not you again! H...H...H...Have a nice day, bye!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r02"
        },
        [60149003] = {
          ContentKR = "지, 지나가려면 통행료를 내놔! 칫, 오늘은 왜 이렇게 강한 녀석만 나오는 거야. 그럼 이만.",
          DialogueId = 60149003,
          Duration = 6.7,
          GUID = "9693A3CE",
          SpeakNpcId = 920001,
          Subtitle = "Y...Y...Your money or your life...! Gosh! How am I supposed to mug a walkin' arsenal? See ya!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_birth_r03"
        },
        [60149004] = {
          ContentKR = "통행료 받기 말고 도망가기도 내 전문이라고!",
          DialogueId = 60149004,
          Duration = 3.5,
          GUID = "9693A3F8",
          SpeakNpcId = 920001,
          Subtitle = "Tell you what, I also major in escapin'!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill01"
        },
        [60149005] = {
          ContentKR = "보물 같은 건 없다니까! 자 이거 다 줄 테니까 그만 쫓아와!",
          DialogueId = 60149005,
          Duration = 5.1,
          GUID = "9693A422",
          SpeakNpcId = 920001,
          Subtitle = "Luno who mugs and runs away, lives to mug another day! Just take these and lemme scarper!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill02"
        },
        [60149006] = {
          ContentKR = "왜 자꾸 쫓아오는 거야?! 여, 여기 주면 됐지?",
          DialogueId = 60149006,
          Duration = 3.5,
          GUID = "9693A44C",
          SpeakNpcId = 920001,
          Subtitle = "Ugh, just take that and lemme off the hook!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill03"
        },
        [60149007] = {
          ContentKR = "왜 그, 그렇게 세게 때리는 거야!",
          DialogueId = 60149007,
          Duration = 2.5,
          GUID = "9693A476",
          SpeakNpcId = 920001,
          Subtitle = "Oww! That hurt!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r01"
        },
        [60149008] = {
          ContentKR = "젠장, 앞으로 밤, 밤길 조심하라고!",
          DialogueId = 60149008,
          Duration = 3.2,
          GUID = "9693A4A0",
          SpeakNpcId = 920001,
          Subtitle = "Ugh, this is not over! Better watch your back at night!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r02"
        },
        [60149009] = {
          ContentKR = "으아아아아앗! 나 화, 화, 화낸다!",
          DialogueId = 60149009,
          Duration = 3.4,
          GUID = "9693A4CA",
          SpeakNpcId = 920001,
          Subtitle = "RAAAARGH!! Now I'm mad!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_be_hit_heavy_r03"
        },
        [60149010] = {
          ContentKR = "바, 바, 바보, 못 잡겠지? 키키키킥~",
          DialogueId = 60149010,
          Duration = 6,
          GUID = "9693A4F4",
          SpeakNpcId = 920001,
          Subtitle = "You ju...ju...jumbo dumbo are too stupid to catch me! HYA-HYA-HYA!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Skill04"
        },
        [60149011] = {
          ContentKR = "이번엔 너무 방, 방심했네. 다음엔 네가 각, 가오하라고. 흑...",
          DialogueId = 60149011,
          Duration = 10.4,
          GUID = "9693A51E",
          SpeakNpcId = 920001,
          Subtitle = "I've mucked it all up! You'll get yours next time — just you wait! Boohoo...",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_death"
        },
        [60149012] = {
          ContentKR = "길에서 아무나 붙잡고 물어봐! 이 강도 루나 님의 명성을 모르는 사람이 있을 것 같아!",
          DialogueId = 60149012,
          Duration = 6.9,
          GUID = "9693A548",
          SpeakNpcId = 920001,
          Subtitle = "North, south, east and west! I'm your pappy and I'm da best! Ask around and you will know, give your money to this Luno!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r01"
        },
        [60149013] = {
          ContentKR = "내 상대가 되려면 넌 아직 한~~참 멀었다고~",
          DialogueId = 60149013,
          Duration = 5.7,
          GUID = "9693A572",
          SpeakNpcId = 920001,
          Subtitle = "Hah, tenderfoot! You're gettin' pawned!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r02"
        },
        [60149014] = {
          ContentKR = "흥~ 이 강, 강도 루나 님을 만만하게 본 건 아니겠지.",
          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          Subtitle = "Hmph, this Lulu Lunoloot is not someone you can mess with!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
          ContentKR = "헥헥... 뭘 먹고 자랐길래 아직도 팔팔한 거야.",
          DialogueId = 60149015,
          Duration = 8.8,
          GUID = "9693A5C6",
          SpeakNpcId = 920001,
          Subtitle = "Huff... huff... Ain't you tired yet? What did they feed you?",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r04"
        },
        [60150001] = {
          ContentKR = "저리 꺼져!",
          DialogueId = 60150001,
          Duration = 3,
          GUID = "9694478A",
          SpeakNpcId = 200053,
          Subtitle = "Back off!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack01"
        },
        [60150002] = {
          ContentKR = "고통을 맛보고 싶다면 원하는 대로 해주지!",
          DialogueId = 60150002,
          Duration = 3,
          GUID = "969447B4",
          SpeakNpcId = 200053,
          Subtitle = "You asked for this!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Attack02"
        },
        [60150003] = {
          ContentKR = "더는 못 뛰겠어... 항복할게...",
          DialogueId = 60150003,
          Duration = 5,
          GUID = "969447DE",
          SpeakNpcId = 200053,
          Subtitle = "I can't run any further... I surrender...",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Die"
        },
        [60150004] = {
          ContentKR = "힘 좀 쓴다고 으스대지 마!",
          DialogueId = 60150004,
          Duration = 3,
          GUID = "96944808",
          SpeakNpcId = 200053,
          Subtitle = "Give it up!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill01"
        },
        [60150005] = {
          ContentKR = "그만 쫓아오라고!",
          DialogueId = 60150005,
          Duration = 3,
          GUID = "96944832",
          SpeakNpcId = 200053,
          Subtitle = "Quit it!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill02"
        },
        [60150006] = {
          ContentKR = "날 따라잡을 순 없을 거다!",
          DialogueId = 60150006,
          Duration = 4,
          GUID = "9694485C",
          SpeakNpcId = 200053,
          Subtitle = "No way you can catch me!",
          VoiceName = "sfx/enemy/Mn/Haer/vo_$Locale$_Skill03"
        },
        [60160001] = {
          Content = "开启锯轮攻击！（待包装）",
          DialogueId = 60160001,
          Duration = 4,
          GUID = "969AB02A",
          SpeakNpcId = 920001
        },
        [60160002] = {
          Content = "持续轰炸目标！（待包装）",
          DialogueId = 60160002,
          Duration = 4,
          GUID = "969AB054",
          SpeakNpcId = 920001
        },
        [60160003] = {
          Content = "列车，提速，狂暴模式！！（待包装）",
          DialogueId = 60160003,
          Duration = 4,
          GUID = "969AB07E",
          SpeakNpcId = 920001
        },
        [60160004] = {
          Content = "连锁型-炸弹攻击！（待包装）",
          DialogueId = 60160004,
          Duration = 4,
          GUID = "969AB0A8",
          SpeakNpcId = 920001
        },
        [60160005] = {
          Content = "追踪型-炸弹攻击！（待包装）",
          DialogueId = 60160005,
          Duration = 4,
          GUID = "969AB0D2",
          SpeakNpcId = 920001
        },
        [60170001] = {
          ContentKR = "죽어... 죽어!",
          DialogueId = 60170001,
          Duration = 1.5,
          GUID = "96A118CA",
          Subtitle = "Die... DIIIEEE!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_BattleStart01"
        },
        [60170002] = {
          ContentKR = "크아... 윽... 아아아아...",
          DialogueId = 60170002,
          Duration = 1.5,
          GUID = "96A118F4",
          Subtitle = "Raaagh... Ughhh... AAAARRRGH!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill06"
        },
        [60170003] = {
          ContentKR = "캬오오오... 크아... 크아!!",
          DialogueId = 60170003,
          Duration = 4,
          GUID = "96A1191E",
          Subtitle = "GRRRRR... Roar... ROOOAAAR!",
          VoiceName = "sfx/boss/Tuosi/vo_$Locale$_Skill08"
        },
        [60180001] = {
          Content = "近吾者，必罹天劫！",
          DialogueId = 60180001,
          Duration = 3,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleStart"
        },
        [60180002] = {
          Content = "吼————",
          DialogueId = 60180002,
          Duration = 3,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Condemn"
        },
        [60180003] = {
          Content = "俱往矣……",
          DialogueId = 60180003,
          Duration = 3,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_BattleEnd"
        },
        [60180004] = {
          Content = "晦暝临世。",
          DialogueId = 60180004,
          Duration = 4,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill05"
        },
        [60180005] = {
          Content = "吼————",
          DialogueId = 60180005,
          Duration = 5,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill06"
        },
        [60180006] = {
          Content = "曀曀其阴，虺虺其雷——",
          DialogueId = 60180006,
          Duration = 3,
          VoiceName = "sfx/boss/Heilong/vo_$Locale$_Skill07"
        },
        [60200101] = {
          ContentKR = "이런, 적에게 들켰어!",
          DialogueId = 60200101,
          Duration = 4,
          GUID = "96B46312",
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh, we've been spotted by the enemy!",
          VoiceName = "voice/$Locale$/story/0/602001/96B46312",
          bTurnOffVoice = true
        },
        [60200201] = {
          ContentKR = "적을 발견했어. 녀석들이 동료를 부르기 전에 적을 막아야 해.",
          DialogueId = 60200201,
          Duration = 4,
          GUID = "96B4737A",
          SpeakNpcId = 200002,
          Subtitle = "Enemies in sight; stop them before they call for backup.",
          VoiceName = "voice/$Locale$/story/0/602002/96B4737A",
          bTurnOffVoice = true
        },
        [60200301] = {
          ContentKR = "조심해, 적이 동료를 부르러 갈 거야! 이대로라면 골치 아프겠어.",
          DialogueId = 60200301,
          Duration = 4,
          GUID = "96B483E2",
          SpeakNpcId = 200002,
          Subtitle = "Watch out, the enemy's about to call for backup! Things will get sticky if we don't nip this in the bud.",
          VoiceName = "voice/$Locale$/story/0/602003/96B483E2",
          bTurnOffVoice = true
        },
        [60200401] = {
          ContentKR = "그들이 동료를 부르러 갔어. 얼른 막을 방법을 생각해야 해!",
          DialogueId = 60200401,
          Duration = 4,
          GUID = "96B4944A",
          SpeakNpcId = 200002,
          Subtitle = "They're going to call for backup! Do something! Now!",
          VoiceName = "voice/$Locale$/story/0/602004/96B4944A",
          bTurnOffVoice = true
        },
        [60200501] = {
          ContentKR = "나 참, 이렇게 잘 숨어 있었는데 들켜버리다니... 어쩔 수 없지. 얼른 처치해 버리자.",
          DialogueId = 60200501,
          Duration = 4,
          GUID = "96B4A4B2",
          SpeakNpcId = 200002,
          Subtitle = "Ugh, thought we hid well. Eh, let's sort them out quickly.",
          VoiceName = "voice/$Locale$/story/0/602005/96B4A4B2",
          bTurnOffVoice = true
        },
        [60210101] = {
          ContentKR = "의뢰인이 벌어준 시간은 얼마 없어. 빨리빨리 저 이상한 장치 세 대를 처리하자!",
          DialogueId = 60210101,
          Duration = 4,
          GUID = "9687C88C",
          SpeakNpcId = 200002,
          Subtitle = "The client's only bought us a teeny bit of time — so let's bust those weird-looking thingies before it's too late!",
          VoiceName = "voice/$Locale$/story/0/602101/9687C88C",
          bTurnOffVoice = true
        },
        [60210201] = {
          ContentKR = "야호! 다 처리했어! 의뢰 임무 완벽하게 끝냈어!",
          DialogueId = 60210201,
          Duration = 3,
          GUID = "9687C892",
          SpeakNpcId = 200002,
          Subtitle = "Yay! All down! Commission accomplished~!",
          VoiceName = "voice/$Locale$/story/0/602102/9687C892",
          bTurnOffVoice = true
        },
        [60210301] = {
          ContentKR = "의뢰인이 시간이 얼마 없다고 해. 우리도 서둘러 빠져나가자!",
          DialogueId = 60210301,
          Duration = 3,
          GUID = "9687C896",
          SpeakNpcId = 200002,
          Subtitle = "The client says time's up! Let's get out of here before it gets messy!",
          VoiceName = "voice/$Locale$/story/0/602103/9687C896",
          bTurnOffVoice = true
        },
        [60220101] = {
          ContentKR = "뭐야 뭐야, 1 라운드가 벌써 시작된 거야?",
          DialogueId = 60220101,
          Duration = 4,
          GUID = "9687C89A",
          NextDialogue = 60220102,
          SpeakNpcId = 200002,
          Subtitle = "Wait, what, the first match is starting already?",
          VoiceName = "voice/$Locale$/story/0/602201/9687C89A",
          bTurnOffVoice = true
        },
        [60220102] = {
          ContentKR = "어디 보자... 우리가 1 라운드에서 할 일은 '포세이돈 동맹'이라는 팀의 시드 선수를 탈락시키는 거야!",
          DialogueId = 60220102,
          Duration = 3,
          GUID = "9687C89E",
          NextDialogue = 60220103,
          SpeakNpcId = 200002,
          Subtitle = "Let me see… Our first task is to eliminate the star player of the \"The Fork Shakens\" team!",
          VoiceName = "voice/$Locale$/story/0/602201/9687C89E",
          bTurnOffVoice = true
        },
        [60220103] = {
          ContentKR = "근데 우린 다른 사람들이 어디 숨어 있는지 모르잖아! 일단 주변에서 단서를 찾아보자.",
          DialogueId = 60220103,
          Duration = 3,
          GUID = "9687C8A2",
          SpeakNpcId = 200002,
          Subtitle = "But we've no idea where the others are hiding! Let's look around for clues.",
          VoiceName = "voice/$Locale$/story/0/602201/9687C8A2",
          bTurnOffVoice = true
        },
        [60220201] = {
          ContentKR = "시드 선수가 어디 숨어 있는지 알았어! 가서 혼내주... 아니, 탈락시키자!",
          DialogueId = 60220201,
          Duration = 3,
          GUID = "9687C8A6",
          SpeakNpcId = 200002,
          Subtitle = "We know where their star player is hiding! Let's go defeat — oops, I mean eliminate them!",
          VoiceName = "voice/$Locale$/story/0/602202/9687C8A6",
          bTurnOffVoice = true
        },
        [60220301] = {
          ContentKR = "다음은 땅따먹기 시합인가 본데? 얼른 가보자.",
          DialogueId = 60220301,
          Duration = 3,
          GUID = "9687C8AA",
          SpeakNpcId = 200002,
          Subtitle = "The next round seems to be a territory battle! Let's hurry over!",
          VoiceName = "voice/$Locale$/story/0/602203/9687C8AA",
          bTurnOffVoice = true
        },
        [60220401] = {
          ContentKR = "녀석들을 우리 구역에서 쫓아내라! 이번 시합은 꼭 우리 '천하제일 군단장'에서 승리해야 한다.",
          DialogueId = 60220401,
          Duration = 4,
          GUID = "9687C8AE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Drive them out of the designated zone! Victory will surely belong to us, \"Chief's the Best\"!",
          VoiceName = "voice/$Locale$/story/0/602204/9687C8AE",
          bTurnOffVoice = true
        },
        [60220501] = {
          ContentKR = "군단의 명예는 너희에게 달렸다!",
          DialogueId = 60220501,
          Duration = 4,
          GUID = "9687C8B2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "The pride of the legion rests on you.",
          VoiceName = "voice/$Locale$/story/0/602205/9687C8B2",
          bTurnOffVoice = true
        },
        [60220601] = {
          ContentKR = "젠장, 생각보다 끈질기군. 어쩔 수 없이 진짜 실력을 보여줘야겠구나.",
          DialogueId = 60220601,
          Duration = 4,
          GUID = "9687C8B6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Ugh, they're so stubborn! Guess it's time to get serious.",
          VoiceName = "voice/$Locale$/story/0/602206/9687C8B6",
          bTurnOffVoice = true
        },
        [60220701] = {
          ContentKR = "져버리다니... 하지만 다음 시합에선 아직 기회가 있다!",
          DialogueId = 60220701,
          Duration = 3,
          GUID = "9687C8BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "Even though we lost… there's still next round! We still have a chance!",
          VoiceName = "voice/$Locale$/story/0/602207/9687C8BA",
          bTurnOffVoice = true
        },
        [60220801] = {
          ContentKR = "드디어 3 라운드야. 얼른 보물 상자로 가자, 절대 다른 사람한테 빼앗기면 안 돼!",
          DialogueId = 60220801,
          Duration = 4,
          GUID = "9687C8BE",
          SpeakNpcId = 200002,
          Subtitle = "Finally, the third match! Quick, to the prize chest, we can't let anyone else grab it!",
          VoiceName = "voice/$Locale$/story/0/602208/9687C8BE",
          bTurnOffVoice = true
        },
        [60220901] = {
          ContentKR = "자, 시작됐어! 저 녀석들한테서 열쇠를 빼앗아서, 마지막 보물 상자를 열어야 해.",
          DialogueId = 60220901,
          Duration = 3,
          GUID = "9687C8C2",
          NextDialogue = 60220902,
          SpeakNpcId = 200002,
          Subtitle = "It's starting now! Snatch the keys back from these guys and unlock the final treasure chest!",
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C2",
          bTurnOffVoice = true
        },
        [60220902] = {
          ContentKR = "이교도 놈들, 감히 신이 내린 보물에 손대려 하다니! 신의 노여움을 감당할 수 있겠느냐!",
          DialogueId = 60220902,
          Duration = 4,
          GUID = "9687C8C4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          Subtitle = "Heretics! How dare you covet treasures bestowed by the gods. Ready to face divine wrath?",
          VoiceName = "voice/$Locale$/story/0/602209/9687C8C4",
          bTurnOffVoice = true
        },
        [60221001] = {
          ContentKR = "가자, 가장 경건한 신도들이여! 신에게 바칠 승리의 열매를 위하여!",
          DialogueId = 60221001,
          Duration = 4,
          GUID = "9687C8C6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930003,
          Subtitle = "Go, devout followers! Pluck the fruit of victory in Its name.",
          VoiceName = "voice/$Locale$/story/0/602210/9687C8C6",
          bTurnOffVoice = true
        },
        [60221101] = {
          ContentKR = "군단의 영광을 위하여, 전진하라!",
          DialogueId = 60221101,
          Duration = 4,
          GUID = "9687C8CA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930002,
          Subtitle = "For the glory of the legion, advance!",
          VoiceName = "voice/$Locale$/story/0/602211/9687C8CA",
          bTurnOffVoice = true
        },
        [60221201] = {
          ContentKR = "생각했던 대로, 역시 3라운드가 가장 중요하군. 이제 우리 실력을 제대로 보여주자.",
          DialogueId = 60221201,
          Duration = 4,
          GUID = "9687C8CE",
          SpeakNpcId = 930004,
          Subtitle = "Just as I predicted — the third match is where it really counts. Now, it's our time to shine!",
          VoiceName = "voice/$Locale$/story/0/602212/9687C8CE",
          bTurnOffVoice = true
        },
        [60221301] = {
          ContentKR = "첫 번째 잠금장치를 열었어. 힘내서 나머지 것들도 계속 열어 보자!",
          DialogueId = 60221301,
          Duration = 3,
          GUID = "9687C8D2",
          SpeakNpcId = 200002,
          Subtitle = "One lock opened! Keep it up, we can get the rest too!",
          VoiceName = "voice/$Locale$/story/0/602213/9687C8D2",
          bTurnOffVoice = true
        },
        [60221401] = {
          ContentKR = "와, 보물 상자가 열렸다! 우리가 이겼어~",
          DialogueId = 60221401,
          Duration = 3,
          GUID = "9687C8D6",
          SpeakNpcId = 200002,
          Subtitle = "The chest is open, yayyy! We won!",
          VoiceName = "voice/$Locale$/story/0/602214/9687C8D6",
          bTurnOffVoice = true
        },
        [60221501] = {
          ContentKR = "우와, 저기 봐! 주최 측에서 경기장에 새로운 열쇠 하나를 추가했어!",
          DialogueId = 60221501,
          Duration = 4,
          GUID = "9687C8DA",
          SpeakNpcId = 200002,
          Subtitle = "Look, look over there! The organizers just threw a new key into the arena!",
          VoiceName = "voice/$Locale$/story/0/602215/9687C8DA",
          bTurnOffVoice = true
        },
        [60221601] = {
          ContentKR = "군단의 영광을 위하여, 전진하라!",
          DialogueId = 60221601,
          Duration = 4,
          GUID = "9687C8DE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 930005,
          Subtitle = "For the glory of the legion, advance!",
          VoiceName = "voice/$Locale$/story/0/602216/9687C8DE",
          bTurnOffVoice = true
        },
        [60230101] = {
          ContentKR = "제약 설비를 얼른 찾아보자.",
          DialogueId = 60230101,
          Duration = 4,
          GUID = "96910001",
          SpeakNpcId = 200002,
          Subtitle = "Hurry, let's find the Potion Station!",
          VoiceName = "voice/$Locale$/story/0/602301/96910001",
          bTurnOffVoice = true
        },
        [60230201] = {
          ContentKR = "아참, 제약 설비에 혈청을 회수하려면, 설비 근처에서 적을 쓰러뜨려야 해!",
          DialogueId = 60230201,
          Duration = 4,
          GUID = "96910029",
          NextDialogue = 60230202,
          SpeakNpcId = 200002,
          Subtitle = "Oh yeah! To make the station collect the serum, we gotta defeat enemies near it!",
          VoiceName = "voice/$Locale$/story/0/602302/96910029",
          bTurnOffVoice = true
        },
        [60230202] = {
          ContentKR = "제약 설비를 가득 채우면 의뢰를 완료할 수 있어. 힘내!",
          DialogueId = 60230202,
          Duration = 4,
          GUID = "96910191",
          SpeakNpcId = 200002,
          Subtitle = "Fill up the Potion Station to complete the commission! Go, go, go!",
          VoiceName = "voice/$Locale$/story/0/602302/96910191",
          bTurnOffVoice = true
        },
        [60230301] = {
          ContentKR = "쉿... 뭔가 수상한 소리가 들리는 것 같아. 덩치 큰 녀석이 오고 있나 봐!",
          DialogueId = 60230301,
          Duration = 4,
          GUID = "96910321",
          SpeakNpcId = 200002,
          Subtitle = "Shh… I hear something weird, sounds like a big guy's coming!",
          VoiceName = "voice/$Locale$/story/0/602303/96910321",
          bTurnOffVoice = true
        },
        [60230401] = {
          ContentKR = "으아아, 저 녀석이 거대한 독 안개를 몰고 왔잖아. 이러다간 제약 설비 안에 있는 혈청이 전부 다 침식돼 버릴 거야. 얼른 해치워야 해!",
          DialogueId = 60230401,
          Duration = 4,
          GUID = "969104B1",
          SpeakNpcId = 200002,
          Subtitle = "Whoaaa, a huge thing is charging over with Toxic Smog! It'll corrupt all the serum in the station! Take it down, quick!",
          VoiceName = "voice/$Locale$/story/0/602304/969104B1",
          bTurnOffVoice = true
        },
        [60300101] = {
          ContentKR = "쉿... 마령의 목소리가 들리는 것 같아! 어서 가서 찾아보자, 서둘러 구해내야 해!",
          DialogueId = 60300101,
          Duration = 4,
          GUID = "96F47952",
          SpeakNpcId = 200002,
          Subtitle = "Shh... I think I heard the crying of a Geniemon! Let's go rescue it!",
          VoiceName = "voice/$Locale$/story/0/603001/96F47952",
          bTurnOffVoice = true
        },
        [60800101] = {
          ContentKR = "열쇠가 없다…… 주변을 찾아보자.",
          DialogueId = 60800101,
          Duration = 5,
          GUID = "9834E892",
          SpeakNpcId = 100001,
          Subtitle = "A chest key needed... Look around to seek one."
        },
