        },
        [71000220] = {
          ContentKR = "(고양이 사료를 놓는다)",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001,
          Subtitle = "(Put down some cat food)"
        },
        [71000300] = {
          ContentKR = "(길고양이가 깡충거리며 몇 발짝 달려가더니 멈춰 서서 나를 바라본다. 마치 따라오라는 듯하다.)",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000310] = {
          ContentKR = "(길고양이가 깡충거리며 몇 발짝 달려가더니 멈춰 서서 나를 바라본다. 마치 따라오라는 듯하다.)",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000320] = {
          ContentKR = "(길고양이가 깡충거리며 몇 발짝 달려가더니 멈춰 서서 나를 바라본다. 마치 따라오라는 듯하다.)",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000330] = {
          ContentKR = "(길고양이가 내 발치를 즐겁게 두 바퀴 돌았다. 만족스러운 표정을 보니 내 마음도 치유되는 것 같다.)",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006,
          Subtitle = "(The cat circles around your feet, obviously happy and content. A warm sense of peace and joy fills your heart.)"
        },
        [71000501] = {
          ContentKR = "그만 때리라고, 계속 때리면 비장의 무기를 쓸 거... 좋아, 정 그렇다면... 살려주세요!!",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005,
          Subtitle = "Hey, stop it! Or I'll have to pull out my secret weapon... Alright, you asked for this — HELP! AAHHH!!!"
        },
        [71000502] = {
          ContentKR = "으아아아...",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005,
          Subtitle = "Waaahhh..."
        },
        [71000503] = {
          ContentKR = "마지막 하나, 끝났어.",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014,
          Subtitle = "That was the last of them. All clear."
        },
        [71000504] = {
          ContentKR = "근처에 적이 더 있나 살펴볼 테니 조심해.",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014,
          Subtitle = "I'll go check if there are any more enemies nearby. Be careful on your own."
        },
        [71000505] = {
          ContentKR = "알겠어, 조심할게!",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015,
          Subtitle = "Got it! I'll stay sharp!"
        },
        [71000506] = {
          ContentKR = "어어, 너도 왔구나. 흑흑... 이렇게나 많이들 도와주다니... 이건 모두를 위한 감사 선물이야. 앞으로도 잘 부탁해.",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015,
          Subtitle = "Aww, you're here too... *sob*... I can't believe so many people are willing to help me. Here's a little something for your trouble. Thanks, everyone! You guys are the best!"
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "고마워, 위기는 벗어난 것 같네! 모험을 계속하자.",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          Subtitle = "Thank you, I'm safe now! On to more adventures!",
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "고마워, 위기는 벗어난 것 같네! 모험을 계속하자.",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          Subtitle = "Thank you, I'm safe now! On to more adventures!",
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentKR = "(파도에 떠밀려온 나무통들이 해변에 쌓여 있다. 찾아보면 유용한 것들을 발견할 수 있을지도 모른다.)",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006,
          Subtitle = "(Barrels washed ashore line the beach. Maybe they hold something useful.)"
        },
        [71000612] = {
          ContentKR = "(나무통 바닥에 큰 구멍이 뚫려 있다. 예전에 뭔가 귀중한 것들이 들어있었을지 모르지만, 지금은 쓸모없는 쓰레기일 뿐이다. 다른 나무통을 살펴보자.)",
          DialogueId = 71000612,
          GUID = "B1BE19E8",
          Subtitle = "(This barrel has a gaping hole in the bottom. Whatever treasure it once held is long gone. Better try another.)"
        },
        [71000613] = {
          ContentKR = "(나무통 안에는 썩은 생선과 새우 외에는 아무것도 없다. 다른 나무통을 살펴보자.)",
          DialogueId = 71000613,
          GUID = "B1BE1A12",
          Subtitle = "(Nothing but rotten fish and shrimp in this one. Better try another.)"
        },
        [71000615] = {
          ContentKR = "(정성 들여 뒤진 끝에, 드디어 나무통 틈새에서 쓸만한 물자를 발견했다!)",
          DialogueId = 71000615,
          GUID = "B1BE1A66",
          Subtitle = "(Patience pays off. After a meticulous search, you spot a hidden compartment — and inside, a stash of usable supplies.)"
        },
        [71000701] = {
          ContentKR = "정말 골치 아프네, 남은 배관이 별로 없는데.",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007,
          Subtitle = "Dang it! Just a few more to go, and now this."
        },
        [71000710] = {
          ContentKR = "무슨 일이죠?",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001,
          Subtitle = "What happened?"
        },
        [71000711] = {
          ContentKR = "거참, 도시의 폭시코르 배관들이 제대로 작동하는지 점검해야 하는데...",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007,
          Subtitle = "I was checking the condition of the Phoxichor pipes that connect the city."
        },
        [71000721] = {
          ContentKR = "작업용 로프가 이전 배관 작업을 하다가 끊어졌어. 혹시 남은 배관을 좀 확인해 줄 수 있을까?",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007,
          Subtitle = "I've only got a few left, but my safety rope just snapped. Could you go check the rest of the pipes for me?"
        },
        [71000741] = {
          ContentKR = "남은 배관의 위치를 표시해 뒀어. 정말 고마워!",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007,
          Subtitle = "I've marked the remaining pipes for you. I'm counting on you!"
        },
        [71000751] = {
          ContentKR = "(이 배관에는 손상이 없네. 다음 배관을 확인해 보자.)",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006,
          Subtitle = "(This pipe's in good shape. Let's go check the next one.)"
        },
        [71000761] = {
          ContentKR = "(마지막 배관도 손상이 없어. 아까 그 작업자에게 가서 알려주자.)",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006,
          Subtitle = "(The last one looks good too. Time to go back and inform the fitter.)"
        },
        [71000771] = {
          ContentKR = "모두 괜찮다고? 정말 다행이네! 정말 고마워!",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007,
          Subtitle = "All good? That's great news! Thank you so much!"
        },
        [71000780] = {
          ContentKR = "(배관에 약간의 손상이 있다. 작업자에게 알려주자.)",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006,
          Subtitle = "(This pipe has been slightly damaged. Better inform the fitter.)"
        },
        [71000781] = {
          ContentKR = "하아... 또 야근이네. 내가 공구를 가져올 테니까 이 열쇠로 폭시코르 배관 총밸브를 잠가주지 않겠니?",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007,
          Subtitle = "Oof... Looks like I'll be working overtime again. Here, take my key and shut off the main Phoxichor valve while I grab my tools."
        },
        [71000782] = {
          ContentKR = "고마워, 이제 나머지는 내가 할게.",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007,
          Subtitle = "Thank you. I'll take it from here."
        },
        [71000801] = {
          ContentKR = "{nickname}! {nickname}! 얼른요! 완전 흥미로운 연구 주제를 찾아냈다고요!",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011,
          Subtitle = "Hey, ! Come quick — I've found something amazing! A brand new research subject!"
        },
        [71000802] = {
          ContentKR = "이번 연구에 필요한 재료가 호수 건너편에 있거든요... 도와주실 수 있을까요?",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011,
          Subtitle = "The material I need is way across the lake. Would you mind helping me grab some?"
        },
        [71000803] = {
          ContentKR = "이게 테오가 찾던 연구 재료구나. 조금 가져다주자.",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001,
          Subtitle = "This should be what Theo's looking for. Time to bring it back."
        },
        [71000804] = {
          ContentKR = "고마워요! 위대한 연금술사가 되려면... 진짜 배울 게 너무너무 많아요...!",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011,
          Subtitle = "Thank you! To become a great alchemist, there's still sooo much I've got to learn... But I'll get there!"
        },
        [71000805] = {
          ContentKR = "...그렇군요. 결국 위대한 연금술사가 되기 위한 첫걸음은... 스스로 연구 재료를 찾아내는 거죠!",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011,
          Subtitle = "Oh... I see. Well, I guess that's lesson number one for any great alchemist — gather your own materials! Got it!"
        },
        [71000901] = {
          ContentKR = "숨바꼭질, 숨바꼭질, 다 같이 숨바꼭질하자!",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008,
          Subtitle = "Hide and seek! Come and play hide and seek!"
        },
        [71000902] = {
          ContentKR = "숨바꼭질, 숨바꼭질, 다 같이 숨바꼭질하자!",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          Subtitle = "Hide and seek! Come and play hide and seek!",
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          ContentKR = "좋아! 하지만 난 찾는 거 말고 숨고 싶은데.",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          Subtitle = "I'm in! But I don't want to be the seeker, I want to hide!",
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          ContentKR = "나도. 완전 숨기 좋은 곳을 발견했는데, 거기 숨으면 분명 내가 이길 거야!",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          Subtitle = "Me too! I've found a super secret spot. I'm sure to win this time!",
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          ContentKR = "그럼 어떡하지? 같이 숨바꼭질할 사람 없나...",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009,
          Subtitle = "But we need a seeker... Anyone else up for a game with us?"
        },
        [71000906] = {
          ContentKR = "(아이들이 지나가는 나를 발견하고는 기대에 찬 눈으로 대답을 기다리고 있다.)",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006,
          Subtitle = "(The kids notice you passing by, their eyes wide with hope, eagerly waiting for your response.)"
        },
        [71000907] = {
          ContentKR = "(아이들이 신나서 펄쩍 뛰더니 순식간에 골목 모퉁이로 사라졌다. 이제 이 아이들을 어디서 찾아야 할지 잘 생각해 봐야겠다.)",
          DialogueId = 71000907,
          GUID = "B1BE4A4E",
          Subtitle = "(The children cheer excitedly and vanish around the corner in the blink of an eye. Time to find them!)"
        },
        [71000908] = {
          ContentKR = "와, 이렇게 빨리 찾아내다니.",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008,
          Subtitle = "Wow, that was quick!"
        },
        [71000909] = {
          ContentKR = "정말 대단하세요.",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009,
          Subtitle = "You're really good at this!"
        },
        [71000910] = {
          ContentKR = "으악, 내가 지다니...",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010,
          Subtitle = "Ugh, can't believe I lost..."
        },
        [71000911] = {
          ContentKR = "알겠어요. 졌으니 인정해야죠. 이건 감사 선물이에요. 다음에 또 우리랑 같이 놀아요!",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008,
          Subtitle = "Alright, you win. Here's your prize. Come play with us again sometime!"
        },
        [71001001] = {
          ContentKR = "(새 차량 한 대. 혹시 이게... 돈 벌 기회일지도?)",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006,
          Subtitle = "(A brand-new vehicle sits unattended. Could this be... a golden opportunity?)"
        },
        [71001002] = {
          ContentKR = "(차 안의 폭시코르 에너지 장치가 가득 차 있다. 역시 돈 벌 기회군!)",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006,
          Subtitle = "(The car's got a full canister of Phoxichor — jackpot!)"
        },
        [71001003] = {
          ContentKR = "뭐 하는 거야! 누구 없어요?!",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010,
          Subtitle = "What do you think you're doing!? Guys, I need support!"
        },
        [71001004] = {
          ContentKR = "(이제 아무도 날 막지 않을 것이다. 차 문을 열고 액체 폭시코르로 가득 찬 에너지 장치를 가져가 좋은 값에 팔면 된다. 모든 게 계획대로 진행되었고, 오늘 하루도 기분이 좋다.)",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006,
          Subtitle = "(With no one left to stop you, you pry open the door, grab the Phoxichor Canister, and walk away with a small fortune. Everything's going smooth. What a lucky day.)"
        },
        [71001005] = {
          ContentKR = "(결국 양심이 유혹을 눌렀다. 차량 보안에 허점이 있음을 성문 경비에게 알리기로 한다.)",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006,
          Subtitle = "(Your better angels prevail. You decide to report the security lapse to the guards at the city gate.)"
        },
        [71001006] = {
          ContentKR = "알려줘서 고마워. 바로 순찰을 강화해야겠군. 이건 내 성의니 받아줘.",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010,
          Subtitle = "Thank you for bringing this to our attention. I'll send more patrols right away. Please accept this small gift as a gesture of gratitude from us."
        },
        [71001101] = {
          ContentKR = "(필토이드가 몰려옵니다. 물리치세요!)",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006,
          Subtitle = "(Filthoids incoming! Dispel them!)"
        },
        [71001201] = {
          ContentKR = "(당신과 베레가 남긴 흔적 위로 잡초가 무성해졌다. 신상 주변을 정리해 보는 게 좋겠다.)",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006,
          Subtitle = "(Overgrown weeds have swallowed the traces of the memories you once shared here with Berry. Perhaps it's time to clear the shrine's surroundings.)"
        },
        [71001202] = {
          ContentKR = "(당신의 손길 덕분에 신상 주변이 다시 깔끔해졌고, 기억 속 그 모습으로 되돌아왔다.)",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006,
          Subtitle = "(The weeds are gone. The shrine stands pristine once more — just as you remember it.)"
        },
        [71001301] = {
          ContentKR = "베레의 말로는 여기가 우리가 살았던 집이라는데, 난 아무것도 기억나지 않아...",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001,
          Subtitle = "Berry said this is where we used to live, but I can't remember a thing..."
        },
        [71001302] = {
          ContentKR = "주변을 좀 둘러보면 뭔가 떠오를지도 모르겠어.",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001,
          Subtitle = "Maybe if I look around, something will jog my memory."
        },
        [71001303] = {
          ContentKR = "가구는 무척 조잡하게 만들어졌고, 못들이 나무 깊숙이 박혀있어. 마을 집 문손잡이처럼. 베레는 어릴 때부터 이렇게 힘이 셌구나.",
          DialogueId = 71001303,
          GUID = "B1BE8B46",
          Subtitle = "The furniture looks pretty rough — lots of nails hammered deep into the wood, just like the door handles back in the village. Berry must have been incredibly strong even as a kid."
        },
        [71001304] = {
          ContentKR = "이건... 연금술 동화책? 어릴 때 베레가 들려줬던 그 이상한 잠자리 동화들이 전부 이 책에서 나온 거였구나.",
          DialogueId = 71001304,
          GUID = "B1BE8B70",
          NextDialogue = 71001305,
          Subtitle = "Wait, is this... an alchemy storybook? So all those weird bedtime stories Berry told me when we were little came from this."
        },
        [71001305] = {
          ContentKR = "하지만 책에 적힌 이 메모들은 베레의 글씨체보다 훨씬 반듯한데, 누가 쓴 걸까?",
          DialogueId = 71001305,
          GUID = "B1BE8B9A",
          Subtitle = "But these notes in the margins are much neater than Berry's handwriting. Who could've written them?"
        },
        [71001306] = {
          ContentKR = "베레에 대한 기억은 많이 떠올랐네. 하지만 이곳에 대해서는 아직도 아무것도 기억나지 않아...",
          DialogueId = 71001306,
          GUID = "B1BE8BC4",
          NextDialogue = 71001307,
          SpeakNpcId = 100001,
          Subtitle = "Mm, I'm recalling a lot about Berry, but still nothing about this place."
        },
        [71001307] = {
          ContentKR = "됐어, 나중에 자연스럽게 기억나겠지.",
          DialogueId = 71001307,
          GUID = "B1BE8BEE",
          SpeakNpcId = 100001,
          Subtitle = "Never mind. Maybe it'll come back to me someday."
        },
        [71001401] = {
          ContentKR = "(멀리서도 아이스베리 향이 풍기네요. 몇 개 따서 팔면 좋은 값을 받을 수 있을 텐데요.)",
          DialogueId = 71001401,
          Duration = 4,
          GUID = "B1BE9B5A",
          SpeakNpcId = 800006,
          Subtitle = "(You catch the fragrant aroma of Borealberries from afar. If you pick some, you could make a small fortune.)"
        },
        [71001402] = {
          ContentKR = "(이번에 딴 아이스베리는 색도 곱고 과육도 실해서, 이런 특산품이라면 누가 봐도 금방 팔릴 게 분명하다.)",
          DialogueId = 71001402,
          Duration = 4,
          GUID = "B1BE9B84",
          SpeakNpcId = 800006,
          Subtitle = "(These Borealberries are vibrant and plump. It's clear these seasonal delights will fetch a good price anywhere.)"
        },
        [71001403] = {
          ContentKR = "(저 멀리 아이스베리를 수매하는 상인이 둘이 있다. 그들과 이야기를 나눠보고 누구에게 팔지 결정하자.)",
          DialogueId = 71001403,
          Duration = 4,
          GUID = "B1BE9BAE",
          SpeakNpcId = 800006,
          Subtitle = "(You notice two traders nearby looking to buy Borealberries. Maybe it's worth talking to them both before deciding who to sell to.)"
        },
        [71001404] = {
          ContentKR = "제가 아이스레이크 시티에서 장사한 지도 몇 년은 되었어요. 수익은 적지만 다들 단골이랍니다. 이번 아이스베리는 제가 다 살 테니 이참에 친구가 되는 건 어떨까요. 다들 이 도시에 사는 사람들이니 앞으로 서로 도울 일도 있을 거고요.",
          DialogueId = 71001404,
          GUID = "B1BE9BD8",
          NextOptions = {
            [1] = 710014041,
            [2] = 710014042
          },
          SpeakNpcId = 818002,
          Subtitle = "I've been running this little stall in Icelake for years. Just a small business — it makes more friends than money. I mean, we can look out for each other in this city, am I right?"
        },
        [71001405] = {
          ContentKR = "안녕하세요, 아이스베리를 가지고 계시는 것 같은데요. 제가 아이스레이크 시티의 가난한 상인들보다 훨씬 더 많이 쳐줄 수 있는데요. 같이 한몫 벌어보는 게 어때요?",
          DialogueId = 71001405,
          GUID = "B1BE9C02",
          NextOptions = {
            [1] = 710014051,
            [2] = 710014052
          },
          SpeakNpcId = 818003,
          Subtitle = "Hey there, I see you've got some Borealberries. I can pay way more than those penny-pinching local traders. How about we make some serious cash together, huh?"
        },
        [71001406] = {
          ContentKR = "(수익은 적지만 장기적이고 안정적인 인맥을 위해, 결국 현지 상인과 거래를 했다.)",
          DialogueId = 71001406,
          Duration = 3,
          GUID = "B1BE9C2C",
          SpeakNpcId = 800006,
          Subtitle = "(Prioritising long-term connections, you make the deal with the local trader despite the lower profit.)"
        },
        [71001407] = {
          ContentKR = "(미래의 약속보다는 당장의 이익이 더 확실하다. 결국 외지 상인과 거래를 했고, 거액의 수익을 얻었다.)",
          DialogueId = 71001407,
          Duration = 4,
          GUID = "B1BE9C56",
          SpeakNpcId = 800006,
          Subtitle = "(Promises of future benefits aren't as reliable as immediate gains. You make the deal with the out-of-town trader and walk away with a hefty sum.)"
        },
        [71001501] = {
          ContentKR = "아이고... 이 망할 물건이 또 고장 났네...",
          DialogueId = 71001501,
          Duration = 3,
          GUID = "B1BEABC2",
          SpeakNpcId = 818006,
          Subtitle = "Ugh... not this again."
        },
        [71001502] = {
          ContentKR = "무슨 일이죠?",
          DialogueId = 71001502,
          GUID = "B1BEABEC",
          NextDialogue = 71001503,
          SpeakNpcId = 100001,
          Subtitle = "What happened?"
        },
        [71001503] = {
          ContentKR = "이 기계가 자꾸 말썽이에요. 기계 문제인지 제 문제인지 확인해 주시지 않을래요.",
          DialogueId = 71001503,
          GUID = "B1BEAC16",
          SpeakNpcId = 818006,
          Subtitle = "I can't seem to get this machine working properly. Why don't you give it a try? Let's see if it's the machine or just me."
        },
        [71001504] = {
          ContentKR = "고마워요.",
          DialogueId = 71001504,
          Duration = 2,
          GUID = "B1BEAC40",
          SpeakNpcId = 818006,
          Subtitle = "Thank you."
        },
        [71001505] = {
          ContentKR = "대단하네요! 역시 제 조작 방법이 잘못됐나 봐요...",
          DialogueId = 71001505,
          GUID = "B1BEAC6A",
          SpeakNpcId = 818006,
          Subtitle = "Impressive! Looks like I'm the problem then..."
        },
        [71001506] = {
          ContentKR = "그게 될까요?",
          DialogueId = 71001506,
          Duration = 2,
          GUID = "B1BEAC94",
          SpeakNpcId = 818006,
          Subtitle = "That actually worked?"
        },
        [71001507] = {
          ContentKR = "음... 정말로 두드리기만 하면 돼요?",
          DialogueId = 71001507,
          Duration = 2,
          GUID = "B1BEACBE",
          SpeakNpcId = 818006,
          Subtitle = "Um... are you sure a smack would work?"
        },
        [71001508] = {
          ContentKR = "저기요, 방금 부품이 튀어 나간 것 같은데요.",
          DialogueId = 71001508,
          Duration = 2,
          GUID = "B1BEACE8",
          SpeakNpcId = 818006,
          Subtitle = "Wait, did a part just fly off?"
        },
        [71001509] = {
          ContentKR = "대단해요, 정말 효과가 있네요!",
          DialogueId = 71001509,
          GUID = "B1BEAD12",
          SpeakNpcId = 818006,
          Subtitle = "Wow, you've got the magic touch!"
        },
        [71001601] = {
          ContentKR = "필토이드가 너무 많아... 어떡하지...",
          DialogueId = 71001601,
          Duration = 3,
          GUID = "B1BEBC2A",
          SpeakNpcId = 818004,
          Subtitle = "So many Filthoids... What am I going to do...?"
        },
        [71001602] = {
          ContentKR = "무슨 일이죠?",
          DialogueId = 71001602,
          GUID = "B1BEBC54",
          NextDialogue = 71001603,
          SpeakNpcId = 100001,
          Subtitle = "What's wrong?"
        },
        [71001603] = {
          ContentKR = "와, 옷차림을 보니 분명 대단한 월석 사냥꾼이겠군요! 저도 사실 월석 사냥꾼인데, 너무 약해서...",
          DialogueId = 71001603,
          GUID = "B1BEBC7E",
          NextDialogue = 71001604,
          SpeakNpcId = 818004,
          Subtitle = "Wow, judging by your gear, you must be a really skilled Phoxhunter, right? Actually... I'm a Phoxhunter myself, but I'm not very strong..."
        },
        [71001604] = {
          ContentKR = "저 필토이드 무리 속에 떨어뜨린 제 무기를 찾아와 주실 수 있나요? 그러지 않으면 다음 의뢰도 수행할 수 없을 것 같아요...",
          DialogueId = 71001604,
          GUID = "B1BEBCA8",
          NextDialogue = 71001605,
          SpeakNpcId = 818004,
          Subtitle = "Could you help me retrieve my weapon from those Filthoids? If I don't get it back, I won't be able to take on my next commission..."
        },
        [71001605] = {
          ContentKR = "...제가 도와드리죠.",
          DialogueId = 71001605,
          GUID = "B1BEBCD2",
          NextDialogue = 71001606,
          SpeakNpcId = 100001,
          Subtitle = "...Sure, I'll help you out."
        },
        [71001606] = {
          ContentKR = "정말 감사합니다!",
          DialogueId = 71001606,
          GUID = "B1BEBCFC",
          SpeakNpcId = 818004,
          Subtitle = "Thank you so much!"
        },
        [71001607] = {
          ContentKR = "필토이드들이 바로 앞에 있어요. 부디 조심하세요.",
          DialogueId = 71001607,
          Duration = 3,
          GUID = "B1BEBD26",
          SpeakNpcId = 818004,
          Subtitle = "They're just up ahead. Be careful!"
        },
        [71001608] = {
          ContentKR = "으으으... 의뢰를 받지 못하면 어떡하죠. 며칠째 굶고 있어요...",
          DialogueId = 71001608,
          GUID = "B1BEBD50",
          NextOptions = {
            [1] = 710016081,
            [2] = 710016082
          },
          SpeakNpcId = 818004,
          Subtitle = "*sob* If I can't take it back, how am I supposed to make a living...? I haven't had a proper meal in days..."
        },
        [71001609] = {
          ContentKR = "감사합니다! 그럼 저는 이제 의뢰를 하러 가볼게요. 나중에 또 만나요!",
          DialogueId = 71001609,
          GUID = "B1BEBD7A",
          SpeakNpcId = 818004,
          Subtitle = "Thank you! I'm off to my next commission. Take care!"
        },
        [71001610] = {
          ContentKR = "상황은 다 알고 있어요. 약자에게 무기를 돌려주는 게 정말 좋은 일일까요? 어쩌면 언젠가 의뢰 중에 죽을 수도 있잖아요. 그보다 차라리 그 사람의 무기를 모두 저한테 파는 게 어때요? 이게 모두에게 좋을 거예요.",
          DialogueId = 71001610,
          GUID = "B1BEBDA4",
          NextOptions = {
            [1] = 710016101,
            [2] = 710016102
          },
          SpeakNpcId = 818005,
          Subtitle = "I know the whole story. Are you sure it's a good idea to give her the weapon back? With her strength, she might just die on her next commission. So, why not sell the weapon to me? It's the safer option for everyone."
        },
        [71001611] = {
          ContentKR = "좋은 거래였어요. 앞으로도 계속 저를 찾아주세요.",
          DialogueId = 71001611,
          GUID = "B1BEBDCE",
          SpeakNpcId = 818005,
          Subtitle = "Thank you! Looking forward to our next deal!"
        },
        [71001701] = {
          ContentKR = "어라, {nickname} 아니야? 어서 와, 어서 와.",
          DialogueId = 71001701,
          GUID = "B1BECC92",
          SpeakNpcId = 818012,
          Subtitle = "Oh, hey! Isn't that ? Come here!"
        },
        [71001702] = {
          ContentKR = "흠흠, 여기를 잘 조사해 봐야 할 것 같은데, 날 잘 지켜줄 거지?",
          DialogueId = 71001702,
          GUID = "B1BECCBC",
          NextOptions = {
            [1] = 710017021,
            [2] = 710017022
          },
          SpeakNpcId = 818012,
          Subtitle = "I've got some serious research to do here. Can you protect me while I work?"
        },
        [71001703] = {
          ContentKR = "어떻게 내가 연구할 때마다 나쁜 녀석들이 와서 방해하는 걸까? 부탁할게! 지금 중요한 부분을 연구하고 있거든.",
          DialogueId = 71001703,
          GUID = "B1BECCE6",
          SpeakNpcId = 818012,
          Subtitle = "Why do baddies always show up when I'm in the middle of research? I'm counting on you! I'm just getting to the bottom of it."
        },
        [71001704] = {
          ContentKR = "여기는 이렇게, 그리고 이렇게... 음... 거의 다 됐어, 조금만 더 기다려 줘.",
          DialogueId = 71001704,
          GUID = "B1BECD10",
          SpeakNpcId = 818012,
          Subtitle = "Let's see... Hmm... Huh... Almost there! Hang in there!"
        },
        [71001705] = {
          ContentKR = "됐다, 바로 이거야! 야호, 연구 끝!",
          DialogueId = 71001705,
          GUID = "B1BECD3A",
          SpeakNpcId = 818012,
          Subtitle = "That's a wrap! Research successfully complete! Hooray!"
        },
        [71001706] = {
          ContentKR = "{nickname} 덕분에 이번 조사를 무사히 마쳤어! 이건 작은 감사 선물이야. 다음에도 잘 부탁해~",
          DialogueId = 71001706,
          GUID = "B1BECD64",
          SpeakNpcId = 818012,
          Subtitle = "I couldn't have done it without you! Here's a little something for your trouble~ Let's team up again next time!"
        },
        [71001707] = {
          ContentKR = "음... 같이 가기 힘들다면 그냥 일찍 떠나는 게 좋겠어. 여긴 좀 음침한 기분이 들거든...",
          DialogueId = 71001707,
          GUID = "B1BECD8E",
          SpeakNpcId = 818012,
          Subtitle = "Oh... Well, if you won't stick around, I'd better leave. This place gives me the creeps..."
        },
        [71001801] = {
          ContentKR = "어르신, 정말 별거 아니라니까요. 괜한 걱정 하시는 거예요.",
          DialogueId = 71001801,
          GUID = "B1BEDCFA",
          NextDialogue = 71001802,
          SpeakNpcId = 818059,
          Subtitle = "Come on, sir — it's not that deep. You're reading too much into it."
        },
        [71001802] = {
          ContentKR = "너희는 지금 이 도시에 숨어 있는 위험을 전혀 눈치채지 못하고 있어! 아이스레이크 시티를 너희 같은 애들한테 맡겨선 정말 끝장이야!",
          DialogueId = 71001802,
          GUID = "B1BEDD24",
          SpeakNpcId = 818009,
          Subtitle = "Reading too much? You lot can't see the danger crawling right under your noses! Icelake's done for with your lot in charge!"
        },
        [71001803] = {
          ContentKR = "어르신, 너무 흥분하지 마시고요. 제가 도와드릴 일이 있을까요?",
          DialogueId = 71001803,
          GUID = "B1BEDD4E",
          NextDialogue = 71001804,
          SpeakNpcId = 100001,
          Subtitle = "Easy, sir. Is there something I can help you with?"
        },
        [71001804] = {
          ContentKR = "무법자들 천지야! 아이스레이크 시티에 숨은 무법자들이 점점 많아지고 있다고... 갈수록 세상이 왜 이 모양인지...",
          DialogueId = 71001804,
          GUID = "B1BEDD78",
          NextDialogue = 71001805,
          SpeakNpcId = 818009,
          Subtitle = "Criminals — swarming out of the cracks, I tell you! Tch — kids these days, all spineless!"
        },
        [71001805] = {
          ContentKR = "치안서의 젊은것들은 전~혀 관심도 없지. 그래서 내가 나서야겠다 이 말이야! {性别: 자네처럼 듬직한 청년이|이렇게 야무진 아가씨가} 도와줄 수 있겠나?",
          DialogueId = 71001805,
          GUID = "B1BEDDA2",
          SpeakNpcId = 818009,
          Subtitle = "If the lazy pups at the Security Bureau won't act, then I will! And you — {性别:lad|lass} — you look sharp. Feel like lending an old soldier a hand?"
        },
        [71001806] = {
          ContentKR = "흥, 잘 생각했어.",
          DialogueId = 71001806,
          GUID = "B1BEDDCC",
          SpeakNpcId = 818009,
          Subtitle = "Hmph..."
        },
        [71001807] = {
          ContentKR = "쯧... (마음에 안 든다는 듯 혀를 찬다.)",
          DialogueId = 71001807,
          GUID = "B1BEDDF6",
          SpeakNpcId = 818009,
          Subtitle = "Tch..."
        },
        [71001808] = {
          ContentKR = "쯧... 이번엔 꽤 깊숙이 숨었잖아? 그래도 난 절대 포기 안 해! 이 버러지 같은 놈들... 어디 걸리기만 해봐!",
          DialogueId = 71001808,
          GUID = "B1BEDE20",
          SpeakNpcId = 818009,
          Subtitle = "Hmph, sneaky little devils... But I'm not done. This city needs justice — and I won't stop till it gets it. You lot better watch your backs..."
        },
        [71001809] = {
          ContentKR = "다들 각오해라!",
          DialogueId = 71001809,
          GUID = "B1BEDE4A",
          NextDialogue = 71001810,
          SpeakNpcId = 818011,
          Subtitle = "Now!"
        },
        [71001810] = {
          ContentKR = "역시! 쓰레기들이 튀어나왔군! 아이스레이크 시티는 절대 겉보기처럼 안전하지 않아! 지금부터 내가 직접 심판해 주마!",
          DialogueId = 71001810,
          GUID = "B1BEDE74",
          NextDialogue = 71001813,
          SpeakNpcId = 818009,
          Subtitle = "Ha! The rats are out of hiding! Told you — Icelake's never been safe! Time for these old bones to dish out some justice!"
        },
        [71001811] = {
          ContentKR = "수고 많았네, 젊은이. 이젠 아이스레이크 시티의 치안은 자네와 나, 우리 둘한테 달렸네.",
          DialogueId = 71001811,
          GUID = "B1BEDE9E",
          SpeakNpcId = 818009,
          Subtitle = "You did good, kid. The safety of Icelake rests on shoulders like ours."
        },
        [71001812] = {
          ContentKR = "흥, 애초에 남한테 기대한 적도 없어! 가 버려!",
          DialogueId = 71001812,
          GUID = "B1BEDEC8",
          SpeakNpcId = 818009,
          Subtitle = "Hmph. Figures. Should've known better than to count on anyone. Off with you, then."
        },
        [71001813] = {
          ContentKR = "(노인은 말도 없이 돌진해 버렸다. 더 큰 사고로 번지기 전에, 이 혼란스러운 난투극을 막는 건 이제 당신의 몫이다.)",
          DialogueId = 71001813,
          GUID = "B1BEDE75",
          SpeakNpcId = 800006,
          Subtitle = "(Before you can stop him, the old man charges straight in. You'd better follow — before this turns into a bloodbath.)"
        },
        [71001901] = {
          ContentKR = "조정하고 나서... 진짜 뭐가 달라지긴 했나?",
          DialogueId = 71001901,
          GUID = "B1BEED62",
          SpeakNpcId = 818016,
          Subtitle = "Hmm... I wonder if that tweak actually made any difference..."
        },
        [71001902] = {
          ContentKR = "오? 잘 왔어요! 방금 이 승강기를 조정했는데, 너무 오르락내리락했는지 감이 잘 안 잡히네요. 혹시 한번 타보고 전보다 빨라졌는지 확인해 주실 수 있을까요?",
          DialogueId = 71001902,
          GUID = "B1BEED8C",
          SpeakNpcId = 818016,
          Subtitle = "Ah — good timing. I just finished adjusting the lift again. Could you give it a quick ride and tell me if it feels any faster? I've been up and down so many times I honestly can't tell anymore."
        },
        [71001903] = {
          ContentKR = "이렇게 빠르다고요? 어쩌면 제가 뭔가를 놓쳤나 보네요. 전체 점검을 해야겠어요. 테스트에 도움 주셔서 감사합니다. 이건 작은 보답이에요.",
          DialogueId = 71001903,
          GUID = "B1BEEDB6",
          SpeakNpcId = 818016,
          Subtitle = "It went that fast? Huh... maybe I missed something. Looks like I'll have to do a full diagnostic again. Thanks for helping with the data — here, take this for your trouble."
        },
        [71001904] = {
          ContentKR = "딱히 달라진 건 없는 것 같아요.",
          DialogueId = 71001904,
          GUID = "B1BEEDE0",
          NextDialogue = 71001905,
          SpeakNpcId = 100001,
          Subtitle = "Didn't really feel any different."
        },
        [71001905] = {
          ContentKR = "그렇군요, 조정이라는 게 결국 자기 위안이었나 봐요. 어쨌든 테스트에 응해주셔서 감사해요. 이건 작은 감사의 표시예요.",
          DialogueId = 71001905,
          GUID = "B1BEEE0A",
          SpeakNpcId = 818016,
          Subtitle = "Yeah... figures. Maybe I'm just tweaking it for peace of mind at this point. Still — appreciate the feedback. Here, something for your time."
        },
        [71002001] = {
          ContentKR = "제리... 또 어디로 숨어버린 거야... 으앙... 흐엉...",
          DialogueId = 71002001,
          GUID = "B1BEFDCA",
          SpeakNpcId = 818017,
          Subtitle = "Jerry! Where did you run off to again...? *sniffles*"
        },
        [71002002] = {
          ContentKR = "<H>고양이</>를 잃어버렸어요... 혹시 찾아주실 수 있나요? 분명 이 근처 어딘가에 있을 거예요...",
          DialogueId = 71002002,
          GUID = "B1BEFDF4",
          SpeakNpcId = 818017,
          Subtitle = "Could you help me look for my cat? He should still be around here somewhere..."
        },
        [71002003] = {
          ContentKR = "('제리'는 몸을 웅크린 채 바닥에 붙어 꼼짝하지 않는다. 사람의 손길을 몹시 두려워하는 눈치다.)",
          DialogueId = 71002003,
          GUID = "B1BEFE1E",
          SpeakNpcId = 800006,
          Subtitle = "(You soon spot a small cat curled up on the ground, trembling. He looks terrified of human contact.)"
        },
        [71002004] = {
          ContentKR = "제리, 돌아왔구나! 다행이야! 제리를 찾아 주셔서 정말 고맙습니다!",
          DialogueId = 71002004,
          GUID = "B1BEFE48",
          NextDialogue = 71002005,
          SpeakNpcId = 818018,
          Subtitle = "Oh, Jerry, there you are! Thank you so much!"
        },
        [71002005] = {
          ContentKR = "(소녀는 제리를 꼭 껴안고 기쁨에 겨워 뺨을 비빈다. 당신은 고양이가 발버둥 치는 모습을 못 본 척하며 조용히 보상을 챙기고 자리를 떠난다.)",
          DialogueId = 71002005,
          GUID = "B1BEFE72",
          SpeakNpcId = 800006,
          Subtitle = "(The girl scoops Jerry into her arms and buries him in kisses. You try not to notice the poor thing wriggling in panic as you quietly accept your reward and slip away.)"
        },
        [71002006] = {
          ContentKR = "못 찾았다고요... 됐어요! 아무 데나 돌아다니는 고양이는 제리가 아니에요. 엄마한테 말 잘 듣는 다른 고양이를 데려와 달라고 해야겠어요!",
          DialogueId = 71002006,
          GUID = "B1BEFE9C",
          SpeakNpcId = 818018,
          Subtitle = "You couldn't find him either...? Tch, whatever. I don't want a scruffy stray to be my Jerry anyway. I'll just have Mum get me a better cat — even cuter and well-behaved!"
        },
        [71002007] = {
          ContentKR = "정말 고마워요! 제리야... 우리 제리...",
          DialogueId = 71002007,
          GUID = "B1BEFEC6",
          SpeakNpcId = 818017,
          Subtitle = "Thank you! Oh, Jerry... please be okay..."
        },
        [71002101] = {
          ContentKR = "아, {nickname}!! 구세주가 멀리 있는 게 아니었어. 제발 좀 도와줘!",
          DialogueId = 71002101,
          GUID = "B1BF0E32",
          SpeakNpcId = 818007,
          Subtitle = "! Thank goodness you're here! I need your help!"
        },
        [71002102] = {
          ContentKR = "이거 눈물의 호수에 있는 동료한테 전달해야 하는데, 갑자기 배가 너무 아파서... 대신 전달해 줄 수 있어? 제발!",
          DialogueId = 71002102,
          GUID = "B1BF0E5C",
          SpeakNpcId = 818007,
          Subtitle = "I was supposed to deliver this crate of supplies to my colleagues across the Lamenting Lake, but I've suddenly got this terrible stomachache. Could you deliver it for me? Please, I'm begging you!"
        },
        [71002103] = {
          ContentKR = "안녕하세요, 이건 케빈이 전달을 부탁한 물자입니다.",
          DialogueId = 71002103,
          GUID = "B1BF0E86",
          NextDialogue = 71002104,
          SpeakNpcId = 100001,
          Subtitle = "Hello, Kevin asked me to bring these supplies to you."
        },
        [71002104] = {
          ContentKR = "음... 뭔가 이상한데요. 탄창 2개와 소총 1정이 부족한데, 말해보세요. 당신이 몰래 가져간 거죠!",
          DialogueId = 71002104,
          GUID = "B1BF0EB0",
          SpeakNpcId = 818008,
          Subtitle = "Wait a minute... The crate is missing two clips and a rifle. You took them, didn't you?"
        },
        [71002105] = {
          ContentKR = "제국의 재산을 횡령했군. 나와 함께 가자!",
          DialogueId = 71002105,
          GUID = "B1BF0EDA",
          SpeakNpcId = 818008,
          Subtitle = "Embezzling imperial property is a serious offence. You're coming with me!"
        },
        [71002106] = {
          ContentKR = "엥?? 내가 화장실 좀 다녀온 사이에 무슨 일이 일어난 거야!",
          DialogueId = 71002106,
          GUID = "B1BF0F04",
          NextDialogue = 71002107,
          SpeakNpcId = 818007,
          Subtitle = "Whoa! I was in the bathroom for a minute, and you're already at each other's throats!"
        },
        [71002107] = {
          ContentKR = "저쪽이 먼저 시작했어요.",
          DialogueId = 71002107,
          GUID = "B1BF0F2E",
          NextDialogue = 71002108,
          SpeakNpcId = 100001,
          Subtitle = "They started it."
        },
        [71002108] = {
          ContentKR = "이런 사람을 어떻게 구했냐, 군단의 물자까지 감히 훔치려 들다니.",
          DialogueId = 71002108,
          GUID = "B1BF0F58",
          NextDialogue = 71002109,
          SpeakNpcId = 818008,
          Subtitle = "Look what this crook did — even had the nerve to steal legion supplies!"
        },
        [71002109] = {
          ContentKR = "엥? 아! 탄창 2개랑 소총 1정? 여기 있어, 여기. 내 몫은 미리 챙겼거든.",
          DialogueId = 71002109,
          GUID = "B1BF0F82",
          NextDialogue = 71002110,
          SpeakNpcId = 818007,
          Subtitle = "Huh? Oh, you mean two clips and a rifle? That's on me. I already took my share earlier."
        },
        [71002110] = {
          ContentKR = "너무 경솔했잖아요. 군단 물자를 지나가는 사람한테 맡기다니? 만약 동맹 놈들이었으면 어쩔 뻔했어요?",
          DialogueId = 71002110,
          GUID = "B1BF0FAC",
          NextDialogue = 71002111,
          SpeakNpcId = 818008,
          Subtitle = "You're unbelievable! How could you just hand over legion supplies to a random stranger? {性别:He|She} could've been one of The Forsakens!"
        },
        [71002111] = {
          ContentKR = "아하하, 미안 미안. 다음부턴 조심할게, 진짜로!",
          DialogueId = 71002111,
          GUID = "B1BF0FD6",
          NextDialogue = 71002112,
          SpeakNpcId = 818007,
          Subtitle = "Ah, sorry, my bad! Lesson learned — won't happen again!"
        },
        [71002112] = {
          ContentKR = "{nickname}, 이거라도 받아줘. 괜히 너까지 휘말리게 해서 미안해.",
          DialogueId = 71002112,
          GUID = "B1BF1000",
          Scripts = "TurnTo{TurnToDescription{\"818007:n(0)\"}}",
          SpeakNpcId = 818007,
          Subtitle = "Here, . Take this as an apology. Sorry for dragging you into this mess."
        },
        [71002113] = {
          ContentKR = "시간을 끌면서 도망치려고? 모두, 이 자식 못 도망가게 잘 지켜봐.",
          DialogueId = 71002113,
          GUID = "B1BF102A",
          SpeakNpcId = 818008,
          Subtitle = "Trying to stall and slip away, huh? Everyone, keep a close eye on this kid. Don't let {性别:him|her} get away."
        },
        [71002114] = {
          ContentKR = "휴, 죽는 줄 알았네. 미안 내가 좀 늦었지?",
          DialogueId = 71002114,
          GUID = "B1BF1054",
          NextDialogue = 71002115,
          SpeakNpcId = 818007,
          Subtitle = "I'm back!"
        },
        [71002115] = {
          ContentKR = "뭐? 물자가 모자라? 아! 탄창 2개랑 소총 1정? 여기 있어. 내 몫이라 미리 챙겨놨거든.",
          DialogueId = 71002115,
          GUID = "B1BF107E",
          NextDialogue = 71002116,
          SpeakNpcId = 818007,
          Subtitle = "Huh? Missing supplies? Oh, you mean two clips and a rifle, right? That's on me. I already took my share earlier."
        },
        [71002116] = {
          ContentKR = "너무 경솔했잖아요. 군단 물자를 지나가는 사람한테 맡기다니? 만약 동맹 놈들이었으면 어쩔 뻔했어요?",
          DialogueId = 71002116,
          GUID = "B1BF10A8",
          NextDialogue = 71002117,
          SpeakNpcId = 818008,
          Subtitle = "You're unbelievable! How could you just hand over legion supplies to a random stranger? {性别:He|She} could've been one of The Forsakens!"
        },
        [71002117] = {
          ContentKR = "아하하, 미안 미안. 다음부턴 조심할게, 진짜로!",
          DialogueId = 71002117,
          GUID = "B1BF10D2",
          NextDialogue = 71002118,
          SpeakNpcId = 818007,
          Subtitle = "Ah, sorry, my bad! Lesson learned — won't happen again!"
        },
        [71002118] = {
          ContentKR = "{nickname}, 이거라도 받아줘. 괜히 너까지 휘말리게 해서 미안해.",
          DialogueId = 71002118,
          GUID = "B1BF10FC",
          Scripts = "TurnTo{TurnToDescription{\"818007:n(0)\"}}",
          SpeakNpcId = 818007,
          Subtitle = "Here, . Take this as an apology. Sorry for dragging you into this mess."
        },
        [71002201] = {
          ContentKR = "아흑... 일하기 싫어... 진짜 너무너무너무 일하기 싫다...",
          DialogueId = 71002201,
          GUID = "B1BF1E9A",
          SpeakNpcId = 818019,
          Subtitle = "Ugh... I really, really don't feel like working today..."
        },
        [71002202] = {
          ContentKR = "에휴... 사장님은 입만 열면 \"은빛 평화 식당의 맛을 모든 가정에!\"라시지만... 정작 고생은 누가 해? 이 배달원들이잖아...",
          DialogueId = 71002202,
          GUID = "B1BF1EC4",
          NextDialogue = 71002203,
          SpeakNpcId = 818019,
          Subtitle = "The boss and his \"brilliant\" ideas again. \"Bringing Silverpeace flavours to every household,\" he says. Did he ever stop to think about us poor delivery grunts!?"
        },
        [71002203] = {
          ContentKR = "내가 도와줄까?",
          DialogueId = 71002203,
          GUID = "B1BF1EEE",
          NextDialogue = 71002204,
          SpeakNpcId = 100001,
          Subtitle = "Need a hand?"
        },
        [71002204] = {
          ContentKR = "응! 제발! 진짜 누가 대신 공짜로 일 좀 해주면 좋겠어... 근데 그런 천사가 세상에 어딨겠어. 하...",
          DialogueId = 71002204,
          GUID = "B1BF1F18",
          NextDialogue = 71002205,
          SpeakNpcId = 818019,
          Subtitle = "Desperately! Ideally, someone to cover my shift — for free. But hey, when does that ever happen?"
        },
        [71002205] = {
          ContentKR = "네가 도와준다고 해도... 내가 해줄 수 있는 건 진짜 고맙다는 말이랑... 눈물의 호수 물이나 펑펑 마시게 해주는 정도야...",
          DialogueId = 71002205,
          GUID = "B1BF1F42",
          SpeakNpcId = 818019,
          Subtitle = "If you're really up for it, mind carrying a few things for me? I can't pay you, but hey, I'll treat you to all the water you can drink by Lamenting Lake."
        },
        [71002206] = {
          ContentKR = "오? 이 루나 맛있는 거 많이 들었네? 얘들아, 오늘 우리 한 끼 거하게 먹겠는데?",
          DialogueId = 71002206,
          GUID = "B1BF1F6C",
          NextDialogue = 71002207,
          SpeakNpcId = 818057,
          Subtitle = "Oi! Look what we've got here — someone carrying a feast. Lucky day, boys!"
        },
        [71002207] = {
          ContentKR = "안 돼! 이거 못 배달하면 내 월급 싹 날아간다고!!",
          DialogueId = 71002207,
          GUID = "B1BF1F96",
          NextDialogue = 71002208,
          SpeakNpcId = 818019,
          Subtitle = "No! These are for customers! If they don't get their food, my whole day's pay goes poof!"
        },
        [71002208] = {
          ContentKR = "그게 우리랑 뭔 상관인데? 그냥 내놔!",
          DialogueId = 71002208,
          GUID = "B1BF1F97",
          NextDialogue = 71002209,
          SpeakNpcId = 818057,
          Subtitle = "Not our problem. Now hand it over."
        },
        [71002209] = {
          ContentKR = "손 떼!!",
          DialogueId = 71002209,
          GUID = "B1BF1F98",
          SpeakNpcId = 100001,
          Subtitle = "Back off."
        },
        [71002210] = {
          ContentKR = "휴— 국물 안 쏟아서 다행이다... 빨리 다시 배달 가자...",
          DialogueId = 71002210,
          GUID = "B1BF1FC0",
          SpeakNpcId = 818019,
          Subtitle = "Whew... thank goodness the soup didn't spill. C'mon, let's finish this delivery before anything else goes wrong..."
        },
        [71002211] = {
          ContentKR = "됐다! 이제 한 건 남았어... 진짜, 사장님은 맨날 이상한 아이디어만 생각하신다니까...",
          DialogueId = 71002211,
          GUID = "B1BF20BC",
          SpeakNpcId = 818019,
          Subtitle = "That's another one down! One more to go... Seriously, can't the boss go five minutes without a \"visionary new idea\"?"
        },
        [71002212] = {
          ContentKR = "대체 이런 잡동사니를 누가 길 한가운데 쌓아둔 거야?! 아 진짜! 오늘따라 정말 되는 일이 하나도 없네!",
          DialogueId = 71002212,
          GUID = "B1BF1FEA",
          NextDialogue = 71002218,
          SpeakNpcId = 818019,
          Subtitle = "Ugh — what is all this stuff!? Who even leaves this kind of mess in the middle of the road!?"
        },
        [71002213] = {
          ContentKR = "음식은 네가 잘 들고 있어. 이건 내가 치울게.",
          DialogueId = 71002213,
          GUID = "B1BF2014",
          SpeakNpcId = 100001,
          Subtitle = "Here. You hold the food. I'll clear the path."
        },
        [71002214] = {
          ContentKR = "헉, 다 치웠다! 시간 아직 남았어! 얼른얼른얼른~!!",
          DialogueId = 71002214,
          GUID = "B1BF2015",
          SpeakNpcId = 818019,
          Subtitle = "Wait — you cleared it all? We can still make it! GO GO GO!"
        },
        [71002215] = {
          ContentKR = "휴... 드디어 다 배달했다... 너 없었으면 이번 달 월급 진짜 하나도 못 받을 뻔했다니까... 후우... 좀 쉬었으니, 다시 일하러 가야지...",
          DialogueId = 71002215,
          GUID = "B1BF203E",
          NextDialogue = 71002216,
          SpeakNpcId = 818019,
          Subtitle = "Phew... all delivered. If it weren't for you, I wouldn't have earned a single coin today. Okay... break's over. Time to get back to work."
        },
        [71002216] = {
          ContentKR = "아까는 일 그만두겠다며?",
          DialogueId = 71002216,
          GUID = "B1BF2068",
          NextDialogue = 71002217,
          SpeakNpcId = 100001,
          Subtitle = "Weren't you just quitting?"
        },
        [71002217] = {
          ContentKR = "(배달원 루나는 몸에 묻은 먼지를 툭툭 털어내고는 말없이 돌아섰다. 돌아서며 내쉰 그 한숨 속에 모든 대답이 담겨 있었다.)",
          DialogueId = 71002217,
          GUID = "B1BF2092",
          SpeakNpcId = 800006,
          Subtitle = "(The Lunodeliverer brushes off her coat and walks away. The only answer is a long, weary sigh tossed over her shoulder.)"
        },
        [71002218] = {
          ContentKR = "못 해, 못 해, 진짜 못 해!! 사장님한테 당장 말해야지! 이딴 일 못 하겠다고!!",
          DialogueId = 71002218,
          GUID = "B1BF1FEB",
          NextDialogue = 71002213,
          SpeakNpcId = 818019,
          Subtitle = "That's it! I quit! I'm going back to tell the boss I'm DONE with this nonsense!"
        },
        [71002301] = {
          ContentKR = "으윽... 방금 거, 혹시 망가진 건 아니겠지...?",
          DialogueId = 71002301,
          GUID = "B1BF2F02",
          SpeakNpcId = 818020,
          Subtitle = "Oof... Please tell me I didn't just break it..."
        },
        [71002302] = {
          ContentKR = "누구야?!",
          DialogueId = 71002302,
          GUID = "B1BF2F2C",
          NextDialogue = 71002303,
          SpeakNpcId = 818020,
          Subtitle = "Who's there!?"
        },
        [71002303] = {
          ContentKR = "아, 흐흠... 그냥 지나가던 월석 사냥꾼이구나. 저기, 잠깐만 도와줄래? 이 장비가 잘 작동하는지만 테스트해 주면 돼. 진짜 쉬워! 물론 보수도 챙겨줄게.",
          DialogueId = 71002303,
          GUID = "B1BF2F56",
          SpeakNpcId = 818020,
          Subtitle = "Oh... just a passing Phoxhunter. Ahem... Say, how about lending me a hand? Just help me test this thing. It won't bite, promise! I'll even toss you a reward for the trouble."
