        },
        [71003207] = {
          ContentKR = "(돌무더기를 치우는 중에 유용한 물자를 발견했다. 잘 챙겨두자.)",
          DialogueId = 71003207,
          GUID = "B1BFC3A6",
          SpeakNpcId = 800006,
          Subtitle = "(Amid the rubble, you spot a few salvageable supplies. No point leaving them behind.)"
        },
        [71003501] = {
          ContentKR = "(멀리서 반짝이는 무언가가 당신의 시선을 끈다. 가까이 가서 확인해 보자.)",
          DialogueId = 71003501,
          GUID = "B1BFF3E2",
          SpeakNpcId = 800006,
          Subtitle = "(Something glittering in the distance catches your eye. Might be worth a closer look.)"
        },
        [71003502] = {
          ContentKR = "내가 말했지? 이 깨진 거울에 이끌려 월석 사냥꾼이 제 발로 찾아올 거라고! 공격해!",
          DialogueId = 71003502,
          GUID = "B1BFF40C",
          SpeakNpcId = 818028,
          Subtitle = "Hah! Knew that shiny scrap would reel in a Phoxhunter! Get 'em!"
        },
        [71003504] = {
          ContentKR = "그만... 그만해요! 저희... 다시는 안 그럴게요...",
          DialogueId = 71003504,
          GUID = "B1BFF460",
          SpeakNpcId = 818028,
          Subtitle = "Alright, alright — we're sorry! We won't do it again... We promise...!"
        },
        [71003601] = {
          ContentKR = "(날카로운 경보가 사방에서 울려 퍼지며, 수많은 자기 폭풍 드론들이 몰려든다.)",
          DialogueId = 71003601,
          GUID = "B1C0044A",
          SpeakNpcId = 800006,
          Subtitle = "(Sudden sirens rip through the silence. A swarm of Magnetix Drones surges towards you.)"
        },
        [71003602] = {
          ContentKR = "(경보음이 점점 더 커지고, 적들의 수는 계속 늘어난다.)",
          DialogueId = 71003602,
          GUID = "B1C00474",
          SpeakNpcId = 800006,
          Subtitle = "(The blare rises to a piercing crescendo. More enemies are closing in.)"
        },
        [71003603] = {
          ContentKR = "(경보 소리가 서서히 잦아들 무렵, 마지막 적들이 모습을 드러낸다.)",
          DialogueId = 71003603,
          GUID = "B1C0049E",
          SpeakNpcId = 800006,
          Subtitle = "(The alarm wanes — but the final wave approaches. Stand your ground.)"
        },
        [71003604] = {
          ContentKR = "(모든 적이 쓰러지고, 마침내 주변은 다시 조용해졌다.)",
          DialogueId = 71003604,
          GUID = "B1C004C8",
          SpeakNpcId = 800006,
          Subtitle = "(All threats neutralised. The last siren sputters and dies, leaving only silence behind.)"
        },
        [71003701] = {
          ContentKR = "아흑... 일하기 싫어... 진짜 너무너무너무 일하기 싫다...",
          DialogueId = 71003701,
          GUID = "B1C014B2",
          SpeakNpcId = 818019,
          Subtitle = "Ugh... I really, really don't feel like working today..."
        },
        [71003702] = {
          ContentKR = "하윽... 왜 이번엔 또 눈물의 호수로 배달이야? 좀 평범한 데서 먹으면 안 돼? 사고라도 나면 어쩌려고! 진짜 이리 뛰고 저리 뛰고 죽겠어...",
          DialogueId = 71003702,
          GUID = "B1C014DC",
          NextDialogue = 71003703,
          SpeakNpcId = 818019,
          Subtitle = "Seriously? They want food delivered all the way to Lamenting Lake? Why do people always pick the weirdest places to eat...? Do they care about safety at all? Huff... can't feel my legs..."
        },
        [71003703] = {
          ContentKR = "내가 도와줄까?",
          DialogueId = 71003703,
          GUID = "B1C014DD",
          NextDialogue = 71003704,
          SpeakNpcId = 100001,
          Subtitle = "Need a hand?"
        },
        [71003704] = {
          ContentKR = "응! 제발! 저런 귀찮은 손님들 좀 확 깨물어주고, 눈덩이도 왕창 던져줘! 다시는 이런 외진 데서 배달시키지 못하게 말이야!",
          DialogueId = 71003704,
          GUID = "B1C014DE",
          NextOptions = {
            [1] = 710037041,
            [2] = 710037042
          },
          SpeakNpcId = 818019,
          Subtitle = "YES! I need you to punch those customers — real hard! And chuck a whole blizzard of snowballs at them! Maybe then they'll stop ordering food from the middle of nowhere!",
          bForbidSkipOptions = true
        },
        [71003705] = {
          ContentKR = "휴... 이렇게 불평이라도 해야 살지. 너도 온 김에 같이 가자. 가면서 수다라도 떨면 덜 지루하니까. 가자... 일하러…",
          DialogueId = 71003705,
          GUID = "B1C01506",
          SpeakNpcId = 818019,
          Subtitle = "*sigh* Yeah, yeah, I know. Just let me blow off a little steam, alright? Since I bumped into you — why not tag along for a bit? We can chat while we walk. Might make the trip feel less... ugh. Alright then — let's hit the road."
        },
        [71003706] = {
          ContentKR = "이 얼음 조각들이 음식에 들어가면 큰일인데... 어떻게 좀 치울 방법 없으려나...",
          DialogueId = 71003706,
          GUID = "B1C01530",
          SpeakNpcId = 818019,
          Subtitle = "Ugh, all this ice — if it gets into the food, I'm doomed. There's gotta be a way to clear this mess..."
        },
        [71003707] = {
          ContentKR = "와아~ 진짜 빠르다! 음식이 아직도 따뜻해! 빨리 가자, 안 그러면 또 사장님 잔소리 폭격 온다~",
          DialogueId = 71003707,
          GUID = "B1C01656",
          SpeakNpcId = 818019,
          Subtitle = "Whoa — that was fast! The dishes are still warm! Let's get them there now before the boss starts his nag-fest again..."
        },
        [71003708] = {
          ContentKR = "으아아 살려줘! 적어도 밥은 먹고 죽자고!!",
          DialogueId = 71003708,
          GUID = "B1C0155A",
          NextDialogue = 71003709,
          SpeakNpcId = 818029,
          Subtitle = "Help! I don't wanna die on an empty stomach!!"
        },
        [71003709] = {
          ContentKR = "헉, 진짜 사고 났잖아?! 우리 가서 도와주자! 혹시 저 사람이 사장님 앞에서 나 칭찬해 주면... 사장님이 보너스 주실지도 모르잖아~ 헤헤... 헤헤헤...",
          DialogueId = 71003709,
          GUID = "B1C01584",
          SpeakNpcId = 818019,
          Subtitle = "Whoa! What did I just say!? Someone's actually in danger! Quick, let's help him! And hey, if he puts in a good word for me with the boss, maybe I'll finally get a raise... Hehe... hehehehe..."
        },
        [71003710] = {
          ContentKR = "성가신 녀석도 사라졌겠다, 따끈한 음식에 눈물의 호수 풍경까지... 완전 힐링 아니냐~?",
          DialogueId = 71003710,
          GUID = "B1C015AE",
          NextDialogue = 71003711,
          SpeakNpcId = 818024,
          Subtitle = "Phew! Pesky critters all cleared, warm food in hand, lakeside view... Ahhh, this is the life~!"
        },
        [71003711] = {
          ContentKR = "저기... 저 손님... 아직 계산 안 하셨는데...",
          DialogueId = 71003711,
          GUID = "B1C015D8",
          NextDialogue = 71003712,
          SpeakNpcId = 818019,
          Subtitle = "Um... sir, you haven't paid yet..."
        },
        [71003712] = {
          ContentKR = "응? 넌 배달부 아냐? 여기 왜 서 있어? 밥값은 다음에 너희 식당 가서 줄게.",
          DialogueId = 71003712,
          GUID = "B1C01602",
          NextDialogue = 71003713,
          SpeakNpcId = 818024,
          Subtitle = "Huh? Aren't you just a delivery Luno? Why're you still here? Just put it on my tab — I'll pay next time I'm at the restaurant."
        },
        [71003713] = {
          ContentKR = "하지만... 이러면 사장님한테 드릴 말이...",
          DialogueId = 71003713,
          Duration = 3,
          GUID = "B1C0162C",
          NextDialogue = 71003714,
          SpeakNpcId = 818019,
          Subtitle = "But... I can't just go back empty-handed... The boss's gonna yell at me..."
        },
        [71003714] = {
          ContentKR = "(당신은 모든 것을 지켜보며 조용히 다가갔다. 아무도 당신이 등 뒤에 숨긴 손으로 눈덩이를 만들고 있는 것을 눈치채지 못했다.)",
          DialogueId = 71003714,
          Duration = 4,
          GUID = "B1C0162D",
          NextDialogue = 71003715,
          SpeakNpcId = 800006,
          Subtitle = "(You've seen enough. Without a word, you follow behind. No one notices the snowball quietly forming in your hand...)"
        },
        [71003715] = {
          ContentKR = "아악! 웬 눈덩이야?! 차가워! 너무 차가워!! 아아아악!! 내 밥이! 내 밥이 물에 빠졌어!! 안 돼——!!!",
          DialogueId = 71003715,
          GUID = "B1C0162E",
          SpeakNpcId = 818024,
          Subtitle = "Aagh!! What the—!? A snowball!? It's freezing! Aaahhh!! My food — it's in the water! NOOOOO—!!"
        },
        [71003801] = {
          ContentKR = "(필토이드들이 몰려들어 통로를 가득 채우고 있다. 모두 물리쳐야 한다.)",
          DialogueId = 71003801,
          GUID = "B1C0251A",
          SpeakNpcId = 800006,
          Subtitle = "(The tunnel is infested with roaming Filthoids. Clear them out.)"
        },
        [71003802] = {
          ContentKR = "(전투 소리에 이끌려 더 많은 필토이드가 몰려온다. 계속 싸워야 한다.)",
          DialogueId = 71003802,
          GUID = "B1C02544",
          SpeakNpcId = 800006,
          Subtitle = "(The sound of battle stirs the depths — more Filthoids emerge. Hold your line.)"
        },
        [71003803] = {
          ContentKR = "(필토이드를 모두 처치했다. 이곳은 잠시나마 안전해졌다.)",
          DialogueId = 71003803,
          GUID = "B1C0256E",
          SpeakNpcId = 800006,
          Subtitle = "(The last Filthoid falls. For now, the tunnel is safe.)"
        },
        [71003901] = {
          Content = "房间中传来一股肃杀的气息，不安的预感萦绕在心头（待包装）",
          DialogueId = 71003901,
          GUID = "B1C03582",
          SpeakNpcId = 800006
        },
        [71003902] = {
          Content = "齿轮运动的声音响起，敌人正从开启的通道口中窜出（待包装）",
          DialogueId = 71003902,
          GUID = "B1C035AC",
          SpeakNpcId = 800006
        },
        [71003903] = {
          Content = "又是齿轮响动的声音，不远处的两个通道也开启了（待包装）",
          DialogueId = 71003903,
          GUID = "B1C035D6",
          SpeakNpcId = 800006
        },
        [71003904] = {
          Content = "齿轮转动，室内的全部通道均已开启，努力击杀敌人吧（待包装）",
          DialogueId = 71003904,
          GUID = "B1C03600",
          SpeakNpcId = 800006
        },
        [71003905] = {
          Content = "所有通道均已关闭，剩余的敌人将在不久后溃散（待包装）",
          DialogueId = 71003905,
          GUID = "B1C0362A",
          SpeakNpcId = 800006
        },
        [71004101] = {
          ContentKR = "(폐기된 비행선이 어느새 산속 동물들의 거대한 창고가 되어버렸다. 잘 뒤져보면 쓸만한 물자가 있을지도 모른다.)",
          DialogueId = 71004101,
          GUID = "B1C05652",
          SpeakNpcId = 800006,
          Subtitle = "(The wrecked airship looks like it's been turned into a stash by the local wildlife. There might still be something worth salvaging.)"
        },
        [71004102] = {
          ContentKR = "(물자를 뒤적거리는 소리에 적들이 몰려왔다. 그들을 물리치자.)",
          DialogueId = 71004102,
          GUID = "B1C056A6",
          SpeakNpcId = 800006,
          Subtitle = "(Your rummaging noises have attracted hostile creatures nearby. Prepare to defend yourself.)"
        },
        [71004103] = {
          ContentKR = "(적들을 물리친 지금, 방금 모은 물자들을 확인해 보자.)",
          DialogueId = 71004103,
          GUID = "B1C056D0",
          SpeakNpcId = 800006,
          Subtitle = "(With the danger cleared, you finally have time to take stock of your findings.)"
        },
        [71004201] = {
          ContentKR = "호오... 꽤 튼튼한걸?",
          DialogueId = 71004201,
          GUID = "B1C066BA",
          SpeakNpcId = 818038,
          Subtitle = "Mmm-hmm... Yep. Nice and tough..."
        },
        [71004202] = {
          ContentKR = "뭐 하는 거야?",
          DialogueId = 71004202,
          GUID = "B1C066E4",
          NextDialogue = 71004203,
          SpeakNpcId = 100001,
          Subtitle = "What are you doing?"
        },
        [71004203] = {
          ContentKR = "요즘 필토이드 생태를 연구 중인데, 혹시 죽은 필토이드 샘플 좀 구해줄 수 있어?",
          DialogueId = 71004203,
          GUID = "B1C066E5",
          NextOptions = {
            [1] = 710042031,
            [2] = 710042032
          },
          SpeakNpcId = 818038,
          Subtitle = "I'm studying the local Filthoids! Could you help me gather some specimens?"
        },
        [71004204] = {
          ContentKR = "좋아! 그럼 부탁할게! 나 혼자 계속 샘플 모으다가 진짜 죽는 줄 알았어...",
          DialogueId = 71004204,
          GUID = "B1C0670E",
          SpeakNpcId = 818038,
          Subtitle = "Brilliant! I'll leave the rest to you — my legs are jelly after crawling around all day..."
        },
        [71004205] = {
          ContentKR = "으악, 아직 살아 있는 필토이드가 남아 있었잖아! 오지 마! 내가 너희를 연구하는 거지, 너희가 나를 연구하는 게 아니라고!",
          DialogueId = 71004205,
          GUID = "B1C06738",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 818038,
          Subtitle = "Aaaah! Why are there still live ones!? I'm the researcher here — you're the sample! Not the other way round! Shoo!"
        },
        [71004206] = {
          ContentKR = "정말 고마워~ 샘플은 다 모았고, 이제 연구하러 가볼게! 다음에 또 봐!",
          DialogueId = 71004206,
          GUID = "B1C0678C",
          SpeakNpcId = 818038,
          Subtitle = "Thanks a bunch! That wraps up my samples. Back to the lab I go — see you around!"
        },
        [71004301] = {
          ContentKR = "(이 근처에선 예쁜 조개껍질이 자주 보인다. 해변으로 떠밀려온 상자들을 부숴서 찾아보자.)",
          DialogueId = 71004301,
          GUID = "B1C07722",
          SpeakNpcId = 800006,
          Subtitle = "(This stretch of shoreline is known for its lovely seashells. A few crates have washed up with the tide — smash them open and see what's inside.)"
        },
        [71004302] = {
          ContentKR = "(상자 밑에 깔려 있던 조개껍질을 발견했다.)",
          DialogueId = 71004302,
          GUID = "B1C0774C",
          SpeakNpcId = 800006,
          Subtitle = "(Among the debris, you uncover a few intact shells.)"
        },
        [71004303] = {
          ContentKR = "(어두운 상자 속에 필토이드가 숨어 있다가 사람을 습격한다는 얘기를 들은 적 있지만, 이번엔 그 불운이 당신 차례다. 놈들을 처치하고, 마땅한 전리품을 챙기자.)",
          DialogueId = 71004303,
          GUID = "B1C07776",
          SpeakNpcId = 800006,
          Subtitle = "(Tales speak of Filthoids hiding in crates to ambush the unwary. Looks like this batch picked the wrong target. Deal with them and claim your prize.)"
        },
        [71004401] = {
          ContentKR = "(주변이 필토이드들로 가득하다. 처치하고 마령을 포획하자.)",
          DialogueId = 71004401,
          GUID = "B1C0878A",
          SpeakNpcId = 800006,
          Subtitle = "(The area is swarming with Filthoids. Clear them out to save the Geniemon.)"
        },
        [71004402] = {
          ContentKR = "(격렬한 전투 소리에 이끌려 불굴의 재앙, 불길한 화신이 모습을 드러냈다. 지금까지 그래왔듯, 이번에도 반드시 쓰러뜨려야 한다.)",
          DialogueId = 71004402,
          GUID = "B1C087B4",
          SpeakNpcId = 800006,
          Subtitle = "(The sound of battle draws an indomitable calamity — the avatar of doom descends. Defeat it, just as you have countless times before.)"
        },
        [71004403] = {
          ContentKR = "(주변이 잠시 안전해졌다. 지금이 마령을 포획할 기회다.)",
          DialogueId = 71004403,
          GUID = "B1C087DE",
          SpeakNpcId = 800006,
          Subtitle = "(The area is secure for now. You've saved the Geniemon!)"
        },
        [71004501] = {
          ContentKR = "(회수할 물자 앞을 적들이 가로막고 있다. 모두 처치하자.)",
          DialogueId = 71004501,
          GUID = "B1C097F2",
          SpeakNpcId = 800006,
          Subtitle = "(The path to the supplies is blocked. Eliminate the enemies to proceed.)"
        },
        [71004502] = {
          ContentKR = "(불길한 화신이 드디어 모습을 드러냈다. 그를 물리치고 물자를 회수하자.)",
          DialogueId = 71004502,
          GUID = "B1C0981C",
          SpeakNpcId = 800006,
          Subtitle = "(The avatar of doom descends upon the area. Defeat it to proceed.)"
        },
        [71004503] = {
          ContentKR = "(주변이 잠시 조용해졌다. 지금이 회수할 기회다.)",
          DialogueId = 71004503,
          GUID = "B1C09846",
          SpeakNpcId = 800006,
          Subtitle = "(The area is temporarily secure. Gather the supplies while you still can.)"
        },
        [71004601] = {
          ContentKR = "(앞쪽에 물자 상자가 여러 개 쌓여 있다. 열어서 유용한 것을 찾아보자.)",
          DialogueId = 71004601,
          GUID = "B1C0A85A",
          SpeakNpcId = 800006,
          Subtitle = "(A cluster of supply crates lies ahead. Might be worth a closer look.)"
        },
        [71004602] = {
          ContentKR = "(상자 안에서 쓸만한 물자를 발견했다.)",
          DialogueId = 71004602,
          GUID = "B1C0A884",
          SpeakNpcId = 800006,
          Subtitle = "(You discover a stash of valuable materials within the crate.)"
        },
        [71004603] = {
          ContentKR = "(어두운 상자 속에 필토이드가 숨어 있다가 사람을 습격한다는 얘기를 들은 적 있지만, 이번엔 그 불운이 당신 차례다. 놈들을 처치하고, 마땅한 전리품을 챙기자.)",
          DialogueId = 71004603,
          GUID = "B1C0A8AE",
          SpeakNpcId = 800006,
          Subtitle = "(Tales speak of Filthoids hiding in crates to ambush the unwary. Looks like this batch picked the wrong target. Deal with them and claim your prize.)"
        },
        [71004701] = {
          ContentKR = "(멀리서 반짝이는 무언가가 당신의 시선을 끈다. 가까이 가서 확인해 보자.)",
          DialogueId = 71004701,
          GUID = "B1C0B8C2",
          SpeakNpcId = 800006,
          Subtitle = "(Something glittering in the distance catches your eye. Might be worth a closer look.)"
        },
        [71004702] = {
          ContentKR = "(물자를 집는 순간, 경보가 울리고 적들이 몰려오기 시작했다. 그들을 물리치자.)",
          DialogueId = 71004702,
          GUID = "B1C0B8EC",
          SpeakNpcId = 800006,
          Subtitle = "(Just as you pick up the item, alarms blare to life. Hostile units are closing in — prepare for battle.)"
        },
        [71004703] = {
          ContentKR = "(경보가 꺼지자 또 다른 적들이 소리에 이끌려 도착했다. 그들을 물리치자.)",
          DialogueId = 71004703,
          GUID = "B1C0B916",
          SpeakNpcId = 800006,
          Subtitle = "(The alarm fades, but its echo draws in a second wave. Hold your ground.)"
        },
        [71004704] = {
          ContentKR = "(모든 적이 쓰러지고, 마침내 주변은 다시 조용해졌다.)",
          DialogueId = 71004704,
          GUID = "B1C0B940",
          SpeakNpcId = 800006,
          Subtitle = "(All threats neutralised. The last siren sputters and dies, leaving only silence behind.)"
        },
        [71004801] = {
          ContentKR = "(멀리서 얼음이 깨져 떨어지는 소리가 들린다. 무슨 일이 벌어졌는지 확인하러 가보자.)",
          DialogueId = 71004801,
          GUID = "B1C0C92A",
          SpeakNpcId = 800006,
          Subtitle = "(In the distance, the sharp crack of breaking ice echoes through the air. Might be worth checking out.)"
        },
        [71004802] = {
          ContentKR = "월석 사냥꾼인가? 잘 왔어. 요즘 도로 아래에 고드름이 너무 많아서 말이야. 같이 정리해 줄 수 있을까?",
          DialogueId = 71004802,
          GUID = "B1C0C954",
          NextOptions = {
            [1] = 710048021,
            [2] = 710048022
          },
          SpeakNpcId = 818039,
          Subtitle = "A Phoxhunter? Perfect timing. The icicles forming under the bridge are becoming a serious hazard. Mind lending a hand with the clearing?"
        },
        [71004803] = {
          ContentKR = "도와줘서 고마워. 저쪽 몇 개는 자네에게 맡길게.",
          DialogueId = 71004803,
          GUID = "B1C0C97E",
          SpeakNpcId = 818039,
          Subtitle = "Thanks — could you handle those ones over there?"
        },
        [71004805] = {
          ContentKR = "이제 훨씬 안전해졌군. 자, 이건 자네 보수야.",
          DialogueId = 71004805,
          GUID = "B1C0C9D2",
          SpeakNpcId = 818039,
          Subtitle = "That's much better. Appreciate it — here's a little something for your trouble."
        },
        [71004901] = {
          ContentKR = "하아... 못 건너가겠군. 미리 풀 미끼를 좀 사둘 걸 그랬어...",
          DialogueId = 71004901,
          GUID = "B1C0D992",
          SpeakNpcId = 818040,
          Subtitle = "*sigh* ...Should've stocked up on bait. Now I can't even make it across to gather more..."
        },
        [71004902] = {
          ContentKR = "거기 월석 사냥꾼, 낚시 미끼로 쓸 로터스가 필요한데, 다 건너편에 있어서 가지를 못하겠네. 자네가 좀 채집해 줄 수 있겠나?",
          DialogueId = 71004902,
          GUID = "B1C0D9BC",
          NextOptions = {
            [1] = 710049021,
            [2] = 710049022
          },
          SpeakNpcId = 818040,
          Subtitle = "Hey, Phoxhunter! I'm in a bit of a pickle — I need some Eclipta Grass for bait, but it's across the lake. Could you fetch some for me?",
          bForbidSkipOptions = true
        },
        [71004903] = {
          ContentKR = "고마워! 그럼 난 낚싯대를 세워두고 자네를 기다리겠네.",
          DialogueId = 71004903,
          GUID = "B1C0D9E6",
          SpeakNpcId = 818040,
          Subtitle = "Great! I'll get the rod ready while you're at it."
        },
        [71004905] = {
          ContentKR = "(주변에 필토이드들이 잔뜩 몰려 있다. 먼저 놈들을 물리치고 로터스를 채집하자.)",
          DialogueId = 71004905,
          GUID = "B1C0DA3A",
          SpeakNpcId = 800006,
          Subtitle = "(The shoreline is crawling with Filthoids. Best clear them out before gathering the Eclipta Grass.)"
        },
        [71004906] = {
          ContentKR = "(근처의 로터스를 전부 채집했다. 어부에게 가져다주자.)",
          DialogueId = 71004906,
          GUID = "B1C0DA64",
          SpeakNpcId = 800006,
          Subtitle = "(You collect all the usable Eclipta Grass nearby. Time to head back to the fisherman.)"
        },
        [71004907] = {
          ContentKR = "좋아좋아, 이렇게 미끼가 많으니 오늘은 반드시 한 마리 낚겠구먼!",
          DialogueId = 71004907,
          GUID = "B1C0DA8E",
          SpeakNpcId = 818040,
          Subtitle = "Perfect! With this much bait, there's no way I'm going home with an empty bucket!"
        },
        [71005001] = {
          ContentKR = "저기요~ 거기 계신 분! 사진 한 장만 찍어주실 수 있을까요?",
          DialogueId = 71005001,
          GUID = "B1C0E9FA",
          SpeakNpcId = 818041,
          Subtitle = "Hey there! Would you mind taking a photo for me?"
        },
        [71005002] = {
          ContentKR = "죄송한데, 사진 몇 장만 부탁드릴게요. 아이스레이크 시티까지 왔는데, 기념사진 하나 없이 돌아가긴 너무 아쉽잖아요.",
          DialogueId = 71005002,
          GUID = "B1C0EA24",
          NextOptions = {
            [1] = 710050021,
            [2] = 710050022
          },
          SpeakNpcId = 818041,
          Subtitle = "Hello! Would you mind taking a few photos for me? It's my first time in Icelake, and I'd hate to leave without a picture or two.",
          bForbidSkipOptions = true
        },
        [71005004] = {
          ContentKR = "정말 감사합니다! 찍으실 때 제 뒤에 있는 저 건물도 꼭 같이 담아주세요~ 제가 진짜 좋아하는 스타일이라서요!",
          DialogueId = 71005004,
          GUID = "B1C0EA78",
          SpeakNpcId = 818041,
          Subtitle = "Thank you so much! Make sure you get that lovely building behind me in the frame — love the design."
        },
        [71005005] = {
          ContentKR = "사진 정말 잘 찍으시네요! 완전 감탄했어요~ 진짜 감사해요!",
          DialogueId = 71005005,
          GUID = "B1C0EAA2",
          SpeakNpcId = 818041,
          Subtitle = "These are fantastic! You've got a real eye for this — seriously, thank you!"
        },
        [71005101] = {
          ContentKR = "물고기야~ 와라 와라~",
          DialogueId = 71005101,
          GUID = "B1C0EAA3",
          SpeakNpcId = 818045,
          Subtitle = "Come, fish. Come."
        },
        [71005102] = {
          ContentKR = "뭐 하고 계세요?",
          DialogueId = 71005102,
          GUID = "B1C0FA62",
          NextDialogue = 71005103,
          SpeakNpcId = 100001,
          Subtitle = "What are you doing?"
        },
        [71005103] = {
          ContentKR = "낚시 중이니까, 나중에 얘기해요.",
          DialogueId = 71005103,
          GUID = "B1C0FA8C",
          SpeakNpcId = 818045,
          Subtitle = "Fishing. Shh. Not now."
        },
        [71005104] = {
          ContentKR = "(옆에서 꽤 오랫동안 지켜봤지만, 남자는 여전히 한 마리도 못 낚았다.)",
          DialogueId = 71005104,
          GUID = "B1C0FA8D",
          NextDialogue = 71005105,
          SpeakNpcId = 800006,
          Subtitle = "(You wait quietly beside him. Not a single fish bites.)"
        },
        [71005105] = {
          ContentKR = "이런 식으로 해서 진짜 물고기가 잡히긴 하나요?",
          DialogueId = 71005105,
          GUID = "B1C0FAB6",
          NextDialogue = 71005106,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure this is how fishing works?"
        },
        [71005106] = {
          ContentKR = "그냥 조용히 보기만 해요.",
          DialogueId = 71005106,
          GUID = "B1C0FAE0",
          SpeakNpcId = 818045,
          Subtitle = "Silence. Just watch."
        },
        [71005107] = {
          ContentKR = "(당신은 옆에서 조용히 기다려 봤지만, 남자는 여전히 빈손이다.)",
          DialogueId = 71005107,
          GUID = "B1C0FAE1",
          NextDialogue = 71005108,
          SpeakNpcId = 800006,
          Subtitle = "(Still no catch after a long wait.)"
        },
        [71005108] = {
          ContentKR = "물고기야~ 와라 와라~",
          DialogueId = 71005108,
          GUID = "B1C0FAE2",
          NextDialogue = 71005109,
          SpeakNpcId = 818045,
          Subtitle = "Come, fish. Come."
        },
        [71005109] = {
          ContentKR = "아무리 그래도... 낚싯대는 있어야 하지 않아요? 입으로만 외친다고 물고기가 잡히진 않잖아요.",
          DialogueId = 71005109,
          GUID = "B1C0FB0A",
          NextDialogue = 71005110,
          SpeakNpcId = 100001,
          Subtitle = "You don't even have a rod. I don't think chanting's gonna land you anything."
        },
        [71005110] = {
          ContentKR = "이건 제가 수많은 사람들과 교류 끝에 얻어낸 최신 낚시 기술인데요, 무조건 크고 좋은 놈이 걸리게 돼 있어요. 못 믿겠으면 당신도 한 마리 낚아서 저랑 겨뤄봐요.",
          DialogueId = 71005110,
          GUID = "B1C0FB34",
          SpeakNpcId = 818045,
          Subtitle = "This is a technique I developed after speaking with all sorts of people. The fish I catch? Big. The biggest. You don't believe me? Fine. Catch one yourself. Let's see who's better."
        },
        [71005111] = {
          ContentKR = "전 낚았어요, 당신은요?",
          DialogueId = 71005111,
          GUID = "B1C0FB5E",
          NextDialogue = 71005112,
          SpeakNpcId = 100001,
          Subtitle = "Got one. Where's yours?"
        },
        [71005112] = {
          ContentKR = "흠... 확실히 큰 물고기네요. 하지만 제가 노리는 녀석에 비하면 아직 부족하죠.",
          DialogueId = 71005112,
          GUID = "B1C0FB88",
          NextDialogue = 71005113,
          SpeakNpcId = 818045,
          Subtitle = "Hmm. That's a big one — I'll give you that. But the one I'm after? Even bigger."
        },
        [71005113] = {
          ContentKR = "저쪽에서 로터스 냄새가 나요. 그 냄새 때문에 내 물고기들이 입질을 안 하는 거예요. 가서 그거 좀 치워주시고 다시 와봐요.",
          DialogueId = 71005113,
          GUID = "B1C0FC06",
          SpeakNpcId = 818045,
          Subtitle = "I smell Eclipta Grass nearby. Its scent is luring my fish away. Clear it out. Then we'll see."
        },
        [71005114] = {
          ContentKR = "'문제'를 해결했으니, 돌아가 보자.",
          DialogueId = 71005114,
          GUID = "B1C0FC30",
          SpeakNpcId = 100001,
          Subtitle = "The \"problem\" has been dealt with. Time to check on the strange angler."
        },
        [71005115] = {
          ContentKR = "해결했어요. 이제 물고기는 낚았나요?",
          DialogueId = 71005115,
          GUID = "B1C0FC5A",
          NextDialogue = 71005116,
          SpeakNpcId = 100001,
          Subtitle = "All done. Now — your fish?"
        },
        [71005116] = {
          ContentKR = "이미 낚았어요. 여기, 보세요.",
          DialogueId = 71005116,
          GUID = "B1C0FC84",
          NextDialogue = 71005117,
          SpeakNpcId = 818045,
          Subtitle = "Already caught it."
        },
        [71005117] = {
          ContentKR = "(남자는 당신을 가리켰다.)",
          DialogueId = 71005117,
          GUID = "B1C0FCAE",
          NextDialogue = 71005118,
          SpeakNpcId = 800006,
          Subtitle = "(He points at you.)"
        },
        [71005118] = {
          ContentKR = "낚시는 꼭 물고기만 낚는 게 아니에요. 말 몇 마디 흘리고, 이상한 짓 몇 번 하면— 미끼를 물고 스스로 달려드는 ‘물고기’는 생각보다 많거든요.",
          DialogueId = 71005118,
          GUID = "B1C0FCD8",
          NextDialogue = 71005119,
          SpeakNpcId = 818045,
          Subtitle = "Not every fish has fins, you know. Sometimes all it takes is a few cryptic words and a strange act or two... And something always bites."
        },
        [71005119] = {
          ContentKR = "그게 바로 제가 수없이 많은 사람들과 부딪치며 얻은 교훈이에요. 앞으론 누군가 던진 '미끼'에 쉽게 속지 않길 바라요.",
          DialogueId = 71005119,
          GUID = "B1C0FD02",
          NextDialogue = 71005120,
          SpeakNpcId = 818045,
          Subtitle = "That's what I learned from people. Just try not to nibble so easily next time."
        },
        [71005120] = {
          ContentKR = "괜히 오래 붙잡아서 미안해요. 이건 사과의 의미니까, 받아주세요.",
          DialogueId = 71005120,
          GUID = "B1C0FD2C",
          SpeakNpcId = 818045,
          Subtitle = "Anyway — sorry for the mischief. Here. Consider this an apology."
        },
        [71005121] = {
          ContentKR = "전 낚았어요, 당신은요?",
          DialogueId = 71005121,
          GUID = "B1C0FD56",
          NextDialogue = 71005122,
          SpeakNpcId = 100001,
          Subtitle = "Got one. Where's yours?"
        },
        [71005122] = {
          ContentKR = "흠... 확실히 큰 물고기네요. 하지만 제가 노리는 녀석에 비하면 아직 부족하죠.",
          DialogueId = 71005122,
          GUID = "B1C0FD80",
          NextDialogue = 71005123,
          SpeakNpcId = 818045,
          Subtitle = "Hmm. That's a big one — I'll give you that. But the one I'm after? Even bigger."
        },
        [71005123] = {
          ContentKR = "저쪽에서 필토이드 냄새가 나요. 그 냄새 때문에 내 물고기들이 입질을 안 하는 거예요. 가서 좀 쫓아주시고 다시 와봐요.",
          DialogueId = 71005123,
          GUID = "B1C0FDAA",
          SpeakNpcId = 818045,
          Subtitle = "I heard Filthoids nearby. They scared off my catch. Drive them off. Then we'll see."
        },
