        },
        [71007802] = {
          ContentKR = "제가 마음속 깊은 곳의 잠재의식을 발견할 수 있는 새로운 향을 하나 개발했는데, 실험에 참여해서 뭐가 보였는지 말씀해 주실 수 있을까요?",
          DialogueId = 71007802,
          GUID = "B1C2B584",
          NextOptions = {
            [1] = 710078021,
            [2] = 710078022
          },
          SpeakNpcId = 818082,
          Subtitle = "I've been working on a new incense that awakens what lies buried in the mind. Would you help me test it? Just light it, and then tell me what you see.",
          bForbidSkipOptions = true
        },
        [71007803] = {
