          DialogueId = 71007804,
          GUID = "B1C2B5D8",
          NextDialogue = 71007805,
          SpeakNpcId = 800006,
          Subtitle = "(A strange fragrance threads into your senses. Your thoughts begin to drift outward, scattering across the world around you.)"
        },
        [71007805] = {
          ContentKR = "(마음속 깊은 곳에서 질문이 하나 떠오른다. '지금 이 순간, 내가 가장 바라는 건 무엇인가?')",
