          bAllowClickSkipScript = false
        },
        [72001002] = {
          ContentKR = "벽은 막고 싶은 건 다 막을 수 있대.",
          DialogueId = 72001002,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F3864",
          NextDialogue = 72001003,
          SpeakNpcId = 820000,
          Subtitle = "The wall says it only keeps out what it wants to keep out."
        },
        [72001003] = {
          ContentKR = "하지만 막고 싶지 않은 건 다 성 안으로 들여보내!",
          DialogueId = 72001003,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F388E",
          NextDialogue = 72001004,
          SpeakNpcId = 820000,
          Subtitle = "But if it likes you... it lets you through."
