          bAllowClickSkipScript = false
        },
        [72001102] = {
          ContentKR = "이 상자가 안녕 상자인 줄 알았어. 움직이라고 한참을 설득했지.",
          DialogueId = 72001102,
          FacialId = {
            [1] = "820000:PetPan_Wink"
          },
          GUID = "B43F48CC",
          NextDialogue = 72001103,
          SpeakNpcId = 820000,
          Subtitle = "I thought this box was a Bro Boxie. I spent forever trying to talk him into moving."
        },
        [72001103] = {
          ContentKR = "그런데 아니었어, 차라리 진작에 발로 차 버릴 걸 그랬네.",
          DialogueId = 72001103,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F48F6",
          NextDialogue = 72001104,
          SpeakNpcId = 820000,
          Subtitle = "Turns out he wasn't. Maybe I should've given him a teeny kick..."
        },
        [72001104] = {
