          bAllowClickSkipScript = false
        },
        [72001202] = {
          ContentKR = "이 나무는 많이 피곤한가 봐. 땅에 누워 쉬고 있네.",
          DialogueId = 72001202,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F5934",
          NextDialogue = 72001203,
          SpeakNpcId = 820000,
          Subtitle = "This tree looks tired... It's just lying down for a nap."
        },
        [72001203] = {
          ContentKR = "그럼, 땅에 떨어진 저 눈들도 피곤해서 누워 있는 걸까?",
          DialogueId = 72001203,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F595E",
          NextDialogue = 72001204,
          SpeakNpcId = 820000,
          Subtitle = "Do you think the snow on the ground is tired too? Maybe it just wanted a little rest."
        },
        [72001204] = {
          DialogueId = 72001204,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
