          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72001302] = {
          ContentKR = "여기는 아주 따뜻해, 너도 여기 앉아 봐.",
          DialogueId = 72001302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F699C",
          NextDialogue = 72001303,
          SpeakNpcId = 820000,
          Subtitle = "It's nice and warm here. You can sit with me if you like."
        },
        [72001303] = {
          ContentKR = "하지만 너무 오래 앉아 있으면 안돼. 다른 친구들도 추울 테니까.",
          DialogueId = 72001303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F69C6",
          NextDialogue = 72001304,
          SpeakNpcId = 820000,
          Subtitle = "Just don't stay too long — my other friends might get chilly."
        },
        [72001304] = {
