          bAllowClickSkipScript = false
        },
        [72001402] = {
          ContentKR = "이 길은 막혔어, 음...",
          DialogueId = 72001402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F7A04",
          NextDialogue = 72001403,
          SpeakNpcId = 820000,
          Subtitle = "This is a dead end... mm..."
        },
        [72001403] = {
          ContentKR = "그게 아니라 내가 하고 싶은 말은, 잠시 혼자 있고 싶다는 거야. 너도 나와 함께 혼자 있고 싶어?",
          DialogueId = 72001403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F7A2E",
          NextDialogue = 72001404,
          SpeakNpcId = 820000,
          Subtitle = "Or maybe what I meant was — I want to be alone for a while. Would you like to be alone with me?"
        },
        [72001404] = {
          ContentKR = "하지만 그러면 혼자 있는 게 아니잖아.",
          DialogueId = 72001404,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F7A58",
          NextDialogue = 72001405,
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
          SpeakNpcId = 820000,
          Subtitle = "But... does that still count as being alone?",
          bAllowClickSkipScript = false
        },
        [72001405] = {
