          bAllowClickSkipScript = false
        },
        [72001502] = {
          ContentKR = "여기 집들은 다들 피곤해 보이네, 피부가 얼룩덜룩해.",
          DialogueId = 72001502,
          FacialId = {
            [1] = "820000:PetPan_Speechless"
          },
          GUID = "B43F8A6C",
          NextDialogue = 72001503,
          SpeakNpcId = 820000,
          Subtitle = "These houses look so tired. Their skin's all spotty and peeling..."
        },
        [72001503] = {
          ContentKR = "모두가 낫기를, 진심으로 바래.",
          DialogueId = 72001503,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F8A96",
          NextDialogue = 72001504,
          SpeakNpcId = 820000,
          Subtitle = "I hope they get better soon."
