          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002202] = {
          ContentKR = "난 길 위의 차들과 누가 더 빠른지 겨뤄보고 싶어.",
          DialogueId = 72002202,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43FFD44",
          NextDialogue = 72002203,
          SpeakNpcId = 820000,
          Subtitle = "I want to race the cars."
        },
        [72002203] = {
          ContentKR = "하지만 그들이 너무 빨리 달리면 미끄러질 텐데, 정말 걱정돼.",
          DialogueId = 72002203,
          FacialId = {
            [1] = "820000:PetPan_Wink"
          },
          GUID = "B43FFD6E",
          NextDialogue = 72002204,
          SpeakNpcId = 820000,
          Subtitle = "But what if they go too fast and slip? I'd feel bad for them..."
        },
        [72002204] = {
          DialogueId = 72002204,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43FFD98",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72002301] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72002301,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400D82",
          NextDialogue = 72002302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002302] = {
          ContentKR = "꽃들은 모두 착해서, 그 애들을 받은 사람들은 모두 행복해질 거야.",
          DialogueId = 72002302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DAC",
          NextDialogue = 72002303,
          SpeakNpcId = 820000,
          Subtitle = "Flowers are so kind. They always make people smile."
        },
        [72002303] = {
          ContentKR = "이 꽃들이 우리 몰래, 꽃을 받은 사람과 속삭이는 게 아닐까?",
          DialogueId = 72002303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DD6",
          NextDialogue = 72002304,
          SpeakNpcId = 820000,
          Subtitle = "Do you think they whisper little secrets to them when we're not looking?"
        },
        [72002304] = {
          DialogueId = 72002304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400E00",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72002401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72002401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4401DEA",
          NextDialogue = 72002402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002402] = {
          ContentKR = "그런 생각 해 봤어? 누군가, 예를 들면 신이라고 불리는 대단한 사람이, 눈물의 호수를 통째로 들어올려서 사탕처럼 먹어버리는 거.",
          DialogueId = 72002402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4401E14",
          NextDialogue = 72002403,
          SpeakNpcId = 820000,
          Subtitle = "Do you think... someone super strong — like a god, maybe — could pick up the whole Lamenting Lake and eat it like candy?"
        },
        [72002403] = {
          ContentKR = "눈물의 호수는 어떤 맛일까? 파란색이니까 아마 하늘과 같은 맛일지도 몰라.",
          DialogueId = 72002403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4401E3E",
          NextDialogue = 72002404,
          SpeakNpcId = 820000,
          Subtitle = "I wonder what it tastes like. It's blue, so... maybe it tastes like the sky?"
        },
        [72002404] = {
          DialogueId = 72002404,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4401E68",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72002501] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72002501,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4402E52",
          NextDialogue = 72002502,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002502] = {
          ContentKR = "그 꽃을 데리고 가는 거야? 그 애가 정말 기뻐할 거야.",
          DialogueId = 72002502,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4402E7C",
          NextDialogue = 72002503,
          SpeakNpcId = 820000,
          Subtitle = "Are you taking this flower with you? She'll be really happy."
        },
        [72002503] = {
          ContentKR = "이렇게 하면, 그 애가 다른 곳에 가서도 구경할 수 있겠네.",
          DialogueId = 72002503,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4402EA6",
          NextDialogue = 72002504,
          SpeakNpcId = 820000,
          Subtitle = "Because now she gets to go on a little trip."
        },
        [72002504] = {
          DialogueId = 72002504,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4402ED0",
