          },
          GUID = "B4403EBA",
          NextDialogue = 72002602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002602] = {
          ContentKR = "흠흠, 집을 지어줘서 고마워.",
          DialogueId = 72002602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403EE4",
          NextDialogue = 72002603,
          SpeakNpcId = 820000,
          Subtitle = "Mm~ Thank you for building a cabin for me."
        },
        [72002603] = {
          ContentKR = "언젠가 네가 나만큼 크게 자라면, 너를 초대할게. 우리 이웃이 되자.",
          DialogueId = 72002603,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403F0E",
          NextDialogue = 72002604,
          SpeakNpcId = 820000,
          Subtitle = "If you ever grow as tall as me, you can move in too — and we'll be neighbours."
        },
        [72002604] = {
          DialogueId = 72002604,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
