          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002702] = {
          ContentKR = "어디로 가는 거야?",
          DialogueId = 72002702,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4404F4C",
          NextDialogue = 72002703,
          SpeakNpcId = 820000,
          Subtitle = "Where are you off to?"
        },
        [72002703] = {
          ContentKR = "만약 그 유리 조각 같은 사람을 만나면, 꼭 그녀와 친구가 되어 줘.",
          DialogueId = 72002703,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4404F76",
          NextDialogue = 72002704,
          SpeakNpcId = 820000,
          Subtitle = "If you see that human who looks like a piece of broken glass... try to be her friend, okay?"
        },
        [72002704] = {
          DialogueId = 72002704,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
