          bAllowClickSkipScript = false
        },
        [72002802] = {
          ContentKR = "딩딩당당, 딩딩당당.",
          DialogueId = 72002802,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4405FB4",
          NextDialogue = 72002803,
          SpeakNpcId = 820000,
          Subtitle = "Ding ding ding~! Clink clink clink!"
        },
        [72002803] = {
          ContentKR = "병들이 이렇게 노래하는 거야. 내가 잘 따라 한 건지?",
          DialogueId = 72002803,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4405FDE",
          NextDialogue = 72002804,
          SpeakNpcId = 820000,
          Subtitle = "That's how the bottles sing! ...Well? Did I get it right?"
        },
        [72002804] = {
          DialogueId = 72002804,
          DialoguePanelType = "AllHide",
