          },
          GUID = "B44090EB",
          NextDialogue = 72003102,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003102] = {
          ContentKR = "뭘 찾는 거야?",
          DialogueId = 72003102,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B44090EC",
          NextDialogue = 72003103,
          SpeakNpcId = 820000,
          Subtitle = "What are you looking for?"
        },
        [72003103] = {
          ContentKR = "날 찾는 게 아니라면, 내가 찾는걸 도와줄게.",
          DialogueId = 72003103,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4409116",
          NextDialogue = 72003104,
          SpeakNpcId = 820000,
          Subtitle = "If you're not looking for me, I can help."
        },
        [72003104] = {
          DialogueId = 72003104,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4409140",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72003301] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72003301,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B192",
          NextDialogue = 72003302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003302] = {
          ContentKR = "많은 사람들이 왔다가, 또 많은 사람들이 떠났어.",
          DialogueId = 72003302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B1BC",
          NextDialogue = 72003303,
          SpeakNpcId = 820000,
          Subtitle = "So many people came, and so many left."
        },
        [72003303] = {
          ContentKR = "냄새가 너무 많아서 기억할 수가 없어... 넌 기억할 수 있어?",
          DialogueId = 72003303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B1E6",
          NextDialogue = 72003304,
          SpeakNpcId = 820000,
          Subtitle = "So many scents lingering... I can't remember them all. Can you?"
        },
        [72003304] = {
          DialogueId = 72003304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B210",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72003401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72003401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C223",
          NextDialogue = 72003402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003402] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "여기가 내 보물 창고야! 지혜의 시험을 통과해야 들어올 수 있어!",
          DialogueId = 72003402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C224",
          NextDialogue = 72003403,
          SpeakNpcId = 820000,
          Subtitle = "This is my treasure trove! Only those who pass the trial of wisdom may enter!"
        },
        [72003403] = {
          ContentKR = "이 요새를 통과할 수 있는 색은 어떤 색일까!",
          DialogueId = 72003403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C24E",
          SpeakNpcId = 820000,
          Subtitle = "So tell me — here, in this fortress... What colour lets you through?",
          TalkOptions = {
            [1] = 72003404,
            [2] = 72003405,
            [3] = 72003406
          }
        },
        [72003404] = {
          ContentKR = "파란색!",
          DialogueId = 72003404,
          GUID = "B440C278",
          ImprPlusId = 1003,
          Subtitle = "Blue!"
        },
        [72003405] = {
          ContentKR = "빨간색!",
          DialogueId = 72003405,
          GUID = "B440C2A2",
          ImprPlusId = 1016,
          Subtitle = "Red!"
        },
        [72003406] = {
          ContentKR = "주황색!",
          DialogueId = 72003406,
          GUID = "B440C2CC",
          ImprPlusId = 1016,
          Subtitle = "Orange!"
        },
        [72003407] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아! 통과할 수 있는 색을 골랐네! 그러니까 통과시켜줄게!",
          DialogueId = 72003407,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C2F6",
          NextDialogue = 72003409,
          SpeakNpcId = 820000,
          Subtitle = "That's right! You picked the right colour — so in you go!"
        },
