          },
          GUID = "B44186DA",
          NextDialogue = 72004602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72004602] = {
          ContentKR = "야하, 내 비밀 기지를 찾아냈구나, 축하해!",
          DialogueId = 72004602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4418704",
          NextDialogue = 72004603,
          SpeakNpcId = 820000,
          Subtitle = "Ta-daa! Congrats on finding my secret base!"
        },
        [72004603] = {
          ContentKR = "여긴 덩굴, 수초, 연못, 그리고 나만의 아주 작은 생태계야.",
          DialogueId = 72004603,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B441872E",
          NextDialogue = 72004604,
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 820000,
          Subtitle = "The vines, the water plants, the pond, and me... we're our own little ecosystem!",
          bAllowClickSkipScript = false
        },
        [72004604] = {
          DialogueId = 72004604,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4418758",
