          bAllowClickSkipScript = false
        },
        [72100101] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100101,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EBAD2",
          NextDialogue = 72100102,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100102] = {
          ContentKR = "허명을 씻어내면 마음이 보이느니, 하늘의 달은 본래 티끌 없이 맑은 법.",
          DialogueId = 72100102,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EBAFC",
          NextDialogue = 72100103,
          SpeakNpcId = 830001,
          Subtitle = [[
Strip away the fleeting fame, and the true heart is revealed.
Untouched by worldly dust, its original clarity remains.]]
        },
        [72100103] = {
          ContentKR = "멀리서 찾아온 친구! 화려한 치장을 걷어내면, 자신의 본심이 환하게 드러날 거야.",
          DialogueId = 72100103,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EBB26",
          NextDialogue = 72100104,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Traveler from afar, as you brush aside the blossoms of your past, have you glimpsed your own bright and clear heart?",
          bAllowClickSkipScript = false
        },
        [72100104] = {
          DialogueId = 72100104,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EBB50",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100201] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100201,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB3A",
          NextDialogue = 72100202,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100202] = {
          ContentKR = "아주 긴 꿈을 꾼 것 같아...",
          DialogueId = 72100202,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB64",
          NextDialogue = 72100203,
          SpeakNpcId = 830001,
          Subtitle = "Feels like I had a long, beautiful dream..."
        },
        [72100203] = {
          ContentKR = "꿈에서 어머니를 봤어. 어린 내 손을 잡고 나루터에 가서 설탕엿을 사 주셨지.",
          DialogueId = 72100203,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB8E",
          NextDialogue = 72100204,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I dreamed of when I was a child, holding my mother's hand, going to the wharf to buy a sugar figurine.",
          bAllowClickSkipScript = false
        },
        [72100204] = {
          DialogueId = 72100204,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECBB8",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100301] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100301,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EDBA2",
          NextDialogue = 72100302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100302] = {
          ContentKR = "해한테 붙잡히게 생겼어! 다 너 때문이야! 너 때문에 해한테 붙잡히게 됐잖아!",
          DialogueId = 72100302,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EDBCC",
          NextDialogue = 72100303,
          SpeakNpcId = 830001,
          Subtitle = "The sun's gonna catch me! It's all your fault — I‘ve been caught by the sun!"
        },
        [72100303] = {
          ContentKR = "으... 해한테 잡히느니 차라리 너한테 잡히는 게 나을지도...",
          DialogueId = 72100303,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EDBF6",
          NextDialogue = 72100304,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Hmm... I'd rather be caught by you than by the sun...",
          bAllowClickSkipScript = false
        },
        [72100304] = {
          DialogueId = 72100304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EDC20",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC0A",
          NextDialogue = 72100402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100402] = {
          ContentKR = "공기 중에 떠도는 이 향은 무슨 향이지? 고창인가? 아니면 춘일품?",
          DialogueId = 72100402,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC34",
          NextDialogue = 72100403,
          SpeakNpcId = 830001,
          Subtitle = "What's that scent drifting on the air? Sky Lily? Or perhaps Vernal Prime?"
        },
        [72100403] = {
          ContentKR = "내가 만든 향이 훨씬 나은데! 하지만 이젠 만들 수가 없으니 아쉽네.",
          DialogueId = 72100403,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC5E",
          NextDialogue = 72100404,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Not as good as my own blend. A pity... I can't make it anymore.",
          bAllowClickSkipScript = false
        },
        [72100404] = {
          DialogueId = 72100404,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC88",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100501] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100501,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFC72",
          NextDialogue = 72100502,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100502] = {
          ContentKR = "우리 아들! 잘 지내고 있는 거지?",
          DialogueId = 72100502,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFC9C",
          NextDialogue = 72100503,
          SpeakNpcId = 830001,
          Subtitle = "Liang Qing, my child! Are you well?"
        },
        [72100503] = {
          ContentKR = "으응? 우리 아들이 아니잖아? 넌 누구...?",
          DialogueId = 72100503,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFCC6",
          NextDialogue = 72100504,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Oh? Not my child? Then who... are you?",
          bAllowClickSkipScript = false
        },
        [72100504] = {
          DialogueId = 72100504,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFCF0",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100601] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100601,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0CDA",
          NextDialogue = 72100602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100602] = {
          ContentKR = "저 높은 나무를 타고 하늘 높이 오르면, 태호 님 가까이 갈 수 있을까요?",
          DialogueId = 72100602,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D04",
          NextDialogue = 72100603,
          SpeakNpcId = 830001,
          Subtitle = "If I climb a tall tree all the way up, can I get closer to Lord Taihao?"
        },
        [72100603] = {
          ContentKR = "근데 얼마나 올라야 하죠? 십 년? 백 년? 그걸로 될까요?",
          DialogueId = 72100603,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D2E",
          NextDialogue = 72100604,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "How long would it take? Ten years? A hundred? Would that be enough?",
          bAllowClickSkipScript = false
        },
        [72100604] = {
          DialogueId = 72100604,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D58",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100701] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100701,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1D42",
          NextDialogue = 72100702,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100702] = {
          ContentKR = "추워요... 너무 추워서, 이가 다 얼어서 떨어져 나갈 것 같아요.",
          DialogueId = 72100702,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1D6C",
          NextDialogue = 72100703,
          SpeakNpcId = 830001,
          Subtitle = "So chilly... I'm freezing all over. Feels like my teeth are about to shatter."
        },
        [72100703] = {
          ContentKR = "어엇, 전 이가 없다고요? 그럼 이 으슬으슬 떨리는 기분은...",
          DialogueId = 72100703,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1D96",
          NextDialogue = 72100704,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Wait... I don't have teeth, do I? Then this shivering feeling is from...",
          bAllowClickSkipScript = false
        },
        [72100704] = {
          DialogueId = 72100704,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F1DC0",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100801] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100801,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2DAA",
          NextDialogue = 72100802,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100802] = {
          ContentKR = "전에 여기서 자주 하늘을 봤어. 구름 너머로 내 자신을 볼 수 있을 것만 같았거든.",
          DialogueId = 72100802,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2DD4",
          NextDialogue = 72100803,
          SpeakNpcId = 830001,
          Subtitle = "I used to come here to gaze at the sky. It was like I could see myself behind the clouds."
        },
        [72100803] = {
          ContentKR = "이젠 그럴 필요가 없어졌어. 어차피 나도 내가 보이지 않으니까!",
          DialogueId = 72100803,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2DFE",
          NextDialogue = 72100804,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "No need to look now. After all, I can't see myself anymore!",
          bAllowClickSkipScript = false
        },
        [72100804] = {
          DialogueId = 72100804,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F2E28",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72100901] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72100901,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E12",
          NextDialogue = 72100902,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100902] = {
          ContentKR = "넌 무슨 색이 좋아? 연두색? 아니면 회색?",
          DialogueId = 72100902,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E3C",
          NextDialogue = 72100903,
          SpeakNpcId = 830001,
          Subtitle = "What's your favourite colour? Light green, or crane-gray?"
        },
        [72100903] = {
          ContentKR = "난 옅은 물빛이 좋아. 나랑 똑같은 색이니까.",
          DialogueId = 72100903,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E66",
          NextDialogue = 72100904,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I love cloud-water blue. Just like my... body.",
          bAllowClickSkipScript = false
        },
        [72100904] = {
          DialogueId = 72100904,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E90",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101001] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101001,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4E7A",
          NextDialogue = 72101002,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101002] = {
          ContentKR = "주변이 온통 낙진으로 뒤덮여서 어디로 가야 할지 방향을 모르겠네...",
          DialogueId = 72101002,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4EA4",
          NextDialogue = 72101003,
          SpeakNpcId = 830001,
          Subtitle = "The Gritblight blots out the sky. No sense of direction, can't even tell where I came from..."
        },
        [72101003] = {
          ContentKR = "네가 방향을 알려줘서 다행이야. 고마워, 멀리서 온 친구.",
          DialogueId = 72101003,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4ECE",
          NextDialogue = 72101004,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Lucky to have you show me the way. Thank you, friend from afar.",
          bAllowClickSkipScript = false
        },
        [72101004] = {
          DialogueId = 72101004,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4EF8",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101101] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101101,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5EE2",
          NextDialogue = 72101102,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101102] = {
          ContentKR = "야하하! 날 찾아냈구나! 역시 다 내 계획대로야!",
          DialogueId = 72101102,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5F0C",
          NextDialogue = 72101103,
          SpeakNpcId = 830001,
          Subtitle = "E-hehe! You found me! All according to my grand scheme!"
        },
        [72101103] = {
          ContentKR = "다음 계획은, 바로 이걸 너한테 주는 거야!",
          DialogueId = 72101103,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5F36",
          NextDialogue = 72101104,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "As planned, the next step is to give you this!",
          bAllowClickSkipScript = false
        },
        [72101104] = {
          DialogueId = 72101104,
