          VoiceName = "voice/$Locale$/story/1201/120111/C8462FAC"
        },
        [80001023] = {
          Camera = "85.921997,188.681641,126.737305,0.000048,-0.755863,-106.954742,35.0,272.596405,false,Manual,7.0",
          ContentKR = "피나는 대마법사의 도움이 필요해. 나랑 같이 현실 세계로 가줘!",
          DialogueId = 80001023,
          GUID = "C8462FD6",
          Scripts = [[
PARA{
CameraMoveTo{_delay{0.1},TargetPosition{"140.144897,460.263672,108.315918,0.000057,9.844024,-100.355888,35.0,272.596405,false,Manual,7.0"},duration{10}},
