          SpeakNpcId = 211001,
          Subtitle = "(Still missing some feathers... Should we head back and search again?)"
        },
        [80002001] = {
          ContentKR = "와, 이건 미로 화원이네!",
          DialogueId = 80002001,
          GUID = "C846D04A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 80002002,
          SpeakNpcId = 700142,
          Subtitle = "Wow, a labyrinthine garden!",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D04A"
        },
        [80002002] = {
          ContentKR = "유니콘 {性别:오빠|언니}는 어디 숨어 있을까?",
          DialogueId = 80002002,
          GUID = "C846D074",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Where could {性别:Mr|Miss} Unicorn be hiding?",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D074"
        },
        [80002003] = {
          ContentKR = "으응? 반응이 없네... 혹시 똑같은 색깔로 그려야 하나?",
          DialogueId = 80002003,
          GUID = "C846D09E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Hm? Nothing happened... Maybe I need to paint it with the very same colour?",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D09E"
        },
        [80002004] = {
          ContentKR = "피나한텐 다른 물감이 없으니까, 미로에 가서 찾아봐야겠다.",
          DialogueId = 80002004,
          GUID = "C846D0C8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "I don't have other pigment yet. Let me find some in the labyrinth.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D0C8"
        },
        [80002005] = {
          ContentKR = "엇, 미로 이쪽 편은 잠겨 있잖아. 다른 쪽부터 먼저 시작해야겠네.",
          DialogueId = 80002005,
          GUID = "C846D0F2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Hmm, it's blocked on this side. Looks like I have to deal with it on the other side.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D0F2"
        },
        [80002006] = {
          ContentKR = "유니콘 {性别:오빠|언니}는 예전에 가족과 함께, 괴물을 피해서 좁은 동굴에 숨어 지냈지...",
          DialogueId = 80002006,
          GUID = "C846D11C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "{性别:Mr|Miss} Unicorn once hid in a narrow cave with {性别:his|her} family to avoid some beasts...",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D11C"
        },
        [80002007] = {
          ContentKR = "그러다 나중엔 용감하게 무기를 들고 괴물에게 맞섰어.",
          DialogueId = 80002007,
          GUID = "C846D146",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Later, they picked up their weapons, braved on and fought against the beasts.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D146"
        },
        [80002008] = {
          ContentKR = "마침내, 유니콘 {性别:오빠|언니}는 가족과 함께, 길을 막는 필토이드를 물리치고, 겹겹의 포위를 뚫었지...",
          DialogueId = 80002008,
          GUID = "C846D170",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "But just when they finally drove away the Filthoids and broke through their ring...",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D170"
        },
        [80002009] = {
          ContentKR = "그런데 더 강한 적이 나타난 거야!",
          DialogueId = 80002009,
          GUID = "C846D19A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "They encountered an even more powerful enemy!",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D19A"
        },
        [80002010] = {
          ContentKR = "그들은 죽을힘을 다해 싸웠지만, 결국은 뿔뿔이 흩어지고 말았어...",
          DialogueId = 80002010,
          GUID = "C846D1C4",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 80002011,
          SpeakNpcId = 700142,
          Subtitle = "They fought desperately with all their might, but were forced apart in the end.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D1C4"
        },
        [80002011] = {
          ContentKR = "유니콘 {性别:오빠|언니}가 빨리 소중한 가족을 되찾았으면 좋겠어.",
          DialogueId = 80002011,
          GUID = "C846D1EE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "May {性别:Mr|Miss} Unicorn find {性别:his|her} beloved family soon.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D1EE"
        },
        [80002012] = {
          ContentKR = "차가운 얼음 도시에 도착한 유니콘 {性别:오빠|언니}는, 새로운 동료를 만나서, 멋진 모험을 계속했어.",
          DialogueId = 80002012,
          GUID = "C846D218",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "After arriving in the realm of ice, {性别:Mr|Miss} Unicorn met some new friends and embarked on one exciting adventure after another.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D218"
        },
        [80002013] = {
          ContentKR = "어? 물웅덩이에 있는 둥근 고리 반쪽에 불이 들어왔네... 수수께끼의 절반은 풀었나 봐!",
          DialogueId = 80002013,
          GUID = "C846D242",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Oh? The ring in the pool has lit up halfway… Looks like I've solved half the puzzle already!",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D242"
        },
        [80002014] = {
          Camera = "-52.069061,81.001106,136.062469,0.000082,-5.627324,-67.980148,28.0,103.692528,false,Manual,3.5",
          ContentKR = "유니콘 {性别:오빠|언니}, 여기 있었구나! 응? 그건 피나한테 주는 거야?",
