        [80004101] = {
          ContentKR = "숲속에 안개가 자욱하네!",
          DialogueId = 80004101,
          Duration = 3,
          GUID = "C84828D2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004102,
          SpeakNpcId = 700142,
          Subtitle = "The forest is thick with fog!",
          VoiceName = "voice/$Locale$/story/1201/120114/C84828D2"
        },
        [80004102] = {
          ContentKR = "길을 잃지 않게, 이 시냇물을 따라가자.",
          DialogueId = 80004102,
          Duration = 3,
          GUID = "C84828FC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's stay on course by keeping this brook beside us.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84828FC"
        },
        [80004103] = {
          ContentKR = "어... 가시덤불에 색깔이 없는 곳이 있네.",
          DialogueId = 80004103,
          Duration = 3,
          GUID = "C8482926",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004104,
          SpeakNpcId = 700142,
          Subtitle = "These vines... Parts of their color are simply gone.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8482926"
        },
        [80004104] = {
          ContentKR = "빈 곳에 색깔을 칠해 주자. 그럼 움직일지도 몰라.",
          DialogueId = 80004104,
          Duration = 3,
          GUID = "C8482950",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Maybe they will move when I paint the missing parts.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8482950"
        },
        [80004105] = {
          ContentKR = "나이팅게일아, 왜 그 안에 있어? 혹시 이 가시들 때문에 못 나오는 거야?",
          DialogueId = 80004105,
          Duration = 3,
          GUID = "C848297A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80004106,
          SpeakNpcId = 700142,
          Subtitle = "Little Nightingale, why are you staying in there? Are you trapped by these vines?",
          VoiceName = "voice/$Locale$/story/1201/120114/C848297A"
        },
        [80004106] = {
          ContentKR = "걱정 마, 피나가 도와줄게!",
          DialogueId = 80004106,
          Duration = 3,
          GUID = "C84829A4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Don't be afraid. I'll help you get out!",
          VoiceName = "voice/$Locale$/story/1201/120114/C84829A4"
        },
        [80004107] = {
          ContentKR = "가시덤불이 너무 커서, 나이팅게일의 둥지를 가려버렸네.",
          DialogueId = 80004107,
          Duration = 3,
          GUID = "C84829CE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80004108,
          SpeakNpcId = 700142,
          Subtitle = "These vines have grown so tall they've completely blocked the Little Nightingale's nest.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84829CE"
        },
        [80004108] = {
          ContentKR = "방금처럼 색깔을 칠해주면, 나이팅게일한테 길을 열어주겠지?",
          DialogueId = 80004108,
          Duration = 3,
          GUID = "C84829F8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "If I colour them in the way I just did, they would make way for the Little Nightingale.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84829F8"
        },
        [80004109] = {
          ContentKR = "길을 막는 가시덤불이 사라졌으니까, 이제 계속 가보자, 나이팅게일~",
          DialogueId = 80004109,
          Duration = 3,
          GUID = "C8482A22",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "The vines are gone. Let's continue our journey, Little Nightingale~",
          VoiceName = "voice/$Locale$/story/1201/120114/C8482A22"
        },
        [80004110] = {
          Camera = "-4.021118,-147.850586,140.854248,0.000064,-3.469995,89.231857,35.0,160.025635,false,Manual,12.0",
