        [80004201] = {
          ContentKR = "앞쪽의 안개가 더 짙어진 것 같아...",
          DialogueId = 80004201,
          Duration = 3,
          GUID = "C848393A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004202,
          SpeakNpcId = 700142,
          Subtitle = "The fog ahead looks even thicker...",
          VoiceName = "voice/$Locale$/story/1201/120114/C848393A"
        },
        [80004202] = {
          ContentKR = "나이팅게일아, 네가 길을 안내해 줄래?",
          DialogueId = 80004202,
          Duration = 3,
          GUID = "C8483964",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Little Nightingale, could you lead the way for me?",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483964"
        },
        [80004203] = {
          ContentKR = "와... 이 돌은 등불이었구나! 등불을 켜니까 안개가 사라졌어.",
          DialogueId = 80004203,
          Duration = 3,
          GUID = "C848398E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80004204,
          SpeakNpcId = 700142,
          Subtitle = "Wow... So the stone here is actually a lamp! The fog was dispersed when the lights came on.",
          VoiceName = "voice/$Locale$/story/1201/120114/C848398E"
        },
        [80004204] = {
          ContentKR = "우리 다른 돌도 찾아보자.",
          DialogueId = 80004204,
          Duration = 3,
          GUID = "C84839B8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's go look for more stones.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84839B8"
        },
        [80004205] = {
          ContentKR = "안개 때문에 방향을 헷갈릴 수 있으니까, 나이팅게일을 바짝 따라가야 해.",
          DialogueId = 80004205,
          Duration = 3,
          GUID = "C84839E2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "The fog can be disorientating, so stay close to the Little Nightingale to be safe.",
          VoiceName = "voice/$Locale$/story/1201/120114/C84839E2"
        },
        [80004206] = {
          ContentKR = "드디어 안개 구역을 빠져나왔어! 봐, 숲의 출구가 저 앞에 있어.",
          DialogueId = 80004206,
          Duration = 3,
          GUID = "C8483A0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Finally getting out of this foggy place! Look, the exit of the forest is just up ahead.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A0C"
        },
        [80004207] = {
          ContentKR = "숲을 나가면 어떤 풍경이 기다리고 있을까? 정말 기대돼!",
          DialogueId = 80004207,
          Duration = 3,
          GUID = "C8483A36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "What wonders await beyond the forest? I can't wait to see!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A36"
        },
        [80004208] = {
          ContentKR = "어, 저건... 대마법사랑 유니콘 {性别:오빠|언니}랑 나비 소녀잖아! 다들 여기서 우릴 기다리고 있었구나.",
          DialogueId = 80004208,
          Duration = 3,
          GUID = "C8483A60",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80004209,
          SpeakNpcId = 700142,
          Subtitle = "Oh, Great Magician, {性别:Mr|Miss} Unicorn... and Miss Butterfly! Everyone is waiting for us!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A60"
        },
        [80004209] = {
          ContentKR = "나이팅게일아, 얼른 모두를 만나러 가자!",
          DialogueId = 80004209,
          Duration = 3,
          GUID = "C8483A8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Little Nightingale, let's go join them!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A8A"
        },
        [80004210] = {
          Camera = "-393.173828,-198.093201,117.472694,0.000079,-4.382597,17.344532,35.000008,348.827637,false,Manual,20.0",
