        },
        [80040102] = {
          Camera = "-29.085938,-97.268799,150.180298,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786",
          ContentKR = "음, 그래...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040102,
          FacialId = {
            [1] = "790007:Iyada01"
          },
          GUID = "C85F3B3C",
          NextDialogue = 80040103,
          SpeakNpcId = 790007,
          Subtitle = "Hmm, okay...",
          TalkActionId = {
            [1] = "790007:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B3C"
        },
        [80040103] = {
          Camera = "-199.146484,-426.681641,234.483765,0.000222,-15.191071,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentKR = "맞다, 그런데 방금 왜 국자를 뺏으려 한 거야?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040103,
          FinalCamera = "-186.857422,-430.990479,234.483765,0.000221,-15.191064,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B66",
          NextDialogue = 80040104,
          SpeakNpcId = 790007,
          Subtitle = "So, why were you so eager to take the ladle from me earlier?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B66"
        },
        [80040104] = {
          Camera = "-24.671387,-68.66333,139.902344,0.000222,-5.191469,35.319683,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentKR = "그야 네가 생선 수프에 석류를 넣으려 하니까.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040104,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "-24.671387,-68.66333,139.902344,0.000222,-4.591458,35.919678,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B90",
          NextDialogue = 80040105,
          SpeakNpcId = 790008,
          Subtitle = "Because you were about to add pomegranates to the fish soup!",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B90"
        },
        [80040105] = {
          ContentKR = "그게 왜? 어릴 때는 석류를 좋아했잖아.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040105,
          FacialId = {
            [1] = "790007:Shock02"
          },
          GUID = "C85F3BBA",
          NextDialogue = 80040106,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Shock_Start\"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{\"Shock_End\"},Duration{1}}}",
