        [80040204] = {
          Camera = "-63.011719,2.983643,162.785645,-0.000092,-22.699921,59.573631,35.000008,497.258331,false,DoNotOverride,1.2",
          ContentKR = "너 방금 다친 거 아냐? 손 줘봐. 내가 치료해 줄게.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040204,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "-58.447266,0.387207,162.785645,-0.000093,-22.699913,61.973614,35.000008,497.258331,false,DoNotOverride,1.2",
          GUID = "C85F4BF8",
          NextDialogue = 80040205,
          SpeakNpcId = 790008,
