          GUID = "C85F4D48",
          LookAt = {
            [1] = "790007:n(790007)"
          },
          NextDialogue = 80040213,
          SpeakNpcId = 790007,
          Subtitle = "I'll be more careful next time.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/002/C85F4D48"
        },
        [80040213] = {
