          ContentKR = "저기 동그랗게 솟아 있는 구릿빛 물체는 은색 평화 광장에 있는 조각상이야! 몇백 년 동안 저 자리를 지켜왔지.",
          DialogueId = 80050312,
          FinalCamera = "3399.474609,-93.6745,922.0,0.000066,-15.400177,-17.203409,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C650",
          NextDialogue = 80050313,
          SpeakNpcId = 790017,
          Subtitle = "See that brass-coloured, round thing with a spiky tip? That's the Silverpeace Monument! It's been there for hundreds of years.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C650"
        },
        [80050313] = {
          Camera = "-82.092773,-23.63623,98.630615,0.000068,2.799851,-101.803772,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "남쪽에 다닥다닥 붙어있는 건물들 사이에 피나의 집이 있어! 이웃들은 조금 시끄럽지만 그래도 친절해.",
          DialogueId = 80050313,
          GUID = "C865C67A",
          NextDialogue = 80050314,
          SpeakNpcId = 790017,
          Subtitle = "And do you see those cramped rows of houses down south? One of them is my home! The neighbours are loud but friendly.",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C67A"
        },
        [80050314] = {
          Camera = "-70.529297,-88.626709,162.978516,0.000101,-23.199331,-111.998558,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "서쪽은...",
          DialogueId = 80050314,
          FacialId = {
            [1] = "790017:Sad01"
          },
          FinalCamera = "-75.646484,-101.298706,157.119873,0.000101,-23.199331,-111.998558,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C6A4",
          NextDialogue = 80050315,
          SpeakNpcId = 790017,
          Subtitle = "And to the west...",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C6A4"
        },
        [80050315] = {
          ContentKR = "......",
          DialogueId = 80050315,
          FacialId = {
            [1] = "790017:Disappoint01"
          },
          GUID = "C865C6CE",
          NextOptions = {
            [1] = 80050316
          },
          SpeakNpcId = 790017,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C6CE"
        },
        [80050316] = {
          ContentKR = "왜? 모르면 내가 알려 줄게.",
          DialogueId = 80050316,
          GUID = "C865C6F8",
          NextDialogue = 80050317,
          Subtitle = "What's wrong? If you don't know that place, I can tell you about it."
        },
        [80050317] = {
          Camera = "-65.606445,-263.350464,109.867432,0.000101,0.000478,109.002274,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...나도 알아.",
          DialogueId = 80050317,
          GUID = "C865C722",
          NextDialogue = 80050318,
          SpeakNpcId = 790017,
          Subtitle = "...I know that place.",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C722"
        },
        [80050318] = {
          Camera = "-65.606445,-263.350464,109.867432,0.000101,0.000478,109.002274,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "저긴 내성이야... 피나가 자란 곳이지. 보면... 저쪽에 내가 살았던 집이 있어.",
          DialogueId = 80050318,
          GUID = "C865C74C",
          NextOptions = {
            [1] = 80050319,
            [2] = 80050321
          },
          SpeakNpcId = 790017,
          Subtitle = "That's the inner city... where I grew up. That house over there... that's where I used to live.",
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C74C"
        },
        [80050319] = {
          ContentKR = "피나는 부잣집 딸이었구나. 좋겠다.",
          DialogueId = 80050319,
          GUID = "C865C776",
          NextDialogue = 80050320,
          Subtitle = "Oh, so you came from a rich family. That's nice."
        },
        [80050320] = {
          ContentKR = "아니. 하나도 안 좋아.",
          DialogueId = 80050320,
          GUID = "C865C7A0",
          NextDialogue = 80050323,
          SpeakNpcId = 790017,
          Subtitle = "No, it wasn't nice at all.",
          TalkActionId = {
            [1] = "790017:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C7A0"
        },
        [80050321] = {
          ContentKR = "저곳이 그리워?",
          DialogueId = 80050321,
          GUID = "C865C7CA",
          NextDialogue = 80050322,
          Subtitle = "Do you miss it there?"
        },
        [80050322] = {
          Camera = "-61.318359,8.6604,109.648682,0.000008,0.0,-104.999664,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아니, 전혀. 하나도 안 그리워.",
          DialogueId = 80050322,
          GUID = "C865C7F4",
          NextDialogue = 80050323,
          SpeakNpcId = 790017,
          Subtitle = "No, not at all.",
          TalkActionId = {
            [1] = "790017:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C7F4"
        },
        [80050323] = {
          Camera = "-101.632812,-105.954285,114.34375,0.000072,0.999728,-97.801895,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "저건 집이 아니라, 그냥 건물일 뿐이거든.",
          DialogueId = 80050323,
          GUID = "C865C81E",
          NextDialogue = 80050324,
          SpeakNpcId = 790017,
          Subtitle = "Because that place was just a house rather than a home.",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C81E"
        },
        [80050324] = {
          Camera = "-52.174805,-292.937622,109.959473,0.00007,-1.40012,109.791321,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "피나의 부모님은 아주 먼 곳에 있는 나라로 갔어. 8월 폭우가 내리던 어느 날 밤이었지.",
          DialogueId = 80050324,
          GUID = "C865C848",
          NextDialogue = 80050325,
          SpeakNpcId = 790017,
          Subtitle = "My parents were taken to a faraway place. It all happened on a stormy night in August.",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C848"
        },
        [80050325] = {
          Camera = "2649.62207,-5001.596191,-1486.966064,7.200227,0.799276,-178.809067,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아빠는 '나쁜 사냥꾼'에게 잡혀갔어. 목에 밧줄이 감긴 채, 공중에 매달린 상태로 발견됐지.",
          DialogueId = 80050325,
          FinalCamera = "2247.921875,-5009.945801,-1481.363281,7.200307,0.799276,-178.809067,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C872",
          NextDialogue = 80050326,
          SpeakNpcId = 790017,
          Subtitle = "Dad was taken by a \"bad hunter,\" and his body was left hanging in the sky with a noose around his neck.",
          TalkActionId = {
            [1] = "790017:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C872"
        },
        [80050326] = {
          Camera = "-7238.111328,-5586.991699,-2040.967285,7.243233,-14.796771,-166.212799,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "엄마는 흉폭한 '야수'한테 당했어. 장미꽃처럼 새빨간 엄마의 피가 폭우에 씻겨 내려가 아무것도 남지 않았지.",
          DialogueId = 80050326,
          FinalCamera = "-7238.111328,-5586.991699,-2040.967285,7.245794,-5.59622,164.383118,35.000015,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C89C",
          NextDialogue = 80050327,
          SpeakNpcId = 790017,
          Subtitle = "Mom was killed by a savage \"beast,\" and her blood, red as roses, was washed away by the pouring rain, leaving nothing behind.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C89C"
        },
        [80050327] = {
          Camera = "-61.800781,64.192169,129.852539,0.000068,-7.399963,-108.799545,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "부모님은 아주 먼 곳에 있는 나라로 갔어... 그러니까 저기엔 이제 피나의 집이 없어.",
          DialogueId = 80050327,
          GUID = "C865C8C6",
          IsBlack = 1,
          NextOptions = {
            [1] = 80050328,
            [2] = 80050329
          },
          SpeakNpcId = 790017,
          Subtitle = "They've gone to a faraway place... and there's no home for me there anymore.",
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C8C6"
        },
        [80050328] = {
          ContentKR = "(피나의 머리를 쓰다듬기)",
          DialogueId = 80050328,
          GUID = "C865C8F0",
          NextDialogue = 80050330,
          Subtitle = "(Pat her head gently)"
        },
        [80050329] = {
          ContentKR = "(피나를 안아주기)",
          DialogueId = 80050329,
          GUID = "C865C91A",
          NextDialogue = 80050330,
          Subtitle = "(Give her a hug)"
        },
        [80050330] = {
          Camera = "-61.800781,64.192169,129.852539,0.000068,-7.399963,-108.799545,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "유니콘 {性别:오빠|언니}의 손도 따뜻하네...",
          DialogueId = 80050330,
          GUID = "C865C944",
          IsBlack = 1,
          NextOptions = {
            [1] = 80050331
          },
          SpeakNpcId = 790017,
          Subtitle = "Your hands are as warm as you, {性别:Mr|Miss} Unicorn...",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C944"
        },
        [80050331] = {
          ContentKR = "전에 네가 말했던 '새와 별' 이야기 기억나지?",
          DialogueId = 80050331,
          GUID = "C865C96E",
          NextDialogue = 80050332,
          Subtitle = "Remember the story you told me? The one about the little bird and the stars?"
        },
        [80050332] = {
          Camera = "408.845703,-129.991882,-10.434082,0.000055,3.199656,177.195557,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "피나의 아빠와 엄마도... 하늘의 별이 되었을 거야. 말은 안해도 따뜻한 눈빛으로 묵묵히 피나를 지켜보고 있을 거야.",
          DialogueId = 80050332,
          FinalCamera = "408.845703,-129.991882,-10.434082,0.000055,8.599618,177.395554,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C998",
          NextDialogue = 80050333,
          SpeakNpcId = 100001,
          Subtitle = "Maybe your parents have become stars in the sky... Though they can't speak, they're still quietly, gently watching over you.",
          TalkActionId = {
            [1] = "790017:Explain02_End",
            [2] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C998"
        },
        [80050333] = {
          ContentKR = "부모님이 보고 싶을 땐, 밤하늘을 보고 웃어봐.",
          DialogueId = 80050333,
          GUID = "C865C9C2",
          NextDialogue = 80050334,
          SpeakNpcId = 100001,
          Subtitle = "So, whenever you miss them, just smile at the night sky.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C9C2"
        },
        [80050334] = {
          Camera = "-101.089844,-114.304626,115.5979,0.000041,2.199259,-98.406013,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "응... 알겠어... 그렇게 해볼게.",
          DialogueId = 80050334,
          FacialId = {
            [1] = "790017:Satisfy01",
            [2] = "100001:Sad01"
          },
          GUID = "C865C9EC",
          NextDialogue = 80050335,
          SpeakNpcId = 790017,
          Subtitle = "Thank you... I'll do that.",
          TalkActionId = {
            [1] = "790017:AgreeHead",
            [2] = "100001:Sad02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C9EC"
        },
        [80050335] = {
          Camera = "-64.15625,-266.238037,110.220703,0.000082,-0.001892,107.984558,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentKR = "괜찮아, 괜찮아. 나 때문에 우울해하지 마. 피나에게는 새로운 집이 생겼거든.",
          DialogueId = 80050335,
          GUID = "C865CA16",
          NextDialogue = 80050336,
          SpeakNpcId = 790017,
          Subtitle = "It's okay, don't feel bad for me, because I have a new home now.",
          TalkActionId = {
            [1] = "790017:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865CA16"
        },
        [80050336] = {
          Camera = "-109.111328,-35.609192,129.727539,0.000115,-9.201903,-90.815498,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentKR = "대마법사도 있고... 우리 둘도 함께 있잖아. 이걸로 만족해.",
          DialogueId = 80050336,
          FacialId = {
            [1] = "790017:Happy02"
          },
          FinalCamera = "-109.111328,-35.609192,129.727539,0.000117,-6.401854,-90.81559,35.000015,100000.0,false,DoNotOverride,2.8",
          GUID = "C865CA40",
          SpeakNpcId = 790017,
          Subtitle = "I have the Great Magician, and I have you. I am more than content now.",
          TalkActionId = {
            [1] = "100001:Sad02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865CA40"
        },
        [80050401] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentKR = "유니콘 {性别:오빠|언니}, 왔구나?",
          DialogueId = 80050401,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865D4EA",
          NextOptions = {
            [1] = 80050402
          },
          SpeakNpcId = 790017,
          Subtitle = "There you are, {性别:Mr|Miss} Unicorn!",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D4EA"
        },
        [80050402] = {
          ContentKR = "이제 마지막 소원이지? 이번에는 어디로 갈까?",
          DialogueId = 80050402,
          GUID = "C865D514",
          NextDialogue = 80050403,
          Subtitle = "Only one wish to go. Where do you want to go this time, Fina?"
        },
        [80050403] = {
          ContentKR = "음... 이번에는 아무 데도 안 가. 피나의 마지막 소원은 여기에 있거든.",
          DialogueId = 80050403,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D53E",
          NextDialogue = 80050404,
          SpeakNpcId = 790017,
          Subtitle = "This time, we're not going anywhere because my last wish is already here with us.",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D53E"
        },
        [80050404] = {
          ContentKR = "새로운 이야기책을 가져왔어!",
          DialogueId = 80050404,
          FacialId = {
            [1] = "790017:Happy01"
          },
          GUID = "C865D568",
          NextDialogue = 80050405,
          SpeakNpcId = 790017,
          Subtitle = "Look, I've brought my new storybook!",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D568"
        },
        [80050405] = {
          ContentKR = "피나가 만든 이야기구나... 엇, 그런데 아무것도 없는데?",
          DialogueId = 80050405,
          GUID = "C865D592",
          NextDialogue = 80050406,
          SpeakNpcId = 100001,
          Subtitle = "Oh, it's a collection of stories by Fina... wait, why are all the pages blank?",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D592"
        },
        [80050406] = {
          ContentKR = "우리 둘이 '새로운 이야기'를 쓰고 싶거든... 이게 네 번째 소원이야.",
          DialogueId = 80050406,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865D5BC",
          NextOptions = {
            [1] = 80050407,
            [2] = 80050408
          },
          SpeakNpcId = 790017,
          Subtitle = "Because I want to write a new storybook with you — that's my fourth wish.",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D5BC"
        },
        [80050407] = {
          ContentKR = "간단하네... 좋아.",
          DialogueId = 80050407,
          GUID = "C865D5E6",
          NextDialogue = 80050411,
          Subtitle = "Oh, that's a rather simple wish... Absolutely, we can do that."
        },
        [80050408] = {
          ContentKR = "난 이야기를 쓸 줄 몰라!",
          DialogueId = 80050408,
          GUID = "C865D610",
          NextDialogue = 80050409,
          Subtitle = "But I'm not good at writing stories."
        },
        [80050409] = {
          ContentKR = "괜찮아... 내가 알려줄게!",
          DialogueId = 80050409,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D63A",
          NextDialogue = 80050410,
          SpeakNpcId = 790017,
          Subtitle = "That's okay, I'll teach you!",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D63A"
        },
        [80050410] = {
          ContentKR = "어렵지 않아. 같이 천천히 생각해 보면 돼.",
          DialogueId = 80050410,
          FacialId = {
            [1] = "790017:Confident02"
          },
          GUID = "C865D664",
          NextDialogue = 80050411,
          SpeakNpcId = 790017,
          Subtitle = "No pressure, we'll figure it out together.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D664"
        },
        [80050411] = {
          ContentKR = "첫 번째 이야기는... 가장 쉬운 모험부터 시작해 보자~",
          DialogueId = 80050411,
          GUID = "C865D68E",
          NextDialogue = 80050412,
          SpeakNpcId = 790017,
          Subtitle = "Let's start the first story with a simple adventure~",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D68E"
        },
        [80050412] = {
          ContentKR = "어느 날 나이팅게일과 유니콘 {性别:오빠|언니}가 함께 모험을 떠났습니다...",
          DialogueId = 80050412,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D6B8",
          NextDialogue = 80050413,
          SpeakNpcId = 790017,
          Subtitle = "One day, Little Nightingale and {性别:Mr|Miss} Unicorn embarked on an adventure together...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D6B8"
        },
        [80050413] = {
          ContentKR = "...둘이서만 가는 거야, 아니면 다른 친구들도 있어?",
          DialogueId = 80050413,
          GUID = "C865D6E2",
          NextOptions = {
            [1] = 80050414,
            [2] = 80050416,
            [3] = 80050418
          },
          SpeakNpcId = 790017,
          Subtitle = "Was it just the two of them, or were there other friends?",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D6E2"
        },
        [80050414] = {
          ContentKR = "둘이서만 가는 거야.",
          DialogueId = 80050414,
          GUID = "C865D70C",
          NextDialogue = 80050415,
          Subtitle = "Just the two of them."
        },
        [80050415] = {
