          DialogueId = 80080110,
          GUID = "C878DF0C",
          NextDialogue = 80080111,
          SpeakNpcId = 790004,
          Subtitle = "...Um, am I?",
          TalkActionId = {
            [1] = "790001:Explain01_End",
            [2] = "790004:Shock_Start"
