          DialogueId = 80080126,
          GUID = "C878E1AC",
          NextDialogue = 80080127,
          SpeakNpcId = 790004,
          Subtitle = "Carolina gives us a fascinating glimpse into the novel lives of the ladies in the inner city, Elisa offers unique takes on old fairy tales, and Fred shares clever cleaning tricks...",
          TalkActionId = {
