          TalkActionId = {
            [1] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E2FC"
        },
        [80080135] = {
          Camera = "955.041016,143.792236,123.109375,0.0,0.0,90.006081,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러니까 꽃을 키우거나 책을 읽든, 아니면 모험을 하든, 또 우리끼리 새로운 이야기를 하든... 나는 뭐라도 해야겠어...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080135,
          FinalCamera = "955.041016,594.0,123.109375,0.0,0.0,90.006081,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C878E326",
          NextDialogue = 80080136,
          SpeakNpcId = 790004,
          Subtitle = "So I tend flowers, read, go on adventures, and share stories with everyone... I always feel that I should busy myself with something, anything...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E326"
        },
        [80080136] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...그럼 그날이 와도 아쉬움이 덜하지 않을까?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080136,
          GUID = "C878E350",
          NextDialogue = 80080137,
          SpeakNpcId = 790004,
          Subtitle = "Perhaps then, when that day comes, I'll have fewer regrets.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E350"
        },
        [80080137] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "근데 이런 이야기가 엘리사를 힘들게 할 줄은 몰랐어. 미안해. 다음부터는 조심할게.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080137,
          GUID = "C878E37A",
          NextDialogue = 80080138,
          SpeakNpcId = 790004,
          Subtitle = "But I didn't mean to upset you, Elisa — I'm sorry. I'll try to keep my mouth shut from now on.",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E37A"
        },
        [80080138] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "엇? 그렇지만 프시케, 헌트가 떠난 후 나와 이야기를 나눠준 사람은 너밖에 없는 걸...",
          DialogueId = 80080138,
          GUID = "C878E3A4",
          LookAt = {
            [1] = "790004:n(790001)"
          },
          NextDialogue = 80080139,
          SpeakNpcId = 790001,
          Subtitle = "Huh? But Psyche, you're the only one willing to talk to me ever since Hunt left...",
          TalkActionId = {
            [1] = "790001:Give"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E3A4"
        },
        [80080139] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 80080139,
          GUID = "C878E3CE",
          LookAt = {
            [1] = "790002:n(790002)"
          },
          NextDialogue = 80080140,
          SpeakNpcId = 790002,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E3CE"
        },
        [80080140] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "됐어. 그냥 한 말이야... 매일 조잘거리는 네가 없다고 생각하니... 정말 어색하네.",
          DialogueId = 80080140,
          GUID = "C878E3F8",
          LookAt = {
            [1] = "790002:n(790004)",
            [2] = "790004:n(790002)"
          },
          NextDialogue = 80080141,
          SpeakNpcId = 790002,
          Subtitle = "Don't worry about it. I was just speaking off the cuff... I'd actually miss your chatter if it was gone.",
          TalkActionId = {
            [1] = "790002:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E3F8"
        },
        [80080141] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "알겠어... 엘리사가 화난 것만 아니면 돼.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080141,
          GUID = "C878E422",
          NextDialogue = 80080142,
          SpeakNpcId = 790004,
          Subtitle = "Okay... I'm glad you're not upset, Elisa.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E422"
        },
        [80080142] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...그럼 다음에 그 사람을 만나면 금빛 모래에 대해서도 물어봐 줘.",
          DialogueId = 80080142,
          GUID = "C878E44C",
          LookAt = {
            [1] = "790003:n(790004)",
            [2] = "790004:n(790003)",
            [3] = "790002:n(790003)",
            [4] = "790001:n(790003)"
          },
          NextDialogue = 80080143,
          SpeakNpcId = 790003,
          Subtitle = "Next time you see that person, could you ask about the golden sand for me?",
          TalkActionId = {
            [1] = "790003:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E44C"
        },
        [80080143] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "천국의 나무에 대해서도.",
          DialogueId = 80080143,
          GUID = "C878E476",
          LookAt = {
            [1] = "790004:n(790001)",
            [2] = "790003:n(790004)",
            [3] = "790002:n(790001)",
            [4] = "790001:n(790004)"
          },
          NextDialogue = 80080144,
          SpeakNpcId = 790001,
          Subtitle = "And about the Heaventree.",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E476"
        },
        [80080144] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "응, 기억해둘게... 다음에 물어봐 줄게.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080144,
          FacialId = {
            [1] = "790004:Smile01"
          },
          GUID = "C878E4A0",
          LookAt = {
            [1] = "790004:n(790002)"
          },
          SpeakNpcId = 790004,
          Subtitle = "Sure! I'll keep all this in mind. I'll ask for you next time I see {性别:him|her}.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E4A0"
        },
        [80080201] = {
          Camera = "152.138672,195.628784,134.539062,0.0,-1.200071,-127.200096,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "linear",
          ContentKR = "엘리사, 나 왔어.",
          DialogueId = 80080201,
          FinalCamera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C878EDFA",
          NextDialogue = 80080202,
          Scripts = "SEQ{MoveTo{ActorId{790004},MoveSpeed{75},TargetPoint{\"QuestPoint_530102\"}},TurnTo{TurnToDescription{\"790004:n(790006)\"}}}",
          SpeakNpcId = 790004,
          Subtitle = "Elisa, I'm back.",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EDFA"
        },
        [80080202] = {
          Camera = "-81.119141,-25.830444,135.263672,0.0,0.599909,-131.198853,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "자, 여기 빵 좀 가져왔어! 아무것도 안 먹었을 테니까 어서 먹어. 다 먹는지 확인할 거야!",
          DialogueId = 80080202,
          GUID = "C878EE24",
          NextDialogue = 80080203,
          SpeakNpcId = 790004,
          Subtitle = "I brought you some bread — I bet you've skipped the meals again. I'm not going anywhere until you finish it.",
          TalkActionId = {
            [1] = "790004:Give"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE24"
        },
        [80080203] = {
          Camera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...됐어... 지금 우리 처지에 밥을 먹는 것조차도 너무 사치스러운 것 같아.",
          DialogueId = 80080203,
          GUID = "C878EE4E",
          NextDialogue = 80080204,
          SpeakNpcId = 790006,
          Subtitle = "Why waste food... We're all going to leave the world soon anyway.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE4E"
        },
        [80080204] = {
          Camera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그건 아니지. 저기... 저 꽃처럼 말이야! 결국 시들 운명이더라도, 우리가 매일 물과 거름을 줘서 저 생기를 유지하는 거잖아.",
          DialogueId = 80080204,
          GUID = "C878EE78",
          NextDialogue = 80080205,
          SpeakNpcId = 790004,
          Subtitle = "Don't say that... Do you see that plant over there? It'll eventually wither for sure, but we still water and take care of it so that it'll bloom one day.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE78"
        },
        [80080205] = {
          Camera = "-0.818359,59.526489,190.207031,0.000001,-10.400117,20.598642,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "피우지 못할 꽃이라면?",
          DialogueId = 80080205,
          FinalCamera = "-0.818359,59.526489,206.207031,0.000001,-10.400117,20.598642,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C878EEA2",
          NextDialogue = 80080206,
          SpeakNpcId = 790006,
          Subtitle = "But what if it never blooms?",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EEA2"
        },
        [80080206] = {
          Camera = "-78.357422,-27.765015,126.353516,0.000021,3.399993,-132.00238,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "새싹이 나고 잘 자라기만 해도 충분해.",
          DialogueId = 80080206,
          GUID = "C878EECC",
          NextDialogue = 80080207,
          SpeakNpcId = 790004,
          Subtitle = "Then, just watching it sprout and grow bigger is still wonderful, isn't it?",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EECC"
        },
        [80080207] = {
          Camera = "-263.033203,-174.554382,138.316406,0.000001,-1.800322,23.388023,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...됐어. 난 너만큼 꽃에 대해 잘 아는 게 아니라서.",
          DialogueId = 80080207,
          GUID = "C878EEF6",
          NextDialogue = 80080208,
          SpeakNpcId = 790006,
          Subtitle = "...Forget it. I don't have your green thumb.",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EEF6"
        },
        [80080208] = {
          Camera = "-263.033203,-174.554382,138.316406,0.000001,-1.800322,23.388023,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아까 그 사람은 왜 온거야? 침식자도 아니면서 하루가 멀다하고 오다니... 치안서의 감시자인 건 아니겠지?",
          DialogueId = 80080208,
          GUID = "C878EF20",
          NextDialogue = 80080209,
          SpeakNpcId = 790006,
          Subtitle = "By the way, why was that person here earlier? {性别:He|She} is not a Deteriorator, so why the frequent visits? Is {性别:he|she} a spy for the Security Bureau?",
          TurnTo = {
            [1] = "790006:n(790004)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF20"
        },
        [80080209] = {
          Camera = "26.732422,82.374146,145.716797,0.000007,-5.80006,-125.792847,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{nickname}? 그 사람은 여기 사람이 아닌데, 지금은 월석 사냥꾼이야. 치안서랑은 관련 없어. 아마 의뢰 때문에 온 것 같아...",
          DialogueId = 80080209,
          GUID = "C878EF4A",
          NextDialogue = 80080210,
          SpeakNpcId = 790004,
          Subtitle = "You mean ? {性别:He|She}'s not a local. {性别:He|She} now works as a Phoxhunter and has nothing to do with the Security Bureau. I think {性别:he|she} was here for a commission.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF4A"
        },
        [80080210] = {
          Camera = "26.732422,82.374146,145.716797,0.000007,-5.80006,-125.792847,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentKR = "듣기론 헨릭 아저씨에게 필요한 물건을 찾았대. 도와줄 수 있으면 우리가... 아니야, 됐어.",
          DialogueId = 80080210,
          GUID = "C878EF74",
          NextDialogue = 80080211,
          SpeakNpcId = 790004,
          Subtitle = "I heard {性别:he|she} found something Dr Henrik needs. If it helps, maybe we... um, never mind.",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF74"
        },
        [80080211] = {
          Camera = "-147.058594,-85.52063,138.552734,0.000007,-0.200043,29.804741,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "너 저번에 성 밖으로 따라 나갔다가, 헨릭 의사 선생님한테 혼났다고 했잖아.",
          DialogueId = 80080211,
          GUID = "C878EF9E",
          NextDialogue = 80080212,
          SpeakNpcId = 790006,
          Subtitle = "Didn't you say you went out of town with that person yesterday and got an earful from Dr Henrik?",
          TalkActionId = {
            [1] = "790006:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF9E"
        },
        [80080212] = {
          Camera = "-160.625,-5.968567,134.414062,0.000007,0.199988,-105.995361,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아...? 응, 그렇지...",
          DialogueId = 80080212,
          GUID = "C878EFC8",
          NextDialogue = 80080213,
          SpeakNpcId = 790004,
          Subtitle = "Huh? Um, yes...",
          TalkActionId = {
            [1] = "790004:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EFC8"
        },
        [80080213] = {
          Camera = "-164.548828,-79.17041,134.091797,0.000007,0.80002,25.802954,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "왜 또 그 사람의 일에 참견하는 거야? 침식자도, 치안서 사람도 아니면 우리랑 관련 없잖아?",
          DialogueId = 80080213,
          GUID = "C878EFF2",
          NextDialogue = 80080214,
          SpeakNpcId = 790006,
          Subtitle = "Then why still mix up with {性别:him|her}? Since {性别:he|she}'s not one of us and not with the Security Bureau, {性别:he|she} has nothing to do with us, right?",
          TalkActionId = {
            [1] = "790004:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EFF2"
        },
        [80080214] = {
          Camera = "22.615234,70.785767,148.324219,0.000011,-8.000091,-127.191437,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "나... 나는 뭔가 도울만한 게 없는지...",
          DialogueId = 80080214,
          GUID = "C878F01C",
          NextDialogue = 80080215,
          SpeakNpcId = 790004,
          Subtitle = "I... I just thought there might be something I could do—",
          TalkActionId = {
            [1] = "790006:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F01C"
        },
        [80080215] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...프시케, 솔직히 난 이해가 안 가.",
          DialogueId = 80080215,
          GUID = "C878F046",
          NextDialogue = 80080216,
          SpeakNpcId = 790006,
          Subtitle = "Honestly, Psyche, I don't understand you sometimes.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F046"
        },
        [80080216] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "너가 말한 {nickname}, 그 사람은 스쳐 가는 남일 뿐인데, 당장 내일이라도 떠날지도 모르고. 우리는 남은 시간도 얼마 안 남았는데, 너도 당장 내일 어떻게 될지도... 모르잖아.",
          DialogueId = 80080216,
          GUID = "C878F070",
          NextDialogue = 80080217,
          SpeakNpcId = 790006,
          Subtitle = "{性别:He|She} is just a stranger, and might just leave Icelake tomorrow. {性别:He|She} doesn't even know... what will happen to you... You know it — everyone here is not long for this world.",
          TalkActionId = {
            [1] = "790006:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F070"
        },
        [80080217] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맨날 이것저것 도와주고, 꽃도 주고, 먹을 것도 주고, 또 이야기에, 잘 곳 찾는 것까지 도와주고... 그게 다 무슨 소용이야?",
          DialogueId = 80080217,
          GUID = "C878F09A",
          NextDialogue = 80080218,
          SpeakNpcId = 790006,
          Subtitle = "Yet you're always out helping others, giving away flowers, making meals, telling stories, helping travellers with accommodations... What's the point?",
          TalkActionId = {
            [1] = "790006:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F09A"
        },
        [80080218] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "남 신경 쓸 시간에 본인이나 챙겨.",
          DialogueId = 80080218,
          GUID = "C878F0C4",
          NextDialogue = 80080219,
          SpeakNpcId = 790006,
          Subtitle = "Maybe you should stop meddling in other people's business and focus on yourself more.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F0C4"
        },
        [80080219] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...맞아...",
          DialogueId = 80080219,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C878F0EE",
          NextDialogue = 80080220,
          SpeakNpcId = 790004,
          Subtitle = "...You have a point.",
          TalkActionId = {
            [1] = "790004:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F0EE"
        },
        [80080220] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다만... 네가 잘못 알고 있는 게 있어. 나는... 네 말처럼 그냥 그렇게 헌신적이지만은 않아.",
          DialogueId = 80080220,
          GUID = "C878F118",
          NextDialogue = 80080221,
          SpeakNpcId = 790004,
          Subtitle = "But you got one thing wrong — I'm not as selfless as you think.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F118"
        },
        [80080221] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어쩌면... 나 자신을 위해 그러는 거야.",
          DialogueId = 80080221,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878F142",
          NextDialogue = 80080222,
          SpeakNpcId = 790004,
          Subtitle = "To be more precise... I did all those things for myself.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F142"
        },
        [80080222] = {
          Camera = "37.734375,86.957642,146.630859,0.000001,-5.400023,-127.39193,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "난 죽음이 두렵지 않아... 아니, 솔직히 두렵긴 해.",
          DialogueId = 80080222,
          GUID = "C878F16C",
          NextDialogue = 80080223,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790004},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{790004},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 790004,
          Subtitle = "I'm not afraid of dying — no, that's an overstatement... I am afraid.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F16C"
        },
        [80080223] = {
          Camera = "-130.748047,-103.410034,139.367188,0.00001,3.199786,-140.194809,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "하지만 죽음보다 더 두려운 건... '사라진다'는 사실이야. 내가 잊히면 과거의 내 존재조차 사라지는 거잖아.",
          DialogueId = 80080223,
          GUID = "C878F196",
          NextDialogue = 80080224,
          SpeakNpcId = 790004,
          Subtitle = "But what terrifies me even more than death is... the idea of \"disappearing.\" Once you're forgotten, it's like the very evidence of your existence just gets wiped away.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F196"
        },
        [80080224] = {
          Camera = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래. 그러니까 네 말은, 조금이라도 더 오래 누군가의 기억에 남고 싶어서 이것저것 도와주고 있다는 거네?",
          DialogueId = 80080224,
          GUID = "C878F1C0",
          NextDialogue = 80080225,
          SpeakNpcId = 790006,
          Subtitle = "So you go out of your way to help as many people as possible, hoping they'll remember you for as long as they can — is that it?",
          TalkActionId = {
            [1] = "790004:Explain01_End",
            [2] = "790006:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F1C0"
        },
        [80080225] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아. 사실 난... 굉장히 이기적이야. 네 말대로 그 사람도 언젠가 떠나겠지.",
          DialogueId = 80080225,
          GUID = "C878F1EA",
          NextDialogue = 80080226,
          SpeakNpcId = 790004,
          Subtitle = "Yes... I'm actually... very selfish. You're right, {性别:he|she} will leave one day.",
          TalkActionId = {
            [1] = "790004:Agree",
            [2] = "790006:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F1EA"
        },
        [80080226] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{nickname}(은)는 아이스레이크 시티 사람이 아니야. 이곳 사람들과 달리 {nickname}(이)가 여기에 평생 묶여 있지 않을 거라는 건 처음부터 알고 있었어.",
          DialogueId = 80080226,
          GUID = "C878F214",
          NextDialogue = 80080227,
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} doesn't belong here. I've always known that {性别:he|she} is different — unlike us, trapped in Icelake forever.",
          TalkActionId = {
            [1] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F214"
        },
        [80080227] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래서 더 친해지고 싶어. 그럼 나중에 여길 떠날 때 나와 관련된 기억을 갖고 다양한 곳으로 모험을 떠나게 되는 거잖아.",
          DialogueId = 80080227,
          GUID = "C878F23E",
          NextDialogue = 80080228,
          SpeakNpcId = 790004,
          Subtitle = "And that's exactly why I want to be friends with {性别:him|her} — so that {性别:he|she} will carry memories of me while going on wonderful adventures around the world.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F23E"
        },
        [80080228] = {
          Camera = "-2481.224609,-566.944275,10.640625,0.0,1.999715,-93.189522,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...책에서 봤는데 북쪽 아스카드에는 지지 않는 태양이, 남쪽 엘리시안에는 산보다 높은 거대한 탑이, 동쪽 화서에는 별로 향하는 비행선이 있대...",
          DialogueId = 80080228,
          FinalCamera = "-2069.626953,-579.504761,10.279297,0.0,1.999715,-93.189522,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "C878F268",
          NextDialogue = 80080229,
          SpeakNpcId = 790004,
          Subtitle = "I've read about the never-setting sun in Askard to the north, the cloud-capped tower of Elysium down the south, and further east, the star-bound ships of Huaxu...",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F268"
        },
        [80080229] = {
          Camera = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇지만 그때 넌 없는 사람인걸.",
          DialogueId = 80080229,
          GUID = "C878F292",
          NextDialogue = 80080230,
          SpeakNpcId = 790006,
          Subtitle = "But you'll be gone by then.",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F292"
        },
        [80080230] = {
          Camera = "28.722656,72.22937,144.703125,0.00001,-5.200185,-127.592773,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{nickname}의 기억 속에 남아있겠지. 그렇다는 건 내 생명도 {nickname}, 그 친구와 함께 이어지는 거라고 믿어.",
          DialogueId = 80080230,
          GUID = "C878F2BC",
          NextDialogue = 80080231,
          SpeakNpcId = 790004,
          Subtitle = "But I'll live on in {性别:his|her} memories. That way, it's like my life continues with {性别:him|her}.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F2BC"
        },
        [80080231] = {
          Camera = "-272.109375,-179.431152,139.566406,0.000012,-3.599967,24.199917,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{nickname}(이)가 널 잊지 않을 거라고 어떻게 확신해?",
          DialogueId = 80080231,
          GUID = "C878F2E6",
          NextDialogue = 80080232,
          SpeakNpcId = 790006,
          Subtitle = "How do you know for sure that {性别:he|she} will remember you?",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F2E6"
        },
        [80080232] = {
          Camera = "21.574219,67.467163,141.941406,0.000012,-5.400146,-127.189346,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentKR = "나도... 확신할 수는 없어. 난 너처럼 똑똑하지 않아서 모르는 것도 많고, 남들이 날 기억하게 하는 방법도 몰라.",
          DialogueId = 80080232,
          GUID = "C878F310",
          NextDialogue = 80080233,
          SpeakNpcId = 790004,
          Subtitle = "I... I'm not sure. I'm not as smart as you. I don't understand many things, and I don't know how to make people remember me more.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F310"
        },
        [80080233] = {
          Camera = "21.574219,67.467163,141.941406,0.000012,-5.400146,-127.189346,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러니 시도해보는 거야... 만날 때마다 대화를 많이 나누고, 고민도 들어주고, 도움도 주다 보면...",
          DialogueId = 80080233,
          GUID = "C878F33A",
          NextDialogue = 80080234,
          SpeakNpcId = 790004,
          Subtitle = "So I just try my luck... like chatting with {性别:him|her}, listening to {性别:his|her} problems, and helping out with things...",
          TalkActionId = {
            [1] = "790004:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F33A"
        },
        [80080234] = {
          Camera = "-104.746094,-61.860352,133.810547,0.000011,3.199862,-132.793442,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{nickname}의 기억 한편에 내가 남지 않을까? 물론 내 생각이지만...",
          DialogueId = 80080234,
          GUID = "C878F364",
          NextDialogue = 80080235,
          SpeakNpcId = 790004,
          Subtitle = "Hopefully, that will leave more of an impression in {性别:his|her} memory — it's really just a shot in the dark though...",
          TalkActionId = {
            [1] = "790004:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F364"
        },
        [80080235] = {
          Camera = "38.255859,86.966919,163.544922,0.00009,-9.399658,-125.779823,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "휴...",
          DialogueId = 80080235,
          FinalCamera = "38.255859,86.966919,163.544922,0.000088,-9.399658,-122.98008,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "C878F38E",
          NextDialogue = 80080236,
          SpeakNpcId = 790006,
          Subtitle = "*Sigh*",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F38E"
        },
        [80080236] = {
          Camera = "38.255859,86.966919,163.544922,0.000088,-9.399658,-122.98008,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "프시케, 넌 정말 바보야.",
          DialogueId = 80080236,
          GUID = "C878F3B8",
          NextDialogue = 80080237,
          SpeakNpcId = 790006,
          Subtitle = "You can be such a fool sometimes, Psyche.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F3B8"
        },
        [80080237] = {
          Camera = "-272.960938,-184.779846,138.189453,0.000032,-3.000755,27.59623,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...선물을 주는 건 어때? 대신, 꽃은 빼고.",
          DialogueId = 80080237,
          GUID = "C878F3E2",
          NextDialogue = 80080238,
          SpeakNpcId = 790006,
          Subtitle = "...Maybe give {性别:him|her} a gift. But please, no more of your flowers.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F3E2"
        },
        [80080238] = {
          Camera = "-144.699219,-93.240356,140.8125,0.000035,0.199558,-130.997589,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아? 그, 그럼 뭘 주면 좋을까...",
          DialogueId = 80080238,
          GUID = "C878F40C",
          NextDialogue = 80080239,
          SpeakNpcId = 790004,
          Subtitle = "Huh? Then what should I get {性别:him|her}...?",
          TalkActionId = {
            [1] = "790004:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F40C"
        },
        [80080239] = {
          Camera = "-269.560547,-176.554443,135.869141,0.000043,-2.40075,25.794977,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "금방 망가지는 건 주지 마... 대신 오래 남고, 특별하면서 항상 지닐 수 있는 걸 줘봐. 되도록 실용적인 걸로 말이야.",
          DialogueId = 80080239,
          GUID = "C878F436",
          NextDialogue = 80080240,
          SpeakNpcId = 790006,
          Subtitle = "Something that won't break or go bad easily, that's for sure... It should be durable, special, and easy for {性别:him|her} to carry around at all times, ideally something practical.",
          TalkActionId = {
            [1] = "790004:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F436"
        },
        [80080240] = {
          Camera = "-269.560547,-176.554443,135.869141,0.000043,-2.40075,25.794977,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그럼... {nickname}(이)가 널 영원히 기억할 수도 있잖아.",
          DialogueId = 80080240,
          GUID = "C878F460",
          NextDialogue = 80080241,
          SpeakNpcId = 790006,
          Subtitle = "That way... it might always remind {性别:him|her} of you.",
          TalkActionId = {
            [1] = "790006:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F460"
        },
        [80080241] = {
          Camera = "-137.921875,-86.418274,139.603516,0.000013,0.598939,-130.579102,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...네 말이 맞아!",
          DialogueId = 80080241,
          GUID = "C878F48A",
          NextDialogue = 80080242,
          SpeakNpcId = 790004,
          Subtitle = "That's a great idea!",
          TalkActionId = {
