          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878F508",
          NextDialogue = 80080245,
          SpeakNpcId = 790004,
          Subtitle = "Alright, you need to eat the bread now.",
          TalkActionId = {
            [1] = "790004:Give"
