        [80080302] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "내가 좀 더 늦게 올 걸 그랬구나. 그랬으면 너희가 제대로 작별 인사라도 나눴을 텐데.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080302,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FE8C",
          NextDialogue = 80080303,
          SpeakNpcId = 790005,
          Subtitle = "I should've come a bit later to give you more time to say goodbye.",
          TalkActionId = {
            [1] = "790005:Explain01_Start"
          },
          TurnTo = {
            [1] = "790004:n(790005)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FE8C"
        },
        [80080303] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "헨릭 아저씨 말씀은...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080303,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FEB6",
          NextDialogue = 80080304,
          SpeakNpcId = 790004,
          Subtitle = "Dr Henrik, do you mean...",
          TalkActionId = {
            [1] = "790004:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FEB6"
        },
        [80080304] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "{nickname}, 그 녀석 말이야. 그 녀석이 널 붙잡았을 때, 너도 아쉬웠을 것 아니니.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080304,
          GUID = "C878FEE0",
          NextDialogue = 80080305,
          SpeakNpcId = 790005,
          Subtitle = "I mean that kid, . It was hard letting go of {性别:him|her} when {性别:he|she} grasped your hand, wasn't it?",
          TalkActionId = {
            [1] = "790004:Think_End",
            [2] = "790005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FEE0"
        },
        [80080305] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...네, 맞아요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080305,
          GUID = "C878FF0A",
          NextDialogue = 80080306,
          SpeakNpcId = 790004,
          Subtitle = "Yeah... you always see right through me.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF0A"
        },
        [80080306] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇지만 아무리 제 앞에 서 있더라도, 저와 {nickname}의 거리는 아이스레이크 시티와 바다만큼 멀다는 걸 알고 있어요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080306,
          GUID = "C878FF34",
          LookAt = {
            [1] = "790004:n(790004)"
          },
          NextDialogue = 80080307,
          SpeakNpcId = 790004,
          Subtitle = "But I know that even though {性别:he|she} was right in front of me, {性别:he|she} was actually very far away, as far as Icelake is from the ocean.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF34"
        },
        [80080307] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래서 그렇게 저를 붙잡는데도, 그 손을 맞잡을 수 없었어요. 제가 필사적으로 {nickname}(을)를 바라보려고 해도, 아무것도 보지 못한 것처럼요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080307,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FF5E",
          LookAt = {
            [1] = "790004:n(790005)"
          },
          NextDialogue = 80080308,
          SpeakNpcId = 790004,
          Subtitle = "So even though {性别:he|she} reached out, I couldn't really grasp {性别:his|her} hand, just as I tried so hard to look at {性别:him|her}, but couldn't see anything.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF5E"
        },
        [80080308] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...프시케, 할 이야기가 있단다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080308,
          GUID = "C878FF88",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080309,
          SpeakNpcId = 790005,
          Subtitle = "...Psyche, there's something I want you to know.",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790005:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF88"
        },
        [80080309] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "침식을 억제할 수 있는 약을 완성했어.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080309,
          GUID = "C878FFB2",
          NextDialogue = 80080310,
          SpeakNpcId = 790005,
          Subtitle = "The development of anti-deterioration medication is finished.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFB2"
        },
        [80080310] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "정말요? 전 더 연구해야 할 줄 알았어요...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080310,
          FacialId = {
            [1] = "790004:Shock01"
          },
          GUID = "C878FFDC",
          NextDialogue = 80080311,
          SpeakNpcId = 790004,
          Subtitle = "Already? I thought the research would take longer...",
          TalkActionId = {
            [1] = "790004:Alright_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFDC"
        },
        [80080311] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "사실 연구는 훨씬 오래전부터 시작했지만, 헤일리가 세상을 뜨면서 멈췄던 건데. 그러다 너... 너희를 위해 다시 시작했단다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080311,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C8790006",
          LookAt = {
            [1] = "790005:n(790004)"
          },
          NextDialogue = 80080312,
          SpeakNpcId = 790005,
          Subtitle = "I started the research years ago but put it aside after Hayley's death. I only picked it up again for you... for all of you.",
          TalkActionId = {
            [1] = "790005:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790006"
        },
        [80080312] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다행히 이론은 모두 똑똑히 기억하고 있어서 가장 핵심이 되는 <H>반짝이는 수정</>만 있다면, 당시 실험을 대부분 재현할 수 있을 거야...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080312,
          GUID = "C8790030",
          NextDialogue = 80080313,
          SpeakNpcId = 790005,
          Subtitle = "Fortunately, all the previous theoretical data is still fresh in my mind, and with that piece of the Crystallo of Stella, I managed to replicate most of the experimental steps...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790030"
        },
        [80080313] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "잘됐어요! 정말 기쁜 소식이네요... 그런데 헨릭 아저씨, 목소리가 왜 그렇게 안 좋은가요? 기쁜 일이잖아요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080313,
          GUID = "C879005A",
          NextDialogue = 80080314,
          SpeakNpcId = 790004,
          Subtitle = "That's great! Your research succeeded! But... this is good news, right? Why do you still look so sad...?",
          TalkActionId = {
            [1] = "790004:Alright_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879005A"
        },
        [80080314] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그게, 네가 이해할 수 있을지 모르겠다만...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080314,
          GUID = "C8790084",
          NextDialogue = 80080315,
          SpeakNpcId = 790005,
          Subtitle = "*sigh* It's complicated...",
          TalkActionId = {
            [1] = "790005:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790084"
        },
        [80080315] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "수정은 굉장히 불안정한 물질이야. 특정 약물의 도움을 받으면 침식의 진행을 억제할 수 있지만, 반대로 침식을 가속화시킬 수도 있단다... 그리고 이 두 가지 결과를 만들어내는 합성 방법에는 정말 종이 한 장 차이라고 할 정도로 미세한 차이밖에 없단다.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080315,
          GUID = "C87900AE",
          NextDialogue = 80080316,
          SpeakNpcId = 790005,
          Subtitle = "Crystallo is highly unstable. Under specific medicinal catalysts, it can suppress the process of deterioration, or accelerate it... The conditions triggering each process are only minutely different.",
          TalkActionId = {
            [1] = "790005:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87900AE"
        },
        [80080316] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "수정에 관한 화서의 약학 논문은, 휘페르보레아 제국에 남아 있지 않단다. 그래서 모든 단계가 올바르게 진행되고 있는지 판단할 길이 없어.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080316,
          GUID = "C87900D8",
          NextDialogue = 80080317,
          SpeakNpcId = 790005,
          Subtitle = "Sadly, all the relevant pharmacological texts from Huaxu were lost in Hyperborea, and I can't verify each step of my work purely through theory.",
          TalkActionId = {
            [1] = "790005:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87900D8"
        },
        [80080317] = {
          Camera = "271.882812,218.0,222.382812,0.0,0.0,-172.398712,35.0,500.0,false,Manual,2.8",
          ContentKR = "유일한 방법은 임상실험뿐이지... 하지만 검증되지 않은 약물을 너희에게 쓸 엄두가 나지 않는구나.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080317,
          FinalCamera = "271.882812,268.0,222.382812,0.0,0.0,-172.398712,35.0,300.0,false,Manual,2.8",
          GUID = "C8790102",
          NextDialogue = 80080318,
          SpeakNpcId = 790005,
          Subtitle = "The only option is clinical trials... but I can't bring myself to test an unverified new drug on you.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790102"
        },
        [80080318] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603367,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아마도 헨릭 아저씨가 저희를 너무 생각하셔서... 침식 억제제의 검증을 마치지 못한 거겠죠? 아저씨, 제가 연구를 돕고 싶어요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080318,
          GUID = "C879012C",
          NextDialogue = 80080319,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 790004,
          Subtitle = "Perhaps your kindness is why the research on the anti-deterioration drug hasn't progressed further. Dr Henrik, please allow me to help you with the clinical trials.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879012C"
        },
        [80080319] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "히프노스의 집은 고통을 없애기 위해 만든 곳이야... 내가 너희를 이용해 실험한다면, 군단이 하는 짓과 뭐가 다르겠니!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080319,
          GUID = "C8790156",
          NextDialogue = 80080320,
          SpeakNpcId = 790005,
          Subtitle = "Hypnos' House was founded to alleviate suffering... If I use you for experiments, how am I any different from the Legion!?",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790005:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790156"
        },
        [80080320] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇지 않아요... 헨릭 아저씨는 저희를 돌보며 고통을 줄여주셨잖아요. 하지만 사실 고통이 사라진 게 아니라, 아저씨가 대신 짊어지신 것뿐이죠.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080320,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C8790180",
          NextDialogue = 80080321,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"DisagreeHead\"},Duration{1}},PlayAnimation{ActorId{790004},AnimationId{\"Talk02_Start\"},Duration{2}}}",
          SpeakNpcId = 790004,
          Subtitle = "It's not like that... You've been taking care of us, going out of your way to ease our pain, but the pain hasn't disappeared — you've simply taken it upon yourself.",
          TalkActionId = {
            [1] = "790005:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790180"
        },
        [80080321] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러니까 아저씨를 저도 도울 수 있게 해주세요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080321,
          GUID = "C87901AA",
          NextDialogue = 80080322,
          SpeakNpcId = 790004,
          Subtitle = "So, please let me share some of that burden.",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901AA"
        },
        [80080322] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그게 말은 쉽지만... 그 약을 먹는다는 게 무슨 의미인 줄 아니?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080322,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C87901D4",
          NextDialogue = 80080323,
          SpeakNpcId = 790005,
          Subtitle = "It's more complicated than you might think... Do you realise what could happen if you take that medicine?",
          TalkActionId = {
            [1] = "790005:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901D4"
        },
        [80080323] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "제가 잘 이해했는지 모르겠지만... 효과가 있을 수도, 또 없을 수도 있다는 말씀 아닌가요?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080323,
          GUID = "C87901FE",
          NextDialogue = 80080324,
          Scripts = "SEQ{LookAt{LookAtDescription{\"790004:n(790004)\"}},LookAt{_delay{2},LookAtDescription{\"790004:n(790005)\"}}}",
          SpeakNpcId = 790004,
          Subtitle = "... I'm not sure if I get this right. Do you mean it might work, but also might not?",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87901FE"
        },
        [80080324] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...가능성은 반뿐이야.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080324,
          GUID = "C8790228",
          NextDialogue = 80080325,
          SpeakNpcId = 790005,
          Subtitle = "There's a fifty-fifty chance.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790228"
        },
        [80080325] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "완전히 치유되어 새로운 삶을 살게 되거나, 오히려 반대로...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080325,
          GUID = "C8790252",
          NextDialogue = 80080326,
          SpeakNpcId = 790005,
          Subtitle = "You could recover and gain a second chance at life, or...",
          TalkActionId = {
            [1] = "790005:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790252"
        },
        [80080326] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "침식 상태가 더 빠르게 악화될 수도 있단다... 마지막 남은 목숨마저 누리지 못할 수도 있어...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080326,
          GUID = "C879027C",
          NextDialogue = 80080327,
          SpeakNpcId = 790005,
          Subtitle = "Your condition could deteriorate rapidly... You might even be robbed of your last moments.",
          TalkActionId = {
            [1] = "790005:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879027C"
        },
        [80080327] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080327,
          GUID = "C87902A6",
          LookAt = {
            [1] = "790004:n(790004)"
          },
          NextDialogue = 80080328,
          SpeakNpcId = 790004,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902A6"
        },
        [80080328] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "헨릭 아저씨, 전 이미 결정했어요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080328,
          GUID = "C87902D0",
          LookAt = {
            [1] = "790004:n(790005)"
          },
          NextDialogue = 80080329,
          SpeakNpcId = 790004,
          Subtitle = "Dr Henrik, I've made up my mind.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902D0"
        },
        [80080329] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "침식 억제제는 저희의 고통을 줄여줄 수 있는 희망이에요. 단 1%의 희망만 있다고 해도 아저씨를 도와 연구를 완성하고 싶어요. 게다가...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080329,
          GUID = "C87902FA",
          NextDialogue = 80080330,
          SpeakNpcId = 790004,
          Subtitle = "The anti-deterioration drug is a chance to ease the pain of us all. Even if the chances of success are slim to none, I'd still like to help with your research. Besides...",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87902FA"
        },
        [80080330] = {
          Camera = "-127.080078,-30.343323,142.15625,0.000079,-5.799957,57.598873,50.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "제, 제가 달라진 것 같거든요... 예전의 제가 아니에요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080330,
          GUID = "C8790324",
          NextDialogue = 80080331,
          SpeakNpcId = 790004,
          Subtitle = "I feel like I've changed... I'm not who I used to be.",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790324"
        },
        [80080331] = {
          Camera = "-87.792969,98.007385,119.857422,0.000075,6.799897,-100.99704,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "달라졌다고...?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080331,
          GUID = "C879034E",
          NextDialogue = 80080332,
          SpeakNpcId = 790005,
          Subtitle = "What do you mean?",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879034E"
        },
        [80080332] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "누군가를 알게 되고, 모험을 하고 나니... 달라진 것 같아요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080332,
          GUID = "C8790378",
          NextDialogue = 80080333,
          SpeakNpcId = 790004,
          Subtitle = "I've changed ever since I met someone and went on an adventure.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790378"
        },
        [80080333] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이제 욕심이 생겼어요... 제게 더 많은 시간이 주어졌으면 좋겠고, 또...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080333,
          GUID = "C87903A2",
          NextDialogue = 80080334,
          SpeakNpcId = 790004,
          Subtitle = "I've become much greedier... I now yearn for more time, more of everything...",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903A2"
        },
        [80080334] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "누군가의 손을 붙잡고 아이스레이크 시티를 떠나 머나먼 곳으로 떠나고 싶어요...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080334,
          GUID = "C87903CC",
          NextDialogue = 80080335,
          SpeakNpcId = 790004,
          Subtitle = "I wish to hold someone's hand and escape Icelake, to travel to far-off lands...",
          TalkActionId = {
            [1] = "790004:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903CC"
        },
        [80080335] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "부모님의 나이만큼 살고 싶다는 욕심이 생겼어요... 주름이 가득한 할머니가 되어서... 광장에 앉아 새에게 먹이를 주고, 성 안의 아이들에게 옛날이야기를 들려주고 싶어요...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080335,
          GUID = "C87903F6",
          NextDialogue = 80080336,
          SpeakNpcId = 790004,
          Subtitle = "I wish to grow older... so that one day I'll become a wrinkled old lady, sitting in the square, feeding birds and sharing stories of my youth with children...",
          TalkActionId = {
            [1] = "790004:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87903F6"
        },
        [80080336] = {
          Camera = "-178.794922,-57.247498,139.419922,0.000046,-6.999994,44.603405,32.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "예전에는 저에게 남은 시간만 잘 보내면 충분할 거라고 생각했어요. 하지만 지금은...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080336,
          GUID = "C8790420",
          NextDialogue = 80080337,
          SpeakNpcId = 790004,
          Subtitle = "I once thought that making the most of my last days was enough. But now, I want more...",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790420"
        },
        [80080337] = {
          Camera = "-115.541016,2.555298,138.173828,0.000146,-6.001127,46.597878,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "'살고' 싶어요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080337,
          GUID = "C879044A",
          NextDialogue = 80080338,
          SpeakNpcId = 790004,
          Subtitle = "I want to LIVE.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879044A"
        },
        [80080338] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그러니, 헨릭 아저씨... 부탁이에요.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080338,
          GUID = "C8790474",
          NextDialogue = 80080339,
          SpeakNpcId = 790004,
          Subtitle = "So, Dr Henrik, please allow me to help with the research.",
          TalkActionId = {
            [1] = "790004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C8790474"
        },
        [80080339] = {
          Camera = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "'어차피 사람답게 살 수 없다면, 적어도 사람답게 죽고 싶어요...'",
          DialogueId = 80080339,
          GUID = "C879049E",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080340,
          SpeakNpcId = 790005,
          Subtitle = "\"If fate decides I can't live like a person, then at least let me die like one...\"",
          TalkActionId = {
            [1] = "790005:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879049E"
        },
        [80080340] = {
          Camera = "-87.298828,86.861511,111.849609,0.00008,9.999362,-101.195549,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이건 헤일리... 내 딸 헤일리가 마지막 밤에 나에게 부탁했던 소원이란다. 너희 둘은 다르지만 또 한편으로는 닮았구나...",
          DialogueId = 80080340,
          GUID = "C87904C8",
          LookAt = {
            [1] = "790005:n(790004)"
          },
          NextDialogue = 80080341,
          SpeakNpcId = 790005,
          Subtitle = "That was Hayley — my daughter's last wish. You and her are so alike, yet so different...",
          TalkActionId = {
            [1] = "790005:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87904C8"
        },
        [80080341] = {
          Camera = "-137.392578,-0.853027,138.126953,0.000042,13.199668,-95.195374,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "'사람답게 살고 싶다'... 네 소원이 뭔지 이해했다.",
          DialogueId = 80080341,
          GUID = "C87904F2",
          LookAt = {
            [1] = "790005:n(790005)"
          },
          NextDialogue = 80080342,
          SpeakNpcId = 790005,
          Subtitle = "\"To live like a person\" — I understand your wish now.",
          TalkActionId = {
            [1] = "790005:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C87904F2"
        },
        [80080342] = {
          Camera = "-123.386719,-265.981384,183.080078,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentKR = "운명의 신이시여... 부디 한 번만 절 불쌍히 여기시어... 이 아이의 소원을 이룰 수 있게 해주십시오.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080342,
          FinalCamera = "-123.013672,-238.728149,177.398438,0.000053,-11.799984,89.199028,32.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "C879051C",
          SpeakNpcId = 790005,
          Subtitle = "Fate, grant me mercy just this once... allow me to help her fulfil this wish.",
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "790005:p(180)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C879051C"
        },
        [80090100] = {
          ContentKR = "히히, 오늘은 뭘 하고 놀아볼까?",
          DialogueId = 80090100,
          GUID = "C87F4608",
          Subtitle = "Heehee, what mischief shall we get into today?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4608"
        },
        [80090101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "......",
          DialogueId = 80090101,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4632",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090102,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4632"
        },
        [80090102] = {
          ContentKR = "......",
          DialogueId = 80090102,
          GUID = "C87F465C",
          NextDialogue = 80090103,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F465C"
        },
        [80090103] = {
          ContentKR = "...야! 내가 방금 음료수 마시자마자 갑자기 사라졌잖아, 너는 왜 걱정도 안 하는 거야!",
          DialogueId = 80090103,
          GUID = "C87F4686",
          NextDialogue = 80090104,
          SpeakNpcId = 92301,
          Subtitle = "...Hey! Didn't you see I suddenly vanished after finishing my drink? How could you just act like nothing happened?!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4686"
        },
        [80090104] = {
          ContentKR = "이 대낮에! '악마대도'가 아무도 모르게 사라졌는데! 이상하거나 걱정되지 않는 거냐고!",
          DialogueId = 80090104,
          GUID = "C87F46B0",
          NextOptions = {
            [1] = 80090105,
            [2] = 80090107
          },
          SpeakNpcId = 92301,
          Subtitle = "Right in broad daylight, Demon Tabethe the Red Hand mysteriously disappeared! Aren't you at least a bit curious or worried?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F46B0"
        },
        [80090105] = {
          ContentKR = "방금 여기에 의자가 하나 더 생겼던데, 네가 변한 거 아니었어?",
          DialogueId = 80090105,
          GUID = "C87F46DA",
          NextDialogue = 80090106,
          Subtitle = "There was an extra chair here... It was you, wasn't it?"
        },
        [80090106] = {
          ContentKR = "아닛! 나의 이 대단한 위장 기술을 눈치채다니!",
          DialogueId = 80090106,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F4704",
          NextDialogue = 80090109,
          SpeakNpcId = 92301,
          Subtitle = "What?! You saw through my awesome disguise?!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4704"
        },
        [80090107] = {
          ContentKR = "걱정? 타비사가 나를 즐겁게 해주려고 의자로 변했잖아. 난 오히려 기분이 좋은걸.",
          DialogueId = 80090107,
          GUID = "C87F472E",
          NextDialogue = 80090108,
          Subtitle = "Why would I be worried? If anything, I appreciate that you turned into a chair just to entertain me."
        },
        [80090108] = {
          ContentKR = "윽, 김칫국 그만 마셔. 난 그저 널 놀라게 하려고 그런 거야! 놀, 라, 게!",
          DialogueId = 80090108,
          GUID = "C87F4758",
          NextDialogue = 80090109,
          SpeakNpcId = 92301,
          Subtitle = "Pff, get over yourself — I was just trying to spook you! BOO! Get it?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4758"
        },
        [80090109] = {
          ContentKR = "...칫, 이번은 실수야. 다음에는 네가 눈치챌 수 없게 다른 걸로 변하겠어!",
          DialogueId = 80090109,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4782",
          NextDialogue = 80090110,
          SpeakNpcId = 92301,
          Subtitle = "Hmph, I slipped up this time. But next time, I'll turn into something you'd never expect!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4782"
        },
        [80090110] = {
          ContentKR = "뭐로 변할까... 술통? 샹들리에? 아니면 망치?",
          DialogueId = 80090110,
          GUID = "C87F47AC",
          NextDialogue = 80090111,
          SpeakNpcId = 92301,
          Subtitle = "What to turn into next... Maybe a barrel? A chandelier? Or even a big hammer?",
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F47AC"
        },
        [80090111] = {
          ContentKR = "와, 정말 대단한데?",
          DialogueId = 80090111,
          GUID = "C87F47D6",
          NextDialogue = 80090112,
          SpeakNpcId = 790008,
          Subtitle = "Wow, you're really good at this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F47D6"
        },
        [80090112] = {
          ContentKR = "당연하지! 내 위... 위 뭐였더라... 위당?... 아, 위장! 그래, '위장' 실력이 얼마나 대단한데!",
          DialogueId = 80090112,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4800",
          NextDialogue = 80090113,
          SpeakNpcId = 92301,
          Subtitle = "Of course! I heard this trick of mine is called... caramel... camel... camel-something... Ah — camouflage! That's it!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4800"
        },
        [80090113] = {
          ContentKR = "뭐든지 다 변할 수 있는 거야?",
          DialogueId = 80090113,
          GUID = "C87F482A",
          NextDialogue = 80090114,
          SpeakNpcId = 790008,
          Subtitle = "So you can turn into anything?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F482A"
        },
        [80090114] = {
          ContentKR = "히히, 물론이지! 잘 봐!",
          DialogueId = 80090114,
          GUID = "C87F4854",
          NextDialogue = 80090144,
          SpeakNpcId = 92301,
          Subtitle = "Hehe, you bet! Watch this—",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4854"
        },
        [80090115] = {
          Camera = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
          ContentKR = "지금 그쪽이 거절할 수 없는 제안을 할게. 곰곰이 잘 생각해서 대답해.",
          DialogueId = 80090115,
          GUID = "C87F487E",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090116,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I'll make an offer you can't refuse. Think it over before you respond.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F487E"
        },
        [80090116] = {
          ContentKR = "날 깨운 것은 장사인데, 널 깨운 것은 뭐야?",
          DialogueId = 80090116,
          GUID = "C87F48A8",
          NextOptions = {
            [1] = 80090117,
            [2] = 80090119
          },
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What wakes me is business; what about you?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F48A8"
        },
        [80090117] = {
          ContentKR = "푸핫, 날 깨운 건 태양보다 빛나는 악마대도의 반짝임이지!",
          DialogueId = 80090117,
          GUID = "C87F48D2",
          NextDialogue = 80090118,
          Subtitle = "Haha — what wakes me is the blinding brilliance of Demon Tabethe the Red Hand!"
        },
        [80090118] = {
          ContentKR = "히히, 듣기 좋은데? 네가 만든 음료수보다 훨씬 달콤한걸!",
          DialogueId = 80090118,
          FacialId = {
            [1] = "790052:Happy01"
          },
          GUID = "C87F48FC",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hehe, you're so sweet — sweeter than this drink you made!",
          TalkActionId = {
            [1] = "790052:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F48FC"
        },
        [80090119] = {
          ContentKR = "푸핫, 카밀라 님한테 이를 거야!",
          DialogueId = 80090119,
          GUID = "C87F4926",
          NextDialogue = 80090120,
          Subtitle = "Haha — I'm going to tell on you to Camilla!"
        },
        [80090120] = {
          ContentKR = "나는 하나도 안 무섭거든! 그 누구도 악마대도를 막을 수는 없다고!",
          DialogueId = 80090120,
          FacialId = {
            [1] = "790052:Confident01"
          },
          GUID = "C87F4950",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "I'm not scared of her! No one can catch Demon Tabethe the Red Hand!",
          TalkActionId = {
            [1] = "790052:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4950"
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "근데 아무거나 다 될 수 있는 건 아니야. 너무 작거나 크면 변할 수 없거든. 고양이나 통나무는 가능하지만, 쥐랑 가로등은 불가능해.",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          Subtitle = "But I can't turn into anything too big or too small. I can do a cat, but not a mouse; a barrel, but not a lamppost.",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F497A"
        },
        [80090122] = {
          ContentKR = "하지만 이 정도면 충분해. 웬만한 사람은 나의 완벽한 위장을 눈치채지 못하거든! 내가 캔이나, 상자, 쓰레기통으로 변해버리면 나쁜 도둑들은 다 내 손안에 있는 거나 다름없지!",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301,
          Subtitle = "That's enough to fool most people, though. I can just turn into a bin or a crate, and those rotten thieves won't know what hit them!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49A4"
        },
        [80090123] = {
          ContentKR = "...망했네, 앞으로 골치 아프겠어.",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124,
          Subtitle = "...Oh boy, this might be a problem someday."
        },
        [80090124] = {
          ContentKR = "혼자 뭐라고 중얼대는 거야?",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F49F8",
          NextDialogue = 80090125,
          SpeakNpcId = 92301,
          Subtitle = "What are you mumbling about?",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F49F8"
        },
        [80090125] = {
          ContentKR = "아무것도 아니야. 네가 엄청 대단하다고.",
          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008,
          Subtitle = "Nothing, I just meant you are awesome.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A22"
        },
        [80090126] = {
          ContentKR = "그래도 캔이나 상자, 쓰레기통 같은 것들로 변하지는 마. 지나가던 누군가 부수거나 뒤지면 어떡해...",
          DialogueId = 80090126,
          GUID = "C87F4A4C",
          NextDialogue = 80090127,
          SpeakNpcId = 790008,
          Subtitle = "But maybe avoid turning into bins or crates next time. Wouldn't want someone accidentally smashing you while looking for something useful...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A4C"
        },
        [80090127] = {
          ContentKR = "도대체 누가 그런 나쁜 손버릇을 가졌길래?",
          DialogueId = 80090127,
          GUID = "C87F4A76",
          NextDialogue = 80090128,
          SpeakNpcId = 92301,
          Subtitle = "Who would do that?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4A76"
        },
        [80090128] = {
          ContentKR = "음... 길을 지나가던 호기심이 엄청난 시민?",
          DialogueId = 80090128,
          GUID = "C87F4AA0",
          NextDialogue = 80090129,
          SpeakNpcId = 790008,
          Subtitle = "Er... some overly curious passersby, perhaps?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4AA0"
        },
        [80090129] = {
          ContentKR = "쓸모 있을 때는 좋아하고, 쓸모 없어지면 버리다니. 나쁜 어른들은 다 똑같아!",
          DialogueId = 80090129,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4ACA",
          NextDialogue = 80090130,
          SpeakNpcId = 92301,
          Subtitle = "Always taking what's useful and tossing the rest — typical bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4ACA"
        },
        [80090130] = {
          ContentKR = "지나가던 시민은 아무도 해치지 않아! 근데 왜 계속 '나쁜 어른' 얘기를 하는 거야?",
          DialogueId = 80090130,
          GUID = "C87F4AF4",
          NextDialogue = 80090136,
          SpeakNpcId = 790008,
          Subtitle = "Those passersby wouldn't mean to hurt anyone! Anyway, who are those \"bad grown-ups\" you always talk about?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4AF4"
        },
        [80090131] = {
          ContentKR = "굉장하네. 그래도 네가 착한 아이라서 다행이야.",
          DialogueId = 80090131,
          GUID = "C87F4B1E",
          NextDialogue = 80090132,
          Subtitle = "Sounds impressive; good thing you're not a baddy."
        },
        [80090132] = {
          ContentKR = "무슨 뜻이야?",
          DialogueId = 80090132,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F4B48",
          NextDialogue = 80090133,
          SpeakNpcId = 92301,
          Subtitle = "What do you mean?",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B48"
        },
        [80090133] = {
          ContentKR = "그러니까, 똑똑한데 나쁜 속셈을 품은 사람이 그런 기술까지 있다면 온통 난리가 나지 않겠어?",
          DialogueId = 80090133,
          GUID = "C87F4B72",
          NextDialogue = 80090134,
          SpeakNpcId = 790008,
          Subtitle = "I mean, imagine if someone smart but nasty had your skills — the whole town would be in chaos.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B72"
        },
        [80090134] = {
          ContentKR = "흐음, 맞는 말이야! 나는 나쁜 어른과 전혀 다르다고! 잠깐, 설마 지금 '악마대도'가 똑똑하지 않다는 거야?",
          DialogueId = 80090134,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F4B9C",
          NextDialogue = 80090135,
          SpeakNpcId = 92301,
          Subtitle = "Mm-hmm, I thought so too! I'm nothing like those bad grown-ups. Wait, are you saying I'm not smart?",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4B9C"
        },
        [80090135] = {
          ContentKR = "그럴 리가, 타비사는 똑똑한 악마잖아. 그나저나 '나쁜 어른'은 무슨 말인지 더 궁금한데.",
          DialogueId = 80090135,
          GUID = "C87F4BC6",
          NextDialogue = 80090136,
          SpeakNpcId = 790008,
          Subtitle = "Of course not, Tabethe is very smart. Anyway, I've been curious about these \"bad grown-ups\" you always talk about. Who are they?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4BC6"
        },
        [80090136] = {
          ContentKR = "약자를 괴롭히는 나쁜 어른을 말하는 거야! 내가 만났던 첫 나쁜 어른은 보육원의 아이들을 돌보는 사람이었어... 칫, 말만 보살핀다고 포장하지만 사실 감옥처럼 감시한다는 말이 더 어울렸달까?",
          DialogueId = 80090136,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4BF0",
          NextDialogue = 80090137,
          SpeakNpcId = 92301,
          Subtitle = "Any bullies who pick on the weak! The first time I met bad grown-ups was at the orphanage. Those caretakers... well, calling them \"caretakers\" is a stretch — they were more like jailers.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4BF0"
        },
        [80090137] = {
          ContentKR = "어릴 때 배가 고팠던 나는 주방에 몰래 가서 음식을 뒤졌거든. 그런데 그걸 발견한 나쁜 어른이 날 때렸어. 너무 나빠! 밥도 안 줬으면서!",
          DialogueId = 80090137,
          GUID = "C87F4C1A",
          NextDialogue = 80090138,
          SpeakNpcId = 92301,
          Subtitle = "Back then, when they caught me sneaking food in the kitchen, they'd beat me. Ugh, those monsters! I only did it because they never fed me enough!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4C1A"
        },
        [80090138] = {
          ContentKR = "내 눈앞에 또 보이기만 해봐! 지붕에 거꾸로 매달아서 내가 주방에 있는 음식을 먹어 치우는 걸 지켜보게 할 거야!",
          DialogueId = 80090138,
          GUID = "C87F4C44",
          NextOptions = {
            [1] = 80090139,
            [2] = 80090140
          },
          SpeakNpcId = 92301,
          Subtitle = "If I ran into them now, I'd hang them upside down from the ceiling and make them watch as I eat up all the food in the kitchen!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4C44"
        },
        [80090139] = {
          ContentKR = "다 지나간 일이야. 지금은 그 어떤 나쁜 어른도 타비사를 때릴 수 없어.",
          DialogueId = 80090139,
          GUID = "C87F4C6E",
          NextDialogue = 80090141,
          Subtitle = "There, there. Those bad grown-ups can't hurt you anymore."
        },
        [80090140] = {
          ContentKR = "맞아. 그 나쁜 녀석들에게 본때를 보여줘야 해.",
          DialogueId = 80090140,
          GUID = "C87F4C98",
          NextDialogue = 80090141,
          Subtitle = "Sounds great! Those baddies so deserve that."
        },
        [80090141] = {
          ContentKR = "흥! 맞아, 맞아!",
          DialogueId = 80090141,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4CC2",
          NextDialogue = 80090142,
          SpeakNpcId = 92301,
          Subtitle = "Hmph! Exactly!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4CC2"
        },
        [80090142] = {
          ContentKR = "음료수 다 마셨어. '나쁜 어른'에 대한 이야기는 다음에 또 들려줄게. 이제 나가서 놀자!",
          DialogueId = 80090142,
          GUID = "C87F4CEC",
          NextDialogue = 80090143,
          SpeakNpcId = 92301,
          Subtitle = "Alright, I've finished my drink. I'll tell you more about those bad grown-ups next time. Now, let's go play outside!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4CEC"
        },
        [80090143] = {
          ContentKR = "히히히, 우리 숨바꼭질하고 놀자. 이번에는 찾기 힘들걸!",
          DialogueId = 80090143,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F4D16",
          SpeakNpcId = 92301,
          Subtitle = "Hehehe, wanna play hide and seek? I bet you won't find me so easily this time!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/001/C87F4D16"
        },
        [80090144] = {
          DialogueId = 80090144,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "C87F4D17",
          IsBlack = 1
        },
        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "음~ 조금 짜지만 맛있어. 꼭 바닷바람 맛의 솜사탕 같아!",
          DialogueId = 80090201,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F569A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090202,
          SpeakNpcId = 92301,
          Subtitle = "Mmm, this drink's a bit salty but so yummy — like sea breeze-flavored cotton candy!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F569A"
        },
        [80090202] = {
          ContentKR = "아주 예전에 비슷한 걸 마셔본 적 있는 것 같아. 그때는 나랑 부모님이 타고 있던 배가 침몰하지 않았고, 나도 떠내려와서 마을의 보육원으로 보내지기 전이었지...",
          DialogueId = 80090202,
          GUID = "C87F56C4",
          NextDialogue = 80090203,
          SpeakNpcId = 92301,
          Subtitle = "It kind of reminds me of something I drank long ago... back when I was still with my mom and dad, before our ship sank and I ended up at that orphanage...",
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F56C4"
        },
        [80090203] = {
          ContentKR = "다시 돌아간다면, 차라리 혼자 떠돌이 생활을 하겠어! 그 나쁜 어른들은 먹을 것도 제대로 안 줬는데, 음료는 더더욱 없었으니까.",
          DialogueId = 80090203,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F56EE",
          NextDialogue = 80090204,
          SpeakNpcId = 92301,
          Subtitle = "But honestly, I'd choose wandering on my own over staying with those bad grown-ups! They were stingy with food, not to mention anything as nice as a drink.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F56EE"
        },
        [80090204] = {
          ContentKR = "떠돌아다니다가 쓰레기통의 음식을 구해서 먹는 게, 나쁜 어른들이 있는 보육원에서 굶는 것보다 훨씬 나아!",
          DialogueId = 80090204,
          GUID = "C87F5718",
          NextDialogue = 80090205,
          SpeakNpcId = 92301,
          Subtitle = "At least being on the streets, I could scavenge for something to eat — beats starving under the watch of those bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5718"
        },
        [80090205] = {
          ContentKR = "좀 더 크고 나서는 나처럼 뿔이 달리고 입양되지 못한 아이들을 데려가는 분이 있었는데, 듣기로는 부잣집에 입양된 거라고 하더라고.",
          DialogueId = 80090205,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F5742",
          NextDialogue = 80090206,
          SpeakNpcId = 92301,
          Subtitle = "When I got a bit older, groups of rich visitors would come by now and then, taking away some unwanted kids with horns like me. People at the orphanage said they were adopted by rich families.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5742"
        },
        [80090206] = {
          ContentKR = "나는 다른 엄마나 아빠가 생기기는 건 싫지만 배부르게 먹고 싶어서 부잣집에 가고 싶었거든. 그런데 나쁜 어른들은 내가 너무 말썽꾸러기라 그분들이 날 입양하지 않는 거라고 했어.",
          DialogueId = 80090206,
          GUID = "C87F576C",
          NextDialogue = 80090207,
          SpeakNpcId = 92301,
          Subtitle = "I didn't want new parents, but I thought being in a rich home meant I'd never go hungry again, so I wanted them to take me. But those bad grown-ups said no rich people would want a naughty troublemaker like me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F576C"
        },
        [80090207] = {
          ContentKR = "흥! 그게 어쨌다는 거야. 이 타비사 님이 그런다고 고분고분해질 리 있나! 어쨌든 난 이 구질구질한 곳에 하루도 더 있기 싫어서 그 손님이 한눈판 틈을 타서 캐리어로 변신했어.",
          DialogueId = 80090207,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5796",
          NextDialogue = 80090208,
          SpeakNpcId = 92301,
          Subtitle = "Hmph! As if I'd ever behave just to be chosen! I couldn't stand that awful place for another day, so during their visit, I transformed into one of their suitcases.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5796"
        },
        [80090208] = {
          ContentKR = "부자들도 똑똑한 건 아닌가 봐! 아무도 눈치채지 못하고 나를 들고 나가더라고. 근데 가는 동안 내 귀를 손잡이처럼 계속 잡아당겨서, 어찌나 아프던지!",
          DialogueId = 80090208,
          GUID = "C87F57C0",
          NextOptions = {
            [1] = 80090209,
            [2] = 80090211
          },
          SpeakNpcId = 92301,
          Subtitle = "Turns out those rich folks weren't too bright — they just picked me up and walked away, completely clueless. It was rough on my ears, though — they were pulled as the handles, and I almost got dropped along the way!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F57C0"
        },
        [80090209] = {
          ContentKR = "윽, 듣기만 해도 아프네! 앞으로 네 귀는 내가 잘 지켜줄게!",
          DialogueId = 80090209,
          GUID = "C87F57EA",
          NextDialogue = 80090210,
          Subtitle = "Oof, that must've hurt a lot! I'll take extra care of your ears from now on!"
        },
        [80090210] = {
          ContentKR = "...뭔가 좀 이상한데... 됐어, 그게 중요한 게 아니야!",
          DialogueId = 80090210,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F5814",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          Subtitle = "...Thanks, sounds a bit weird though...",
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5814"
        },
        [80090211] = {
          ContentKR = "타비사, 그런 곳에서 도망쳐 나왔다니. 역시 미래의 '악마대도'는 남달랐네!",
          DialogueId = 80090211,
          GUID = "C87F583E",
          NextDialogue = 80090212,
          Subtitle = "Managing to escape from that place proves Demon Tabethe the Red Hand was awesome even as a kid!"
        },
        [80090212] = {
          ContentKR = "히히, 당연하지! 근데 그때는 내가 아직 위장에 익숙하지 않았어. 아니었다면 귀가 손잡이로 변할 일은 없었을 텐데.",
          DialogueId = 80090212,
          GUID = "C87F5868",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          Subtitle = "Hehe, you bet! Too bad I wasn't as skilled back then, or I wouldn't have turned my ears into the handles.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5868"
        },
        [80090213] = {
          ContentKR = "원래는 입양된 아이들 사이에 슬쩍 끼어들어가려고 했어. 부잣집에 입양된다면 더 이상 배고플 일은 없겠다고 생각했거든.",
          DialogueId = 80090213,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5892",
          NextDialogue = 80090214,
          SpeakNpcId = 92301,
          Subtitle = "Actually, I was planning to sneak in with those kids getting adopted, hoping I'd never starve again with a rich family.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5892"
        },
        [80090214] = {
          ContentKR = "근데 그 손님들 몸에서 이상한 소독약 냄새가 났어. 코가 따가울 정도로! 그리고 이유는 모르겠지만... 아이들을 쳐다보는 눈빛이 너무 소름 돋았어...",
          DialogueId = 80090214,
          GUID = "C87F58BC",
          NextDialogue = 80090215,
          SpeakNpcId = 92301,
          Subtitle = "But those rich people reeked of disinfectant — it stung my nose! And the way they looked at those kids... I don't know why, but it gave me the creeps...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58BC"
        },
        [80090215] = {
          ContentKR = "마치... 쉐프가 생선이랑 오리를 보는 듯한 눈빛이 그런 눈빛일 것 같달까!",
          DialogueId = 80090215,
          GUID = "C87F58E6",
          NextDialogue = 80090216,
          SpeakNpcId = 92301,
          Subtitle = "It was like... a chef sizing up fish or ducks!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F58E6"
        },
        [80090216] = {
          ContentKR = "착한 어른은 거의 못 봤지만, 나쁜 어른은 많이 봤거든! 그들을 믿을 바엔 나를 믿는 게 더 나아. 그래서 결국 아이들 사이에 숨지 않고, 혼자 도망쳤어.",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          Subtitle = "I've seen too many bad grown-ups to trust them — I might be better off on my own. So I didn't join those kids, and ended up running away by myself.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5910"
        },
        [80090217] = {
          ContentKR = "그렇게 타비사는 악마대도가 되는 첫걸음을 내디딘 거지!",
          DialogueId = 80090217,
          GUID = "C87F593A",
          NextOptions = {
            [1] = 80090218,
            [2] = 80090220
          },
          SpeakNpcId = 92301,
          Subtitle = "And that was my first step towards becoming Demon Tabethe the Red Hand!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F593A"
        },
        [80090218] = {
          ContentKR = "타비사는 나쁜 아이가 아니야. 넌 그저... 특별할 뿐이야.",
          DialogueId = 80090218,
          GUID = "C87F5964",
          NextDialogue = 80090219,
          Subtitle = "I think you're not a bad kid, Tabethe. You're just... very special."
        },
        [80090219] = {
          ContentKR = "나쁜 게 아니라 특별한 거라고? 이런 말은 처음이야... 특별한, 특별한 아이... 헤헤!",
          DialogueId = 80090219,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F598E",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          Subtitle = "Not bad, just special? No one's ever put it that way before... A special kid, special... Hehe!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F598E"
        },
        [80090220] = {
          ContentKR = "'손님'이라니 역시 수상하네. 타비사가 냉정하게 잘 판단했어.",
          DialogueId = 80090220,
          GUID = "C87F59B8",
          NextDialogue = 80090221,
          Subtitle = "Those rich visitors sounded really sketchy; you made a smart call, Tabethe."
        },
        [80090221] = {
          ContentKR = "그렇지? 너도 그렇게 생각하지?!",
          DialogueId = 80090221,
          GUID = "C87F59E2",
          NextDialogue = 80090222,
          SpeakNpcId = 92301,
          Subtitle = "Exactly, you got it!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F59E2"
        },
        [80090222] = {
          ContentKR = "근데 그때는 도망치는 것 말고 다른 건 신경 쓸 여력이 없었어. 지금의 나라면 몰래 따라다녀서 나쁜 일을 벌이는 게 아닌지 알아냈을 거야!",
          DialogueId = 80090222,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5A0C",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          Subtitle = "Back then, I was just focused on getting away. If I were as good at my disguise tricks then, I would've secretly followed them to see what they were really up to!",
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A0C"
        },
        [80090223] = {
          ContentKR = "무사히 도망쳐 나온 것만으로 타비사는 잘한 거야. 자유를 얻은 걸 축하해.",
          DialogueId = 80090223,
          GUID = "C87F5A36",
          NextDialogue = 80090224,
          SpeakNpcId = 790008,
          Subtitle = "Getting out safely on your own was already something. Congratulations on earning your freedom, Tabethe.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A36"
        },
        [80090224] = {
          ContentKR = "맞아, 나도 축하해! 모처럼 신선한 공기를 마시며 고개를 들어보니 밤하늘은 어둠만 있는 게 아니더라고. 보육원의 더러운 유리창을 통해 본 밤하늘에는 흐릿한 별밖에 없었거든. 하지만 그때 본 밤하늘의 별들은 놀라울 정도로 반짝거렸어.",
          DialogueId = 80090224,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F5A60",
          NextDialogue = 80090225,
          SpeakNpcId = 92301,
          Subtitle = "Yeah, I did great! Breathing fresh air again was so awesome. For the first time, I realised the night sky wasn't always so dark, and the dim stars I'd seen through dirty glass were actually bright and beautiful.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A60"
        },
        [80090225] = {
          ContentKR = "나는 잔디에 누운 채 별들과 함께 잠에 들었고, 깨어나니 맑은 날이 눈앞에 펼쳐졌어! 그 후로 나는 그 바닷가 마을에 살았고, 그 뒤로는 나를 때리는 '나쁜 어른'은 없었어!",
          DialogueId = 80090225,
          GUID = "C87F5A8A",
          NextDialogue = 80090226,
          SpeakNpcId = 92301,
          Subtitle = "I slept under the stars that night, right on the grass — and woke up to a beautiful sunny day! Since that day, I've been living in that little seaside town, free from those bad grown-ups!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5A8A"
        },
        [80090226] = {
          ContentKR = "그리고 거기서 누구를 만났냐면...",
          DialogueId = 80090226,
          GUID = "C87F5AB4",
          NextDialogue = 80090227,
          SpeakNpcId = 92301,
          Subtitle = "And I met someone there...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5AB4"
        },
        [80090227] = {
          ContentKR = "드디어 좋은 어른을 만난 건가?",
          DialogueId = 80090227,
          GUID = "C87F5ADE",
          NextDialogue = 80090228,
          SpeakNpcId = 790008,
          Subtitle = "Did you finally meet someone kind?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5ADE"
        },
        [80090228] = {
          ContentKR = "엄청 좋은 어른이야! 휴, 그런데 오늘은 좀 힘드네... '악마대도'에게도 휴식이 필요하거든!",
          DialogueId = 80090228,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F5B08",
          NextDialogue = 80090229,
          SpeakNpcId = 92301,
          Subtitle = "Yep, a really, really kind person! But I'm a bit tired now... even Demon Tabethe the Red Hand needs her rest!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5B08"
        },
        [80090229] = {
          ContentKR = "다음에 새로운 음료수를 준비해 주면, 또 이야기해 줄게!",
          DialogueId = 80090229,
          GUID = "C87F5B32",
          SpeakNpcId = 92301,
          Subtitle = "Next time you whip up a new drink, I'll tell you all about it!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/002/C87F5B32"
        },
        [80090301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "이번 음료수도 맛있네! 헤헤헤, 넌 역시 내 입맛을 잘 아는구나!",
          DialogueId = 80090301,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F6702",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090302,
          SpeakNpcId = 92301,
          Subtitle = "Yum-yum! This drink's so good — just like all the other drinks you've made! Hehe, you know exactly what I like.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6702"
        },
        [80090302] = {
          ContentKR = "어제 내가 잔디에 누워 밤하늘을 보며 잠이 들었거든. 파랗던 하늘이 어두워지고 별이 하나씩 반짝이기 시작하는 모습이 꼭 블루베리 치즈 폼 위에 뿌려진 설탕 같았어!",
          DialogueId = 80090302,
          GUID = "C87F672C",
          NextDialogue = 80090303,
          SpeakNpcId = 92301,
          Subtitle = "I fell asleep on the grass under the stars last night. The sky turned from bright blue to dark navy, with stars twinkling like frosting on a blueberry smoothie!",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F672C"
        },
        [80090303] = {
          ContentKR = "보육원에서 탈출한 그날 밤을 제외하면, 사실 난 잔디 위에서 이렇게 편하게 잠든 적이 거의 없었어.",
          DialogueId = 80090303,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6756",
          NextDialogue = 80090304,
          SpeakNpcId = 92301,
          Subtitle = "Except for the night I escaped the orphanage, I almost never had such a sound night's sleep on the grass.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6756"
        },
        [80090304] = {
          ContentKR = "...왜냐하면, 내가 마을에 막 왔을 때 나쁜 짓을 많이 했거든...",
          DialogueId = 80090304,
          GUID = "C87F6780",
          NextDialogue = 80090305,
          SpeakNpcId = 92301,
          Subtitle = "...Because when I first got to the town, I did a lot of bad stuff...",
          TalkActionId = {
            [1] = "92301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6780"
        },
        [80090305] = {
          ContentKR = "그래서 어른들은 나를 싫어했고, '악마'라고 부르더라고...",
          DialogueId = 80090305,
          GUID = "C87F67AA",
          NextOptions = {
            [1] = 80090306,
            [2] = 80090308
          },
          SpeakNpcId = 92301,
          Subtitle = "The grown-ups there hated me for that. They called me a \"demon\"...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F67AA"
        },
        [80090306] = {
          ContentKR = "장난이 지나쳤던 거야?",
          DialogueId = 80090306,
          GUID = "C87F67D4",
          NextDialogue = 80090307,
          Subtitle = "Did you maybe go too far with your pranks?"
        },
        [80090307] = {
          ContentKR = "그들이 너무 멍청한 거였어! 윽... 그래, 네 말이 맞아.",
          DialogueId = 80090307,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F67FE",
          NextDialogue = 80090310,
          SpeakNpcId = 92301,
          Subtitle = "They could've handled it if they were smarter! Well... you're right, it was my fault.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F67FE"
        },
        [80090308] = {
          ContentKR = "혹시 마을의 모든 생선을 먹어 치운 거야?",
          DialogueId = 80090308,
          GUID = "C87F6828",
          NextDialogue = 80090309,
          Subtitle = "Did you polish off all the fish in town?"
        },
        [80090309] = {
          ContentKR = "내가 뭘 얼마나 먹는다고! 뭐, 틀린 말은 아니지만...",
          DialogueId = 80090309,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F6852",
          NextDialogue = 80090310,
          SpeakNpcId = 92301,
          Subtitle = "I'm not that big of an eater! Well, you got part of it right though...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6852"
        },
        [80090310] = {
          ContentKR = "나는 늘 길거리 음식을 훔쳐서 배를 채웠어. 화난 상인들이 나를 때리려고 했지만, 나는 오히려 상인들을 약 올려줬지. 딱히 잘못했다고 생각하지는 않아.",
          DialogueId = 80090310,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F687C",
          NextDialogue = 80090311,
          SpeakNpcId = 92301,
          Subtitle = "I had been living off stealing food from the street stalls. The vendors were so mad they tried to beat me, but I just mimicked their angry faces to piss them off. I didn't think what I did was wrong back then.",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F687C"
        },
        [80090311] = {
          ContentKR = "\"좀 나눠준다고 굶어 죽는 거 아니잖아, 치사하긴!\"",
          DialogueId = 80090311,
          GUID = "C87F68A6",
          NextDialogue = 80090312,
          SpeakNpcId = 92301,
          Subtitle = "\"I just took a little, it's not like you'd starve! Tightwad!\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68A6"
        },
        [80090312] = {
          ContentKR = "하지만 그 아이를 만나고...",
          DialogueId = 80090312,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F68D0",
          NextDialogue = 80090313,
          SpeakNpcId = 92301,
          Subtitle = "Until I met her...",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68D0"
        },
        [80090313] = {
          ContentKR = "그 아이는 생선 가게 주인의 딸이었어. 내가 훔치는 걸 보고도 때리지 않고, 생선을 나눠주기까지 했어. 또 가족에 관해 물어봐 주고, 길을 잃은 거면 자신의 집에서 하룻밤 머물러도 된다고 하더라고. 그렇게 좋은 사람은 처음이었어.",
          DialogueId = 80090313,
          GUID = "C87F68FA",
          NextDialogue = 80090314,
          SpeakNpcId = 92301,
          Subtitle = "She was the fishmonger's daughter. She caught me stealing from her dad's stall but didn't tell on me; instead, she gave me fish to fill my belly, asked if I was separated from my family, and even offered me a place to stay for the night. She was the first truly kind person I'd ever met.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F68FA"
        },
        [80090314] = {
          ContentKR = "그 뒤로 많은 일이 있었어... 그 아이가 가족을 잃어서 보육원에 가게 됐거든. 난 그걸 눈 뜨고 볼 수 없었어! 내가 겪은 걸 똑같이 겪게 둘 수 없었거든! 그래서 난 함께 살기로 했지!",
          DialogueId = 80090314,
          GUID = "C87F6924",
          NextDialogue = 80090315,
          SpeakNpcId = 92301,
          Subtitle = "A lot happened after that... She ended up without a home and had to go to the orphanage — like I'd let her go through what I had! I decided I'd be her family!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6924"
        },
        [80090315] = {
          ContentKR = "우리는 햇빛 아래에서 즐겁게 웃고, 바다에서 물장난을 치고, 진흙 길에서 술래잡기했어. 내가 다양한 동물로 변해서 그 아이를 웃게 하기도 했고.",
          DialogueId = 80090315,
          GUID = "C87F694E",
          NextDialogue = 80090316,
          SpeakNpcId = 92301,
          Subtitle = "We'd giggle under the hot sun, splash each other by the sea, and race down muddy paths together. I'd turn into little animals just to make her laugh.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F694E"
        },
        [80090316] = {
          ContentKR = "그리고 나를 '타비사 언니'라고 불렀어! 종종 굶기도 했지만, 그 아이는 행복하다고 했지.",
          DialogueId = 80090316,
          GUID = "C87F6978",
          NextDialogue = 80090317,
          SpeakNpcId = 92301,
          Subtitle = "She was like a little sister to me — she'd call me Big Sis Tabethe. Even though we didn't always have enough food, she always said she was happy.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6978"
        }
      }
    end
  },
  {
    MinKey = 80090317,
    MaxKey = 80110102,
    Loader = function()
      return {
        [80090317] = {
          ContentKR = "덕분에 난 어른들의 물건에 손대지 않겠다고 다짐했어. 대신 나쁜 어른을 혼내는 '악마대도'가 되겠다고 생각했지!",
          DialogueId = 80090317,
          GUID = "C87F69A2",
          NextOptions = {
            [1] = 80090318,
            [2] = 80090320
          },
          SpeakNpcId = 92301,
          Subtitle = "It was because of her that I decided to stop stealing from good grown-ups. From then on, Demon Tabethe the Red Hand would only target the bad ones!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F69A2"
        },
        [80090318] = {
          ContentKR = "그 아이가 뭐라고 생각할지 걱정한 거야?",
          DialogueId = 80090318,
          GUID = "C87F69CC",
          NextDialogue = 80090319,
          Subtitle = "Is it because you care about what she thinks?"
        },
        [80090319] = {
          ContentKR = "응, 속상하게 하긴 싫었거든.",
          DialogueId = 80090319,
          GUID = "C87F69F6",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          Subtitle = "Yeah. I didn't wanna break her heart.",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F69F6"
        },
        [80090320] = {
          ContentKR = "{性别:타비사 누나!|타비사 언니!}",
          DialogueId = 80090320,
          GUID = "C87F6A20",
          NextDialogue = 80090321,
          Subtitle = "Big Sis Tabethe!"
        },
        [80090321] = {
          ContentKR = "갑자기... 으악, 그만해. 너무 이상하잖아!",
          DialogueId = 80090321,
          FacialId = {
            [1] = "92301:Unacceptable01"
          },
          GUID = "C87F6A4A",
          NextDialogue = 80090322,
          SpeakNpcId = 92301,
          Subtitle = "Wha... Stop it! You're embarrassing both yourself and me!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6A4A"
        },
        [80090322] = {
          ContentKR = "난 그저 이렇게 부르면, 나도 데리고 살아줄까 궁금해서...",
          DialogueId = 80090322,
          GUID = "C87F6A74",
          NextDialogue = 80090323,
          SpeakNpcId = 790008,
          Subtitle = "I just wanted to see if you'd also take me in if I called you that...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6A74"
        },
        [80090323] = {
          ContentKR = "윽! 그 아이는 여덟 살 꼬마였다고! 난 네가 다 큰 어른인 줄 알았는데!",
          DialogueId = 80090323,
          GUID = "C87F6A9E",
          NextDialogue = 80090324,
          SpeakNpcId = 92301,
          Subtitle = "...Are you an eight-year-old? Come on, act your age.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6A9E"
        },
        [80090324] = {
          ContentKR = "장난이야. 그러니까, 타비사는 그 아이가 어떻게 생각할지 신경 썼던 거야?",
          DialogueId = 80090324,
          GUID = "C87F6AC8",
          NextDialogue = 80090325,
          SpeakNpcId = 790008,
          Subtitle = "Just kidding. So, was it because you really care about what she thinks?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6AC8"
        },
        [80090325] = {
          ContentKR = "한 번은 내게 '착한 사람의 물건을 훔치는 건 옳은 일이야?'라고 묻더라고.",
          DialogueId = 80090325,
          GUID = "C87F6AF2",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          Subtitle = "She once asked me, \"Is it right to steal from good people?\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6AF2"
        },
        [80090326] = {
          ContentKR = "처음에는 그 상인들을 착하다고 말하는 걸 이해할 수 없었어. 내가 굶주리는데도 먹을 것도 안 주고, 화만 내던 사람들이니까.",
          DialogueId = 80090326,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6B1C",
          NextDialogue = 80090327,
          SpeakNpcId = 92301,
          Subtitle = "At first, I didn't listen — how could those vendors be good people? I was starving, and they just yelled at me, never giving me anything to eat.",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B1C"
        },
        [80090327] = {
          ContentKR = "근데 나중에 알고 보니, 어떤 상인은 내가 물건을 가져가는 걸 보고도 그냥 둔 거더라고.",
          DialogueId = 80090327,
          GUID = "C87F6B46",
          NextDialogue = 80090328,
          SpeakNpcId = 92301,
          Subtitle = "But then I realised — some vendors actually saw me stealing, but they looked the other way.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B46"
        },
        [80090328] = {
          ContentKR = "나를 혼내겠다며 쫓아오던 상인도 얼마 안 쫓아오고는 그냥 가더라고... 물론, 그 사람들이 내 속도를 쫓아올 수 없겠지만 말이야!",
          DialogueId = 80090328,
          GUID = "C87F6B70",
          NextDialogue = 80090329,
          SpeakNpcId = 92301,
          Subtitle = "And those who chased me never really followed through... Of course, they couldn't catch me if they tried — I was fast...!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B70"
        },
        [80090329] = {
          ContentKR = "어떤 상인은 팔고 남은 음식을 내게 주곤 했어. 나는 두려워서 내게 바치는 거로 생각했지만...",
          DialogueId = 80090329,
          GUID = "C87F6B9A",
          NextDialogue = 80090330,
          SpeakNpcId = 92301,
          Subtitle = "And some vendors even left unsold food out for me. But back then I thought they did it because they were scared of me and were paying protection money.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6B9A"
        },
        [80090330] = {
          ContentKR = "내가 사람들의 나쁜 모습만 기억하고, 좋은 모습은 못 본 척한 거야.",
          DialogueId = 80090330,
          GUID = "C87F6BC4",
          NextDialogue = 80090331,
          SpeakNpcId = 92301,
          Subtitle = "I held such a grudge against the bad people I met, that I was completely blind to the kindness of those good people.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6BC4"
        },
        [80090331] = {
          ContentKR = "...다시 생각해도 가슴만 먹먹해지네. 입맛도 별로 없고...",
          DialogueId = 80090331,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6BEE",
          NextDialogue = 80090332,
          SpeakNpcId = 92301,
          Subtitle = "When I realised all this, I felt so bad that the food I stole tasted off.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6BEE"
        },
        [80090332] = {
          ContentKR = "난 이전의 '나쁜 어른'에게 당한 것 때문에 상인들에게 화풀이한 것 같아.",
          DialogueId = 80090332,
          GUID = "C87F6C18",
          NextDialogue = 80090333,
          SpeakNpcId = 92301,
          Subtitle = "I guess I'd been taking out my hate for the bad grown-ups on those vendors.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6C18"
        },
        [80090333] = {
          ContentKR = "난 정말 '악마'였어...",
          DialogueId = 80090333,
          GUID = "C87F6C42",
          NextOptions = {
            [1] = 80090334,
            [2] = 80090336
          },
          SpeakNpcId = 92301,
          Subtitle = "I really was a demon...",
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6C42"
        },
        [80090334] = {
          ContentKR = "타비사는 이미 잘하고 있어. 대부분의 사람은 자신의 잘못을 평생 깨닫지 못하잖아.",
          DialogueId = 80090334,
          GUID = "C87F6C6C",
          NextDialogue = 80090335,
          Subtitle = "There's no need to beat yourself up, Tabethe. A lot of people fail to own up to their mistakes in a whole lifetime. You already did great."
        },
        [80090335] = {
          ContentKR = "고마워... 휴, 위로하지 않아도 돼. 잘못한 건 잘못한 거니까.",
          DialogueId = 80090335,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6C96",
          NextDialogue = 80090338,
          SpeakNpcId = 92301,
          Subtitle = "Thank you... but you don't need to sugar-coat it for me. I know what I did was wrong.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6C96"
        },
        [80090336] = {
          ContentKR = "타비사도 언젠가는 어른이 될 텐데, 자꾸 착한 사람을 괴롭히면 나중에 타비사도 나쁜 어른이 되는 거 아냐?",
          DialogueId = 80090336,
          GUID = "C87F6CC0",
          NextDialogue = 80090337,
          Subtitle = "You will grow up someday. Wouldn't bullying good people just make you one of the bad grown-ups?"
        },
        [80090337] = {
          ContentKR = "맞아... 더 많이 화내 줘. 말대꾸도 안 하고 얌전히 들을게.",
          DialogueId = 80090337,
          GUID = "C87F6CEA",
          NextDialogue = 80090338,
          SpeakNpcId = 92301,
          Subtitle = "You're right... Go ahead and let me have it. I won't talk back — I deserve this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6CEA"
        },
        [80090338] = {
          ContentKR = "그 뒤로 나는 도둑놈과 나쁜 어른의 물건만 훔쳤어. 그게 멋있기도 하고, 착한 사람에게 상처를 줄 일도 없으니까.",
          DialogueId = 80090338,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F6D14",
          NextDialogue = 80090339,
          SpeakNpcId = 92301,
          Subtitle = "Ever since then, I'd only take stuff from bad thieves and mean grown-ups. It felt great, and it wouldn't hurt good people.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D14"
        },
        [80090339] = {
          ContentKR = "그거 알아? 나쁜 사람은 전부 돈이 엄청 많아! 이제 나는 웬만해서는 굶지도 않고, 그냥 가끔 나쁜 사람을 약 올리고, 화내는 모습을 보기만 하지. 히히히, 하루하루가 너무 재밌어졌어!",
          DialogueId = 80090339,
          GUID = "C87F6D3E",
          NextOptions = {
            [1] = 80090340
          },
          SpeakNpcId = 92301,
          Subtitle = "And guess what — those bad guys are loaded! I hardly ever go hungry now. Plus, I get to play tricks on them and watch them fume, hehe, it's so much fun!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D3E"
        },
        [80090340] = {
          ContentKR = "그 사람들을 약 올리는 게 핵심인 것 같은데.",
          DialogueId = 80090340,
          GUID = "C87F6D68",
          NextDialogue = 80090341,
          Subtitle = "It's more about the fun of playing tricks on them than finding stuff to eat, huh?"
        },
        [80090341] = {
          ContentKR = "맞아! 크흠, 아니거든! 이건 나쁜 싹을 뽑는 거라고 말해야 해! 착한 사람을 괴롭히면 벌받는다는 걸 알려줘야지.",
          DialogueId = 80090341,
          GUID = "C87F6D92",
          NextDialogue = 80090342,
          SpeakNpcId = 92301,
          Subtitle = "Exactly! Er, I mean, not really! This is about \"serving justice.\" All I did was teach them not to mess with the good folks.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6D92"
        },
        [80090342] = {
          ContentKR = "오늘 말을 너무 많이 했나 봐, 목이 아프네!",
          DialogueId = 80090342,
          GUID = "C87F6DBC",
          NextDialogue = 80090343,
          SpeakNpcId = 92301,
          Subtitle = "Whew, that was a lot of talking today — my throat's literally smoking!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6DBC"
        },
        [80090343] = {
          ContentKR = "헤헤, 방금 블루베리 음료, 한 잔 더 주면 안 될까!",
          DialogueId = 80090343,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F6DE6",
          SpeakNpcId = 92301,
          Subtitle = "Hehe, can I get a refill of that blueberry drink?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/003/C87F6DE6"
        },
        [80090401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "음, 맛있어! 내가 칭찬은 잘 안 하는데, 계속 마셔도 질리지 않는 것 같아! 어쨌든, 맨날 이렇게 음식을 준비해 줘서 고마워.",
          DialogueId = 80090401,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F776A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090402,
          SpeakNpcId = 92301,
          Subtitle = "This is so good! I could never get enough of this drink! I don't often say nice things, but thank you for always making these for me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F776A"
        },
        [80090402] = {
          ContentKR = "헤헤, 그동안 얻어먹기만 했으니, 이번에는 내 솜씨를 발휘해 볼까!",
          DialogueId = 80090402,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F7794",
          NextDialogue = 80090403,
          SpeakNpcId = 92301,
          Subtitle = "Hehehe, since you've made so many good drinks for me, it's time I return the favour!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7794"
        },
        [80090403] = {
          ContentKR = "앞에 수상한 검은 액체가 담긴 잔이 하나 놓였다. 작은 기포가 끊임없이 올라오고 이상한 냄새가 난다. 그 안에는 말린 과일과 사탕 조금을 제외하면 정체를 알 수 없는 것들로 가득하다.",
          DialogueId = 80090403,
          GUID = "C87F77BE",
          NextDialogue = 80090404,
          Subtitle = "Before you is a suspicious dark drink, bubbling and giving off a strange scent. Upon closer inspection, you recognise various dried fruits and candies settled at the bottom."
        },
        [80090404] = {
          ContentKR = "짠! 이게 바로 이 타비사 님의 시그니처 메뉴인 '악마대도'야! 나와 같은 별명을 붙여줬지. 히히히, 너한테 고마운 마음을 모두 쏟아넣었다고!",
          DialogueId = 80090404,
          GUID = "C87F77E8",
          NextOptions = {
            [1] = 80090405,
            [2] = 80090410
          },
          SpeakNpcId = 92301,
          Subtitle = "Ta-da! Behold my special creation — Demon Tabethe the Red Hand — named after my own title! Just so you know, this glass is filled with my thanks, hehe!",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F77E8"
        },
        [80090405] = {
          ContentKR = "안 마신다",
          DialogueId = 80090405,
          GUID = "C87F7812",
          NextDialogue = 80090406,
          Subtitle = "Refuse the drink"
        },
        [80090406] = {
          ContentKR = "진짜 뭘 모르네! 이건 세상에 한 잔뿐인 '악마대도'라고!",
          DialogueId = 80090406,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F783C",
          NextDialogue = 80090407,
          SpeakNpcId = 92301,
          Subtitle = "Come on! This is the one and only \"Demon Tabethe the Red Hand\" in the world!",
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F783C"
        },
        [80090407] = {
          ContentKR = "여기 들어간 재료는 모두 착한 어른이 나눠준 거야. 나 혼자 먹기 아까워서 챙겨둔 거라고. 그게 전부 들어갔으니 얼마나 맛있을까?!",
          DialogueId = 80090407,
          GUID = "C87F7866",
          NextDialogue = 80090408,
          SpeakNpcId = 92301,
          Subtitle = "I've put all the good food that good grown-ups gave me into this drink. I've been saving the ingredients bit by bit — tried so hard not to eat them right away! I can't even imagine how yummy this drink will be with all that good stuff put together!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7866"
        },
        [80090408] = {
          ContentKR = "자, 그러면 같이 나눠 마시는 건 어때? 크흠, 내가 맛보고 싶은 건 아니고 네가 못 마시니까 내가 먼저 시범을 보여주려는 거야!",
          DialogueId = 80090408,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F7890",
          NextDialogue = 80090409,
          SpeakNpcId = 92301,
          Subtitle = "How about we share it? Not that I want to try it myself! I'm just setting an example for a coward!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7890"
        },
        [80090409] = {
          ContentKR = "자, 짠!",
          DialogueId = 80090409,
          GUID = "C87F78BA",
          SpeakNpcId = 92301,
          Subtitle = "Cheers!",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F78BA"
        },
        [80090410] = {
          ContentKR = "마신다",
          DialogueId = 80090410,
          GUID = "C87F78E4",
          NextDialogue = 80090411,
          Subtitle = "Accept the drink"
        },
        [80090411] = {
          ContentKR = "역시 보는 눈이 있네!",
          DialogueId = 80090411,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F790E",
          NextDialogue = 80090412,
          SpeakNpcId = 92301,
          Subtitle = "Excellent choice!",
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F790E"
        },
        [80090412] = {
          ContentKR = "여기 들어간 재료는 모두 착한 어른이 나눠준 거야. 나 혼자 먹기 아까워서 챙겨둔 거라고. 그게 전부 들어갔으니 얼마나 맛있을까?!",
          DialogueId = 80090412,
          GUID = "C87F7938",
          NextDialogue = 80090413,
          SpeakNpcId = 92301,
          Subtitle = "I've put all the good food that good grown-ups gave me into this drink. I've been saving the ingredients bit by bit — tried so hard not to eat them right away! I can't even imagine how yummy this drink will be with all that good stuff put together!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7938"
        },
        [80090413] = {
          ContentKR = "이렇게 귀한 식재료를 누구와 나눌지 고민했는데, 역시 너뿐이더라고. 그런데 나도 조금만 마셔봐도 될까? 헤헤, 나도 '이 세상에서 가장 맛있는 음료수'가 어떤 맛일지 궁금하거든!",
          DialogueId = 80090413,
          GUID = "C87F7962",
          NextDialogue = 80090414,
          SpeakNpcId = 92301,
          Subtitle = "Who else but you deserves such a precious drink, right? But could you share a little with me? Hehe, I'm curious what the best drink in the world tastes like!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7962"
        },
        [80090414] = {
          ContentKR = "알겠어, 알겠다고! 부끄러우니까 여기까지만 하고 건배하는 거야!",
          DialogueId = 80090414,
          GUID = "C87F798C",
          SpeakNpcId = 92301,
          Subtitle = "Alright, I'm done getting all mushy! Cheers!",
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F798C"
        },
        [80090415] = {
          ContentKR = "나와 타비사는 함께 음료수를 마셨다. 곧 기괴한 단맛이 입안을 가득 채웠고, 그렇게 의식을 잃는다.",
          DialogueId = 80090415,
          GUID = "C87F79B6",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "You both chug Tabethe's special concoction. A bizarre sweetness overwhelms your taste buds; soon after, you black out."
        },
        [80090416] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "아직 숨은 붙어있어, 둘 다 괜찮아. 그냥 잠에 든 것뿐이야.",
          DialogueId = 80090416,
          DisableMouth = 1,
          FacialId = {
            [1] = "92301:Close"
          },
          GUID = "C87F79E0",
          IsBlack = 1,
          NextDialogue = 80090417,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "They're still breathing. Both of them are fine — just passed out.",
          TalkActionId = {
            [1] = "92301:Zhangyu_Story_Tentacle"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F79E0"
        },
        [80090417] = {
          ContentKR = "흑흑... 깜짝 놀랐어... 이래서 타비사한테 음식에 아무거나 넣지 말라고, 사고 나면 어쩌냐고 했던 건데... 흑흑...",
          DialogueId = 80090417,
          DisableMouth = 1,
          GUID = "C87F7A0A",
          IsBlack = 1,
          NextDialogue = 80090418,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Waah... I was so scared... I've warned Tabethe not to put just anything in that drink — it's not safe...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7A0A"
        },
        [80090418] = {
          ContentKR = "히힛, 머리에 문제 생기거나, 이상한 후유증이 생길지도 몰라!",
          DialogueId = 80090418,
          DisableMouth = 1,
          GUID = "C87F7A34",
          IsBlack = 1,
          NextDialogue = 80090419,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Hehehe, maybe it'll mess up their brains and cause some weird side effects!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7A34"
        },
        [80090419] = {
          ContentKR = "조용히 해! 말이 씨가 될 수 있어.",
          DialogueId = 80090419,
          DisableMouth = 1,
          GUID = "C87F7A5E",
          IsBlack = 1,
          NextOptions = {
            [1] = 80090420
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Knock it off! You ghoul!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7A5E"
        },
        [80090420] = {
          ContentKR = "...누구야?",
          DialogueId = 80090420,
          GUID = "C87F7A88",
          NextDialogue = 80090421,
          Subtitle = "...Who's there?"
        },
        [80090421] = {
          ContentKR = "타비사의 몸에서 나온 촉수가 날 향해 부드럽게 흔들렸다.",
          DialogueId = 80090421,
          DisableMouth = 1,
          GUID = "C87F7AB2",
          NextDialogue = 80090422,
          Subtitle = "You see several tentacles extending from Tabethe gently swaying in front of you."
        },
        [80090422] = {
          ContentKR = "너희도 들었어...? 우리에게 말한 거 같은데?",
          DialogueId = 80090422,
          DisableMouth = 1,
          GUID = "C87F7ADC",
          NextDialogue = 80090423,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Did you hear that...?  is talking to us.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7ADC"
        },
        [80090423] = {
          ContentKR = "우리의 말소리는 타비사만 들을 수 있지 않나?",
          DialogueId = 80090423,
          DisableMouth = 1,
          GUID = "C87F7B06",
          NextDialogue = 80090424,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "To my knowledge, only Tabethe can hear us speak.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7B06"
        },
        [80090424] = {
          ContentKR = "...이런, 어쩌지! 역시 음료 때문에 문제가 생긴 건가? 5호가 불길한 말만 하면 꼭 현실이 된다니까! 제발, 그 입 좀 다물어!",
          DialogueId = 80090424,
          DisableMouth = 1,
          GUID = "C87F7B30",
          NextOptions = {
            [1] = 80090425
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Oh no... This is bad, really bad! I knew it — every time 5 says something bad, it always happens for real! Could you zip it next time? I'm begging you!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7B30"
        },
        [80090425] = {
          ContentKR = "촉수가... 말을 해...?",
          DialogueId = 80090425,
          GUID = "C87F7B5A",
          NextDialogue = 80090426,
          Subtitle = "Are those tentacles talking...?"
        },
        [80090426] = {
          ContentKR = "어... 안녕? 우리는 타비사의 다리야. 이런 상황에서 이야기를 나누게 될 줄은 몰랐네! 인생은 참 한치 앞도 알 수 없다니까~ 하, 하하...",
          DialogueId = 80090426,
          DisableMouth = 1,
          GUID = "C87F7B84",
          NextDialogue = 80090427,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Um... hello? Yes, we're Tabethe's tentacles. Never thought we'd be having a conversation like this! Life's full of surprises, huh? Haha...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7B84"
        },
        [80090427] = {
          ContentKR = "그러니까... 아까 그 음료수 때문에 우리의 말을 듣을 수 있게 된 거 같은데... 이상한 걸 마시게 해서 미안해. 하지만 타비사랑 우리는 일부러 그런 게 아니야. 흑흑...",
          DialogueId = 80090427,
          DisableMouth = 1,
          GUID = "C87F7BAE",
          NextOptions = {
            [1] = 80090428,
            [2] = 80090429
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2",
          Subtitle = "Um... it might be that drink that caused this situation... We're so sorry... didn't mean to make you chug down something weird...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7BAE"
        },
        [80090428] = {
          ContentKR = "타비사는 괜찮아?",
          DialogueId = 80090428,
          GUID = "C87F7BD8",
          NextDialogue = 80090430,
          Subtitle = "Is Tabethe okay?"
        },
        [80090429] = {
          ContentKR = "나, 괜찮은 거지?",
          DialogueId = 80090429,
          GUID = "C87F7C02",
          NextDialogue = 80090430,
          Subtitle = "Am I okay?"
        },
        [80090430] = {
          ContentKR = "제가 보기엔 그저... 식재료가 특별해서 그런 것 같군요. 자고 일어나면 괜찮을 거예요!",
          DialogueId = 80090430,
          DisableMouth = 1,
          GUID = "C87F7C2C",
          NextDialogue = 80090431,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "Based on my observations, you're both just reacting to some... special ingredients. A good sleep should fix it!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7C2C"
        },
        [80090431] = {
          ContentKR = "다만, 크흠... 저의 인도 아래 모든 다리가 함께 완성한 이 음료수는 바로 오늘의 이 특별한 만남을 위해 만들어진 것이랍니다.",
          DialogueId = 80090431,
          DisableMouth = 1,
          GUID = "C87F7C56",
          NextDialogue = 80090432,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "Ahem, just so you know — it was under my leadership that we concocted this beverage for Tabethe's unprecedented get-together with you!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7C56"
        },
        [80090432] = {
          ContentKR = "그래? 타비사가 음료 만드는 법도 모르면서 예쁜 버섯을 넣어서 이렇게 된 거 아니었어?",
          DialogueId = 80090432,
          DisableMouth = 1,
          GUID = "C87F7C80",
          NextDialogue = 80090433,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Hmm? I thought it was because Tabethe knew nothing about making drinks, so she just threw in some pretty mushroom slices, which led to this.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7C80"
        },
        [80090433] = {
          ContentKR = "히힛... 3호, 자꾸 이상한 소리하면 너도 이 음료수 안에 넣어줄 줄 알아, 히히히힛...",
          DialogueId = 80090433,
          DisableMouth = 1,
          GUID = "C87F7CAA",
          NextDialogue = 80090434,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu5",
          Subtitle = "Hehe, keep acting all smug, 3, and you might find yourself part of the next drink, hehehe.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7CAA"
        },
        [80090434] = {
          ContentKR = "흐엉, 너무 무서워!",
          DialogueId = 80090434,
          DisableMouth = 1,
          GUID = "C87F7CD4",
          NextDialogue = 80090435,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2",
          Subtitle = "Ah, that sounds horrible! Waah!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7CD4"
        },
        [80090435] = {
          ContentKR = "조용히 해... 너흰 지치지도 않냐... 그리고, {nickname} 놀라게 하지 마...",
          DialogueId = 80090435,
          DisableMouth = 1,
          GUID = "C87F7CFE",
          NextOptions = {
            [1] = 80090436
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu4",
          Subtitle = "Please, you guys are too loud... Aren't you tired? And don't scare ...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7CFE"
        },
        [80090436] = {
          ContentKR = "아, 그래. 여긴 꿈속이구나.",
          DialogueId = 80090436,
          GUID = "C87F7D28",
          NextDialogue = 80090437,
          Subtitle = "Got it — this is a dream. A really weird one."
        },
        [80090437] = {
          ContentKR = "꿈이라고 생각해도 돼. 그나저나 이게 언제까지 지속될지 모르겠네... 사실 우리는 너와 하고 싶은 말이 엄청 많거든! 이번 기회에 다 해볼까... 1호, 너 먼저 해!",
          DialogueId = 80090437,
          DisableMouth = 1,
          GUID = "C87F7D52",
          NextDialogue = 80090438,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "That's one way to see it. Though no one knows how long the drink's effects will last... Actually, there's quite a lot we'd like to talk to you about! Maybe this is the chance... 1, you go first!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7D52"
        },
        [80090438] = {
          ContentKR = "...나의 의식은 바다에서 생겨났어. 사고가 일어난 후, 나와 타비사는 바다 위를 표류 중이라 언제 죽어도 이상하지 않았어. 하지만 내가 말동무가 되어주며, 타비사가 그 힘든 시간을 버틸 수 있었지.",
          DialogueId = 80090438,
          DisableMouth = 1,
          GUID = "C87F7D7C",
          NextDialogue = 80090439,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1",
          Subtitle = "...My sentience came into being on the ocean, right after the shipwreck. I kept Tabethe company during those dark times in the sea. She got through it by talking to me.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7D7C"
        },
        [80090439] = {
          ContentKR = "나, 나는 보육원에서 깨어났어. 그때 타비사는 그곳에 막 도착한 참이었는데, 어른들은 모두 그 애한테 심술궂게 굴었어. 타비사는 무서워했지만 고집이 세서 누구 앞에서도 약한 모습을 보이기 싫어했어. 하지만 밤만 되면 나를 꼭 껴안고 무서움에 계속 떨곤 했지...",
          DialogueId = 80090439,
          DisableMouth = 1,
          GUID = "C87F7DA6",
          NextDialogue = 80090440,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2",
          Subtitle = "I... I woke up when Tabethe had just been taken in by the orphanage. The staff there were mean to her; she was scared, but wouldn't show weakness in front of anyone. At night, she'd cling on to me, shivering...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7DA6"
        },
        [80090440] = {
          ContentKR = "저는 보육원 주방에서 이 팀에 합류했습니다. 위기의 순간, 저의 지휘 덕분에 순찰하는 경비를 피해 무사히 빵 반쪽을 전리품으로 얻을 수 있었지요!",
          DialogueId = 80090440,
          DisableMouth = 1,
          GUID = "C87F7DD0",
          NextDialogue = 80090441,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "I myself joined this esteemed group in the orphanage's kitchen. In a dire moment, it was under my command that we managed to evade the patrolling guards and secure half a loaf of bread!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7DD0"
        },
        [80090441] = {
          ContentKR = "제 말투는... 보육원 원장을 완벽하게 재현한 것입니다.",
          DialogueId = 80090441,
          DisableMouth = 1,
          GUID = "C87F7DFA",
          NextDialogue = 80090442,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "And as for my manner of speaking, it's a perfect impersonation of the head of the orphanage.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7DFA"
        },
        [80090442] = {
          ContentKR = "흐아암... 졸려... 난 보육원에서 탈출하던 날 밤에 깨어났어. 죽다 살아난 느낌이 얼마나 버겁고... 버겁던지... 너무 버거워서 안전한 곳에 도착하자마자 우리는 잔디 위에서 바로 잠들어 버렸어...",
          DialogueId = 80090442,
          DisableMouth = 1,
          GUID = "C87F7E24",
          NextDialogue = 80090443,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu4",
          Subtitle = "Yawn... I awoke the night we escaped the orphanage. The sense of relief was so heavy... that once we were safe, I fell asleep right away on the grass with her...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7E24"
        },
        [80090443] = {
          ContentKR = "히힛, 이제 내 차례인가! 나는 타비사 최고의 전우! 함께하는 도둑질은 언제나 짜릿해! 와우!",
          DialogueId = 80090443,
          DisableMouth = 1,
          GUID = "C87F7E4E",
          NextDialogue = 80090444,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu5",
          Subtitle = "And then there's me, hehehe! I'm Tabethe's best partner in crime! The thrill of all sorts of heists is just the best! Woo-hoo!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7E4E"
        },
        [80090444] = {
          ContentKR = "적당히 해! 미안, 얘가 아직 철이 덜 들었어! 크흠, 드디어 내 차례네! 난 막내야. 최근에 의식이 생겼거든.",
          DialogueId = 80090444,
          DisableMouth = 1,
          GUID = "C87F7E78",
          NextDialogue = 80090445,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Get ahold of yourself! Sorry, this kid is a bit of a wild card. Ahem, I'm the youngest, and only recently became sentient.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7E78"
        },
        [80090445] = {
          ContentKR = "사실 훨씬 전에 한 번 깨어난 적이 있어. 다만 생선을 팔던 아이와 헤어졌을 때 타비사가 말은 안 했지만 정말 힘들어했거든. 심지어 나도 현실을 마주하기 싫을 정도라서 다시 잠에 들었어.",
          DialogueId = 80090445,
          DisableMouth = 1,
          GUID = "C87F7EA2",
          NextDialogue = 80090446,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Actually, I woke up once a long time ago. But then that little fish vendor girl got separated from Tabethe, which made her very sad. She didn't talk about it, but it hit her really hard and even affected me — I fell back into slumber, immersed in those memories.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7EA2"
        },
        [80090446] = {
          ContentKR = "그러다가 타비사가 진심으로 대하는 새로운 사람이 나타났지... 맞아, 난 너 덕분에 깨어난 거야.",
          DialogueId = 80090446,
          DisableMouth = 1,
          GUID = "C87F7ECC",
          NextDialogue = 80090447,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Until she met another person who also truly cherishes her — yes, it was because of you that I woke up again.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7ECC"
        },
        [80090447] = {
          ContentKR = "그동안 타비사를 보살펴줘서 고마워. 너의 따뜻한 마음 덕분에 내가 깨어날 수 있었어. 고마운 마음을 담아 너에게 음료수를 만들어 주자는 것도 나의 제안이었어.",
          DialogueId = 80090447,
          DisableMouth = 1,
          GUID = "C87F7EF6",
          NextDialogue = 80090448,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "Thank you for taking care of Tabethe. Your kindness woke me from my dream. And it was on my suggestion that she decided to make this drink as a thank you.",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7EF6"
        },
        [80090448] = {
          ContentKR = "하지만 그래도 음료를 그렇게까지 마구잡이로 만들 줄은 몰랐지, 으아아! 음료 만드는 법도 모르면서, 닥치는 대로 아무거나 넣더라니까... 그리고 3호랑 5호, 너희도 계속 옆에서 부추긴 거 다 알고 있어!",
          DialogueId = 80090448,
          DisableMouth = 1,
          GUID = "C87F7F20",
          NextDialogue = 80090449,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "But I didn't expect her to go this overboard! She knows nothing about mixing drinks and just tossed in whatever looked good — and you two, 3 and 5! You two egged her on!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7F20"
        },
        [80090449] = {
          ContentKR = "미안해, 정말 미안해...",
          DialogueId = 80090449,
          DisableMouth = 1,
          GUID = "C87F7F4A",
          NextOptions = {
            [1] = 80090450
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6",
          Subtitle = "We're so sorry...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7F4A"
        },
        [80090450] = {
          ContentKR = "하하, 괜찮아.",
          DialogueId = 80090450,
          GUID = "C87F7F74",
          NextDialogue = 80090451,
          Subtitle = "Haha, it's okay."
        },
        [80090451] = {
          ContentKR = "......",
          DialogueId = 80090451,
          DisableMouth = 1,
          GUID = "C87F7F9E",
          NextDialogue = 80090452,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7F9E"
        },
        [80090452] = {
          ContentKR = "타비사가 곧 깨어날 것 같아. 넌?",
          DialogueId = 80090452,
          DisableMouth = 1,
          GUID = "C87F7FC8",
          NextDialogue = 80090453,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1",
          Subtitle = "Tabethe's waking up. How do you feel?",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7FC8"
        },
        [80090453] = {
          ContentKR = "벌써?! 저는 아직 이 대화를 끝낼 준비를 못 했는데...",
          DialogueId = 80090453,
          DisableMouth = 1,
          GUID = "C87F7FF2",
          NextOptions = {
            [1] = 80090454,
            [2] = 80090455
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3",
          Subtitle = "Ah, already?! I haven't finished my speech...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F7FF2"
        },
        [80090454] = {
          ContentKR = "이상한 꿈이네, 얼른 깼으면...",
          DialogueId = 80090454,
          GUID = "C87F801C",
          NextDialogue = 80090456,
          Subtitle = "What a weird dream. Better wake up ASAP..."
        },
        [80090455] = {
          ContentKR = "볼수록 귀엽네, 계속 이야기할 수 있으면 좋을 텐데.",
          DialogueId = 80090455,
          GUID = "C87F8046",
          NextDialogue = 80090456,
          Subtitle = "They're adorable. I hope this could happen more often."
        },
        [80090456] = {
          ContentKR = "그 기괴한 맛이 다시 느껴졌다. 의식은 돌아온 것 같았지만, 눈앞은 여전히 새카맸다.",
          DialogueId = 80090456,
          GUID = "C87F8070",
          IsBlack = 1,
          NextDialogue = 80090457,
          Subtitle = "That odd taste hits you again. Even though you've experienced it before, it still overwhelmingly floods your senses."
        },
        [80090457] = {
          ContentKR = "다시 의식을 잃기 전, 많은 목소리가 들렸다. '착한 사람은 좋은 일이 가득할 거야', '이런 거 먹으면 더 튼튼해질 거야', '내가 지휘하겠습니다'... 그리고 수많은 '고마워'까지...",
          DialogueId = 80090457,
          GUID = "C87F809A",
          IsBlack = 1,
          Subtitle = "Before blacking out again, you seem to hear a cacophony of voices: \"Gods bless the kind-hearted,\" \"What doesn't kill you makes you stronger,\" \"I'll take the lead with the head,\" along with many voices murmuring, \"Thank you.\"",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F809A"
        },
        [80090458] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentKR = "너, 너... 괜찮아? 이런, 설마 정말 그 음료수 때문... 인 걸까...",
          DialogueId = 80090458,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F80C4",
          NextDialogue = 80090459,
          SpeakNpcId = 92301,
          Subtitle = "Aaaare you alright?! Oh no... it wasn't the drink, was it...?",
          TalkActionId = {
            [1] = "92301:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F80C4"
        },
        [80090459] = {
          ContentKR = "...그런데 음료수는 나도 마셨잖아? 난 너무 맛있어서 잠깐 쓰러진 것뿐이지, 지금은 괜찮단 말이야! 어서 깨어나란 말이야! 이 악마대도님을 속일 생각은 하지 말라고!",
          DialogueId = 80090459,
          GUID = "C87F80EE",
          NextOptions = {
            [1] = 80090460
          },
          SpeakNpcId = 92301,
          Subtitle = "...I drank the same thing! It was so good that it knocked me out for a moment, but I'm perfectly fine now! Hey, wake up! Don't even think about trying to scam me by pretending it's food poisoning...!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F80EE"
        },
        [80090460] = {
          ContentKR = "그만 소리 질러... 난 괜찮아... 그냥 촉수의 말이 들렸을 뿐이야...",
          DialogueId = 80090460,
          GUID = "C87F8118",
          NextDialogue = 80090461,
          Subtitle = "Will you keep it down...? I'm fine... just heard some tentacles talking, that's all..."
        },
        [80090461] = {
          ContentKR = "......",
          DialogueId = 80090461,
          FacialId = {
            [1] = "92301:Shock02"
          },
          GUID = "C87F8142",
          NextDialogue = 80090462,
          SpeakNpcId = 92301,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F8142"
        },
        [80090462] = {
          ContentKR = "의사! 의사 선생님!",
          DialogueId = 80090462,
          GUID = "C87F816C",
          NextDialogue = 80090463,
          SpeakNpcId = 92301,
          Subtitle = "Doc! Help!!!",
          VoiceName = "voice/$Locale$/inv/Zhangyu/004/C87F816C"
        },
        [80090463] = {
          ContentKR = "여전히 몸 상태는 좋지 않았지만, 타비사의 촉수가 날 향해 반갑게 흔들리는 걸 본 것 같았다.",
          DialogueId = 80090463,
          GUID = "C87F8196",
          Subtitle = "You're still feeling awful, but you seem to see Tabethe's tentacles cheerfully quivering, as if they are nodding at you."
        },
        [80100100] = {
          ContentKR = "이건 우리 둘만의 데이트인 건가요?",
          DialogueId = 80100100,
          GUID = "C885AEA8",
          Subtitle = "Are we going on a private date?",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEA8"
        },
        [80100101] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "드디어 초대를 받았네요. 제가 이곳에 온 지 꽤 오래됐는데, 떠돌이 조향사인 절 언제까지 기다리게 할 생각인지 궁금했거든요.",
          DialogueId = 80100101,
          FacialId = {
            [1] = "92101:Satisfy01"
          },
          GUID = "C885AED2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100102,
          SpeakNpcId = 92101,
          Subtitle = "Finally received your invitation. Much time has passed since I arrived at this place, and I'd been wondering how long you were going to keep this poor wandering perfumer waiting.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AED2"
        },
        [80100102] = {
          ContentKR = "차가운 사람... 아무리 뜨거운 마음이라도, 시간이... 시간이 이렇게 오래 지나버리면 식어버리기 마련이라고요.",
          DialogueId = 80100102,
          GUID = "C885AEFC",
          NextOptions = {
            [1] = 801001021,
            [2] = 801001022
          },
          SpeakNpcId = 92101,
          Subtitle = "You should know even the most passionate heart cannot burn forever. Indifference will extinguish those flames, leaving it hard and cold.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEFC"
        },
        [80100103] = {
          ContentKR = "제게 차갑게 굴었다고 말했잖아요. 운명도 참 잔인하네요... 이렇게 소외감을 느끼며 시작되는 사랑을 제게 안겨주다니...",
          DialogueId = 80100103,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF26",
          NextOptions = {
            [1] = 801001041
          },
          SpeakNpcId = 92101,
          Subtitle = "You left me out in the cold. Fate is so cruel for giving me a romance that begins with the coldest of shoulders.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF26"
        },
        [80100104] = {
          ContentKR = "아아, 당신의 행동보다도 그 말이 절 더 외롭게 하네요. 곧 사랑이 시작될 거라는 걸, 설마 정말로 알아차리지 못한 건가요?",
          DialogueId = 80100104,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF50",
          NextOptions = {
            [1] = 801001041
          },
          SpeakNpcId = 92101,
          Subtitle = "*sigh* Never thought your words could be even colder than your actions. Are you truly blind to the romance that is about to blossom?",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF50"
        },
        [80100105] = {
          ContentKR = "당연히 지금 이 순간, 시선이 교차하고 있는 당신과 저죠. 그리고 시치미 떼는 건 그리 좋은 선택이 아니에요.",
          DialogueId = 80100105,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF7A",
          NextDialogue = 80100106,
          SpeakNpcId = 92101,
          Subtitle = "Between you and me, of course. Who else's eyes are looking deep into each other at this very moment?",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF7A"
        },
        [80100106] = {
          ContentKR = "그렇게 놀라지 마요. 당신에겐 제가 그저 잠시 머무는 손님일 뿐일지 모르지만 전... 모든 우연한 만남의 뒤에는 그 숨겨진 이유가 있다고 생각해요. 특히, 당신과의 만남이라면 더욱요.",
          DialogueId = 80100106,
          GUID = "C885AFA4",
          NextDialogue = 80100107,
          SpeakNpcId = 92101,
          Subtitle = "Don't be so surprised, hehe. You might treat me as a temporary guest staying over at your place. But for me, every encounter is a story waiting to unfold, especially when it's you.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFA4"
        },
        [80100107] = {
          ContentKR = "절 똑바로 보세요. 전 당신의 와인색 눈동자 안에서 우리의 미래에 대한 가능성을 보았어요. 우리는 분명 취기로 몽롱한 상태로 함께 춤을 추거나 향료원을 거닐게 될 거예요.",
          DialogueId = 80100107,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885AFCE",
          NextDialogue = 80100108,
          SpeakNpcId = 92101,
          Subtitle = "Don't look away. Your wine-red eyes reflect possibilities of our future. Within this intoxicating haze, we shall share a duet of love or a walk in my aroma garden.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFCE"
        },
        [80100108] = {
          ContentKR = "결국 당신도 제 사랑에 익숙해질 거예요. 온몸에 제 향기가 배어들 때쯤, 당신이 저의 그 운명의 상대가 맞는지 운명이 알려주겠죠.",
          DialogueId = 80100108,
          GUID = "C885AFF8",
          NextDialogue = 80100109,
          SpeakNpcId = 92101,
          Subtitle = "You will eventually sway to my passions, and every inch of you shall bear my scent. When that moment comes, fate shall reveal if you are indeed the destined one.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFF8"
        },
        [80100109] = {
          ContentKR = "그리고 이 모든 과정에서 당신은 아무것도 고민할 필요 없이, 그저 제가 이끄는 대로 따라오기만 하면 되죠. 제가 순수하고 달콤한 사랑이 무엇인지 느끼게 해 줄게요.",
          DialogueId = 80100109,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B022",
          NextOptions = {
            [1] = 801001091,
            [2] = 801001092
          },
          SpeakNpcId = 92101,
          Subtitle = "You don't even need to make your own move for all this to happen. Just submit and follow my lead, and I shall let you experience a love of utmost purity and sweetness.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B022"
        },
        [80100110] = {
          ContentKR = "후후, 그래요, 그런 걱정을 할 수도 있죠. 하지만 당신도 알겠지만, 처음 만나고 며칠이 지나고서야 사랑에 빠질 수 있다는 법은 없어요.",
          DialogueId = 80100110,
          GUID = "C885B04C",
          NextDialogue = 80100112,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, I understand your concerns. But you should know that no law or tradition dictates the number of days one must wait for love to sprout.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B04C"
        },
        [80100111] = {
          ContentKR = "쿡... 정말 사랑스러운 생각이네요. 그렇다면 이렇게 말해볼게요. 전 곧 사랑이라는 무대에 오르게 될 거예요. 그리고 지금 아주 어울리는 파트너를 찾고 있죠.",
          DialogueId = 80100111,
          FacialId = {
            [1] = "92101:Shock02"
          },
          GUID = "C885B076",
          NextDialogue = 80100112,
          SpeakNpcId = 92101,
          Subtitle = "Ahem... What a cute and lovely guess. Perhaps I shall rephrase my words: I'm about to ascend the stage called Love, and I'm seeking a suitable partner.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B076"
        },
        [80100112] = {
          ContentKR = "당연하지만, 거절하고 싶다면, 오늘 있던 모든 일을 제가 당신을 위해 특별히 만든 향기로운 꿈이라고 생각하셔도 돼요.",
          DialogueId = 80100112,
          GUID = "C885B0A0",
          NextDialogue = 80100113,
          SpeakNpcId = 92101,
          Subtitle = "Of course, if you wish to refuse, then just treat today's encounter as a scented dream that I have carefully concocted for you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0A0"
        },
        [80100113] = {
          ContentKR = "하지만 알아주셨으면 해요. 저... 각지를 떠도는 조향사 레베카는 계속해서 운명이 정한 사랑의 상대를 찾고 있다는 거예요.",
          DialogueId = 80100113,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B0CA",
          NextDialogue = 80100114,
          SpeakNpcId = 92101,
          Subtitle = "But I want you to know that I, Rebecca the wandering perfumer, am always seeking my destined life partner.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0CA"
        },
        [80100114] = {
          ContentKR = "전 무수한 시도를 해서라도 그 운명의 상대를 찾고, 또 천 번이고 만 번이고 사랑을 속삭이며 그 사람과 영원히 함께하고 싶어요.",
          DialogueId = 80100114,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885B0F4",
          NextDialogue = 80100115,
          SpeakNpcId = 92101,
          Subtitle = "When I finally find the one, I shall share countless moments and sweet words with them, and we will never be apart.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0F4"
        },
        [80100115] = {
          ContentKR = "하지만 쉽지 않은 일이에요. 제 몸은 따뜻하면서도 달콤한 독액에 둘러싸여 있거든요. 그것들이 저를 보호하긴 하지만, 동시에 포옹과 입맞춤의 감각을 느낄 수 없게 만들어 버린답니다.",
          DialogueId = 80100115,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885B11E",
          NextDialogue = 80100116,
          SpeakNpcId = 92101,
          Subtitle = "I know it is difficult, for I am enshrouded in a warm layer of sweet venom. Though the coating protects me, it renders me incapable of receiving intimate hugs or loving kisses.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B11E"
        },
        [80100116] = {
          ContentKR = "그래도 저는 포기하지 않아요. 이 땅이 이런 모습의 저를 태어나게 했다면, 분명 저를 포용할 수 있는 사람도 태어나게 했을 테니까요.",
          DialogueId = 80100116,
          GUID = "C885B148",
          NextDialogue = 80100117,
          SpeakNpcId = 92101,
          Subtitle = "But I never give up. I strongly believe that if this land gave birth to a freak like me, it must have given birth to another who can withstand my venom and accept me for who I am.",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B148"
        },
        [80100117] = {
          ContentKR = "그리고 당신, 와인색의 눈동자를 가진 나의 친구, 당신에게서 그 가능성을 봤어요.",
          DialogueId = 80100117,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B172",
          NextDialogue = 80100118,
          SpeakNpcId = 92101,
          Subtitle = "And you, my darling with wine-red eyes, you showed me the potential in this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B172"
        },
        [80100118] = {
          ContentKR = "그러니 오늘 이 자리를 우리의 첫 달콤한 데이트로 생각하죠. 제 고백에 대한 보답으로 말이에요.",
          DialogueId = 80100118,
          GUID = "C885B19C",
          NextDialogue = 80100119,
          SpeakNpcId = 92101,
          Subtitle = "So, let's consider this very moment as our very first date, a sweet little gift for your sincerity.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B19C"
        },
        [80100119] = {
          ContentKR = "거절해도 좋아요. 하지만 그러면 영원히 제 비밀을 지키기 위해 입술과 혀가 독으로 봉인될지도 몰라요. 어느 쪽이 더 마음에 드나요?",
          DialogueId = 80100119,
          GUID = "C885B1C6",
          SpeakNpcId = 92101,
          Subtitle = "You can refuse, but then my venom will seal your tongue to safeguard my secret forever. Which one do you prefer?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B1C6"
        },
        [80100201] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "또 우리 둘만 남았네요. 모처럼인걸요. 제 그런 면을 알고도 비명을 지르며 도망가지 않는 사람을 만나는 건 말이에요.",
          DialogueId = 80100201,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885BF3A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801002011
          },
          SpeakNpcId = 92101,
          Subtitle = "Another occasion of us alone. It's rare that someone hasn't fled screaming in terror after discovering that side of me.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF3A"
        },
        [80100202] = {
          ContentKR = "눈치채셨지 않나요?",
          DialogueId = 80100202,
          GUID = "C885BF64",
          NextDialogue = 80100203,
          SpeakNpcId = 92101,
          Subtitle = "You must have sensed it already.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF64"
        },
        [80100203] = {
          ContentKR = "팔을 한 번 뻗어 보세요. 얼마나 깨끗한가요. 오래된 굳은살과 상처가 있긴 하지만 그래도 깨끗하잖아요. 또 힘들 때면 그 팔에서는 짭짤한 땀이 나겠죠...",
          DialogueId = 80100203,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885BF8E",
          NextDialogue = 80100204,
          SpeakNpcId = 92101,
          Subtitle = "Stretch out your arms and take a look. Aww, such clean and lovely arms. Though callused and scarred, they remain pure and immaculate. And when tired, they only weep with salty sweat—",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF8E"
        },
        [80100204] = {
          ContentKR = "하지만 제 이... 손에서 나오는 건 치명적인 독뿐이에요.",
          DialogueId = 80100204,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885BFB8",
          NextDialogue = 80100205,
          SpeakNpcId = 92101,
          Subtitle = "They differ from mine, which solely exude and bleed deadly venom.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFB8"
        },
        [80100205] = {
          ContentKR = "통제할 수 없는 독액은 말 안 듣는 오랜 친구 같아요. 저는 덕분에 숲에 숨어있던 필토이드를 쫓아내고, 저를 쫓는 병사들을 영원히 잠들게 할 수 있었죠.",
          DialogueId = 80100205,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885BFE2",
          NextDialogue = 80100206,
          SpeakNpcId = 92101,
          Subtitle = "The uncontrollable venom is like a wild old friend of mine. I rely on it to ward off Filthoids pouncing on me in forest trails or to send pursuing soldiers to an eternal sleep.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFE2"
        },
        [80100206] = {
          ContentKR = "하지만 시도 때도 없이 이빨을 드러내서 제가 가까이하고 싶은 것들도 멀어지게 해요. 제가 샘물로 얼굴을 씻기만 해도, 가까이 다가온 물고기들이 마비되고 질식하니까요.",
          DialogueId = 80100206,
          GUID = "C885C00C",
          NextDialogue = 80100207,
          SpeakNpcId = 92101,
          Subtitle = "But the venom is the vile and vicious repellant of anything and anyone that I wish to get closer to. Merely washing my face in a pond paralyses and suffocates any fish that tries to give me a friendly peck.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C00C"
        },
        [80100207] = {
          ContentKR = "예전엔 이 독을 싫어했어요. 이 독만 없었다면 저도 또래 여자애들처럼 시장에 가서 옷도 고르고, 벽 모퉁이에 숨어 좋아하는 사람을 훔쳐볼 수 있었을 텐데요.",
          DialogueId = 80100207,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C036",
          NextOptions = {
            [1] = 801002071,
            [2] = 801002072
          },
          SpeakNpcId = 92101,
          Subtitle = "I once detested it. If not for my venom, I would be like many other girls of my age. I would be picking out my favorite clothes at the market, or stealing a glance at my crush.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C036"
        },
        [80100208] = {
          ContentKR = "꿈이라기 보다는 한때 잠깐 했던 생각이에요. 지금 생각하면 우습기만 하지만요.",
          DialogueId = 80100208,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C060",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          Subtitle = "They're not dreams. Just occasional notions that never linger. I laugh at myself for having had those thoughts.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C060"
        },
        [80100209] = {
          ContentKR = "익숙해졌다기보다는 길들였다고 할까요. 더 잘 지낼 수 있는 방법을 찾았거든요.",
          DialogueId = 80100209,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C08A",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          Subtitle = "Not exactly. It's more like I've subdued the venom. I found a more fitting way to coexist with it.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C08A"
        },
        [80100210] = {
          ContentKR = "이제는 몰래 훔쳐보지 않아도 되고, 지루하고 요란하기만 한 대화로 서로를 탐색할 필요도 없어요. 잠깐의 달콤한 포옹이면 눈앞의 사람이 저와 평생을 함께할 수 있는 사람인지 알 수 있으니까요.",
          DialogueId = 80100210,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C0B4",
          NextDialogue = 80100211,
          SpeakNpcId = 92101,
          Subtitle = "Now, I no longer peep at someone I like, nor waste time on hours of useless talk to test their sincerity. A moment of sweet embrace is all I need to determine if this one is suited for a long-term commitment with me.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0B4"
        },
        [80100211] = {
          ContentKR = "독액은 제게 가장 소중한 시금석이에요. 언젠가 저의 포옹을 견디는 사람이 나타난다면, 그 사람이 바로 제 운명의 상대라는 걸 바로 확신할 수 있을 거예요.",
          DialogueId = 80100211,
          GUID = "C885C0DE",
          NextDialogue = 80100212,
          SpeakNpcId = 92101,
          Subtitle = "The venom serves as my most valuable touchstone. If I meet someone capable of withstanding my embrace, I would immediately know that I've met the destined one.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0DE"
        },
        [80100212] = {
          ContentKR = "안타깝게도 그런 사람은 아직 나타나지 않았어요. 어쩌면 영원히 나타나지 않을지도 모르죠. 하지만 이게 속물들의 얄팍하고 재미없는 속삭임보다는 훨씬 로맨틱하지 않나요?",
          DialogueId = 80100212,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C108",
          NextDialogue = 80100213,
          SpeakNpcId = 92101,
          Subtitle = "It's just that this person has yet to appear — perhaps they never will. But don't you find this far more romantic than the inane love talks between worldly people?",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C108"
        },
        [80100213] = {
          ContentKR = "적어도 지금의 저에게 이건 선물이에요. 저를 두려워하는 사람, 저를 협박하는 사람, 저를 동정하는 사람, 저에게 아부하는 사람, 모두가 평등한 시험을 받게 하거든요.",
          DialogueId = 80100213,
          GUID = "C885C132",
          NextDialogue = 80100214,
          SpeakNpcId = 92101,
          Subtitle = "At least for me, it's a gift. Those who fear me, intimidate me, care for me, or obey me are all subject to this fair and equal trial.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C132"
        },
        [80100214] = {
          ContentKR = "그래서 지금의 저는 전과 마찬가지로 떠돌아다니고 있지만, 더 이상 다른 사람을 부러워하지 않아요. 제 특별한 독이 저만의 독특한 사랑을 찾아줄 테니까요.",
          DialogueId = 80100214,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C15C",
          NextDialogue = 80100215,
          SpeakNpcId = 92101,
          Subtitle = "Although I remain the same as I was and my wanderings continue, I no longer envy others, because my unique venom will help me find the special love that will be wholly mine.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C15C"
        },
        [80100215] = {
          ContentKR = "그럼, 이제 저의 이 두 팔을 벌려 묻고 싶어요. 저와 포옹하겠어요?",
          DialogueId = 80100215,
          GUID = "C885C186",
          NextOptions = {
            [1] = 801002151,
            [2] = 801002152
          },
          SpeakNpcId = 92101,
          Subtitle = "Now, I intend to open my arms and ask you one question: Will you embrace me?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C186"
        },
        [80100216] = {
          ContentKR = "후후, 겁내지 마세요. 제 과거 이야기를 이렇게 많이 들은 건 당신이 처음이거든요. 기회는 단 한 번 뿐이지만, 어쩌면 당신이 제가 찾던 바로 그 사람일지도 모르잖아요?",
          DialogueId = 80100216,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885C1B0",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, don't be scared. You're the first to hear me divulge this much about my past. You get only one chance, but perhaps you're indeed the one I've been searching for.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1B0"
        },
        [80100217] = {
          ContentKR = "말은 그렇게 하고선 손에 든 칼로 제 목을 찌르시려고요? 그렇게 경계할 필요 없어요. 느껴지나요? 사실 우리는 같은 부류예요. 둘 다 다른 사람들과는 다른 운명을 타고났죠.",
          DialogueId = 80100217,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885C1DA",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          Subtitle = "And then you'll pierce my throat with that sword in your hand, right? Hehe, don't be so on guard. I can feel it. We're kindred souls, you and me, fated to lead lives not shared by any other.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1DA"
        },
        [80100218] = {
          ContentKR = "하하... 당신이 시작한 데이트가 당신의 거절로 끝날 거라고는 생각하지 못했네요. 정말 아쉽네요.",
          DialogueId = 80100218,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C204",
          NextDialogue = 80100219,
          SpeakNpcId = 92101,
          Subtitle = "*sigh* I didn't expect that this date, iniciated by you, would actually end with your rejection of my advance. What a pity.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C204"
        },
        [80100219] = {
          ContentKR = "하지만 우리에겐 시간이 많아요. 조심하세요. 어느 날 갑자기 제가 뒤에서 당신을 꼭 안아버릴지도 모르니까요.",
          DialogueId = 80100219,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885C22E",
          NextOptions = {
            [1] = 801002191
          },
          SpeakNpcId = 92101,
          Subtitle = "But we still have time, and you'd better be careful. A day might come when I decide to appear right behind you and hold you tight.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C22E"
        },
        [80100220] = {
          ContentKR = "어머, 정말 귀엽네요. 꼭 이빨을 드러낸 아기고양이 같아요... 아무래도 잠시 떨어져 있는 게 좋겠네요. 다음 만남을 기다리고 있을게요. 안녕...",
          DialogueId = 80100220,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885C258",
          SpeakNpcId = 92101,
          Subtitle = "Oh, how cute, just like a little kitten baring its tiny fangs. Perhaps I should keep my distance, then. Goodbye, I look forward to our next rendezvous.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C258"
        },
        [80100221] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.396057,51.444664,130.0,false,Manual,2.8",
          ContentKR = "반가워요. 얼마나 지났다고 금방 또 만났네요.",
          DialogueId = 80100221,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C282",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100222,
          SpeakNpcId = 92101,
          Subtitle = "Only a few seconds have passed, yet we meet again.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C282"
        },
        [80100222] = {
          ContentKR = "당신도 저를 그렇게 경계하지는 않는 것 같아 기뻐요. 안심하세요. 저도 지금 당신을 껴안을 생각은 없으니까요. 대신 조언 하나만 할게요.",
          DialogueId = 80100222,
          GUID = "C885C2AC",
          NextDialogue = 80100223,
          SpeakNpcId = 92101,
          Subtitle = "Hehe, it seems you're not that wary of me, which is nice. Don't worry, I don't intend to embrace you right now, but I have a word of advice:",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2AC"
        },
        [80100223] = {
          ContentKR = "다음에 만날 땐, 저의 목소리가 들리면 꼭 돌아서서 저한테서 시선을 떼지 마세요. 안 그러면... 위험할지도 모르거든요.",
          DialogueId = 80100223,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C2D6",
          NextDialogue = 80100224,
          SpeakNpcId = 92101,
          Subtitle = "Turn around and look at me once you hear my voice the next time we meet, and do not shift your gaze elsewhere, or something dangerous might happen.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2D6"
        },
        [80100224] = {
          ContentKR = "그럼, 이번엔 정말로... Arrivederci.",
          DialogueId = 80100224,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C300",
          SpeakNpcId = 92101,
          Subtitle = "Now, this is goodbye for sure. Arrivederci.",
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C300"
        },
        [80100301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "오늘은 '사랑의 기운'에 이끌려 왔어요. 제 독액 한 방울 한 방울이 당신을 보고 싶어 했거든요.",
          DialogueId = 80100301,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885CFA2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100302,
          SpeakNpcId = 92101,
          Subtitle = "The \"Unspoken Bond of Love\" has called me here today. Every drop of my venom yearns to see you.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFA2"
        },
        [80100302] = {
          ContentKR = "자, 우리가 얼마나 통하는지 한번 볼까요? 제가 다음에 무슨 말을 할지 맞춰보세요.",
          DialogueId = 80100302,
          GUID = "C885CFCC",
          NextOptions = {
            [1] = 801003021,
            [2] = 801003022
          },
          SpeakNpcId = 92101,
          Subtitle = "Interested in seeing how in tune we are with each other? Guess what I'm about to say next.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFCC"
        },
        [80100303] = {
          ContentKR = "솔직함도 당신의 매력 중 하나죠.",
          DialogueId = 80100303,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885CFF6",
          NextDialogue = 80100304,
          SpeakNpcId = 92101,
          Subtitle = "And being so straightforward happens to be one of your charms.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFF6"
        },
        [80100304] = {
          ContentKR = "말 돌리는 건 이쯤 하고, 바로 옛날이야기를 해보죠.",
          DialogueId = 80100304,
          GUID = "C885D020",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          Subtitle = "Then let's just skip the senseless prattle and focus directly on matters of the past.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D020"
        },
        [80100305] = {
          ContentKR = "맞아요. 역시 우리는 통한다니까요. 앞으로 제가 할 일이 틀리지 않는다는 걸 알겠어요.",
          DialogueId = 80100305,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885D04A",
          NextDialogue = 80100306,
          SpeakNpcId = 92101,
          Subtitle = "That's right. See, we are so in sync with each other. Seems I've made the right choice in deciding to do this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D04A"
        },
        [80100306] = {
          ContentKR = "사실, 당신에게 위험이 다가오고 있다는 걸 솔직하게 알려드리려고요.",
          DialogueId = 80100306,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D074",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          Subtitle = "I'm about to share a certain secret with you, which also means danger is approaching.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D074"
        },
        [80100307] = {
          ContentKR = "전에 저와 비슷한 사람을 만난 적이 있어요. 그 여자는 태어날 때부터 화염처럼 붉은 피부를 가졌어요. 성격도 불같아서 쉽게 화내고 복잡한 걸 못 견뎌했죠.",
          DialogueId = 80100307,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D09E",
          NextDialogue = 80100308,
          SpeakNpcId = 92101,
          Subtitle = "I once met someone like me. She was born with fiery-red skin. Her temperament is the same, a blazing firebrand with little tolerance for the impure.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D09E"
        },
        [80100308] = {
          ContentKR = "어릴 때부터 사람들에게 괴물 같다며 손가락질 받던 저와는 달리, 그 사람은 가문의 사명을 지고 큰 기대를 받으며 자랐어요. 결국 죄수들을 감시하는 정의의 심판관이 되었죠. 또 자신이 노린 범죄자는 절대 놓치지 않았어요.",
          DialogueId = 80100308,
          GUID = "C885D0C8",
          NextDialogue = 80100309,
          SpeakNpcId = 92101,
          Subtitle = "Unlike me, a monster despised and abandoned since childhood, she carries the legacy and hopes of her family, and ultimately becomes the righteous warden. No criminal she sets her sights on can ever escape her.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0C8"
        },
        [80100309] = {
          ContentKR = "하지만 그 사람의 불꽃은 제 독과 비슷해서, 가까이 오려는 모든 이들을 밀어냈어요. 선의를 품었든, 악의를 품었든, 아무도 접근할 수 없었죠. 아니면 두려움에 멀어지거나요.",
          DialogueId = 80100309,
          GUID = "C885D0F2",
          NextOptions = {
            [1] = 801003091
          },
          SpeakNpcId = 92101,
          Subtitle = "However, like my venom, her flames tend to drive away or scare off anyone who tries to approach, be it with good or ill intent.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0F2"
        },
        [80100310] = {
          ContentKR = "맞아요. 아시다시피, 저 같은 천성적으로 독을 지닌 괴물은 고의든 아니든 실수로 타인의 목숨을 앗아가게 되죠. 그러니 누군가 저를 쫓는 것도 이상한 일은 아니에요.",
          DialogueId = 80100310,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D11C",
          NextDialogue = 80100311,
          SpeakNpcId = 92101,
          Subtitle = "Yes. You know, a monster like me, who's born with lethal venom, can't help but leave a few bodies behind, whether by accident or willful intent. It shouldn't surprise you that I'm wanted.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D11C"
        },
        [80100311] = {
          ContentKR = "하지만 그 사람의 길고 집요한 추적 과정에서 한 가지를 깨달았어요. 그녀도 저와 마찬가지로 외로운 괴물이라는 걸요. 그래서 저는 이 점을 이용했죠.",
          DialogueId = 80100311,
          GUID = "C885D146",
          NextDialogue = 80100312,
          SpeakNpcId = 92101,
          Subtitle = "During her long and persistent chase, I realised something — she's just like me, we're both lonely monsters. So, I took advantage of this.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D146"
        },
        [80100312] = {
          ContentKR = "진심 어린 고백을 하는 척했고, 그녀는 잠시 망설였어요. 자신이 이 넓은 아트라시아 대륙에서 유일한 변종이 아니라고, 또 연민과 용서를 통해 저를 멈추게 할 수 있다고 믿게 했죠.",
          DialogueId = 80100312,
          GUID = "C885D170",
          NextDialogue = 80100313,
          SpeakNpcId = 92101,
          Subtitle = "I offered a seemingly sincere confession to confuse her, making her realise that she wasn't the only freak in this vast land and think that her pity and clemency would get me back on track.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D170"
        },
        [80100313] = {
          ContentKR = "그리고 저는 그 사람이 증거를 직접 처리한 걸 확인하자마자 바로 도망갔어요.",
          DialogueId = 80100313,
          GUID = "C885D19A",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100314,
          SpeakNpcId = 92101,
          Subtitle = "But then, I just ran away right after she destroyed the evidence of my crimes.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D19A"
        },
        [80100314] = {
          ContentKR = "그 사람이 이를 갈며 저를 잡으려 불같이 화내는 모습을 당신은 상상하기 힘들 거예요. 하지만 이해하셨겠죠? 저를 감싸준 당신도 공범으로 여겨져 함께 감옥에 갇힐 수 있다는 걸요.",
          DialogueId = 80100314,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D1C4",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801003141,
            [2] = 801003142
          },
          SpeakNpcId = 92101,
          Subtitle = "You can hardly imagine how furious she became, how her fires burnt as she gnashed her teeth and swore to throw me in prison. However, you should know that by granting me refuge, you will be seen as an accomplice.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1C4"
        },
        [80100315] = {
          ContentKR = "그랬군요. 처음 당신을 봤을 때 느꼈던 그 매혹적인 위험한 기운의 이유를 이제 알 것 같아요.",
          DialogueId = 80100315,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885D1EE",
          NextDialogue = 80100316,
          SpeakNpcId = 92101,
          Subtitle = "Is that so? Now I understand why I always feel an intoxicating aura of danger whenever I see you.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1EE"
        },
        [80100316] = {
          ContentKR = "그럼, 제가 앞으로 닥칠 위험에 대해 알려드렸는데도, 피하지 않으신다는 건... 이제 제가 당신에게 더 가까이 다가가도 된다는 뜻으로 받아들여도 될까요?",
          DialogueId = 80100316,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D218",
          NextDialogue = 80100317,
          SpeakNpcId = 92101,
          Subtitle = "Since you showed no sign of displeasure or rejection after I told you about a potential threat, does that mean we're growing closer?",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D218"
        },
        [80100317] = {
          ContentKR = "사실 이런 위험한 과거에 대해 알려드리기 전에 좀 망설였어요. 또다시 떠돌아다니게 될까 봐 걱정됐거든요.",
          DialogueId = 80100317,
          GUID = "C885D242",
          NextDialogue = 80100318,
          SpeakNpcId = 92101,
          Subtitle = "I confess that I did struggle a bit when I was deciding if I should tell you about my dangerous past. I was worried that I would end up wandering this world on my own again.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D242"
        },
        [80100318] = {
          ContentKR = "하지만, 그보다도 당신이 더 큰 위험에 처하는 걸 보고 싶지 않았어요. 제 독만으로도 이미 충분히 위험하니까요.",
          DialogueId = 80100318,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D26C",
          NextDialogue = 80100319,
          SpeakNpcId = 92101,
          Subtitle = "But I cannot bear to see you menaced by other threats. My venom alone is dangerous enough as it is.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D26C"
        },
        [80100319] = {
          ContentKR = "다행히 당신의 대답 덕분에 더욱 확신하게 됐어요. 제가 여기 머문다면 반드시 제 운명의 상대를 찾을 수 있을 거라고요.",
          DialogueId = 80100319,
          GUID = "C885D296",
          NextOptions = {
            [1] = 801003191
          },
          SpeakNpcId = 92101,
          Subtitle = "Yet your answers have strengthened my belief that I shall find my destined one by staying here.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D296"
        },
        [80100320] = {
          ContentKR = "그래요, 루카 공화국에서 휘페르보레아까지 찾아다녔지만 만나지 못한 사람이죠. 전에는 그 사람이 제 꿈속에만 존재한다고 생각했어요. 빛나고 찬란하지만 흐릿하고 아른거리는...",
          DialogueId = 80100320,
          GUID = "C885D2C0",
          NextDialogue = 80100321,
          SpeakNpcId = 92101,
          Subtitle = "Yes, someone that I've yet to find as I travelled from Luca to Hyperborea. I thought that person only appeared in my dreams as a shiny yet indistinct figure.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2C0"
        },
        [80100321] = {
          ContentKR = "그 사람이라면 강인한 몸으로 제 모든 독을 견뎌낼 수 있을 거예요... 순수한 마음으로 제 모든 사랑을 받아들일 수 있을 거예요... 또 자비로운 손길로 제 모든 슬픔을 어루만져 줄 거예요...",
          DialogueId = 80100321,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885D2EA",
          NextDialogue = 80100322,
          SpeakNpcId = 92101,
          Subtitle = "{性别:His|Her} body is strong enough to withstand every drop of my venom... whose heart is pure enough to take in all my love... and whose hands are gentle enough to wipe away all my sorrows...",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2EA"
        },
        [80100322] = {
          ContentKR = "그 사람이 제 말을 들었을까요? 어떻게 생각해요?",
          DialogueId = 80100322,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D314",
          NextOptions = {
            [1] = 801003221,
            [2] = 801003222
          },
          SpeakNpcId = 92101,
          Subtitle = "Do you think {性别:he|she} has heard all that?",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D314"
        },
        [80100323] = {
          ContentKR = "아... 풋... 하하하...",
          DialogueId = 80100323,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885D33E",
          NextDialogue = 80100324,
          SpeakNpcId = 92101,
          Subtitle = "Oh... Hahahaha...",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D33E"
        },
        [80100324] = {
          ContentKR = "당신은 역시 귀엽고 이상하네요. 너무 재미있어서 그 매력에서 못 벗어나겠어요.",
          DialogueId = 80100324,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D368",
          NextDialogue = 80100325,
          SpeakNpcId = 92101,
          Subtitle = "You are so cute, weird, and interesting that I just can't get enough of...",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D368"
        },
        [80100325] = {
          ContentKR = "지금 당장 독으로 당신을 감싸버리고 싶지만... 저도 경솔한 장난을 좋아하지는 않으니까요.",
          DialogueId = 80100325,
          GUID = "C885D392",
          NextDialogue = 80100326,
          SpeakNpcId = 92101,
          Subtitle = "I really want to embrace you with my venom now... But I'm 100% serious when it comes to love.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D392"
        },
        [80100326] = {
          ContentKR = "그러니 우리 둘 다 생각할 시간을 가져보는 게 어떨까요? 저도 어떻게 하면 좋을지 곰곰이 생각해 봐야겠어요.",
          DialogueId = 80100326,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D3BC",
          SpeakNpcId = 92101,
          Subtitle = "So, let's give us some time to ponder over it.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3BC"
        },
        [80100327] = {
          ContentKR = "교활한 사람이군요. 이렇게 애매모호한 말로 거절하면서도 희미한 가능성은 남겨두는 건가요?",
          DialogueId = 80100327,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D3E6",
          NextDialogue = 80100328,
          SpeakNpcId = 92101,
          Subtitle = "How cunning. How do you come up with these ambiguous lines of rejection that subtly lead people on?",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3E6"
        },
        [80100328] = {
          ContentKR = "적당한 거리라... 이걸 어떻게 받아들여야 할까요? 제게 가장 적당한 거리는 그림자처럼 떨어지지 않는 건데, 당신에게 적당한 거리는 어떤 건가요?",
          DialogueId = 80100328,
          GUID = "C885D410",
          NextDialogue = 80100329,
          SpeakNpcId = 92101,
          Subtitle = "Appropriate... how am I supposed to interpret that? For me, shadowing you around is the appropriate distance... But what about you? I'm not sure what's the appropriate distance for you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D410"
        },
        [80100329] = {
          ContentKR = "비밀연애 중인 사람처럼 다른 사람 앞에선 모르는 척하며, 은근히 곁에 있는 건가요? 아니면 서로 영원히, 다시는 만나지 않는 건가요?",
          DialogueId = 80100329,
          GUID = "C885D43A",
          NextDialogue = 80100330,
          SpeakNpcId = 92101,
          Subtitle = "Is it like secret lovers who frolic only when alone and pretend to be strangers in the presence of others? Or should we just go our separate ways and never, ever see each other again?",
          TalkActionId = {
            [1] = "92101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D43A"
        },
        [80100330] = {
          ContentKR = "저울의 양쪽 끝에 있는 '좋아'나 '더 좋은 사람을 만날 거야'같은 직접 말하는 간단한 길 보다는 계속 대화하고 탐색하는 걸 좋아하시는 것 같네요.",
          DialogueId = 80100330,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D464",
          NextDialogue = 80100331,
          SpeakNpcId = 92101,
          Subtitle = "But these two extremes might just offer the easiest solutions. Instead of just saying \"I do\" or \"I hope you find someone who actually deserves you,\" you chose the option that paves the way for future dialogues and tests.",
          TalkActionId = {
            [1] = "92101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D464"
        },
        [80100331] = {
          ContentKR = "저는 당신에게 너무 가까이 다가가 위험에 빠뜨릴 수도, 멀리 떨어져 완전히 남이 될 수도 없어요.",
          DialogueId = 80100331,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D48E",
          NextDialogue = 80100332,
          SpeakNpcId = 92101,
          Subtitle = "I can't get too close and risk putting you in danger, nor can I stay away from you and let us become strangers.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D48E"
        },
        [80100332] = {
          ContentKR = "성분 비율이 표기되지 않은 향수를 조향하는 것처럼, 가장 좋은 결과를 낼 때까지 계속 시도하는 것밖에 없겠네요.",
          DialogueId = 80100332,
          GUID = "C885D4B8",
          NextOptions = {
            [1] = 801003321
          },
          SpeakNpcId = 92101,
          Subtitle = "This is like crafting a perfume formula without precise measurements. I can only keep fiddling with the weights and measures as I work towards the perfect result.",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4B8"
        },
        [80100333] = {
          ContentKR = "맞아요. 이렇게 어려운 상황은 처음이거든요. 또 이걸 해결한 뒤엔 제가 찾아 헤매던 그 답을 찾아 운명의 상대를 찾을 거라고 믿고 있어요.",
          DialogueId = 80100333,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D4E2",
          NextOptions = {
            [1] = 801003331
          },
          SpeakNpcId = 92101,
          Subtitle = "Of course I am. I've never had a problem like this before, and I believe that by solving it, I will get the answer I've been looking for and find my destined one.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4E2"
        },
        [80100334] = {
          ContentKR = "그래요, 루카 공화국에서 휘페르보레아까지 찾아다녔지만 만나지 못한 사람이죠. 전에는 그 사람이 제 꿈속에만 존재한다고 생각했어요. 빛나고 찬란하지만 흐릿하고 아른거리는...",
          DialogueId = 80100334,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D50C",
          NextDialogue = 80100335,
          SpeakNpcId = 92101,
          Subtitle = "Yes, someone that I've yet to find as I travelled from Luca to Hyperborea. I thought that person only appeared in my dreams as a shiny yet indistinct figure.",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D50C"
        },
        [80100335] = {
          ContentKR = "그 사람이라면 강인한 몸으로 제 모든 독을 견뎌낼 수 있을 거예요... 순수한 마음으로 제 모든 사랑을 받아들일 수 있을 거예요... 또 자비로운 손길로 제 모든 슬픔을 어루만져 줄 거예요...",
          DialogueId = 80100335,
          GUID = "C885D536",
          NextDialogue = 80100336,
          SpeakNpcId = 92101,
          Subtitle = "{性别:His|Her} body is strong enough to withstand every drop of my venom... whose heart is pure enough to take in all my love... and whose hands are gentle enough to wipe away all my sorrows...",
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D536"
        },
        [80100336] = {
          ContentKR = "그 운명의 상대가, 이토록 귀엽고 특이하고 재미있어서 저를 헤어나지 못하게 만드는 당신인지는...",
          DialogueId = 80100336,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885D560",
          NextDialogue = 80100337,
          SpeakNpcId = 92101,
          Subtitle = "As for whether the destined one is you, who is so cute, weird, and interesting that I just can't get enough of...",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D560"
        },
        [80100337] = {
          ContentKR = "저한테 시간을 좀 주세요. 제가 어떻게 해야 하면 좋을지 곰곰이 생각해 봐야겠어요.",
          DialogueId = 80100337,
          GUID = "C885D58A",
          SpeakNpcId = 92101,
          Subtitle = "Please give me some time to ponder over it.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D58A"
        },
        [80100401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "휴우...",
          DialogueId = 80100401,
          FacialId = {
            [1] = "92101:Sad02"
          },
          GUID = "C885E00A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801004011,
            [2] = 801004012
          },
          SpeakNpcId = 92101,
          Subtitle = "*sigh*...",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E00A"
        },
        [80100402] = {
          ContentKR = "그래요. 아주 아주 골치 아픈 일이에요. 머릿속이 복잡해요. 그리고 그 골치가 아픈 이유는 바로 당신 때문이에요.",
          DialogueId = 80100402,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E034",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          Subtitle = "Yes, a most vexing matter, and the person who is in front of me is the very source of that trouble.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E034"
        },
        [80100403] = {
          ContentKR = "아뇨, 시간의 문제가 아니라 사람의 문제예요. 초대를 받은 그 순간부터 계속 머릿속이 복잡했거든요.",
          DialogueId = 80100403,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E05E",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          Subtitle = "No, it's not about the timing, it's the person. My troubles began the moment I received your invitation.",
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E05E"
        },
        [80100404] = {
          ContentKR = "아시나요? 당신은 겉으로는 순수해 보이지만, 당신 또한 독으로 사람을 질식시킬 수도 있다는 사실을?",
          DialogueId = 80100404,
          GUID = "C885E088",
          NextDialogue = 80100405,
          SpeakNpcId = 92101,
          Subtitle = "Despite your pure, flawless appearance, you can suffocate people with your own \"venom.\"",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E088"
        },
        [80100405] = {
          ContentKR = "당신은 저와 다르게 첫 만남에서 자신의 위험성을 알리지 않았죠. 대신 말로 정교하게 그물을 엮었어요.",
          DialogueId = 80100405,
          GUID = "C885E0B2",
          NextDialogue = 80100406,
          SpeakNpcId = 92101,
          Subtitle = "You did not announce your danger like I did at our first encounter, but instead cautiously wove a web of words.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0B2"
        },
        [80100406] = {
          ContentKR = "어쩌면 당신은 의도하지 않았을지도 모르지만, 그래서 더 무서워요. 사람들이 모르는 사이에 여기 머물게 되고, 당신에 의해 조금씩 변하면서 원래의 자신이 아니게 되니까요.",
          DialogueId = 80100406,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E0DC",
          NextDialogue = 80100407,
          SpeakNpcId = 92101,
          Subtitle = "Perhaps you didn't mean to, but it makes people more accustomed to staying here subconsciously, being imperceptibly influenced and changed by you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0DC"
        },
        [80100407] = {
          ContentKR = "전 루카 공화국을 떠난 후로 한 곳에서 오래 머무른 적이 거의 없어요. 정말 중요하게 여길 만한 사람도 만나지 못했고요.",
          DialogueId = 80100407,
          GUID = "C885E106",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100408,
          SpeakNpcId = 92101,
          Subtitle = "After leaving Luca, I hardly stayed at any place for long or met anyone worthy of my attention.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E106"
        },
        [80100408] = {
          ContentKR = "이번에도 똑같을 줄 알았어요. 지루해질 때쯤 포옹으로 마지막 작별인사를 하고 떠날 거라고요.",
          DialogueId = 80100408,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E130",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100409,
          SpeakNpcId = 92101,
          Subtitle = "I thought it would be the same this time — that I would bid farewell to the one with my embrace when I was tired of the journey.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E130"
        },
        [80100409] = {
          ContentKR = "하지만 이번엔 망설이게 되네요. 제 몸속의 독이 제게 이곳을 떠날 수 없다고 속삭이고 있어요.",
          DialogueId = 80100409,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885E15A",
          NextDialogue = 80100410,
          SpeakNpcId = 92101,
          Subtitle = "But I hesitated this time. The venom within my body keeps whispering that I can never leave this place.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E15A"
        },
        [80100410] = {
          ContentKR = "저도 이런 제 모습을 받아들일 수 없었고, 그래서 이렇게 고민을 시작하게 된 거예요. 그래서 전 오늘, 이 여행의 휴식에 마침표를 찍기로 했어요.",
          DialogueId = 80100410,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E184",
          NextDialogue = 80100411,
          SpeakNpcId = 92101,
          Subtitle = "I can't take this, and this is the source of my troubles. So, I've decided to conclude this journey today.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E184"
        },
        [80100411] = {
          ContentKR = "간단히 말해서... 제 독으로 당신을 감싸 안으며 작별 인사를 하려고요.",
          DialogueId = 80100411,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E1AE",
          NextDialogue = 80100412,
          SpeakNpcId = 92101,
          Subtitle = "Simply put — I want to wrap you in my venom and bid you farewell.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1AE"
        },
        [80100412] = {
          ContentKR = "자, 이제 남은 몇 초 동안 하고 싶은 말이 있나요?",
          DialogueId = 80100412,
          GUID = "C885E1D8",
          NextOptions = {
            [1] = 801004121,
            [2] = 801004122
          },
          SpeakNpcId = 92101,
          Subtitle = "So, any last words for the last seconds?",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1D8"
        },
        [80100413] = {
          ContentKR = "피하고 있다고요? 설마요. 제가 정말 원하는 게 뭔지 잘 알고 있어요. 저는 그저 당신이 겁에 질린 모습을 보고 싶을 뿐이에요.",
          DialogueId = 80100413,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E202",
          NextDialogue = 80100414,
          SpeakNpcId = 92101,
          Subtitle = "Running away? No, not at all. I know exactly what I want, and I yearn to see the terror on your face.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E202"
        },
        [80100414] = {
          ContentKR = "딱히 놀라지는 않은 것 같군요. 정말 아쉬워요.",
          DialogueId = 80100414,
          GUID = "C885E22C",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          Subtitle = "But you don't seem scared. What a pity.",
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E22C"
        },
        [80100415] = {
          ContentKR = "그 정도로 별로였나요? 정말로 하나도 안 놀랐나요? 겁에 질린 얼굴이 보고 싶었는데, 정말 아쉽네요.",
          DialogueId = 80100415,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E256",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          Subtitle = "Really? That didn't scare you at all? I was so hoping to see terror on your face. What a pity.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E256"
        },
        [80100416] = {
          ContentKR = "그럼 장난은 이제 됐고, 이제 제 진짜 결정을 말씀드릴게요.",
          DialogueId = 80100416,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E280",
          NextDialogue = 80100417,
          SpeakNpcId = 92101,
          Subtitle = "Then I'll have to settle for the next best thing, and tell you about my real thoughts.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E280"
        },
        [80100417] = {
          ContentKR = "당신과 함께 보낸 최근 며칠은, 이전의 제 일상과 완전히 달랐어요. 매일 오후 이렇게 당신과 사랑의 말을 건네며 서로를 탐색하는 시간을 가졌죠...",
          DialogueId = 80100417,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E2AA",
          NextDialogue = 80100418,
          SpeakNpcId = 92101,
          Subtitle = "Days I shared with you are unlike the others I had before. I would say romantic things and we would test each other's sincerity during these afternoon dates...",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2AA"
        },
        [80100418] = {
          ContentKR = "그리고 헤어진 후에는 우산을 펴고 아무도 없는 골목으로 달려가 우리가 나눈 대화를 되새기며 혼자 춤을 추곤 했어요.",
          DialogueId = 80100418,
          GUID = "C885E2D4",
          NextDialogue = 80100419,
          SpeakNpcId = 92101,
          Subtitle = "And when the date ended, I would take my umbrella and find a deserted alley. There, I would mull over the conversations we had while dancing and swaying all on my own.",
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2D4"
        },
        [80100419] = {
          ContentKR = "후훗... 이것도 나름의 로맨스 아닐까요?",
          DialogueId = 80100419,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E2FE",
          NextDialogue = 80100420,
          SpeakNpcId = 92101,
          Subtitle = "Hehe... Isn't that romantic as well?",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2FE"
        },
        [80100420] = {
          ContentKR = "지금까지 저는 제 포옹을 견딜 수 있는 운명의 상대를 찾으려고 했지만 오늘에서야 깨달았어요. 제가 진정으로 원했던 건 그저 하나뿐인 특별한 사랑이었다는 걸요.",
          DialogueId = 80100420,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E328",
          NextDialogue = 80100421,
          SpeakNpcId = 92101,
          Subtitle = "I had always wanted to find the destined one who was capable of surviving my embrace. But today, I finally realised that all I want is love that belongs to me.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E328"
        },
        [80100421] = {
          ContentKR = "'포옹'은 한때 제 시금석이었죠. 하지만 단 한 번 마음이 두근거리자 깨닫게 됐죠. 하나뿐인 특별한 사랑은 그런 검증 따윈 필요 없다는 걸요.",
          DialogueId = 80100421,
          GUID = "C885E352",
          NextDialogue = 80100422,
          SpeakNpcId = 92101,
          Subtitle = "My embrace used to be my touchstone. But when my heart skipped a beat, I started to know that true love, the kind I can call my own, does not need to be tested.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E352"
        },
        [80100422] = {
          ContentKR = "키스나 포옹도 꼭 필요한 게 아니에요. 오히려 제가 원하는 건 더 오래, 사라지지 않는 잔향 같은 거예요.",
          DialogueId = 80100422,
          GUID = "C885E37C",
          NextDialogue = 80100423,
          SpeakNpcId = 92101,
          Subtitle = "The kisses and hugs are not necessary. I prefer the lingering aftertaste that does not fade.",
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E37C"
        },
        [80100423] = {
          ContentKR = "매일 아침 서로 인사하고 제가 새로 만든 향수의 향기를 맡아 보고 또 새로운 조합을 시도해 보는 이런 일상이 매일 반복돼도 좋을 것 같아요.",
          DialogueId = 80100423,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885E3A6",
          NextDialogue = 80100424,
          SpeakNpcId = 92101,
          Subtitle = "It doesn't seem bad to have daily routines like morning greetings, smelling my latest perfume, and continuing my work on other perfume recipes...",
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3A6"
        },
        [80100424] = {
          ContentKR = "제 독을 무력화할 수 있는 향수를 만들거나, 독을 정화할 수 있는 마법을 찾아볼 거예요. 고향의 동화 속 인어공주처럼 사랑하는 사람을 위해 온갖 방법을 동원해서 제 자신을 바꿔볼 거예요.",
          DialogueId = 80100424,
          GUID = "C885E3D0",
          NextDialogue = 80100425,
          SpeakNpcId = 92101,
          Subtitle = "I will try to make a perfume that can neutralise my venom, or search for a spell that can cleanse the toxins. Like some little mermaid in those fairytales, I'll do whatever I can to change for my love.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3D0"
        },
        [80100425] = {
          ContentKR = "어쩌면 언젠가는 당신을 안을 수 있게 될지도 몰라요.",
          DialogueId = 80100425,
          GUID = "C885E3FA",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100426,
          SpeakNpcId = 92101,
          Subtitle = "Perhaps a day will come when I can finally hold you in my arms.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3FA"
        },
        [80100426] = {
          ContentKR = "시험해 보려는 게 아니라 그저... 당신을 사랑하니까요.",
          DialogueId = 80100426,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885E424",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          SpeakNpcId = 92101,
          Subtitle = "Not for any test, but only to express my love for you.",
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E424"
        },
        [80110100] = {
          ContentKR = "하, 고마워.",
          DialogueId = 80110100,
          GUID = "C88C1748",
          Subtitle = "Hah, thanks.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1748"
        },
        [80110101] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentKR = "잘 만든 것 같냐고? 번지수 잘못 찾았어. 나한테 그런거 물어봐도 난 잘 모른다고.",
          DialogueId = 80110101,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1772",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110102,
          SpeakNpcId = 93101,
          Subtitle = "Assessing your drink mixing skills? You got the wrong person. I know nothing about this.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1772"
        },
        [80110102] = {
          ContentKR = "나한텐 세상의 모든 술이 다 똑같아. 마실 수만 있으면 그만이지. 유리잔에서 울리는 소리는 마치 시 읊는 것처럼 들리고 말야.",
          DialogueId = 80110102,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C179C",
          NextOptions = {
            [1] = 801101021
          },
          SpeakNpcId = 93101,
          Subtitle = "All drinks are the same to me — If it tastes right, I'll drink it. When it comes to these bottles and flasks sounds, they are just noise to me.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C179C"
        }
      }
    end
  },
  {
    MinKey = 80110103,
    MaxKey = 80120327,
    Loader = function()
      return {
        [80110103] = {
          ContentKR = "군단은 싸우는 곳이야, 소풍 가는 곳이 아니라고.",
          DialogueId = 80110103,
          GUID = "C88C17C6",
          NextDialogue = 80110104,
          SpeakNpcId = 93101,
          Subtitle = "The Legion's built for war, not picnics.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17C6"
        },
        [80110104] = {
          ContentKR = "잠깐, 방금 '군단'이라고...?",
          DialogueId = 80110104,
          FacialId = {
            [1] = "93101:Doubt01"
          },
          GUID = "C88C17F0",
          NextDialogue = 80110105,
          SpeakNpcId = 93101,
          Subtitle = "Wait, you mentioned the \"Legion\"...",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17F0"
        },
        [80110105] = {
          ContentKR = "...너 뭐야? 무슨 속셈이지? 정체가 뭐야? 누가 보냈어? 어떤 정보를 캐내려는 거야? 바른대로 말해.",
          DialogueId = 80110105,
          GUID = "C88C181A",
          NextOptions = {
            [1] = 801101051,
            [2] = 801101052
          },
          SpeakNpcId = 93101,
          Subtitle = "...What do you want? What are you planning? Who are you? Who sent you? What intel are you after? Spill it.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C181A"
        },
        [80110106] = {
          ContentKR = "'월석 사냥꾼' 주제에 알고 있는 게 너무 많군.",
          DialogueId = 80110106,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1844",
          NextDialogue = 80110107,
          SpeakNpcId = 93101,
          Subtitle = "You're too well-informed for a mere Phoxhunter.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1844"
        },
        [80110107] = {
          ContentKR = "...이럴 줄 알았다니까, 갑자기 웬 공짜 술인가 했더니 역시 꿍꿍이가 있었군.",
          DialogueId = 80110107,
          GUID = "C88C186E",
          NextDialogue = 80110108,
          SpeakNpcId = 93101,
          Subtitle = "…I should've known. No one offers gifts without wanting something in return.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C186E"
        },
        [80110108] = {
          ContentKR = "나랑 군단에 가서 진득하게 이야기 해보실까? 얌전히 따라와. 괜히 힘들게 묶어서 메고 가게 하지 말고.",
          DialogueId = 80110108,
          FacialId = {
            [1] = "93101:Confident01"
          },
          GUID = "C88C1898",
          NextDialogue = 80110109,
          SpeakNpcId = 93101,
          Subtitle = "Time to take you to the Legion for questioning. Cooperate, and don't make me tie you up — it won't look good for either of us.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1898"
        },
        [80110109] = {
          ContentKR = "(린이 망설임 없이 총을 꺼내들고, 검은 총구가 내 미간을 겨누고 있는 모습이 머릿속에 떠오른다.)",
          DialogueId = 80110109,
          GUID = "C88C18C2",
          IsBlack = 1,
          NextDialogue = 80110110,
          Subtitle = "(The following quickly flashes through your mind: Lynn takes out her gun immediately, and the dark muzzle is pointed straight at your forehead.)",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18C2"
        },
        [80110110] = {
          ContentKR = "(이는 필연적인 결말이 될 것이다. 고개를 저으며 이 무모한 생각을 떨쳐낸다.)",
          DialogueId = 80110110,
          GUID = "C88C18EC",
          IsBlack = 1,
          NextDialogue = 80110111,
          Subtitle = "(This outcome is predictable. You shook your head and dismissed the risky idea to keep fishing out intel from her.)",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18EC"
        },
        [80110111] = {
          ContentKR = "오해한 것 같아. 그냥 너한테 한잔 대접하고 싶어서야.",
          DialogueId = 80110111,
          GUID = "C88C1916",
          NextDialogue = 80110112,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You've got it wrong. I just saw you and thought I'd invite you for a drink.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1916"
        },
        [80110112] = {
          ContentKR = "......",
          DialogueId = 80110112,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1940",
          NextDialogue = 80110113,
          SpeakNpcId = 93101,
          Subtitle = "......",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1940"
        },
        [80110113] = {
          ContentKR = "내가 너무 예민했나 보네. 음, 크흠, 미안해 {性别:임마|아가씨}.",
          DialogueId = 80110113,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C196A",
          NextDialogue = 80110114,
          SpeakNpcId = 93101,
          Subtitle = "Guess I was too on edge. Ahem, sorry about that.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C196A"
        },
        [80110114] = {
          ContentKR = "예전에 내가 이 일을 했었다는 걸 알고 그걸 핑계로 말 걸면서 군단의 비밀을 캐내려는 뻔뻔한 월석 사냥꾼들도 있었거든.",
          DialogueId = 80110114,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1994",
          NextOptions = {
            [1] = 801101141,
            [2] = 801101142
          },
          SpeakNpcId = 93101,
          Subtitle = "It's just there have been some audacious Phoxhunters who, seeing that I was one of them, tried to get close to me and fish for the secrets of the legion.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1994"
        },
        [80110115] = {
          ContentKR = "맞아, 꽤 오래전 일이지만. 아, 이런 말해도 괜찮으려나?",
          DialogueId = 80110115,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C19BE",
          NextDialogue = 80110116,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, that was years ago. Wait, should I reveal this to others?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19BE"
        },
        [80110116] = {
          ContentKR = "...뭐, 군단에 과거 신분을 숨기라는 규정은 없으니까.",
          DialogueId = 80110116,
          GUID = "C88C19E8",
          NextOptions = {
            [1] = 801101161
          },
          SpeakNpcId = 93101,
          Subtitle = "...Never mind. The Legion doesn't say we have to hide who we were.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19E8"
        },
        [80110117] = {
          ContentKR = "하, 넌 군단이 어떤 곳인지 몰라.",
          DialogueId = 80110117,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C1A12",
          NextDialogue = 80110118,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, you have no idea what it's like in the Legion.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A12"
        },
        [80110118] = {
          ContentKR = "군단 담장엔 닿기만 해도 통구이가 되는 폭시코르 전기망이 있어. 탈영병이든, 도둑이나 스파이라고 해도 닿기만 하면 끝장이지.",
          DialogueId = 80110118,
          GUID = "C88C1A3C",
          NextDialogue = 80110119,
          SpeakNpcId = 93101,
          Subtitle = "Legion camps are surrounded by electric fences powered by Phoxichor. They crackle with sparks, detering deserters, as well as discouraging thieves and spies.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A3C"
        },
        [80110119] = {
          ContentKR = "근데 그건 눈에 보이는 전기망이라 그나마 피하기 쉽지. 군단엔 보이지 않는 전기망도 있어. 실수로 잘못된 일을 하거나 말을 잘못하면, 어느 순간 '팍' 하고 죽어버릴 수도 있다고.",
          DialogueId = 80110119,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1A66",
          NextDialogue = 80110120,
          SpeakNpcId = 93101,
          Subtitle = "But at least you can see those fences. It's the invisible ones you have to worry about — if you slip up, say the wrong thing, one zap, and you're gone.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A66"
        },
        [80110120] = {
          ContentKR = "특히 내 상관은 배신자를 제일 싫어하지. 괜히 정보를 누설해서 죽기는 싫거든.",
          DialogueId = 80110120,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1A90",
          NextOptions = {
            [1] = 801101201,
            [2] = 801101202
          },
          SpeakNpcId = 93101,
          Subtitle = "My supreme officer has something personal against traitors. I don't want to end up dead over some accidental leak.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A90"
        },
        [80110121] = {
          ContentKR = "헛소리 하고 있네. 내가 원해서 들어온 게 아니라고.",
          DialogueId = 80110121,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1ABA",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          Subtitle = "You think? I never wanted to be in the Legion.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1ABA"
        },
        [80110122] = {
          ContentKR = "멋지다고? 널 멋지게 만들어놓고 언제라도 총에 맞을지도 모르는 상태로 일하라고 하면 좋을 것 같아?",
          DialogueId = 80110122,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1AE4",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          Subtitle = "Status and prestige? Sure, if you think risking your neck daily is worth it.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1AE4"
        },
        [80110123] = {
          ContentKR = "...차라리 예전에 월석 사냥꾼으로 일할 때가 나았어. 몸은 편하진 않았어도 그래도 자유라는 게 있었으니까.",
          DialogueId = 80110123,
          GUID = "C88C1B0E",
          NextDialogue = 80110124,
          SpeakNpcId = 93101,
          Subtitle = "...I was happier as a Phoxhunter. It wasn't an easy gig, but at least I was free.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B0E"
        },
        [80110124] = {
          ContentKR = "모든 의뢰가 목숨을 걸어야 할 정도는 아니었어. 가끔은 개 산책시키기, 사슴 사냥하기 같은 좋은 일거리도 있었고, 큰 일 치르고 나면 '아스포델'에 가서 술 한잔 하며 속을 달랠 수도 있었지.",
          DialogueId = 80110124,
          GUID = "C88C1B38",
          NextDialogue = 80110125,
          SpeakNpcId = 93101,
          Subtitle = "Not all commissions were about cheating death. Sometimes you'd get to walk dogs or hunt deer. And after a big score, you could enjoy a pint at The Asphodel.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B38"
        },
        [80110125] = {
          ContentKR = "혼자 일할 수 있었다고. 누구랑 팀 짜지 않아도 되고, 내 계획을 남들에게 설명할 필요도 없고, 임무 수행하면서 쓸모없는 짐덩이들 신경 쓸 필요도 없었어.",
          DialogueId = 80110125,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1B62",
          NextDialogue = 80110126,
          SpeakNpcId = 93101,
          Subtitle = "You can do it on your own. No need to explain to anyone about your plans or worry about dead weight.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B62"
        },
        [80110126] = {
          ContentKR = "더 중요한 건, 참새처럼 쫑알거리는 시끄러운 상관 신경 쓸 필요가 없다는 거야.",
          DialogueId = 80110126,
          GUID = "C88C1B8C",
          NextOptions = {
            [1] = 801101261
          },
          SpeakNpcId = 93101,
          Subtitle = "Most importantly, you didn't have to deal with commanders who can't stop their yapping.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B8C"
        },
        [80110127] = {
          ContentKR = "이렇게 상관을 욕하는 것도 '잘못된 말'에 포함되는 것 아냐? '감전사' 당하는 거 아냐?",
          DialogueId = 80110127,
          GUID = "C88C1BB6",
          NextDialogue = 80110128,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "I thought bad-mouthing your superiors can be considered as something wrong. Wouldn't that get you zapped?",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BB6"
        },
        [80110128] = {
          ContentKR = "......!",
          DialogueId = 80110128,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1BE0",
          NextDialogue = 80110129,
          SpeakNpcId = 93101,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BE0"
        },
        [80110129] = {
          ContentKR = "당연하지! 난 그 귀족 출신 놈들처럼 두꺼운 가죽을 가진 게 아니라고. 아무리 감전시켜도 죽지 않는 거대 필토이드 같은 놈들이랑은 달라. 이 말이 새어나가면 감전사는 아니더라도 엄청난 꼴을 당할 거야.",
          DialogueId = 80110129,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1C0A",
          NextDialogue = 80110130,
          SpeakNpcId = 93101,
          Subtitle = "A...Absolutely! I'm no noble — those thick-skinned aristocrats can definitely survive a zap. But if my superiors heard this, they'd fry me, or worse.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C0A"
        },
        [80110130] = {
          ContentKR = "방금 말한 것들이 어디 딴 데서 내 귀에 들리는 날엔 대가리에 구멍 뚫릴 줄 알아.",
          DialogueId = 80110130,
          GUID = "C88C1C34",
          NextOptions = {
            [1] = 801101301
          },
          SpeakNpcId = 93101,
          Subtitle = "If you go around telling people what I just said, I'll put a bullet in your head. Understood?",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C34"
        },
        [80110131] = {
          ContentKR = "그런데 생각보단 좀... 의외야.",
          DialogueId = 80110131,
          GUID = "C88C1C5E",
          NextDialogue = 80110132,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Anyway, I find you quite... different.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C5E"
        },
        [80110132] = {
          ContentKR = "난 린이 휘페르보레아 장교로서 좀 더 '신념' 같은 게 있을 줄 알았거든. 뭐랄까, '명예'라든가 '충성심' 같은 거 말이야.",
          DialogueId = 80110132,
          GUID = "C88C1C88",
          NextDialogue = 80110133,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "I thought as a Hyperborean officer, you would have some... belief in the Empire. Like, talk about honour, loyalty, stuff like that...",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C88"
        },
        [80110133] = {
          ContentKR = "흥, 그런 건 밑에 있는 신병들 속일 때나 쓰는 말이고. 나는...",
          DialogueId = 80110133,
          GUID = "C88C1CB2",
          NextDialogue = 80110134,
          SpeakNpcId = 93101,
          Subtitle = "Pfft, that kind of crap might work on the noobs.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CB2"
        },
        [80110134] = {
          ContentKR = "많은 사람들이 그런 보이지도 않고 잡히지도 않는 것들을 위해 모든 걸 바치겠지만, 난 아냐. 난 나 자신이 왜 월석 사냥꾼이 됐고, 또 왜 군단에 들어갔는지 잘 알고 있어.",
          DialogueId = 80110134,
          GUID = "C88C1CDC",
          NextDialogue = 80110135,
          SpeakNpcId = 93101,
          Subtitle = "Many would sacrifice everything for those invisible and untouchable things like sense of faith, but I am not one of them. I know exactly why I became a Phoxhunter and why I joined the Legion.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CDC"
        },
        [80110135] = {
          ContentKR = "...그저 군단에 들어가면 배불리 먹을 수 있으니까, 그게 다야. 난 처음부터 그걸 잘 알고 있었지. 사실 간단해. 군단에는 내 힘이 필요하고, 난 돈이 필요했던 거고. 이건 그저 서로 필요한 걸 주고받는 거래일뿐이야.",
          DialogueId = 80110135,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1D06",
          NextDialogue = 80110136,
          SpeakNpcId = 93101,
          Subtitle = "...I just needed a job that brings food to the table. I got that figured out from the start. The Legion needs my skills and I need their paycheck. Simple exchange.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D06"
        },
        [80110136] = {
          ContentKR = "네가 말한 명예니 신념이니 하는 건 한 톨도 없어.",
          DialogueId = 80110136,
          GUID = "C88C1D30",
          NextOptions = {
            [1] = 801101361
          },
          SpeakNpcId = 93101,
          Subtitle = "All that talk of \"glory\" and \"faith\" — it's not why I'm here.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D30"
        },
        [80110137] = {
          ContentKR = "......!",
          DialogueId = 80110137,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1D5A",
          NextDialogue = 80110138,
          SpeakNpcId = 93101,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D5A"
        },
        [80110138] = {
          ContentKR = "이 * 씨*, 짜증 나. 이 망할 술을 마시지 말았어야 했어. 마시면 이것저것 지껄이게 돼.",
          DialogueId = 80110138,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1D84",
          NextDialogue = 80110139,
          SpeakNpcId = 93101,
          Subtitle = "D**n it! I knew I shouldn't have had this drink. Can't keep my mouth shut when I'm a bit tipsy.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D84"
        },
        [80110139] = {
          ContentKR = "나 간다! 방금 말한 건 아무에게도 말하지 마!",
          DialogueId = 80110139,
          GUID = "C88C1DAE",
          SpeakNpcId = 93101,
          Subtitle = "I'm done here! And don't you dare let today's conversation out!",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1DAE"
        },
        [80110201] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentKR = "...한 잔 더.",
          DialogueId = 80110201,
          GUID = "C88C27DA",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110202,
          SpeakNpcId = 93101,
          Subtitle = "...Hit me with another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          ContentKR = "있잖아, 평소에 아이스레이크 시티에서 어떻게 일거리를 구해? 역시 '아스포델'이야?",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          Subtitle = "Hey, how do you usually pick up your gigs? Still at The Asphodel?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentKR = "그건 예전이랑 하나도 안 변했네. '아스포델'이라... 좋지... 최소한 카밀라는 갑자기 살인이나 강도질 하라고 시키진 않을 테니까.",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          Subtitle = "Hmm, just like old times. The Asphodel is a neat place... At least Camilla doesn't suddenly throw in jobs where you have to kill people and rob their stuff.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          ContentKR = "하, 아이스레이크 시티가 수도에서 멀리 떨어진 변방이라고 얕봤다간 큰코다쳐. 수도보다 인재들이 더 많이 나온다니까. 특히 치안서가 관리 안 하는 외곽 지역은 더 그래. 하지만 걱정 마, 카밀라랑 일하면서 사적인 일만 따로 안 받으면 그런 의뢰는 볼일 없을 테니.",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          Subtitle = "Hah, never underestimate Icelake. It's teeming with tougher nuts than the capital, especially with the Security Bureau ignoring the outskirts. But don't worry — Camilla's gigs are clean, unless you're dabbling in the sketchy ones.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          ContentKR = "그나저나 카밀라는 어때? 지금도 무서운 호랑이 같아?",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          Subtitle = "Speaking of which, how is Camilla these days? Still got that edge?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          ContentKR = "그건 다행이네! 아, 시간 참 빨리 가네. 카밀라가 친절해졌다니, 내 상관은 지금도 호랑이 같은데 말이야.",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "That's good to hear! Ugh, time flies, even turned Camilla sweet, but it still couldn't soften up my iron-fisted supreme officer.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          ContentKR = "그래, 카밀라도 여전하구나... 아, 내 상관이랑 똑같네. 생긴건 참 예쁜데 무서운 호랑이가 따로 없다니까.",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "Okay, so Camilla hasn't changed at all... Ugh, she's just like my supreme officer — pretty but goes around acting like a pissed volcano.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          ContentKR = "이름은... 말 못 해. 말하면 군단 담장 위 전기망에 걸려 감전사할 거야.",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          Subtitle = "Her name is... Sorry, can't tell you. I'd rather not end up on the electric fence getting zapped to ashes.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          ContentKR = "그 분은 매일 얼굴을 찌푸리고 다녀. 마치 온 군단이 그 분한테 빚진 것처럼 말이야.",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          Subtitle = "She's always got this long face like the entire Legion owes her money or something.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          ContentKR = "아! 그 분은 이상한 취미가 한가득이야. 예를 들어 보통 사람은 다 총을 쓰잖아? 근데 그 분은 꼭 전기 채찍을 휘두르셔. 총보다 편하대.",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, and her quirks! Like, who doesn't use a gun these days? But she insists on using her electrified whip and claims it works better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          ContentKR = "(가슴이 갑자기 철렁 내려앉았다. 린이 말하는 사람은 내가 찾고 있던 사람, 시빌라를 떠올리게 했다.)",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          Subtitle = "(Your heart skipped a beat. Her descriptions reminded you of someone you're looking for — Sibylle.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          ContentKR = "보통 사람들은 생각할 때 조용한 걸 좋아하잖아? 그 분은 시끄러운 녹음을 틀어놓고 듣는다고. 그러면 생각이 더 잘 된다나.",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          Subtitle = "And people usually prefer peace and quiet when they have something to think about, right? Not her — she always blasts a loud recording and says it pumps her up and helps her think better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          ContentKR = "심지어 사무실에 까마귀를 몇 마리나 키우고 있어. 그 새들이 폐... 아니, 상관에게 보내는 보고서에 똥을 싸도 괜찮대?",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          Subtitle = "She even keeps crows in her office. Hasn't she ever worried about bird droppings on her reports to His M—um, her higher-ups?",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          ContentKR = "또 있어. 보통 사람들은 강가에 가면 산책하거나, 바람 쐬고, 경치 구경도 하잖아? 내 상관은 강가에 가서 낚시꾼들이 빈손으로 돌아가는 걸 보러 간대. 스트레스 받을 때 그걸 보면 풀린다나 뭐라나.",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          Subtitle = "And then there's this: normal people go to the riverside to unwind and enjoy the breeze and scenery, right? My boss? She goes there only to watch anglers come back empty-handed, says it's funny and stress-relieving.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          ContentKR = "뭐 그런 사람이 다 있어!",
          DialogueId = 80110215,
          GUID = "C88C2A26",
          NextOptions = {
            [1] = 801102151
          },
          SpeakNpcId = 93101,
          Subtitle = "I mean — who does that!?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A26"
        },
        [80110216] = {
          ContentKR = "괴짜 그 자체야. 실제로 만나면 재미없을 걸. 지금 말한 건 맨 위 상관이고, 부관도 있는데 아까 말했던 상관보다 더 미* 놈이라니까.",
          DialogueId = 80110216,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C2A50",
          NextDialogue = 80110217,
          SpeakNpcId = 93101,
          Subtitle = "She's nuts. Trust me, she's far less interesting in person. Oh, and that's just the top boss. My direct superior? Even nuttier.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A50"
        },
        [80110217] = {
          ContentKR = "말할 때 목에 힘을 잔뜩 주고 으쓱대는데, 자기가 우아한 줄 아나 봐. 근데 아무리 들어도 그냥 뒤뚱거리는 거위 같아.",
          DialogueId = 80110217,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2A7A",
          NextDialogue = 80110218,
          SpeakNpcId = 93101,
          Subtitle = "Now this dude rambles in circles and thinks he's all classy. Honestly? He sounds like a wishy-washy wet goose.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A7A"
        },
        [80110218] = {
          ContentKR = "또 맨날 고효율 에너지 절약 모드니 뭐니 떠들어대는데, 결국은 땡깡 부리고 게으름 피우려는 핑계라는 걸 모르는 사람이 없지.",
          DialogueId = 80110218,
          GUID = "C88C2AA4",
          NextDialogue = 80110219,
          SpeakNpcId = 93101,
          Subtitle = "That guy's always babbling about efficiency and energy saving. Ugh, everyone knows that he's just making excuses for his laziness.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AA4"
        },
        [80110219] = {
          ContentKR = "근데 이 자식이 똑똑하긴 한 게, 맨날 게으름 피우면서도 일은 다 해내고, 꼬투리 잡힐 일도 안 만든다니까.",
          DialogueId = 80110219,
          GUID = "C88C2ACE",
          NextDialogue = 80110220,
          SpeakNpcId = 93101,
          Subtitle = "But I'll give him this — he's sharp. Slacks off, sure, but somehow still manages to get the job done. No one can really fault him for that.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2ACE"
        },
        [80110220] = {
          ContentKR = "저번에 보니까 얼마 전에도 아주 작은 단서만 가지고 상관이 15년 동안 찾아 헤맸던 보물이 어디 있는지 알아냈다니까. 그 과정에서... 좀 꼬이긴 했지만...",
          DialogueId = 80110220,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2AF8",
          NextDialogue = 80110221,
          SpeakNpcId = 93101,
          Subtitle = "Not long ago, he cracked the location of treasure with just a few clues. That's something my supreme officer had been chasing for years. But, well, there was... a little hiccup.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AF8"
        },
        [80110221] = {
          ContentKR = "(틀림없어, 방금 말한 '보물'은... 아마도 베레니카일 거야.)",
          DialogueId = 80110221,
          GUID = "C88C2B22",
          NextOptions = {
            [1] = 801102211
          },
          Subtitle = "(If I guessed correctly, the \"treasure\" that Lynn mentioned could very well be Berry.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B22"
        },
        [80110222] = {
          ContentKR = "나한테 묻지 마... 그 둘이 찾으러 갔어. 기밀이라 나도 몰라.",
          DialogueId = 80110222,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2B4C",
          NextDialogue = 80110223,
          SpeakNpcId = 93101,
          Subtitle = "Don't ask me... The two of them handled that mission together. It's all top secret — how would I know?",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B4C"
        },
        [80110223] = {
          ContentKR = "......",
          DialogueId = 80110223,
          GUID = "C88C2B76",
          NextDialogue = 80110224,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "......",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B76"
        },
        [80110224] = {
          ContentKR = "이런, 오늘 정말 말하면 안 될 것들을 너무 많이 말해버린 것 같아... 아, 다 이 망할 술 때문이야! 설마 술에 진실의 약이라도 탔어?",
          DialogueId = 80110224,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C2BA0",
          NextDialogue = 80110225,
          SpeakNpcId = 93101,
          Subtitle = "Crap. I really said a load of stuff I shouldn't be saying at all... It must be this lousy booze! You didn't spike it with a truth serum or something, did you?",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BA0"
        },
        [80110225] = {
          ContentKR = "가자, 가. 하... 다행히 디즈마니아에선 술을 안 마셨지. 안 그랬으면 어느 날 갑자기 상관 채찍에 감전사 당했을 지도... 아니, 이건 더 말하면 안 돼...",
          DialogueId = 80110225,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2BCA",
          SpeakNpcId = 93101,
          Subtitle = "Sheesh. I'm outta here. Ugh — thank goodness I don't drink in Dismania, or I'd end up zapped by my superior's whip... Argh, better stop talking now...",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BCA"
        },
        [80110226] = {
          Camera = "164.130432,-127.039795,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "넌 말 안 할 거라 믿어.",
          DialogueId = 80110226,
          FinalCamera = "164.130432,-118.0,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C88C2BF4",
          LookAt = {
            [1] = "790014:n(790008)"
          },
          NextDialogue = 80110227,
          SpeakNpcId = 790014,
          Subtitle = "And I trust you won't go blabbing about what I said.",
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "790008:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BF4"
        },
        [80110227] = {
          Camera = "13.894012,-267.815552,157.042679,0.00001,-2.999996,96.801392,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "마치 내가 네가 이번에 일부러 독한 술을 골랐다는 걸, 뭔가 의도를 갖고 나한테서 정보를 끌어내려 했다는 걸 알고 있지만 모른 척할 수 있는 것처럼 말이야.",
          DialogueId = 80110227,
          GUID = "C88C2C1E",
          NextDialogue = 80110228,
          SpeakNpcId = 790014,
          Subtitle = "I know exactly why you chose that extra-strong drink. You had your own reasons for coaxing intel from me — but I chose to act the fool and play along.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C1E"
        },
        [80110228] = {
          Camera = "13.276428,-53.140625,124.735672,0.000025,0.0,86.600571,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "여기서 그만하자. 더 이상 시험하지 마. 난 군단과 맞서는 일은 할 수 없어. 나라고 목숨을 걸 수는 없는 일이니까, 그렇지?",
          DialogueId = 80110228,
          FinalCamera = "13.276428,-68.0,124.735672,0.000025,0.0,86.600571,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C88C2C48",
          LookAt = {
            [1] = "790014:n(790014)"
          },
          NextDialogue = 80110229,
          SpeakNpcId = 790014,
          Subtitle = "Let's stop here. Don't push any further. I can't cross the Legion — everyone's gotta live, right?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C48"
        },
        [80110229] = {
          Camera = "14.200928,-236.600464,163.609055,-0.0,-7.599944,97.395355,35.0,180.0,false,Manual,2.8",
          ContentKR = "게다가, 나도... 적어도 진심을 좀 털어놓을 수 있는 사람을 잃고 싶지 않아.",
          DialogueId = 80110229,
          FinalCamera = "12.948349,-226.679688,163.609055,0.000001,-7.599944,97.195381,35.0,130.0,false,Manual,2.8",
          GUID = "C88C2C72",
          NextDialogue = 80110230,
          SpeakNpcId = 790014,
          Subtitle = "And I don't want to... lose someone that I can actually talk to.",
          TalkActionId = {
            [1] = "790014:Disagree",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C72"
        },
        [80110230] = {
          ContentKR = "됐어, 간다!",
          DialogueId = 80110230,
          GUID = "C88C2C9C",
          IsBlack = 1,
          SpeakNpcId = 790014,
          Subtitle = "Alright, that's it. I'm off!",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C9C"
        },
        [80110301] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentKR = "있잖아, 부탁 좀 들어줄래? 보수는 줄테니까.",
          DialogueId = 80110301,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3842",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110302,
          SpeakNpcId = 93101,
          Subtitle = "Hey, do me a favor. I'll pay you.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3842"
        },
        [80110302] = {
          ContentKR = "난 내일 수도로 돌아가야 해. 여기 소포가 하나 있는데, 외곽 서구 오크 가 48번지에 사는 리오라 베커라는 여자한테 전해줄 수 있어?",
          DialogueId = 80110302,
          GUID = "C88C386C",
          NextOptions = {
            [1] = 801103021
          },
          SpeakNpcId = 93101,
          Subtitle = "I'm off to the capital tomorrow and I've got a package here that needs to be delivered to No. 48, Oak Street in the west suburbs. It's for a lady named Riola Baker.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C386C"
        },
        [80110303] = {
          ContentKR = "왜 이렇게 캐물어?",
          DialogueId = 80110303,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3896",
          NextOptions = {
            [1] = 801103031,
            [2] = 801103032
          },
          SpeakNpcId = 93101,
          Subtitle = "You're asking too many questions.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3896"
        },
        [80110304] = {
          ContentKR = "그래, 일리는 있네. 그럼 말해줄게. 안에는 총 한 자루랑 가면 하나가 들어있어.",
          DialogueId = 80110304,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C38C0",
          NextDialogue = 80110305,
          SpeakNpcId = 93101,
          Subtitle = "Fair point. Alright, I'll spill it. There's a gun and a mask in there.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38C0"
        },
        [80110305] = {
          ContentKR = "그렇게 긴장하지 마, 장난감 총이야. 믿기지 않으면 날 쏴봐.",
          DialogueId = 80110305,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C38EA",
          NextOptions = {
            [1] = 801103051
          },
          SpeakNpcId = 93101,
          Subtitle = "Don't be nervous. It's just a toy gun. If you don't believe me, feel free to test it on me.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38EA"
        },
        [80110306] = {
          ContentKR = "(탕—)",
          DialogueId = 80110306,
          GUID = "C88C3914",
          NextDialogue = 80110307,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          Subtitle = "(BANG—)",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3914"
        },
        [80110307] = {
          ContentKR = "아야야, 아파! 가짜 총알이라도 아프다고, 이마에 쏘지 마! 이리 와봐, 내가 네 대가리 한 번 때려줄 테니까! 씨*, 왜 이렇게 세게 쏘냐.",
          DialogueId = 80110307,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C393E",
          NextDialogue = 80110308,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          SpeakNpcId = 93101,
          Subtitle = "Ow! Fake bullets hurt too! And why aim at the head!? Get over here, I'm gonna give you a thrashing! D**n, that friggin' hurt.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C393E"
        },
        [80110308] = {
          ContentKR = "하, 네가 이러니까 생각나네. 어렸을 때 나랑 리오라가 싸울 때도 새총으로 서로 머리 겨냥해서 쏘고 그랬어. 지금 생각해보면 안 죽은 게 다행이지. 이 총이... 바로 리오라한테 주는 거야.",
          DialogueId = 80110308,
          GUID = "C88C3968",
          NextOptions = {
            [1] = 801103081
          },
          SpeakNpcId = 93101,
          Subtitle = "*sigh* You know what, this reminds me of the fights I used to have with Riola when we were little. We'd use slingshots to hit each other in the head. Lucky I'm still alive, huh? Anyway, this gun... is my present for her.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3968"
        },
        [80110309] = {
          ContentKR = "음, 그렇다고 볼 수 있지... 이번에 임무로 아이스레이크 시티에 오게 됐으니까, 뭔가 가져가야겠다고 생각했어.",
          DialogueId = 80110309,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3992",
          NextDialogue = 80110310,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, sort of... Had to come to Icelake for a mission, figured I might as well bring something.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3992"
        },
        [80110310] = {
          ContentKR = "이것저것 물어보느라 시간만 보내네, 결국 할 거야 말 거야? 안 할거면 다른 월석 사냥꾼을 찾아볼게.",
          DialogueId = 80110310,
          GUID = "C88C39BC",
          NextOptions = {
            [1] = 801103101
          },
          SpeakNpcId = 93101,
          Subtitle = "And you've had way too many questions. Look, are you in or out? There's no shortage of Phoxhunters for the job, you know.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39BC"
        },
        [80110311] = {
          ContentKR = "내가 가? 됐어. 상관이 보내지 않았다면 난 아이스레이크 시티 같은 곳엔 절대 안 왔을 거야.",
          DialogueId = 80110311,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C39E6",
          NextOptions = {
            [1] = 801103111,
            [2] = 801103112
          },
          SpeakNpcId = 93101,
          Subtitle = "Deliver it myself? Forget it. If it weren't for orders from the top, I wouldn't bother coming back to Icelake.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39E6"
        },
        [80110312] = {
          ContentKR = "흥, 비꼬지 마.",
          DialogueId = 80110312,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3A10",
          NextDialogue = 80110313,
          SpeakNpcId = 93101,
          Subtitle = "Tsk, cut it out.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A10"
        },
        [80110313] = {
          ContentKR = "전에도 한 번 와봤어. 어렸을 때 같이 새 둥지 뒤지고 감자 훔치던 친구들이랑 술 한잔 하면서 옛날 얘기나 할까 했지. 그냥 그때 바보 같았던 일들 얘기하면서 잠깐이라도 군단에서 벗어나고 싶었어.",
          DialogueId = 80110313,
          GUID = "C88C3A3A",
          NextDialogue = 80110314,
          SpeakNpcId = 93101,
          Subtitle = "I did come back here before and had plans to catch up with the old gang. We used to climb trees and swipe veg together as kids. I wanted to chat with them, laugh about those silly pranks over a pint or two, and forget about life in the Legion for a while.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A3A"
        },
        [80110314] = {
          ContentKR = "근데 어떻게 됐게? 그 녀석들이 어디서 내가 온다는 걸 들었는지 미리 줄까지 서 있더라고. 내가 오니까 멀리서 경례하면서 다 같이 \"린 님\"하고 부르는데 지붕 위의 새들까지 놀라서 날아가더라.",
          DialogueId = 80110314,
          GUID = "C88C3A64",
          NextDialogue = 80110315,
          SpeakNpcId = 93101,
          Subtitle = "But word got out I was coming. They all lined up, saluted from a distance, yelling \"Officer Lynn\" so loud it scared the birds off the roofs.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A64"
        },
        [80110315] = {
          ContentKR = "사실 지금은 서로 좀 어색해졌더라도 예전에 거리에서 뛰어놀던 얘기라도 하면 다시 가까워질 줄 알았는데.",
          DialogueId = 80110315,
          GUID = "C88C3A8E",
          NextDialogue = 80110316,
          SpeakNpcId = 93101,
          Subtitle = "I thought I'd let them do their thing. Get it out of their system. Then we'd all loosen up a bit reminiscing about tearing down the streets as kids.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A8E"
        },
        [80110316] = {
          ContentKR = "근데 그 친구들이 내가 그런 말 할 기회조차 주지 않더라고. 허리 굽혀 인사하느라 머리가 발끝에 닿을 것 같았어. 나랑 눈도 제대로 마주치지 않더라.",
          DialogueId = 80110316,
          GUID = "C88C3AB8",
          NextOptions = {
            [1] = 801103161
          },
          SpeakNpcId = 93101,
          Subtitle = "But the old gang never gave me the chance. Everyone was too busy saluting, bowing like they owed me something. Couldn't even look me in the eye.",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AB8"
        },
        [80110317] = {
          ContentKR = "당연히 정상이지. 어렸을 때부터 이런 거 많이 봐왔거든. 그들이 왜 나를 무서워하는지 너무 잘 알지. 내가 이 일을 하지 않았다면 나부터도 군인만 봐도 덜덜 떨고 있었을 거야.",
          DialogueId = 80110317,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3AE2",
          NextDialogue = 80110318,
          SpeakNpcId = 93101,
          Subtitle = "Of course it's normal. I've seen my fair share of things to know why they're so afraid of me. If it weren't for my joining the Legion, I'd be the one who trembles at the sight of soldiers.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AE2"
        },
        [80110318] = {
          ContentKR = "아이스레이크 시티... 아니, 휘페르보레아는 늘 그래왔어. 힘 있는 자가 약한 자를 괴롭히고, 부자가 가난한 자를 짓밟고... 내가 어렸을 때부터 그랬고, 지금도 변한 게 없어.",
          DialogueId = 80110318,
          GUID = "C88C3B0C",
          NextDialogue = 80110319,
          SpeakNpcId = 93101,
          Subtitle = "Icelake... No, it's the same for the whole of Hyperborea — the strong and rich walk all over the weak and poor... This has always been the way since I was a little girl. Nothing's changed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B0C"
        },
        [80110319] = {
          ContentKR = "있잖아, 이 총이랑 가면이 뭐에 쓰이는지 알아?",
          DialogueId = 80110319,
          GUID = "C88C3B36",
          NextDialogue = 80110320,
          SpeakNpcId = 93101,
          Subtitle = "Anyway, do you know what the gun and mask are for?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B36"
        },
        [80110320] = {
          ContentKR = "내가 어렸을 때 리오라랑 같이 만화책을 봤는데, '루팡'이란 의적 얘기였어. 루팡은 나쁜 부자들 집에서 보물을 훔쳐다 가난한 사람들한테 나눠줬지. 사람들은 그를 '가면의 영웅'이라고 불렀어.",
          DialogueId = 80110320,
          GUID = "C88C3B60",
          NextDialogue = 80110321,
          SpeakNpcId = 93101,
          Subtitle = "When we were kids, Riola and I were obsessed with this comic about Leblanc, a rogue who'd steal from wicked rich folks and give to the poor. They called him the \"Masked Hero.\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B60"
        },
        [80110321] = {
          ContentKR = "그때 우리는 폐지로 가면을 만들어 쓰고 새총을 총처럼 들고 아이스레이크 시티 성벽 위로 올라가서 루팡이 만화에서 하던 말을 큰 소리로 외쳤어. 전혀 부끄럽지 않았지.",
          DialogueId = 80110321,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3B8A",
          NextDialogue = 80110322,
          SpeakNpcId = 93101,
          Subtitle = "We made masks from scrap cardboard and used slingshots as our guns. We'd climb the town walls of Icelake, shouting Leblanc's lines from the comics. Silly, I know, but we didn't feel a bit embarrassed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B8A"
        },
        [80110322] = {
          ContentKR = "그때는 우리 둘 다... 언젠가는... 우리도 '영웅'이 될 수 있을 거라고 생각했거든.",
          DialogueId = 80110322,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3BB4",
          NextDialogue = 80110323,
          SpeakNpcId = 93101,
          Subtitle = "Those were the days when we felt we could... well... eventually become heroes ourselves.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BB4"
        },
        [80110323] = {
          ContentKR = "여러 해가 지나고 디즈마니아의 어떤 가게에서 더 정교한 루팡 가면이랑 장난감 권총을 봤어. 진짜 같더라고. 그래서 돈 주고 샀지.",
          DialogueId = 80110323,
          GUID = "C88C3BDE",
          NextDialogue = 80110324,
          SpeakNpcId = 93101,
          Subtitle = "Years later, I spotted a beautifully crafted Leblanc mask and toy gun in a Dismania store. I couldn't resist, so I bought them.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BDE"
        },
        [80110324] = {
          ContentKR = "\"내가 이제 카론에게만 총 쏘는 나쁜 놈이 됐어도 적어도 리오라는 아직 '영웅'이 될 기회가 있겠지\"... 그때는 그렇게 생각했어.",
          DialogueId = 80110324,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3C08",
          NextDialogue = 80110325,
          SpeakNpcId = 93101,
          Subtitle = "Back then, I thought, \"I might have turned into a Charon-killing baddie, but at least Riola could still be a hero...\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C08"
        },
        [80110325] = {
          ContentKR = "...그런데 리오라가 아이스레이크 시티에서 날 봤을 때 겁에 질린 거위처럼 떨더라고. 날 부를 때도 '린'이 아니라 '린 님'이라고 하더라. 그때 알았지, 리오라도 나처럼 돌아갈 수 없게 됐다는 걸.",
          DialogueId = 80110325,
          GUID = "C88C3C32",
          NextDialogue = 80110326,
          SpeakNpcId = 93101,
          Subtitle = "The last time I saw her in Icelake, she trembled like a scared goose and called me \"Officer Lynn.\" That's when I knew, we'd both changed. There's no going back to the good old days.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C32"
        },
        [80110326] = {
          ContentKR = "...아, 머리 아파. 한 잔 더!",
          DialogueId = 80110326,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3C5C",
          NextDialogue = 80110327,
          SpeakNpcId = 93101,
          Subtitle = "...Ugh, my head's hurting. Hit me with another!",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C5C"
        },
        [80110327] = {
          ContentKR = "이런 쓰레기 같은 일들 때문에 아이스레이크 시티에 돌아가고 싶지 않아. 심지어 친동생들조차 보고 싶지 않더라. 멀리서 한 번 봐서 살아있다는 것, 키가 좀 컸다는 것, 그럭저럭 잘 살고 있다는 걸 아는 것만으로도 충분해.",
          DialogueId = 80110327,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3C86",
          NextOptions = {
            [1] = 801103271
          },
          SpeakNpcId = 93101,
          Subtitle = "These are the reasons why I avoid being back at Icelake. I don't even want to meet my own siblings. Just seeing them from afar, knowing they're alive and well, that's enough for me.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C86"
        },
        [80110328] = {
          ContentKR = "아니, 오히려 반대야. 그들은 항상 편지에 날 보고 싶어 하고 자주 와달라고 쓰지.",
          DialogueId = 80110328,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C3CB0",
          NextDialogue = 80110329,
          SpeakNpcId = 93101,
          Subtitle = "No, quite the opposite. They write all the time, saying how much they miss me and wish I'd visit.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CB0"
        },
        [80110329] = {
          ContentKR = "하지만 가족을 보러 가도 내가 뭘 말할 수 있겠어? 연금원에서 어떤 실험을 봤다고? 아니면 또 카론을 몇 명 잡아왔다고?",
          DialogueId = 80110329,
          GUID = "C88C3CDA",
          NextDialogue = 80110330,
          SpeakNpcId = 93101,
          Subtitle = "But what could I tell them? About the latest horrors I've seen at the Academy? Or how many Charon prisoners I took?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CDA"
        },
        [80110330] = {
          ContentKR = "...에잇, 됐어. 누구나 다 고민거리는 있는 법이지. 이건 너무나 당연한 거야.",
          DialogueId = 80110330,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3D04",
          NextOptions = {
            [1] = 801103301
          },
          SpeakNpcId = 93101,
          Subtitle = "...Forget it. Everyone's got their own burdens. It's all so damn normal these days.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D04"
        },
        [80110331] = {
          ContentKR = "이건 네가 집에 가고 싶을 때 갈 수 있는 세상이어야 해... 아니, 우리 세대가 그런 세상을 만들어야 한다고 봐.",
          DialogueId = 80110331,
          GUID = "C88C3D2E",
          NextDialogue = 80110332,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "This should be a world where you can return home whenever you want... Perhaps our generation should try to make it one.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D2E"
        },
        [80110332] = {
          ContentKR = "너 같은 외부인만 이런 게 비정상이라고 생각하고, 바뀔 수 있다고 여기는 거야.",
          DialogueId = 80110332,
          GUID = "C88C3D58",
          NextDialogue = 80110333,
          SpeakNpcId = 93101,
          Subtitle = "Only outsiders like you would think this is weird and believe this can change.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D58"
        },
        [80110333] = {
          ContentKR = "혹시 너는 언젠가 카론과 솔라가 우호적으로 지내고, 이상한 뿔이나 척추, 이상한 마법 때문에 차별받지 않을 거라고 생각하나 봐?",
          DialogueId = 80110333,
          GUID = "C88C3D82",
          NextDialogue = 80110334,
          SpeakNpcId = 93101,
          Subtitle = "Perhaps you also believe a day will come when Charons and Solas can live together in peace, and that people won't be judged for their strange-looking horns and spines, and the weird magic in their veins.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D82"
        },
        [80110334] = {
          ContentKR = "그럴지도 모르지.",
          DialogueId = 80110334,
          GUID = "C88C3DAC",
          NextDialogue = 80110335,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "That could happen.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DAC"
        },
        [80110335] = {
          ContentKR = "게다가, 네가 아이스레이크 시티에 눈이 안 오게 할 순 없어도, 눈을 치우고 눈사람을 만드는 건 할 수 있잖아.",
          DialogueId = 80110335,
          GUID = "C88C3DD6",
          NextDialogue = 80110336,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Even if you can't stop the snow in Icelake, you can at least shovel it away and make snowmen out of it, right?",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DD6"
        },
        [80110336] = {
          ContentKR = "적어도, 네 친구에게 가서 옛날의 꿈을 아직도 기억하고 있다고 말할 수 있어. 그 꿈이 깨져버렸더라도 말이야. 가족들에게 가서 네가 어떤 위치에 있든 그들을 항상 생각하고 있다고, 그건 절대 변하지 않을 거라고 말해줄 수 있잖아.",
          DialogueId = 80110336,
          GUID = "C88C3E00",
          NextDialogue = 80110337,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You can at least go to your friend and tell her you remember your childhood dreams, even if they're broken now. You should be able to knock on the door of your family home and tell your folks that you'll always miss them no matter who you've become. That part of you never changes.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E00"
        },
        [80110337] = {
          ContentKR = "...하하, 솔직히 말하면 난 네 생각이 정말 마음에 들어. 아직도 좀 비현실적이라고 생각하긴 하지만, \"세상은 원래 그런 거야, 아무도 바꿀 수 없어\"라는 쓰레기 같은 말보다는 훨씬 낫네.",
          DialogueId = 80110337,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E2A",
          NextDialogue = 80110338,
          SpeakNpcId = 93101,
          Subtitle = "...Hah. To be honest, I like your way of thinking, even if it's a bit naive for my taste. It's way better than the usual crap like \"Oh, that's the way it is, nobody can change the world.\"",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E2A"
        },
        [80110338] = {
          ContentKR = "적어도 네 말을 들으니까 이 아이스레이크 시티의 바람이 좀 따뜻해진 것 같아. 음... 한 잔 더 줘.",
          DialogueId = 80110338,
          FacialId = {
            [1] = "93101:Happy02"
          },
          GUID = "C88C3E54",
          NextDialogue = 80110339,
          SpeakNpcId = 93101,
          Subtitle = "And your words actually made this Icelake breeze a bit warmer, I must say. Hmm... Pour me another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E54"
        },
        [80110339] = {
          ContentKR = "네가 어디까지 갈 수 있는지 보여줘. 네가 세상을 바꾸겠다는 그런 헛된 꿈을 꾸고 있다면, 난 지켜보고 있을게. 이 세상이 순진한 놈 하나 때문에 조금이라도 달라질 수 있는지 말이야.",
          DialogueId = 80110339,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E7E",
          NextDialogue = 80110340,
          SpeakNpcId = 93101,
          Subtitle = "Let's see how far you can take this dream of changing the world. I'm curious if a naive fool can actually make a difference, even a little.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E7E"
        },
        [80110340] = {
          ContentKR = "도움이 필요하면 한가할 때 날 찾아. 물론, 군단과 맞서는 일은 빼고. 하지만 오늘은 안 돼. 방금 마음이 바뀌었거든. 이따 다른 일이 있어.",
          DialogueId = 80110340,
          GUID = "C88C3EA8",
          NextDialogue = 80110341,
          SpeakNpcId = 93101,
          Subtitle = "And if you ever need help, and I'm free, just ask — as long as it's nothing against the Legion. But not today — I've just changed my mind about something and will be busy later.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3EA8"
        },
        [80110341] = {
          ContentKR = "네게 부탁한 일은 취소야. 가면이랑 장난감 총 돌려줘.",
          DialogueId = 80110341,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3ED2",
          SpeakNpcId = 93101,
          Subtitle = "I'm cancelling the commission. Now, gimme back my mask and gun.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3ED2"
        },
        [80120000] = {
          ContentKR = "아, 너무 좋다. 편한 의자에 맛있는 음료랑 간식, 따뜻한 벽난로에 {nickname}까지... 이러다 완전 게을러질 것 같아.",
          DialogueId = 80120000,
          GUID = "C8926F80",
          Subtitle = "Ahh, this is the life — a comfy chair, a drink, some snacks, a warm fireplace, and your company. All nice and cosy..."
        },
        [80120100] = {
          Camera = "254.617188,-63.0,110.607666,0.0,0.0,155.600769,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이 집 가구들은 다 내가 30년 전에 황성 디즈마니아에서 가져온 거야. 얼마나 귀한 재료로 정교하게 만들어졌는지, 너희들은 상상도 못할 거다.",
          DialogueId = 80120100,
          FinalCamera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8927FE8",
          NextDialogue = 80120101,
          SpeakNpcId = 790018,
          Subtitle = "The pieces of furniture inside? I brought them from the Imperial capital of Dismania thirty years ago. The rarity of the materials and the craftsmanship are beyond your wildest dreams.",
          TalkActionId = {
            [1] = "790018:Explain01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8927FE8"
        },
        [80120101] = {
          Camera = "-270.549316,-21.425171,153.719727,0.000001,-9.200162,19.797686,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그렇게 귀중한 물건들을 저희한테 맡기셔도 될까요? 저희가 워낙 작은 업체라서요. 혹시 중간에 마음이 바뀌시기라도 하면...",
          DialogueId = 80120101,
          FacialId = {
            [1] = "790019:Iyada01"
          },
          GUID = "C8928012",
          NextDialogue = 80120102,
          SpeakNpcId = 790019,
          Subtitle = "Um, are you sure you want me to handle these valuable items, sir? If you change your mind all of a sudden, there's no way for a scavenger like me to...",
          TalkActionId = {
            [1] = "790019:Explain02_Start",
            [2] = "790018:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928012"
        },
        [80120102] = {
          Camera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "벌써 몇 번이나 같은 질문을 하는 거냐. 내 대답도 여러 번 했지 않나. 이 가구들, 너희한테 맡긴다고. 내가 진짜 아끼는 보물은 수년간 모아온 악보들이고, 그건 이미 안전한 곳에 뒀으니까.",
          DialogueId = 80120102,
          GUID = "C892803C",
          NextDialogue = 80120103,
          SpeakNpcId = 790018,
          Subtitle = "You've already asked multiple times, and my answer remains: yes, these pieces are yours to handle. My true treasures are my music scores, and they have been well secured where they belong.",
          TalkActionId = {
            [1] = "790019:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892803C"
        },
        [80120103] = {
          Camera = "-91.792969,-17.010254,119.101807,0.000001,-2.600096,26.798737,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래도요... 혹시 모르니까 한 번만 더 여쭤볼게요. 서재에 종이들이 잔뜩 흩어져 있던데, 모아보니 이만큼이나 되더라고요! 보니까 악보 같던데...",
          DialogueId = 80120103,
          GUID = "C8928066",
          NextDialogue = 80120104,
          SpeakNpcId = 790019,
          Subtitle = "Well then, just to double-check before we start: about this huge pile of sheets — I collected them from the study. They look like music scores too...",
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928066"
        },
        [80120104] = {
          Camera = "188.380859,5.304199,118.568604,0.000005,0.0,165.387512,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "다 태워버려.",
          DialogueId = 80120104,
          GUID = "C8928090",
          NextDialogue = 80120105,
          SpeakNpcId = 790018,
          Subtitle = "Just burn them.",
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928090"
        },
        [80120105] = {
          Camera = "-194.875488,-9.761597,155.702393,0.000033,-32.798512,130.396423,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "전부 쓸모없는 쓰레기야. 그냥 버릴 거라고. 필요 없어. 춥다는 집 있으면 아무나 가져가서 땔감으로 쓰라고 해.",
          DialogueId = 80120105,
          FinalCamera = "-183.950195,-22.665466,181.275146,0.000027,-35.598583,129.996002,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89280BA",
          NextDialogue = 80120106,
          SpeakNpcId = 790018,
          Subtitle = "They're nothing but useless drafts, rubbish. Give them to someone struggling to stay warm to burn.",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280BA"
        },
        [80120106] = {
          Camera = "7.850098,-71.797974,9.991455,0.000032,31.599302,132.795364,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "웃기는군. 내가 정말 그게 중요하다고 생각했으면 벌써 잘 챙겼겠지. 네가 굳이 물어볼 필요도 없어.",
          DialogueId = 80120106,
          GUID = "C89280E4",
          NextDialogue = 80120107,
          SpeakNpcId = 790018,
          Subtitle = "How laughable — if they were important to me, before you waste my time with these stupid questions, don't you think I'd have properly saved them already?",
          TalkActionId = {
            [1] = "790018:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280E4"
        },
        [80120107] = {
          Camera = "-65.708008,-20.782593,149.700928,0.000017,-11.799984,31.404984,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 80120107,
          FacialId = {
            [1] = "790019:Sad01"
          },
          GUID = "C892810E",
          LookAt = {
            [1] = "790019:p(P33010101)"
          },
          NextDialogue = 80120108,
          SpeakNpcId = 790019,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C892810E"
        },
        [80120108] = {
          Camera = "10.617676,-39.324158,127.336182,0.000074,1.400339,142.991364,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(멀리서 다시 기차 소리가 들린다. 마치 이 괴팍한 음악가에게 '디즈마니아로 어서 떠나라'고 재촉하는 것만 같다.)",
          DialogueId = 80120108,
          GUID = "C8928138",
          LookAt = {
            [1] = "790018:p(P33010102)"
          },
          NextDialogue = 80120109,
          Subtitle = "The distant sound of a train whistle echoes, as if hurrying the eccentric musician on his journey back to Dismania.",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928138"
        },
        [80120109] = {
          Camera = "-272.822754,-25.003113,137.138184,0.0,-3.399993,22.39842,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이제 가봐야겠다. 다시는 보지 말자, 카론 녀석아.",
          DialogueId = 80120109,
          GUID = "C8928162",
          LookAt = {
            [1] = "790019:n(790018)"
          },
          NextDialogue = 80120110,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790018:n(790018)"}},
MoveTo{ActorId{790018},MoveSpeed{75},TargetPoint{"MovePoint_33010102"}}
}]],
          SpeakNpcId = 790018,
          Subtitle = "It's time I left. See you never, Charon.",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928162"
        },
        [80120110] = {
          Camera = "41.422852,127.761597,116.559082,0.000003,-0.200043,-76.786568,25.0,73.935852,false,Manual,2.8",
          ContentKR = "......",
          DialogueId = 80120110,
          FacialId = {
            [1] = "790019:Sad02"
          },
          FinalCamera = "36.748535,126.659424,116.559082,0.000003,-0.200043,-76.586166,25.0,235.730316,false,Manual,3.0",
          GUID = "C892818C",
          LookAt = {
            [1] = "790008:n(790019)",
            [2] = "790019:p(P33010101)"
          },
          NextOptions = {
            [1] = 801201101,
            [2] = 801201102
          },
          Scripts = "MoveTo{ActorId{790008},MoveSpeed{75},TargetPoint{\"MovePoint_33010101\"}}",
          SpeakNpcId = 790019,
          Subtitle = "...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Maer/001/C892818C"
        },
        [80120111] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentKR = "아, {nickname} 님이시군요. 잠깐만요, 1분만 기다려 주시겠어요?",
          DialogueId = 80120111,
          GUID = "C89281B6",
          NextDialogue = 80120112,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790019:n(790008)"}},
TurnTo{TurnToDescription{"790019:n(790008)"}},
PlayAnimation{ActorId{790019},AnimationId{"Agree"},Duration{1}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Oh, it's you. Excuse me for a minute!",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89281B6"
        },
        [80120112] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentKR = "(마르제가 깊게 숨을 들이쉬고 작은 목소리로 중얼거린다. 하지만 오히려 더 잘 들린다.)",
          DialogueId = 80120112,
          GUID = "C89281E0",
          NextDialogue = 80120113,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790019:n(790019)"}},
TurnTo{TurnToDescription{"790019:p(180)"}}
}]],
          Subtitle = "(Margie takes a deep breath and begins to murmur to herself under her breath, though you can still hear her, even more clearly.)",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89281E0"
        },
        [80120113] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentKR = "인생이라는 게 뭐 별거야? 그냥 커다란 쓰레기장인걸... 그러니 자꾸 쓰레기가 보이는 건 당연한 거겠지. 그래도 쓰레기는 못 움직이니까, 적당히 피하는 게 정신 건강에 낫지. 똥이 더러워서 피하지 무서워서 피하나...",
          DialogueId = 80120113,
          GUID = "C892820A",
          NextDialogue = 80120114,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Angry01_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Angry01_End"},Duration{1},_delay{2},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Life's a dump, full of junk. They can't move but I can run, to keep my life safe and sound...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C892820A"
        },
        [80120114] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentKR = "누가 소리 질러대도 별거 아니야. 그냥 개가 짖는다고 생각하면 돼. 개한테 화내봤자 내 속만 상하지. 차라리 일이나 빨리 끝내고 햇볕이라도 좀 쬐자...",
          DialogueId = 80120114,
          GUID = "C8928234",
          NextDialogue = 80120115,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Sigh_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Sigh_End"},Duration{1},_delay{2},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Don't get pissed, the jerks would win. Save your strength, unclench your fist, go soak up the sun with a grin...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928234"
        },
        [80120115] = {
          Camera = "32.413086,166.017761,96.0354,0.000066,5.199563,-79.384827,60.0,248.284149,false,Manual,5.0",
          ContentKR = "후우... 화내지 말자, 화내지 말자.",
          DialogueId = 80120115,
          GUID = "C892825E",
          NextDialogue = 80120116,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790008},AnimationId{"Explain02_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790008},AnimationId{"Explain02_End"},Duration{1},_delay{3},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Whew — Go to your happy place. Go to your happy place...",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892825E"
        },
        [80120116] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentKR = "좋아요... 이제 괜찮아요. 그냥 무시 좀 당한 것 뿐이에요. 아이스레이크 시티에서 이렇게 오래 살다 보면 다 일상이라, 이제 익숙해졌어요.",
          DialogueId = 80120116,
          FacialId = {
            [1] = "790019:Unhappy01"
          },
          GUID = "C8928288",
          NextOptions = {
            [1] = 801201161
          },
          SpeakNpcId = 790019,
          Subtitle = "All set... I'm all good now! Just some barking noise. After all these years in Icelake, I'm so used to it.",
          TurnTo = {
            [1] = "790019:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928288"
        },
        [80120117] = {
          ContentKR = "강아지요? 강아지가 어디 있는데요? 쓰다듬고 싶은데... 앗, 코르삭 씨 말씀하시는 건가요?",
          DialogueId = 80120117,
          GUID = "C89282B2",
          NextDialogue = 80120118,
          Scripts = [[
SEQ{
PlayFacial{ActorId{790019},FacialId{"Smile02"}},
PlayFacial{_delay{4},ActorId{790019},FacialId{"Shock01"}},
}]],
          SpeakNpcId = 790019,
          Subtitle = "Doggie? Where? I wanna pet it... Oh, you mean Mr Kossak.",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89282B2"
        },
        [80120118] = {
          ContentKR = "그 사람 말이에요, 황성 디즈마니아에서 온 음악가라는데 아주 유명하대요. 그 사람이 쓴 곡중에 〈율리우스 황제 찬가〉라는 게 있는데, 황제가 직접 듣고 칭찬했다나. 그래선지 매년 건국 기념주간에는 군인들이 하루 종일 그 노래를 부른다고 하더라고요.",
          DialogueId = 80120118,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89282DC",
          NextDialogue = 80120119,
          SpeakNpcId = 790019,
          Subtitle = "Well, I heard he's a famous composer from Dismania. That \"Julius Anthem\" he wrote — don't know if I got the name right — impressed even the Emperor. Those soldiers sing it every year on National Day.",
          TalkActionId = {
            [1] = "790019:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89282DC"
        },
        [80120119] = {
          Camera = "26.599121,-60.766174,127.509766,0.00013,-3.899717,69.789467,35.000008,130.711365,false,Manual,4.0",
          ContentKR = "그런데 왜 그런진 모르겠지만, 가장 화려했을 시절에 갑자기 황성에서 쫓겨나서 여기 갈레아 극장에서 낡은 징이나 치면서 30년을 보냈대요.",
          DialogueId = 80120119,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          FinalCamera = "26.599121,-60.766174,127.509766,0.00013,-3.899717,69.789467,37.0,130.711365,false,Manual,4.0",
          GUID = "C8928306",
          NextDialogue = 80120120,
          SpeakNpcId = 790019,
          Subtitle = "But for some reason, he was thrown out of the capital at the height of his fame. Ended up in Icelake, banging on that beat-up gong at Galea Theatre for thirty years.",
          TalkActionId = {
            [1] = "790019:Disagree"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928306"
        },
        [80120120] = {
          Camera = "25.643555,148.86615,117.203857,0.000134,-1.299553,-75.005913,35.0,286.089264,false,Manual,4.0",
          ContentKR = "그러다 몇 달 전에 〈휘페르보레아의 빛〉이라는 새 교향곡을 썼는데, 황성의 높으신 분들한테 인정을 받아서 돌아가게 됐다나.",
          DialogueId = 80120120,
          GUID = "C8928330",
          NextDialogue = 80120121,
          SpeakNpcId = 790019,
          Subtitle = "But I heard he recently wrote some symphonic works called \"The Glory of Hyperborea,\" and some big shots in the capital liked them enough to bring him back.",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928330"
        },
        [80120121] = {
          Camera = "13.561035,-82.322632,125.807861,0.000016,-12.60006,31.003906,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그 사람이 남긴 이 집에 가득한 물건들은 카밀라 언니한테 처리를 맡겼고, 카밀라 언니가 또 이 큰 건을 저한테 소개해 주셨거든요. 처음엔 뜻밖의 행운이라고 생각했는데, 고용주가 이런 사람일 줄이야... 정말 재수 없네요...",
          DialogueId = 80120121,
          FacialId = {
            [1] = "790019:Sad02"
          },
          FinalCamera = "3.181641,-88.561157,128.515381,0.000017,-12.60006,31.004112,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C892835A",
          NextOptions = {
            [1] = 801201211
          },
          Scripts = [[
PARA{
PlayAnimation{ActorId{790019},AnimationId{"Explain02_End"},Duration{1},_click{false}},
SEQ{
PlayAnimation{_delay{8},ActorId{790019},AnimationId{"ScratchHead_Start"},Duration{1},_click{false}},
PlayAnimation{_delay{3},ActorId{790019},AnimationId{"ScratchHead_End"},Duration{1},_click{false}},
},
SEQ{
CameraMoveTo{_delay{7.6},TargetPosition{"32.449707,-25.237549,113.582275,0.000057,3.999902,67.00164,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"33.751953,-22.16748,113.815186,0.000057,3.999902,67.001724,35.0,100000.0,false,DoNotOverride,2.8"},duration{7}},
},
}]],
          SpeakNpcId = 790019,
          Subtitle = "He turned to Camilla to deal with all the stuff he left behind, and Camilla passed the big job on to me. I thought it was a stroke of luck at first, but it turned out the client was quite the character. Tough break...",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C892835A"
        },
        [80120122] = {
          Camera = "13.058594,-189.487427,130.297607,0.000067,-5.400023,73.400612,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아요. 평소엔 여러 쓰레기통을 돌아다니면서 쓸 만한 물건을 발견하면 주워와서 필요한 분들에게 팔아요.",
          DialogueId = 80120122,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "10.127441,-188.613403,130.297607,0.000069,-5.400023,72.800484,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928384",
          NextDialogue = 80120123,
          SpeakNpcId = 790019,
          Subtitle = "Uh-huh. Normally I'm just hustling between rubbish bins trying to collect anything useful to resell.",
          TalkActionId = {
            [1] = "790019:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928384"
        },
        [80120123] = {
          Camera = "-379.716797,343.199707,394.461182,0.000096,-29.400166,-38.797962,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "근데 이렇게 많은 물건을 남겨두고 아이스레이크 시티를 뒤도 안 돌아보고 떠나는 부자는 드물거든요. 그분의 집에 남은 물건들이 말이에요, 백 개의... 아니, 좀 과장됐네요... 오십 개의 쓰레기통과 맞먹을 거예요!",
          DialogueId = 80120123,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-379.716797,343.199707,372.476074,0.000104,-27.00005,-39.19701,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89283AE",
          NextDialogue = 80120124,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{790019},AnimationId{"DisagreeHead"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_Start"},Duration{3},_delay{2},_click{false}},
PlayAnimation{_delay{3},ActorId{790019},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "It's not often you find a rich guy who leaves behind a houseful of stuff without a second thought. His leftover belongings are worth a fortune — okay, maybe not a hundred bins worth, but definitely fifty at least!",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283AE"
        },
        [80120124] = {
          Camera = "-46.604492,-258.057495,81.282959,0.000152,2.599918,66.012314,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "오래된 앤티크 가구 같은 건 목재 질이 아주 좋아서, 분해하면 침대 판자나 식탁으로 쓸 수 있어요. 재봉점 주인한테도 물어봤는데, 그 커튼이랑 테이블보, 카펫 같은 것들도 몇 번만 잘 씻으면 옷감으로 쓸 수 있대요.",
          DialogueId = 80120124,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C89283D8",
          NextDialogue = 80120125,
          SpeakNpcId = 790019,
          Subtitle = "Take those antique furniture pieces — the wood is top quality. You could turn them into beds or tables. I also checked with the tailor — those curtains, tablecloths, and rugs can be made into clothes after a few washes.",
          TalkActionId = {
            [1] = "790019:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283D8"
        },
        [80120125] = {
          Camera = "3.307129,189.679504,120.907227,0.0,-2.599973,-71.797028,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "빈민가에 잠자리도, 옷도 제대로 없는 집들이 얼마나 많은데, 이걸로 그분들 좀 도와줄 수 있고 저도 약간 벌 수 있고, 게다가 그 음악가가 말은 좀 거칠어도 주는 수고비가 적지 않거든요. 히히...",
          DialogueId = 80120125,
          GUID = "C8928402",
          NextDialogue = 80120126,
          SpeakNpcId = 790019,
          Subtitle = "A few more families in the slums will get to sleep and dress better, and I'll make a tiny fortune. Plus, even though that musician was quite mean, he was pretty generous with the pay, hehe...",
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = "790019:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928402"
        },
        [80120126] = {
          Camera = "30.832031,-69.490662,105.26709,0.000002,4.999924,73.193848,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이상하지 않아요? 방금 전까진 가슴에 불이 붙은 것처럼 화가 났는데, 지금은 순식간에 꺼져버렸어요!",
          DialogueId = 80120126,
          FacialId = {
            [1] = "790019:Happy01"
          },
          GUID = "C892842C",
          NextDialogue = 80120127,
          SpeakNpcId = 790019,
          Subtitle = "Can you believe it? I was totally upset just a moment ago, but now I'm not mad at all!",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892842C"
        },
        [80120127] = {
          Camera = "-37.370605,-328.404663,168.14209,0.000007,-11.000026,70.593628,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어쨌든, 코르삭 씨는 디즈마니아로 돌아가셨고, 빈민가 분들은 생활용품을 얻으셨고, 저야 한두 마디 욕을 먹긴 했지만 괜찮아요! 일만 시작하면 금방 잊어버릴 거예요!",
          DialogueId = 80120127,
          FacialId = {
            [1] = "790019:Smile01"
          },
          FinalCamera = "-37.370605,-328.404663,152.396973,0.000009,-9.199978,70.193542,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928456",
          NextOptions = {
            [1] = 801201271,
            [2] = 801201272
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Explain02_End"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"DisagreeHead"},Duration{3},_delay{4},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Anyway, Kossak's off to Dismania, and the folks in the slums get some good supplies. It doesn't matter that I got a little scolding — once I start to get busy, I'll forget all about it!",
          ToFinalCameraBlendTime = 11.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928456"
        },
        [80120128] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "좋아요 좋아요, 혼자서는 저 커다란 장롱 옮기는 게 좀 힘들 것 같아요. 옮기면서 마음에 드는 게 있으면 마음껏 골라요.",
          DialogueId = 80120128,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C8928480",
          SpeakNpcId = 790019,
          Subtitle = "Oh, that would be great! It's a bit of a chore hauling out his cabinets on my own. Feel free to pick anything you like while we're at it.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928480"
        },
        [80120129] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "좋아요, 제 넋두리를 들어주신 보답으로 삼죠. 자, 같이 정리해요. 마음에 드는 거 있으면 마음껏 고르고요.",
          DialogueId = 80120129,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C89284AA",
          SpeakNpcId = 790019,
          Subtitle = "Sure thing! Consider it a thank you for putting up with my grumble. Come on, help me out here. You can pick whatever catches your eye.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284AA"
        },
        [80120130] = {
          ContentKR = "(마르제와 함께 의미 있는 하루를 보냈다... 다만 집에 돌아와 잠자리에 들었을 때 팔이 많이 아팠다...)",
          DialogueId = 80120130,
          GUID = "C89284D4",
          Subtitle = "You spent a productive day with Margie... Though your arms were sore from all the lifting by bedtime...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284D4"
        },
        [80120201] = {
          Camera = "1333.655273,158.495117,593.059387,0.000084,-23.399462,-148.791443,45.0,1393.645752,false,Manual,2.8",
          ContentKR = "(마르제가 대음악가 코르삭의 남은 물건들을 맡게 되면서, 휴식처의 한 방을 임시로 사용하게 됐다. 방에서 자주 딸그락거리는 소리가 들리는데, 아마도 그녀가 계속해서 폐품을 유용한 물건으로 바꾸고 있는 것 같다.)",
          DialogueId = 80120201,
          FinalCamera = "1329.534668,166.603516,574.799133,0.000082,-22.599415,-147.989853,45.0,1393.645752,false,Manual,2.8",
          GUID = "C892907A",
          Scripts = [[
SEQ{
CameraMoveTo{TargetPosition{"-536.0,361.0,216.0,0.000089,-19.999989,-58.799721,35.0,100000.0,false,DoNotOverride,2.8"},duration{3}},
CameraMoveTo{TargetPosition{"-180.185974,-395.118164,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-180.185974,-405.0,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8"},duration{3}},
}]],
          Subtitle = "Margie has taken up a room at Sanctuary to sort through the items left behind by the famous musician Kossak. The constant clatters and clanking from the room suggest she's busy turning waste into treasure.",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892907A"
        },
        [80120202] = {
          ContentKR = "(한번 가보자...)",
          DialogueId = 80120202,
          GUID = "C89290A4",
          Subtitle = "You decide to check on her...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290A4"
        },
        [80120203] = {
          Camera = "-153.358521,286.205566,141.870239,0.000003,-7.000151,-147.997467,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어라? {nickname} 님이시군요, 어서 오세요. 마침 이상한 물건을 찾은 참이에요!",
          DialogueId = 80120203,
          FacialId = {
            [1] = "790019:Smile01"
          },
          GUID = "C89290CE",
          NextDialogue = 80120204,
          SpeakNpcId = 790019,
          Subtitle = "Oh! , it's you! Come here — I've just stumbled upon something strange!",
          TurnTo = {
            [1] = "790019:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290CE"
        },
        [80120204] = {
          Camera = "-225.281067,222.903564,116.151337,0.000004,-0.80002,-144.597412,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이건 제가 장롱을 분해하다가 발견한 나무판이에요. 뭐가 이상하냐고요? 한 번 두드려 보세요.",
          DialogueId = 80120204,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-234.476318,216.367676,116.006004,0.000004,-0.600005,-144.597412,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89290F8",
          NextOptions = {
            [1] = 801202041,
            [2] = 801202042
          },
          SpeakNpcId = 790019,
          Subtitle = "Found this wooden plank while I was taking apart a cabinet. Now, listen to how it sounds when I tap it.",
          TalkActionId = {
            [1] = "790019:Give"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290F8"
        },
        [80120205] = {
          Camera = "-284.374023,129.285156,139.56041,0.000053,-11.399346,-170.182327,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아요, 두드리면 '텅텅'거리는 걸 보니까 안에 뭔가 들어 있는 게 분명해요.",
          DialogueId = 80120205,
          FacialId = {
            [1] = "790019:Smile02"
          },
          GUID = "C8929122",
          NextDialogue = 80120207,
          SpeakNpcId = 790019,
          Subtitle = "Exactly! The sound isn't right. There's definitely something stashed inside.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929122"
        },
        [80120206] = {
          Camera = "-284.374023,129.285156,139.56041,0.000053,-11.399346,-170.182327,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "맞아요, 코르삭이 자기 가구는 뭐 어쩌고 저쩌고 하는 고급 목재라고 했어요. 하지만 중요한 건... 속이 비어 있다는 거예요.",
          DialogueId = 80120206,
          FacialId = {
            [1] = "790019:Smile02"
          },
          GUID = "C892914C",
          NextDialogue = 80120207,
          SpeakNpcId = 790019,
          Subtitle = "Oh, yeah. Kossak bragged that all his furniture was made from some fancy wood, though I can't remember the name. But what I'm trying to tell you is — it's hollow!",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892914C"
        },
        [80120207] = {
          Camera = "232.653351,361.8125,281.633331,0.000094,-18.999201,-161.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "본 '탐정'의 감각으로는, 이 나무에 뭔가 비밀이 있을 게 분명해요! 제가 쓰레기통에서 보물 찾기를 시작한 이후로, 온갖 비밀들이... 알고 싶은 것이든 아니든 저한테 찾아왔거든요.",
          DialogueId = 80120207,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C8929176",
          NextDialogue = 80120208,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Agree"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_Start"},Duration{4},_delay{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "My detective instincts are telling me this piece of wood must have a breathtaking backstory! Ever since I started treasure hunting around the city's rubbish bins, secrets keep finding their way to me, whether I want them or not.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929176"
        },
        [80120208] = {
          Camera = "-233.092163,217.391113,116.084183,0.0,-0.600005,-144.397369,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "누구 집에서 유리창 조각이 버려졌다면, 그 집에서 싸웠을 가능성이 있고요. 누구 집에서 갑자기 낡은 옷을 많이 버렸다면, 뜻밖의 돈을 벌었을 수도 있죠. 가끔은 찢어진 연애편지도 발견하고...",
          DialogueId = 80120208,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89291A0",
          NextDialogue = 80120209,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Explain01_Start"},Duration{3},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Explain01_End"},Duration{1},_click{false}},
PARA{
PlayFacial{_delay{6.5},ActorId{790008},FacialId{"Happy02"}},
LookAt{LookAtDescription{"790019:p(P33010202)"}},
}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Like, if there's broken glass in the bin, it usually means the household just had a fight. If it's a huge bunch of old clothes, then they must've come into cash all of a sudden. And don't get me started on those torn-up love letters I found...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291A0"
        },
        [80120209] = {
          Camera = "96.989166,365.946533,258.328094,0.000015,-19.39859,-156.192947,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아, 말이 샜네요. 다시 이 속이 빈 나무판 얘기로 돌아와서요. 방 안에선 잘 안 보여서 밖으로 가져왔어요. 막 열어보려던 참에 {nickname} 님이 오셨네요. 여기 안에 뭔가 숨겨져 있을 텐데...",
          DialogueId = 80120209,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "135.622986,382.351562,322.567413,0.000009,-24.598625,-156.393433,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89291CA",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120290,
          SpeakNpcId = 790019,
          Subtitle = "Anyway, back to this hollow plank. It was too dark in the room, so I brought it out here. I was just about to crack it open when you showed up. There's got to be something interesting hidden inside. Let's see...",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291CA"
        },
        [80120210] = {
          Camera = "-181.880615,263.347656,136.257751,0.000037,-5.797976,-149.392807,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "...악보네요? 그는 소중한 악보는 다 가져갔다고 했잖아요. 하지만 소중하지 않다면, 왜 굳이 숨겨뒀을까요?",
          DialogueId = 80120210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_Read_02.T_Read_02'}",
          FacialId = {
            [1] = "790019:Shock01"
          },
          GUID = "C89291F4",
          NextDialogue = 80120211,
          SpeakNpcId = 790019,
          Subtitle = "...Another music score? Kossak said he'd take all the valuable ones with him. But if this one wasn't important to him, why did he go through the trouble of hiding it so carefully?",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291F4"
        },
        [80120211] = {
          Camera = "-288.548035,170.670166,120.789764,0.000075,0.402121,-147.390503,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "도대체 뭐라고 쓴 건지 한번 볼까요... 〈악마가 쇠사슬을 끊고〉? 한 번도 들어본 적 없는 곡이에요...",
          DialogueId = 80120211,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C892921E",
          NextOptions = {
            [1] = 801202111
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{790019},AnimationId{\"Think_End\"},Duration{1},_click{false}},",
          SpeakNpcId = 790019,
          Subtitle = "Lemme see what it's about... \"Demons Broken Loose\"? Never heard of this piece before...",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892921E"
        },
        [80120212] = {
          Camera = "-409.604431,-6.535156,126.660339,0.000048,-2.997824,66.607025,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "\"안녕, 먼 미래의 코르삭. 지금 행복하니? 아니면 불행하니? 내가 곧 매우 위험한 일을 하려 한다는 걸 알려주고 싶어.",
          DialogueId = 80120212,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-407.011719,-7.655762,126.660339,0.000048,-2.997797,66.607208,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929248",
          LookAt = {
            [1] = "790019:p(P33010202)"
          },
          NextDialogue = 80120213,
          SpeakNpcId = 790019,
          Subtitle = "\"Hello there, future me. How are you? Are you happy with your life now? Just a heads up — I'm about to take a risky leap:\"",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929248"
        },
        [80120213] = {
          Camera = "-144.685608,266.765869,90.548981,0.000028,3.199581,-150.191788,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "우리나라에서 가장 사람들 눈에 띄지 않는 집단인 카론을 창작의 소재로 삼으려 해. 어때, 좋은 생각 같지 않아?",
          DialogueId = 80120213,
          FacialId = {
            [1] = "790019:Shock01"
          },
          FinalCamera = "-143.404663,264.529785,90.548981,0.000028,3.199581,-150.191788,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929272",
          LookAt = {
            [1] = "790019:p(P33010202)"
          },
          NextDialogue = 80120214,
          SpeakNpcId = 790019,
          Subtitle = "\"I'm writing a composition about our land's most overlooked community — Charons. Sounds like a great idea, doesn't it?\"",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929272"
        },
        [80120214] = {
          Camera = "117.682922,273.904541,278.035675,0.000035,-23.000122,-167.605408,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이게 발표되고 나서 어떤 일이 벌어질지 모르겠어. 최선의 경우엔 명성을 얻고, 사람들이 카론들에게 동정심을 갖게 되겠지. 하지만 더 가능성 있는 건 선배들에게 예술을 더럽혔다고 질책받는 거야.",
          DialogueId = 80120214,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "149.964203,280.998291,292.065369,0.000035,-23.000122,-167.605408,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C892929C",
          NextDialogue = 80120215,
          SpeakNpcId = 790019,
          Subtitle = "\"I don't know what will come of it after it's published. Hopefully, it'll earn me some recognition and maybe even get people to sympathize with the Charon community. But it's more likely that the old guard will scold me for 'sullying music.'\"",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892929C"
        },
        [80120215] = {
          Camera = "401.697601,87.518555,94.828476,0.000034,-2.599092,173.794434,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "어쩌면 머지않아 내가 충동적이었다고 후회할지도 몰라. 하지만 적어도 지금 이 순간만큼은, 내가 옳은 일을 하고 있다고 굳게 믿고 있어.",
          DialogueId = 80120215,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "401.697601,87.518555,124.666946,0.000034,-4.599217,173.394348,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89292C6",
          NextDialogue = 80120216,
          SpeakNpcId = 790019,
          Subtitle = "\"I might regret this decision someday, but at the moment, I believe in what I'm doing.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89292C6"
        },
        [80120216] = {
          Camera = "787.620972,-53.718506,1202.445679,0.000004,-45.999557,170.397659,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "그래서 여기에 사본을 하나 남겨두려고. 혹시라도 내가 냉대를 받고 좌절해서, 또는 고루한 선배들이 내 작품을 완전히 없애버릴 경우를 대비해서야.",
          DialogueId = 80120216,
          FinalCamera = "697.515381,213.27832,1078.197266,0.000005,-44.799149,-177.402649,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89292F0",
          NextDialogue = 80120217,
          SpeakNpcId = 790019,
          Subtitle = "\"So, I'm leaving a copy here, just in case the cold shoulder — or those old guard bigots — end up destroying my hard work.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89292F0"
        },
        [80120217] = {
          Camera = "1272.104248,1465.506348,636.589355,0.000045,-20.798307,-178.202515,60.0,1238.551392,false,Manual,2.8",
          ContentKR = "네가 이 편지를 다시 보게 될 때, 창밖에서 카론들이 이 노래를 부르는 소리가 들리길 바라. 그리고 너도 지금의 나처럼 모든 것을 웃으며 대할 수 있기를 바라.\"",
          DialogueId = 80120217,
          FinalCamera = "1271.768799,1475.04248,636.589355,0.000045,-20.598291,-178.002518,60.0,1238.551392,false,Manual,2.8",
          GUID = "C892931A",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120218,
          SpeakNpcId = 790019,
          Subtitle = "\"I really hope that by the time you read this letter, you'll hear Charons singing this song outside your window. And I hope you'll be able to smile at life, like I'm doing right now.\"",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892931A"
        },
        [80120218] = {
          Camera = "-393.488953,121.270996,118.823044,0.000066,3.202293,41.604927,60.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "......",
          DialogueId = 80120218,
          FacialId = {
            [1] = "790019:Sad01"
          },
          GUID = "C8929344",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextOptions = {
            [1] = 801202181,
            [2] = 801202182
          },
          SpeakNpcId = 790019,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929344"
        },
        [80120219] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아, 오래전의 이 코르삭은 사실 좋은 분이셨네요.",
          DialogueId = 80120219,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892936E",
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          Subtitle = "That Kossak... he was really a decent fellow back then.",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892936E"
        },
        [80120220] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "음... 그럴 수도 있겠네요. 모든 악보를 무시하는 척 했으면서도 정작 가장 중요한 보물은 '이미 제자리에 뒀다'고 하셨잖아요...",
          DialogueId = 80120220,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C8929398",
          LookAt = {
            [1] = "790019:p(P33010201)",
            [2] = "790008:p(P33010201)"
          },
          NextDialogue = 80120221,
          SpeakNpcId = 790019,
          Subtitle = "Hmm... You might be right. He didn't care about most of his music scores, but he was awfully sure that his most important pieces had been \"well secured where they belong\"...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929398"
        },
        [80120221] = {
          Camera = "-440.217041,86.593506,117.899193,0.000059,-0.799351,34.609612,35.0,234.284531,false,Manual,5.0",
          ContentKR = "그 말은 즉, 그의 마음속에서 가장 소중한 악보가 바로 이 악보라는 거예요... 그리고 '제자리'라는 건, 카론인 제 손에 맡기는 것을 의미하는 거죠. 원래 카론을 위해 쓴 노래니까요.",
          DialogueId = 80120221,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89293C2",
          LookAt = {
            [1] = "790019:n(790008)",
            [2] = "790008:n(790019)"
          },
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          Subtitle = "So maybe, just maybe, this score was the one he cherished most. And the \"right place\" for it was in the hands of a Charon — because it was written for them.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89293C2"
        },
        [80120222] = {
          Camera = "-252.260193,281.916748,126.221512,0.000009,-3.999636,-119.588837,35.0,234.284531,false,Manual,5.0",
          ContentKR = "가사가 정말 좋네요... 아, 이 노래를 실제로 부르면 어떨지 궁금해요.",
          DialogueId = 80120222,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          GUID = "C89293EC",
          LookAt = {
            [1] = "790019:n(790019)"
          },
          NextDialogue = 80120223,
          SpeakNpcId = 790019,
          Subtitle = "The lyrics are really something... I wonder what this song will sound like.",
          TalkActionId = {
            [1] = "790019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89293EC"
        },
        [80120223] = {
          Camera = "-304.703491,193.633301,104.081329,-0.0,7.999981,-131.396408,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "좋아요~ 결심했어요!",
          DialogueId = 80120223,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C8929416",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120224,
          SpeakNpcId = 790019,
          Subtitle = "Alright — I've made up my mind!",
          TalkActionId = {
            [1] = "790019:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929416"
        },
        [80120224] = {
          Camera = "-255.582703,344.383789,69.178757,0.000035,7.599951,-112.388451,35.000008,264.602783,false,Manual,2.8",
          ContentKR = "이 노래를 코르삭 씨가 잊어버리셨든 일부러 남기셨든, 어쨌든 그가 남은 물건들을 처리하라고 저한테 맡기신 거잖아요. 그러니 전 진지하게 생각할 거예요.",
          DialogueId = 80120224,
          GUID = "C8929440",
          NextDialogue = 80120225,
          SpeakNpcId = 790019,
          Subtitle = "Whether Kossak forgot about this score or left it behind on purpose, he trusted me to handle his stuff, so I'm going to take it seriously.",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929440"
        },
        [80120225] = {
          Camera = "-501.36084,57.133301,131.599701,0.000011,-4.399932,31.404215,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "자, {nickname} 님, 저랑 카밀라 언니한테 가요. 언니가 악보도 읽을 줄 안다고 들었어요. 노래하는 법을 가르쳐 달라고 하려고요.",
          DialogueId = 80120225,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892946A",
          NextDialogue = 80120226,
          SpeakNpcId = 790019,
          Subtitle = "Come on, , let's head over to Ms Camilla's tavern. I think she can read music. I'm going to ask her to teach me this song.",
          TalkActionId = {
            [1] = "790019:Explain02_End",
            [2] = [[

790008:AgreeHead]]
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892946A"
        },
        [80120226] = {
          Camera = "-302.98645,187.943359,114.158592,0.000014,3.400027,-133.7966,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "제가 배우고 나면, 아이스레이크 시티의 카론들에게 가르쳐 줄 거예요. 그리고 이 노래는 모두에게 존경받는 음악가가 우리 카론을 위해 특별히 작곡한 거라고 말해줄 거고요.",
          DialogueId = 80120226,
          FacialId = {
            [1] = "790019:Happy01"
          },
          FinalCamera = "-302.98645,187.943359,114.158592,0.000026,3.400027,-133.7966,36.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929494",
          NextDialogue = 80120227,
          SpeakNpcId = 790019,
          Subtitle = "Once I've learned it, I'll teach it to all the Charons in Icelake. I'll tell them it's a song written especially for us by a respected musician.",
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929494"
        },
        [80120227] = {
          Camera = "193.657837,-330.853027,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이렇게 하면 이 노래가 그 분의 폐기된 악보처럼 난로에 던져져 한순간에 사라지는 일은 없을 거예요.",
          DialogueId = 80120227,
          FinalCamera = "153.661621,-330.320312,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89294BE",
          NextDialogue = 80120228,
          SpeakNpcId = 790019,
          Subtitle = "That way, this song won't end up like his discarded drafts, tossed into the fire and burned to ashes.",
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294BE"
        },
        [80120228] = {
          Camera = "79.69873,985.43457,55.531265,0.000044,12.80017,92.181931,55.0,490.84668,false,Manual,1.2",
          ContentKR = "어쩌면 언젠가 이 노래가 황성까지 퍼져서 그가 실제로 카론들이 이 노래를 부르는 걸 들을 수 있을지도 몰라요. 하지만 듣지 못해도 상관없어요. 어쨌든 전 제가 해야 할 일을 한 거니까...",
          DialogueId = 80120228,
          FinalCamera = "103.997955,961.556152,69.737282,0.000067,10.600037,97.981682,55.0,490.84668,false,Manual,1.2",
          GUID = "C89294E8",
          NextDialogue = 80120229,
          SpeakNpcId = 790019,
          Subtitle = "Who knows? Maybe one day, this song will reach the capital, so he'll hear Charons singing it outside his window. But even if that won't happen, it doesn't matter. I'll have done my job—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294E8"
        },
        [80120229] = {
          Camera = "-312.233704,183.148438,116.782532,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentKR = "버려져서는 안 될 것들을 다시 세상에 나오게 하고, 쓸모없는 걸 유용한 걸로 바꾸는 게 바로 제 책임이에요!",
          DialogueId = 80120229,
          FacialId = {
            [1] = "790019:Happy02"
          },
          FinalCamera = "-316.72876,177.902344,117.07206,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929512",
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"-285.357117,180.728271,121.084183,0.0,0.0,-143.597351,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 790019,
          Subtitle = "Bringing forgotten treasures back into the light and letting their value be seen — that's my mission!",
          TalkActionId = {
            [1] = "790019:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929512"
        },
        [80120230] = {
          ContentKR = "(후에 카밀라의 말에 따르면, 이 〈악마가 쇠사슬을 끊고〉라는 곡은 정말 뛰어난 곡이었지만, 난이도가 매우 높았다고 한다.)",
          DialogueId = 80120230,
          Duration = 4,
          GUID = "C892953C",
          NextDialogue = 80120231,
          Subtitle = "Later, according to Camilla, \"Demons Broken Loose\" is indeed a brilliant piece, and quite a challenging one.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C892953C"
        },
        [80120231] = {
          ContentKR = "(결국 마르제는 사흘 동안 노력했고, 음정을 한 옥타브 낮춰서야 이 노래를 배울 수 있었다. 그 후 얼마 지나지 않아, 아이스레이크 시티에서 가끔 이 노래를 부르는 소리를 들을 수 있게 되었다.)",
          DialogueId = 80120231,
          Duration = 5,
          GUID = "C8929566",
          NextDialogue = 80120232,
          Subtitle = "It took Margie three full days to master the song, and even then, she had to transpose it down an octave. Before long, echoes of the melody began to drift through the streets of Icelake.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929566"
        },
        [80120232] = {
          ContentKR = "(이것이 바로 마르제가 말하는 '쓸모없는 걸 유용한 걸로 바꾸는 것'인가 보다.)",
          DialogueId = 80120232,
          Duration = 3,
          GUID = "C8929590",
          Subtitle = "Seems like Margie has accomplished her mission of bringing forgotten treasures back into the light.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929590"
        },
        [80120290] = {
          DialogueId = 80120290,
          GUID = "C89291CB",
          IsBlack = 1,
          NextDialogue = 80120210,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_woodbrk\"},PlayAs2D{true}}"
        },
        [80120301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "음...",
          DialogueId = 80120301,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A0E2",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120302,
          SpeakNpcId = 93301,
          Subtitle = "Hmm...",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentKR = "쓰기도 하고 달기도 하고... 으, 우리 집 꼰대가 좋아할 것 같은 맛이에요! 저야 뭐, 아마 10년, 아니 20년은 더 지나야 이런 맛을 이해할 수 있겠죠.",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          Subtitle = "Bitter and sweet at the same time... Ugh, this tastes like something my stupid old man would love! As for me, I think I'll need another ten... no, make that twenty years to appreciate this taste.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentKR = "전혀 이해가 안 돼요! 사람들은 왜 굳이 힘들게 이런 걸 마시는 거예요!",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "I just don't get this drink! Why would anyone want to torture themselves with this bitter taste?",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentKR = "맞아요! 일 끝나고 한 잔 마시면 머리끝부터 발끝까지 상쾌해지는 느낌이 좋아요.",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "Exactly! Nothing beats a refreshing drink after a day's work — it's like a cool wave from head to toe!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A160"
        },
        [80120305] = {
          ContentKR = "우리 아빠 말이에요! 다들 그를 마틴 할배라고 불러요. 제가 독립하기 전까지는 아이스레이크 시티의 쓰레기통을 모두 그가 관리했죠.",
          DialogueId = 80120305,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A18A",
          NextDialogue = 80120306,
          SpeakNpcId = 93301,
          Subtitle = "Oh, that's my dad! They call him Old Martin. Before I took over, he was the one managing all the rubbish bins in Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A18A"
        },
        [80120306] = {
          ContentKR = "사람들이 아빠를 '쓰레기통의 왕'이라고 부르지 않았다면... 애초에 제가 어떻게 '쓰레기통 공주'라는 이상하고 촌스러운 별명을 갖게 됐겠어요... 으으, 꼰대가 쓸데없이 화려한 걸 좋아해서 망신만 당했다고요!",
          DialogueId = 80120306,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A1B4",
          NextDialogue = 80120307,
          SpeakNpcId = 93301,
          Subtitle = "If it weren't for his stupid title \"King of the Bins,\" I wouldn't be stuck with that tacky, lame nickname \"Princess Rubbish Bin\"... Ugh, it's all that flashy old man's fault!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1B4"
        },
        [80120307] = {
          ContentKR = "저는 분명 더 멋지고, 더 지혜롭고, 더 믿음직한...",
          DialogueId = 80120307,
          FacialId = {
            [1] = "93301:Iyada01"
          },
          GUID = "C892A1DE",
          NextOptions = {
            [1] = 801203071,
            [2] = 801203081
          },
          SpeakNpcId = 93301,
          Subtitle = "I mean, I was hoping for something cooler, smarter, and more reliable...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1DE"
        },
        [80120308] = {
          ContentKR = "맞아요 맞아요~ 헤헤헤, 역시 {nickname} 님이 절 제일 잘 알아주시네요!",
          DialogueId = 80120308,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A208",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          Subtitle = "That's right! Hehe, you totally get me!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A208"
        },
        [80120309] = {
          ContentKR = "으악—— 그만하세요 그만! 한 마디만 더 하시면 제 삽을 맛보시게 될 거예요!",
          DialogueId = 80120309,
          FacialId = {
            [1] = "93301:Disappoint01"
          },
          GUID = "C892A232",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          Subtitle = "Aaaah! Stop it! I'll whack you with my shovel if you say that again!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A232"
        },
        [80120310] = {
          ContentKR = "휴... 그 꼰대, 일을 저한테 떠넘기고 나서는 종일 안 보이더니, 뭘 하고 다니는지 모르겠어요. 카밀라 언니랑 저한테 걱정 끼치는 일만 하지 않았으면 좋겠는데요!",
          DialogueId = 80120310,
          FacialId = {
            [1] = "93301:Unhappy01"
          },
          GUID = "C892A25C",
          NextOptions = {
            [1] = 801203101
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh... ever since that stupid old man dumped all the work on me, I barely see him around. No idea what he's been doing. He better not be causing trouble for me and Ms Camilla!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A25C"
        },
        [80120311] = {
          ContentKR = "으음, 이 쓴 맛만 아니었다면... 확실히, 저도 꼰대 생각을 한동안 안 했던 것 같아요...",
          DialogueId = 80120311,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892A286",
          NextOptions = {
            [1] = 801203111,
            [2] = 801203121
          },
          SpeakNpcId = 93301,
          Subtitle = "Uh, well... if it weren't for this bitter taste, I guess I haven't really thought about him in a while...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A286"
        },
        [80120312] = {
          ContentKR = "저는 일이 바빠서예요! 게다가 결국, 이 모든 일은 그가 저한테 떠넘긴 거잖아요!",
          DialogueId = 80120312,
          FacialId = {
            [1] = "93301:Shock02"
          },
          GUID = "C892A2B0",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          Subtitle = "Well, in my defence, I've been swamped with work! His work, to be precise!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2B0"
        },
        [80120313] = {
          ContentKR = "켁켁... 작은 동물들도 다 자라면 둥지를 떠나 혼자 살아가야 하는 법이죠. 정상적인 거예요.",
          DialogueId = 80120313,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A2DA",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          Subtitle = "Ahem... Well, you know, when little animals grow up, they leave the nest to fend for themselves. It's totally normal.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2DA"
        },
        [80120314] = {
          ContentKR = "그리고 제 인생의 처음 십 몇 년 동안, 꼰대는 거의 항상 제 주변을 맴돌았어요. 특히 고향에서 아이스레이크 시티로 올 때, 우리는 일 년 내내 설원에서 지냈는데, 우리 둘뿐이었어요. 다른 사람은 한 명도 못 봤다고요.",
          DialogueId = 80120314,
          GUID = "C892A304",
          NextDialogue = 80120315,
          SpeakNpcId = 93301,
          Subtitle = "Besides, that stupid old man has been fussing over me for more than ten years. Especially after we left our old home for Icelake — we spent a whole year trekking across the snowfields, just the two of us, not another living soul in sight.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A304"
        },
        [80120315] = {
          ContentKR = "전 이미 꼰대가 하는 말이나, 노래, 쓸데없는 아재 개그야 충~분히 들었으니까, 그리 그립지는 않아요... 아마도요.",
          DialogueId = 80120315,
          GUID = "C892A32E",
          NextDialogue = 80120316,
          SpeakNpcId = 93301,
          Subtitle = "I've had enough of his tales, his songs, and his tricks to last me a lifetime. So... I guess that's why I don't really miss him that much... probably.",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A32E"
        },
        [80120316] = {
          ContentKR = "게다가 아이스레이크 시티에 온 지 얼마 안 됐을 때, 꼰대는 '영역 나누기', '지역 깡패 포섭하기', '보호비 징수 방법 정하기', '기존 세력과 손잡기', '실세 되기' 같은 걸 시작했어요... 혼자서도 꽤 즐거워 보이더라고요.",
          DialogueId = 80120316,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A358",
          NextOptions = {
            [1] = 801203161
          },
          SpeakNpcId = 93301,
          Subtitle = "Plus, soon after we arrived in Icelake, he jumped right into \"staking out territories,\" \"recruiting the local henchmen,\" \"figuring out the protection racket,\" \"making alliances with local powers,\" and \"becoming the top dog.\" He seemed to enjoy himself just fine on his own.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A358"
        },
        [80120317] = {
          ContentKR = "아, 그냥 쓰레기통 분포를 파악하고, 기존 환경미화원들을 고용하고, 쓰레기통 관리 기준을 정하고, 카밀라 언니를 통해 재활용품을 사갈 상인들을 찾고, 마지막으로 '쓰레기통의 왕'이 된 거예요.",
          DialogueId = 80120317,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A382",
          NextDialogue = 80120318,
          SpeakNpcId = 93301,
          Subtitle = "Oh, it's actually just mapping out the rubbish bin locations, recruiting the sanitation workers, setting rules for rubbish collection, finding buyers through Ms Camilla, and becoming the \"King of the Bins.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A382"
        },
        [80120318] = {
          ContentKR = "으악, 꼰대는 그냥 연극 대본에 나오는 것처럼 허세 가득한 말을 하는 걸 좋아해요. 아마도 옛날에 살던 그 싸움만 일어나는 엉망진창 동네에서 나쁜 버릇이 든 모양이에요. 지금도 고치질 못하고, 으악——",
          DialogueId = 80120318,
          GUID = "C892A3AC",
          NextOptions = {
            [1] = 801203181
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh, that stupid old man loves spouting off fancy talk — he sounds like a flashy character from a drama script! Bad habits from his rough-and-tumble days back home, I guess. He can't seem to shake them off. Gah!",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3AC"
        },
        [80120319] = {
          ContentKR = "글쎄요! 꼰대는 자기가 예전에 했던 '위대한 업적'에 대한 이야기를 제게 들려주는 걸 제일 좋아했어요! 뭐...",
          DialogueId = 80120319,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A3D6",
          NextDialogue = 80120320,
          SpeakNpcId = 93301,
          Subtitle = "It's hard to say! The old man always liked to brag about his \"glorious past\" back home. Stuff like...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3D6"
        },
        [80120320] = {
          ContentKR = "\"'청소부'가 받는 모든 명령은 개인의 명예와 가문의 이익에 관련되어 있지. 계획을 세우는 것부터 당일의 복장까지, 모든 게 완벽해야 해. 그리고 네 아버지인 나야말로 최고의 청소부였다.\"라는 식으로 말하기나 하고.",
          DialogueId = 80120320,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A400",
          NextDialogue = 80120321,
          SpeakNpcId = 93301,
          Subtitle = "\"A scavenger's every mission is a matter of personal honour and family interest. From daily planning to personal grooming, everything must be meticulously prepared. And your father, my dear, was the finest scavenger of all.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A400"
        },
        [80120321] = {
          ContentKR = "다 꼰대 때문이에요. 제가 아이스레이크 시티에 막 왔을 때, 말하는 게 꼭 '작은 마틴' 같았다고 하더라고요. 카밀라 언니가 이런 말투를 정말 싫어해서, 나중에 절 꽤 오래 붙잡고 교정해 주셨는데...",
          DialogueId = 80120321,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A42A",
          NextOptions = {
            [1] = 801203211
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh, his bad influence is why, when I first got to Icelake, I talked exactly like a \"Mini-Martin.\" Ms Camilla said it was really annoying, and it took her forever to help me lose that tone...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A42A"
        },
        [80120322] = {
          ContentKR = "싫어요! 너무 창피해요!",
          DialogueId = 80120322,
          FacialId = {
            [1] = "93301:Unacceptable01"
          },
          GUID = "C892A454",
          NextOptions = {
            [1] = 801203221,
            [2] = 801203231
          },
          SpeakNpcId = 93301,
          Subtitle = "No way! That's too embarrassing!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A454"
        },
        [80120323] = {
          ContentKR = "딱 한 번이에요, 다시는 안 할 거예요!",
          DialogueId = 80120323,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A47E",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          Subtitle = "Fine, just this once, okay? No encores!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A47E"
        },
        [80120324] = {
          ContentKR = "아! 말할게요, 말할게요! 제발 그만하세요——",
          DialogueId = 80120324,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A4A8",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          Subtitle = "Aaaahhhh!!! Okay, okay! I'll do it! Just stop already!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4A8"
        },
        [80120325] = {
          ContentKR = "음... 마틴 할배가 절 카밀라 언니 가게에 맡기고, 일하러 갈 때 제가 이렇게 말했어요...",
          DialogueId = 80120325,
          FacialId = {
            [1] = "93301:Think01"
          },
          GUID = "C892A4D2",
          NextDialogue = 80120326,
          SpeakNpcId = 93301,
          Subtitle = "Uh… When Old Martin dropped me off at Ms Camilla's tavern before he went off to do who-knows-what, I'd say...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4D2"
        },
        [80120326] = {
          ContentKR = "\"당신의 사명을 명심하세요, 아버지. 우리의 미래는 당신의 앞으로의 모든 행보에 달려 있습니다. 그러니 아버지가 세수하고, 양치하고, 완벽한 계획을 세웠는지 꼭 확인하셨으면 좋겠군요.\"",
          DialogueId = 80120326,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A4FC",
          NextOptions = {
            [1] = 801203261
          },
          SpeakNpcId = 93301,
          Subtitle = "\"Remember your mission, Father. Our future hinges on your every move, so I trust you've washed your face, brushed your teeth, and made a thorough plan.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4FC"
        },
        [80120327] = {
          ContentKR = "그러면 마틴 할배가 모자를 벗고 제게 이렇게 말했죠. \"알겠습니다, 레이디! 우리 둘 중 누군가 임무에 실패한다면, 그 사람의 이름 앞에 '바보'라는 단어를 붙여 아스포델의 문 앞에 써 붙이겠습니다.\"",
          DialogueId = 80120327,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A526",
          NextOptions = {
            [1] = 801203271
          },
          SpeakNpcId = 93301,
          Subtitle = "And then Old Martin would tip his hat and say, \"As you command, ma'am! Should either of us fail, we'll inscribe that person's name with the modifier \"idiot\" on The Asphodel's door for all to see.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A526"
        }
      }
    end
  },
  {
    MinKey = 80120328,
    MaxKey = 80130409,
    Loader = function()
      return {
        [80120328] = {
          ContentKR = "그러면 저는 이렇게 대답했죠. \"오, 우리가 같은 성을 쓰는 걸 고려하면, 차라리 냄비 바닥에 쓰는 게 어떨까요? 그러면 제 체면을 지키면서도, 불꽃이 당신의 치욕을 지져버릴 수 있을 테니까요!\"",
          DialogueId = 80120328,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A550",
          NextOptions = {
            [1] = 801203281
          },
          SpeakNpcId = 93301,
          Subtitle = "And I'd reply, \"Oh, considering we share a last name, better to inscribe it on the bottom of a pot instead — saves me the shame and allows the stove fire to scorch your disgrace!\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A550"
        },
        [80120329] = {
          ContentKR = "하하하하하하하하하하!",
          DialogueId = 80120329,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A57A",
          NextDialogue = 80120330,
          SpeakNpcId = 100001,
          Subtitle = "Ahahahahahahaha!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A57A"
        },
        [80120330] = {
          ContentKR = "이제 보니 네가 '쓰레기통 공주'라고 불리는 게 전부 마틴 할배의 잘못은 아닌 것 같아.",
          DialogueId = 80120330,
          GUID = "C892A5A4",
          NextDialogue = 80120331,
          SpeakNpcId = 100001,
          Subtitle = "Now I see why you ended up with the title \"Princess Rubbish Bin\" — it's not all Old Martin's fault!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5A4"
        },
        [80120331] = {
          ContentKR = "상관없어요! 다 꼰대 잘못이에요! 꼰대랑 똑같이 잘난 체하는 사람이 될 뻔했다는 생각만 해도 온몸에 소름이 돋아요.",
          DialogueId = 80120331,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A5CE",
          NextDialogue = 80120332,
          SpeakNpcId = 93301,
          Subtitle = "I don't care! It's totally his fault! Just thinking I almost turned into a pompous blowhard like him gives me the chills.",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5CE"
        },
        [80120332] = {
          ContentKR = "그리고 들어보세요, 꼰대는 자기 과거에 대해 분명히 그리움과 자부심을 가지고 있어요. 제가 보기에는 꼰대가 고향의 혼란을 완전히 싫어해서 떠난 건 아닌 것 같아요.",
          DialogueId = 80120332,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A5F8",
          NextDialogue = 80120333,
          SpeakNpcId = 93301,
          Subtitle = "And I don't know if you figured this out — the stupid old man clearly misses and takes pride in his past. I don't think he left home just because he hated the chaos there.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5F8"
        },
        [80120333] = {
          ContentKR = "하지만 도대체 무슨 일이 있었길래, 저를 데리고 설원을 건너서라도 고향을 떠나야 했을까요?",
          DialogueId = 80120333,
          FacialId = {
            [1] = "93301:Unhappy02"
          },
          GUID = "C892A622",
          NextDialogue = 80120334,
          SpeakNpcId = 93301,
          Subtitle = "But what could have happened that made him leave home and drag me across the snowfields?",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A622"
        },
        [80120334] = {
          ContentKR = "분명 제게 말 못할 큰 비밀이 있어요! 하지만 제가 물어볼 때마다 그는 '말해주지 않을 거야. 알고 싶으면 네 머리를 좀 굴려봐.'라고만 해요.",
          DialogueId = 80120334,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A64C",
          NextDialogue = 80120335,
          SpeakNpcId = 93301,
          Subtitle = "He's definitely hiding something huge from me! But every time I ask, all he says is, \"I won't tell you. If you do want to know, use your head and figure it out yourself.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A64C"
        },
        [80120335] = {
          ContentKR = "그래서 작년에 몰래 꼰대에 대해 한참 동안 조사했어요. 하지만 항상 귀신같이 나타났다 사라졌다 하고, 고향에서 가져온 짐도 어디에 숨겼는지 모르겠어요.",
          DialogueId = 80120335,
          GUID = "C892A676",
          NextDialogue = 80120336,
          SpeakNpcId = 93301,
          Subtitle = "So last year, I secretly investigated him for months. But the old man's so crafty and sneaky, he even hid the stuff he brought from our hometown. I couldn't find it no matter what.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A676"
        },
        [80120336] = {
          ContentKR = "몇 달 동안 조사했지만, 아무것도 찾지 못했어요. 결국엔 심하게 조롱만 당했다니까요.",
          DialogueId = 80120336,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A6A0",
          NextOptions = {
            [1] = 801203361
          },
          SpeakNpcId = 93301,
          Subtitle = "After months of digging, I came up empty. And to top it off, he had the nerve to mock me—",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6A0"
        },
        [80120337] = {
          ContentKR = "맞아요, 조롱! 그러다 어느 날, 한참을 안보이더니 갑자기 돌아와서 하루 종일 저랑 놀아줬어요. 마지막엔 심지어 여행 가방을 두고 가기까지 했어요. 고향에서 가져온 그 가방 말이에요!",
          DialogueId = 80120337,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A6CA",
          NextDialogue = 80120338,
          SpeakNpcId = 93301,
          Subtitle = "One day, out of nowhere, the old man actually showed up. He spent the whole day with me, and even forgot to take his suitcase with him when he left — the one he brought from our hometown!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6CA"
        },
        [80120338] = {
          ContentKR = "그래서 전 꼰대가 실수로 그걸 놓고 갔다고 생각했어요. 드디어 제 차례라고 생각하면서 가방을 열었는데, 안에는 냄비 하나밖에 없더라고요...",
          DialogueId = 80120338,
          GUID = "C892A6F4",
          NextDialogue = 80120339,
          SpeakNpcId = 93301,
          Subtitle = "I thought, \"Ha! That old man slipped up at last!\" So I opened the suitcase, and inside... was just a pot.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6F4"
        },
        [80120339] = {
          ContentKR = "(마르제가 화가 나서 자기 머리 위에 쓰고 있는 것을 쾅쾅 두들긴다. 둔탁한 소리가 난다.)",
          DialogueId = 80120339,
          GUID = "C892A71E",
          NextDialogue = 80120340,
          Subtitle = "(Margie angrily taps on the pot she's wearing on her head, producing a hollow sound.)",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A71E"
        },
        [80120340] = {
          ContentKR = "바로 이거예요! 게다가 여행 가방에 쪽지까지 남겼더라고요...",
          DialogueId = 80120340,
          GUID = "C892A748",
          NextDialogue = 80120341,
          SpeakNpcId = 93301,
          Subtitle = "This thing right here! And he left a note in the suitcase...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A748"
        },
        [80120341] = {
          ContentKR = "\"마르제 양에게, 당신이 반드시 이 여행 가방을 열어 내 비밀을 찾으려 할 것이라 예상했소. 그래서 나는 이미 비밀을 당신이 상상도 못할 곳으로 옮겼소.\"",
          DialogueId = 80120341,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A772",
          NextDialogue = 80120342,
          SpeakNpcId = 93301,
          Subtitle = "\"Dear Miss Margie, I knew you'd snoop in this suitcase, so I've relocated the secret to a place you'd least expect.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A772"
        },
        [80120342] = {
          ContentKR = "\"당신의 실망을 달래기 위해 이것을 남긴다오. 이 다기능 헬멧은 바로 쓰면 머리를 효과적으로 보호할 수 있고, 거꾸로 쓰면 불을 피워 요리할 수 있으며, 앞쪽의 광부 램프는 조명으로 사용할 수 있소. 집에서나 외출할 때나 최고의 선택이 될 것이오.\"",
          DialogueId = 80120342,
          GUID = "C892A79C",
          NextDialogue = 80120343,
          SpeakNpcId = 93301,
          Subtitle = "\"To make up for your disappointment, I've left you this — an all-purpose pot helmet! Worn normally, it protects your head; flip it over, and it's a perfect cooking pot. The attached lamp even works as a flashlight. Truly, the ultimate all-in-one tool.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A79C"
        },
        [80120343] = {
          ContentKR = "\"그리고 생일 축하하오. —— 마틴.\"",
          DialogueId = 80120343,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A7C6",
          NextOptions = {
            [1] = 801203431,
            [2] = 801203432
          },
          SpeakNpcId = 93301,
          Subtitle = "\"By the way, happy birthday. — Martin.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7C6"
        },
        [80120344] = {
          ContentKR = "...제가 보기엔 그냥 절 놀리는 거예요!",
          DialogueId = 80120344,
          GUID = "C892A7F0",
          NextDialogue = 80120345,
          SpeakNpcId = 93301,
          Subtitle = "...I'm pretty sure he was mocking me!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7F0"
        },
        [80120345] = {
          ContentKR = "어쨌든 그 후로는 꼰대의 비밀에 대해 신경 쓰지 않기로 했어요.",
          DialogueId = 80120345,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A81A",
          NextDialogue = 80120346,
          SpeakNpcId = 93301,
          Subtitle = "Anyway, after that, I gave up caring about his stupid secret.",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A81A"
        },
        [80120346] = {
          ContentKR = "그러고 보니, 갑자기 이상한 예감이 들어...",
          DialogueId = 80120346,
          GUID = "C892A844",
          NextDialogue = 80120347,
          SpeakNpcId = 100001,
          Subtitle = "Speaking of secrets, I've got a hunch...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A844"
        },
        [80120347] = {
          ContentKR = "어떤 예감이요?",
          DialogueId = 80120347,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A86E",
          NextDialogue = 80120348,
          SpeakNpcId = 93301,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A86E"
        },
        [80120348] = {
          ContentKR = "혹시 이 '다기능 헬멧' 안에 비밀이 있는 건 아닐까?",
          DialogueId = 80120348,
          GUID = "C892A898",
          NextDialogue = 80120349,
          SpeakNpcId = 100001,
          Subtitle = "Could his secret be hidden... inside this \"all-purpose helmet\"?",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A898"
        },
        [80120349] = {
          ContentKR = "마틴 할배가 \"비밀은 예상치 못한 곳에 있다\"고 말했잖아. 그렇다면 한 가지 가능성이 있어... 가장 위험한 곳이 오히려 가장 안전한 곳일 수도 있지 않을까?",
          DialogueId = 80120349,
          GUID = "C892A8C2",
          NextDialogue = 80120350,
          SpeakNpcId = 100001,
          Subtitle = "I mean, he did say it was at a place you'd least expect, so... maybe the most obvious place is the place you'd never expect.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8C2"
        },
        [80120350] = {
          ContentKR = "그렇게 말씀하시고 보니, 그때는 기분이 좋지 않아서 이 헬멧을 자세히 살펴보지 않았어요! 이제 와서 생각해보니, 이 헬멧이 개조된 거라면 안에 뭔가 숨겨져 있을 수도 있겠어요! 한번 분해해 볼게요!",
          DialogueId = 80120350,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A8EC",
          NextDialogue = 80120351,
          SpeakNpcId = 93301,
          Subtitle = "Ah...!!! Come to think of it, I was so bummed back then I didn't even check this helmet carefully! You might be right — it's been modified, so it's possible that he had hidden something inside! Let's take it apart now!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8EC"
        },
        [80120351] = {
          ContentKR = "정말이에요! 충격 흡수층 아래에 숨겨진 공간이 있어요! 역시 {nickname} 님 말씀이 맞았어요. 정말 탐정 자질이 있으시네요!",
          DialogueId = 80120351,
          GUID = "C892A916",
          IsBlack = 1,
          NextDialogue = 80120352,
          SpeakNpcId = 93301,
          Subtitle = "Aha! A hidden compartment under the padding! I knew you had a detective's knack!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A916"
        },
        [80120352] = {
          ContentKR = "꼰대! 이번엔 당신 비밀을 찾았다고!",
          DialogueId = 80120352,
          GUID = "C892A940",
          IsBlack = 1,
          NextDialogue = 80120353,
          SpeakNpcId = 93301,
          Subtitle = "Gotcha, stupid old man! The jig's up!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A940"
        },
        [80120353] = {
          ContentKR = "(마르제가 아마도 여러 번 폐품을 개조해 본 경험 덕분인지 냄비로 만든 헬멧을 능숙하게 만지작거린다. 마르제의 손가락이 재빨리 움직이더니 곧 분해를 마쳤다.)",
          DialogueId = 80120353,
          GUID = "C892A96A",
          IsBlack = 1,
          NextDialogue = 80120354,
          Subtitle = "(Margie skillfully manipulates the pot helmet — her experience with repurposing scrap obviously helps a lot. Her fingers move deftly, and soon the pot is fully disassembled.)",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A96A"
        },
        [80120354] = {
          ContentKR = "이, 이건...",
          DialogueId = 80120354,
          GUID = "C892A994",
          IsBlack = 1,
          NextDialogue = 80120355,
          SpeakNpcId = 93301,
          Subtitle = "Ah, this is...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A994"
        },
        [80120355] = {
          ContentKR = "(마르제가 눈을 동그랗게 뜨고 냄비를 쳐다보며 말을 잇지 못한다. 그녀의 손에서 냄비를 받아 들자 바닥에 작은 글씨로 새겨진 것이 보인다.)",
          DialogueId = 80120355,
          GUID = "C892A9BE",
          IsBlack = 1,
          NextDialogue = 80120356,
          Subtitle = "(Margie stares wide-eyed at the pot, speechless. You take the pot from her and see a small inscription on the bottom—)",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9BE"
        },
        [80120356] = {
          ContentKR = "\"나의 바보 같은 딸 마르제에게.",
          DialogueId = 80120356,
          GUID = "C892A9E8",
          IsBlack = 1,
          NextDialogue = 80120357,
          Subtitle = "\"Dear Margie, my silly daughter,\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9E8"
        },
        [80120357] = {
          ContentKR = "'마틴 할배의 비밀 찾기' 게임에서 또 한 번 실패한 것을 축하한다. 그래서 나는 네 이름 앞에 '바보'라는 단어를 붙이겠다.",
          DialogueId = 80120357,
          GUID = "C892AA12",
          IsBlack = 1,
          NextDialogue = 80120358,
          Subtitle = "\"Congratulations on failing yet again in the 'Find Old Martin's Secret' game. As punishment, I shall add the modifier 'Idiot' to your name.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA12"
        },
        [80120358] = {
          ContentKR = "우리가 같은 성을 쓰는 걸 고려해, 네 이름을 냄비 바닥에 새겼다. 이러면 내 체면을 지키면서도, 불꽃이 네 치욕을 지져버릴 수 있겠지.\"",
          DialogueId = 80120358,
          GUID = "C892AA3C",
          IsBlack = 1,
          Subtitle = "\"Considering we share a last name, I hereby inscribe it on the bottom of this pot instead, which saves me the shame, and allows the stove fire to scorch your disgrace.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA3C"
        },
        [80120401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentKR = "흐윽! 흑흑흑... 탐정님이 또 엄청난 사건을 해결하셨군요...",
          DialogueId = 80120401,
          GUID = "C892B14A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204011
          },
          SpeakNpcId = 93301,
          Subtitle = "*sniffles* ...Detective Margie has cracked yet another groundbreaking case...",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B14A"
        },
        [80120402] = {
          ContentKR = "이, 이건 기쁨의 눈물이에요!",
          DialogueId = 80120402,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892B174",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204021
          },
          SpeakNpcId = 93301,
          Subtitle = "Th—These are tears of joy!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B174"
        },
        [80120403] = {
          ContentKR = "(마르제가 물을 한 잔 가득 들이킨 뒤, 주머니에서 뭔가를 조심스럽게 꺼내 내 앞에 내민다. 작은 동물의 털 뭉치 같은데, 색깔이 어디서 본 듯하다...)",
          DialogueId = 80120403,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B19E",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120404,
          Subtitle = "(Margie gulps down a full glass of water, then gingerly pulls something from her pocket and presents it to you — it's a clump of fur, somewhat familiar in colour.)",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B19E"
        },
        [80120404] = {
          ContentKR = "'팻테일'을 찾았어요!",
          DialogueId = 80120404,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B1C8",
          NextOptions = {
            [1] = 801204041
          },
          SpeakNpcId = 93301,
          Subtitle = "I found Plumpytail!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1C8"
        },
        [80120405] = {
          ContentKR = "예전에 저랑 같이 설원을 떠돌아다녔던 고양이에요!",
          DialogueId = 80120405,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B1F2",
          NextDialogue = 80120406,
          SpeakNpcId = 93301,
          Subtitle = "Plumpytail's the little cat I used to roam the snowfields with!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1F2"
        },
        [80120406] = {
          ContentKR = "나중에 제가 아이스레이크 시티로 왔을 때, 걔는 따라오지 않고 밖에 남았어요. 그리고 전 걔랑 똑같이 생긴 인형을 만들어서 기념했죠!",
          DialogueId = 80120406,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B21C",
          NextDialogue = 80120407,
          SpeakNpcId = 93301,
          Subtitle = "Then I came to Icelake, but she didn't want to come with me and stayed in the wilderness. I made a plushie that looks just like her to remember her!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B21C"
        },
        [80120407] = {
          ContentKR = "오늘 제가 물건을 구하려고 성문 근처 쓰레기통에 갔는데, 우연히 이 털을 주웠어요. 보세요!",
          DialogueId = 80120407,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B246",
          NextDialogue = 80120408,
          SpeakNpcId = 93301,
          Subtitle = "I was just going to check the bins near the city gates today, but instead, I stumbled upon this clump of fur! Look!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B246"
        },
        [80120408] = {
          ContentKR = "이 회색빛에 검은 점이 있는 털 색깔, 부드러우면서도 뻣뻣한 느낌, 게다가 주웠을 때 아직 축축했어요... 틀림없이 팻테일이 절 찾아온 거예요!",
          DialogueId = 80120408,
          GUID = "C892B270",
          NextDialogue = 80120409,
          SpeakNpcId = 93301,
          Subtitle = "The greyish colour with black spots, the soft yet coarse feel, and the fact that it was even a bit damp when I found it... It's definitely Plumpytail! She came back for me!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B270"
        },
        [80120409] = {
          ContentKR = "예전에, 제가 팻테일이랑 '범인 추적' 놀이를 할 때, 자기 털을 핥아서 여기저기 흩뿌려 놓고 절 헷갈리게 하는 게 걔의 특기였어요.",
          DialogueId = 80120409,
          GUID = "C892B29A",
          NextDialogue = 80120410,
          SpeakNpcId = 93301,
          Subtitle = "Back in the day, when Plumpytail and I played \"Tailing the Suspect,\" she would leave bits of furball from her grooming in different directions to throw me off. That was one of her signature tricks.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B29A"
        },
        [80120410] = {
          ContentKR = "그때는 아직 탐정 경험이 부족해서 자주 걔한테 농락당했죠. 제가 한참을 헤매다가 헉헉거리며 지쳐 있으면, 그 쬐끄만 게 고개를 높이 들고 꼬리를 치켜세우고는 제 앞에서 거만하게 왔다 갔다 하곤 했어요!",
          DialogueId = 80120410,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B2C4",
          NextDialogue = 80120411,
          SpeakNpcId = 93301,
          Subtitle = "I was such a rookie detective back then, so I always walked straight into Plumpytail's traps. By the time I was worn out from running in circles, Plumpytail would prance around with her head held high, tail swaying like she was king of the world!",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2C4"
        },
        [80120411] = {
          ContentKR = "생각나네요... 다 생각났어요... 그때 '팻테일'한테 농락당했을 때의 분노, 추적 방향을 잃어버린 괴로움, 실수로 설원에서 길을 잃었을 때의 공포... 그리고 축축한 고양이 털 한 줌을 쥐고 있을 때의 당혹감까지!",
          DialogueId = 80120411,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B2EE",
          NextOptions = {
            [1] = 801204111
          },
          SpeakNpcId = 93301,
          Subtitle = "...It's all coming back to me — the irritation of being toyed with by the \"Suspect Cat,\" the frustration of losing the trail, the panic of getting lost in the snowfields, and the bafflement of holding a handful of wet fur!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2EE"
        },
        [80120412] = {
          ContentKR = "흥! 시간도 많이 지났고 이제 전 그때의 신참 탐정이 아니에요! 게다가 아이스레이크 시티는 바로 이 탐정님의 주 무대죠. 이번엔 무슨 수를 써서라도 그 정체를 밝히고 말 거예요.",
          DialogueId = 80120412,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B318",
          NextDialogue = 80120413,
          SpeakNpcId = 93301,
          Subtitle = "Hmph! Those days are long behind me! I'm no longer the rookie I once was! Plus, Icelake is my turf now, and this time, I'm definitely going to catch the \"Suspect Cat\"!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B318"
        },
        [80120413] = {
          ContentKR = "각 골목의 지형을 바탕으로 팻테일의 은신처를 추측하는 것은 물론이고, 약간의 말린 생선을 써서 이곳의 '꼬마 길냥이'들을 매수했어요. 밖에서 온 고양이에 대한 정보를 제공하면 후하게 보상하겠다고요!",
          DialogueId = 80120413,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B342",
          NextOptions = {
            [1] = 801204131,
            [2] = 801204141
          },
          SpeakNpcId = 93301,
          Subtitle = "I've been mapping out the possible hiding spots based on the alley layouts and even bribed the local strays with fish treats. Anyone who can provide a lead on this outsider cat will be handsomely rewarded!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B342"
        },
        [80120414] = {
          ContentKR = "잡았다 요놈! 거짓 정보를 제공한 하얀 털 큰 고양이! 벌로 보름 동안 말린 생선을 못 먹을 줄 알아!",
          DialogueId = 80120414,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B36C",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Aha! Caught a white-furred big cat spreading false alarms! As punishment, no fish treats for half a month!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B36C"
        },
        [80120415] = {
          ContentKR = "헤헤, 이렇게 칭찬한다고 해서, 헤헤, 기분 좋아지진 않는다고요, 헤헤!",
          DialogueId = 80120415,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B396",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Hehe, even if you flatter me like that... hehe, I won't let it go to my head, hehe!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B396"
        },
        [80120416] = {
          ContentKR = "흠흠, 본론으로 돌아와서... 정밀한 추리 끝에 마침내 종이 상자가 가득한 작은 골목에서 팻테일을 찾아냈어요. 밖에서 사는 고양이에게 종이 상자 더미라니, 그냥 넘어갈 리가 없죠!",
          DialogueId = 80120416,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B3C0",
          NextDialogue = 80120417,
          SpeakNpcId = 93301,
          Subtitle = "Ahem, as I was saying... my detailed deductions finally led me to a narrow alley full of cardboard boxes — it's like an irresistible paradise for a cat used to living in the wild!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3C0"
        },
        [80120417] = {
          ContentKR = "역시나 용의자는 체포 당시 종이 상자 안에서 햇볕을 쬐고 있었고, 제게 꼬리를 흔들며 인사하더라고요!",
          DialogueId = 80120417,
          FacialId = {
            [1] = "93301:Happy01"
          },
          GUID = "C892B3EA",
          NextDialogue = 80120418,
          SpeakNpcId = 93301,
          Subtitle = "And sure enough, there was the suspect, basking in the sun inside a cardboard box, casually flicking her tail at me as if she owned the place!",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3EA"
        },
        [80120418] = {
          ContentKR = "이렇게 오랜만에 만났는데도, 팻테일은 그대로더라고요. 하지만 또 한 편으로는 예전과는 조금 달라 보였어요...",
          DialogueId = 80120418,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B414",
          NextDialogue = 80120419,
          Scripts = "PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "It's been so long, yet Plumpytail was still the same Plumpytail I knew... No, actually, she seemed a bit different this time.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B414"
        },
        [80120419] = {
          ContentKR = "우리가 헤어질 때만 해도 팻테일은 막 성체가 됐었는데, 당시엔 다른 사람이 만지는 걸 별로 좋아하지 않았어요. 기분이 안 좋으면 순식간에 사라져 버리곤 했죠. 이번에 만나보니 많이 성숙해진 것 같아요. 심지어 좀 늙어 보이기까지 해요.",
          DialogueId = 80120419,
          GUID = "C892B43E",
          NextDialogue = 80120420,
          SpeakNpcId = 93301,
          Subtitle = "When we last parted, Plumpytail had just grown up and didn't like being petted — one wrong move, and she'd vanish in a flash. But today, she seemed more mature, almost like an old cat.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B43E"
        },
        [80120420] = {
          ContentKR = "'나이 들면 성격이 좋아진다'는 말이 동물에게도 통하는 지는 모르겠지만 제가 가장 좋아하는 육포를 가져가지 않았는데도 녀석은 눈을 감고 배도 만지고 발도 만지고 꼬리도 다 만지게 놔두더라고요.",
          DialogueId = 80120420,
          GUID = "C892B468",
          NextDialogue = 80120421,
          SpeakNpcId = 93301,
          Subtitle = "Does \"mellow with age\" also apply to animals? Even without her favourite jerky, she let me pet her all over — belly rubs, paw squeezes, tail strokes and all.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B468"
        },
        [80120421] = {
          ContentKR = "이번엔 팻테일이 새끼 고양이 몇 마리를 데리고 절 찾아왔어요. 다만 걔네들은 어릴 때 팻테일처럼 겁이 많아서 상자 안에서 작은 머리만 내밀고 훔쳐보더라고요. 하지만 털 색만 봐도 팻테일이 잘 돌봐줬다는 걸 알겠더라고요!",
          DialogueId = 80120421,
          GUID = "C892B492",
          NextDialogue = 80120422,
          Scripts = "SEQ{PlayAnimation{ActorId{93301},AnimationId{\"Sit_Talk01_Start\"},Duration{1}},PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_Talk01_End\"},Duration{1}}}",
          SpeakNpcId = 93301,
          Subtitle = "This time, Plumpytail even brought a few kittens along. They're just as timid as Plumpytail used to be, peeking their little heads out from the box. But just from their fur, I could tell Plumpytail has been taking great care of them!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B492"
        },
        [80120422] = {
          ContentKR = "정말 감회가 새로워요... 설원 쥐도 잡지 못하던 그 멍청한 고양이가 이제는 새끼 고양이들도 잘 키우게 되었다니!",
          DialogueId = 80120422,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4BC",
          NextOptions = {
            [1] = 801204221
          },
          SpeakNpcId = 93301,
          Subtitle = "It's amazing... that clumsy cat who couldn't even catch a snowfield rat is now providing for a whole litter of kittens of her own!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4BC"
        },
        [80120423] = {
          ContentKR = "그렇게 말씀하시니까 그러네요. 저랑 팻테일 모두 만났을 때보다 더 성장했어요. 헤헤... 좀 쑥스럽네요...",
          DialogueId = 80120423,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4E6",
          NextDialogue = 80120424,
          SpeakNpcId = 93301,
          Subtitle = "You're right... we've both grown since we first met. Hehe... it's kinda embarrassing to admit though...",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4E6"
        },
        [80120424] = {
          ContentKR = "솔직히 말씀드리자면, 아이스레이크 시티에 처음 왔을 때는 지금처럼 다 할 수 있지 않았어요. 또 그때는 자주 울었거든요... 아, 제발 비웃지 마세요!",
          DialogueId = 80120424,
          GUID = "C892B510",
          NextDialogue = 80120425,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "Actually, when I first came to Icelake, I was such a crybaby — hey, don't you dare make fun of me!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B510"
        },
        [80120425] = {
          ContentKR = "몇 번이나 아이스레이크 시티를 떠나고 싶었어요. 마치 처음부터 여기 오지 않았던 것처럼요. 팻테일이랑 같이 돌아다니는 것도 나쁘지 않을 것 같았죠.",
          DialogueId = 80120425,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B53A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204251
          },
          SpeakNpcId = 93301,
          Subtitle = "I thought about leaving Icelake more than once. I figured I could just pretend I'd never come and wander the world with Plumpytail, which seemed pretty great.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B53A"
        },
        [80120426] = {
          ContentKR = "마틴 할배는 항상 도시가 좋은 곳이라고 했어요. 그래서 저도 그렇게 믿었죠. 전 도시가 서로 의지하고 지켜주는 피난처라고 생각했거든요.",
          DialogueId = 80120426,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B564",
          NextDialogue = 80120427,
          SpeakNpcId = 93301,
          Subtitle = "Old Martin always said the city was a good place, so I believed it too. I imagined a \"city\" as a sanctuary where torch-bearing folks huddle together for warmth and protection.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B564"
        },
        [80120427] = {
          ContentKR = "그런데 말이에요. 이 피난처에는 정말 말도 안 되는 일들이 많더라고요. 카론들은 이유도 없이 차별받고, 부자들은 평생 입어도 못 다 입을 모피를 가진 반면, 빈민가 사람들은 이번 겨울을 넘길 수 있을지도 모르고...",
          DialogueId = 80120427,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B58E",
          NextDialogue = 80120428,
          SpeakNpcId = 93301,
          Subtitle = "But... Ugh! The things that go on in this \"sanctuary\" are just absurd. Charons are discriminated against for no reason; rich folks have more furs than they could wear in a lifetime, while the poor in the slums might not even survive the cold winter...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B58E"
        },
        [80120428] = {
          ContentKR = "게다가 팻테일이 너무 보고 싶었어요. 어차피 어디에나 장단점이 있는데, 제가 제일 좋아하는 팻테일이랑 함께 있는 게 낫지 않을까 싶었죠.",
          DialogueId = 80120428,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B5B8",
          NextOptions = {
            [1] = 801204281,
            [2] = 801204291
          },
          SpeakNpcId = 93301,
          Subtitle = "And I just missed Plumpytail so much! I figured, every place has its good and bad, so why not just stick with my favourite cat?",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5B8"
        },
        [80120429] = {
          ContentKR = "그요? 설마 울진 않으실 거예요... 아마도요. 어쨌든 전 아직 아이스레이크 시티에 잘 있잖아요!",
          DialogueId = 80120429,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B5E2",
          NextDialogue = 80120431,
          Scripts = "PlayAnimation{_delay{1},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "Huh? He wouldn't... um, maybe... Anyway, I'm still here in Icelake, aren't I?",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5E2"
        },
        [80120430] = {
          ContentKR = "지금 생각해보면 그냥 어려움을 만나면 도망치고 싶어 하는 어린애 같은 생각이었어요.",
          DialogueId = 80120430,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B60C",
          NextDialogue = 80120431,
          SpeakNpcId = 93301,
          Subtitle = "Yeah, now that I think about it, I was just a kid trying to run away from problems.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B60C"
        },
        [80120431] = {
          ContentKR = "그때 정말 그렇게 했어요. 한번은 솔라 아이들에게 돌을 맞았는데, 너무 화가 나서 정신없이 도시 밖으로 달렸죠. 팻테일을 부르면서 계속 달렸어요.",
          DialogueId = 80120431,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892B636",
          NextDialogue = 80120432,
          SpeakNpcId = 93301,
          Subtitle = "I actually did it once. One time, some Sola kids threw rocks at me, and I got so mad that I ran straight for the city gate. I just kept running, calling out for Plumpytail.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B636"
        },
        [80120432] = {
          ContentKR = "그러다 정말 팻테일을 만났어요. 스노우 울프랑 싸우고 있었는데, 은빛 쥐를 놓고 다투고 있더라고요. 둘 다 그걸 사냥감으로 노리고 있었거든요.",
          DialogueId = 80120432,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B660",
          NextDialogue = 80120433,
          SpeakNpcId = 93301,
          Subtitle = "And then... I did run into Plumpytail. She was fighting a snow wolf over a silverback vole.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B660"
        },
        [80120433] = {
          ContentKR = "팻테일이 배고파 보여서 육포를 던져줬는데, 쳐다보지도 않더라고요. 오직 사냥감과 적만 보이는 것 같았어요.",
          DialogueId = 80120433,
          GUID = "C892B68A",
          NextDialogue = 80120434,
          SpeakNpcId = 93301,
          Subtitle = "I figured Plumpytail must've been starving, so I threw her a piece of jerky. But she didn't even look at it. Her eyes were fixed only on her prey and her enemy.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B68A"
        },
        [80120434] = {
          ContentKR = "결국 팻테일이 스노우 울프를 이겼는데 거만하게 걸어와서 저한테 \"야옹\", \"야옹\" 하고 울는 거 있죠. 자랑하는 건지, 절 반기는 건지 모르겠더라고요.",
          DialogueId = 80120434,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B6B4",
          NextDialogue = 80120435,
          SpeakNpcId = 93301,
          Subtitle = "In the end, Plumpytail won. She strutted over to me all proud-like, meowing — either showing off or maybe just happy to see me after so long.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6B4"
        },
        [80120435] = {
          ContentKR = "전 팻테일의 부드러운 머리를 쓰다듬으면서 말했어요. \"팻테일, 나 너랑 같이 갈래. 우리 앞으로 함께 살자.\"",
          DialogueId = 80120435,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B6DE",
          NextDialogue = 80120436,
          SpeakNpcId = 93301,
          Subtitle = "I petted her fluffy head and said, \"Plumpytail, I'll go with you. Let's live together in the snowfields.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6DE"
        },
        [80120436] = {
          ContentKR = "하지만 팻테일은 절 데려가지 않았어요. 오히려 제 품에서 후다닥 빠져나가더니 아이스레이크 시티 방향으로 계속 야옹야옹 울어대기 시작했죠.",
          DialogueId = 80120436,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B708",
          NextDialogue = 80120437,
          SpeakNpcId = 93301,
          Subtitle = "But Plumpytail didn't take me to her home. She darted out of my arms and kept meowing in one direction — it was the direction of Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B708"
        },
        [80120437] = {
          ContentKR = "그때 생각했어요. 아마도 팻테일은 제게 설원이 아니라 아이스레이크 시티가 제 집이라고 말하는 것 같았어요.",
          DialogueId = 80120437,
          GUID = "C892B732",
          NextDialogue = 80120438,
          SpeakNpcId = 93301,
          Subtitle = "I guess she was trying to tell me the snowfields weren't my home, and I belonged to Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B732"
        },
        [80120438] = {
          ContentKR = "그리고 갑자기 깨달았어요. 제가 먹이를 주고 있어도 팻테일은 여전히 열심히 사냥하고 있었다는 걸요. 그게 바로 팻테일의 생존 방식이니까요.",
          DialogueId = 80120438,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B75C",
          NextDialogue = 80120439,
          SpeakNpcId = 93301,
          Subtitle = "That's when I realised... Even with me feeding her, Plumpytail would still try her best to hunt, because that was her way of living.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B75C"
        },
        [80120439] = {
          ContentKR = "저도 제 나름의 생존 방식이 있는데, 전 도시에서의 삶을 피해 팻테일 뒤에 숨으려고 했다니... 정말 부끄러워요!",
          DialogueId = 80120439,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B786",
          NextOptions = {
            [1] = 801204391,
            [2] = 801204401
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "And I had my way of living too, but I was too chicken to face my life in the city, always thinking of running back to Plumpytail — ugh, I was such a coward!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B786"
        },
        [80120440] = {
          ContentKR = "맞아요. 그래서 팻테일의 말을 듣고 돌아왔어요. 하지만 돌아오는 길에 약간의 문제가 있었죠...",
          DialogueId = 80120440,
          GUID = "C892B7B0",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120442,
          SpeakNpcId = 93301,
          Subtitle = "Yeah. So I listened to her advice and went back. But there was a slight mishap...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B7B0"
        },
        [80120441] = {
          ContentKR = "아, 그만하세요. 마틴 할배도 절 혼내지 않았다고요! 그러고 보니 그때 꼰대가 웬일인지 걱정까지 하더라니까요. 돌아오는 길에 좀 문제가 있었거든요...",
          DialogueId = 80120441,
          FacialId = {
            [1] = "93301:Pain01"
          },
          GUID = "C892B7DA",
          NextDialogue = 80120442,
          SpeakNpcId = 93301,
          Subtitle = "Waaah, I know I messed up... I'm sorry! Not even Old Martin scolded me for that! Speaking of which, the old man was actually worried sick for once, because I ran into a little trouble on the way back...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B7DA"
        },
        [80120442] = {
          ContentKR = "전 정신없이 밖으로 뛰쳐나갔다가 길을 잃어버렸어요. 팻테일과 작별 인사를 하고 걸어오다 보니 점점 더 피곤해져서 그만... 잠들어 버렸어요.",
          DialogueId = 80120442,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B804",
          NextDialogue = 80120443,
          SpeakNpcId = 93301,
          Subtitle = "I was so mad when I ran out that I didn't even pay attention to remembering the way! So after I said goodbye to Plumpytail, I got lost... And I just kept walking, feeling more and more tired, until I fell asleep in the snow...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B804"
        },
        [80120443] = {
          ContentKR = "깨어나 보니 몸이 흔들리고 있더라고요. 알고 보니 꼰대가 절 업고 있었어요. 키는 안 커도, 등은 정말 든든했어요. 어릴 때랑 똑같이요.",
          DialogueId = 80120443,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B82E",
          NextDialogue = 80120444,
          SpeakNpcId = 93301,
          Subtitle = "I woke up to a bumpy ride — turned out that stupid old man was carrying me on his back. He's not tall, but his back is as sturdy as it was when I was little.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B82E"
        },
        [80120444] = {
          ContentKR = "온몸이 따뜻했는데, 꼰대가 인간들처럼 목도리로 절 여러 겹 감싸줬더라고요. 입까지 다 가려가면서요.",
          DialogueId = 80120444,
          GUID = "C892B858",
          NextDialogue = 80120445,
          SpeakNpcId = 93301,
          Subtitle = "I felt very warm because he had bundled me up in a long scarf, wrapping me in layer after layer, covering even my mouth, like Solas do.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B858"
        },
        [80120445] = {
          ContentKR = "제가 아이스레이크 시티에 온 후 첫 번째 도시 밖 모험은 그렇게 어영부영 끝나버렸어요.",
          DialogueId = 80120445,
          GUID = "C892B882",
          NextDialogue = 80120446,
          SpeakNpcId = 93301,
          Subtitle = "And that's how Margie's first adventure outside Icelake sloppily ended.",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B882"
        },
        [80120446] = {
          ContentKR = "그 후로 전 아이스레이크 시티에서 어떻게 살아남을지 열심히 배웠어요. 하지만 어려운 일이 생길 때마다 꼰대는 여전히 절 보고 '사냥도 못하는 팻테일 2호'라고 놀려대요.",
          DialogueId = 80120446,
          GUID = "C892B8AC",
          NextDialogue = 80120447,
          SpeakNpcId = 93301,
          Subtitle = "Since then, I've been learning how to make a life for myself in Icelake. But every time I run into trouble, that stupid old man still teases me, calling me \"Can't-catch-anything Plumpytail Junior.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B8AC"
        },
        [80120447] = {
          ContentKR = "하지만 그 말은 틀렸어요! 팻테일은 결국 훌륭한 사냥꾼이 됐고, 저도 여기서 어떻게 살아남는지 배웠어요. 말씀하신 대로, 우리 모두 성장했어요.",
          DialogueId = 80120447,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B8D6",
          NextOptions = {
            [1] = 801204471
          },
          SpeakNpcId = 93301,
          Subtitle = "But he's wrong! Plumpytail had already become a skilled hunter, and I've learned to survive here too — just like you said, we've both grown.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B8D6"
        },
        [80120448] = {
          ContentKR = "제 잘못이 아니에요, 다 팻테일 때문이라고요! 누가 해가 지기도 전에 가버리래요? 제가 마음속으로 '제발 남아 있어 줘!'라고 수없이 외쳤는데도 다 그냥 가버렸다고요...",
          DialogueId = 80120448,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B900",
          NextDialogue = 80120449,
          SpeakNpcId = 93301,
          Subtitle = "Well, it's all Plumpytail's fault! Why did she have to leave so soon!? I must've begged her to stay a thousand times in my head, yet she still left before the sun even set...",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B900"
        },
        [80120449] = {
          ContentKR = "좋아요, 더는 변명하지 않을게요. 다음에 팻테일을 만나면 웃으면서 작별 인사를 할 수 있을 거예요!",
          DialogueId = 80120449,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B92A",
          SpeakNpcId = 93301,
          Subtitle = "...Alright, no more excuses! Next time Plumpytail and I meet again, I'll see her off with a smile!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B92A"
        },
        [80130000] = {
          ContentKR = "안녕... 내 방문이 방해되지 않았으면 좋겠네...",
          DialogueId = 80130000,
          GUID = "C898D820",
          SpeakNpcId = 93103,
          Subtitle = "H—Hi... I hope I'm not being a bother...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898D820"
        },
        [80130101] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentKR = "아... 안녕하세요...",
          DialogueId = 80130101,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E8B2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130102,
          SpeakNpcId = 93103,
          Subtitle = "H—Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E8B2"
        },
        [80130102] = {
          ContentKR = "제, 제 소개를 할게요... 저... 저는 스칼렛에서 온 예일이라고 해요. 장난감 가게 '우르르쾅쾅'의 주인이에요.",
          DialogueId = 80130102,
          GUID = "C898E8DC",
          NextDialogue = 80130103,
          SpeakNpcId = 93103,
          Subtitle = "P—Please allow me to introduce myself. I... I'm Yale, from Scarletriver... I run a little shop called Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E8DC"
        },
        [80130103] = {
          ContentKR = "'우르르쾅쾅'에선 폭발하는 작은 장난감들을 다양하게 판매하고 있어요. 꼬마들이 저희 가게를 아주 많이 좋아해요...",
          DialogueId = 80130103,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898E906",
          NextDialogue = 80130104,
          SpeakNpcId = 93103,
          Subtitle = "We sell, um... little toys that explode... in a fun way! The kids in Scarletriver love them...",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E906"
        },
        [80130104] = {
          ContentKR = "이건 저희 가게의 제품 리스트에요. 관심 있으시면 메시지를 보내주세요. 직접 배달해 드릴게요.",
          DialogueId = 80130104,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E930",
          NextDialogue = 80130105,
          SpeakNpcId = 93103,
          Subtitle = "Here's a catalogue of our products. If anything catches your eye, just drop us a note. We do home delivery as well...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E930"
        },
        [80130105] = {
          ContentKR = "그럼, 너무 늦으면... 위험할 수 있으니, 이만 돌아가 볼게요. ",
          DialogueId = 80130105,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898E95A",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801301051,
            [2] = 801301052
          },
          SpeakNpcId = 93103,
          Subtitle = "Er... I should get going. It's not safe to stay out too late...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E95A"
        },
        [80130106] = {
          ContentKR = "그럼 좀 더 있을게요...",
          DialogueId = 80130106,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E984",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          Subtitle = "O—Okay... I can stay a little longer...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E984"
        },
        [80130107] = {
          ContentKR = "저기... 기분이 좀 상하신 것 같은데, 제가 예의 없게 굴었나 봐요. 죄송해요, 일부러 그런 건 아닌데...",
          DialogueId = 80130107,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E9AE",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          Subtitle = "You look upset... I—I'm sorry... Did I say something wrong? I didn't mean to...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9AE"
        },
        [80130108] = {
          ContentKR = "아, 됐어, 그냥 내가 할게. 오기 전엔 분명 안 무섭다면서, '우르르쾅쾅' 장난감을 꼭 아이스레이크 시티에 팔겠다고 했잖아. ",
          DialogueId = 80130108,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898E9D8",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130109,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh, for crying out loud — move over. Didn't you swear you wouldn't chicken out this time? That you'd pitch our toys to Icelake?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9D8"
        },
        [80130109] = {
          ContentKR = "결국 이 모양이라니, 역시 내가 나서야겠군.",
          DialogueId = 80130109,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA02",
          NextDialogue = 80130110,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "And now look at you! Ugh, looks like I'll have to bail you out again.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA02"
        },
        [80130110] = {
          ContentKR = "미... 미안. 저분이 아이스레이크 시티에서 유명한 월석 사냥꾼이라고 생각하니까, 겁이 나서 어떻게 입을 열어야 할지 모르겠어...",
          DialogueId = 80130110,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA2C",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130111,
          SpeakNpcId = 93103,
          Subtitle = "I—I'm sorry... It's just... {性别：he|she}'s a really famous Phoxhunter in Icelake... I got nervous...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA2C"
        },
        [80130111] = {
          ContentKR = "뭐가 무서워, 쟤가 사람을 잡아먹는 것도 아니고, 그냥 평소에 꼬맹이들 대하듯이 말하면 돼. ",
          DialogueId = 80130111,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA56",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801301111,
            [2] = 801301112
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Don't be a chicken. {性别：He|She}'s not gonna eat you alive. Just talk to {性别：him|her} like you talk to the kids at our shop.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA56"
        },
        [80130112] = {
          ContentKR = "......",
          DialogueId = 80130112,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA80",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130113,
          SpeakNpcId = 93103,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA80"
        },
        [80130113] = {
          ContentKR = "하나도 안 무서워요, 절 편하게 해주려는 거죠? 고마워요.",
          DialogueId = 80130113,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EAAA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          Subtitle = "That wasn't scary at all. You were just trying to help me relax, right? Thank you...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAAA"
        },
        [80130114] = {
          ContentKR = "치... 치유계 월석 사냥꾼이요? 그런 이름을 들은 적은 없지만, 확실히 제가 상상했던 그 거대하고, 폭탄보다 더 큰 목소리를 가진 월석 사냥꾼하고는 다르네요.",
          DialogueId = 80130114,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898EAD4",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          Subtitle = "H...heartwarming type...? I've never heard of that type before, but you're definitely not what I pictured — you know, huge, louder than a bomb...",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAD4"
        },
        [80130115] = {
          ContentKR = "그럼, 소개해 드릴게요. 얘는 올리버, 제 친구예요. 연금술사한테 당해서 이 폭탄 안에 갇혔어요.",
          DialogueId = 80130115,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EAFE",
          NextDialogue = 80130116,
          SpeakNpcId = 93103,
          Subtitle = "Anyway, let me introduce my friend. This is Oliver. He, um, lives in this bomb. An alchemist sealed him inside...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAFE"
        },
        [80130116] = {
          ContentKR = "아까 말씀드린 '우르르쾅쾅'은 사실 올리버와 함께 운영하는 가게예요. 저는 손님을 상대하고 올리버는 신제품 개발을 담당하고 있어요.",
          DialogueId = 80130116,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EB28",
          NextDialogue = 80130117,
          SpeakNpcId = 93103,
          Subtitle = "We run Snap 'n' Spark together: I serve customers, and he comes up with new products.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB28"
        },
        [80130117] = {
          ContentKR = "하지만 예일은 종종 말을 하다가 막힐 때가 있어서, 내가 대신 손님들을 상대하기도 해. 바로 오늘처럼.",
          DialogueId = 80130117,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB52",
          NextDialogue = 80130118,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Let's be real — Yale freezes halfway through his pitch more often than not, so I end up handling the talking too, like today.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB52"
        },
        [80130118] = {
          ContentKR = "아까 예일이 말했듯이, '우르르쾅쾅'에서는 폭발하는 작은 장난감을 판매하고 있어. 지난달 우리 가게 제품 중 인기 TOP 3는 폭발 비행선, 하늘높이 폭죽, 그리고 폭발 팽이였지.",
          DialogueId = 80130118,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB7C",
          NextOptions = {
            [1] = 801301181,
            [2] = 801301182
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "He already mentioned we sell explosive little toys. Last month's top three sellers were: Boom-Blimp, Whizpop Firework, and Kaboom-Spinner.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB7C"
        },
        [80130119] = {
          ContentKR = "조급해하지 말라고, 더 폭발적인 상품을 곧 소개할 테니까.",
          DialogueId = 80130119,
          GUID = "C898EBA6",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Tsk, hear me out first — I haven't even gotten to the real boom yet!",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBA6"
        },
        [80130120] = {
          ContentKR = "오... 이런 거 좋아해? 사실 아까 그것들은 그냥 밑밥일 뿐이었고, 우리가 진짜로 너한테 팔고 싶은 건 이거야.",
          DialogueId = 80130120,
          GUID = "C898EBD0",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Heh... so you're interested, huh? Well, those were just the warm-up. What we really want to show you is this—",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBD0"
        },
        [80130121] = {
          ContentKR = "겉보기에는 무해한 알람 시계처럼 보이지만, 사실 위력은 엄청나지. 단 한 발로 눈에 거슬리는 모든 것을 날려버릴 수 있는 초고에너지 폭탄, '샤터드 스타즈'라고.",
          DialogueId = 80130121,
          GUID = "C898EBFA",
          NextDialogue = 80130122,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Looks like an ordinary alarm clock, right? But just one of these — and boom, all your troubles go up in smoke. Introducing: the Starshatterer.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBFA"
        },
        [80130122] = {
          ContentKR = "넌 스칼렛에서 꽤 잘나가는 월석 사냥꾼이라고 들었어. 분명히 이런 물건이 필요할 거야.",
          DialogueId = 80130122,
          GUID = "C898EC24",
          NextDialogue = 80130123,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Word about you's even made it to Scarletriver. Bet an awesome Phoxhunter like you could use a little extra firepower.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC24"
        },
        [80130123] = {
          ContentKR = "폭탄 이름을 기억하기 어렵다면 그냥 귀요미라고 불러주세요. 제가 지은 이름인데, 제국 병사들이 그냥 장난감이라고 생각해서 경계심을 풀게 만들 수 있어요.",
          DialogueId = 80130123,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EC4E",
          NextDialogue = 80130124,
          SpeakNpcId = 93103,
          Subtitle = "If the name's too hard to remember, you can just call them Tot Poppers. That's what I call them... it helps throw off Empire soldiers... makes them think it's just some kid's toy, so they drop their guard.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC4E"
        },
        [80130124] = {
          ContentKR = "그리고 위에 있는 그림도 제가 그린 거예요. 음, 이렇게 하면 이 차가운 폭탄들이 덜 무섭게 보이거든요.",
          DialogueId = 80130124,
          GUID = "C898EC78",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130125,
          SpeakNpcId = 93103,
          Subtitle = "And the little drawings on the casings — they're also from me... This way the bombs look a bit less scary...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC78"
        },
        [80130125] = {
          ContentKR = "휴, 몇 번을 말하는 거야. 폭탄을 사려는 손님들은 그 폭발 순간을 보고 싶어 하는 사람들이야. 폭탄 표면의 무늬 따위엔 관심 없다고.",
          DialogueId = 80130125,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECA2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130126,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ugh. How many times do I have to say it? People who buy bombs just want a good BOOM, not some cutesy nonsense.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECA2"
        },
        [80130126] = {
          ContentKR = "하지만 난 이게 우리 제품을 더 특별하게 만든다고 생각해. 게다가 내가 무늬를 그릴 때, 너도 신나 하면서 어떻게 하면 고객들이 더 좋아할지에 대해 조언해 줬잖아.",
          DialogueId = 80130126,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ECCC",
          NextDialogue = 80130127,
          SpeakNpcId = 93103,
          Subtitle = "But I think the drawings make our products stand out. And when I was sketching them, you were the one shouting all those tips about how to make them even cuter...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECCC"
        },
        [80130127] = {
          ContentKR = "그... 그건 어차피 그릴 거면 잘 그려야 하니까 그런 거지. 그림이 너무 엉망이면 안 팔릴 거 아니야!",
          DialogueId = 80130127,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECF6",
          NextDialogue = 80130128,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I... I only did that so you wouldn't botch it, all right? If the logo's ugly, no one's gonna buy them — duh!",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECF6"
        },
        [80130128] = {
          ContentKR = "흠흠, 아무튼 할 얘긴 다 했으니 필요하면 연락해. '샤터드 스타즈'를 사고 싶다고 우리한테 편지를 보내면 돼.",
          DialogueId = 80130128,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED20",
          NextDialogue = 80130129,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ahem. Anyway — that's our big sales pitch. If you'd like to place an order, just send us a note.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED20"
        },
        [80130129] = {
          ContentKR = "대신 편지에는 '귀요미'라고 쓰는 걸 잊지 마. 안 그러면 발각될 수 있으니까.",
          DialogueId = 80130129,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED4A",
          NextDialogue = 80130130,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But make sure you write Tot Poppers on your order, not Starshatterers. Otherwise... we'll both be in hot water.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED4A"
        },
        [80130130] = {
          ContentKR = "가게 위치는 제가 드린 제품 리스트에 있어요. 그럼, 주문 기다릴게요.",
          DialogueId = 80130130,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ED74",
          NextDialogue = 80130131,
          SpeakNpcId = 93103,
          Subtitle = "Our shop address is on the catalogue. We'll be waiting for your order...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED74"
        },
        [80130131] = {
          ContentKR = "스칼렛의 예일과 올리버, 인상 깊은 콤비다. 여유로울 때 작은 장난감 몇 개를 사보자. 폭발 팽이와 하늘높이 폭죽 모두 꽤 흥미가 당긴다...",
          DialogueId = 80130131,
          GUID = "C898ED9E",
          Subtitle = "Yale and Oliver — the unforgettable duo from Scarletriver. If you ever have the chance, why not pick up a few of their creations? Those Kaboom Spinners and Whizpop Fireworks sound like an absolute blast...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED9E"
        },
        [80130201] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentKR = "안녕하세요...",
          DialogueId = 80130201,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F91A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130202,
          SpeakNpcId = 93103,
          Subtitle = "Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F91A"
        },
        [80130202] = {
          ContentKR = "저 기억하세요? '우르르쾅쾅'의 주인, 예일이에요.",
          DialogueId = 80130202,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898F944",
          NextOptions = {
            [1] = 801302021,
            [2] = 801302022
          },
          SpeakNpcId = 93103,
          Subtitle = "Do you remember me? I'm Yale, from Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F944"
        },
        [80130203] = {
          ContentKR = "그... 그때는 서로 잘 몰라서... 이제는 괜찮아요.",
          DialogueId = 80130203,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F96E",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Th—That was because we barely knew each other then. It's better now.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F96E"
        },
        [80130204] = {
          ContentKR = "음... 확실히 올리버는 저보다 말수가 많은 편이죠.",
          DialogueId = 80130204,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F998",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Mm... He's always been much better at talking than I am.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F998"
        },
        [80130205] = {
          ContentKR = "오늘은 일이 좀 있어서, 올리버를 데려오지 않았어요. ",
          DialogueId = 80130205,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898F9C2",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130206,
          SpeakNpcId = 93103,
          Subtitle = "I came by myself today, though.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9C2"
        },
        [80130206] = {
          ContentKR = "싸운 건 아니니까 오해하진 마세요. 저희 둘은 사이가 정말 좋아요. 그래서 오히려 어떤 말은 누구한테 얘기해야 될지 모르겠더라고요...",
          DialogueId = 80130206,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898F9EC",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130207,
          SpeakNpcId = 93103,
          Subtitle = "It's not that we had a fight or anything — Oliver and I get along just fine. Which... might be exactly why there are things I can't quite say to him.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9EC"
        },
        [80130207] = {
          ContentKR = "그래서 이렇게 무례하게 찾아온 거예요. 답을 바라는 건 아니고, 그냥 제 이야기만 들어주시면 돼요. 아무래도 남의 이야기를 잘 들어주실 것 같아서요...",
          DialogueId = 80130207,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FA16",
          NextDialogue = 80130208,
          SpeakNpcId = 93103,
          Subtitle = "So... I thought maybe... I could tell you instead. N—No pressure — I'm not here asking for advice. I... just need someone to listen. And... you seemed like a good listener.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA16"
        },
        [80130208] = {
          ContentKR = "사실 '우르르쾅쾅'의 첫 번째 주인은 저도 아니고 올리버도 아니었어요. 아주 성격이 나쁜 할아버지셨죠.",
          DialogueId = 80130208,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FA40",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130209,
          SpeakNpcId = 93103,
          Subtitle = "I never told you this, but Snap 'n' Spark wasn't ours to begin with. It belonged to a very, very grumpy old man.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA40"
        },
        [80130209] = {
          ContentKR = "그분은 참을성이 없어서 항상 저한테 이래라저래라 강요하셨어요. 저는 늘 제대로 해내지 못했고요. 그래도 그분 밑에서 어찌어찌 가게 운영하는 법을 배웠죠.",
          DialogueId = 80130209,
          FacialId = {
            [1] = "93103:Unhappy01"
          },
          GUID = "C898FA6A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130210,
          SpeakNpcId = 93103,
          Subtitle = "He yelled a lot... always bossing me around. I messed up a lot of things at first... But after a while, even through all the shouting... I started to pick up how to run the place.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA6A"
        },
        [80130210] = {
          ContentKR = "그런데 어느 날 갑자기 그분이 아주 먼 곳으로 가야 한다고 하시면서, '우르르쾅쾅'을 저한테 맡기셨어요.",
          DialogueId = 80130210,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FA94",
          NextDialogue = 80130211,
          SpeakNpcId = 93103,
          Subtitle = "Then one day he simply announced he was off somewhere far away — and left the place to me.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA94"
        },
        [80130211] = {
          ContentKR = "그 이후로는 혼자서 가게를 운영했어요. 그 할아버지가 없으니 새로운 장난감을 어떻게 만들어야 할지 몰라서, 그냥 있는 재고로 겨우겨우 버텼죠.",
          DialogueId = 80130211,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FABE",
          NextOptions = {
            [1] = 801302111,
            [2] = 801302112
          },
          SpeakNpcId = 93103,
          Subtitle = "After that, it was just me. Without him there... I didn't really know how to make new toys anymore. So I just kept selling whatever stock he'd left behind...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FABE"
        },
        [80130212] = {
          ContentKR = "음... 저도 참 이상하다고 생각해요. 그렇게 갑자기 사라지시다니요.",
          DialogueId = 80130212,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FAE8",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "I... I didn't understand it either. It all happened so suddenly.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FAE8"
        },
        [80130213] = {
          ContentKR = "감사합니다. 그땐 정말 매일매일 여러 가지를 배우려고 애썼어요.",
          DialogueId = 80130213,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FB12",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "Thank you... I really did try my best to learn everything I could back then.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB12"
        },
        [80130214] = {
          ContentKR = "아무튼 그렇게 몇 달이 지나고 못 보던 어른들이 아이를 데리고 장난감을 사러 오면서, '우르르쾅쾅'의 장사가 점점 나아지더라고요.",
          DialogueId = 80130214,
          FacialId = {
            [1] = "93103:Happy01"
          },
          GUID = "C898FB3C",
          NextDialogue = 80130215,
          SpeakNpcId = 93103,
          Subtitle = "Anyway... a few months passed. More parents came in with their kids, business was finally picking up...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB3C"
        },
        [80130215] = {
          ContentKR = "그런데 그때 갑자기 저랑 나이가 비슷한 남자애가 온 거예요. 처음에는 그냥 평범한 손님인 줄 알고 장난감을 추천해 주려고 했죠.",
          DialogueId = 80130215,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FB66",
          NextDialogue = 80130216,
          SpeakNpcId = 93103,
          Subtitle = "Then one day a boy about my age showed up. I thought he was just another customer, so I started recommending toys.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB66"
        },
        [80130216] = {
          ContentKR = "그런데 그 애가 차갑게 말하더라고요. '우르르쾅쾅'는 그 할아버지의 가게가 아니라, 자기한테 빼앗아 간 가게라고요.",
          DialogueId = 80130216,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FB90",
          NextDialogue = 80130217,
          SpeakNpcId = 93103,
          Subtitle = "But he just looked at me and said, in this cold voice, that Snap 'n' Spark wasn't the old man's shop at all — that he had stolen it from him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB90"
        },
        [80130217] = {
          ContentKR = "처음에는 당연히 안 믿었죠. 근데 그 애는 가게 안팎을 정말 잘 알고 있었어요. 곧장 가게의 작업대로 들어가서 여러 도구를 집어 들더라고요.",
          DialogueId = 80130217,
          GUID = "C898FBBA",
          NextDialogue = 80130218,
          SpeakNpcId = 93103,
          Subtitle = "I didn't believe him at first. But then he marched straight to the workbench, picked up the tools like he'd been using them forever...",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBBA"
        },
        [80130218] = {
          ContentKR = "원래는 이 폭발물들이 위험하다고 알려주려고 했는데, 금세 폭탄을 만들어 냈어요. 사라진 할아버지보다도 솜씨가 더 능숙해 보이더라고요.",
          DialogueId = 80130218,
          GUID = "C898FBE4",
          NextDialogue = 80130219,
          SpeakNpcId = 93103,
          Subtitle = "I tried to warn him that the materials were dangerous and not to mess with them — but before I could even finish, he had already put together a bomb. Faster than the old man ever could.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBE4"
        },
        [80130219] = {
          ContentKR = "그러고 나서 엄청나게 거친 말투로, 할아버지는 도둑이라고, 그리고 저도 도둑이라고 했어요.",
          DialogueId = 80130219,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FC0E",
          NextDialogue = 80130220,
          SpeakNpcId = 93103,
          Subtitle = "He looked at me — and, in this really harsh, accusing voice — said the old man was a thief... and that I was one too.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC0E"
        },
        [80130220] = {
          ContentKR = "인정하고 싶진 않지만, 이 가게에 대해 그 정도로 잘 안다면 정말로 '우르르쾅쾅'의 원래 주인이 맞는 것 같아요.",
          DialogueId = 80130220,
          GUID = "C898FC38",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130221,
          SpeakNpcId = 93103,
          Subtitle = "I didn't want to believe him. But the way he handled everything... it felt like... he really belonged there. Like he was the real owner all along.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC38"
        },
        [80130221] = {
          ContentKR = "그래서... 그래서 저는...",
          DialogueId = 80130221,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FC62",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302211,
            [2] = 801302212
          },
          SpeakNpcId = 93103,
          Subtitle = "So... now I...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC62"
        },
        [80130222] = {
          ContentKR = "네, 맞아요. 저는 이 일들이 진짜인지 가짜인지 알고 싶어요. 그러고 나서 '우르르쾅쾅'을 돌려줄지 말지 결정하려고 해요.",
          DialogueId = 80130222,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FC8C",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "Yes. If what he said is true... maybe I should give Snap 'n' Spark back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC8C"
        },
        [80130223] = {
          ContentKR = "만약 그 애 말이 사실이라면... 그럴 생각이에요. ",
          DialogueId = 80130223,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FCB6",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "If he really was the owner... then I think I should.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCB6"
        },
        [80130224] = {
          ContentKR = "하지만 두렵기도 해요. 만약 그 애가 확실히 '우르르쾅쾅' 진짜 주인이라면 어떻게 해야 될지. ",
          DialogueId = 80130224,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FCE0",
          NextDialogue = 80130225,
          SpeakNpcId = 93103,
          Subtitle = "The truth is, I'm scared. B—but... if he really is the true owner of Snap 'n' Spark... what am I supposed to do?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCE0"
        },
        [80130225] = {
          ContentKR = "이 가게를 포기하긴 사실 아쉽거든요... 겨우 아이들하고 인사하고, 새로운 장난감을 추천하는 일에 익숙해졌는데, 그 애가 과연 이런 걸 할 수 있을까요? ",
          DialogueId = 80130225,
          GUID = "C898FD0A",
          NextDialogue = 80130226,
          SpeakNpcId = 93103,
          Subtitle = "I've grown so attached to the place... I worked really hard — learning how to greet customers, recommend toys, get better at talking to other kids... Could he do all that too?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD0A"
        },
        [80130226] = {
          ContentKR = "그리고, 제가 어떻게 보상해 줘야 할까요... 그 애가 왜 '우르르쾅쾅'을 떠났는지는 모르지만, 그래도 전 보상해 주고 싶은 마음이에요...",
          DialogueId = 80130226,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FD34",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130227,
          SpeakNpcId = 93103,
          Subtitle = "And if it was his shop all along... how could I ever make it up to him? I don't know why he left in the first place, but... it just feels wrong.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD34"
        },
        [80130227] = {
          ContentKR = "자신의 가게를 잃고, 돌아와 보니 가게에 이미 다른 주인이 있다는 걸 아는 기분... 정말 힘들 거예요.",
          DialogueId = 80130227,
          GUID = "C898FD5E",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302271
          },
          SpeakNpcId = 93103,
          Subtitle = "Imagine losing your own shop, then coming back to find a stranger behind the counter... I can't even picture how awful that must feel...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD5E"
        },
        [80130229] = {
          ContentKR = "전 그 애를 잘 알아요. 그 애는 분명히 저를 호되게 욕할 거예요. 바보 아니냐고, 가게 주인이 됐으면 운영이나 잘할 것이지, 왜 남한테 공짜로 넘겨줄 생각을 하냐고요.",
          DialogueId = 80130229,
          FacialId = {
            [1] = "93103:Confident02"
          },
          GUID = "C898FDB2",
          NextDialogue = 80130230,
          SpeakNpcId = 93103,
          Subtitle = "I know exactly what he'd say: yell at me, call me an idiot, insist I'm the rightful owner now — tell me to focus on running it better instead of handing it over.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDB2"
        },
        [80130230] = {
          ContentKR = "그리고, 못 하게 할 거예요... 입은 거칠지만, 실은 착한 애거든요. ",
          DialogueId = 80130230,
          FacialId = {
            [1] = "93103:Syouganai01"
          },
          GUID = "C898FDDC",
          NextDialogue = 80130231,
          SpeakNpcId = 93103,
          Subtitle = "He'd definitely try to stop me... But I know — underneath it all, he's actually really kind.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDDC"
        },
        [80130231] = {
          ContentKR = "음... 그 원래 주인은 착한 사람이에요. 착한 사람이 매번 나쁜 일만 겪으면 안 돼요. 좋은 마음으로 따뜻하게 대해 주는 사람도 있어야죠.",
          DialogueId = 80130231,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE06",
          NextDialogue = 80130232,
          SpeakNpcId = 93103,
          Subtitle = "But... that boy was a good person too. And I don't think good people should always get the short end of the stick. Someone ought to do right by him as well.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE06"
        },
        [80130232] = {
          ContentKR = "차 잘 마셨어요. 덕분에 생각을 정리할 수 있었어요... 고맙습니다, 이제 스칼렛으로 돌아갈게요.",
          DialogueId = 80130232,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C898FE30",
          NextDialogue = 80130233,
          SpeakNpcId = 93103,
          Subtitle = "Thanks for the tea. I think I know what I need to do now. Really — thank you. I'll head back to Scarletriver.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE30"
        },
        [80130233] = {
          ContentKR = "아참, 만약 '우르르쾅쾅' 장난감을 더 사고 싶으시면, 평소처럼 편지를 보내주시면 돼요. 이 가게는 계속 운영될 거예요.",
          DialogueId = 80130233,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE5A",
          NextDialogue = 80130234,
          SpeakNpcId = 93103,
          Subtitle = "Oh! And if you still want to order something from Snap 'n' Spark, just send a letter. The shop's staying open either way.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE5A"
        },
        [80130234] = {
          ContentKR = "예일은 급히 뛰어나가 버렸다. 아무래도 그는 '우르르쾅쾅'을 갑자기 나타난 그 옛 주인에게 돌려주기로 마음먹은 것 같다. ",
          DialogueId = 80130234,
          GUID = "C898FE84",
          IsBlack = 1,
          Subtitle = "Yale hurries off — clearly, he's made up his mind to return Snap 'n' Spark to its rightful owner.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE84"
        },
        [80130301] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentKR = "어이, 안녕.",
          DialogueId = 80130301,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990982",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130302,
          SpeakNpcId = 93103,
          Subtitle = "Yo.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990982"
        },
        [80130302] = {
          ContentKR = "바빠? 얘기 좀 할까?",
          DialogueId = 80130302,
          GUID = "C89909AC",
          NextOptions = {
            [1] = 801303021,
            [2] = 801303022
          },
          SpeakNpcId = 93103,
          Subtitle = "Got a minute?",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909AC"
        },
        [80130303] = {
          ContentKR = "흥, 난 그 바보가 아니야.",
          DialogueId = 80130303,
          GUID = "C89909D6",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          Subtitle = "Tch. I'm not that idiot.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909D6"
        },
        [80130304] = {
          ContentKR = "당연히 아니지, 폭탄 게임 따윈 이미 질렸다고.",
          DialogueId = 80130304,
          GUID = "C8990A00",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          Subtitle = "Duh. I'm done playing \"say hello to my talking bomb.\"",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A00"
        },
        [80130305] = {
          ContentKR = "난 올리버, 올리버 쿠즈카다. 폭탄 속에 갇힌 이상한 노리개가 아니라.",
          DialogueId = 80130305,
          GUID = "C8990A2A",
          NextDialogue = 80130306,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Name's Oliver. Oliver Kuzka. Not some fantastic creature holed up inside a bomb.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A2A"
        },
        [80130306] = {
          ContentKR = "들어본 적 없는 이름이겠지만 뭐, 상관없고, 잘 기억해 둬. 언젠가 황성 디즈마니아에 가게 되면, 북문 밖 15킬로미터 지점에 있는 폐허가 된 요새를 잘 살펴봐. 내가 폭파시킨 곳이니까.",
          DialogueId = 80130306,
          GUID = "C8990A54",
          NextDialogue = 80130307,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "You probably haven't heard the name. Doesn't matter. Just remember it. If you ever swing by Dismania, head fifteen kilometres out from the north gate. You'll find a ruined fortress. My signature work.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A54"
        },
        [80130307] = {
          ContentKR = "내가 여기 왜 왔는지는 네 태도에 달려 있어. 말해, 예일이 지난번에 와서 너와 무슨 이야기를 나눴는지.",
          DialogueId = 80130307,
          GUID = "C8990A7E",
          NextOptions = {
            [1] = 801303071,
            [2] = 801303072
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "As for why I'm here... That depends. Tell me — what did Yale say to you last time he was here?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A7E"
        },
        [80130308] = {
          ContentKR = "오, 보기보다 세네, 재미있어. 너도 강하게 나가면 반발하는 타입인가 보군.",
          DialogueId = 80130308,
          GUID = "C8990AA8",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Hah. Tougher than you look — I like that. You only play along when asked nicely, huh? Guess we're the same type.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AA8"
        },
        [80130309] = {
          ContentKR = "나쁘지 않지, 그 단도직입적인 성격은 마음에 드네.",
          DialogueId = 80130309,
          GUID = "C8990AD2",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Fair enough. I like straight talk.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AD2"
        },
        [80130310] = {
          ContentKR = "그럼 나도 솔직하게 나가지, 처음부터 이야기해 볼까. ",
          DialogueId = 80130310,
          GUID = "C8990AFC",
          NextDialogue = 80130311,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "The truth, then. But fair warning — it's a long story.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AFC"
        },
        [80130311] = {
          ContentKR = "아까도 말했듯이, 이 몸은 원래 내 거야. 폭탄의 천재, 올리버 쿠즈카.",
          DialogueId = 80130311,
          GUID = "C8990B26",
          NextDialogue = 80130312,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Like I said — I'm Oliver Kuzka, the real owner of this body. And the best damn bomb maker you'll ever meet.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B26"
        },
        [80130312] = {
          ContentKR = "그 시절 난 어렸고, 내가 만든 장난감들로 휘페르보레아 전체를 날려버릴 수 있을 거라고 생각했지. 잡히면 어떻게 될지, 아니, 잡힐 거라는 생각 자체를 하지 않았어.",
          DialogueId = 80130312,
          GUID = "C8990B50",
          NextDialogue = 80130313,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Back then, I was barely more than a kid myself. Thought I could blow the whole Empire sky-high with my little toys. Never even stopped to think what'd happen if I got caught... or maybe I just figured it wouldn't happen.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B50"
        },
        [80130313] = {
          ContentKR = "그래서 군단에 붙잡혔을 때, 나한테 무슨 일이 기다리고 있을지 전혀 몰랐지.",
          DialogueId = 80130313,
          GUID = "C8990B7A",
          NextDialogue = 80130314,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So when the Legion finally bagged me, I had no clue what was coming.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B7A"
        },
        [80130314] = {
          ContentKR = "난 소드 연금원의 한 연구실로 끌려갔고, 거기서 존스라는 영감탱이를 만났어. 생긴 건 인자하게 생겼더군.",
          DialogueId = 80130314,
          GUID = "C8990BA4",
          NextDialogue = 80130315,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "They hauled me off to some Spathatoi lab and sat me in front of this kindly looking old man called Jones.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BA4"
        },
        [80130315] = {
          ContentKR = "존스는 다정하고 부드럽게, 범죄는 심리적인 문제일 뿐이니까, 약을 먹으면 좋아질 거라나 뭐라나 하는 헛소리를 늘어놓았어.",
          DialogueId = 80130315,
          GUID = "C8990BCE",
          NextDialogue = 80130316,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Spoke real gentle, that one — kept saying crime was just \"a mental hiccup\" curable with right medication. Rubbish.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BCE"
        },
        [80130316] = {
          ContentKR = "뭐, 굶기지는 않았고, 단지 약이랑 신체검사를 강요했지. 쓴 약은 아니었지만, 마시고 나면 머리가 느리게 돌아가는 느낌이 들었고... 점차 많은 것들을 잊어버리게 됐어.",
          DialogueId = 80130316,
          GUID = "C8990BF8",
          NextDialogue = 80130317,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "They didn't starve me, not really. Fed me fine, even. But they did force drugs down my throat and ran endless \"check-ups.\" The stuff didn't taste bad, but after every dose, my thoughts would slow to a crawl... and little by little, my memories started slipping away.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BF8"
        },
        [80130317] = {
          ContentKR = "처음에는 이 교활한 영감탱이한테 욕이라도 퍼부을 수 있었지만, 약을 계속 먹다 보니 나중엔 욕하는 법도 기억나지 않았어.",
          DialogueId = 80130317,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990C22",
          NextDialogue = 80130318,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "At first, I still had enough fire left to cuss that shady codger out — but the more meds I swallowed, the harder it was to remember the curse words.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C22"
        },
        [80130318] = {
          ContentKR = "욕할 줄 모르는 사람은 말도 할 줄 모르는 거라는 말도 있잖아. 누가 한 말인지는 까먹었지만.",
          DialogueId = 80130318,
          GUID = "C8990C4C",
          NextDialogue = 80130319,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Someone once said: a man who never swears is a man who's lost his voice.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C4C"
        },
        [80130319] = {
          ContentKR = "근데 이건 단지 시작일 뿐이었어. 점점 걸어 다니는 법을 잊어버리게 됐고... 손을 어떻게 움직이는지, 심지어는 숨 쉬는 방법도 잊어버렸지.",
          DialogueId = 80130319,
          GUID = "C8990C76",
          NextDialogue = 80130320,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "And that was only the beginning. Slowly, I forgot how to walk straight, how to grip things — even how to breathe.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C76"
        },
        [80130320] = {
          ContentKR = "존스가 준 약에 문제가 있다는 걸 알았지만, 약을 마실 때가 되면 뱉어내는 방법이 기억나지 않았어. 그래서 그냥 내 기억이 서서히 녹아내리도록 기다릴 수밖에 없었지. 차라리 폭발해서 산산조각 나는 게 더 나았을 거야.",
          DialogueId = 80130320,
          GUID = "C8990CA0",
          NextDialogue = 80130321,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I knew there was something wrong with those drugs. But every time they poured something down my throat, I couldn't even remember how to spit it out. All I could do was sit there and watch my memories dissolve. I'd have preferred being blown to bits.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CA0"
        },
        [80130321] = {
          ContentKR = "마지막엔, 거울 속에 비친 올리버 쿠즈카의 몸을 방관자처럼 바라보면서도, 그게 누구인지조차 알 수 없었어.",
          DialogueId = 80130321,
          GUID = "C8990CCA",
          NextDialogue = 80130322,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "In the end, all that was left of me was a shadow — watching some puppet called \"Oliver Kuzka\" move in the mirror, without a clue who the hell he was anymore.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CCA"
        },
        [80130322] = {
          ContentKR = "그러던 어느 날, 존스 영감탱이가 방에 들어오더니, 이 몸을 향해 말하더군, 이 몸의 이름은 예일이라고.",
          DialogueId = 80130322,
          GUID = "C8990CF4",
          NextDialogue = 80130323,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Until one day, that old bastard walked in, stared at my body, and said: \"Your name is Yale.\"",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CF4"
        },
        [80130323] = {
          ContentKR = "...그러니까, 걔가 예일이래. 그럼, 나는 누구지?",
          DialogueId = 80130323,
          GUID = "C8990D1E",
          NextOptions = {
            [1] = 801303231,
            [2] = 801303232
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So he's Yale... then who the hell am I?",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D1E"
        },
        [80130324] = {
          ContentKR = "이해가 안 되는 것도 당연해. 나도 한참이 지나서야 존스가 새로운 인격을 만들어 냈다는 걸 깨달았으니까.",
          DialogueId = 80130324,
          GUID = "C8990D48",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Figures. Took me a while, too. Jones... he created a new alter ego inside my body.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D48"
        },
        [80130325] = {
          ContentKR = "그래, 그는 올리버라는 카론 범죄자를 완전히 대체할 새로운 인격을 만들어낸 거야.",
          DialogueId = 80130325,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990D72",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Too right. He created a new alter ego inside my body — meant to overwrite the Charon criminal named Oliver Kuzka.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D72"
        },
        [80130326] = {
          ContentKR = "근데 예일의 등장은 나한테 오히려 좋은 일이었어. 그전에는 몸을 완전히 잃어버려서, 아무리 움직이려고 해도 소용이 없었거든.",
          DialogueId = 80130326,
          GUID = "C8990D9C",
          NextDialogue = 80130327,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But I'll give it to him — without Yale, I'd have lost control of my body forever. No matter how hard I fought, I couldn't move a finger.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D9C"
        },
        [80130327] = {
          ContentKR = "하지만 내 생각은 예일에게 직접 전달할 수 있었어. 내가 \"넌 가짜야\"라고 생각하기만 하면, 예일은 놀란 메추라기처럼 좌우를 두리번거리며 고개를 움츠렸지.",
          DialogueId = 80130327,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990DC6",
          NextDialogue = 80130328,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But my thoughts could get through to him. Every time I so much as thought \"You're a knock-off,\" he'd flinch like a startled quail — eyes darting, shoulders hunched.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DC6"
        },
        [80130328] = {
          ContentKR = "내가 걜 얼마나 싫어했을지 상상이 되지? 난 기억해 낼 수 있는 가장 악독한 말들로 매일매일 예일을 저주했어.",
          DialogueId = 80130328,
          GUID = "C8990DF0",
          NextDialogue = 80130329,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "You can imagine how much I hated him back then. I spent every waking second hurling every insult I could still remember at him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DF0"
        },
        [80130329] = {
          ContentKR = "걔 입장에선 아마 머릿속에서 갑자기 이상한 목소리가 들려온다고 생각했겠지.",
          DialogueId = 80130329,
          GUID = "C8990E1A",
          NextDialogue = 80130330,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "To him, I must have been just a crazy voice in his head.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E1A"
        },
        [80130330] = {
          ContentKR = "걔도 한때는 날 머릿속에서 몰아내려고 했지만, 내가 질 리가 있어? 애초에 이 몸의 주인은 나였는데.",
          DialogueId = 80130330,
          GUID = "C8990E44",
          NextDialogue = 80130331,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "He tried to shut me out, of course. But how could he? That body was mine.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E44"
        },
        [80130331] = {
          ContentKR = "열 받는 건, 존스 영감탱이가 예일의 이상 행동을 눈치챘는지 걔한테 올리버를 아냐고 묻더라고.",
          DialogueId = 80130331,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990E6E",
          NextDialogue = 80130332,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Then that old bastard caught on. He asked Yale if he'd ever heard the name \"Oliver.\"",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E6E"
        },
        [80130332] = {
          ContentKR = "걘 한사코 모른다고 했지만, 존스는 예일의 눈을 꿰뚫어 보는 것처럼 끈질기게 노려봤어. 꼭 내가 보이기라도 하는 것처럼 말이야.",
          DialogueId = 80130332,
          GUID = "C8990E98",
          NextDialogue = 80130333,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Yale denied it. But Jones just kept staring into his eyes... like he could see me hiding behind them.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E98"
        },
        [80130333] = {
          ContentKR = "그 일 이후, 존스는 예일한테 축음기를 하나 가져다줬어. 그 플레이어로 음악을 틀기 시작하면 난 완전히 의식을 잃게 됐지. 누군가 캄캄한 어둠 속에서 촛불을 '훅' 불어 끄는 것처럼 말이야.",
          DialogueId = 80130333,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990EC2",
          NextDialogue = 80130334,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "After that, Jones wheeled in a record player. Each time the needle dropped and the music started, I blacked out— like someone snuffing a candle.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EC2"
        },
        [80130334] = {
          ContentKR = "난 깨달았어. 그 축음기와 음악은 바로 존스가 나를 없애기 위해 사용한 새로운 방법이었어. 존스는 예일이 나를 완전히 대체하길 바랐던 거야.",
          DialogueId = 80130334,
          GUID = "C8990EEC",
          NextDialogue = 80130335,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I knew the record player and the music was his new trick to wipe me out, so Yale could take the body for good.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EEC"
        },
        [80130335] = {
          ContentKR = "나는 이런 잠과 깨어남의 반복 속에서 모든 기억을 잃어버릴 줄 알았어. 하지만 어느 날 갑자기 잠에서 깨어났을 때, 예일이 말하더군. 더 이상 그 음악을 듣고 싶지 않아졌다는 거야.",
          DialogueId = 80130335,
          GUID = "C8990F16",
          NextDialogue = 80130336,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Caught in that endless loop of blackouts and brief flashes of waking, I figured I'd lose everything — memories, thoughts, even the last scraps of who I was. But then, one day, I heard Yale's voice, telling me he didn't want to listen to the music any more.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F16"
        },
        [80130336] = {
          ContentKR = "그 순간부터, 난 내가 쭉 '가짜'라고 부르던 녀석이 실제로는 독립적인 존재임을 깨달았어. 그래서 난 걔랑 같이 계획을 세워, 존스 영감탱이의 손아귀에서 성공적으로 탈출했어.",
          DialogueId = 80130336,
          GUID = "C8990F40",
          NextDialogue = 80130337,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "That's when it hit me: the \"knock-off\" I kept abusing... was a real person. So we made a deal. Put together a plan. And broke out of that old bastard's lab for good.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F40"
        },
        [80130337] = {
          ContentKR = "마침내 우리는 스칼렛에 도착해서 함께 장난감 가게를 열었어. 예일은 가게에 '우르르쾅쾅'이라는 별난 이름을 붙였지. 우리는 연구소에서 있었던 일에 대해 다시는 언급하지 않았어.",
          DialogueId = 80130337,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990F6A",
          NextDialogue = 80130338,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "We made it to Scarletriver and opened a toy shop. He named it Snap 'n' Spark — stupid name, if you ask me — and we never spoke of the lab again.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F6A"
        },
        [80130338] = {
          ContentKR = "며칠 전까지만 해도 말이야. 며칠 전 갑자기 익숙한 느낌이 들면서 의식을 잃었어. 예일이 또 약을 먹었다는 걸 짐작했지만 걔가 어디로 갔는지 알 수 없었지. 여기저기 물어본 끝에 아이스레이크 시티를 방문했다는 걸 알게 됐어.",
          DialogueId = 80130338,
          GUID = "C8990F94",
          NextDialogue = 80130339,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Couple days ago, I blacked out again — that same old, familiar feeling. Figured he must've dosed himself to shut me down. No idea what he got up to while I was under, so I asked around. Turns out he'd taken a trip to Icelake.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F94"
        },
        [80130339] = {
          ContentKR = "솔직히 말해서, 예일을 가장 잘 아는 사람은 나야. 예일이 소심하고 낯을 가리긴 해도, 본성은 착한 애야. 걔가 나한테... 숨기고 싶은 일이 있을 것 같지는 않거든.",
          DialogueId = 80130339,
          GUID = "C8990FBE",
          NextDialogue = 80130340,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Thing is, I know him better than anyone — timid, shy... but too kind and soft for his own good. Definitely not the type to pull a stunt behind my back — not unless something was eating at him.",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FBE"
        },
        [80130340] = {
          ContentKR = "그래서 나도 또 다른 인격을 잠재울 수 있는 약을 삼키고 여기에 온 거야. 걔가 도대체 무슨 이야기를 했는지 알아내기 위해서.",
          DialogueId = 80130340,
          GUID = "C8990FE8",
          NextOptions = {
            [1] = 801303401
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So I took the meds myself, knocked him out, and came here. I need to know what he said behind my back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FE8"
        },
        [80130341] = {
          ContentKR = "(예일이 '우르르쾅쾅'과 원래 주인에 대해 가진 고민, 즉, 자신의 몸과 올리버에 대한 고민을 다시 이야기한다.)",
          DialogueId = 80130341,
          GUID = "C8991012",
          IsBlack = 1,
          NextDialogue = 80130342,
          Subtitle = "(You recount Yale's tale about Snap 'n' Spark and the mysterious former shopkeeper, which, in fact, is a metaphor of his very body and its true owner.)",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991012"
        },
        [80130342] = {
          ContentKR = "그러니까... 예일이 나를 잠재우는 약을 먹고 여기 와서, 몸을 나한테 돌려줄 결심을 했다는 거야?",
          DialogueId = 80130342,
          GUID = "C899103C",
          NextDialogue = 80130343,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So... he drugged me, came here, and decided to give the body back to me!?",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899103C"
        },
        [80130343] = {
          ContentKR = "이... 이... 앞뒤 분간도 못하는 빡*가리 같은 놈! ",
          DialogueId = 80130343,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8991066",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801303431,
            [2] = 801303432
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "That... that idiot... that hopeless, soft-hearted wimp!",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991066"
        },
        [80130344] = {
          ContentKR = "...빈정거리지 마. 어쨌든 난 여기서 예일이 깨어나기를 기다렸다가, 과거 일들을 제대로 얘기해야겠어.",
          DialogueId = 80130344,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8991090",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "...Hilarious. What I need to do now is wait for him to wake up, so that we can sort all this out.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991090"
        },
        [80130345] = {
          ContentKR = "흠, 글쎄. 어쨌든 여기서 녀석이 깨어나기를 기다렸다가, 과거 일들을 제대로 얘기해야겠어.",
          DialogueId = 80130345,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C89910BA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Maybe. Maybe not. Either way, I'm staying put till he wakes, and we'll sort it out.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910BA"
        },
        [80130346] = {
          ContentKR = "...고마워, 이렇게 예전 일들을 들어줘서. 미안한데 이따가 예일이 깨어나면, 너도 옆에서 몇 마디 좀 거들어 줘.",
          DialogueId = 80130346,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C89910E4",
          NextDialogue = 80130347,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Thanks, by the way, for hearing me out. When Yale wakes up... if he turns out to be too stubborn, I might need you to back me up.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910E4"
        },
        [80130347] = {
          ContentKR = "올리버가 매우 초조해하며 의자에 앉아 다리를 떨고 있다. 예일이 깨어나려면 시간이 좀 더 필요한 것 같다... ",
          DialogueId = 80130347,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C899110E",
          IsBlack = 1,
          Subtitle = "Oliver sits restlessly, one leg bouncing non-stop. It looks like it'll be a while before Yale wakes up...",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899110E"
        },
        [80130401] = {
          Camera = "-49.926758,-243.0,161.0,0.000036,-19.199852,68.998772,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "여긴... 어디지? ",
          DialogueId = 80130401,
          FacialId = {
            [1] = "790023:Smile01"
          },
          FinalCamera = "-49.926758,-249.212219,161.0,0.000036,-19.199852,68.998741,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89919EA",
          NextDialogue = 80130402,
          SpeakNpcId = 790023,
          Subtitle = "Where am I...?",
          TalkActionId = {
            [1] = "790023:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Yeer/004/C89919EA"
        },
        [80130402] = {
          Camera = "-75.0,-188.0,153.0,0.000051,-4.999999,-66.802383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "밝고... 따뜻해... 자주 꿈에서 보던 거기랑은 달라. 거긴 항상 불이 켜져 있지만 늘 추웠는데.",
          DialogueId = 80130402,
          FinalCamera = "-58.0,-188.0,153.0,0.000051,-4.999999,-66.802383,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8991A14",
          LookAt = {
            [1] = "100001:n(790023)"
          },
          NextDialogue = 80130403,
          Scripts = "SetLocation{ActorId{100001},TargetPoint{\"TargetPoint_Nvzhu\"},Visibility{\"Show\"}}",
          SpeakNpcId = 790023,
          Subtitle = "So bright... and warm... Not like the place in my dreams— lights always on, yet freezing cold.",
          TalkActionId = {
            [1] = "790023:Talk03_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991A14"
        },
        [80130403] = {
          Camera = "79.0,-274.0,116.0,0.0,0.0,110.998604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "아... {nickname}, 당신이었군요. 여긴 아이스레이크 시티? 제가 어떻게 여기에...",
          DialogueId = 80130403,
