        },
        [80210109] = {
          ContentKR = "왜 떠나려는 거지?",
          DialogueId = 80210109,
          GUID = "C8CC2F02",
          NextDialogue = 80210110,
          SpeakNpcId = 790065,
          Subtitle = "Why do you have to go?",
          TalkActionId = {
            [1] = "790065:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2F02"
        },
        [80210110] = {
          ContentKR = "한 사람을 살려야 하거든.",
          DialogueId = 80210110,
          GUID = "C8CC2F2C",
          NextDialogue = 80210111,
          SpeakNpcId = 790066,
          Subtitle = "To spare a life.",
          TalkActionId = {
            [1] = "790066:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2F2C"
        },
        [80210111] = {
          ContentKR = "그게 누구지...?",
          DialogueId = 80210111,
          GUID = "C8CC2F56",
          NextDialogue = 80210112,
          SpeakNpcId = 790065,
          Subtitle = "Whose life?",
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2F56"
        },
        [80210112] = {
          Camera = "-97.171875,135.871094,124.923828,0.000072,-11.800135,-56.803616,25.0,226.88681,false,Manual,2.8",
          ContentKR = "바로 너!",
          DialogueId = 80210112,
          Duration = 4,
          GUID = "C8CC2F80",
          LookAt = {
            [1] = "790066:n(790065)"
          },
          NextDialogue = 80210113,
          SpeakNpcId = 790066,
          Subtitle = "Yours!",
