        [90010201] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentKR = "요즘 괜찮은 물건 구하지 못했는가? 이 늙은이에게 보여다오, 뭔가 특별한 무기를 만들 수 있을지도 모르니까!",
          DialogueId = 90010201,
          GUID = "E154C29A",
          SpeakNpcId = 900001,
