          GUID = "E15B3BCC",
          Subtitle = "Goodbye"
        },
        [90030000] = {
          ContentKR = "{性别:그|그녀}는 결코 새장에 갇힌 새가 아니야. 언젠가 {性别:그|그녀}가 그 섬을 떠나 더 먼 하늘로 날아갈 것을 알고 있지만 이것이 우리에게 행운인지 불행인지는 잘 모르겠어.",
          DialogueId = 90030000,
          GUID = "E15B3BCB",
          SpeakNpcId = 81101,
          Subtitle = "{性别:He|She} was never meant to be caged. I always knew {性别:he|she} would someday leave the island to reach for the sky. What I couldn't tell was whether that would be a blessing or a curse for us.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_idle"
        },
        [90030001] = {
          ContentKR = "돌아왔구나. 오늘은 뭐 할 거야? 집에서 쉴 거야?",
          DialogueId = 90030001,
          GUID = "E161730A",
          LookAt = {
            [1] = "81101:n(0)",
