          Subtitle = "Goodbye"
        },
        [90030101] = {
          ContentKR = "소원? 음... 딱히 생각해 본 적은 없는데. 그저 아침에 네가 웃는 것을 보는 것만으로도 충분해.",
          DialogueId = 90030101,
          GUID = "E1618372",
          LookAt = {
            [1] = "81101:n(0)",
