        [90250203] = {
          ContentKR = "크흠, 아니거든! 사제님들은 다 좋은 분들이야. 다들 굉장히 친절하고 자상하셔. 경전 내용을 잘못 외워도 딱 30번만 베껴 쓰면 되고, 사마엘한테 크림 먹이다 들켜도 딱 이틀만 벽 보고 반성하면 되거든. 난 모두를 아주아주 좋아해.",
          DialogueId = 90250203,
