          VoiceName = "voice/$Locale$/story/1201/120135/120135070"
        },
        [120135071] = {
          ContentKR = "제가 왜 당신들을 도와야 하죠?",
          DialogueId = 120135071,
          GUID = "120135071.0",
          NextDialogue = 12013509,
          Subtitle = "Why should I help you?"
        },
        [120135072] = {
          ContentKR = "몰이사냥이요? 딱히 좋은 일처럼 들리진 않는데요.",
          DialogueId = 120135072,
          GUID = "120135072.0",
          NextDialogue = 12013526,
          Subtitle = "A hunting expedition? That doesn't sound like anything honest or aboveboard."
        },
        [120136021] = {
          ContentKR = "일단 부소를 먼저 찾아가자. ",
          DialogueId = 120136021,
          GUID = "120136021.0",
          ImprPlusId = 1204,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Let's go check on Fushu first."
        },
        [120136022] = {
          ContentKR = "규선생에게 가서 의뢰 상황을 알아보자.",
          DialogueId = 120136022,
          GUID = "120136022.0",
          ImprPlusId = 1201,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Let's have a look at Mr Qiu's commission."
        },
        [120140071] = {
