        [120351151] = {
          Content = "起床！",
          DialogueId = 120351151,
          GUID = "120351151.0"
        },
        [120351152] = {
          Content = "再睡一会儿~",
          DialogueId = 120351152,
          GUID = "120351152.0"
        },
        [200005261] = {
          ContentKR = "(저렴한 가격, 설렌다)",
          DialogueId = 200005261,
          GUID = "200005261",
          ImprPlusId = 1001,
          NextDialogue = 20000533,
          Subtitle = "(Cheap labour. Not bad.)"
        },
        [200005262] = {
          ContentKR = "(갑자기 잘해준다고? 불안하다)",
          DialogueId = 200005262,
          GUID = "200005262.0",
          ImprPlusId = 1003,
          NextDialogue = 20000528,
          Subtitle = "(Labour never comes this cheap. I'd better be careful.)"
        },
        [200006051] = {
          ContentKR = "루나는 어떤 종족이야?",
          DialogueId = 200006051,
          GUID = "200006051",
          NextDialogue = 20000606,
          Subtitle = "Could you tell me more about Lunos?"
        },
        [200006151] = {
          ContentKR = "눼에, 눼에, 알겠습니다요.",
          DialogueId = 200006151,
          GUID = "200006151",
          ImprPlusId = 1004,
          NextDialogue = 20000619,
          Subtitle = "Yes, Your Highness!"
        },
        [200006152] = {
          ContentKR = "군단장 월급은 어떻게 돼?",
          DialogueId = 200006152,
          GUID = "200006152",
          ImprPlusId = 1001,
          NextDialogue = 20000618,
          Subtitle = "How much will the leader of your legion get paid?"
        },
        [200008091] = {
          ContentKR = "(프시케가 기운 없어 보인다. 무슨 고민이 있는 것 같은데.)",
          DialogueId = 200008091,
          GUID = "200008091",
          ImprPlusId = 1004,
          NextDialogue = 20000810,
          Subtitle = "(She looks rather lethargic. Something seems to be on her mind.)"
        },
        [200008092] = {
          ContentKR = "(프시케가 아까 돌보던 꽃에 주목한다 - 아까 그 꽃을 보며 한숨 쉬는 것 같았는데.)",
          DialogueId = 200008092,
          GUID = "200008092.0",
          ImprPlusId = 1003,
          NextDialogue = 20000811,
          Subtitle = "(You noticed the potted plant she was taking care of, and she was sighing at it.)"
        },
        [200008093] = {
          ContentKR = "보통 쉰다고 해결되는 게 아니야. 밖에 나가서 즐겁게 놀면 기운 나.",
          DialogueId = 200008093,
          GUID = "200008093.0",
          ImprPlusId = 1005,
          NextDialogue = 20000812,
          Subtitle = "Resting might not do much. Why not try going out and doing something fun to lift your spirits?"
        },
        [200008161] = {
          ContentKR = "꽃이 좀 기운이 없어 보여.",
          DialogueId = 200008161,
          GUID = "200008161.0",
          NextDialogue = 20000817,
          Subtitle = "The flowers seem a bit under the weather."
        },
        [200008162] = {
          ContentKR = "꽃이 아주 잘 피었어!",
          DialogueId = 200008162,
          GUID = "200008162.0",
          NextDialogue = 20000818,
          Subtitle = "They're thriving and blooming!"
        },
        [200008201] = {
          ContentKR = "(꽃의 색깔을 설명한다.)",
          DialogueId = 200008201,
          GUID = "200008201.0",
          NextDialogue = 20000821,
          Subtitle = "(Describe the colour of the flowers)"
        },
        [200008202] = {
          ContentKR = "(꽃의 모양을 설명한다.)",
          DialogueId = 200008202,
          GUID = "200008202.0",
          NextDialogue = 20000823,
          Subtitle = "(Describe the shape of the flowers)"
        },
        [200008203] = {
          ContentKR = "(꽃잎의 세부 사항을 설명한다.)",
          DialogueId = 200008203,
          GUID = "200008203.0",
          NextDialogue = 20000827,
          Subtitle = "(Describe the petal details)"
        },
        [200008341] = {
          ContentKR = "(위로한다. 아무리 튼튼한 꽃이라도 연약한 식물이니까, 시들어가는 건 당연한 일이야.)",
          DialogueId = 200008341,
          GUID = "200008341",
          ImprPlusId = 1004,
          NextDialogue = 20000835,
          Subtitle = "(Comfort her — even the toughest flower can be vulnerable and will wilt one day.)"
        },
        [200008342] = {
          ContentKR = "(자세히 생각해보라고 한다. 돌보는 방법 말고, 뭔가 전과 다른 점은 없었는지.)",
          DialogueId = 200008342,
          GUID = "200008342",
          ImprPlusId = 1003,
          NextDialogue = 20000836,
          Subtitle = "(Ask her to think of any changes or differences compared to the way the plant used to be nurtured.)"
        },
        [200008411] = {
          ContentKR = "('특별한 흙'에 대해 궁금해한다.)",
          DialogueId = 200008411,
          GUID = "200008411",
          ImprPlusId = 1001,
          NextDialogue = 20000842,
          Subtitle = "(You are interested in this special soil.)"
        },
        [200008412] = {
          ContentKR = "(프시케를 돕기로 결심한다.)",
          DialogueId = 200008412,
          GUID = "200008412",
          ImprPlusId = 1002,
          NextDialogue = 20000842,
          Subtitle = "(You decide to help Psyche.)"
        },
        [200009111] = {
          ContentKR = "맞아... 꽃도 선택권이 있다면 꺾이지 않길 바랄 거야.",
          DialogueId = 200009111,
          GUID = "200009111",
          ImprPlusId = 1004,
          NextDialogue = 20000913,
          Subtitle = "Indeed... If flowers had a choice, they probably wouldn't want to be snipped off."
        },
        [200009112] = {
          ContentKR = "그래도 꽃들이 사람들에게 감상되는 거라면, 그것도 의미 있는 일이지 않을까.",
          DialogueId = 200009112,
          GUID = "200009112",
          ImprPlusId = 1001,
          NextDialogue = 20000912,
          Subtitle = "But maybe that is the flowers' purpose, to have their beauty appreciated by others."
        },
        [200009151] = {
          ContentKR = "최대한 오래 살 수 있게 노력할 거야.",
          DialogueId = 200009151,
          GUID = "200009151",
          ImprPlusId = 1002,
          NextDialogue = 20000916,
          Subtitle = "I'll do my best to make them survive for as long as I can."
        },
        [200009152] = {
          ContentKR = "활짝 핀 순간을 소중히 여길 거야.",
          DialogueId = 200009152,
          GUID = "200009152",
          ImprPlusId = 1001,
          NextDialogue = 20000917,
          Subtitle = "I will cherish the moment of their blossoming."
        },
        [200009153] = {
          ContentKR = "나도 좀 불쌍하다고 생각해...",
          DialogueId = 200009153,
          GUID = "200009153",
          ImprPlusId = 1004,
          NextDialogue = 20000918,
          Subtitle = "I actually feel sorry for them as well..."
        },
        [200009221] = {
          ContentKR = "맞아, 정말 대단해.",
          DialogueId = 200009221,
          GUID = "200009221.0",
          NextDialogue = 20000923,
          Subtitle = "Indeed. They're amazing."
        },
        [200009222] = {
          ContentKR = "그래도 난 꽃들이 꺾이지 않고 가지에 붙어 있었으면 좋겠어. ",
          DialogueId = 200009222,
          GUID = "200009222.0",
          NextDialogue = 20000924,
          Subtitle = "Personally, I prefer to leave them on the plant rather than snipping them off."
        },
        [200009261] = {
          ContentKR = "천만에, 부족하면 또 가서 파올게.",
          DialogueId = 200009261,
          GUID = "200009261.0",
          NextDialogue = 20000929,
          Subtitle = "You're welcome. And if you ever need more, just let me know."
        },
        [200009262] = {
          ContentKR = "그렇다면 시간 날 때 나한테도 좀 알려줘.",
          DialogueId = 200009262,
          GUID = "200009262.0",
          NextDialogue = 20000927,
          Subtitle = "I could really use a teacher if you're available."
        },
        [200017011] = {
          ContentKR = "출발하자.",
          DialogueId = 200017011,
          GUID = "200017011",
          Subtitle = "Let's go."
        },
        [200017012] = {
          ContentKR = "아직 준비가 안 됐어.",
          DialogueId = 200017012,
          GUID = "200017012",
          SpeakNpcId = 200021,
          Subtitle = "Not ready yet."
        },
        [200023011] = {
          ContentKR = "프시케를 깨우자.",
          DialogueId = 200023011,
          GUID = "200023011",
          Subtitle = "Awaken her."
        },
        [200023012] = {
          ContentKR = "아직 준비가 안 됐어.",
          DialogueId = 200023012,
          GUID = "200023012",
          Subtitle = "I'm not ready."
        },
        [200048041] = {
          ContentKR = "그건 좋은 일 아니야? 너는 어떤 요리법을 좋아해?",
          DialogueId = 200048041,
          GUID = "200048041",
          NextDialogue = 20004805,
          Subtitle = "Oh wow, should we go with roast or braised? What's your pick?"
        },
        [200048042] = {
          ContentKR = "'큰일'이 엄청나게 큰 돼지를 본 일이라는 거야?",
          DialogueId = 200048042,
          GUID = "200048042.0",
          NextDialogue = 20004806,
          Subtitle = "So... the \"big news\" is that someone saw a really big pig?"
        },
        [200049011] = {
          Content = "可以。",
          DialogueId = 200049011,
          GUID = "200049011.0"
        },
        [200049012] = {
          Content = "猪的事先放一放。",
          DialogueId = 200049012,
          GUID = "200049012.0"
        },
        [200054111] = {
          ContentKR = "카론과 솔라가 생긴 건 다르지만, 다 같은 인간인 것처럼?",
          DialogueId = 200054111,
          GUID = "200054111",
          ImprPlusId = 1003,
          NextDialogue = 20005412,
          Subtitle = "Kind of like how Charons and Solas look different but are both human?"
        },
        [200054112] = {
          ContentKR = "총이랑 활이 겉모습은 다르지만 둘 다 원거리 무기인 것처럼?",
          DialogueId = 200054112,
          GUID = "200054112.0",
          ImprPlusId = 1001,
          NextDialogue = 20005413,
          Subtitle = "Kind of like how guns and bows look different but are both ranged weapons?"
        },
        [200054113] = {
          ContentKR = "눈이랑 안개 서로 다른 거지만, 사실 대부분 물로 만들어진 거랑 비슷한 거야?",
          DialogueId = 200054113,
          GUID = "200054113.0",
          ImprPlusId = 1005,
          NextDialogue = 20005414,
          Subtitle = "Kind of like how snow and mist look totally different but are both mainly made of water?"
        },
        [200054311] = {
          ContentKR = "나한테 맡겨.",
          DialogueId = 200054311,
          GUID = "200054311",
          NextDialogue = 20005432,
          Subtitle = "Sure, you can count on me."
        },
        [200054312] = {
          ContentKR = "마령이 하는 말을 알아들을 수 있어?",
          DialogueId = 200054312,
          GUID = "200054312.0",
          NextDialogue = 20005433,
          Subtitle = "Wait, you can understand the Geniemon language?"
