        [200065130] = {
          Camera = "242.134766,284.203125,81.299271,0.000249,2.80091,-142.179596,28.0,300.0,false,Manual,8.0",
          DialogueId = 200065130,
          FacialId = {
            [1] = "100001:Smile01"
          },
