          NextOptions = {
            [1] = 200065131,
            [2] = 200065132,
            [3] = 200065133
          },
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [200065131] = {
          ContentKR = "난 팀 녹토보이저의 대장, {nickname}이다! 지금 여기서 네놈들의 죄를 묻겠다!",
          DialogueId = 200065131,
          GUID = "200065131",
          ImprPlusId = 1004,
          NextDialogue = 20006514,
          Subtitle = "And I am , captain of the Noctoyagers! Your crimes end here!"
        },
        [200065132] = {
          ContentKR = "난 그냥 지나가던 배관공 마리오야, 저 사람들이랑은 모르는 사이야!",
          DialogueId = 200065132,
          GUID = "200065132",
          ImprPlusId = 1005,
          NextDialogue = 20006516,
          Subtitle = "And I am just a mushroom-loving plumber passing by. Have no idea who they are."
        },
        [200065133] = {
          ContentKR = "어서 이 마령들을 풀어줘!",
          DialogueId = 200065133,
          GUID = "200065133",
          ImprPlusId = 1002,
          NextDialogue = 20006518,
          Subtitle = "Release the Geniemons now!"
        },
        [200070081] = {
          ContentKR = "바보 같은 소리 하지 마, 트러플이 곤란해지잖아.",
          DialogueId = 200070081,
          GUID = "200070081",
          NextDialogue = 20007009,
          Subtitle = "Stop it, Snow, don't make it harder for Truffle."
        },
        [200070161] = {
          ContentKR = "약속!",
          DialogueId = 200070161,
          GUID = "200070161",
          NextDialogue = 20007017,
          Subtitle = "Pinky swear!"
        },
        [200071011] = {
          ContentKR = "판신 마령에 대하여...",
          DialogueId = 200071011,
          GUID = "200071011",
          NextDialogue = 20007102,
          Subtitle = "What do you know about Paniemon?"
        },
        [200071012] = {
          ContentKR = "마령 학자가 된 소감이 어때?",
          DialogueId = 200071012,
          GUID = "200071012",
          NextDialogue = 20007105,
          Subtitle = "How's life as a Geniemon scholar?"
        },
        [200071013] = {
          ContentKR = "아무것도 아니야.",
          DialogueId = 200071013,
          GUID = "200071013",
          Subtitle = "Nothing. Goodbye."
        },
        [510001041] = {
          ContentKR = "으아아! 먹을게요! 혼자 먹을 수 있어요!",
          DialogueId = 510001041,
          GUID = "510001041.0",
          ImprPlusId = 1004,
          NextDialogue = 51000105,
          Subtitle = "Ahhh! I'll drink it myself! Thank you!"
        },
        [510001042] = {
          ContentKR = "(재빨리 피한다. 낯선 사람의 지나친 호의를 믿지 않는다.)",
          DialogueId = 510001042,
          GUID = "510001042.0",
          ImprPlusId = 1001,
          NextDialogue = 51000107,
          Subtitle = "(Skillfully sidestep — You're wary of over-the-top kindness from strangers.)"
        },
        [510001101] = {
          ContentKR = "말씀하시는 '마님'께서 병에 걸리셨나요?",
          DialogueId = 510001101,
          GUID = "510001101",
          NextDialogue = 51000111,
          Subtitle = "The lady you mentioned — is she sick?"
        },
        [510003021] = {
          ContentKR = "(옷감이 꽤 고급스러워 보인다.)",
          DialogueId = 510003021,
          GUID = "510003021.0",
          ImprPlusId = 1001,
          NextDialogue = 51000303,
          Subtitle = "(The fabric of her outfit appears quite luxurious.)"
        },
        [510003022] = {
          ContentKR = "(누군가를 찾고 있는 것 같다.)",
          DialogueId = 510003022,
          GUID = "510003022.0",
          ImprPlusId = 1003,
          NextDialogue = 51000304,
          Subtitle = "(She seems to be looking for someone.)"
        },
        [510003023] = {
          ContentKR = "(매우 슬퍼 보인다.)",
          DialogueId = 510003023,
          GUID = "510003023.0",
          ImprPlusId = 1004,
          NextDialogue = 51000305,
          Subtitle = "(She appears mournful.)"
        },
        [510003051] = {
          ContentKR = "(도움을 줄 수 있을지도 몰라.)",
          DialogueId = 510003051,
          GUID = "510003051.0",
          NextDialogue = 510003052,
          Subtitle = "(Perhaps I can offer some help.)"
        },
        [510003052] = {
          ContentKR = "(도움을 줄 수 있을지도 몰라.)",
          DialogueId = 510003052,
          GUID = "510003052.0",
          NextOptions = {
            [1] = 510003054,
            [2] = 510003055,
            [3] = 510003056
          },
          SpeakNpcId = 100001,
          Subtitle = "(Perhaps I can offer some help.)",
          bForbidSkipOptions = true
        },
        [510003053] = {
          ContentKR = "(떠난다.)",
          DialogueId = 510003053,
          GUID = "510003053.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Leave)"
        },
        [510003054] = {
          ContentKR = "(무슨 고민거리가 있는지 물어본다. 또 보수를 지불한다면, 해결해 줄 수도 있다고 말한다.)",
          DialogueId = 510003054,
          FailDialogue = 51000306,
          GUID = "510003054.0",
          ImprCheckId = 1001,
          NextDialogue = 51000307,
          Subtitle = "(Ask if she's in some sort of trouble. Offer to help with proper payment in return.)"
        },
        [510003055] = {
          ContentKR = "(찾는 사람이 있는지 물어보고, 나중에 성 밖으로 나갈 때 염두에 두겠다고 말한다.)",
          DialogueId = 510003055,
          FailDialogue = 51000306,
          GUID = "510003055.0",
          ImprCheckId = 1002,
          NextDialogue = 51000307,
          Subtitle = "(Ask if she's looking for someone. Offer to keep an eye out during your travels.)"
        },
        [510003056] = {
          ContentKR = "(곤란한 일이 생겼는지 묻는다. 도움을 줄 수 있을 것 같다고 말한다.)",
          DialogueId = 510003056,
          FailDialogue = 51000306,
          GUID = "510003056.0",
          ImprCheckId = 1003,
          NextDialogue = 51000307,
          Subtitle = "(Ask if there's anything you can do to help her.)"
        },
        [510003111] = {
          ContentKR = "본 기억이 없어요.",
          DialogueId = 510003111,
          GUID = "510003111.0",
          NextDialogue = 51000312,
          Subtitle = "Not really, sorry."
        },
        [510004031] = {
          ContentKR = "에... {性别:저는 남자인데요. |저는 아줌마 딸이 아닌데요.}",
          DialogueId = 510004031,
          GUID = "510004031.0",
          ImprPlusId = 1001,
          NextDialogue = 51000490,
          Subtitle = "Umm... {性别:I am a man.|I am not your daughter.}"
        },
        [510004032] = {
          ContentKR = "진정하세요. 혹시 사람을 찾으시나요? 제가 알아봐 드릴게요.",
          DialogueId = 510004032,
          GUID = "510004032.0",
          ImprPlusId = 1004,
          NextDialogue = 51000490,
          Subtitle = "Please calm down. Are you looking for someone? I'll keep an eye out for you."
        },
        [510004033] = {
          ContentKR = "엄마!!!",
          DialogueId = 510004033,
          GUID = "510004033.0",
          ImprPlusId = 1005,
          NextDialogue = 51000404,
          Subtitle = "Mum!!!"
        },
        [510004071] = {
          ContentKR = "(수락)",
          DialogueId = 510004071,
          GUID = "510004071.0",
          NextDialogue = 51000408,
          Subtitle = "(Accept)"
        },
        [510004921] = {
          ContentKR = "따님의 특징과 실종 경위를 자세히 얘기해 주세요. 그래야 도와드릴 수 있는지 알 수 있으니까요.",
          DialogueId = 510004921,
          FailDialogue = 51000405,
          GUID = "510004921.0",
          ImprCheckId = 1007,
          NextDialogue = 51000406,
          Subtitle = "Please think carefully about your daughter's features and how she disappeared, so I can see what I can do."
        },
        [510005011] = {
          ContentKR = "엘사, 애니의 소식을 가져왔어요...",
          DialogueId = 510005011,
          GUID = "510005011.0",
          NextDialogue = 51000502,
          Subtitle = "Elsa, I have news about Annie..."
        },
        [510005021] = {
          ContentKR = "삼가 조의를 표합니다. 비록 애니는 세상을 떠났지만... 생명이 다 하는 순간에도 함께 있던 다른 여자아이를 구해냈어요. 애니의 선량함은 모두에게 기억될 거예요.",
          DialogueId = 510005021,
          GUID = "510005021.0",
          NextDialogue = 51000503,
          Subtitle = "I'm so sorry, but Annie has passed away... my condolences. In her final moments, she helped another girl survive, and her kindness will always be remembered."
        },
        [510006011] = {
          ContentKR = "엘사, 당신 딸을 찾았어요.",
          DialogueId = 510006011,
          GUID = "510006011.0",
          NextDialogue = 51000602,
          Subtitle = "Elsa, I've found your daughter."
        },
        [510007011] = {
          ContentKR = "계속 여기서 서성이고 있던데, 도움이 필요하니?",
          DialogueId = 510007011,
          GUID = "510007011.0",
          NextDialogue = 51000702,
          Subtitle = "Have you been wandering around here all this time? Is there anything I can help you with?"
        },
        [510007031] = {
          ContentKR = "네가 혼란스러운 건 이해해. 돌아갈 곳을 잃는 기분은 정말 좋지 않거든.",
          DialogueId = 510007031,
          GUID = "510007031.0",
          ImprPlusId = 1004,
          NextDialogue = 51000705,
          Subtitle = "I understand. Losing a sense of belonging is awful."
        },
        [510007032] = {
          ContentKR = "혼자서 밖에 돌아다니는 건 안전하지 않아. 최대한 빨리 자신이 누군지 알아내는 게 좋을 것 같아.",
          DialogueId = 510007032,
          GUID = "510007032.0",
          ImprPlusId = 1002,
          NextDialogue = 51000705,
          Subtitle = "Staying out here isn't safe. It's best to figure out your true identity as soon as possible."
        },
        [510007033] = {
          ContentKR = "눈에 보이는 것이 꼭 진실이라는 법은 없어. 무엇이든 잘 확인해 봐야 결론을 낼 수 있지.",
          DialogueId = 510007033,
          GUID = "510007033.0",
          ImprPlusId = 1003,
          NextDialogue = 51000705,
          Subtitle = "Seeing is not always believing. You've got to investigate everything thoroughly before jumping to conclusions."
        },
        [510007051] = {
          ContentKR = "(수락)",
          DialogueId = 510007051,
          GUID = "510007051.0",
          NextDialogue = 51000706,
          Subtitle = "(Accept)"
        },
        [510008121] = {
          ContentKR = "(앨리스의 일기를 보여주지 않는다)",
          DialogueId = 510008121,
          GUID = "510008121.0",
          NextDialogue = 51000813,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "(Do not show Alice's diary)"
        },
        [510008141] = {
          ContentKR = "맞아, 바로 네 어머니가 널 찾아달라고 의뢰했어. 어머니한테 데려다줄게.",
          DialogueId = 510008141,
          GUID = "510008141.0",
          NextDialogue = 51000814,
          Subtitle = "Exactly. Your mother asked me to find you. I will take you to her."
        },
        [510008921] = {
          ContentKR = "(앨리스의 일기를 보여준다)",
          DialogueId = 510008921,
          GUID = "510008921.0",
          NextDialogue = 51000803,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = " (Show Alice's diary)"
        },
        [510009031] = {
          ContentKR = "싸구려만 보이는데. 아무리 잘 쳐줘도 돌멩이 몇 개만도 못하겠는걸.",
          DialogueId = 510009031,
          GUID = "510009031.0",
          ImprPlusId = 1001,
          NextDialogue = 51000904,
          Subtitle = "I only see some junk here. According to my evaluation, they're not worth more than a few stones."
        },
        [510009032] = {
          ContentKR = "물건을 훔치는 짓은 안 하는 게 좋을 텐데.",
          DialogueId = 510009032,
          GUID = "510009032.0",
          ImprPlusId = 1002,
          NextDialogue = 51000905,
          Subtitle = "It's better not to take things without asking."
        },
        [510009033] = {
          ContentKR = "어디서 난 건데? 나도 끼워줘!",
          DialogueId = 510009033,
          GUID = "510009033.0",
          ImprPlusId = 1005,
          NextDialogue = 51000906,
          Subtitle = "Where did you swipe these from? Teach me that!"
        },
        [510009071] = {
          ContentKR = "아쉽지만 여기엔 나한테 필요한 물건이 없네.",
          DialogueId = 510009071,
          GUID = "510009071.0",
          NextDialogue = 51000907,
          Subtitle = "Sadly, there's nothing I need here."
        },
        [510009072] = {
          ContentKR = "(그는 당신을 훑어보며 깊은 생각에 잠긴 듯 한 표정을 지었다.)",
          DialogueId = 510009072,
          GUID = "510009072.0",
          ImprCheckId = 1004,
          NextDialogue = 51000909,
          Subtitle = "(He scrutinises you closely, revealing a thoughtful expression)"
        },
        [510009101] = {
          ContentKR = "저렴한 연료와 옷감을 제공하는 사람이 있어서 많은 가난한 사람들이 겨울을 편안하게 보낼 수 있었다고 들었어.",
          DialogueId = 510009101,
          GUID = "510009101.0",
          ImprPlusId = 1002,
          Subtitle = "I heard someone can provide some low-priced fuel and cloth to help many poor people get through the winter."
        },
        [510009102] = {
          ContentKR = "정보를 팔긴 하지만 사립탐정처럼 보이진 않는데, 특별한 정보원이라도 있는 건가?",
          DialogueId = 510009102,
          GUID = "510009102.0",
          ImprPlusId = 1003,
          Subtitle = "You sell information, but you don't look like a private detective. Do you have a special source for receiving intelligence?"
        },
        [510009103] = {
          ContentKR = "벌써 마틴이라는 이름을 세 번이나 들었는데, 진짜 뭐 하는 사람이야?",
          DialogueId = 510009103,
          GUID = "510009103.0",
          ImprPlusId = 1005,
          Subtitle = "I've already heard you say Martin three times. Who exactly are you?"
        },
        [510009121] = {
          ContentKR = "그 정도로 신기해?",
          DialogueId = 510009121,
          GUID = "510009121",
          Subtitle = "Is it really that magical?"
        },
        [510009161] = {
          ContentKR = "(수락)",
          DialogueId = 510009161,
          GUID = "510009161.0",
          Subtitle = "(Accept) "
        },
        [510010071] = {
          ContentKR = "네가 잃어버린 물건이야. 이걸 보니 너도 방금 그 사람과 다를 바 없어 보이는데.",
          DialogueId = 510010071,
          GUID = "510010071.0",
          ImprCheckId = 1005,
          NextDialogue = 51001008,
          Subtitle = "You've lost something. That thing proves that you are a shack-dwelling tycoon just like him."
        },
        [510010072] = {
          ContentKR = "네가 잃어버린 물건이야. 만료된 티켓은 통상적으로 위조 방지를 위해 폐기해야 하지. 개인적으로 보관하는 건 엄연한 위법 행위고.",
          DialogueId = 510010072,
          GUID = "510010072.0",
          ImprCheckId = 1006,
          NextDialogue = 51001008,
          Subtitle = "You've lost something. Normally, expired tickets should be destroyed to prevent counterfeiting, and keeping them is obviously a violation."
        },
        [510010101] = {
          ContentKR = "별은 소원을 들어주는 능력이 있다고 하던데, 어떤 소원을 빌려고 승차권으로 별을 수백 개나 접은 거야?",
          DialogueId = 510010101,
          GUID = "510010101.0",
          Subtitle = "Legend has it that stars have the power to fulfil wishes. You folded hundreds of stars from tickets, so what's your wish?"
        },
        [510010181] = {
          ContentKR = "네가 억울하고 슬픈 건 나도 이해해, 인생은 뜻대로 되지 않을 때가 생기기 마련이니까. 하지만 지금 힘들어 보이는 것도 나중에는 쉬워질지도 몰라.",
          DialogueId = 510010181,
          GUID = "510010181.0",
          ImprPlusId = 1004,
          NextDialogue = 51001019,
          Subtitle = "I understand your frustration and sorrow. Life always has disappointment, but what's insurmountable now might one day become a clear path."
        },
        [510010182] = {
