        [510030091] = {
          ContentKR = "그래도 금전적인 손해는 없잖아요.",
          DialogueId = 510030091,
          GUID = "510030091.0",
          ImprPlusId = 1004,
          NextDialogue = 51003010,
          Subtitle = "Mr Buck did not lose any money or personal belongings."
        },
        [510030092] = {
          ContentKR = "아무것도 안 훔쳤다고요? 남이 자는 걸 즐겨 보는 사람인 걸까요?",
