          GUID = "510030092.0",
          ImprPlusId = 1005,
          NextDialogue = 51003010,
          Subtitle = "The thief stole nothing? So they just love to spy on people in their sleep? Yeesh!"
        },
        [510030111] = {
          ContentKR = "바크 씨는 진상을 밝히는 사람을 다음 연극의 주인공으로 선택할 거군요.",
