          GUID = "510030112.0",
          ImprPlusId = 1005,
          NextDialogue = 51003012,
          Subtitle = "This man has no money!"
        },
        [510030121] = {
          ContentKR = "제가 해결해 볼게요, 바크 씨.",
          DialogueId = 510030121,
          GUID = "510030121.0",
          NextDialogue = 51003013,
          Subtitle = "Let me help you, Mr Buck."
