        [510030122] = {
          ContentKR = "됐어요.",
          DialogueId = 510030122,
          GUID = "510030122.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "Forget it."
        },
        [510033051] = {
          ContentKR = "오늘 장사는 어땠어? 밤새 쓸 연료를 사기엔 충분해?",
          DialogueId = 510033051,
          GUID = "510033051.0",
          ImprPlusId = 1002,
          NextDialogue = 510033053,
          Subtitle = "How's business today? Will it cover your heating expenses for the night?"
        },
        [510033052] = {
          ContentKR = "여긴 먹을 것도 별로 없잖아.",
          DialogueId = 510033052,
          GUID = "510033052.0",
          ImprPlusId = 1005,
          NextDialogue = 510033054,
          Subtitle = "These are hardly enough for me. I'm a big eater."
        },
        [510033053] = {
          ContentKR = "덕분에 음식이나 연료를 살 수 있게 됐어요. 인생은 선택이잖아요.",
          DialogueId = 510033053,
          GUID = "510033053.0",
          NextDialogue = 51003306,
          SpeakNpcId = 700080,
          Subtitle = "Your concern is appreciated. I can either afford enough food or fuel. Guess for some people, having it all isn't an option."
        },
        [510033054] = {
          ContentKR = "젤리를 드릴게요! 몇 개 없지만 맛은 보장한답니다!",
          DialogueId = 510033054,
          GUID = "510033054.0",
          NextDialogue = 51003306,
          SpeakNpcId = 700080,
          Subtitle = "Then think of them as appetisers! There isn't much, but the flavor is definitely top-notch!"
        },
        [510033141] = {
          ContentKR = "하지만 넌 바크 씨를 미워하는 것도 아니고 물건을 훔치지도 않았어. 그럼, 왜 한밤중에 들어간 건지 내가 한번 맞춰볼까?",
          DialogueId = 510033141,
          FailDialogue = 51003315,
          GUID = "510033141.0",
          ImprCheckId = 1022,
          NextDialogue = 51003316,
          Subtitle = "You don't hate him and you stole nothing from him. Let me guess why you sneaked into his home in the middle of the night."
        },
        [510034141] = {
          ContentKR = "곧 무언가 일어날 거예요! 얼어붙은 호수 위에 서면 오직 차디차고, 깊고, 응어리진 모습만 볼 수 있죠.",
          DialogueId = 510034141,
          GUID = "510034141.0",
          NextDialogue = 510034142,
          SpeakNpcId = 700015,
          Subtitle = "Something is about to happen! We stand upon the frozen lake, yet we perceive only coldness, deep isolation, and the frigid rigidity of our surroundings.",
          TalkActionId = {
            [1] = "700093:Talk01_Start"
          }
        },
        [510034142] = {
          ContentKR = "다만 우리는 커지고 있는 이 어둠의 흐름이 언젠가 지금의 모든 것을 집어삼킬 거라는 사실을 알고 있어요. 그 전에 저는 기차에 올라 징조의 근원지로 갈 겁니다.",
          DialogueId = 510034142,
          GUID = "510034142.0",
          SpeakNpcId = 700015,
          Subtitle = "But we all know a dark tide is rising, gaining strength. One day it will consume everything we cherish. But before that day comes, I shall journey to the source that has been prophesied.",
          TalkActionId = {
            [1] = "700093:Talk01_End"
          }
        },
        [510034143] = {
          ContentKR = "더 이상 겨울의 추위 때문에 괴롭지 않아요. 고마워요, 월석 사냥꾼.",
          DialogueId = 510034143,
          GUID = "510034143.0",
          SpeakNpcId = 700080,
          Subtitle = "I no longer have to worry about the cold winter. Thank you so much, Phoxhunter.",
          TalkActionId = {
            [1] = "700094:Explain02_Start"
          }
        },
        [510035031] = {
          ContentKR = "(엠마는 급히 정해진 위치에 꽃을 내려놓고, 식순대로 감사의 인사를 전했다. 하지만 엠마는 결국 선생님께 혼나고 말았다.)",
          DialogueId = 510035031,
          Duration = 3,
          GUID = "510035031.0",
          Subtitle = [[
Emma quickly places the floral tribute at the designated location and offers an acknowledgement speech according to the program agenda.
However, her teacher is displeased with her momentary distraction.]]
        },
        [510035041] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "이제 자유 시간이야. 30분 후에 조각상 밑에서 모여야 하니 다들 너무 멀리 가진 말도록 하렴.",
          DialogueId = 510035041,
          GUID = "510035041.0",
          NextDialogue = 510035042,
          SpeakNpcId = 700086,
          Subtitle = "Alright. We'll have a short break now. Feel free to explore this place, but do not stray too far. We will regather in half an hour beneath the statue.",
          TalkActionId = {
            [1] = "700086:Sigh_End",
            [2] = "700086:Explain01_Start"
          }
        },
        [510035042] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "(기념행사가 끝난 후 홀로 남은 엠마는 멍하니 중얼거리고 있다.)",
          DialogueId = 510035042,
          GUID = "510035042.0",
          Subtitle = "(The memorial event has ended. However, Emma lingers alone, mumbling absentmindedly to herself.)",
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [510035051] = {
          ContentKR = "그런 식으로 선생님 말씀을 흘려들으면 안 돼. 찍힐 수도 있으니까 조심하는 게 좋을걸.",
          DialogueId = 510035051,
          GUID = "510035051.0",
          ImprPlusId = 1001,
          NextDialogue = 510035054,
          Subtitle = "You're totally spacing out. Pretty sure your teacher's putting you on the naughty list."
        },
        [510035052] = {
          ContentKR = "추모식 말고 가고 싶은 곳이 있는 거지?",
          DialogueId = 510035052,
          GUID = "510035052.0",
          ImprPlusId = 1004,
          NextDialogue = 510035055,
          Subtitle = "Is there something you'd rather be doing instead of participating in this memorial ceremony?"
        },
        [510035053] = {
          ContentKR = "공식적인 자리에서 집중하지 못 하는 건 예의가 아니야.",
          DialogueId = 510035053,
          GUID = "510035053.0",
          ImprPlusId = 1002,
          NextDialogue = 510035056,
          Subtitle = "Tuning out on an occasion like this is quite disrespectful, especially to those being memorialised."
        },
        [510035054] = {
          ContentKR = "선생님은 안 그러셔! 잔소리를 하시긴 해도, 인내심이 있으시다고!",
          DialogueId = 510035054,
          GUID = "510035054",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003506,
          SpeakNpcId = 700016,
          Subtitle = "No, she won't! Miss Lisse nags from time to time, but she's actually very patient with us!"
        },
        [510035055] = {
          ContentKR = "앗, 그게 티 났어?",
          DialogueId = 510035055,
          GUID = "510035055",
          NextDialogue = 51003506,
          SpeakNpcId = 700016,
          Subtitle = "Oh! Am I being that obvious?"
        },
        [510035056] = {
