        [510040061] = {
          ContentKR = "알았으면 꺼져.",
          DialogueId = 510040061,
          GUID = "510040061.0",
          NextDialogue = 51004008,
          Subtitle = "Since you know we're Charons, you better scram."
        },
        [510040062] = {
          ContentKR = "소녀가 나름 착한 말을 고민 중이니, 조금만 기다린다.",
