          DialogueId = 510049032,
          GUID = "510049032.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Leave)"
        },
        [510049091] = {
          ContentKR = "진정해요. 당신을 위협하러 온 게 아니에요.",
          DialogueId = 510049091,
          GUID = "510049091.0",
          ImprPlusId = 1002,
          NextDialogue = 51004910,
          Subtitle = "Relax. I'm not here to threaten you."
        },
        [510049092] = {
          ContentKR = "루나처럼 허공에 손짓한다.",
          DialogueId = 510049092,
          GUID = "510049092.0",
          ImprPlusId = 1005,
          NextDialogue = 51004911,
          Subtitle = "Gesture like she does."
        },
        [510049141] = {
          ContentKR = "'나중엔 로터스로 만든 독약까지 먹였어요. 목숨은 건졌지만, 두 번 다시 말을 할 수 없게 되어 버렸죠.'",
          DialogueId = 510049141,
          GUID = "510049141.0",
          NextDialogue = 51004915,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Then they forced poison brewed from Eclipta Grass down my throat. It didn't kill me... but it took my voice.\"",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [510049171] = {
          ContentKR = "이런 걸 쓰는 게 무슨 소용이에요? 본인만 곤란해질 뿐, 변하는 건 없잖아요.",
          DialogueId = 510049171,
          GUID = "510049171.0",
          ImprPlusId = 1001,
          NextDialogue = 51004918,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "But it won't change anything. It only gets you in trouble."
        },
        [510049172] = {
          ContentKR = "이렇게 힘든 와중에도 창작 활동을 하시다니, 용기가 존경스럽습니다.",
          DialogueId = 510049172,
          GUID = "510049172.0",
          ImprPlusId = 1004,
          NextDialogue = 51004923,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Despite enduring such a great misfortune, you still keep on writing. I truly admire your courage."
        },
        [510049173] = {
          ContentKR = "종이는 제가 갖고 있으니, 돌려받고 싶거든 대가를 지불하세요.",
          DialogueId = 510049173,
          GUID = "510049173.0",
          ImprPlusId = 1005,
          NextDialogue = 51004927,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "This \"prescription\" is now in my hands. Better pay up if you want it back."
        },
        [510050121] = {
          ContentKR = "이제 모두 이 집을 귀신의 집이라고 생각하는데, 당신은 아무렇지 않은 것 같네요.",
          DialogueId = 510050121,
          FailDialogue = 51005013,
          GUID = "510050121.0",
          ImprCheckId = 1024,
          NextDialogue = 51005015,
          Subtitle = "Everyone sees this house as a haunted place, but you seem neither disturbed nor surprised."
        },
        [510050171] = {
          ContentKR = "헨릭 씨와 오래 알고 지내셨나요?",
          DialogueId = 510050171,
          GUID = "510050171.0",
          NextDialogue = 51005018,
          Subtitle = "Have you known Mr Henrik for a long time?"
        },
        [510050201] = {
          ContentKR = "아쉽게도 헨릭 씨의 선의가 명성으로 이어지지는 않았네요.",
          DialogueId = 510050201,
          GUID = "510050201.0",
          ImprPlusId = 1001,
          NextDialogue = 51005021,
          Subtitle = "Too bad his kindness failed to earn him the reputation he deserved."
        },
        [510050202] = {
          ContentKR = "도리가 무엇인지 잘 아는 분이셨네요.",
          DialogueId = 510050202,
          GUID = "510050202.0",
          ImprPlusId = 1002,
          NextDialogue = 51005022,
          Subtitle = "He upheld the fundamental values that define the humanity."
        },
        [510050203] = {
          ContentKR = "아마... 딸 생각이 났을 거예요.",
          DialogueId = 510050203,
          GUID = "510050203.0",
          ImprPlusId = 1004,
          NextDialogue = 51005023,
          Subtitle = "Perhaps... that Charon girl reminded him of his own daughter."
        },
        [510050231] = {
          ContentKR = "당신이 여전히 관리하고 있다는 사실을 돌아가신 헨릭 씨가 알면 분명 기뻐하실 거예요.",
          DialogueId = 510050231,
          GUID = "510050231.0",
          NextDialogue = 51005024,
          Subtitle = "Mr Henrik would be pleased to know his home has been well cared for after his departure."
        },
        [510050261] = {
          ContentKR = "(레나가 들고 있는 열쇠가 어딘가 익숙하다.)",
          DialogueId = 510050261,
          FailDialogue = 51005027,
          GUID = "510050261.0",
          ImprCheckId = 1025,
          NextDialogue = 51005028,
          Subtitle = "(The key in Ms Lina's hand stirs a sense of familiarity.)"
        },
        [510050291] = {
          ContentKR = "레나 아주머니, 이 열쇠를 아세요?",
          DialogueId = 510050291,
          GUID = "510050291.0",
          NextDialogue = 51005030,
          Subtitle = "Ms Lina, is this key familiar to you?"
        },
        [510050391] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentKR = "자, 받으세요. 제가 증인이잖아요. 이 열쇠는 레나 아주머니 거예요.",
          DialogueId = 510050391,
          GUID = "510050391.0",
          SpeakNpcId = 100001,
          Subtitle = "Please accept this. I shall bear witness to this transfer. This key is, and shall forever be, yours."
        },
        [510050411] = {
          ContentKR = "이 태양 아래의 모든 사람이 완전무결한 건 아니야.",
          DialogueId = 510050411,
          GUID = "510050411.0",
          SpeakNpcId = 700013,
          Subtitle = "Not all who dwell in the light live with a clear conscience."
        },
        [510051051] = {
          ContentKR = "별생각 없어. 목적이 있어서 잠깐 머무는 것뿐이거든.",
          DialogueId = 510051051,
          GUID = "510051051.0",
          ImprPlusId = 1001,
          NextDialogue = 51005106,
          Subtitle = "I don't judge and I don't care. I've got things to do here, and that's why I'm staying for now."
        },
        [510051052] = {
          ContentKR = "이런 대도시는 처음인데, 조금 특이한 것 같아. 새로운 사람을 만나고, 새로운 일을 겪었거든. 솔직히 아직 좀 어색해...",
          DialogueId = 510051052,
          GUID = "510051052.0",
          ImprPlusId = 1004,
          NextDialogue = 51005107,
          Subtitle = "It's my first visit to a large city like this. The place has a unique vibe. I've met plenty of interesting people and had some bizarre adventures here. Truth be told, I'm not very used to it..."
        },
        [510051053] = {
          ContentKR = "집에 온 느낌이야!",
          DialogueId = 510051053,
          GUID = "510051053.0",
          ImprPlusId = 1005,
          NextDialogue = 51005108,
          Subtitle = "Feels just like home!"
        },
        [510051111] = {
          ContentKR = "낡아서 별 가치가 없을 것 같아.",
          DialogueId = 510051111,
          GUID = "510051111.0",
          ImprPlusId = 1001,
          NextDialogue = 51005112,
          Subtitle = "Just a bunch of second-hand stuff with no real value."
        },
        [510051112] = {
          ContentKR = "근데 이 물건들... 훔쳐 온 건 아니지?",
          DialogueId = 510051112,
          GUID = "510051112.0",
          ImprPlusId = 1002,
          NextDialogue = 51005113,
          Subtitle = "I have to ask this first — these aren't... stolen, by any chance?"
        },
        [510051113] = {
          ContentKR = "어디서 난 건데? 하나 가져갈래!",
          DialogueId = 510051113,
          GUID = "510051113.0",
          ImprPlusId = 1005,
          NextDialogue = 51005114,
          Subtitle = "Where did you get them? Count me in!"
        },
        [510051151] = {
          ContentKR = "(처방전 하나를 집는다. 위에 그다지 '친절'하지 않아 보이는 싯구가 적혀 있는 듯하다.)",
          DialogueId = 510051151,
          FailDialogue = 51005116,
          GUID = "510051151.0",
          ImprCheckId = 1040,
          NextDialogue = 51005117,
          Subtitle = "(You pick up a prescription. A seemingly seditious poem is written behind it.)"
        },
        [510051152] = {
          ContentKR = "(종이별이 담긴 상자를 집는다. 물건의 주인은 분명히 꼭 이루고 싶은 소망이 있을 것이다.)",
          DialogueId = 510051152,
          FailDialogue = 51005116,
          GUID = "510051152.0",
          ImprCheckId = 1041,
          NextDialogue = 51005117,
          Subtitle = "(You pick up a box of paper stars. Its owner probably had a wish they wanted to fulfil.)"
        },
        [510051153] = {
          ContentKR = "(열쇠 하나를 집는다. 열쇠 모양이 왠지 눈에 익은 게, 헨릭의 집에서 본 것과 비슷한 듯하다.)",
          DialogueId = 510051153,
          FailDialogue = 51005116,
          GUID = "510051153.0",
          ImprCheckId = 1042,
          NextDialogue = 51005117,
          Subtitle = "(You pick up a key that looks rather familiar — you remember seeing a similar key at Henrik's place.)"
        },
        [510051251] = {
          ContentKR = "이 정도면 될까?",
          DialogueId = 510051251,
          GUID = "510051251.0",
          ImprPlusId = 1002,
          NextDialogue = 51005126,
          Subtitle = "Will these coins be enough?"
        },
        [510051252] = {
          ContentKR = "20% 할인해 준다고 했지?",
          DialogueId = 510051252,
          GUID = "510051252.0",
          ImprPlusId = 1001,
          NextDialogue = 51005127,
          Subtitle = "What about my 20% discount?"
        },
        [510051253] = {
          ContentKR = "안 살래.",
          DialogueId = 510051253,
          GUID = "510051253.0",
          ImprPlusId = 1005,
          NextDialogue = 51005128,
          Subtitle = "Outta here."
        },
        [510051321] = {
          ContentKR = "행운을 빌어요, 탐정님!",
          DialogueId = 510051321,
          GUID = "510051321.0",
          NextDialogue = 510051322,
          SpeakNpcId = 700115,
          Subtitle = "Good luck with your investigations, Detective!"
        },
        [510051322] = {
          ContentKR = "이것들의 사연을 알아낸 후에, 아이스레이크 시티에 대한 느낌을 다시 말해줘요!",
          DialogueId = 510051322,
          GUID = "510051322.0",
          SpeakNpcId = 700115,
          Subtitle = "Once you've investigated the stories behind them, come back and tell me what you think about Icelake!"
        },
        [510052021] = {
          ContentKR = "처방전의 주인은 의사인 루나였어. 음유시인이었던 루나는 자신의 목소리를 앗아간 카론을 증오했지. 이 말들은 자신이 털어놓을 수 있는 유일한 방법이었어.",
          DialogueId = 510052021,
          GUID = "510052021.0",
          NextDialogue = 51005203,
          Subtitle = "Dr Luna wrote the prescription. She was once a wandering bard, but some Charon-haters took her voice. Now, composing poems in this way is her only outlet for expressing her anguish."
        },
        [510052022] = {
          ContentKR = "매표원 제시카는 이곳을 떠나는 기차를 타는 게 소원이었어. 하지만 이미 기한이 지나버린 기차표로 별을 접으면서 기적을 기다릴 수밖에 없었지.",
          DialogueId = 510052022,
          GUID = "510052022.0",
          NextDialogue = 51005204,
          Subtitle = "The biggest dream of Jessica, the ticket seller, is to take a train and leave this place. All she could do was fold expired tickets into paper stars and pray for a miracle."
        },
        [510052023] = {
          ContentKR = "열쇠는 금고의 열쇠였어. 그리고 거기서 유언장을 하나 발견했지. 레나 씨가 새로운 집 주인이 되었고, 내 임대료를 면제해 줬어.",
          DialogueId = 510052023,
          GUID = "510052023.0",
          NextDialogue = 51005205,
          Subtitle = "That key opens a safe. Inside, we found a will, and Ms Lina became my new landlady. She also said I could stay rent-free."
        },
        [510052081] = {
          ContentKR = "아이스레이크 시티에서는 '안전'한 일만 해야겠어. 선을 넘으면 잃는 게 더 많아.",
          DialogueId = 510052081,
          GUID = "510052081.0",
          ImprPlusId = 1001,
          NextDialogue = 51005209,
          Subtitle = "Always try to play it \"safe\" in Icelake. Going the extra mile will just get yourself and others into trouble. It really isn't worth it."
        },
        [510052082] = {
          ContentKR = "순탄한 삶을 사는 건 쉽지 않아. 아이스레이크 시티에서 우리가 유일하게 지킬 수 있는 건 본인의 원칙뿐이지.",
          DialogueId = 510052082,
          GUID = "510052082.0",
          ImprPlusId = 1002,
          NextDialogue = 51005209,
          Subtitle = "Life is seldom a breeze. The only thing we can do in Icelake is stick to our principles."
        },
        [510052083] = {
          ContentKR = "다들 '도시의 규칙'을 따르는 건 아니잖아. 그렇다면 따르지 않는 사람은 얼마나 있을까?",
          DialogueId = 510052083,
          GUID = "510052083.0",
          ImprPlusId = 1003,
          NextDialogue = 51005209,
          Subtitle = "Not everyone believes in the \"city laws\". It makes you wonder how many people break the rules in the dark."
        },
        [510052084] = {
          ContentKR = "사람들에게는 희망과 믿음, 그리고 고충이 있어... 이런 것들 때문에 사건도 생기는 거지.",
          DialogueId = 510052084,
          GUID = "510052084.0",
          ImprPlusId = 1004,
          NextDialogue = 51005209,
          Subtitle = "The people here cling to their hopes, faiths, and circumstances... These are all they have. They try to hold on, and then bad things happen."
        },
        [510052085] = {
          ContentKR = "도시는 위험해. 눈물의 호수는 언제든 마를 수 있지!",
          DialogueId = 510052085,
          GUID = "510052085.0",
          ImprPlusId = 1005,
          NextDialogue = 51005209,
          Subtitle = "The city's like powder kegs ready to explode! Lamenting Lake shall vaporize and give us a show!"
        },
