        },
        [510067091] = {
          ContentKR = "솔직히 나도 이길 수 없어 보이는 기록이면 도전할 맛이 안 날 것 같아.",
          DialogueId = 510067091,
          GUID = "510067091.0",
          ImprPlusId = 1004,
          NextDialogue = 51006710,
          Subtitle = "That's understandable. I wouldn't want to compete against an unbeatable record either."
        },
        [510067092] = {
          ContentKR = "그래서 날 이용해서 아웃사이더한테 복수한 거구나.",
          DialogueId = 510067092,
          GUID = "510067092.0",
          ImprPlusId = 1001,
          NextDialogue = 51006712,
          Subtitle = "So you were using me to get back at Outsider."
        },
        [510067093] = {
          ContentKR = "아웃사이더, 그렇게 느려서 얼굴이나 들고 다니겠어? 차라리 직업을 바꾸는 게 어때?",
          DialogueId = 510067093,
          GUID = "510067093.0",
          ImprPlusId = 1005,
          NextDialogue = 51006715,
          Subtitle = "You're too slow, Outsider. That's just embarrassing. Maybe it's time for a career switch."
        },
        [510070011] = {
          ContentKR = "이 도시는 분위기가 원래 그런가 봐요. 듣다 보면 익숙해질 거예요.",
          DialogueId = 510070011,
          GUID = "510070011.0",
          ImprPlusId = 1004,
