          DialogueId = 710020031,
          GUID = "710020031.0",
          Subtitle = "(Pick him up and bring him back to the girl)"
        },
        [710020032] = {
          ContentKR = "(고양이를 그대로 둔 채, 소녀에게 적당한 핑계를 대며 둘러댄다.)",
          DialogueId = 710020032,
          GUID = "710020032.0",
