        },
        [710035041] = {
          ContentKR = "사과로 끝날 거였으면 내 주먹은 왜 있겠어. 오늘 제대로 뼈저리게 기억하게 해주지.",
          DialogueId = 710035041,
          GUID = "710035041.0",
          Subtitle = "If \"sorry\" fixed everything, I wouldn't need my sword. Let this be a lesson you don't forget."
        },
        [710035042] = {
          ContentKR = "그런 말 하는 사람들이 한둘인 줄 알아? 하지만 한 번만 기회를 주지. 다시는 이런 짓 하지 마.",
          DialogueId = 710035042,
          GUID = "710035042.0",
          Subtitle = "I've heard that line more times than I can count. But I'll give you a second chance. Don't blow it."
        },
        [710037041] = {
          ContentKR = "오케이, 문제없어. 아우우~ 아우우우~!",
          DialogueId = 710037041,
          GUID = "710037021.0",
          NextDialogue = 71003705,
          Subtitle = "Got it. Pow! Bam! Consider them punched."
        },
        [710037042] = {
