        },
        [710052141] = {
          ContentKR = "와, 정말 신기하네! 행복 동전 전부 다 살게!",
          DialogueId = 710052141,
          GUID = "710052071.0",
          Subtitle = "They're amazing! I'll take all of them!"
        },
        [710052142] = {
          ContentKR = "난... 무언가에 의지하기보단, 내 스스로 행복을 찾고 싶어.",
          DialogueId = 710052142,
          GUID = "710052072.0",
          Subtitle = "I think I'd rather earn happiness on my own."
        },
        [710053081] = {
          ContentKR = "(돈을 챙긴다. 내성의 잘난 사람들에게 한 번쯤은 이런 맛도 보여줘야지.)",
          DialogueId = 710053081,
          GUID = "710053121.0",
          Subtitle = "(Pocket the money. Let those spoiled rich kids learn what the real world's like.)"
        },
        [710053082] = {
          ContentKR = "(물건을 돌려준다. 어디서 왔든, 잃어버린 슬픔만큼은 모두 똑같다.)",
          DialogueId = 710053082,
          GUID = "710053122.0",
          Subtitle = "(Return the money. Getting robbed sucks — rich or poor.)"
        },
        [710054021] = {
          ContentKR = "좋아, 한번 해보자.",
          DialogueId = 710054021,
          GUID = "710054031.0",
          Subtitle = "Give it a try"
        },
        [710054022] = {
          ContentKR = "음, 잠깐만... 뭔가 수상한데?",
          DialogueId = 710054022,
          GUID = "710054032.0",
          Subtitle = "Maybe later"
        },
        [710054041] = {
          ContentKR = "상자를 건드리기만 해도 고장나던데... 미리 손을 써둔 게 아니라면, 이 자물쇠 심을 분해해서 모두에게 보여줘도 될까?",
          DialogueId = 710054041,
          GUID = "710054071.0",
          NextDialogue = 71005405,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "A box that breaks just from trying it? If it's not rigged, how about I pop that lock out — let the crowd have a proper look."
        },
        [710054042] = {
          ContentKR = "지난번에 나한테 같은 수작 부리다가 병원 신세를 진 친구가 생각나는군.",
          DialogueId = 710054042,
          GUID = "710054072.0",
          NextDialogue = 71005407,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Last guy who tried to scam me is still recovering in hospital."
        },
