        },
        [710077052] = {
          ContentKR = "중급 보물 상자",
          DialogueId = 710077052,
          GUID = "710077052.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "Standard Chest"
        },
        [710077053] = {
          ContentKR = "고급 보물 상자",
          DialogueId = 710077053,
          GUID = "710077053.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{3}}",
          Subtitle = "Premium Chest"
        },
        [710077054] = {
          ContentKR = "다 갖고 싶은데요.",
          DialogueId = 710077054,
          GUID = "710077054.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{4}}",
          Subtitle = "I'll take all of them"
        },
        [710078021] = {
          ContentKR = "(수락한다.)",
          DialogueId = 710078021,
          GUID = "710078021.0",
          NextDialogue = 71007803,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "(Accept.)"
        },
        [710078022] = {
          ContentKR = "(거절한다.)",
          DialogueId = 710078022,
          GUID = "710078022.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "(Decline.)"
        },
        [710078051] = {
          ContentKR = "(셀 수 없이 많은 보물 상자를 갖는 것)",
          DialogueId = 710078051,
          GUID = "710078051.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "(Endless treasure chests)"
        },
        [710078052] = {
          ContentKR = "(적을 없애는 것)",
          DialogueId = 710078052,
          GUID = "710078052.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "(Eliminate every foe)"
        },
        [710078053] = {
          ContentKR = "(그리운 사람을 다시 만나는 것)",
          DialogueId = 710078053,
          GUID = "710078053.0",
          Scripts = "SetOutport{FinishType{2},OptionIdx{3}}",
          Subtitle = "(See the person you've missed dearly)"
        },
        [710079051] = {
          ContentKR = "(보물이 진정한 가치를 발휘하려면, 땅에 묻어둘 게 아니라, 본래 용도에 맞게 사용해야 한다고 가르쳐 준다.)",
          DialogueId = 710079051,
          GUID = "710079051.0",
          NextDialogue = 71007906,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "(Tell him that treasure buried deep underground is worthless — it only finds meaning when brought out and put to use.)"
        },
        [710079052] = {
          ContentKR = "(어른의 속마음은 숨긴 채, 비밀을 알려 줘서 고맙다고 말하며 동심을 지켜 준다.)",
          DialogueId = 710079052,
          GUID = "710079052.0",
          NextDialogue = 71007908,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "(Thank him for the secret and keep your heavier thoughts to yourself, so as to protect his innocence.)"
        },
        [710080021] = {
          Content = "（接受。）",
