          ContentKR = "그 귀찮은 일들 네가 처리해준 거였구나.",
          DialogueId = 801901172,
          GUID = "801901172.0",
          NextDialogue = 80190119,
          Subtitle = "So you've been chasing off the freeloaders for me?"
        },
        [801902011] = {
          ContentKR = "술 한 잔 주겠다는 사람한테 늦게 오다니, 너무하네.",
          DialogueId = 801902011,
          GUID = "801902011.0",
          NextDialogue = 80190203,
          Subtitle = "It's rude to be late when someone invites you for a drink."
        },
        [801902012] = {
          ContentKR = "사과는 무슨, 그냥 한 잔이라도 더 마시려는 거잖아?",
          DialogueId = 801902012,
          GUID = "801902012.0",
          NextDialogue = 80190202,
          Subtitle = "That's not an apology. You're just angling for more drinks."
        },
        [801902041] = {
          ContentKR = "혹시 군단 쪽?",
          DialogueId = 801902041,
          GUID = "801902041.0",
          NextDialogue = 80190205,
          Subtitle = "The Legion?"
        },
        [801902151] = {
          ContentKR = "그 일에 비하면, 삼십 분 정도 늦은 건 아무것도 아니지.",
          DialogueId = 801902151,
          GUID = "801902151.0",
          NextDialogue = 80190216,
          Subtitle = "In that case, thirty minutes late doesn't sound so bad."
        },
        [801902152] = {
          ContentKR = "지금은 여기서 술 마실 때가 아니고, 얼른 돌아가서 쉬어야 해.",
          DialogueId = 801902152,
          GUID = "801902152.0",
          NextDialogue = 80190217,
          Subtitle = "You should be getting rest, not drinking."
        },
        [801902191] = {
          ContentKR = "말투 보니까, 꽤 싫어하는 모양인데?",
          DialogueId = 801902191,
          GUID = "801902191.0",
          NextDialogue = 80190220,
          Subtitle = "You really hate them, don't you?"
        },
        [801903031] = {
          ContentKR = "뭐라도 좀 말해봐.",
          DialogueId = 801903031,
          GUID = "801903031.0",
          NextDialogue = 80190304,
          Subtitle = "Say something."
        },
        [801903032] = {
          ContentKR = "괜찮은 거야?",
          DialogueId = 801903032,
          GUID = "801903032.0",
          NextDialogue = 80190304,
          Subtitle = "You okay?"
        },
        [801903061] = {
          ContentKR = "혹시 눈물 닦을 손수건 준비해줘야 하는 거 아냐?",
          DialogueId = 801903061,
          GUID = "801903061.0",
          NextDialogue = 80190307,
          Subtitle = "Should I be getting you a handkerchief?"
        },
        [801903062] = {
          ContentKR = "계속 이러면 너, 진짜 울어버릴 거 같은데?",
          DialogueId = 801903062,
          GUID = "801903062.0",
          NextDialogue = 80190307,
          Subtitle = "Are you gonna cry?"
        },
        [801903151] = {
          ContentKR = "친구끼리 자신의 과거를 나누는 건 아주 자연스러운 일이야.",
          DialogueId = 801903151,
          GUID = "801903151.0",
          NextDialogue = 80190316,
          Subtitle = "I think it's totally normal to open up to friends."
        },
        [801903152] = {
          ContentKR = "난 모두를 믿어. 네가 너무 극단적인 거야.",
          DialogueId = 801903152,
          GUID = "801903152.0",
          NextDialogue = 80190316,
          Subtitle = "That's a bit cynical. I still believe in people."
        },
        [801903171] = {
          ContentKR = "보니까 아웃사이더는 나를 진짜 친구로 생각하지 않는 것 같아...",
          DialogueId = 801903171,
          GUID = "801903171.0",
          NextDialogue = 80190318,
          Subtitle = "So what you're saying is, I'm not really your friend..."
        },
        [801903221] = {
          ContentKR = "내가 따른 건 국이 아니야!",
          DialogueId = 801903221,
          GUID = "801903221.0",
          NextDialogue = 80190323,
          Subtitle = "I'm not running a soup kitchen here, you know."
        },
        [801903222] = {
          ContentKR = "네가 원한다면.",
          DialogueId = 801903222,
          GUID = "801903222.0",
          NextDialogue = 80190323,
          Subtitle = "Sure. Just try not to gulp this one down too."
        },
        [801903231] = {
          ContentKR = "응, 좋은 친구에 좋은 술, 거기다 좋은 개까지.",
          DialogueId = 801903231,
          GUID = "801903231.0",
          NextDialogue = 80190324,
          Subtitle = "Mhm. Good booze, good banter, and one very talkative mutt."
        },
        [801904021] = {
          ContentKR = "아니야.",
          DialogueId = 801904021,
          GUID = "801904021.0",
          NextDialogue = 80190403,
          Subtitle = "I didn't say anything."
        },
        [801904091] = {
          ContentKR = "그때 그... 포세이큰 동맹에 물건 배달하는 의뢰 말이야?",
          DialogueId = 801904091,
          GUID = "801904091.0",
          NextDialogue = 80190410,
          Subtitle = "You mean the delivery job from earlier?"
        },
        [801904161] = {
          ContentKR = "알겠어. 빨리 가.",
          DialogueId = 801904161,
          GUID = "801904161.0",
          NextDialogue = 80190417,
          Subtitle = "Got it. You should go."
        },
        [801904162] = {
          ContentKR = "하지만 넌 술친구가 아니잖아.",
          DialogueId = 801904162,
          GUID = "801904162.0",
          NextDialogue = 80190417,
          Subtitle = "You're not just a drinking buddy."
        },
        [801904321] = {
          ContentKR = "끝장 보는 건 너도 만만치 않잖아.",
          DialogueId = 801904321,
          GUID = "801904321.0",
          NextDialogue = 80190433,
          Subtitle = "Talk about having no moral scruples... you'd almost rival the Forsakens."
        },
        [801904322] = {
          ContentKR = "그럼 아직 네가 떠나야 할 때는 아니라는 뜻이겠네.",
          DialogueId = 801904322,
          GUID = "801904322.0",
          NextDialogue = 80190433,
          Subtitle = "So you've got no reason to run away this time either, right?"
        },
        [801904361] = {
          ContentKR = "뭐 마시고 싶은 거 있어?",
          DialogueId = 801904361,
          GUID = "801904361.0",
          NextDialogue = 80190437,
          Subtitle = "Not at all. Want another drink?"
        },
        [801904362] = {
          ContentKR = "기분 나빴으니까, 배상해. 돈으로.",
          DialogueId = 801904362,
          GUID = "801904362.0",
          NextDialogue = 80190437,
          Subtitle = "You absolutely did. You owe me money for emotional damage."
        },
        [802000021] = {
          ContentKR = "식물 얘긴 거 같은데, 책에 실릴 정도면, 꽤 귀한 건가 보네.",
          DialogueId = 802000021,
          GUID = "C8C5B4FE",
          NextDialogue = 80200004,
          Subtitle = "They sound like plant names. If they're listed in that book you're reading, I figure they must be useful for something."
        },
        [802000022] = {
          ContentKR = "약초들 얘기인 것 같네. 의학 서적에서 다룰 법한 내용들인걸.",
          DialogueId = 802000022,
          GUID = "C8C5B552",
          NextDialogue = 80200006,
          Subtitle = "That sounds like something from a medical text. Is it about herbs?"
        },
        [802000023] = {
          ContentKR = "집중해서 읽고 있는 것 같던데, 혹시 방해됐어?",
          DialogueId = 802000023,
          GUID = "C8C5B5A6",
          NextDialogue = 80200008,
          Subtitle = "Am I interrupting? You seemed deeply absorbed in your reading."
        },
        [802000101] = {
          ContentKR = "부소 혼자 여기서 지내는 데 불편하진 않아?",
          DialogueId = 802000101,
          GUID = "C8C5B64E",
          NextDialogue = 80200012,
          Subtitle = "Is it hard, living here all on your own?"
        },
        [802000102] = {
          ContentKR = "뭐 그런 걸로. 신경 안 써도 돼.",
          DialogueId = 802000102,
          GUID = "C8C5B6A2",
          NextDialogue = 80200014,
          Subtitle = "It's nothing."
        },
        [802000103] = {
          ContentKR = "큰일 났네. 또 밥 못 얻어먹게 생겼잖아.",
          DialogueId = 802000103,
          GUID = "C8C5B6F6",
          NextDialogue = 80200016,
          Subtitle = "Oh no — there goes my free meal!"
        },
        [802000271] = {
          ContentKR = "고영법을 덜 쓰려고 하는 건데, 좋은 일이잖아. 그 정도쯤이야 얼마든 도와줄게. ",
          DialogueId = 802000271,
          GUID = "C8C5B918",
          NextDialogue = 80200029,
          Subtitle = "If it helps you rely less on the Art of Ephemerality, I'd be glad to help."
        },
        [802000272] = {
          ContentKR = "이런 공짜 진료 기회를 놓칠 순 없지! 자, 어디서부터 봐 줄 거야?",
          DialogueId = 802000272,
          GUID = "C8C5B96C",
          NextDialogue = 80200031,
          Subtitle = "Free check-ups? Count me in! How do we start?"
        },
        [802000273] = {
          ContentKR = "겨우 그거였어? 난 촉룡이랑 제대로 한판 하러 가자는 줄 알았어.",
          DialogueId = 802000273,
          GUID = "C8C5B9C0",
          NextDialogue = 80200033,
          Subtitle = "That's it? I thought you were going to ask me to fight Zhuyin or something!"
        },
        [802000371] = {
          ContentKR = "요즘 이런저런 일로 바빠서, 잠을 좀 못 자긴 했어...",
          DialogueId = 802000371,
          GUID = "C8C5BABC",
          NextDialogue = 80200039,
          Subtitle = "I've just been on the move a lot lately. Haven't really had the chance..."
        },
        [802000372] = {
          ContentKR = "지류 사장님의 두둑한 용돈을 포기할 순 없잖아. 바빠서 잘 시간이 없었어.",
          DialogueId = 802000372,
          GUID = "C8C5BB10",
          NextDialogue = 80200041,
          Subtitle = "I've been chasing Proprietress Zhiliu's sky-high allowance — who has time to sleep with that kind of reward dangling in front of you?"
        },
        [802000373] = {
          ContentKR = "훗, 잠 같은 건, 딱히 안 자도 아무 지장 없어.",
          DialogueId = 802000373,
          GUID = "C8C5BB8E",
          NextDialogue = 80200044,
          Subtitle = "Bah, sleep's overrated. Who really needs it anyway?"
        },
        [802001141] = {
          ContentKR = "?",
          DialogueId = 802001141,
          GUID = "C8C5C75E",
          NextDialogue = 80200118,
          Subtitle = "?"
        },
        [802001142] = {
          ContentKR = "??",
          DialogueId = 802001142,
          GUID = "C8C5C788",
          NextDialogue = 80200118,
          Subtitle = "??"
        },
        [802001143] = {
          ContentKR = "???",
          DialogueId = 802001143,
          GUID = "C8C5C7B2",
          NextDialogue = 80200118,
          Subtitle = "???"
        },
        [802001371] = {
          ContentKR = "난 부소의 언니가 아니라 친구야. 네 친구 {nickname}. 우린 같이 약초를 찾고 있었어.",
          DialogueId = 802001371,
          GUID = "C8C5CB24",
          NextDialogue = 80200139,
          Subtitle = "I'm not your sister. I'm your friend — . We're here gathering herbs, remember?"
        },
        [802001372] = {
          ContentKR = "그래, 언니 맞아. 언니가 잘못했어.",
          DialogueId = 802001372,
          GUID = "C8C5CB78",
          NextDialogue = 80200141,
          Subtitle = "I AM your sister. I've realised how wrong I was."
        },
        [802001373] = {
          ContentKR = "난 언니가 아니라, 네 엄마다!",
          DialogueId = 802001373,
          GUID = "C8C5CBCC",
          NextDialogue = 80200143,
          Subtitle = "Actually, I'm your mother."
        },
        [802001501] = {
          ContentKR = "네 탓이 아니야. 나 푹 자게 해 주려고 잎사귀를 맛봤던 거잖아.",
          DialogueId = 802001501,
          GUID = "C8C5CD46",
          NextDialogue = 80200153,
          Subtitle = "You ate that herb just to help me sleep — how could I blame you?"
        },
        [802001502] = {
          ContentKR = "나보나 나이 훨씬 많은 사람한테 처음으로 언니 소리 들으니까, 되게 짜릿하더라.",
          DialogueId = 802001502,
          GUID = "C8C5CD70",
          NextDialogue = 80200153,
          Subtitle = "First time someone a century older than me mistook me for their big sister. Weirdly exhilarating."
        },
        [802002251] = {
          ContentKR = "부소는 성실하고, 환자한테도 정성을 다해요. 우린 친구고요.",
          DialogueId = 802002251,
          GUID = "C8C5D358",
          NextDialogue = 80200226,
          Subtitle = "Fushu treats everyone with sincerity. She's a good physician — and a good friend."
        },
        [802002252] = {
          ContentKR = "전 부소의 환자예요. 저번에 저한테 진료비를 바가지 씌워서, 되돌려받으러 왔어요.",
          DialogueId = 802002252,
          GUID = "C8C5D3AC",
          NextDialogue = 80200227,
          Subtitle = "I'm actually one of her patients. She charged me a fortune last time — I'm here to get my money back."
        },
        [802002253] = {
          ContentKR = "미인이시네요! 전 부소를 만나러 온 게 아니라, 당신을 보러 온 거예요!",
          DialogueId = 802002253,
          GUID = "C8C5D400",
          NextDialogue = 80200228,
          Subtitle = "Hello, pretty lady! I'm not here for Fushu — I came for you!"
        },
        [802003071] = {
          ContentKR = "?",
          DialogueId = 802003071,
          GUID = "C8C5E708",
          NextDialogue = 80200311,
          Subtitle = "?"
        },
        [802003072] = {
          ContentKR = "??",
          DialogueId = 802003072,
          GUID = "C8C5E732",
          NextDialogue = 80200311,
          Subtitle = "??"
        },
        [802003073] = {
          ContentKR = "???",
          DialogueId = 802003073,
          GUID = "C8C5E75C",
          NextDialogue = 80200311,
          Subtitle = "???"
        },
        [802003371] = {
          ContentKR = "부소랑 언니의 추억인데 당연히 부소가 결정해야지.",
          DialogueId = 802003371,
          GUID = "C8C5EBF4",
          NextDialogue = 80200339,
          Subtitle = "Sure — it's your memory. You should decide what to do with it."
        },
        [802003372] = {
          ContentKR = "그래도 구경하는 거 엄청 재미있는데...",
          DialogueId = 802003372,
          GUID = "C8C5EC48",
          NextDialogue = 80200341,
          Subtitle = "But I was really hoping for some juicy drama..."
        },
        [802003451] = {
          ContentKR = "회몽초 같아.",
          DialogueId = 802003451,
          GUID = "C8C5ED44",
          NextDialogue = 80200348,
          Subtitle = "It's Oneirowort."
        },
        [802003452] = {
          ContentKR = "음용초 같아.",
          DialogueId = 802003452,
          GUID = "C8C5ED6E",
          NextDialogue = 80200348,
          Subtitle = "It's Echowort."
        },
        [900103011] = {
          ContentKR = "뒤에 이 검은 건 뭔가요?",
          DialogueId = 900103011,
          GUID = "900103011.0",
          Subtitle = "What's that black thingy over there?"
        },
        [900103012] = {
          ContentKR = "가볼게요.",
          DialogueId = 900103012,
          GUID = "900103012.0",
          Subtitle = "Goodbye."
        },
        [900300011] = {
          ContentKR = "베레는 소원이 있어?",
          DialogueId = 900300011,
          GUID = "900300011.0",
          NextDialogue = 90030101,
          Subtitle = "Do you have any wishes, Berry?"
        },
        [900300013] = {
          ContentKR = "아이스레이크 시티는 정말 추워...",
          DialogueId = 900300013,
          GUID = "900300013.0",
          NextDialogue = 90030301,
          Subtitle = "It's so bitterly cold here in Icelake..."
        },
        [900300014] = {
          ContentKR = "베레? 네가 어떻게 여기에 있는 거야?",
          DialogueId = 900300014,
          GUID = "900300014.0",
          NextDialogue = 90030401,
          Subtitle = "Berry? How come you are here?"
        },
        [900300015] = {
          ContentKR = "휘페르보레아 제국은 어떤 곳이야?",
          DialogueId = 900300015,
          GUID = "900300015.0",
          NextDialogue = 90030501,
          Subtitle = "What's the Hyperborean Legion like?"
        },
        [900300016] = {
          ContentKR = "넌 항상 조용한 걸 좋아했잖아. 여기, 너무 시끄럽지 않아?",
          DialogueId = 900300016,
          GUID = "900300016.0",
          NextDialogue = 90030601,
          Subtitle = "You've always preferred quiet settings; does the noise here bother you?"
        },
        [900300018] = {
          ContentKR = "베레, 나 피곤해...",
          DialogueId = 900300018,
          GUID = "900300018.0",
          NextDialogue = 90030801,
          Subtitle = "Berry, I'm tired..."
        },
        [900400011] = {
          ContentKR = "비가 내릴 때마다 레베카는 유난히 기분이 좋은 것 같네?",
          DialogueId = 900400011,
          GUID = "900400011.0",
          NextDialogue = 90040101,
          Subtitle = "You always seem so happy when it rains."
        },
        [900400012] = {
          ContentKR = "레베카는 항상 '사랑' 얘기뿐이네. 네 마음속의 '사랑'은 대체 뭐야...?",
          DialogueId = 900400012,
          GUID = "900400012.0",
          NextDialogue = 90040201,
          Subtitle = "You're always talking about love. What does \"love\" really mean to you...?"
        },
        [900400013] = {
          ContentKR = "네 생각은 언제나 특별한 것 같아.",
          DialogueId = 900400013,
          GUID = "900400013.0",
          NextDialogue = 90040301,
          Subtitle = "Your way of thinking is quite special."
        },
        [900400014] = {
          ContentKR = "몸속의 독소는 괜찮은 거야?",
          DialogueId = 900400014,
          GUID = "900400014.0",
          NextDialogue = 90040401,
          Subtitle = "Are you alright with that much toxin in your body?"
        },
        [900400015] = {
          ContentKR = "네 곁에 있으면 항상 좋은 향기가 나는 것 같아.",
          DialogueId = 900400015,
          GUID = "900400015.0",
          NextDialogue = 90040501,
          Subtitle = "There's always a pleasant smell around you."
        },
        [900500011] = {
          ContentKR = "오늘 왜 이렇게 조용해? 꼭 다른 사람 같네.",
          DialogueId = 900500011,
          GUID = "900500011.0",
          NextDialogue = 90050101,
          Subtitle = "You're so quiet today... It's like you're a completely different person."
        },
        [900500012] = {
          ContentKR = "좀도둑은 다 경계심이 강한데, 어떻게 그들 눈을 피해서 물건을 훔친 거야?",
          DialogueId = 900500012,
          GUID = "900500012.0",
          NextDialogue = 90050201,
          Subtitle = "Thieves are usually quite alert. How do you manage to swipe their stuff right under their noses?"
        },
        [900500013] = {
          ContentKR = "훔치는 걸 좋아하는 사람은 나쁜 사람이야!",
          DialogueId = 900500013,
          GUID = "900500013.0",
          NextDialogue = 90050301,
          Subtitle = "Those who like to steal are no good."
        },
        [900500014] = {
          ContentKR = "대부분의 카론은 '악마'라고 불리는 걸 싫어하겠지?",
          DialogueId = 900500014,
          GUID = "900500014.0",
          NextDialogue = 90050401,
          Subtitle = "I thought most Charons wouldn't appreciate being called a \"demon\"..."
        },
        [900600011] = {
          ContentKR = "몸이 불처럼 빨간데, 정말 특이하시군요.",
          DialogueId = 900600011,
          GUID = "900600011.0",
          NextDialogue = 90060101,
          Subtitle = "Your skin is as red as fire. That's quite unique."
        },
        [900600012] = {
          ContentKR = "왜 교도소장이 되는 길을 선택하신 거죠?",
