          GUID = "901200015.0",
          NextDialogue = 90120501,
          Subtitle = "You seem to have been zoning out here for a while."
        },
        [901300011] = {
          ContentKR = "시빌라에 관한 정보를 줄 수 있을까?",
          DialogueId = 901300011,
          GUID = "901300011.0",
          NextDialogue = 90130101,
          Subtitle = "Can you tell me something about Sibylle?"
