        [901800014] = {
          ContentKR = "올리버와는 어린 시절부터 아는 사이야?",
          DialogueId = 901800014,
          GUID = "901800014.0",
          NextDialogue = 90180401,
          Subtitle = "Were you and Oliver childhood friends?"
