          DialogueId = 902000015,
          GUID = "902000015.0",
          NextDialogue = 90200501,
          Subtitle = "Could you tell me about the Galea Theatre?"
        },
        [902100011] = {
          ContentKR = "하모니카를 엄청 좋아하네요?",
          DialogueId = 902100011,
          GUID = "902100011.0",
          NextDialogue = 90210101,
          Subtitle = "It seems like you really like playing the harmonica.",
