        [902100012] = {
          ContentKR = "군단에서는 잘 지내요?",
          DialogueId = 902100012,
          GUID = "902100012.0",
          NextDialogue = 90210201,
          Subtitle = "How's life in the Legion treating you?",
          TriggerCondition = {
            QuestChainUnFinish = {QuestChainId = 100306}
          }
        },
        [902100013] = {
          ContentKR = "당신이 그 누구보다 더 책임감을 가지고 임무에 임하는 것 같아요.",
