          GUID = "902100016.0",
          NextDialogue = 90210601,
          Subtitle = "How are you managing lately? Are you doing okay financially?",
          TriggerCondition = {
            QuestChainFinish = {QuestChainId = 100306}
          }
        },
        [902100017] = {
          ContentKR = "군단을 떠난 뒤 어떻게 지내고 있어요?",
